try:
    import tkinter as _bootstrap_tk
    from tkinter import ttk as _bootstrap_ttk
except Exception:
    _bootstrap_tk = None
    _bootstrap_ttk = None


def _is_gui_bootstrap_startup_mode() -> bool:
    """Return whether startup should show the pre-import bootstrap splash.

    Purpose:
        Decide if the process should display the lightweight splash before heavy
        dependency imports begin.
    Why:
        GUI launches can spend noticeable time importing scientific/UI modules,
        so users need immediate visual confirmation that startup is in progress.
    Inputs:
        None.
    Outputs:
        bool: True for normal GUI app launches, False for CLI/test runs or when
        bootstrap splash is explicitly disabled.
    Side Effects:
        None.
    Exceptions:
        Any argument/environment probing failures are handled defensively and
        return False for safe no-splash fallback behavior.
    """
    try:
        if str(globals().get("__name__", "")) != "__main__":
            return False
    except Exception:
        return False

    if str(os.environ.get("GL260_DISABLE_BOOTSTRAP_SPLASH", "")).strip().lower() in {
        "1",
        "true",
        "yes",
        "on",
    }:
        return False
    if os.environ.get("RUN_SOLUBILITY_REGRESSION") == "1":
        return False
    if os.environ.get("RUN_PITZER_TESTS") == "1":
        return False
    if os.environ.get("RUN_TIMELINE_TABLE_EXPORT_TEST") == "1":
        return False

    argv = tuple(str(arg) for arg in sys.argv[1:])
    if "--debug-validate-svg" in argv:
        return False
    if "--benchmark" in argv:
        return False
    return True


def _create_bootstrap_startup_splash(
    *,
    message: str = "Starting GL-260...",
    detail: str = "",
) -> object:
    """Create a lightweight splash window used before heavyweight imports.

    Purpose:
        Display immediate startup feedback before `UnifiedApp` and its in-app
        splash can be initialized.
    Why:
        Importing scientific plotting/data dependencies can take seconds, which
        otherwise appears as a blank/no-response launch.
    Inputs:
        message: Primary status text shown in the bootstrap splash.
        detail: Secondary detail text shown under the primary message.
    Outputs:
        object: Splash handle dict containing Tk widgets, or None when splash
        creation is unavailable/disabled.
    Side Effects:
        Creates a temporary hidden-root + top-level splash window and forces an
        initial paint so users see progress immediately.
    Exceptions:
        Any Tk creation/layout failures are swallowed and return None so startup
        continues without interruption.
    """
    if not _is_gui_bootstrap_startup_mode():
        return None
    if _bootstrap_tk is None or _bootstrap_ttk is None:
        return None

    root = None
    overlay = None
    label = None
    detail_label = None
    progress_var = None
    progress_label = None
    try:
        root = _bootstrap_tk.Tk()
        root.withdraw()
        overlay = _bootstrap_tk.Toplevel(root)
        overlay.title("Starting GL-260")
        try:
            overlay.attributes("-topmost", True)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            overlay.resizable(False, False)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            overlay.protocol("WM_DELETE_WINDOW", lambda: None)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

        width = 520
        height = 188
        try:
            screen_w = int(overlay.winfo_screenwidth())
            screen_h = int(overlay.winfo_screenheight())
            pos_x = max(0, int((screen_w - width) / 2))
            pos_y = max(0, int((screen_h - height) / 2))
            overlay.geometry(f"{width}x{height}+{pos_x}+{pos_y}")
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

        body = _bootstrap_ttk.Frame(overlay, padding=14)
        body.pack(fill="both", expand=True)
        _bootstrap_ttk.Label(
            body, text="GL-260 Data Analysis & Processing Engine", anchor="w"
        ).pack(fill="x", pady=(0, 8))
        label = _bootstrap_ttk.Label(
            body,
            text=str(message or ""),
            anchor="w",
            width=64,
        )
        label.pack(fill="x")
        detail_label = _bootstrap_ttk.Label(
            body,
            text=str(detail or ""),
            anchor="w",
            justify="left",
            wraplength=476,
            width=64,
        )
        detail_label.pack(fill="x", pady=(6, 0))
        progress_var = _bootstrap_tk.DoubleVar(master=overlay, value=2.0)
        _bootstrap_ttk.Progressbar(
            body,
            mode="determinate",
            maximum=100.0,
            variable=progress_var,
            length=360,
        ).pack(fill="x", pady=(12, 0))
        progress_label = _bootstrap_ttk.Label(
            body,
            text="2% | 0.00s",
            anchor="e",
            width=64,
        )
        progress_label.pack(fill="x", pady=(6, 0))

        overlay.update_idletasks()
        overlay.update()
    except Exception:
        try:
            if overlay is not None:
                overlay.destroy()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            if root is not None:
                root.destroy()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        return None

    return {
        "root": root,
        "overlay": overlay,
        "label": label,
        "detail_label": detail_label,
        "progress_var": progress_var,
        "progress_label": progress_label,
        "progress_value": 2.0,
        "started_at": time.monotonic(),
        "detail_base": str(detail or "").strip(),
        "heartbeat_after_id": None,
    }


def _format_bootstrap_startup_elapsed(elapsed_seconds: object) -> str:
    """Format elapsed seconds for the pre-import bootstrap splash footer.

    Purpose:
        Keep bootstrap elapsed-time text consistent with later in-app splash
        timers before `UnifiedApp` exists.
    Why:
        The bootstrap splash runs before class helpers are available, but users
        still need a live wall-clock timer during heavyweight imports.
    Inputs:
        elapsed_seconds: Candidate monotonic elapsed duration in seconds.
    Outputs:
        str: Display-safe elapsed text.
    Side Effects:
        None.
    Exceptions:
        Invalid values are coerced to `0.00s`.
    """
    try:
        elapsed_value = float(elapsed_seconds)
    except Exception:
        elapsed_value = 0.0
    if elapsed_value != elapsed_value or elapsed_value in (float("inf"), float("-inf")):
        elapsed_value = 0.0
    if elapsed_value < 0.0:
        elapsed_value = 0.0
    if elapsed_value < 60.0:
        return f"{elapsed_value:0.2f}s"
    minutes, seconds = divmod(elapsed_value, 60.0)
    if minutes < 60.0:
        return f"{int(minutes):02d}:{seconds:05.2f}"
    hours, rem_minutes = divmod(int(minutes), 60)
    return f"{hours:02d}:{rem_minutes:02d}:{seconds:05.2f}"


def _format_bootstrap_startup_footer(progress_value: object, elapsed_text: str) -> str:
    """Format bootstrap progress and elapsed time for the footer label.

    Purpose:
        Centralize the `NN% | elapsed` footer text used by bootstrap loading.
    Why:
        Keeping elapsed time in the footer avoids duplicating timer text inside
        status/detail labels where frequent repainting can leave stale glyphs.
    Inputs:
        progress_value: Candidate determinate progress value in percent.
        elapsed_text: Already formatted elapsed-time string.
    Outputs:
        str: Footer text suitable for the progress label.
    Side Effects:
        None.
    Exceptions:
        Invalid progress values fall back to zero.
    """
    try:
        percent_value = int(round(float(progress_value)))
    except Exception:
        percent_value = 0
    percent_value = max(0, min(100, percent_value))
    return f"{percent_value}% | {elapsed_text}"


def _stop_bootstrap_startup_splash_heartbeat(splash_handle: object) -> None:
    """Cancel the bootstrap splash heartbeat callback when present.

    Purpose:
        Stop pre-import elapsed timer callbacks during bootstrap teardown or
        terminal startup states.
    Why:
        The temporary bootstrap root must not retain orphaned `after` callbacks.
    Inputs:
        splash_handle: Handle returned by `_create_bootstrap_startup_splash`.
    Outputs:
        None.
    Side Effects:
        Cancels the scheduled Tk callback and clears its handle field.
    Exceptions:
        Cancellation failures are ignored so startup cleanup can continue.
    """
    if not isinstance(splash_handle, dict):
        return
    after_id = splash_handle.get("heartbeat_after_id")
    if after_id is None:
        return
    overlay = splash_handle.get("overlay")
    try:
        if overlay is not None:
            overlay.after_cancel(after_id)
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting startup.
        pass
    splash_handle["heartbeat_after_id"] = None


def _start_bootstrap_startup_splash_heartbeat(splash_handle: object) -> None:
    """Start live footer timer updates for the bootstrap startup splash.

    Purpose:
        Refresh the bootstrap splash progress footer between import milestones.
    Why:
        Heavy imports can run for noticeable intervals without status calls, so
        a scheduled heartbeat keeps the splash responsive and visibly alive.
    Inputs:
        splash_handle: Handle returned by `_create_bootstrap_startup_splash`.
    Outputs:
        None.
    Side Effects:
        Schedules recurring Tk callbacks on the temporary bootstrap overlay.
    Exceptions:
        Missing or destroyed widgets stop the heartbeat safely.
    """
    if not isinstance(splash_handle, dict):
        return
    if splash_handle.get("heartbeat_after_id") is not None:
        return

    def _tick() -> None:
        """Refresh one bootstrap splash footer heartbeat frame."""
        splash_handle["heartbeat_after_id"] = None
        overlay = splash_handle.get("overlay")
        if overlay is None:
            return
        try:
            if not overlay.winfo_exists():
                return
        except Exception:
            return
        started_at = splash_handle.get("started_at")
        if not isinstance(started_at, (int, float)):
            started_at = time.monotonic()
            splash_handle["started_at"] = float(started_at)
        try:
            progress_value = float(splash_handle.get("progress_value", 0.0) or 0.0)
        except Exception:
            progress_value = 0.0
        elapsed_text = _format_bootstrap_startup_elapsed(
            max(0.0, time.monotonic() - float(started_at))
        )
        progress_label = splash_handle.get("progress_label")
        if progress_label is not None:
            try:
                progress_label.configure(
                    text=_format_bootstrap_startup_footer(
                        progress_value,
                        elapsed_text,
                    )
                )
            except Exception:
                # Best-effort guard; ignore failures to keep startup moving.
                pass
        if progress_value >= 100.0:
            return
        try:
            overlay.update_idletasks()
        except Exception:
            # Best-effort guard; ignore failures to keep startup moving.
            pass
        try:
            splash_handle["heartbeat_after_id"] = overlay.after(100, _tick)
        except Exception:
            splash_handle["heartbeat_after_id"] = None

    _tick()


def _update_bootstrap_startup_splash(
    splash_handle: object,
    *,
    message: str | None = None,
    detail: str | None = None,
    progress: float | None = None,
) -> None:
    """Update bootstrap splash text/progress while imports continue.

    Purpose:
        Keep early-launch progress messaging visible between heavyweight import
        milestones before `UnifiedApp` becomes available.
    Why:
        Import cost can vary by environment, so deterministic progress updates
        reduce perceived hangs and improve startup clarity.
    Inputs:
        splash_handle: Handle returned from `_create_bootstrap_startup_splash`.
        message: Optional primary status text.
        detail: Optional secondary detail text.
        progress: Optional determinate progress value in the 0..100 range.
    Outputs:
        None.
    Side Effects:
        Mutates bootstrap splash labels/progress bar and repaints the window.
    Exceptions:
        Missing/destroyed widgets are ignored by best-effort guards.
    """
    if not isinstance(splash_handle, dict):
        return
    overlay = splash_handle.get("overlay")
    if overlay is None:
        return
    try:
        if not overlay.winfo_exists():
            return
    except Exception:
        return

    if message is not None:
        label = splash_handle.get("label")
        if label is not None:
            try:
                label.configure(text=str(message))
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
    if detail is not None:
        splash_handle["detail_base"] = str(detail).strip()
        detail_label = splash_handle.get("detail_label")
        if detail_label is not None:
            try:
                detail_label.configure(text=str(detail))
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
    started_at = splash_handle.get("started_at")
    if not isinstance(started_at, (int, float)):
        started_at = time.monotonic()
        splash_handle["started_at"] = float(started_at)
    elapsed_value = max(0.0, time.monotonic() - float(started_at))
    elapsed_text = _format_bootstrap_startup_elapsed(elapsed_value)
    if progress is not None:
        current_value = float(splash_handle.get("progress_value", 0.0) or 0.0)
        target_value = max(current_value, max(0.0, min(100.0, float(progress))))
        splash_handle["progress_value"] = target_value
        progress_var = splash_handle.get("progress_var")
        if progress_var is not None:
            try:
                progress_var.set(target_value)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        progress_label = splash_handle.get("progress_label")
        if progress_label is not None:
            try:
                progress_label.configure(
                    text=_format_bootstrap_startup_footer(
                        target_value,
                        elapsed_text,
                    )
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
    else:
        progress_label = splash_handle.get("progress_label")
        progress_value = float(splash_handle.get("progress_value", 0.0) or 0.0)
        if progress_label is not None:
            try:
                progress_label.configure(
                    text=_format_bootstrap_startup_footer(
                        progress_value,
                        elapsed_text,
                    )
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
    try:
        overlay.lift()
        overlay.update_idletasks()
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass
    try:
        terminal_progress = float(splash_handle.get("progress_value", 0.0) or 0.0)
    except Exception:
        terminal_progress = 0.0
    if terminal_progress >= 100.0:
        _stop_bootstrap_startup_splash_heartbeat(splash_handle)
    else:
        _start_bootstrap_startup_splash_heartbeat(splash_handle)


def _clear_bootstrap_startup_splash(splash_handle: object) -> None:
    """Destroy the pre-import bootstrap splash and its temporary Tk root.

    Purpose:
        Tear down bootstrap splash resources after handoff to `UnifiedApp` or on
        abnormal startup exit.
    Why:
        The bootstrap splash uses a temporary hidden root that must be cleaned up
        to avoid leaking windows/timers.
    Inputs:
        splash_handle: Handle returned from `_create_bootstrap_startup_splash`.
    Outputs:
        None.
    Side Effects:
        Destroys bootstrap splash widgets and their hidden Tk root.
    Exceptions:
        Teardown errors are swallowed to avoid masking primary startup failures.
    """
    if not isinstance(splash_handle, dict):
        return
    _stop_bootstrap_startup_splash_heartbeat(splash_handle)
    overlay = splash_handle.get("overlay")
    if overlay is not None:
        try:
            overlay.destroy()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
    root = splash_handle.get("root")
    if root is not None:
        try:
            root.destroy()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass


def _claim_tk_default_root(app_root: object) -> None:
    """Bind Tk's default-root pointer to the active UnifiedApp root.

    Purpose:
        Ensure Tk variable constructors without explicit `master` resolve to the
        current application root during startup handoff.
    Why:
        Startup now creates a temporary bootstrap `Tk()` root before `UnifiedApp`.
        Destroying that bootstrap root can clear Tk's global `_default_root`,
        which causes `tk.StringVar(...)` and similar calls to fail early.
    Inputs:
        app_root: Active `UnifiedApp`/`tk.Tk` root that should own default-root
            resolution for subsequent Tk variable creation.
    Outputs:
        None.
    Side Effects:
        Mutates the tkinter module's `_default_root` global when supported.
    Exceptions:
        Uses best-effort guards and never raises so startup cannot regress when
        tkinter internals differ across runtimes.
    """
    module_ref = globals().get("tk", None)
    if module_ref is None:
        module_ref = _bootstrap_tk
    if module_ref is None:
        return
    try:
        support_default_root = bool(getattr(module_ref, "_support_default_root", False))
    except Exception:
        support_default_root = False
    if not support_default_root:
        return
    try:
        module_ref._default_root = app_root
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass


