def _py_gil_disabled_build_flag():
    """Return normalized build flag for optional GIL disabling support.

    Purpose:
        Read and normalize the interpreter build metadata that indicates whether
        `-X gil=0` is supported for this executable.
    Why:
        Runtime APIs such as `sys._is_gil_enabled` can exist on both standard
        and free-threaded builds, so build metadata must be authoritative for
        capability gating.
    Args:
        None.
    Returns:
        Optional[int]: `1` for free-threaded-capable builds, `0` for standard
        builds, or `None` when unavailable/unparseable.
    Side Effects:
        None.
    Exceptions:
        Any sysconfig read/parse failure is handled internally and returns
        `None` so callers can fail safely.
    """
    try:
        raw_value = sysconfig.get_config_var("Py_GIL_DISABLED")
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        return None
    # Normalize to integers so capability checks remain stable across str/int config values.
    try:
        return int(raw_value)
    except Exception:
        return None


def _supports_free_threading_build():
    """Return whether the current interpreter build supports GIL-disabled mode.

    Purpose:
        Gate UI controls and restart behavior that rely on free-threaded build
        support.
    Why:
        Standard and free-threaded builds may both expose runtime GIL APIs, so
        capability must be based on build-time metadata.
    Args:
        None.
    Returns:
        bool: True only when the interpreter is compiled with
        `Py_GIL_DISABLED=1`.
    Side Effects:
        None.
    Exceptions:
        Unknown or invalid config state is treated as unsupported.
    """
    return _py_gil_disabled_build_flag() == 1


def _current_gil_status():
    """Return current GIL status.
    Used to surface GIL status for downstream logic."""
    if hasattr(sys, "_is_gil_enabled"):
        try:
            return bool(sys._is_gil_enabled())
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            return None
    return None


def _is_runtime_gil_disabled() -> bool:
    """Return whether the current process is running with the GIL disabled.

    Purpose:
        Provide one canonical runtime gate for no-GIL optimized execution paths.
    Why:
        Free-threaded builds can still run with the GIL enabled depending on
        launch mode, so build capability alone is not sufficient.
    Inputs:
        None.
    Outputs:
        True only when the interpreter build supports free-threading and runtime
        GIL state is explicitly disabled; otherwise False.
    Side Effects:
        None.
    Exceptions:
        Any runtime probing failures are handled internally and treated as
        GIL-enabled for safe fallback behavior.
    """
    if not _supports_free_threading_build():
        return False
    gil_status = _current_gil_status()
    if gil_status is None:
        return False
    return not bool(gil_status)


def _runtime_free_threading_fingerprint():
    """Collect runtime/build details for free-threading diagnostics.

    Purpose:
        Provide one canonical snapshot of interpreter/runtime state for
        Developer Tools status text, restart preflight messaging, and warnings.
    Why:
        Consolidating the values avoids mismatched UI messaging when multiple
        code paths report free-threading capability and GIL state.
    Args:
        None.
    Returns:
        dict: Diagnostic payload with version/executable/build fields and
        runtime GIL status.
    Side Effects:
        None.
    Exceptions:
        Best-effort guards convert read failures to `None`/fallback text.
    """
    try:
        python_version = platform.python_version()
    except Exception:
        python_version = f"{sys.version_info.major}.{sys.version_info.minor}.{sys.version_info.micro}"
    try:
        soabi = sysconfig.get_config_var("SOABI")
    except Exception:
        soabi = None
    py_gil_disabled = _py_gil_disabled_build_flag()
    supports_free_threading = bool(py_gil_disabled == 1)
    return {
        "python_version": python_version,
        "python_version_full": str(sys.version),
        "executable": str(sys.executable or ""),
        "py_gil_disabled": py_gil_disabled,
        "soabi": str(soabi) if soabi is not None else None,
        "supports_free_threading": supports_free_threading,
        "gil_enabled": _current_gil_status(),
        "build_label": (
            "Free-threaded build" if supports_free_threading else "Standard build"
        ),
    }


def _enforce_startup_no_gil_for_free_threaded_build() -> None:
    """Restart once with GIL disabled when free-threaded startup is misconfigured.

    Purpose:
        Enforce no-GIL runtime mode early in process startup for free-threaded
        interpreter builds.
    Why:
        Some launch paths can start `cp314t` with the GIL enabled; this guard
        re-execs once with `-X gil=0` so startup behavior is deterministic.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        May mutate `os.environ` and replace the current process image via
        `os.execv`.
    Exceptions:
        Restart failures are reported to stderr and startup continues without
        raising.
    """
    if not _supports_free_threading_build():
        return
    if _current_gil_status() is not True:
        return
    if str(os.environ.get(_STARTUP_GIL_ENFORCE_GUARD_ENV, "")).strip() == "1":
        return

    exe = str(sys.executable or "").strip()
    if not exe:
        return

    argv = list(sys.argv)
    filtered_args: List[str] = []
    idx = 1
    # Strip any existing `-X gil=...` forms so one explicit `-X gil=0` wins.
    while idx < len(argv):
        arg = argv[idx]
        if isinstance(arg, str) and arg.startswith("-Xgil="):
            idx += 1
            continue
        if arg == "-X" and idx + 1 < len(argv):
            next_arg = argv[idx + 1]
            if isinstance(next_arg, str) and next_arg.startswith("gil="):
                idx += 2
                continue
        filtered_args.append(arg)
        idx += 1

    new_args = [exe, "-X", "gil=0", *filtered_args]
    os.environ[_STARTUP_GIL_ENFORCE_GUARD_ENV] = "1"
    os.environ["PYTHON_GIL"] = "0"
    try:
        os.execv(exe, new_args)
    except Exception as exc:
        try:
            print(
                "Startup no-GIL enforcement restart failed: "
                f"{type(exc).__name__}: {exc}",
                file=sys.stderr,
            )
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass


def _runtime_extension_abi_tag():
    """Resolve the runtime C-extension ABI tag for the active interpreter.

    Purpose:
        Identify which compiled-extension ABI suffix this interpreter expects.
    Why:
        NumPy/Matplotlib binary wheels must match this ABI tag, especially when
        switching between standard (`cp314`) and free-threaded (`cp314t`) builds.
    Args:
        None.
    Returns:
        Optional[str]: ABI token like `cp314` or `cp314t`, else None when the
        runtime suffix cannot be derived.
    Side Effects:
        None.
    Exceptions:
        Invalid or unavailable config values are handled internally and treated
        as unknown ABI.
    """
    try:
        ext_suffix = sysconfig.get_config_var("EXT_SUFFIX")
    except Exception:
        return None
    if not isinstance(ext_suffix, str) or not ext_suffix:
        return None
    suffix_text = ext_suffix.lstrip(".")
    if suffix_text.endswith(".pyd"):
        suffix_text = suffix_text[:-4]
    abi_tag = suffix_text.split("-", 1)[0].strip()
    if not abi_tag.startswith("cp"):
        return None
    return abi_tag


def _distribution_wheel_tags(distribution_name):
    """Read wheel tags from installed distribution metadata.

    Purpose:
        Retrieve the wheel `Tag:` entries recorded for an installed package.
    Why:
        ABI mismatch detection requires comparing installed wheel metadata
        against the currently running interpreter ABI.
    Args:
        distribution_name (str): Distribution identifier, e.g. `numpy`.
    Returns:
        List[str]: Parsed wheel tags from `WHEEL`; empty when unavailable.
    Side Effects:
        None.
    Exceptions:
        Missing distributions or metadata parsing failures are treated as
        no-data conditions and return an empty list.
    """
    try:
        distribution = importlib_metadata.distribution(distribution_name)
    except Exception:
        return []
    try:
        wheel_text = distribution.read_text("WHEEL")
    except Exception:
        return []
    if not wheel_text:
        return []

    tags = []
    # Extract only `Tag:` metadata lines to compare runtime ABI expectations.
    for raw_line in wheel_text.splitlines():
        line = raw_line.strip()
        if not line.startswith("Tag:"):
            continue
        tag_text = line.split(":", 1)[1].strip()
        if tag_text:
            tags.append(tag_text)
    return tags


def _wheel_abi_tags(tags):
    """Extract ABI components from wheel tags.

    Purpose:
        Normalize wheel tag strings into ABI tokens for compatibility checks.
    Why:
        The app only needs ABI-level comparison (e.g., `cp314` vs `cp314t`) to
        flag binary extension mismatch at startup.
    Args:
        tags (Iterable[str]): Wheel tag strings from distribution metadata.
    Returns:
        List[str]: Distinct ABI tokens sorted alphabetically.
    Side Effects:
        None.
    Exceptions:
        Malformed tags are ignored to keep checks robust.
    """
    abi_tokens = set()
    # Parse wheel tag triplets: python tag, ABI tag, and platform tag.
    for tag_text in tags:
        try:
            _python_tag, abi_tag, _platform_tag = str(tag_text).split("-", 2)
        except ValueError:
            continue
        abi_tag = abi_tag.strip()
        if abi_tag.startswith("cp"):
            abi_tokens.add(abi_tag)
    return sorted(abi_tokens)


def _binary_abi_mismatch_report():
    """Build a deterministic mismatch report for critical binary dependencies.

    Purpose:
        Detect whether installed NumPy/Matplotlib wheel ABIs match the active
        interpreter ABI expectations.
    Why:
        Mismatched cp314/cp314t wheels cause opaque C-extension import errors;
        early deterministic reporting gives users immediate recovery steps.
    Args:
        None.
    Returns:
        Optional[Dict[str, Any]]: Report payload when mismatch is confirmed;
        otherwise None.
    Side Effects:
        None.
    Exceptions:
        Missing metadata is treated as inconclusive and does not trigger a
        mismatch report.
    """
    expected_abi = _runtime_extension_abi_tag()
    if not expected_abi:
        return None

    mismatches = []
    for distribution_name in ("numpy", "matplotlib"):
        wheel_tags = _distribution_wheel_tags(distribution_name)
        if not wheel_tags:
            continue
        abi_tags = _wheel_abi_tags(wheel_tags)
        if not abi_tags:
            continue
        if expected_abi in abi_tags:
            continue
        mismatches.append(
            {
                "name": distribution_name,
                "abi_tags": abi_tags,
                "wheel_tags": wheel_tags,
            }
        )

    if not mismatches:
        return None
    return {
        "expected_abi": expected_abi,
        "expected_ext_suffix": sysconfig.get_config_var("EXT_SUFFIX"),
        "executable": str(sys.executable or ""),
        "mismatches": mismatches,
    }


def _raise_on_binary_abi_mismatch():
    """Fail fast when binary wheel ABI mismatches are confirmed.

    Purpose:
        Stop startup before heavy imports when critical binary wheels are not
        ABI-compatible with the active interpreter.
    Why:
        Failing early avoids long C-extension tracebacks and gives exact repair
        commands for standard and free-threaded virtual environments.
    Args:
        None.
    Returns:
        None.
    Side Effects:
        Raises `SystemExit` with user-facing remediation steps when mismatch is
        confirmed.
    Exceptions:
        No exception is raised when mismatch cannot be confirmed from metadata.
    """
    report = _binary_abi_mismatch_report()
    if report is None:
        return

    mismatch_lines = []
    for entry in report.get("mismatches", []):
        mismatch_lines.append(
            f"- {entry.get('name')}: installed ABI tags {entry.get('abi_tags')}"
        )

    message_lines = [
        "Startup blocked: binary wheel ABI mismatch detected for critical dependencies.",
        "",
        "Reason: This is an interpreter/wheel ABI mismatch (cp314 vs cp314t),",
        "not a NumPy source-tree issue.",
        "",
        f"Interpreter executable: {report.get('executable')}",
        f"Expected extension suffix: {report.get('expected_ext_suffix')}",
        f"Expected ABI tag: {report.get('expected_abi')}",
        "Detected mismatches:",
        *mismatch_lines,
        "",
        "Recovery (use separate environments; do not share global site-packages):",
        "",
        "Standard Python 3.14 (.venv):",
        "  py -3.14 -m venv .venv",
        r"  .\.venv\Scripts\Activate.ps1",
        "  python -m pip install --upgrade pip",
        "  python -m pip install -r requirements.txt",
        r"  .\.venv\Scripts\python.exe \"GL-260 Data Analysis and Plotter.py\"",
        "",
        "Free-threaded Python 3.14t (.venv-314t):",
        "  py -3.14t -m venv .venv-314t",
        r"  .\.venv-314t\Scripts\Activate.ps1",
        "  python -m pip install --upgrade pip",
        "  python -m pip install -r requirements.txt",
        r"  .\.venv-314t\Scripts\python.exe \"GL-260 Data Analysis and Plotter.py\"",
    ]
    raise SystemExit("\n".join(message_lines))


def _is_running_under_vscode():
    """Check whether it is running under vscode.
    Used to gate conditional behavior in the workflow."""
    return "VSCODE_PID" in os.environ or os.environ.get("TERM_PROGRAM") == "vscode"


