def _install_customtkinter_plain_tk_dpi_compat() -> None:
    """Install CustomTkinter DPI callbacks expected by plain Tk windows.

    Purpose:
        Add CTk-compatible dimension-update guard hooks to standard Tk root
        classes when CustomTkinter is available.
    Why:
        GL-260 deliberately mixes CTk widgets into existing `tk.Tk` and
        `tk.Toplevel` windows. CustomTkinter's DPI polling can track those
        plain windows and call CTk-only guard methods during scaling checks.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Adds no-op `block_update_dimensions_event` and
        `unblock_update_dimensions_event` methods to `tk.Tk` and `tk.Toplevel`
        if the active Tk runtime does not already provide them.
    Exceptions:
        Best-effort guards suppress patch failures so optional CTk support
        cannot block startup.
    """
    if ctk is None:
        return

    def _block_update_dimensions_event(self: Any) -> None:
        """Accept CustomTkinter DPI guard calls on plain Tk windows.

        Purpose:
            Provide the method CustomTkinter calls before applying DPI scaling.
        Why:
            Plain Tk windows do not track CTk's internal dimension state, so no
            additional blocking work is required.
        Inputs:
            self: Plain Tk/Toplevel window receiving the compatibility call.
        Outputs:
            None.
        Side Effects:
            None.
        Exceptions:
            None.
        """
        _ = self

    def _unblock_update_dimensions_event(self: Any) -> None:
        """Accept CustomTkinter DPI unguard calls on plain Tk windows.

        Purpose:
            Provide the method CustomTkinter calls after applying DPI scaling.
        Why:
            The matching block hook is intentionally a no-op for plain Tk
            windows, so unblocking is also a no-op.
        Inputs:
            self: Plain Tk/Toplevel window receiving the compatibility call.
        Outputs:
            None.
        Side Effects:
            None.
        Exceptions:
            None.
        """
        _ = self

    # CustomTkinter owns these methods on CTk/CTkToplevel; add them only where
    # the standard Tk classes lack them so CTk subclasses keep their behavior.
    for window_class in (tk.Tk, tk.Toplevel):
        try:
            if not hasattr(window_class, "block_update_dimensions_event"):
                window_class.block_update_dimensions_event = (
                    _block_update_dimensions_event
                )
            if not hasattr(window_class, "unblock_update_dimensions_event"):
                window_class.unblock_update_dimensions_event = (
                    _unblock_update_dimensions_event
                )
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting startup.
            pass


_install_customtkinter_plain_tk_dpi_compat()


def _is_valid_customtkinter_scale(value: Any) -> bool:
    """Return whether a CustomTkinter scale value is safe to use.

    Purpose:
        Identify finite, positive scale factors before CTk stores or broadcasts
        them to widgets.
    Why:
        CTk 5.2.2 divides widget dimensions by the effective widget scale during
        configure callbacks, so a zero DPI result becomes a repeated
        `ZeroDivisionError`.
    Inputs:
        value: Candidate scale value from CTk, Windows DPI APIs, or cached state.
    Outputs:
        bool: True when the value can be safely used as a divisor/multiplier.
    Side Effects:
        None.
    Exceptions:
        Conversion errors return False.
    """
    try:
        numeric = float(value)
    except Exception:
        return False
    return (
        numeric > 0.0
        and numeric == numeric
        and numeric
        not in (
            float("inf"),
            float("-inf"),
        )
    )


def _fallback_customtkinter_dpi_scale(window: Any) -> float:
    """Return a safe fallback scale for a CustomTkinter-tracked window.

    Purpose:
        Provide deterministic fallback ordering when CTk reports an invalid
        window DPI scaling value.
    Why:
        Mixed plain-Tk/CTk windows can receive a zero DPI value from CTk's
        Windows monitor probe, which must be replaced before widget callbacks
        receive it.
    Inputs:
        window: Tk or Toplevel window whose CTk DPI scale is being resolved.
    Outputs:
        float: Positive finite fallback scale.
    Side Effects:
        None.
    Exceptions:
        Best-effort probing failures fall through to the next fallback.
    """
    hwnd = None
    try:
        hwnd = int(window.winfo_id())
    except Exception:
        hwnd = None

    detect_windows_scale = globals().get("_detect_windows_scale")
    if callable(detect_windows_scale):
        try:
            detected = detect_windows_scale(hwnd)
            if _is_valid_customtkinter_scale(detected):
                return float(detected)
        except Exception:
            # Best-effort guard; fall through to CTk cache or neutral scaling.
            pass

    try:
        tracker = getattr(ctk, "ScalingTracker", None) if ctk is not None else None
        cached = getattr(tracker, "window_dpi_scaling_dict", {}).get(window)
        if _is_valid_customtkinter_scale(cached):
            return float(cached)
    except Exception:
        # Best-effort guard; fall through to neutral scaling.
        pass

    return 1.0


def _install_customtkinter_scaling_safety() -> None:
    """Install CustomTkinter DPI scaling guards for mixed Tk/CTk windows.

    Purpose:
        Patch CTk's window DPI scale resolver so invalid zero/non-finite values
        are sanitized before CTk stores them or broadcasts them to widgets.
    Why:
        GL-260 uses CTk widgets inside a standard `tk.Tk` root. CTk 5.2.2 trusts
        Windows DPI probe results and later divides configure-event dimensions
        by the effective widget scale.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Replaces `ctk.ScalingTracker.get_window_dpi_scaling` idempotently and
        clamps CTk's global widget/window scaling state when available.
    Exceptions:
        Best-effort guards suppress optional CTk patch failures so startup can
        continue with Tk fallbacks.
    """
    if ctk is None:
        return

    try:
        tracker = getattr(ctk, "ScalingTracker", None)
    except Exception:
        tracker = None
    if tracker is None:
        return

    try:
        if not _is_valid_customtkinter_scale(getattr(tracker, "widget_scaling", 1.0)):
            tracker.widget_scaling = 1.0
        if not _is_valid_customtkinter_scale(getattr(tracker, "window_scaling", 1.0)):
            tracker.window_scaling = 1.0
    except Exception:
        # Best-effort guard; the resolver patch below still prevents bad DPI.
        pass

    try:
        if getattr(tracker, "_gl260_dpi_safety_installed", False):
            return
        original_get_window_dpi_scaling = tracker.get_window_dpi_scaling

        def _safe_get_window_dpi_scaling(cls: Any, window: Any) -> float:
            """Return CTk's window DPI scaling with GL-260 safety fallback.

            Purpose:
                Preserve CTk's native DPI behavior for valid readings while
                replacing invalid readings before widget scale callbacks run.
            Why:
                CTk widgets divide by this scale during configure handling, so
                zero/non-finite values must never be returned.
            Inputs:
                cls: CTk `ScalingTracker` class passed by `classmethod`.
                window: Window object whose DPI scale is being queried.
            Outputs:
                float: Positive finite DPI scale.
            Side Effects:
                None.
            Exceptions:
                Original CTk resolver failures are handled by fallback probing.
            """
            _ = cls
            try:
                value = original_get_window_dpi_scaling(window)
                if _is_valid_customtkinter_scale(value):
                    return float(value)
            except Exception:
                # Best-effort guard; fallback logic below keeps CTk callbacks safe.
                pass
            return _fallback_customtkinter_dpi_scale(window)

        tracker._gl260_original_get_window_dpi_scaling = original_get_window_dpi_scaling
        tracker.get_window_dpi_scaling = classmethod(_safe_get_window_dpi_scaling)
        tracker._gl260_dpi_safety_installed = True
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting startup.
        pass


_install_customtkinter_scaling_safety()
