def _mojibake_marker_count(text: str) -> int:
    """Count likely mojibake markers in one text payload.

    Purpose:
        Provide a lightweight quality metric to compare repaired text candidates.
    Why:
        UTF-8 text that was decoded with the wrong codec often contains a small
        set of marker glyphs (`Â`, `Ã`, `Î`, `â`) and C1 control characters.
        Counting these markers lets repair logic keep only conversions that
        actually reduce corruption.
    Inputs:
        text: Candidate text to evaluate.
    Outputs:
        Integer count of suspicious marker glyphs/control code points.
    Side Effects:
        None.
    Exceptions:
        None.
    """
    count = 0
    # Iterate over text to apply the per-item logic.
    for ch in text:
        if ch in _MOJIBAKE_TRIGGER_CHARS:
            count += 1
            continue
        code_point = ord(ch)
        if 0x80 <= code_point <= 0x9F:
            count += 1
    return count


def _repair_mojibake_text(value: Any) -> str:
    """Repair likely mojibake text using guarded legacy-codec round-trips.

    Purpose:
        Normalize UI/display strings that were accidentally persisted or authored
        with broken unicode decoding.
    Why:
        The application renders scientific symbols (`\u0394`, `\u00b0`, subscripts,
        superscripts) across Tk/Matplotlib surfaces; mojibake (for example
        `\u00ce\u201dP`, `\u00c2\u00b0C`, `CO\u00e2\u201a\u201a`) makes labels unreadable.
        This helper restores symbols at display boundaries without rewriting the
        full source/literal corpus.
    Inputs:
        value: Any display value to normalize; non-string values are stringified.
    Outputs:
        Repaired display string when corruption is detected; otherwise the
        original text representation.
    Side Effects:
        None.
    Exceptions:
        Codec conversion attempts use strict error handling and fall back
        silently when conversion is invalid for the input text.
    """
    text = "" if value is None else str(value)
    if not text:
        return text
    baseline_score = _mojibake_marker_count(text)
    if baseline_score <= 0:
        return text
    repaired = text
    best_score = baseline_score
    # Probe both common legacy decoders used in prior ingestion/export paths.
    for source_encoding in ("cp1252", "latin-1"):
        try:
            candidate = text.encode(source_encoding, errors="strict").decode(
                "utf-8", errors="strict"
            )
        except UnicodeError:
            continue
        candidate_score = _mojibake_marker_count(candidate)
        if candidate_score < best_score:
            repaired = candidate
            best_score = candidate_score
    # Fallback replacements handle residual sequences and edge cases where strict
    # round-trips cannot fully recover symbols (for example mixed encodings).
    for bad_text, good_text in _MOJIBAKE_FALLBACK_REPLACEMENTS.items():
        repaired = repaired.replace(bad_text, good_text)
    return repaired


def _set_stringvar_repaired(target_var: Any, value: Any) -> None:
    """Set a Tk/CTk variable using mojibake-repaired display text.

    Purpose:
        Centralize display-string normalization for `StringVar` style outputs.
    Why:
        Several UI surfaces assemble dynamic text from multiple pipelines; using
        one setter avoids repeating repair guards and prevents mojibake regressions
        in status banners, guidance text, and helper summaries.
    Inputs:
        target_var: Variable-like object expected to expose `.set(...)`.
        value: Raw text payload to display.
    Outputs:
        None.
    Side Effects:
        Updates `target_var` with repaired text when a compatible variable is
        provided.
    Exceptions:
        Missing or incompatible variable objects are ignored by design.
    """
    setter = getattr(target_var, "set", None)
    if not callable(setter):
        return
    try:
        setter(_repair_mojibake_text(value))
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass


def _sanitize_widget_text_tree(root_widget: Any) -> None:
    """Recursively repair mojibake in widget labels and Treeview text content.

    Purpose:
        Apply safe display-text repair across existing widget hierarchies.
    Why:
        Legacy `ttk.Label(...)`/`ttk.LabelFrame(...)` call sites and Treeview
        headings/items bypass wrapper constructors; this utility repairs those
        surfaces without requiring broad UI refactors.
    Inputs:
        root_widget: Root widget for subtree traversal.
    Outputs:
        None.
    Side Effects:
        May update widget `text` configuration values, Treeview heading labels,
        and Treeview row text/value payloads.
    Exceptions:
        Widget access/update failures are swallowed so traversal can continue.
    """

    def _repair_widget_text(widget: Any) -> None:
        """Repair one widget's direct `text` property when available."""
        try:
            current_text = widget.cget("text")
        except Exception:
            return
        if current_text is None:
            return
        repaired_text = _repair_mojibake_text(current_text)
        if repaired_text == current_text:
            return
        try:
            widget.configure(text=repaired_text)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _repair_tree_item(tree: ttk.Treeview, item_id: str) -> None:
        """Recursively repair one Treeview item's text and values."""
        try:
            row_data = tree.item(item_id)
        except Exception:
            return
        if isinstance(row_data, dict):
            text_value = row_data.get("text")
            repaired_text = _repair_mojibake_text(text_value)
            values = row_data.get("values", ())
            repaired_values = tuple(_repair_mojibake_text(value) for value in values)
            if repaired_text != text_value or repaired_values != tuple(values):
                try:
                    tree.item(item_id, text=repaired_text, values=repaired_values)
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
        try:
            child_ids = list(tree.get_children(item_id))
        except Exception:
            child_ids = []
        for child_id in child_ids:
            _repair_tree_item(tree, child_id)

    def _repair_treeview(tree: ttk.Treeview) -> None:
        """Repair Treeview heading labels and all item text/value payloads."""
        try:
            column_ids = ["#0", *list(tree["columns"])]
        except Exception:
            column_ids = ["#0"]
        for column_id in column_ids:
            try:
                heading_cfg = tree.heading(column_id)
            except Exception:
                continue
            heading_text = heading_cfg.get("text", "")
            repaired_heading = _repair_mojibake_text(heading_text)
            if repaired_heading != heading_text:
                try:
                    tree.heading(column_id, text=repaired_heading)
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
        try:
            root_items = list(tree.get_children(""))
        except Exception:
            root_items = []
        for item_id in root_items:
            _repair_tree_item(tree, item_id)

    queue: List[Any] = [root_widget]
    while queue:
        widget = queue.pop(0)
        if widget is None:
            continue
        _repair_widget_text(widget)
        if isinstance(widget, ttk.Treeview):
            _repair_treeview(widget)
        try:
            queue.extend(list(widget.winfo_children()))
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass


def _sanitize_figure_text_artists(fig: Any) -> None:
    """Repair mojibake across text artists in one Matplotlib figure.

    Purpose:
        Normalize all figure/axes/legend/table text just before export.
    Why:
        Saved artifacts can receive mixed UI/data strings; sanitizing text artists
        at export boundaries ensures PNG/PDF/SVG outputs are mojibake-free even
        when upstream strings were encoded incorrectly.
    Inputs:
        fig: Matplotlib figure-like object.
    Outputs:
        None.
    Side Effects:
        Mutates figure text artist content in place.
    Exceptions:
        Artist traversal/update errors are ignored best-effort.
    """
    if fig is None:
        return

    def _repair_text_artist(text_artist: Any) -> None:
        """Repair one text-artist payload in place when getter/setter exist."""
        getter = getattr(text_artist, "get_text", None)
        setter = getattr(text_artist, "set_text", None)
        if not callable(getter) or not callable(setter):
            return
        try:
            source_text = getter()
        except Exception:
            return
        repaired_text = _repair_mojibake_text(source_text)
        if repaired_text == source_text:
            return
        try:
            setter(repaired_text)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    for figure_text in list(getattr(fig, "texts", []) or []):
        _repair_text_artist(figure_text)
    _repair_text_artist(getattr(fig, "_suptitle", None))
    for figure_legend in list(getattr(fig, "legends", []) or []):
        for legend_text in list(figure_legend.get_texts() or []):
            _repair_text_artist(legend_text)
    for axis in list(getattr(fig, "axes", []) or []):
        _repair_text_artist(getattr(axis, "title", None))
        _repair_text_artist(getattr(getattr(axis, "xaxis", None), "label", None))
        _repair_text_artist(getattr(getattr(axis, "yaxis", None), "label", None))
        for axis_text in list(getattr(axis, "texts", []) or []):
            _repair_text_artist(axis_text)
        legend = None
        try:
            legend = axis.get_legend()
        except Exception:
            legend = None
        if legend is not None:
            for legend_text in list(legend.get_texts() or []):
                _repair_text_artist(legend_text)
            _repair_text_artist(legend.get_title())
        for table in list(getattr(axis, "tables", []) or []):
            get_cells = getattr(table, "get_celld", None)
            if not callable(get_cells):
                continue
            try:
                cell_map = get_cells()
            except Exception:
                continue
            if not isinstance(cell_map, Mapping):
                continue
            for cell in cell_map.values():
                get_text = getattr(cell, "get_text", None)
                if callable(get_text):
                    _repair_text_artist(get_text())


def _compact_layer_status_text(value: Any, *, default_status: str = "clean") -> str:
    """Normalize layer-status labels into a compact, deduplicated display form.

    Purpose:
        Convert verbose or duplicated status text into a short toolbar-safe label.
    Why:
        Plot toolbar status text can be sourced from multiple refresh paths and
        persisted metadata; some paths duplicate prefixes (for example
        `Layer State: Layer State: clean`) and create long strings that overlap
        neighboring controls.
    Inputs:
        value: Raw status text payload from any caller.
        default_status: Fallback status token when payload is empty after cleanup.
    Outputs:
        Compact status string in the canonical `State: ...` format.
    Side Effects:
        None.
    Exceptions:
        None.
    """
    raw_text = _repair_mojibake_text(value)
    normalized = re.sub(r"\s+", " ", raw_text).strip()
    if not normalized:
        normalized = str(default_status or "clean").strip() or "clean"
    # Strip repeated legacy prefixes before applying the compact prefix.
    normalized = re.sub(
        r"^(?:Layer\s*State\s*:\s*)+",
        "",
        normalized,
        flags=re.IGNORECASE,
    ).strip()
    if not normalized:
        normalized = str(default_status or "clean").strip() or "clean"
    if normalized.lower().startswith("state:"):
        normalized = normalized.split(":", 1)[1].strip() or (
            str(default_status or "clean").strip() or "clean"
        )
    return f"State: {normalized}"


