def _normalize_ctk_input_width(width_value: Any) -> Any:
    """Normalize entry/combobox width when constructing CTk widgets.

    Purpose:
        Translate legacy ttk-style character widths into readable CTk pixel widths.
    Why:
        The codebase historically uses ttk width values (character units), while CTk
        interprets width in pixels. Without conversion, migrated inputs can render as
        one-character boxes and become difficult to use.
    Args:
        width_value: Width value from widget kwargs (usually int/float, sometimes None).
    Returns:
        A pixel width for CTk-compatible numeric inputs, or the original value when
        conversion is not applicable.
    Side Effects:
        None.
    Exceptions:
        Invalid or non-numeric values are passed through unchanged.
    """
    if isinstance(width_value, bool) or not isinstance(width_value, (int, float)):
        return width_value
    if width_value <= 0:
        return width_value
    width_int = int(round(float(width_value)))
    # Widths at or below this threshold are most likely legacy ttk character widths.
    if width_int <= 60:
        return max(96, (width_int * 8) + 24)
    return width_int


def _install_ctk_numeric_entry_bridge(
    entry_widget: Any,
    numeric_var: tk.Variable,
    proxy_var: tk.StringVar,
) -> None:
    """Bridge CTk entry text updates to numeric Tk variables safely.

    Purpose:
        Prevent CustomTkinter entry callbacks from crashing when numeric Tk
        variables temporarily receive blank/partial text during editing.
    Why:
        `ctk.CTkEntry` reads the bound variable via `.get()` during internal
        callbacks. Binding `tk.DoubleVar` or `tk.IntVar` directly can raise
        `TclError` while a user clears or partially edits the field.
    Args:
        entry_widget: The CTk entry widget receiving text input.
        numeric_var: Backing numeric Tk variable (`tk.DoubleVar`/`tk.IntVar`).
        proxy_var: String proxy variable bound to the CTk entry.
    Returns:
        None.
    Side Effects:
        Registers write traces on both variables, synchronizes numeric values
        into the proxy, and attaches destroy-time cleanup to remove traces.
    Exceptions:
        Best-effort guards suppress trace cleanup/sync failures to keep UI
        workflows responsive.
    """
    if entry_widget is None or numeric_var is None or proxy_var is None:
        return
    is_int_var = isinstance(numeric_var, tk.IntVar)
    bridge_state: Dict[str, Any] = {
        "syncing": False,
        "proxy_trace_id": None,
        "numeric_trace_id": None,
    }

    def _parse_proxy_value(raw_value: Any) -> Optional[float | int]:
        """Parse proxy text into a valid numeric value for the target variable."""
        text = str(raw_value or "").strip()
        if not text:
            return None
        try:
            parsed_float = float(text)
        except Exception:
            return None
        if not math.isfinite(parsed_float):
            return None
        if not is_int_var:
            return parsed_float
        parsed_int = int(parsed_float)
        if abs(parsed_float - float(parsed_int)) > 1e-9:
            return None
        return parsed_int

    # Closure captures bridge locals to keep numeric-entry synchronization scoped.
    def _sync_proxy_from_numeric(*_args: Any) -> None:
        """Mirror committed numeric values into the CTk-bound proxy variable."""
        if bridge_state["syncing"]:
            return
        try:
            numeric_value = numeric_var.get()
        except Exception:
            return
        if is_int_var:
            try:
                display_value = str(int(float(numeric_value)))
            except Exception:
                return
        else:
            try:
                numeric_float = float(numeric_value)
            except Exception:
                return
            if not math.isfinite(numeric_float):
                return
            display_value = f"{numeric_float:g}"
        bridge_state["syncing"] = True
        try:
            if proxy_var.get() != display_value:
                proxy_var.set(display_value)
        finally:
            bridge_state["syncing"] = False

    # Closure captures bridge locals to keep numeric-entry synchronization scoped.
    def _commit_proxy_to_numeric(*_args: Any) -> None:
        """Commit parseable proxy text into the numeric variable.

        Blank or invalid text is ignored so previously committed numeric values
        remain intact until the user enters a valid number.
        """
        if bridge_state["syncing"]:
            return
        parsed_value = _parse_proxy_value(proxy_var.get())
        if parsed_value is None:
            return
        bridge_state["syncing"] = True
        try:
            numeric_var.set(parsed_value)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        finally:
            bridge_state["syncing"] = False

    # Closure captures bridge locals to keep numeric-entry synchronization scoped.
    def _cleanup_bridge(_event: Any = None) -> None:
        """Detach bridge traces when the entry widget is destroyed."""
        proxy_trace_id = bridge_state.get("proxy_trace_id")
        numeric_trace_id = bridge_state.get("numeric_trace_id")
        if proxy_trace_id:
            try:
                proxy_var.trace_remove("write", proxy_trace_id)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        if numeric_trace_id:
            try:
                numeric_var.trace_remove("write", numeric_trace_id)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        bridge_state["proxy_trace_id"] = None
        bridge_state["numeric_trace_id"] = None
        try:
            setattr(entry_widget, "_gl260_ctk_numeric_bridge", None)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    bridge_state["proxy_trace_id"] = proxy_var.trace_add("write", _commit_proxy_to_numeric)
    bridge_state["numeric_trace_id"] = numeric_var.trace_add("write", _sync_proxy_from_numeric)
    _sync_proxy_from_numeric()
    try:
        entry_widget.bind("<Destroy>", _cleanup_bridge, add="+")
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass
    try:
        setattr(
            entry_widget,
            "_gl260_ctk_numeric_bridge",
            {
                "numeric_var": numeric_var,
                "proxy_var": proxy_var,
                "state": bridge_state,
                "cleanup": _cleanup_bridge,
            },
        )
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass


def _ui_entry(parent, *args, **kwargs):
    """Create an entry widget using CTk when available, else ttk.

    Purpose:
        Unify text-entry construction across ttk and CTk.
    Why:
        Keeps existing grid/pack wiring intact during incremental migration.
    Args:
        parent: Parent widget that owns the entry.
        *args: Positional constructor args.
        **kwargs: Keyword args, including `textvariable`, `width`, and `state`.
    Returns:
        Widget instance (`ctk.CTkEntry` or `ttk.Entry`).
    Side Effects:
        None beyond widget construction.
    Exceptions:
        ttk-specific style kwargs are ignored on the CTk branch.
    """
    if ctk is None:
        return ttk.Entry(parent, *args, **kwargs)
    ctk_kwargs = dict(kwargs)
    numeric_source_var = ctk_kwargs.get("textvariable")
    numeric_proxy_var: Optional[tk.StringVar] = None
    if isinstance(numeric_source_var, (tk.DoubleVar, tk.IntVar)):
        numeric_proxy_var = tk.StringVar(master=parent, value="")
        ctk_kwargs["textvariable"] = numeric_proxy_var
    if str(ctk_kwargs.get("state", "")).strip().lower() == "readonly":
        ctk_kwargs["state"] = "disabled"
    if "width" in ctk_kwargs:
        normalized_width = _normalize_ctk_input_width(ctk_kwargs.get("width"))
        if normalized_width is None:
            ctk_kwargs.pop("width", None)
        else:
            ctk_kwargs["width"] = normalized_width
    ctk_kwargs.pop("style", None)
    ctk_kwargs.pop("padding", None)
    entry_widget = ctk.CTkEntry(parent, *args, **ctk_kwargs)
    if numeric_proxy_var is not None and isinstance(
        numeric_source_var, (tk.DoubleVar, tk.IntVar)
    ):
        _install_ctk_numeric_entry_bridge(
            entry_widget,
            numeric_source_var,
            numeric_proxy_var,
        )
    return entry_widget


def _ui_combobox(parent, *args, **kwargs):
    """Create a combobox using CTk when available, else ttk.

    Purpose:
        Provide a toolkit-agnostic constructor for dropdown selectors.
    Why:
        CTk and ttk use different keyword names (`variable` vs `textvariable`);
        this helper normalizes the call-site contract.
    Args:
        parent: Parent widget that owns the combobox.
        *args: Positional constructor args.
        **kwargs: Keyword args such as values, textvariable/variable, width, state.
    Returns:
        Widget instance (`ctk.CTkComboBox` or `ttk.Combobox`).
    Side Effects:
        None beyond widget construction.
    Exceptions:
        Unsupported kwargs are ignored on the CTk branch.
    """
    if ctk is None:
        return ttk.Combobox(parent, *args, **kwargs)

    ctk_kwargs = dict(kwargs)
    user_command = ctk_kwargs.pop("command", None)
    text_var = ctk_kwargs.pop("textvariable", None)
    explicit_var = ctk_kwargs.pop("variable", None)
    if explicit_var is None and text_var is not None:
        ctk_kwargs["variable"] = text_var
    elif explicit_var is not None:
        ctk_kwargs["variable"] = explicit_var
    ctk_kwargs.pop("style", None)
    ctk_kwargs.pop("padding", None)
    ctk_kwargs.pop("postcommand", None)
    if "width" in ctk_kwargs:
        normalized_width = _normalize_ctk_input_width(ctk_kwargs.get("width"))
        if normalized_width is None:
            ctk_kwargs.pop("width", None)
        else:
            ctk_kwargs["width"] = normalized_width
    widget = ctk.CTkComboBox(parent, *args, **ctk_kwargs)

    def _dispatch(selection_value: Any) -> None:
        """Dispatch CTk combobox selection to command and virtual event hooks."""
        if callable(user_command):
            try:
                user_command(selection_value)
            except TypeError:
                user_command()
        try:
            widget.event_generate("<<ComboboxSelected>>")
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    try:
        widget.configure(command=_dispatch)
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass
    return widget


def _ui_scrollbar(parent, *args, **kwargs):
    """Create a scrollbar using CTk when available, else ttk.

    Purpose:
        Standardize vertical/horizontal scrollbar creation during migration.
    Why:
        Scrollable layouts appear in multiple tabs and dialogs with shared logic.
    Args:
        parent: Parent widget that owns the scrollbar.
        *args: Positional constructor args.
        **kwargs: Keyword args such as orient/orientation and command.
    Returns:
        Widget instance (`ctk.CTkScrollbar` or `ttk.Scrollbar`).
    Side Effects:
        None beyond widget construction.
    Exceptions:
        Orientation keyword is normalized for CTk when needed.
    """
    if ctk is None:
        return ttk.Scrollbar(parent, *args, **kwargs)

    ctk_kwargs = dict(kwargs)
    orientation = ctk_kwargs.pop("orient", None)
    if orientation is None:
        orientation = ctk_kwargs.get("orientation", None)
    if orientation is not None:
        ctk_kwargs["orientation"] = orientation
    ctk_kwargs.pop("style", None)
    return ctk.CTkScrollbar(parent, *args, **ctk_kwargs)


def _ui_scale(parent, *args, **kwargs):
    """Create a slider/scale using CTk when available, else ttk.

    Purpose:
        Provide one constructor for numeric slider controls.
    Why:
        Some migrated tabs use scales heavily and should adopt CTk styling when
        available without changing callback logic.
    Args:
        parent: Parent widget that owns the scale.
        *args: Positional constructor args.
        **kwargs: Keyword args including from_/to, variable, and command.
    Returns:
        Widget instance (`ctk.CTkSlider` or `ttk.Scale`).
    Side Effects:
        None beyond widget construction.
    Exceptions:
        Non-horizontal orientation falls back to ttk for compatibility.
    """
    if ctk is None:
        return ttk.Scale(parent, *args, **kwargs)
    orientation = kwargs.get("orient")
    if orientation not in (None, "horizontal", tk.HORIZONTAL):
        return ttk.Scale(parent, *args, **kwargs)
    ctk_kwargs = dict(kwargs)
    ctk_kwargs.pop("orient", None)
    ctk_kwargs.pop("style", None)
    ctk_kwargs.pop("length", None)
    return ctk.CTkSlider(parent, *args, **ctk_kwargs)

