def _runtime_python_profile() -> str:
    """Classify the active interpreter runtime profile for Rust tooling checks.

    Purpose:
        Normalize the running process into a free-threaded or GIL-enabled profile.
    Why:
        Rust tool path resolution must follow the active interpreter profile in
        dual-environment setups to avoid stale PATH shims.
    Inputs:
        None.
    Outputs:
        str: `"free_threaded"` or `"gil_enabled"`.
    Side Effects:
        None.
    Exceptions:
        Runtime metadata probe failures are handled defensively.
    """
    abi_tag = ""
    soabi = ""
    try:
        abi_tag = str(_runtime_extension_abi_tag() or "").strip().lower()
    except Exception:
        abi_tag = ""
    try:
        soabi = str(sysconfig.get_config_var("SOABI") or "").strip().lower()
    except Exception:
        soabi = ""
    if abi_tag.endswith("t"):
        return RUST_RUNTIME_PROFILE_FREE_THREADED
    if "t-" in soabi or soabi.endswith("t"):
        return RUST_RUNTIME_PROFILE_FREE_THREADED
    try:
        if _supports_free_threading_build():
            return RUST_RUNTIME_PROFILE_FREE_THREADED
    except Exception:
        pass
    return RUST_RUNTIME_PROFILE_GIL_ENABLED


def _runtime_rust_install_fingerprint_payload() -> Dict[str, str]:
    """Build the interpreter fingerprint payload for Rust install persistence.

    Purpose:
        Capture runtime identity fields used to associate Rust extension
        readiness with the active Python interpreter environment.
    Why:
        `maturin develop` installs are interpreter-specific; recording readiness
        by fingerprint avoids repeated setup prompts across restarts while still
        surfacing ABI/environment mismatches.
    Inputs:
        None.
    Outputs:
        Dict[str, str]: Stable runtime fingerprint payload fields.
    Side Effects:
        None.
    Exceptions:
        Best-effort guards normalize unavailable runtime metadata to empty
        strings.
    """
    executable = ""
    try:
        executable = os.path.abspath(str(sys.executable or ""))
    except Exception:
        executable = str(sys.executable or "")
    executable = executable.strip()
    python_version = ""
    try:
        python_version = platform.python_version()
    except Exception:
        python_version = (
            f"{sys.version_info.major}.{sys.version_info.minor}.{sys.version_info.micro}"
        )
    soabi = ""
    try:
        soabi = str(sysconfig.get_config_var("SOABI") or "").strip()
    except Exception:
        soabi = ""
    abi_tag = ""
    try:
        abi_tag = str(_runtime_extension_abi_tag() or "").strip()
    except Exception:
        abi_tag = ""
    platform_name = ""
    try:
        platform_name = str(platform.system() or "").strip()
    except Exception:
        platform_name = ""
    machine_name = ""
    try:
        machine_name = str(platform.machine() or "").strip()
    except Exception:
        machine_name = ""
    return {
        "executable": executable,
        "python_version": python_version,
        "soabi": soabi,
        "abi_tag": abi_tag,
        "platform": platform_name,
        "machine": machine_name,
        "runtime_profile": _runtime_python_profile(),
    }


def _runtime_rust_install_fingerprint_key(
    fingerprint_payload: Optional[Mapping[str, Any]] = None,
) -> str:
    """Serialize a runtime fingerprint payload into a stable key string.

    Purpose:
        Normalize interpreter identity metadata into one deterministic lookup key.
    Why:
        Settings persistence for Rust install readiness needs stable keys so
        repeated launches in the same interpreter resolve to one record.
    Inputs:
        fingerprint_payload: Optional payload override to serialize.
    Outputs:
        str: JSON-serialized stable fingerprint key.
    Side Effects:
        None.
    Exceptions:
        Serialization failures are handled internally and return an empty key.
    """
    payload = (
        dict(fingerprint_payload)
        if isinstance(fingerprint_payload, Mapping)
        else _runtime_rust_install_fingerprint_payload()
    )
    normalized: Dict[str, str] = {}
    for field in (
        "executable",
        "python_version",
        "soabi",
        "abi_tag",
        "platform",
        "machine",
        "runtime_profile",
    ):
        normalized[field] = str(payload.get(field, "") or "").strip()
    try:
        return json.dumps(normalized, sort_keys=True, separators=(",", ":"))
    except Exception:
        return ""


def _current_rust_install_fingerprint_key() -> str:
    """Return the stable runtime fingerprint key for the active interpreter.

    Purpose:
        Provide one canonical key lookup for startup/install Rust readiness paths.
    Why:
        Runtime checks and prompt behavior should compare against the same key
        format used when readiness metadata is persisted.
    Inputs:
        None.
    Outputs:
        str: Runtime fingerprint key string, or empty when unavailable.
    Side Effects:
        None.
    Exceptions:
        Fingerprint serialization errors are handled internally.
    """
    return _runtime_rust_install_fingerprint_key()


def _record_rust_backend_ready_for_current_runtime(*, persist: bool = False) -> None:
    """Persist Rust-backend readiness metadata for the active interpreter.

    Purpose:
        Mark the current runtime fingerprint as Rust-ready after verified import.
    Why:
        Persisting successful readiness avoids repeated install prompts on future
        launches in the same interpreter while preserving per-runtime isolation.
    Inputs:
        persist: True writes updated settings to disk immediately.
    Outputs:
        None.
    Side Effects:
        Updates Rust fingerprint readiness keys in the shared settings dict and
        optionally writes `settings.json`.
    Exceptions:
        Persistence failures are suppressed to avoid interrupting workflows.
    """
    settings_map = globals().get("settings", None)
    if not isinstance(settings_map, dict):
        return
    _apply_rust_runtime_settings_defaults(settings_map)
    fingerprint_key = _current_rust_install_fingerprint_key()
    if not fingerprint_key:
        return
    fingerprints = settings_map.get("rust_runtime_install_fingerprints", {})
    if not isinstance(fingerprints, dict):
        fingerprints = {}
    payload = _runtime_rust_install_fingerprint_payload()
    payload["recorded_at"] = datetime.now().isoformat()
    payload["status"] = "ready"
    fingerprints[fingerprint_key] = payload
    settings_map["rust_runtime_install_fingerprints"] = fingerprints
    settings_map["rust_last_ready_fingerprint"] = fingerprint_key
    if not persist:
        return
    save_fn = globals().get("_save_settings_to_disk")
    if callable(save_fn):
        try:
            save_fn()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass


def _last_recorded_rust_ready_fingerprint() -> Tuple[str, Optional[Dict[str, str]]]:
    """Return the last persisted Rust-ready runtime fingerprint and payload.

    Purpose:
        Retrieve the most recently recorded interpreter identity marked as
        Rust-ready in settings persistence.
    Why:
        Startup prompts should explain interpreter-mismatch scenarios when Rust
        readiness was previously recorded under a different runtime.
    Inputs:
        None.
    Outputs:
        Tuple `(fingerprint_key, payload_or_none)`.
    Side Effects:
        None.
    Exceptions:
        Invalid settings payloads are treated as missing data.
    """
    settings_map = globals().get("settings", None)
    if not isinstance(settings_map, dict):
        return "", None
    _apply_rust_runtime_settings_defaults(settings_map)
    fingerprint_key = str(settings_map.get("rust_last_ready_fingerprint", "") or "").strip()
    if not fingerprint_key:
        return "", None
    fingerprints = settings_map.get("rust_runtime_install_fingerprints", {})
    if not isinstance(fingerprints, Mapping):
        return "", None
    payload = fingerprints.get(fingerprint_key)
    if not isinstance(payload, Mapping):
        return fingerprint_key, None
    normalized_payload: Dict[str, str] = {}
    for key, value in payload.items():
        key_text = str(key or "").strip()
        if not key_text:
            continue
        normalized_payload[key_text] = str(value or "").strip()
    return fingerprint_key, normalized_payload or None


def _current_rust_backend_mode() -> str:
    """Resolve the current Rust backend mode from settings.

    Purpose:
        Normalize persisted backend preference into a supported mode string.
    Why:
        Runtime checks and first-use install prompts need one authoritative mode
        switch that stays stable even when settings are missing or malformed.
    Inputs:
        None.
    Outputs:
        One of `"auto"` or `"python"`.
    Side Effects:
        None.
    Exceptions:
        Invalid settings values are treated as `"auto"`.
    """
    settings_map = globals().get("settings", {})
    if not isinstance(settings_map, dict):
        return "auto"
    mode = str(settings_map.get("rust_backend_mode", "auto") or "auto").strip().lower()
    return "python" if mode == "python" else "auto"


def _is_rust_backend_enabled() -> bool:
    """Report whether Rust backend execution is currently allowed.

    Purpose:
        Gate optional Rust acceleration behind user preference.
    Why:
        Users can force Python-only behavior for reproducibility or troubleshooting.
    Inputs:
        None.
    Outputs:
        True when Rust may be used, False when Python-only mode is requested.
    Side Effects:
        None.
    Exceptions:
        None.
    """
    return _current_rust_backend_mode() != "python"


def _runtime_interpreter_scripts_dir() -> str:
    """Resolve the active interpreter Scripts directory used for tool probing.

    Purpose:
        Provide one canonical scripts-directory path for interpreter-first Rust
        tool resolution.
    Why:
        Dual-runtime installs can expose multiple Python shim directories on PATH;
        selecting the active interpreter's scripts folder avoids stale picks.
    Inputs:
        None.
    Outputs:
        str: Absolute scripts directory path when available, otherwise empty.
    Side Effects:
        None.
    Exceptions:
        Path resolution failures return an empty string.
    """
    try:
        scripts_dir = str(sysconfig.get_path("scripts") or "").strip()
    except Exception:
        scripts_dir = ""
    if scripts_dir:
        try:
            scripts_dir = os.path.abspath(scripts_dir)
        except Exception:
            scripts_dir = str(scripts_dir or "").strip()
        if os.path.isdir(scripts_dir):
            return scripts_dir
    try:
        exe_dir = os.path.dirname(os.path.abspath(str(sys.executable or "")))
    except Exception:
        exe_dir = os.path.dirname(str(sys.executable or ""))
    exe_dir = str(exe_dir or "").strip()
    return exe_dir if exe_dir and os.path.isdir(exe_dir) else ""


def _rust_tool_override_path(
    runtime_profile: str,
    tool_name: str,
    *,
    settings_map: Optional[Mapping[str, Any]] = None,
) -> str:
    """Resolve one configured Rust tool override path for the active profile.

    Purpose:
        Read interpreter-profile-specific Rust tool overrides from settings.
    Why:
        Some environments require explicit tool pinning and must bypass automatic
        path discovery.
    Inputs:
        runtime_profile: Runtime profile key (`free_threaded`/`gil_enabled`).
        tool_name: Tool key (`cargo` or `rustc`).
        settings_map: Optional settings mapping override.
    Outputs:
        str: Absolute override executable path when configured, else empty.
    Side Effects:
        None.
    Exceptions:
        Invalid settings payloads are treated as no override.
    """
    tool_key = str(tool_name or "").strip().lower()
    profile_key = str(runtime_profile or "").strip().lower()
    if tool_key not in {"cargo", "rustc"}:
        return ""
    normalized_profile = (
        RUST_RUNTIME_PROFILE_FREE_THREADED
        if profile_key == RUST_RUNTIME_PROFILE_FREE_THREADED
        else RUST_RUNTIME_PROFILE_GIL_ENABLED
    )
    candidate_settings: Optional[Mapping[str, Any]]
    if isinstance(settings_map, Mapping):
        candidate_settings = settings_map
    else:
        global_settings = globals().get("settings")
        candidate_settings = global_settings if isinstance(global_settings, Mapping) else None
    if isinstance(candidate_settings, dict):
        _apply_rust_runtime_settings_defaults(candidate_settings)
    overrides_root = (
        candidate_settings.get("rust_tool_path_overrides", {})
        if isinstance(candidate_settings, Mapping)
        else {}
    )
    if not isinstance(overrides_root, Mapping):
        return ""
    profile_map = overrides_root.get(normalized_profile, {})
    if not isinstance(profile_map, Mapping):
        return ""
    raw_path = str(profile_map.get(tool_key, "") or "").strip()
    if not raw_path:
        return ""
    expanded = os.path.expandvars(os.path.expanduser(raw_path))
    try:
        return os.path.abspath(expanded)
    except Exception:
        return str(expanded or "").strip()


def _validate_rust_tool_candidate(
    tool_name: str,
    candidate_path: str,
    *,
    timeout_seconds: Optional[float] = None,
) -> Dict[str, Any]:
    """Validate one Rust tool candidate path for existence and executability.

    Purpose:
        Normalize candidate-tool health checks used by interpreter-first selection.
    Why:
        PATH-visible shims can exist but be unrunnable or arch-incompatible; each
        candidate needs explicit validation before selection.
    Inputs:
        tool_name: Tool token for diagnostics (`cargo`/`rustc`).
        candidate_path: Candidate executable path/token.
        timeout_seconds: Optional timeout for the version probe command.
    Outputs:
        Dict[str, Any]: Validation payload with `valid`, `reason`, `details`, and
        `arch_compatible` flags.
    Side Effects:
        Executes `<candidate> --version` when the file exists.
    Exceptions:
        Probe failures are captured in the payload; no exceptions are raised.
    """
    tool_token = str(tool_name or "").strip()
    raw_candidate = str(candidate_path or "").strip().strip('"')
    normalized_path = ""
    if raw_candidate:
        try:
            normalized_path = os.path.abspath(raw_candidate)
        except Exception:
            normalized_path = raw_candidate
    payload: Dict[str, Any] = {
        "tool": tool_token,
        "path": normalized_path,
        "valid": False,
        "reason": "",
        "details": "",
        "arch_compatible": None,
    }
    if not normalized_path:
        payload["reason"] = "missing_path"
        payload["details"] = "no candidate path provided"
        return payload
    if not os.path.isfile(normalized_path):
        payload["reason"] = "not_found"
        payload["details"] = "candidate path does not exist"
        return payload
    ok, details = _run_command_for_status(
        [normalized_path, "--version"],
        timeout_seconds=timeout_seconds,
    )
    details_text = str(details or "").strip()
    payload["details"] = details_text
    if ok:
        payload["valid"] = True
        payload["reason"] = "ok"
        payload["arch_compatible"] = True
        return payload
    lowered = details_text.lower()
    payload["reason"] = "not_runnable"
    payload["arch_compatible"] = True
    # Windows loader failures for wrong-architecture/invalid binary shims
    # should be surfaced explicitly for profile diagnostics.
    if (
        "not a valid application for this os platform" in lowered
        or "os error 216" in lowered
        or "winerror 216" in lowered
        or "%1 is not compatible" in lowered
        or "bad exe format" in lowered
    ):
        payload["reason"] = "arch_incompatible"
        payload["arch_compatible"] = False
    return payload


def _resolve_rust_tool_for_runtime(
    tool_name: str,
    runtime_profile: str,
    *,
    timeout_seconds: Optional[float] = None,
    settings_map: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    """Resolve one Rust tool path using interpreter-first precedence.

    Purpose:
        Select a runtime Rust tool executable using profile-aware precedence.
    Why:
        Dual interpreter environments must not trust PATH-first shims for build
        or diagnostics decisions.
    Inputs:
        tool_name: Tool token (`cargo` or `rustc`).
        runtime_profile: Active runtime profile key.
        timeout_seconds: Optional version-probe timeout in seconds.
        settings_map: Optional settings mapping override.
    Outputs:
        Dict[str, Any]: Selected tool payload plus rejected candidate diagnostics.
    Side Effects:
        Executes validation probes for candidate executables.
    Exceptions:
        Invalid candidates are returned as non-fatal diagnostic records.
    """
    tool_token = str(tool_name or "").strip().lower()
    profile_token = str(runtime_profile or "").strip().lower()
    if tool_token not in {"cargo", "rustc"}:
        return {
            "tool": tool_token,
            "runtime_profile": profile_token,
            "path": "",
            "source": "",
            "valid": False,
            "reason": "unsupported_tool",
            "details": "",
            "arch_compatible": None,
            "rejected_candidates": [],
            "alternate_valid_candidates": [],
        }
    normalized_profile = (
        RUST_RUNTIME_PROFILE_FREE_THREADED
        if profile_token == RUST_RUNTIME_PROFILE_FREE_THREADED
        else RUST_RUNTIME_PROFILE_GIL_ENABLED
    )
    executable_name = (
        f"{tool_token}.exe" if os.name == "nt" and not tool_token.endswith(".exe") else tool_token
    )
    candidates: List[Tuple[str, str]] = []
    override_path = _rust_tool_override_path(
        normalized_profile,
        tool_token,
        settings_map=settings_map,
    )
    if override_path:
        candidates.append((RUST_TOOL_SOURCE_OVERRIDE, override_path))
    scripts_dir = _runtime_interpreter_scripts_dir()
    if scripts_dir:
        candidates.append(
            (
                RUST_TOOL_SOURCE_INTERPRETER_SCRIPTS,
                os.path.join(scripts_dir, executable_name),
            )
        )
    rustup_path = _resolve_rustup_managed_tool_path(tool_token)
    if rustup_path:
        candidates.append((RUST_TOOL_SOURCE_RUSTUP, rustup_path))
    path_fallback = shutil.which(tool_token)
    if path_fallback:
        candidates.append((RUST_TOOL_SOURCE_PATH_FALLBACK, path_fallback))

    deduped: List[Tuple[str, str]] = []
    seen_paths: Set[str] = set()
    for source, raw_path in candidates:
        cleaned = str(raw_path or "").strip().strip('"')
        if not cleaned:
            continue
        try:
            normalized_path = os.path.normcase(os.path.abspath(cleaned))
        except Exception:
            normalized_path = os.path.normcase(cleaned)
        if normalized_path in seen_paths:
            continue
        seen_paths.add(normalized_path)
        deduped.append((str(source or "").strip(), cleaned))

    selected: Optional[Dict[str, Any]] = None
    rejected_candidates: List[Dict[str, Any]] = []
    alternate_valid: List[Dict[str, Any]] = []
    for source, candidate_path in deduped:
        validation = _validate_rust_tool_candidate(
            tool_token,
            candidate_path,
            timeout_seconds=timeout_seconds,
        )
        candidate_payload = {
            "tool": tool_token,
            "runtime_profile": normalized_profile,
            "path": str(validation.get("path") or "").strip(),
            "source": source,
            "valid": bool(validation.get("valid")),
            "reason": str(validation.get("reason") or "").strip(),
            "details": str(validation.get("details") or "").strip(),
            "arch_compatible": validation.get("arch_compatible"),
        }
        if bool(candidate_payload["valid"]):
            if selected is None:
                selected = candidate_payload
            else:
                alternate_valid.append(candidate_payload)
        else:
            rejected_candidates.append(candidate_payload)

    if selected is None:
        return {
            "tool": tool_token,
            "runtime_profile": normalized_profile,
            "path": "",
            "source": "",
            "valid": False,
            "reason": "no_valid_candidate",
            "details": "",
            "arch_compatible": None,
            "rejected_candidates": rejected_candidates,
            "alternate_valid_candidates": alternate_valid,
        }
    selected["rejected_candidates"] = rejected_candidates
    selected["alternate_valid_candidates"] = alternate_valid
    return selected


def _resolve_runtime_rust_toolchain_diagnostics(
    *,
    timeout_seconds: Optional[float] = None,
    settings_map: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    """Resolve profile-aware cargo/rustc diagnostics for runtime checks.

    Purpose:
        Build one diagnostics payload describing selected Rust tools and profile
        consistency state for startup/runtime gating.
    Why:
        Manifest/kernel checks need companion toolchain diagnostics so deprecated
        detection can distinguish stale profile shims from healthy backends.
    Inputs:
        timeout_seconds: Optional probe timeout applied to tool validation calls.
        settings_map: Optional settings payload override.
    Outputs:
        Dict[str, Any]: Runtime profile and toolchain consistency diagnostics.
    Side Effects:
        Executes tool version probes through resolver helper functions.
    Exceptions:
        Resolver failures are captured as inconsistent/unknown diagnostics.
    """
    runtime_profile = _runtime_python_profile()
    probe_timeout = timeout_seconds
    if probe_timeout is None:
        probe_timeout = max(
            float(_resolve_rust_runtime_timeout_ms("rust_workflow_probe_timeout_ms", 2500))
            / 1000.0,
            0.001,
        )
    cargo_status = _resolve_rust_tool_for_runtime(
        "cargo",
        runtime_profile,
        timeout_seconds=probe_timeout,
        settings_map=settings_map,
    )
    rustc_status = _resolve_rust_tool_for_runtime(
        "rustc",
        runtime_profile,
        timeout_seconds=probe_timeout,
        settings_map=settings_map,
    )
    consistency_state = "consistent"
    consistency_reason = "ready"
    consistency_details = ""
    cargo_valid = bool(cargo_status.get("valid"))
    rustc_valid = bool(rustc_status.get("valid"))
    if not cargo_valid and not rustc_valid:
        consistency_state = "unknown"
        consistency_reason = "tools_unavailable"
        consistency_details = "cargo and rustc are unavailable in this runtime context."
    elif not cargo_valid or not rustc_valid:
        consistency_state = "inconsistent"
        consistency_reason = "partial_toolchain"
        missing_parts: List[str] = []
        if not cargo_valid:
            missing_parts.append("cargo")
        if not rustc_valid:
            missing_parts.append("rustc")
        consistency_details = "missing or invalid tools: " + ", ".join(missing_parts)

    scripts_dir = _runtime_interpreter_scripts_dir()
    normalized_scripts_dir = os.path.normcase(os.path.abspath(scripts_dir)) if scripts_dir else ""
    if consistency_state == "consistent" and runtime_profile == RUST_RUNTIME_PROFILE_FREE_THREADED:
        # A PATH fallback that points to a different Python Scripts directory is
        # likely a stale shim from another interpreter profile.
        for tool_payload in (cargo_status, rustc_status):
            if str(tool_payload.get("source") or "").strip() != RUST_TOOL_SOURCE_PATH_FALLBACK:
                continue
            selected_path = str(tool_payload.get("path") or "").strip()
            if not selected_path:
                continue
            selected_dir = os.path.normcase(os.path.abspath(os.path.dirname(selected_path)))
            looks_like_python_scripts = (
                "\\programs\\python\\python" in selected_dir.replace("/", "\\").lower()
                and selected_dir.endswith("\\scripts")
            )
            if (
                looks_like_python_scripts
                and normalized_scripts_dir
                and selected_dir != normalized_scripts_dir
            ):
                consistency_state = "inconsistent"
                consistency_reason = "profile_mismatch_path_fallback"
                consistency_details = (
                    f"{tool_payload.get('tool')}: selected PATH fallback from "
                    f"{selected_dir} instead of active scripts {normalized_scripts_dir}."
                )
                break

    return {
        "runtime_profile": runtime_profile,
        "cargo_path": str(cargo_status.get("path") or "").strip(),
        "cargo_source": str(cargo_status.get("source") or "").strip(),
        "cargo_valid": bool(cargo_status.get("valid")),
        "cargo_reason": str(cargo_status.get("reason") or "").strip(),
        "cargo_details": str(cargo_status.get("details") or "").strip(),
        "cargo_arch_compatible": cargo_status.get("arch_compatible"),
        "cargo_rejected_candidates": list(cargo_status.get("rejected_candidates") or []),
        "rustc_path": str(rustc_status.get("path") or "").strip(),
        "rustc_source": str(rustc_status.get("source") or "").strip(),
        "rustc_valid": bool(rustc_status.get("valid")),
        "rustc_reason": str(rustc_status.get("reason") or "").strip(),
        "rustc_details": str(rustc_status.get("details") or "").strip(),
        "rustc_arch_compatible": rustc_status.get("arch_compatible"),
        "rustc_rejected_candidates": list(rustc_status.get("rejected_candidates") or []),
        "toolchain_consistency_state": consistency_state,
        "toolchain_consistency_reason": consistency_reason,
        "toolchain_consistency_details": consistency_details,
    }


def _rust_backend_identity_key(identity_payload: Mapping[str, Any]) -> str:
    """Serialize one Rust backend identity payload into a deterministic key.

    Purpose:
        Provide a stable key used to compare startup-validated and active Rust
        backend module identities.
    Why:
        Runtime calls should use the same Rust interface module that startup
        validated unless an explicit repair flow installs a new validated module.
    Inputs:
        identity_payload: Identity mapping containing module/interface fields.
    Outputs:
        str: Stable JSON identity key; empty string on serialization failure.
    Side Effects:
        None.
    Exceptions:
        Non-serializable identity values return an empty key.
    """
    normalized = {
        "module_path": str(identity_payload.get("module_path", "") or "").strip(),
        "module_name": str(identity_payload.get("module_name", "") or "").strip(),
        "crate_version": str(identity_payload.get("crate_version", "") or "").strip(),
        "interface_id": str(identity_payload.get("interface_id", "") or "").strip(),
        "interface_version": str(identity_payload.get("interface_version", "") or "").strip(),
    }
    try:
        return json.dumps(normalized, sort_keys=True, separators=(",", ":"))
    except Exception:
        return ""


def _set_rust_backend_capability_status(payload: Optional[Mapping[str, Any]]) -> None:
    """Persist one runtime Rust backend capability snapshot.

    Purpose:
        Keep a current capability/identity snapshot from manifest + required-kernel
        checks for diagnostics and runtime gating.
    Why:
        Startup status, runtime snapshot exports, and kernel routing all need one
        shared source of truth for backend readiness/deprecation state.
    Inputs:
        payload: Capability payload produced by `_evaluate_rust_backend_capability`.
    Outputs:
        None.
    Side Effects:
        Updates `_RUST_BACKEND_CAPABILITY_STATUS` and active identity globals.
    Exceptions:
        Invalid payloads clear capability cache safely.
    """
    global _RUST_BACKEND_CAPABILITY_STATUS
    global _RUST_BACKEND_ACTIVE_IDENTITY_KEY
    if not isinstance(payload, Mapping):
        _RUST_BACKEND_CAPABILITY_STATUS = {}
        _RUST_BACKEND_ACTIVE_IDENTITY_KEY = ""
        return
    copied = {str(key): value for key, value in dict(payload).items()}
    copied["updated_at"] = datetime.now().isoformat(timespec="seconds")
    identity_key = str(copied.get("identity_key", "") or "").strip()
    _RUST_BACKEND_CAPABILITY_STATUS = copied
    _RUST_BACKEND_ACTIVE_IDENTITY_KEY = identity_key


def _snapshot_rust_backend_capability_status() -> Dict[str, Any]:
    """Return a copy of the latest runtime Rust backend capability snapshot.

    Purpose:
        Provide safe read-only access to Rust capability/deprecation diagnostics.
    Why:
        Runtime status rendering and snapshot dumps should not mutate shared
        capability state.
    Inputs:
        None.
    Outputs:
        Dict[str, Any]: Copy of capability snapshot fields.
    Side Effects:
        None.
    Exceptions:
        Invalid cache values return an empty payload.
    """
    if not isinstance(_RUST_BACKEND_CAPABILITY_STATUS, Mapping):
        return {}
    return dict(_RUST_BACKEND_CAPABILITY_STATUS)


def _collect_rust_kernel_contract_audit(
    capability_payload: Optional[Mapping[str, Any]],
    *,
    backend_module: Any = None,
) -> Dict[str, Any]:
    """Collect one warn-only Rust kernel contract audit payload.

    Purpose:
        Summarize required/exported/callable Rust-kernel contract state for
        diagnostics snapshots.
    Why:
        Freeze investigations need explicit visibility into whether Python is
        routing to kernels that are missing from the loaded Rust module or
        manifest.
    Inputs:
        capability_payload: Optional cached capability payload from
            `_snapshot_rust_backend_capability_status`.
        backend_module: Optional backend module override; defaults to the active
            module cache.
    Outputs:
        Dict[str, Any]: Contract audit payload with required exports, callable
        exports, manifest exports, and mismatch lists/counts.
    Side Effects:
        None.
    Exceptions:
        Invalid payload shapes are normalized to empty-safe values.
    """
    required_kernels = list(RUST_REQUIRED_KERNEL_EXPORTS)
    backend_obj = backend_module
    if backend_obj is None:
        backend_obj = globals().get("_RUST_BACKEND_MODULE", None)
    callable_required = sorted(
        [
            kernel_name
            for kernel_name in required_kernels
            if callable(getattr(backend_obj, kernel_name, None))
        ]
    )
    callable_set = set(callable_required)
    missing_callables = [
        kernel_name for kernel_name in required_kernels if kernel_name not in callable_set
    ]
    manifest_map = (
        dict(capability_payload.get("manifest") or {})
        if isinstance(capability_payload, Mapping)
        else {}
    )
    exported_raw = manifest_map.get("exported_kernels", ())
    manifest_exported = []
    if isinstance(exported_raw, Sequence) and not isinstance(
        exported_raw, (str, bytes, bytearray)
    ):
        manifest_exported = sorted(
            {
                str(item or "").strip()
                for item in exported_raw
                if str(item or "").strip()
            }
        )
    manifest_set = set(manifest_exported)
    missing_manifest_exports = [
        kernel_name for kernel_name in required_kernels if kernel_name not in manifest_set
    ]
    callable_not_manifest = [
        kernel_name
        for kernel_name in required_kernels
        if kernel_name in callable_set and kernel_name not in manifest_set
    ]
    manifest_not_callable = [
        kernel_name
        for kernel_name in required_kernels
        if kernel_name in manifest_set and kernel_name not in callable_set
    ]
    routing_mismatches = sorted(
        {
            *missing_callables,
            *missing_manifest_exports,
            *callable_not_manifest,
            *manifest_not_callable,
        }
    )
    return {
        "required_kernels": required_kernels,
        "required_kernel_count": int(len(required_kernels)),
        "callable_required_kernels": callable_required,
        "callable_required_count": int(len(callable_required)),
        "missing_callable_kernels": missing_callables,
        "missing_callable_count": int(len(missing_callables)),
        "manifest_exported_kernels": manifest_exported,
        "manifest_exported_count": int(len(manifest_exported)),
        "missing_manifest_required_kernels": missing_manifest_exports,
        "missing_manifest_required_count": int(len(missing_manifest_exports)),
        "callable_not_manifest_kernels": callable_not_manifest,
        "callable_not_manifest_count": int(len(callable_not_manifest)),
        "manifest_not_callable_kernels": manifest_not_callable,
        "manifest_not_callable_count": int(len(manifest_not_callable)),
        "routing_mismatches": routing_mismatches,
        "routing_mismatch_count": int(len(routing_mismatches)),
        "backend_module_loaded": bool(backend_obj is not None),
        "backend_module_name": str(
            getattr(backend_obj, "__name__", "") if backend_obj is not None else ""
        ).strip(),
        "backend_module_path": str(
            getattr(backend_obj, "__file__", "") if backend_obj is not None else ""
        ).strip(),
        "manifest_interface_id": str(manifest_map.get("interface_id") or "").strip(),
        "manifest_interface_version": str(
            manifest_map.get("interface_version") or ""
        ).strip(),
        "manifest_error": str(manifest_map.get("manifest_error") or "").strip(),
    }


def _set_rust_backend_expected_identity(
    capability_payload: Mapping[str, Any],
    *,
    source: str,
) -> None:
    """Record the expected Rust backend identity for the current session.

    Purpose:
        Lock runtime Rust calls to the same validated module identity selected by
        startup preflight or successful repair.
    Why:
        Startup/runtime consistency requires one expected module identity gate.
    Inputs:
        capability_payload: Validated capability payload with identity key fields.
        source: Short source token for diagnostics.
    Outputs:
        None.
    Side Effects:
        Updates `_RUST_BACKEND_EXPECTED_IDENTITY_KEY`.
    Exceptions:
        Missing identity keys are ignored.
    """
    global _RUST_BACKEND_EXPECTED_IDENTITY_KEY
    expected_key = str(capability_payload.get("identity_key", "") or "").strip()
    if not expected_key:
        return
    _RUST_BACKEND_EXPECTED_IDENTITY_KEY = expected_key
    _emit_runtime_debug_event(
        "rust.backend",
        "Rust backend expected identity updated (%s).",
        str(source or "unknown"),
    )


def _is_rust_backend_identity_consistent(identity_key: str) -> bool:
    """Return whether one Rust backend identity key matches session expectation.

    Purpose:
        Gate Rust execution when module identity drifts from startup/repair
        validated backend identity.
    Why:
        The app should not silently switch to a different Rust module mid-session.
    Inputs:
        identity_key: Active backend identity key.
    Outputs:
        bool: True when no expected key is set or identity matches expectation.
    Side Effects:
        None.
    Exceptions:
        None.
    """
    expected_key = str(_RUST_BACKEND_EXPECTED_IDENTITY_KEY or "").strip()
    if not expected_key:
        return True
    return bool(str(identity_key or "").strip() == expected_key)


def _collect_callable_parameter_names(
    callable_obj: Any,
) -> Tuple[Optional[Tuple[str, ...]], str]:
    """Collect declared parameter names for one callable.

    Purpose:
        Normalize callable signature inspection into one helper used by Rust
        capability contract validation.
    Why:
        Backend capability checks must fail closed when a callable exists but
        exposes a stale parameter contract.
    Inputs:
        callable_obj: Callable object whose parameter list should be inspected.
    Outputs:
        Tuple containing optional parameter-name tuple and source marker string.
    Side Effects:
        None.
    Exceptions:
        Signature-introspection failures are captured in the returned source text.
    """
    try:
        signature_obj = inspect.signature(callable_obj)
    except Exception as exc:
        text_signature = str(
            getattr(callable_obj, "__text_signature__", "") or ""
        ).strip()
        if text_signature:
            parsed_names = tuple(
                token
                for token in re.findall(r"[A-Za-z_][A-Za-z0-9_]*", text_signature)
                if token not in {"None", "True", "False", "self"}
            )
            if parsed_names:
                return parsed_names, "text_signature"
        return None, f"signature_unavailable:{type(exc).__name__}"
    names: List[str] = []
    for param in signature_obj.parameters.values():
        if param.kind in (
            inspect.Parameter.POSITIONAL_ONLY,
            inspect.Parameter.POSITIONAL_OR_KEYWORD,
            inspect.Parameter.KEYWORD_ONLY,
        ):
            names.append(str(param.name))
    return tuple(names), "inspect.signature"


def _validate_measured_ph_calibration_kernel_signature(
    resolver: Any,
) -> Tuple[bool, str]:
    """Validate measured-pH calibration kernel parameter contract.

    Purpose:
        Verify the loaded Rust measured-pH kernel exposes the expected
        multi-anchor/prior-aware interface.
    Why:
        Callable-only checks cannot detect stale binaries with legacy parameter
        layouts that mis-bind payload values at runtime.
    Inputs:
        resolver: Candidate `measured_ph_uptake_calibration_core` callable.
    Outputs:
        Tuple `(is_compatible, details)` describing compatibility status.
    Side Effects:
        None.
    Exceptions:
        Signature parse failures are returned as fail-closed mismatch details.
    """
    parameter_names, source = _collect_callable_parameter_names(resolver)
    if parameter_names is None:
        return (
            False,
            "measured_ph_uptake_calibration_core signature unavailable "
            f"({source}).",
        )
    missing_params = [
        token
        for token in RUST_MEASURED_PH_CALIBRATION_REQUIRED_PARAMS
        if token not in parameter_names
    ]
    if missing_params:
        return (
            False,
            "measured_ph_uptake_calibration_core signature missing params="
            + ", ".join(missing_params)
            + f" (source={source}).",
        )
    return True, ""


def _evaluate_rust_backend_capability(backend: Any) -> Dict[str, Any]:
    """Evaluate Rust backend manifest, kernels, identity, and toolchain profile.

    Purpose:
        Produce one normalized capability payload used to classify active Rust
        backend state as ready or deprecated.
    Why:
        Startup and runtime paths need deterministic enforcement of manifest +
        required-kernel contract semantics plus runtime-profile tool consistency.
    Inputs:
        backend: Imported Rust backend module object.
    Outputs:
        Dict[str, Any]: Capability payload including state/reason, missing kernels,
        manifest metadata, identity fields, and toolchain diagnostics.
    Side Effects:
        None.
    Exceptions:
        Module/manifest introspection failures are captured in payload fields.
    """
    module_path = str(getattr(backend, "__file__", "") or "").strip()
    required_kernels = list(RUST_REQUIRED_KERNEL_EXPORTS)
    missing_kernels = [
        kernel_name
        for kernel_name in required_kernels
        if not callable(getattr(backend, kernel_name, None))
    ]
    measured_kernel_signature_details = ""
    if "measured_ph_uptake_calibration_core" not in missing_kernels:
        measured_kernel = getattr(backend, "measured_ph_uptake_calibration_core", None)
        signature_ok, signature_details = (
            _validate_measured_ph_calibration_kernel_signature(measured_kernel)
        )
        if not signature_ok:
            measured_kernel_signature_details = str(signature_details or "").strip()
    manifest_payload: Dict[str, Any] = {}
    manifest_error = ""
    manifest_callable = getattr(backend, "rust_backend_manifest", None)
    if callable(manifest_callable):
        try:
            raw_manifest = manifest_callable()
        except Exception as exc:
            raw_manifest = {}
            manifest_error = str(exc or "")
        if isinstance(raw_manifest, Mapping):
            manifest_payload = dict(raw_manifest)
        elif not manifest_error:
            manifest_error = "manifest payload is not a mapping"
    else:
        manifest_error = "manifest function missing"
    interface_id = str(manifest_payload.get("interface_id", "") or "").strip()
    interface_version = str(manifest_payload.get("interface_version", "") or "").strip()
    crate_version = str(manifest_payload.get("crate_version", "") or "").strip()
    module_name = str(
        manifest_payload.get("module_name", getattr(backend, "__name__", "")) or ""
    ).strip()
    exported_raw = manifest_payload.get("exported_kernels", ())
    if isinstance(exported_raw, Sequence) and not isinstance(
        exported_raw, (str, bytes, bytearray)
    ):
        exported_kernels = sorted(
            {
                str(item or "").strip()
                for item in exported_raw
                if str(item or "").strip()
            }
        )
    else:
        exported_kernels = []
        if callable(manifest_callable) and not manifest_error:
            manifest_error = "manifest exported_kernels is not a sequence"
    identity_payload = {
        "module_path": module_path,
        "module_name": module_name,
        "crate_version": crate_version,
        "interface_id": interface_id,
        "interface_version": interface_version,
    }
    identity_key = _rust_backend_identity_key(identity_payload)
    toolchain_diag = _resolve_runtime_rust_toolchain_diagnostics()
    toolchain_state = str(
        toolchain_diag.get("toolchain_consistency_state") or ""
    ).strip()
    toolchain_reason = str(
        toolchain_diag.get("toolchain_consistency_reason") or ""
    ).strip()
    toolchain_details = str(
        toolchain_diag.get("toolchain_consistency_details") or ""
    ).strip()
    state = "ready"
    reason = "ready"
    detail_bits: List[str] = []
    warning_bits: List[str] = []
    if not callable(manifest_callable):
        state = "deprecated"
        reason = "manifest_missing"
    elif manifest_error:
        state = "deprecated"
        reason = "invalid_manifest"
        detail_bits.append(manifest_error)
    elif (
        interface_id != RUST_BACKEND_INTERFACE_ID_EXPECTED
        or interface_version != RUST_BACKEND_INTERFACE_VERSION_EXPECTED
    ):
        state = "deprecated"
        reason = "interface_mismatch"
    elif missing_kernels:
        state = "deprecated"
        reason = "missing_kernels"
    elif measured_kernel_signature_details:
        state = "deprecated"
        reason = "kernel_signature_mismatch"
    if state == "deprecated":
        if reason == "manifest_missing":
            detail_bits.append("rust_backend_manifest export not found")
        elif reason == "interface_mismatch":
            detail_bits.append(
                "expected "
                f"{RUST_BACKEND_INTERFACE_ID_EXPECTED}:{RUST_BACKEND_INTERFACE_VERSION_EXPECTED}"
                " got "
                f"{interface_id or '(missing)'}:{interface_version or '(missing)'}"
            )
        elif reason == "toolchain_inconsistent":
            detail_bits.append(
                "runtime profile toolchain is inconsistent: "
                + (toolchain_reason or "unknown")
            )
            if toolchain_details:
                detail_bits.append(toolchain_details)
        elif (
            reason == "kernel_signature_mismatch"
            and measured_kernel_signature_details
        ):
            detail_bits.append(measured_kernel_signature_details)
        if missing_kernels:
            detail_bits.append(f"missing kernels={', '.join(missing_kernels)}")
    elif toolchain_state == "inconsistent":
        # Keep Rust available when extension import/manifest/kernel contracts are
        # healthy. Toolchain mismatch remains diagnostic-only unless capability
        # compatibility checks fail for manifest/interface/kernel reasons above.
        warning_bits.append(
            "runtime profile toolchain is inconsistent: "
            + (toolchain_reason or "unknown")
        )
        if toolchain_details:
            warning_bits.append(toolchain_details)
    details = " | ".join(bit for bit in detail_bits if bit)
    warning_details = " | ".join(bit for bit in warning_bits if bit)
    payload = {
        "state": state,
        "reason": reason,
        "details": details,
        "warning_state": "toolchain_inconsistent" if warning_details else "",
        "warning_details": warning_details,
        "toolchain_warning": bool(warning_details),
        "required_kernels": required_kernels,
        "missing_kernels": missing_kernels,
        "kernel_signature_mismatch": bool(measured_kernel_signature_details),
        "kernel_signature_details": measured_kernel_signature_details,
        "manifest": {
            "interface_id": interface_id,
            "interface_version": interface_version,
            "crate_version": crate_version,
            "module_name": module_name,
            "exported_kernels": exported_kernels,
            "manifest_error": manifest_error,
        },
        "module_path": module_path,
        "module_identity": identity_payload,
        "identity_key": identity_key,
        "identity_consistent": _is_rust_backend_identity_consistent(identity_key),
        "runtime_profile": str(toolchain_diag.get("runtime_profile") or "").strip(),
        "cargo_path": str(toolchain_diag.get("cargo_path") or "").strip(),
        "cargo_source": str(toolchain_diag.get("cargo_source") or "").strip(),
        "cargo_valid": bool(toolchain_diag.get("cargo_valid")),
        "rustc_path": str(toolchain_diag.get("rustc_path") or "").strip(),
        "rustc_source": str(toolchain_diag.get("rustc_source") or "").strip(),
        "rustc_valid": bool(toolchain_diag.get("rustc_valid")),
        "toolchain_consistency_state": toolchain_state,
        "toolchain_consistency_reason": toolchain_reason,
        "toolchain_consistency_details": toolchain_details,
    }
    return payload


def _is_rust_backend_deprecated_error(error: Any) -> bool:
    """Return whether one Rust import/runtime error indicates deprecated backend.

    Purpose:
        Detect fail-closed deprecated-interface errors emitted by backend loading.
    Why:
        Startup and developer diagnostics need to branch cleanly into repair
        prompts when Rust module compatibility is stale.
    Inputs:
        error: Exception or error text candidate.
    Outputs:
        bool: True when the deprecated-backend prefix is present.
    Side Effects:
        None.
    Exceptions:
        Non-stringable values return False.
    """
    if error is None:
        return False
    try:
        return _RUST_BACKEND_DEPRECATED_PREFIX in str(error or "")
    except Exception:
        return False


def _is_rust_backend_identity_mismatch_error(error: Any) -> bool:
    """Return whether one Rust error indicates module identity mismatch.

    Purpose:
        Detect runtime module-identity drift failures raised by backend loading.
    Why:
        Identity mismatch requires fail-closed Rust routing plus clear diagnostics.
    Inputs:
        error: Exception or error text candidate.
    Outputs:
        bool: True when identity-mismatch prefix is present.
    Side Effects:
        None.
    Exceptions:
        Non-stringable values return False.
    """
    if error is None:
        return False
    try:
        return _RUST_BACKEND_IDENTITY_MISMATCH_PREFIX in str(error or "")
    except Exception:
        return False


def _is_rust_backend_restart_required_error(error: Any) -> bool:
    """Return whether one Rust error signals restart-required backend loading.

    Purpose:
        Detect restart-required markers emitted when subprocess validation passes
        but this process still holds a stale extension module image.
    Why:
        Setup/preflight flows must distinguish stale in-process imports from true
        build or manifest failures to avoid misleading repair loops.
    Inputs:
        error: Exception or error text candidate.
    Outputs:
        bool: True when the restart-required prefix is present.
    Side Effects:
        None.
    Exceptions:
        Non-stringable values return False.
    """
    if error is None:
        return False
    try:
        return _RUST_BACKEND_RESTART_REQUIRED_PREFIX in str(error or "")
    except Exception:
        return False


def _build_rust_backend_restart_required_error(
    import_error: Any,
    verification_payload: Optional[Mapping[str, Any]] = None,
) -> Optional[RuntimeError]:
    """Build restart-required error when stale in-process Rust module is detected.

    Purpose:
        Convert stale in-process import mismatches into one explicit marker.
    Why:
        A successful interpreter-pinned subprocess import proves the new build is
        valid, so in-process mismatch should request restart instead of rebuild.
    Inputs:
        import_error: In-process import error from `_load_rust_backend`.
        verification_payload: Optional subprocess verification payload.
    Outputs:
        Optional[RuntimeError]: Marker error when restart is required, else None.
    Side Effects:
        None.
    Exceptions:
        Invalid payloads are handled defensively and return None.
    """
    if import_error is None:
        return None
    if not (
        _is_rust_backend_deprecated_error(import_error)
        or _is_rust_backend_identity_mismatch_error(import_error)
    ):
        return None
    if not isinstance(verification_payload, Mapping) or not bool(
        verification_payload.get("ok")
    ):
        return None
    interface_id = str(verification_payload.get("interface_id") or "").strip()
    interface_version = str(verification_payload.get("interface_version") or "").strip()
    module_path = str(verification_payload.get("module_path") or "").strip()
    detail_bits: List[str] = [
        "subprocess import and manifest checks passed",
        "this process still has a stale Rust module image loaded",
    ]
    if interface_id or interface_version:
        detail_bits.append(
            "verified interface="
            f"{interface_id or '(missing)'}:{interface_version or '(missing)'}"
        )
    if module_path:
        detail_bits.append(f"verified module={module_path}")
    import_detail = str(import_error or "").strip()
    if import_detail:
        detail_bits.append(f"in_process_error={import_detail}")
    return RuntimeError(
        f"{_RUST_BACKEND_RESTART_REQUIRED_PREFIX}stale_in_process_module "
        + " | ".join(detail_bits)
    )


def _median_runtime_ms(samples: Sequence[float]) -> float:
    """Return the median runtime from millisecond samples.

    Purpose:
        Normalize a small sample set into one stable latency metric.
    Why:
        Rust kernel auto-gating compares median Python and Rust runtimes so short
        jitter spikes do not dominate one-shot timing checks.
    Inputs:
        samples: Sequence of runtime values in milliseconds.
    Outputs:
        float: Median runtime in milliseconds (or 0.0 for empty input).
    Side Effects:
        None.
    Exceptions:
        Invalid sample values are ignored.
    """
    values: List[float] = []
    for raw in samples:
        try:
            value = float(raw)
        except Exception:
            continue
        if math.isfinite(value) and value >= 0.0:
            values.append(value)
    if not values:
        return 0.0
    values.sort()
    mid = len(values) // 2
    if len(values) % 2:
        return values[mid]
    return 0.5 * (values[mid - 1] + values[mid])


def _rust_kernel_policy_fingerprint_key() -> str:
    """Return the interpreter fingerprint key used for kernel auto policy.

    Purpose:
        Provide one stable key for persisted per-kernel Rust auto-gate decisions.
    Why:
        Rust performance policy should be scoped to interpreter/runtime identity
        to avoid reusing stale decisions across ABI/environment changes.
    Inputs:
        None.
    Outputs:
        str: Runtime fingerprint key; empty string when unavailable.
    Side Effects:
        None.
    Exceptions:
        Fingerprint serialization failures are handled internally.
    """
    try:
        return _current_rust_install_fingerprint_key()
    except Exception:
        return ""


def _emit_runtime_debug_event(category: str, message: str, *args: Any) -> None:
    """Emit one module-level debug event gated by settings and category toggles.

    Purpose:
        Provide debug logging from module-level Rust/runtime helpers that do not
        have access to the `UnifiedApp._dbg` instance method.
    Why:
        Rust kernel guards and timeout paths need diagnostics during workflow
        execution, including contexts that run outside widget-bound methods.
    Inputs:
        category: Debug category key used for routing and gating.
        message: Logger message template.
        *args: Optional logger format arguments.
    Outputs:
        None.
    Side Effects:
        Writes one debug line to `_GL260_LOGGER` when debug/category gates pass.
    Exceptions:
        Logging failures are swallowed to preserve workflow execution.
    """
    try:
        if not bool(settings.get("debug_enabled", False)):
            return
        categories = settings.get("debug_categories")
        if not isinstance(categories, Mapping):
            return
        if not bool(categories.get(category, False)):
            return
        _GL260_LOGGER.debug("[%s] " + str(message), category, *args)
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass


def _normalize_timeout_ms(
    value: Any,
    *,
    default_ms: int,
    min_ms: int = 100,
    max_ms: int = 120_000,
) -> int:
    """Normalize one timeout setting value to a bounded integer milliseconds value.

    Purpose:
        Coerce timeout inputs from settings/UI controls into safe numeric values.
    Why:
        Rust probes/kernel calls need deterministic timeout bounds to prevent
        UI freezes and avoid invalid persistence values.
    Inputs:
        value: Candidate timeout input.
        default_ms: Fallback timeout when parsing fails.
        min_ms: Lower inclusive timeout bound.
        max_ms: Upper inclusive timeout bound.
    Outputs:
        int: Bounded timeout in milliseconds.
    Side Effects:
        None.
    Exceptions:
        Invalid values are converted to `default_ms`.
    """
    try:
        timeout_value = int(float(value))
    except Exception:
        timeout_value = int(default_ms)
    timeout_value = max(int(min_ms), timeout_value)
    timeout_value = min(int(max_ms), timeout_value)
    return int(timeout_value)


def _resolve_rust_runtime_timeout_ms(setting_key: str, default_ms: int) -> int:
    """Resolve one normalized Rust runtime timeout setting from shared settings.

    Purpose:
        Provide a single lookup path for workflow probe/kernel timeout values.
    Why:
        Runtime timeout controls are user-configurable and must remain normalized
        when read from mutable in-memory settings.
    Inputs:
        setting_key: Rust timeout key in the settings dictionary.
        default_ms: Fallback timeout in milliseconds.
    Outputs:
        int: Normalized timeout in milliseconds.
    Side Effects:
        Ensures Rust runtime defaults are present in the shared settings map.
    Exceptions:
        Missing/invalid settings payloads fall back to `default_ms`.
    """
    settings_map = globals().get("settings", None)
    if not isinstance(settings_map, dict):
        return _normalize_timeout_ms(default_ms, default_ms=default_ms)
    _apply_rust_runtime_settings_defaults(settings_map)
    return _normalize_timeout_ms(
        settings_map.get(setting_key, default_ms), default_ms=default_ms
    )


def _run_callable_with_timeout(
    runner: Callable[[], Any],
    *,
    timeout_seconds: Optional[float],
    thread_name: str,
) -> Tuple[str, Any, Optional[BaseException]]:
    """Execute one callable with an optional timeout using a daemon worker thread.

    Purpose:
        Provide timeout-bounded execution for potentially blocking runtime probes
        and Rust-kernel bridge calls.
    Why:
        Worker hangs in Rust extension calls or environment probes can freeze
        workflows unless execution is bounded and fail-closed.
    Inputs:
        runner: Callable to execute.
        timeout_seconds: Optional timeout budget; non-positive disables timeout.
        thread_name: Worker-thread name for diagnostics.
    Outputs:
        Tuple `(status, value, error)` where status is `ok`, `timeout`, or `error`.
    Side Effects:
        Starts one daemon thread when timeout mode is enabled.
    Exceptions:
        Worker exceptions are captured in the tuple and not raised here.
    """
    if timeout_seconds is None:
        timeout_value = 0.0
    else:
        try:
            timeout_value = float(timeout_seconds)
        except Exception:
            timeout_value = 0.0
    if timeout_value <= 0.0:
        try:
            return "ok", runner(), None
        except BaseException as exc:
            return "error", None, exc

    state: Dict[str, Any] = {"value": None, "error": None}
    done_event = threading.Event()

    def _worker() -> None:
        """Execute the timed callable and capture completion state."""
        try:
            state["value"] = runner()
        except BaseException as exc:
            state["error"] = exc
        finally:
            done_event.set()

    worker = threading.Thread(
        target=_worker,
        name=str(thread_name or "gl260-timeout-worker"),
        daemon=True,
    )
    worker.start()
    finished = done_event.wait(timeout=max(timeout_value, 0.001))
    if not finished:
        return "timeout", None, None
    worker_error = state.get("error")
    if isinstance(worker_error, BaseException):
        return "error", None, worker_error
    return "ok", state.get("value"), None


def _rust_kernel_health_session_key(kernel_name: str) -> str:
    """Return the runtime-scoped session key for one Rust kernel health record.

    Purpose:
        Scope in-memory kernel health guards to both runtime fingerprint and
        kernel identity.
    Why:
        One failing kernel should be disabled for the current runtime session
        without affecting unrelated kernels.
    Inputs:
        kernel_name: Kernel identifier string.
    Outputs:
        str: Session key used by `_RUST_KERNEL_HEALTH_SESSION`.
    Side Effects:
        None.
    Exceptions:
        Missing runtime fingerprint falls back to a process-local key.
    """
    kernel_token = str(kernel_name or "").strip() or "unnamed_kernel"
    fingerprint = _rust_kernel_policy_fingerprint_key()
    if not fingerprint:
        fingerprint = f"runtime:{os.getpid()}"
    return f"{fingerprint}::{kernel_token}"


def _is_rust_kernel_session_unhealthy(kernel_name: str) -> bool:
    """Return whether a Rust kernel has been marked unhealthy this session.

    Purpose:
        Provide one guard check that short-circuits repeated failing kernel calls.
    Why:
        Re-attempting known-bad kernels in hot workflows can repeatedly stall UI
        operations and obscure fallback behavior.
    Inputs:
        kernel_name: Kernel identifier.
    Outputs:
        bool: True when kernel is marked unhealthy in session cache.
    Side Effects:
        None.
    Exceptions:
        Invalid cache payloads are treated as healthy.
    """
    record = _RUST_KERNEL_HEALTH_SESSION.get(_rust_kernel_health_session_key(kernel_name), {})
    if not isinstance(record, Mapping):
        return False
    return bool(record.get("healthy") is False)


def _mark_rust_kernel_session_unhealthy(
    kernel_name: str,
    *,
    reason: str,
    details: str = "",
) -> None:
    """Mark one Rust kernel unhealthy for the active runtime session.

    Purpose:
        Record fail-closed session state after timeout/error/invalid Rust payloads.
    Why:
        Once a kernel fails critically in-session, retries should stop until
        an explicit reset to prevent repeated stalls.
    Inputs:
        kernel_name: Kernel identifier.
        reason: Short failure reason token.
        details: Optional detailed message.
    Outputs:
        None.
    Side Effects:
        Updates `_RUST_KERNEL_HEALTH_SESSION` and emits debug trace lines.
    Exceptions:
        Cache/logging failures are handled best-effort.
    """
    session_key = _rust_kernel_health_session_key(kernel_name)
    record = _RUST_KERNEL_HEALTH_SESSION.get(session_key)
    if not isinstance(record, dict):
        record = {}
        _RUST_KERNEL_HEALTH_SESSION[session_key] = record
    already_unhealthy = bool(record.get("healthy") is False)
    if not already_unhealthy:
        record["reason"] = str(reason or "failure").strip() or "failure"
        record["details"] = str(details or "").strip()
    elif not str(record.get("details") or "").strip() and str(details or "").strip():
        record["details"] = str(details).strip()
    record["healthy"] = False
    record["updated_at"] = datetime.now().isoformat()
    if already_unhealthy:
        return
    _emit_runtime_debug_event(
        "speciation.fallback",
        "Rust kernel %s disabled for session (%s%s).",
        kernel_name,
        record["reason"],
        f"; {record['details']}" if record["details"] else "",
    )
    _emit_runtime_debug_event(
        "rust.backend",
        "Rust kernel health update %s -> unhealthy (%s).",
        kernel_name,
        record["reason"],
    )


def _clear_rust_kernel_session_health(kernel_name: Optional[str] = None) -> None:
    """Clear Rust kernel unhealthy session records.

    Purpose:
        Reset per-session kernel health guards globally or for one kernel.
    Why:
        Developer diagnostics need a manual recovery path after fail-closed
        timeout/error conditions.
    Inputs:
        kernel_name: Optional kernel identifier to clear selectively.
    Outputs:
        None.
    Side Effects:
        Mutates `_RUST_KERNEL_HEALTH_SESSION`.
    Exceptions:
        None.
    """
    if kernel_name is None:
        _RUST_KERNEL_HEALTH_SESSION.clear()
        return
    _RUST_KERNEL_HEALTH_SESSION.pop(_rust_kernel_health_session_key(kernel_name), None)


def _reset_rust_session_caches_after_backend_ready(*, source: str) -> None:
    """Reset Rust fail-closed session caches after backend readiness is restored.

    Purpose:
        Clear per-session kernel health and auto-policy cache records after a
        successful Rust install/reload cycle.
    Why:
        Session fail-closed flags can persist after repair and incorrectly keep
        healthy rebuilt kernels disabled until process restart.
    Inputs:
        source: Short source token describing where readiness was re-established.
    Outputs:
        None.
    Side Effects:
        Clears `_RUST_KERNEL_HEALTH_SESSION` and
        `_RUST_KERNEL_AUTO_POLICY_SESSION_CACHE`; emits one debug line when
        caches were non-empty.
    Exceptions:
        None.
    """
    had_kernel_health = bool(_RUST_KERNEL_HEALTH_SESSION)
    had_auto_policy = bool(_RUST_KERNEL_AUTO_POLICY_SESSION_CACHE)
    _clear_rust_kernel_session_health()
    _RUST_KERNEL_AUTO_POLICY_SESSION_CACHE.clear()
    if had_kernel_health or had_auto_policy:
        _emit_runtime_debug_event(
            "rust.backend",
            "Rust session caches cleared after backend ready (%s).",
            str(source or "unknown"),
        )


def _snapshot_rust_kernel_session_health() -> Dict[str, Dict[str, Any]]:
    """Return a copy of in-session Rust kernel health records.

    Purpose:
        Provide a safe diagnostics snapshot of kernel health fail-closed state.
    Why:
        Runtime-tab diagnostics should expose current kernel health without
        allowing accidental mutation of the live cache.
    Inputs:
        None.
    Outputs:
        Dict[str, Dict[str, Any]]: Shallow-copied health payloads keyed by
        session fingerprint/kernels.
    Side Effects:
        None.
    Exceptions:
        Invalid cache entries are ignored.
    """
    snapshot: Dict[str, Dict[str, Any]] = {}
    for key, record in _RUST_KERNEL_HEALTH_SESSION.items():
        if not isinstance(record, Mapping):
            continue
        snapshot[str(key)] = {
            "healthy": bool(record.get("healthy", True)),
            "reason": str(record.get("reason", "") or ""),
            "details": str(record.get("details", "") or ""),
            "updated_at": str(record.get("updated_at", "") or ""),
        }
    return snapshot


def _run_rust_kernel_with_timeout(
    kernel_name: str,
    runner: Callable[[], Any],
    *,
    timeout_ms: Optional[int] = None,
) -> Any:
    """Execute one Rust kernel call with timeout and session health fail-closed.

    Purpose:
        Centralize timeout-bounded Rust kernel invocation for speciation bridges.
    Why:
        Individual bridge wrappers must fail quickly and consistently on hangs or
        runtime exceptions to keep workflows responsive.
    Inputs:
        kernel_name: Kernel identifier used for session health tracking.
        runner: Callable that performs the direct Rust invocation.
        timeout_ms: Optional explicit timeout override in milliseconds.
    Outputs:
        Any: Rust payload on success, or None on timeout/error/disabled state.
    Side Effects:
        Updates kernel health session cache and `_RUST_BACKEND_IMPORT_ERROR`
        on runtime failures.
    Exceptions:
        Runtime failures are converted to None return values.
    """
    if _is_rust_kernel_session_unhealthy(kernel_name):
        _emit_runtime_debug_event(
            "speciation.runtime",
            "Skipping Rust kernel %s; kernel marked unhealthy for this session.",
            kernel_name,
        )
        return None
    backend_error = globals().get("_RUST_BACKEND_IMPORT_ERROR", None)
    if _is_rust_backend_deprecated_error(
        backend_error
    ) or _is_rust_backend_identity_mismatch_error(backend_error):
        _mark_rust_kernel_session_unhealthy(
            kernel_name,
            reason="backend_deprecated",
            details=str(backend_error or ""),
        )
        return None

    timeout_value_ms = (
        _normalize_timeout_ms(timeout_ms, default_ms=2500)
        if timeout_ms is not None
        else _resolve_rust_runtime_timeout_ms("rust_kernel_call_timeout_ms", 2500)
    )
    timeout_seconds = max(float(timeout_value_ms) / 1000.0, 0.001)
    status, payload, run_error = _run_callable_with_timeout(
        runner,
        timeout_seconds=timeout_seconds,
        thread_name=f"gl260-rust-{kernel_name}",
    )
    if status == "timeout":
        settings_map = globals().get("settings", None)
        disable_after_timeout = True
        if isinstance(settings_map, dict):
            _apply_rust_runtime_settings_defaults(settings_map)
            disable_after_timeout = bool(
                settings_map.get("rust_disable_kernel_after_timeout", True)
            )
        if disable_after_timeout:
            _mark_rust_kernel_session_unhealthy(
                kernel_name,
                reason="timeout",
                details=f"timeout_ms={int(timeout_value_ms)}",
            )
        _emit_runtime_debug_event(
            "speciation.runtime",
            "Rust kernel %s timed out after %sms; using Python fallback.",
            kernel_name,
            int(timeout_value_ms),
        )
        return None
    if status == "error":
        global _RUST_BACKEND_IMPORT_ERROR
        _RUST_BACKEND_IMPORT_ERROR = run_error
        error_name = type(run_error).__name__ if run_error is not None else "RuntimeError"
        _mark_rust_kernel_session_unhealthy(
            kernel_name,
            reason=f"error:{error_name}",
            details=str(run_error or ""),
        )
        return None
    return payload


def _get_persisted_rust_kernel_policy(kernel_name: str) -> Optional[bool]:
    """Return persisted Rust auto-policy decision for one kernel.

    Purpose:
        Resolve a previously recorded auto-mode decision for a Rust kernel.
    Why:
        Auto-gate benchmarking should not run repeatedly once a stable decision is
        recorded for the current runtime fingerprint.
    Inputs:
        kernel_name: Kernel policy name key.
    Outputs:
        Optional[bool]: Persisted `use_rust` decision when available.
    Side Effects:
        None.
    Exceptions:
        Invalid settings payloads are treated as missing records.
    """
    settings_map = globals().get("settings", None)
    if not isinstance(settings_map, Mapping):
        return None
    fingerprint_key = _rust_kernel_policy_fingerprint_key()
    if not fingerprint_key:
        return None
    policy_root = settings_map.get("rust_kernel_auto_policy", {})
    if not isinstance(policy_root, Mapping):
        return None
    fp_policy = policy_root.get(fingerprint_key, {})
    if not isinstance(fp_policy, Mapping):
        return None
    record = fp_policy.get(kernel_name, {})
    if not isinstance(record, Mapping):
        return None
    if "use_rust" not in record:
        return None
    return bool(record.get("use_rust"))


def _persist_rust_kernel_policy_decision(
    kernel_name: str,
    *,
    use_rust: bool,
    rust_ms: float,
    python_ms: float,
) -> None:
    """Persist one Rust auto-policy decision for the active runtime.

    Purpose:
        Store kernel-level auto-gate outcomes in settings for future lookups.
    Why:
        Reusing decisions avoids repeated parity/timing probes during hot paths.
    Inputs:
        kernel_name: Kernel policy key.
        use_rust: Whether Rust should be used by default in `auto` mode.
        rust_ms: Median Rust runtime measurement in milliseconds.
        python_ms: Median Python runtime measurement in milliseconds.
    Outputs:
        None.
    Side Effects:
        Updates in-memory settings and best-effort persists settings to disk.
    Exceptions:
        Persistence failures are suppressed to avoid interrupting workflows.
    """
    settings_map = globals().get("settings", None)
    if not isinstance(settings_map, dict):
        return
    _apply_rust_runtime_settings_defaults(settings_map)
    fingerprint_key = _rust_kernel_policy_fingerprint_key()
    if not fingerprint_key:
        return
    policy_root = settings_map.setdefault("rust_kernel_auto_policy", {})
    if not isinstance(policy_root, dict):
        policy_root = {}
        settings_map["rust_kernel_auto_policy"] = policy_root
    fp_policy = policy_root.get(fingerprint_key)
    if not isinstance(fp_policy, dict):
        fp_policy = {}
        policy_root[fingerprint_key] = fp_policy
    fp_policy[kernel_name] = {
        "use_rust": bool(use_rust),
        "rust_ms": float(rust_ms),
        "python_ms": float(python_ms),
        "updated_at": datetime.now().isoformat(),
    }
    save_fn = globals().get("_save_settings_to_disk")
    if callable(save_fn):
        try:
            save_fn()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass


def _resolve_rust_kernel_auto_policy(
    kernel_name: str,
    *,
    rust_runner: Callable[[], Any],
    python_runner: Callable[[], Any],
    parity_checker: Optional[Callable[[Any, Any], bool]] = None,
) -> bool:
    """Resolve whether a Rust kernel should run by default in auto mode.

    Purpose:
        Centralize per-kernel parity + timing policy checks and caching.
    Why:
        v4.5.6 requires kernel-level default decisions where Rust is used only
        when parity passes and measured runtime is at least as fast as Python.
    Inputs:
        kernel_name: Unique kernel policy key.
        rust_runner: Callable that executes and returns the Rust path result.
        python_runner: Callable that executes and returns the Python path result.
        parity_checker: Optional comparator for result parity validation.
    Outputs:
        bool: True when Rust should be used for this kernel in auto mode.
    Side Effects:
        Reads/writes session cache and persisted settings policy records.
    Exceptions:
        Any timeout/parity/timing errors fail closed to Python policy.
    """
    if _current_rust_backend_mode() == "python":
        return False
    session_key = f"{_rust_kernel_policy_fingerprint_key()}::{kernel_name}"
    cached = _RUST_KERNEL_AUTO_POLICY_SESSION_CACHE.get(session_key)
    if isinstance(cached, bool):
        return cached
    if _is_rust_kernel_session_unhealthy(kernel_name):
        _RUST_KERNEL_AUTO_POLICY_SESSION_CACHE[session_key] = False
        _persist_rust_kernel_policy_decision(
            kernel_name,
            use_rust=False,
            rust_ms=0.0,
            python_ms=0.0,
        )
        return False
    persisted = _get_persisted_rust_kernel_policy(kernel_name)
    if isinstance(persisted, bool):
        _RUST_KERNEL_AUTO_POLICY_SESSION_CACHE[session_key] = persisted
        return persisted

    rust_result = None
    python_result = None
    rust_samples: List[float] = []
    python_samples: List[float] = []
    failure_reason = ""
    failure_details = ""
    probe_timeout_ms = _resolve_rust_runtime_timeout_ms(
        "rust_kernel_call_timeout_ms", 2500
    )
    probe_timeout_seconds = max(float(probe_timeout_ms) / 1000.0, 0.001)
    try:
        for _ in range(3):
            rust_start = time.perf_counter()
            probe_state, probe_payload, probe_error = _run_callable_with_timeout(
                rust_runner,
                timeout_seconds=probe_timeout_seconds,
                thread_name=f"gl260-rust-policy-{kernel_name}",
            )
            rust_result = probe_payload
            rust_samples.append((time.perf_counter() - rust_start) * 1000.0)
            if probe_state == "timeout":
                failure_reason = "auto_probe_timeout"
                failure_details = f"timeout_ms={int(probe_timeout_ms)}"
                break
            if probe_state == "error":
                error_name = (
                    type(probe_error).__name__
                    if probe_error is not None
                    else "RuntimeError"
                )
                failure_reason = f"auto_probe_error:{error_name}"
                failure_details = str(probe_error or "")
                break
            if rust_result is None:
                failure_reason = "auto_probe_none"
                failure_details = "Rust probe returned no payload."
                break
            py_start = time.perf_counter()
            python_result = python_runner()
            python_samples.append((time.perf_counter() - py_start) * 1000.0)
    except Exception as exc:
        failure_reason = f"auto_probe_error:{type(exc).__name__}"
        failure_details = str(exc)
    if failure_reason:
        _mark_rust_kernel_session_unhealthy(
            kernel_name,
            reason=failure_reason,
            details=failure_details,
        )
        _RUST_KERNEL_AUTO_POLICY_SESSION_CACHE[session_key] = False
        _persist_rust_kernel_policy_decision(
            kernel_name,
            use_rust=False,
            rust_ms=_median_runtime_ms(rust_samples),
            python_ms=_median_runtime_ms(python_samples),
        )
        return False
    if rust_result is None:
        _mark_rust_kernel_session_unhealthy(
            kernel_name,
            reason="auto_probe_none",
            details="Rust probe produced no payload.",
        )
        _RUST_KERNEL_AUTO_POLICY_SESSION_CACHE[session_key] = False
        _persist_rust_kernel_policy_decision(
            kernel_name,
            use_rust=False,
            rust_ms=_median_runtime_ms(rust_samples),
            python_ms=_median_runtime_ms(python_samples),
        )
        return False

    check_fn = parity_checker
    if check_fn is None:
        check_fn = lambda left, right: left == right
    parity_ok = False
    try:
        parity_ok = bool(check_fn(rust_result, python_result))
    except Exception:
        parity_ok = False
    if not parity_ok:
        _mark_rust_kernel_session_unhealthy(
            kernel_name,
            reason="parity_mismatch",
            details="Rust/Python auto-policy parity check failed.",
        )
        _RUST_KERNEL_AUTO_POLICY_SESSION_CACHE[session_key] = False
        _persist_rust_kernel_policy_decision(
            kernel_name,
            use_rust=False,
            rust_ms=_median_runtime_ms(rust_samples),
            python_ms=_median_runtime_ms(python_samples),
        )
        return False

    rust_ms = _median_runtime_ms(rust_samples)
    python_ms = _median_runtime_ms(python_samples)
    # >=0% faster policy means Rust must be no slower than Python.
    use_rust = bool(rust_ms <= python_ms)
    _RUST_KERNEL_AUTO_POLICY_SESSION_CACHE[session_key] = use_rust
    _persist_rust_kernel_policy_decision(
        kernel_name,
        use_rust=use_rust,
        rust_ms=rust_ms,
        python_ms=python_ms,
    )
    return use_rust


def _invalidate_rust_backend_cache() -> None:
    """Reset cached Rust backend module state.

    Purpose:
        Force the next backend access to re-attempt module import.
    Why:
        Install/build actions can make the module available during runtime; cache
        invalidation ensures the app sees that update immediately.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Clears module import cache variables and purges Rust package/submodule
        entries from `sys.modules`.
    Exceptions:
        None.
    """
    global _RUST_BACKEND_MODULE
    global _RUST_BACKEND_IMPORT_ERROR
    global _RUST_BACKEND_IMPORT_ATTEMPTED
    global _RUST_BACKEND_ACTIVE_IDENTITY_KEY
    _RUST_BACKEND_MODULE = None
    _RUST_BACKEND_IMPORT_ERROR = None
    _RUST_BACKEND_IMPORT_ATTEMPTED = False
    _RUST_BACKEND_ACTIVE_IDENTITY_KEY = ""
    _purge_rust_backend_module_import_cache()
    _set_rust_backend_capability_status(None)


def _purge_rust_backend_module_import_cache() -> Tuple[str, ...]:
    """Purge Rust backend package/submodule entries from Python import caches.

    Purpose:
        Remove in-process Rust backend modules so the next import resolves the
        newly built extension instead of stale package state.
    Why:
        `maturin develop` can finish successfully while `sys.modules` still holds
        a stale `gl260_rust_ext` object that lacks newly exported kernels.
    Inputs:
        None.
    Outputs:
        Tuple[str, ...]: Module names removed from `sys.modules` in removal order.
    Side Effects:
        Mutates `sys.modules` and invalidates import caches.
    Exceptions:
        Cache invalidation failures are tolerated to keep fallback paths safe.
    """
    purged_names: List[str] = []
    for module_name in (
        _RUST_BACKEND_EXTENSION_MODULE_NAME,
        _RUST_BACKEND_MODULE_NAME,
    ):
        token = str(module_name or "").strip()
        if not token:
            continue
        if token in sys.modules:
            sys.modules.pop(token, None)
            purged_names.append(token)
    try:
        importlib.invalidate_caches()
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass
    return tuple(purged_names)


def _resolve_rust_backend_capability_probe_module(
    backend: Any,
) -> Tuple[Any, str]:
    """Resolve the module object used for Rust capability contract checks.

    Purpose:
        Prefer capability validation against the compiled extension module object.
    Why:
        Package-level `__init__` exports can lag behind rebuilt extension exports,
        which produces false missing-kernel deprecations after successful builds.
    Inputs:
        backend: Imported Rust backend package/module candidate.
    Outputs:
        Tuple `(probe_module, probe_source)` where `probe_source` indicates the
        selected path (`"extension"`, `"package_fallback"`, or `"missing"`).
    Side Effects:
        May import `gl260_rust_ext.gl260_rust_ext`.
    Exceptions:
        Extension import failures are handled by falling back to `backend`.
    """
    if backend is None:
        return None, "missing"
    try:
        extension_backend = importlib.import_module(
            _RUST_BACKEND_EXTENSION_MODULE_NAME
        )
    except Exception:
        return backend, "package_fallback"
    if extension_backend is None:
        return backend, "package_fallback"
    return extension_backend, "extension"


def _evaluate_rust_backend_capability_with_probe_preference(
    backend: Any,
) -> Tuple[Any, Dict[str, Any], str]:
    """Evaluate Rust capability using extension-first probe selection.

    Purpose:
        Produce capability payloads from the most accurate import surface while
        preserving a compatibility fallback path.
    Why:
        Extension-first probing avoids false missing-kernel states after rebuilds,
        but package fallback preserves compatibility if extension probing fails.
    Inputs:
        backend: Imported Rust backend package/module candidate.
    Outputs:
        Tuple `(active_backend, capability_payload, probe_source)`.
    Side Effects:
        May import the extension submodule and updates selected backend handle.
    Exceptions:
        Capability evaluator exceptions are handled by
        `_evaluate_rust_backend_capability`.
    """
    probe_backend, probe_source = _resolve_rust_backend_capability_probe_module(backend)
    capability_payload = _evaluate_rust_backend_capability(probe_backend)
    if (
        probe_backend is not backend
        and str(capability_payload.get("state") or "").strip().lower() == "deprecated"
    ):
        # Keep one compatibility fallback to package-level probing so legacy
        # environments remain usable if submodule probing is unavailable.
        fallback_payload = _evaluate_rust_backend_capability(backend)
        if str(fallback_payload.get("state") or "").strip().lower() == "ready":
            return backend, fallback_payload, "package_compat_fallback"
    return probe_backend, capability_payload, probe_source


def _is_rust_backend_no_gil_mismatch_error(error: Any) -> bool:
    """Return whether an import error represents Rust no-GIL incompatibility.

    Purpose:
        Normalize detection of Rust backend failures caused by GIL re-enable
        transitions while importing the extension on free-threaded runs.
    Why:
        Workflow prompts and startup diagnostics need one reliable signal to
        branch into repair/fallback behavior for no-GIL compatibility issues.
    Inputs:
        error: Candidate exception captured from Rust backend import attempts.
    Outputs:
        True when `error` text carries the no-GIL mismatch marker, else False.
    Side Effects:
        None.
    Exceptions:
        Non-stringable values are handled safely and treated as non-mismatch.
    """
    if error is None:
        return False
    try:
        text = str(error or "")
    except Exception:
        return False
    return _RUST_BACKEND_GIL_MISMATCH_PREFIX in text


def _load_rust_backend(force_reload: bool = False, *, enforce_identity: bool = True):
    """Load and cache the optional Rust backend extension module.

    Purpose:
        Centralize import and cache behavior for the Rust acceleration module.
    Why:
        Repeated import attempts on hot paths add overhead and complicate fallback
        behavior; this helper provides a single cache-aware access point.
    Inputs:
        force_reload: When True, clear cache and re-import the module.
        enforce_identity: When True, fail closed when active module identity
            mismatches the startup/repair-validated identity for this session.
    Outputs:
        Imported module object, or None when unavailable/disabled.
    Side Effects:
        Updates module import cache and error tracking globals; records session
        no-GIL mismatch state when extension import re-enables the GIL.
    Exceptions:
        Import failures are captured and returned as None (no raise).
    """
    global _RUST_BACKEND_MODULE
    global _RUST_BACKEND_IMPORT_ERROR
    global _RUST_BACKEND_IMPORT_ATTEMPTED
    global _RUST_BACKEND_GIL_REENABLE_DETECTED

    if not _is_rust_backend_enabled():
        return None
    if force_reload:
        _invalidate_rust_backend_cache()
    if _RUST_BACKEND_GIL_REENABLE_DETECTED:
        _RUST_BACKEND_MODULE = None
        _RUST_BACKEND_IMPORT_ATTEMPTED = True
        _RUST_BACKEND_IMPORT_ERROR = RuntimeError(
            f"{_RUST_BACKEND_GIL_MISMATCH_PREFIX} Rust backend import previously "
            "re-enabled the GIL in this process; restart is required before Rust "
            "acceleration can be used again."
        )
        _set_rust_backend_capability_status(None)
        return None
    if _RUST_BACKEND_IMPORT_ATTEMPTED:
        if _RUST_BACKEND_MODULE is not None:
            capability_payload = _snapshot_rust_backend_capability_status()
            if not capability_payload:
                (
                    _RUST_BACKEND_MODULE,
                    capability_payload,
                    _,
                ) = _evaluate_rust_backend_capability_with_probe_preference(
                    _RUST_BACKEND_MODULE
                )
                _set_rust_backend_capability_status(capability_payload)
            elif str(capability_payload.get("state") or "").strip().lower() == "deprecated":
                (
                    _RUST_BACKEND_MODULE,
                    capability_payload,
                    _,
                ) = _evaluate_rust_backend_capability_with_probe_preference(
                    _RUST_BACKEND_MODULE
                )
                _set_rust_backend_capability_status(capability_payload)
            if str(capability_payload.get("state") or "").strip().lower() == "deprecated":
                detail_text = str(capability_payload.get("details") or "").strip()
                reason_text = str(capability_payload.get("reason") or "deprecated").strip()
                _RUST_BACKEND_MODULE = None
                _RUST_BACKEND_IMPORT_ERROR = RuntimeError(
                    f"{_RUST_BACKEND_DEPRECATED_PREFIX}{reason_text}"
                    + (f" ({detail_text})" if detail_text else "")
                )
                return None
            active_key = str(capability_payload.get("identity_key") or "").strip()
            if enforce_identity and not _is_rust_backend_identity_consistent(active_key):
                expected_key = str(_RUST_BACKEND_EXPECTED_IDENTITY_KEY or "").strip()
                _RUST_BACKEND_MODULE = None
                _RUST_BACKEND_IMPORT_ERROR = RuntimeError(
                    f"{_RUST_BACKEND_IDENTITY_MISMATCH_PREFIX}expected={expected_key} active={active_key}"
                )
                return None
        return _RUST_BACKEND_MODULE
    _RUST_BACKEND_IMPORT_ATTEMPTED = True
    gil_before_import = _current_gil_status()
    try:
        imported_backend = importlib.import_module(_RUST_BACKEND_MODULE_NAME)
        gil_after_import = _note_gil_reenable(
            _RUST_BACKEND_MODULE_NAME, gil_before_import
        )
        if gil_before_import is False and gil_after_import is True:
            _RUST_BACKEND_MODULE = None
            _RUST_BACKEND_GIL_REENABLE_DETECTED = True
            _RUST_BACKEND_IMPORT_ERROR = RuntimeError(
                f"{_RUST_BACKEND_GIL_MISMATCH_PREFIX} Importing "
                f"'{_RUST_BACKEND_MODULE_NAME}' re-enabled the GIL on a "
                "free-threaded runtime."
            )
            _set_rust_backend_capability_status(None)
            return None
        (
            _RUST_BACKEND_MODULE,
            capability_payload,
            _,
        ) = _evaluate_rust_backend_capability_with_probe_preference(imported_backend)
        _set_rust_backend_capability_status(capability_payload)
        if str(capability_payload.get("state") or "").strip().lower() == "deprecated":
            detail_text = str(capability_payload.get("details") or "").strip()
            reason_text = str(capability_payload.get("reason") or "deprecated").strip()
            _RUST_BACKEND_MODULE = None
            _RUST_BACKEND_IMPORT_ERROR = RuntimeError(
                f"{_RUST_BACKEND_DEPRECATED_PREFIX}{reason_text}"
                + (f" ({detail_text})" if detail_text else "")
            )
            return None
        active_key = str(capability_payload.get("identity_key") or "").strip()
        if enforce_identity and not _is_rust_backend_identity_consistent(active_key):
            expected_key = str(_RUST_BACKEND_EXPECTED_IDENTITY_KEY or "").strip()
            _RUST_BACKEND_MODULE = None
            _RUST_BACKEND_IMPORT_ERROR = RuntimeError(
                f"{_RUST_BACKEND_IDENTITY_MISMATCH_PREFIX}expected={expected_key} active={active_key}"
            )
            return None
        _RUST_BACKEND_IMPORT_ERROR = None
        if _is_rust_backend_identity_consistent(active_key):
            _record_rust_backend_ready_for_current_runtime(persist=False)
    except Exception as exc:
        _RUST_BACKEND_MODULE = None
        _RUST_BACKEND_IMPORT_ERROR = exc
        _set_rust_backend_capability_status(None)
    return _RUST_BACKEND_MODULE


def _run_command_for_status(
    command: Sequence[str],
    *,
    cwd: Optional[str] = None,
    interactive: bool = False,
    env: Optional[Dict[str, str]] = None,
    timeout_seconds: Optional[float] = None,
) -> Tuple[bool, str]:
    """Run a shell command and capture success status for setup workflows.

    Purpose:
        Provide one command runner for Rust dependency checks/installation steps.
    Why:
        Toolchain setup requires many command invocations with consistent error
        reporting and interactive/non-interactive behavior.
    Inputs:
        command: Tokenized command list passed to subprocess.
        cwd: Optional working directory for command execution.
        interactive: True runs command without output capture for installer UIs.
        env: Optional process environment override for command execution.
        timeout_seconds: Optional command timeout budget in seconds.
    Outputs:
        `(ok, details)` where `ok` indicates returncode zero and `details` is a
        short message or captured output snippet.
    Side Effects:
        Executes external processes.
    Exceptions:
        Command-start failures are caught and reported as `(False, message)`.
    """
    try:
        timeout_value = None
        if timeout_seconds is not None:
            timeout_value = max(float(timeout_seconds), 0.001)
        if interactive:
            completed = subprocess.run(
                list(command),
                cwd=cwd,
                check=False,
                env=env,
                timeout=timeout_value,
            )
            return completed.returncode == 0, (
                "ok" if completed.returncode == 0 else f"exit code {completed.returncode}"
            )
        completed = subprocess.run(
            list(command),
            cwd=cwd,
            check=False,
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            env=env,
            timeout=timeout_value,
        )
    except subprocess.TimeoutExpired:
        timeout_text = (
            f"{float(timeout_seconds):.3f}s"
            if timeout_seconds is not None
            else "timeout"
        )
        return False, f"timeout after {timeout_text}"
    except Exception as exc:
        return False, str(exc)
    output = (completed.stdout or "").strip()
    error = (completed.stderr or "").strip()
    details = error or output or f"exit code {completed.returncode}"
    return completed.returncode == 0, details


def _verify_rust_backend_subprocess_manifest(
    *,
    timeout_seconds: Optional[float] = None,
    required_kernels: Optional[Sequence[str]] = None,
) -> Dict[str, Any]:
    """Verify Rust backend import/manifest contract in a fresh subprocess.

    Purpose:
        Validate the active interpreter's installed extension without reusing
        this process import cache.
    Why:
        Successful subprocess import with matching manifest identifies stale
        in-process module states that require restart instead of rebuild loops.
    Inputs:
        timeout_seconds: Optional subprocess timeout budget in seconds.
        required_kernels: Optional kernel export list override.
        Uses the current process Rust interface constants as the subprocess
        contract.
    Outputs:
        Dict[str, Any]: Verification payload including status/reason/details and
        manifest fields (`interface_id`, `interface_version`, kernels, module path).
    Side Effects:
        Executes one interpreter-pinned subprocess command.
    Exceptions:
        Subprocess and JSON-parse errors are reported in the returned payload.
    """
    required = [
        str(token or "").strip()
        for token in (required_kernels or RUST_REQUIRED_KERNEL_EXPORTS)
        if str(token or "").strip()
    ]
    expected_contract = {
        "interface_id": RUST_BACKEND_INTERFACE_ID_EXPECTED,
        "interface_version": RUST_BACKEND_INTERFACE_VERSION_EXPECTED,
    }
    script = textwrap.dedent(
        """
        import importlib
        import json
        import sys
        import traceback

        required = json.loads(sys.argv[1])
        expected_contract = json.loads(sys.argv[2])
        expected_id = str((expected_contract or {}).get("interface_id") or "").strip()
        expected_version = str(
            (expected_contract or {}).get("interface_version") or ""
        ).strip()
        payload = {
            "ok": False,
            "reason": "unknown",
            "details": "",
            "module_path": "",
            "interface_id": "",
            "interface_version": "",
            "crate_version": "",
            "missing_kernels": [],
            "exported_kernel_count": 0,
        }
        try:
            importlib.import_module("gl260_rust_ext")
            ext = importlib.import_module("gl260_rust_ext.gl260_rust_ext")
            payload["module_path"] = str(getattr(ext, "__file__", "") or "").strip()
            manifest_fn = getattr(ext, "rust_backend_manifest", None)
            if not callable(manifest_fn):
                payload["reason"] = "manifest_missing"
                payload["details"] = "rust_backend_manifest missing"
            else:
                manifest = manifest_fn()
                interface_id = str((manifest or {}).get("interface_id") or "").strip()
                interface_version = str(
                    (manifest or {}).get("interface_version") or ""
                ).strip()
                crate_version = str((manifest or {}).get("crate_version") or "").strip()
                exported = (manifest or {}).get("exported_kernels") or []
                exported_names = [
                    str(name or "").strip()
                    for name in exported
                    if str(name or "").strip()
                ]
                missing = [name for name in required if name not in exported_names]
                payload["interface_id"] = interface_id
                payload["interface_version"] = interface_version
                payload["crate_version"] = crate_version
                payload["exported_kernel_count"] = len(exported_names)
                payload["missing_kernels"] = missing
                if (
                    interface_id != expected_id
                    or interface_version != expected_version
                ):
                    payload["reason"] = "interface_mismatch"
                    payload["details"] = (
                        "expected "
                        + f"{expected_id}:{expected_version} "
                        + (
                            f"got {interface_id or '(missing)'}:"
                            f"{interface_version or '(missing)'}"
                        )
                    )
                elif missing:
                    payload["reason"] = "missing_kernels"
                    payload["details"] = "missing kernels=" + ", ".join(missing)
                else:
                    payload["ok"] = True
                    payload["reason"] = "ready"
                    payload["details"] = (
                        "subprocess import + manifest verification passed"
                    )
        except Exception as exc:
            payload["reason"] = "import_error"
            payload["details"] = f"{type(exc).__name__}: {exc}"
            payload["traceback"] = traceback.format_exc()
        print(json.dumps(payload, separators=(",", ":")))
        """
    ).strip()
    command = [
        sys.executable,
        "-c",
        script,
        json.dumps(required),
        json.dumps(expected_contract),
    ]
    timeout_value = None
    if timeout_seconds is not None:
        try:
            timeout_value = max(float(timeout_seconds), 0.001)
        except Exception:
            timeout_value = None
    try:
        completed = subprocess.run(
            command,
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            check=False,
            timeout=timeout_value,
        )
    except subprocess.TimeoutExpired:
        timeout_text = (
            f"{float(timeout_seconds):.3f}s"
            if timeout_seconds is not None
            else "timeout"
        )
        return {
            "ok": False,
            "reason": "timeout",
            "details": f"timeout after {timeout_text}",
            "module_path": "",
            "interface_id": "",
            "interface_version": "",
            "crate_version": "",
            "missing_kernels": list(required),
            "exported_kernel_count": 0,
        }
    except Exception as exc:
        return {
            "ok": False,
            "reason": "subprocess_error",
            "details": str(exc),
            "module_path": "",
            "interface_id": "",
            "interface_version": "",
            "crate_version": "",
            "missing_kernels": list(required),
            "exported_kernel_count": 0,
        }
    stdout_text = str(completed.stdout or "").strip()
    stderr_text = str(completed.stderr or "").strip()
    parsed: Dict[str, Any] = {}
    for line in reversed(stdout_text.splitlines()):
        line = line.strip()
        if not line:
            continue
        try:
            candidate = json.loads(line)
        except Exception:
            continue
        if isinstance(candidate, Mapping):
            parsed = dict(candidate)
            break
    if not parsed:
        details = stderr_text or stdout_text or f"exit code {completed.returncode}"
        return {
            "ok": False,
            "reason": "parse_error",
            "details": details,
            "module_path": "",
            "interface_id": "",
            "interface_version": "",
            "crate_version": "",
            "missing_kernels": list(required),
            "exported_kernel_count": 0,
        }
    missing_kernels = parsed.get("missing_kernels") or []
    if isinstance(missing_kernels, Sequence) and not isinstance(
        missing_kernels, (str, bytes, bytearray)
    ):
        missing_list = [str(name or "").strip() for name in missing_kernels]
        missing_list = [name for name in missing_list if name]
    else:
        missing_list = []
    details_text = str(parsed.get("details") or "").strip()
    if completed.returncode != 0 and not details_text:
        details_text = stderr_text or stdout_text or f"exit code {completed.returncode}"
    return {
        "ok": bool(parsed.get("ok")),
        "reason": str(parsed.get("reason") or "").strip() or "unknown",
        "details": details_text,
        "module_path": str(parsed.get("module_path") or "").strip(),
        "interface_id": str(parsed.get("interface_id") or "").strip(),
        "interface_version": str(parsed.get("interface_version") or "").strip(),
        "crate_version": str(parsed.get("crate_version") or "").strip(),
        "missing_kernels": missing_list,
        "exported_kernel_count": int(parsed.get("exported_kernel_count") or 0),
    }


def _resolve_rustup_managed_tool_path(
    tool_name: str,
    *,
    toolchain: Optional[str] = None,
) -> Optional[str]:
    """Resolve a Rustup-managed executable path for a tool.

    Purpose:
        Locate concrete Rust tool binaries (`rustc`/`cargo`) from rustup.
    Why:
        Python/venv script directories may expose incompatible shim executables;
        rustup resolution keeps setup and build commands pinned to a known
        toolchain implementation.
    Inputs:
        tool_name: Rust tool name (for example, `"rustc"` or `"cargo"`).
        toolchain: Optional rustup toolchain token to resolve against.
    Outputs:
        Absolute executable path when rustup can resolve it, else None.
    Side Effects:
        Executes `rustup which`.
    Exceptions:
        Command failures are handled and returned as None.
    """
    rustup_exe = shutil.which("rustup")
    if not rustup_exe:
        return None
    command: List[str] = [rustup_exe, "which"]
    if toolchain:
        command.extend(["--toolchain", str(toolchain)])
    command.append(tool_name)
    ok, details = _run_command_for_status(command)
    if not ok:
        return None
    candidate = str(details or "").splitlines()[-1].strip()
    if not candidate:
        return None
    return candidate if os.path.isfile(candidate) else None


def _detect_msvc_linker_path() -> str:
    """Detect the MSVC linker executable path.

    Purpose:
        Resolve whether `link.exe` is currently available for MSVC builds.
    Why:
        Rust `*-pc-windows-msvc` builds require an MSVC-compatible linker; setup
        strategy selection needs an explicit linker readiness check.
    Inputs:
        None.
    Outputs:
        Absolute `link.exe` path when found, otherwise an empty string.
    Side Effects:
        None.
    Exceptions:
        Invalid PATH entries are ignored safely.
    """
    candidate = shutil.which("link.exe")
    if not candidate:
        return ""
    return candidate if os.path.isfile(candidate) else ""


def _detect_mingw_bin_dir() -> str:
    """Detect a MinGW bin directory containing GCC and LD.

    Purpose:
        Locate a usable MinGW toolchain directory for GNU Rust fallback builds.
    Why:
        GNU fallback requires a linker/driver pair (`gcc.exe`, `ld.exe`) that is
        not guaranteed to be globally on PATH.
    Inputs:
        None.
    Outputs:
        Absolute MinGW bin directory path when found, otherwise an empty string.
    Side Effects:
        None.
    Exceptions:
        Missing directories and malformed PATH entries are ignored.
    """
    candidates: List[str] = []
    # Inspect current PATH first so user-selected toolchains take precedence.
    for entry in str(os.environ.get("PATH", "") or "").split(os.pathsep):
        cleaned = str(entry or "").strip().strip('"')
        if cleaned:
            candidates.append(cleaned)
    candidates.append(MINGW_FALLBACK_BIN_DIR)
    seen: Set[str] = set()
    # Probe each candidate once and require both compiler and linker binaries.
    for raw_dir in candidates:
        candidate_dir = os.path.abspath(str(raw_dir or "").strip())
        if not candidate_dir or not os.path.isdir(candidate_dir):
            continue
        normalized = os.path.normcase(candidate_dir)
        if normalized in seen:
            continue
        seen.add(normalized)
        gcc_path = os.path.join(candidate_dir, "gcc.exe")
        ld_path = os.path.join(candidate_dir, "ld.exe")
        if os.path.isfile(gcc_path) and os.path.isfile(ld_path):
            return candidate_dir
    return ""


def _rustup_installed_targets(
    *,
    rustup_cmd: Optional[str] = None,
    toolchain: Optional[str] = None,
    timeout_seconds: Optional[float] = None,
) -> Set[str]:
    """Return installed rustup targets for the active Rust installation.

    Purpose:
        Discover target triples currently installed under rustup.
    Why:
        GNU fallback setup should skip redundant target installation work and only
        install missing targets when required.
    Inputs:
        rustup_cmd: Optional rustup executable path/token to invoke.
        toolchain: Optional rustup toolchain token for a scoped target query.
        timeout_seconds: Optional timeout for the target-list command.
    Outputs:
        Set of installed target-triple strings.
    Side Effects:
        Executes `rustup target list --installed`, optionally scoped with
        `--toolchain <token>`.
    Exceptions:
        Command failures return an empty set.
    """
    rustup_exe = str(rustup_cmd or shutil.which("rustup") or "").strip()
    if not rustup_exe:
        return set()
    command = [rustup_exe, "target", "list"]
    toolchain_token = str(toolchain or "").strip()
    if toolchain_token:
        command.extend(["--toolchain", toolchain_token])
    command.append("--installed")
    ok, details = _run_command_for_status(command, timeout_seconds=timeout_seconds)
    if not ok:
        return set()
    targets: Set[str] = set()
    # Parse each non-empty line into one installed target token.
    for raw_line in str(details or "").splitlines():
        token = str(raw_line or "").strip()
        if token:
            targets.add(token)
    return targets


def _rustup_installed_toolchains(
    *,
    rustup_cmd: Optional[str] = None,
    timeout_seconds: Optional[float] = None,
) -> Set[str]:
    """Return installed rustup toolchains.

    Purpose:
        Discover host toolchains available for rustup `run` and `which`.
    Why:
        GNU fallback requires installing/validating a GNU host toolchain in
        addition to target triples.
    Inputs:
        rustup_cmd: Optional rustup executable path/token to invoke.
        timeout_seconds: Optional timeout for the toolchain-list command.
    Outputs:
        Set of installed rustup toolchain tokens.
    Side Effects:
        Executes `rustup toolchain list`.
    Exceptions:
        Command failures return an empty set.
    """
    rustup_exe = str(rustup_cmd or shutil.which("rustup") or "").strip()
    if not rustup_exe:
        return set()
    ok, details = _run_command_for_status(
        [rustup_exe, "toolchain", "list"],
        timeout_seconds=timeout_seconds,
    )
    if not ok:
        return set()
    toolchains: Set[str] = set()
    # `rustup toolchain list` includes status markers; first token is the name.
    for raw_line in str(details or "").splitlines():
        token = str(raw_line or "").strip().split()
        if token:
            toolchains.add(token[0])
    return toolchains


def _prepend_directories_to_path(path_value: str, entries: Sequence[str]) -> str:
    """Prepend directories to a PATH string while preserving uniqueness.

    Purpose:
        Build deterministic PATH updates for Rust setup/build subprocesses.
    Why:
        Rust setup may need rustup-managed binaries to override stale shims
        already present earlier in PATH.
    Inputs:
        path_value: Existing PATH string.
        entries: Directory list to prepend in priority order.
    Outputs:
        Updated PATH string.
    Side Effects:
        None.
    Exceptions:
        Invalid entries are ignored safely.
    """
    existing = [chunk for chunk in str(path_value or "").split(os.pathsep) if chunk]
    seen = {os.path.normcase(item.strip()) for item in existing if item.strip()}
    prefix: List[str] = []
    # Iterate over entries to apply deterministic PATH prepending logic.
    for raw_entry in entries:
        entry = str(raw_entry or "").strip()
        if not entry or not os.path.isdir(entry):
            continue
        normalized = os.path.normcase(entry)
        if normalized in seen:
            continue
        prefix.append(entry)
        seen.add(normalized)
    if not prefix:
        return os.pathsep.join(existing)
    return os.pathsep.join(prefix + existing)


def _ensure_user_cargo_bin_on_path() -> None:
    """Append rustup-managed Rust binary directories to PATH when present.

    Purpose:
        Make rustup/rustc/cargo discoverable in the current process after install.
    Why:
        Fresh rustup installations may not be visible until a shell restart unless
        PATH is refreshed in-process.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Mutates `os.environ["PATH"]` when rust tool directories exist.
    Exceptions:
        Invalid/missing paths are ignored.
    """
    home_dir = os.path.expanduser("~")
    cargo_bin = os.path.join(home_dir, ".cargo", "bin")
    rustc_path = _resolve_rustup_managed_tool_path("rustc")
    rustc_bin = os.path.dirname(rustc_path) if rustc_path else ""
    current_path = os.environ.get("PATH", "")
    os.environ["PATH"] = _prepend_directories_to_path(
        current_path,
        [cargo_bin, rustc_bin],
    )


def _check_rust_cli_tool(
    tool_name: str,
    *,
    timeout_seconds: Optional[float] = None,
) -> Tuple[bool, str, str]:
    """Check Rust CLI tool readiness and return the resolved command path.

    Purpose:
        Validate tool availability with a robust fallback to rustup-resolved paths.
    Why:
        PATH-visible shims may exist but be unusable; this check verifies runnable
        executables before setup/build operations rely on them.
    Inputs:
        tool_name: CLI name to validate (`"rustup"`, `"rustc"`, or `"cargo"`).
        timeout_seconds: Optional timeout budget for each version probe command.
    Outputs:
        `(ok, details, command_path)` where:
        - `ok` indicates successful `--version` execution,
        - `details` is output/error text,
        - `command_path` is the executable path or command token used.
    Side Effects:
        Executes one or more version commands.
    Exceptions:
        Failures are returned in tuple form; no exceptions are raised.
    """
    direct_path = shutil.which(tool_name) or tool_name
    ok, details = _run_command_for_status(
        [direct_path, "--version"],
        timeout_seconds=timeout_seconds,
    )
    if ok:
        return True, details, direct_path
    if tool_name in {"rustc", "cargo"}:
        resolved = _resolve_rustup_managed_tool_path(tool_name)
        if resolved:
            resolved_ok, resolved_details = _run_command_for_status(
                [resolved, "--version"],
                timeout_seconds=timeout_seconds,
            )
            if resolved_ok:
                return True, resolved_details, resolved
            return False, resolved_details, resolved
    return False, details, direct_path


def _build_maturin_subprocess_env(
    *,
    toolchain: str = MSVC_TOOLCHAIN,
    target_triple: Optional[str] = None,
    mingw_bin_dir: Optional[str] = None,
    rustc_path_override: Optional[str] = None,
    cargo_path_override: Optional[str] = None,
) -> Dict[str, str]:
    """Build environment overrides for robust `maturin` extension builds.

    Purpose:
        Provide a subprocess environment where rustup-resolved binaries and target
        toolchain settings are deterministic.
    Why:
        Rust extension builds can fail on Windows when shim executables, missing
        linkers, or mismatched host/target toolchains are discovered implicitly.
    Inputs:
        toolchain: Rustup toolchain token used for `rustc`/`cargo` resolution.
        target_triple: Optional cargo target triple passed through environment.
        mingw_bin_dir: Optional MinGW bin directory for GNU fallback builds.
        rustc_path_override: Optional explicit rustc path selected by runtime
            profile tool diagnostics.
        cargo_path_override: Optional explicit cargo path selected by runtime
            profile tool diagnostics.
    Outputs:
        Environment dictionary suitable for subprocess execution.
    Side Effects:
        None.
    Exceptions:
        Missing tool paths are tolerated; returned env falls back to base values.
    """
    env = dict(os.environ)
    scripts_dir = str(sysconfig.get_path("scripts") or "").strip()
    base_prefix = getattr(sys, "base_prefix", sys.prefix)
    in_virtual_env = bool(getattr(sys, "real_prefix", "")) or sys.prefix != base_prefix
    # Pin PyO3 interpreter discovery to the Python runtime that launched the app.
    env["PYO3_PYTHON"] = sys.executable
    if in_virtual_env:
        env["VIRTUAL_ENV"] = sys.prefix

    rustc_path = str(rustc_path_override or "").strip() or _resolve_rustup_managed_tool_path(
        "rustc",
        toolchain=toolchain,
    )
    cargo_path = str(cargo_path_override or "").strip() or _resolve_rustup_managed_tool_path(
        "cargo",
        toolchain=toolchain,
    )
    prepend_dirs: List[str] = []
    if scripts_dir and os.path.isdir(scripts_dir):
        prepend_dirs.append(scripts_dir)
    env["RUSTUP_TOOLCHAIN"] = str(toolchain or "")
    if rustc_path:
        env["RUSTC"] = rustc_path
        prepend_dirs.append(os.path.dirname(rustc_path))
    if cargo_path:
        env["CARGO"] = cargo_path
        prepend_dirs.append(os.path.dirname(cargo_path))

    if target_triple == GNU_TARGET:
        target_upper = GNU_TARGET.upper().replace("-", "_")
        bin_dir = str(mingw_bin_dir or "").strip()
        if bin_dir and os.path.isdir(bin_dir):
            prepend_dirs.append(bin_dir)
            gcc_path = os.path.join(bin_dir, "gcc.exe")
            gpp_path = os.path.join(bin_dir, "g++.exe")
            ar_path = os.path.join(bin_dir, "ar.exe")
            linker_value = gcc_path if os.path.isfile(gcc_path) else "gcc"
            env["CARGO_BUILD_TARGET"] = GNU_TARGET
            env[f"CARGO_TARGET_{target_upper}_LINKER"] = linker_value
            if os.path.isfile(gcc_path):
                env["CC_x86_64_pc_windows_gnu"] = gcc_path
            if os.path.isfile(gpp_path):
                env["CXX_x86_64_pc_windows_gnu"] = gpp_path
            if os.path.isfile(ar_path):
                env["AR_x86_64_pc_windows_gnu"] = ar_path
        elif target_triple:
            # Preserve explicit target selection even if MinGW probing failed.
            env["CARGO_BUILD_TARGET"] = str(target_triple)
    elif target_triple:
        env["CARGO_BUILD_TARGET"] = str(target_triple)

    env["PATH"] = _prepend_directories_to_path(env.get("PATH", ""), prepend_dirs)
    # Corporate/managed Windows environments often block revocation checks in the
    # crates index TLS chain, causing transient cargo fetch failures by default.
    env.setdefault("CARGO_HTTP_CHECK_REVOKE", "false")
    return env


def _resolve_active_interpreter_pip_path() -> Optional[str]:
    """Resolve the pip executable path for the currently running interpreter.

    Purpose:
        Locate the pip binary that belongs to the same Python interpreter running
        this process.
    Why:
        `maturin develop` can install into the wrong environment when PATH and
        virtualenv context drift from `sys.executable`; an explicit pip path keeps
        extension installation aligned with the active interpreter target.
    Inputs:
        None.
    Outputs:
        Absolute path to the interpreter-matched pip executable, or `None` when
        no pip binary can be resolved from the active scripts directory.
    Side Effects:
        None.
    Exceptions:
        Missing scripts directories/binaries return `None` instead of raising.
    """
    scripts_dir = str(sysconfig.get_path("scripts") or "").strip()
    if not scripts_dir or not os.path.isdir(scripts_dir):
        return None
    candidates = ["pip.exe", "pip"] if os.name == "nt" else ["pip"]
    for name in candidates:
        candidate = os.path.join(scripts_dir, name)
        if os.path.isfile(candidate):
            return candidate
    return None


def _run_maturin_develop_build(
    manifest_path: str,
    *,
    cwd: str,
    toolchain: str = MSVC_TOOLCHAIN,
    target_triple: Optional[str] = None,
    mingw_bin_dir: Optional[str] = None,
    rustc_path: Optional[str] = None,
    cargo_path: Optional[str] = None,
) -> Tuple[bool, str]:
    """Run `maturin develop` pinned to the active interpreter environment.

    Purpose:
        Build/install the Rust extension module into the active Python environment.
    Why:
        PATH-visible `maturin` or pip executables can target a different virtual
        environment than the one launching this app, causing successful builds
        that still fail to import at runtime.
    Inputs:
        manifest_path: Absolute path to `rust_ext/Cargo.toml`.
        cwd: Project working directory for the build invocation.
        toolchain: Rustup toolchain token used to launch cargo/rustc.
        target_triple: Optional target triple supplied to maturin/cargo.
        mingw_bin_dir: Optional MinGW bin directory for GNU fallback builds.
        rustc_path: Optional resolved rustc path for this runtime profile.
        cargo_path: Optional resolved cargo path for this runtime profile.
    Outputs:
        `(ok, details)` command status tuple.
    Side Effects:
        Executes build tooling and creates/removes temporary files.
    Exceptions:
        Command/runtime failures are surfaced through the returned status tuple.
    """
    env = _build_maturin_subprocess_env(
        toolchain=toolchain,
        target_triple=target_triple,
        mingw_bin_dir=mingw_bin_dir,
        rustc_path_override=rustc_path,
        cargo_path_override=cargo_path,
    )
    shim_dir: Optional[str] = None
    pip_path = _resolve_active_interpreter_pip_path()
    try:
        rustup_exe = shutil.which("rustup")
        explicit_tools_selected = bool(
            str(env.get("CARGO", "") or "").strip()
            and str(env.get("RUSTC", "") or "").strip()
        )
        if rustup_exe and not explicit_tools_selected:
            shim_dir = tempfile.mkdtemp(prefix="gl260-rustup-shim-")
            cargo_shim = os.path.join(shim_dir, "cargo.cmd")
            rustc_shim = os.path.join(shim_dir, "rustc.cmd")
            with open(cargo_shim, "w", encoding="utf-8") as fh:
                fh.write(f'@echo off\r\n"{rustup_exe}" run "{toolchain}" cargo %*\r\n')
            with open(rustc_shim, "w", encoding="utf-8") as fh:
                fh.write(f'@echo off\r\n"{rustup_exe}" run "{toolchain}" rustc %*\r\n')
            # Force subprocesses to resolve cargo/rustc through rustup wrappers
            # first; this avoids incompatible shim binaries on PATH.
            env["PATH"] = _prepend_directories_to_path(env.get("PATH", ""), [shim_dir])
        command = [
            sys.executable,
            "-m",
            "maturin",
            "develop",
            "--manifest-path",
            manifest_path,
        ]
        if pip_path:
            command.extend(["--pip-path", pip_path])
        if target_triple:
            command.extend(["--target", str(target_triple)])
        return _run_command_for_status(command, cwd=cwd, env=env)
    finally:
        if shim_dir:
            try:
                shutil.rmtree(shim_dir, ignore_errors=True)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass


def _detect_rust_runtime_requirements(
    *,
    probe_timeout_seconds: Optional[float] = None,
    skip_module_probe: bool = False,
) -> Dict[str, Any]:
    """Inspect Rust/Maturin runtime prerequisites for acceleration.

    Purpose:
        Provide a single status snapshot used by installer prompts and diagnostics.
    Why:
        Setup flow must branch on missing commands and current extension readiness.
    Inputs:
        probe_timeout_seconds: Optional timeout budget applied to command/module
            readiness probes in this check.
        skip_module_probe: When True, skip in-process extension import probing.
    Outputs:
        Dictionary including command availability, version checks, and module state.
    Side Effects:
        May refresh PATH with the user cargo bin directory.
    Exceptions:
        Subprocess errors are captured in result fields.
    """
    _ensure_user_cargo_bin_on_path()
    settings_map = globals().get("settings", None)
    if isinstance(settings_map, dict):
        _apply_rust_runtime_settings_defaults(settings_map)
    normalized_probe_timeout: Optional[float]
    if probe_timeout_seconds is None:
        normalized_probe_timeout = None
    else:
        try:
            normalized_probe_timeout = max(float(probe_timeout_seconds), 0.001)
        except Exception:
            normalized_probe_timeout = None
    rustup_ok, rustup_msg, rustup_cmd = _check_rust_cli_tool(
        "rustup",
        timeout_seconds=normalized_probe_timeout,
    )
    toolchain_diag = _resolve_runtime_rust_toolchain_diagnostics(
        timeout_seconds=normalized_probe_timeout,
        settings_map=settings_map if isinstance(settings_map, Mapping) else None,
    )
    rustc_ok = bool(toolchain_diag.get("rustc_valid"))
    rustc_msg = str(
        toolchain_diag.get("rustc_details")
        or toolchain_diag.get("rustc_reason")
        or ""
    ).strip()
    rustc_cmd = str(toolchain_diag.get("rustc_path") or "").strip()
    cargo_ok = bool(toolchain_diag.get("cargo_valid"))
    cargo_msg = str(
        toolchain_diag.get("cargo_details")
        or toolchain_diag.get("cargo_reason")
        or ""
    ).strip()
    cargo_cmd = str(toolchain_diag.get("cargo_path") or "").strip()
    maturin_ok, maturin_msg = _run_command_for_status(
        [sys.executable, "-m", "maturin", "--version"],
        timeout_seconds=normalized_probe_timeout,
    )
    msvc_linker_path = _detect_msvc_linker_path()
    mingw_bin_dir = _detect_mingw_bin_dir()
    msvc_linker_ok = bool(msvc_linker_path)
    mingw_ok = bool(mingw_bin_dir)
    installed_toolchains = (
        _rustup_installed_toolchains(
            rustup_cmd=rustup_cmd,
            timeout_seconds=normalized_probe_timeout,
        )
        if rustup_ok
        else set()
    )
    gnu_toolchain_installed = GNU_TOOLCHAIN in installed_toolchains
    # Query GNU targets against the GNU toolchain explicitly to avoid false
    # negatives when the default host toolchain is still MSVC.
    gnu_installed_targets = (
        _rustup_installed_targets(
            rustup_cmd=rustup_cmd,
            toolchain=GNU_TOOLCHAIN,
            timeout_seconds=normalized_probe_timeout,
        )
        if rustup_ok and gnu_toolchain_installed
        else set()
    )
    gnu_target_installed = GNU_TARGET in gnu_installed_targets
    selected_build_strategy = "unavailable"
    if rustup_ok and rustc_ok and cargo_ok:
        if msvc_linker_ok:
            selected_build_strategy = "msvc"
        elif mingw_ok:
            selected_build_strategy = "gnu"
    module_probe_status = "ok"
    module_error_text = ""
    if skip_module_probe:
        module_ready = False
        module_probe_status = "skipped"
    elif normalized_probe_timeout is None:
        module_ready = _load_rust_backend() is not None
    else:
        probe_state, probe_payload, probe_error = _run_callable_with_timeout(
            lambda: _load_rust_backend() is not None,
            timeout_seconds=normalized_probe_timeout,
            thread_name="gl260-rust-runtime-probe",
        )
        if probe_state == "timeout":
            module_ready = False
            module_probe_status = "timeout"
            module_error_text = f"timeout after {normalized_probe_timeout:.3f}s"
        elif probe_state == "error":
            module_ready = False
            module_probe_status = f"error:{type(probe_error).__name__}"
            module_error_text = str(probe_error or "")
        else:
            module_ready = bool(probe_payload)
    capability_payload = _snapshot_rust_backend_capability_status()
    capability_state = str(capability_payload.get("state") or "").strip().lower() or "unknown"
    if not module_error_text and _RUST_BACKEND_IMPORT_ERROR and not skip_module_probe:
        module_error_text = str(_RUST_BACKEND_IMPORT_ERROR)
    return {
        "rustup_ok": rustup_ok,
        "rustup_msg": rustup_msg,
        "rustup_cmd": rustup_cmd,
        "rustc_ok": rustc_ok,
        "rustc_msg": rustc_msg,
        "rustc_cmd": rustc_cmd,
        "cargo_ok": cargo_ok,
        "cargo_msg": cargo_msg,
        "cargo_cmd": cargo_cmd,
        "rustc_source": str(toolchain_diag.get("rustc_source") or "").strip(),
        "cargo_source": str(toolchain_diag.get("cargo_source") or "").strip(),
        "rustc_valid": bool(toolchain_diag.get("rustc_valid")),
        "cargo_valid": bool(toolchain_diag.get("cargo_valid")),
        "rustc_reason": str(toolchain_diag.get("rustc_reason") or "").strip(),
        "cargo_reason": str(toolchain_diag.get("cargo_reason") or "").strip(),
        "rustc_arch_compatible": toolchain_diag.get("rustc_arch_compatible"),
        "cargo_arch_compatible": toolchain_diag.get("cargo_arch_compatible"),
        "rustc_rejected_candidates": list(
            toolchain_diag.get("rustc_rejected_candidates") or ()
        ),
        "cargo_rejected_candidates": list(
            toolchain_diag.get("cargo_rejected_candidates") or ()
        ),
        "runtime_profile": str(toolchain_diag.get("runtime_profile") or "").strip(),
        "toolchain_consistency_state": str(
            toolchain_diag.get("toolchain_consistency_state") or ""
        ).strip(),
        "toolchain_consistency_reason": str(
            toolchain_diag.get("toolchain_consistency_reason") or ""
        ).strip(),
        "toolchain_consistency_details": str(
            toolchain_diag.get("toolchain_consistency_details") or ""
        ).strip(),
        "maturin_ok": maturin_ok,
        "maturin_msg": maturin_msg,
        "msvc_linker_ok": msvc_linker_ok,
        "msvc_linker_path": msvc_linker_path,
        "mingw_ok": mingw_ok,
        "mingw_bin_dir": mingw_bin_dir,
        "gnu_target_installed": gnu_target_installed,
        "gnu_toolchain_installed": gnu_toolchain_installed,
        "selected_build_strategy": selected_build_strategy,
        "module_ready": module_ready,
        "module_error": module_error_text,
        "module_probe_status": module_probe_status,
        "module_probe_skipped": bool(skip_module_probe),
        "probe_timeout_seconds": normalized_probe_timeout,
        "capability_state": capability_state,
        "capability_reason": str(capability_payload.get("reason") or "").strip(),
        "capability_details": str(capability_payload.get("details") or "").strip(),
        "required_kernels": list(capability_payload.get("required_kernels") or ()),
        "missing_kernels": list(capability_payload.get("missing_kernels") or ()),
        "manifest": dict(capability_payload.get("manifest") or {}),
        "module_identity": dict(capability_payload.get("module_identity") or {}),
        "identity_key": str(capability_payload.get("identity_key") or "").strip(),
        "identity_consistent": bool(capability_payload.get("identity_consistent", True)),
    }


class TkTaskRunner:
    def __init__(self, tk_root: tk.Misc, max_workers: int = 1) -> None:
        """Initialize a Tk-aware background task runner.

        Purpose:
            Create a reusable executor bridge between background workers and Tk
            main-thread callbacks.
        Why:
            App workflows need one shared scheduling utility that enforces
            latest-task-wins semantics per task name.
        Inputs:
            tk_root: Tk root/widget used to marshal callbacks via `after`.
            max_workers: Maximum worker threads for the backing executor.
        Outputs:
            None.
        Side Effects:
            Allocates a `ThreadPoolExecutor` and initializes in-memory task state.
        Exceptions:
            Invalid `max_workers` values are normalized to safe minimums.
        """
        self._root = tk_root
        self._max_workers = max(1, int(max_workers))
        self._executor = ThreadPoolExecutor(max_workers=self._max_workers)
        self._lock = threading.Lock()
        self._task_counter = 0
        self._latest_task_id: Dict[str, int] = {}
        self._latest_future: Dict[str, Any] = {}
        self._futures: Dict[int, Any] = {}
        self._low_priority_backpressure_enabled = True
        self._low_priority_queue_limit = 6
        self._low_priority_pending_counts: Dict[str, int] = {}
        self._low_priority_drop_count = 0

    def configure_low_priority_backpressure(
        self, *, enabled: bool, queue_limit: int
    ) -> None:
        """Configure low-priority submission backpressure policy.

        Purpose:
            Update bounded-queue controls for low-priority task classes.
        Why:
            Repeated prefetch/warmup submissions can otherwise flood the worker
            queue and delay UI-critical callbacks.
        Inputs:
            enabled: True to enforce backpressure checks.
            queue_limit: Maximum pending low-priority tasks per group.
        Outputs:
            None.
        Side Effects:
            Updates runner-level policy used by `submit(...)` low-priority calls.
        Exceptions:
            Invalid limits are normalized to a safe minimum.
        """
        with self._lock:
            self._low_priority_backpressure_enabled = bool(enabled)
            self._low_priority_queue_limit = max(1, int(queue_limit))

    def _executor_queue_depth(self) -> Optional[int]:
        """Return executor work-queue depth when available.

        Purpose:
            Expose approximate pending queue depth from ThreadPoolExecutor.
        Why:
            Backpressure decisions need a best-effort queue signal.
        Inputs:
            None.
        Outputs:
            Optional[int]: Queue depth, or None when unavailable.
        Side Effects:
            None.
        Exceptions:
            Executor-private attribute access failures return None.
        """
        try:
            work_queue = getattr(self._executor, "_work_queue", None)
            if work_queue is not None and hasattr(work_queue, "qsize"):
                return int(work_queue.qsize())
        except Exception:
            return None
        return None

    def set_max_workers(self, max_workers: int) -> None:
        """Update the executor worker capacity.

        Purpose:
            Reconfigure background concurrency for subsequent submitted tasks.
        Why:
            Developer runtime controls need to tune worker pool size without
            restarting the application.
        Inputs:
            max_workers: Desired worker capacity.
        Outputs:
            None.
        Side Effects:
            Replaces the internal executor and requests non-blocking shutdown on
            the previous executor instance.
        Exceptions:
            Invalid values are normalized; shutdown failures are ignored.
        """
        max_workers = max(1, int(max_workers))
        if max_workers == self._max_workers:
            return
        self._max_workers = max_workers
        old_executor = self._executor
        self._executor = ThreadPoolExecutor(max_workers=self._max_workers)
        try:
            old_executor.shutdown(wait=False)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def submit(
        self,
        task_name: str,
        fn: Callable[[], Any],
        on_ok: Optional[Callable[[Any], None]],
        on_err: Optional[Callable[[BaseException], None]],
        *,
        priority: str = "high",
        backpressure_group: Optional[str] = None,
        low_priority_queue_limit: Optional[int] = None,
    ) -> int:
        """Submit work and marshal completion handlers back to Tk.

        Purpose:
            Run one background callable and deliver completion on the UI thread.
        Why:
            Tk widgets must only be touched on the main thread, while expensive
            work should run in background workers.
        Inputs:
            task_name: Logical task key used for latest-task-wins cancellation.
            fn: Background callable executed by the worker pool.
            on_ok: Optional success callback executed on Tk thread.
            on_err: Optional error callback executed on Tk thread.
            priority: Submission priority token (`high` or `low`).
            backpressure_group: Optional low-priority queue grouping key.
            low_priority_queue_limit: Optional per-call low-priority limit.
        Outputs:
            Integer task identifier for stale-result checks (`-1` when a
            low-priority task is dropped by backpressure policy).
        Side Effects:
            Cancels prior same-name pending futures when possible and tracks the
            submitted future for diagnostics. Low-priority tasks may be dropped
            before submission when queue limits are exceeded.
        Exceptions:
            Worker exceptions are forwarded to `on_err` when provided.
        """
        priority_token = str(priority or "high").strip().lower()
        is_low_priority = priority_token == "low"
        group_token = str(backpressure_group or task_name or "").strip().lower()
        if not group_token:
            group_token = "default"
        if is_low_priority:
            with self._lock:
                enabled = bool(self._low_priority_backpressure_enabled)
                limit = (
                    max(1, int(low_priority_queue_limit))
                    if low_priority_queue_limit is not None
                    else int(self._low_priority_queue_limit)
                )
                pending_group = int(self._low_priority_pending_counts.get(group_token, 0))
                queue_depth = self._executor_queue_depth()
                if enabled and (
                    pending_group >= limit
                    or (
                        queue_depth is not None
                        and queue_depth >= max(limit * max(1, self._max_workers), limit)
                    )
                ):
                    self._low_priority_drop_count += 1
                    return -1
        with self._lock:
            self._task_counter += 1
            task_id = self._task_counter
            previous_future = self._latest_future.get(task_name)
            self._latest_task_id[task_name] = task_id
            if is_low_priority:
                self._low_priority_pending_counts[group_token] = (
                    int(self._low_priority_pending_counts.get(group_token, 0)) + 1
                )
        if previous_future is not None:
            try:
                previous_future.cancel()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        future = self._executor.submit(fn)
        with self._lock:
            self._latest_future[task_name] = future
            self._futures[task_id] = future

        def _handle_result(fut) -> None:
            """Handle result.
            Used as an event callback for result."""
            with self._lock:
                self._futures.pop(task_id, None)
                if self._latest_future.get(task_name) is fut:
                    self._latest_future.pop(task_name, None)
                is_latest = self._latest_task_id.get(task_name) == task_id
                if is_low_priority:
                    remaining = int(self._low_priority_pending_counts.get(group_token, 0)) - 1
                    if remaining > 0:
                        self._low_priority_pending_counts[group_token] = remaining
                    else:
                        self._low_priority_pending_counts.pop(group_token, None)
            if not is_latest:
                return
            try:
                result = fut.result()
            except Exception as exc:  # pragma: no cover - background thread
                if on_err is not None:
                    on_err(exc)
                return
            if on_ok is not None:
                on_ok(result)

        future.add_done_callback(lambda fut: self._root.after(0, _handle_result, fut))
        return task_id

    def get_diagnostics(self) -> Dict[str, Any]:
        """Return runtime diagnostics for the current task-runner state.

        Purpose:
            Expose executor/task metrics for in-app diagnostics panels.
        Why:
            Concurrency tuning requires visibility into configured worker limits,
            active futures, pending queue depth, and live worker threads.
        Inputs:
            None.
        Outputs:
            Dict containing worker counts and task/queue health metrics.
        Side Effects:
            None.
        Exceptions:
            Best-effort guards normalize missing private executor attributes.
        """
        with self._lock:
            futures = list(self._futures.values())
            latest_task_names = tuple(sorted(self._latest_task_id.keys()))
            max_workers = int(self._max_workers)
            low_priority_groups = dict(self._low_priority_pending_counts)
            low_priority_drop_count = int(self._low_priority_drop_count)
            low_priority_enabled = bool(self._low_priority_backpressure_enabled)
            low_priority_limit = int(self._low_priority_queue_limit)
        active_tasks = sum(
            1
            for fut in futures
            if not fut.done() and bool(getattr(fut, "running", lambda: False)())
        )
        pending_tasks = sum(
            1
            for fut in futures
            if not fut.done() and not bool(getattr(fut, "running", lambda: False)())
        )
        done_tasks = sum(1 for fut in futures if fut.done())
        queue_depth = None
        live_threads = None
        try:
            work_queue = getattr(self._executor, "_work_queue", None)
            if work_queue is not None and hasattr(work_queue, "qsize"):
                queue_depth = int(work_queue.qsize())
        except Exception:
            queue_depth = None
        try:
            threads = list(getattr(self._executor, "_threads", set()) or set())
            live_threads = sum(1 for thread in threads if thread.is_alive())
        except Exception:
            live_threads = None
        return {
            "max_workers": max_workers,
            "tracked_tasks": len(futures),
            "active_tasks": int(active_tasks),
            "pending_tasks": int(pending_tasks),
            "done_tasks": int(done_tasks),
            "queue_depth": queue_depth,
            "live_threads": live_threads,
            "task_names": latest_task_names,
            "low_priority_backpressure_enabled": low_priority_enabled,
            "low_priority_queue_limit": low_priority_limit,
            "low_priority_pending_by_group": low_priority_groups,
            "low_priority_drop_count": low_priority_drop_count,
        }


_SHARED_BOUNDED_EXECUTORS: Dict[int, ThreadPoolExecutor] = {}
_SHARED_BOUNDED_EXECUTORS_LOCK = threading.Lock()
_SHARED_BOUNDED_EXECUTORS_SHUTDOWN_REGISTERED = False


def _shutdown_shared_bounded_executors() -> None:
    """Shut down shared bounded executors at process exit.

    Purpose:
        Release worker threads used by shared bounded executor pools.
    Why:
        Shared executors are long-lived and should shut down cleanly on exit.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Requests non-blocking shutdown for all shared bounded executors.
    Exceptions:
        Shutdown failures are ignored by design.
    """
    with _SHARED_BOUNDED_EXECUTORS_LOCK:
        executors = list(_SHARED_BOUNDED_EXECUTORS.values())
        _SHARED_BOUNDED_EXECUTORS.clear()
    for executor in executors:
        try:
            executor.shutdown(wait=False)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting shutdown.
            pass


def _get_shared_bounded_executor(max_workers: int) -> ThreadPoolExecutor:
    """Return a shared bounded executor for hot-path parallel compute tasks.

    Purpose:
        Reuse thread pools for repeated bounded parallel compute calls.
    Why:
        Per-call executor creation adds thread churn and scheduling overhead.
    Inputs:
        max_workers: Desired bounded worker count.
    Outputs:
        ThreadPoolExecutor instance keyed by normalized worker count.
    Side Effects:
        May allocate and register one long-lived executor.
    Exceptions:
        Invalid worker counts are normalized to a safe minimum.
    """
    normalized_workers = max(1, int(max_workers))
    with _SHARED_BOUNDED_EXECUTORS_LOCK:
        executor = _SHARED_BOUNDED_EXECUTORS.get(normalized_workers)
        if executor is None:
            executor = ThreadPoolExecutor(
                max_workers=normalized_workers,
                thread_name_prefix=f"gl260-bounded-{normalized_workers}",
            )
            _SHARED_BOUNDED_EXECUTORS[normalized_workers] = executor
        global _SHARED_BOUNDED_EXECUTORS_SHUTDOWN_REGISTERED
        if not _SHARED_BOUNDED_EXECUTORS_SHUTDOWN_REGISTERED:
            atexit.register(_shutdown_shared_bounded_executors)
            _SHARED_BOUNDED_EXECUTORS_SHUTDOWN_REGISTERED = True
        return executor


def _get_font_path(font_name: str) -> Optional[str]:
    """Return font path.
    Used to retrieve font path for downstream logic."""
    lowered = font_name.lower()
    try:
        # Iterate over font_manager.fontManager.ttflist to apply the per-item logic.
        for entry in font_manager.fontManager.ttflist:
            if entry.name.lower() == lowered:
                return entry.fname
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass
    try:
        return font_manager.findfont(font_name, fallback_to_default=False)
    except TypeError:
        try:
            path = font_manager.findfont(font_name)
        except Exception:
            return None
        return path if lowered in os.path.basename(path).lower() else None
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        return None


def _font_supports_required_glyphs(font_name: str) -> bool:
    """Check whether required glyphs is supported.
    Used by font workflows to check required glyphs."""
    path = _get_font_path(font_name)
    if not path:
        return False
    try:
        face = FT2Font(path)
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        return False
    return all(face.get_char_index(ord(ch)) != 0 for ch in _REQUIRED_FONT_GLYPHS)


@lru_cache(maxsize=1)
def _preferred_plot_font_stack() -> Tuple[str, ...]:
    """Perform preferred plot font stack.
    Used to keep the workflow logic localized and testable."""
    fonts: List[str] = []
    if _font_supports_required_glyphs(_PREFERRED_PLOT_FONT):
        fonts.append(_PREFERRED_PLOT_FONT)
    # Iterate over _FONT_FALLBACKS to apply the per-item logic.
    for fallback_name in _FONT_FALLBACKS:
        if fallback_name not in fonts:
            fonts.append(fallback_name)
    if not fonts:
        fonts.extend(plt.rcParams.get("font.serif", []))
    return tuple(fonts)


def _apply_default_plot_fonts(font_family: Optional[str] = None) -> None:
    """Apply default plot fonts.
    Used to apply default plot fonts changes to live state."""
    stack = list(_preferred_plot_font_stack())
    family_value = (font_family or "").strip()
    if family_value:
        plt.rcParams["font.family"] = family_value
        if family_value not in stack:
            stack = [family_value] + stack
        if stack:
            existing_serif = [
                name for name in plt.rcParams.get("font.serif", []) if name not in stack
            ]
            plt.rcParams["font.serif"] = stack + existing_serif
        return
    if not stack:
        return
    plt.rcParams["font.family"] = stack
    existing_serif = [
        name for name in plt.rcParams.get("font.serif", []) if name not in stack
    ]
    plt.rcParams["font.serif"] = stack + existing_serif


_apply_default_plot_fonts()


def _enforce_axis_text_style(
    ax,
    *,
    font_family: str = "",
    tick_fontsize: Optional[float] = None,
    label_fontsize: Optional[float] = None,
) -> None:
    """Perform enforce axis text style.
    Used to keep the workflow logic localized and testable."""
    if ax is None:
        return
    if tick_fontsize is not None:
        try:
            ax.tick_params(axis="both", which="major", labelsize=tick_fontsize)
            ax.tick_params(axis="both", which="minor", labelsize=tick_fontsize)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
    labels = []
    try:
        labels.extend(ax.get_xticklabels())
        labels.extend(ax.get_yticklabels())
        labels.extend(ax.get_xticklabels(minor=True))
        labels.extend(ax.get_yticklabels(minor=True))
    except Exception:
        labels = list(ax.get_xticklabels()) + list(ax.get_yticklabels())
    # Iterate over labels to apply the per-item logic.
    for lbl in labels:
        try:
            if tick_fontsize is not None:
                lbl.set_fontsize(tick_fontsize)
            if font_family:
                lbl.set_fontfamily(font_family)
        except Exception:
            continue
    # Iterate over (ax.xaxis.get_offset_text(), ax.yaxis.get_offset_text()) to apply the per-item logic.
    for offset_text in (ax.xaxis.get_offset_text(), ax.yaxis.get_offset_text()):
        try:
            if tick_fontsize is not None:
                offset_text.set_fontsize(tick_fontsize)
            if font_family:
                offset_text.set_fontfamily(font_family)
        except Exception:
            continue
    # Iterate over (ax.xaxis.label, ax.yaxis.label) to apply the per-item logic.
    for axis_label in (ax.xaxis.label, ax.yaxis.label):
        try:
            if label_fontsize is not None:
                axis_label.set_fontsize(label_fontsize)
            if font_family:
                axis_label.set_fontfamily(font_family)
        except Exception:
            continue


_TITLE_FONT_DEBUG_CHECKED = False


def _resolve_fontsize_points(value, default: float = 12.0) -> float:
    """Resolve fontsize points.
    Used to compute fontsize points before rendering or export."""
    try:
        if value is None:
            return float(default)
        if isinstance(value, (int, float)):
            size = float(value)
            if math.isfinite(size) and size > 0.0:
                return size
            return float(default)
        if isinstance(value, str):
            cleaned = value.strip()
            if not cleaned:
                return float(default)
            try:
                size = float(cleaned)
            except Exception:
                size = None
            if size is not None and math.isfinite(size) and size > 0.0:
                return float(size)
            try:
                return float(
                    font_manager.FontProperties(size=cleaned).get_size_in_points()
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                base = float(plt.rcParams.get("font.size", default))
            except Exception:
                base = float(default)
            try:
                scale = font_manager.font_scalings.get(cleaned.lower())
            except Exception:
                scale = None
            if scale is not None:
                try:
                    return float(base) * float(scale)
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    return float(default)
        try:
            size = float(value)
            if math.isfinite(size) and size > 0.0:
                return size
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        return float(default)
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        return float(default)


def _debug_title_font_resolution_once() -> None:
    """Perform debug title font resolution once.
    Used to keep the workflow logic localized and testable."""
    global _TITLE_FONT_DEBUG_CHECKED
    if not DEBUG_TITLE_FONT_RESOLVE or _TITLE_FONT_DEBUG_CHECKED:
        return
    _TITLE_FONT_DEBUG_CHECKED = True
    try:
        samples = ("large", "medium", 12, "nonsense")
        results = [_resolve_fontsize_points(value, default=12.0) for value in samples]
        if not all(isinstance(value, float) for value in results):
            print("[TitleSize] font size resolution returned non-float")
    except Exception as exc:
        print(f"[TitleSize] font size resolution check failed: {exc}")


def _center_titles_to_axes_union(
    fig: Figure,
    axes: Sequence[Optional[Axes]],
    title: Optional[str],
    suptitle: Optional[str],
    title_fs: Optional[float],
    suptitle_fs: Optional[float],
    font_family: str,
    title_pad_pts: float,
    suptitle_pad_pts: float,
    *,
    suptitle_y: Optional[float] = None,
) -> None:
    """Center titles to axes union.
    Used to align titles to axes union within layout bounds."""
    if fig is None:
        return
    _debug_title_font_resolution_once()
    axes_list: List[Axes] = []
    # Iterate over axes or [] to apply the per-item logic.
    for axis in axes or []:
        if axis is None:
            continue
        try:
            if not axis.get_visible():
                continue
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        if getattr(axis, "_gl260_legend_only", False):
            continue
        try:
            if not axis.axison and not axis.has_data():
                continue
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        axes_list.append(axis)
    primary_axis = None
    # Title transform parity with combined rendering:
    # the layout solver repositions titles in axes coordinates, so non-combined
    # plots must keep title artists axes-bound (ax.set_title), not fig.text.
    if axes_list:
        # Iterate over axes_list to apply the per-item logic.
        for axis in axes_list:
            if getattr(axis, "_gl260_axis_role", None) == "primary":
                primary_axis = axis
                break
        if primary_axis is None:
            primary_axis = axes_list[0]
        try:
            bbox = Bbox.union([axis.get_position() for axis in axes_list])
            center_x = (bbox.x0 + bbox.x1) / 2.0
        except Exception:
            center_x = 0.5
    else:
        center_x = 0.5

    # Iterate over axes_list to apply the per-item logic.
    for axis in axes_list:
        try:
            axis.set_title("")
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    # Remove stale figure-level and axes-bound title artists before rebuilding.
    for attr in ("_gl260_title_text", "_gl260_suptitle_text"):
        existing = getattr(fig, attr, None)
        if existing is not None:
            try:
                owner_ax = getattr(existing, "axes", None)
                if owner_ax is not None:
                    try:
                        existing.set_text("")
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting the workflow.
                        pass
                else:
                    existing.remove()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            setattr(fig, attr, None)
    old_suptitle = getattr(fig, "_suptitle", None)
    if old_suptitle is not None:
        try:
            old_suptitle.remove()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
    try:
        fig._suptitle = None
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass

    fig_h_pts = max(fig.get_size_inches()[1] * 72.0, 1.0)
    if title_fs is not None:
        title_fs_value = _resolve_fontsize_points(title_fs, default=12.0)
    else:
        title_fs_value = _resolve_fontsize_points(
            plt.rcParams.get("axes.titlesize", 12.0), default=12.0
        )
    if suptitle_fs is not None:
        suptitle_fs_value = _resolve_fontsize_points(suptitle_fs, default=12.0)
    else:
        suptitle_fs_value = _resolve_fontsize_points(
            plt.rcParams.get("figure.titlesize", 12.0), default=12.0
        )

    dy_suptitle = float(suptitle_pad_pts or 0.0) / fig_h_pts

    def _clamp_y(value: float) -> float:
        """Clamp y.
        Used to keep y within safe bounds."""
        return max(0.0, min(1.05, value))

    title_text = (title or "").strip()
    suptitle_text = (suptitle or "").strip()

    title_artist = None
    if title_text:
        if primary_axis is not None:
            title_kwargs: Dict[str, Any] = {
                "fontsize": title_fs_value,
                "pad": float(title_pad_pts or 0.0),
            }
            if font_family:
                title_kwargs["fontfamily"] = font_family
            try:
                title_artist = primary_axis.set_title(title_text, **title_kwargs)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                title_artist = None
        if title_artist is None:
            # Fallback for figures without data axes.
            title_kwargs_fallback: Dict[str, Any] = {
                "ha": "center",
                "va": "top",
                "fontsize": title_fs_value,
            }
            if font_family:
                title_kwargs_fallback["fontfamily"] = font_family
            title_artist = fig.text(0.5, 0.98, title_text, **title_kwargs_fallback)

    suptitle_artist = None
    if suptitle_text:
        if suptitle_y is None:
            y_suptitle = 0.98
        else:
            y_suptitle = float(suptitle_y) + dy_suptitle
        y_suptitle = _clamp_y(y_suptitle)
        suptitle_kwargs: Dict[str, Any] = {
            "fontsize": suptitle_fs_value,
            "x": center_x,
            "y": y_suptitle,
        }
        if font_family:
            suptitle_kwargs["fontfamily"] = font_family
        suptitle_artist = fig.suptitle(suptitle_text, **suptitle_kwargs)

    fig._gl260_title_text = title_artist
    fig._gl260_suptitle_text = suptitle_artist
    fig._suptitle = suptitle_artist
    fig._gl260_title_state = {
        "title": title_text,
        "suptitle": suptitle_text,
        "title_fs": title_fs_value,
        "suptitle_fs": suptitle_fs_value,
        "font_family": font_family,
        "title_pad_pts": title_pad_pts,
        "suptitle_pad_pts": suptitle_pad_pts,
        "suptitle_y": suptitle_y,
    }
    if fig.canvas is None:
        FigureCanvasAgg(fig)
    try:
        fig.canvas.draw()
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass


def _filter_installed_fonts(candidates: Sequence[str]) -> List[str]:
    """Filter installed fonts.
    Used to remove non-relevant entries from installed fonts."""
    filtered: List[str] = []
    # Iterate over candidates to apply the per-item logic.
    for candidate in candidates:
        name = (candidate or "").strip()
        if not name or name in filtered:
            continue
        try:
            font_manager.findfont(name, fallback_to_default=False)
        except TypeError:
            lowered = name.lower()
            if any(
                entry.name.lower() == lowered
                # Iterate to apply the per-item logic.
                for entry in font_manager.fontManager.ttflist
            ):
                filtered.append(name)
        except Exception:
            continue
        else:
            filtered.append(name)
    if "DejaVu Serif" not in filtered:
        filtered.append("DejaVu Serif")
    return filtered


def _normalize_elapsed_time_unit(value: Any) -> str:
    """Normalize elapsed time unit.
    Used to keep elapsed time unit consistent across workflows and persistence."""
    if isinstance(value, str):
        normalized = value.strip().lower()
        if normalized in ELAPSED_TIME_UNITS:
            return normalized
    return DEFAULT_ELAPSED_TIME_UNIT


def _normalize_title_type_list(value: Any) -> List[str]:
    """Normalize title type list.
    Used to keep title type list consistent across workflows and persistence."""
    if not isinstance(value, (list, tuple)):
        return list(DEFAULT_TITLE_TYPES)
    normalized: List[str] = []
    seen: Set[str] = set()
    # Iterate over value to apply the per-item logic.
    for raw in value:
        name = str(raw).strip() if raw is not None else ""
        if not name:
            continue
        key = name.casefold()
        if key in seen:
            continue
        seen.add(key)
        normalized.append(name)
    if not normalized:
        return list(DEFAULT_TITLE_TYPES)
    return normalized


def _normalize_mpl_color(value: Any) -> str:
    """Normalize Matplotlib color.
    Used to keep Matplotlib color consistent across workflows and persistence."""
    try:
        from matplotlib import colors as mcolors
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        return "#000000"
    try:
        if value is None:
            return "#000000"
        if isinstance(value, str):
            stripped = value.strip()
            if not stripped:
                return "#000000"
            lowered = stripped.lower()
            if lowered in {"none", "transparent"}:
                return "#000000"
            value = stripped
        return mcolors.to_hex(mcolors.to_rgba(value), keep_alpha=False)
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        return "#000000"


