def _is_trace_series_key(value: Any) -> bool:
    """Return whether a value is a valid core trace series key.

    Purpose:
        Accept both legacy base trace keys and grouped Columns-tab runtime keys.
    Why:
        Plot Elements can target additional traces such as `y1_2`, so validation
        must not collapse those targets back to base keys.
    Inputs:
        value: Candidate trace key from UI state, settings, or artist metadata.
    Outputs:
        True when the key is a base trace key or a grouped key with ordinal >= 2.
    Side Effects:
        None.
    Exceptions:
        Invalid/non-string values return False.
    """
    if not isinstance(value, str):
        return False
    candidate = value.strip().lower()
    if (
        candidate in TRACE_SERIES_KEYS
        or candidate in REACTION_DASHBOARD_TRACE_SERIES_KEYS
    ):
        return True
    if "_" not in candidate:
        return False
    role_key, ordinal_text = candidate.rsplit("_", 1)
    if role_key not in TRACE_SERIES_KEYS or not ordinal_text.isdigit():
        return False
    try:
        return int(ordinal_text) >= 2
    except Exception:
        return False


def _normalize_trace_series_key(value: Any, default: str = "y2") -> str:
    """Normalize a trace-series key for behavior plot elements.

    Purpose:
        Coerce persisted/UI trace targets into a valid core trace key.
    Why:
        Trace behavior elements must keep grouped runtime keys like `y1_2`
        instead of falling back to a base role.
    Inputs:
        value: Candidate trace key.
        default: Fallback key used when `value` is invalid; an empty fallback is
            preserved for filtering workflows.
    Outputs:
        Valid base/grouped trace key or the normalized fallback.
    Side Effects:
        None.
    Exceptions:
        Invalid inputs are handled by returning the fallback.
    """
    fallback_raw = "" if default is None else str(default).strip().lower()
    if _is_trace_series_key(fallback_raw):
        fallback = fallback_raw
    elif fallback_raw == "":
        fallback = ""
    else:
        fallback = "y2"
    if not isinstance(value, str):
        return fallback
    candidate = value.strip().lower()
    if _is_trace_series_key(candidate):
        return candidate
    return fallback


def _normalize_timeline_trace_series_key(value: Any, default: str = "") -> str:
    """Normalize a timeline Data Trace key to the canonical renderer key.

    Purpose:
        Accept canonical timeline keys and legacy/source-field aliases.
    Why:
        Cycle timeline Data Trace settings can be persisted from multiple UI and
        profile paths; the display, preview, and export renderers must all read
        the same canonical `timeline_*` key for calculated pH and related traces.
    Inputs:
        value: Candidate timeline trace key from settings, UI state, or metadata.
        default: Fallback value returned when the candidate is unknown.
    Outputs:
        Canonical timeline trace key, or the normalized fallback.
    Side Effects:
        None.
    Exceptions:
        Invalid/non-string values return the fallback.
    """
    fallback_raw = "" if default is None else str(default).strip().lower()
    fallback = TIMELINE_TRACE_SERIES_KEY_ALIASES.get(fallback_raw, fallback_raw)
    if not isinstance(value, str):
        return fallback
    candidate = value.strip().lower()
    return TIMELINE_TRACE_SERIES_KEY_ALIASES.get(candidate, fallback)


