def _normalize_sol_output_workspace_panel_layout_map(
    value: Any,
    *,
    fallback: Optional[Mapping[str, Mapping[str, Any]]] = None,
) -> Dict[str, Dict[str, int]]:
    """Normalize output-workspace panel geometry payloads.

    Purpose:
        Sanitize persisted or in-memory panel geometry values into one safe map.
    Why:
        Freeform panel drag/resize persistence must reject invalid payloads and
        always provide complete panel geometry for every required panel id.
    Inputs:
        value: Candidate geometry payload keyed by panel id.
        fallback: Optional fallback geometry map used when a panel is missing.
    Outputs:
        Dict[str, Dict[str, int]]: Complete normalized panel geometry map.
    Side Effects:
        None.
    Exceptions:
        Invalid values fail closed to fallback/default bounds.
    """
    base_layout_source = (
        fallback
        if isinstance(fallback, Mapping)
        else SOL_OUTPUT_WORKSPACE_DEFAULT_PANEL_LAYOUT
    )
    normalized: Dict[str, Dict[str, int]] = {}
    source_map = value if isinstance(value, Mapping) else {}
    for panel_id in SOL_OUTPUT_WORKSPACE_PANEL_IDS:
        fallback_panel = base_layout_source.get(
            panel_id, SOL_OUTPUT_WORKSPACE_DEFAULT_PANEL_LAYOUT[panel_id]
        )
        panel_source = (
            source_map.get(panel_id)
            if isinstance(source_map.get(panel_id), Mapping)
            else {}
        )
        x_val = _safe_rust_int(panel_source.get("x"), _safe_rust_int(fallback_panel.get("x"), 0))
        y_val = _safe_rust_int(panel_source.get("y"), _safe_rust_int(fallback_panel.get("y"), 0))
        w_val = _safe_rust_int(
            panel_source.get("w"),
            _safe_rust_int(
                fallback_panel.get("w"), SOL_OUTPUT_WORKSPACE_MIN_PANEL_WIDTH
            ),
        )
        h_val = _safe_rust_int(
            panel_source.get("h"),
            _safe_rust_int(
                fallback_panel.get("h"), SOL_OUTPUT_WORKSPACE_MIN_PANEL_HEIGHT
            ),
        )
        normalized[panel_id] = {
            "x": max(0, int(x_val if x_val is not None else 0)),
            "y": max(0, int(y_val if y_val is not None else 0)),
            "w": max(
                SOL_OUTPUT_WORKSPACE_MIN_PANEL_WIDTH,
                int(
                    w_val
                    if w_val is not None
                    else SOL_OUTPUT_WORKSPACE_MIN_PANEL_WIDTH
                ),
            ),
            "h": max(
                SOL_OUTPUT_WORKSPACE_MIN_PANEL_HEIGHT,
                int(
                    h_val
                    if h_val is not None
                    else SOL_OUTPUT_WORKSPACE_MIN_PANEL_HEIGHT
                ),
            ),
        }
    return normalized


def _normalize_sol_output_workspace_analytics_scope(value: Any) -> str:
    """Normalize persisted analytics visibility scope for shared workspace panels.

    Purpose:
        Coerce analytics visibility scope payloads into accepted runtime tokens.
    Why:
        Scope controls panel visibility behavior across workflows and must remain
        stable across manual settings edits and version upgrades.
    Inputs:
        value: Raw scope token from settings payload.
    Outputs:
        str: One of `analysis_only` or `all_workflows`.
    Side Effects:
        None.
    Exceptions:
        Invalid payloads fail closed to `analysis_only`.
    """
    token = str(value or "").strip().lower()
    if token in SOL_OUTPUT_WORKSPACE_ANALYTICS_SCOPE_VALUES:
        return token
    return SOL_OUTPUT_WORKSPACE_ANALYTICS_SCOPE_ANALYSIS_ONLY


def _normalize_sol_output_workspace_analysis_table_width_profiles(
    value: Any,
) -> Dict[str, Dict[str, Dict[str, int]]]:
    """Normalize persisted Analysis workspace table-width profiles.

    Purpose:
        Sanitize per-context and per-table column-width payloads.
    Why:
        Manual separator drags and auto-fit actions persist widths that must be
        restored safely without allowing malformed settings to break rendering.
    Inputs:
        value: Raw width-profile payload.
    Outputs:
        Dict[str, Dict[str, Dict[str, int]]]: Normalized width profiles keyed by
        context token then table id.
    Side Effects:
        None.
    Exceptions:
        Invalid payloads are ignored and omitted from normalized output.
    """
    normalized: Dict[str, Dict[str, Dict[str, int]]] = {}
    if not isinstance(value, Mapping):
        return normalized
    for raw_context, raw_tables in value.items():
        context_key = str(raw_context or "").strip()
        if not context_key or not isinstance(raw_tables, Mapping):
            continue
        normalized_tables: Dict[str, Dict[str, int]] = {}
        for raw_table_id, raw_width_map in raw_tables.items():
            table_id = str(raw_table_id or "").strip()
            if not table_id or not isinstance(raw_width_map, Mapping):
                continue
            width_map: Dict[str, int] = {}
            for raw_column, raw_width in raw_width_map.items():
                column_id = str(raw_column or "").strip()
                if not column_id:
                    continue
                width_value = _safe_rust_int(raw_width, 0)
                if width_value is None or int(width_value) <= 0:
                    continue
                width_map[column_id] = int(width_value)
            if width_map:
                normalized_tables[table_id] = width_map
        if normalized_tables:
            normalized[context_key] = normalized_tables
    return normalized


def _default_sol_output_workspace_state() -> Dict[str, Any]:
    """Return default persisted state for shared output-workspace layout.

    Purpose:
        Provide one canonical baseline persistence payload for panel layout state.
    Why:
        Default/global/profile layering requires a deterministic default payload
        for first-run and migration scenarios.
    Inputs:
        None.
    Outputs:
        Dict[str, Any]: Default workspace-layout state payload.
    Side Effects:
        None.
    Exceptions:
        None.
    """
    return {
        "schema_version": SOL_OUTPUT_WORKSPACE_SCHEMA_VERSION,
        "global_layout": _normalize_sol_output_workspace_panel_layout_map(
            SOL_OUTPUT_WORKSPACE_DEFAULT_PANEL_LAYOUT
        ),
        "profile_overrides": {},
        "analytics_visibility_scope": (
            SOL_OUTPUT_WORKSPACE_ANALYTICS_SCOPE_ANALYSIS_ONLY
        ),
        "analysis_table_width_profiles": {},
    }


def _normalize_sol_output_workspace_state(value: Any) -> Dict[str, Any]:
    """Normalize persisted shared output-workspace state into a safe schema.

    Purpose:
        Coerce stored freeform panel layout payloads into a stable settings shape.
    Why:
        Version upgrades and manual edits can introduce malformed payloads that
        must not break output-workspace restore behavior.
    Inputs:
        value: Raw persisted settings payload.
    Outputs:
        Dict[str, Any]: Sanitized workspace-layout state payload.
    Side Effects:
        None.
    Exceptions:
        Invalid payloads fall back to defaults.
    """
    defaults = _default_sol_output_workspace_state()
    if not isinstance(value, Mapping):
        return defaults
    normalized_global = _normalize_sol_output_workspace_panel_layout_map(
        value.get("global_layout"),
        fallback=defaults.get("global_layout"),
    )
    normalized_overrides: Dict[str, Dict[str, Dict[str, int]]] = {}
    raw_overrides = value.get("profile_overrides")
    if isinstance(raw_overrides, Mapping):
        for raw_profile, raw_layout in raw_overrides.items():
            profile_key = str(raw_profile or "").strip()
            if not profile_key:
                continue
            normalized_overrides[profile_key] = _normalize_sol_output_workspace_panel_layout_map(
                raw_layout,
                fallback=normalized_global,
            )
    normalized_scope = _normalize_sol_output_workspace_analytics_scope(
        value.get("analytics_visibility_scope")
    )
    normalized_width_profiles = _normalize_sol_output_workspace_analysis_table_width_profiles(
        value.get("analysis_table_width_profiles")
    )
    return {
        "schema_version": SOL_OUTPUT_WORKSPACE_SCHEMA_VERSION,
        "global_layout": normalized_global,
        "profile_overrides": normalized_overrides,
        "analytics_visibility_scope": normalized_scope,
        "analysis_table_width_profiles": normalized_width_profiles,
    }

