def _normalize_csv_repeatable_mapping_value(value: Any) -> List[str]:
    """Normalize repeatable CSV channel mapping values.

    Purpose:
        Convert legacy scalar channel mappings and new multi-select payloads into
        one ordered list of source CSV column names.
    Why:
        CSV import roles now support multiple traces, but older settings still
        persist single strings or optional `(None)` selections.
    Inputs:
        value: Candidate string, sequence, or malformed mapping payload.
    Outputs:
        Ordered de-duplicated list of source column labels.
    Side Effects:
        None.
    Exceptions:
        None; malformed entries are ignored.
    """
    if isinstance(value, str) or value is None:
        candidates: Sequence[Any] = [value]
    elif isinstance(value, Sequence) and not isinstance(value, (str, bytes)):
        candidates = list(value)
    else:
        candidates = [value]
    values: List[str] = []
    seen: Set[str] = set()
    for item in candidates:
        if item is None:
            normalized = ""
        elif isinstance(item, str):
            normalized = "" if item.strip() == "(None)" else item.strip()
        else:
            normalized = str(item).strip()
        if not normalized or normalized in seen:
            continue
        values.append(normalized)
        seen.add(normalized)
    return values


def _normalize_csv_channel_metadata(raw_metadata: Any) -> Dict[str, Dict[str, str]]:
    """Normalize Graphtec CSV channel metadata.

    Purpose:
        Sanitize metadata rows that map raw channel IDs such as `CH7` to signal
        names and units.
    Why:
        Import dialogs need human-readable labels without changing the raw data
        header keys used for parsing.
    Inputs:
        raw_metadata: Candidate metadata mapping keyed by channel column name.
    Outputs:
        Dict keyed by raw channel name with string `channel`, `signal_name`,
        `unit`, and `display_label` fields.
    Side Effects:
        None.
    Exceptions:
        None; malformed rows are skipped.
    """
    normalized: Dict[str, Dict[str, str]] = {}
    if not isinstance(raw_metadata, Mapping):
        return normalized
    for raw_key, raw_payload in raw_metadata.items():
        channel = str(raw_key or "").strip()
        if not channel:
            continue
        payload = raw_payload if isinstance(raw_payload, Mapping) else {}
        signal_name = str(payload.get("signal_name") or "").strip()
        unit = str(payload.get("unit") or "").strip()
        display_label = _csv_channel_display_label(
            channel,
            {
                channel: {
                    "signal_name": signal_name,
                    "unit": unit,
                }
            },
        )
        normalized[channel] = {
            "channel": channel,
            "signal_name": signal_name,
            "unit": unit,
            "display_label": display_label,
        }
    return normalized


def _csv_channel_display_label(
    column_name: Any, channel_metadata: Optional[Mapping[str, Any]] = None
) -> str:
    """Return a readable CSV channel selector label.

    Purpose:
        Combine raw channel IDs with Graphtec signal names and units for display.
    Why:
        Users should choose `CH7 - Formate 1 (PSI)` instead of guessing from a
        bare `CH7` column, while parser state continues to use the raw key.
    Inputs:
        column_name: Raw CSV column header.
        channel_metadata: Optional normalized metadata mapping.
    Outputs:
        Display label for UI choices and metadata previews.
    Side Effects:
        None.
    Exceptions:
        None; invalid metadata falls back to the raw column label.
    """
    column = str(column_name or "").strip()
    if not column:
        return ""
    payload = None
    if isinstance(channel_metadata, Mapping):
        payload = channel_metadata.get(column)
    if not isinstance(payload, Mapping):
        return column
    signal_name = str(payload.get("signal_name") or "").strip()
    unit = str(payload.get("unit") or "").strip()
    if signal_name and unit:
        return f"{column} - {signal_name} ({unit})"
    if signal_name:
        return f"{column} - {signal_name}"
    if unit:
        return f"{column} ({unit})"
    return column


def _apply_csv_import_settings_defaults(settings_dict: Dict[str, Any]) -> None:
    """Apply CSV import settings defaults.

    Purpose:
        Normalize persisted CSV import settings before UI or import code reads
        them.
    Why:
        Channel mappings now accept repeatable selections while older settings
        stored a single string value for each role.
    Inputs:
        settings_dict: Mutable global settings dictionary.
    Outputs:
        None.
    Side Effects:
        Mutates CSV import keys in `settings_dict`.
    Exceptions:
        Invalid values are replaced with safe defaults instead of raising.
    """
    if not isinstance(settings_dict, dict):
        return
    mapping = settings_dict.get("csv_import_mapping")
    if not isinstance(mapping, dict):
        mapping = {}
    normalized_mapping = {}
    # Normalize each mapping role independently so legacy scalar settings migrate safely.
    for key in CSV_IMPORT_MAPPING_FIELDS.keys():
        value = mapping.get(key, "")
        if key in CSV_IMPORT_REPEATABLE_MAPPING_KEYS:
            normalized_mapping[key] = _normalize_csv_repeatable_mapping_value(value)
            continue
        if value is None:
            normalized_mapping[key] = ""
        elif isinstance(value, str):
            normalized_mapping[key] = "" if value.strip() == "(None)" else value.strip()
        else:
            normalized_mapping[key] = str(value).strip()
    settings_dict["csv_import_mapping"] = normalized_mapping
    channel_metadata = settings_dict.get("csv_import_channel_metadata")
    settings_dict["csv_import_channel_metadata"] = _normalize_csv_channel_metadata(
        channel_metadata
    )

    # Iterate over ("csv_import_last_csv_path", "csv_import_last_workbook_path") to apply the per-item logic.
    for key in ("csv_import_last_csv_path", "csv_import_last_workbook_path"):
        value = settings_dict.get(key, "")
        if value is None:
            value = ""
        if not isinstance(value, str):
            value = str(value)
        settings_dict[key] = value

    sheet_name = settings_dict.get("csv_import_last_sheet_name", "")
    if sheet_name is None:
        sheet_name = ""
    if not isinstance(sheet_name, str):
        sheet_name = str(sheet_name)
    settings_dict["csv_import_last_sheet_name"] = sheet_name

    mode = (
        str(
            settings_dict.get(
                "csv_import_sheet_exists_mode", CSV_IMPORT_DEFAULT_SHEET_EXISTS_MODE
            )
        )
        .strip()
        .lower()
    )
    if mode not in CSV_IMPORT_SHEET_EXISTS_MODES:
        mode = CSV_IMPORT_DEFAULT_SHEET_EXISTS_MODE
    settings_dict["csv_import_sheet_exists_mode"] = mode

    source = (
        str(
            settings_dict.get(
                "csv_import_derivative_source", CSV_IMPORT_DEFAULT_DERIVATIVE_SOURCE
            )
        )
        .strip()
        .lower()
    )
    if source not in CSV_IMPORT_DERIVATIVE_SOURCES:
        source = CSV_IMPORT_DEFAULT_DERIVATIVE_SOURCE
    settings_dict["csv_import_derivative_source"] = source

    dampening = settings_dict.get(
        "csv_import_smoothing_factor", CSV_IMPORT_DEFAULT_DAMPENING
    )
    try:
        dampening_value = float(dampening)
    except (TypeError, ValueError):
        dampening_value = CSV_IMPORT_DEFAULT_DAMPENING
    if not math.isfinite(dampening_value) or not (0.0 <= dampening_value < 1.0):
        dampening_value = CSV_IMPORT_DEFAULT_DAMPENING
    settings_dict["csv_import_smoothing_factor"] = dampening_value

    window = settings_dict.get(
        "csv_import_moving_average_window", CSV_IMPORT_DEFAULT_MOVING_AVG_WINDOW
    )
    try:
        window_value = int(window)
    except (TypeError, ValueError):
        window_value = CSV_IMPORT_DEFAULT_MOVING_AVG_WINDOW
    if window_value < 1:
        window_value = CSV_IMPORT_DEFAULT_MOVING_AVG_WINDOW
    settings_dict["csv_import_moving_average_window"] = window_value

_FINAL_REPORT_FONT_FAMILY: Optional[Tuple[str, ...]] = None


def _get_final_report_font_family_defaults() -> Tuple[str, ...]:
    """Return cached default font-family fallback stack for Final Report output.

    Purpose:
        Lazily resolve report font defaults only when report rendering needs them.
    Why:
        Deferring optional font-stack discovery keeps startup work lightweight
        while preserving deterministic report font fallback behavior.
    Inputs:
        None.
    Outputs:
        Tuple of preferred fallback font family names.
    Side Effects:
        Caches the resolved font tuple in `_FINAL_REPORT_FONT_FAMILY`.
    Exceptions:
        Best-effort guards return an empty tuple on unexpected failures.
    """
    global _FINAL_REPORT_FONT_FAMILY
    if isinstance(_FINAL_REPORT_FONT_FAMILY, tuple):
        return _FINAL_REPORT_FONT_FAMILY
    try:
        _FINAL_REPORT_FONT_FAMILY = tuple(_preferred_plot_font_stack())
    except Exception:
        _FINAL_REPORT_FONT_FAMILY = tuple()
    return _FINAL_REPORT_FONT_FAMILY


