@dataclass
class _RenderCacheSingleflightState:
    """In-flight cache build state for one cache fingerprint.

    Purpose:
        Coordinate one in-flight build across concurrent workers.
    Why:
        Multiple render workers can request the same cache fingerprint at once;
        one owner should compute while other callers wait for completion.
    Inputs:
        None.
    Outputs:
        Dataclass instance containing wait event and waiter counter.
    Side Effects:
        Event is signaled when the owning compute path releases the slot.
    Exceptions:
        None.
    """

    event: threading.Event = field(default_factory=threading.Event)
    waiter_count: int = 0


@dataclass
class RenderCacheManager:
    """Simple cache manager for prepared series and cycle segmentation."""

    prepared: Dict[DataFingerprint, Dict[str, Any]] = field(default_factory=dict)
    cycles: Dict[CycleFingerprint, Dict[str, Any]] = field(default_factory=dict)
    cycle_segments: Dict[CycleSegFingerprint, Dict[str, Any]] = field(
        default_factory=dict
    )
    cycle_metrics: Dict[CycleMetricsFingerprint, Dict[str, Any]] = field(
        default_factory=dict
    )
    _lock: threading.RLock = field(default_factory=threading.RLock, init=False, repr=False)
    _prepared_inflight: Dict[DataFingerprint, _RenderCacheSingleflightState] = field(
        default_factory=dict, init=False, repr=False
    )
    _cycle_segments_inflight: Dict[
        CycleSegFingerprint, _RenderCacheSingleflightState
    ] = field(default_factory=dict, init=False, repr=False)
    _cycle_metrics_inflight: Dict[
        CycleMetricsFingerprint, _RenderCacheSingleflightState
    ] = field(default_factory=dict, init=False, repr=False)

    def _claim_singleflight(
        self,
        inflight_map: Dict[Any, _RenderCacheSingleflightState],
        key: Any,
    ) -> Tuple[bool, threading.Event, int]:
        """Claim or join one in-flight cache build slot.

        Purpose:
            Determine whether the caller owns cache computation for one key.
        Why:
            Singleflight coordination avoids duplicate heavy computations when
            many workers miss the same cache fingerprint concurrently.
        Inputs:
            inflight_map: Namespace map of in-flight slots.
            key: Fingerprint key for the cache namespace.
        Outputs:
            Tuple `(is_owner, wait_event, waiter_count)` where `is_owner` is
            True for the first caller that should compute.
        Side Effects:
            Creates or updates in-flight slot state under the cache lock.
        Exceptions:
            None.
        """
        with self._lock:
            state = inflight_map.get(key)
            if state is None:
                state = _RenderCacheSingleflightState()
                inflight_map[key] = state
                return True, state.event, 0
            state.waiter_count += 1
            return False, state.event, int(state.waiter_count)

    def _release_singleflight(
        self,
        inflight_map: Dict[Any, _RenderCacheSingleflightState],
        cache_map: Dict[Any, Dict[str, Any]],
        key: Any,
        payload: Optional[Dict[str, Any]],
    ) -> int:
        """Release one in-flight cache build slot and optionally store payload.

        Purpose:
            Finalize singleflight state after compute owner finishes.
        Why:
            Waiting workers must be unblocked and should reuse the owner result
            when a valid payload was produced.
        Inputs:
            inflight_map: Namespace map of in-flight slots.
            cache_map: Backing cache map for payload persistence.
            key: Fingerprint key for the cache namespace.
            payload: Computed payload to store, or None on failure.
        Outputs:
            Integer waiter count observed for this in-flight slot.
        Side Effects:
            May write payload to cache, removes in-flight state, and signals
            waiting callers via the slot event.
        Exceptions:
            None.
        """
        event = None
        waiter_count = 0
        with self._lock:
            if isinstance(payload, dict):
                cache_map[key] = payload
            state = inflight_map.pop(key, None)
            if state is not None:
                event = state.event
                waiter_count = int(max(0, state.waiter_count))
        if event is not None:
            try:
                event.set()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        return waiter_count

    def _clear_singleflight_namespace(
        self, inflight_map: Dict[Any, _RenderCacheSingleflightState]
    ) -> None:
        """Clear one singleflight namespace and unblock waiting callers.

        Purpose:
            Reset in-flight build state for a cache namespace.
        Why:
            Cache invalidation/reset workflows must not leave waiters blocked on
            orphaned in-flight events.
        Inputs:
            inflight_map: Namespace map of in-flight slots to clear.
        Outputs:
            None.
        Side Effects:
            Removes in-flight entries and signals each waiter event.
        Exceptions:
            Signaling failures are ignored to keep cache resets resilient.
        """
        states: List[_RenderCacheSingleflightState] = []
        with self._lock:
            states = list(inflight_map.values())
            inflight_map.clear()
        # Iterate over states to release waiting callers during cache reset.
        for state in states:
            try:
                state.event.set()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

    def claim_prepared_singleflight(
        self, fingerprint: DataFingerprint
    ) -> Tuple[bool, threading.Event, int]:
        """Claim one prepared-data singleflight slot.

        Purpose:
            Coordinate ownership for one prepared payload build.
        Why:
            Prevents duplicate prepared-series computation for the same
            fingerprint across concurrent workers.
        Inputs:
            fingerprint: Prepared-data cache fingerprint key.
        Outputs:
            Tuple `(is_owner, wait_event, waiter_count)`.
        Side Effects:
            Mutates prepared in-flight state under cache lock.
        Exceptions:
            None.
        """
        return self._claim_singleflight(self._prepared_inflight, fingerprint)

    def release_prepared_singleflight(
        self, fingerprint: DataFingerprint, payload: Optional[Dict[str, Any]]
    ) -> int:
        """Release one prepared-data singleflight slot.

        Purpose:
            Persist prepared payload and unblock waiting workers.
        Why:
            A single compute owner should satisfy all concurrent waiters.
        Inputs:
            fingerprint: Prepared-data cache fingerprint key.
            payload: Prepared payload dict, or None when compute failed.
        Outputs:
            Integer waiter count released for this key.
        Side Effects:
            May persist payload and signals waiter event.
        Exceptions:
            None.
        """
        return self._release_singleflight(
            self._prepared_inflight, self.prepared, fingerprint, payload
        )

    def claim_cycle_segments_singleflight(
        self, fingerprint: CycleSegFingerprint
    ) -> Tuple[bool, threading.Event, int]:
        """Claim one cycle-segmentation singleflight slot.

        Purpose:
            Coordinate ownership for one segmentation payload build.
        Why:
            Concurrent workers often request the same segmentation key during
            plot refresh bursts.
        Inputs:
            fingerprint: Cycle-segmentation cache fingerprint key.
        Outputs:
            Tuple `(is_owner, wait_event, waiter_count)`.
        Side Effects:
            Mutates segment in-flight state under cache lock.
        Exceptions:
            None.
        """
        return self._claim_singleflight(self._cycle_segments_inflight, fingerprint)

    def release_cycle_segments_singleflight(
        self,
        fingerprint: CycleSegFingerprint,
        payload: Optional[Dict[str, Any]],
    ) -> int:
        """Release one cycle-segmentation singleflight slot.

        Purpose:
            Persist segmentation payload and unblock waiting workers.
        Why:
            One segmentation compute should satisfy all concurrent waiters.
        Inputs:
            fingerprint: Cycle-segmentation cache fingerprint key.
            payload: Segmentation payload dict, or None when compute failed.
        Outputs:
            Integer waiter count released for this key.
        Side Effects:
            May persist payload and signals waiter event.
        Exceptions:
            None.
        """
        return self._release_singleflight(
            self._cycle_segments_inflight,
            self.cycle_segments,
            fingerprint,
            payload,
        )

    def claim_cycle_metrics_singleflight(
        self, fingerprint: CycleMetricsFingerprint
    ) -> Tuple[bool, threading.Event, int]:
        """Claim one cycle-metrics singleflight slot.

        Purpose:
            Coordinate ownership for one metrics payload build.
        Why:
            Metrics builds can be expensive and should be deduplicated across
            concurrent render workers.
        Inputs:
            fingerprint: Cycle-metrics cache fingerprint key.
        Outputs:
            Tuple `(is_owner, wait_event, waiter_count)`.
        Side Effects:
            Mutates metrics in-flight state under cache lock.
        Exceptions:
            None.
        """
        return self._claim_singleflight(self._cycle_metrics_inflight, fingerprint)

    def release_cycle_metrics_singleflight(
        self,
        fingerprint: CycleMetricsFingerprint,
        payload: Optional[Dict[str, Any]],
    ) -> int:
        """Release one cycle-metrics singleflight slot.

        Purpose:
            Persist metrics payload and unblock waiting workers.
        Why:
            One metrics compute should satisfy all concurrent waiters.
        Inputs:
            fingerprint: Cycle-metrics cache fingerprint key.
            payload: Metrics payload dict, or None when compute failed.
        Outputs:
            Integer waiter count released for this key.
        Side Effects:
            May persist payload and signals waiter event.
        Exceptions:
            None.
        """
        return self._release_singleflight(
            self._cycle_metrics_inflight,
            self.cycle_metrics,
            fingerprint,
            payload,
        )

    def get_prepared(self, fingerprint: DataFingerprint) -> Optional[Dict[str, Any]]:
        """Return cached prepared-series payload for one data fingerprint.

        Purpose:
            Fetch previously prepared data context from the render cache.
        Why:
            Async render workers reuse prepared payloads to avoid duplicate
            preprocessing work.
        Inputs:
            fingerprint: Immutable key describing the prepared-data inputs.
        Outputs:
            Optional[Dict[str, Any]]: Cached payload when present, else `None`.
        Side Effects:
            Acquires the cache re-entrant lock for thread-safe lookup.
        Exceptions:
            Missing keys return `None`; lock-protected lookup errors are ignored.
        """
        with self._lock:
            return self.prepared.get(fingerprint)

    def set_prepared(
        self, fingerprint: DataFingerprint, payload: Dict[str, Any]
    ) -> None:
        """Store prepared-series payload for one data fingerprint.

        Purpose:
            Persist prepared data context in the render cache.
        Why:
            Worker/UI phases need a shared thread-safe cache for reused payloads.
        Inputs:
            fingerprint: Immutable key for the prepared payload.
            payload: Prepared data context to cache.
        Outputs:
            None.
        Side Effects:
            Mutates `prepared` cache under the re-entrant lock.
        Exceptions:
            Write failures are not raised to callers.
        """
        with self._lock:
            self.prepared[fingerprint] = payload

    def get_cycles(self, fingerprint: CycleFingerprint) -> Optional[Dict[str, Any]]:
        """Return cached cycle-analysis payload for one cycle fingerprint.

        Purpose:
            Read cached cycle overlay/summary context.
        Why:
            Cycle precompute is expensive and should be reused across renders.
        Inputs:
            fingerprint: Immutable cycle cache key.
        Outputs:
            Optional[Dict[str, Any]]: Cached cycle payload, or `None`.
        Side Effects:
            Acquires the cache re-entrant lock for thread-safe lookup.
        Exceptions:
            Missing keys return `None`; lookup failures are suppressed.
        """
        with self._lock:
            return self.cycles.get(fingerprint)

    def set_cycles(
        self, fingerprint: CycleFingerprint, payload: Dict[str, Any]
    ) -> None:
        """Store cycle-analysis payload for one cycle fingerprint.

        Purpose:
            Persist cycle context for reuse by later render tasks.
        Why:
            Caching avoids repeated cycle segmentation/summary computation.
        Inputs:
            fingerprint: Immutable key for cycle cache entry.
            payload: Cycle-analysis payload to store.
        Outputs:
            None.
        Side Effects:
            Mutates `cycles` cache under the re-entrant lock.
        Exceptions:
            Write failures are not raised to callers.
        """
        with self._lock:
            self.cycles[fingerprint] = payload

    def get_cycle_segments(
        self, fingerprint: CycleSegFingerprint
    ) -> Optional[Dict[str, Any]]:
        """Return cached cycle-segmentation payload for one segment fingerprint.

        Purpose:
            Read cached cycle segment boundaries/metadata.
        Why:
            Segment extraction is reused by both overlay and metrics paths.
        Inputs:
            fingerprint: Immutable cycle-segmentation cache key.
        Outputs:
            Optional[Dict[str, Any]]: Cached segment payload, or `None`.
        Side Effects:
            Acquires the cache re-entrant lock for thread-safe lookup.
        Exceptions:
            Missing keys return `None`; lookup failures are suppressed.
        """
        with self._lock:
            return self.cycle_segments.get(fingerprint)

    def set_cycle_segments(
        self, fingerprint: CycleSegFingerprint, payload: Dict[str, Any]
    ) -> None:
        """Store cycle-segmentation payload for one segment fingerprint.

        Purpose:
            Persist cycle segment results for downstream metrics/overlay reuse.
        Why:
            Shared cache entries reduce repeated segmentation work.
        Inputs:
            fingerprint: Immutable key for cycle-segmentation cache entry.
            payload: Cycle-segmentation payload to store.
        Outputs:
            None.
        Side Effects:
            Mutates `cycle_segments` cache under the re-entrant lock.
        Exceptions:
            Write failures are not raised to callers.
        """
        with self._lock:
            self.cycle_segments[fingerprint] = payload

    def get_cycle_metrics(
        self, fingerprint: CycleMetricsFingerprint
    ) -> Optional[Dict[str, Any]]:
        """Return cached cycle-metrics payload for one metrics fingerprint.

        Purpose:
            Read cached cycle metrics derived from segmentation + moles inputs.
        Why:
            Metrics calculation can be reused across render/update workflows.
        Inputs:
            fingerprint: Immutable cycle-metrics cache key.
        Outputs:
            Optional[Dict[str, Any]]: Cached metrics payload, or `None`.
        Side Effects:
            Acquires the cache re-entrant lock for thread-safe lookup.
        Exceptions:
            Missing keys return `None`; lookup failures are suppressed.
        """
        with self._lock:
            return self.cycle_metrics.get(fingerprint)

    def set_cycle_metrics(
        self, fingerprint: CycleMetricsFingerprint, payload: Dict[str, Any]
    ) -> None:
        """Store cycle-metrics payload for one metrics fingerprint.

        Purpose:
            Persist computed cycle metrics for reuse by render consumers.
        Why:
            Cached metrics avoid repeated calculations for unchanged inputs.
        Inputs:
            fingerprint: Immutable key for cycle-metrics cache entry.
            payload: Cycle-metrics payload to store.
        Outputs:
            None.
        Side Effects:
            Mutates `cycle_metrics` cache under the re-entrant lock.
        Exceptions:
            Write failures are not raised to callers.
        """
        with self._lock:
            self.cycle_metrics[fingerprint] = payload

    def clear_prepared(self) -> None:
        """Clear all prepared-series cache entries.

        Purpose:
            Remove all cached prepared payloads.
        Why:
            Cache invalidation is required when source data/signatures change.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Mutates `prepared` cache under the re-entrant lock.
        Exceptions:
            Clear failures are not raised to callers.
        """
        with self._lock:
            self.prepared.clear()
        self._clear_singleflight_namespace(self._prepared_inflight)

    def clear_cycles(self) -> None:
        """Clear all cycle-analysis cache entries.

        Purpose:
            Remove cached cycle overlay/summary payloads.
        Why:
            Cycle cache must be reset when cycle inputs or policies change.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Mutates `cycles` cache under the re-entrant lock.
        Exceptions:
            Clear failures are not raised to callers.
        """
        with self._lock:
            self.cycles.clear()

    def clear_cycle_segments(self) -> None:
        """Clear all cached cycle-segmentation entries.

        Purpose:
            Remove cached cycle segment payloads.
        Why:
            Segment caches must be invalidated when segmentation inputs change.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Mutates `cycle_segments` cache under the re-entrant lock.
        Exceptions:
            Clear failures are not raised to callers.
        """
        with self._lock:
            self.cycle_segments.clear()
        self._clear_singleflight_namespace(self._cycle_segments_inflight)

    def clear_cycle_metrics(self) -> None:
        """Clear all cached cycle-metrics entries.

        Purpose:
            Remove cached cycle metrics payloads.
        Why:
            Metrics caches must be invalidated when moles/segmentation inputs change.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Mutates `cycle_metrics` cache under the re-entrant lock.
        Exceptions:
            Clear failures are not raised to callers.
        """
        with self._lock:
            self.cycle_metrics.clear()
        self._clear_singleflight_namespace(self._cycle_metrics_inflight)


