@dataclass(frozen=True)
class ReactionSpecies:
    """Describe one reusable Reaction Dashboard species row.

    Purpose:
        Store species identity, display metadata, default amount, and yield math
        values for template-driven reaction calculations.
    Why:
        Reaction Dashboard templates must be editable and extensible without
        hard-coding sodium methoxide workflow assumptions into UI callbacks.
    Inputs:
        Dataclass fields define species id/name/formula, phase, role, molar mass,
        default initial moles, and optional charge.
    Outputs:
        Immutable species record used by template validation and compute paths.
    Side Effects:
        None.
    Exceptions:
        None.
    """

    species_id: str
    name: str
    formula: str
    phase: str
    role: str
    molar_mass_g_mol: float
    initial_moles: float = 0.0
    charge: int = 0


@dataclass(frozen=True)
class ReactionStep:
    """Describe one stoichiometric step in a Reaction Dashboard template.

    Purpose:
        Store the net stoichiometric coefficient map for one linked reaction step.
    Why:
        Linked workflows need a generic step model so intermediate carryover works
        for sodium formate now and future templates later.
    Inputs:
        `stoichiometry` maps species ids to signed coefficients, with negative
        values for consumed species and positive values for produced species.
    Outputs:
        Immutable step record consumed by Rust and Python extent solvers.
    Side Effects:
        None.
    Exceptions:
        None.
    """

    step_id: str
    name: str
    stoichiometry: Dict[str, float]
    description: str = ""


@dataclass(frozen=True)
class ReactionInputField:
    """Describe one template-specific Reaction Dashboard input field.

    Purpose:
        Declare a user-editable input needed by a reaction template.
    Why:
        The dashboard must render required condition/reactant fields from the
        selected template instead of maintaining one fixed form.
    Inputs:
        Dataclass fields define field id, label, units, default value, target
        species binding, whether the field is required, tooltip copy, and the
        visual workflow group used by the dashboard form.
    Outputs:
        Immutable field descriptor used by the template-first UI.
    Side Effects:
        None.
    Exceptions:
        None.
    """

    field_id: str
    label: str
    units: str = ""
    default: str = ""
    required: bool = False
    target_species_id: Optional[str] = None
    quantity: str = "scalar"
    tooltip: str = ""
    group: str = "template"


@dataclass(frozen=True)
class ReactionYieldBasis:
    """Describe the primary yield basis for a Reaction Dashboard template.

    Purpose:
        Identify the product, optional limiting basis species, and actual-yield
        input used for primary KPI calculations.
    Why:
        Template-neutral yield math must know which species represents the final
        product and how completion should be interpreted.
    Inputs:
        Dataclass fields define product species id, optional target reactant id,
        actual mass field id, and KPI label.
    Outputs:
        Immutable yield-basis descriptor used by compute and display paths.
    Side Effects:
        None.
    Exceptions:
        None.
    """

    product_species_id: str
    target_reactant_species_id: Optional[str] = None
    actual_mass_field_id: str = "actual_product_mass_g"
    label: str = "Final product yield"


@dataclass(frozen=True)
class ReactionEquilibriumSpec:
    """Describe optional ChemPy equilibrium rows for pH calculation.

    Purpose:
        Store user/template equilibrium equations and initial concentration rows.
    Why:
        pH calculation is optional and external-engine-backed, so the dashboard
        needs a clean data contract that can fail independently from yield math.
    Inputs:
        Dataclass fields define enablement, equation strings, initial
        concentrations, and the species id/name used for pH.
    Outputs:
        Immutable equilibrium descriptor passed to the ChemPy adapter.
    Side Effects:
        None.
    Exceptions:
        None.
    """

    enabled_by_default: bool = False
    equations: Tuple[str, ...] = ()
    initial_concentrations_m: Dict[str, float] = field(default_factory=dict)
    ph_species: str = "H+"


@dataclass(frozen=True)
class ReactionTemplate:
    """Describe one reusable Reaction Dashboard template.

    Purpose:
        Group species, linked reaction steps, required inputs, yield basis, pH
        options, and display metadata into one selectable template.
    Why:
        Reaction Dashboard must start with sodium methoxide / CO chemistry while
        remaining easy to extend to future reaction schemes.
    Inputs:
        Dataclass fields define stable template id/version/name, read-only state,
        gas species, species/step/input rows, yield basis, equilibrium settings,
        optional display equations, KPI labels, and default plot identifiers.
    Outputs:
        Immutable template record used by the UI, persistence, and compute layer.
    Side Effects:
        None.
    Exceptions:
        None.
    """

    template_id: str
    name: str
    version: str
    description: str
    readonly: bool
    reaction_family: str
    gas_species_id: str
    species: Tuple[ReactionSpecies, ...]
    steps: Tuple[ReactionStep, ...]
    input_fields: Tuple[ReactionInputField, ...]
    yield_basis: ReactionYieldBasis
    equilibrium: ReactionEquilibriumSpec = field(
        default_factory=ReactionEquilibriumSpec
    )
    equation_display: Tuple[str, ...] = ()
    kpi_labels: Dict[str, str] = field(default_factory=dict)
    default_plots: Tuple[str, ...] = ("extent", "inventory", "yield")


REACTION_DASHBOARD_CUSTOM_TEMPLATES_KEY = "reaction_dashboard_custom_templates"
REACTION_DASHBOARD_SELECTED_TEMPLATE_KEY = "reaction_dashboard_selected_template_id"
REACTION_DASHBOARD_SOURCE_MODES: Tuple[Tuple[str, str], ...] = (
    ("cycle_payload", "Imported Cycle Analysis payload"),
    ("reactor_pressure", "Reactor pressure delta"),
    ("cylinder_loss", "Cylinder mass loss"),
    ("manual", "Manual gas mass / moles"),
)
REACTION_DASHBOARD_DEFAULT_SOURCE_MODE = "cycle_payload"
REACTION_DASHBOARD_PLOT_KEY = "fig_reaction_dashboard_tab"
REACTION_DASHBOARD_PLOT_ID = "fig_reaction_dashboard"
REACTION_DASHBOARD_STATUS_COLORS: Dict[str, str] = {
    "complete": "#2e8b57",
    "healthy": "#2e8b57",
    "watch": "#d47f00",
    "blocked": "#b22222",
    "neutral": "#2f6f8f",
    "unavailable": "#7f8c8d",
}


def _normalize_reaction_dashboard_state_payload(
    payload: Optional[Mapping[str, Any]],
) -> Dict[str, Any]:
    """Normalize persisted Reaction Dashboard profile state.

    Purpose:
        Convert candidate profile JSON into the stable dashboard-state shape used
        by save/load paths.
    Why:
        Profiles may be missing dashboard state, may contain stale field ids, or
        may carry non-string values from older experiments; restore code needs one
        sanitized payload before touching live Tk variables.
    Inputs:
        payload: Optional mapping read from a profile document.
    Outputs:
        Dict containing only recognized JSON-safe dashboard-state keys.
    Side Effects:
        None.
    Exceptions:
        Invalid values are dropped or defaulted instead of raising.
    """
    if not isinstance(payload, Mapping):
        return {}

    def _string_map(raw_value: Any) -> Dict[str, str]:
        """Return one string-key/string-value mapping for persisted inputs.

        Purpose:
            Sanitize one nested input-value mapping from profile JSON.
        Why:
            Dashboard restore should only work with stable string field ids and
            JSON-safe text values.
        Args:
            raw_value: Candidate mapping from a profile payload.
        Returns:
            Dict of non-empty string keys to string values.
        Side Effects:
            None.
        Exceptions:
            Invalid mapping rows are skipped instead of raising.
        """
        if not isinstance(raw_value, Mapping):
            return {}
        values: Dict[str, str] = {}
        for raw_key, raw_entry in raw_value.items():
            key = str(raw_key or "").strip()
            if not key:
                continue
            values[key] = "" if raw_entry is None else str(raw_entry)
        return values

    def _optional_bool(raw_value: Any) -> Optional[bool]:
        """Return a profile-safe boolean or None.

        Purpose:
            Normalize persisted boolean-like values from profile JSON.
        Why:
            Older or hand-edited profiles can store strings or numeric values that
            should not be treated as truthy merely because they are non-empty.
        Args:
            raw_value: Candidate boolean-like value.
        Returns:
            True/False when recognized, otherwise None.
        Side Effects:
            None.
        Exceptions:
            Invalid values are normalized to None instead of raising.
        """
        if raw_value is None:
            return None
        if isinstance(raw_value, bool):
            return raw_value
        if isinstance(raw_value, str):
            token = raw_value.strip().lower()
            if token in {"1", "true", "yes", "on"}:
                return True
            if token in {"0", "false", "no", "off"}:
                return False
            return None
        if isinstance(raw_value, (int, float)) and math.isfinite(float(raw_value)):
            return bool(raw_value)
        return None

    normalized: Dict[str, Any] = {}
    template_id = str(payload.get("template_id") or "").strip()
    if template_id:
        normalized["template_id"] = template_id

    source_mode = str(payload.get("source_mode") or "").strip()
    valid_source_modes = {key for key, _label in REACTION_DASHBOARD_SOURCE_MODES}
    if source_mode in valid_source_modes:
        normalized["source_mode"] = source_mode
    elif "source_mode" in payload:
        normalized["source_mode"] = REACTION_DASHBOARD_DEFAULT_SOURCE_MODE

    if "ph_enabled" in payload:
        ph_enabled = _optional_bool(payload.get("ph_enabled"))
        if ph_enabled is not None:
            normalized["ph_enabled"] = ph_enabled

    template_inputs = _string_map(payload.get("template_inputs"))
    if template_inputs or "template_inputs" in payload:
        normalized["template_inputs"] = template_inputs
    source_inputs = _string_map(payload.get("source_inputs"))
    if source_inputs or "source_inputs" in payload:
        normalized["source_inputs"] = source_inputs

    # Run records are additive: a profile saved by the former single-form
    # dashboard becomes one active record rather than losing its typed inputs.
    normalized_runs: List[Dict[str, Any]] = []
    raw_runs = payload.get("runs")
    if isinstance(raw_runs, Sequence) and not isinstance(raw_runs, (str, bytes)):
        for index, raw_run in enumerate(raw_runs, start=1):
            if not isinstance(raw_run, Mapping):
                continue
            run_id = str(raw_run.get("run_id") or "").strip()
            if not run_id:
                continue
            run_state = _normalize_reaction_dashboard_state_payload(
                {
                    "template_id": raw_run.get("template_id"),
                    "source_mode": raw_run.get("source_mode"),
                    "ph_enabled": raw_run.get("ph_enabled"),
                    "template_inputs": raw_run.get("template_inputs"),
                    "source_inputs": raw_run.get("source_inputs"),
                }
            )
            normalized_runs.append(
                {
                    "run_id": run_id,
                    "name": str(raw_run.get("name") or f"Reaction run {index}").strip()
                    or f"Reaction run {index}",
                    "archived": bool(raw_run.get("archived", False)),
                    "notes": str(raw_run.get("notes") or ""),
                    "updated_at": str(raw_run.get("updated_at") or ""),
                    "snapshot": (
                        dict(raw_run.get("snapshot"))
                        if isinstance(raw_run.get("snapshot"), Mapping)
                        else {}
                    ),
                    **run_state,
                }
            )
    if not normalized_runs and normalized:
        normalized_runs.append(
            {
                "run_id": "legacy-active",
                "name": "Current reaction",
                "archived": False,
                "notes": "",
                "updated_at": "",
                "snapshot": {},
                **dict(normalized),
            }
        )
    if normalized_runs:
        normalized["runs"] = normalized_runs
        requested_active_id = str(payload.get("active_run_id") or "").strip()
        valid_run_ids = {str(row["run_id"]) for row in normalized_runs}
        normalized["active_run_id"] = (
            requested_active_id
            if requested_active_id in valid_run_ids
            else str(normalized_runs[0]["run_id"])
        )
    return normalized


