def _reaction_template_to_dict(template: ReactionTemplate) -> Dict[str, Any]:
    """Serialize one Reaction Dashboard template to a JSON-safe mapping.

    Purpose:
        Convert dataclass-backed templates into persisted custom-template records.
    Why:
        Custom templates must survive restart while built-in templates remain
        immutable source definitions.
    Inputs:
        template: Reaction template record to serialize.
    Outputs:
        JSON-compatible dictionary.
    Side Effects:
        None.
    Exceptions:
        None.
    """
    return {
        "template_id": template.template_id,
        "name": template.name,
        "version": template.version,
        "description": template.description,
        "readonly": bool(template.readonly),
        "reaction_family": template.reaction_family,
        "gas_species_id": template.gas_species_id,
        "species": [asdict(species) for species in template.species],
        "steps": [asdict(step) for step in template.steps],
        "input_fields": [asdict(field_spec) for field_spec in template.input_fields],
        "yield_basis": asdict(template.yield_basis),
        "equilibrium": asdict(template.equilibrium),
        "equation_display": list(template.equation_display),
        "kpi_labels": dict(template.kpi_labels),
        "default_plots": list(template.default_plots),
    }


def _reaction_template_from_dict(
    payload: Mapping[str, Any],
) -> Optional[ReactionTemplate]:
    """Deserialize and validate one Reaction Dashboard template mapping.

    Purpose:
        Build a typed template from persisted settings or editable UI payloads.
    Why:
        The dashboard must reject malformed custom templates before they reach
        compute or plot paths.
    Inputs:
        payload: Candidate mapping with template fields.
    Outputs:
        `ReactionTemplate` when valid, otherwise None.
    Side Effects:
        None.
    Exceptions:
        Invalid rows are caught and normalized to None.
    """
    try:
        species_rows = tuple(
            ReactionSpecies(
                species_id=str(row.get("species_id") or row.get("id") or "").strip(),
                name=str(row.get("name") or "").strip(),
                formula=str(row.get("formula") or "").strip(),
                phase=str(row.get("phase") or "").strip() or "solution",
                role=str(row.get("role") or "").strip() or "species",
                molar_mass_g_mol=float(row.get("molar_mass_g_mol")),
                initial_moles=max(float(row.get("initial_moles") or 0.0), 0.0),
                charge=int(float(row.get("charge") or 0)),
            )
            for row in list(payload.get("species") or [])
            if isinstance(row, Mapping)
        )
        step_rows = tuple(
            ReactionStep(
                step_id=str(row.get("step_id") or row.get("id") or "").strip(),
                name=str(row.get("name") or "").strip(),
                stoichiometry={
                    str(key).strip(): float(value)
                    for key, value in dict(row.get("stoichiometry") or {}).items()
                    if str(key).strip()
                },
                description=str(row.get("description") or "").strip(),
            )
            for row in list(payload.get("steps") or [])
            if isinstance(row, Mapping)
        )
        input_rows = tuple(
            ReactionInputField(
                field_id=str(row.get("field_id") or row.get("id") or "").strip(),
                label=str(row.get("label") or "").strip(),
                units=str(row.get("units") or "").strip(),
                default=str(row.get("default") or ""),
                required=bool(row.get("required", False)),
                target_species_id=(
                    str(row.get("target_species_id") or "").strip() or None
                ),
                quantity=str(row.get("quantity") or "scalar").strip() or "scalar",
                tooltip=str(row.get("tooltip") or "").strip(),
                group=str(row.get("group") or "template").strip() or "template",
            )
            for row in list(payload.get("input_fields") or [])
            if isinstance(row, Mapping)
        )
        yield_payload = (
            payload.get("yield_basis")
            if isinstance(payload.get("yield_basis"), Mapping)
            else {}
        )
        equilibrium_payload = (
            payload.get("equilibrium")
            if isinstance(payload.get("equilibrium"), Mapping)
            else {}
        )
        template = ReactionTemplate(
            template_id=str(payload.get("template_id") or "").strip(),
            name=str(payload.get("name") or "").strip(),
            version=str(payload.get("version") or "1.0").strip() or "1.0",
            description=str(payload.get("description") or "").strip(),
            readonly=bool(payload.get("readonly", False)),
            reaction_family=str(payload.get("reaction_family") or "").strip(),
            gas_species_id=str(payload.get("gas_species_id") or "").strip(),
            species=species_rows,
            steps=step_rows,
            input_fields=input_rows,
            yield_basis=ReactionYieldBasis(
                product_species_id=str(
                    yield_payload.get("product_species_id") or ""
                ).strip(),
                target_reactant_species_id=(
                    str(yield_payload.get("target_reactant_species_id") or "").strip()
                    or None
                ),
                actual_mass_field_id=str(
                    yield_payload.get("actual_mass_field_id") or "actual_product_mass_g"
                ).strip(),
                label=str(yield_payload.get("label") or "Final product yield").strip(),
            ),
            equilibrium=ReactionEquilibriumSpec(
                enabled_by_default=bool(
                    equilibrium_payload.get("enabled_by_default", False)
                ),
                equations=tuple(
                    str(item).strip()
                    for item in list(equilibrium_payload.get("equations") or [])
                    if str(item).strip()
                ),
                initial_concentrations_m={
                    str(key).strip(): float(value)
                    for key, value in dict(
                        equilibrium_payload.get("initial_concentrations_m") or {}
                    ).items()
                    if str(key).strip()
                },
                ph_species=str(equilibrium_payload.get("ph_species") or "H+").strip()
                or "H+",
            ),
            equation_display=tuple(
                str(item).strip()
                for item in list(payload.get("equation_display") or [])
                if str(item).strip()
            ),
            kpi_labels=(
                dict(payload.get("kpi_labels"))
                if isinstance(payload.get("kpi_labels"), Mapping)
                else {}
            ),
            default_plots=tuple(
                str(item).strip()
                for item in list(payload.get("default_plots") or [])
                if str(item).strip()
            )
            or ("extent", "inventory", "yield"),
        )
    except Exception:
        return None
    if not template.template_id or not template.name:
        return None
    species_ids = {
        species.species_id for species in template.species if species.species_id
    }
    if not species_ids or template.gas_species_id not in species_ids:
        return None
    if template.yield_basis.product_species_id not in species_ids:
        return None
    for step in template.steps:
        if not step.step_id or not step.stoichiometry:
            return None
        if any(species_id not in species_ids for species_id in step.stoichiometry):
            return None
    return template


_REACTION_FORMULA_SUBSCRIPT_MAP = str.maketrans(
    {
        "0": "₀",
        "1": "₁",
        "2": "₂",
        "3": "₃",
        "4": "₄",
        "5": "₅",
        "6": "₆",
        "7": "₇",
        "8": "₈",
        "9": "₉",
    }
)


def _reaction_formula_display_text(formula: Any) -> str:
    """Return one chemical formula with numeric subscripts for dashboard display.

    Purpose:
        Convert plain template formulas such as `C2H4O2` into compact chemistry
        notation suitable for the Reaction Equation UI.
    Why:
        Templates persist ASCII-safe formulas for JSON editing, while operators
        need a readable equation display in the dashboard.
    Inputs:
        formula: Candidate formula text from a species row or equation payload.
    Outputs:
        Formula string with digits translated to Unicode subscripts.
    Side Effects:
        None.
    Exceptions:
        None; invalid values return an empty string.
    """
    text = str(formula or "").strip()
    if not text:
        return ""
    return text.translate(_REACTION_FORMULA_SUBSCRIPT_MAP)


def _reaction_stoich_coefficient_text(value: Any) -> str:
    """Return a compact stoichiometric coefficient prefix.

    Purpose:
        Format coefficients for derived reaction equations without cluttering
        unit coefficients.
    Why:
        Template stoichiometry is numeric and may be integer-like or fractional,
        so display formatting must preserve non-integer ratios clearly.
    Inputs:
        value: Positive stoichiometric coefficient magnitude.
    Outputs:
        Empty string for coefficient 1, otherwise a display prefix ending in a
        space.
    Side Effects:
        None.
    Exceptions:
        Invalid values are normalized to an empty coefficient.
    """
    coeff = _safe_float(value)
    if coeff is None or not math.isfinite(coeff) or coeff <= 0.0:
        return ""
    if abs(coeff - 1.0) <= 1e-12:
        return ""
    if abs(coeff - round(coeff)) <= 1e-12:
        return f"{int(round(coeff))} "
    return f"{coeff:.6g} "


def _reaction_equation_side_terms(
    stoichiometry: Mapping[str, Any],
    species_formula_by_id: Mapping[str, str],
    *,
    reactants: bool,
) -> List[str]:
    """Build one side of a derived reaction equation.

    Purpose:
        Convert signed stoichiometric coefficients into ordered reactant or
        product terms.
    Why:
        Both per-step equations and the net overall equation need the same
        coefficient/formula formatting contract.
    Inputs:
        stoichiometry: Species-id to signed coefficient mapping.
        species_formula_by_id: Display formula lookup keyed by species id.
        reactants: True for negative coefficients, False for positive products.
    Outputs:
        Ordered list of formatted equation terms.
    Side Effects:
        None.
    Exceptions:
        Invalid coefficients are skipped.
    """
    terms: List[str] = []
    for species_id, raw_coeff in stoichiometry.items():
        coeff = _safe_float(raw_coeff)
        if coeff is None or not math.isfinite(coeff):
            continue
        if reactants and coeff >= -1e-12:
            continue
        if not reactants and coeff <= 1e-12:
            continue
        magnitude = abs(float(coeff))
        formula = species_formula_by_id.get(str(species_id), str(species_id))
        label = _reaction_formula_display_text(formula) or str(species_id)
        terms.append(f"{_reaction_stoich_coefficient_text(magnitude)}{label}")
    return terms


def _reaction_equation_from_stoichiometry(
    stoichiometry: Mapping[str, Any],
    species_formula_by_id: Mapping[str, str],
) -> str:
    """Return a display equation from one stoichiometric coefficient mapping.

    Purpose:
        Render signed template stoichiometry as `reactants -> products` text.
    Why:
        The Reaction Equation section should always reflect the selected
        template, even when no author-provided equation override exists.
    Inputs:
        stoichiometry: Species-id to signed coefficient mapping.
        species_formula_by_id: Display formula lookup keyed by species id.
    Outputs:
        Formatted chemical equation string.
    Side Effects:
        None.
    Exceptions:
        Missing sides fall back to `--` so malformed display data is obvious.
    """
    left = _reaction_equation_side_terms(
        stoichiometry, species_formula_by_id, reactants=True
    )
    right = _reaction_equation_side_terms(
        stoichiometry, species_formula_by_id, reactants=False
    )
    left_text = " + ".join(left) if left else "--"
    right_text = " + ".join(right) if right else "--"
    return f"{left_text} → {right_text}"


def _reaction_template_equation_lines(template: ReactionTemplate) -> Tuple[str, ...]:
    """Return display-ready reaction equation lines for one template.

    Purpose:
        Resolve the operator-facing Reaction Equation text from an optional
        template override or from derived step/net stoichiometry.
    Why:
        Custom templates need editable display equations, while built-in and
        legacy templates should still show useful chemistry without schema edits.
    Inputs:
        template: Active Reaction Dashboard template.
    Outputs:
        Tuple of equation display lines.
    Side Effects:
        None.
    Exceptions:
        None; invalid or empty template data returns a placeholder line.
    """
    override_lines = tuple(
        str(line).strip() for line in template.equation_display if str(line).strip()
    )
    if override_lines:
        return override_lines
    species_formula_by_id = {
        species.species_id: species.formula or species.name or species.species_id
        for species in template.species
        if species.species_id
    }
    lines: List[str] = []
    net_stoichiometry: Dict[str, float] = {}
    for index, step in enumerate(template.steps, start=1):
        equation = _reaction_equation_from_stoichiometry(
            step.stoichiometry, species_formula_by_id
        )
        label = step.name or step.step_id or f"Step {index}"
        lines.append(f"{label}: {equation}")
        for species_id, coeff in step.stoichiometry.items():
            value = _safe_float(coeff)
            if value is None or not math.isfinite(value):
                continue
            key = str(species_id).strip()
            if not key:
                continue
            net_stoichiometry[key] = net_stoichiometry.get(key, 0.0) + float(value)
    net_stoichiometry = {
        species_id: coeff
        for species_id, coeff in net_stoichiometry.items()
        if abs(float(coeff)) > 1e-12
    }
    if len(template.steps) > 1 and net_stoichiometry:
        lines.append(
            "Overall: "
            + _reaction_equation_from_stoichiometry(
                net_stoichiometry, species_formula_by_id
            )
        )
    return tuple(lines or ("No reaction equation is defined for this template.",))


REACTION_SODIUM_MOLAR_MASS_G_MOL = 22.989769
REACTION_WATER_MOLAR_MASS_G_MOL = 18.01528
REACTION_METHANOL_MOLAR_MASS_G_MOL = 32.042
REACTION_NAOH_MOLAR_MASS_G_MOL = 39.997


def _python_reaction_solution_charge_core(
    *,
    sodium_metal_mass_g: Optional[float],
    methanol_mass_g: Optional[float],
    water_ppm_by_mass: Optional[float],
    explicit_naoh_mass_g: Optional[float],
) -> Dict[str, Any]:
    """Compute sodium/methanol/water charge availability in Python.

    Purpose:
        Convert sodium metal, methanol charge, methanol dryness, and explicit
        NaOH charge into moles available to the Reaction Dashboard template.
    Why:
        The sodium methoxide starter workflow must account for water consuming
        sodium before sodium methoxide formation while preserving Python fallback
        behavior when the Rust kernel is unavailable.
    Inputs:
        sodium_metal_mass_g: Sodium metal charged, in grams.
        methanol_mass_g: Wet methanol charge, in grams.
        water_ppm_by_mass: Methanol water content as mg/kg by mass.
        explicit_naoh_mass_g: Added NaOH mass for hydrolysis, in grams.
    Outputs:
        Dict with sodium, water, methanol, generated NaOH, total NaOH, sodium
        methoxide, leftover methanol, and warning fields.
    Side Effects:
        None.
    Exceptions:
        Invalid inputs are normalized to zero and reported in warnings.
    """
    warnings: List[str] = []

    def _nonnegative(value: Optional[float], label: str) -> float:
        """Return one nonnegative finite scalar and record invalid input warnings."""
        parsed = _safe_float(value)
        if parsed is None or not math.isfinite(parsed):
            warnings.append(f"{label} is missing or invalid; using 0.")
            return 0.0
        if parsed < 0.0:
            warnings.append(f"{label} was negative; using 0.")
            return 0.0
        return float(parsed)

    sodium_mass = _nonnegative(sodium_metal_mass_g, "Sodium metal mass")
    wet_methanol_mass = _nonnegative(methanol_mass_g, "Methanol mass")
    water_ppm = _nonnegative(water_ppm_by_mass, "Methanol water ppm")
    explicit_naoh_mass = _nonnegative(explicit_naoh_mass_g, "Explicit NaOH mass")

    water_mass_g = wet_methanol_mass * water_ppm / 1_000_000.0
    dry_methanol_mass_g = max(wet_methanol_mass - water_mass_g, 0.0)
    sodium_mol = sodium_mass / REACTION_SODIUM_MOLAR_MASS_G_MOL
    water_mol = water_mass_g / REACTION_WATER_MOLAR_MASS_G_MOL
    methanol_mol = dry_methanol_mass_g / REACTION_METHANOL_MOLAR_MASS_G_MOL
    explicit_naoh_mol = explicit_naoh_mass / REACTION_NAOH_MOLAR_MASS_G_MOL

    sodium_consumed_by_water_mol = min(sodium_mol, water_mol)
    generated_naoh_mol = sodium_consumed_by_water_mol
    sodium_after_water_mol = max(sodium_mol - sodium_consumed_by_water_mol, 0.0)
    sodium_methoxide_mol = min(sodium_after_water_mol, methanol_mol)
    remaining_methanol_mol = max(methanol_mol - sodium_methoxide_mol, 0.0)
    unreacted_sodium_mol = max(sodium_after_water_mol - sodium_methoxide_mol, 0.0)
    excess_water_mol = max(water_mol - sodium_consumed_by_water_mol, 0.0)

    if excess_water_mol > 1e-12:
        warnings.append(
            "Water exceeds sodium charge; sodium methoxide availability is zero."
        )
    if unreacted_sodium_mol > 1e-12:
        warnings.append("Sodium exceeds available dry methanol; sodium remains unused.")

    total_naoh_mol = explicit_naoh_mol + generated_naoh_mol
    return {
        "backend": "python",
        "sodium_metal_mass_g": sodium_mass,
        "methanol_mass_g": wet_methanol_mass,
        "water_ppm_by_mass": water_ppm,
        "water_mass_g": water_mass_g,
        "dry_methanol_mass_g": dry_methanol_mass_g,
        "sodium_mol": sodium_mol,
        "water_mol": water_mol,
        "methanol_initial_mol": methanol_mol,
        "sodium_consumed_by_water_mol": sodium_consumed_by_water_mol,
        "generated_naoh_mol": generated_naoh_mol,
        "explicit_naoh_mol": explicit_naoh_mol,
        "total_naoh_mol": total_naoh_mol,
        "sodium_methoxide_mol": sodium_methoxide_mol,
        "remaining_methanol_mol": remaining_methanol_mol,
        "unreacted_sodium_mol": unreacted_sodium_mol,
        "excess_water_mol": excess_water_mol,
        "warnings": warnings,
    }


def _python_reaction_dashboard_core(
    species_rows: Sequence[Mapping[str, Any]],
    step_rows: Sequence[Mapping[str, Any]],
    *,
    gas_uptake_mol: float,
    gas_species_id: str,
    yield_species_id: str,
    target_reactant_species_id: Optional[str],
    actual_yield_mass_g: Optional[float],
) -> Dict[str, Any]:
    """Compute template-neutral reaction extent, completion, and yield in Python.

    Purpose:
        Provide the canonical Python fallback for Reaction Dashboard stoichiometry.
    Why:
        Rust acceleration is preferred when healthy, but dashboard calculations
        must remain available in pure Python with the same result schema.
    Inputs:
        species_rows: Species mappings with id, molar mass, and initial moles.
        step_rows: Step mappings with signed stoichiometry by species id.
        gas_uptake_mol: Moles of selected reactant gas absorbed/charged.
        gas_species_id: Species id that receives gas uptake.
        yield_species_id: Product species id used for final yield.
        target_reactant_species_id: Optional species id used for completion basis.
        actual_yield_mass_g: Optional isolated product mass.
    Outputs:
        Dict payload containing inventories, step extents, gas uptake, completion,
        theoretical yield, actual yield, and warnings.
    Side Effects:
        None.
    Exceptions:
        Invalid inputs are normalized into warning-bearing result payloads.
    """
    warnings: List[str] = []
    inventory: Dict[str, float] = {}
    initial_inventory: Dict[str, float] = {}
    molar_masses: Dict[str, float] = {}
    species_names: Dict[str, str] = {}
    for row in species_rows or ():
        if not isinstance(row, Mapping):
            continue
        species_id = str(row.get("species_id") or row.get("id") or "").strip()
        if not species_id:
            continue
        initial = _safe_float(row.get("initial_moles"), 0.0)
        mw_value = _safe_float(row.get("molar_mass_g_mol"), 0.0)
        inventory[species_id] = max(float(initial or 0.0), 0.0)
        initial_inventory[species_id] = inventory[species_id]
        molar_masses[species_id] = max(float(mw_value or 0.0), 0.0)
        species_names[species_id] = str(row.get("name") or species_id).strip()
    gas_id = str(gas_species_id or "").strip()
    gas_uptake = max(float(gas_uptake_mol or 0.0), 0.0)
    if gas_id:
        inventory[gas_id] = inventory.get(gas_id, 0.0) + gas_uptake
        initial_inventory[gas_id] = initial_inventory.get(gas_id, 0.0) + gas_uptake
    else:
        warnings.append("Template does not define a gas species.")

    step_results: List[Dict[str, Any]] = []
    for index, step in enumerate(step_rows or (), start=1):
        if not isinstance(step, Mapping):
            continue
        stoich = {
            str(key).strip(): float(value)
            for key, value in dict(step.get("stoichiometry") or {}).items()
            if str(key).strip()
        }
        reactants = {
            species_id: abs(coeff)
            for species_id, coeff in stoich.items()
            if coeff < 0.0
        }
        if not reactants:
            extent = 0.0
            limiting_species = None
            warnings.append(
                f"{step.get('name') or f'Step {index}'} has no consumed species."
            )
        else:
            candidates = [
                (inventory.get(species_id, 0.0) / max(coeff, 1e-30), species_id)
                for species_id, coeff in reactants.items()
            ]
            extent, limiting_species = min(candidates, key=lambda item: item[0])
            extent = max(float(extent), 0.0)
        for species_id, coeff in stoich.items():
            inventory[species_id] = max(
                inventory.get(species_id, 0.0) + (float(coeff) * extent),
                0.0,
            )
        step_results.append(
            {
                "step_id": str(step.get("step_id") or step.get("id") or index),
                "name": str(step.get("name") or f"Step {index}"),
                "extent_mol": extent,
                "limiting_species_id": limiting_species,
                "limiting_species": species_names.get(limiting_species or "", ""),
            }
        )

    product_id = str(yield_species_id or "").strip()
    product_mol = inventory.get(product_id, 0.0)
    product_mw = molar_masses.get(product_id, 0.0)
    theoretical_yield_g = (
        product_mol * product_mw if product_mol >= 0.0 and product_mw > 0.0 else None
    )
    actual_mass = _safe_float(actual_yield_mass_g)
    actual_yield_pct = None
    if (
        actual_mass is not None
        and theoretical_yield_g is not None
        and theoretical_yield_g > 1e-12
    ):
        actual_yield_pct = max(0.0, (float(actual_mass) / theoretical_yield_g) * 100.0)
    target_id = str(target_reactant_species_id or "").strip()
    target_initial = initial_inventory.get(target_id, 0.0) if target_id else 0.0
    completion_pct = None
    if target_initial > 1e-12:
        completion_pct = max(
            0.0, min(100.0, (product_mol / max(target_initial, 1e-12)) * 100.0)
        )
    elif actual_yield_pct is not None:
        completion_pct = max(0.0, min(100.0, float(actual_yield_pct)))
    elif product_mol > 1e-12:
        completion_pct = 100.0
    gas_mw = molar_masses.get(gas_id, 0.0)
    return {
        "backend": "python",
        "gas_species_id": gas_id,
        "gas_uptake_mol": gas_uptake,
        "gas_uptake_g": gas_uptake * gas_mw if gas_mw > 0.0 else None,
        "initial_inventory_mol": initial_inventory,
        "final_inventory_mol": inventory,
        "step_results": step_results,
        "yield_species_id": product_id,
        "yield_species_moles": product_mol,
        "theoretical_yield_g": theoretical_yield_g,
        "actual_yield_mass_g": actual_mass,
        "actual_yield_pct": actual_yield_pct,
        "completion_pct": completion_pct,
        "warnings": warnings,
    }


def _solve_reaction_dashboard_equilibrium_with_chempy(
    template: ReactionTemplate,
    *,
    enabled: bool,
    liquid_volume_l: Optional[float],
    product_moles: Optional[float],
) -> Dict[str, Any]:
    """Run the optional ChemPy equilibrium/pH adapter for Reaction Dashboard.

    Purpose:
        Convert template equilibrium rows into a ChemPy `EqSystem` solve.
    Why:
        pH should be available when the template provides equilibrium data, while
        uptake/yield results must continue if the external solver fails.
    Inputs:
        template: Active reaction template containing equilibrium rows.
        enabled: Per-run pH engine toggle.
        liquid_volume_l: Optional solution volume for product concentration seed.
        product_moles: Optional final product moles from stoichiometry.
    Outputs:
        Dict with pH, concentration, success/sanity flags, backend, and warnings.
    Side Effects:
        Imports ChemPy lazily when enabled.
    Exceptions:
        ChemPy import/solve failures are captured in the returned warning payload.
    """
    if not enabled:
        return {"enabled": False, "backend": "disabled", "ph": None, "warnings": []}
    eq_spec = template.equilibrium
    if not eq_spec.equations:
        return {
            "enabled": True,
            "backend": "chempy",
            "ph": None,
            "warnings": ["Template does not define equilibrium equations."],
        }
    try:
        from chempy.equilibria import EqSystem
    except Exception as exc:
        return {
            "enabled": True,
            "backend": "chempy",
            "ph": None,
            "warnings": [f"ChemPy is unavailable: {exc}"],
        }
    initial = defaultdict(float)
    for key, value in eq_spec.initial_concentrations_m.items():
        try:
            initial[str(key)] = max(float(value), 0.0)
        except Exception:
            continue
    if liquid_volume_l and product_moles and liquid_volume_l > 0.0:
        # Seed formate concentration for the starter template when the pH system
        # includes the conjugate-base species.
        if "HCOO-" in eq_spec.initial_concentrations_m:
            initial["HCOO-"] = max(float(product_moles) / float(liquid_volume_l), 0.0)
    try:
        eqsys = EqSystem.from_string("\n".join(eq_spec.equations))
        arr, info, sane = eqsys.root(initial)
        concentrations = dict(zip(eqsys.substances, arr, strict=False))
        h_value = _safe_float(concentrations.get(eq_spec.ph_species))
        ph_value = None
        if h_value is not None and h_value > 0.0 and math.isfinite(h_value):
            ph_value = -math.log10(h_value)
        success = bool(info.get("success")) if isinstance(info, Mapping) else bool(info)
        warnings = (
            []
            if success and sane and ph_value is not None
            else ["ChemPy equilibrium solve did not return a sane pH result."]
        )
        return {
            "enabled": True,
            "backend": "chempy",
            "ph": ph_value,
            "success": success,
            "sane": bool(sane),
            "concentrations_m": concentrations,
            "warnings": warnings,
        }
    except Exception as exc:
        return {
            "enabled": True,
            "backend": "chempy",
            "ph": None,
            "warnings": [f"ChemPy equilibrium solve failed: {exc}"],
        }


def _reaction_dashboard_templates_from_settings(
    settings_map: Mapping[str, Any],
) -> Dict[str, ReactionTemplate]:
    """Return built-in and persisted custom Reaction Dashboard templates.

    Purpose:
        Merge immutable built-ins with user-saved custom templates.
    Why:
        The dashboard should always have the starter template while allowing
        future reaction schemes to be saved without code changes.
    Inputs:
        settings_map: Application settings mapping.
    Outputs:
        Mapping of template id to typed `ReactionTemplate` records.
    Side Effects:
        None.
    Exceptions:
        Malformed custom template rows are skipped.
    """
    templates = dict(_builtin_reaction_templates())
    custom_rows = settings_map.get(REACTION_DASHBOARD_CUSTOM_TEMPLATES_KEY)
    if isinstance(custom_rows, Sequence) and not isinstance(custom_rows, (str, bytes)):
        for row in custom_rows:
            if not isinstance(row, Mapping):
                continue
            template = _reaction_template_from_dict(row)
            if template is not None:
                templates[template.template_id] = template
    return templates


