def _solubility_extended_debye_huckel(
    ionic_strength: float, charge: int, ion_size_nm: float
) -> float:
    """Perform solubility extended debye huckel.
    Used to keep the workflow logic localized and testable."""
    if ionic_strength <= 1e-12 or charge == 0:
        return 1.0
    sqrt_i = math.sqrt(ionic_strength)
    denom = 1.0 + SOL_B_DEBYE * ion_size_nm * sqrt_i
    if denom == 0.0:
        denom = 1e-12
    exponent = -SOL_A_DEBYE * (charge**2) * sqrt_i / denom
    return 10.0**exponent


def _solubility_activity_coefficient(
    ionic_strength: float, charge: int, ion_size_nm: float
) -> float:
    """Perform solubility activity coefficient.
    Used to keep the workflow logic localized and testable."""

    if ionic_strength <= SOL_DAVIES_LIMIT:
        sqrt_i = math.sqrt(max(ionic_strength, 1e-12))
        log_gamma = (
            -SOL_A_DEBYE
            * (charge**2)
            * ((sqrt_i / (1.0 + sqrt_i)) - SOL_DAVIES_COEFF * ionic_strength)
        )
        return 10.0**log_gamma
    return _solubility_extended_debye_huckel(ionic_strength, charge, ion_size_nm)


def _solubility_ionic_state(
    na_conc: float,
    h_conc: float,
    hco3_conc: float,
    co3_conc: float,
    *,
    kw_value: float,
    ionic_strength_cap: Optional[float] = None,
) -> tuple[float, Dict[str, float], float]:
    """Perform solubility ionic state.
    Used to keep the workflow logic localized and testable."""
    ionic_strength = max(0.5 * (na_conc + h_conc + hco3_conc + 4.0 * co3_conc), 1e-12)
    if ionic_strength_cap is not None:
        ionic_strength = min(ionic_strength, ionic_strength_cap)
    gammas: Dict[str, float] = {}
    oh_conc = 1e-7
    # Iterate over the configured range to apply the per-item logic.
    for _ in range(24):
        gammas = {
            ion: _solubility_activity_coefficient(
                ionic_strength, SOL_ION_CHARGES[ion], SOL_ION_SIZES_NM[ion]
            )
            # Iterate to apply the per-item logic.
            for ion in ("Na", "H", "HCO3", "CO3", "OH")
        }
        oh_conc = kw_value / max(gammas["H"] * gammas["OH"] * h_conc, 1e-18)
        new_i = 0.5 * (na_conc + h_conc + hco3_conc + 4.0 * co3_conc + oh_conc)
        if ionic_strength_cap is not None:
            new_i = min(new_i, ionic_strength_cap)
        if abs(new_i - ionic_strength) < 1e-12:
            ionic_strength = new_i
            break
        ionic_strength = new_i
    return ionic_strength, gammas, oh_conc


def _solubility_solve_linear_system(
    matrix: List[List[float]], rhs: List[float]
) -> List[float]:
    """Solve linear system.
    Used by solubility workflows to solve linear system."""
    n = len(matrix)
    aug = [row[:] + [b] for row, b in zip(matrix, rhs)]
    # Iterate over the configured range to apply the per-item logic.
    for col in range(n):
        pivot_row = max(range(col, n), key=lambda r: abs(aug[r][col]))
        if abs(aug[pivot_row][col]) < 1e-14:
            raise ValueError("Singular matrix encountered in Newton step.")
        if pivot_row != col:
            aug[col], aug[pivot_row] = aug[pivot_row], aug[col]
        pivot = aug[col][col]
        # Iterate over the configured range to apply the per-item logic.
        for j in range(col, n + 1):
            aug[col][j] /= pivot
        # Iterate over the configured range to apply the per-item logic.
        for row in range(n):
            if row == col:
                continue
            factor = aug[row][col]
            # Iterate over the configured range to apply the per-item logic.
            for j in range(col, n + 1):
                aug[row][j] -= factor * aug[col][j]
    return [aug[i][n] for i in range(n)]


def _solubility_numerical_jacobian(
    func: Callable[[List[float]], List[float]],
    point: List[float],
    step_scale: float = 1e-6,
) -> List[List[float]]:
    """Perform solubility numerical jacobian.
    Used to keep the workflow logic localized and testable."""
    n = len(point)
    jacobian = [[0.0 for _ in range(n)] for _ in range(n)]
    # Iterate over the configured range to apply the per-item logic.
    for j in range(n):
        delta = step_scale * max(1.0, abs(point[j]))
        delta = max(delta, 1e-8)
        forward = point[:]
        backward = point[:]
        forward[j] += delta
        backward[j] -= delta
        fwd = func(forward)
        back = func(backward)
        # Iterate over the configured range to apply the per-item logic.
        for i in range(n):
            jacobian[i][j] = (fwd[i] - back[i]) / (2.0 * delta)
    return jacobian


def _solubility_newton_system_solve(
    func: Callable[[List[float]], List[float]],
    initial_guess: List[float],
    tol: float = 1e-12,
    max_iter: int = 60,
) -> List[float]:
    """Solve value.
    Used by solubility newton system workflows to solve value."""
    x = initial_guess[:]
    # Iterate over the configured range to apply the per-item logic.
    for _ in range(max_iter):
        residual = func(x)
        if not all(math.isfinite(val) for val in residual):
            raise RuntimeError("Non-finite residual encountered during solve.")
        if max(abs(val) for val in residual) < tol:
            return x
        jacobian = _solubility_numerical_jacobian(func, x)
        try:
            delta = _solubility_solve_linear_system(
                jacobian, [-val for val in residual]
            )
        except ValueError as exc:
            raise RuntimeError("Jacobian became singular.") from exc
        if not all(math.isfinite(val) for val in delta):
            raise RuntimeError("Non-finite Newton increment encountered.")
        x = [min(max(value + step, -25.0), 5.0) for value, step in zip(x, delta)]
        if max(abs(step) for step in delta) < tol:
            if max(abs(val) for val in func(x)) < tol:
                return x
    raise RuntimeError("Newton solver did not converge within the iteration limit.")


SPEC_MODE_FIXED_PCO2 = "fixed_pCO2"
SPEC_MODE_CLOSED = "closed_carbon"


def _normalize_speciation_mode(mode: Optional[str]) -> str:
    """Normalize speciation mode.
    Used to keep speciation mode consistent across workflows and persistence."""
    if mode == SPEC_MODE_CLOSED:
        return SPEC_MODE_CLOSED
    return SPEC_MODE_FIXED_PCO2


def _resolved_fixed_co2_boundary(
    params: SolubilityInputs,
) -> Tuple[float, List[str]]:
    """Perform resolved fixed CO2 boundary.
    Used to keep the workflow logic localized and testable."""
    notes: List[str] = []
    kh_value = params.headspace_kh_m_per_atm
    if kh_value is None or kh_value <= 0:
        kh_value = 0.033
        notes.append("Henry constant defaulted to 0.033 M/atm for CO2 dissolution.")
    pco2_value = params.headspace_pco2_atm
    if pco2_value is None or pco2_value <= 0:
        pco2_value = SOL_HEADSPACE_DEFAULT_PCO2_ATM
        notes.append(
            "No positive headspace pCO2 provided; using ambient 4.0e-4 atm as the fixed boundary."
        )
    return max(kh_value * pco2_value, 0.0), notes


def _solve_carbonate_state(
    total_carbon_m: float,
    na_conc: float,
    *,
    ka1: float,
    ka2: float,
    kw: float,
    ionic_strength_cap: Optional[float],
    initial_ph_guess: Optional[float],
    speciation_mode: Optional[str] = None,
    fixed_h2co3: Optional[float] = None,
    _prefer_rust: bool = True,
) -> Tuple[float, float, float, float, float, Dict[str, float], float]:
    """Solve carbonate equilibrium for closed and fixed-pCO2 workflows.

    Purpose:
        Solve the carbonate charge-balance system and return the species/state terms
        required by downstream solubility reporting.
    Why:
        Analysis and planning workflows can provide a blank initial pH guess, so the
        solver must sanitize seed values to avoid failing while building Newton seeds.
    Inputs:
        total_carbon_m (float): Total dissolved inorganic carbon basis (mol/L).
        na_conc (float): Sodium concentration basis (mol/L).
        ka1 (float): First dissociation constant for carbonic acid.
        ka2 (float): Second dissociation constant for carbonic acid.
        kw (float): Water autoionization constant.
        ionic_strength_cap (Optional[float]): Optional ionic strength cap for activity
            coefficient evaluation.
        initial_ph_guess (Optional[float]): Optional initial pH seed. Missing or
            non-finite values fall back to `DEFAULT_SOLUBILITY_INPUTS.initial_ph_guess`.
        speciation_mode (Optional[str]): Solver mode selector.
        fixed_h2co3 (Optional[float]): Optional fixed dissolved CO2 boundary for
            fixed-pCO2 mode.
        _prefer_rust (bool): Internal control that disables Rust routing when
            False so policy parity probes can evaluate the Python baseline.
    Outputs:
        Tuple[float, float, float, float, float, Dict[str, float], float]:
            H, HCO3-, CO3^2-, H2CO3, OH-, activity coefficients, ionic strength.
    Side Effects:
        None.
    Exceptions:
        Raises RuntimeError when Newton solve attempts do not converge.
    """

    total_carbon_m = max(total_carbon_m, 1e-16)
    na_conc = max(na_conc, 0.0)
    mode = _normalize_speciation_mode(speciation_mode)
    fixed_h2co3_value = max(fixed_h2co3 or 0.0, 0.0)
    use_fixed_pco2 = mode == SPEC_MODE_FIXED_PCO2
    guess_ph = float(DEFAULT_SOLUBILITY_INPUTS.initial_ph_guess)
    try:
        if initial_ph_guess is not None:
            candidate_guess = float(initial_ph_guess)
            if math.isfinite(candidate_guess):
                guess_ph = candidate_guess
    except Exception:
        guess_ph = float(DEFAULT_SOLUBILITY_INPUTS.initial_ph_guess)

    if _prefer_rust:
        rust_mode = _current_rust_backend_mode()
        use_rust = False
        if rust_mode == "auto":
            benchmark = _synthetic_speciation_carbonate_state_core_payload(
                speciation_mode=mode
            )
            use_rust = _resolve_rust_kernel_auto_policy(
                "speciation_carbonate_state_core",
                rust_runner=lambda: _rust_carbonate_state_core(
                    benchmark["total_carbon_m"],
                    benchmark["na_conc"],
                    ka1=benchmark["ka1"],
                    ka2=benchmark["ka2"],
                    kw=benchmark["kw"],
                    ionic_strength_cap=benchmark["ionic_strength_cap"],
                    initial_ph_guess=benchmark["initial_ph_guess"],
                    speciation_mode=benchmark["speciation_mode"],
                    fixed_h2co3=benchmark["fixed_h2co3"],
                ),
                python_runner=lambda: _solve_carbonate_state(
                    benchmark["total_carbon_m"],
                    benchmark["na_conc"],
                    ka1=benchmark["ka1"],
                    ka2=benchmark["ka2"],
                    kw=benchmark["kw"],
                    ionic_strength_cap=benchmark["ionic_strength_cap"],
                    initial_ph_guess=benchmark["initial_ph_guess"],
                    speciation_mode=benchmark["speciation_mode"],
                    fixed_h2co3=benchmark["fixed_h2co3"],
                    _prefer_rust=False,
                ),
                parity_checker=_rust_carbonate_state_core_parity,
            )
        elif rust_mode != "python":
            use_rust = True
        if use_rust:
            rust_result = _rust_carbonate_state_core(
                total_carbon_m,
                na_conc,
                ka1=ka1,
                ka2=ka2,
                kw=kw,
                ionic_strength_cap=ionic_strength_cap,
                initial_ph_guess=guess_ph,
                speciation_mode=mode,
                fixed_h2co3=fixed_h2co3_value,
            )
            if isinstance(rust_result, Mapping):
                gamma_map = (
                    rust_result.get("gammas")
                    if isinstance(rust_result.get("gammas"), Mapping)
                    else {}
                )
                return (
                    float(rust_result.get("h", 0.0)),
                    float(rust_result.get("hco3", 0.0)),
                    float(rust_result.get("co3", 0.0)),
                    float(rust_result.get("h2co3", 0.0)),
                    float(rust_result.get("oh", 0.0)),
                    {
                        "Na": float(gamma_map.get("Na", 1.0)),
                        "H": float(gamma_map.get("H", 1.0)),
                        "HCO3": float(gamma_map.get("HCO3", 1.0)),
                        "CO3": float(gamma_map.get("CO3", 1.0)),
                        "OH": float(gamma_map.get("OH", 1.0)),
                    },
                    float(rust_result.get("ionic_strength", 0.0)),
                )

    def build_log_vector_closed(
        pH: float, hco3_fraction: float, co3_fraction: float
    ) -> List[float]:
        """Build log vector closed.
        Used to assemble log vector closed during UI or plot setup."""
        H = 10.0 ** (-pH)
        hco3 = max(total_carbon_m * hco3_fraction, 1e-16)
        co3 = max(total_carbon_m * co3_fraction, 1e-16)
        remainder = total_carbon_m - (hco3 + co3)
        h2co3 = max(remainder if remainder > 0 else total_carbon_m * 1e-3, 1e-16)
        return [math.log10(H), math.log10(hco3), math.log10(co3), math.log10(h2co3)]

    def residuals_closed(log_vars: List[float]) -> List[float]:
        """Perform residuals closed.
        Used to keep the workflow logic localized and testable."""
        H = 10.0 ** log_vars[0]
        HCO3 = 10.0 ** log_vars[1]
        CO3 = 10.0 ** log_vars[2]
        H2CO3 = 10.0 ** log_vars[3]
        ionic_strength, gammas, OH = _solubility_ionic_state(
            na_conc,
            H,
            HCO3,
            CO3,
            kw_value=kw,
            ionic_strength_cap=ionic_strength_cap,
        )
        Ka1_actual = (gammas["H"] * gammas["HCO3"] * H * HCO3) / max(H2CO3, 1e-16)
        Ka2_actual = (gammas["H"] * gammas["CO3"] * H * CO3) / (gammas["HCO3"] * HCO3)
        eq1 = math.log10(Ka1_actual / ka1)
        eq2 = math.log10(Ka2_actual / ka2)
        eq3 = H2CO3 + HCO3 + CO3 - total_carbon_m
        eq4 = na_conc + H - HCO3 - 2.0 * CO3 - OH
        return [eq1, eq2, eq3, eq4]

    def build_log_vector_open(pH: float) -> List[float]:
        """Build log vector open.
        Used to assemble log vector open during UI or plot setup."""
        # Seed guesses from Henry's law boundary; CO2(aq) is fixed by pCO2 and KH.
        H = 10.0 ** (-pH)
        hco3_guess = max((ka1 * max(fixed_h2co3_value, 1e-16)) / max(H, 1e-16), 1e-16)
        co3_guess = max((ka2 * hco3_guess) / max(H, 1e-16), 1e-16)
        return [math.log10(H), math.log10(hco3_guess), math.log10(co3_guess)]

    def residuals_open(log_vars: List[float]) -> List[float]:
        """Open value.
        Used by residuals workflows to open value."""
        H = 10.0 ** log_vars[0]
        HCO3 = 10.0 ** log_vars[1]
        CO3 = 10.0 ** log_vars[2]
        ionic_strength, gammas, OH = _solubility_ionic_state(
            na_conc,
            H,
            HCO3,
            CO3,
            kw_value=kw,
            ionic_strength_cap=ionic_strength_cap,
        )
        Ka1_actual = (gammas["H"] * gammas["HCO3"] * H * HCO3) / max(
            fixed_h2co3_value, 1e-16
        )
        Ka2_actual = (gammas["H"] * gammas["CO3"] * H * CO3) / (gammas["HCO3"] * HCO3)
        eq1 = math.log10(Ka1_actual / ka1)
        eq2 = math.log10(Ka2_actual / ka2)
        # Charge balance (Na+ + H+) == (HCO3- + 2*CO3^2- + OH-)
        eq3 = na_conc + H - HCO3 - 2.0 * CO3 - OH
        return [eq1, eq2, eq3]

    solution: Optional[List[float]] = None
    if use_fixed_pco2:
        guess_ph_values = [
            guess_ph,
            8.2,
            7.8,
            9.0,
        ]
        # Iterate over guess_ph_values to apply the per-item logic.
        for pH_guess in guess_ph_values:
            try:
                solution = _solubility_newton_system_solve(
                    residuals_open, build_log_vector_open(pH_guess)
                )
                break
            except RuntimeError:
                continue
    else:
        guess_specs = [
            (guess_ph, 0.85, 0.12),
            (8.8, 0.80, 0.19),
            (7.5, 0.95, 0.03),
            (9.2, 0.70, 0.29),
        ]
        # Iterate over guess_specs to apply the per-item logic.
        for pH_guess, hco3_frac, co3_frac in guess_specs:
            try:
                solution = _solubility_newton_system_solve(
                    residuals_closed,
                    build_log_vector_closed(pH_guess, hco3_frac, co3_frac),
                )
                break
            except RuntimeError:
                continue
    if solution is None:
        raise RuntimeError(
            "Equilibrium solver did not converge. Try different inputs or adjust the initial pH guess."
        )

    if use_fixed_pco2:
        H = 10.0 ** solution[0]
        HCO3 = 10.0 ** solution[1]
        CO3 = 10.0 ** solution[2]
        H2CO3 = max(fixed_h2co3_value, 1e-16)
    else:
        H = 10.0 ** solution[0]
        HCO3 = 10.0 ** solution[1]
        CO3 = 10.0 ** solution[2]
        H2CO3 = 10.0 ** solution[3]
    ionic_strength, gammas, OH = _solubility_ionic_state(
        na_conc,
        H,
        HCO3,
        CO3,
        kw_value=kw,
        ionic_strength_cap=ionic_strength_cap,
    )
    return H, HCO3, CO3, H2CO3, OH, gammas, ionic_strength


def _solubility_speciation_for_inventory(
    params: SolubilityInputs,
    total_carbon: float,
    na_conc: float,
    constants: Tuple[float, float, float, List[str]],
    *,
    saturation_enforced: Optional[Sequence[str]] = None,
    speciation_mode: Optional[str] = None,
    fixed_h2co3: Optional[float] = None,
) -> SolubilitySpeciationResult:
    """Perform solubility speciation for inventory.
    Used to keep the workflow logic localized and testable."""
    ka1, ka2, kw, constant_notes = constants
    mode = _normalize_speciation_mode(
        speciation_mode or getattr(params, "speciation_mode", None)
    )
    fixed_h2co3_value = fixed_h2co3
    if mode == SPEC_MODE_FIXED_PCO2:
        boundary, notes = _resolved_fixed_co2_boundary(params)
        fixed_h2co3_value = boundary if fixed_h2co3_value is None else fixed_h2co3_value
        constant_notes = list(constant_notes) + notes
    (
        H,
        HCO3,
        CO3,
        H2CO3,
        OH,
        gammas,
        ionic_strength,
    ) = _solve_carbonate_state(
        total_carbon,
        na_conc,
        ka1=ka1,
        ka2=ka2,
        kw=kw,
        ionic_strength_cap=params.ionic_strength_cap,
        initial_ph_guess=params.initial_ph_guess,
        speciation_mode=mode,
        fixed_h2co3=fixed_h2co3_value,
    )
    volume = params.volume_l()
    ph = -math.log10(H)
    concentrations = {
        "Na+": na_conc,
        "H+": H,
        "HCO3-": HCO3,
        "CO3^2-": CO3,
        "H2CO3": H2CO3,
        "OH-": OH,
    }
    moles = {species: conc * volume for species, conc in concentrations.items()}
    activity_coeffs = {
        "Na+": gammas["Na"],
        "H+": gammas["H"],
        "HCO3-": gammas["HCO3"],
        "CO3^2-": gammas["CO3"],
        "OH-": gammas["OH"],
    }
    a_na = gammas["Na"] * na_conc
    a_hco3 = gammas["HCO3"] * HCO3
    a_co3 = gammas["CO3"] * CO3
    saturation_indices = {
        "NaHCO3": (a_na * a_hco3) / SOL_KSP_NAHCO3,
        "Na2CO3": (a_na**2 * a_co3) / SOL_KSP_NA2CO3,
    }
    ionic_strength_capped = (
        params.ionic_strength_cap is not None
        and ionic_strength >= params.ionic_strength_cap * 0.999
    )
    return _solubility_finalize_result(
        params=params,
        volume=volume,
        ionic_strength=ionic_strength,
        ph=ph,
        concentrations=concentrations,
        moles=moles,
        activity_coeffs=activity_coeffs,
        saturation_indices=saturation_indices,
        constant_notes=constant_notes,
        ionic_strength_capped=ionic_strength_capped,
        kw_value=kw,
        dissolved_na_moles=na_conc * volume,
        saturation_enforced=saturation_enforced,
        fixed_co2_boundary=fixed_h2co3_value if mode == SPEC_MODE_FIXED_PCO2 else None,
        speciation_mode=mode,
    )


def _solubility_within_saturation_limits(
    spec: SolubilitySpeciationResult, tol: float = SOL_SATURATION_TOL
) -> bool:
    """Perform solubility within saturation limits.
    Used to keep the workflow logic localized and testable."""
    return all(ratio <= 1.0 + tol for ratio in spec.saturation_indices.values())


def _solubility_apply_saturation_limits(
    params: SolubilityInputs,
    constants: Tuple[float, float, float, List[str]],
    sodium_conc: float,
    base_carbon_conc: float,
    headspace_conc: float,
    *,
    speciation_mode: Optional[str],
    fixed_h2co3: Optional[float],
) -> SolubilitySpeciationResult:
    """Apply saturation limits.
    Used by solubility workflows to apply saturation limits."""
    mode = _normalize_speciation_mode(
        speciation_mode or getattr(params, "speciation_mode", None)
    )
    base_total = (
        max(base_carbon_conc, 1e-12)
        if mode == SPEC_MODE_FIXED_PCO2
        else max(base_carbon_conc + headspace_conc, 1e-12)
    )
    equilibrium = _solubility_speciation_for_inventory(
        params,
        base_total,
        sodium_conc,
        constants,
        speciation_mode=mode,
        fixed_h2co3=fixed_h2co3,
    )
    limiters = [
        salt
        # Iterate to apply the per-item logic.
        for salt, ratio in equilibrium.saturation_indices.items()
        if ratio > 1.0 + SOL_SATURATION_TOL
    ]
    if not limiters:
        return equilibrium
    lo_frac = 0.0
    hi_frac = 1.0
    best_frac: Optional[float] = None
    # Iterate over the configured range to apply the per-item logic.
    for _ in range(48):
        mid = max((lo_frac + hi_frac) * 0.5, 1e-6)
        na_mid = sodium_conc * mid
        carbon_mid = (
            max(base_carbon_conc * mid, 1e-12)
            if mode == SPEC_MODE_FIXED_PCO2
            else max(base_carbon_conc * mid + headspace_conc, 1e-12)
        )
        candidate = _solubility_speciation_for_inventory(
            params,
            carbon_mid,
            na_mid,
            constants,
            speciation_mode=mode,
            fixed_h2co3=fixed_h2co3,
        )
        if _solubility_within_saturation_limits(candidate):
            best_frac = mid
            lo_frac = mid
        else:
            hi_frac = mid
    if best_frac is None:
        best_frac = max(hi_frac * 0.5, 1e-6)
    final_na = max(sodium_conc * best_frac, 1e-12)
    final_total = (
        max(base_carbon_conc * best_frac, 1e-12)
        if mode == SPEC_MODE_FIXED_PCO2
        else max(base_carbon_conc * best_frac + headspace_conc, 1e-12)
    )
    return _solubility_speciation_for_inventory(
        params,
        final_total,
        final_na,
        constants,
        speciation_mode=mode,
        fixed_h2co3=fixed_h2co3,
        saturation_enforced=limiters,
    )


def solubility_solve_speciation(
    params: SolubilityInputs,
    constants: Optional[Tuple[float, float, float, List[str]]] = None,
    math_logger: Optional[SolubilityMathLogger] = None,
    math_section: str = "Speciation",
    *,
    model_options: Optional[ModelOptions] = None,
) -> SolubilitySpeciationResult:
    """Solve speciation.
    Used by solubility workflows to solve speciation."""
    effective_params = params
    if model_options and model_options.override_ionic_strength_cap is not None:
        effective_params = replace(
            params, ionic_strength_cap=model_options.override_ionic_strength_cap
        )
    mode = _normalize_speciation_mode(
        getattr(effective_params, "speciation_mode", None)
    )
    sodium_conc = effective_params.sodium_concentration()
    if sodium_conc <= 0.0:
        raise ValueError("Computed dissolved sodium concentration must be positive.")
    base_carbon = effective_params.total_carbon_concentration()
    if base_carbon <= 0.0 and mode == SPEC_MODE_CLOSED:
        raise ValueError("Total inorganic carbon concentration must be positive.")
    headspace_conc = (
        effective_params.headspace_carbon_contribution()
        if mode == SPEC_MODE_CLOSED
        else 0.0
    )
    fixed_h2co3_value: Optional[float] = None
    if mode == SPEC_MODE_FIXED_PCO2:
        # Open-system assumption: dissolved CO2 is pinned by pCO2 via Henry's law.
        fixed_h2co3_value, _ = _resolved_fixed_co2_boundary(effective_params)
        fixed_h2co3_value = max(fixed_h2co3_value, 1e-16)
    if constants is None:
        constants = _resolve_solubility_constants(
            effective_params, math_logger=math_logger, section=math_section
        )
    result = _solubility_apply_saturation_limits(
        effective_params,
        constants,
        sodium_conc,
        base_carbon,
        headspace_conc,
        speciation_mode=mode,
        fixed_h2co3=fixed_h2co3_value,
    )
    _solubility_log_result_math(
        logger=math_logger,
        section=math_section,
        params=effective_params,
        result=result,
    )
    return result


def _python_forced_ph_distribution_core(
    total_carbon_m: float,
    na_conc: float,
    forced_ph: float,
    *,
    ka1: float,
    ka2: float,
    kw: float,
    ionic_strength_cap: Optional[float],
    fixed_h2co3: Optional[float],
    max_iter: int = 80,
) -> Dict[str, Any]:
    """Run the canonical Python forced-pH distribution iterative core.

    Purpose:
        Solve carbonate distribution terms at fixed pH for forced-pH workflows.
    Why:
        Rust auto-policy decisions require one stable Python baseline, and
        runtime fallback must remain authoritative on any extension failure.
    Inputs:
        total_carbon_m: Initial total inorganic carbon estimate (mol/L).
        na_conc: Total sodium concentration (mol/L).
        forced_ph: Forced pH target.
        ka1: First acid dissociation constant.
        ka2: Second acid dissociation constant.
        kw: Water autoionization constant.
        ionic_strength_cap: Optional ionic-strength cap.
        fixed_h2co3: Optional fixed dissolved CO2 boundary for fixed-pCO2 mode.
        max_iter: Iteration cap for charge-balance convergence.
    Outputs:
        Dict with converged carbonate species, activity coefficients, ionic
        strength, and charge-balance residual terms.
    Side Effects:
        None.
    Exceptions:
        Invalid intermediate values are guarded; the routine converges to the
        best stable estimate within `max_iter`.
    """
    total_carbon = max(float(total_carbon_m), 1e-12)
    na_total = max(float(na_conc), 0.0)
    H = 10.0 ** (-float(forced_ph))
    hco3 = total_carbon * 0.9
    co3 = total_carbon * 0.05
    h2co3 = max(total_carbon - hco3 - co3, 0.0)
    charge_residual = 0.0
    limit = max(int(max_iter), 1)

    # Iterate over the configured range to apply the per-item logic.
    for _ in range(limit):
        ionic_strength, gammas, OH = _solubility_ionic_state(
            na_total,
            H,
            hco3,
            co3,
            kw_value=kw,
            ionic_strength_cap=ionic_strength_cap,
        )
        coeff_co3 = (ka2 * gammas["HCO3"]) / (gammas["H"] * gammas["CO3"] * H)
        coeff_h2co3 = (gammas["H"] * gammas["HCO3"] * H) / ka1
        charge_basis = max(na_total + H - OH, 1e-16)
        hco3 = max(charge_basis / max(1.0 + (2.0 * coeff_co3), 1e-12), 1e-16)
        co3 = max(coeff_co3 * hco3, 1e-16)
        h2co3 = max(coeff_h2co3 * hco3, fixed_h2co3 or 0.0, 1e-16)
        total_carbon_from_species = max(h2co3 + hco3 + co3, 1e-16)
        charge_residual = na_total + H - hco3 - 2.0 * co3 - OH
        new_total_carbon = max(total_carbon_from_species, 1e-16)
        delta_ct = abs(new_total_carbon - total_carbon) / max(total_carbon, 1e-12)
        total_carbon = new_total_carbon
        if delta_ct < 1e-8 and abs(charge_residual) < 1e-8:
            break

    ionic_strength, gammas, OH = _solubility_ionic_state(
        na_total,
        H,
        hco3,
        co3,
        kw_value=kw,
        ionic_strength_cap=ionic_strength_cap,
    )
    coeff_co3 = (ka2 * gammas["HCO3"]) / (gammas["H"] * gammas["CO3"] * H)
    coeff_h2co3 = (gammas["H"] * gammas["HCO3"] * H) / ka1
    charge_basis = max(na_total + H - OH, 1e-16)
    hco3 = max(charge_basis / max(1.0 + (2.0 * coeff_co3), 1e-12), 1e-16)
    co3 = max(coeff_co3 * hco3, 1e-16)
    h2co3 = max(coeff_h2co3 * hco3, fixed_h2co3 or 0.0, 1e-16)
    total_carbon = max(h2co3 + hco3 + co3, 1e-16)
    charge_residual = na_total + H - hco3 - 2.0 * co3 - OH
    ionic_strength, gammas, OH = _solubility_ionic_state(
        na_total,
        H,
        hco3,
        co3,
        kw_value=kw,
        ionic_strength_cap=ionic_strength_cap,
    )
    charge_residual = na_total + H - hco3 - 2.0 * co3 - OH
    return {
        "total_carbon_m": float(total_carbon),
        "h": float(H),
        "hco3": float(hco3),
        "co3": float(co3),
        "h2co3": float(h2co3),
        "oh": float(OH),
        "charge_balance_residual": float(charge_residual),
        "ionic_strength": float(ionic_strength),
        "gammas": {
            "Na": float(gammas["Na"]),
            "H": float(gammas["H"]),
            "HCO3": float(gammas["HCO3"]),
            "CO3": float(gammas["CO3"]),
            "OH": float(gammas["OH"]),
        },
    }


def solubility_speciation_at_forced_ph(
    params: SolubilityInputs,
    forced_ph: float,
    constants: Optional[Tuple[float, float, float, List[str]]] = None,
    math_logger: Optional[SolubilityMathLogger] = None,
    math_section: str = "Forced pH Speciation",
    *,
    model_options: Optional[ModelOptions] = None,
) -> SolubilitySpeciationResult:
    """Perform solubility speciation at forced pH.
    Used to keep the workflow logic localized and testable."""
    if forced_ph <= 0 or forced_ph >= 14:
        raise ValueError("Forced pH must be between 0 and 14.")
    effective_params = (
        replace(params, ionic_strength_cap=model_options.override_ionic_strength_cap)
        if model_options and model_options.override_ionic_strength_cap is not None
        else params
    )
    mode = _normalize_speciation_mode(
        getattr(effective_params, "speciation_mode", None)
    )
    fixed_h2co3_value: Optional[float] = None
    boundary_notes: List[str] = []
    if mode == SPEC_MODE_FIXED_PCO2:
        fixed_h2co3_value, boundary_notes = _resolved_fixed_co2_boundary(
            effective_params
        )
        fixed_h2co3_value = max(fixed_h2co3_value, 1e-16)
    inventory_carbon = effective_params.carbon_inventory_concentration()
    total_carbon = max(inventory_carbon, fixed_h2co3_value or 1e-12)
    na_conc = effective_params.sodium_concentration()
    if constants is None:
        constants = _resolve_solubility_constants(
            effective_params, math_logger=math_logger, section=math_section
        )
    ka1, ka2, kw, constant_notes = constants
    if boundary_notes:
        constant_notes = list(constant_notes) + boundary_notes
    use_rust = False
    rust_mode = _current_rust_backend_mode()
    if rust_mode == "auto":
        benchmark = _synthetic_speciation_forced_ph_distribution_core_payload(
            fixed_h2co3=fixed_h2co3_value
        )
        use_rust = _resolve_rust_kernel_auto_policy(
            "speciation_forced_ph_distribution_core",
            rust_runner=lambda: _rust_forced_ph_distribution_core(
                benchmark["total_carbon_m"],
                benchmark["na_conc"],
                benchmark["forced_ph"],
                ka1=benchmark["ka1"],
                ka2=benchmark["ka2"],
                kw=benchmark["kw"],
                ionic_strength_cap=benchmark["ionic_strength_cap"],
                fixed_h2co3=benchmark["fixed_h2co3"],
                max_iter=benchmark["max_iter"],
            ),
            python_runner=lambda: _python_forced_ph_distribution_core(
                benchmark["total_carbon_m"],
                benchmark["na_conc"],
                benchmark["forced_ph"],
                ka1=benchmark["ka1"],
                ka2=benchmark["ka2"],
                kw=benchmark["kw"],
                ionic_strength_cap=benchmark["ionic_strength_cap"],
                fixed_h2co3=benchmark["fixed_h2co3"],
                max_iter=benchmark["max_iter"],
            ),
            parity_checker=_rust_forced_ph_distribution_core_parity,
        )
    elif rust_mode != "python":
        use_rust = True

    core_payload = (
        _rust_forced_ph_distribution_core(
            total_carbon,
            na_conc,
            forced_ph,
            ka1=ka1,
            ka2=ka2,
            kw=kw,
            ionic_strength_cap=effective_params.ionic_strength_cap,
            fixed_h2co3=fixed_h2co3_value,
            max_iter=80,
        )
        if use_rust
        else None
    )
    if not isinstance(core_payload, Mapping):
        core_payload = _python_forced_ph_distribution_core(
            total_carbon,
            na_conc,
            forced_ph,
            ka1=ka1,
            ka2=ka2,
            kw=kw,
            ionic_strength_cap=effective_params.ionic_strength_cap,
            fixed_h2co3=fixed_h2co3_value,
            max_iter=80,
        )
    total_carbon = float(core_payload.get("total_carbon_m", total_carbon))
    H = float(core_payload.get("h", 10.0 ** (-forced_ph)))
    hco3 = float(core_payload.get("hco3", 0.0))
    co3 = float(core_payload.get("co3", 0.0))
    h2co3 = float(core_payload.get("h2co3", 0.0))
    OH = float(core_payload.get("oh", 0.0))
    ionic_strength = float(core_payload.get("ionic_strength", 0.0))
    gammas = (
        core_payload.get("gammas")
        if isinstance(core_payload.get("gammas"), Mapping)
        else {}
    )
    volume = params.volume_l()

    concentrations = {
        "Na+": na_conc,
        "H+": H,
        "HCO3-": hco3,
        "CO3^2-": co3,
        "H2CO3": h2co3,
        "OH-": OH,
    }
    moles = {species: conc * volume for species, conc in concentrations.items()}
    activity_coeffs = {
        "Na+": gammas["Na"],
        "H+": gammas["H"],
        "HCO3-": gammas["HCO3"],
        "CO3^2-": gammas["CO3"],
        "OH-": gammas["OH"],
    }
    a_na = gammas["Na"] * na_conc
    a_hco3 = gammas["HCO3"] * hco3
    a_co3 = gammas["CO3"] * co3
    saturation_indices = {
        "NaHCO3": (a_na * a_hco3) / SOL_KSP_NAHCO3,
        "Na2CO3": (a_na**2 * a_co3) / SOL_KSP_NA2CO3,
    }
    ionic_strength_capped = (
        effective_params.ionic_strength_cap is not None
        and ionic_strength >= effective_params.ionic_strength_cap * 0.999
    )
    result = _solubility_finalize_result(
        params=effective_params,
        volume=volume,
        ionic_strength=ionic_strength,
        ph=forced_ph,
        concentrations=concentrations,
        moles=moles,
        activity_coeffs=activity_coeffs,
        saturation_indices=saturation_indices,
        constant_notes=constant_notes,
        ionic_strength_capped=ionic_strength_capped,
        kw_value=kw,
        dissolved_na_moles=na_conc * volume,
        fixed_co2_boundary=fixed_h2co3_value if mode == SPEC_MODE_FIXED_PCO2 else None,
        speciation_mode=mode,
    )
    return result


def solubility_speciation_calibrated_to_measurement(
    params: SolubilityInputs,
    measured_ph: float,
    *,
    measured_alkalinity_meq: Optional[float] = None,
    constants: Optional[Tuple[float, float, float, List[str]]] = None,
    math_logger: Optional[SolubilityMathLogger] = None,
    math_section: str = "Measurement-Calibrated Speciation",
    model_options: Optional[ModelOptions] = None,
) -> Tuple[SolubilitySpeciationResult, SolubilityInputs, float]:
    """Perform solubility speciation calibrated to measurement.
    Used to keep the workflow logic localized and testable."""

    if constants is None:
        constants = _resolve_solubility_constants(
            params, math_logger=math_logger, section=math_section
        )

    def _evaluate(scale: float) -> Tuple[SolubilitySpeciationResult, SolubilityInputs]:
        """Perform evaluate.
        Used to keep the workflow logic localized and testable."""
        retained = params._retained_carbon_fraction()
        scaled_retained = min(max(retained * scale, 1e-6), 5.0)
        scaled_degassed = 1.0 - scaled_retained
        scaled_params = replace(params, degassed_fraction=scaled_degassed)
        spec = solubility_speciation_at_forced_ph(
            scaled_params,
            measured_ph,
            constants=constants,
            math_logger=None,
            math_section=math_section,
            model_options=model_options,
        )
        return spec, scaled_params

    best_spec, best_params = _evaluate(1.0)
    best_scale = 1.0
    target_alk = measured_alkalinity_meq
    if target_alk is not None and target_alk > 0:
        target_alk = float(target_alk)
        low_scale, high_scale = 0.2, 5.0
        low_spec, low_params = _evaluate(low_scale)
        high_spec, high_params = _evaluate(high_scale)
        candidates = [
            (
                abs(best_spec.alkalinity_meq_per_l - target_alk),
                best_spec,
                best_params,
                1.0,
            ),
            (
                abs(low_spec.alkalinity_meq_per_l - target_alk),
                low_spec,
                low_params,
                low_scale,
            ),
            (
                abs(high_spec.alkalinity_meq_per_l - target_alk),
                high_spec,
                high_params,
                high_scale,
            ),
        ]
        best_diff, best_spec, best_params, best_scale = min(
            candidates, key=lambda entry: entry[0]
        )
        low_diff = low_spec.alkalinity_meq_per_l - target_alk
        high_diff = high_spec.alkalinity_meq_per_l - target_alk
        if low_diff == 0.0:
            best_spec, best_params, best_scale = low_spec, low_params, low_scale
        elif high_diff == 0.0:
            best_spec, best_params, best_scale = high_spec, high_params, high_scale
        elif low_diff * high_diff < 0:
            # Iterate over the configured range to apply the per-item logic.
            for _ in range(30):
                mid_scale = 0.5 * (low_scale + high_scale)
                mid_spec, mid_params = _evaluate(mid_scale)
                mid_diff = mid_spec.alkalinity_meq_per_l - target_alk
                if abs(mid_diff) < best_diff:
                    best_diff = abs(mid_diff)
                    best_spec, best_params, best_scale = mid_spec, mid_params, mid_scale
                if abs(mid_diff) < 0.05:
                    break
                if mid_diff > 0:
                    high_scale, high_diff = mid_scale, mid_diff
                else:
                    low_scale, low_diff = mid_scale, mid_diff
        if abs(low_diff) < best_diff:
            best_diff = abs(low_diff)
            best_spec, best_params, best_scale = low_spec, low_params, low_scale
        if abs(high_diff) < best_diff:
            best_spec, best_params, best_scale = high_spec, high_params, high_scale
    if math_logger:
        _solubility_log_result_math(
            logger=math_logger,
            section=math_section,
            params=best_params,
            result=best_spec,
        )
    return best_spec, best_params, best_scale


def _safe_rust_float(value: Any, fallback: float = 0.0) -> float:
    """Coerce a Rust payload numeric value to a finite float.

    Purpose:
        Normalize optional/loosely typed extension payload values.
    Why:
        Rust bridge results are validated at runtime before they are allowed to
        replace Python calculations.
    Inputs:
        value: Raw value from the Rust extension payload.
        fallback: Value returned when conversion fails or value is non-finite.
    Outputs:
        Finite float.
    Side Effects:
        None.
    Exceptions:
        Conversion failures are handled internally.
    """
    try:
        candidate = float(value)
    except Exception:
        return fallback
    return candidate if math.isfinite(candidate) else fallback


def _safe_rust_int(value: Any, fallback: int = -1) -> int:
    """Coerce a Rust payload numeric value to a safe integer.

    Purpose:
        Normalize integer-like payload values returned by Rust kernels.
    Why:
        Plot/cycle index payloads must be validated before they are trusted by
        UI update paths.
    Inputs:
        value: Raw value from the Rust extension payload.
        fallback: Value returned when conversion fails.
    Outputs:
        Integer value suitable for index validation.
    Side Effects:
        None.
    Exceptions:
        Conversion failures are handled internally.
    """
    try:
        return int(value)
    except Exception:
        return int(fallback)


def _rust_speciation_mode_token(mode: Optional[str]) -> str:
    """Normalize speciation mode text for Rust-core payload routing.

    Purpose:
        Bridge Python mode labels to Rust extension mode tokens.
    Why:
        Rust uses lowercase normalized mode names while Python keeps the legacy
        `fixed_pCO2` casing for UI/user-facing settings compatibility.
    Inputs:
        mode: Python-side speciation mode token.
    Outputs:
        Rust-compatible mode token.
    Side Effects:
        None.
    Exceptions:
        Invalid values are normalized to closed-carbon mode.
    """
    token = _normalize_speciation_mode(mode).strip().lower()
    return "fixed_pco2" if token == SPEC_MODE_FIXED_PCO2.lower() else "closed_carbon"


def _chemistry_float_close(
    left: Any,
    right: Any,
    *,
    rel_tol: float = 1e-5,
    abs_tol: float = 1e-9,
) -> bool:
    """Compare two chemistry numeric values with tolerant floating thresholds.

    Purpose:
        Provide one reusable comparator for Rust/Python chemistry parity checks.
    Why:
        Minor floating-point differences across implementations are expected and
        should not disable Rust auto-policy for equivalent outputs.
    Inputs:
        left: First candidate numeric value.
        right: Second candidate numeric value.
        rel_tol: Relative tolerance.
        abs_tol: Absolute tolerance.
    Outputs:
        True when both values are finite and within tolerance.
    Side Effects:
        None.
    Exceptions:
        Conversion failures return False.
    """
    try:
        left_val = float(left)
        right_val = float(right)
    except Exception:
        return False
    if not (math.isfinite(left_val) and math.isfinite(right_val)):
        return False
    return math.isclose(left_val, right_val, rel_tol=rel_tol, abs_tol=abs_tol)


def _chemistry_mapping_float_close(
    left: Mapping[str, Any],
    right: Mapping[str, Any],
    keys: Sequence[str],
    *,
    rel_tol: float = 1e-5,
    abs_tol: float = 1e-9,
) -> bool:
    """Compare selected numeric keys across two mapping payloads.

    Purpose:
        Provide key-scoped parity checks for chemistry mapping payloads.
    Why:
        Rust kernel wrappers return normalized dictionaries with multiple fields
        where only specific numeric keys should drive parity policy.
    Inputs:
        left: First mapping payload.
        right: Second mapping payload.
        keys: Keys to compare.
        rel_tol: Relative tolerance.
        abs_tol: Absolute tolerance.
    Outputs:
        True when all requested keys match within tolerance.
    Side Effects:
        None.
    Exceptions:
        Missing keys or invalid values return False.
    """
    if not isinstance(left, Mapping) or not isinstance(right, Mapping):
        return False
    for key in keys:
        if key not in left or key not in right:
            return False
        if not _chemistry_float_close(
            left.get(key), right.get(key), rel_tol=rel_tol, abs_tol=abs_tol
        ):
            return False
    return True


def _rust_carbonate_state_core_parity(
    rust_payload: Any,
    python_payload: Any,
) -> bool:
    """Validate parity between Rust carbonate-state payload and Python tuple output.

    Purpose:
        Gate Rust auto-policy for `_solve_carbonate_state` with tolerant chemistry
        comparisons across equivalent outputs.
    Why:
        Rust wrapper returns mapping payloads while Python returns tuple output.
    Inputs:
        rust_payload: Rust wrapper mapping payload.
        python_payload: Python `_solve_carbonate_state` tuple output.
    Outputs:
        True when key concentrations, ionic strength, and gammas match.
    Side Effects:
        None.
    Exceptions:
        Invalid payload shapes return False.
    """
    if not isinstance(rust_payload, Mapping):
        return False
    if not isinstance(python_payload, tuple) or len(python_payload) < 7:
        return False
    try:
        h, hco3, co3, h2co3, oh, gammas_py, ionic = python_payload
    except Exception:
        return False
    if not isinstance(gammas_py, Mapping):
        return False
    base_left = {
        "h": rust_payload.get("h"),
        "hco3": rust_payload.get("hco3"),
        "co3": rust_payload.get("co3"),
        "h2co3": rust_payload.get("h2co3"),
        "oh": rust_payload.get("oh"),
        "ionic_strength": rust_payload.get("ionic_strength"),
    }
    base_right = {
        "h": h,
        "hco3": hco3,
        "co3": co3,
        "h2co3": h2co3,
        "oh": oh,
        "ionic_strength": ionic,
    }
    if not _chemistry_mapping_float_close(
        base_left,
        base_right,
        ("h", "hco3", "co3", "h2co3", "oh", "ionic_strength"),
        rel_tol=5e-5,
        abs_tol=1e-9,
    ):
        return False
    gamma_left = (
        rust_payload.get("gammas")
        if isinstance(rust_payload.get("gammas"), Mapping)
        else {}
    )
    gamma_right = {
        "Na": gammas_py.get("Na"),
        "H": gammas_py.get("H"),
        "HCO3": gammas_py.get("HCO3"),
        "CO3": gammas_py.get("CO3"),
        "OH": gammas_py.get("OH"),
    }
    return _chemistry_mapping_float_close(
        gamma_left,
        gamma_right,
        ("Na", "H", "HCO3", "CO3", "OH"),
        rel_tol=2e-4,
        abs_tol=1e-8,
    )


