def _python_aqion_closed_speciation_core(
    total_inorganic_carbon_m: float,
    *,
    ka1: float,
    ka2: float,
    kw: float,
    ph_low: float = 2.0,
    ph_high: float = 12.5,
) -> Optional[Dict[str, Any]]:
    """Run the canonical Python Aqion closed-system core solver payload.

    Purpose:
        Provide the authoritative Python baseline for Aqion Rust auto-policy
        checks and fallback operation.
    Why:
        Rust policy logic compares against one deterministic Python payload.
    Inputs:
        total_inorganic_carbon_m: Total inorganic carbon concentration (mol/L).
        ka1: First acid dissociation constant.
        ka2: Second acid dissociation constant.
        kw: Water autoionization constant.
        ph_low: Lower pH bracket bound.
        ph_high: Upper pH bracket bound.
    Outputs:
        Optional mapping with pH, species, alpha fractions, and residual terms.
    Side Effects:
        None.
    Exceptions:
        Solver failures are handled internally and return None.
    """
    try:
        payload = solve_closed_carbonate_system(
            ClosedCarbonateInputs(
                total_inorganic_carbon_m=max(float(total_inorganic_carbon_m), 0.0),
                temperature_c=25.0,
                ka1=float(ka1),
                ka2=float(ka2),
                kw=float(kw),
            ),
            ph_bracket=(float(min(ph_low, ph_high)), float(max(ph_low, ph_high))),
            validate_quartic=True,
        )
    except Exception:
        return None
    species = payload.species_m if isinstance(payload.species_m, Mapping) else {}
    alpha = payload.alpha if isinstance(payload.alpha, Mapping) else {}
    return {
        "ph": float(payload.ph),
        "h_conc": float(payload.h_conc),
        "oh_conc": float(payload.oh_conc),
        "ionic_strength": float(payload.ionic_strength),
        "charge_balance_residual": float(payload.charge_balance_residual),
        "solver": str(payload.solver),
        "species_m": {
            "H+": float(species.get("H+", 0.0)),
            "H2CO3": float(species.get("H2CO3", 0.0)),
            "HCO3-": float(species.get("HCO3-", 0.0)),
            "CO3^2-": float(species.get("CO3^2-", 0.0)),
            "OH-": float(species.get("OH-", 0.0)),
        },
        "alpha": {
            "a0": float(alpha.get("a0", 0.0)),
            "a1": float(alpha.get("a1", 0.0)),
            "a2": float(alpha.get("a2", 0.0)),
        },
    }


def _rust_carbonate_state_core(
    total_carbon_m: float,
    na_conc: float,
    *,
    ka1: float,
    ka2: float,
    kw: float,
    ionic_strength_cap: Optional[float],
    initial_ph_guess: float,
    speciation_mode: Optional[str],
    fixed_h2co3: Optional[float],
) -> Optional[Dict[str, Any]]:
    """Attempt the Rust carbonate-state core solver and sanitize payload output.

    Purpose:
        Bridge `_solve_carbonate_state` to Rust while preserving strict Python
        fallback behavior on missing backend or malformed payloads.
    Why:
        Advanced speciation workflows repeatedly solve this core system and can
        benefit from native acceleration when parity is confirmed.
    Inputs:
        Mirrors `_solve_carbonate_state` scalar chemistry inputs.
    Outputs:
        Optional sanitized mapping payload for solver state terms.
    Side Effects:
        May update cached Rust import error state when runtime failures occur.
    Exceptions:
        Extension invocation and payload-validation failures are swallowed.
    """
    kernel_name = "speciation_carbonate_state_core"
    backend = _load_rust_backend()
    if backend is None:
        return None
    resolver = getattr(backend, "carbonate_state_core", None)
    if not callable(resolver):
        return None
    payload: Any = _run_rust_kernel_with_timeout(
        kernel_name,
        lambda: resolver(
            float(total_carbon_m),
            float(na_conc),
            float(ka1),
            float(ka2),
            float(kw),
            ionic_strength_cap,
            float(initial_ph_guess),
            _rust_speciation_mode_token(speciation_mode),
            fixed_h2co3,
        ),
    )
    if not isinstance(payload, Mapping):
        _mark_rust_kernel_session_unhealthy(
            kernel_name,
            reason="invalid_payload",
            details="non-mapping payload",
        )
        return None
    gammas_raw = payload.get("gammas")
    if not isinstance(gammas_raw, Mapping):
        _mark_rust_kernel_session_unhealthy(
            kernel_name,
            reason="invalid_payload",
            details="missing gammas mapping",
        )
        return None
    normalized = {
        "h": _safe_rust_float(payload.get("h"), float("nan")),
        "hco3": _safe_rust_float(payload.get("hco3"), float("nan")),
        "co3": _safe_rust_float(payload.get("co3"), float("nan")),
        "h2co3": _safe_rust_float(payload.get("h2co3"), float("nan")),
        "oh": _safe_rust_float(payload.get("oh"), float("nan")),
        "ionic_strength": _safe_rust_float(payload.get("ionic_strength"), float("nan")),
        "speciation_mode": str(payload.get("speciation_mode") or "").strip(),
        "gammas": {
            "Na": _safe_rust_float(gammas_raw.get("Na"), float("nan")),
            "H": _safe_rust_float(gammas_raw.get("H"), float("nan")),
            "HCO3": _safe_rust_float(gammas_raw.get("HCO3"), float("nan")),
            "CO3": _safe_rust_float(gammas_raw.get("CO3"), float("nan")),
            "OH": _safe_rust_float(gammas_raw.get("OH"), float("nan")),
        },
    }
    if any(
        (not math.isfinite(normalized[key]) or normalized[key] < 0.0)
        for key in ("h", "hco3", "co3", "h2co3", "oh", "ionic_strength")
    ):
        _mark_rust_kernel_session_unhealthy(
            kernel_name,
            reason="invalid_payload",
            details="non-finite or negative scalar payload values",
        )
        return None
    if any(
        (not math.isfinite(value) or value <= 0.0)
        for value in normalized["gammas"].values()
    ):
        _mark_rust_kernel_session_unhealthy(
            kernel_name,
            reason="invalid_payload",
            details="invalid activity coefficient payload values",
        )
        return None
    return normalized


