def _synthetic_pitzer_solve_total_carbon_core_payload(
    pitzer_params: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    """Return deterministic NaOH-CO2 Pitzer benchmark payload for auto policy.

    Purpose:
        Provide stable benchmark inputs for Pitzer Rust kernel policy probes.
    Why:
        Policy checks should be independent of runtime planning-cycle values.
    Inputs:
        pitzer_params: Optional compact Pitzer numeric map.
    Outputs:
        Dict payload compatible with `_rust_pitzer_solve_total_carbon_core`.
    Side Effects:
        None.
    Exceptions:
        None.
    """
    default_params = {
        "b0_na_oh": 0.0864,
        "b1_na_oh": 0.253,
        "c0_na_oh": 0.0044,
        "b0_na_hco3": 0.028,
        "b1_na_hco3": 0.0,
        "c0_na_hco3": 0.0,
        "b0_na_co3": 0.0399,
        "b1_na_co3": 1.389,
        "c0_na_co3": 0.0044,
        "theta_co3_oh": -0.1,
        "psi_co3_na_oh": 0.0,
        "psi_co3_hco3_na": 0.0,
    }
    compact = dict(default_params)
