def _python_cycle_timeline_normalize_core(
    timeline_rows: Sequence[Mapping[str, Any]],
) -> List[Dict[str, Any]]:
    """Normalize cycle-timeline rows for responsive table/callout rendering.

    Purpose:
        Build one deterministic, renderer-friendly row schema from mixed timeline
        payload shapes generated by different workflow/model paths.
    Why:
        Timeline rendering now runs staged/chunked updates and requires a stable
        per-row schema for both Rust and Python execution paths.
    Inputs:
        timeline_rows: Raw cycle timeline rows from simulation output.
    Outputs:
        List[Dict[str, Any]]: Normalized cycle rows preserving passthrough fields
        while coercing key display/plot fields to finite scalar values.
    Side Effects:
        None.
    Exceptions:
        Invalid rows are skipped; invalid field values are normalized to safe
        defaults.
    """

    def _value_from_keys(
        row_map: Mapping[str, Any],
        keys: Sequence[str],
        *,
        default: Optional[float] = None,
    ) -> Optional[float]:
        """Resolve the first finite numeric field from a candidate key sequence."""
        for key in keys:
            value = _safe_float(row_map.get(key))
            if value is not None and math.isfinite(value):
                return float(value)
        return default

    normalized_rows: List[Dict[str, Any]] = []
    for idx, entry in enumerate(timeline_rows or (), start=1):
        if not isinstance(entry, Mapping):
            continue
        row = dict(entry)
        cycle_id = row.get("cycle_id")
        try:
            cycle_id = int(float(cycle_id))
        except Exception:
            cycle_id = idx
        if cycle_id <= 0:
            cycle_id = idx
        co2_total_g = _value_from_keys(
            row,
            ("co2_g", "co2_mass_g", "cumulative_co2_added_mass_g"),
            default=0.0,
        )
        co2_cycle_g = _value_from_keys(
            row,
            ("co2_mass_g", "cycle_co2_mass_g", "selected_mass_g"),
            default=0.0,
        )
        equilibrium_ph_value = _value_from_keys(
            row,
            ("equilibrium_ph", "ph", "actual_ph", "solution_ph", "speciation_ph"),
        )
        raw_calculated_ph = _value_from_keys(
            row,
            (
                "calculated_ph",
                "calculated_ph_raw_co2",
                "planning_co2_aligned_ph",
                "equilibrium_ph",
                "ph",
            ),
        )
        corrected_calculated_ph = _value_from_keys(
            row,
            ("calculated_ph_corrected_co2",),
        )
        calculated_delta = _value_from_keys(
            row,
            ("calculated_ph_corrected_minus_raw_delta",),
        )
        if (
            calculated_delta is None
            and raw_calculated_ph is not None
            and corrected_calculated_ph is not None
        ):
            calculated_delta = corrected_calculated_ph - raw_calculated_ph
        fractions = row.get("fractions")
        fractions_map = dict(fractions) if isinstance(fractions, Mapping) else {}

        def _fraction_value(key: str) -> float:
            """Return one normalized carbonate fraction as a bounded scalar."""
            frac = _safe_float(fractions_map.get(key), 0.0)
            if frac is None or not math.isfinite(frac):
                return 0.0
            if frac > 1.0:
                frac /= 100.0
            return max(0.0, float(frac))

        warnings: List[str] = []
        raw_warnings = row.get("warnings")
        if isinstance(raw_warnings, Sequence) and not isinstance(
            raw_warnings, (str, bytes, bytearray)
        ):
            warnings = [str(item).strip() for item in raw_warnings if str(item).strip()]
        elif isinstance(raw_warnings, str) and raw_warnings.strip():
            warnings = [raw_warnings.strip()]
        prediction = row.get("analysis_prediction")
        prediction_map = dict(prediction) if isinstance(prediction, Mapping) else {}
        row.update(
            {
                "cycle_id": int(cycle_id),
                "co2_g": float(co2_total_g or 0.0),
                "co2_mass_g": float(co2_cycle_g or 0.0),
                "co2_to_target_g": _value_from_keys(
                    row,
                    ("co2_to_target_g",),
                ),
                "equilibrium_ph": equilibrium_ph_value,
                "ph": equilibrium_ph_value,
                "final_ph": equilibrium_ph_value,
                "final_pH": equilibrium_ph_value,
                "actual_ph": _value_from_keys(
                    row, ("actual_ph", "equilibrium_ph", "ph")
                ),
                "solution_ph": _value_from_keys(
                    row,
                    ("equilibrium_ph", "solution_ph", "ph", "actual_ph"),
                ),
                "speciation_ph": _value_from_keys(
                    row,
                    ("equilibrium_ph", "speciation_ph", "solution_ph", "ph"),
                ),
                "forecast_ph": _value_from_keys(row, ("forecast_ph",)),
                "pco2_atm": _value_from_keys(row, ("pco2_atm",)),
                "planning_cycle_ph": _value_from_keys(row, ("planning_cycle_ph",)),
                "planning_co2_aligned_ph": _value_from_keys(
                    row, ("planning_co2_aligned_ph",)
                ),
                "calculated_ph": _value_from_keys(
                    row,
                    (
                        "calculated_ph",
                        "calculated_ph_raw_co2",
                        "equilibrium_ph",
                        "ph",
                    ),
                ),
                "calculated_ph_raw_co2": raw_calculated_ph,
                "calculated_ph_corrected_co2": corrected_calculated_ph,
                "calculated_ph_corrected_minus_raw_delta": calculated_delta,
                "ph_delta_cycle": _value_from_keys(row, ("ph_delta_cycle",)),
                "ph_delta_co2": _value_from_keys(row, ("ph_delta_co2",)),
                "actual_cycle_co2_mol": _value_from_keys(
                    row,
                    ("actual_cycle_co2_mol", "co2_moles"),
                ),
                "planning_cycle_co2_mol": _value_from_keys(
                    row, ("planning_cycle_co2_mol",)
                ),
                "co2_mol_delta": _value_from_keys(row, ("co2_mol_delta",)),
                "co2_mol_delta_pct": _value_from_keys(row, ("co2_mol_delta_pct",)),
                "actual_hco3_pct": _value_from_keys(row, ("actual_hco3_pct",)),
                "actual_co3_pct": _value_from_keys(row, ("actual_co3_pct",)),
                "planning_hco3_pct": _value_from_keys(row, ("planning_hco3_pct",)),
                "planning_co3_pct": _value_from_keys(row, ("planning_co3_pct",)),
                "hco3_pct_delta": _value_from_keys(row, ("hco3_pct_delta",)),
                "co3_pct_delta": _value_from_keys(row, ("co3_pct_delta",)),
                "solid_na2co3_g": float(
                    _value_from_keys(row, ("solid_na2co3_g",), default=0.0) or 0.0
                ),
                "solid_nahco3_g": float(
                    _value_from_keys(row, ("solid_nahco3_g",), default=0.0) or 0.0
                ),
                "delta_pressure_psi": _value_from_keys(row, ("delta_pressure_psi",)),
                "co2_moles": _value_from_keys(row, ("co2_moles",)),
                "peak_pressure_psi": _value_from_keys(row, ("peak_pressure_psi",)),
                "trough_pressure_psi": _value_from_keys(row, ("trough_pressure_psi",)),
                "headspace_pressure_psi": _value_from_keys(
                    row, ("headspace_pressure_psi",)
                ),
                "alignment_quality_flag": str(
                    row.get("alignment_quality_flag") or ""
                ).strip(),
                "fractions": {
                    "H2CO3": _fraction_value("H2CO3"),
                    "HCO3-": _fraction_value("HCO3-"),
                    "CO3^2-": _fraction_value("CO3^2-"),
                },
                "ph_source": (
                    "equilibrium_guidance"
                    if equilibrium_ph_value is not None
                    and math.isfinite(equilibrium_ph_value)
                    else str(row.get("ph_source") or "").strip()
                ),
                "warnings": warnings,
                "analysis_prediction": {
                    "target_ph": _value_from_keys(prediction_map, ("target_ph",)),
                    "co2_to_target_g": _value_from_keys(
                        prediction_map, ("co2_to_target_g",)
                    ),
                },
                "error": bool(row.get("error")),
            }
        )
        normalized_rows.append(row)
    return normalized_rows


def _rust_cycle_timeline_normalize_core(
    timeline_rows: Sequence[Mapping[str, Any]],
) -> Optional[List[Dict[str, Any]]]:
    """Attempt Rust timeline-row normalization with timeout and payload guards.

    Purpose:
        Offload cycle-timeline row normalization to the Rust extension when
        available and healthy.
    Why:
        Large timeline payloads can make repeated Python normalization and string
        preparation a hot path during workflow rendering.
    Inputs:
        timeline_rows: Raw cycle timeline payload sequence.
    Outputs:
        Optional normalized row list; None triggers Python fallback.
    Side Effects:
        May mark Rust kernel session health as unhealthy for invalid payloads.
    Exceptions:
        Backend invocation and validation failures are swallowed.
    """
    kernel_name = "cycle_timeline_normalize_core"
    backend = _load_rust_backend()
    if backend is None:
        return None
    resolver = getattr(backend, "cycle_timeline_normalize_core", None)
    if not callable(resolver):
        _mark_rust_kernel_session_unhealthy(
            kernel_name,
            reason="missing_symbol",
            details="cycle_timeline_normalize_core export missing from Rust module.",
        )
        return None
    payload_rows = [dict(row) for row in (timeline_rows or ()) if isinstance(row, Mapping)]
    payload: Any = _run_rust_kernel_with_timeout(
        kernel_name,
        lambda: resolver(payload_rows),
    )
    if not isinstance(payload, Sequence):
        _mark_rust_kernel_session_unhealthy(
            kernel_name,
            reason="invalid_payload",
            details="non-sequence payload",
        )
        return None
    normalized_rows = _python_cycle_timeline_normalize_core(payload)
    if payload_rows and len(normalized_rows) != len(payload_rows):
        _mark_rust_kernel_session_unhealthy(
            kernel_name,
            reason="invalid_payload",
            details="row_count mismatch",
        )
        return None
    return normalized_rows


def _rust_cycle_timeline_normalize_core_parity(
    rust_payload: Any,
    python_payload: Any,
) -> bool:
    """Validate parity between Rust and Python timeline-normalization payloads.

    Purpose:
        Gate auto-policy routing for the timeline-normalization kernel.
    Why:
        Rust should only be auto-enabled when normalized timeline values remain
        compatible with Python fallback semantics.
    Inputs:
        rust_payload: Rust-normalized row payload candidate.
        python_payload: Python-normalized row payload candidate.
    Outputs:
        True when key row/value fields match within tolerance.
    Side Effects:
        None.
    Exceptions:
        Invalid payload shapes return False.
    """
    if not isinstance(rust_payload, Sequence) or not isinstance(python_payload, Sequence):
        return False
    if len(rust_payload) != len(python_payload):
        return False
    for left_row, right_row in zip(rust_payload, python_payload):
        if not isinstance(left_row, Mapping) or not isinstance(right_row, Mapping):
            return False
        if _safe_rust_int(left_row.get("cycle_id"), -1) != _safe_rust_int(
            right_row.get("cycle_id"), -1
        ):
            return False
        for key in (
            "co2_g",
            "co2_mass_g",
            "ph",
            "planning_cycle_ph",
            "planning_co2_aligned_ph",
            "calculated_ph",
            "calculated_ph_raw_co2",
            "calculated_ph_corrected_co2",
            "calculated_ph_corrected_minus_raw_delta",
            "ph_delta_cycle",
            "ph_delta_co2",
            "actual_cycle_co2_mol",
            "planning_cycle_co2_mol",
            "co2_mol_delta",
            "co2_mol_delta_pct",
            "solid_na2co3_g",
            "solid_nahco3_g",
        ):
            left_val = _safe_float(left_row.get(key))
            right_val = _safe_float(right_row.get(key))
            if left_val is None or right_val is None:
                if left_val is not None or right_val is not None:
                    return False
                continue
            if not _chemistry_float_close(left_val, right_val, rel_tol=5e-5, abs_tol=1e-8):
                return False
        left_fractions = left_row.get("fractions")
        right_fractions = right_row.get("fractions")
        if not isinstance(left_fractions, Mapping) or not isinstance(
            right_fractions, Mapping
        ):
            return False
        for key in ("H2CO3", "HCO3-", "CO3^2-"):
            left_val = _safe_float(left_fractions.get(key), 0.0)
            right_val = _safe_float(right_fractions.get(key), 0.0)
            if not _chemistry_float_close(
                float(left_val or 0.0),
                float(right_val or 0.0),
                rel_tol=5e-5,
                abs_tol=1e-8,
            ):
                return False
        left_warnings = left_row.get("warnings") or []
        right_warnings = right_row.get("warnings") or []
        if [str(item) for item in left_warnings] != [str(item) for item in right_warnings]:
            return False
    return True


