def _normalize_cycle_timeline_for_render(
    timeline_rows: Sequence[Mapping[str, Any]],
) -> List[Dict[str, Any]]:
    """Normalize timeline rows with Rust auto-policy + Python fallback routing.

    Purpose:
        Provide one normalized cycle-row list for responsive timeline rendering.
    Why:
        Render staging and chunked UI updates need a stable row schema while
        preserving Rust acceleration when healthy and parity-safe.
    Inputs:
        timeline_rows: Raw cycle timeline rows.
    Outputs:
        List of normalized timeline rows.
    Side Effects:
        May update Rust kernel auto-policy/session-health caches.
    Exceptions:
        Any Rust execution failures fail closed to Python normalization.
    """
    payload_rows = [dict(row) for row in (timeline_rows or ()) if isinstance(row, Mapping)]
    if not payload_rows:
        return []
    rust_mode = _current_rust_backend_mode()
    use_rust = False
    if rust_mode == "auto":
        benchmark_rows = _synthetic_cycle_timeline_normalize_payload()
        use_rust = _resolve_rust_kernel_auto_policy(
            "cycle_timeline_normalize_core",
            rust_runner=lambda: _rust_cycle_timeline_normalize_core(benchmark_rows),
            python_runner=lambda: _python_cycle_timeline_normalize_core(benchmark_rows),
            parity_checker=_rust_cycle_timeline_normalize_core_parity,
        )
    elif rust_mode != "python":
        use_rust = True
    normalized_rows = (
        _rust_cycle_timeline_normalize_core(payload_rows) if use_rust else None
    )
    if not isinstance(normalized_rows, Sequence):
        normalized_rows = _python_cycle_timeline_normalize_core(payload_rows)
    elif use_rust:
        normalized_list = [
            dict(row) for row in normalized_rows if isinstance(row, Mapping)
        ]
        for original_row, normalized_row in zip(payload_rows, normalized_list):
            original_calculated = _safe_float(original_row.get("calculated_ph"))
            normalized_calculated = _safe_float(normalized_row.get("calculated_ph"))
            normalized_raw_trace = _safe_float(
                normalized_row.get("calculated_ph_raw_co2")
            )
            if original_calculated is None:
                continue
            if (
                normalized_calculated is None
                or normalized_raw_trace is None
                or not _chemistry_float_close(
                    original_calculated,
                    normalized_raw_trace,
                    rel_tol=5e-5,
                    abs_tol=1e-8,
                )
            ):
                normalized_rows = _python_cycle_timeline_normalize_core(payload_rows)
                break
    return [dict(row) for row in normalized_rows if isinstance(row, Mapping)]


def _python_ledger_sort_filter_indices_core(
    entries: Sequence[Mapping[str, Any]],
    *,
    filter_value: str,
    sort_mode: str,
    sort_key: str,
    sort_desc: bool,
    sort_column_type: str,
) -> Optional[List[int]]:
    """Return Ledger row indices after canonical filter/sort preparation.

    Purpose:
        Provide deterministic Python ordering for Ledger filter/sort operations.
    Why:
        Rust auto-policy parity checks and fallback routing need one stable
        reference implementation for index preparation.
    Inputs:
        entries: Ledger row payloads in source cache order.
        filter_value: Active profile filter token (`All Profiles` or profile name).
        sort_mode: Sort mode token (`manual` or `column`).
        sort_key: Active sort column key.
        sort_desc: True for descending order.
        sort_column_type: Normalized type for `sort_key`.
    Outputs:
        Optional list of source-row indices in filtered/sorted order.
    Side Effects:
        None.
    Exceptions:
        Unsupported formula sort returns None to trigger non-core fallback logic.
    """
    indexed_rows: List[Tuple[int, Mapping[str, Any]]] = [
        (idx, row) for idx, row in enumerate(entries or ()) if isinstance(row, Mapping)
    ]
    filter_token = str(filter_value or "").strip()
    if filter_token and filter_token != "All Profiles":
        filter_lower = filter_token.lower()
        indexed_rows = [
            (idx, row)
            for idx, row in indexed_rows
            if str(row.get("profile_name") or "").strip().lower() == filter_lower
        ]

    mode_token = str(sort_mode or "").strip().lower()
    if mode_token not in {"manual", "column"}:
        mode_token = "manual"
    if mode_token == "manual":
        indexed_rows.sort(
            key=lambda item: (
                int(item[1].get("display_order", 0) or 0),
                str(item[1].get("updated_at") or ""),
                str(item[1].get("id") or ""),
            )
        )
        return [idx for idx, _row in indexed_rows]

    normalized_col_type = str(sort_column_type or "").strip().lower()
    if normalized_col_type == "formula":
        return None
    normalized_sort_key = str(sort_key or "").strip() or "updated_at"

    def _column_raw_value(row: Mapping[str, Any]) -> Any:
        """Resolve one row value for built-in or custom sort keys."""
        if normalized_sort_key in set(LEDGER_TABLE_COLUMNS):
            return row.get(normalized_sort_key)
        custom_values = row.get("custom_values")
        custom_map = custom_values if isinstance(custom_values, Mapping) else {}
        return custom_map.get(normalized_sort_key)

    def _sort_tuple(row: Mapping[str, Any]) -> Tuple[int, Any]:
        """Build deterministic sort tuple for one Ledger row payload."""
        raw_value = _column_raw_value(row)
        if normalized_col_type == "number":
            if raw_value in (None, ""):
                return (1, 0.0)
            try:
                numeric_value = float(raw_value)
            except Exception:
                return (1, 0.0)
            if not math.isfinite(numeric_value):
                return (1, 0.0)
            return (0, float(numeric_value))
        if normalized_col_type == "date":
            text = str(raw_value or "").strip()
            if not text:
                return (1, 0.0)
            try:
                return (0, float(datetime.fromisoformat(text).timestamp()))
            except Exception:
                return (1, 0.0)
        return (0, str(raw_value or "").strip().lower())

    indexed_rows.sort(
        key=lambda item: _sort_tuple(item[1]),
        reverse=bool(sort_desc),
    )
    return [idx for idx, _row in indexed_rows]


