def _rust_ledger_sort_filter_indices_core(
    entries: Sequence[Mapping[str, Any]],
    *,
    filter_value: str,
    sort_mode: str,
    sort_key: str,
    sort_desc: bool,
    sort_column_type: str,
) -> Optional[List[int]]:
    """Attempt Rust Ledger filter/sort index preparation.

    Purpose:
        Offload Ledger filter/sort key/index preparation for table refresh flows.
    Why:
        Large Ledger tables repeatedly evaluate filter/sort tuples on UI refresh.
    Inputs:
        Mirrors `_python_ledger_sort_filter_indices_core` scalar parameters.
    Outputs:
        Optional list of source-row indices, or None for Python fallback.
    Side Effects:
        May update cached Rust import error state on backend failures.
    Exceptions:
        Backend invocation and payload validation failures are swallowed.
    """
    backend = _load_rust_backend()
    if backend is None:
        return None
    resolver = getattr(backend, "ledger_sort_filter_indices_core", None)
    if not callable(resolver):
        return None
    payload_rows: List[Dict[str, Any]] = []
    for row in entries or ():
        if not isinstance(row, Mapping):
            continue
        payload = dict(row)
        custom_values = payload.get("custom_values")
        payload["custom_values"] = (
            dict(custom_values) if isinstance(custom_values, Mapping) else {}
        )
        payload_rows.append(payload)
    payload: Any = None
    try:
        payload = resolver(
            payload_rows,
            str(filter_value or ""),
            str(sort_mode or ""),
            str(sort_key or ""),
            bool(sort_desc),
            str(sort_column_type or ""),
        )
    except Exception as exc:
        global _RUST_BACKEND_IMPORT_ERROR
        _RUST_BACKEND_IMPORT_ERROR = exc
        return None
    if not isinstance(payload, Sequence):
        return None
    max_index = int(len(payload_rows))
    indices: List[int] = []
    for raw in payload:
        idx = _safe_rust_int(raw, -1)
        if idx < 0 or idx >= max_index:
            return None
        indices.append(int(idx))
    if len(set(indices)) != len(indices):
        return None
    return indices


def _python_ledger_prefill_metrics_core(
    cycle_rows: Sequence[Mapping[str, Any]],
    *,
    total_drop_value: Optional[float],
    reaction_basis: Mapping[str, Any],
) -> Dict[str, Any]:
    """Compute Ledger add-from-profile metric prefill payload in Python.

    Purpose:
        Build cycle-count/uptake/theoretical defaults used by Ledger prefill.
    Why:
        Rust policy parity and fail-closed fallback need one canonical baseline.
    Inputs:
        cycle_rows: Sequence of cycle-transfer style row mappings.
        total_drop_value: Optional precomputed total uptake value.
        reaction_basis: Basis mapping with starting-mass/MW/stoich/gas-MW fields.
    Outputs:
        Dict containing `cycles`, `total_dp_uptake`, `theoretical_yield_g`.
    Side Effects:
        None.
    Exceptions:
        Invalid values are normalized to `None`.
    """

    def _opt_nonneg_float(raw_value: Any) -> Optional[float]:
        """Parse one optional finite non-negative float from mixed payload fields."""
        if raw_value in (None, ""):
            return None
        try:
            candidate = float(raw_value)
        except Exception:
            return None
        if not math.isfinite(candidate) or candidate < 0.0:
            return None
        return float(candidate)

    def _cycle_cumulative_mass_value(row: Mapping[str, Any]) -> Optional[float]:
        """Extract one cumulative uptake mass from cycle-transfer field variants."""
        for key in (
            "cumulative_co2_mass_g",
            "cumulative_co2_added_mass_g",
            "cumulative_co2_added_g",
            "cumulative_co2_g",
            "cumulative_added_g",
            "cumulative_mass_g",
        ):
            value = _opt_nonneg_float(row.get(key))
            if value is not None:
                return float(value)
        return None

    normalized_rows = [dict(row) for row in cycle_rows or () if isinstance(row, Mapping)]
    total_drop = _opt_nonneg_float(total_drop_value)
    if total_drop is None and normalized_rows:
        total_drop = _cycle_cumulative_mass_value(normalized_rows[-1])
    theoretical = compute_theoretical_product_yield_g(
        _normalize_reaction_basis_payload(reaction_basis)
    )
    return {
        "cycles": int(len(normalized_rows)) if normalized_rows else None,
        "total_dp_uptake": total_drop,
        "theoretical_yield_g": theoretical,
    }


