def _rust_ledger_prefill_metrics_core(
    cycle_rows: Sequence[Mapping[str, Any]],
    *,
    total_drop_value: Optional[float],
    reaction_basis: Mapping[str, Any],
) -> Optional[Dict[str, Any]]:
    """Attempt Rust Ledger prefill metric extraction.

    Purpose:
        Offload cycle/uptake/theoretical prefill metric shaping for Ledger add.
    Why:
        Profile bundle prefill can be repeatedly executed during ledger workflows.
    Inputs:
        Mirrors `_python_ledger_prefill_metrics_core` payloads.
    Outputs:
        Optional metrics mapping, or None when Python fallback is required.
    Side Effects:
        May update cached Rust import error state on backend failures.
    Exceptions:
        Backend invocation and payload validation failures are swallowed.
    """
    backend = _load_rust_backend()
    if backend is None:
        return None
    resolver = getattr(backend, "ledger_prefill_metrics_core", None)
    if not callable(resolver):
        return None
    payload_rows = [dict(row) for row in cycle_rows or () if isinstance(row, Mapping)]
    payload_basis = dict(reaction_basis) if isinstance(reaction_basis, Mapping) else {}
    payload: Any = None
    try:
        payload = resolver(payload_rows, total_drop_value, payload_basis)
    except Exception as exc:
        global _RUST_BACKEND_IMPORT_ERROR
        _RUST_BACKEND_IMPORT_ERROR = exc
        return None
    if not isinstance(payload, Mapping):
        return None
    cycles_value = payload.get("cycles")
    if cycles_value in (None, ""):
        cycles = None
    else:
        cycles = _safe_rust_int(cycles_value, -1)
        if cycles < 0:
            return None
        cycles = int(cycles)
    total_drop = payload.get("total_dp_uptake")
    if total_drop in (None, ""):
        total_drop_clean = None
    else:
        total_drop_clean = _safe_rust_float(total_drop, float("nan"))
        if not math.isfinite(total_drop_clean) or total_drop_clean < 0.0:
            return None
        total_drop_clean = float(total_drop_clean)
    theoretical = payload.get("theoretical_yield_g")
    if theoretical in (None, ""):
        theoretical_clean = None
    else:
        theoretical_clean = _safe_rust_float(theoretical, float("nan"))
        if not math.isfinite(theoretical_clean) or theoretical_clean < 0.0:
            return None
        theoretical_clean = float(theoretical_clean)
    return {
        "cycles": cycles,
        "total_dp_uptake": total_drop_clean,
        "theoretical_yield_g": theoretical_clean,
    }


