def _python_array_signature_core(array: Any) -> Optional[Tuple[int, str, int]]:
    """Return the Python fallback signature tuple for one ndarray payload.

    Purpose:
        Build a deterministic shape/dtype/content signature for plot refresh data.
    Why:
        Rust array-signature acceleration in v4.5.6 must preserve strict parity
        with a Python implementation when Rust is unavailable or invalid.
    Inputs:
        array: Candidate array-like payload to normalize and fingerprint.
    Outputs:
        Optional tuple `(size, dtype, content_hash)`, or None on conversion failure.
    Side Effects:
        None.
    Exceptions:
        Conversion/fingerprint failures are handled internally.
    """
    try:
        np_array = np.asarray(array)
    except Exception:
        return None
    try:
        contiguous = np.ascontiguousarray(np_array)
        payload_bytes = contiguous.tobytes()
        return (
            int(contiguous.size),
            str(contiguous.dtype),
            _stable_signature_hash_bytes(payload_bytes),
        )
    except Exception:
        return None


def _rust_array_signature_core(array: Any) -> Optional[Tuple[int, str, int]]:
    """Attempt Rust array-signature generation for plot refresh state.

    Purpose:
        Offload ndarray content fingerprint generation used by layer-signature
        change detection in adaptive refresh routing.
    Why:
        Large arrays can make Python byte hashing a visible hotspot during repeat
        refresh decisions.
    Inputs:
        array: Candidate ndarray-like payload.
    Outputs:
        Optional `(size, dtype, content_hash)` tuple, or None for fallback.
    Side Effects:
        May update cached Rust import error state on backend failures.
    Exceptions:
        Backend invocation and payload validation failures are swallowed.
    """
    backend = _load_rust_backend()
    if backend is None:
        return None
    resolver = getattr(backend, "array_signature_core", None)
    if not callable(resolver):
        return None
    try:
        np_array = np.ascontiguousarray(np.asarray(array, dtype=float).reshape(-1))
    except Exception:
        return None
    payload: Any = None
    try:
        payload = resolver(np_array)
    except Exception as exc:
        global _RUST_BACKEND_IMPORT_ERROR
        _RUST_BACKEND_IMPORT_ERROR = exc
        return None
    if not isinstance(payload, Sequence) or len(payload) < 3:
        return None
    size = _safe_rust_int(payload[0], -1)
    dtype_text = str(payload[1] or "").strip()
    hash_value = _safe_rust_int(payload[2], 0)
    if size < 0 or not dtype_text:
        return None
    return (int(size), dtype_text, int(hash_value))


