def _rust_combined_required_indices(
    *,
    x_array: np.ndarray,
    series_arrays: Mapping[str, Any],
) -> Optional[np.ndarray]:
    """Attempt Rust required-index extraction for combined preview decimation.

    Purpose:
        Offload non-finite retention index discovery across x/y series arrays.
    Why:
        Combined preview refreshes repeatedly scan arrays for NaN/inf boundaries;
        Rust can compute the required-retention set with lower Python overhead.
    Inputs:
        x_array: Source x-axis array aligned to combined series length.
        series_arrays: Mapping of optional y-series arrays keyed by trace id.
    Outputs:
        Sorted numpy integer index array, or `None` when fallback is required.
    Side Effects:
        May update cached Rust import error state when runtime failures occur.
    Exceptions:
        Extension invocation errors are swallowed and reported via cache state.
    """
    backend = _load_rust_backend()
    if backend is None:
        return None
    resolver = getattr(backend, "combined_required_indices", None)
    if not callable(resolver):
        return None
    try:
        x_payload = np.asarray(x_array, dtype=float).reshape(-1)
    except Exception:
        return None
    if x_payload.size <= 0:
        return np.zeros((0,), dtype=int)
    payload_series: List[np.ndarray] = []
    for key in ("y1", "y2", "y3", "z", "z2"):
        raw_values = series_arrays.get(key)
        if raw_values is None:
            continue
        try:
            series_arr = np.asarray(raw_values, dtype=float).reshape(-1)
        except Exception:
            continue
        if series_arr.size != x_payload.size:
            continue
        payload_series.append(series_arr)
    payload: Any = None
    try:
        payload = resolver(x_payload, payload_series)
    except Exception as exc:
        global _RUST_BACKEND_IMPORT_ERROR
        _RUST_BACKEND_IMPORT_ERROR = exc
        return None
    if not isinstance(payload, Sequence):
        return None
    clean: List[int] = []
    for raw in payload:
        idx = _safe_rust_int(raw, -1)
        if 0 <= idx < int(x_payload.size):
            clean.append(idx)
    if not clean:
        return np.zeros((0,), dtype=int)
    return np.array(sorted(set(clean)), dtype=int)


def _rust_combined_decimation_indices(
    *,
    data_len: int,
    step: int,
    required_indices: Optional[Sequence[Any]] = None,
) -> Optional[np.ndarray]:
    """Attempt Rust decimation-index selection for combined plot preview refresh.

    Purpose:
        Offload deterministic decimation index generation for large datasets.
    Why:
        Combined plot refresh paths repeatedly build index unions with endpoint
        and NaN-neighbor preservation; Rust can execute that set logic faster.
    Inputs:
        data_len: Total source series length.
        step: Base decimation stride.
        required_indices: Optional source indices that must be retained.
    Outputs:
        Sorted numpy integer index array, or `None` when fallback is required.
    Side Effects:
        May update cached Rust import error state when runtime failures occur.
    Exceptions:
        Extension invocation errors are swallowed and reported via cache state.
    """
    if data_len <= 0 or step <= 0:
        return None
    backend = _load_rust_backend()
    if backend is None:
        return None
    resolver = getattr(backend, "combined_decimation_indices", None)
    if not callable(resolver):
        return None
    payload_required: Optional[List[int]] = None
    if required_indices is not None:
        payload_required = []
        # Iterate over required_indices to preserve only safe integer candidates.
        for raw in required_indices:
            idx = _safe_rust_int(raw, -1)
            if 0 <= idx < int(data_len):
                payload_required.append(idx)
    payload: Any = None
    try:
        payload = resolver(int(data_len), int(step), payload_required)
    except Exception as exc:
        global _RUST_BACKEND_IMPORT_ERROR
        _RUST_BACKEND_IMPORT_ERROR = exc
        return None
    if not isinstance(payload, Sequence):
        return None
    clean: List[int] = []
    # Iterate over payload to validate Rust-provided decimation indices.
    for raw in payload:
        idx = _safe_rust_int(raw, -1)
        if 0 <= idx < int(data_len):
            clean.append(idx)
    if not clean:
        return None
    unique_sorted = np.array(sorted(set(clean)), dtype=int)
    if unique_sorted.size == 0:
        return None
    if int(unique_sorted[-1]) != int(data_len - 1):
        return None
    return unique_sorted


def _build_reusable_scatter_offsets(
    *,
    offsets_cache: Dict[str, np.ndarray],
    cache_key: str,
    x_values: Any,
    y_values: Any,
) -> Optional[np.ndarray]:
    """Build reusable scatter offsets without per-refresh column-stack churn.

    Purpose:
        Reuse cached `(N, 2)` scatter offset buffers for combined refresh paths.
    Why:
        Combined plot reuse loops can issue repeated scatter `set_offsets` calls;
        reusing buffers avoids repeated temporary `np.column_stack` allocations.
    Inputs:
        offsets_cache: Mutable cache mapping trace keys to offset buffers.
        cache_key: Trace key used to store/retrieve the reusable buffer.
        x_values: X-axis values to write into column 0.
        y_values: Y-axis values to write into column 1.
    Outputs:
        Optional[np.ndarray]: Filled `(N, 2)` offset array, or `None` when input
        conversion fails.
    Side Effects:
        Mutates/updates the cached offset buffer for `cache_key`.
    Exceptions:
        Conversion failures are handled internally and return `None`.
    """
    try:
        x_arr = np.asarray(x_values, dtype=float).reshape(-1)
        y_arr = np.asarray(y_values, dtype=float).reshape(-1)
    except Exception:
        return None
    count = int(min(x_arr.size, y_arr.size))
    if count <= 0:
        return np.zeros((0, 2), dtype=float)
    cache = offsets_cache if isinstance(offsets_cache, dict) else {}
    buffer = cache.get(cache_key)
    if not isinstance(buffer, np.ndarray) or buffer.shape != (count, 2):
        buffer = np.empty((count, 2), dtype=float)
        cache[cache_key] = buffer
    buffer[:, 0] = x_arr[:count]
    buffer[:, 1] = y_arr[:count]
    return buffer

def _rust_cycle_detect_markers_core(
    *,
    x_values: np.ndarray,
    y_values: np.ndarray,
    mask_arr: np.ndarray,
    prominence: float,
    distance: int,
    width: int,
    smoothing_window: int,
    refine_radius: int,
) -> Optional[Dict[str, Any]]:
    """Attempt Rust automatic peak/trough detection with raw-extrema refinement.

    Purpose:
        Offload automatic cycle-marker detection to the Rust extension when it is
        available and compatible with the active interpreter.
    Why:
        Peak/trough auto-detection and sharp-feature refinement are repeatedly
        triggered by Cycle Analysis and Compare workflows and benefit from one
        shared high-performance implementation.
    Inputs:
        x_values: Full x-axis data aligned to `y_values`.
        y_values: Full pressure-series data used for marker detection.
        mask_arr: Boolean selection mask restricting detection to the active range.
        prominence: Minimum prominence threshold for candidate extrema.
        distance: Minimum spacing between accepted markers in samples.
        width: Minimum accepted width in samples.
        smoothing_window: Centered moving-average window used for candidate search.
        refine_radius: Raw-series refinement radius in samples.
    Outputs:
        Dict containing validated `auto_peaks`, `auto_troughs`, and `debug`
        payloads, or `None` when Python fallback is required.
    Side Effects:
        May update cached Rust import error state when runtime failures occur.
    Exceptions:
        Extension invocation errors are swallowed and converted into `None`.
    """
    backend = _load_rust_backend()
    if backend is None:
        return None
    resolver = getattr(backend, "cycle_detect_markers_core", None)
    if not callable(resolver):
        return None
    try:
        xv = np.asarray(x_values, dtype=float).reshape(-1)
        yv = np.asarray(y_values, dtype=float).reshape(-1)
        mask_safe = np.asarray(mask_arr, dtype=bool).reshape(-1)
    except Exception:
        return None
    data_len = min(int(xv.size), int(yv.size), int(mask_safe.size))
    if data_len <= 0:
        return None
    xv = xv[:data_len]
    yv = yv[:data_len]
    mask_safe = mask_safe[:data_len]
    payload: Any = None
    try:
        payload = resolver(
            xv,
            yv,
            mask_safe,
            float(prominence),
            max(1, int(distance)),
            max(1, int(width)),
            max(1, int(smoothing_window)),
            max(1, int(refine_radius)),
        )
    except Exception as exc:
        global _RUST_BACKEND_IMPORT_ERROR
        _RUST_BACKEND_IMPORT_ERROR = exc
        return None
    if not isinstance(payload, Mapping):
        return None
    mask_view = mask_safe

    def _sanitize_indices(values: Any) -> List[int]:
        """Validate Rust-detected automatic marker indices against local inputs."""
        if not isinstance(values, Sequence):
            return []
        safe: List[int] = []
        # Iterate over values to keep only in-range masked indices.
        for raw in values:
            idx = _safe_rust_int(raw, -1)
            if idx < 0 or idx >= data_len:
                continue
            if not bool(mask_view[idx]):
                continue
            safe.append(int(idx))
        return sorted(set(safe))

    debug_payload = payload.get("debug")
    return {
        "auto_peaks": _sanitize_indices(payload.get("auto_peaks", ())),
        "auto_troughs": _sanitize_indices(payload.get("auto_troughs", ())),
        "debug": dict(debug_payload) if isinstance(debug_payload, Mapping) else {},
    }


def _rust_cycle_manual_snap_core(
    *,
    x_values: np.ndarray,
    y_values: np.ndarray,
    mask_arr: np.ndarray,
    x_target: float,
    y_target: Optional[float],
    prefer_peak: bool,
    snap_radius: int,
    smoothing_window: int,
) -> Optional[Dict[str, Any]]:
    """Attempt Rust context-aware manual marker snapping.

    Purpose:
        Resolve one manual peak/trough placement candidate from cursor context.
    Why:
        Main Cycle Analysis and Compare side editors should share one placement
        policy so sharp extrema do not land on the slope in one editor but not
        the other.
    Inputs:
        x_values: Full x-axis data aligned to `y_values`.
        y_values: Full pressure series used for manual marker placement.
        mask_arr: Boolean selection mask for active data rows.
        x_target: Cursor x-coordinate in data units.
        y_target: Optional cursor y-coordinate in data units.
        prefer_peak: When True, snap to a peak; otherwise snap to a trough.
        snap_radius: Sample radius for candidate search, where `0` means auto.
        smoothing_window: Centered moving-average window used for candidate search.
    Outputs:
        Dict containing snapped `index`, `x`, `y`, `prominence`, and `score`, or
        `None` when fallback is required.
    Side Effects:
        May update cached Rust import error state when runtime failures occur.
    Exceptions:
        Extension invocation errors are swallowed and converted into `None`.
    """
    backend = _load_rust_backend()
    if backend is None:
        return None
    resolver = getattr(backend, "cycle_manual_snap_core", None)
    if not callable(resolver):
        return None
    try:
        xv = np.asarray(x_values, dtype=float).reshape(-1)
        yv = np.asarray(y_values, dtype=float).reshape(-1)
        mask_safe = np.asarray(mask_arr, dtype=bool).reshape(-1)
        x_cursor = float(x_target)
        y_cursor = None if y_target is None else float(y_target)
    except Exception:
        return None
    data_len = min(int(xv.size), int(yv.size), int(mask_safe.size))
    if data_len <= 0 or not math.isfinite(x_cursor):
        return None
    xv = xv[:data_len]
    yv = yv[:data_len]
    mask_safe = mask_safe[:data_len]
    payload: Any = None
    try:
        payload = resolver(
            xv,
            yv,
            mask_safe,
            x_cursor,
            y_cursor,
            bool(prefer_peak),
            max(0, int(snap_radius)),
            max(1, int(smoothing_window)),
        )
    except Exception as exc:
        global _RUST_BACKEND_IMPORT_ERROR
        _RUST_BACKEND_IMPORT_ERROR = exc
        return None
    if not isinstance(payload, Mapping):
        return None
    idx = _safe_rust_int(payload.get("index"), -1)
    if idx < 0 or idx >= data_len or not bool(mask_safe[idx]):
        return None
    x_value = _safe_rust_float(payload.get("x"), float("nan"))
    y_value = _safe_rust_float(payload.get("y"), float("nan"))
    prominence = _safe_rust_float(payload.get("prominence"), float("nan"))
    score = _safe_rust_float(payload.get("score"), float("nan"))
    if not (math.isfinite(x_value) and math.isfinite(y_value)):
        return None
    return {
        "index": int(idx),
        "x": float(x_value),
        "y": float(y_value),
        "prominence": float(prominence) if math.isfinite(prominence) else None,
        "score": float(score) if math.isfinite(score) else None,
    }


def _rust_cycle_segmentation_core(
    *,
    y_arr: np.ndarray,
    mask_arr: np.ndarray,
    auto_peaks: Set[int],
    auto_troughs: Set[int],
    add_peaks: Set[int],
    add_troughs: Set[int],
    rm_peaks: Set[int],
    rm_troughs: Set[int],
    min_cycle_drop: float,
    ignore_min_drop: bool,
    manual_only: bool,
) -> Optional[Dict[str, Any]]:
    """Attempt Rust cycle segmentation merge/form logic.

    Purpose:
        Offload peak/trough merge and cycle construction for cached plot context.
    Why:
        Combined refresh and cycle overlays repeatedly execute this merge logic.
    Inputs:
        Mirrors Python segmentation merge parameters after auto-detection.
    Outputs:
        Validated segmentation payload or `None` when fallback is required.
    Side Effects:
        May update cached Rust import error state when runtime failures occur.
    Exceptions:
        Extension invocation errors are swallowed and reported via cache state.
    """
    backend = _load_rust_backend()
    if backend is None:
        return None
    resolver = getattr(backend, "cycle_segmentation_core", None)
    if not callable(resolver):
        return None
    mask_len = min(int(np.asarray(mask_arr, dtype=bool).size), int(np.asarray(y_arr).size))
    if mask_len <= 0:
        return None
    payload: Any = None
    try:
        payload = resolver(
            np.asarray(y_arr, dtype=float),
            np.asarray(mask_arr, dtype=bool),
            sorted(int(v) for v in auto_peaks),
            sorted(int(v) for v in auto_troughs),
            sorted(int(v) for v in add_peaks),
            sorted(int(v) for v in add_troughs),
            sorted(int(v) for v in rm_peaks),
            sorted(int(v) for v in rm_troughs),
            float(min_cycle_drop),
            bool(ignore_min_drop),
            bool(manual_only),
        )
    except Exception as exc:
        global _RUST_BACKEND_IMPORT_ERROR
        _RUST_BACKEND_IMPORT_ERROR = exc
        return None
    if not isinstance(payload, Mapping):
        return None
    mask_safe = np.asarray(mask_arr, dtype=bool)[:mask_len]
    y_safe = np.asarray(y_arr, dtype=float)[:mask_len]

    def _sanitize_indices(values: Any, *, require_mask: bool) -> List[int]:
        """Return validated cycle indices from a Rust payload field."""
        if not isinstance(values, Sequence):
            return []
        safe: List[int] = []
        # Iterate over values to normalize index payload entries.
        for raw in values:
            idx = _safe_rust_int(raw, -1)
            if idx < 0 or idx >= mask_len:
                continue
            if require_mask and not bool(mask_safe[idx]):
                continue
            safe.append(int(idx))
        return sorted(set(safe))

    peaks = _sanitize_indices(payload.get("peaks", ()), require_mask=True)
    troughs = _sanitize_indices(payload.get("troughs", ()), require_mask=True)
    plot_peaks = np.asarray(
        _sanitize_indices(payload.get("plot_peaks", ()), require_mask=True), dtype=int
    )
    plot_troughs = np.asarray(
        _sanitize_indices(payload.get("plot_troughs", ()), require_mask=True), dtype=int
    )
    raw_cycles = payload.get("cycles")
    if not isinstance(raw_cycles, Sequence):
        return None
    cycles: List[Dict[str, Any]] = []
    # Iterate over raw_cycles to validate each cycle payload row.
    for row in raw_cycles:
        if not isinstance(row, Mapping):
            continue
        peak_idx = _safe_rust_int(row.get("peak_idx"), -1)
        trough_idx = _safe_rust_int(row.get("trough_idx"), -1)
        if (
            peak_idx < 0
            or trough_idx < 0
            or peak_idx >= mask_len
            or trough_idx >= mask_len
            or not bool(mask_safe[peak_idx])
            or not bool(mask_safe[trough_idx])
        ):
            continue
        peak_val = _safe_rust_float(row.get("peak"), float("nan"))
        trough_val = _safe_rust_float(row.get("trough"), float("nan"))
        delta_p = _safe_rust_float(row.get("delta_P"), float("nan"))
        if not (math.isfinite(peak_val) and math.isfinite(trough_val) and math.isfinite(delta_p)):
            continue
        # Align peak/trough with source arrays to preserve Python schema semantics.
        if not (
            math.isfinite(_safe_rust_float(y_safe[peak_idx], float("nan")))
            and math.isfinite(_safe_rust_float(y_safe[trough_idx], float("nan")))
        ):
            continue
        cycles.append(
            {
                "peak_idx": int(peak_idx),
                "trough_idx": int(trough_idx),
                "peak": float(peak_val),
                "trough": float(trough_val),
                "delta_P": float(delta_p),
            }
        )
    if not cycles and (peaks or troughs):
        return None
    return {
        "peaks": peaks,
        "troughs": troughs,
        "plot_peaks": plot_peaks,
        "plot_troughs": plot_troughs,
        "cycles": cycles,
        "total_drop": _safe_rust_float(payload.get("total_drop"), 0.0),
        "selection_size": max(_safe_rust_int(payload.get("selection_size"), 0), 0),
    }


def _rust_cycle_metrics_core(
    *,
    cycles: Sequence[Mapping[str, Any]],
    z_values: Optional[np.ndarray],
    x_values: Optional[np.ndarray],
    volume_l: float,
    a_const: float,
    b_const: float,
    gas_molar_mass: float,
    x_label: str,
    compute_vdw: bool,
) -> Optional[Dict[str, Any]]:
    """Attempt Rust cycle metrics and transfer-row assembly.

    Purpose:
        Offload per-cycle gas calculations and transfer table generation.
    Why:
        Combined overlay refresh paths repeatedly assemble these metrics payloads.
    Inputs:
        cycles: Cycle segmentation rows with peak/trough indices and pressure deltas.
        z_values: Optional cycle temperature series.
        x_values: Optional x-axis series used for transfer start/end/duration fields.
        volume_l: Vessel volume in liters.
        a_const: Van der Waals `a` constant.
        b_const: Van der Waals `b` constant.
        gas_molar_mass: Gas molecular weight (g/mol) for mass conversion.
        x_label: Display label for x-axis transfer columns.
        compute_vdw: Whether VDW terms should be computed.
    Outputs:
        Validated metrics payload dict or `None` when fallback is required.
    Side Effects:
        May update cached Rust import error state when runtime failures occur.
    Exceptions:
        Extension invocation errors are swallowed and reported via cache state.
    """
    backend = _load_rust_backend()
    if backend is None:
        return None
    resolver = getattr(backend, "cycle_metrics_core", None)
    if not callable(resolver):
        return None
    if not isinstance(cycles, Sequence):
        return None
    payload_cycles: List[Dict[str, Any]] = []
    # Iterate over cycles to normalize rows before Rust invocation.
    for row in cycles:
        if not isinstance(row, Mapping):
            continue
        payload_cycles.append(
            {
                "peak_idx": _safe_rust_int(row.get("peak_idx"), -1),
                "trough_idx": _safe_rust_int(row.get("trough_idx"), -1),
                "peak": _safe_rust_float(row.get("peak"), float("nan")),
                "trough": _safe_rust_float(row.get("trough"), float("nan")),
                "delta_P": _safe_rust_float(row.get("delta_P"), float("nan")),
            }
        )
    if not payload_cycles:
        return None
    payload: Any = None
    try:
        payload = resolver(
            payload_cycles,
            np.asarray(z_values, dtype=float) if z_values is not None else None,
            np.asarray(x_values, dtype=float) if x_values is not None else None,
            float(volume_l),
            float(a_const),
            float(b_const),
            float(gas_molar_mass),
            str(x_label),
            bool(compute_vdw),
            25.0,
        )
    except Exception as exc:
        global _RUST_BACKEND_IMPORT_ERROR
        _RUST_BACKEND_IMPORT_ERROR = exc
        return None
    if not isinstance(payload, Mapping):
        return None
    per_cycle_raw = payload.get("per_cycle")
    transfer_raw = payload.get("cycle_transfer")
    if not isinstance(per_cycle_raw, Sequence) or not isinstance(transfer_raw, Sequence):
        return None
    per_cycle: List[Dict[str, Any]] = []
    # Iterate over per_cycle_raw to validate each per-cycle metric row.
    for row in per_cycle_raw:
        if not isinstance(row, Mapping):
            continue
        per_cycle.append(
            {
                "peak": _safe_rust_float(row.get("peak"), float("nan")),
                "trough": _safe_rust_float(row.get("trough"), float("nan")),
                "deltaP": _safe_rust_float(row.get("deltaP"), float("nan")),
                "T_mean_C": _safe_rust_float(row.get("T_mean_C"), float("nan")),
                "used_default": bool(row.get("used_default", False)),
                "n_ideal": _safe_rust_float(row.get("n_ideal"), float("nan")),
                "n_vdw": _safe_rust_float(row.get("n_vdw"), float("nan")),
            }
        )
    cycle_transfer: List[Dict[str, Any]] = []
    # Iterate over transfer_raw to preserve validated transfer rows.
    for row in transfer_raw:
        if isinstance(row, Mapping):
            cycle_transfer.append(dict(row))
    if not per_cycle:
        return None
    return {
        "per_cycle": per_cycle,
        "total_moles_ideal": _safe_rust_float(payload.get("total_moles_ideal"), 0.0),
        "total_moles_vdw": _safe_rust_float(payload.get("total_moles_vdw"), 0.0),
        "vdw_used": bool(payload.get("vdw_used", False)),
        "cycle_transfer": cycle_transfer,
    }


def _rust_cycle_overlay_points_core(
    *,
    x_values: np.ndarray,
    y_values: np.ndarray,
    peak_indices: Sequence[Any],
    trough_indices: Sequence[Any],
) -> Optional[Dict[str, Any]]:
    """Attempt Rust cycle overlay point extraction for combined/core overlays.

    Purpose:
        Offload point extraction for peak/trough marker overlays.
    Why:
        Overlay point mapping is repeated for combined/core render paths and can
        be safely accelerated while preserving strict Python fallback parity.
    Inputs:
        x_values: Source x-axis series used for point coordinate lookup.
        y_values: Source y-axis series used for point coordinate lookup.
        peak_indices: Candidate peak indices to map into finite `(x, y)` pairs.
        trough_indices: Candidate trough indices to map into finite `(x, y)` pairs.
    Outputs:
        Dict with `peak_points` and `trough_points`, or `None` when fallback is
        required.
    Side Effects:
        May update cached Rust import error state when runtime failures occur.
    Exceptions:
        Extension invocation errors are swallowed and reported via cache state.
    """
    backend = _load_rust_backend()
    if backend is None:
        return None
    resolver = getattr(backend, "cycle_overlay_points_core", None)
    if not callable(resolver):
        return None
    try:
        xv = np.asarray(x_values, dtype=float).reshape(-1)
        yv = np.asarray(y_values, dtype=float).reshape(-1)
    except Exception:
        return None
    data_len = min(int(xv.size), int(yv.size))
    if data_len <= 0:
        return None
    if int(xv.size) != data_len:
        xv = xv[:data_len]
    if int(yv.size) != data_len:
        yv = yv[:data_len]

    def _sanitize_indices(values: Sequence[Any]) -> List[int]:
        """Normalize candidate point indices before Rust invocation."""
        safe: List[int] = []
        # Iterate over values to preserve only valid integer indices.
        for raw in values or ():
            idx = _safe_rust_int(raw, -1)
            if 0 <= idx < data_len:
                safe.append(int(idx))
        return sorted(set(safe))

    payload_peak_indices = _sanitize_indices(peak_indices)
    payload_trough_indices = _sanitize_indices(trough_indices)
    payload: Any = None
    try:
        payload = resolver(
            xv,
            yv,
            payload_peak_indices,
            payload_trough_indices,
        )
    except Exception as exc:
        global _RUST_BACKEND_IMPORT_ERROR
        _RUST_BACKEND_IMPORT_ERROR = exc
        return None
    if not isinstance(payload, Mapping):
        return None

    def _sanitize_points(values: Any) -> Optional[List[Tuple[float, float]]]:
        """Validate one Rust `(x, y)` point-list payload."""
        if not isinstance(values, Sequence):
            return None
        points: List[Tuple[float, float]] = []
        # Iterate over values to validate point payload entries.
        for raw in values:
            if not isinstance(raw, Sequence) or len(raw) < 2:
                continue
            x_val = _safe_rust_float(raw[0], float("nan"))
            y_val = _safe_rust_float(raw[1], float("nan"))
            if not (math.isfinite(x_val) and math.isfinite(y_val)):
                continue
            points.append((float(x_val), float(y_val)))
        return points

    peak_points = _sanitize_points(payload.get("peak_points"))
    trough_points = _sanitize_points(payload.get("trough_points"))
    if peak_points is None or trough_points is None:
        return None
    return {
        "peak_points": peak_points,
        "trough_points": trough_points,
    }


def _rust_simulate_reaction_state_with_accounting(
    ledger: Dict[str, float],
    delta_mol: float,
    pka2_value: float,
    *,
    solution_volume_l: Optional[float] = None,
    temperature_c: Optional[float] = None,
    ionic_strength_cap: Optional[float] = None,
    use_temp_adjusted_constants: bool = False,
    initial_ph_guess: Optional[float] = None,
    constants: Optional[Tuple[float, float, float]] = None,
    planning_mode: bool = False,
) -> Optional[Tuple[Dict[str, float], Dict[str, float]]]:
    """Attempt the Rust simulation kernel and validate returned payloads.

    Purpose:
        Provide a strict bridge between Python chemistry workflows and Rust math.
    Why:
        Runtime guardrails ensure Python fallback remains authoritative whenever
        the extension is missing, incompatible, or returns malformed data.
    Inputs:
        Mirrors `_simulate_reaction_state_with_accounting` solver parameters.
    Outputs:
        `(state, accounting)` on success, else `None` to trigger Python fallback.
    Side Effects:
        May update cached Rust import error state when runtime failures occur.
    Exceptions:
        Extension invocation errors are swallowed and reported via cache state.
    """
    backend = _load_rust_backend()
    if backend is None:
        return None
    solver = getattr(backend, "simulate_reaction_state_with_accounting", None)
    if not callable(solver):
        return None
    payload: Any = None
    try:
        payload = solver(
            ledger,
            float(delta_mol),
            float(pka2_value),
            solution_volume_l,
            temperature_c,
            ionic_strength_cap,
            bool(use_temp_adjusted_constants),
            initial_ph_guess,
            constants,
            bool(planning_mode),
        )
    except Exception as exc:
        global _RUST_BACKEND_IMPORT_ERROR
        _RUST_BACKEND_IMPORT_ERROR = exc
        return None
    if not isinstance(payload, Mapping):
        return None
    state_raw = payload.get("state")
    accounting_raw = payload.get("accounting")
    if not isinstance(state_raw, Mapping) or not isinstance(accounting_raw, Mapping):
        return None
    state = {
        "naoh_remaining_mol": max(
            _safe_rust_float(state_raw.get("naoh_remaining_mol"), 0.0), 0.0
        ),
        "na2co3_mol": max(_safe_rust_float(state_raw.get("na2co3_mol"), 0.0), 0.0),
        "nahco3_mol": max(_safe_rust_float(state_raw.get("nahco3_mol"), 0.0), 0.0),
        "co2_excess_mol": max(_safe_rust_float(state_raw.get("co2_excess_mol"), 0.0), 0.0),
        "ph": _safe_rust_float(state_raw.get("ph"), float("nan")),
    }
    if not math.isfinite(state["ph"]):
        return None
    accounting = {
        "co2_consumed_to_carbonate_mol": max(
            _safe_rust_float(accounting_raw.get("co2_consumed_to_carbonate_mol"), 0.0),
            0.0,
        ),
        "co2_consumed_to_bicarbonate_mol": max(
            _safe_rust_float(
                accounting_raw.get("co2_consumed_to_bicarbonate_mol"), 0.0
            ),
            0.0,
        ),
        "co2_consumed_total_mol": max(
            _safe_rust_float(accounting_raw.get("co2_consumed_total_mol"), 0.0), 0.0
        ),
        "co2_unconsumed_mol": max(
            _safe_rust_float(accounting_raw.get("co2_unconsumed_mol"), 0.0), 0.0
        ),
    }
    return state, accounting


def _rust_analyze_bicarbonate_core(
    *,
    naoh_mass_g: float,
    co2_charged_g: float,
    solution_volume_l: Optional[float],
    measured_ph: Optional[float],
    slurry_ph: Optional[float],
    target_ph: Optional[float],
    temperature_c: Optional[float],
    use_temp_adjusted_constants: bool,
    ionic_strength_cap: Optional[float],
    constants: Optional[Tuple[float, float, float]],
) -> Optional[Dict[str, Any]]:
    """Attempt the Rust bicarbonate core analysis kernel.

    Purpose:
        Offload high-cost repeated simulation steps used by dosing guidance.
    Why:
        Core guidance and timeline paths repeatedly evaluate this math and benefit
        from a native implementation.
    Inputs:
        Mirrors `analyze_bicarbonate_reaction` core scalar inputs.
    Outputs:
        Sanitized mapping when Rust payload is valid, else None.
    Side Effects:
        May update cached Rust import error state when runtime failures occur.
    Exceptions:
        Extension invocation errors are swallowed and reported via cache state.
    """
    backend = _load_rust_backend()
    if backend is None:
        return None
    analyzer = getattr(backend, "analyze_bicarbonate_core", None)
    if not callable(analyzer):
        return None
    payload: Any = None
    try:
        payload = analyzer(
            float(naoh_mass_g),
            float(co2_charged_g),
            solution_volume_l,
            measured_ph,
            slurry_ph,
            target_ph,
            temperature_c,
            bool(use_temp_adjusted_constants),
            ionic_strength_cap,
            constants,
        )
    except Exception as exc:
        global _RUST_BACKEND_IMPORT_ERROR
        _RUST_BACKEND_IMPORT_ERROR = exc
        return None
    if not isinstance(payload, Mapping):
        return None
    simulation_curve = payload.get("simulation_curve")
    if not isinstance(simulation_curve, Sequence):
        return None
    required = (
        "naoh_mol",
        "co2_mol",
        "stage1_co2",
        "naoh_after_stage1",
        "na2co3_remaining",
        "nahco3_produced",
        "co2_excess",
        "buffer_carbon",
        "pka2_value",
        "co3_current",
        "hco3_current",
        "desired_ph",
        "ratio_target",
        "co2_for_ratio",
        "co2_for_naoh",
        "total_extra_mol",
        "total_extra_g",
        "predicted_ph",
        "slider_max_g",
        "eq_ka1",
        "eq_ka2",
        "eq_kw",
    )
    if any(key not in payload for key in required):
        return None
    normalized = {key: payload.get(key) for key in payload.keys()}
    normalized["simulation_curve"] = list(simulation_curve)
    return normalized


def _rust_reaction_solution_charge_core(
    *,
    sodium_metal_mass_g: Optional[float],
    methanol_mass_g: Optional[float],
    water_ppm_by_mass: Optional[float],
    explicit_naoh_mass_g: Optional[float],
) -> Optional[Dict[str, Any]]:
    """Attempt Rust sodium/methanol charge-basis normalization.

    Purpose:
        Run the Reaction Dashboard sodium/water/methanol availability model in
        Rust when the current backend exports the v4.15.8 kernel.
    Why:
        Compute edits must preserve Rust acceleration with a Python fallback path
        and fail safely when the extension is unavailable or stale.
    Inputs:
        sodium_metal_mass_g: Sodium metal mass in grams.
        methanol_mass_g: Methanol mass in grams.
        water_ppm_by_mass: Water content as mg/kg by mass.
        explicit_naoh_mass_g: Added NaOH mass in grams.
    Outputs:
        Sanitized result mapping when Rust succeeds, otherwise None.
    Side Effects:
        May mark the Rust kernel unhealthy when payload shape is invalid.
    Exceptions:
        Rust import/invocation errors are swallowed and converted to fallback.
    """
    kernel_name = "reaction_solution_charge_core"
    backend = _load_rust_backend()
    if backend is None:
        return None
    resolver = getattr(backend, kernel_name, None)
    if not callable(resolver):
        return None
    payload: Any = _run_rust_kernel_with_timeout(
        kernel_name,
        lambda: resolver(
            sodium_metal_mass_g,
            methanol_mass_g,
            water_ppm_by_mass,
            explicit_naoh_mass_g,
        ),
    )
    if not isinstance(payload, Mapping):
        _mark_rust_kernel_session_unhealthy(
            kernel_name,
            reason="invalid_payload",
            details="non-mapping payload",
        )
        return None
    required = (
        "sodium_methoxide_mol",
        "remaining_methanol_mol",
        "generated_naoh_mol",
        "total_naoh_mol",
        "water_mol",
        "warnings",
    )
    if any(key not in payload for key in required):
        _mark_rust_kernel_session_unhealthy(
            kernel_name,
            reason="invalid_payload",
            details="missing reaction solution charge keys",
        )
        return None
    normalized = dict(payload)
    normalized["backend"] = "rust"
    normalized["warnings"] = list(payload.get("warnings") or [])
    return normalized


def _run_reaction_solution_charge_core(
    *,
    sodium_metal_mass_g: Optional[float],
    methanol_mass_g: Optional[float],
    water_ppm_by_mass: Optional[float],
    explicit_naoh_mass_g: Optional[float],
) -> Dict[str, Any]:
    """Run sodium/methanol charge-basis math with Rust-first fallback routing.

    Purpose:
        Provide one stable charge-basis interface for the Reaction Dashboard UI,
        tests, and future generated plot diagnostics.
    Why:
        The dashboard needs sodium methoxide and generated NaOH availability
        before the existing stoichiometric reaction core can run accurately.
    Inputs:
        Same keyword-only fields as `_python_reaction_solution_charge_core`.
    Outputs:
        Dict result with backend marker, normalized moles, diagnostics, and warnings.
    Side Effects:
        May probe Rust backend health through `_rust_reaction_solution_charge_core`.
    Exceptions:
        Python fallback exceptions are allowed to propagate for programmer errors.
    """
    rust_payload = _rust_reaction_solution_charge_core(
        sodium_metal_mass_g=sodium_metal_mass_g,
        methanol_mass_g=methanol_mass_g,
        water_ppm_by_mass=water_ppm_by_mass,
        explicit_naoh_mass_g=explicit_naoh_mass_g,
    )
    if rust_payload is not None:
        return rust_payload
    return _python_reaction_solution_charge_core(
        sodium_metal_mass_g=sodium_metal_mass_g,
        methanol_mass_g=methanol_mass_g,
        water_ppm_by_mass=water_ppm_by_mass,
        explicit_naoh_mass_g=explicit_naoh_mass_g,
    )


def _rust_reaction_dashboard_core(
    species_rows: Sequence[Mapping[str, Any]],
    step_rows: Sequence[Mapping[str, Any]],
    *,
    gas_uptake_mol: float,
    gas_species_id: str,
    yield_species_id: str,
    target_reactant_species_id: Optional[str],
    actual_yield_mass_g: Optional[float],
) -> Optional[Dict[str, Any]]:
    """Attempt the Rust Reaction Dashboard template-neutral kernel.

    Purpose:
        Execute gas uptake, stoichiometric extent, completion, and yield math in
        the Rust backend when the loaded extension exposes the current contract.
    Why:
        Reaction Dashboard compute must meet the repository Rust/Python fallback
        standard without tying pH/ChemPy behavior to native code.
    Inputs:
        species_rows: Species mappings with ids, molar masses, and initial moles.
        step_rows: Step mappings with signed stoichiometry maps.
        gas_uptake_mol: Moles of reactant gas charged or absorbed.
        gas_species_id: Species id receiving gas uptake.
        yield_species_id: Final product species id.
        target_reactant_species_id: Optional completion basis species id.
        actual_yield_mass_g: Optional isolated product mass.
    Outputs:
        Sanitized result mapping when Rust succeeds, otherwise None.
    Side Effects:
        May mark the Rust kernel unhealthy when payload shape is invalid.
    Exceptions:
        Rust import/invocation failures are swallowed and converted to fallback.
    """
    kernel_name = "reaction_dashboard_core"
    backend = _load_rust_backend()
    if backend is None:
        return None
    resolver = getattr(backend, kernel_name, None)
    if not callable(resolver):
        return None
    payload: Any = _run_rust_kernel_with_timeout(
        kernel_name,
        lambda: resolver(
            list(species_rows or []),
            list(step_rows or []),
            float(gas_uptake_mol or 0.0),
            str(gas_species_id or ""),
            str(yield_species_id or ""),
            target_reactant_species_id,
            actual_yield_mass_g,
        ),
    )
    if not isinstance(payload, Mapping):
        _mark_rust_kernel_session_unhealthy(
            kernel_name,
            reason="invalid_payload",
            details="non-mapping payload",
        )
        return None
    required = (
        "gas_uptake_mol",
        "final_inventory_mol",
        "step_results",
        "yield_species_id",
        "theoretical_yield_g",
        "completion_pct",
        "warnings",
    )
    if any(key not in payload for key in required):
        _mark_rust_kernel_session_unhealthy(
            kernel_name,
            reason="invalid_payload",
            details="missing reaction dashboard keys",
        )
        return None
    normalized = dict(payload)
    normalized["backend"] = "rust"
    normalized["step_results"] = list(payload.get("step_results") or [])
    normalized["warnings"] = list(payload.get("warnings") or [])
    return normalized


def _run_reaction_dashboard_core(
    species_rows: Sequence[Mapping[str, Any]],
    step_rows: Sequence[Mapping[str, Any]],
    *,
    gas_uptake_mol: float,
    gas_species_id: str,
    yield_species_id: str,
    target_reactant_species_id: Optional[str],
    actual_yield_mass_g: Optional[float],
) -> Dict[str, Any]:
    """Run Reaction Dashboard core math with Rust first and Python fallback.

    Purpose:
        Provide one authoritative entry point for template-neutral reaction math.
    Why:
        UI, tests, and generated plots need a stable result schema independent of
        whether Rust acceleration is available in the current environment.
    Inputs:
        Mirrors `_python_reaction_dashboard_core` and `_rust_reaction_dashboard_core`.
    Outputs:
        Result mapping with backend marker, inventories, extents, yield, and warnings.
    Side Effects:
        May probe the Rust backend and update kernel health state.
    Exceptions:
        Python fallback exceptions are allowed to propagate to the caller because
        they indicate malformed normalized inputs.
    """
    rust_payload = _rust_reaction_dashboard_core(
        species_rows,
        step_rows,
        gas_uptake_mol=gas_uptake_mol,
        gas_species_id=gas_species_id,
        yield_species_id=yield_species_id,
        target_reactant_species_id=target_reactant_species_id,
        actual_yield_mass_g=actual_yield_mass_g,
    )
    result = (
        rust_payload
        if rust_payload is not None
        else _python_reaction_dashboard_core(
            species_rows,
            step_rows,
            gas_uptake_mol=gas_uptake_mol,
            gas_species_id=gas_species_id,
            yield_species_id=yield_species_id,
            target_reactant_species_id=target_reactant_species_id,
            actual_yield_mass_g=actual_yield_mass_g,
        )
    )
    completion_pct = _safe_float(result.get("completion_pct"))
    gas_uptake = _safe_float(result.get("gas_uptake_mol"))
    if completion_pct is not None and gas_uptake is not None and completion_pct > 1e-12:
        # This is intentionally backend-neutral so the Rust and Python kernels
        # expose the same operator-facing gas-to-completion estimate.
        result["gas_required_mol"] = max(
            float(gas_uptake) * 100.0 / min(float(completion_pct), 100.0), 0.0
        )
    else:
        result["gas_required_mol"] = None
    return result


def _reaction_dashboard_cycle_metric_series(
    template: ReactionTemplate,
    species_rows: Sequence[Mapping[str, Any]],
    step_rows: Sequence[Mapping[str, Any]],
    cycle_payload: Optional[Mapping[str, Any]],
    *,
    actual_yield_mass_g: Optional[float],
    ph_enabled: bool,
    liquid_volume_l: Optional[float],
) -> List[Dict[str, Any]]:
    """Compute per-cycle Reaction Dashboard metrics from cumulative uptake rows.

    Purpose:
        Build reaction-progress series for cycle-derived Reaction Dashboard plots.
    Why:
        The generated dashboard plot needs uptake, completion, yield, product, and
        optional pH values over time while preserving the existing Rust-first
        Python-fallback reaction core.
    Inputs:
        template: Active reaction template.
        species_rows: Current species rows with template input amounts applied.
        step_rows: Linked reaction step mappings from the template editor.
        cycle_payload: Cycle Analysis transfer payload containing per-cycle rows.
        actual_yield_mass_g: Optional final isolated product mass.
        ph_enabled: True when ChemPy pH should be evaluated for each point.
        liquid_volume_l: Optional liquid volume for pH concentration seeding.
    Outputs:
        List of per-cycle metric dictionaries ordered by cycle id.
    Side Effects:
        May invoke Rust reaction core and optional ChemPy solve helpers.
    Exceptions:
        Invalid cycle rows are skipped; core/solver warnings stay inside rows.
    """
    if not isinstance(cycle_payload, Mapping):
        return []
    cycle_rows = [
        dict(row)
        for row in list(cycle_payload.get("cycle_transfer") or [])
        if isinstance(row, Mapping)
    ]
    if not cycle_rows:
        return []
    gas_row = next(
        (
            row
            for row in species_rows
            if isinstance(row, Mapping)
            and str(row.get("species_id") or "") == template.gas_species_id
        ),
        {},
    )
    gas_mw = _safe_float(gas_row.get("molar_mass_g_mol"), 0.0) or 0.0
    running_moles = 0.0
    series: List[Dict[str, Any]] = []
    for index, row in enumerate(cycle_rows, start=1):
        cycle_id = _safe_float(row.get("cycle_id"), float(index))
        x_value = _safe_float(row.get("end_x"))
        if x_value is None:
            x_value = _safe_float(row.get("start_x"))
        if x_value is None:
            x_value = cycle_id if cycle_id is not None else float(index)
        cycle_moles = _safe_float(
            row.get("selected_moles")
            or row.get("moles_vdw")
            or row.get("moles_ideal")
            or row.get("co2_moles")
        )
        cumulative_moles = _safe_float(
            row.get("cumulative_moles")
            or row.get("cumulative_co2_moles")
            or row.get("cumulative_co2_added_moles")
        )
        if cumulative_moles is None:
            running_moles += max(float(cycle_moles or 0.0), 0.0)
            cumulative_moles = running_moles
        else:
            running_moles = max(float(cumulative_moles), running_moles)
        core = _run_reaction_dashboard_core(
            species_rows,
            step_rows,
            gas_uptake_mol=max(float(cumulative_moles or 0.0), 0.0),
            gas_species_id=template.gas_species_id,
            yield_species_id=template.yield_basis.product_species_id,
            target_reactant_species_id=(
                template.yield_basis.target_reactant_species_id
            ),
            actual_yield_mass_g=actual_yield_mass_g,
        )
        equilibrium = _solve_reaction_dashboard_equilibrium_with_chempy(
            template,
            enabled=bool(ph_enabled),
            liquid_volume_l=liquid_volume_l,
            product_moles=_safe_float(core.get("yield_species_moles")),
        )
        theoretical_g = _safe_float(core.get("theoretical_yield_g"))
        product_mol = _safe_float(core.get("yield_species_moles"))
        completion_pct = _safe_float(core.get("completion_pct"))
        actual_yield_pct = _safe_float(core.get("actual_yield_pct"))
        series.append(
            {
                "cycle_id": cycle_id if cycle_id is not None else float(index),
                "x": x_value,
                "x_label": str(row.get("x_label") or "Cycle"),
                "cycle_gas_delta_mol": (
                    float(cycle_moles) if cycle_moles is not None else None
                ),
                "cumulative_gas_mol": float(cumulative_moles or 0.0),
                "cumulative_gas_g": (
                    float(cumulative_moles or 0.0) * gas_mw if gas_mw > 0.0 else None
                ),
                "completion_pct": completion_pct,
                "yield_pct": actual_yield_pct
                if actual_yield_pct is not None
                else completion_pct,
                "product_mol": product_mol,
                "product_mass_g": theoretical_g,
                "ph": _safe_float(equilibrium.get("ph")),
                "core_backend": core.get("backend"),
                "ph_backend": equilibrium.get("backend"),
                "warnings": list(core.get("warnings") or [])
                + list(equilibrium.get("warnings") or []),
            }
        )
    final_gas_basis = max(
        (
            float(row.get("cumulative_gas_mol") or 0.0)
            for row in series
            if _safe_float(row.get("cumulative_gas_mol")) is not None
        ),
        default=0.0,
    )
    if (
        template.yield_basis.target_reactant_species_id == template.gas_species_id
        and final_gas_basis > 1e-12
    ):
        for row in series:
            product_mol = _safe_float(row.get("product_mol"))
            progress_pct = (
                max(0.0, min(100.0, (float(product_mol) / final_gas_basis) * 100.0))
                if product_mol is not None
                else None
            )
            row["completion_pct"] = progress_pct
            if actual_yield_mass_g is None or _safe_float(row.get("yield_pct")) is None:
                row["yield_pct"] = progress_pct
    return series


def _reaction_dashboard_species_display(
    template: ReactionTemplate,
    species_id: Optional[str],
) -> Dict[str, Any]:
    """Return display metadata for one Reaction Dashboard species.

    Purpose:
        Resolve template species ids into operator-facing labels, formulas, and
        molar masses.
    Why:
        The visual dashboard must describe the selected gaseous reactant and
        product from the active template instead of hard-coding CO-specific copy.
    Args:
        template: Active Reaction Dashboard template.
        species_id: Species id to resolve.
    Returns:
        Dict containing id, name, formula, display label, and molar mass.
    Side Effects:
        None.
    Exceptions:
        Missing species ids fall back to a safe placeholder mapping.
    """
    target_id = str(species_id or "").strip()
    species = next(
        (item for item in template.species if item.species_id == target_id),
        None,
    )
    if species is None:
        return {
            "species_id": target_id,
            "name": target_id or "Gas reactant",
            "formula": "",
            "display": target_id or "Gas reactant",
            "molar_mass_g_mol": None,
        }
    formula = _reaction_formula_display_text(species.formula)
    display = species.name
    if formula:
        display = f"{species.name} ({formula})"
    return {
        "species_id": species.species_id,
        "name": species.name,
        "formula": formula,
        "display": display,
        "molar_mass_g_mol": species.molar_mass_g_mol,
    }


def _reaction_dashboard_cycle_trend(
    cycle_series: Sequence[Mapping[str, Any]],
) -> Dict[str, str]:
    """Classify recent per-cycle gas uptake trend for visual status messaging.

    Purpose:
        Convert cycle-derived gas deltas into a compact reaction-progress trend.
    Why:
        Operators need to know whether gas consumption is slowing, steady, or
        increasing without reading every imported cycle row.
    Args:
        cycle_series: Ordered Reaction Dashboard cycle metric rows.
    Returns:
        Dict containing trend label, status bucket, and detail text.
    Side Effects:
        None.
    Exceptions:
        Invalid rows are skipped and return an insufficient-data status.
    """
    cumulative_values = [
        float(value)
        for value in (
            _safe_float(row.get("cumulative_gas_mol"))
            for row in cycle_series
            if isinstance(row, Mapping)
        )
        if value is not None and math.isfinite(value)
    ]
    if len(cumulative_values) < 3:
        return {
            "label": "Insufficient cycle trend",
            "status": "unavailable",
            "detail": "Need at least three cycle points for trend classification.",
        }
    deltas = [
        max(cumulative_values[idx] - cumulative_values[idx - 1], 0.0)
        for idx in range(1, len(cumulative_values))
    ]
    if len(deltas) < 2:
        return {
            "label": "Insufficient cycle trend",
            "status": "unavailable",
            "detail": "Need at least two uptake deltas for trend classification.",
        }
    previous = max(float(deltas[-2]), 1e-12)
    latest = float(deltas[-1])
    ratio = latest / previous
    if ratio <= 0.75:
        return {
            "label": "Slowing uptake",
            "status": "watch",
            "detail": f"Latest gas delta is {latest:.4f} mol vs {previous:.4f} mol.",
        }
    if ratio >= 1.25:
        return {
            "label": "Increasing uptake",
            "status": "neutral",
            "detail": f"Latest gas delta is {latest:.4f} mol vs {previous:.4f} mol.",
        }
    return {
        "label": "Steady uptake",
        "status": "healthy",
        "detail": f"Latest gas delta is {latest:.4f} mol vs {previous:.4f} mol.",
    }


def _reaction_dashboard_forecast(
    cycle_series: Sequence[Mapping[str, Any]],
    completion_pct: Optional[float],
) -> Dict[str, Any]:
    """Estimate remaining reaction cycles and time from imported cycle history.

    Purpose:
        Turn the completed portion of a reaction and its recent cycle history
        into an explicitly labelled, conservative operator forecast.
    Why:
        The Reaction Hub should answer how much longer a run may take without
        claiming a time estimate when the imported x-axis is not time-like.
    Inputs:
        cycle_series: Ordered cycle rows carrying completion, x, and x-label
            values from Cycle Analysis.
        completion_pct: Current completion percentage on the active template's
            declared stoichiometric basis.
    Outputs:
        Mapping with cycle/time estimates, observed rates, and a confidence note.
    Side Effects:
        None.
    Exceptions:
        Invalid, missing, or non-progressing rows return unavailable estimates.
    """
    completion = _safe_float(completion_pct)
    rows = [dict(row) for row in cycle_series if isinstance(row, Mapping)]
    if completion is None or not math.isfinite(completion) or completion >= 100.0:
        return {
            "remaining_cycles": 0.0
            if completion is not None and completion >= 100.0
            else None,
            "remaining_time": None,
            "time_unit": "",
            "completion_rate_pct_per_cycle": None,
            "confidence": "No forecast needed."
            if completion is not None and completion >= 100.0
            else "Completion basis is unavailable.",
        }
    progress = [
        _safe_float(row.get("completion_pct"))
        for row in rows
        if _safe_float(row.get("completion_pct")) is not None
    ]
    if len(progress) < 2:
        return {
            "remaining_cycles": None,
            "remaining_time": None,
            "time_unit": "",
            "completion_rate_pct_per_cycle": None,
            "confidence": "Import at least two usable cycle points to forecast completion.",
        }
    # Use only the latest positive progress deltas so stalled or duplicate rows
    # do not make an optimistic forecast look more precise than the data allows.
    all_positive_deltas = [
        later - earlier
        for earlier, later in zip(progress, progress[1:])
        if later > earlier + 1e-9
    ]
    deltas = all_positive_deltas[-4:]
    if not deltas:
        return {
            "remaining_cycles": None,
            "remaining_time": None,
            "time_unit": "",
            "completion_rate_pct_per_cycle": None,
            "confidence": "No positive completion trend is available for a forecast.",
        }
    rate = sum(deltas) / len(deltas)
    remaining_cycles = max((100.0 - float(completion)) / max(rate, 1e-12), 0.0)
    average_rate = sum(all_positive_deltas) / len(all_positive_deltas)
    average_remaining_cycles = max(
        (100.0 - float(completion)) / max(average_rate, 1e-12), 0.0
    )
    x_values = [_safe_float(row.get("x")) for row in rows]
    x_values = [
        value for value in x_values if value is not None and math.isfinite(value)
    ]
    x_label = str(rows[-1].get("x_label") or "").strip()
    normalized_label = x_label.lower()
    is_time_axis = any(
        token in normalized_label
        for token in ("time", "second", "minute", "hour", "day", " sec", " min", " hr")
    )
    time_per_cycle = None
    if is_time_axis and len(x_values) >= 2:
        elapsed = x_values[-1] - x_values[0]
        if elapsed > 0.0:
            time_per_cycle = elapsed / max(len(x_values) - 1, 1)
    return {
        "remaining_cycles": remaining_cycles,
        "remaining_time": remaining_cycles * time_per_cycle
        if time_per_cycle is not None
        else None,
        "average_remaining_cycles": average_remaining_cycles,
        "average_remaining_time": average_remaining_cycles * time_per_cycle
        if time_per_cycle is not None
        else None,
        "time_unit": x_label if time_per_cycle is not None else "",
        "completion_rate_pct_per_cycle": rate,
        "average_completion_rate_pct_per_cycle": average_rate,
        "confidence": (
            "Recent positive completion-rate estimate; process changes can invalidate it."
            if time_per_cycle is not None
            else "Cycle forecast only; imported x-axis is not a recognized time basis."
        ),
    }


def _reaction_dashboard_material_inventory(
    template: ReactionTemplate,
    core: Mapping[str, Any],
) -> List[Dict[str, Any]]:
    """Build an operator-facing material inventory from reaction-core balances.

    Purpose:
        Expose starting amount, estimated consumption, and remaining inventory
        for every declared species in the active reaction template.
    Why:
        A reusable reaction hub must make the charge basis visible instead of
        only presenting a final product number for one reaction family.
    Inputs:
        template: Active template defining species identity and molar masses.
        core: Rust/Python reaction-core result containing initial and final molar
            inventory mappings.
    Outputs:
        Ordered display rows with molar and mass balances for each species.
    Side Effects:
        None.
    Exceptions:
        Missing inventories are normalized to zero or unavailable values.
    """
    initial = (
        core.get("initial_inventory_mol")
        if isinstance(core.get("initial_inventory_mol"), Mapping)
        else {}
    )
    final = (
        core.get("final_inventory_mol")
        if isinstance(core.get("final_inventory_mol"), Mapping)
        else {}
    )
    rows: List[Dict[str, Any]] = []
    for species in template.species:
        starting = _safe_float(initial.get(species.species_id), 0.0) or 0.0
        ending = _safe_float(final.get(species.species_id), 0.0) or 0.0
        net_change = float(ending) - float(starting)
        rows.append(
            {
                "species_id": species.species_id,
                "material": _reaction_dashboard_species_display(
                    template, species.species_id
                ).get("display"),
                "role": species.role.replace("_", " "),
                "starting_mol": starting,
                "starting_g": starting * species.molar_mass_g_mol,
                "consumed_mol": max(-net_change, 0.0),
                "remaining_mol": ending,
                "remaining_g": ending * species.molar_mass_g_mol,
            }
        )
    return rows


def _reaction_dashboard_cycle_row_status(
    row: Mapping[str, Any],
    *,
    selected: bool = False,
) -> str:
    """Return the semantic table status for one visual cycle row.

    Purpose:
        Bucket cycle rows for Treeview tag coloring.
    Why:
        The dashboard table needs immediate visual scanning for current, complete,
        watch, blocked, and warning states.
    Args:
        row: Cycle metric row containing completion and warning fields.
        selected: True when the row is the active cycle focus.
    Returns:
        Status token used by table tags and display summaries.
    Side Effects:
        None.
    Exceptions:
        Invalid values fall back to a watch/unavailable status.
    """
    if selected:
        return "current"
    warnings = [str(item) for item in list(row.get("warnings") or []) if str(item)]
    if warnings:
        return "warning"
    completion = _safe_float(row.get("completion_pct"))
    if completion is None or not math.isfinite(completion):
        return "blocked"
    if completion >= 95.0:
        return "complete"
    if completion >= 60.0:
        return "watch"
    return "blocked"


def _reaction_dashboard_visual_summary(
    template: ReactionTemplate,
    result: Mapping[str, Any],
    *,
    selected_cycle_id: Optional[Any] = None,
) -> Dict[str, Any]:
    """Build display-focused Reaction Dashboard summary fields.

    Purpose:
        Normalize run results into headline values, visual status buckets, cycle
        rows, and next-action text for the redesigned dashboard.
    Why:
        The UI should remain visual and operational while preserving the existing
        Rust/Python reaction core result contract.
    Args:
        template: Active Reaction Dashboard template.
        result: Dashboard result payload from `_run_reaction_dashboard`.
        selected_cycle_id: Optional cycle id selected by the operator.
    Returns:
        Dict with gas/product metadata, headline metrics, cycle table rows, status
        colors, and next-action text.
    Side Effects:
        None.
    Exceptions:
        Missing result fields are normalized to placeholders.
    """
    core = result.get("core") if isinstance(result.get("core"), Mapping) else {}
    cycle_series = [
        dict(row)
        for row in list(result.get("cycle_series") or [])
        if isinstance(row, Mapping)
    ]
    gas_meta = _reaction_dashboard_species_display(template, template.gas_species_id)
    product_meta = _reaction_dashboard_species_display(
        template, template.yield_basis.product_species_id
    )
    selected_row: Optional[Dict[str, Any]] = None
    selected_id_float = _safe_float(selected_cycle_id)
    if cycle_series:
        if selected_id_float is not None:
            selected_row = next(
                (
                    row
                    for row in cycle_series
                    if _safe_float(row.get("cycle_id")) == selected_id_float
                ),
                None,
            )
        if selected_row is None:
            selected_row = cycle_series[-1]
            selected_id_float = _safe_float(selected_row.get("cycle_id"))
    trend = _reaction_dashboard_cycle_trend(cycle_series)
    headline_gas_mol = (
        _safe_float(selected_row.get("cumulative_gas_mol"))
        if selected_row is not None
        else _safe_float(core.get("gas_uptake_mol"))
    )
    headline_gas_g = (
        _safe_float(selected_row.get("cumulative_gas_g"))
        if selected_row is not None
        else _safe_float(core.get("gas_uptake_g"))
    )
    if headline_gas_g is None and headline_gas_mol is not None:
        gas_mw = _safe_float(gas_meta.get("molar_mass_g_mol"))
        if gas_mw is not None and math.isfinite(gas_mw):
            headline_gas_g = float(headline_gas_mol) * float(gas_mw)
    headline_product_g = (
        _safe_float(selected_row.get("product_mass_g"))
        if selected_row is not None
        else _safe_float(core.get("theoretical_yield_g"))
    )
    headline_product_mol = (
        _safe_float(selected_row.get("product_mol"))
        if selected_row is not None
        else _safe_float(core.get("yield_species_moles"))
    )
    completion_pct = (
        _safe_float(selected_row.get("completion_pct"))
        if selected_row is not None
        else _safe_float(core.get("completion_pct"))
    )
    warnings = [str(item) for item in list(result.get("warnings") or []) if str(item)]
    if warnings:
        status = "watch"
    elif completion_pct is None:
        status = "unavailable"
    elif completion_pct >= 95.0:
        status = "complete"
    elif completion_pct >= 60.0:
        status = "healthy"
    else:
        status = "watch"
    limiting_values: List[str] = []
    for step in list(core.get("step_results") or []):
        if not isinstance(step, Mapping):
            continue
        limiting = str(
            step.get("limiting_species") or step.get("limiting_species_id") or ""
        ).strip()
        if limiting and limiting not in limiting_values:
            limiting_values.append(limiting)
    if warnings:
        next_action = "Review warnings before using product prediction."
    elif completion_pct is None:
        next_action = "Run the dashboard with valid gas and charge inputs."
    elif completion_pct >= 95.0:
        next_action = "Reaction appears near complete by current stoichiometry."
    elif trend.get("label") == "Slowing uptake":
        next_action = "Review whether gas uptake is tapering before adding more gas."
    else:
        next_action = "Continue monitoring gas uptake and cycle trend."
    cycle_rows: List[Dict[str, Any]] = []
    previous_cumulative = 0.0
    for row in cycle_series:
        cumulative = _safe_float(row.get("cumulative_gas_mol"), previous_cumulative)
        delta = _safe_float(row.get("cycle_gas_delta_mol"))
        if delta is None and cumulative is not None:
            delta = max(float(cumulative) - previous_cumulative, 0.0)
        if cumulative is not None:
            previous_cumulative = max(float(cumulative), previous_cumulative)
        is_selected = (
            selected_id_float is not None
            and _safe_float(row.get("cycle_id")) == selected_id_float
        )
        cycle_rows.append(
            {
                "cycle_id": row.get("cycle_id"),
                "gas_delta_mol": delta,
                "cumulative_gas_mol": row.get("cumulative_gas_mol"),
                "cumulative_gas_g": row.get("cumulative_gas_g"),
                "completion_pct": row.get("completion_pct"),
                "product_mass_g": row.get("product_mass_g"),
                "trend": trend.get("label", "--"),
                "warnings": "; ".join(
                    str(item) for item in list(row.get("warnings") or []) if str(item)
                ),
                "status": _reaction_dashboard_cycle_row_status(
                    row, selected=is_selected
                ),
            }
        )
    forecast = _reaction_dashboard_forecast(cycle_series, completion_pct)
    material_inventory = _reaction_dashboard_material_inventory(template, core)
    return {
        "gas": gas_meta,
        "product": product_meta,
        "selected_cycle_id": selected_id_float,
        "headline_gas_consumed_mol": headline_gas_mol,
        "headline_gas_consumed_g": headline_gas_g,
        "headline_product_mass_g": headline_product_g,
        "headline_product_mol": headline_product_mol,
        "completion_pct": completion_pct,
        "actual_yield_pct": _safe_float(core.get("actual_yield_pct")),
        "limiting": ", ".join(limiting_values) if limiting_values else "--",
        "cycle_status": status,
        "cycle_trend": trend,
        "cycle_rows": cycle_rows,
        "forecast": forecast,
        "material_inventory": material_inventory,
        "warnings": warnings,
        "next_action": next_action,
        "status_color": REACTION_DASHBOARD_STATUS_COLORS.get(
            status, REACTION_DASHBOARD_STATUS_COLORS["unavailable"]
        ),
    }


def _resolve_pka2_value(
    temp_c: Optional[float], use_temp_adjusted_constants: bool
) -> float:
    """Resolve pKa2 value.
    Used to compute pKa2 value before rendering or export."""
    temperature = 25.0 if temp_c is None else float(temp_c)
    if use_temp_adjusted_constants:
        return max(
            0.0, _estimate_temperature_adjusted_pka(temperature, SOL_PKA2_COEFFS)
        )
    return -math.log10(SOL_KA2)


def _clamp_ph_value(ph: float) -> float:
    """Clamp pH value.
    Used to keep pH value within safe bounds."""

    return max(0.0, min(ph, 14.3))


def _clamp_analysis_corrected_ph_value(ph: float) -> float:
    """Clamp Analysis corrected pH without hiding concentrated NaOH starts.

    Purpose:
        Preserve physically expected strong-base corrected pH values above the
        generic display clamp used by older pH channels.
    Why:
        Analysis corrected pH can legitimately start near pH 14.8 for
        concentrated NaOH before CO2 has consumed enough hydroxide.
    Inputs:
        ph: Candidate pH value.
    Outputs:
        pH clamped to the Analysis corrected-pH display/calculation range.
    Side Effects:
        None.
    Exceptions:
        Non-finite values are clamped by Python float comparisons.
    """
    return max(0.0, min(float(ph), 15.0))


def _analysis_strong_base_ph_from_corrected_co2(
    *,
    initial_naoh_mol: Optional[float],
    solution_volume_l: Optional[float],
    corrected_cumulative_co2_mol: Optional[float],
    temperature_c: Optional[float],
) -> Optional[float]:
    """Return strong-base pH before CO2 consumes free NaOH.

    Purpose:
        Seed Analysis corrected pH from known NaOH stoichiometry at low CO2
        loading rather than from already-acidified reference rows.
    Why:
        For NaOH + CO2, each mole of CO2 consumes two moles of hydroxide before
        the carbonate equivalence point; corrected pH should remain high while
        free NaOH remains.
    Inputs:
        initial_naoh_mol: Initial NaOH moles.
        solution_volume_l: Process liquor volume in liters.
        corrected_cumulative_co2_mol: Corrected cumulative CO2 uptake in moles.
        temperature_c: Process temperature in Celsius for pKw.
    Outputs:
        Strong-base pH when free hydroxide remains, else None.
    Side Effects:
        None.
    Exceptions:
        Invalid or non-finite inputs return None.
    """
    naoh_mol = _safe_float(initial_naoh_mol)
    volume_l = _safe_float(solution_volume_l)
    co2_mol = _safe_float(corrected_cumulative_co2_mol, 0.0)
    if (
        naoh_mol is None
        or volume_l is None
        or co2_mol is None
        or not math.isfinite(float(naoh_mol))
        or not math.isfinite(float(volume_l))
        or not math.isfinite(float(co2_mol))
        or naoh_mol <= 0.0
        or volume_l <= 0.0
    ):
        return None
    hydroxide_remaining_mol = float(naoh_mol) - (2.0 * max(float(co2_mol), 0.0))
    if hydroxide_remaining_mol <= 1e-12:
        return None
    try:
        pkw = carbonate_pkw_from_temp(float(_safe_float(temperature_c, 25.0) or 25.0))
    except Exception:
        pkw = -math.log10(max(SOL_KW, 1e-30))
    hydroxide_m = max(hydroxide_remaining_mol / float(volume_l), 1e-16)
    return _clamp_analysis_corrected_ph_value(float(pkw) + math.log10(hydroxide_m))


def _estimate_ledger_ph(
    state: dict[str, float],
    pka2_value: float,
    *,
    solution_volume_l: float | None,
    temperature_c: float | None,
    ionic_strength_cap: float | None,
    use_temp_adjusted_constants: bool,
    constants: tuple[float, float, float] | None = None,
    initial_ph_guess: float | None = None,
) -> float:
    """Estimate pH from the reaction ledger's current chemical state.

    Purpose:
        Convert NaOH/carbonate/bicarbonate/excess-CO2 ledger moles into a pH
        estimate for cycle timeline and Analysis raw calculated-pH channels.
    Why:
        The ledger is the owning source for reaction progress. When residual NaOH
        remains, its strong-base hydroxide floor must constrain any carbonate
        charge-balance solve so raw pH does not contradict the reaction state.
    Inputs:
        state: Ledger mapping containing `naoh_remaining_mol`, `na2co3_mol`,
            `nahco3_mol`, and `co2_excess_mol`.
        pka2_value: Carbonate/bicarbonate pKa2 used for buffer fallback.
        solution_volume_l: Liquid volume in liters.
        temperature_c: Temperature in Celsius for pKw/pKa selection.
        ionic_strength_cap: Optional ionic-strength cap for the carbonate solver.
        use_temp_adjusted_constants: Whether temperature-adjusted constants apply.
        constants: Optional `(Ka1, Ka2, Kw)` tuple.
        initial_ph_guess: Optional starting pH for nonlinear solving.
    Outputs:
        float: Clamped pH estimate.
    Side Effects:
        None.
    Exceptions:
        Solver failures fall back to buffer/strong-base estimates.
    """

    ratio = max(
        state.get("na2co3_mol", 0.0) / max(state.get("nahco3_mol", 0.0), 1e-12), 1e-12
    )
    fallback_ph = _clamp_ph_value(pka2_value + math.log10(ratio))

    if solution_volume_l is None or solution_volume_l <= 0:
        return fallback_ph

    total_na = (
        max(state.get("naoh_remaining_mol", 0.0), 0.0)
        + max(state.get("nahco3_mol", 0.0), 0.0)
        + 2.0 * max(state.get("na2co3_mol", 0.0), 0.0)
    )
    total_carbon = (
        max(state.get("nahco3_mol", 0.0), 0.0)
        + max(state.get("na2co3_mol", 0.0), 0.0)
        + max(state.get("co2_excess_mol", 0.0), 0.0)
    )
    total_na_conc = total_na / max(solution_volume_l, 1e-9)
    total_carbon_conc = total_carbon / max(solution_volume_l, 1e-9)

    if total_na_conc <= 0 and total_carbon_conc <= 0:
        return fallback_ph

    if constants is None:
        constants = _basic_carbonate_constants(
            temperature_c, use_temp_adjusted_constants
        )
    ka1, ka2, kw = constants
    pkw = -math.log10(max(kw, 1e-30))
    guess = initial_ph_guess if initial_ph_guess is not None else fallback_ph
    naoh_remaining = max(state.get("naoh_remaining_mol", 0.0), 0.0)
    residual_naoh_ph_floor = None
    if naoh_remaining > 0.0:
        # Residual NaOH is a strong-base ledger term; carbonate equilibrium can
        # raise pH above this floor but must not drive it below the free-OH value.
        residual_oh_m = max(naoh_remaining / max(solution_volume_l, 1e-9), 1e-16)
        residual_naoh_ph_floor = _clamp_ph_value(pkw + math.log10(residual_oh_m))

    try:
        if total_carbon_conc <= 1e-12:
            # No carbonate inventory: treat as a simple strong base solution
            if total_na_conc <= 0:
                return _clamp_ph_value(pkw / 2.0)
            ph = pkw + math.log10(max(total_na_conc, 1e-16))
            if residual_naoh_ph_floor is not None:
                ph = max(ph, residual_naoh_ph_floor)
            return _clamp_ph_value(ph)

        (
            H,
            _,
            _,
            _,
            _,
            _gammas,
            _ionic_strength,
        ) = _solve_carbonate_state(
            total_carbon_conc,
            total_na_conc,
            ka1=ka1,
            ka2=ka2,
            kw=kw,
            ionic_strength_cap=ionic_strength_cap,
            initial_ph_guess=guess,
        )
        ph = -math.log10(max(H, 1e-30))
        ph = _clamp_ph_value(ph)
        if residual_naoh_ph_floor is not None:
            ph = _clamp_ph_value(max(ph, residual_naoh_ph_floor))
        if ph < 6.0 and (
            state.get("nahco3_mol", 0.0) > 0.0 or state.get("co2_excess_mol", 0.0) > 0.0
        ):
            buffer_hint = _clamp_ph_value(max(fallback_ph, pka2_value - 2.2, 8.0))
            if residual_naoh_ph_floor is not None:
                buffer_hint = _clamp_ph_value(max(buffer_hint, residual_naoh_ph_floor))
            return buffer_hint
        return ph
    except Exception:
        if state.get("nahco3_mol", 0.0) > 0.0 or state.get("co2_excess_mol", 0.0) > 0.0:
            buffer_hint = max(fallback_ph, pka2_value - 2.2, 8.0)
            if residual_naoh_ph_floor is not None:
                buffer_hint = max(buffer_hint, residual_naoh_ph_floor)
            return _clamp_ph_value(buffer_hint)
        if residual_naoh_ph_floor is not None:
            return residual_naoh_ph_floor
        return fallback_ph


def _estimate_ledger_ph_planning(
    state: Dict[str, float],
    pka2_value: float,
    *,
    solution_volume_l: Optional[float],
    temperature_c: Optional[float],
    ionic_strength_cap: Optional[float],
    use_temp_adjusted_constants: bool,
    constants: Optional[Tuple[float, float, float]] = None,
    initial_ph_guess: Optional[float] = None,
) -> float:
    """Estimate ledger pH planning.
    Used to approximate ledger pH planning for model workflows."""

    state_for_ph = dict(state)
    co3 = max(state_for_ph.get("na2co3_mol", 0.0), 0.0)
    hco3 = max(state_for_ph.get("nahco3_mol", 0.0), 0.0)
    excess = max(state_for_ph.get("co2_excess_mol", 0.0), 0.0)
    carbonate_only_equivalence = (
        state_for_ph.get("naoh_remaining_mol", 0.0) <= 1e-12
        and co3 > 0.0
        and hco3 <= 1e-12
    )
    carbon_pool = co3 + hco3
    carbonate_depleted = co3 <= PLANNING_PLATEAU_CARBONATE_THRESHOLD or (
        carbon_pool > 0
        and co3 / max(carbon_pool, 1e-12) <= PLANNING_PLATEAU_RELATIVE_THRESHOLD
    )
    state_for_ph["co2_excess_mol"] = excess
    ph_estimate = _estimate_ledger_ph(
        state_for_ph,
        pka2_value,
        solution_volume_l=solution_volume_l,
        temperature_c=temperature_c,
        ionic_strength_cap=ionic_strength_cap,
        use_temp_adjusted_constants=use_temp_adjusted_constants,
        constants=constants,
        initial_ph_guess=initial_ph_guess,
    )
    if (
        carbonate_only_equivalence
        and ph_estimate is not None
        and math.isfinite(ph_estimate)
    ):
        anchor = pka2_value if pka2_value is not None else 10.33
        ph_estimate = _clamp_ph_value(
            min(max(ph_estimate, anchor - 0.35), anchor + 0.35)
        )
    if (
        carbonate_depleted
        and (hco3 > 0 or excess > 0)
        and ph_estimate is not None
        and math.isfinite(ph_estimate)
    ):
        ph_estimate = min(
            max(ph_estimate, PLANNING_PLATEAU_PH_MIN), PLANNING_PLATEAU_PH_MAX
        )
    return ph_estimate


def _simulate_reaction_state_with_accounting(
    ledger: Dict[str, float],
    delta_mol: float,
    pka2_value: float,
    *,
    solution_volume_l: Optional[float] = None,
    temperature_c: Optional[float] = None,
    ionic_strength_cap: Optional[float] = None,
    use_temp_adjusted_constants: bool = False,
    initial_ph_guess: Optional[float] = None,
    constants: Optional[Tuple[float, float, float]] = None,
    planning_mode: bool = False,
) -> Tuple[Dict[str, float], Dict[str, float]]:
    """Perform simulate reaction state with accounting.
    Used to keep the workflow logic localized and testable."""
    resolved_constants = (
        constants
        if constants is not None
        else _basic_carbonate_constants(temperature_c, use_temp_adjusted_constants)
    )

    rust_result = _rust_simulate_reaction_state_with_accounting(
        ledger,
        delta_mol,
        pka2_value,
        solution_volume_l=solution_volume_l,
        temperature_c=temperature_c,
        ionic_strength_cap=ionic_strength_cap,
        use_temp_adjusted_constants=use_temp_adjusted_constants,
        initial_ph_guess=initial_ph_guess,
        constants=resolved_constants,
        planning_mode=planning_mode,
    )
    if rust_result is not None:
        return rust_result

    extra = max(float(delta_mol), 0.0)
    naoh_free = max(ledger.get("naoh_remaining_mol", 0.0), 0.0)
    co3 = max(ledger.get("na2co3_mol", 0.0), 0.0)
    hco3 = max(ledger.get("nahco3_mol", 0.0), 0.0)
    excess = max(ledger.get("co2_excess_mol", 0.0), 0.0)

    consumed_to_carbonate = 0.0
    consumed_to_bicarbonate = 0.0

    if naoh_free > 0:
        needed = naoh_free / 2.0
        consume = min(extra, needed)
        consumed_to_carbonate = consume
        naoh_free = max(0.0, naoh_free - consume * 2.0)
        co3 += consume
        extra -= consume

    if co3 > 0 and extra > 0:
        convert = min(extra, co3)
        consumed_to_bicarbonate = convert
        co3 -= convert
        hco3 += convert * 2.0
        extra -= convert

    excess += extra
    ratio_hint = co3 / max(hco3, 1e-12)
    estimator = _estimate_ledger_ph_planning if planning_mode else _estimate_ledger_ph

    state = {
        "naoh_remaining_mol": naoh_free,
        "na2co3_mol": co3,
        "nahco3_mol": hco3,
        "co2_excess_mol": excess,
    }
    ph_value = estimator(
        state,
        pka2_value,
        solution_volume_l=solution_volume_l,
        temperature_c=temperature_c,
        ionic_strength_cap=ionic_strength_cap,
        use_temp_adjusted_constants=use_temp_adjusted_constants,
        constants=resolved_constants,
        initial_ph_guess=(
            initial_ph_guess
            if initial_ph_guess is not None
            else pka2_value + math.log10(max(ratio_hint, 1e-12))
        ),
    )
    state["ph"] = ph_value
    accounting = {
        "co2_consumed_to_carbonate_mol": consumed_to_carbonate,
        "co2_consumed_to_bicarbonate_mol": consumed_to_bicarbonate,
        "co2_consumed_total_mol": consumed_to_carbonate + consumed_to_bicarbonate,
        "co2_unconsumed_mol": max(extra, 0.0),
    }
    return state, accounting


def _simulate_reaction_state(
    ledger: Dict[str, float],
    delta_mol: float,
    pka2_value: float,
    *,
    solution_volume_l: Optional[float] = None,
    temperature_c: Optional[float] = None,
    ionic_strength_cap: Optional[float] = None,
    use_temp_adjusted_constants: bool = False,
    initial_ph_guess: Optional[float] = None,
    constants: Optional[Tuple[float, float, float]] = None,
) -> Dict[str, float]:
    """Perform simulate reaction state.
    Used to keep the workflow logic localized and testable."""
    state, _ = _simulate_reaction_state_with_accounting(
        ledger,
        delta_mol,
        pka2_value,
        solution_volume_l=solution_volume_l,
        temperature_c=temperature_c,
        ionic_strength_cap=ionic_strength_cap,
        use_temp_adjusted_constants=use_temp_adjusted_constants,
        initial_ph_guess=initial_ph_guess,
        constants=constants,
        planning_mode=False,
    )
    return state


def _regression_test_post_equivalence_ph_trends() -> None:
    """Perform regression test post equivalence pH trends.
    Used to keep the workflow logic localized and testable."""
    temp_c = 25.0
    use_temp_adjusted = False
    pka2_value = _resolve_pka2_value(temp_c, use_temp_adjusted)
    constants = _basic_carbonate_constants(temp_c, use_temp_adjusted)
    volume_l = 1.0
    sodium_basis_mol = 1.0

    # Closure captures _regression_test_post_equivalence_ph_trends local context to keep helper logic scoped and invoked directly within _regression_test_post_equivalence_ph_trends.
    def _ledger_state_for_fraction(fraction: float) -> Tuple[Dict[str, float], float]:
        """Perform ledger state for fraction.
        Used to keep the workflow logic localized and testable."""
        ledger_state = _ledger_from_sodium_and_carbonate_fraction(
            sodium_basis_mol, fraction
        )
        ph_val = _estimate_ledger_ph(
            ledger_state,
            pka2_value,
            solution_volume_l=volume_l,
            temperature_c=temp_c,
            ionic_strength_cap=None,
            use_temp_adjusted_constants=use_temp_adjusted,
            constants=constants,
        )
        if ph_val is None or not math.isfinite(ph_val):
            raise AssertionError(
                f"Ledger fraction {fraction:.3f}: pH estimation failed."
            )
        return ledger_state, ph_val

    ledger_119, baseline_ph = _ledger_state_for_fraction(0.119)
    assert abs(baseline_ph - 9.46) < 0.05, f"Expected ~9.46 pH, got {baseline_ph:.3f}"

    ledger_5, ph_5pct = _ledger_state_for_fraction(0.05)
    assert ph_5pct < 9.2, f"5% carbonate state should be <9.2 pH (got {ph_5pct:.3f})"

    ledger_2, ph_2pct = _ledger_state_for_fraction(0.02)
    assert (
        ph_2pct <= 8.65
    ), f"2% carbonate state should trend below ~8.6 pH (got {ph_2pct:.3f})"

    # Projection-style regression: consume carbonate, accumulate dissolved CO2, and approach pH ~8
    increments = [0.05] * 8
    ledger = dict(ledger_119)
    previous_carbonate = ledger["na2co3_mol"]
    previous_excess = ledger.get("co2_excess_mol", 0.0)
    co2_excess_seen = False
    ph_trace: List[float] = []
    ph_guess = baseline_ph
    # Iterate over increments to apply the per-item logic.
    for delta in increments:
        state = _simulate_reaction_state(
            ledger,
            delta,
            pka2_value,
            solution_volume_l=volume_l,
            temperature_c=temp_c,
            ionic_strength_cap=None,
            use_temp_adjusted_constants=use_temp_adjusted,
            constants=constants,
            initial_ph_guess=ph_guess,
        )
        ph_guess = state.get("ph", ph_guess)
        ph_val = state.get("ph")
        if ph_val is None or not math.isfinite(ph_val):
            raise AssertionError("Projection regression: invalid pH state.")
        ph_trace.append(ph_val)
        co3_now = state.get("na2co3_mol", 0.0)
        excess_now = state.get("co2_excess_mol", 0.0)
        assert (
            co3_now <= previous_carbonate + 1e-9
        ), "Carbonate did not decrease monotonically."
        assert (
            excess_now + 1e-9 >= previous_excess
        ), "Excess CO2 should not decrease once formed."
        co2_excess_seen = co2_excess_seen or excess_now > 0
        previous_carbonate = co3_now
        previous_excess = excess_now
        ledger = {
            "naoh_remaining_mol": max(state.get("naoh_remaining_mol", 0.0), 0.0),
            "na2co3_mol": max(co3_now, 0.0),
            "nahco3_mol": max(state.get("nahco3_mol", 0.0), 0.0),
            "co2_excess_mol": max(excess_now, 0.0),
        }

    if not any(val < 9.0 for val in ph_trace):
        raise AssertionError("Projection regression: pH did not drop below 9.0.")
    if not any(val < 8.5 for val in ph_trace):
        raise AssertionError("Projection regression: pH did not drop below 8.5.")
    if not co2_excess_seen:
        raise AssertionError("Projection regression: excess CO2 never accumulated.")
    final_ph = ph_trace[-1]
    assert (
        final_ph <= 8.3
    ), f"Projection regression: final pH should approach ~8 (got {final_ph:.3f})."

    print(
        "Post-equivalence regression:",
        f"11.9% pH={baseline_ph:.3f}",
        f"5% pH={ph_5pct:.3f}",
        f"2% pH={ph_2pct:.3f}",
        f"projection min pH={min(ph_trace):.3f}",
        f"projection final pH={final_ph:.3f}",
    )


def _regression_test_residual_naoh_enforces_alkaline_raw_ph_floor() -> None:
    """Validate residual NaOH prevents impossible low raw calculated pH.

    Purpose:
        Guard the ledger pH estimator and cycle-accounting path used by Analysis
        raw calculated-pH rows.
    Why:
        A measured anchor near pH 10 with residual NaOH exposed a defect where
        carbonate charge balance could report raw calculated pH below 8 even
        though free NaOH remained in the ledger.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Executes deterministic in-memory chemistry calculations only.
    Exceptions:
        Raises AssertionError when residual strong-base chemistry no longer
        constrains raw pH estimates.
    """
    temp_c = 25.0
    use_temp_adjusted = False
    constants = _basic_carbonate_constants(temp_c, use_temp_adjusted)
    pka2_value = _resolve_pka2_value(temp_c, use_temp_adjusted)
    volume_l = 1.0
    residual_naoh_mol = 1.0e-5
    pkw = -math.log10(max(constants[2], 1e-30))
    expected_floor = _clamp_ph_value(pkw + math.log10(residual_naoh_mol / volume_l))
    stressed_state = {
        "naoh_remaining_mol": residual_naoh_mol,
        "na2co3_mol": 0.0,
        "nahco3_mol": 0.35,
        "co2_excess_mol": 0.40,
    }
    estimated_ph = _estimate_ledger_ph(
        stressed_state,
        pka2_value,
        solution_volume_l=volume_l,
        temperature_c=temp_c,
        ionic_strength_cap=None,
        use_temp_adjusted_constants=use_temp_adjusted,
        constants=constants,
        initial_ph_guess=7.2,
    )
    if estimated_ph < expected_floor - 1e-9:
        raise AssertionError(
            f"Residual NaOH pH floor failed: expected >= {expected_floor:.3f}, "
            f"got {estimated_ph:.3f}."
        )
    if estimated_ph < 8.0:
        raise AssertionError(
            f"Residual-NaOH raw pH should stay alkaline, got {estimated_ph:.3f}."
        )

    ledger = {
        "naoh_remaining_mol": 1.0,
        "na2co3_mol": 0.0,
        "nahco3_mol": 0.0,
        "co2_excess_mol": 0.0,
    }
    state, accounting = _simulate_reaction_state_with_accounting(
        ledger,
        0.499995,
        pka2_value,
        solution_volume_l=volume_l,
        temperature_c=temp_c,
        ionic_strength_cap=None,
        use_temp_adjusted_constants=use_temp_adjusted,
        initial_ph_guess=13.0,
        constants=constants,
        planning_mode=False,
    )
    if state.get("naoh_remaining_mol", 0.0) <= 0.0:
        raise AssertionError(f"Test setup should retain NaOH, got state {state!r}.")
    if state.get("ph", 0.0) < 8.0:
        raise AssertionError(
            f"Cycle accounting produced low raw pH with NaOH: {state!r}."
        )
    if accounting.get("co2_consumed_total_mol", 0.0) <= 0.0:
        raise AssertionError(
            f"Cycle accounting should consume CO2, got {accounting!r}."
        )


def _planning_projection_trace(
    *,
    initial_naoh_mol: float,
    cycle_moles: float,
    volume_l: float,
    temp_c: float,
    stop_ph: float = PLANNING_DEFAULT_STOP_PH,
    stop_added_g: float = PLANNING_DEFAULT_STOP_CO2_ADDED_G,
    max_cycles: int = 240,
    respect_stop_ph: bool = True,
) -> Dict[str, Any]:
    """Perform planning projection trace.
    Used to keep the workflow logic localized and testable."""

    pka2_value = _resolve_pka2_value(temp_c, False)
    constants = _basic_carbonate_constants(temp_c, False)
    ledger = {
        "naoh_remaining_mol": initial_naoh_mol,
        "na2co3_mol": 0.0,
        "nahco3_mol": 0.0,
        "co2_excess_mol": 0.0,
    }
    ph_trace: List[float] = []
    carbonate_trace: List[float] = []
    h2co3_trace: List[float] = []
    rows: List[Dict[str, Any]] = []
    cumulative_added_moles = 0.0
    cumulative_consumed_moles = 0.0
    stop_index: Optional[int] = None
    stop_added_mass_g: Optional[float] = None
    stop_consumed_mass_g: Optional[float] = None
    depletion_index: Optional[int] = None
    added_mass_g = 0.0
    consumed_mass_g = 0.0
    # Iterate over the configured range to apply the per-item logic.
    for idx in range(1, max_cycles + 1):
        cumulative_added_moles += cycle_moles
        state, accounting = _simulate_reaction_state_with_accounting(
            ledger,
            cycle_moles,
            pka2_value,
            solution_volume_l=volume_l,
            temperature_c=temp_c,
            ionic_strength_cap=None,
            use_temp_adjusted_constants=False,
            initial_ph_guess=ph_trace[-1] if ph_trace else None,
            constants=constants,
            planning_mode=True,
        )
        ledger = {
            "naoh_remaining_mol": max(state.get("naoh_remaining_mol", 0.0), 0.0),
            "na2co3_mol": max(state.get("na2co3_mol", 0.0), 0.0),
            "nahco3_mol": max(state.get("nahco3_mol", 0.0), 0.0),
            "co2_excess_mol": max(state.get("co2_excess_mol", 0.0), 0.0),
        }
        ph_val = state.get("ph")
        if ph_val is None or not math.isfinite(ph_val):
            raise AssertionError("Planning projection produced an invalid pH value.")
        ph_trace.append(ph_val)
        carbonate_trace.append(ledger["na2co3_mol"])
        consumed_cycle = accounting.get("co2_consumed_total_mol", 0.0)
        cumulative_consumed_moles += consumed_cycle
        added_mass_g = cumulative_added_moles * SOL_MW_CO2
        consumed_mass_g = cumulative_consumed_moles * SOL_MW_CO2
        carbon_pool = (
            ledger["na2co3_mol"]
            + ledger["nahco3_mol"]
            + ledger.get("co2_excess_mol", 0.0)
        )
        h2co3_frac = (
            ledger.get("co2_excess_mol", 0.0) / carbon_pool if carbon_pool > 0 else 0.0
        )
        h2co3_trace.append(h2co3_frac)
        regime_label = "naoh_to_carbonate"
        if ledger["naoh_remaining_mol"] <= 1e-12:
            regime_label = "carbonate_to_bicarbonate"
            if ledger["na2co3_mol"] <= PLANNING_PLATEAU_CARBONATE_THRESHOLD:
                regime_label = "excess_co2"
        rows.append(
            {
                "cycle": idx,
                "delta_added_g": cycle_moles * SOL_MW_CO2,
                "cumulative_added_g": added_mass_g,
                "delta_consumed_g": consumed_cycle * SOL_MW_CO2,
                "cumulative_consumed_g": consumed_mass_g,
                "naoh_mol": ledger["naoh_remaining_mol"],
                "na2co3_mol": ledger["na2co3_mol"],
                "nahco3_mol": ledger["nahco3_mol"],
                "co2_excess_mol": ledger["co2_excess_mol"],
                "ph": ph_val,
                "regime": regime_label,
                "h2co3_fraction": h2co3_frac,
            }
        )
        if (
            depletion_index is None
            and ledger["na2co3_mol"] <= PLANNING_PLATEAU_CARBONATE_THRESHOLD
        ):
            depletion_index = idx
        if stop_index is None and ph_val <= stop_ph + 1e-12:
            stop_index = idx
            stop_added_mass_g = added_mass_g
            stop_consumed_mass_g = consumed_mass_g
        if respect_stop_ph and stop_index is not None:
            break
        if added_mass_g >= stop_added_g - 1e-12:
            break
    return {
        "rows": rows,
        "ph_trace": ph_trace,
        "carbonate_trace": carbonate_trace,
        "h2co3_trace": h2co3_trace,
        "stop_index": stop_index,
        "stop_added_mass_g": stop_added_mass_g,
        "stop_consumed_mass_g": stop_consumed_mass_g,
        "depletion_index": depletion_index,
        "final_added_mass_g": added_mass_g,
        "final_consumed_mass_g": consumed_mass_g,
    }


def _format_planning_cycle_table(
    rows: Sequence[Dict[str, float]], limit: int = 12
) -> str:
    """Format planning cycle table.
    Used to prepare planning cycle table for display or export."""
    headers = [
        "cyc",
        "Δg",
        "Σg",
        "Δrxn",
        "Σrxn",
        "NaOH",
        "CO3",
        "HCO3",
        "CO2x",
        "pH",
        "regime",
    ]
    lines = [" | ".join(f"{h:>6}" for h in headers)]
    display_rows = rows[:limit]
    if len(rows) > limit:
        display_rows.append(
            {
                "cycle": "...",
                "delta_added_g": None,
                "cumulative_added_g": None,
                "delta_consumed_g": None,
                "cumulative_consumed_g": None,
                "naoh_mol": None,
                "na2co3_mol": None,
                "nahco3_mol": None,
                "co2_excess_mol": None,
                "ph": None,
                "regime": "...",
            }
        )
    # Iterate over display_rows to apply the per-item logic.
    for row in display_rows:
        if row.get("cycle") == "...":
            lines.append(" ... (truncated)")
            continue
        lines.append(
            " | ".join(
                [
                    f"{int(row['cycle']):6d}",
                    f"{row['delta_added_g']:.2f}",
                    f"{row['cumulative_added_g']:.2f}",
                    f"{row['delta_consumed_g']:.2f}",
                    f"{row['cumulative_consumed_g']:.2f}",
                    f"{row['naoh_mol']:.3f}",
                    f"{row['na2co3_mol']:.3f}",
                    f"{row['nahco3_mol']:.3f}",
                    f"{row['co2_excess_mol']:.3f}",
                    f"{row['ph']:.3f}",
                    f"{row['regime']:>6}",
                ]
            )
        )
    return "\n".join(lines)


def _regression_test_planning_equivalence_definition() -> None:
    """Perform regression test planning equivalence definition.
    Used to keep the workflow logic localized and testable."""

    temp_c = 25.0
    use_temp_adjusted = False
    pka2_value = _resolve_pka2_value(temp_c, use_temp_adjusted)
    constants = _basic_carbonate_constants(temp_c, use_temp_adjusted)
    volume_l = 2.0
    naoh_initial_mol = 10.0
    n_eq = naoh_initial_mol / 2.0
    ledger = {
        "naoh_remaining_mol": naoh_initial_mol,
        "na2co3_mol": 0.0,
        "nahco3_mol": 0.0,
        "co2_excess_mol": 0.0,
    }
    state, accounting = _simulate_reaction_state_with_accounting(
        ledger,
        n_eq,
        pka2_value,
        solution_volume_l=volume_l,
        temperature_c=temp_c,
        ionic_strength_cap=None,
        use_temp_adjusted_constants=use_temp_adjusted,
        constants=constants,
        planning_mode=True,
    )
    ph_eq = state.get("ph")
    assert ph_eq is not None and math.isfinite(
        ph_eq
    ), "Equivalence pH estimation failed."
    assert (
        abs(accounting.get("co2_consumed_total_mol", 0.0) - n_eq) < 1e-6
    ), "Stage 1 stoichiometry failed at equivalence."
    assert (
        state.get("naoh_remaining_mol", 0.0) <= 1e-9
    ), "NaOH should be consumed at equivalence."
    assert (
        abs(state.get("na2co3_mol", 0.0) - n_eq) < 1e-6
    ), "Carbonate ledger at equivalence is incorrect."
    assert (
        abs(ph_eq - 10.33) < 0.35
    ), f"Equivalence pH should be ~10.33 (got {ph_eq:.2f})."
    print(f"Equivalence regression: n_eq={n_eq:.2f} mol, pH={ph_eq:.3f}")


def _regression_test_planning_post_equivalence_decline() -> None:
    """Perform regression test planning post equivalence decline.
    Used to keep the workflow logic localized and testable."""

    temp_c = 25.0
    volume_l = 2.5
    initial_naoh_mol = 700.0 / SOL_MW_NAOH  # default UI basis
    cycle_moles = UnifiedApp._planning_cycle_moles_from_pressure(
        None, 250.0, 1.0, temp_c
    )
    trace = _planning_projection_trace(
        initial_naoh_mol=initial_naoh_mol,
        cycle_moles=cycle_moles,
        volume_l=volume_l,
        temp_c=temp_c,
        respect_stop_ph=False,
    )
    ph_trace = trace["ph_trace"]
    carbonate_trace = trace["carbonate_trace"]
    rows = trace["rows"]
    eq_cross_idx = next(
        (i for i, row in enumerate(rows) if row["naoh_mol"] <= 1e-9), None
    )
    assert eq_cross_idx is not None, "Equivalence was never crossed in regression."
    if eq_cross_idx + 1 < len(rows):
        before = rows[eq_cross_idx]
        after = rows[eq_cross_idx + 1]
        delta_co3 = before["na2co3_mol"] - after["na2co3_mol"]
        delta_hco3 = after["nahco3_mol"] - before["nahco3_mol"]
        if delta_co3 > 1e-8:
            ratio = delta_hco3 / max(delta_co3, 1e-12)
            assert (
                1.8 <= ratio <= 2.2
            ), f"Stage 2 stoichiometry off (ratio {ratio:.3f})."
    post_eq_carbonate = carbonate_trace[eq_cross_idx:]
    # Iterate over paired elements from multiple sequences to apply the per-item logic.
    for before, after in zip(post_eq_carbonate, post_eq_carbonate[1:]):
        assert (
            after <= before + 1e-9
        ), "Carbonate did not decrease monotonically after equivalence."
    post_eq_ph = ph_trace[eq_cross_idx:]
    assert any(
        val < 9.0 for val in post_eq_ph
    ), "Post-equivalence pH never left the carbonate buffer region."
    assert (
        post_eq_ph[-1] < ph_trace[eq_cross_idx]
    ), "Post-equivalence pH did not decline."
    assert any(
        row.get("h2co3_fraction", 0.0) > 0 for row in rows[eq_cross_idx:]
    ), "H2CO3 fraction never rose post-equivalence."


def _regression_test_planning_convergence_window() -> None:
    """Perform regression test planning convergence window.
    Used to keep the workflow logic localized and testable."""

    temp_c = 25.0
    volume_l = 2.5
    initial_naoh_mol = 700.0 / SOL_MW_NAOH
    cycle_moles = UnifiedApp._planning_cycle_moles_from_pressure(
        None, 250.0, 1.0, temp_c
    )
    trace = _planning_projection_trace(
        initial_naoh_mol=initial_naoh_mol,
        cycle_moles=cycle_moles,
        volume_l=volume_l,
        temp_c=temp_c,
        respect_stop_ph=True,
    )
    stop_idx = trace.get("stop_index")
    assert stop_idx is not None, "Planning projection did not reach the pH stop."
    stop_added_mass = trace.get("stop_added_mass_g") or 0.0
    stop_consumed_mass = trace.get("stop_consumed_mass_g") or 0.0
    assert (
        stop_added_mass < PLANNING_DEFAULT_STOP_CO2_ADDED_G
    ), "pH stop exceeded the CO2 added cap."
    if not (750.0 <= stop_consumed_mass <= 1500.0):
        table = _format_planning_cycle_table(trace["rows"][:stop_idx])
        raise AssertionError(
            f"pH<=8.25 occurred after {stop_consumed_mass:.1f} g CO₂ consumed (expected 750–1500 g).\n{table}"
        )
    assert trace["ph_trace"][stop_idx - 1] <= PLANNING_DEFAULT_STOP_PH + 1e-12


def _regression_test_planning_post_carbonate_stability() -> None:
    """Perform regression test planning post carbonate stability.
    Used to keep the workflow logic localized and testable."""

    temp_c = 25.0
    volume_l = 2.5
    initial_naoh_mol = 700.0 / SOL_MW_NAOH
    cycle_moles = UnifiedApp._planning_cycle_moles_from_pressure(
        None, 250.0, 1.0, temp_c
    )
    trace = _planning_projection_trace(
        initial_naoh_mol=initial_naoh_mol,
        cycle_moles=cycle_moles,
        volume_l=volume_l,
        temp_c=temp_c,
        respect_stop_ph=False,
    )
    dep_idx = trace.get("depletion_index")
    assert dep_idx is not None, "Carbonate was never depleted in planning projection."
    tail_ph = trace["ph_trace"][dep_idx - 1 : dep_idx + 6]
    if len(tail_ph) >= 2:
        drift = max(tail_ph) - min(tail_ph)
        assert (
            drift < 0.05
        ), f"Post-carbonate pH drift exceeded tolerance ({drift:.3f})."
    else:
        raise AssertionError(
            "Insufficient post-depletion cycles to evaluate stability."
        )


def _regression_test_planning_input_wiring() -> None:
    """Perform regression test planning input wiring.
    Used to keep the workflow logic localized and testable."""

    delta_psi = 150.0
    temp_c = 25.0
    small_volume_moles = UnifiedApp._planning_cycle_moles_from_pressure(
        None, delta_psi, 1.0, temp_c
    )
    large_volume_moles = UnifiedApp._planning_cycle_moles_from_pressure(
        None, delta_psi, 2.0, temp_c
    )
    assert (
        small_volume_moles > 0
    ), "Computed moles for the small volume must be positive."
    ratio = large_volume_moles / small_volume_moles
    assert 1.9 < ratio < 2.1, f"Headspace scaling failed (ratio {ratio:.3f})."
    print(
        f"Headspace wiring regression: 1 L -> {small_volume_moles:.4f} mol, 2 L -> {large_volume_moles:.4f} mol"
    )


def _regression_test_planning_tail_ph_band() -> None:
    """Perform regression test planning tail pH band.
    Used to keep the workflow logic localized and testable."""

    temp_c = 25.0
    volume_l = 2.5
    initial_naoh_mol = 700.0 / SOL_MW_NAOH
    pka2_value = _resolve_pka2_value(temp_c, False)
    constants = _basic_carbonate_constants(temp_c, False)
    ledger = _ledger_from_sodium_and_carbonate_fraction(initial_naoh_mol, 0.02)
    ph_value = _estimate_ledger_ph_planning(
        ledger,
        pka2_value,
        solution_volume_l=volume_l,
        temperature_c=temp_c,
        ionic_strength_cap=None,
        use_temp_adjusted_constants=False,
        constants=constants,
        initial_ph_guess=8.2,
    )
    assert ph_value is not None and math.isfinite(
        ph_value
    ), "Planning tail pH solve failed."
    assert (
        8.05 <= ph_value <= 8.35
    ), f"Planning 2% carbonate pH should be ~8.1-8.3 (got {ph_value:.3f})."
    print(f"Planning tail regression: pH@2% carbonate = {ph_value:.3f}")


def _regression_test_planning_mass_balance_and_progression() -> None:
    """Perform regression test planning mass balance and progression.
    Used to keep the workflow logic localized and testable."""

    temp_c = 25.0
    volume_l = 2.5
    initial_naoh_mol = 700.0 / SOL_MW_NAOH
    cycle_moles = UnifiedApp._planning_cycle_moles_from_pressure(
        None, 250.0, 1.0, temp_c
    )
    trace = _planning_projection_trace(
        initial_naoh_mol=initial_naoh_mol,
        cycle_moles=cycle_moles,
        volume_l=volume_l,
        temp_c=temp_c,
        respect_stop_ph=True,
    )
    rows = trace["rows"]
    assert rows, "Planning projection returned no rows."
    total_added_calc = sum(row.get("delta_added_g", 0.0) for row in rows)
    cumulative_added = rows[-1].get("cumulative_added_g", 0.0)
    tol = max(1e-6 * max(cumulative_added, 1.0), 1e-3)
    assert (
        abs(total_added_calc - cumulative_added) <= tol
    ), f"CO2 bookkeeping mismatch: sum {total_added_calc:.4f} g vs cumulative {cumulative_added:.4f} g."
    eq_idx = next(
        (i for i, row in enumerate(rows) if row.get("naoh_mol", 0.0) <= 1e-9), None
    )
    assert eq_idx is not None, "Equivalence was never reached in planning projection."
    # Iterate over rows[eq_idx to apply the per-item logic.
    for row in rows[eq_idx:]:
        assert (
            row.get("naoh_mol", 0.0) <= 1e-9
        ), "NaOH should not reappear after equivalence."
    frac_series: List[float] = []
    # Iterate over rows[eq_idx to apply the per-item logic.
    for row in rows[eq_idx:]:
        pool = (
            row.get("na2co3_mol", 0.0)
            + row.get("nahco3_mol", 0.0)
            + row.get("co2_excess_mol", 0.0)
        )
        frac_series.append(
            row.get("na2co3_mol", 0.0) / max(pool, 1e-12) if pool > 0 else 0.0
        )
    # Iterate over paired elements from multiple sequences to apply the per-item logic.
    for before, after in zip(frac_series, frac_series[1:]):
        assert after <= before + 1e-9, "Carbonate fraction increased after equivalence."
    assert (
        frac_series[-1] <= 0.02
    ), f"Carbonate fraction did not approach zero (final {frac_series[-1]:.4f})."
    stop_added = (
        trace.get("stop_added_mass_g") or trace.get("final_added_mass_g") or 0.0
    )
    assert (
        stop_added <= PLANNING_DEFAULT_STOP_CO2_ADDED_G + 1e-6
    ), "Planning exceeded CO2 added cap."
    stop_idx = trace.get("stop_index") or len(trace.get("ph_trace", []))
    ph_trace = trace.get("ph_trace", [])
    if ph_trace and stop_idx > 0:
        final_ph = ph_trace[min(stop_idx, len(ph_trace)) - 1]
        assert (
            final_ph <= PLANNING_DEFAULT_STOP_PH + 1e-6
        ), "Planning pH stop not achieved within cap."
    print(
        f"Planning mass-balance regression: cycles={len(rows)}, final frac={frac_series[-1]:.4f}, "
        f"final added={stop_added:.2f} g"
    )


class _PlanningPayloadHarness:
    def __init__(self, spec_key: str, ph_key: str, use_same: bool) -> None:
        """Initialize _PlanningPayloadHarness instance.
        Used at object creation to configure initial state and bindings."""
        self._planning_use_same_model = bool(use_same)
        self._planning_spec_model_key = spec_key
        self._planning_ph_model_key = ph_key
        self._sol_model_key = spec_key
        self._normalize_speciation_model_key = (
            UnifiedApp._normalize_speciation_model_key.__get__(self, UnifiedApp)
        )
        self._resolve_planning_model_keys = (
            UnifiedApp._resolve_planning_model_keys.__get__(self, UnifiedApp)
        )
        self._resolve_workflow_model_keys = (
            UnifiedApp._resolve_workflow_model_keys.__get__(self, UnifiedApp)
        )
        self._workflow_model_attribute_keys = (
            UnifiedApp._workflow_model_attribute_keys.__get__(self, UnifiedApp)
        )
        self._workflow_model_setting_keys = (
            UnifiedApp._workflow_model_setting_keys.__get__(self, UnifiedApp)
        )
        self._canonicalize_planning_inputs = (
            UnifiedApp._canonicalize_planning_inputs.__get__(self, UnifiedApp)
        )
        self._scrub_planning_measured_fields = (
            UnifiedApp._scrub_planning_measured_fields.__get__(self, UnifiedApp)
        )
        self._planning_cycle_moles_from_pressure = (
            UnifiedApp._planning_cycle_moles_from_pressure.__get__(self, UnifiedApp)
        )
        self._generate_planning_cycle_payload = (
            UnifiedApp._generate_planning_cycle_payload.__get__(self, UnifiedApp)
        )


def _run_naoh_pitzer_internal_tests() -> None:
    """Run NaOH Pitzer internal tests.
    Used to execute NaOH Pitzer internal tests and coordinate results."""
    if _NAOH_PITZER_MODULE is None:
        raise AssertionError("NaOH-CO2 Pitzer module not available.")
    params = _load_naoh_pitzer_params()
    if params is None:
        raise AssertionError("NaOH-CO2 Pitzer parameters could not be loaded.")
    cfg = _NAOH_PITZER_MODULE.SystemConfig(
        water_mL=2200.0,
        naoh_g=700.0,
        temperature_C=25.0,
        headspace_L=10.0,
        P_high_psig=750.0,
        dP_psig=75.0,
    )
    _NAOH_PITZER_MODULE.run_internal_tests(params, cfg)


def _integration_test_planning_pitzer_smoke() -> None:
    """Perform integration test planning Pitzer smoke.
    Used to keep the workflow logic localized and testable."""
    model_key = "naoh_co2_pitzer_hmw"
    available = {model.key for model in list_speciation_models()}
    if model_key not in available:
        raise AssertionError("NaOH-CO2 Pitzer model not registered.")
    harness = _PlanningPayloadHarness(model_key, model_key, True)
    form_data = {
        "workflow_key": "Planning",
        "mass_naoh_g": 700.0,
        "water_mass_g": 2200.0,
        "solution_volume_l": 2.2,
        "temperature_c": 25.0,
        "planning_cycle_delta_p_psi": 75.0,
        "planning_headspace_volume_l": 10.0,
        "planning_headspace_pressure_high_psi": 750.0,
        "planning_cycle_co2_g": None,
        "planning_stop_co2_added_g": 2000.0,
        "planning_stop_ph": 8.25,
        "planning_spec_model_key": model_key,
        "planning_ph_model_key": model_key,
        "planning_use_same_model": True,
    }
    params = SolubilityInputs(
        mass_na_hco3_g=1.0,
        water_mass_g=2200.0,
        solution_volume_l=2.2,
        temperature_c=25.0,
        initial_ph_guess=8.35,
        forced_ph_target=None,
        use_temperature_adjusted_constants=False,
        ionic_strength_cap=None,
        headspace_pco2_atm=None,
        headspace_kh_m_per_atm=None,
        degassed_fraction=0.0,
        headspace_volume_l=10.0,
        speciation_mode=SPEC_MODE_FIXED_PCO2,
    )
    solver_inputs = SolubilitySolverInputs(
        params=params,
        forced_target=None,
        sweep_low=SOL_PH_SWEEP_DEFAULT[0],
        sweep_high=SOL_PH_SWEEP_DEFAULT[1],
        sweep_steps=SOL_PH_SWEEP_DEFAULT[2],
        reaction_naoh_mass=None,
        reaction_solution_volume=None,
        reaction_co2_g=None,
        reaction_final_ph=None,
        reaction_slurry_ph=None,
        reaction_target_ph=None,
        measured_ph_cycle_index=None,
        measured_ph_value=None,
        measured_ph_anchors=[],
        measured_ph_anchor_enabled=False,
        diagnostic_data=None,
        mode_key="nahco3_dissolution",
        model_key=model_key,
        model_options=None,
        guide_key="nahco3_dissolution",
        workflow_key="Planning",
        assumed_solution_volume_l=None,
        failing_ph=None,
        solvent_basis=None,
        solvent_basis_value=None,
    )
    payload = harness._generate_planning_cycle_payload(form_data, solver_inputs)
    if not payload:
        raise AssertionError("Planning payload generation failed.")
    cycles = payload.get("cycle_transfer") or []
    ph_values = [
        entry.get("ph_after") for entry in cycles if entry.get("ph_after") is not None
    ]
    if not ph_values:
        raise AssertionError("No planning pH values were generated.")
    first_ph = ph_values[0]
    assert first_ph >= 13.5, f"Expected initial pH >= 13.5 (got {first_ph:.3f})."
    # Iterate over paired elements from multiple sequences to apply the per-item logic.
    for prev, curr in zip(ph_values, ph_values[1:]):
        assert curr <= prev + 0.05, "Planning pH is not decreasing smoothly."
    target_entry = min(
        cycles,
        key=lambda entry: abs((entry.get("cumulative_co2_mass_g") or 0.0) - 900.0),
    )
    target_ph = target_entry.get("ph_after")
    if target_ph is None:
        raise AssertionError("Missing pH near 900 g CO2.")
    assert (
        7.7 <= target_ph <= 8.6
    ), f"Expected pH ~7.7-8.6 near 900 g CO2 (got {target_ph:.3f})."


