def _regression_test_analysis_progress_overlay() -> None:
    """Perform regression test analysis progress overlay.
    Used to keep the workflow logic localized and testable."""
    model_key = DEFAULT_SPEC_MODEL_KEY
    harness = _PlanningPayloadHarness(model_key, model_key, True)
    form_data = {
        "workflow_key": "Planning",
        "mass_naoh_g": 700.0,
        "water_mass_g": 2200.0,
        "solution_volume_l": 2.2,
        "temperature_c": 25.0,
        "planning_cycle_delta_p_psi": 75.0,
        "planning_headspace_volume_l": 10.0,
        "planning_headspace_pressure_high_psi": 750.0,
        "planning_cycle_co2_g": None,
        "planning_stop_co2_added_g": 2000.0,
        "planning_stop_ph": 8.25,
        "planning_spec_model_key": model_key,
        "planning_ph_model_key": model_key,
        "planning_use_same_model": True,
    }
    params = SolubilityInputs(
        mass_na_hco3_g=1.0,
        water_mass_g=2200.0,
        solution_volume_l=2.2,
        temperature_c=25.0,
        initial_ph_guess=8.35,
        forced_ph_target=None,
        use_temperature_adjusted_constants=False,
        ionic_strength_cap=None,
        headspace_pco2_atm=None,
        headspace_kh_m_per_atm=None,
        degassed_fraction=0.0,
        headspace_volume_l=10.0,
        speciation_mode=SPEC_MODE_FIXED_PCO2,
    )
    solver_inputs = SolubilitySolverInputs(
        params=params,
        forced_target=None,
        sweep_low=SOL_PH_SWEEP_DEFAULT[0],
        sweep_high=SOL_PH_SWEEP_DEFAULT[1],
        sweep_steps=SOL_PH_SWEEP_DEFAULT[2],
        reaction_naoh_mass=None,
        reaction_solution_volume=None,
        reaction_co2_g=None,
        reaction_final_ph=None,
        reaction_slurry_ph=None,
        reaction_target_ph=None,
        measured_ph_cycle_index=None,
        measured_ph_value=None,
        measured_ph_anchors=[],
        measured_ph_anchor_enabled=False,
        diagnostic_data=None,
        mode_key="nahco3_dissolution",
        model_key=model_key,
        model_options=None,
        guide_key=SOL_DEFAULT_SIM_MODE,
        workflow_key="Planning",
        assumed_solution_volume_l=None,
        failing_ph=None,
        solvent_basis=None,
        solvent_basis_value=None,
    )
    payload = harness._generate_planning_cycle_payload(form_data, solver_inputs)
    if not payload or not payload.get("cycle_transfer"):
        raise AssertionError("Planning payload missing from analysis overlay test.")
    cycles = payload["cycle_transfer"]
    x_series = []
    ph_series = []
    # Iterate over cycles to apply the per-item logic.
    for entry in cycles:
        x_val = _safe_float(entry.get("cumulative_co2_added_mass_g"))
        if x_val is None:
            x_val = _safe_float(entry.get("cumulative_co2_mass_g"))
        if x_val is None or not math.isfinite(x_val):
            continue
        x_series.append(x_val)
        ph_series.append(entry.get("ph_after"))
    if not x_series:
        raise AssertionError("Planning trace missing CO2 totals.")
    final_co2_g = x_series[-1]
    initial_naoh_mol = 700.0 / SOL_MW_NAOH
    eq_co2_g = (initial_naoh_mol / 2.0) * SOL_MW_CO2
    low_point = max(eq_co2_g * 0.2, x_series[0])
    high_point = min(final_co2_g, eq_co2_g * 1.2)
    mapped_low = _map_current_state_to_planning_curve(low_point, x_series, ph_series)
    mapped_high = _map_current_state_to_planning_curve(high_point, x_series, ph_series)
    if mapped_low[1] is None or not math.isfinite(mapped_low[1]):
        raise AssertionError("Analysis overlay mapping returned invalid low pH.")
    if mapped_high[1] is None or not math.isfinite(mapped_high[1]):
        raise AssertionError("Analysis overlay mapping returned invalid high pH.")
    overall_pct = max(0.0, min(low_point / max(final_co2_g, 1e-6), 1.0)) * 100.0
    eq_pct = max(0.0, min(low_point / max(eq_co2_g, 1e-6), 1.0)) * 100.0
    assert 0.0 <= overall_pct <= 100.0, "Overall completion out of bounds."
    assert 0.0 <= eq_pct <= 100.0, "Equivalence completion out of bounds."
    regime_low = _analysis_regime_label(mapped_low[1])
    regime_high = _analysis_regime_label(mapped_high[1])
    if regime_low == regime_high:
        raise AssertionError("Regime classification did not change across progression.")
    missing = _map_current_state_to_planning_curve(10.0, [], [])
    assert missing == (
        None,
        None,
        None,
    ), "Missing planning curve mapping should be safe."


def _regression_test_analysis_runtime_fallback_reference_without_planning_inputs() -> None:
    """Validate Analysis runtime builds progress from fallback reference traces.

    Purpose:
        Ensure Analysis runtime progress does not fail when Planning-only inputs
        are unavailable but cycle uptake rows exist.
    Why:
        Analysis input mode does not expose delta-P/manual CO2-per-cycle controls.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Executes runtime payload assembly through a local harness.
    Exceptions:
        Raises AssertionError when fallback trace propagation regresses.
    """

    class _Harness:
        """Minimal runtime harness with deterministic fallback-only behavior."""

        _build_analysis_runtime_payload = UnifiedApp._build_analysis_runtime_payload
        _analysis_consistency_audit_and_sanitize = (
            UnifiedApp._analysis_consistency_audit_and_sanitize
        )

        @staticmethod
        def _analysis_anchor_fit_tolerance_ph() -> float:
            """Return default anchor-fit tolerance used by consistency audit."""
            return 0.10

        @staticmethod
        def _analysis_input_signature_payload(
            _form_snapshot: Mapping[str, Any]
        ) -> Dict[str, Any]:
            """Return deterministic signature payload for runtime regressions."""
            return {}

        @staticmethod
        def _analysis_signature_fingerprint(_payload: Mapping[str, Any]) -> str:
            """Return deterministic runtime signature hash token."""
            return "analysis-signature"

        @staticmethod
        def _analysis_cycle_signature_from_timeline(
            _timeline_rows: Sequence[Mapping[str, Any]]
        ) -> str:
            """Return deterministic cycle signature token for runtime regressions."""
            return "cycle-signature"

        @staticmethod
        def _analysis_alignment_audit_and_reconcile(
            *,
            timeline_rows: Sequence[Mapping[str, Any]],
            dashboard_payload: Optional[Mapping[str, Any]],
            calibration_payload: Optional[Mapping[str, Any]],
        ) -> Dict[str, Any]:
            """Return no-op alignment audit payload for fallback-only checks."""
            _ = timeline_rows
            _ = dashboard_payload
            _ = calibration_payload
            return {
                "status": "ok",
                "mismatch_count": 0,
                "mismatches": [],
                "warnings": [],
            }

        @staticmethod
        def _prepare_solver_inputs(_form_snapshot: Mapping[str, Any]) -> Any:
            """Raise deterministic error to force fallback trace generation."""
            raise ValueError("planning controls unavailable in Analysis mode")

        @staticmethod
        def _build_analysis_reference_trace_from_timeline(
            _timeline_rows: Sequence[Mapping[str, Any]],
            *,
            form_data: Optional[Mapping[str, Any]] = None,
        ) -> Optional[Dict[str, Any]]:
            """Return deterministic fallback trace used by the regression."""
            _ = form_data
            return {
                "x_co2_g_series": [4.0, 8.0, 12.0],
                "ph_series": [10.6, 9.4, 8.4],
                "cumulative_co2_mol_series": [
                    4.0 / SOL_MW_CO2,
                    8.0 / SOL_MW_CO2,
                    12.0 / SOL_MW_CO2,
                ],
                "cycle_co2_mol_series": [
                    4.0 / SOL_MW_CO2,
                    4.0 / SOL_MW_CO2,
                    4.0 / SOL_MW_CO2,
                ],
                "hco3_series": [0.60, 0.68, 0.74],
                "co3_series": [0.32, 0.22, 0.14],
                "fraction_series": [
                    {"H2CO3": 0.08, "HCO3-": 0.60, "CO3^2-": 0.32},
                    {"H2CO3": 0.10, "HCO3-": 0.68, "CO3^2-": 0.22},
                    {"H2CO3": 0.12, "HCO3-": 0.74, "CO3^2-": 0.14},
                ],
                "final_co2_g": 12.0,
                "equivalence_co2_g": 8.0,
                "equivalence_index": 1,
            }

        @staticmethod
        def _compute_analysis_forensic_timeline(
            timeline_rows: Sequence[Mapping[str, Any]],
            *,
            reference_trace: Optional[Mapping[str, Any]] = None,
        ) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
            """Pass timeline rows through without forensic augmentation."""
            _ = reference_trace
            return [dict(row) for row in timeline_rows], {}

        @staticmethod
        def _apply_analysis_measured_ph_calibration(
            timeline_rows: Sequence[Mapping[str, Any]],
            *,
            form_snapshot: Mapping[str, Any],
            reference_trace: Optional[Mapping[str, Any]],
        ) -> Tuple[List[Dict[str, Any]], Optional[Dict[str, Any]], Optional[Dict[str, Any]]]:
            """Return rows unchanged with no measured-pH calibration payload."""
            _ = form_snapshot
            _ = reference_trace
            return [dict(row) for row in timeline_rows], None, None

        @staticmethod
        def _build_analysis_dashboard_data(
            _timeline_rows: Sequence[Mapping[str, Any]],
            *,
            form_data: Optional[Mapping[str, Any]] = None,
        ) -> Dict[str, Any]:
            """Return deterministic summary fields used by runtime text assembly."""
            _ = form_data
            return {
                "actual_cycle_series": [],
                "reference_cycle_series": [],
                "comparison_series": [],
                "summary": {
                    "planning_completion_pct": 50.0,
                    "equivalence_completion_pct": 75.0,
                    "total_uptake_g": 6.0,
                    "total_uptake_mol": 6.0 / SOL_MW_CO2,
                },
            }

    harness = _Harness()
    runtime_payload = harness._build_analysis_runtime_payload(
        cycle_payload={"total_moles_vdw": 6.0 / SOL_MW_CO2, "gas_molar_mass": SOL_MW_CO2},
        timeline_rows=[
            {
                "cycle_id": 1,
                "co2_mass_g": 2.0,
                "co2_moles": 2.0 / SOL_MW_CO2,
                "cumulative_co2_added_mass_g": 2.0,
                "cumulative_co2_added_moles": 2.0 / SOL_MW_CO2,
            },
            {
                "cycle_id": 2,
                "co2_mass_g": 4.0,
                "co2_moles": 4.0 / SOL_MW_CO2,
                "cumulative_co2_added_mass_g": 6.0,
                "cumulative_co2_added_moles": 6.0 / SOL_MW_CO2,
            },
        ],
        form_data={"workflow_key": "Analysis"},
    )
    trace = runtime_payload.get("reference_trace") or {}
    if not trace or not (trace.get("x_co2_g_series") or []):
        raise AssertionError("Analysis fallback reference trace was not populated.")
    progress_text = str(runtime_payload.get("progress_text") or "")
    if "50.0% complete" not in progress_text:
        raise AssertionError(
            f"Fallback runtime progress should use completion text, got: {progress_text!r}"
        )


def _regression_test_analysis_runtime_prefers_cycle_reference_trace_source() -> None:
    """Validate Analysis runtime prefers cycle-derived reference trace over planning fallback.

    Purpose:
        Guard reference-trace source precedence when both cycle-derived and
        planning-derived traces are available.
    Why:
        Analysis simulation parity requires per-cycle CO2 trace fidelity to
        Cycle Analysis data before considering planning fallback.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Executes runtime payload assembly through a local harness.
    Exceptions:
        Raises AssertionError when trace precedence or source metadata regresses.
    """

    class _Harness:
        """Minimal runtime harness with both cycle and planning trace builders."""

        _build_analysis_runtime_payload = UnifiedApp._build_analysis_runtime_payload
        _analysis_consistency_audit_and_sanitize = (
            UnifiedApp._analysis_consistency_audit_and_sanitize
        )

        def __init__(self) -> None:
            """Initialize deterministic call-tracking fields."""
            self.planning_trace_called = False

        @staticmethod
        def _analysis_anchor_fit_tolerance_ph() -> float:
            """Return default anchor-fit tolerance used by consistency audit."""
            return 0.10

        @staticmethod
        def _analysis_input_signature_payload(
            _form_snapshot: Mapping[str, Any]
        ) -> Dict[str, Any]:
            """Return deterministic signature payload for runtime regressions."""
            return {}

        @staticmethod
        def _analysis_signature_fingerprint(_payload: Mapping[str, Any]) -> str:
            """Return deterministic runtime signature hash token."""
            return "analysis-signature"

        @staticmethod
        def _analysis_cycle_signature_from_timeline(
            _timeline_rows: Sequence[Mapping[str, Any]]
        ) -> str:
            """Return deterministic cycle signature token for runtime regressions."""
            return "cycle-signature"

        @staticmethod
        def _analysis_alignment_audit_and_reconcile(
            *,
            timeline_rows: Sequence[Mapping[str, Any]],
            dashboard_payload: Optional[Mapping[str, Any]],
            calibration_payload: Optional[Mapping[str, Any]],
        ) -> Dict[str, Any]:
            """Return no-op alignment audit payload for trace-source checks."""
            _ = timeline_rows
            _ = dashboard_payload
            _ = calibration_payload
            return {
                "status": "ok",
                "mismatch_count": 0,
                "mismatches": [],
                "warnings": [],
            }

        @staticmethod
        def _prepare_solver_inputs(_form_snapshot: Mapping[str, Any]) -> Any:
            """Return placeholder solver inputs object accepted by fallback builder."""
            return object()

        def _build_planning_reference_trace_for_analysis(
            self,
            _form_data: Dict[str, Any],
            _solver_inputs: Any,
        ) -> Dict[str, Any]:
            """Build one deterministic planning fallback trace and track invocation."""
            self.planning_trace_called = True
            return {
                "x_co2_g_series": [3.0, 6.0, 9.0],
                "ph_series": [10.9, 9.7, 8.8],
                "cumulative_co2_mol_series": [
                    3.0 / SOL_MW_CO2,
                    6.0 / SOL_MW_CO2,
                    9.0 / SOL_MW_CO2,
                ],
                "cycle_co2_mol_series": [
                    3.0 / SOL_MW_CO2,
                    3.0 / SOL_MW_CO2,
                    3.0 / SOL_MW_CO2,
                ],
                "final_co2_g": 9.0,
                "equivalence_co2_g": 6.0,
                "equivalence_index": 1,
            }

        @staticmethod
        def _build_analysis_reference_trace_from_timeline(
            _timeline_rows: Sequence[Mapping[str, Any]],
            *,
            form_data: Optional[Mapping[str, Any]] = None,
        ) -> Optional[Dict[str, Any]]:
            """Return deterministic cycle-derived trace used as primary source."""
            _ = form_data
            return {
                "x_co2_g_series": [4.0, 8.0, 12.0],
                "ph_series": [10.6, 9.4, 8.4],
                "cumulative_co2_mol_series": [
                    4.0 / SOL_MW_CO2,
                    8.0 / SOL_MW_CO2,
                    12.0 / SOL_MW_CO2,
                ],
                "cycle_co2_mol_series": [
                    4.0 / SOL_MW_CO2,
                    4.0 / SOL_MW_CO2,
                    4.0 / SOL_MW_CO2,
                ],
                "final_co2_g": 12.0,
                "equivalence_co2_g": 8.0,
                "equivalence_index": 1,
            }

        @staticmethod
        def _compute_analysis_forensic_timeline(
            timeline_rows: Sequence[Mapping[str, Any]],
            *,
            reference_trace: Optional[Mapping[str, Any]] = None,
        ) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
            """Pass timeline rows through without forensic augmentation."""
            _ = reference_trace
            return [dict(row) for row in timeline_rows], {}

        @staticmethod
        def _apply_analysis_measured_ph_calibration(
            timeline_rows: Sequence[Mapping[str, Any]],
            *,
            form_snapshot: Mapping[str, Any],
            reference_trace: Optional[Mapping[str, Any]],
        ) -> Tuple[List[Dict[str, Any]], Optional[Dict[str, Any]], Optional[Dict[str, Any]]]:
            """Return rows unchanged with no measured-pH calibration payload."""
            _ = form_snapshot
            _ = reference_trace
            return [dict(row) for row in timeline_rows], None, None

        @staticmethod
        def _build_analysis_dashboard_data(
            _timeline_rows: Sequence[Mapping[str, Any]],
            *,
            form_data: Optional[Mapping[str, Any]] = None,
        ) -> Dict[str, Any]:
            """Return minimal dashboard payload used by runtime text assembly."""
            _ = form_data
            return {
                "actual_cycle_series": [],
                "reference_cycle_series": [],
                "comparison_series": [],
                "summary": {},
            }

    harness = _Harness()
    runtime_payload = harness._build_analysis_runtime_payload(
        cycle_payload={"total_moles_vdw": 6.0 / SOL_MW_CO2, "gas_molar_mass": SOL_MW_CO2},
        timeline_rows=[
            {
                "cycle_id": 1,
                "co2_mass_g": 2.0,
                "co2_moles": 2.0 / SOL_MW_CO2,
                "cumulative_co2_added_mass_g": 2.0,
                "cumulative_co2_added_moles": 2.0 / SOL_MW_CO2,
            },
            {
                "cycle_id": 2,
                "co2_mass_g": 4.0,
                "co2_moles": 4.0 / SOL_MW_CO2,
                "cumulative_co2_added_mass_g": 6.0,
                "cumulative_co2_added_moles": 6.0 / SOL_MW_CO2,
            },
        ],
        form_data={"workflow_key": "Analysis"},
    )
    trace_source = str(runtime_payload.get("analysis_reference_trace_source") or "")
    if trace_source != "analysis_cycle":
        raise AssertionError(f"Expected cycle-derived reference source, got: {trace_source!r}")
    trace = dict(runtime_payload.get("reference_trace") or {})
    if _safe_float(trace.get("final_co2_g")) != 12.0:
        raise AssertionError(
            "Runtime reference trace should use cycle-derived values when available."
        )
    if harness.planning_trace_called:
        raise AssertionError("Planning fallback builder should not run when cycle trace is available.")


def _regression_test_analysis_guidance_measurement_uses_anchor_fallback_when_primary_missing() -> None:
    """Validate Analysis guidance uses anchor pH when final/slurry values are absent.

    Purpose:
        Guard measured-pH warning wiring used by Analysis reaction guidance.
    Why:
        Analysis support warnings should treat a valid measured-pH anchor as the
        measurement source when final/slurry fields are blank.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Executes one deterministic helper call through a local harness.
    Exceptions:
        Raises AssertionError on missing or incorrect anchor fallback behavior.
    """

    class _Harness:
        """Expose the Analysis guidance measurement resolver for regression checks."""

        _resolve_analysis_reaction_guidance_measurements = (
            UnifiedApp._resolve_analysis_reaction_guidance_measurements
        )

    harness = _Harness()
    resolved = harness._resolve_analysis_reaction_guidance_measurements(
        workflow_key="Analysis",
        reaction_final_ph=None,
        reaction_slurry_ph=None,
        measured_ph_value=9.70,
        measured_ph_cycle_index=2,
        measured_ph_anchors=[],
        measured_ph_anchor_enabled=True,
        cycle_count=3,
    )
    measured_ph = _safe_float(resolved.get("measured_ph"))
    slurry_ph = _safe_float(resolved.get("slurry_ph"))
    if measured_ph is None or abs(measured_ph - 9.70) > 1e-9:
        raise AssertionError(f"Expected anchor fallback measured pH, got: {resolved!r}")
    if slurry_ph is not None:
        raise AssertionError(
            f"Anchor fallback should not set slurry pH when absent, got: {resolved!r}"
        )


def _regression_test_analysis_guidance_measurement_prefers_final_and_slurry_over_anchor() -> None:
    """Validate final/slurry inputs stay authoritative over Analysis anchor fallback.

    Purpose:
        Ensure primary measured fields retain precedence in guidance wiring.
    Why:
        Anchor fallback should only apply when both final and slurry fields are
        unavailable.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Executes deterministic helper calls through a local harness.
    Exceptions:
        Raises AssertionError when precedence rules regress.
    """

    class _Harness:
        """Expose the Analysis guidance measurement resolver for precedence checks."""

        _resolve_analysis_reaction_guidance_measurements = (
            UnifiedApp._resolve_analysis_reaction_guidance_measurements
        )

    harness = _Harness()
    resolved_final = harness._resolve_analysis_reaction_guidance_measurements(
        workflow_key="Analysis",
        reaction_final_ph=8.65,
        reaction_slurry_ph=9.10,
        measured_ph_value=9.70,
        measured_ph_cycle_index=2,
        measured_ph_anchors=[],
        measured_ph_anchor_enabled=True,
        cycle_count=3,
    )
    if _safe_float(resolved_final.get("measured_ph")) != 8.65:
        raise AssertionError(f"Final pH should remain primary, got: {resolved_final!r}")
    if _safe_float(resolved_final.get("slurry_ph")) != 9.10:
        raise AssertionError(f"Slurry pH should remain available, got: {resolved_final!r}")

    resolved_slurry = harness._resolve_analysis_reaction_guidance_measurements(
        workflow_key="Analysis",
        reaction_final_ph=None,
        reaction_slurry_ph=9.20,
        measured_ph_value=9.70,
        measured_ph_cycle_index=2,
        measured_ph_anchors=[],
        measured_ph_anchor_enabled=True,
        cycle_count=3,
    )
    if _safe_float(resolved_slurry.get("measured_ph")) is not None:
        raise AssertionError(
            f"Slurry-only path should not force measured final pH, got: {resolved_slurry!r}"
        )
    if _safe_float(resolved_slurry.get("slurry_ph")) != 9.20:
        raise AssertionError(
            f"Slurry pH should remain primary when final pH is absent, got: {resolved_slurry!r}"
        )


def _regression_test_analysis_anchor_calibration_populates_required_co2_and_completion() -> None:
    """Validate measured-pH calibration outputs required CO2 and completion values.

    Purpose:
        Guard calibration core fields needed by Analysis reaction-progress text.
    Why:
        Required-CO2 and measured completion are now first-class runtime/dashboard
        outputs in Analysis mode.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Executes Python calibration core with deterministic cycle uptake values.
    Exceptions:
        Raises AssertionError on missing required calibration outputs.
    """
    payload = _python_measured_ph_uptake_calibration_core(
        model_key=DEFAULT_SPEC_MODEL_KEY,
        cycle_uptake_mol_series=[0.06, 0.06, 0.06, 0.06],
        anchor_cycle_index=2,
        measured_ph=10.10,
        equivalence_cycle_index=2,
        target_ph=8.20,
        initial_naoh_mol=0.22,
        solution_volume_l=1.0,
        temperature_c=25.0,
        planning_reference_total_mol=0.30,
        equivalence_co2_mol=0.11,
    )
    if str(payload.get("solver_status") or "").lower() != "ok":
        raise AssertionError(f"Calibration core did not converge: {payload!r}")
    required_g = _safe_float(payload.get("co2_required_for_target_ph_g"))
    completion_pct = _safe_float(payload.get("completion_from_measured_ph_pct"))
    if required_g is None or required_g <= 0.0:
        raise AssertionError("Expected positive required-CO2 output from calibration core.")
