    harness = _Harness()
    stale_fig = Figure(figsize=(4.0, 3.0))
    stale_ax = stale_fig.add_subplot(1, 1, 1)
    stale_ax.plot([0.0, 1.0], [0.0, 1.0], label="Stale trace")
    stale_legend = stale_ax.legend(loc="lower center")
    harness._planning_timeline_legend = stale_legend

    timeline_rows = [
        {
            "cycle_id": idx,
            "fractions": {"H2CO3": 0.18, "HCO3-": 0.70, "CO3^2-": 0.12},
            "solution_ph": 8.30 + (idx * 0.03),
            "co2_mass_g": 1.0 + (idx * 0.08),
            "planning_cycle_ph": 8.25 + (idx * 0.02),
            "planning_co2_aligned_ph": 8.26 + (idx * 0.019),
            "planning_cycle_co2_mol": 0.02 + (idx * 0.0002),
        }
        for idx in range(1, 11)
    ]
    payload = {
        "workflow": "Analysis",
        "timeline": timeline_rows,
        "columns": (),
        "tree_rows": [],
        "full_rows": [],
        "full_columns": (),
        "full_headers": [],
        "preview_mode": False,
        "callout_lines": [],
    }
    UnifiedApp._update_cycle_spec_view(
        harness,
        timeline_rows,
        workflow_key="Analysis",
        render_payload=payload,
        skip_tree=True,
        skip_callout=True,
    )
    refreshed_legend = getattr(harness, "_planning_timeline_legend", None)
    if refreshed_legend is None:
        raise AssertionError("Display timeline refresh should recreate a stale cached legend.")
    if refreshed_legend is stale_legend:
        raise AssertionError("Display timeline refresh should replace stale legend instances.")
    if getattr(refreshed_legend, "figure", None) is not harness._sol_cycle_spec_ax.figure:
        raise AssertionError("Rebuilt display timeline legend should attach to active display figure.")
    if not bool(getattr(refreshed_legend, "get_visible", lambda: False)()):
        raise AssertionError("Rebuilt display timeline legend should remain visible.")


