            prefs_map = dict(prefs or self._prefs)
            return {
                "ph_axis_labelpad": float(prefs_map.get("ph_axis_labelpad", 10.0)),
                "ph_axis_spine_offset": float(prefs_map.get("ph_axis_spine_offset", 1.02)),
                "pco2_axis_labelpad": float(prefs_map.get("pco2_axis_labelpad", 10.0)),
                "pco2_axis_spine_offset": float(
                    prefs_map.get("pco2_axis_spine_offset", 1.12)
                ),
            }

