def _regression_test_cycle_timeline_export_preview_preserves_export_bottom_margin() -> (
    None
):
    """Validate export-preview layout health honors the export bottom margin.

    Purpose:
        Exercise Cycle Timeline export-mode margin authority with a deliberately
        wrong subplot bottom value.
    Why:
        Plot Preview uses the export layout profile; layout-health verification
        must not rewrite the configured export bottom margin and make the subplot
        adjust tool report a different value than Plot Settings.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Builds and closes one transient Matplotlib figure.
    Exceptions:
        Raises AssertionError when export-mode bottom-margin authority regresses.
    """
    explicit_bottom = 0.123
    fig = Figure(figsize=(6.0, 4.0))
    FigureCanvasAgg(fig)
    ax = fig.add_subplot(111)
    ax.plot([1.0, 2.0], [8.2, 8.4])
    try:
        fig._gl260_plot_id = "fig_cycle_timeline"  # type: ignore[attr-defined]
        fig._gl260_layout_mode = "export"  # type: ignore[attr-defined]
        ax._gl260_axis_role = "right"  # type: ignore[attr-defined]
    except Exception:
        # Best-effort guard; metadata failures are validated by assertions below.
        pass
    fig.subplots_adjust(left=0.08, right=0.88, top=0.90, bottom=0.44)
    layout_mgr = PlotLayoutManager(
        fig,
        mode="export",
        baseline_margins={
            "left": 0.08,
            "right": 0.88,
            "top": 0.90,
            "bottom": explicit_bottom,
        },
        margins_authoritative=True,
    )
    layout_mgr.register_axes(ax)
    fig._gl260_layout_manager = layout_mgr  # type: ignore[attr-defined]
    try:
        authoritative_bottom = _layout_health_authoritative_timeline_bottom(
            fig,
            "export",
            layout_mgr,
        )
        if authoritative_bottom is None:
            raise AssertionError(
                "Cycle Timeline export preview should expose authoritative bottom margin."
            )
        fig.subplots_adjust(bottom=0.44)
        fig.subplots_adjust(bottom=float(authoritative_bottom))
        final_bottom = float(fig.subplotpars.bottom)
    finally:
        plt.close(fig)
    if abs(final_bottom - explicit_bottom) > 1e-9:
        raise AssertionError(
            "Cycle Timeline export preview should restore the export bottom margin "
            f"(expected {explicit_bottom}, got {final_bottom})."
        )


