def _regression_test_sol_output_workspace_drop_collision_resolution_non_overlap() -> None:
    """Validate drop-time collision normalization resolves overlaps deterministically.

    Purpose:
        Guard the new release-time collision solver used by workspace drag/drop.
    Why:
        Freeform interactions should allow temporary overlap while moving, then
        resolve to a non-overlapping snapped layout when released.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Uses lightweight stubs to execute collision resolution logic.
    Exceptions:
        Raises AssertionError when overlap resolution contracts regress.
    """

    class _CanvasStub:
        """Canvas stub returning deterministic dimensions for resolver bounds."""

        @staticmethod
        def winfo_width() -> int:
            """Return fixed test width for collision-resolution bounds."""
            return 1200

        @staticmethod
        def winfo_height() -> int:
            """Return fixed test height for collision-resolution bounds."""
            return 900

    class _Harness:
        """Harness exposing workspace collision-resolution helpers."""

        _sol_output_workspace_snap = UnifiedApp._sol_output_workspace_snap
        _sol_output_workspace_layout_bounds = UnifiedApp._sol_output_workspace_layout_bounds
        _sol_output_workspace_resolve_drop_collisions = (
            UnifiedApp._sol_output_workspace_resolve_drop_collisions
        )
        _sol_output_workspace_panel_has_collision = (
            UnifiedApp._sol_output_workspace_panel_has_collision
        )
        _sol_output_workspace_bounds_overlap = staticmethod(
            UnifiedApp._sol_output_workspace_bounds_overlap
        )

        def __init__(self) -> None:
            """Initialize resolver harness state with deterministic canvas geometry."""
            self._sol_output_workspace_canvas = _CanvasStub()

        @staticmethod
        def _sol_output_workspace_effective_layout() -> Dict[str, Dict[str, int]]:
            """Provide normalized default layout for resolver fallback paths."""
            return _normalize_sol_output_workspace_panel_layout_map(
                SOL_OUTPUT_WORKSPACE_DEFAULT_PANEL_LAYOUT
            )

        @staticmethod
        def _sol_output_workspace_set_collision_feedback(
            _panel_id: str,
            *,
            has_collision: bool,
        ) -> None:
            """No-op collision styling sink used by interaction-end flow."""
            _ = has_collision
            return None

    harness = _Harness()
    overlapped_layout = _normalize_sol_output_workspace_panel_layout_map(
        {
            **SOL_OUTPUT_WORKSPACE_DEFAULT_PANEL_LAYOUT,
            "cycle_compare": {"x": 20, "y": 20, "w": 620, "h": 420},
        }
    )
    resolved_layout, had_collision = harness._sol_output_workspace_resolve_drop_collisions(
        overlapped_layout,
        active_panel_id="cycle_compare",
    )
    if not had_collision:
        raise AssertionError("Collision resolver should report collisions when panels overlap on drop.")
    active_bounds = resolved_layout.get("cycle_compare", {})
    if int(active_bounds.get("x", -1)) != 20 or int(active_bounds.get("y", -1)) != 20:
        raise AssertionError("Drop resolver should preserve active panel release position priority.")
    for left_idx, left_id in enumerate(SOL_OUTPUT_WORKSPACE_PANEL_IDS):
        left_bounds = resolved_layout.get(left_id, {})
        for right_id in SOL_OUTPUT_WORKSPACE_PANEL_IDS[left_idx + 1 :]:
            right_bounds = resolved_layout.get(right_id, {})
            if harness._sol_output_workspace_bounds_overlap(left_bounds, right_bounds):
                raise AssertionError(
                    f"Drop-time collision resolver should eliminate overlaps ({left_id} vs {right_id})."
                )


