def _regression_test_sol_output_workspace_stacked_preset_geometry_normalization() -> (
    None
):
    """Validate stacked-preset geometry contracts for one-column normalization.

    Purpose:
        Guard snap-grid width/height normalization and monotonic stacked y-order.
    Why:
        Preset geometry must produce reliable, reachable controls on compact
        displays without violating minimum panel/bounds rules.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Evaluates stacked preset layout helper against deterministic canvas size.
    Exceptions:
        Raises AssertionError when stacked-preset geometry contracts regress.
    """

    class _CanvasStub:
        """Canvas stub returning deterministic width for preset calculations."""

        @staticmethod
        def winfo_width() -> int:
            return 1021

    class _Harness:
        """Harness exposing snap and stacked-preset layout helpers."""

        _sol_output_workspace_snap = UnifiedApp._sol_output_workspace_snap
        _sol_output_workspace_stacked_preset_layout = (
            UnifiedApp._sol_output_workspace_stacked_preset_layout
        )

        def __init__(self) -> None:
            self._sol_output_workspace_canvas = _CanvasStub()

        @staticmethod
        def _sol_output_workspace_effective_layout() -> Dict[str, Dict[str, int]]:
            return _normalize_sol_output_workspace_panel_layout_map(
                SOL_OUTPUT_WORKSPACE_DEFAULT_PANEL_LAYOUT
            )

    harness = _Harness()
    layout = harness._sol_output_workspace_stacked_preset_layout()
    expected_x = 20
    prior_y = -1
    prior_bottom = -1
    for panel_id in SOL_OUTPUT_WORKSPACE_PANEL_IDS:
        panel = layout.get(panel_id) or {}
        x_val = int(panel.get("x", -1))
        y_val = int(panel.get("y", -1))
        w_val = int(panel.get("w", -1))
        h_val = int(panel.get("h", -1))
        if x_val != expected_x:
            raise AssertionError("Stacked preset should align all panels to x=20.")
        if y_val <= prior_y:
            raise AssertionError("Stacked preset should enforce strictly increasing y positions.")
        if prior_bottom >= 0 and y_val < prior_bottom + 20:
            raise AssertionError("Stacked preset should preserve a 20px inter-panel vertical gap.")
        if w_val < SOL_OUTPUT_WORKSPACE_MIN_PANEL_WIDTH or (w_val % SOL_OUTPUT_WORKSPACE_GRID_PX) != 0:
            raise AssertionError("Stacked preset width should respect min width and snap grid.")
        min_height = max(
            SOL_OUTPUT_WORKSPACE_MIN_PANEL_HEIGHT,
            int(SOL_OUTPUT_WORKSPACE_STACKED_MIN_HEIGHTS.get(panel_id, 0)),
        )
        if h_val < min_height or (h_val % SOL_OUTPUT_WORKSPACE_GRID_PX) != 0:
            raise AssertionError("Stacked preset height should respect configured minimum and snap grid.")
        prior_y = y_val
        prior_bottom = y_val + h_val


