    top_axis_pos = ax_top.get_position()
    top_overlap = _layout_health_bbox_overlap_area(top_bbox, top_axis_pos)
    top_area = max(
        1e-9, float(top_bbox.x1 - top_bbox.x0) * float(top_bbox.y1 - top_bbox.y0)
    )
    overlap_ratio = float(top_overlap / top_area)
    if overlap_ratio < 0.35:
        raise AssertionError(
            "Timeline top-legend recovery should place legend within top subplot "
            f"(overlap_ratio={overlap_ratio:.3f})."
        )
    loc_value = _normalize_legend_loc_value(
        getattr(top_legend, "get_loc", lambda: getattr(top_legend, "_loc", None))()
    )
    if loc_value not in {"upper left", 2}:
        raise AssertionError(
            f"Timeline top-legend recovery should anchor to upper-left, got {loc_value!r}."
        )
    if not bool(result.get("applied")):
        raise AssertionError(
            "Expected timeline top-legend recovery auto-fix to apply corrections."
        )
    try:
        plt.close(fig)
    except Exception:
        # Best-effort guard; ignore failures during regression cleanup.
        pass
