def _regression_test_analysis_scroll_edge_handoff_prefers_local_then_canvas() -> None:
    """Validate Analysis wheel dispatcher uses local-first scroll with canvas handoff.

    Purpose:
        Ensure edge-aware wheel routing scrolls local Text/Tree widgets when
        possible, and hands off to outer canvas at widget boundaries.
    Why:
        Analysis tab should avoid dead-end scroll traps across nested regions.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        None.
    Exceptions:
        Raises AssertionError when dispatch or boundary handoff regresses.
    """

    class _CanvasStub:
        """Canvas stub capturing fallback scroll calls."""

        def __init__(self) -> None:
            self.calls: List[Tuple[int, str]] = []

        def yview_scroll(self, step: int, units: str) -> None:
            """Capture one canvas scroll invocation."""
            self.calls.append((int(step), str(units)))

    class _ScrollOwnerStub:
        """Text-like scroll owner stub with bounded yview state."""

        def __init__(self, *, first: float, last: float) -> None:
            self.first = float(first)
            self.last = float(last)
            self.calls: List[Tuple[int, str]] = []

        def winfo_class(self) -> str:
            """Return Text class so owner detection routes locally."""
            return "Text"

        def yview(self) -> Tuple[float, float]:
            """Return current normalized yview bounds."""
            return (self.first, self.last)

        def yview_scroll(self, step: int, units: str) -> None:
            """Apply bounded yview movement for regression assertions."""
            self.calls.append((int(step), str(units)))
            span = max(self.last - self.first, 0.05)
            shift = float(step) * 0.1
            new_first = min(max(self.first + shift, 0.0), max(0.0, 1.0 - span))
            self.first = new_first
            self.last = min(1.0, self.first + span)

    class _EventStub:
        """Minimal wheel event payload stub."""

        def __init__(self, widget: Any, *, delta: int = 0, num: int = 0) -> None:
            self.widget = widget
            self.delta = int(delta)
            self.num = int(num)

    class _Harness:
        """Harness exposing scroll-dispatch helpers."""

        _widget_owns_vertical_scroll = UnifiedApp._widget_owns_vertical_scroll
        _normalize_mousewheel_step = UnifiedApp._normalize_mousewheel_step
        _scroll_owned_widget_if_possible = UnifiedApp._scroll_owned_widget_if_possible
        _dispatch_canvas_mousewheel_with_handoff = (
            UnifiedApp._dispatch_canvas_mousewheel_with_handoff
        )

        def __init__(self) -> None:
            self._sol_scroll_wheel_remainder = 0.0

    harness = _Harness()
    canvas = _CanvasStub()
    local_widget = _ScrollOwnerStub(first=0.25, last=0.55)
    consumed = harness._dispatch_canvas_mousewheel_with_handoff(
        _EventStub(local_widget, delta=-120),
        canvas=canvas,
        accumulator_attr="_sol_scroll_wheel_remainder",
    )
    if consumed != "break" or len(local_widget.calls) != 1 or canvas.calls:
        raise AssertionError("Wheel dispatcher should prefer local owned widget scrolling when available.")

    edge_widget = _ScrollOwnerStub(first=0.75, last=1.0)
    consumed = harness._dispatch_canvas_mousewheel_with_handoff(
        _EventStub(edge_widget, delta=-120),
        canvas=canvas,
        accumulator_attr="_sol_scroll_wheel_remainder",
    )
    if consumed != "break" or not canvas.calls:
        raise AssertionError("Wheel dispatcher should hand off to canvas when local widget is at edge.")


