def _regression_test_generate_selected_plots_forces_combined_full_rebuild() -> None:
    """Validate selected-plot generation forces combined full-rebuild rendering.

    Purpose:
        Ensure `_generate_selected_plots` routes combined generation through
        deterministic full-rebuild async rendering.
    Why:
        Combined initial-generate layout stability should not depend on adaptive
        reuse when users click `Generate Plot`.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Executes `_generate_selected_plots` with a local harness and temporary
        `settings` selection-state overrides.
    Exceptions:
        Raises AssertionError when combined generation does not force rebuild.
    """

    class _VarStub:
        """Minimal tk-variable stub exposing `get` for selection controls."""

        def __init__(self, value: bool) -> None:
            self._value = bool(value)

        def get(self) -> bool:
            """Return configured boolean selection value."""
            return self._value

    class _Harness:
        """Minimal harness for selected combined-generation regression checks."""

        def __init__(self) -> None:
            self._plot_select_fig1_var = _VarStub(False)
            self._plot_select_fig2_var = _VarStub(False)
            self._plot_select_combined_var = _VarStub(True)
            self.df = object()
            self.columns = {"x": "Elapsed Time", "y1": "Pressure"}
            self.start_calls: List[Dict[str, Any]] = []

        @staticmethod
        def _flush_open_plot_settings_dialog(*, refresh_after_apply: bool = False) -> bool:
            """No-op settings flush for generate regression harness."""
            _ = refresh_after_apply
            return False

        @staticmethod
        def _schedule_save_settings() -> None:
            """No-op settings persistence hook for generate regression harness."""

        @staticmethod
        def _render_figures_in_tabs(
            _figs: Dict[str, Any],
            *,
            clear_existing: bool = True,
            auto_refresh: bool = True,
        ) -> None:
            """No-op placeholder tab renderer for generate regression harness."""
            _ = clear_existing
            _ = auto_refresh

        @staticmethod
        def _find_plot_tab_canvas(_plot_key: str) -> Tuple[Any, Any]:
            """Return deterministic frame/canvas placeholders for harness flow."""
            return object(), object()

        @staticmethod
        def _resolve_combined_initial_figsize_inches(
            _frame: Any,
            _canvas: Any,
            *,
            timeout_ms: int = 0,
        ) -> Tuple[float, float]:
            """Return deterministic figure size for combined snapshot capture."""
            _ = timeout_ms
            return (8.0, 4.5)

        @staticmethod
        def _capture_plot_render_snapshot(**_kwargs) -> Dict[str, Any]:
            """Return minimal snapshot payload for async-start assertions."""
            return {"snapshot": True}

        def _start_combined_render_async(
            self,
            _snapshot: Dict[str, Any],
            *,
            warn_on_failure: bool,
            frame: Any = None,
            canvas: Any = None,
            placement_state: Optional[Dict[str, Any]] = None,
            on_success: Optional[Callable[[Figure], None]] = None,
            force_full_rebuild: bool = False,
        ) -> None:
            """Capture combined async-start arguments for regression assertions."""
            _ = placement_state
            self.start_calls.append(
                {
                    "warn_on_failure": bool(warn_on_failure),
                    "frame": frame,
                    "canvas": canvas,
                    "on_success": on_success,
                    "force_full_rebuild": bool(force_full_rebuild),
                }
            )

    settings_map = globals().get("settings")
    if not isinstance(settings_map, dict):
        raise AssertionError("Global settings must be a dictionary for generate regression.")
    sentinel = object()
    original_selection = settings_map.get("plot_generation_selection", sentinel)
    try:
        settings_map["plot_generation_selection"] = {}
        harness = _Harness()
        UnifiedApp._generate_selected_plots(harness)
    finally:
        if original_selection is sentinel:
            settings_map.pop("plot_generation_selection", None)
        else:
            settings_map["plot_generation_selection"] = original_selection

    if len(harness.start_calls) != 1:
        raise AssertionError("Expected one combined async-start call from selected plot generation.")
    if not bool(harness.start_calls[0].get("force_full_rebuild")):
        raise AssertionError("Selected combined generation should force full rebuild.")


