def _regression_test_plot_layer_refresh_meta_round_trip() -> None:
    """Validate layer-refresh state persistence into lightweight settings metadata.

    Purpose:
        Confirm in-memory layer refresh state writes to `plot_layer_refresh_meta`
        with the expected lightweight schema.
    Why:
        Adaptive refresh routing in v4.5.6 depends on hybrid persistence to retain
        route/layer context across session flow.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Mutates the global `settings` map during test execution.
    Exceptions:
        Raises AssertionError when state persistence or normalization regresses.
    """
    settings_map = globals().get("settings")
    if not isinstance(settings_map, dict):
        raise AssertionError("Global settings must be a dictionary for metadata regression.")
    sentinel = object()
    original_meta = settings_map.get("plot_layer_refresh_meta", sentinel)
    settings_map["plot_layer_refresh_meta"] = {}

    class _Harness:
        """Minimal harness exposing layer-refresh state maps for persistence tests."""

        def __init__(self) -> None:
            self._plot_layer_refresh_state: Dict[str, Dict[str, Any]] = {}

        def _persist_plot_layer_refresh_meta(self, plot_id: str) -> None:
            """Delegate persistence to the app helper under test."""
            UnifiedApp._persist_plot_layer_refresh_meta(self, plot_id)

    try:
        harness = _Harness()
        UnifiedApp._record_plot_layer_refresh_state(
            harness,
            "fig_pressure_temp",
            route="in_place_layer_refresh",
            changed_layers=["layout", "elements"],
            bundle={"layout": ("seed", 1)},
        )
        meta_root = settings_map.get("plot_layer_refresh_meta")
        if not isinstance(meta_root, dict):
            raise AssertionError("Layer metadata root should be persisted as a dictionary.")
        row = meta_root.get("fig_pressure_temp")
        if not isinstance(row, dict):
            raise AssertionError("Layer metadata row missing for recorded plot id.")
        if str(row.get("last_route")) != "in_place_layer_refresh":
            raise AssertionError("Persisted layer route mismatch.")
        if list(row.get("last_changed_layers") or []) != ["layout", "elements"]:
            raise AssertionError("Persisted changed layer list mismatch.")
        normalized = {"plot_layer_refresh_meta": meta_root}
        _apply_rust_runtime_settings_defaults(normalized)
        norm_row = normalized.get("plot_layer_refresh_meta", {}).get("fig_pressure_temp")
        if not isinstance(norm_row, dict):
            raise AssertionError("Normalized settings should preserve persisted plot layer metadata.")
    finally:
        if original_meta is sentinel:
            settings_map.pop("plot_layer_refresh_meta", None)
        else:
            settings_map["plot_layer_refresh_meta"] = original_meta


def _regression_test_mojibake_text_repair_samples() -> None:
    """Validate mojibake repair for representative scientific/UI symbol payloads.

    Purpose:
        Confirm centralized text repair restores core symbols used by GL-260
        labels, legends, and status text.
    Why:
        Unicode corruption regressions are easiest to reintroduce at display
        boundaries; this test locks expected repair output for the most common
        broken sequences seen in production settings/data labels.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        None.
    Exceptions:
        Raises AssertionError when a repair sample does not match expectation.
    """
    # These literals are intentionally mojibake-corrupted fixture inputs. Keep
    # them broken so the repair helper regression continues to prove recovery.
    samples = [
        ("Total \u00ce\u201dP", "Total \u0394P"),
        ("Temperature (\u00c2\u00b0C)", "Temperature (\u00b0C)"),
        ("CO\u00e2\u201a\u201a", "CO\u2082"),
        (
            "CO\u00e2\u201a\u0192\u00c2\u00b2\u00e2\u0081\u00bb",
            "CO\u2083\u00b2\u207b",
        ),
        ("Loading\u00e2\u20ac\u00a6", "Loading\u2026"),
        ("\u00e2\u20ac\u00a2 item", "\u2022 item"),
        ("\u00e2\u0153\u201c done", "\u2713 done"),
        ("x \u00e2\u2030\u02c6 y", "x \u2248 y"),
        ("a \u00e2\u2020\u2019 b", "a \u2192 b"),
    ]
    for raw_value, expected in samples:
        actual = _repair_mojibake_text(raw_value)
        if actual != expected:
            raise AssertionError(
                f"Mojibake repair mismatch for {raw_value!r}: got={actual!r}, expected={expected!r}"
            )
    ascii_text = "Pressure (PSI)"
    ascii_repaired = _repair_mojibake_text(ascii_text)
    if ascii_repaired != ascii_text:
        raise AssertionError("ASCII text should remain unchanged by repair helper.")


def _regression_test_authored_user_text_is_mojibake_free() -> None:
    """Validate curated authored user-facing source blocks are mojibake-free.

    Purpose:
        Catch newly-authored mojibake in source literals before it leaks into the
        UI, reports, or export text.
    Why:
        The runtime repair helpers should remain a safety net for dynamic data,
        not the primary mechanism for fixing committed display strings.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Reads the current source file from disk.
    Exceptions:
        Raises AssertionError when curated authored text blocks still contain
        suspicious mojibake markers.
    """
    source_text = Path(__file__).read_text(encoding="utf-8")
    suspicious_sequences = tuple(_MOJIBAKE_FALLBACK_REPLACEMENTS.keys()) + (
        "COâ‚‚",
        "NaHCOâ‚ƒ",
        "Â°C",
        "â‰ˆ",
        "â€”",
        "â€“",
        "â€¢",
        "Î³",
        "HÃ¼",
        "OHâ»",
        "pCOâ‚‚",
        "Câ‚‚Hâ‚†O",
        "Hâ‚‚",
    )
    blocks = [
        (
            "workflow_templates",
            "SOL_WORKFLOW_TEMPLATES:",
            "def _clamp_temperature(",
        ),
        (
            "solubility_constant_notes",
            "def _resolve_solubility_constants(",
            "class SolubilitySolverInputs:",
        ),
        (
            "solubility_warnings",
            "def _solubility_build_warnings(",
            "def _solubility_finalize_result(",
        ),
        (
            "speciation_model_labels",
            "class DebyeHuckelSpeciationModel:",
            "_NAOH_PITZER_PARAMS = None",
        ),
        (
            "planning_regressions",
            "def _regression_test_planning_ph_stop_within_expected_window() -> None:",
            "def _regression_test_planning_post_carbonate_stability() -> None:",
        ),
        (
            "timeline_math_logging",
            "def _log_solubility_timeline_math(",
            "def _reprocessing_charge_basis(",
        ),
        (
            "gas_presets",
            "BASE_GAS_PRESETS = OrderedDict(",
            "CUSTOM_GAS_PRESETS = OrderedDict()",
        ),
    ]
    for block_name, start_marker, end_marker in blocks:
        start = source_text.find(start_marker)
        end = source_text.find(end_marker, start if start >= 0 else 0)
        if start < 0 or end < 0 or end <= start:
            raise AssertionError(f"Unable to locate authored-text block {block_name!r}.")
        block_text = source_text[start:end]
        hits = [
            item.encode("unicode_escape").decode("ascii")
            for item in suspicious_sequences
            if item in block_text
        ]
        if hits:
            raise AssertionError(
                f"Authored user-facing text block {block_name!r} still contains mojibake markers: {hits[:5]!r}"
            )


def _regression_test_layer_status_text_compaction() -> None:
    """Validate compact layer-status formatting and duplicate-prefix cleanup.

    Purpose:
        Confirm toolbar status text remains short and deterministic.
    Why:
        Layer status messages can be assembled from multiple sources and may
        include repeated prefixes or mojibake; compact normalization prevents
        layout overflow and duplicate text patterns.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        None.
    Exceptions:
        Raises AssertionError when compact formatting behavior regresses.
    """
    deduped = _compact_layer_status_text("Layer State: Layer State: clean")
    if deduped != "State: clean":
        raise AssertionError(f"Layer-status dedupe mismatch: {deduped!r}")
    mojibake_status = _compact_layer_status_text("Layer State: CO\u00e2\u201a\u201a ready")
    if mojibake_status != "State: CO\u2082 ready":
        raise AssertionError(f"Layer-status mojibake repair mismatch: {mojibake_status!r}")

    class _Harness:
        """Minimal harness used to call status-formatting helpers."""

    clean_status = UnifiedApp._layer_status_text_from_flags(
        _Harness(),
        dirty_data=False,
        dirty_layout=False,
        dirty_elements=False,
        dirty_trace=False,
    )
    if clean_status != "State: clean":
        raise AssertionError(f"Clean status mismatch: {clean_status!r}")
    dirty_status = UnifiedApp._layer_status_text_from_flags(
        _Harness(),
        dirty_data=False,
        dirty_layout=True,
        dirty_elements=True,
        dirty_trace=False,
    )
    if dirty_status != "State: layout+elements":
        raise AssertionError(f"Dirty-layer status mismatch: {dirty_status!r}")
    data_pending_status = UnifiedApp._layer_status_text_from_flags(
        _Harness(),
        dirty_data=True,
        dirty_layout=False,
        dirty_elements=False,
        dirty_trace=False,
    )
    if data_pending_status != "State: Data pending":
        raise AssertionError(f"Data-pending status mismatch: {data_pending_status!r}")


