def _regression_test_figure_text_artist_export_sanitization() -> None:
    """Validate figure-level text artist sanitization for export paths.

    Purpose:
        Confirm the shared figure sanitizer repairs key artist text categories.
    Why:
        Saved plots/reports can include titles, labels, legends, and annotations;
        one shared sanitizer must normalize all of them before `savefig`.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Creates and closes a temporary Matplotlib figure.
    Exceptions:
        Raises AssertionError when any text artist remains mojibake-corrupted.
    """
    fig = Figure(figsize=(4, 3), dpi=100)
    ax = fig.add_subplot(111)
    ax.plot([0, 1], [0, 1], label="ΔP")
    # These are intentional mojibake fixtures that the shared figure sanitizer
    # must repair before export.
    ax.set_title("pH â‰ˆ 8")
    ax.set_xlabel("Temperature (Â°C)")
    ax.set_ylabel("COâ‚‚ loading")
    ax.text(0.5, 0.5, "NaHCOâ‚ƒ", transform=ax.transAxes)
    fig.text(0.5, 0.02, "State â€” clean", ha="center")
    legend = ax.legend(loc="upper left")
    if legend is not None:
        legend.set_title("Legend â€¢ symbols")
    _sanitize_figure_text_artists(fig)

    if "â" in ax.get_title():
        raise AssertionError("Axis title should be repaired by figure text sanitizer.")
    if "\u00b0C" not in ax.get_xlabel():
        raise AssertionError("Axis xlabel should contain repaired degree symbol.")
    if "CO\u2082" not in ax.get_ylabel():
        raise AssertionError("Axis ylabel should contain repaired CO2 symbol.")
    if "NaHCO\u2083" not in ax.texts[0].get_text():
        raise AssertionError("Axis annotation should contain repaired NaHCO3 symbol.")
    if "State \u2014 clean" not in fig.texts[0].get_text():
        raise AssertionError("Figure text should contain repaired em dash.")
    legend_texts = [text.get_text() for text in (legend.get_texts() if legend else [])]
    if not legend_texts or "\u0394P" not in legend_texts[0]:
        raise AssertionError("Legend labels should contain repaired delta symbol.")
    try:
        plt.close(fig)
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass


def _regression_test_refresh_plot_for_plot_id_defaults_to_adaptive() -> None:
    """Validate `refresh_plot_for_plot_id` defaults to adaptive (not forced) refresh.

    Purpose:
        Ensure routed refresh calls do not force full rebuild unless explicitly set.
    Why:
        v4.5.6 manual Refresh should leverage adaptive routing after initial Generate.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Executes `_refresh_plot_for_plot_id` through a local harness.
    Exceptions:
        Raises AssertionError when routed force flags regress.
    """

    class _Harness:
        """Minimal harness recording force flag values passed into force refresh."""

        def __init__(self) -> None:
            frame = type("_FrameStub", (), {})()
            frame._plot_id = "fig_pressure_temp"
            self._plot_tabs = [frame]
            self._canvases = [object()]
            self.force_flags: List[bool] = []

        def _force_plot_refresh(self, _tab: Any, _canvas: Any, **kwargs: Any) -> None:
            """Capture routed force flag from refresh dispatcher."""
            self.force_flags.append(bool(kwargs.get("force_full_rebuild", False)))

    harness = _Harness()
    UnifiedApp._refresh_plot_for_plot_id(
        harness,
        "fig_pressure_temp",
        reason="Regression refresh",
        rearm_overlay=False,
        capture_combined_legend=True,
    )
    if harness.force_flags != [False]:
        raise AssertionError("Refresh dispatcher should default to adaptive (force_full_rebuild=False).")


def _regression_test_final_report_preview_splash_lifecycle_cleanup() -> None:
    """Validate Final Report splash lifecycle cleanup for both preview actions.

    Purpose:
        Confirm both preview entry points always close splash state via `finally`.
    Why:
        Preview workflows must not leave modal grabs/timers active after success
        or early-return paths.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Temporarily monkeypatches settings persistence to avoid disk writes.
    Exceptions:
        Raises AssertionError when splash show/hide lifecycle regresses.
    """
    original_save = globals().get("_save_settings_to_disk")
    settings_map = globals().get("settings")
    if not isinstance(settings_map, dict):
        raise AssertionError("Global settings must be available for splash lifecycle regression.")
    settings_map.setdefault("final_report", {})
    globals()["_save_settings_to_disk"] = lambda: None

    class _ListboxStub:
        """Listbox stub exposing a single selected section index."""

        @staticmethod
        def curselection() -> Tuple[int]:
            """Return one selected index for selected-page preview flow."""
            return (0,)

    class _Harness:
        """Harness that tracks splash show/hide calls for preview workflows."""

        def __init__(self) -> None:
            self._final_report_section_order_listbox = _ListboxStub()
            self._final_report_section_order = ["cycle_stats_table"]
            self.show_calls = 0
            self.hide_calls = 0
            self.open_calls = 0

        def _collect_final_report_state_from_ui(self) -> Dict[str, Any]:
            """Return minimal final-report state payload."""
            return {}

        def _show_final_report_preview_splash(self, _title: str) -> None:
            """Count splash show invocations."""
            self.show_calls += 1

        @staticmethod
        def _update_final_report_preview_splash(**_kwargs: Any) -> None:
            """No-op splash update hook for lifecycle assertions."""

        def _hide_final_report_preview_splash(self) -> None:
            """Count splash hide invocations."""
            self.hide_calls += 1

        def _final_report_build_selected_page(
            self, section_id: str, state: Dict[str, Any]
        ) -> Dict[str, Any]:
            """Return minimal selected-page payload for preview open flow."""
            _ = state
            return {"section_id": section_id, "figure": None}

        def _open_final_report_preview_window(self, page_figures=None) -> None:
            """Count preview-window open calls for selected-page path."""
            _ = page_figures
            self.open_calls += 1

        def _final_report_build_page_figures(
            self, state: Dict[str, Any]
        ) -> List[Dict[str, Any]]:
            """Return empty list to force early return path in full preview."""
            _ = state
            return []

    try:
        harness = _Harness()
        UnifiedApp._final_report_render_selected_page_preview(harness)
        if harness.show_calls != 1 or harness.hide_calls != 1:
            raise AssertionError("Selected-page preview should show and hide splash exactly once.")
        UnifiedApp._open_final_report_preview_window(harness, None)
        if harness.show_calls != 2 or harness.hide_calls != 2:
            raise AssertionError("Full preview should show and hide splash exactly once per invocation.")
    finally:
        if original_save is not None:
            globals()["_save_settings_to_disk"] = original_save
        else:
            globals().pop("_save_settings_to_disk", None)


def _regression_test_rust_final_report_wrappers() -> None:
    """Validate new Rust wrappers fallback behavior and payload sanitization.

    Purpose:
        Ensure v4.5.6 Rust wrapper additions preserve strict Python fallback rules.
    Why:
        Missing backend or malformed payloads must never break report generation.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Temporarily monkeypatches `_load_rust_backend`.
    Exceptions:
        Raises AssertionError when wrapper behavior regresses.
    """
    original_loader = globals().get("_load_rust_backend")
    try:
        globals()["_load_rust_backend"] = lambda: None
        if _rust_array_signature_core(np.asarray([1.0, 2.0], dtype=float)) is not None:
            raise AssertionError("Array-signature wrapper should return None when backend is absent.")
        if _rust_final_report_cycle_stats_rows_core([], "Duration (days)") is not None:
            raise AssertionError("Cycle-stats wrapper should return None when backend is absent.")
        if _rust_final_report_cycle_timeline_rows_core([]) is not None:
            raise AssertionError("Cycle-timeline wrapper should return None when backend is absent.")

        class _FakeRustBackend:
            """Minimal Rust backend stub used for wrapper payload regression checks."""

            @staticmethod
            def array_signature_core(values: np.ndarray) -> Tuple[int, str, int]:
                """Return deterministic payload for signature wrapper assertions."""
                return (int(values.size), "float64", 12345)

            @staticmethod
            def final_report_cycle_stats_rows_core(rows: List[Dict[str, Any]], _header: str) -> List[Dict[str, Any]]:
                """Echo deterministic stats rows for wrapper sanitization checks."""
                return [{"Cycle": "1", "Peak PSI": "12.3"}] if rows is not None else []

            @staticmethod
            def final_report_cycle_timeline_rows_core(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
                """Echo deterministic timeline rows for wrapper sanitization checks."""
                return [{"Cycle": "1", "pH": "8.50"}] if rows is not None else []

        globals()["_load_rust_backend"] = lambda: _FakeRustBackend()
        sig = _rust_array_signature_core(np.asarray([1.0, 2.0, 3.0], dtype=float))
        if sig != (3, "float64", 12345):
            raise AssertionError(f"Unexpected array-signature payload: {sig!r}")
        stats_rows = _rust_final_report_cycle_stats_rows_core(
            [{"cycle_id": 1}], "Duration (days)"
        )
        if stats_rows != [{"Cycle": "1", "Peak PSI": "12.3"}]:
            raise AssertionError(f"Unexpected cycle-stats wrapper payload: {stats_rows!r}")
        timeline_rows = _rust_final_report_cycle_timeline_rows_core(
            [{"cycle_id": 1}]
        )
        if timeline_rows != [{"Cycle": "1", "pH": "8.50"}]:
            raise AssertionError(f"Unexpected cycle-timeline wrapper payload: {timeline_rows!r}")
    finally:
        if original_loader is not None:
            globals()["_load_rust_backend"] = original_loader
        else:
            globals().pop("_load_rust_backend", None)


def _regression_test_compare_resize_scheduler_lightweight_refresh() -> None:
    """Validate Compare resize scheduling routes through lightweight redraw flow.

    Purpose:
        Ensure compare resize callbacks avoid triggering full side rerenders.
    Why:
        Geometry-only resize work should not block the UI with expensive rebuilds.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Executes `_compare_schedule_resize` and `_compare_refresh_resized_panes`
        against a local harness that records redraw behavior.
    Exceptions:
        Raises AssertionError when resize scheduling regresses to heavy rerenders.
    """

    class _Harness:
        """Harness capturing compare-resize routing and redraw parameters."""

        def __init__(self) -> None:
            self._compare_resize_after_id: Optional[str] = None
            self._compare_resize_pending_sides: Set[str] = set()
            self._compare_panels = {
                "A": {
                    "bundle": {"profile_name": "A"},
                    "figure": object(),
                    "canvas": object(),
                    "widget": object(),
                },
                "B": {
                    "bundle": None,
                    "figure": object(),
                    "canvas": object(),
                    "widget": object(),
                },
            }
            self.render_calls = 0
            self.finalize_force_draw: List[bool] = []
            self.lock_modes: List[str] = []

        @staticmethod
        def after_cancel(_after_id: str) -> None:
            """No-op cancel hook for resize debounce harness."""
            return None

        def after(self, _delay_ms: int, callback: Callable[[], None]) -> str:
            """Invoke scheduled callback immediately for deterministic assertions."""
            callback()
            return "after-compare-resize"

        def _compare_refresh_resized_panes(self, side_keys: Iterable[str]) -> None:
            """Delegate to production lightweight resize refresh helper."""
            UnifiedApp._compare_refresh_resized_panes(self, side_keys)

        def _compare_render_profile_side(self, _side_key: str, *, reason: str = "") -> None:
            """Capture unexpected full rerender usage during resize flow."""
            _ = reason
            self.render_calls += 1

        def _finalize_matplotlib_canvas_layout(self, **kwargs: Any) -> None:
            """Capture finalize draw mode used by lightweight resize helper."""
            self.finalize_force_draw.append(bool(kwargs.get("force_draw", True)))

        def _compare_apply_locked_x_axis(self, *, redraw_mode: str = "force") -> None:
            """Capture lock-x redraw mode used after resize refresh."""
            self.lock_modes.append(str(redraw_mode))

    harness = _Harness()
    UnifiedApp._compare_schedule_resize(harness, "A")
    if harness.render_calls != 0:
        raise AssertionError("Compare resize scheduler should not call full side rerender path.")
    if harness.finalize_force_draw != [False]:
        raise AssertionError(
            "Compare resize lightweight refresh should finalize with force_draw=False."
        )
    if harness.lock_modes != ["idle"]:
        raise AssertionError("Compare resize flow should request idle lock-x redraw mode.")


def _regression_test_compare_tab_canvas_geometry_sync() -> None:
    """Validate Compare tab canvas geometry sync preserves viewport/content visibility.

    Purpose:
        Ensure compare canvas-window sync applies both width and required height.
    Why:
        A prior width-only sync collapsed the Compare plot/table pane on render.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Executes `_compare_sync_tab_canvas_geometry` on local widget stubs.
    Exceptions:
        Raises AssertionError when width/height/scrollregion sync regresses.
    """

    class _CanvasStub:
        """Minimal canvas stub capturing itemconfigure/configure calls."""

        def __init__(self, *, width: int, height: int) -> None:
            self._width = int(width)
            self._height = int(height)
            self.itemconfigure_calls: List[Dict[str, int]] = []
            self.scrollregion_calls: List[Any] = []

        def winfo_width(self) -> int:
            """Return deterministic viewport width."""
            return int(self._width)

        def winfo_height(self) -> int:
            """Return deterministic viewport height."""
            return int(self._height)

        def itemconfigure(self, _window_id: Any, **kwargs: Any) -> None:
            """Capture canvas-window geometry updates."""
            payload = {
                "width": int(kwargs.get("width", 0) or 0),
                "height": int(kwargs.get("height", 0) or 0),
            }
            self.itemconfigure_calls.append(payload)

        @staticmethod
        def bbox(_token: str) -> Tuple[int, int, int, int]:
            """Return deterministic bounding box for scrollregion updates."""
            return (0, 0, 1440, 1920)

        def configure(self, **kwargs: Any) -> None:
            """Capture scrollregion configure calls."""
            self.scrollregion_calls.append(kwargs.get("scrollregion"))

    class _FrameStub:
        """Frame stub exposing requested content height for sync logic."""

        def __init__(self, reqheight: int) -> None:
            self._reqheight = int(reqheight)

        def winfo_reqheight(self) -> int:
            """Return deterministic requested frame height."""
            return int(self._reqheight)

    class _Harness:
        """Harness carrying Compare canvas state consumed by sync helper."""

        def __init__(self) -> None:
            self._compare_tab_canvas = _CanvasStub(width=920, height=520)
            self._compare_tab_canvas_window_id = "compare-window"
            self._compare_tab_content_frame = _FrameStub(reqheight=1180)

    harness = _Harness()
    UnifiedApp._compare_sync_tab_canvas_geometry(harness, width_px=760, height_px=480)
    if not harness._compare_tab_canvas.itemconfigure_calls:
        raise AssertionError("Expected compare canvas geometry sync to configure window size.")
    first_call = harness._compare_tab_canvas.itemconfigure_calls[-1]
    if first_call.get("width") != 760:
        raise AssertionError("Compare geometry sync should apply viewport width to window.")
    if first_call.get("height") != 1180:
        raise AssertionError("Compare geometry sync should preserve requested content height.")
    if not harness._compare_tab_canvas.scrollregion_calls:
        raise AssertionError("Compare geometry sync should refresh scrollregion after sizing.")

    harness._compare_tab_content_frame = _FrameStub(reqheight=320)
    UnifiedApp._compare_sync_tab_canvas_geometry(harness, width_px=640, height_px=700)
    second_call = harness._compare_tab_canvas.itemconfigure_calls[-1]
    if second_call.get("height") != 700:
        raise AssertionError("Compare geometry sync should expand window height to viewport when larger.")


def _regression_test_compare_split_persistence_allows_free_drag() -> None:
    """Validate Compare split persistence keeps user sash placement without snapback.

    Purpose:
        Ensure compare split persistence no longer enforces bottom-pane clamp snapback.
    Why:
        Compare users need full-range sash control for side-by-side and cycle-table balance.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Executes `_persist_compare_split_from_widget` against a local harness.
    Exceptions:
        Raises AssertionError when split persistence no longer reflects sash position.
    """

    class _PanedStub:
        """Paned stub exposing deterministic sash geometry for split persistence."""

        def __init__(self, *, height: int, sash_px: int) -> None:
            self._height = int(height)
            self._sash_px = int(sash_px)
            self.set_calls: List[int] = []

        @staticmethod
        def winfo_exists() -> bool:
            """Return paned exists sentinel for harness usage."""
            return True

        def winfo_height(self) -> int:
            """Return deterministic paned height in pixels."""
            return int(self._height)

        def sashpos(self, _index: int, *args: Any) -> int:
            """Read/write sash pixel position using Tk-compatible signature."""
            if args:
                self._sash_px = int(args[0])
                self.set_calls.append(self._sash_px)
            return int(self._sash_px)

    class _Harness:
        """Harness exposing split persistence helpers for regression coverage."""

        _compare_clamp_split_frac_for_visibility = UnifiedApp._compare_clamp_split_frac_for_visibility
        _persist_compare_split_from_widget = UnifiedApp._persist_compare_split_from_widget

        def __init__(self) -> None:
            self._compare_paned = _PanedStub(height=900, sash_px=870)
            self.save_calls = 0

        def _schedule_save_settings(self) -> None:
            """Count save scheduling calls from split persistence."""
            self.save_calls += 1

    prior_compare_state = copy.deepcopy(settings.get("compare_tab"))
    try:
        settings["compare_tab"] = _normalize_compare_tab_settings(settings.get("compare_tab"))
        harness = _Harness()
        persisted = UnifiedApp._persist_compare_split_from_widget(harness, save=True)
        expected = UnifiedApp._compare_clamp_split_frac_for_visibility(
            harness,
            float(870.0 / 900.0),
            total_height=900,
        )
        if persisted is None:
            raise AssertionError("Expected split persistence to return a normalized split fraction.")
        if abs(float(persisted) - float(expected)) > 1e-9:
            raise AssertionError(
                f"Expected persisted split {expected:.6f}, got {float(persisted):.6f}."
            )
        state = _normalize_compare_tab_settings(settings.get("compare_tab"))
        actual_state_split = float(state.get("split_frac", DEFAULT_COMPARE_SPLIT_FRAC))
        if abs(actual_state_split - float(expected)) > 1e-9:
            raise AssertionError(
                f"Expected compare state split {expected:.6f}, got {actual_state_split:.6f}."
            )
        if harness._compare_paned.sashpos(0) != 870:
            raise AssertionError(
                "Compare split persistence should not snap sash position for "
                "user-selected in-range values."
            )
        if harness.save_calls != 1:
            raise AssertionError("Expected exactly one split-save scheduling call.")
    finally:
        settings["compare_tab"] = prior_compare_state


def _regression_test_compare_sash_release_syncs_tab_canvas_geometry() -> None:
    """Validate Compare sash release triggers outer-tab geometry synchronization.

    Purpose:
        Ensure immediate sash-release callbacks refresh compare tab scroll geometry.
    Why:
        Without explicit post-sash sync, the outer compare scrollregion can remain stale.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Executes `_on_compare_paned_release` against a local harness.
    Exceptions:
        Raises AssertionError when release callback wiring regresses.
    """

    class _Harness:
        """Harness recording callbacks invoked from compare sash-release handler."""

        def __init__(self) -> None:
            self.persist_calls: List[bool] = []
            self.sync_calls = 0
            self.debounce_calls = 0
            self.resize_calls: List[str] = []

        def _persist_compare_split_from_widget(self, *, save: bool = True) -> Optional[float]:
            """Record split-persist calls from sash release."""
            self.persist_calls.append(bool(save))
            return 0.62

        def _compare_sync_tab_canvas_geometry(self) -> None:
            """Record geometry-sync invocations from sash release."""
            self.sync_calls += 1

        def _compare_update_split_persist_debounced(self) -> None:
            """Record debounced split scheduling calls."""
            self.debounce_calls += 1

        def _compare_schedule_resize(self, side_key: str) -> None:
            """Record compare side resize scheduling calls."""
            self.resize_calls.append(str(side_key))

    harness = _Harness()
    UnifiedApp._on_compare_paned_release(harness)
    if harness.persist_calls != [True]:
        raise AssertionError("Expected sash release to persist split once with save=True.")
    if harness.sync_calls != 1:
        raise AssertionError("Expected sash release to refresh compare tab canvas geometry.")
    if harness.debounce_calls != 1:
        raise AssertionError("Expected sash release to queue debounced split persistence.")
    if harness.resize_calls != ["A", "B"]:
        raise AssertionError("Expected sash release to queue resize refresh for both sides.")


def _regression_test_compare_split_debounce_syncs_tab_canvas_geometry() -> None:
    """Validate debounced Compare split persistence refreshes outer-tab geometry.

    Purpose:
        Ensure delayed split-settle callback refreshes compare tab scroll geometry.
    Why:
        Compare pane size can continue changing after release; delayed sync keeps
        scrollregion accurate for the uptake section.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Executes `_compare_update_split_persist_debounced` on a local harness.
    Exceptions:
        Raises AssertionError when delayed split-sync wiring regresses.
    """

    class _Harness:
        """Harness providing timer stubs for debounced split-persistence callback."""

        _compare_update_split_persist_debounced = (
            UnifiedApp._compare_update_split_persist_debounced
        )

        def __init__(self) -> None:
            self._compare_split_settle_after_id: Optional[str] = None
            self.pending_callback: Optional[Callable[[], None]] = None
            self.after_calls: List[int] = []
            self.cancel_calls: List[str] = []
            self.persist_calls = 0
            self.sync_calls = 0
            self.resize_calls: List[str] = []

        def after_cancel(self, after_id: str) -> None:
            """Record canceled timer ids for debounce coverage."""
            self.cancel_calls.append(str(after_id))

        def after(self, delay_ms: int, callback: Callable[[], None]) -> str:
            """Store delayed callback and return deterministic timer id."""
            self.after_calls.append(int(delay_ms))
            self.pending_callback = callback
            return "after-compare-split"

        def _persist_compare_split_from_widget(self, *, save: bool = True) -> Optional[float]:
            """Record delayed split persistence calls."""
            _ = bool(save)
            self.persist_calls += 1
            return 0.61

        def _compare_sync_tab_canvas_geometry(self) -> None:
            """Record delayed compare-tab geometry sync calls."""
            self.sync_calls += 1

        def _compare_schedule_resize(self, side_key: str) -> None:
            """Record delayed resize scheduling side keys."""
            self.resize_calls.append(str(side_key))

    harness = _Harness()
    UnifiedApp._compare_update_split_persist_debounced(harness)
    if harness._compare_split_settle_after_id != "after-compare-split":
        raise AssertionError("Expected debounce scheduling to store the timer id.")
    if harness.pending_callback is None:
        raise AssertionError("Expected debounce scheduling to capture a settle callback.")
    harness.pending_callback()
    if harness._compare_split_settle_after_id is not None:
        raise AssertionError("Expected settle callback to clear pending timer id.")
    if harness.persist_calls != 1:
        raise AssertionError("Expected delayed split persistence to run exactly once.")
    if harness.sync_calls != 1:
        raise AssertionError("Expected delayed split persistence to refresh canvas geometry.")
    if harness.resize_calls != ["A", "B"]:
        raise AssertionError("Expected delayed split persistence to refresh both compare panes.")


def _regression_test_finalize_layout_force_draw_single_pass() -> None:
    """Validate force-draw finalize path executes a single blocking draw.

    Purpose:
        Ensure force-draw finalization does not issue duplicate `canvas.draw` calls.
    Why:
        Duplicate blocking draws substantially increase UI stall time on large figures.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Executes `_finalize_matplotlib_canvas_layout` with local canvas/widget stubs.
    Exceptions:
        Raises AssertionError when force-draw performs more than one draw call.
    """

    class _WidgetStub:
        """Minimal Tk widget stub exposing deterministic width/height values."""

        @staticmethod
        def winfo_width() -> int:
            """Return fixed widget width in pixels."""
            return 1200

        @staticmethod
        def winfo_height() -> int:
            """Return fixed widget height in pixels."""
            return 700

        @staticmethod
        def winfo_reqwidth() -> int:
            """Return fixed requested width in pixels."""
            return 1200

        @staticmethod
        def winfo_reqheight() -> int:
            """Return fixed requested height in pixels."""
            return 700

    class _CanvasStub:
        """Canvas stub that counts draw and draw_idle invocations."""

        def __init__(self) -> None:
            self.draw_calls = 0
            self.draw_idle_calls = 0

        @staticmethod
        def get_renderer() -> object:
            """Return non-None renderer sentinel to avoid needs-draw fallback path."""
            return object()

        def draw(self) -> None:
            """Count blocking draw calls."""
            self.draw_calls += 1

        def draw_idle(self) -> None:
            """Count non-blocking draw requests."""
            self.draw_idle_calls += 1

    fig = Figure(figsize=(4.0, 3.0), dpi=100)
    canvas = _CanvasStub()
    widget = _WidgetStub()
    UnifiedApp._finalize_matplotlib_canvas_layout(
        object(),
        canvas=canvas,
        fig=fig,
        tk_widget=widget,
        keep_export_size=False,
        trigger_resize_event=False,
        force_draw=True,
    )
    if canvas.draw_calls != 1:
        raise AssertionError(
            f"Expected one blocking draw for force_draw=True, got {canvas.draw_calls}."
        )
    if canvas.draw_idle_calls != 0:
        raise AssertionError("Force draw path should return before draw_idle scheduling.")


