def _regression_test_ledger_formula_expression_safety() -> None:
    """Validate Ledger safe-formula evaluator accepts arithmetic and rejects unsafe syntax.

    Purpose:
        Guard expression-evaluator safety for persisted custom formula columns.
    Why:
        Formula persistence must never execute arbitrary Python code.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Executes formula helper functions with deterministic sample payloads.
    Exceptions:
        Raises AssertionError when safe or unsafe expression behavior regresses.
    """
    safe_names = {"final_mass_g", "cycles"}
    safe_value = _evaluate_safe_ledger_formula_expression(
        "final_mass_g / cycles",
        {"final_mass_g": 12.0, "cycles": 3.0},
        allowed_names=set(safe_names),
    )
    if safe_value != 4.0:
        raise AssertionError(f"Expected safe Ledger formula result 4.0, got {safe_value!r}.")

    unsafe_value = _evaluate_safe_ledger_formula_expression(
        "__import__('os').system('calc')",
        {"final_mass_g": 12.0, "cycles": 3.0},
        allowed_names=set(safe_names),
    )
    if unsafe_value is not None:
        raise AssertionError("Unsafe Ledger formula syntax should be rejected.")

    name_set = _ledger_formula_identifier_names("final_mass_g + custom_rate")
    if name_set != {"final_mass_g", "custom_rate"}:
        raise AssertionError(
            f"Expected formula identifier extraction for arithmetic names, got {name_set!r}."
        )
    bad_name_set = _ledger_formula_identifier_names("sum([1,2,3])")
    if bad_name_set is not None:
        raise AssertionError("Unsafe formula identifier parsing should return None.")


def _regression_test_ledger_state_normalization_custom_schema() -> None:
    """Validate Ledger table/entry normalization preserves custom schema and values.

    Purpose:
        Guard backward-compatible Ledger migration for custom columns and values.
    Why:
        Startup normalization must not drop persisted custom keys across upgrades.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Executes normalization helpers with deterministic legacy-style payloads.
    Exceptions:
        Raises AssertionError when normalized schema/value retention regresses.
    """
    raw_table = {
        "column_order": ["run_date", "custom_assay", "profile_name"],
        "view_mode": "Fit to Content",
        "view_profiles": {"fit": {"column_widths": {"custom_assay": 210}}},
        "custom_columns": [
            {"key": "custom_assay", "label": "Assay", "type": "number", "formula": ""},
            {"key": "custom_note", "label": "Custom Note", "type": "text", "formula": ""},
        ],
    }
    allowed = _ledger_allowed_columns_from_custom_columns(
        _normalize_ledger_custom_columns(raw_table.get("custom_columns"))
    )
    normalized_table = _normalize_ledger_table_settings(raw_table, allowed_columns=allowed)
    normalized_order = list(normalized_table.get("column_order") or [])
    if "custom_assay" not in normalized_order:
        raise AssertionError("Normalized Ledger column order should retain custom columns.")
    if normalized_table.get("view_mode") != "fit":
        raise AssertionError("Ledger view_mode normalization should map label text to token.")

    normalized_entries = _normalize_ledger_entries_settings(
        [
            {
                "profile_name": "Profile A",
                "custom_values": {"custom_assay": 99.1, "unknown_key": "keep"},
            }
        ]
    )
    if not normalized_entries:
        raise AssertionError("Ledger entry normalization should keep valid rows.")
    custom_values = normalized_entries[0].get("custom_values")
    if not isinstance(custom_values, Mapping) or custom_values.get("unknown_key") != "keep":
        raise AssertionError("Ledger entry normalization should preserve unknown custom value keys.")


def _regression_test_final_report_generation_dispatch_splash_lifecycle() -> None:
    """Validate staged Final Report generation dispatch splash lifecycle handling.

    Purpose:
        Ensure format-combo dispatch drives one shared splash lifecycle.
    Why:
        Report tab generation now routes through shared splash/progress staging.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Executes dispatch helper against a local harness.
    Exceptions:
        Raises AssertionError when splash or dispatch stage routing regresses.
    """

    class _Harness:
        """Harness capturing staged generation and splash callbacks."""

        def __init__(self) -> None:
            self.show_calls = 0
            self.hide_calls = 0
            self.pdf_calls = 0
            self.png_calls = 0
            self.html_calls = 0

        def _show_operation_splash(self, _title: str, *, context: str) -> None:
            """Record splash show invocation for dispatch lifecycle checks."""
            if context != "final_report_generation":
                raise AssertionError("Unexpected splash context in report dispatch.")
            self.show_calls += 1

        @staticmethod
        def _update_operation_splash(**_kwargs: Any) -> None:
            """No-op splash update hook for staged dispatch regression."""
            return None

        def _hide_operation_splash(self, *, context: Optional[str] = None) -> None:
            """Record splash hide invocation for dispatch lifecycle checks."""
            if context != "final_report_generation":
                raise AssertionError("Unexpected splash hide context in report dispatch.")
            self.hide_calls += 1

        def after(self, _delay_ms: int, callback: Callable[[], None]) -> Optional[str]:
            """Execute scheduled callback immediately for deterministic testing."""
            callback()
            return None

        @staticmethod
        def update_idletasks() -> None:
            """No-op Tk idle update hook for regression harness."""
            return None

        def _generate_final_report_pdf(self) -> None:
            """Record PDF generation stage execution."""
            self.pdf_calls += 1

        def _generate_final_report_png(self) -> None:
            """Record PNG generation stage execution."""
            self.png_calls += 1

        def _generate_final_report_html(self, *, preview_only: bool = False) -> None:
            """Record HTML generation stage execution."""
            if preview_only:
                raise AssertionError("Dispatch should call HTML export with preview_only=False.")
            self.html_calls += 1

    harness = _Harness()
    UnifiedApp._dispatch_final_report_generation_choice(harness, "pdf+png+html")
    if (harness.pdf_calls, harness.png_calls, harness.html_calls) != (1, 1, 1):
        raise AssertionError("Expected staged dispatch to execute PDF/PNG/HTML once each.")
    if harness.show_calls != 1 or harness.hide_calls != 1:
        raise AssertionError("Expected one shared splash show/hide for combo generation.")
    UnifiedApp._dispatch_final_report_generation_choice(harness, "html")
    if harness.html_calls != 2:
        raise AssertionError("Expected standalone HTML dispatch to execute one additional HTML stage.")
    if harness.show_calls != 2 or harness.hide_calls != 2:
        raise AssertionError("Expected one shared splash lifecycle per dispatch invocation.")


def _regression_test_profile_load_splash_deferred_completion() -> None:
    """Validate deferred profile-load splash completion gating behavior.

    Purpose:
        Ensure profile-load splash remains active until deferred restore settles.
    Why:
        Process Profiles load now depends on `_is_applying_columns` and
        `_profile_restore_pending` completion before teardown.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Executes splash-completion helpers against a local harness.
    Exceptions:
        Raises AssertionError when defer/finish gating regresses.
    """

    class _Harness:
        """Harness exposing profile-load splash completion state controls."""

        def __init__(self) -> None:
            self._profile_load_splash_active = True
            self._is_applying_columns = True
            self._profile_restore_pending: Optional[Dict[str, Any]] = {"pending": True}
            self.finish_calls: List[Tuple[bool, str]] = []

        def _finish_profile_load_splash(self, *, succeeded: bool, detail: str) -> None:
            """Record finish calls for deferred-completion assertions."""
            self.finish_calls.append((bool(succeeded), str(detail)))

    harness = _Harness()
    finished_early = UnifiedApp._maybe_finish_profile_load_splash(
        harness,
        succeeded=True,
        detail="early",
    )
    if finished_early:
        raise AssertionError("Profile-load splash should not finish while deferred restore is pending.")
    if harness.finish_calls:
        raise AssertionError("Deferred splash finish should not be invoked before restore settles.")
    harness._is_applying_columns = False
    harness._profile_restore_pending = None
    finished_after = UnifiedApp._maybe_finish_profile_load_splash(
        harness,
        succeeded=True,
        detail="ready",
    )
    if not finished_after:
        raise AssertionError("Profile-load splash should finish once deferred restore settles.")
    if harness.finish_calls != [(True, "ready")]:
        raise AssertionError("Expected one successful deferred splash completion call.")


def _regression_test_profile_restore_sheet_selection_autorepair() -> None:
    """Validate malformed multi-sheet restore state repairs to single-sheet mode.

    Purpose:
        Exercise profile restore sheet-selection normalization without building Tk.
    Why:
        Startup autosave can persist multi-sheet mode with no selected sheets; a
        valid stored single-sheet selection should restore silently instead of
        entering the missing-data apply loop.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Mutates a local profile-state dictionary through the production helper.
    Exceptions:
        Raises AssertionError when repair behavior regresses.
    """

    class _Harness:
        """Harness exposing workbook sheet names for restore normalization."""

        def __init__(self) -> None:
            """Initialize deterministic workbook sheet names for the test."""
            self.sheet_names = ["Pressure Test Day 0", "Pressure Test Day 1"]

    state: dict[str, Any] = {
        "multi_sheet_enabled": True,
        "selected_sheet": "Pressure Test Day 0",
        "selected_sheets": [],
    }
    repaired = UnifiedApp._normalize_profile_restore_sheet_selection(
        _Harness(),
        state,
    )
    if not repaired:
        raise AssertionError("Valid single-sheet autosave selection should repair.")
    if bool(state.get("multi_sheet_enabled")):
        raise AssertionError("Empty multi-sheet restore should switch to single mode.")
    if state.get("selected_sheet") != "Pressure Test Day 0":
        raise AssertionError("Repair should preserve the valid selected sheet.")
    if state.get("selected_sheets") != []:
        raise AssertionError("Single-sheet repair should clear selected_sheets.")


def _regression_test_profile_restore_apply_validation_clears_pending() -> None:
    """Validate apply-column validation clears deferred restore state.

    Purpose:
        Exercise the missing selected-sheet validation path under profile restore.
    Why:
        A validation return with `_profile_restore_pending` still set causes
        startup restore polling to reschedule forever.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Runs `_apply_columns` against a local harness and records splash/status
        cleanup calls.
    Exceptions:
        Raises AssertionError when pending restore cleanup regresses.
    """

    class _StatusStub:
        """Status-label stub capturing text updates."""

        def __init__(self) -> None:
            """Initialize captured status text."""
            self.text = ""

        def config(self, **kwargs: Any) -> None:
            """Capture label configuration values used by the test."""
            self.text = str(kwargs.get("text") or "")

    class _Harness:
        """Harness exposing the first `_apply_columns` validation gate."""

        _abort_deferred_profile_restore = (
            UnifiedApp._abort_deferred_profile_restore
        )

        def __init__(self) -> None:
            """Initialize missing-sheet restore state for validation cleanup."""
            self.df = None
            self.multi_sheet_enabled = True
            self.file_path = "C:/tmp/profile.xlsx"
            self.selected_sheets: list[str] = []
            self._profile_restore_pending: dict[str, Any] | None = {
                "plot_elements": {}
            }
            self._profile_restore_abort_reason = ""
            self._profile_load_splash_active = True
            self._is_applying_columns = False
            self.lbl_status = _StatusStub()
            self.reset_calls = 0
            self.finish_calls: list[tuple[bool, str]] = []

        def _reset_apply_buttons_state(self) -> None:
            """Record apply-button reset calls from the validation path."""
            self.reset_calls += 1

        def _finish_profile_load_splash(
            self,
            *,
            succeeded: bool,
            detail: str,
        ) -> None:
            """Record splash completion calls for cleanup assertions."""
            self.finish_calls.append((bool(succeeded), str(detail)))

    harness = _Harness()
    UnifiedApp._apply_columns(harness)
    if harness._profile_restore_pending is not None:
        raise AssertionError("Deferred restore pending state should be cleared.")
    if "selected sheets are missing" not in harness._profile_restore_abort_reason:
        raise AssertionError("Restore abort reason should describe missing sheets.")
    if harness.finish_calls != [
        (
            False,
            "Profile restore could not apply columns because the file or "
            "selected sheets are missing.",
        )
    ]:
        raise AssertionError("Profile-load splash should finish failed once.")
    if harness.reset_calls != 1:
        raise AssertionError("Apply button state should be reset after abort.")


def _regression_test_profile_restore_invalid_sheet_aborts_before_apply() -> None:
    """Validate invalid stored sheets abort restore before column apply starts.

    Purpose:
        Exercise `_restore_workspace_from_profile` with unavailable stored sheets.
    Why:
        Restore must not start deferred column apply unless the profile has a valid
        workbook sheet target.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Runs restore against a local harness and captures skipped-restore status.
    Exceptions:
        Raises AssertionError when invalid sheets still reach apply-column logic.
    """

    class _StatusStub:
        """Status-label stub capturing restore status text."""

        def __init__(self) -> None:
            """Initialize captured status text."""
            self.text = ""

        def config(self, **kwargs: Any) -> None:
            """Capture label text assigned during restore abort."""
            self.text = str(kwargs.get("text") or "")

    class _Harness:
        """Harness exposing profile restore with invalid sheet selection."""

        _deserialize_workspace_state = UnifiedApp._deserialize_workspace_state
        _normalize_profile_restore_sheet_selection = (
            UnifiedApp._normalize_profile_restore_sheet_selection
        )

        def __init__(self) -> None:
            """Initialize profile-restore state and call counters."""
            self.sheet_names: list[str] = []
            self.file_path = ""
            self.selected_sheets: list[str] = []
            self.multi_sheet_enabled = False
            self.e_file = None
            self.lbl_status = _StatusStub()
            self.splash_updates: list[dict[str, Any]] = []
            self.apply_calls = 0
            self.set_multi_calls = 0

        def _update_operation_splash(self, **kwargs: Any) -> None:
            """Capture restore splash progress updates."""
            self.splash_updates.append(dict(kwargs))

        @staticmethod
        def _resolve_profile_dataset_path(path: Optional[str]) -> Optional[str]:
            """Return the supplied dataset path without opening relink dialogs."""
            return str(path or "").strip() or None

        @staticmethod
        def _clear_workspace_state() -> None:
            """No-op workspace clear for restore harness isolation."""

        @staticmethod
        def _apply_profile_identifiers(
            identifiers: Mapping[str, Any] | None
        ) -> None:
            """No-op identifier restore hook for this regression."""
            _ = identifiers

        @staticmethod
        def _apply_profile_plot_settings(plot_settings: Mapping[str, Any]) -> None:
            """No-op plot settings restore hook for this regression."""
            _ = plot_settings

        @staticmethod
        def _apply_profile_reaction_basis(
            reaction_basis: Mapping[str, Any]
        ) -> None:
            """No-op reaction-basis restore hook for this regression."""
            _ = reaction_basis

        @staticmethod
        def _apply_profile_reaction_dashboard_state(
            reaction_dashboard_state: Mapping[str, Any]
        ) -> None:
            """No-op dashboard restore hook for this regression."""
            _ = reaction_dashboard_state

        @staticmethod
        def _apply_profile_cycle_markers(cycle_markers: Any) -> None:
            """No-op cycle marker restore hook for this regression."""
            _ = cycle_markers

        def _load_sheet_names(self) -> None:
            """Provide workbook sheets that do not include the stored profile sheet."""
            self.sheet_names = ["Actual Sheet"]

        def _set_multi_sheet_enabled(
            self,
            enabled: bool,
            *,
            persist: bool = True,
        ) -> None:
            """Record unexpected mode writes after invalid sheet detection."""
            _ = enabled
            _ = persist
            self.set_multi_calls += 1

        def _apply_column_selection(
            self,
            *,
            auto_refresh_axes: bool = False,
        ) -> None:
            """Record unexpected deferred apply starts."""
            _ = auto_refresh_axes
            self.apply_calls += 1

    profile_doc = {
        "payload": {
            "dataset_path": "C:/tmp/profile.xlsx",
            "multi_sheet_enabled": True,
            "selected_sheet": "Missing Sheet",
            "selected_sheets": [],
        }
    }
    harness = _Harness()
    restored = UnifiedApp._restore_workspace_from_profile(harness, profile_doc)
    if restored:
        raise AssertionError("Invalid stored sheet selection should abort restore.")
    if harness.apply_calls != 0:
        raise AssertionError("Invalid sheet restore should not start column apply.")
    if harness.set_multi_calls != 0:
        raise AssertionError("Invalid sheet restore should abort before mode writes.")
    if "invalid" not in harness.lbl_status.text.lower():
        raise AssertionError("Invalid sheet restore should publish status text.")


def _regression_test_profile_identifiers_round_trip_and_ledger_prefill() -> None:
    """Validate profile identifier normalization and Ledger prefill propagation.

    Purpose:
        Guard schema-level profile identifier persistence and Ledger prefill wiring.
    Why:
        New profile metadata fields must persist and populate Add From Profile.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Temporarily monkeypatches Rust mode helper to force Python path.
    Exceptions:
        Raises AssertionError when identifier or prefill propagation regresses.
    """
    normalized_empty = _normalize_profile_identifiers(None)
    if normalized_empty != {
        "project_number": "",
        "batch_number": "",
        "item_number": "",
    }:
        raise AssertionError("Expected empty profile identifier defaults for missing payload.")
    normalized_payload = _normalize_profile_identifiers(
        {"project_number": "P-42", "batch_number": "B-07", "item_number": "I-3"}
    )
    if normalized_payload.get("project_number") != "P-42":
        raise AssertionError("Profile identifier normalization should retain project number.")

    original_mode_fn = globals().get("_current_rust_backend_mode")
    globals()["_current_rust_backend_mode"] = lambda: "python"
    try:

        class _Harness:
            """Harness providing deterministic compare payload hooks for prefill."""

            @staticmethod
            def _compare_parse_float_entry(raw_value: Any) -> Optional[float]:
                """Parse optional finite non-negative floats for harness checks."""
                if raw_value in (None, ""):
                    return None
                try:
                    value = float(raw_value)
                except Exception:
                    return None
                if not math.isfinite(value) or value < 0.0:
                    return None
                return float(value)

            @staticmethod
            def _compare_build_render_context_from_bundle(
                _bundle: Dict[str, Any],
            ) -> Tuple[None, List[Dict[str, Any]], Optional[float], Dict[str, Any]]:
                """Return deterministic cycle rows for prefill metric extraction."""
                cycle_rows = [
                    {"cycle_id": 1, "cumulative_co2_mass_g": 0.41},
                    {"cycle_id": 2, "cumulative_co2_mass_g": 0.88},
                ]
                return None, cycle_rows, None, {}

            @staticmethod
            def _compare_resolve_reaction_basis(_bundle: Dict[str, Any]) -> Dict[str, Any]:
                """Return deterministic reaction basis payload for prefill checks."""
                return {
                    "starting_mass_g": 30.0,
                    "starting_material_mw_g_mol": 106.0,
                    "stoich_mol_gas_per_mol_starting": 1.0,
                    "gas_molar_mass": 44.01,
                }

        harness = _Harness()
        bundle = {
            "state": {
                "profile_identifiers": {
                    "project_number": "P-42",
                    "batch_number": "B-07",
                    "item_number": "I-3",
                }
            }
        }
        prefill = UnifiedApp._ledger_prefill_from_profile_bundle(
            harness, "Profile A", bundle
        )
        if prefill.get("project_number") != "P-42":
            raise AssertionError("Ledger prefill should propagate profile Project # identifier.")
        if prefill.get("batch_number") != "B-07":
            raise AssertionError("Ledger prefill should propagate profile Batch # identifier.")
        if prefill.get("item_number") != "I-3":
            raise AssertionError("Ledger prefill should propagate profile Item # identifier.")
        if prefill.get("cycles") != 2:
            raise AssertionError("Ledger prefill should include computed cycle count.")
        if prefill.get("total_dp_uptake") != 0.88:
            raise AssertionError("Ledger prefill should resolve cumulative uptake from cycle rows.")
    finally:
        if original_mode_fn is not None:
            globals()["_current_rust_backend_mode"] = original_mode_fn
        else:
            globals().pop("_current_rust_backend_mode", None)


def _regression_test_ledger_comma_format_ui_helpers() -> None:
    """Validate Ledger grouped-number formatting and input normalization helpers.

    Purpose:
        Guard comma formatting/parsing behavior across Ledger display helpers.
    Why:
        Ledger UI now shows grouped thousands while storing unformatted numerics.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Executes display-format helper paths against a local harness.
    Exceptions:
        Raises AssertionError when comma format/parse behavior regresses.
    """

    class _Harness:
        """Harness exposing custom-column hooks for Ledger display helper checks."""

        _ledger_format_number_with_grouping = UnifiedApp._ledger_format_number_with_grouping

        @staticmethod
        def _ledger_custom_column_definitions_map() -> Dict[str, Dict[str, str]]:
            """Return deterministic custom schema for display-format assertions."""
            return {
                "custom_number": {"key": "custom_number", "type": "number"},
                "custom_formula": {"key": "custom_formula", "type": "formula"},
            }

        @staticmethod
        def _ledger_formula_value_for_row(
            _row: Mapping[str, Any], _column_key: str
        ) -> Optional[float]:
            """Return deterministic formula value for grouped formatting checks."""
            return 12345.6789

    harness = _Harness()
    grouped = UnifiedApp._ledger_format_number_with_grouping(
        harness, 12345.678, decimals=2
    )
    if grouped != "12,345.68":
        raise AssertionError(f"Expected grouped decimal formatting, got {grouped!r}.")
    normalized = UnifiedApp._ledger_normalize_numeric_input(harness, "1,234.50")
    if normalized != "1234.50":
        raise AssertionError("Expected comma-stripped numeric input normalization.")
    row = {"cycles": 12345, "custom_values": {"custom_number": 9876.54321}}
    cycles_display = UnifiedApp._ledger_display_value_for_column(harness, row, "cycles")
    if cycles_display != "12,345":
        raise AssertionError(f"Expected grouped integer display for cycles, got {cycles_display!r}.")
    custom_number_display = UnifiedApp._ledger_display_value_for_column(
        harness, row, "custom_number"
    )
    if "," not in custom_number_display:
        raise AssertionError("Expected grouped display for custom numeric column.")
    formula_display = UnifiedApp._ledger_display_value_for_column(
        harness, row, "custom_formula"
    )
    if formula_display != "12,345.6789":
        raise AssertionError(
            f"Expected grouped formula display with fixed decimals, got {formula_display!r}."
        )


def _regression_test_workflow_tile_breakpoints() -> None:
    """Validate responsive workflow tile column breakpoints.

    Purpose:
        Guard 2->1 tile column behavior used by workflow input/action/KPI cards.
    Why:
        Planning/Analysis/Reprocessing layouts should expand on wide canvases
        and collapse cleanly when narrow.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Executes tile-breakpoint helper against a lightweight harness.
    Exceptions:
        Raises AssertionError on breakpoint regressions.
    """

    class _Harness:
        """Harness exposing workflow tile breakpoint helper."""

    harness = _Harness()
    if UnifiedApp._sol_tile_columns_for_width(harness, None) != 1:
        raise AssertionError("Expected one tile column when width is unavailable.")
    if UnifiedApp._sol_tile_columns_for_width(harness, 640) != 1:
        raise AssertionError("Expected one tile column for narrow workflow width.")
    if UnifiedApp._sol_tile_columns_for_width(harness, 920) != 2:
        raise AssertionError("Expected two tile columns at the responsive breakpoint.")
    if UnifiedApp._sol_tile_columns_for_width(harness, 1400) != 2:
        raise AssertionError("Expected two tile columns for wide workflow widths.")


def _regression_test_rust_ledger_wrappers() -> None:
    """Validate Rust Ledger wrappers parity fallback and payload sanitization.

    Purpose:
        Ensure Ledger Rust wrappers fail closed and sanitize valid payloads.
    Why:
        Ledger acceleration must never break filter/sort or prefill workflows.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Temporarily monkeypatches `_load_rust_backend`.
    Exceptions:
        Raises AssertionError when wrapper behavior regresses.
    """
    original_loader = globals().get("_load_rust_backend")
    try:
        globals()["_load_rust_backend"] = lambda: None
        if (
            _rust_ledger_sort_filter_indices_core(
                _synthetic_ledger_sort_filter_entries(),
                filter_value="All Profiles",
                sort_mode="manual",
                sort_key="updated_at",
                sort_desc=False,
                sort_column_type="text",
            )
            is not None
        ):
            raise AssertionError("Ledger sort/filter wrapper should return None when backend is absent.")
        if (
            _rust_ledger_prefill_metrics_core(
                [{"cycle_id": 1}],
                total_drop_value=None,
                reaction_basis={},
            )
            is not None
        ):
            raise AssertionError("Ledger prefill wrapper should return None when backend is absent.")

        class _FakeRustBackend:
            """Minimal Rust backend stub for Ledger wrapper regression checks."""

            @staticmethod
            def ledger_sort_filter_indices_core(
                _rows: List[Dict[str, Any]],
                _filter_value: str,
                _sort_mode: str,
                _sort_key: str,
                _sort_desc: bool,
                _sort_column_type: str,
            ) -> List[int]:
                """Return deterministic index ordering payload for wrapper assertions."""
                return [1, 0]

            @staticmethod
            def ledger_prefill_metrics_core(
                _rows: List[Dict[str, Any]],
                _total_drop_value: Optional[float],
                _basis: Dict[str, Any],
            ) -> Dict[str, Any]:
                """Return deterministic metrics payload for wrapper assertions."""
                return {
                    "cycles": 2,
                    "total_dp_uptake": 0.88,
                    "theoretical_yield_g": 12.45,
                }

        globals()["_load_rust_backend"] = lambda: _FakeRustBackend()
        indices = _rust_ledger_sort_filter_indices_core(
            _synthetic_ledger_sort_filter_entries(),
            filter_value="All Profiles",
            sort_mode="manual",
            sort_key="updated_at",
            sort_desc=False,
            sort_column_type="text",
        )
        if indices != [1, 0]:
            raise AssertionError(f"Unexpected Rust ledger sort/filter payload: {indices!r}")
        metrics = _rust_ledger_prefill_metrics_core(
            [{"cycle_id": 1}],
            total_drop_value=None,
            reaction_basis={},
        )
        if metrics != {
            "cycles": 2,
            "total_dp_uptake": 0.88,
            "theoretical_yield_g": 12.45,
        }:
            raise AssertionError(f"Unexpected Rust ledger prefill payload: {metrics!r}")
    finally:
        if original_loader is not None:
            globals()["_load_rust_backend"] = original_loader
        else:
            globals().pop("_load_rust_backend", None)


