def _regression_test_rust_advanced_speciation_numeric_parity() -> None:
    """Validate Rust/Python numeric parity for advanced speciation kernels.

    Purpose:
        Check representative chemistry cases across new Rust core kernels.
    Why:
        Regression coverage should detect parity drift before auto-policy can
        persist a Rust preference for advanced speciation workflows.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        None.
    Exceptions:
        Raises AssertionError on parity mismatches when Rust backend is present.
    """
    if _load_rust_backend() is None:
        return

    closed_py = _solve_carbonate_state(
        0.36,
        0.34,
        ka1=SOL_KA1,
        ka2=SOL_KA2,
        kw=SOL_KW,
        ionic_strength_cap=0.9,
        initial_ph_guess=8.4,
        speciation_mode=SPEC_MODE_CLOSED,
        fixed_h2co3=None,
        _prefer_rust=False,
    )
    closed_rust = _rust_carbonate_state_core(
        0.36,
        0.34,
        ka1=SOL_KA1,
        ka2=SOL_KA2,
        kw=SOL_KW,
        ionic_strength_cap=0.9,
        initial_ph_guess=8.4,
        speciation_mode=SPEC_MODE_CLOSED,
        fixed_h2co3=None,
    )
    if not _rust_carbonate_state_core_parity(closed_rust, closed_py):
        raise AssertionError("Closed-system carbonate-state parity mismatch.")

    fixed_py = _solve_carbonate_state(
        0.22,
        0.21,
        ka1=SOL_KA1,
        ka2=SOL_KA2,
        kw=SOL_KW,
        ionic_strength_cap=0.9,
        initial_ph_guess=8.2,
        speciation_mode=SPEC_MODE_FIXED_PCO2,
        fixed_h2co3=0.018,
        _prefer_rust=False,
    )
    fixed_rust = _rust_carbonate_state_core(
        0.22,
        0.21,
        ka1=SOL_KA1,
        ka2=SOL_KA2,
        kw=SOL_KW,
        ionic_strength_cap=0.9,
        initial_ph_guess=8.2,
        speciation_mode=SPEC_MODE_FIXED_PCO2,
        fixed_h2co3=0.018,
    )
    if not _rust_carbonate_state_core_parity(fixed_rust, fixed_py):
        raise AssertionError("Fixed-pCO2 carbonate-state parity mismatch.")

    forced_py = _python_forced_ph_distribution_core(
        0.28,
        0.27,
        8.35,
        ka1=SOL_KA1,
        ka2=SOL_KA2,
        kw=SOL_KW,
        ionic_strength_cap=0.9,
        fixed_h2co3=None,
        max_iter=80,
    )
    forced_rust = _rust_forced_ph_distribution_core(
        0.28,
        0.27,
        8.35,
        ka1=SOL_KA1,
        ka2=SOL_KA2,
        kw=SOL_KW,
        ionic_strength_cap=0.9,
        fixed_h2co3=None,
        max_iter=80,
    )
    if not _rust_forced_ph_distribution_core_parity(forced_rust, forced_py):
        raise AssertionError("Forced-pH distribution parity mismatch.")

    aqion_py = _python_aqion_closed_speciation_core(
        0.24,
        ka1=SOL_KA1,
        ka2=SOL_KA2,
        kw=SOL_KW,
        ph_low=2.0,
        ph_high=12.5,
    )
    aqion_rust = _rust_aqion_closed_speciation_core(
        0.24,
        ka1=SOL_KA1,
        ka2=SOL_KA2,
        kw=SOL_KW,
        ph_low=2.0,
        ph_high=12.5,
    )
    if not _rust_aqion_closed_speciation_core_parity(aqion_rust, aqion_py):
        raise AssertionError("Aqion closed-system parity mismatch.")

    compact_params = _compact_pitzer_params_for_rust(_NAOH_PITZER_PARAMS)
    if compact_params is None or _NAOH_PITZER_PARAMS is None:
        return
    na_total_m = 1.20
    kgw_for_900g = 20.0
    pitzer_cases = (
        0.0,
        na_total_m * 0.5,
        (900.0 / SOL_MW_CO2) / kgw_for_900g,
    )
    # Iterate over pitzer_cases to verify parity from low-carbon to 900 g trajectory.
    for ct_m in pitzer_cases:
        py_payload = _python_pitzer_solve_total_carbon_core(
            total_carbon_m=ct_m,
            total_sodium_m=na_total_m,
            pitzer_params=_NAOH_PITZER_PARAMS,
            max_iter=60,
        )
        rust_payload = _rust_pitzer_solve_total_carbon_core(
            ct_m,
            na_total_m,
            compact_params,
            max_iter=60,
        )
        if not _rust_pitzer_solve_total_carbon_core_parity(rust_payload, py_payload):
            raise AssertionError(
                f"NaOH-CO2 Pitzer parity mismatch at CT={ct_m:.6f} mol/kg."
            )


