def _regression_test_rust_tool_resolver_prefers_rustup_over_bad_path() -> None:
    """Validate interpreter-first resolver prefers rustup over bad PATH shims.

    Purpose:
        Ensure resolver precedence selects a healthy rustup tool candidate before
        accepting a bad PATH fallback shim.
    Why:
        Free-threaded runtime sessions must not trust stale Python Scripts shims
        that can fail with loader errors.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Temporarily monkeypatches tool resolver dependencies and shutil.which.
    Exceptions:
        Raises AssertionError when resolver precedence or rejected-candidate
        diagnostics regress.
    """
    original_override = globals().get("_rust_tool_override_path")
    original_scripts = globals().get("_runtime_interpreter_scripts_dir")
    original_rustup = globals().get("_resolve_rustup_managed_tool_path")
    original_validate = globals().get("_validate_rust_tool_candidate")
    original_which = shutil.which
    try:
        globals()["_rust_tool_override_path"] = (
            lambda *args, **kwargs: ""
        )
        globals()["_runtime_interpreter_scripts_dir"] = lambda: ""
        globals()["_resolve_rustup_managed_tool_path"] = (
            lambda tool_name, **_kwargs: (
                "C:/Users/test/.rustup/toolchains/stable-x86_64-pc-windows-gnu/bin/"
                f"{tool_name}.exe"
            )
        )

        def _which_stub(tool_name: str) -> Optional[str]:
            """Return one bad PATH shim candidate for cargo/rustc checks."""
            token = str(tool_name or "").strip().lower()
            if token in {"cargo", "rustc"}:
                return f"C:/Users/test/AppData/Local/Programs/Python/Python314/Scripts/{token}.exe"
            return None

        shutil.which = _which_stub

        def _validate_stub(
            tool_name: str,
            candidate_path: str,
            *,
            timeout_seconds: Optional[float] = None,
        ) -> Dict[str, Any]:
            """Return deterministic candidate validation for resolver regression."""
            _ = timeout_seconds
            path_text = str(candidate_path or "").replace("\\", "/")
            if "/.rustup/" in path_text:
                return {
                    "tool": tool_name,
                    "path": path_text,
                    "valid": True,
                    "reason": "ok",
                    "details": "cargo 1.0.0",
                    "arch_compatible": True,
                }
            return {
                "tool": tool_name,
                "path": path_text,
                "valid": False,
                "reason": "arch_incompatible",
                "details": "os error 216",
                "arch_compatible": False,
            }

        globals()["_validate_rust_tool_candidate"] = _validate_stub
        resolved = _resolve_rust_tool_for_runtime(
            "cargo",
            RUST_RUNTIME_PROFILE_FREE_THREADED,
            timeout_seconds=0.1,
        )
        if not bool(resolved.get("valid")):
            raise AssertionError("Expected resolver to find a valid rustup cargo path.")
        if str(resolved.get("source") or "") != RUST_TOOL_SOURCE_RUSTUP:
            raise AssertionError("Expected resolver to prefer rustup over bad PATH fallback.")
        rejected = list(resolved.get("rejected_candidates") or ())
        bad_path_rejected = [
            item
            for item in rejected
            if str(item.get("source") or "") == RUST_TOOL_SOURCE_PATH_FALLBACK
            and str(item.get("reason") or "") == "arch_incompatible"
        ]
        if not bad_path_rejected:
            raise AssertionError(
                "Expected bad PATH fallback shim to be reported as rejected."
            )
    finally:
        shutil.which = original_which
        if original_override is not None:
            globals()["_rust_tool_override_path"] = original_override
        else:
            globals().pop("_rust_tool_override_path", None)
        if original_scripts is not None:
            globals()["_runtime_interpreter_scripts_dir"] = original_scripts
        else:
            globals().pop("_runtime_interpreter_scripts_dir", None)
        if original_rustup is not None:
            globals()["_resolve_rustup_managed_tool_path"] = original_rustup
        else:
            globals().pop("_resolve_rustup_managed_tool_path", None)
        if original_validate is not None:
            globals()["_validate_rust_tool_candidate"] = original_validate
        else:
            globals().pop("_validate_rust_tool_candidate", None)


