def _regression_test_combined_authoritative_bottom_margin_not_reclaimed() -> None:
    """Validate combined render does not lower explicit profile bottom margins.

    Purpose:
        Exercise bottom-whitespace auto-fix with an authoritative combined layout
        manager and confirm the stored baseline survives the pass.
    Why:
        Display and export bottom-margin inputs must remain authoritative; render
        health may suggest lower margins but must not overwrite them silently.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Builds and closes one transient Matplotlib figure.
    Exceptions:
        Raises AssertionError when auto-fix shrinks the explicit bottom margin.
    """
    fig = Figure(figsize=(6.0, 4.0))
    FigureCanvasAgg(fig)
    ax = fig.add_subplot(111)
    ax.plot([0.0, 1.0], [0.0, 1.0])
    ax.tick_params(axis="x", pad=0)
    xlabel = fig.supxlabel("Elapsed Time", y=0.12)
    legend = fig.legend(
        [ax.lines[0]],
        ["Pressure"],
        loc="lower center",
        bbox_to_anchor=(0.5, 0.01),
    )
    try:
        fig._gl260_plot_id = "fig_combined_triple_axis"  # type: ignore[attr-defined]
        fig._gl260_xlabel_text = xlabel  # type: ignore[attr-defined]
        ax._gl260_axis_role = "primary"  # type: ignore[attr-defined]
    except Exception:
        # Best-effort guard; ignore metadata tagging failures in regression setup.
        pass
    explicit_bottom = 0.31
    layout_mgr = PlotLayoutManager(
        fig,
        mode="display",
        baseline_margins={
            "left": 0.12,
            "right": 0.90,
            "top": 0.88,
            "bottom": explicit_bottom,
        },
        margins_authoritative=True,
        legend_gap_pts=8.0,
        xlabel_tick_gap_pts=8.0,
        legend_margin_pts=2.0,
    )
    layout_mgr.register_axes(ax)
    layout_mgr.register_artist("xlabel", xlabel)
    layout_mgr.register_artist("plot_legend", legend)
    fig._gl260_layout_manager = layout_mgr  # type: ignore[attr-defined]
    prior_autofix_enabled = settings.get("layout_health_autofix_enabled")
    settings["layout_health_autofix_enabled"] = False
    try:
        layout_mgr.solve(max_passes=1, allow_draw=False)
    finally:
        if prior_autofix_enabled is None:
            settings.pop("layout_health_autofix_enabled", None)
        else:
            settings["layout_health_autofix_enabled"] = prior_autofix_enabled
    try:
        result = layout_health_autofix(
            fig,
            "fig_combined_triple_axis",
            "display",
            {
                "layout_health_autofix_enabled": True,
                "layout_health_max_passes": 2,
                "layout_health_check_legend_conflicts": True,
                "layout_health_check_x_axis_conflicts": True,
                "layout_health_min_gap_pts": 2.0,
                "layout_health_max_gap_pts": 140.0,
                "layout_health_max_bottom_whitespace_pts": 8.0,
            },
        )
        final_bottom = float(fig.subplotpars.bottom)
        baseline_bottom = float(layout_mgr._baseline_bottom)
    finally:
        plt.close(fig)
    if final_bottom < explicit_bottom - 1e-6:
        raise AssertionError(
            "Combined bottom margin should not be reduced by whitespace reclaim "
            f"(expected >= {explicit_bottom}, got {final_bottom})."
        )
    if baseline_bottom != explicit_bottom:
        raise AssertionError(
            "Combined layout-manager baseline bottom should remain authoritative "
            f"(expected {explicit_bottom}, got {baseline_bottom})."
        )
    if not result.get("issues"):
        raise AssertionError("Regression setup should report bottom whitespace.")


def _regression_test_layout_health_collects_analysis_timeline_target() -> None:
    """Validate active Advanced Speciation timeline layout-health targeting.

    Purpose:
        Ensure Developer Tools and wizard fallback discovery include the embedded
        Cycle Speciation Timeline in the Analysis workflow tab.
    Why:
        The embedded Advanced Speciation timeline must receive the same layout
        health coverage as generated tabs and previews.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Builds and closes one transient Matplotlib figure.
    Exceptions:
        Raises AssertionError when target discovery omits the timeline figure.
    """

    class _Notebook:
        """Small notebook stand-in returning the selected Advanced Speciation tab."""

        def __init__(self, selected: Any) -> None:
            """Initialize a deterministic notebook selection stub.

            Purpose:
                Store the selected-tab marker returned by `select`.
            Why:
                The regression needs active-tab behavior without constructing a
                real Tk notebook.
            Inputs:
                selected: Arbitrary object representing the selected tab.
            Outputs:
                None.
            Side Effects:
                Stores `selected` on the stub instance.
            Exceptions:
                None.
            """
            self.selected = selected

        def select(self) -> Any:
            """Return the configured selected-tab marker.

            Purpose:
                Emulate the subset of `ttk.Notebook.select` used by target
                discovery.
            Why:
                Layout-health discovery only needs the active tab identity.
            Inputs:
                None.
            Outputs:
                The selected-tab marker supplied at initialization.
            Side Effects:
                None.
            Exceptions:
                None.
            """
            return self.selected

    class _Harness:
        """Harness exposing active-figure collection dependencies."""

        _collect_active_figures_for_layout_health = (
            UnifiedApp._collect_active_figures_for_layout_health
        )

    fig = Figure()
    try:
        harness = _Harness()
        harness.tab_solubility_new = object()
        harness.tab_compare = object()
        harness.nb = _Notebook(harness.tab_solubility_new)
        harness._sol_cycle_spec_fig = fig
        harness._plot_tabs = []
        harness._canvases = []
        targets = UnifiedApp._collect_active_figures_for_layout_health(harness)
    finally:
        plt.close(fig)
    if ("fig_cycle_timeline", fig) not in targets:
        raise AssertionError(
            "Advanced Speciation Analysis timeline should be a layout-health target."
        )


def _regression_test_cycle_legend_number_formatting() -> None:
    """Validate comma thousands separators in cycle legend text.

    Purpose:
        Ensure shared cycle legend formatters cover counts, pressure, moles, and
        completion percentages.
    Why:
        Large cycle summaries should be readable consistently across legend paths.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        None.
    Exceptions:
        Raises AssertionError when comma grouping is absent.
    """
    if _format_cycle_legend_count(12345) != "12,345":
        raise AssertionError("Cycle counts should use comma grouping.")
    if _format_cycle_legend_number(12345.678, 2) != "12,345.68":
        raise AssertionError("Cycle numeric values should use comma grouping.")
    harness = object.__new__(UnifiedApp)
    lines = UnifiedApp._cycle_moles_legend_lines(
        harness,
        {
            "cycle_transfer": [
                {
                    "delta_pressure_psi": 12345.678,
                    "mean_temperature_c": 1234.5,
                    "moles_ideal": 1234.56789,
                    "moles_vdw": 9876.54321,
                }
            ],
            "total_moles_ideal": 12345.6789,
            "total_moles_vdw": 98765.4321,
            "vdw_used": True,
            "reagent_summary": {
                "completion_percent_ideal": 1234.5,
                "completion_percent_vdw": 9876.5,
                "vdw_available": True,
            },
        },
    )
    joined = "\n".join(lines)
    for expected in (
        "12,345.68 PSI",
        "1,234.567890 mol",
        "98,765.432100 mol",
        "9,876.50%",
    ):
        if expected not in joined:
            raise AssertionError(f"Missing comma-grouped cycle legend text: {expected}")


