def _regression_test_reaction_dashboard_import_cycle_auto_runs() -> None:
    """Validate Cycle Analysis import triggers a dashboard run.

    Purpose:
        Confirm the import action selects cycle payload mode and immediately
        refreshes the dashboard.
    Why:
        The redesigned workflow treats imported Cycle Analysis data as active
        operational input rather than a passive source selection.
    Inputs:
        None; uses a small harness with Tk-like variable stubs.
    Outputs:
        None.
    Side Effects:
        Mutates only the harness variable state.
    Exceptions:
        Raises AssertionError when source selection or auto-run behavior regresses.
    """

    class _Var:
        """Minimal variable stand-in for import auto-run tests."""

        def __init__(self, value: Any = "") -> None:
            """Store a deterministic variable value for get/set calls.

            Purpose:
                Emulate the small Tk variable API used by the import helper.
            Why:
                The regression should not construct a full Tk application.
            Args:
                value: Initial variable value.
            Returns:
                None.
            Side Effects:
                Stores the value on the instance.
            Exceptions:
                None.
            """
            self.value = value

        def get(self) -> Any:
            """Return the stored variable value.

            Purpose:
                Provide read access matching Tk variable behavior.
            Why:
                The import helper may inspect variable values through production
                callbacks after source selection.
            Args:
                None.
            Returns:
                Stored value.
            Side Effects:
                None.
            Exceptions:
                None.
            """
            return self.value

        def set(self, value: Any) -> None:
            """Replace the stored variable value.

            Purpose:
                Provide write access matching Tk variable behavior.
            Why:
                Source mode and display labels are updated during import.
            Args:
                value: Replacement variable value.
            Returns:
                None.
            Side Effects:
                Mutates stored value.
            Exceptions:
                None.
            """
            self.value = value

    class _Harness:
        """Small harness exposing the import helper under test."""

        _reaction_dashboard_import_cycle_payload = (
            UnifiedApp._reaction_dashboard_import_cycle_payload
        )

        def __init__(self) -> None:
            """Initialize import state for the harness.

            Purpose:
                Provide source variables, warnings, and payload state used by the
                production import method.
            Why:
                The test should assert behavior without running the full GUI.
            Args:
                None.
            Returns:
                None.
            Side Effects:
                Stores harness variables and counters.
            Exceptions:
                None.
            """
            self._cycle_last_transfer_payload = {"cycle_transfer": [{"cycle_id": 1}]}
            self._reaction_source_mode_var = _Var("manual")
            self._reaction_source_display_var = _Var("Manual gas mass / moles")
            self._reaction_cycle_focus_var = _Var("Cycle 2")
            self._reaction_warnings_var = _Var("")
            self._reaction_source_key_to_label = {
                key: label for key, label in REACTION_DASHBOARD_SOURCE_MODES
            }
            self.run_count = 0

        def _run_reaction_dashboard(self) -> None:
            """Record that the dashboard auto-run callback fired.

            Purpose:
                Avoid executing full reaction math in this focused import test.
            Why:
                The import helper contract is source selection plus run dispatch.
            Args:
                None.
            Returns:
                None.
            Side Effects:
                Increments `run_count`.
            Exceptions:
                None.
            """
            self.run_count += 1

    harness = _Harness()
    harness._reaction_dashboard_import_cycle_payload()
    if harness._reaction_source_mode_var.get() != "cycle_payload":
        raise AssertionError("Import should select cycle payload source mode.")
    if harness._reaction_cycle_focus_var.get() != "Latest":
        raise AssertionError("Import should reset cycle focus to Latest.")
    if harness.run_count != 1:
        raise AssertionError("Import should auto-run the dashboard once.")


def _regression_test_reaction_solution_charge_core() -> None:
    """Validate sodium/methanol/water charge-basis calculations.

    Purpose:
        Exercise the v4.15.8 sodium metal, wet methanol, water ppm, and explicit
        NaOH conversion model.
    Why:
        Reaction Dashboard yield math depends on computed sodium methoxide and
        total hydrolysis NaOH moles before stoichiometry runs.
    Inputs:
        None; uses fixed masses with water ppm by mass.
    Outputs:
        None.
    Side Effects:
        None.
    Exceptions:
        Raises AssertionError when water conversion, generated NaOH, or sodium
        methoxide availability changes unexpectedly.
    """
    result = _python_reaction_solution_charge_core(
        sodium_metal_mass_g=2.2989769,
        methanol_mass_g=100.0,
        water_ppm_by_mass=1800.0,
        explicit_naoh_mass_g=4.0,
    )
    water_mol = 0.18 / REACTION_WATER_MOLAR_MASS_G_MOL
    sodium_mol = 0.1
    expected_naome = sodium_mol - water_mol
    expected_total_naoh = water_mol + (4.0 / REACTION_NAOH_MOLAR_MASS_G_MOL)
    if abs(float(result.get("water_mol") or 0.0) - water_mol) > 1e-12:
        raise AssertionError("Water ppm by mass conversion should remain stable.")
    if abs(float(result.get("generated_naoh_mol") or 0.0) - water_mol) > 1e-12:
        raise AssertionError("Water should generate NaOH 1:1 from sodium.")
    if abs(float(result.get("sodium_methoxide_mol") or 0.0) - expected_naome) > 1e-12:
        raise AssertionError("NaOMe should be sodium remaining after water.")
    if abs(float(result.get("total_naoh_mol") or 0.0) - expected_total_naoh) > 1e-12:
        raise AssertionError("Total NaOH should include explicit plus generated.")


def _regression_test_reaction_charge_basis_applies_to_species_rows() -> None:
    """Validate charge-basis outputs feed Reaction Dashboard species rows.

    Purpose:
        Confirm the starter template maps sodium metal, methanol, water ppm, and
        explicit NaOH inputs into the species inventory sent to the reaction core.
    Why:
        The UI and compute path must not leave the new charge fields as
        diagnostics-only values.
    Inputs:
        None; uses a small harness without creating Tk widgets.
    Outputs:
        None.
    Side Effects:
        None.
    Exceptions:
        Raises AssertionError when adjusted species moles are not applied.
    """

    class _Var:
        """Minimal StringVar-like value holder for the reaction input harness."""

        def __init__(self, value: str) -> None:
            """Store one fixed input string for harness reads.

            Purpose:
                Provide the small `get()` API used by dashboard input helpers.
            Why:
                The regression should exercise input normalization without
                constructing Tk widgets.
            Args:
                value: String value returned by `get()`.
            Returns:
                None.
            Side Effects:
                Stores the value on the harness object.
            Exceptions:
                None.
            """
            self.value = value

        def get(self) -> str:
            """Return the stored input value.

            Purpose:
                Emulate `tk.StringVar.get()` for the dashboard method under test.
            Why:
                The input method only requires read access to field text.
            Args:
                None.
            Returns:
                Stored string value.
            Side Effects:
                None.
            Exceptions:
                None.
            """
            return self.value

    class _Harness:
        """Small harness exposing species-row methods without Tk construction."""

        _reaction_dashboard_input_float = UnifiedApp._reaction_dashboard_input_float
        _reaction_dashboard_input_text = UnifiedApp._reaction_dashboard_input_text
        _reaction_dashboard_species_rows_with_inputs = (
            UnifiedApp._reaction_dashboard_species_rows_with_inputs
        )

        def __init__(self, template: ReactionTemplate) -> None:
            """Initialize species and input rows used by the harness.

            Purpose:
                Provide enough instance state for the species-row application
                method to run without a full application object.
            Why:
                The regression must stay focused on charge-basis data flow.
            Args:
                template: Reaction template whose species rows are copied.
            Returns:
                None.
            Side Effects:
                Stores copied species rows and fake input variables.
            Exceptions:
                None.
            """
            self.rows = [asdict(species) for species in template.species]
            self._reaction_source_vars: Dict[str, Any] = {}
            self._reaction_input_vars = {
                "sodium_metal_mass_g": _Var("2.2989769"),
                "methanol_mass_g": _Var("100.0"),
                "methanol_water_ppm_by_mass": _Var("1800.0"),
                "sodium_hydroxide_mass_g": _Var("4.0"),
            }

        def _reaction_dashboard_collect_species_rows(self) -> List[Dict[str, Any]]:
            """Return copied species rows for the method under test.

            Purpose:
                Supply editable species rows to the dashboard method under test.
            Why:
                The production method reads species from a Treeview, which this
                focused regression intentionally avoids.
            Args:
                None.
            Returns:
                List of copied species row dictionaries.
            Side Effects:
                None.
            Exceptions:
                None.
            """
            return [dict(row) for row in self.rows]

    template = _builtin_reaction_templates()["sodium_methoxide_co_to_sodium_formate"]
    harness = _Harness(template)
    rows, charge_basis = UnifiedApp._reaction_dashboard_species_rows_with_inputs(
        harness, template
    )
    by_id = {row["species_id"]: row for row in rows}
    if not isinstance(charge_basis, Mapping):
        raise AssertionError("Charge-basis diagnostics should be returned.")
    if abs(
        float(by_id["sodium_methoxide"]["initial_moles"])
        - float(charge_basis["sodium_methoxide_mol"])
    ) > 1e-12:
        raise AssertionError("NaOMe species moles should use charge-basis output.")
    if abs(
        float(by_id["sodium_hydroxide"]["initial_moles"])
        - float(charge_basis["total_naoh_mol"])
    ) > 1e-12:
        raise AssertionError("NaOH species moles should include generated NaOH.")
    if abs(
        float(by_id["methanol"]["initial_moles"])
        - float(charge_basis["remaining_methanol_mol"])
    ) > 1e-12:
        raise AssertionError("Methanol species moles should be remaining methanol.")


def _regression_test_reaction_dashboard_input_metadata_and_equation_targets() -> None:
    """Validate required input metadata and equation species targeting.

    Purpose:
        Ensure every required starter-template field has tooltip/group metadata
        and that equation-visible species map back to UX inputs or species rows.
    Why:
        The redesigned dashboard relies on clear required labels, tooltips, and
        equation-token navigation.
    Inputs:
        None; uses the built-in sodium methoxide / CO template.
    Outputs:
        None.
    Side Effects:
        None.
    Exceptions:
        Raises AssertionError when metadata or species targeting regresses.
    """
    template = _builtin_reaction_templates()["sodium_methoxide_co_to_sodium_formate"]
    fields = {field.field_id: field for field in template.input_fields}
    required_ids = {
        "sodium_metal_mass_g",
        "methanol_mass_g",
        "methanol_water_ppm_by_mass",
    }
    if not required_ids.issubset(fields):
        raise AssertionError("Starter template should expose charge-basis fields.")
    for field_id in required_ids:
        field = fields[field_id]
        if not field.required:
            raise AssertionError(f"{field_id} should be marked required.")
        if not field.tooltip or not field.group:
            raise AssertionError(f"{field_id} should include tooltip/group metadata.")
    if fields["sodium_hydroxide_mass_g"].required:
        raise AssertionError("NaOH charge should be optional before hydrolysis starts.")
    if not fields["sodium_hydroxide_mass_g"].tooltip:
        raise AssertionError("Optional NaOH field should retain operator guidance.")
    target_species = {
        field.target_species_id for field in fields.values() if field.target_species_id
    }
    if "sodium_methoxide" not in target_species or "methanol" not in target_species:
        raise AssertionError("Equation species should target charge-basis inputs.")
    equation_text = "\n".join(_reaction_template_equation_lines(template))
    for formula in ("CH₃ONa", "CO", "NaOH", "CHNaO₂"):
        if formula not in equation_text:
            raise AssertionError(f"Equation should show clickable species {formula}.")


def _regression_test_reaction_dashboard_profile_state_roundtrip() -> None:
    """Validate Reaction Dashboard profile-state save and restore behavior.

    Purpose:
        Exercise dashboard-state serialization, deserialization, and profile apply
        order without constructing the full Tk application.
    Why:
        Reaction Dashboard UX inputs must survive profile JSON save/load and
        startup autosave restores instead of reverting to template defaults.
    Inputs:
        None; uses built-in template metadata and lightweight variable stubs.
    Outputs:
        None.
    Side Effects:
        Temporarily mutates profile-related keys in the global settings mapping.
    Exceptions:
        Raises AssertionError when saved dashboard values are missing, invalid
        fields are applied, or template reload order overwrites profile values.
    """

    class _Var:
        """Minimal Tk variable stand-in for dashboard profile tests."""

        def __init__(self, value: Any = "") -> None:
            """Initialize the variable with a deterministic value.

            Purpose:
                Provide the `get`/`set` surface used by profile helper methods.
            Why:
                The regression should validate persistence logic without creating
                Tk widgets.
            Args:
                value: Initial value returned by `get()`.
            Returns:
                None.
            Side Effects:
                Stores the provided value on the instance.
            Exceptions:
                None.
            """
            self.value = value

        def get(self) -> Any:
            """Return the stored variable value.

            Purpose:
                Emulate Tk variable reads used by dashboard profile helpers.
            Why:
                Production methods treat Tk variables as small `get()` providers.
            Args:
                None.
            Returns:
                Stored value.
            Side Effects:
                None.
            Exceptions:
                None.
            """
            return self.value

        def set(self, value: Any) -> None:
            """Replace the stored variable value.

            Purpose:
                Emulate Tk variable writes used during profile restore.
            Why:
                The apply path must be tested without real Tk state.
            Args:
                value: Replacement value to store.
            Returns:
                None.
            Side Effects:
                Mutates the stored value.
            Exceptions:
                None.
            """
            self.value = value

    class _Harness:
        """Small harness exposing profile and dashboard methods under test."""

        _collect_reaction_dashboard_state_payload = (
            UnifiedApp._collect_reaction_dashboard_state_payload
        )
        _serialize_workspace_state = UnifiedApp._serialize_workspace_state
        _deserialize_workspace_state = UnifiedApp._deserialize_workspace_state
        _apply_profile_reaction_dashboard_state = (
            UnifiedApp._apply_profile_reaction_dashboard_state
        )

        def __init__(self, template: ReactionTemplate) -> None:
            """Initialize profile and dashboard state for persistence tests.

            Purpose:
                Provide the minimal state required by profile serialization and
                restore helpers.
            Why:
                Focused regression coverage should avoid the full application
                constructor while preserving real helper behavior.
            Args:
                template: Reaction template used for simulated UI rebuilds.
            Returns:
                None.
            Side Effects:
                Stores fake profile, source, template, and dashboard variable state.
            Exceptions:
                None.
            """
            self.template = template
            self.multi_sheet_enabled = False
            self.selected_sheet = _Var("Sheet1")
            self.selected_sheets: List[str] = []
            self.columns: Dict[str, str] = {}
            self.file_path = "C:/tmp/reaction-dashboard-profile.xlsx"
            self.load_calls: List[str] = []
            self.refresh_calls = 0
            self._reaction_template_var = _Var(template.template_id)
            self._reaction_source_mode_var = _Var("manual")
            self._reaction_source_display_var = _Var("Manual gas mass / moles")
            self._reaction_source_key_to_label = {
                key: label for key, label in REACTION_DASHBOARD_SOURCE_MODES
            }
            self._reaction_input_vars: Dict[str, _Var] = {
                "sodium_metal_mass_g": _Var("2.3"),
                "methanol_mass_g": _Var("100.0"),
                "liquid_volume_l": _Var("1.25"),
            }
            self._reaction_source_vars: Dict[str, _Var] = {
                "manual_gas_moles": _Var("0.40"),
                "manual_gas_mass_g": _Var("11.2"),
                "reactor_temperature_c": _Var("66"),
            }
            self._reaction_ph_enabled_var = _Var(True)

        def _get_per_sheet_column_map(self) -> Dict[str, Any]:
            """Return empty per-sheet mapping for profile serialization.

            Purpose:
                Satisfy `_serialize_workspace_state` without dataset UI state.
            Why:
                The regression targets dashboard persistence only.
            Args:
                None.
            Returns:
                Empty mapping.
            Side Effects:
                None.
            Exceptions:
                None.
            """
            return {}

        def _collect_profile_plot_settings(self) -> Dict[str, Any]:
            """Return empty plot settings for profile serialization.

            Purpose:
                Provide the plot-settings slot required by the profile payload.
            Why:
                Dashboard profile assertions do not depend on plot settings.
            Args:
                None.
            Returns:
                Empty mapping.
            Side Effects:
                None.
            Exceptions:
                None.
            """
            return {}

        def _collect_final_report_state_from_ui(self) -> Dict[str, Any]:
            """Return empty final-report state for profile serialization.

            Purpose:
                Provide the final-report slot required by the profile payload.
            Why:
                The regression is isolated to Reaction Dashboard state.
            Args:
                None.
            Returns:
                Empty mapping.
            Side Effects:
                None.
            Exceptions:
                None.
            """
            return {}

        def _collect_reaction_basis_payload(self) -> Dict[str, Any]:
            """Return empty reaction-basis state for profile serialization.

            Purpose:
                Satisfy the existing profile payload contract.
            Why:
                This regression must not change Compare/Ledger reaction-basis
                behavior while testing dashboard-specific persistence.
            Args:
                None.
            Returns:
                Empty mapping.
            Side Effects:
                None.
            Exceptions:
                None.
            """
            return {}

        def _collect_profile_cycle_markers(self) -> Optional[Dict[str, Any]]:
            """Return no cycle markers for profile serialization.

            Purpose:
                Satisfy the profile serializer's cycle-marker slot.
            Why:
                Dashboard persistence is independent from cycle marker state.
            Args:
                None.
            Returns:
                None.
            Side Effects:
                None.
            Exceptions:
                None.
            """
            return None

        def _collect_profile_identifiers(self) -> Dict[str, str]:
            """Return empty profile identifiers for profile serialization.

            Purpose:
                Satisfy the profile serializer's metadata slot.
            Why:
                Identifier persistence is unrelated to dashboard field retention.
            Args:
                None.
            Returns:
                Empty mapping.
            Side Effects:
                None.
            Exceptions:
                None.
            """
            return {}

        def _reaction_active_template(self) -> ReactionTemplate:
            """Return the harness reaction template.

            Purpose:
                Provide active-template resolution for dashboard state collection.
            Why:
                The production collector falls back to active template metadata.
            Args:
                None.
            Returns:
                Harness template.
            Side Effects:
                None.
            Exceptions:
                None.
            """
            return self.template

        def _refresh_reaction_template_selector(self) -> None:
            """Record one template-selector refresh call.

            Purpose:
                Track that profile restore refreshed selector state.
            Why:
                Restore should keep visible selector choices aligned to the loaded
                template id.
            Args:
                None.
            Returns:
                None.
            Side Effects:
                Increments `refresh_calls`.
            Exceptions:
                None.
            """
            self.refresh_calls += 1

        def _load_reaction_template_into_ui(self, template: ReactionTemplate) -> None:
            """Simulate rebuilding dashboard inputs from a template.

            Purpose:
                Recreate the production behavior where template loading replaces
                input variables with default-valued fields.
            Why:
                Profile restore must apply saved values after this rebuild step.
            Args:
                template: Template whose input field defaults should be loaded.
            Returns:
                None.
            Side Effects:
                Resets `_reaction_input_vars`, pH state, and records load order.
            Exceptions:
                None.
            """
            self.load_calls.append(template.template_id)
            self._reaction_input_vars = {
                field.field_id: _Var(str(field.default or ""))
                for field in template.input_fields
            }
            self._reaction_ph_enabled_var.set(
                bool(template.equilibrium.enabled_by_default)
            )

    template = _builtin_reaction_templates()["sodium_methoxide_co_to_sodium_formate"]
    prior_selected_template = settings.get(REACTION_DASHBOARD_SELECTED_TEMPLATE_KEY)
    prior_source_mode = settings.get("reaction_dashboard_source_mode")
    try:
        harness = _Harness(template)
        serialized = UnifiedApp._serialize_workspace_state(
            harness, include_dataset_path=False
        )
        saved_state = serialized.get("reaction_dashboard_state")
        if not isinstance(saved_state, Mapping):
            raise AssertionError("Profile payload should include dashboard state.")
        if saved_state.get("template_id") != template.template_id:
            raise AssertionError("Dashboard profile state should save template id.")
        if saved_state.get("source_mode") != "manual":
            raise AssertionError("Dashboard profile state should save source mode.")
        if saved_state.get("ph_enabled") is not True:
            raise AssertionError("Dashboard profile state should save pH toggle.")
        if saved_state.get("template_inputs", {}).get("sodium_metal_mass_g") != "2.3":
            raise AssertionError("Dashboard profile state should save template inputs.")
        if saved_state.get("source_inputs", {}).get("manual_gas_moles") != "0.40":
            raise AssertionError("Dashboard profile state should save source inputs.")

        state = UnifiedApp._deserialize_workspace_state(
            harness,
            {
                "reaction_dashboard_state": {
                    "template_id": template.template_id,
                    "source_mode": "manual",
                    "ph_enabled": "false",
                    "template_inputs": {
                        "sodium_metal_mass_g": "9.1",
                        "unknown_future_field": "ignored",
                    },
                    "source_inputs": {
                        "manual_gas_moles": "0.25",
                        "unknown_source_field": "ignored",
                    },
                }
            },
        )
        restored_state = state.get("reaction_dashboard_state")
        restore_harness = _Harness(template)
        restore_harness._reaction_input_vars["sodium_metal_mass_g"].set("stale")
        UnifiedApp._apply_profile_reaction_dashboard_state(
            restore_harness, restored_state
        )
        if restore_harness.load_calls != [template.template_id]:
            raise AssertionError(
                "Profile restore should rebuild the selected template once."
            )
        if restore_harness._reaction_input_vars["sodium_metal_mass_g"].get() != "9.1":
            raise AssertionError("Saved template input should survive template reload.")
        if "unknown_future_field" in restore_harness._reaction_input_vars:
            raise AssertionError("Unknown template inputs should not be applied.")
        if restore_harness._reaction_source_vars["manual_gas_moles"].get() != "0.25":
            raise AssertionError("Saved source input should be restored.")
        if "unknown_source_field" in restore_harness._reaction_source_vars:
            raise AssertionError("Unknown source inputs should not be applied.")
        if restore_harness._reaction_source_mode_var.get() != "manual":
            raise AssertionError("Source mode should restore to the saved value.")
        if restore_harness._reaction_ph_enabled_var.get() is not False:
            raise AssertionError("Saved pH toggle should override template default.")

        legacy_state = UnifiedApp._deserialize_workspace_state(harness, {})
        if legacy_state.get("reaction_dashboard_state") != {}:
            raise AssertionError("Legacy profiles should load without dashboard state.")
        legacy_harness = _Harness(template)
        UnifiedApp._apply_profile_reaction_dashboard_state(legacy_harness, {})
        if legacy_harness.load_calls:
            raise AssertionError("Missing dashboard state should not rebuild the UI.")
    finally:
        if prior_selected_template is None:
            settings.pop(REACTION_DASHBOARD_SELECTED_TEMPLATE_KEY, None)
        else:
            settings[REACTION_DASHBOARD_SELECTED_TEMPLATE_KEY] = prior_selected_template
        if prior_source_mode is None:
            settings.pop("reaction_dashboard_source_mode", None)
        else:
            settings["reaction_dashboard_source_mode"] = prior_source_mode


def _regression_test_auto_title_startup_warning_suppression() -> None:
    """Validate startup Auto Title data warnings do not open modal warnings.

    Purpose:
        Exercise the production title resolver with an unresolved Date & Time
        mapping warning during startup and after startup.
    Why:
        Startup plot refreshes should preserve the manual title silently, while
        post-startup user-triggered refresh/export paths should still surface
        the existing Auto Title warning.
    Inputs:
        None; uses a lightweight harness with deterministic Auto Title output.
    Outputs:
        None.
    Side Effects:
        Records warning emissions on the harness object only.
    Exceptions:
        Raises AssertionError when startup suppression or post-startup warning
        behavior regresses.
    """

    class _Var:
        """Minimal Tk variable stand-in for Auto Title resolver tests."""

        def __init__(self, value: Any) -> None:
            """Store a deterministic variable value for the harness.

            Purpose:
                Emulate the small `get()` surface used by the resolver.
            Why:
                The regression should not construct Tk widgets.
            Args:
                value: Value returned by `get()`.
            Returns:
                None.
            Side Effects:
                Stores value on the instance.
            Exceptions:
                None.
            """
            self.value = value

        def get(self) -> Any:
            """Return the stored variable value.

            Purpose:
                Provide the read API expected by `_resolve_effective_title`.
            Why:
                Production code reads Tk variables through `get()`.
            Args:
                None.
            Returns:
                Stored value.
            Side Effects:
                None.
            Exceptions:
                None.
            """
            return self.value

    class _Harness:
        """Harness exposing only the Auto Title resolver surface."""

        _resolve_effective_title = UnifiedApp._resolve_effective_title
        _auto_title_warning_suppressed_during_startup = (
            UnifiedApp._auto_title_warning_suppressed_during_startup
        )

        def __init__(self) -> None:
            """Initialize deterministic startup and warning state.

            Purpose:
                Supply resolver state without building the full application.
            Why:
                The regression targets title warning behavior only.
            Args:
                None.
            Returns:
                None.
            Side Effects:
                Stores warning capture state.
            Exceptions:
                None.
            """
            self.auto_title_enabled_var = _Var(True)
            self._startup_main_window_revealed = False
            self.startup_active = True
            self.warnings: List[Tuple[str, str]] = []

        def _compute_auto_title_text(
            self,
        ) -> Tuple[Optional[str], Optional[str], bool, Optional[str]]:
            """Return a valid formatted title plus missing Date & Time warning.

            Purpose:
                Isolate resolver behavior from token formatting internals.
            Why:
                The startup bug is caused by how the resolver handles a warning
                on an otherwise format-ready Auto Title string.
            Args:
                None.
            Returns:
                Tuple matching `_compute_auto_title_text`.
            Side Effects:
                None.
            Exceptions:
                None.
            """
            return (
                "Auto Title",
                "Auto Title needs a valid Date & Time mapping to compute date range.",
                False,
                None,
            )

        def _is_startup_loading_active(self) -> bool:
            """Return the harness startup-active flag.

            Purpose:
                Let the production suppressor observe startup state.
            Why:
                The resolver uses the same readiness gate as application startup.
            Args:
                None.
            Returns:
                bool: Current startup-active flag.
            Side Effects:
                None.
            Exceptions:
                None.
            """
            return bool(self.startup_active)

        def _emit_auto_title_warning(self, key: str, message: str) -> None:
            """Capture resolver warning emissions.

            Purpose:
                Verify whether a warning would be shown without opening a UI.
            Why:
                Regression tests must be deterministic and non-modal.
            Args:
                key: Warning de-duplication key.
                message: Warning text.
            Returns:
                None.
            Side Effects:
                Appends the warning to `warnings`.
            Exceptions:
                None.
            """
            self.warnings.append((key, message))

    harness = _Harness()
    if harness._resolve_effective_title("Manual") != "Manual":
        raise AssertionError("Startup warning should preserve manual title.")
    if harness.warnings:
        raise AssertionError("Startup Auto Title warning should be suppressed.")
    harness.startup_active = False
    harness._startup_main_window_revealed = True
    if harness._resolve_effective_title("Manual") != "Auto Title":
        raise AssertionError("Post-startup resolver should use computed Auto Title.")
    if not harness.warnings:
        raise AssertionError("Post-startup Auto Title warning should still emit.")


def _regression_test_reaction_dashboard_formula_helper_reference() -> None:
    """Validate the dashboard equation renderer references the live helper name.

    Purpose:
        Guard against the stale `_reaction_formula_display` NameError.
    Why:
        The clickable equation widget should use the shared formula display
        helper that exists in this module.
    Inputs:
        None; inspects the production method bytecode names.
    Outputs:
        None.
    Side Effects:
        None.
    Exceptions:
        Raises AssertionError when the stale helper name is present or the
        replacement helper name is missing.
    """
    names = set(UnifiedApp._refresh_reaction_equation_widget.__code__.co_names)
    if "_reaction_formula_display" in names:
        raise AssertionError("Equation widget still references stale helper name.")
    if "_reaction_formula_display_text" not in names:
        raise AssertionError("Equation widget should use formula display text helper.")


def _regression_test_reaction_dashboard_blank_naoh_defers_hydrolysis() -> None:
    """Validate blank NaOH runs carbonylation and defers hydrolysis output.

    Purpose:
        Exercise species-row charge basis and step filtering with optional NaOH.
    Why:
        Users need first-step methyl formate analysis before they know the NaOH
        charge for the second hydrolysis step.
    Inputs:
        None; uses the built-in sodium methoxide/CO template and Python core.
    Outputs:
        None.
    Side Effects:
        None.
    Exceptions:
        Raises AssertionError when hydrolysis is not deferred or carbonylation
        output is lost.
    """

    class _Var:
        """Minimal StringVar stand-in for Reaction Dashboard input tests."""

        def __init__(self, value: str) -> None:
            """Store one input value.

            Purpose:
                Emulate the `get()` method used by dashboard parsers.
            Why:
                Focused regressions should not build Tk controls.
            Args:
                value: Input text value.
            Returns:
                None.
            Side Effects:
                Stores the value.
            Exceptions:
                None.
            """
            self.value = value

        def get(self) -> str:
            """Return stored input text.

            Purpose:
                Provide the Tk variable read API for dashboard helpers.
            Why:
                Production parsing reads all inputs through `get()`.
            Args:
                None.
            Returns:
                Stored string value.
            Side Effects:
                None.
            Exceptions:
                None.
            """
            return self.value

    class _Harness:
        """Harness exposing dashboard input, species, and step-filter helpers."""

        _reaction_dashboard_input_text = UnifiedApp._reaction_dashboard_input_text
        _reaction_dashboard_input_float = UnifiedApp._reaction_dashboard_input_float
        _reaction_dashboard_species_rows_with_inputs = (
            UnifiedApp._reaction_dashboard_species_rows_with_inputs
        )
        _reaction_dashboard_step_rows_for_available_inputs = (
            UnifiedApp._reaction_dashboard_step_rows_for_available_inputs
        )

        def __init__(self, template: ReactionTemplate) -> None:
            """Initialize species rows and blank-NaOH input values.

            Purpose:
                Provide enough state for production dashboard helpers.
            Why:
                The regression should validate helper contracts without Tk.
            Args:
                template: Built-in reaction template under test.
            Returns:
                None.
            Side Effects:
                Stores copied species rows and fake input variables.
            Exceptions:
                None.
            """
            self.rows = [asdict(species) for species in template.species]
            self._reaction_source_vars: Dict[str, Any] = {}
            self._reaction_input_vars = {
                "sodium_metal_mass_g": _Var("2.30"),
                "methanol_mass_g": _Var("100.0"),
                "methanol_water_ppm_by_mass": _Var("0"),
                "sodium_hydroxide_mass_g": _Var(""),
            }

        def _reaction_dashboard_collect_species_rows(self) -> List[Dict[str, Any]]:
            """Return copied species rows for dashboard helper execution.

            Purpose:
                Stand in for Treeview-backed species collection.
            Why:
                The helper under test only needs species row mappings.
            Args:
                None.
            Returns:
                List of copied species dictionaries.
            Side Effects:
                None.
            Exceptions:
                None.
            """
            return [dict(row) for row in self.rows]

    template = _builtin_reaction_templates()["sodium_methoxide_co_to_sodium_formate"]
    fields = {field.field_id: field for field in template.input_fields}
    if fields["sodium_hydroxide_mass_g"].required:
        raise AssertionError("NaOH charge should be optional.")
    harness = _Harness(template)
    species_rows, charge_basis = harness._reaction_dashboard_species_rows_with_inputs(
        template
    )
    raw_steps = [asdict(step) for step in template.steps]
    filtered_steps, deferred_steps = (
        harness._reaction_dashboard_step_rows_for_available_inputs(template, raw_steps)
    )
    if [step.get("step_id") for step in filtered_steps] != ["carbonylation"]:
        raise AssertionError("Blank NaOH should filter the hydrolysis step only.")
    if not deferred_steps or deferred_steps[0].get("step_id") != "hydrolysis":
        raise AssertionError("Hydrolysis should be reported as deferred.")
    core = _python_reaction_dashboard_core(
        species_rows,
        filtered_steps,
        gas_uptake_mol=0.05,
        gas_species_id=template.gas_species_id,
        yield_species_id=template.yield_basis.product_species_id,
        target_reactant_species_id=template.yield_basis.target_reactant_species_id,
        actual_yield_mass_g=None,
    )
    adapter_core = _run_reaction_dashboard_core(
        species_rows,
        filtered_steps,
        gas_uptake_mol=0.05,
        gas_species_id=template.gas_species_id,
        yield_species_id=template.yield_basis.product_species_id,
        target_reactant_species_id=template.yield_basis.target_reactant_species_id,
        actual_yield_mass_g=None,
    )
    final_inventory = core.get("final_inventory_mol")
    adapter_inventory = adapter_core.get("final_inventory_mol")
    if not isinstance(final_inventory, Mapping):
        raise AssertionError("Dashboard core should return final inventory.")
    if not isinstance(adapter_inventory, Mapping):
        raise AssertionError("Dashboard adapter should return final inventory.")
    if float(final_inventory.get("methyl_formate") or 0.0) <= 0.0:
        raise AssertionError("Carbonylation should preserve methyl formate output.")
    if float(final_inventory.get("sodium_formate") or 0.0) != 0.0:
        raise AssertionError("Deferred hydrolysis should not create sodium formate.")
    if len(list(core.get("step_results") or [])) != 1:
        raise AssertionError("Core should receive only filtered carbonylation step.")
    if len(list(adapter_core.get("step_results") or [])) != 1:
        raise AssertionError("Adapter should receive only filtered carbonylation step.")
    for species_id in ("methyl_formate", "sodium_formate"):
        python_value = float(final_inventory.get(species_id) or 0.0)
        adapter_value = float(adapter_inventory.get(species_id) or 0.0)
        if abs(python_value - adapter_value) > 1e-12:
            raise AssertionError(
                f"Filtered-step adapter mismatch for {species_id}."
            )
    if not isinstance(charge_basis, Mapping):
        raise AssertionError("Charge-basis diagnostics should still be returned.")


def _regression_test_reaction_dashboard_mousewheel_binding_dispatch() -> None:
    """Validate Reaction Dashboard wheel binding dispatches to canvas scrolling.

    Purpose:
        Exercise the recursive binding helper and shared wheel dispatcher without
        constructing Tk widgets.
    Why:
        Dashboard rebuilds should attach one wheel handler per widget and route
        wheel movement through the canvas handoff path.
    Inputs:
        None; uses lightweight fake widgets and a fake canvas.
    Outputs:
        None.
    Side Effects:
        Records bind calls and canvas scroll requests on fake objects.
    Exceptions:
        Raises AssertionError when binding or dispatch behavior regresses.
    """

    class _FakeWidget:
        """Small widget stand-in that records event bindings."""

        def __init__(self, name: str, children: Optional[List[Any]] = None) -> None:
            """Initialize fake widget identity and child list.

            Purpose:
                Provide the widget methods used by the recursive binder.
            Why:
                The regression should not require a Tk root.
            Args:
                name: Stable widget string identity.
                children: Optional child widgets returned by `winfo_children()`.
            Returns:
                None.
            Side Effects:
                Stores binding and child state.
            Exceptions:
                None.
            """
            self.name = name
            self.children = list(children or [])
            self.bindings: Dict[str, Any] = {}

        def __str__(self) -> str:
            """Return stable widget identity text.

            Purpose:
                Match the production binder's widget-id tracking.
            Why:
                Duplicate suppression uses string widget identifiers.
            Args:
                None.
            Returns:
                Widget name.
            Side Effects:
                None.
            Exceptions:
                None.
            """
            return self.name

        def bind(
            self, event_name: str, callback: Any, add: Optional[str] = None
        ) -> None:
            """Record one event callback binding.

            Purpose:
                Capture the callback installed by the production binder.
            Why:
                The test invokes the callback directly to validate dispatch.
            Args:
                event_name: Tk event name.
                callback: Bound callback.
                add: Tk additive binding flag.
            Returns:
                None.
            Side Effects:
                Stores callback by event name.
            Exceptions:
                None.
            """
            _ = add
            self.bindings[event_name] = callback

        def winfo_children(self) -> List[Any]:
            """Return child widgets for recursive binding.

            Purpose:
                Provide the widget traversal API used by the binder.
            Why:
                Production recursively binds all dashboard descendants.
            Args:
                None.
            Returns:
                List of child widgets.
            Side Effects:
                None.
            Exceptions:
                None.
            """
            return list(self.children)

        def winfo_class(self) -> str:
            """Return a non-scroll-owner widget class name.

            Purpose:
                Keep wheel dispatch focused on canvas handoff.
            Why:
                The fake widget is not a Text/Listbox/Treeview owner.
            Args:
                None.
            Returns:
                Widget class name.
            Side Effects:
                None.
            Exceptions:
                None.
            """
            return "Frame"

    class _FakeCanvas:
        """Small canvas stand-in that records y-scroll requests."""

        def __init__(self) -> None:
            """Initialize empty scroll-call capture.

            Purpose:
                Track whether dispatcher handed the wheel event to the canvas.
            Why:
                The test needs a deterministic assertion without Tk.
            Args:
                None.
            Returns:
                None.
            Side Effects:
                Stores an empty scroll-call list.
            Exceptions:
                None.
            """
            self.scroll_calls: List[Tuple[int, str]] = []

        def yview_scroll(self, step: int, unit: str) -> None:
            """Record one canvas scroll request.

            Purpose:
                Emulate the Tk Canvas scrolling API.
            Why:
                The shared dispatcher calls this method on handoff.
            Args:
                step: Signed scroll units.
                unit: Tk scroll unit string.
            Returns:
                None.
            Side Effects:
                Appends the scroll request to `scroll_calls`.
            Exceptions:
                None.
            """
            self.scroll_calls.append((step, unit))

    class _Event:
        """Simple wheel event payload."""

        def __init__(self, widget: Any, delta: int) -> None:
            """Store event widget and wheel delta.

            Purpose:
                Provide attributes read by the wheel dispatcher.
            Why:
                Tk event objects are not needed for this focused regression.
            Args:
                widget: Event target widget.
                delta: MouseWheel delta.
            Returns:
                None.
            Side Effects:
                Stores event fields.
            Exceptions:
                None.
            """
            self.widget = widget
            self.delta = delta

    class _Harness:
        """Harness exposing dashboard wheel helper methods."""

        _bind_reaction_dashboard_mousewheel_recursive = (
            UnifiedApp._bind_reaction_dashboard_mousewheel_recursive
        )
        _dispatch_canvas_mousewheel_with_handoff = (
            UnifiedApp._dispatch_canvas_mousewheel_with_handoff
        )
        _normalize_mousewheel_step = UnifiedApp._normalize_mousewheel_step
        _widget_owns_vertical_scroll = UnifiedApp._widget_owns_vertical_scroll
        _scroll_owned_widget_if_possible = UnifiedApp._scroll_owned_widget_if_possible

        def __init__(self) -> None:
            """Initialize fake canvas and binding state.

            Purpose:
                Supply the instance attributes used by the binder and dispatcher.
            Why:
                The production methods are instance methods.
            Args:
                None.
            Returns:
                None.
            Side Effects:
                Stores fake canvas and wheel state.
            Exceptions:
                None.
            """
            self._reaction_dashboard_canvas = _FakeCanvas()
            self._reaction_dashboard_mousewheel_bound: Set[str] = set()
            self._reaction_dashboard_scroll_wheel_remainder = 0.0

    child = _FakeWidget("child")
    root = _FakeWidget("root", [child])
    harness = _Harness()
    harness._bind_reaction_dashboard_mousewheel_recursive(root)
    harness._bind_reaction_dashboard_mousewheel_recursive(root)
    if "<MouseWheel>" not in root.bindings or "<MouseWheel>" not in child.bindings:
        raise AssertionError("Dashboard widgets should receive wheel bindings.")
    if len(harness._reaction_dashboard_mousewheel_bound) != 2:
        raise AssertionError("Dashboard wheel binding should avoid duplicates.")
    consumed = root.bindings["<MouseWheel>"](_Event(root, -120))
    if consumed != "break":
        raise AssertionError("Dashboard wheel handler should consume canvas scroll.")
    if harness._reaction_dashboard_canvas.scroll_calls != [(1, "units")]:
        raise AssertionError("Wheel dispatch should scroll the dashboard canvas.")


def _regression_test_reaction_dashboard_trace_scoping() -> None:
    """Validate Reaction Dashboard trace discovery and settings scoping.

    Purpose:
        Ensure Data Trace Settings discovers Reaction Dashboard traces and stores
        edits under the reaction-specific preference bucket.
    Why:
        Reaction plots use the combined-style toolbar but must not overwrite
        combined/core scatter-series settings.
    Inputs:
        None; uses a local harness with a synthetic last-result payload.
    Outputs:
        None.
    Side Effects:
        Temporarily mutates `settings["reaction_dashboard_plot_prefs"]` and
        restores the previous value.
    Exceptions:
        Raises AssertionError when trace keys, labels, or persistence scope regress.
    """

    class _Harness:
        """Minimal harness exposing Reaction Dashboard trace methods."""

        _reaction_dashboard_trace_catalog = UnifiedApp._reaction_dashboard_trace_catalog
        _data_trace_series_label = UnifiedApp._data_trace_series_label
        _trace_settings_store_for_plot_id = UnifiedApp._trace_settings_store_for_plot_id
        _persist_trace_settings_store_for_plot_id = (
            UnifiedApp._persist_trace_settings_store_for_plot_id
        )
        _collect_data_trace_series_keys = UnifiedApp._collect_data_trace_series_keys
        _sanitize_series_settings_dict = UnifiedApp._sanitize_series_settings_dict
        _sanitize_single_series_config = UnifiedApp._sanitize_single_series_config

        def __init__(self) -> None:
            self._reaction_dashboard_last_result = {
                "core": {"completion_pct": 100.0},
                "cycle_series": [{"ph": 8.4, "completion_pct": 100.0}],
            }

        def _collect_trace_series_keys_from_figure(
            self, _fig: Optional[Figure], *, plot_id: Optional[str] = None
        ) -> List[str]:
            """Return no rendered keys so catalog fallback is exercised."""
            _ = plot_id
            return []

        def _resolve_plot_figure_for_plot_id(self, _plot_id: str) -> Optional[Figure]:
            """Return no live figure so catalog-based discovery is tested."""
            return None

    previous_prefs = settings.get("reaction_dashboard_plot_prefs")
    previous_scatter = settings.get("scatter_series")
    save_settings_func = globals().get("_save_settings_to_disk")
    try:
        globals()["_save_settings_to_disk"] = lambda: None
        settings["reaction_dashboard_plot_prefs"] = {}
        settings["scatter_series"] = {"y1": {"enabled": True}}
        harness = _Harness()
        keys = UnifiedApp._collect_data_trace_series_keys(
            harness, REACTION_DASHBOARD_PLOT_ID
        )
        if "reaction_uptake" not in keys or "reaction_ph" not in keys:
            raise AssertionError("Reaction Dashboard trace keys should be scoped.")
        label = UnifiedApp._data_trace_series_label(
            harness,
            "reaction_completion",
            plot_id=REACTION_DASHBOARD_PLOT_ID,
        )
        if label != "Reaction completion (%)":
            raise AssertionError("Reaction Dashboard trace label should be friendly.")
        UnifiedApp._persist_trace_settings_store_for_plot_id(
            harness,
            REACTION_DASHBOARD_PLOT_ID,
            {"reaction_uptake": {"enabled": False}},
        )
        stored = settings.get("reaction_dashboard_plot_prefs") or {}
        if not isinstance(stored, Mapping):
            raise AssertionError("Reaction trace prefs should be a mapping.")
        trace_settings = stored.get("trace_series") or {}
        if not isinstance(trace_settings, Mapping):
            raise AssertionError("Reaction trace settings should be scoped.")
        if trace_settings.get("reaction_uptake", {}).get("enabled") is not False:
            raise AssertionError("Reaction trace setting should persist.")
        if settings.get("scatter_series") != {"y1": {"enabled": True}}:
            raise AssertionError("Combined/core scatter settings should be untouched.")
    finally:
        if previous_prefs is None:
            settings.pop("reaction_dashboard_plot_prefs", None)
        else:
            settings["reaction_dashboard_plot_prefs"] = previous_prefs
        if previous_scatter is None:
            settings.pop("scatter_series", None)
        else:
            settings["scatter_series"] = previous_scatter
        if callable(save_settings_func):
            globals()["_save_settings_to_disk"] = save_settings_func


def _regression_test_reaction_dashboard_rust_python_parity_when_available() -> None:
    """Validate Rust/Python Reaction Dashboard parity when Rust is importable.

    Purpose:
        Compare the template-neutral Rust kernel against the Python fallback for
        the same sodium formate linked reaction payload.
    Why:
        Repository policy requires Rust-backed compute to preserve a functional
        Python fallback with matching result schema and numerical behavior.
    Inputs:
        None; uses fixed sodium methoxide / CO template inputs.
    Outputs:
        None.
    Side Effects:
        None.
    Exceptions:
        Raises AssertionError when an available Rust kernel diverges from Python.
        Missing Rust support skips the parity comparison because fallback remains
        authoritative.
    """
    template = _builtin_reaction_templates()["sodium_methoxide_co_to_sodium_formate"]
    species_rows = []
    for species in template.species:
        initial_moles = 0.0
        if species.species_id == "sodium_methoxide":
            initial_moles = 1.0
        elif species.species_id == "sodium_hydroxide":
            initial_moles = 0.8
        species_rows.append(asdict(replace(species, initial_moles=initial_moles)))
    step_rows = [asdict(step) for step in template.steps]
    python_result = _python_reaction_dashboard_core(
        species_rows,
        step_rows,
        gas_uptake_mol=0.75,
        gas_species_id=template.gas_species_id,
        yield_species_id=template.yield_basis.product_species_id,
        target_reactant_species_id=template.yield_basis.target_reactant_species_id,
        actual_yield_mass_g=45.904725,
    )
    rust_result = _rust_reaction_dashboard_core(
        species_rows,
        step_rows,
        gas_uptake_mol=0.75,
        gas_species_id=template.gas_species_id,
        yield_species_id=template.yield_basis.product_species_id,
        target_reactant_species_id=template.yield_basis.target_reactant_species_id,
        actual_yield_mass_g=45.904725,
    )
    if rust_result is None:
        return
    numeric_keys = (
        "gas_uptake_mol",
        "gas_uptake_g",
        "yield_species_moles",
        "theoretical_yield_g",
        "actual_yield_pct",
        "completion_pct",
    )
    for key in numeric_keys:
        py_value = python_result.get(key)
        rust_value = rust_result.get(key)
        if py_value is None and rust_value is None:
            continue
        if py_value is None or rust_value is None:
            raise AssertionError(f"Rust/Python parity mismatch for {key}.")
        if abs(float(py_value) - float(rust_value)) > 1e-9:
            raise AssertionError(f"Rust/Python parity mismatch for {key}.")
    py_steps = list(python_result.get("step_results") or [])
    rust_steps = list(rust_result.get("step_results") or [])
    if len(py_steps) != len(rust_steps):
        raise AssertionError("Rust/Python step result count should match.")
    for py_step, rust_step in zip(py_steps, rust_steps, strict=False):
        if (
            abs(
                float(py_step.get("extent_mol") or 0.0)
                - float(rust_step.get("extent_mol") or 0.0)
            )
            > 1e-9
        ):
            raise AssertionError("Rust/Python step extent should match.")


def _regression_test_reaction_solution_charge_rust_python_parity() -> None:
    """Validate Rust/Python sodium/methanol charge-basis parity when available.

    Purpose:
        Compare the Rust charge-basis kernel with the Python fallback for the
        same sodium, methanol, water ppm, and explicit NaOH inputs.
    Why:
        Repository policy requires compute edits to keep Rust and Python paths
        consistent where practical while preserving fallback behavior.
    Inputs:
        None; uses a fixed starter-template charge-basis payload.
    Outputs:
        None.
    Side Effects:
        None.
    Exceptions:
        Raises AssertionError when an available Rust kernel diverges from Python.
        Missing Rust support skips comparison because Python fallback remains
        authoritative.
    """
    kwargs = {
        "sodium_metal_mass_g": 2.2989769,
        "methanol_mass_g": 100.0,
        "water_ppm_by_mass": 1800.0,
        "explicit_naoh_mass_g": 4.0,
    }
    python_result = _python_reaction_solution_charge_core(**kwargs)
    rust_result = _rust_reaction_solution_charge_core(**kwargs)
    if rust_result is None:
        return
    numeric_keys = (
        "water_mol",
        "sodium_mol",
        "methanol_initial_mol",
        "generated_naoh_mol",
        "explicit_naoh_mol",
        "total_naoh_mol",
        "sodium_methoxide_mol",
        "remaining_methanol_mol",
    )
    for key in numeric_keys:
        python_value = float(python_result.get(key) or 0.0)
        rust_value = float(rust_result.get(key) or 0.0)
        if abs(python_value - rust_value) > 1e-12:
            raise AssertionError(f"Rust/Python charge-basis mismatch for {key}.")


def _regression_test_loading_footer_timer_and_progress_contracts() -> None:
    """Validate splash footer timer and monotonic progress helper contracts.

    Purpose:
        Exercise the shared loading footer behavior without requiring a real Tk
        event loop.
    Why:
        Splash regressions are easy to reintroduce when status/detail text and
        progress timers are maintained by several UI controllers.
    Inputs:
        None.
    Outputs:
        None.
    Side Effects:
        Invokes startup splash helper methods on local widget stubs only.
    Exceptions:
        Raises AssertionError when elapsed text leaks into detail labels, progress
        regresses without reset, or heartbeat callbacks fail to schedule.
    """

    class _LabelStub:
        """Minimal label stub recording configured text values."""

        def __init__(self) -> None:
            """Initialize captured text state."""
            self.text = ""

        def configure(self, **kwargs: Any) -> None:
            """Capture text configuration calls from splash helpers."""
            if "text" in kwargs:
                self.text = str(kwargs["text"])

    class _OverlayStub:
        """Minimal overlay stub with Tk-like existence and idle hooks."""

        def __init__(self) -> None:
            """Initialize overlay callback capture state."""
            self.after_calls: List[Tuple[int, Any]] = []
            self.cancelled: List[Any] = []

        @staticmethod
        def winfo_exists() -> bool:
            """Return stable existing-widget state."""
            return True

        @staticmethod
        def update_idletasks() -> None:
            """Accept idle flush calls from splash helpers."""

        def after(self, delay_ms: int, callback: Any) -> str:
            """Record scheduled heartbeat callbacks without executing them."""
            self.after_calls.append((int(delay_ms), callback))
            return f"after-{len(self.after_calls)}"

        def after_cancel(self, after_id: Any) -> None:
            """Record heartbeat cancellation requests."""
            self.cancelled.append(after_id)

    class _Harness:
        """Startup splash helper harness exposing required methods/state."""

        def __init__(self) -> None:
            """Initialize startup splash helper state for assertions."""
            self._startup_loading_overlay = _OverlayStub()
            self._startup_loading_detail_label = _LabelStub()
            self._startup_loading_progress_label = _LabelStub()
            self._startup_loading_label = _LabelStub()
            self._startup_loading_progress_var = None
            self._startup_loading_bar = None
            self._startup_loading_progress_value = 25.0
            self._startup_loading_started_at = time.monotonic() - 1.0
            self._startup_loading_detail_base = "Stage: Testing."
            self._startup_loading_timer_after_id = None
            self.cancelled: List[Any] = []

        def after(self, delay_ms: int, callback: Any) -> str:
            """Record app-level heartbeat scheduling without running callback."""
            return self._startup_loading_overlay.after(delay_ms, callback)

        def after_cancel(self, after_id: Any) -> None:
            """Record app-level heartbeat cancellation."""
            self.cancelled.append(after_id)

        @staticmethod
        def _raise_startup_loading_overlay(
            *,
            force_place: bool = False,
            refresh: bool = False,
        ) -> bool:
            """Return visible overlay state for timer helper compatibility."""
            _ = force_place
            _ = refresh
            return True

        def _format_wall_clock_elapsed(self, elapsed_seconds: Any) -> str:
            """Delegate elapsed formatting to the app helper."""
            return UnifiedApp._format_wall_clock_elapsed(self, elapsed_seconds)

        def _format_loading_progress_footer(
            self,
            progress_value: Any,
            elapsed_text: str,
        ) -> str:
            """Delegate progress-footer formatting to the app helper."""
            return UnifiedApp._format_loading_progress_footer(
                self,
                progress_value,
                elapsed_text,
            )

        def _format_loading_stage_label(
            self,
            *,
            stage_key: Optional[str],
            message: Optional[str] = None,
        ) -> str:
            """Delegate stage-label formatting to the app helper."""
            return UnifiedApp._format_loading_stage_label(
                self,
                stage_key=stage_key,
                message=message,
            )

        def _resolve_loading_detail_base(
            self,
            *,
            current_detail_base: Any,
            stage_key: Optional[str],
            message: Optional[str],
            detail: Optional[str],
            clear_on_message: bool = True,
        ) -> str:
            """Delegate detail-base resolution to the app helper."""
            return UnifiedApp._resolve_loading_detail_base(
                self,
                current_detail_base=current_detail_base,
                stage_key=stage_key,
                message=message,
                detail=detail,
                clear_on_message=clear_on_message,
            )

        def _compose_loading_detail_with_elapsed(
            self,
            *,
            detail_base: Any,
            stage_key: Optional[str],
            message: Optional[str],
            elapsed_text: str,
        ) -> str:
            """Delegate detail composition to the app helper."""
            return UnifiedApp._compose_loading_detail_with_elapsed(
                self,
                detail_base=detail_base,
                stage_key=stage_key,
                message=message,
                elapsed_text=elapsed_text,
            )

        def _normalize_startup_loading_splash_text(
            self,
            text: Any,
            max_lines: int = 2,
        ) -> str:
            """Delegate startup splash text normalization to the app helper."""
            return UnifiedApp._normalize_startup_loading_splash_text(
                self,
                text,
                max_lines=max_lines,
            )

        def _start_startup_loading_timer(self) -> None:
            """Delegate startup timer start to the app helper."""
            UnifiedApp._start_startup_loading_timer(self)

        def _stop_startup_loading_timer(self) -> None:
            """Delegate startup timer stop to the app helper."""
            UnifiedApp._stop_startup_loading_timer(self)

    bootstrap_elapsed = _format_bootstrap_startup_elapsed(1.25)
    if bootstrap_elapsed != "1.25s":
        raise AssertionError(
            "Bootstrap elapsed formatter should keep sub-second precision."
        )
    if _format_bootstrap_startup_footer(33.4, bootstrap_elapsed) != "33% | 1.25s":
        raise AssertionError("Bootstrap footer should use percent plus elapsed text.")

    bootstrap_label = _LabelStub()
    bootstrap_overlay = _OverlayStub()
    bootstrap_handle = {
        "overlay": bootstrap_overlay,
        "progress_label": bootstrap_label,
        "progress_value": 42.0,
        "started_at": time.monotonic() - 1.0,
        "heartbeat_after_id": None,
    }
    _start_bootstrap_startup_splash_heartbeat(bootstrap_handle)
    if "42% | " not in bootstrap_label.text:
        raise AssertionError("Bootstrap heartbeat should refresh the footer label.")
    if bootstrap_handle.get("heartbeat_after_id") is None:
        raise AssertionError(
            "Bootstrap heartbeat should schedule a follow-up callback."
        )
    _stop_bootstrap_startup_splash_heartbeat(bootstrap_handle)
    if bootstrap_handle.get("heartbeat_after_id") is not None:
        raise AssertionError("Bootstrap heartbeat stop should clear callback id.")

    harness = _Harness()
    UnifiedApp._start_startup_loading_timer(harness)
    if "25% | " not in harness._startup_loading_progress_label.text:
        raise AssertionError(
            "Startup timer should refresh footer without a status event."
        )
    if "Elapsed:" in harness._startup_loading_detail_label.text:
        raise AssertionError(
            "Elapsed text should not be duplicated into detail labels."
        )
    if harness._startup_loading_timer_after_id is None:
        raise AssertionError("Startup timer should schedule a follow-up heartbeat.")

    UnifiedApp._update_startup_loading_splash_progress(
        harness,
        progress=10.0,
        message="Short",
    )
    if float(harness._startup_loading_progress_value) != 25.0:
        raise AssertionError("Startup progress should remain monotonic without reset.")
    UnifiedApp._update_startup_loading_splash_progress(
        harness,
        progress=5.0,
        message="Reset",
        reset=True,
    )
    if float(harness._startup_loading_progress_value) != 5.0:
        raise AssertionError("Startup progress reset should allow lower values.")
    if harness._startup_loading_label.text != "Reset":
        raise AssertionError("Short replacement status should overwrite previous text.")


