def _log_co2_dosing_math(
    math_logger: SolubilityMathLogger,
    *,
    naoh_mass_g: float,
    naoh_mol: float,
    co2_mass_g: float,
    co2_mol: float,
    stage1_co2: float,
    stage2_co2: float,
    na2co3_from_stage1: float,
    naoh_after_stage1: float,
    na2co3_remaining: float,
    nahco3_produced: float,
    co2_excess: float,
    co2_after_stage1: float,
    co3_current: float,
    hco3_current: float,
    measurement_label: Optional[str],
    measurement_value: Optional[float],
    ratio_estimate: Optional[float],
    pka2_value: float,
    desired_ph: float,
    ratio_target: float,
    co2_for_ratio: float,
    co2_for_naoh: float,
    total_extra_mol: float,
    total_extra_g: float,
) -> None:
    """Perform log CO2 dosing math.
    Used to keep the workflow logic localized and testable."""
    section = "CO2 Dosing"
    math_logger.log(
        section,
        "NaOH charge (mol)",
        f"{naoh_mass_g:.2f} g / {SOL_MW_NAOH:.3f} g/mol",
        f"{naoh_mol:.4f}",
        units="mol",
        steps=(
            SolubilityMathStep(
                title="Mass to moles",
                expression="n = m / MW",
                latex=r"n = \frac{m}{MW}",
                detail="Convert NaOH mass into moles.",
            ),
            SolubilityMathStep(
                title="Substitute",
                expression=f"n = {naoh_mass_g:.2f} / {SOL_MW_NAOH:.3f}",
                latex=rf"n = \frac{{{naoh_mass_g:.2f}}}{{{SOL_MW_NAOH:.3f}}}",
            ),
            SolubilityMathStep(
                title="Evaluate",
                expression=f"n = {naoh_mol:.4f} mol",
            ),
        ),
    )
    math_logger.log(
        section,
        "CO2 added (mol)",
        f"{co2_mass_g:.2f} g / {SOL_MW_CO2:.4f} g/mol",
        f"{co2_mol:.4f}",
        units="mol",
        steps=(
            SolubilityMathStep(
                title="Mass to moles",
                expression="n = m / MW",
                latex=r"n = \frac{m}{MW}",
                detail="Convert charged CO2 mass into moles.",
            ),
            SolubilityMathStep(
                title="Substitute",
                expression=f"n = {co2_mass_g:.2f} / {SOL_MW_CO2:.4f}",
                latex=rf"n = \frac{{{co2_mass_g:.2f}}}{{{SOL_MW_CO2:.4f}}}",
            ),
            SolubilityMathStep(
                title="Evaluate",
                expression=f"n = {co2_mol:.4f} mol",
            ),
        ),
    )
    naoh_half = naoh_mol / 2.0
    math_logger.log(
        section,
        "Stage 1: 2 NaOH + CO2 -> Na2CO3",
        f"min({co2_mol:.4f}, {naoh_half:.4f})",
        f"{stage1_co2:.4f}",
        units="mol",
        steps=(
            SolubilityMathStep(
                title="Stoichiometry",
                expression="2 NaOH + CO2 -> Na2CO3 + H2O",
                latex=r"2\,NaOH + CO_2 \rightarrow Na_2CO_3 + H_2O",
                detail="Two moles of NaOH consume one mole of CO2.",
            ),
            SolubilityMathStep(
                title="Limiting reagent",
                expression=(
                    f"n_CO2 = {co2_mol:.4f} mol; " f"n_NaOH/2 = {naoh_half:.4f} mol"
                ),
            ),
            SolubilityMathStep(
                title="Extent",
                expression=(
                    f"min({co2_mol:.4f}, {naoh_half:.4f}) = {stage1_co2:.4f} mol"
                ),
            ),
        ),
    )
    math_logger.log(
        section,
        "Stage 2: Na2CO3 + CO2 -> 2 NaHCO3",
        f"min({co2_after_stage1:.4f}, {na2co3_from_stage1:.4f})",
        f"{stage2_co2:.4f}",
        units="mol",
        steps=(
            SolubilityMathStep(
                title="Stoichiometry",
                expression="Na2CO3 + CO2 + H2O -> 2 NaHCO3",
                latex=r"Na_2CO_3 + CO_2 + H_2O \rightarrow 2\,NaHCO_3",
                detail="Each mole of Na2CO3 converts with one mole of CO2.",
            ),
            SolubilityMathStep(
                title="Remaining feed",
                expression=(
                    f"CO2 remaining = {co2_after_stage1:.4f} mol; "
                    f"Na2CO3 = {na2co3_from_stage1:.4f} mol"
                ),
            ),
            SolubilityMathStep(
                title="Extent",
                expression=(
                    f"min({co2_after_stage1:.4f}, {na2co3_from_stage1:.4f}) = "
                    f"{stage2_co2:.4f} mol"
                ),
            ),
        ),
    )
    buffer_carbon = na2co3_remaining + nahco3_produced
    current_ratio = co3_current / max(hco3_current, 1e-12)
    math_logger.log(
        section,
        "Carbonate ledger",
        "Na2CO3 + NaHCO3",
        f"{buffer_carbon:.4f} mol",
        units="mol",
        steps=(
            SolubilityMathStep(
                title="Na2CO3",
                expression=f"{na2co3_remaining:.4f} mol remain",
            ),
            SolubilityMathStep(
                title="NaHCO3",
                expression=f"{nahco3_produced:.4f} mol produced",
            ),
            SolubilityMathStep(
                title="Dissolved CO2",
                expression=f"{co2_excess:.4f} mol excess",
            ),
        ),
    )
    math_logger.log(
        section,
        "Current carbonate ratio",
        "[CO3]/[HCO3]",
        f"{current_ratio:.4f}",
        steps=(
            SolubilityMathStep(
                title="Ledger split",
                expression=f"[CO3] = {co3_current:.4f} mol",
            ),
            SolubilityMathStep(
                title="Ledger split",
                expression=f"[HCO3] = {hco3_current:.4f} mol",
            ),
            SolubilityMathStep(
                title="Ratio",
                expression=(
                    f"{co3_current:.4f} / {max(hco3_current,1e-12):.4f} = "
                    f"{current_ratio:.4f}"
                ),
            ),
        ),
    )
    if measurement_value is not None and ratio_estimate is not None:
        label = measurement_label or "Measurement"
        math_logger.log(
            section,
            f"{label} ratio estimate",
            f"10^({measurement_value:.2f} - {pka2_value:.2f})",
            f"{ratio_estimate:.4f}",
            steps=(
                SolubilityMathStep(
                    title="Henderson-Hasselbalch",
                    expression="pH = pKa2 + log10([CO3]/[HCO3])",
                    latex=r"pH = pK_{a2} + \log_{10}\frac{[CO_3^{2-}]}{[HCO_3^-]}",
                    detail="Rearrange to solve for the carbonate ratio at the measured pH.",
                ),
                SolubilityMathStep(
                    title="Solve for ratio",
                    expression=(
                        f"[CO3]/[HCO3] = 10^({measurement_value:.2f} - {pka2_value:.2f})"
                    ),
                    latex=(
                        rf"\frac{{[CO_3^{{2-}}]}}{{[HCO_3^-]}} = "
                        rf"10^{{({measurement_value:.2f} - {pka2_value:.2f})}}"
                    ),
                ),
                SolubilityMathStep(
                    title="Evaluate",
                    expression=f"ratio = {ratio_estimate:.4f}",
                ),
                SolubilityMathStep(
                    title="Interpret ratio",
                    expression=">1 carbonate-rich, <1 bicarbonate-rich",
                    detail="Shows how the measured pH skews the CO3^2-/HCO3^- balance.",
                ),
            ),
        )
    math_logger.log(
        section,
        "Target ratio",
        f"10^({desired_ph:.2f} - {pka2_value:.2f})",
        f"{ratio_target:.4f}",
        steps=(
            SolubilityMathStep(
                title="Henderson-Hasselbalch",
                expression="pH = pKa2 + log10([CO3]/[HCO3])",
                latex=r"pH = pK_{a2} + \log_{10}\frac{[CO_3^{2-}]}{[HCO_3^-]}",
                detail="Solve for the desired carbonate ratio at the target pH.",
            ),
            SolubilityMathStep(
                title="Solve for ratio",
                expression=(f"[CO3]/[HCO3] = 10^({desired_ph:.2f} - {pka2_value:.2f})"),
                latex=(
                    rf"\frac{{[CO_3^{{2-}}]}}{{[HCO_3^-]}} = "
                    rf"10^{{({desired_ph:.2f} - {pka2_value:.2f})}}"
                ),
            ),
            SolubilityMathStep(
                title="Evaluate",
                expression=f"ratio = {ratio_target:.4f}",
            ),
        ),
    )
    math_logger.log(
        section,
        "CO2 for ratio shift",
        "(CO3 - R * HCO3) / (1 + 2R)",
        f"{co2_for_ratio:.4f}",
        units="mol",
        steps=(
            SolubilityMathStep(
                title="Formula",
                expression="n = (CO3 - R * HCO3) / (1 + 2R)",
                latex=r"n_{\text{ratio}} = \frac{[CO_3^{2-}] - R[HCO_3^-]}{1 + 2R}",
                detail="Add CO2 until the carbonate ratio reaches R = [CO3]/[HCO3].",
            ),
            SolubilityMathStep(
                title="Substitute",
                expression=(
                    f"({co3_current:.4f} - {ratio_target:.4f} * {hco3_current:.4f}) "
                    f"/ (1 + 2*{ratio_target:.4f})"
                ),
            ),
            SolubilityMathStep(
                title="Evaluate",
                expression=f"n = {co2_for_ratio:.4f} mol",
            ),
        ),
    )
    math_logger.log(
        section,
        "CO2 for residual NaOH",
        "n = n_NaOH_remaining / 2",
        f"{co2_for_naoh:.4f}",
        units="mol",
        steps=(
            SolubilityMathStep(
                title="Definition",
                expression="2 NaOH + CO2 -> Na2CO3 + H2O",
                latex=r"2\,NaOH + CO_2 \rightarrow Na_2CO_3 + H_2O",
                detail="Each mole of CO2 neutralizes two moles of NaOH.",
            ),
            SolubilityMathStep(
                title="Remaining NaOH",
                expression=f"n_NaOH = {naoh_after_stage1:.4e} mol",
            ),
            SolubilityMathStep(
                title="Required CO2",
                expression=f"{naoh_after_stage1:.4e} / 2 = {co2_for_naoh:.4f} mol",
            ),
        ),
    )
    math_logger.log(
        section,
        "Total CO2 recommendation (mol)",
        "n_total = n_ratio + n_NaOH",
        f"{total_extra_mol:.4f}",
        units="mol",
        steps=(
            SolubilityMathStep(
                title="Ratio adjustment",
                expression=f"n_ratio = {co2_for_ratio:.4f} mol",
            ),
            SolubilityMathStep(
                title="NaOH neutralization",
                expression=f"n_NaOH = {co2_for_naoh:.4f} mol",
            ),
            SolubilityMathStep(
                title="Sum",
                expression=(
                    f"{co2_for_ratio:.4f} + {co2_for_naoh:.4f} = {total_extra_mol:.4f} mol"
                ),
                latex=r"n_{\text{total}} = n_{\text{ratio}} + n_{\text{NaOH}}",
            ),
        ),
    )
    math_logger.log(
        section,
        "Total CO2 recommendation (g)",
        f"{total_extra_mol:.4f} mol * {SOL_MW_CO2:.4f} g/mol",
        f"{total_extra_g:.2f}",
        units="g",
        steps=(
            SolubilityMathStep(
                title="Convert to mass",
                expression="m = n * MW",
                latex=r"m = n \times MW",
            ),
            SolubilityMathStep(
                title="Substitute",
                expression=(
                    f"{total_extra_mol:.4f} * {SOL_MW_CO2:.4f} = {total_extra_g:.2f} g"
                ),
            ),
        ),
    )


def _log_reaction_tracker_math(
    math_logger: Optional[SolubilityMathLogger],
    entries: Sequence[Dict[str, Any]],
) -> None:
    """Perform log reaction tracker math.
    Used to keep the workflow logic localized and testable."""
    if not math_logger or not math_logger.enabled:
        return
    section = "Reaction Progress Tracker"
    prev_total = 0.0
    # Iterate over indexed elements from entries, 1 to apply the per-item logic.
    for idx, entry in enumerate(entries, 1):
        total_mass = _safe_float(entry.get("co2_g"))
        if total_mass is None or not math.isfinite(total_mass):
            continue
        timestamp = str(entry.get("timestamp") or f"Entry {idx}")
        notes = str(entry.get("notes") or "").strip()
        ph_value = _safe_float(entry.get("ph"))
        delta_mass = total_mass - prev_total
        steps: List[SolubilityMathStep] = [
            SolubilityMathStep(
                title="Mass basis",
                expression=f"m_CO2 = {total_mass:.2f} g",
                latex=rf"m_{{\mathrm{{CO_2}}}} = {total_mass:.2f}\,\mathrm{{g}}",
                detail=notes or "Logged measurement",
            ),
            SolubilityMathStep(
                title="Incremental CO2",
                expression=f"Delta m = {total_mass:.2f} - {prev_total:.2f} = {delta_mass:.2f} g",
                latex=rf"\Delta m = {total_mass:.2f} - {prev_total:.2f} = {delta_mass:.2f}",
            ),
            SolubilityMathStep(
                title="Convert to moles",
                expression=f"n = {total_mass:.2f} / {SOL_MW_CO2:.4f}",
                latex=rf"n = \frac{{{total_mass:.2f}}}{{{SOL_MW_CO2:.4f}}}",
                units="mol",
            ),
        ]
        if ph_value is not None and math.isfinite(ph_value):
            steps.append(
                SolubilityMathStep(
                    title="Measured pH",
                    expression=f"pH = {ph_value:.2f}",
                    latex=rf"\mathrm{{pH}} = {ph_value:.2f}",
                )
            )
        total_moles = total_mass / SOL_MW_CO2
        math_logger.log(
            section,
            f"Tracker entry #{idx} ({timestamp})",
            r"n_{\mathrm{CO_2}} = \frac{m_{\mathrm{CO_2}}}{MW_{\mathrm{CO_2}}}",
            f"{total_moles:.4f}",
            units="mol",
            steps=tuple(steps),
        )
        prev_total = total_mass


def _log_inputs_constants_basis_math(
    math_logger: Optional[SolubilityMathLogger],
    *,
    solver_inputs: SolubilitySolverInputs,
    model: SpeciationModel,
) -> None:
    """Log input constants and basis conversions for Math Viewer transparency.

    Purpose:
        Capture scalar inputs, thermodynamic constants, and mode-defining
        equations used as the foundation for active-model calculations.
    Why:
        Users need one auditable section showing how the active run basis was
        assembled before pH/speciation and requirement calculations.
    Inputs:
        math_logger: Optional detailed-math logger sink.
        solver_inputs: Prepared solver input bundle for the active workflow.
        model: Active speciation model instance used by the solver.
    Outputs:
        None.
    Side Effects:
        Appends entries to the math logger when enabled.
    Exceptions:
        Best-effort conversion failures are handled without raising.
    """
    if not math_logger or not math_logger.enabled:
        return
    params = solver_inputs.params
    section = "Inputs / Constants / Basis Conversions"
    model_key = str(getattr(model, "key", "") or "")
    model_label = str(getattr(model, "label", model_key) or model_key)
    math_logger.log(
        section,
        "Active model",
        "model_key / model_label",
        f"{model_key} / {model_label}",
        steps=(
            SolubilityMathStep(
                title="Selection",
                expression=f"key = {model_key}",
                detail="Math Viewer remains scoped to the active model only.",
            ),
        ),
    )
    volume_l: Optional[float]
    try:
        volume_l = _safe_float(params.volume_l())
    except Exception:
        volume_l = _safe_float(solver_inputs.reaction_solution_volume)
    water_mass_g = _safe_float(getattr(params, "water_mass_g", None))
    if water_mass_g is None and volume_l is not None and volume_l > 0:
        water_mass_g = volume_l * 1000.0 * SOL_WATER_DENSITY_25C_G_PER_ML
    naoh_mass_g = _safe_float(solver_inputs.reaction_naoh_mass)
    if (
        naoh_mass_g is not None
        and naoh_mass_g > 0
        and volume_l is not None
        and volume_l > 0
    ):
        naoh_mol = naoh_mass_g / SOL_MW_NAOH
        naoh_molarity = naoh_mol / volume_l
        math_logger.log(
            section,
            "NaOH basis concentration",
            "C_NaOH = (m_NaOH / MW_NaOH) / V",
            f"{naoh_molarity:.6e}",
            units="mol/L",
            steps=(
                SolubilityMathStep(
                    title="Symbolic",
                    expression="C_NaOH = (m_NaOH / MW_NaOH) / V",
                    latex=r"C_{\mathrm{NaOH}}=\frac{m_{\mathrm{NaOH}}/MW_{\mathrm{NaOH}}}{V}",
                ),
                SolubilityMathStep(
                    title="Substitute",
                    expression=(
                        f"(({naoh_mass_g:.4f} / {SOL_MW_NAOH:.4f}) / {volume_l:.6f})"
                    ),
                ),
                SolubilityMathStep(
                    title="Evaluate",
                    expression=f"C_NaOH = {naoh_molarity:.6e} mol/L",
                    units="mol/L",
                ),
            ),
        )
    if volume_l is not None and volume_l > 0:
        math_logger.log(
            section,
            "Solution volume basis",
            "V",
            f"{volume_l:.6f}",
            units="L",
            steps=(SolubilityMathStep(title="Volume basis", expression=f"V = {volume_l:.6f} L"),),
        )
    if water_mass_g is not None and water_mass_g > 0:
        math_logger.log(
            section,
            "Water basis mass",
            "m_water",
            f"{water_mass_g:.3f}",
            units="g",
            steps=(SolubilityMathStep(title="Water basis", expression=f"m_water = {water_mass_g:.3f} g"),),
        )
    ka1, ka2, kw = _basic_carbonate_constants(
        _safe_float(params.temperature_c),
        bool(getattr(params, "use_temperature_adjusted_constants", False)),
    )
    pka1 = -math.log10(max(ka1, 1e-30))
    pka2 = -math.log10(max(ka2, 1e-30))
    pkw = -math.log10(max(kw, 1e-30))
    math_logger.log(
        section,
        "Carbonate equilibrium constants",
        "K_a1, K_a2, K_w",
        f"{ka1:.6e}, {ka2:.6e}, {kw:.6e}",
        steps=(
            SolubilityMathStep(
                title="Definitions",
                expression="K_a1 = 10^(-pK_a1), K_a2 = 10^(-pK_a2), K_w = 10^(-pK_w)",
                latex=r"K_{a1}=10^{-pK_{a1}},\;K_{a2}=10^{-pK_{a2}},\;K_w=10^{-pK_w}",
            ),
            SolubilityMathStep(
                title="Resolved pK values",
                expression=f"pK_a1 = {pka1:.4f}, pK_a2 = {pka2:.4f}, pK_w = {pkw:.4f}",
            ),
            SolubilityMathStep(
                title="Evaluate constants",
                expression=f"K_a1 = {ka1:.6e}, K_a2 = {ka2:.6e}, K_w = {kw:.6e}",
            ),
        ),
    )
    math_logger.log(
        section,
        "Speciation and charge-balance equations",
        "alpha_i, pH, ionic strength, and residual",
        "captured",
        steps=(
            SolubilityMathStep(
                title="Speciation fractions",
                expression="alpha0, alpha1, alpha2 from H+, K_a1, K_a2",
                latex=(
                    r"\alpha_0=\frac{[H^+]^2}{D},\;"
                    r"\alpha_1=\frac{K_{a1}[H^+]}{D},\;"
                    r"\alpha_2=\frac{K_{a1}K_{a2}}{D},\;"
                    r"D=[H^+]^2+K_{a1}[H^+]+K_{a1}K_{a2}"
                ),
            ),
            SolubilityMathStep(
                title="pH definition",
                expression="pH = -log10([H+])",
                latex=r"\mathrm{pH}=-\log_{10}[H^+]",
            ),
            SolubilityMathStep(
                title="Ionic strength and charge residual",
                expression="I = 0.5*sum(c_i*z_i^2), R_q = cations - anions",
                latex=(
                    r"I=\frac{1}{2}\sum_i c_i z_i^2,\;"
                    r"R_q=[Na^+]+[H^+]-([HCO_3^-]+2[CO_3^{2-}]+[OH^-])"
                ),
            ),
        ),
    )
    mode = _normalize_speciation_mode(getattr(params, "speciation_mode", None))
    if mode == SPEC_MODE_CLOSED:
        mode_expr = "f(H+) = [H+] + [Na+] - [OH-] - [HCO3-] - 2[CO3^2-] = 0"
        mode_latex = r"f([H^+])=[H^+]+[Na^+]-[OH^-]-[HCO_3^-]-2[CO_3^{2-}]=0"
    else:
        mode_expr = "fixed [H2CO3] from Henry law: [H2CO3] = pCO2 * K_H"
        mode_latex = r"[H_2CO_3^\ast]=p_{\mathrm{CO_2}}K_H"
    math_logger.log(
        section,
        "Boundary mode residual",
        "Closed-system root vs fixed-pCO2 boundary",
        mode,
        steps=(SolubilityMathStep(title="Mode equation", expression=mode_expr, latex=mode_latex),),
    )


def _log_active_model_pathway_math(
    math_logger: Optional[SolubilityMathLogger],
    *,
    solver_inputs: SolubilitySolverInputs,
    model: SpeciationModel,
    result: SolubilitySpeciationResult,
) -> None:
    """Log the active-model pH/speciation pathway and model-specific equations.

    Purpose:
        Expose the exact active-model pathway used to produce displayed pH and
        carbonate species values.
    Why:
        Math Viewer users need model-aware traceability without recomputing all
        models in one run.
    Inputs:
        math_logger: Optional detailed-math logger sink.
        solver_inputs: Prepared solver inputs for this run.
        model: Active model instance.
        result: Solved speciation output for the active model.
    Outputs:
        None.
    Side Effects:
        Appends model-pathway sections and steps to the math logger.
    Exceptions:
        Best-effort conversion failures are handled without raising.
    """
    if not math_logger or not math_logger.enabled:
        return
    model_key = str(getattr(model, "key", "") or "").strip().lower()
    model_label = str(getattr(model, "label", model_key) or model_key)
    section = "Active-Model pH / Speciation Pathway"
    math_logger.log(
        section,
        "Active model pathway",
        "model key -> solver -> displayed pH/speciation",
        model_label,
        steps=(
            SolubilityMathStep(title="Selection", expression=f"model_key = {model_key or 'unknown'}"),
            SolubilityMathStep(
                title="Displayed pH",
                expression=f"pH_active = {result.ph:.4f}",
                latex=rf"\mathrm{{pH}}_{{\mathrm{{active}}}}={result.ph:.4f}",
                units="pH",
            ),
        ),
    )
    fractions = result.fractional_carbon or {}
    h2co3_frac = _safe_float(fractions.get("H2CO3"), 0.0) or 0.0
    hco3_frac = _safe_float(fractions.get("HCO3-"), 0.0) or 0.0
    co3_frac = _safe_float(fractions.get("CO3^2-"), 0.0) or 0.0
    math_logger.log(
        section,
        "Displayed carbonate fractions",
        "alpha_i = C_i / C_T",
        f"{h2co3_frac*100.0:.2f}% / {hco3_frac*100.0:.2f}% / {co3_frac*100.0:.2f}%",
        units="%",
        steps=(
            SolubilityMathStep(title="Fraction definitions", expression="alpha_i = C_i / C_T", latex=r"\alpha_i=\frac{C_i}{C_T}"),
            SolubilityMathStep(
                title="Evaluate",
                expression=f"alpha0={h2co3_frac:.6f}, alpha1={hco3_frac:.6f}, alpha2={co3_frac:.6f}",
            ),
        ),
    )
    if model_key in {"debye_huckel_full", "debye_huckel_capped"}:
        math_logger.log(
            section,
            "Debye-Huckel activity equation",
            "log10(gamma_i) = -A*z_i^2*sqrt(I)/(1 + B*a_i*sqrt(I))",
            "used",
            steps=(
                SolubilityMathStep(
                    title="Symbolic form",
                    expression="Extended Debye-Huckel",
                    latex=r"\log_{10}\gamma_i=-\frac{A z_i^2\sqrt{I}}{1+B a_i\sqrt{I}}",
                ),
            ),
        )
    elif model_key == "davies_limited":
        math_logger.log(
            section,
            "Davies activity equation",
            "log10(gamma_i) = -A*z_i^2*(sqrt(I)/(1+sqrt(I)) - 0.3*I)",
            "used",
            steps=(
                SolubilityMathStep(
                    title="Symbolic form",
                    expression="Davies limited regime",
                    latex=r"\log_{10}\gamma_i=-A z_i^2\left(\frac{\sqrt{I}}{1+\sqrt{I}}-0.3I\right)",
                ),
            ),
        )
    elif model_key == "pitzer_lite":
        math_logger.log(
            section,
            "Pitzer-lite activity expression",
            "ln(gamma_i) from ion-interaction virial terms",
            "used",
            steps=(
                SolubilityMathStep(
                    title="Symbolic form",
                    expression="b0, b1, c_phi interactions",
                    latex=r"\ln\gamma_i=f(I)+\sum_j m_j(2B_{ij}+Z C_{ij})+\cdots",
                ),
            ),
        )
    elif model_key == "aqion_closed":
        math_logger.log(
            section,
            "Aqion closed-system root",
            "charge-balance root solve with alpha fractions",
            "used",
            steps=(
                SolubilityMathStep(
                    title="Closed-system residual",
                    expression="[H+] - [OH-] - [HCO3-] - 2[CO3^2-] = 0",
                    latex=r"[H^+]-[OH^-]-[HCO_3^-]-2[CO_3^{2-}]=0",
                ),
            ),
        )
    if model_key == "naoh_co2_pitzer_hmw":
        _log_naoh_pitzer_model_math(math_logger, solver_inputs=solver_inputs, result=result)


def _log_naoh_pitzer_model_math(
    math_logger: SolubilityMathLogger,
    *,
    solver_inputs: SolubilitySolverInputs,
    result: SolubilitySpeciationResult,
) -> None:
    """Log dedicated NaOH-CO2 Pitzer HMW model details for traceability.

    Purpose:
        Provide deep, model-specific transparency for context normalization,
        solver-path routing, and species outputs that feed dashboard metrics.
    Why:
        NaOH Pitzer HMW is the most detailed planning model and needs explicit
        math-path visibility in both docs and Math Viewer.
    Inputs:
        math_logger: Enabled logger receiving detailed entries.
        solver_inputs: Active solver input bundle.
        result: Active-model solved speciation payload.
    Outputs:
        None.
    Side Effects:
        Appends entries to the `NaOH Pitzer HMW Detail` section.
    Exceptions:
        Conversion failures are handled without raising.
    """
    params = solver_inputs.params
    section = "NaOH Pitzer HMW Detail"
    water_kg = None
    water_mass_g = _safe_float(getattr(params, "water_mass_g", None))
    if water_mass_g is not None and water_mass_g > 0:
        water_kg = water_mass_g / 1000.0
    else:
        volume_l = _safe_float(getattr(params, "solution_volume_l", None))
        if volume_l is None:
            try:
                volume_l = _safe_float(params.volume_l())
            except Exception:
                volume_l = None
        if volume_l is not None and volume_l > 0:
            water_kg = max(
                (volume_l * 1000.0 * SOL_WATER_DENSITY_25C_G_PER_ML) / 1000.0,
                1e-9,
            )
    naoh_mass_g = _safe_float(solver_inputs.reaction_naoh_mass)
    cumulative_co2_g = _safe_float(solver_inputs.reaction_co2_g)
    if (
        water_kg is not None
        and water_kg > 0
        and naoh_mass_g is not None
        and naoh_mass_g > 0
    ):
        na_total_m = (naoh_mass_g / SOL_MW_NAOH) / water_kg
        ct_m = (
            (max(cumulative_co2_g, 0.0) / SOL_MW_CO2) / water_kg
            if cumulative_co2_g is not None
            else None
        )
        math_logger.log(
            section,
            "Context normalization",
            "Na_total and C_T on kg-water basis",
            (
                f"Na_total = {na_total_m:.6e} mol/kg"
                + (
                    f", C_T = {ct_m:.6e} mol/kg"
                    if ct_m is not None and math.isfinite(ct_m)
                    else ""
                )
            ),
            steps=(
                SolubilityMathStep(title="Water basis", expression=f"kg_water = {water_kg:.6f}", units="kg"),
                SolubilityMathStep(
                    title="Na total molality",
                    expression=f"m_NaT = ({naoh_mass_g:.4f}/{SOL_MW_NAOH:.4f})/{water_kg:.6f}",
                    latex=r"m_{\mathrm{NaT}}=\frac{m_{\mathrm{NaOH}}/MW_{\mathrm{NaOH}}}{kg_{\mathrm{water}}}",
                    units="mol/kg",
                ),
                SolubilityMathStep(
                    title="CO2 total molality",
                    expression=f"m_CT = ({max(cumulative_co2_g or 0.0, 0.0):.4f}/{SOL_MW_CO2:.4f})/{water_kg:.6f}",
                    latex=r"m_{CT}=\frac{m_{\mathrm{CO_2}}/MW_{\mathrm{CO_2}}}{kg_{\mathrm{water}}}",
                    units="mol/kg",
                ),
            ),
        )
    rust_mode = _current_rust_backend_mode()
    math_logger.log(
        section,
        "Rust/Python health-gated path",
        "auto policy with parity and timeout gates",
        rust_mode,
        steps=(
            SolubilityMathStep(
                title="Runtime policy",
                expression=f"rust_backend_mode = {rust_mode}",
                detail=(
                    "Rust path is used only when payload validation and parity gates pass; "
                    "otherwise Python baseline is used fail-closed."
                ),
            ),
        ),
    )
    species = result.concentrations_m or {}
    ct_value = (
        _safe_float(species.get("H2CO3"), 0.0)
        + _safe_float(species.get("HCO3-"), 0.0)
        + _safe_float(species.get("CO3^2-"), 0.0)
    )
    math_logger.log(
        section,
        "Core solve outputs feeding dashboard metrics",
        "pH, species, and C_T values drive requirement/completion/forecast",
        f"pH={result.ph:.4f}, C_T={ct_value:.6e} mol/L",
        steps=(
            SolubilityMathStep(
                title="Total inorganic carbon",
                expression=(
                    f"C_T = {species.get('H2CO3', 0.0):.6e} + "
                    f"{species.get('HCO3-', 0.0):.6e} + {species.get('CO3^2-', 0.0):.6e}"
                ),
                latex=r"C_T=[H_2CO_3]+[HCO_3^-]+[CO_3^{2-}]",
                units="mol/L",
            ),
        ),
    )


def _log_co2_requirement_completion_forecast_math(
    math_logger: Optional[SolubilityMathLogger],
    cycle_summary: Optional[Dict[str, Any]],
) -> None:
    """Log requirement precedence and completion/forecast derivations.

    Purpose:
        Record the exact target-gap, completion, and forecast formulas used by
        Analysis summary tiles in one transparent section.
    Why:
        Users compare these values directly in dashboard tiles and Math Viewer
        and need source precedence and substitutions shown step-by-step.
    Inputs:
        math_logger: Optional detailed-math logger sink.
        cycle_summary: Timeline/runtime payload that may include dashboard summary.
    Outputs:
        None.
    Side Effects:
        Appends entries into the math logger when Analysis summary is present.
    Exceptions:
        Missing or partial summary payloads are handled without raising.
    """
    if not math_logger or not math_logger.enabled:
        return
    summary_payload = cycle_summary or {}
    dashboard_payload = summary_payload.get("dashboard_payload")
    if not isinstance(dashboard_payload, Mapping):
        dashboard_payload = summary_payload.get("analysis_dashboard")
    summary = (
        dict(dashboard_payload.get("summary"))
        if isinstance(dashboard_payload, Mapping)
        and isinstance(dashboard_payload.get("summary"), Mapping)
        else {}
    )
    if not summary:
        return
    section = "CO2 Requirement / Completion / Forecast"
    requirement_source = str(summary.get("co2_requirement_source") or "").strip().lower()
    additional_g = _safe_float(summary.get("additional_co2_required_g"))
    required_total_g = _safe_float(summary.get("co2_required_for_target_ph_g"))
    primary_uptake_g = _safe_float(summary.get("corrected_total_uptake_g"))
    if primary_uptake_g is None:
        primary_uptake_g = _safe_float(summary.get("total_uptake_g"))
    if (
        additional_g is None
        and required_total_g is not None
        and primary_uptake_g is not None
        and math.isfinite(required_total_g)
        and math.isfinite(primary_uptake_g)
    ):
        additional_g = max(required_total_g - primary_uptake_g, 0.0)
    math_logger.log(
        section,
        "Requirement source precedence",
        "guidance_model -> measured_ph_calibration -> planning_reference",
        requirement_source or "unavailable",
        steps=(
            SolubilityMathStep(
                title="Priority order",
                expression=(
                    "1) guidance additional requirement, 2) measured-anchor calibration, "
                    "3) planning-reference fallback"
                ),
            ),
            SolubilityMathStep(
                title="Selected source",
                expression=f"source = {requirement_source or 'unavailable'}",
            ),
        ),
    )
    if required_total_g is not None and math.isfinite(required_total_g):
        math_logger.log(
            section,
            "Required total CO2 to target pH",
            "m_required = m_uptake + m_additional",
            f"{required_total_g:.6f}",
            units="g",
            steps=(
                SolubilityMathStep(
                    title="Symbolic",
                    expression="m_required = m_uptake + m_additional",
                    latex=r"m_{\mathrm{required}}=m_{\mathrm{uptake}}+m_{\mathrm{additional}}",
                    units="g",
                ),
                SolubilityMathStep(
                    title="Substitute",
                    expression=f"{(primary_uptake_g or 0.0):.6f} + {(additional_g or 0.0):.6f}",
                    units="g",
                ),
                SolubilityMathStep(
                    title="Evaluate",
                    expression=f"m_required = {required_total_g:.6f} g",
                    units="g",
                ),
            ),
        )
        math_logger.log(
            section,
            "Required total CO2 (moles)",
            "n_required = m_required / MW_CO2",
            f"{required_total_g / SOL_MW_CO2:.6f}",
            units="mol",
            steps=(
                SolubilityMathStep(
                    title="Symbolic",
                    expression="n_required = m_required / MW_CO2",
                    latex=r"n_{\mathrm{required}}=\frac{m_{\mathrm{required}}}{MW_{\mathrm{CO_2}}}",
                ),
                SolubilityMathStep(
                    title="Substitute",
                    expression=f"{required_total_g:.6f} / {SOL_MW_CO2:.6f}",
                ),
                SolubilityMathStep(
                    title="Evaluate",
                    expression=f"n_required = {required_total_g / SOL_MW_CO2:.6f} mol",
                    units="mol",
                ),
            ),
        )
    raw_completion = _safe_float(summary.get("planning_completion_pct"))
    corrected_completion = _safe_float(summary.get("corrected_planning_completion_pct"))
    if corrected_completion is None:
        corrected_completion = _safe_float(summary.get("completion_from_measured_ph_pct"))
    if raw_completion is not None and math.isfinite(raw_completion):
        math_logger.log(
            section,
            "Raw planning completion",
            "C_raw = clamp(m_raw_uptake / m_reference, 0, 1) * 100",
            f"{raw_completion:.4f}",
            units="%",
            steps=(
                SolubilityMathStep(
                    title="Formula",
                    expression="C_raw = clamp(m_raw_uptake / m_reference, 0, 1) * 100",
                    latex=r"C_{\mathrm{raw}}=\mathrm{clamp}\!\left(\frac{m_{\mathrm{raw\ uptake}}}{m_{\mathrm{reference}}},0,1\right)\times100",
                    units="%",
                ),
            ),
        )
    if corrected_completion is not None and math.isfinite(corrected_completion):
        math_logger.log(
            section,
            "Corrected planning completion",
            "C_corr = clamp(m_corrected_uptake / m_reference, 0, 1) * 100",
            f"{corrected_completion:.4f}",
            units="%",
            steps=(
                SolubilityMathStep(
                    title="Formula",
                    expression="C_corr = clamp(m_corrected_uptake / m_reference, 0, 1) * 100",
                    latex=r"C_{\mathrm{corr}}=\mathrm{clamp}\!\left(\frac{m_{\mathrm{corrected\ uptake}}}{m_{\mathrm{reference}}},0,1\right)\times100",
                    units="%",
                ),
            ),
        )
    if additional_g is not None and math.isfinite(additional_g):
        math_logger.log(
            section,
            "Target gap",
            "Delta_target = max(m_required - m_uptake, 0)",
            f"{additional_g:.6f}",
            units="g",
            steps=(
                SolubilityMathStep(
                    title="Formula",
                    expression="Delta_target = max(m_required - m_uptake, 0)",
                    latex=r"\Delta m_{\mathrm{target}}=\max\!\left(m_{\mathrm{required}}-m_{\mathrm{uptake}},0\right)",
                    units="g",
                ),
                SolubilityMathStep(
                    title="Substitute",
                    expression=f"max({(required_total_g or 0.0):.6f} - {(primary_uptake_g or 0.0):.6f}, 0)",
                    units="g",
                ),
                SolubilityMathStep(
                    title="Evaluate",
                    expression=f"Delta_target = {additional_g:.6f} g",
                    units="g",
                ),
            ),
        )
    forecast_tail_rate = _safe_float(summary.get("forecast_tail_rate_g_per_cycle"))
    forecast_cycles = _safe_float(summary.get("forecast_remaining_cycles"))
    forecast_time = _safe_float(summary.get("forecast_remaining_time_x"))
    if (
        additional_g is not None
        and forecast_tail_rate is not None
        and math.isfinite(additional_g)
        and math.isfinite(forecast_tail_rate)
        and forecast_tail_rate > 1e-12
    ):
        resolved_cycles = (
            forecast_cycles
            if forecast_cycles is not None and math.isfinite(forecast_cycles)
            else max(additional_g / forecast_tail_rate, 0.0)
        )
        math_logger.log(
            section,
            "Forecast remaining cycles",
            "N_remaining = Delta_target / r_tail",
            f"{resolved_cycles:.6f}",
            units="cycles",
            steps=(
                SolubilityMathStep(
                    title="Formula",
                    expression="N_remaining = Delta_target / r_tail",
                    latex=r"N_{\mathrm{remaining}}=\frac{\Delta m_{\mathrm{target}}}{r_{\mathrm{tail}}}",
                    units="cycles",
                ),
                SolubilityMathStep(
                    title="Substitute",
                    expression=f"{additional_g:.6f} / {forecast_tail_rate:.6f}",
                ),
                SolubilityMathStep(
                    title="Evaluate",
                    expression=f"N_remaining = {resolved_cycles:.6f}",
                    units="cycles",
                ),
            ),
        )
    if forecast_time is not None and math.isfinite(forecast_time):
        math_logger.log(
            section,
            "Forecast remaining time basis",
            "T_remaining = N_remaining * average_cycle_duration",
            f"{forecast_time:.6f}",
            units=str(summary.get("forecast_time_basis") or "x-units"),
            steps=(
                SolubilityMathStep(
                    title="Formula",
                    expression="T_remaining = N_remaining * average_cycle_duration",
                    latex=r"T_{\mathrm{remaining}}=N_{\mathrm{remaining}}\cdot \bar{t}_{\mathrm{cycle}}",
                ),
            ),
        )


def _log_cycle_timeline_math(
    math_logger: Optional[SolubilityMathLogger],
    cycle_summary: Optional[Dict[str, Any]],
) -> None:
    """Log cycle-level derivations for pH, speciation, and target-gap values.

    Purpose:
        Convert timeline rows into symbolic, substituted, and evaluated math
        steps so one cycle can be audited end-to-end in the Math Viewer.
    Why:
        Users need to trust cycle-level pH/speciation and CO2-to-target values
        without manually reconstructing equations from raw payload rows.
    Inputs:
        math_logger: Optional detailed-math logger sink.
        cycle_summary: Timeline summary payload with per-cycle chemistry rows.
    Outputs:
        None.
    Side Effects:
        Appends one cycle-derivation section to the active math logger.
    Exceptions:
        Invalid or incomplete rows are skipped without raising.
    """

    if not math_logger or not math_logger.enabled:
        return
    summary = cycle_summary or {}
    timeline = summary.get("timeline") or []
    if not timeline:
        return
    section = "Cycle-Level Derivations"
    supersat_factor = _safe_float(summary.get("supersaturation_factor"))
    if supersat_factor is not None and math.isfinite(supersat_factor):
        math_logger.log(
            section,
            "Supersaturation factor",
            "S = C_effective / C_eq",
            f"{supersat_factor:.2f}",
            units="ratio",
            steps=(
                SolubilityMathStep(
                    title="Definition",
                    expression="S = C_effective / C_eq",
                    latex=r"S=\frac{C_{\mathrm{effective}}}{C_{\mathrm{eq}}}",
                    units="ratio",
                ),
                SolubilityMathStep(
                    title="Evaluate",
                    expression=f"S = {supersat_factor:.2f}",
                    units="ratio",
                ),
            ),
        )
    headspace_g = _safe_float(summary.get("headspace_co2_g"))
    if headspace_g is not None and math.isfinite(headspace_g):
        math_logger.log(
            section,
            "Headspace CO2 inventory (summary)",
            "m_headspace",
            f"{headspace_g:.2f}",
            units="g",
            steps=(
                SolubilityMathStep(
                    title="Evaluate",
                    expression=f"m_headspace = {headspace_g:.2f} g",
                    units="g",
                ),
            ),
        )
    # Iterate over indexed elements from timeline, 1 to apply the per-item logic.
    for idx, entry in enumerate(timeline, 1):
        cycle_id = entry.get("cycle_id", idx)
        if entry.get("error"):
            math_logger.log(
                section,
                f"Cycle {cycle_id}",
                "Error",
                str(entry.get("error")),
            )
            continue
        delta_moles = _safe_float(entry.get("co2_moles"))
        delta_mass = (
            delta_moles * SOL_MW_CO2
            if delta_moles is not None and math.isfinite(delta_moles)
            else None
        )
        cumulative_mass = _safe_float(entry.get("co2_g"))
        cumulative_moles = _safe_float(entry.get("co2_total_moles"))
        equilibrium_ph = _safe_float(
            entry.get("equilibrium_ph", entry.get("ph", entry.get("solution_ph")))
        )
        if equilibrium_ph is None:
            equilibrium_ph = _safe_float(entry.get("speciation_ph"))
        forecast_ph = _safe_float(entry.get("forecast_ph"))
        target_ph = _safe_float(entry.get("target_ph"))
        co2_to_target = _safe_float(entry.get("co2_to_target_g"))
        pco2_atm = _safe_float(entry.get("pco2_atm"))
        solid_na2co3 = _safe_float(entry.get("solid_na2co3_g"))
        solid_nahco3 = _safe_float(entry.get("solid_nahco3_g"))
        fractions = entry.get("fractions") or {}
        frac_h2co3 = (_safe_float(fractions.get("H2CO3"), 0.0) or 0.0) * 100.0
        frac_hco3 = (_safe_float(fractions.get("HCO3-"), 0.0) or 0.0) * 100.0
        frac_co3 = (_safe_float(fractions.get("CO3^2-"), 0.0) or 0.0) * 100.0
        steps: List[SolubilityMathStep] = []
        if delta_moles is not None and math.isfinite(delta_moles):
            steps.append(
                SolubilityMathStep(
                    title="Symbolic cycle dose conversion",
                    expression="Delta m_CO2 = Delta n_CO2 * MW_CO2",
                    latex=r"\Delta m_{\mathrm{CO_2}}=\Delta n_{\mathrm{CO_2}}MW_{\mathrm{CO_2}}",
                    units="g",
                )
            )
            steps.append(
                SolubilityMathStep(
                    title="Substitute cycle dose",
                    expression=f"Delta m_CO2 = {delta_moles:.6f} * {SOL_MW_CO2:.6f}",
                    units="g",
                )
            )
            if delta_mass is not None and math.isfinite(delta_mass):
                steps.append(
                    SolubilityMathStep(
                        title="Evaluate cycle dose",
                        expression=f"Delta m_CO2 = {delta_mass:.6f} g",
                        units="g",
                    )
                )
            steps.append(
                SolubilityMathStep(
                    title="Cycle moles",
                    expression=f"Delta n_CO2 = {delta_moles:.6f} mol",
                    units="mol",
                )
            )
        if cumulative_moles is not None and math.isfinite(cumulative_moles):
            steps.append(
                SolubilityMathStep(
                    title="Cumulative moles",
                    expression=f"n_total = {cumulative_moles:.6f} mol",
                    latex=r"n_{\mathrm{total}}=\sum_{k=1}^{i}\Delta n_k",
                    units="mol",
                )
            )
            if cumulative_mass is not None and math.isfinite(cumulative_mass):
                steps.append(
                    SolubilityMathStep(
                        title="Cumulative mass",
                        expression=f"m_total = {cumulative_mass:.6f} g",
                        latex=r"m_{\mathrm{total}}=n_{\mathrm{total}}MW_{\mathrm{CO_2}}",
                        units="g",
                    )
                )
        if equilibrium_ph is not None and math.isfinite(equilibrium_ph):
            steps.append(
                SolubilityMathStep(
                    title="pH definition",
                    expression="pH = -log10([H+])",
                    latex=r"\mathrm{pH}=-\log_{10}[H^+]",
                    units="pH",
                )
            )
            steps.append(
                SolubilityMathStep(
                    title="Evaluate equilibrium pH",
                    expression=f"pH_eq = {equilibrium_ph:.4f}",
                    units="pH",
                )
            )
        if forecast_ph is not None and math.isfinite(forecast_ph):
            steps.append(
                SolubilityMathStep(
                    title="Forecast pH",
                    expression=f"pH_forecast = {forecast_ph:.4f}",
                    latex=r"\mathrm{pH}_{\mathrm{forecast}}",
                    units="pH",
                )
            )
        if target_ph is not None and math.isfinite(target_ph):
            steps.append(
                SolubilityMathStep(
                    title="Target pH reference",
                    expression=f"pH_target = {target_ph:.4f}",
                    units="pH",
                )
            )
        if co2_to_target is not None and math.isfinite(co2_to_target):
            steps.append(
                SolubilityMathStep(
                    title="Target-gap relation",
                    expression="Delta m_target = max(m_required - m_uptake, 0)",
                    latex=r"\Delta m_{\mathrm{target}}=\max\!\left(m_{\mathrm{required}}-m_{\mathrm{uptake}},0\right)",
                    units="g",
                )
            )
            steps.append(
                SolubilityMathStep(
                    title="Evaluate target gap",
                    expression=f"Delta m_target = {co2_to_target:.6f} g",
                    units="g",
                )
            )
        steps.append(
            SolubilityMathStep(
                title="Speciation fraction definitions",
                expression="alpha_i = C_i / C_T",
                latex=r"\alpha_i=\frac{C_i}{C_T}",
            )
        )
        steps.append(
            SolubilityMathStep(
                title="Evaluate speciation fractions",
                expression=(
                    f"alpha_H2CO3={frac_h2co3:.2f}%, alpha_HCO3={frac_hco3:.2f}%, "
                    f"alpha_CO3={frac_co3:.2f}%"
                ),
                units="%",
            )
        )
        steps.append(
            SolubilityMathStep(
                title="Solids and headspace",
                expression=(
                    f"Na2CO3 {(solid_na2co3 or 0.0):.4f} g, "
                    f"NaHCO3 {(solid_nahco3 or 0.0):.4f} g"
                ),
                detail=(
                    f"pCO2 ~= {pco2_atm:.6g} atm"
                    if pco2_atm is not None and math.isfinite(pco2_atm)
                    else "pCO2 not estimated"
                ),
            )
        )
        math_logger.log(
            section,
            f"Cycle {cycle_id} derivation",
            (
                f"Delta CO2 {delta_mass:.6f} g"
                if delta_mass is not None and math.isfinite(delta_mass)
                else "Delta CO2 n/a"
            ),
            (
                f"pH_eq {equilibrium_ph:.4f}"
                if equilibrium_ph is not None and math.isfinite(equilibrium_ph)
                else "pH n/a"
            ),
            steps=steps,
        )


def analyze_bicarbonate_reaction(
    *,
    naoh_mass_g: Optional[float],
    co2_charged_g: Optional[float],
    solution_volume_l: Optional[float],
    measured_ph: Optional[float],
    slurry_ph: Optional[float],
    target_ph: Optional[float],
    temperature_c: Optional[float],
    use_temp_adjusted_constants: bool,
    ionic_strength_cap: Optional[float] = None,
    math_logger: Optional[SolubilityMathLogger] = None,
) -> Optional[Dict[str, Any]]:
    """Analyze bicarbonate reaction.
    Used to produce bicarbonate reaction diagnostics or summaries."""

    if (
        naoh_mass_g is None
        or co2_charged_g is None
        or naoh_mass_g <= 0
        or co2_charged_g < 0
    ):
        return None

    naoh_mol = naoh_mass_g / SOL_MW_NAOH
    co2_mol = co2_charged_g / SOL_MW_CO2
    if naoh_mol <= 0:
        return None

    measurement_label = None
    measurement_value = None
    if measured_ph is not None:
        measurement_label = "Final product pH"
        measurement_value = measured_ph
    elif slurry_ph is not None:
        measurement_label = "Slurry pH"
        measurement_value = slurry_ph

    eq_constants = _basic_carbonate_constants(
        temperature_c, use_temp_adjusted_constants
    )
    desired_ph = target_ph if target_ph is not None else 8.0
    initial_guess = measurement_value if measurement_value is not None else desired_ph
    pka2_value = _resolve_pka2_value(temperature_c, use_temp_adjusted_constants)

    stage1_co2 = min(co2_mol, naoh_mol / 2.0)
    naoh_after_stage1 = max(0.0, naoh_mol - stage1_co2 * 2.0)
    na2co3_from_stage1 = stage1_co2
    co2_after_stage1 = max(0.0, co2_mol - stage1_co2)
    stage2_co2 = min(co2_after_stage1, na2co3_from_stage1)
    na2co3_remaining = max(0.0, na2co3_from_stage1 - stage2_co2)
    nahco3_produced = max(0.0, stage2_co2 * 2.0)
    co2_excess = max(0.0, co2_after_stage1 - stage2_co2)
    buffer_carbon = na2co3_remaining + nahco3_produced
    ratio_estimate = (
        10 ** (measurement_value - pka2_value)
        if measurement_value is not None
        else None
    )
    if buffer_carbon > 0 and ratio_estimate is not None:
        frac_co3 = ratio_estimate / (1.0 + ratio_estimate)
        co3_current = buffer_carbon * frac_co3
        hco3_current = max(0.0, buffer_carbon - co3_current)
    else:
        co3_current = na2co3_remaining
        hco3_current = nahco3_produced
    ratio_target = 10 ** (desired_ph - pka2_value)
    numerator = co3_current - ratio_target * hco3_current
    denom = 1.0 + 2.0 * ratio_target
    co2_for_ratio = 0.0
    if denom > 0 and numerator > 0:
        co2_for_ratio = min(numerator / denom, max(co3_current, 0.0))
    co2_for_naoh = naoh_after_stage1 / 2.0
    total_extra_mol = max(0.0, co2_for_ratio) + max(0.0, co2_for_naoh)
    total_extra_g = total_extra_mol * SOL_MW_CO2
    predicted_ph = float("nan")
    slider_max_g = max(total_extra_g * 1.6, 2.0)
    simulation_curve: List[Dict[str, float]] = []

    rust_core = _rust_analyze_bicarbonate_core(
        naoh_mass_g=naoh_mass_g,
        co2_charged_g=co2_charged_g,
        solution_volume_l=solution_volume_l,
        measured_ph=measured_ph,
        slurry_ph=slurry_ph,
        target_ph=target_ph,
        temperature_c=temperature_c,
        use_temp_adjusted_constants=use_temp_adjusted_constants,
        ionic_strength_cap=ionic_strength_cap,
        constants=eq_constants,
    )
    if rust_core is not None:
        # Rust path supplies the heavy Newton/ledger loop results.
        naoh_mol = _safe_rust_float(rust_core.get("naoh_mol"), naoh_mol)
        co2_mol = _safe_rust_float(rust_core.get("co2_mol"), co2_mol)
        stage1_co2 = _safe_rust_float(rust_core.get("stage1_co2"), stage1_co2)
        naoh_after_stage1 = _safe_rust_float(
            rust_core.get("naoh_after_stage1"), naoh_after_stage1
        )
        na2co3_from_stage1 = _safe_rust_float(
            rust_core.get("na2co3_from_stage1"), na2co3_from_stage1
        )
        co2_after_stage1 = _safe_rust_float(
            rust_core.get("co2_after_stage1"), co2_after_stage1
        )
        stage2_co2 = _safe_rust_float(rust_core.get("stage2_co2"), stage2_co2)
        na2co3_remaining = _safe_rust_float(
            rust_core.get("na2co3_remaining"), na2co3_remaining
        )
        nahco3_produced = _safe_rust_float(
            rust_core.get("nahco3_produced"), nahco3_produced
        )
        co2_excess = _safe_rust_float(rust_core.get("co2_excess"), co2_excess)
        buffer_carbon = _safe_rust_float(rust_core.get("buffer_carbon"), buffer_carbon)
        pka2_value = _safe_rust_float(rust_core.get("pka2_value"), pka2_value)
        co3_current = _safe_rust_float(rust_core.get("co3_current"), co3_current)
        hco3_current = _safe_rust_float(rust_core.get("hco3_current"), hco3_current)
        desired_ph = _safe_rust_float(rust_core.get("desired_ph"), desired_ph)
        ratio_target = _safe_rust_float(rust_core.get("ratio_target"), ratio_target)
        co2_for_ratio = _safe_rust_float(rust_core.get("co2_for_ratio"), co2_for_ratio)
        co2_for_naoh = _safe_rust_float(rust_core.get("co2_for_naoh"), co2_for_naoh)
        total_extra_mol = _safe_rust_float(rust_core.get("total_extra_mol"), total_extra_mol)
        total_extra_g = _safe_rust_float(rust_core.get("total_extra_g"), total_extra_g)
        predicted_ph = _safe_rust_float(rust_core.get("predicted_ph"), float("nan"))
        slider_max_g = _safe_rust_float(rust_core.get("slider_max_g"), slider_max_g)
        eq_constants = (
            _safe_rust_float(rust_core.get("eq_ka1"), eq_constants[0]),
            _safe_rust_float(rust_core.get("eq_ka2"), eq_constants[1]),
            _safe_rust_float(rust_core.get("eq_kw"), eq_constants[2]),
        )
        raw_curve = rust_core.get("simulation_curve", [])
        if isinstance(raw_curve, Sequence):
            # Validate each row before trusting extension output for downstream UI.
            for row in raw_curve:
                if not isinstance(row, Mapping):
                    continue
                simulation_curve.append(
                    {
                        "delta_g": _safe_rust_float(row.get("delta_g"), 0.0),
                        "total_co2_g": _safe_rust_float(
                            row.get("total_co2_g"), co2_charged_g
                        ),
                        "ph": _safe_rust_float(row.get("ph"), float("nan")),
                        "na2co3_mol": _safe_rust_float(row.get("na2co3_mol"), 0.0),
                        "nahco3_mol": _safe_rust_float(row.get("nahco3_mol"), 0.0),
                    }
                )
        ratio_estimate = (
            10 ** (measurement_value - pka2_value)
            if measurement_value is not None
            else None
        )

    if not simulation_curve or not math.isfinite(predicted_ph):
        ledger = {
            "naoh_initial_mol": naoh_mol,
            "co2_added_mol": co2_mol,
            "co2_stage1_mol": stage1_co2,
            "co2_stage2_mol": stage2_co2,
            "naoh_remaining_mol": naoh_after_stage1,
            "na2co3_mol": na2co3_remaining,
            "nahco3_mol": nahco3_produced,
            "co2_excess_mol": co2_excess,
            "buffer_carbon_mol": buffer_carbon,
        }
        predicted_after = _simulate_reaction_state(
            ledger,
            total_extra_mol,
            pka2_value,
            solution_volume_l=solution_volume_l,
            temperature_c=temperature_c,
            ionic_strength_cap=ionic_strength_cap,
            use_temp_adjusted_constants=use_temp_adjusted_constants,
            initial_ph_guess=initial_guess,
            constants=eq_constants,
        )
        predicted_ph = predicted_after["ph"]
        slider_max_g = max(total_extra_g * 1.6, 2.0)
        simulation_curve = []
        step_guess = initial_guess
        steps = 12
        # Iterate over the configured range to apply the per-item logic.
        for idx in range(steps + 1):
            delta_g = slider_max_g * (idx / steps)
            delta_mol = delta_g / SOL_MW_CO2
            state = _simulate_reaction_state(
                ledger,
                delta_mol,
                pka2_value,
                solution_volume_l=solution_volume_l,
                temperature_c=temperature_c,
                ionic_strength_cap=ionic_strength_cap,
                use_temp_adjusted_constants=use_temp_adjusted_constants,
                initial_ph_guess=step_guess,
                constants=eq_constants,
            )
            step_guess = state.get("ph", step_guess)
            simulation_curve.append(
                {
                    "delta_g": delta_g,
                    "total_co2_g": co2_charged_g + delta_g,
                    "ph": state["ph"],
                    "na2co3_mol": state["na2co3_mol"],
                    "nahco3_mol": state["nahco3_mol"],
                }
            )

    ledger = {
        "naoh_initial_mol": naoh_mol,
        "co2_added_mol": co2_mol,
        "co2_stage1_mol": stage1_co2,
        "co2_stage2_mol": stage2_co2,
        "naoh_remaining_mol": naoh_after_stage1,
        "na2co3_mol": na2co3_remaining,
        "nahco3_mol": nahco3_produced,
        "co2_excess_mol": co2_excess,
        "buffer_carbon_mol": buffer_carbon,
    }

    warnings: List[str] = []
    notes: List[str] = []
    if measurement_value is None:
        warnings.append("No measured pH provided; relying on ledger ratios.")
    elif measurement_value <= desired_ph + 0.02:
        warnings.append(
            f"{measurement_label or 'Measurement'} ({measurement_value:.2f}) is already near the target pH."
        )
    if naoh_after_stage1 > 1e-4:
        warnings.append("Residual NaOH detected; neutralize remaining caustic first.")
    if solution_volume_l and solution_volume_l > 0:
        notes.append(f"Reaction volume basis: {solution_volume_l:.2f} L.")
    if co2_excess > 0:
        notes.append("Carbon ledger includes dissolved CO2 beyond solid conversions.")
    if ratio_estimate is not None:
        label = measurement_label or "Measured pH"
        notes.append(
            f"{label} implies [CO3]/[HCO3] ≈ {ratio_estimate:.3f} "
            "(>1 carbonate-rich buffer, <1 bicarbonate-rich)."
        )

    measurement_point = {
        "label": measurement_label or "Estimated pH",
        "ph": (
            measurement_value
            if measurement_value is not None
            else pka2_value
            + math.log10(max(co3_current / max(hco3_current, 1e-12), 1e-12))
        ),
        "co2_g": co2_charged_g,
    }

    math_lines = [
        f"n(NaOH) = {naoh_mass_g:.2f} g / {SOL_MW_NAOH:.3f} g/mol = {naoh_mol:.4f} mol",
        f"n(CO2) fed = {co2_charged_g:.2f} g / {SOL_MW_CO2:.4f} g/mol = {co2_mol:.4f} mol",
        f"Stage 1 (2 NaOH + CO2 -> Na2CO3): {stage1_co2:.4f} mol Na2CO3 generated",
        f"Stage 2 (Na2CO3 + CO2 -> 2 NaHCO3): {stage2_co2:.4f} mol converted",
        f"Residuals -> NaOH {naoh_after_stage1:.4e} mol, Na2CO3 {na2co3_remaining:.4f} mol, NaHCO3 {nahco3_produced:.4f} mol",
        f"Henderson-Hasselbalch with pKa2 = {pka2_value:.3f} informs CO3/HCO3 ratios.",
        f"CO2 for ratio shift = {co2_for_ratio:.4f} mol; for NaOH neutralization = {co2_for_naoh:.4f} mol",
        f"Total CO2 recommendation = {total_extra_mol:.4f} mol ({total_extra_g:.2f} g)",
    ]

    summary_lines = [
        f"Initial NaOH charge: {naoh_mass_g:.1f} g ({naoh_mol:.4f} mol)",
        f"CO2 absorbed to date: {co2_charged_g:.1f} g ({co2_mol:.4f} mol)",
        f"Ledger -> Na2CO3 {na2co3_remaining:.4f} mol, NaHCO3 {nahco3_produced:.4f} mol, dissolved CO2 {co2_excess:.4f} mol",
    ]
    if total_extra_g <= 0.02:
        summary_lines.append(
            f"System already meets the target pH ~= {desired_ph:.2f}; monitor for drift."
        )
    else:
        summary_lines.append(
            f"Add {total_extra_g:.2f} g CO2 ({total_extra_mol:.4f} mol) to approach pH {desired_ph:.2f} "
            f"(predicted ~= {predicted_ph:.2f})."
        )

    if math_logger:
        _log_co2_dosing_math(
            math_logger,
            naoh_mass_g=naoh_mass_g,
            naoh_mol=naoh_mol,
            co2_mass_g=co2_charged_g,
            co2_mol=co2_mol,
            stage1_co2=stage1_co2,
            stage2_co2=stage2_co2,
            na2co3_from_stage1=na2co3_from_stage1,
            naoh_after_stage1=naoh_after_stage1,
            na2co3_remaining=na2co3_remaining,
            nahco3_produced=nahco3_produced,
            co2_excess=co2_excess,
            co2_after_stage1=co2_after_stage1,
            co3_current=co3_current,
            hco3_current=hco3_current,
            measurement_label=measurement_label,
            measurement_value=measurement_value,
            ratio_estimate=ratio_estimate,
            pka2_value=pka2_value,
            desired_ph=desired_ph,
            ratio_target=ratio_target,
            co2_for_ratio=co2_for_ratio,
            co2_for_naoh=co2_for_naoh,
            total_extra_mol=total_extra_mol,
            total_extra_g=total_extra_g,
        )
        math_logger.extend_lines("CO2 Dosing", math_lines)

    return {
        "summary": "\n".join(summary_lines),
        "warnings": warnings,
        "notes": notes,
        "math_lines": math_lines,
        "ledger": ledger,
        "measurement": {
            "label": measurement_label or "Estimated pH",
            "value": measurement_value,
        },
        "target_ph": desired_ph,
        "recommended_co2_g": total_extra_g,
        "recommended_co2_mol": total_extra_mol,
        "predicted_ph_after": predicted_ph,
        "slider_max_g": slider_max_g,
        "base_co2_g": co2_charged_g,
        "simulation_curve": simulation_curve,
        "pka2": pka2_value,
        "measurement_point": measurement_point,
        "equilibrium_constants": {
            "ka1": eq_constants[0],
            "ka2": eq_constants[1],
            "kw": eq_constants[2],
        },
        "delta_components": {
            "neutralize_naoh_mol": co2_for_naoh,
            "carbonate_conversion_mol": co2_for_ratio,
        },
        "evaluation": {
            "ledger": ledger,
            "pka2": pka2_value,
            "base_co2_g": co2_charged_g,
            "volume_l": solution_volume_l,
            "temperature_c": temperature_c,
            "ionic_strength_cap": ionic_strength_cap,
            "use_temp_adjusted_constants": use_temp_adjusted_constants,
            "constants": eq_constants,
            "initial_ph_guess": predicted_ph,
        },
        "solution_volume_l": solution_volume_l,
        "temperature_c": temperature_c,
        "ionic_strength_cap": ionic_strength_cap,
        "use_temp_adjusted_constants": use_temp_adjusted_constants,
    }


def analyze_contaminated_bicarb_diagnostic(
    *,
    params: SolubilityInputs,
    result: SolubilitySpeciationResult,
    forced_result: Optional[SolubilitySpeciationResult],
    diagnostic: Optional[Dict[str, Any]],
    math_logger: Optional[SolubilityMathLogger] = None,
) -> Optional[Dict[str, Any]]:
    """Analyze contaminated bicarb diagnostic.
    Used to produce contaminated bicarb diagnostic diagnostics or summaries."""
    if not diagnostic:
        return None
    dried_ph = diagnostic.get("dried_ph")
    slurry_ph = diagnostic.get("slurry_ph")
    target_ph = diagnostic.get("target_ph") or 8.0
    sample_mass = diagnostic.get("sample_mass_g") or params.mass_na_hco3_g
    assumed_water = diagnostic.get("assumed_water_mass_g")
    used_slurry = slurry_ph is not None
    measured_alk = diagnostic.get("slurry_alk_meq_l")
    degas_fraction = diagnostic.get("degassed_fraction") or 0.0
    measurement_label = (
        "Atmospheric slurry pH" if slurry_ph is not None else "Dried sample pH"
    )
    measurement_value = (
        float(slurry_ph)
        if slurry_ph is not None
        else (float(dried_ph) if dried_ph is not None else result.ph)
    )
    volume = max(params.volume_l(), 1e-9)
    carbonate_moles = max(result.moles.get("CO3^2-", 0.0), 0.0)
    neutralize_mol = max(0.0, carbonate_moles)
    neutralize_g = neutralize_mol * SOL_MW_CO2
    current_total_mol = max(result.total_carbon_m, 0.0) * volume
    target_total_mol = current_total_mol
    predicted_ph = result.ph
    if forced_result is not None:
        target_total_mol = max(forced_result.total_carbon_m, 0.0) * volume
        predicted_ph = forced_result.ph
    total_needed_mol = max(0.0, target_total_mol - current_total_mol)
    neutralize_mol = min(neutralize_mol, total_needed_mol)
    polish_mol = max(0.0, total_needed_mol - neutralize_mol)
    total_needed_g = total_needed_mol * SOL_MW_CO2
    polish_g = polish_mol * SOL_MW_CO2
    sample_line = f"Sample mass evaluated: {sample_mass:.3f} g"
    if assumed_water:
        sample_line += f"; assumed {assumed_water:.1f} g water for dissolution"
    elif used_slurry:
        sample_line += "; slurry pH measured at atmosphere"
    summary_lines = [
        sample_line,
        f"{measurement_label}: {measurement_value:.2f} pH",
        f"Total CO2 recommendation: {total_needed_g:.2f} g -> predicted pH {predicted_ph:.2f}",
    ]
    warnings: List[str] = []
    notes: List[str] = []
    if forced_result is None:
        warnings.append("Forced pH calculation unavailable; slider preview disabled.")
    if slurry_ph is None:
        notes.append(
            "No slurry pH provided; dried-sample pH was used for the diagnostic seed."
        )
    else:
        notes.append(
            "Slurry pH measurement supplied at standard atmospheric conditions."
        )
    if measured_alk:
        notes.append(f"Measured slurry alkalinity = {measured_alk:.1f} meq/L.")
    if assumed_water:
        notes.append(
            f"Water basis auto-assumed at {assumed_water:.1f} g to dissolve the dried sample."
        )
    if degas_fraction:
        notes.append(
            f"Solver assumed {degas_fraction*100:.1f}% inorganic carbon vented prior to measurement."
        )
    notes.append(
        "Charge neutrality is solved implicitly; review the charge residual warning if it deviates from zero."
    )
    simulation_curve = [
        {"total_co2_g": 0.0, "ph": result.ph},
        {"total_co2_g": total_needed_g, "ph": predicted_ph},
    ]
    slider_max_g = max(total_needed_g * 1.5, 1.0) if total_needed_g > 0 else 0.0
    measurement_point = {
        "label": measurement_label,
        "ph": measurement_value,
        "co2_g": 0.0,
    }
    math_lines = [
        f"Sample mass = {sample_mass:.3f} g",
        f"Measurement ({measurement_label}) = {measurement_value:.2f} pH",
        f"Neutralize carbonate: {neutralize_mol:.4f} mol CO2 ({neutralize_g:.2f} g)",
        f"Polish to pH {target_ph:.2f}: {polish_mol:.4f} mol CO2 ({polish_g:.2f} g)",
        f"Total CO2 addition = {total_needed_mol:.4f} mol ({total_needed_g:.2f} g)",
    ]
    if math_logger:
        section = "Contaminated NaHCO3 Diagnostic"
        math_logger.extend_lines(section, math_lines)
    return {
        "summary": "\n".join(summary_lines),
        "warnings": warnings,
        "notes": notes,
        "math_lines": math_lines,
        "measurement": {"label": measurement_label, "value": measurement_value},
        "target_ph": target_ph,
        "recommended_co2_g": total_needed_g,
        "recommended_co2_mol": total_needed_mol,
        "predicted_ph_after": predicted_ph,
        "slider_max_g": slider_max_g,
        "base_co2_g": 0.0,
        "simulation_curve": simulation_curve if slider_max_g > 0 else [],
        "measurement_point": measurement_point,
        "delta_components": {
            "neutralize_naoh_mol": 0.0,
            "carbonate_conversion_mol": neutralize_mol,
            "polish_to_target_mol": polish_mol,
        },
        "evaluation": None,
        "sample_mass_g": sample_mass,
        "assumed_water_mass_g": assumed_water,
        "used_slurry": used_slurry,
    }


def _reprocessing_charge_basis(
    params: SolubilityInputs, measured_alk_meq: Optional[float]
) -> Tuple[float, str]:
    """Perform reprocessing charge basis.
    Used to keep the workflow logic localized and testable."""
    if measured_alk_meq is not None:
        try:
            alk = float(measured_alk_meq)
            if math.isfinite(alk) and alk > 0:
                return alk / 1000.0, "measured slurry alkalinity"
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
    try:
        basis = max(params.sodium_concentration(), 0.0)
    except Exception:
        basis = 0.0
    return basis, "sodium charge balance"


def _reprocessing_speciation_from_ph(
    params: SolubilityInputs,
    ph: float,
    *,
    constants: Optional[Tuple[float, float, float, List[str]]] = None,
    charge_basis_m: Optional[float] = None,
    measured_alk_meq: Optional[float] = None,
    math_logger: Optional[SolubilityMathLogger] = None,
    math_section: str = "Reprocessing equilibrium",
    basis_label: Optional[str] = None,
) -> Tuple[SolubilitySpeciationResult, float]:
    """Perform reprocessing speciation from pH.
    Used to keep the workflow logic localized and testable."""
    if ph is None or not math.isfinite(ph):
        raise ValueError("Reprocessing speciation requires a finite pH value.")
    resolved_constants = (
        constants
        if constants is not None
        else _resolve_solubility_constants(
            params, math_logger=math_logger, section=math_section
        )
    )
    basis_m, resolved_basis_label = _reprocessing_charge_basis(params, measured_alk_meq)
    if charge_basis_m is not None:
        basis_m = max(charge_basis_m, 0.0)
    if basis_label:
        resolved_basis_label = basis_label
    spec_params = replace(params, speciation_mode=SPEC_MODE_FIXED_PCO2)
    try:
        volume_l = spec_params.volume_l()
    except Exception:
        volume_l = 0.0
    if volume_l > 0 and basis_m > 0:
        sodium_mol = basis_m * volume_l
        spec_params = replace(spec_params, mass_na_hco3_g=sodium_mol * SOL_MW_NAHCO3)
    spec = solubility_speciation_at_forced_ph(
        spec_params,
        ph,
        constants=resolved_constants,
        math_logger=math_logger,
        math_section=math_section,
        model_options=ModelOptions(
            override_ionic_strength_cap=spec_params.ionic_strength_cap
        ),
    )
    if math_logger:
        math_logger.extend_lines(
            math_section,
            [
                f"Charge basis ({resolved_basis_label}) = {basis_m:.6f} M",
                "Open-system, fixed-pCO2 equilibrium enforced for reprocessing.",
            ],
        )
    return spec, max(spec.total_carbon_m, 0.0)


def _apply_measured_headspace(
    params: SolubilityInputs,
    measured_headspace_pco2_atm: Optional[float],
) -> SolubilityInputs:
    """Apply measured headspace.
    Used to apply measured headspace changes to live state."""
    if (
        measured_headspace_pco2_atm is None
        or not math.isfinite(measured_headspace_pco2_atm)
        or measured_headspace_pco2_atm <= 0
    ):
        return params
    kh_value = params.headspace_kh_m_per_atm
    if kh_value is None or not math.isfinite(kh_value) or kh_value <= 0:
        kh_value = 0.033
    return replace(
        params,
        headspace_pco2_atm=measured_headspace_pco2_atm,
        headspace_kh_m_per_atm=kh_value,
    )


def simulate_reprocessing_co2_demand(
    *,
    params: SolubilityInputs,
    initial_spec: SolubilitySpeciationResult,
    target_ph: Optional[float],
    math_logger: Optional[SolubilityMathLogger] = None,
    carbonates_to_neutralize_mol: Optional[float] = None,
    failing_ph: Optional[float] = None,
    measured_alk_meq: Optional[float] = None,
    measured_headspace_pco2_atm: Optional[float] = None,
    charge_basis_m: Optional[float] = None,
    basis_label: Optional[str] = None,
    constants: Optional[Tuple[float, float, float, List[str]]] = None,
    ph_tolerance: float = 1e-3,
) -> Dict[str, Any]:
    """Perform simulate reprocessing CO2 demand.
    Used to keep the workflow logic localized and testable."""

    volume = max(params.volume_l(), 1e-9)
    if target_ph is None or not math.isfinite(target_ph):
        return {
            "initial_ph": initial_spec.ph,
            "initial_total_carbon_m": initial_spec.total_carbon_m,
            "target_total_carbon_m": initial_spec.total_carbon_m,
            "added_co2_mol": carbonates_to_neutralize_mol or 0.0,
            "added_co2_g": (carbonates_to_neutralize_mol or 0.0) * SOL_MW_CO2,
            "target_ph": initial_spec.ph,
            "target_spec": initial_spec,
            "limit_reached": False,
            "target_ph_error": 0.0,
            "neutralize_mol": carbonates_to_neutralize_mol or 0.0,
            "polish_mol": 0.0,
        }

    basis_m, basis_origin = _reprocessing_charge_basis(params, measured_alk_meq)
    if basis_label:
        basis_origin = basis_label
    constants = (
        constants
        if constants is not None
        else _resolve_solubility_constants(
            params, math_logger=math_logger, section="Reprocessing equilibrium"
        )
    )

    carbonate_moles = max(
        (
            carbonates_to_neutralize_mol
            if carbonates_to_neutralize_mol is not None
            else initial_spec.moles.get("CO3^2-", 0.0)
        ),
        0.0,
    )
    neutralize_mol = carbonate_moles
    baseline_spec = initial_spec
    baseline_carbon = max(initial_spec.total_carbon_m, 0.0)
    initial_ph = (
        failing_ph
        if failing_ph is not None and math.isfinite(failing_ph)
        else initial_spec.ph
    )
    try:
        if initial_ph is not None and math.isfinite(initial_ph):
            baseline_spec, baseline_carbon = _reprocessing_speciation_from_ph(
                params,
                initial_ph,
                constants=constants,
                charge_basis_m=basis_m,
                measured_alk_meq=measured_alk_meq,
                math_logger=math_logger,
                math_section="Reprocessing baseline speciation",
                basis_label=basis_origin,
            )
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass

    if math_logger and neutralize_mol > 0:
        math_logger.log(
            "Reprocessing workflow",
            "Neutralize carbonate",
            f"CO2 needed = {neutralize_mol:.4f} mol",
            f"{neutralize_mol * SOL_MW_CO2:.2f}",
            units="g",
        )

    try:
        target_spec, target_carbon = _reprocessing_speciation_from_ph(
            params,
            target_ph,
            constants=constants,
            charge_basis_m=basis_m,
            measured_alk_meq=measured_alk_meq,
            math_logger=math_logger,
            math_section="Reprocessing target speciation",
            basis_label=basis_origin,
        )
    except Exception:
        target_spec = baseline_spec
        target_carbon = baseline_carbon

    delta_total = max(0.0, target_carbon - baseline_carbon)
    added_moles = max(delta_total * volume, neutralize_mol)
    polish_mol = max(0.0, added_moles - neutralize_mol)
    final_ph = (
        target_spec.ph
        if target_spec.ph is not None and math.isfinite(target_spec.ph)
        else target_ph
    )
    target_error = (final_ph - target_ph) if final_ph is not None else None
    limit_reached = (
        target_carbon <= 0.0
        or basis_m <= 0.0
        or (target_error is not None and abs(target_error) > ph_tolerance)
    )
    return {
        "initial_ph": initial_ph,
        "initial_total_carbon_m": baseline_carbon,
        "target_total_carbon_m": target_carbon,
        "added_co2_mol": added_moles,
        "added_co2_g": added_moles * SOL_MW_CO2,
        "target_ph": final_ph,
        "target_spec": target_spec,
        "limit_reached": limit_reached,
        "target_ph_error": target_error,
        "neutralize_mol": neutralize_mol,
        "polish_mol": polish_mol,
    }


def analyze_reprocessing_workflow(
    *,
    params: SolubilityInputs,
    result: SolubilitySpeciationResult,
    forced_result: Optional[SolubilitySpeciationResult],
    failing_ph: Optional[float],
    forced_ph: Optional[float],
    solvent_basis: Optional[str],
    solvent_basis_value: Optional[float],
    diagnostic_data: Optional[Dict[str, Any]] = None,
    math_logger: Optional[SolubilityMathLogger] = None,
    model_options: Optional[ModelOptions] = None,
    measured_headspace_pco2_atm: Optional[float] = None,
    measured_headspace_pressure_psi: Optional[float] = None,
) -> Optional[Dict[str, Any]]:
    """Analyze reprocessing workflow.
    Used to produce reprocessing workflow diagnostics or summaries."""
    if failing_ph is None:
        return None
    baseline_spec = result
    baseline_carbon = max(baseline_spec.total_carbon_m, 0.0)
    warnings: List[str] = []
    constants: Optional[Tuple[float, float, float, List[str]]] = None
    measured_alk_meq = None
    if diagnostic_data:
        measured_alk_meq = diagnostic_data.get("slurry_alk_meq_l")
    params = _apply_measured_headspace(params, measured_headspace_pco2_atm)
    basis_m, basis_label = _reprocessing_charge_basis(params, measured_alk_meq)
    try:
        constants = _resolve_solubility_constants(
            params, math_logger=math_logger, section="Reprocessing baseline"
        )
        baseline_spec, baseline_carbon = _reprocessing_speciation_from_ph(
            params,
            failing_ph,
            constants=constants,
            charge_basis_m=basis_m,
            measured_alk_meq=measured_alk_meq,
            math_logger=math_logger,
            math_section="Reprocessing baseline speciation",
            basis_label=basis_label,
        )
    except Exception as exc:
        warnings.append(
            f"Baseline speciation at failing pH fell back to the measured run: {exc}"
        )
        baseline_spec = result
        baseline_carbon = max(baseline_spec.total_carbon_m, 0.0)
    try:
        volume = max(params.volume_l(), 1e-9)
    except Exception:
        volume = max(params.solution_volume_l or 1e-9, 1e-9)
    current_total_mol = baseline_carbon * volume
    target_ph_value = (
        forced_ph
        if forced_ph is not None
        else (forced_result.ph if forced_result is not None else None)
    )
    carbonate_moles = max(baseline_spec.moles.get("CO3^2-", 0.0), 0.0)
    target_state = simulate_reprocessing_co2_demand(
        params=params,
        initial_spec=baseline_spec,
        target_ph=target_ph_value,
        math_logger=math_logger,
        carbonates_to_neutralize_mol=carbonate_moles,
        failing_ph=failing_ph,
        measured_alk_meq=measured_alk_meq,
        charge_basis_m=basis_m,
        basis_label=basis_label,
        constants=constants,
        measured_headspace_pco2_atm=measured_headspace_pco2_atm,
    )
    total_needed_mol = max(0.0, target_state.get("added_co2_mol", 0.0))
    total_needed_g = max(0.0, target_state.get("added_co2_g", 0.0))
    predicted_ph = target_state.get("target_ph") or result.ph
    target_total_mol = target_state.get("target_total_carbon_m", 0.0) * volume
    frac = baseline_spec.fractional_carbon
    hco3_pct = frac.get("HCO3-", 0.0) * 100.0
    co3_pct = frac.get("CO3^2-", 0.0) * 100.0
    h2co3_pct = frac.get("H2CO3", 0.0) * 100.0
    if solvent_basis == "water_mass" and solvent_basis_value is not None:
        solvent_summary = f"{solvent_basis_value:.1f} g water"
    elif solvent_basis == "solution_volume" and solvent_basis_value is not None:
        solvent_summary = f"{solvent_basis_value:.2f} L liquor"
    else:
        solvent_summary = f"{volume:.2f} L liquor"
    summary_lines = [
        f"{params.mass_na_hco3_g:.1f} g NaHCO3 in {solvent_summary}.",
        f"Failing slurry pH: {failing_ph:.2f}.",
        f"Speciation at failing pH: HCO3- {hco3_pct:.1f}%, CO3^2- {co3_pct:.1f}%, H2CO3 {h2co3_pct:.1f}%.",
        (
            f"CO2 needed for pH {target_ph_value:.2f}: {total_needed_g:.2f} g ({total_needed_mol:.4f} mol)."
            if target_ph_value is not None
            else f"CO2 delta: {total_needed_g:.2f} g ({total_needed_mol:.4f} mol)."
        ),
        f"Predicted pH after dosing: {predicted_ph:.2f}.",
    ]
    warnings.append("No NaOH basis; carbonate inferred from failing pH measurement.")
    warnings.append(f"Solvent basis assumed: {solvent_summary}.")
    if total_needed_g <= 0:
        warnings.append(
            "Current speciation already meets or exceeds the target pH; no extra CO2 required."
        )
    if target_state.get("limit_reached"):
        warnings.append(
            "Target pH may require more CO2 than the modeled inventory allows; treat the guidance as a minimum."
        )
    if forced_result is None:
        warnings.append("Slider preview unavailable; forced-pH result not computed.")
    notes: List[str] = []
    notes.append(
        f"Reprocessing charge basis: {basis_label} ({basis_m*1000:.2f} meq/L)."
    )
    measurement_note: Optional[str] = None
    if (
        measured_headspace_pressure_psi is not None
        and measured_headspace_pco2_atm is not None
    ):
        measurement_note = (
            f"Headspace measurement: {measured_headspace_pressure_psi:.2f} PSI "
            f"(~{measured_headspace_pco2_atm:.3f} atm pCO₂)."
        )
    elif measured_headspace_pco2_atm is not None:
        measurement_note = (
            f"Headspace pCO₂ anchored to {measured_headspace_pco2_atm:.3f} atm."
        )
    if measurement_note:
        notes.append(measurement_note)
    math_lines = [
        f"Total dissolved carbon (current) = {current_total_mol:.4f} mol",
        f"Total dissolved carbon (target) = {target_total_mol:.4f} mol",
        f"Additional CO2 needed = {total_needed_mol:.4f} mol ({total_needed_g:.2f} g)",
    ]
    if math_logger:
        math_logger.extend_lines("Reprocessing workflow", math_lines)
    neutralize_mol = max(target_state.get("neutralize_mol", carbonate_moles), 0.0)
    polish_mol = max(
        target_state.get("polish_mol", total_needed_mol - neutralize_mol), 0.0
    )
    measurement_point = {
        "label": "Reprocessing measurement",
        "ph": baseline_spec.ph,
        "co2_g": 0.0,
    }
    simulation_curve = [
        {"total_co2_g": 0.0, "ph": baseline_spec.ph},
        {"total_co2_g": total_needed_g, "ph": predicted_ph},
    ]
    slider_max_g = max(total_needed_g * 1.5, 1.0) if total_needed_g > 0 else 0.0
    return {
        "summary": "\n".join([line for line in summary_lines if line]),
        "warnings": warnings,
        "notes": notes,
        "math_lines": math_lines,
        "target_ph": target_ph_value,
        "recommended_co2_g": total_needed_g,
        "recommended_co2_mol": total_needed_mol,
        "predicted_ph_after": predicted_ph,
        "volume_l": volume,
        "solvent_basis": solvent_basis,
        "solvent_basis_value": solvent_basis_value,
        "failing_ph": failing_ph,
        "hco3_pct": hco3_pct,
        "co3_pct": co3_pct,
        "h2co3_pct": h2co3_pct,
        "measurement_point": measurement_point,
        "baseline_spec": baseline_spec,
        "baseline_carbon_m": baseline_carbon,
        "simulation_curve": simulation_curve if slider_max_g > 0 else [],
        "slider_max_g": slider_max_g,
        "delta_components": {
            "neutralize_mol": neutralize_mol,
            "polish_mol": polish_mol,
        },
        "target_spec": target_state.get("target_spec"),
        "dissolved_limit_moles": total_needed_mol,
        "limit_reached": target_state.get("limit_reached"),
        "target_ph_error": target_state.get("target_ph_error"),
    }


def format_solubility_summary(
    params: SolubilityInputs,
    result: SolubilitySpeciationResult,
    forced_result: Optional[SolubilitySpeciationResult] = None,
    forced_error: Optional[str] = None,
    sweep_summary: Optional[List[Dict[str, float]]] = None,
    sensitivity_rows: Optional[List[Dict[str, Any]]] = None,
    mode_context: Optional[Dict[str, str]] = None,
) -> str:
    """Format solubility summary.
    Used to prepare solubility summary for display or export."""
    volume = params.volume_l()
    lines = [
        "=== Advanced Sodium Bicarbonate Speciation ===",
        f"Mass NaHCO3          : {params.mass_na_hco3_g:.4f} g",
    ]
    if result.dissolved_mass_na_hco3_g is not None:
        lines.append(f"Dissolved NaHCO3      : {result.dissolved_mass_na_hco3_g:.4f} g")
    if result.undissolved_mass_na_hco3_g is not None:
        lines.append(
            f"Undissolved NaHCO3    : {result.undissolved_mass_na_hco3_g:.4f} g"
        )
    if mode_context:
        label = mode_context.get("label")
        if label:
            lines.append(f"Simulation basis     : {label}")
        starting = mode_context.get("starting")
        if starting:
            lines.append(f"Starting point       : {starting}")
        goal = mode_context.get("goal")
        if goal:
            lines.append(f"Solver goal          : {goal}")
        assumption = mode_context.get("assumption")
        if assumption:
            lines.append(f"Key assumption       : {assumption}")
        lines.append("")
    if params.water_mass_g is not None:
        lines.append(f"Water mass           : {params.water_mass_g:.4f} g")
    if params.solution_volume_l is not None:
        lines.append(f"User volume          : {params.solution_volume_l:.4f} L")
    if params.headspace_pco2_atm is not None:
        lines.append(f"Headspace CO2        : {params.headspace_pco2_atm:.2e} atm")
    temp_note = (
        "temperature-adjusted constants"
        if params.use_temperature_adjusted_constants
        else "constants fixed at 25 C"
    )
    lines.extend(
        [
            f"Resolved volume      : {volume:.6f} L",
            f"Temperature          : {params.temperature_c:.2f} deg C ({temp_note})",
            f"Initial pH guess     : {params.initial_ph_guess:.2f}",
            (
                f"Forced pH target     : {params.forced_ph_target:.2f}"
                if params.forced_ph_target is not None
                else "Forced pH target     : not specified"
            ),
            "",
        ]
    )

    def render_block(title: str, spec: SolubilitySpeciationResult) -> None:
        """Render block.
        Used to draw block for preview or export workflows."""
        lines.extend(
            [
                f"--- {title} ---",
                f"pH                   : {spec.ph:.4f}",
                f"Ionic strength (I)   : {spec.ionic_strength:.6e} M",
            ]
        )
        total_carbon = spec.total_carbon_m
        lines.append(
            "Total inorganic C    : "
            f"{total_carbon:.6e} mol/L (target {params.total_carbon_with_headspace():.6e} mol/L)"
        )
        lines.append(f"Alkalinity           : {spec.alkalinity_meq_per_l:.2f} meq/L")
        if spec.dissolved_fraction is not None:
            lines.append(
                "Dissolved fraction    : "
                f"{spec.dissolved_fraction*100:.2f}% of charged NaHCO3"
            )
        if spec.warnings:
            lines.append("Warnings             :")
            # Iterate over spec.warnings to apply the per-item logic.
            for warn in spec.warnings:
                lines.append(f"  - {warn}")
        lines.extend(
            [
                "",
                "Carbon speciation (% of inorganic C):",
            ]
        )
        # Iterate over ("H2CO3", "HCO3-", "CO3^2-") to apply the per-item logic.
        for species in ("H2CO3", "HCO3-", "CO3^2-"):
            frac = spec.fractional_carbon.get(species, 0.0) * 100.0
            lines.append(f"  {species:<6s}: {frac:6.2f}%")
        lines.extend(
            [
                "",
                "Species concentrations, mass loading, and moles:",
                f"{'Species':<10s}{'[C] / M':>16s}{'g/L':>12s}{'n / mol':>16s}{'gamma':>10s}",
                "-" * 66,
            ]
        )
        ordered = ["Na+", "H+", "HCO3-", "CO3^2-", "H2CO3", "OH-"]
        # Iterate over ordered to apply the per-item logic.
        for species in ordered:
            conc = spec.concentrations_m.get(species, 0.0)
            moles_val = spec.moles.get(species, 0.0)
            mass_g_l = spec.mass_concentrations_g_per_l.get(species, 0.0)
            gamma = spec.activity_coefficients.get(species, 1.0)
            lines.append(
                f"{species:<10s}{conc:>16.6e}{mass_g_l:>12.6e}{moles_val:>16.6e}{gamma:>10.4f}"
            )
        lines.extend(["", "Saturation indices (ionic product / Ksp):"])
        # Iterate over items from spec.saturation_indices to apply the per-item logic.
        for salt, ratio in spec.saturation_indices.items():
            flag = " > 1 (supersaturated)" if ratio > 1.0 else ""
            lines.append(f"{salt:<10s}{ratio:>16.6f}{flag}")
        left_charge = spec.concentrations_m["Na+"] + spec.concentrations_m["H+"]
        right_charge = (
            spec.concentrations_m["HCO3-"]
            + 2.0 * spec.concentrations_m["CO3^2-"]
            + spec.concentrations_m["OH-"]
        )
        lines.append(
            f"\nCharge balance residual : {left_charge - right_charge:+.3e} mol/L"
        )
        lines.append("")

    render_block("Equilibrium solution", result)

    if forced_result is not None:
        render_block(
            f"Speciation at user-specified pH ({forced_result.ph:.2f})",
            forced_result,
        )

    if forced_error:
        lines.extend(["", f"[warning] {forced_error}"])

    if sensitivity_rows:
        lines.extend(
            [
                "",
                "Sensitivity snapshots (perturb parameter → pH / Ionic Strength / Na2CO3 SI):",
            ]
        )
        # Iterate over sensitivity_rows to apply the per-item logic.
        for row in sensitivity_rows:
            lines.append(
                f"  {row['label']:<24s} : {row['ph']:>6} / {row['ionic_strength']:>10} / {row['na2co3_si']:>8}"
            )

    if sweep_summary:
        lines.extend(
            [
                "",
                "pH sweep (% HCO\u2083\u207b / % CO\u2083\u00b2\u207b / % H\u2082CO\u2083):",
            ]
        )
        # Iterate over sweep_summary to apply the per-item logic.
        for row in sweep_summary:
            lines.append(
                f"  pH {row['ph']:>4.2f} : {row['hco3_pct']:>6.2f}% / "
                f"{row['co3_pct']:>6.2f}% / {row['h2co3_pct']:>6.2f}%"
            )

    if result.assumptions:
        lines.extend(["", "Assumptions & notes:"])
        # Iterate over result.assumptions to apply the per-item logic.
        for note in result.assumptions:
            lines.append(f"  - {note}")

    return "\n".join(line.rstrip() for line in lines).rstrip()


def carbonate_pkw_from_temp(temp_c: float) -> float:
    """Perform carbonate pkw from temp.
    Used to keep the workflow logic localized and testable."""

    a, b, c = (20.795999999999985, -0.0639999999999997, 0.00031999999999999987)
    return a + b * temp_c + c * (temp_c**2)


def compute_carbonate_contamination(inputs: CarbonateInputs) -> CarbonateResults:
    """Compute carbonate contamination.
    Used to derive carbonate contamination for analysis or plotting."""

    mw_naoh = 39.997  # g/mol
    mw_na2co3 = 105.9888  # g/mol

    eff_mass_naoh = inputs.mass_naoh_g * (inputs.purity_wt_percent / 100.0)
    sodium_moles = eff_mass_naoh / mw_naoh

    pellet_na2co3_mass = 0.0
    pellet_na2co3_moles = 0.0
    if inputs.naoh_carbonate_wt_percent is not None:
        pellet_na2co3_mass = inputs.mass_naoh_g * (
            inputs.naoh_carbonate_wt_percent / 100.0
        )
        pellet_na2co3_moles = pellet_na2co3_mass / mw_na2co3

    ratio = 10.0 ** (inputs.ph - inputs.pka2)

    pkw = carbonate_pkw_from_temp(inputs.temp_c)
    h_conc = 10.0 ** (-inputs.ph)
    oh_conc = 10.0 ** (-(pkw - inputs.ph))

    hydrogen_moles = h_conc * inputs.final_volume_l
    hydroxide_moles = oh_conc * inputs.final_volume_l

    bicarbonate_moles = (sodium_moles + hydrogen_moles - hydroxide_moles) / (
        1.0 + 2.0 * ratio
    )
    carbonate_moles = ratio * bicarbonate_moles

    sodium_bicarbonate_moles = bicarbonate_moles
    sodium_carbonate_moles = carbonate_moles
    sodium_carbonate_mass = sodium_carbonate_moles * mw_na2co3

    return CarbonateResults(
        sodium_moles=sodium_moles,
        ratio=ratio,
        hydrogen_moles=hydrogen_moles,
        hydroxide_moles=hydroxide_moles,
        bicarbonate_moles=bicarbonate_moles,
        carbonate_moles=carbonate_moles,
        sodium_bicarbonate_moles=sodium_bicarbonate_moles,
        sodium_carbonate_moles=sodium_carbonate_moles,
        sodium_carbonate_mass_g=sodium_carbonate_mass,
        pellet_sodium_carbonate_moles=pellet_na2co3_moles,
        pellet_sodium_carbonate_mass_g=pellet_na2co3_mass,
    )


def _carbonate_speciation_at_fixed_ph(
    inputs: CarbonateInputs,
    pka2: float,
    sodium_moles_dissolved: float,
    ph_value: float,
):
    """Perform carbonate speciation at fixed pH.
    Used to keep the workflow logic localized and testable."""

    ratio = 10.0 ** (ph_value - pka2)
    pkw = carbonate_pkw_from_temp(inputs.temp_c)
    hydrogen_conc = 10.0 ** (-ph_value)
    hydroxide_conc = 10.0 ** (-(pkw - ph_value))

    hydrogen_moles = hydrogen_conc * inputs.final_volume_l
    hydroxide_moles = hydroxide_conc * inputs.final_volume_l

    denominator = 1.0 + 2.0 * ratio
    bicarbonate_moles = (
        sodium_moles_dissolved + hydrogen_moles - hydroxide_moles
    ) / denominator
    carbonate_moles = ratio * bicarbonate_moles

    return bicarbonate_moles, carbonate_moles, hydrogen_moles, hydroxide_moles


def compute_carbonate_contamination_augmented(
    inputs: CarbonateInputs, options: CarbonateEquilibriumOptions
) -> CarbonateAugmentedResults:
    """Compute carbonate contamination augmented.
    Used to derive carbonate contamination augmented for analysis or plotting."""

    baseline = compute_carbonate_contamination(inputs)

    mw_na2co3 = 105.9888  # g/mol
    mw_nahco3 = 84.0066  # g/mol

    ph_effective = options.slurry_ph if options.slurry_ph is not None else inputs.ph

    sodium_total = baseline.sodium_moles
    sodium_dissolved = sodium_total

    (
        bicarbonate_aq,
        carbonate_aq,
        _,
        _,
    ) = _carbonate_speciation_at_fixed_ph(
        inputs, inputs.pka2, sodium_dissolved, ph_effective
    )

    sodium_bicarbonate_solid = 0.0
    sodium_carbonate_solid = 0.0

    # Iterate over the configured range to apply the per-item logic.
    for iteration in range(1, options.max_iter + 1):
        precip_hco3 = 0.0
        precip_co3 = 0.0

        if options.s_hco3_max_m is not None:
            cap_hco3 = options.s_hco3_max_m * inputs.final_volume_l
            if bicarbonate_aq > cap_hco3:
                precip_hco3 = bicarbonate_aq - cap_hco3
                bicarbonate_aq = cap_hco3

        if options.s_co3_max_m is not None:
            cap_co3 = options.s_co3_max_m * inputs.final_volume_l
            if carbonate_aq > cap_co3:
                precip_co3 = carbonate_aq - cap_co3
                carbonate_aq = cap_co3

        sodium_removed = precip_hco3 + 2.0 * precip_co3
        if sodium_removed < options.tol_mol:
            iterations = iteration
            break

        sodium_bicarbonate_solid += precip_hco3
        sodium_carbonate_solid += precip_co3
        sodium_dissolved = max(sodium_dissolved - sodium_removed, 0.0)

        (
            bicarbonate_aq,
            carbonate_aq,
            _,
            _,
        ) = _carbonate_speciation_at_fixed_ph(
            inputs, inputs.pka2, sodium_dissolved, ph_effective
        )
    else:
        iterations = options.max_iter

    sodium_bicarbonate_solid_mass = sodium_bicarbonate_solid * mw_nahco3
    sodium_carbonate_solid_mass = sodium_carbonate_solid * mw_na2co3
    solid_total_mass = sodium_bicarbonate_solid_mass + sodium_carbonate_solid_mass
    solid_naco3_fraction = (
        sodium_carbonate_solid_mass / solid_total_mass if solid_total_mass > 0 else 0.0
    )

    if inputs.final_volume_l > 0:
        ratio_hco3_co2 = 10.0 ** (ph_effective - options.pka1)
        if ratio_hco3_co2 > 0:
            co2_conc = (bicarbonate_aq / inputs.final_volume_l) / ratio_hco3_co2
            co2star_moles = co2_conc * inputs.final_volume_l
        else:
            co2star_moles = 0.0
    else:
        co2star_moles = 0.0

    dic_moles = co2star_moles + bicarbonate_aq + carbonate_aq

    co2star_henry = None
    co2star_ratio = None
    if options.pco2_atm is not None and inputs.final_volume_l > 0:
        effective_kh = max(options.kh_co2_m_per_atm, 0.0)
        effective_pco2 = max(options.pco2_atm, 0.0)
        co2star_henry = effective_kh * effective_pco2 * inputs.final_volume_l
        if co2star_henry > 0.0:
            co2star_ratio = co2star_moles / co2star_henry

    return CarbonateAugmentedResults(
        baseline=baseline,
        co2star_moles=co2star_moles,
        dic_moles=dic_moles,
        co2star_henry_moles=co2star_henry,
        co2star_consistency_ratio=co2star_ratio,
        iterations=iterations,
        sodium_dissolved_moles=sodium_dissolved,
        bicarbonate_aqueous_moles=bicarbonate_aq,
        carbonate_aqueous_moles=carbonate_aq,
        sodium_bicarbonate_solid_moles=sodium_bicarbonate_solid,
        sodium_carbonate_solid_moles=sodium_carbonate_solid,
        sodium_bicarbonate_solid_mass_g=sodium_bicarbonate_solid_mass,
        sodium_carbonate_solid_mass_g=sodium_carbonate_solid_mass,
        solid_total_mass_g=solid_total_mass,
        solid_sodium_carbonate_mass_fraction=solid_naco3_fraction,
    )


def carbonate_literature_caps_stp() -> CarbonateEquilibriumOptions:
    """Perform carbonate literature caps stp.
    Used to keep the workflow logic localized and testable."""

    return CarbonateEquilibriumOptions(s_hco3_max_m=1.10, s_co3_max_m=2.00)


def _normalize_cached_cycle_markers(data):
    """Normalize cached cycle markers.
    Used to keep cached cycle markers consistent across workflows and persistence."""
    if not isinstance(data, dict):
        return None
    try:
        file_path = str(data.get("file", "")).strip()
        sheet = str(data.get("sheet", "")).strip()
        columns = data.get("columns") or {}
        x_col = columns.get("x")
        y1_col = columns.get("y1")
        data_len = int(data.get("data_len", -1))
        mask_true = data.get("mask_true")
        mask_true = int(mask_true) if mask_true is not None else None
        peaks = [int(p) for p in data.get("peaks", [])]
        troughs = [int(t) for t in data.get("troughs", [])]
        params = data.get("peak_params") or {}
        peak_prominence = float(params.get("prominence", 0.0))
        peak_distance = int(params.get("distance", 1))
        peak_width = int(params.get("width", 1))
        min_cycle_drop = float(data.get("min_cycle_drop", 0.0))
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        return None

    return {
        "file": file_path,
        "sheet": sheet,
        "columns": {"x": x_col, "y1": y1_col},
        "data_len": data_len,
        "mask_true": mask_true,
        "peaks": peaks,
        "troughs": troughs,
        "peak_params": {
            "prominence": peak_prominence,
            "distance": peak_distance,
            "width": peak_width,
        },
        "min_cycle_drop": min_cycle_drop,
        "timestamp": float(data.get("timestamp", 0.0)),
    }


def _normalize_cycle_trace_marker_state(value: Any) -> Dict[str, Any]:
    """Normalize one per-trace Cycle Analysis marker state payload.

    Purpose:
        Coerce marker indices and revision metadata into one stable schema.
    Why:
        Primary Y traces now keep independent manual and automatic marker state,
        while legacy marker arrays can still be migrated into the same structure.
    Inputs:
        value: Raw marker-state mapping from settings, profiles, or runtime state.
    Outputs:
        Dict with sorted marker-index lists and a non-negative manual revision.
    Side Effects:
        None.
    Exceptions:
        Malformed values are ignored and replaced with empty marker collections.
    """

    raw = value if isinstance(value, Mapping) else {}

    def _normalize_idx_set(raw_values: Any) -> List[int]:
        """Coerce one marker collection to sorted unique non-negative indices.

        Purpose:
            Sanitize one marker-index collection from a trace marker payload.
        Why:
            Per-trace marker stores may come from hand-edited JSON, legacy
            settings, or runtime sets, and downstream plotting expects sorted
            integer indices.
        Inputs:
            raw_values: Candidate marker collection containing index-like values.
        Outputs:
            Sorted list of unique non-negative integer indices.
        Side Effects:
            None.
        Exceptions:
            Invalid entries are skipped rather than raised.
        """
        if not isinstance(raw_values, (list, tuple, set)):
            return []
        clean: Set[int] = set()
        # Marker payloads may be hand-edited JSON, so invalid entries are skipped.
        for raw_idx in raw_values:
            try:
                idx = int(raw_idx)
            except Exception:
                continue
            if idx < 0:
                continue
            clean.add(idx)
        return sorted(clean)

    return {
        "auto_peaks": _normalize_idx_set(raw.get("auto_peaks")),
        "auto_troughs": _normalize_idx_set(raw.get("auto_troughs")),
        "add_peaks": _normalize_idx_set(raw.get("add_peaks")),
        "add_troughs": _normalize_idx_set(raw.get("add_troughs")),
        "rm_peaks": _normalize_idx_set(raw.get("rm_peaks")),
        "rm_troughs": _normalize_idx_set(raw.get("rm_troughs")),
        "manual_revision": max(0, int(_coerce_int(raw.get("manual_revision")) or 0)),
    }


def _cycle_trace_marker_state_has_markers(value: Mapping[str, Any]) -> bool:
    """Return whether a normalized per-trace marker state contains marker data.

    Purpose:
        Distinguish meaningful marker payloads from empty compatibility shells.
    Why:
        Settings/profile persistence should retain per-trace marker entries only
        when they carry automatic markers, manual edits, or a revision marker.
    Inputs:
        value: Normalized marker-state mapping.
    Outputs:
        True when any marker collection or manual revision is present.
    Side Effects:
        None.
    Exceptions:
        Missing keys are treated as empty collections.
    """

    return bool(
        value.get("auto_peaks")
        or value.get("auto_troughs")
        or value.get("add_peaks")
        or value.get("add_troughs")
        or value.get("rm_peaks")
        or value.get("rm_troughs")
        or int(value.get("manual_revision") or 0) > 0
    )


def _normalize_cycle_trace_marker_store(value: Any) -> Dict[str, Dict[str, Any]]:
    """Normalize the per-trace Cycle Analysis marker store.

    Purpose:
        Convert persisted marker stores into `{trace_key: marker_state}` mappings.
    Why:
        Cycle Analysis needs trace-isolated marker edits without breaking older
        settings files that never had this store.
    Inputs:
        value: Raw settings/profile marker-store mapping.
    Outputs:
        Dict keyed by stable trace identifiers.
    Side Effects:
        None.
    Exceptions:
        Invalid store entries are ignored.
    """

    if not isinstance(value, Mapping):
        return {}
    normalized: Dict[str, Dict[str, Any]] = {}
    for raw_key, raw_state in value.items():
        key = str(raw_key or "").strip()
        if not key:
            continue
        state = _normalize_cycle_trace_marker_state(raw_state)
        if _cycle_trace_marker_state_has_markers(state):
            normalized[key] = state
    return normalized


def _fallback_find_peaks(
    values,
    *,
    prominence: float = 0.0,
    distance: int = 1,
    width: int = 1,
):
    """Perform fallback find peaks.
    Used to keep the workflow logic localized and testable."""

    arr = np.asarray(values, dtype=float)

    if arr.size == 0:

        return np.array([], dtype=int), {}

    prom = max(float(prominence), 0.0)

    dist = max(int(distance), 1)

    def _coerce_min_width(value):
        """Coerce min width.
        Used to force min width into a safe type or range."""

        try:

            if isinstance(value, (tuple, list)):

                if len(value) == 0:

                    return 1

                candidate = float(value[0])

            elif isinstance(value, np.ndarray):

                if value.size == 0:

                    return 1

                candidate = float(value.flat[0])

            else:

                candidate = float(value)

        except Exception:

            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            return 1

        if not math.isfinite(candidate):

            return 1

        return max(int(math.ceil(candidate)), 1)

    min_width = _coerce_min_width(width)

    peaks = []

    widths = []

    last_idx = -dist

    n = arr.size

    # Iterate over the configured range to apply the per-item logic.
    for idx in range(1, n - 1):

        if idx - last_idx < dist:

            continue

        center = arr[idx]

        left = arr[idx - 1]

        right = arr[idx + 1]

        if not (np.isfinite(center) and np.isfinite(left) and np.isfinite(right)):

            continue

        if center >= left and center >= right:

            local_prom = center - min(left, right)

            if local_prom + 1e-12 >= prom:  # tolerate minor FP error

                est_width = 1

                if min_width > 1:

                    half_level = center - max(local_prom, 0.0) / 2.0

                    left_idx = idx

                    # Repeat while left_idx > 0 and arr[left_idx - 1] >= half_level to advance the looped workflow.
                    while left_idx > 0 and arr[left_idx - 1] >= half_level:

                        left_idx -= 1

                    right_idx = idx

                    # Repeat while right_idx < n - 1 and arr[right_idx + 1] >= half_level to advance the looped workflow.
                    while right_idx < n - 1 and arr[right_idx + 1] >= half_level:

                        right_idx += 1

                    est_width = right_idx - left_idx + 1

                if est_width >= min_width:

                    peaks.append(idx)

                    widths.append(est_width)

                    last_idx = idx

    props = {}

    if widths:

        props["widths"] = np.asarray(widths, dtype=float)

    return np.array(peaks, dtype=int), props


_FALLBACK_FIND_PEAKS = None if find_peaks is not None else _fallback_find_peaks


def _normalize_cycle_window(window: Any, *, allow_zero: bool = False) -> int:
    """Normalize cycle smoothing or snap window settings into safe integers.

    Purpose:
        Sanitize user-facing cycle detection and manual snap window controls.
    Why:
        These values are persisted to settings/profile payloads and are read by
        both Python fallback logic and the Rust bridge.
    Inputs:
        window: Raw window value from UI, settings, or payload state.
        allow_zero: When True, preserve `0` as an auto-window sentinel.
    Outputs:
        Integer window value, normalized to odd values when positive.
    Side Effects:
        None.
    Exceptions:
        Invalid inputs fall back to `0` or `1` based on `allow_zero`.
    """
    default_value = 0 if allow_zero else 1
    try:
        parsed = int(float(window))
    except Exception:
        parsed = default_value
    if allow_zero and parsed <= 0:
        return 0
    parsed = max(1, int(parsed))
    if parsed % 2 == 0:
        parsed += 1
    return parsed


def _smooth_cycle_series(values: np.ndarray, window: int) -> np.ndarray:
    """Return a centered moving-average series for cycle candidate search.

    Purpose:
        Build a smoothed signal used only for candidate detection.
    Why:
        Automatic detection and manual snapping should search on a less noisy
        signal while still refining final markers back to raw extrema.
    Inputs:
        values: One-dimensional finite-or-NaN numeric series.
        window: Odd centered window size; values <= 1 disable smoothing.
    Outputs:
        NumPy array of smoothed values with the same shape as `values`.
    Side Effects:
        None.
    Exceptions:
        Invalid input shapes are handled by NumPy coercion before entry.
    """
    arr = np.asarray(values, dtype=float).reshape(-1)
    normalized = _normalize_cycle_window(window)
    if arr.size == 0 or normalized <= 1:
        return arr.copy()
    half = normalized // 2
    smoothed = np.empty(arr.shape, dtype=float)
    # Centered smoothing preserves endpoint coverage without shifting candidate locations.
    for idx in range(arr.size):
        start = max(0, idx - half)
        end = min(arr.size, idx + half + 1)
        segment = arr[start:end]
        finite = segment[np.isfinite(segment)]
        smoothed[idx] = float(np.nanmean(finite)) if finite.size else float(arr[idx])
    return smoothed


def _is_cycle_local_extremum(values: np.ndarray, idx: int, *, prefer_peak: bool) -> bool:
    """Check whether one index is a strict local extremum of the requested polarity.

    Purpose:
        Gate candidate peaks/troughs before ranking or refinement.
    Why:
        Manual snapping should reject slope points first so sharp peaks do not
        settle on the run-up when the cursor is slightly off-center.
    Inputs:
        values: One-dimensional numeric series aligned to the active selection.
        idx: Candidate index within `values`.
        prefer_peak: True for maxima, False for minima.
    Outputs:
        Boolean indicating whether `idx` is a strict local extremum.
    Side Effects:
        None.
    Exceptions:
        Out-of-range and non-finite values return False.
    """
    arr = np.asarray(values, dtype=float).reshape(-1)
    if idx <= 0 or idx >= arr.size - 1:
        return False
    center = float(arr[idx])
    left = float(arr[idx - 1])
    right = float(arr[idx + 1])
    if not (math.isfinite(center) and math.isfinite(left) and math.isfinite(right)):
        return False
    if prefer_peak:
        return center >= left and center >= right and (center > left or center > right)
    return center <= left and center <= right and (center < left or center < right)


def _estimate_cycle_prominence(values: np.ndarray, idx: int, *, prefer_peak: bool) -> float:
    """Estimate one local peak/trough prominence on a transformed signal.

    Purpose:
        Provide a deterministic prominence metric for Rust/Python parity.
    Why:
        Candidate ranking and auto-detection filtering both rely on prominence.
    Inputs:
        values: One-dimensional numeric series aligned to the active selection.
        idx: Candidate extremum index.
        prefer_peak: True for maxima, False for minima.
    Outputs:
        Non-negative prominence estimate.
    Side Effects:
        None.
    Exceptions:
        Invalid indices return `0.0`.
    """
    arr = np.asarray(values, dtype=float).reshape(-1)
    if idx < 0 or idx >= arr.size:
        return 0.0
    transformed = arr if prefer_peak else -arr
    peak = float(transformed[idx])
    if not math.isfinite(peak):
        return 0.0
    left_min = peak
    j = idx
    while j > 0:
        j -= 1
        value = float(transformed[j])
        if not math.isfinite(value):
            continue
        left_min = min(left_min, value)
        if value > peak:
            break
    right_min = peak
    k = idx
    while k < transformed.size - 1:
        k += 1
        value = float(transformed[k])
        if not math.isfinite(value):
            continue
        right_min = min(right_min, value)
        if value > peak:
            break
    return max(peak - max(left_min, right_min), 0.0)


def _estimate_cycle_width(values: np.ndarray, idx: int, prominence: float, *, prefer_peak: bool) -> int:
    """Estimate one cycle candidate width at half prominence.

    Purpose:
        Mirror the Rust-side width filter used during candidate acceptance.
    Why:
        Python fallback must preserve the same sharp-spike filtering behavior.
    Inputs:
        values: One-dimensional numeric series aligned to the active selection.
        idx: Candidate extremum index.
        prominence: Estimated candidate prominence.
        prefer_peak: True for maxima, False for minima.
    Outputs:
        Integer width estimate in samples.
    Side Effects:
        None.
    Exceptions:
        Invalid candidates return `0`.
    """
    arr = np.asarray(values, dtype=float).reshape(-1)
    if idx < 0 or idx >= arr.size or prominence <= 0.0:
        return 0
    transformed = arr if prefer_peak else -arr
    center = float(transformed[idx])
    if not math.isfinite(center):
        return 0
    threshold = center - (float(prominence) * 0.5)
    left = idx
    while left > 0:
        prev = float(transformed[left - 1])
        if not math.isfinite(prev) or prev < threshold:
            break
        left -= 1
    right = idx
    while right < transformed.size - 1:
        nxt = float(transformed[right + 1])
        if not math.isfinite(nxt) or nxt < threshold:
            break
        right += 1
    return int(max(0, right - left + 1))


def _refine_cycle_candidate(
    values: np.ndarray,
    anchor_idx: int,
    refine_radius: int,
    *,
    prefer_peak: bool,
) -> int:
    """Refine one detected candidate back to the raw local extremum.

    Purpose:
        Snap smoothed candidate positions back to the raw signal.
    Why:
        Final stored markers should stay physically aligned to the original data,
        not to the smoothed candidate-search series.
    Inputs:
        values: One-dimensional raw cycle series for the active selection.
        anchor_idx: Candidate index chosen from the smoothed search series.
        refine_radius: Search radius in samples.
        prefer_peak: True for maxima, False for minima.
    Outputs:
        Refined raw-series index.
    Side Effects:
        None.
    Exceptions:
        Invalid inputs fall back to `anchor_idx`.
    """
    arr = np.asarray(values, dtype=float).reshape(-1)
    if arr.size == 0:
        return 0
    base_idx = int(max(0, min(int(anchor_idx), arr.size - 1)))
    radius = max(1, int(refine_radius))
    lo = max(0, base_idx - radius)
    hi = min(arr.size - 1, base_idx + radius)
    best_idx = base_idx
    best_value = float(arr[best_idx])
    if not prefer_peak:
        best_value = -best_value
    best_delta = abs(best_idx - base_idx)
    # Prefer true raw local extrema inside the refinement window before falling back.
    for idx in range(lo, hi + 1):
        if not _is_cycle_local_extremum(arr, idx, prefer_peak=prefer_peak):
            continue
        raw_value = float(arr[idx])
        metric_value = raw_value if prefer_peak else -raw_value
        delta = abs(idx - base_idx)
        if (
            not math.isfinite(best_value)
            or metric_value > best_value
            or (metric_value == best_value and delta < best_delta)
        ):
            best_idx = idx
            best_value = metric_value
            best_delta = delta
    if _is_cycle_local_extremum(arr, best_idx, prefer_peak=prefer_peak):
        return int(best_idx)
    for idx in range(lo, hi + 1):
        raw_value = float(arr[idx])
        if not math.isfinite(raw_value):
            continue
        metric_value = raw_value if prefer_peak else -raw_value
        delta = abs(idx - base_idx)
        if (
            not math.isfinite(best_value)
            or metric_value > best_value
            or (metric_value == best_value and delta < best_delta)
        ):
            best_idx = idx
            best_value = metric_value
            best_delta = delta
    return int(best_idx)


def _detect_cycle_markers_python(
    x_values: np.ndarray,
    y_values: np.ndarray,
    mask_arr: np.ndarray,
    *,
    prominence: float,
    distance: int,
    width: int,
    smoothing_window: int,
    refine_radius: int,
) -> Dict[str, Any]:
    """Detect automatic cycle markers in Python with raw-extrema refinement.

    Purpose:
        Provide the authoritative fallback when the Rust detection kernel is not
        available at runtime.
    Why:
        Cycle Analysis must remain functional without the optional Rust extension.
    Inputs:
        x_values: Full x-axis data aligned to `y_values`.
        y_values: Full pressure series used for detection.
        mask_arr: Boolean selection mask limiting active rows.
        prominence: Minimum prominence threshold.
        distance: Minimum accepted spacing in samples.
        width: Minimum accepted width in samples.
        smoothing_window: Centered moving-average window used for candidate search.
        refine_radius: Raw-series refinement radius in samples.
    Outputs:
        Dict with `auto_peaks`, `auto_troughs`, and `debug` metadata.
    Side Effects:
        None.
    Exceptions:
        Invalid inputs are sanitized into empty marker sets.
    """
    xv = np.asarray(x_values, dtype=float).reshape(-1)
    yv = np.asarray(y_values, dtype=float).reshape(-1)
    mask_safe = np.asarray(mask_arr, dtype=bool).reshape(-1)
    data_len = min(int(xv.size), int(yv.size), int(mask_safe.size))
    if data_len <= 0:
        return {"auto_peaks": [], "auto_troughs": [], "debug": {}}
    xv = xv[:data_len]
    yv = yv[:data_len]
    mask_safe = mask_safe[:data_len]
    selected = np.where(mask_safe & np.isfinite(xv) & np.isfinite(yv))[0]
    if selected.size < 3:
        return {"auto_peaks": [], "auto_troughs": [], "debug": {"selection_size": int(selected.size)}}
    compact_y = np.asarray(yv[selected], dtype=float)
    smoothed = _smooth_cycle_series(compact_y, smoothing_window)
    detector = _get_peak_finder() or _fallback_find_peaks

    def _detect(prefer_peak: bool) -> List[int]:
        """Detect one polarity of cycle markers on the active compact series."""
        series = smoothed if prefer_peak else -smoothed
        peak_idx, _props = detector(
            series,
            prominence=max(float(prominence), 0.0),
            distance=max(1, int(distance)),
            width=max(1, int(width)),
        )
        unique: Dict[int, Tuple[float, float]] = {}
        # Refine each smoothed candidate back onto the raw series before deduping.
        for raw_idx in np.asarray(peak_idx, dtype=int).tolist():
            if raw_idx < 0 or raw_idx >= compact_y.size:
                continue
            refined_idx = _refine_cycle_candidate(
                compact_y,
                int(raw_idx),
                max(1, int(refine_radius)),
                prefer_peak=prefer_peak,
            )
            prominence_value = _estimate_cycle_prominence(
                compact_y, refined_idx, prefer_peak=prefer_peak
            )
            width_value = _estimate_cycle_width(
                compact_y,
                refined_idx,
                prominence_value,
                prefer_peak=prefer_peak,
            )
            if prominence_value < max(float(prominence), 0.0):
                continue
            if width_value < max(1, int(width)):
                continue
            curvature_value = abs(
                float(compact_y[refined_idx - 1] - 2.0 * compact_y[refined_idx] + compact_y[refined_idx + 1])
            ) if 0 < refined_idx < compact_y.size - 1 else 0.0
            current = unique.get(refined_idx)
            metric = (float(prominence_value), float(curvature_value))
            if current is None or metric > current:
                unique[int(refined_idx)] = metric
        if not unique:
            return []
        sorted_candidates = sorted(
            unique.items(),
            key=lambda item: (-item[1][0], -item[1][1], int(selected[item[0]])),
        )
        accepted: List[int] = []
        accepted_global: List[int] = []
        for compact_idx, _metric in sorted_candidates:
            global_idx = int(selected[compact_idx])
            if any(abs(global_idx - existing) < max(1, int(distance)) for existing in accepted_global):
                continue
            accepted.append(int(compact_idx))
            accepted_global.append(global_idx)
        accepted.sort()
        return [int(selected[idx]) for idx in accepted]

    return {
        "auto_peaks": _detect(True),
        "auto_troughs": _detect(False),
        "debug": {
            "selection_size": int(selected.size),
            "smoothing_window": int(_normalize_cycle_window(smoothing_window)),
            "refine_radius": int(max(1, int(refine_radius))),
        },
    }


def _resolve_cycle_manual_candidate(
    x_values: np.ndarray,
    y_values: np.ndarray,
    mask_arr: np.ndarray,
    *,
    x_target: float,
    y_target: Optional[float],
    prefer_peak: bool,
    snap_radius: int,
    smoothing_window: int,
) -> Optional[Dict[str, Any]]:
    """Resolve one manual cycle marker candidate via Rust-first shared logic.

    Purpose:
        Provide one placement contract for the main Cycle Analysis editor and the
        Compare side editor.
    Why:
        Manual marker placement should behave identically across every editing
        surface, with safe Python fallback when Rust is unavailable.
    Inputs:
        x_values: Full x-axis data aligned to `y_values`.
        y_values: Full pressure series used for manual placement.
        mask_arr: Boolean selection mask limiting active rows.
        x_target: Cursor x-coordinate.
        y_target: Optional cursor y-coordinate.
        prefer_peak: True for maxima, False for minima.
        snap_radius: Candidate search radius, where `0` means auto window.
        smoothing_window: Centered moving-average window used for candidate search.
    Outputs:
        Dict with `index`, `x`, `y`, `prominence`, and `score`, or `None` when no
        valid candidate exists.
    Side Effects:
        None.
    Exceptions:
        Invalid inputs return `None`.
    """
    rust_payload = _rust_cycle_manual_snap_core(
        x_values=x_values,
        y_values=y_values,
        mask_arr=mask_arr,
        x_target=x_target,
        y_target=y_target,
        prefer_peak=prefer_peak,
        snap_radius=snap_radius,
        smoothing_window=smoothing_window,
    )
    if isinstance(rust_payload, Mapping):
        return dict(rust_payload)
    xv = np.asarray(x_values, dtype=float).reshape(-1)
    yv = np.asarray(y_values, dtype=float).reshape(-1)
    mask_safe = np.asarray(mask_arr, dtype=bool).reshape(-1)
    data_len = min(int(xv.size), int(yv.size), int(mask_safe.size))
    if data_len <= 0 or not math.isfinite(float(x_target)):
        return None
    xv = xv[:data_len]
    yv = yv[:data_len]
    mask_safe = mask_safe[:data_len]
    selected = np.where(mask_safe & np.isfinite(xv) & np.isfinite(yv))[0]
    if selected.size < 3:
        return None
    compact_x = np.asarray(xv[selected], dtype=float)
    compact_y = np.asarray(yv[selected], dtype=float)
    anchor_pos = int(np.nanargmin(np.abs(compact_x - float(x_target))))
    window_radius = (
        max(6, min(80, int(round(selected.size * 0.01))))
        if int(snap_radius) <= 0
        else max(1, int(snap_radius))
    )
    lo = max(0, anchor_pos - window_radius)
    hi = min(selected.size - 1, anchor_pos + window_radius)
    local_positions = np.arange(lo, hi + 1, dtype=int)
    if local_positions.size == 0:
        return None
    local_y = compact_y[local_positions]
    smoothed = _smooth_cycle_series(local_y, smoothing_window)
    transformed = smoothed if prefer_peak else -smoothed
    maxima = []
    # Find local extrema on the smoothed search series before raw refinement.
    for idx in range(1, transformed.size - 1):
        if _is_cycle_local_extremum(transformed, idx, prefer_peak=True):
            maxima.append(int(idx))
    refine_radius = max(2, _normalize_cycle_window(smoothing_window) // 2)
    candidates: List[Tuple[float, float, float, int, int]] = []
    compact_anchor_idx = int(local_positions[min(anchor_pos - lo, local_positions.size - 1)])
    for candidate_idx in maxima:
        compact_idx = int(local_positions[candidate_idx])
        refined_idx = _refine_cycle_candidate(
            compact_y, compact_idx, refine_radius, prefer_peak=prefer_peak
        )
        prominence_value = _estimate_cycle_prominence(
            compact_y, refined_idx, prefer_peak=prefer_peak
        )
        curvature_value = (
            abs(float(compact_y[refined_idx - 1] - 2.0 * compact_y[refined_idx] + compact_y[refined_idx + 1]))
            if 0 < refined_idx < compact_y.size - 1
            else 0.0
        )
        x_distance = abs(float(compact_x[refined_idx] - float(x_target)))
        anchor_delta = abs(int(refined_idx) - int(compact_anchor_idx))
        score = (
            float(prominence_value) * 1000.0
            + float(curvature_value) * 50.0
            - float(x_distance)
            - float(anchor_delta) * 0.01
        )
        candidates.append(
            (
                -float(prominence_value),
                float(x_distance),
                -float(curvature_value),
                int(anchor_delta),
                int(refined_idx),
            )
        )
        candidates[-1] = candidates[-1] + (score,)
    if not candidates:
        refined_idx = _refine_cycle_candidate(
            compact_y, compact_anchor_idx, refine_radius, prefer_peak=prefer_peak
        )
        prominence_value = _estimate_cycle_prominence(
            compact_y, refined_idx, prefer_peak=prefer_peak
        )
        score = float(prominence_value) * 1000.0
        return {
            "index": int(selected[refined_idx]),
            "x": float(compact_x[refined_idx]),
            "y": float(compact_y[refined_idx]),
            "prominence": float(prominence_value),
            "score": score,
        }
    candidates.sort()
    best = candidates[0]
    refined_idx = int(best[4])
    return {
        "index": int(selected[refined_idx]),
        "x": float(compact_x[refined_idx]),
        "y": float(compact_y[refined_idx]),
        "prominence": float(-best[0]),
        "score": float(best[5]),
    }


def _great_tables_missing_message(feature: str) -> str:
    """Return a user-facing message for unavailable great_tables support.

    Purpose:
        Centralize optional dependency guidance for timeline-table export paths.
    Why:
        Startup now lazily imports `great_tables`, so failures need one consistent
        remediation message when the feature is used.
    Inputs:
        feature: Workflow label that requires `great_tables`.
    Outputs:
        Human-readable error text with install guidance.
    Side Effects:
        None.
    Exceptions:
        None.
    """
    msg = (
        f"great_tables is required for {feature}, but it could not be imported.\n"
        "Install it with 'pip install great-tables' and restart the application."
    )
    if _GREAT_TABLES_IMPORT_ERROR is not None:
        msg += f"\n\nImport error: {_GREAT_TABLES_IMPORT_ERROR}"
    return msg


def _get_great_tables_module():
    """Lazily import and cache the optional `great_tables` module.

    Purpose:
        Resolve `great_tables` only when timeline table export workflows need it.
    Why:
        Deferring this optional import reduces startup overhead while preserving
        feature availability when invoked later in the session.
    Inputs:
        None.
    Outputs:
        Imported `great_tables` module object, or `None` when unavailable.
    Side Effects:
        Caches the imported module/import failure and updates shared GIL-import
        diagnostics when import succeeds.
    Exceptions:
        Import failures are captured and converted to `None`.
    """
    global _GREAT_TABLES_MODULE, _GREAT_TABLES_IMPORT_ERROR, _GIL_IMPORT_STATUS
    if _GREAT_TABLES_MODULE is not None:
        return _GREAT_TABLES_MODULE
    if _GREAT_TABLES_IMPORT_ERROR is not None:
        return None
    _gil_before_great_tables = _current_gil_status()
    try:
        import great_tables as great_tables_module  # type: ignore
    except Exception as exc:
        _GREAT_TABLES_IMPORT_ERROR = exc
        return None
    _GIL_IMPORT_STATUS = _note_gil_reenable(
        "great_tables", _gil_before_great_tables
    )
    _GREAT_TABLES_MODULE = great_tables_module
    return _GREAT_TABLES_MODULE


def _scipy_missing_message(feature: str) -> str:
    """Perform scipy missing message.
    Used to keep the workflow logic localized and testable."""

    base = (
        f"SciPy is required for {feature}, but it could not be imported.\n"
        "Install SciPy with 'pip install scipy' and restart the application for the "
        "most accurate results."
    )

    if _FALLBACK_FIND_PEAKS is not None:

        base += (
            "\n\nThe app will fall back to a basic built-in peak detection so you can still "
            "continue working, but installing SciPy is highly recommended."
        )

    if _SCIPY_IMPORT_ERROR is not None:

        base += f"\n\nImport error: {_SCIPY_IMPORT_ERROR}"

    return base


_SCIPY_WARNED_FEATURES = set()


def _warn_missing_scipy(feature: str, *, parent=None, kind: str = "warning") -> None:
    """Perform warn missing scipy.
    Used to keep the workflow logic localized and testable."""

    key = feature.lower()

    if key in _SCIPY_WARNED_FEATURES:

        return

    _SCIPY_WARNED_FEATURES.add(key)

    msg = _scipy_missing_message(feature)

    if parent is None:

        try:

            if kind == "error":

                messagebox.showerror("SciPy Required", msg)

            else:

                messagebox.showwarning("SciPy Required", msg)

        except Exception:

            print(msg, file=sys.stderr)

        return

    try:

        if kind == "error":

            messagebox.showerror("SciPy Required", msg, parent=parent)

        else:

            messagebox.showwarning("SciPy Required", msg, parent=parent)

    except Exception:

        print(msg, file=sys.stderr)


def _make_legend_draggable(
    legend,
    enabled: bool = True,
    *,
    update_mode: str = "loc",
):
    """Set legend draggability through one normalized helper path.

    Purpose:
        Enable or disable drag behavior for a Matplotlib legend artist.
    Why:
        Centralizing drag-state wiring keeps legend behavior consistent across
        combined and non-combined plot builders.

    Args:
        legend: Matplotlib Legend to update. None is accepted and ignored.
        enabled: True to enable drag, False to disable drag.
        update_mode: Matplotlib drag update mode ("loc" or "bbox") used when
            enabling drag. Invalid values fall back to "loc".

    Returns:
        The original legend reference, or None when legend is None.

    Side Effects:
        Calls legend.set_draggable(...) and may create or disconnect internal
        Matplotlib drag callbacks on the legend's canvas.

    Exceptions:
        Errors are swallowed to avoid interrupting UI workflows.
    """
    if legend is None:
        return legend
    if update_mode not in {"loc", "bbox"}:
        update_mode = "loc"
    try:
        if enabled:
            try:
                legend.set_draggable(True, update=update_mode)
            except TypeError:
                # Matplotlib variants that do not expose the update kwarg.
                legend.set_draggable(True)
        else:
            legend.set_draggable(False)
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass
    return legend


def _mark_timeline_main_legend_artist(legend: Any) -> Any:
    """Tag one legend as the canonical cycle timeline main legend.

    Purpose:
        Normalize timeline legend metadata so capture/sync helpers can target
        only the consolidated timeline legend.
    Why:
        Timeline figures can include inset legends (for pressure context) that
        must be excluded from preview-to-display legend synchronization.
    Inputs:
        legend: Candidate Matplotlib legend artist.
    Outputs:
        Any: The same legend reference, or None when no legend is provided.
    Side Effects:
        Mutates legend metadata attributes used by GL-260 legend discovery.
    Exceptions:
        Best-effort; metadata write failures are ignored.
    """
    if legend is None:
        return None
    try:
        legend._gl260_legend_role = "main"  # type: ignore[attr-defined]
        legend._cycle_timeline_main_legend = True  # type: ignore[attr-defined]
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass
    return legend


def _legend_shadowbox_kwargs() -> Dict[str, Any]:
    """Perform legend shadowbox kwargs.
    Used to keep the workflow logic localized and testable."""
    fill_color_default = "#FFFFFF"
    fill_color = fill_color_default
    try:
        settings_map = globals().get("settings", {})
        raw_value = None
        if isinstance(settings_map, dict):
            raw_value = settings_map.get("combined_legend_shadowbox_fill_color")
        try:
            from matplotlib.colors import to_rgba  # type: ignore

            candidate = str(raw_value or "").strip()
            if candidate:
                to_rgba(candidate)
                fill_color = candidate
        except Exception:
            fill_color = fill_color_default
    except Exception:
        fill_color = fill_color_default
    return {
        "frameon": True,
        "facecolor": fill_color,
        "edgecolor": "#444",
        "fancybox": True,
        "shadow": True,
        "framealpha": 0.9,
    }


