def _resolve_compare_plot_preset_values(
    preset_name: str,
    *,
    custom_presets: Optional[Mapping[str, Mapping[str, Any]]] = None,
) -> Dict[str, Any]:
    """Resolve one compare preset payload from custom and built-in collections.

    Purpose:
        Select compare preset values using deterministic custom-then-built-in
        resolution order.
    Why:
        Compare rendering needs one predictable override payload for each pane
        refresh and persistence restore.
    Args:
        preset_name: Candidate preset name selected by the user/settings.
        custom_presets: Optional mapping of user-defined presets.
    Returns:
        Dict containing normalized preset values for rendering overrides.
    Side Effects:
        None.
    Exceptions:
        Invalid names fall back to the default built-in preset.
    """
    normalized_custom = (
        _normalize_compare_custom_plot_presets(custom_presets)
        if isinstance(custom_presets, Mapping)
        else {}
    )
    builtins = _builtin_compare_plot_presets()
    fallback_name = (
        DEFAULT_COMPARE_PLOT_PRESET_NAME
        if DEFAULT_COMPARE_PLOT_PRESET_NAME in builtins
        else next(iter(builtins), DEFAULT_COMPARE_PLOT_PRESET_NAME)
    )
    requested = str(preset_name or "").strip()
    if requested in normalized_custom:
        return _normalize_compare_plot_preset_values(
            normalized_custom.get(requested) or {},
            fallback=_default_compare_plot_preset_values(),
        )
    if requested in builtins:
        return _normalize_compare_plot_preset_values(
            builtins.get(requested) or {},
            fallback=_default_compare_plot_preset_values(),
        )
    return _normalize_compare_plot_preset_values(
        builtins.get(fallback_name) or {},
        fallback=_default_compare_plot_preset_values(),
    )


