def _normalize_reaction_catalog_entry(
    raw_entry: Any,
    *,
    reaction_id: str,
) -> Dict[str, Any]:
    """Normalize one reaction catalog entry into the canonical persistence schema.

    Purpose:
        Provide one stable schema for built-in and user-defined reaction entries.
    Why:
        Plot Settings, Analysis yield math, Compare, Ledger, and Final Report all
        need to read the same reaction payload without per-surface translation.
    Inputs:
        raw_entry: Candidate mapping-like payload from settings or code defaults.
        reaction_id: Canonical reaction identifier used as the storage key.
    Outputs:
        Dict[str, Any]: Normalized reaction entry with all required keys present.
    Side Effects:
        None.
    Exceptions:
        Invalid numeric values are coerced to safe defaults.
    """
    seed = dict(REACTION_CATALOG_SEED.get(reaction_id) or REACTION_CATALOG_SEED["custom"])
    source = dict(raw_entry) if isinstance(raw_entry, Mapping) else {}

    def _opt_float(raw_value: Any, fallback: float) -> float:
        """Return one finite float for reaction catalog normalization."""
        try:
            candidate = float(raw_value)
        except Exception:
            return float(fallback)
        if not math.isfinite(candidate):
            return float(fallback)
        return float(candidate)

    normalized = dict(seed)
    normalized.update(
        {
            "reaction_id": str(source.get("reaction_id") or reaction_id or "custom").strip()
            or "custom",
            "reaction_label": str(
                source.get("reaction_label") or seed.get("reaction_label") or reaction_id
            ).strip()
            or reaction_id,
            "starting_material_display_name": str(
                source.get("starting_material_display_name")
                or seed.get("starting_material_display_name")
                or ""
            ).strip(),
            "starting_material_formula": str(
                source.get("starting_material_formula")
                or seed.get("starting_material_formula")
                or ""
            ).strip(),
            "starting_material_mw_g_mol": _opt_float(
                source.get("starting_material_mw_g_mol"),
                float(seed.get("starting_material_mw_g_mol") or 0.0),
            ),
            "starting_mass_g": _opt_float(
                source.get("starting_mass_g"),
                float(seed.get("starting_mass_g") or 0.0),
            ),
            "gas_molar_mass": _opt_float(
                source.get("gas_molar_mass"),
                float(seed.get("gas_molar_mass") or DEFAULT_GAS_MOLAR_MASS),
            ),
            "gas_stoich_mol_per_mol_starting": _opt_float(
                source.get("gas_stoich_mol_per_mol_starting"),
                float(seed.get("gas_stoich_mol_per_mol_starting") or 0.0),
            ),
            "final_product_name": str(
                source.get("final_product_name") or seed.get("final_product_name") or ""
            ).strip(),
            "final_product_formula": str(
                source.get("final_product_formula")
                or seed.get("final_product_formula")
                or ""
            ).strip(),
            "final_product_mw_g_mol": _opt_float(
                source.get("final_product_mw_g_mol"),
                float(seed.get("final_product_mw_g_mol") or 0.0),
            ),
            "product_stoich_mol_per_mol_starting": _opt_float(
                source.get("product_stoich_mol_per_mol_starting"),
                float(seed.get("product_stoich_mol_per_mol_starting") or 0.0),
            ),
            "yield_mode": str(
                source.get("yield_mode") or seed.get("yield_mode") or REACTION_YIELD_MODE_PRODUCT
            ).strip()
            or REACTION_YIELD_MODE_PRODUCT,
            "builtin": bool(source.get("builtin", seed.get("builtin", False))),
        }
    )
    if normalized["yield_mode"] not in REACTION_YIELD_MODE_CHOICES:
        normalized["yield_mode"] = REACTION_YIELD_MODE_PRODUCT
    return normalized


def _normalize_reaction_catalog(raw_catalog: Any) -> "OrderedDict[str, Dict[str, Any]]":
    """Normalize the persisted reaction catalog and append built-in entries.

    Purpose:
        Guarantee that every runtime session has a valid reaction catalog with
        seeded carbonate presets plus any saved custom entries.
    Why:
        The UI now exposes shared reaction selection in Plot Settings and Final
        Report, so missing/malformed settings must self-heal deterministically.
    Inputs:
        raw_catalog: Candidate settings payload for the reaction catalog.
    Outputs:
        OrderedDict[str, Dict[str, Any]]: Canonical catalog keyed by reaction id.
    Side Effects:
        None.
    Exceptions:
        Invalid payloads fall back to the seeded catalog only.
    """
    normalized: "OrderedDict[str, Dict[str, Any]]" = OrderedDict()
    raw_map = raw_catalog if isinstance(raw_catalog, Mapping) else {}
    # Seed built-ins first so upgraded settings always retain canonical presets.
    for reaction_id, entry in REACTION_CATALOG_SEED.items():
        normalized[reaction_id] = _normalize_reaction_catalog_entry(
            raw_map.get(reaction_id, entry),
            reaction_id=reaction_id,
        )
    for raw_key, raw_entry in raw_map.items():
        reaction_id = str(raw_key or "").strip()
        if not reaction_id or reaction_id in normalized:
            continue
        normalized[reaction_id] = _normalize_reaction_catalog_entry(
            raw_entry, reaction_id=reaction_id
        )
    return normalized


def _reaction_catalog_labels(catalog: Mapping[str, Mapping[str, Any]]) -> List[str]:
    """Return ordered reaction labels for dropdown display."""
    labels: List[str] = []
    for reaction_id, entry in (catalog or {}).items():
        if not isinstance(entry, Mapping):
            continue
        label = str(entry.get("reaction_label") or reaction_id).strip()
        if label:
            labels.append(label)
    return labels


