def _default_ledger_view_profiles() -> Dict[str, Dict[str, Any]]:
    """Return default Ledger view-mode width profiles.

    Purpose:
        Provide one canonical baseline mapping for persisted Ledger view widths.
    Why:
        Ledger now supports named width modes and each mode needs a stable
        persistence shape even when the user has not customized widths yet.
    Args:
        None.
    Returns:
        Dict keyed by view-mode token with empty `column_widths` maps.
    Side Effects:
        None.
    Exceptions:
        None.
    """
    return {
        mode_token: {"column_widths": {}}
        for mode_token in LEDGER_VIEW_MODE_TOKENS
    }


def _normalize_ledger_view_mode(value: Any, *, default: str = "standard") -> str:
    """Normalize the persisted Ledger view-mode token.

    Purpose:
        Coerce raw Ledger view-mode settings into one supported token.
    Why:
        View-mode persistence must remain deterministic across upgrades and
        malformed settings payloads.
    Args:
        value: Incoming raw mode value.
        default: Fallback mode token used for invalid values.
    Returns:
        Normalized mode token (`standard`, `tight`, or `fit`).
    Side Effects:
        None.
    Exceptions:
        Invalid values fall back to `default` or `standard`.
    """
    default_token = str(default or "standard").strip().lower()
    if default_token not in LEDGER_VIEW_MODE_TOKENS:
        default_token = "standard"
    candidate = str(value or "").strip().lower()
    if candidate in LEDGER_VIEW_MODE_TOKENS:
        return candidate
    # Accept label-like values from combobox/UI text.
    for mode_token, mode_label in LEDGER_VIEW_MODE_LABELS.items():
        if candidate == str(mode_label or "").strip().lower():
            return mode_token
    return default_token


def _normalize_ledger_view_profiles(value: Any) -> Dict[str, Dict[str, Any]]:
    """Normalize persisted Ledger view profiles.

    Purpose:
        Coerce raw width-profile settings into one stable schema.
    Why:
        Treeview width persistence must reject invalid width values while keeping
        per-mode profile keys intact across sessions.
    Args:
        value: Incoming settings payload for Ledger view profiles.
    Returns:
        Dict keyed by mode token with normalized `column_widths` integer maps.
    Side Effects:
        None.
    Exceptions:
        Invalid payloads/values are replaced with defaults.
    """
    raw_map = value if isinstance(value, Mapping) else {}
    normalized = _default_ledger_view_profiles()
    for mode_token in LEDGER_VIEW_MODE_TOKENS:
        mode_payload = raw_map.get(mode_token)
        mode_map = mode_payload if isinstance(mode_payload, Mapping) else {}
        raw_widths = mode_map.get("column_widths")
        widths_map = raw_widths if isinstance(raw_widths, Mapping) else {}
        normalized_widths: Dict[str, int] = {}
        # Keep only positive finite integer width values keyed by non-empty strings.
        for raw_key, raw_width in widths_map.items():
            key = str(raw_key or "").strip()
            if not key:
                continue
            try:
                width_value = int(float(raw_width))
            except Exception:
                continue
            if width_value <= 0:
                continue
            normalized_widths[key] = int(width_value)
        normalized[mode_token] = {"column_widths": normalized_widths}
    return normalized


def _ledger_slugify_custom_column_key(label: str) -> str:
    """Build a stable custom-column key token from a display label.

    Purpose:
        Convert free-form custom column labels into storage-safe key tokens.
    Why:
        Formula references and persisted row `custom_values` require deterministic
        ASCII-safe keys that remain stable across sessions.
    Args:
        label: User-facing custom column label candidate.
    Returns:
        Key token prefixed by `custom_`.
    Side Effects:
        None.
    Exceptions:
        Empty/invalid labels fall back to `custom_column`.
    """
    text = str(label or "").strip().lower()
    slug = re.sub(r"[^a-z0-9]+", "_", text).strip("_")
    if not slug:
        slug = "column"
    return f"{LEDGER_CUSTOM_COLUMN_KEY_PREFIX}{slug}"


def _normalize_ledger_custom_columns(value: Any) -> List[Dict[str, str]]:
    """Normalize persisted Ledger custom-column definitions.

    Purpose:
        Sanitize stored custom Ledger column schema definitions.
    Why:
        Custom columns power table rendering, entry dialogs, and formulas, so
        malformed schema payloads must be normalized safely.
    Args:
        value: Incoming settings payload for `custom_columns`.
    Returns:
        List of normalized custom column dicts (`key`, `label`, `type`, `formula`).
    Side Effects:
        None.
    Exceptions:
        Invalid entries are skipped; duplicate keys are de-duplicated with suffixes.
    """
    rows = value if isinstance(value, Sequence) and not isinstance(value, (str, bytes)) else []
    normalized: List[Dict[str, str]] = []
    seen_keys: Set[str] = set()
    for raw_item in rows:
        if not isinstance(raw_item, Mapping):
            continue
        label = str(raw_item.get("label") or "").strip()
        key_candidate = str(raw_item.get("key") or "").strip().lower()
        if not key_candidate.startswith(LEDGER_CUSTOM_COLUMN_KEY_PREFIX):
            key_candidate = _ledger_slugify_custom_column_key(label or key_candidate)
        if not key_candidate:
            key_candidate = _ledger_slugify_custom_column_key(label)
        col_type = str(raw_item.get("type") or "text").strip().lower()
        if col_type not in LEDGER_CUSTOM_COLUMN_TYPES:
            col_type = "text"
        formula_text = str(raw_item.get("formula") or "").strip() if col_type == "formula" else ""
        if not label:
            suffix = key_candidate[len(LEDGER_CUSTOM_COLUMN_KEY_PREFIX) :]
            label = suffix.replace("_", " ").strip().title() or "Custom Column"
        base_key = key_candidate
        dedupe_idx = 2
        while key_candidate in seen_keys:
            key_candidate = f"{base_key}_{dedupe_idx}"
            dedupe_idx += 1
        seen_keys.add(key_candidate)
        normalized.append(
            {
                "key": key_candidate,
                "label": label,
                "type": col_type,
                "formula": formula_text,
            }
        )
    return normalized


def _ledger_allowed_columns_from_custom_columns(
    custom_columns: Sequence[Mapping[str, Any]],
) -> Tuple[str, ...]:
    """Return canonical Ledger table columns for base + custom schema.

    Purpose:
        Compute one deterministic allowed-column ordering for Ledger table state.
    Why:
        Column-order and width persistence need a shared allowed-key list that
        includes dynamic custom columns.
    Args:
        custom_columns: Normalized custom column definitions.
    Returns:
        Tuple containing built-in Ledger columns followed by custom column keys.
    Side Effects:
        None.
    Exceptions:
        Invalid custom-key entries are skipped.
    """
    ordered = list(LEDGER_TABLE_COLUMNS)
    seen: Set[str] = set(ordered)
    for col in list(custom_columns or []):
        key = str(col.get("key") or "").strip()
        if not key or key in seen:
            continue
        ordered.append(key)
        seen.add(key)
    return tuple(ordered)


def _evaluate_safe_ledger_formula_expression(
    expression: str,
    values: Mapping[str, float],
    *,
    allowed_names: Set[str],
) -> Optional[float]:
    """Evaluate one restricted arithmetic expression for Ledger formula columns.

    Purpose:
        Compute formula-column values using a safe arithmetic-only expression
        evaluator over row-local numeric values.
    Why:
        Ledger formulas must remain deterministic and safe; unrestricted Python
        evaluation is not acceptable for persisted user expressions.
    Args:
        expression: Formula expression text.
        values: Numeric values available for variable substitution.
        allowed_names: Identifier names permitted in the expression.
    Returns:
        Computed finite float value, or None when expression is invalid.
    Side Effects:
        None.
    Exceptions:
        Parse/validation/evaluation failures return None.
    """
    text = str(expression or "").strip()
    if not text:
        return None
    try:
        parsed = ast.parse(text, mode="eval")
    except Exception:
        return None

    class _FormulaValidator(ast.NodeVisitor):
        """Validate that parsed formula AST uses only safe arithmetic constructs."""

        _allowed_bin_ops = (ast.Add, ast.Sub, ast.Mult, ast.Div)
        _allowed_unary_ops = (ast.UAdd, ast.USub)

        def generic_visit(self, node: ast.AST) -> Any:
            """Reject unsupported node types during traversal."""
            raise ValueError(f"Unsupported syntax node: {type(node).__name__}")

        def visit_Expression(self, node: ast.Expression) -> Any:
            """Visit root expression node."""
            return self.visit(node.body)

        def visit_BinOp(self, node: ast.BinOp) -> Any:
            """Validate binary arithmetic operations."""
            if not isinstance(node.op, self._allowed_bin_ops):
                raise ValueError("Only +, -, *, and / operators are supported.")
            self.visit(node.left)
            self.visit(node.right)
            return None

        def visit_UnaryOp(self, node: ast.UnaryOp) -> Any:
            """Validate unary sign operators."""
            if not isinstance(node.op, self._allowed_unary_ops):
                raise ValueError("Only unary + and - operators are supported.")
            self.visit(node.operand)
            return None

        def visit_Name(self, node: ast.Name) -> Any:
            """Validate variable identifiers against the allowed-name set."""
            if node.id not in allowed_names:
                raise ValueError(f"Unknown formula name: {node.id}")
            return None

        def visit_Constant(self, node: ast.Constant) -> Any:
            """Validate numeric constants."""
            if isinstance(node.value, (int, float)):
                return None
            raise ValueError("Only numeric constants are supported.")

        def visit_Num(self, node: ast.Num) -> Any:  # pragma: no cover - py<3.8 compatibility
            """Validate legacy numeric constants for compatibility."""
            if isinstance(node.n, (int, float)):
                return None
            raise ValueError("Only numeric constants are supported.")

    try:
        _FormulaValidator().visit(parsed)
    except Exception:
        return None

    eval_locals: Dict[str, float] = {}
    # Only pass finite numeric values to expression scope.
    for name in list(allowed_names):
        raw_value = values.get(name)
        try:
            numeric_value = float(raw_value)
        except Exception:
            continue
        if not math.isfinite(numeric_value):
            continue
        eval_locals[name] = float(numeric_value)
    try:
        compiled = compile(parsed, "<ledger_formula>", "eval")
        result = eval(compiled, {"__builtins__": {}}, eval_locals)
    except Exception:
        return None
    try:
        numeric_result = float(result)
    except Exception:
        return None
    if not math.isfinite(numeric_result):
        return None
    return float(numeric_result)


def _ledger_formula_identifier_names(expression: str) -> Optional[Set[str]]:
    """Return referenced identifier names for one safe Ledger formula expression.

    Purpose:
        Validate formula syntax and extract referenced variable identifiers.
    Why:
        Custom-column formula authoring should reject unsafe syntax and enforce
        allowed numeric-reference rules before persistence.
    Args:
        expression: Raw formula expression text.
    Returns:
        Set of identifier names when syntax is safe; None on invalid/unsafe text.
    Side Effects:
        None.
    Exceptions:
        Parse/validation failures return None.
    """
    text = str(expression or "").strip()
    if not text:
        return set()
    try:
        parsed = ast.parse(text, mode="eval")
    except Exception:
        return None
    names: Set[str] = set()

    class _Validator(ast.NodeVisitor):
        """AST validator permitting arithmetic expressions and identifier names."""

        _allowed_bin_ops = (ast.Add, ast.Sub, ast.Mult, ast.Div)
        _allowed_unary_ops = (ast.UAdd, ast.USub)

        def generic_visit(self, node: ast.AST) -> Any:
            """Reject unsupported syntax node types."""
            raise ValueError(f"Unsupported syntax node: {type(node).__name__}")

        def visit_Expression(self, node: ast.Expression) -> Any:
            """Visit root expression body."""
            return self.visit(node.body)

        def visit_BinOp(self, node: ast.BinOp) -> Any:
            """Validate binary arithmetic operators."""
            if not isinstance(node.op, self._allowed_bin_ops):
                raise ValueError("Only +, -, *, and / operators are supported.")
            self.visit(node.left)
            self.visit(node.right)
            return None

        def visit_UnaryOp(self, node: ast.UnaryOp) -> Any:
            """Validate unary sign operators."""
            if not isinstance(node.op, self._allowed_unary_ops):
                raise ValueError("Only unary + and - operators are supported.")
            self.visit(node.operand)
            return None

        def visit_Name(self, node: ast.Name) -> Any:
            """Collect identifier names used in the formula expression."""
            names.add(str(node.id))
            return None

        def visit_Constant(self, node: ast.Constant) -> Any:
            """Validate numeric constants."""
            if isinstance(node.value, (int, float)):
                return None
            raise ValueError("Only numeric constants are supported.")

        def visit_Num(self, node: ast.Num) -> Any:  # pragma: no cover - py<3.8 compatibility
            """Validate legacy numeric constants for compatibility."""
            if isinstance(node.n, (int, float)):
                return None
            raise ValueError("Only numeric constants are supported.")

    try:
        _Validator().visit(parsed)
    except Exception:
        return None
    return set(names)


def _default_ledger_table_state() -> Dict[str, Any]:
    """Return default persisted state for the Ledger table layout.

    Purpose:
        Provide one canonical baseline payload for Ledger-table UI preferences.
    Why:
        Startup normalization and dialog reset actions require one stable source
        of truth for default column ordering.
    Args:
        None.
    Returns:
        Dict containing Ledger table layout defaults.
    Side Effects:
        None.
    Exceptions:
        None.
    """
    return {
        "column_order": list(LEDGER_TABLE_COLUMNS),
        "view_mode": "standard",
        "view_profiles": _default_ledger_view_profiles(),
        "custom_columns": [],
    }


def _normalize_ledger_table_settings(
    value: Any,
    *,
    allowed_columns: Optional[Sequence[str]] = None,
) -> Dict[str, Any]:
    """Normalize persisted Ledger-table layout settings.

    Purpose:
        Coerce stored Ledger table preferences into a stable schema.
    Why:
        Column-order persistence can contain stale keys or malformed payloads
        across upgrades; normalization keeps Treeview display ordering valid.
    Args:
        value: Incoming settings payload for `ledger_table`.
        allowed_columns: Optional explicit allowed column-key list.
    Returns:
        Dict containing normalized Ledger-table settings.
    Side Effects:
        None.
    Exceptions:
        Invalid payloads fall back to defaults.
    """
    defaults = _default_ledger_table_state()
    raw = value if isinstance(value, Mapping) else {}
    custom_columns = _normalize_ledger_custom_columns(raw.get("custom_columns"))
    allowed = (
        tuple(
            str(key or "").strip()
            for key in list(allowed_columns or [])
            if str(key or "").strip()
        )
        if allowed_columns is not None
        else _ledger_allowed_columns_from_custom_columns(custom_columns)
    )
    if not allowed:
        allowed = tuple(LEDGER_TABLE_COLUMNS)
    allowed_set = set(allowed)
    normalized_order: List[str] = []
    seen: Set[str] = set()
    raw_order = raw.get("column_order")
    if isinstance(raw_order, Sequence) and not isinstance(raw_order, (str, bytes)):
        # Preserve user order while dropping invalid/duplicate column tokens.
        for raw_key in raw_order:
            key = str(raw_key or "").strip()
            if key not in allowed_set:
                continue
            if key in seen:
                continue
            normalized_order.append(key)
            seen.add(key)
    for default_key in allowed:
        if default_key in seen:
            continue
        normalized_order.append(default_key)
        seen.add(default_key)
    view_mode = _normalize_ledger_view_mode(
        raw.get("view_mode"),
        default=str(defaults.get("view_mode") or "standard"),
    )
    view_profiles = _normalize_ledger_view_profiles(raw.get("view_profiles"))
    return {
        "column_order": list(normalized_order),
        "view_mode": view_mode,
        "view_profiles": view_profiles,
        "custom_columns": list(custom_columns),
    }


def _normalize_ledger_entries_settings(value: Any) -> List[Dict[str, Any]]:
    """Normalize persisted Ledger entries.

    Purpose:
        Coerce Ledger rows to a predictable schema for UI display/edit flows.
    Why:
        Ledger persistence allows user-edited freeform data that can drift in
        type/shape across sessions; normalization prevents runtime errors.
    Args:
        value: Incoming settings payload for `ledger_entries`.
    Returns:
        List of normalized Ledger entry dictionaries.
    Side Effects:
        None.
    Exceptions:
        Invalid rows are dropped.
    """

    def _opt_float(raw_value: Any) -> Optional[float]:
        """Return finite float value or None for optional Ledger fields."""
        if raw_value in (None, ""):
            return None
        raw_text = str(raw_value).replace(",", "").strip()
        if not raw_text:
            return None
        try:
            candidate = float(raw_text)
        except Exception:
            return None
        if not math.isfinite(candidate):
            return None
        return float(candidate)

    def _opt_int(raw_value: Any) -> Optional[int]:
        """Return integer value or None for optional Ledger integer fields."""
        if raw_value in (None, ""):
            return None
        raw_text = str(raw_value).replace(",", "").strip()
        if not raw_text:
            return None
        try:
            candidate = int(raw_text)
        except Exception:
            return None
        return int(candidate)

    normalized_rows: List[Dict[str, Any]] = []
    rows = value if isinstance(value, list) else []
    # Iterate over persisted ledger rows and retain only valid object payloads.
    for idx, row in enumerate(rows):
        if not isinstance(row, dict):
            continue
        custom_values_raw = row.get("custom_values")
        custom_values_map = custom_values_raw if isinstance(custom_values_raw, Mapping) else {}
        normalized_custom_values: Dict[str, Any] = {}
        # Preserve unknown custom-value keys while normalizing key text.
        for raw_custom_key, raw_custom_value in custom_values_map.items():
            custom_key = str(raw_custom_key or "").strip()
            if not custom_key:
                continue
            normalized_custom_values[custom_key] = raw_custom_value
        row_id = str(row.get("id") or "").strip() or str(uuid.uuid4())
        display_order_raw = _opt_int(row.get("display_order"))
        if display_order_raw is None:
            display_order_raw = int((idx + 1) * 10)
        display_order = max(0, int(display_order_raw))
        normalized_rows.append(
            {
                "id": row_id,
                "profile_name": str(row.get("profile_name") or "").strip(),
                "project_number": str(row.get("project_number") or "").strip(),
                "batch_number": str(row.get("batch_number") or "").strip(),
                "item_number": str(row.get("item_number") or "").strip(),
                "run_date": str(row.get("run_date") or "").strip(),
                "final_mass_g": _opt_float(row.get("final_mass_g")),
                "final_pH": _opt_float(row.get("final_pH")),
                "cycles": _opt_int(row.get("cycles")),
                "total_dp_uptake": _opt_float(row.get("total_dp_uptake")),
                "theoretical_yield_g": _opt_float(row.get("theoretical_yield_g")),
                "actual_yield_pct": _opt_float(row.get("actual_yield_pct")),
                "notes": str(row.get("notes") or "").strip(),
                "updated_at": str(row.get("updated_at") or "").strip(),
                "display_order": int(display_order),
                "custom_values": dict(normalized_custom_values),
            }
        )
    return normalized_rows


def _normalize_final_report_split_frac(value: Any, default: float = 0.60) -> float:
    """Normalize the Final Report split fraction preference.

    Purpose:
        Coerce persisted Final Report pane split ratios into safe bounds.
    Why:
        Invalid, missing, or out-of-range fractions can hide controls in either
        pane and make the sash position unstable at startup.
    Args:
        value: Raw settings value for `final_report_split_frac`.
        default: Fallback fraction used when value is missing/invalid.
    Returns:
        float: Clamped split fraction in the inclusive range `[0.40, 0.85]`.
    Side Effects:
        None.
    Exceptions:
        Non-numeric values fall back to `default` before clamping.
    """
    try:
        candidate = float(value)
    except Exception:
        candidate = float(default)
    if not math.isfinite(candidate):
        candidate = float(default)
    return max(0.40, min(0.85, candidate))


def _normalize_core_render_cycle_side_effects_mode(value: Any) -> str:
    """Normalize the core-render cycle side-effects mode.

    Purpose:
        Coerce stored or UI-provided side-effects mode values into one
        supported setting.
    Why:
        Core render scheduling now conditionally runs cycle-analysis side
        effects; unsupported values must fail safely to a deterministic mode.
    Args:
        value: Incoming mode candidate from settings or UI.
    Returns:
        str: One of `"auto"`, `"always"`, or `"never"`.
    Side Effects:
        None.
    Exceptions:
        Invalid or missing values are normalized to `"auto"`.
    """
    normalized = str(value or "").strip().lower()
    if normalized not in {"auto", "always", "never"}:
        return "auto"
    return normalized


def _normalize_requested_core_plot_keys(value: Any) -> Tuple[str, ...]:
    """Normalize the requested core plot-key collection.

    Purpose:
        Coerce caller-provided core-plot key collections into one canonical
        ordered tuple.
    Why:
        Core render snapshots and UI rendering need deterministic requested-key
        semantics for selective figure generation.
    Args:
        value: Optional iterable containing requested core plot keys.
    Returns:
        Tuple[str, ...]: Ordered unique keys from `fig1`, `fig2`, `fig_peaks`.
    Side Effects:
        None.
    Exceptions:
        Invalid inputs return an empty tuple.
    """
    if value is None:
        return ()
    allowed = ("fig1", "fig2", "fig_peaks")
    try:
        raw_values = list(value)
    except Exception:
        return ()
    normalized: List[str] = []
    seen: Set[str] = set()
    # Preserve caller order while dropping unsupported/duplicate entries.
    for raw_item in raw_values:
        key = str(raw_item or "").strip().lower()
        if key not in allowed:
            continue
        if key in seen:
            continue
        normalized.append(key)
        seen.add(key)
    return tuple(normalized)


def _normalize_debug_categories(value: Any) -> Dict[str, bool]:
    """Normalize debug categories for persistence.

    Purpose:
        Coerce the stored debug category map into a full, known-key dictionary.
    Why:
        Keeps debug toggle persistence stable across upgrades and prevents
        missing keys from breaking Developer Tools toggles.
    Args:
        value: Incoming settings value, expected to be a dict[str, bool].
    Returns:
        Dict[str, bool] containing all DEBUG_CATEGORIES with boolean values.
    Side Effects:
        None.
    Exceptions:
        Falls back to defaults when input types are invalid.
    """
    normalized: Dict[str, bool] = {}
    if isinstance(value, dict):
        # Iterate over DEBUG_CATEGORIES to apply the per-item logic.
        for name in DEBUG_CATEGORIES:
            normalized[name] = bool(value.get(name, False))
    else:
        for name in DEBUG_CATEGORIES:
            normalized[name] = False
    return normalized


def _normalize_combined_svg_export_settings(value: Any) -> dict[str, Any]:
    """Normalize combined triple-axis SVG reduction settings.

    Purpose:
        Coerce persisted or UI-provided SVG export settings into one safe schema.
    Why:
        Developer Tools can expose experimental size-reduction options, so export
        code needs deterministic bounds before mutating Matplotlib artists.
    Args:
        value: Mapping-like settings payload, usually the global settings dict.
    Returns:
        Dict containing reduction mode, max vector points per trace, and raster
        DPI values ready to persist or apply.
    Side Effects:
        None.
    Exceptions:
        Invalid or malformed values fall back to conservative defaults.
    """
    source = value if isinstance(value, Mapping) else {}
    raw_mode = (
        str(
            source.get(
                COMBINED_SVG_REDUCTION_MODE_SETTINGS_KEY,
                DEFAULT_COMBINED_SVG_REDUCTION_MODE,
            )
            or DEFAULT_COMBINED_SVG_REDUCTION_MODE
        )
        .strip()
        .lower()
    )
    label_to_mode = {
        str(label).strip().lower(): mode
        for mode, label in COMBINED_SVG_REDUCTION_LABELS.items()
    }
    mode = label_to_mode.get(raw_mode, raw_mode)
    if mode not in COMBINED_SVG_REDUCTION_MODES:
        mode = DEFAULT_COMBINED_SVG_REDUCTION_MODE

    try:
        max_points = int(
            float(
                source.get(
                    COMBINED_SVG_MAX_POINTS_SETTINGS_KEY,
                    DEFAULT_COMBINED_SVG_MAX_POINTS,
                )
            )
        )
    except Exception:
        max_points = DEFAULT_COMBINED_SVG_MAX_POINTS
    max_points = max(
        MIN_COMBINED_SVG_MAX_POINTS,
        min(MAX_COMBINED_SVG_MAX_POINTS, int(max_points)),
    )

    try:
        raster_dpi = int(
            float(
                source.get(
                    COMBINED_SVG_RASTER_DPI_SETTINGS_KEY,
                    DEFAULT_COMBINED_SVG_RASTER_DPI,
                )
            )
        )
    except Exception:
        raster_dpi = DEFAULT_COMBINED_SVG_RASTER_DPI
    raster_dpi = max(
        MIN_COMBINED_SVG_RASTER_DPI,
        min(MAX_COMBINED_SVG_RASTER_DPI, int(raster_dpi)),
    )
    return {
        COMBINED_SVG_REDUCTION_MODE_SETTINGS_KEY: mode,
        COMBINED_SVG_MAX_POINTS_SETTINGS_KEY: max_points,
        COMBINED_SVG_RASTER_DPI_SETTINGS_KEY: raster_dpi,
    }


def _sanitize_workspace_profile_name(value: Any) -> str:
    """Normalize a persisted workspace-profile name.

    Purpose:
        Canonicalize stored profile names before path resolution and validation.
    Why:
        Persisted profile identity must match filename-safe naming rules used by
        the profile manager so startup validation is deterministic.
    Args:
        value: Raw settings value for the current workspace profile name.
    Returns:
        A sanitized profile name string, or an empty string when invalid.
    Side Effects:
        None.
    Exceptions:
        Invalid or non-string-like values normalize to an empty string.
    """
    if value is None:
        return ""
    cleaned = str(value).strip()
    cleaned = re.sub(r"[<>:\"/\\\\|?*]", "_", cleaned)
    cleaned = re.sub(r"\s+", " ", cleaned)
    return cleaned.strip(" .")


def _workspace_profile_expected_path(name: str) -> Optional[Path]:
    """Build the canonical profile JSON path for a profile name.

    Purpose:
        Derive the one valid on-disk location for a managed workspace profile.
    Why:
        Current-profile tracking should be anchored to the same `profiles/`
        directory contract used by the profile manager.
    Args:
        name: Candidate profile name.
    Returns:
        Canonical `Path` for `profiles/<name>.json`, or None when name is empty.
    Side Effects:
        None.
    Exceptions:
        None.
    """
    safe_name = _sanitize_workspace_profile_name(name)
    if not safe_name:
        return None
    base_dir = Path(__file__).resolve().parent
    return base_dir / "profiles" / f"{safe_name}.json"


def _normalize_current_workspace_profile_settings(settings_dict: Dict[str, Any]) -> None:
    """Normalize and validate persisted current-profile settings.

    Purpose:
        Ensure current-profile name/path settings are internally consistent.
    Why:
        Startup should not keep stale profile pointers after profile rename,
        delete, or manual settings edits.
    Args:
        settings_dict: Live settings dictionary loaded from `settings.json`.
    Returns:
        None.
    Side Effects:
        Mutates `settings_dict` keys:
        - `current_workspace_profile_name`
        - `current_workspace_profile_path`
    Exceptions:
        Invalid or missing values are cleared to empty strings.
    """
    if not isinstance(settings_dict, dict):
        return
    raw_name = settings_dict.get("current_workspace_profile_name", "")
    raw_path = str(settings_dict.get("current_workspace_profile_path", "") or "").strip()
    safe_name = _sanitize_workspace_profile_name(raw_name)
    expected_path = _workspace_profile_expected_path(safe_name)
    if not safe_name or expected_path is None:
        settings_dict["current_workspace_profile_name"] = ""
        settings_dict["current_workspace_profile_path"] = ""
        return
    expected_str = str(expected_path)
    if not expected_path.exists():
        settings_dict["current_workspace_profile_name"] = ""
        settings_dict["current_workspace_profile_path"] = ""
        return
    if raw_path:
        try:
            raw_resolved = Path(raw_path).resolve()
            expected_resolved = expected_path.resolve()
        except Exception:
            settings_dict["current_workspace_profile_name"] = ""
            settings_dict["current_workspace_profile_path"] = ""
            return
        if raw_resolved != expected_resolved:
            settings_dict["current_workspace_profile_name"] = ""
            settings_dict["current_workspace_profile_path"] = ""
            return
    settings_dict["current_workspace_profile_name"] = safe_name
    settings_dict["current_workspace_profile_path"] = expected_str

if os.path.exists(SETTINGS_FILE):

    loaded_settings = None

    try:

        with open(SETTINGS_FILE, "r", encoding="utf-8") as f:

            loaded_settings = json.load(f)

        if not isinstance(loaded_settings, dict):

            raise ValueError("Settings file must contain a JSON object.")

    except Exception as exc:

        _SETTINGS_LOAD_ERROR = exc

        try:

            timestamp = time.strftime("%Y%m%d-%H%M%S")

            backup_name = f"{SETTINGS_FILE}.corrupt-{timestamp}"

            shutil.move(SETTINGS_FILE, backup_name)

            _SETTINGS_BACKUP_PATH = backup_name

        except Exception:

            _SETTINGS_BACKUP_PATH = None

        settings = {}

    else:

        settings = loaded_settings

    settings["debug_enabled"] = bool(settings.get("debug_enabled", False))
    settings["debug_categories"] = _normalize_debug_categories(
        settings.get("debug_categories")
    )
    settings["debug_file_logging_enabled"] = bool(
        settings.get("debug_file_logging_enabled", False)
    )
    _apply_rust_runtime_settings_defaults(settings)

    def _coerce_setting_float(value, fallback):
        """Coerce setting float.
        Used to force setting float into a safe type or range."""
        try:
            candidate = float(value)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            return fallback
        if not math.isfinite(candidate):
            return fallback
        return candidate

    _starting_material_key_map = {
        "product_preset": "starting_material_preset",
        "product_name": "starting_material_name",
        "product_formula": "starting_material_formula",
        "product_molar_mass": "starting_material_mw_g_mol",
        "starting_mass": "starting_material_mass_g",
    }
    # Iterate over items from _starting_material_key_map to apply the per-item logic.
    for old_key, new_key in _starting_material_key_map.items():
        if new_key not in settings and old_key in settings:
            settings[new_key] = settings.get(old_key)

    raw_name = settings.get("starting_material_name")
    if not isinstance(raw_name, str):
        settings["starting_material_name"] = DEFAULT_STARTING_MATERIAL_NAME

    raw_formula = settings.get("starting_material_formula")
    if not isinstance(raw_formula, str):
        settings["starting_material_formula"] = DEFAULT_STARTING_MATERIAL_FORMULA

    raw_display_name = settings.get("starting_material_display_name")
    if not isinstance(raw_display_name, str):
        settings["starting_material_display_name"] = DEFAULT_STARTING_MATERIAL_DISPLAY_NAME

    raw_display_note = settings.get("starting_material_display_note")
    if not isinstance(raw_display_note, str):
        settings["starting_material_display_note"] = DEFAULT_STARTING_MATERIAL_DISPLAY_NOTE

    settings["starting_material_mw_g_mol"] = _coerce_setting_float(
        settings.get("starting_material_mw_g_mol"),
        DEFAULT_STARTING_MATERIAL_MOLAR_MASS,
    )
    settings["starting_material_mass_g"] = _coerce_setting_float(
        settings.get("starting_material_mass_g"),
        settings.get("starting_mass", settings.get("naoh_mass", 0.0)),
    )
    settings["stoich_mol_gas_per_mol_starting"] = _coerce_setting_float(
        settings.get("stoich_mol_gas_per_mol_starting"),
        DEFAULT_STOICH_MOL_GAS_PER_MOL_STARTING,
    )
    settings[REACTION_CATALOG_SETTINGS_KEY] = _normalize_reaction_catalog(
        settings.get(REACTION_CATALOG_SETTINGS_KEY)
    )
    legacy_selected_reaction = str(
        settings.get("selected_reaction_id", settings.get("starting_material_preset", DEFAULT_SELECTED_REACTION_ID))
        or ""
    ).strip()
    if legacy_selected_reaction not in settings[REACTION_CATALOG_SETTINGS_KEY]:
        legacy_selected_reaction = DEFAULT_SELECTED_REACTION_ID
    settings["selected_reaction_id"] = legacy_selected_reaction
    final_report_reaction_id = str(
        settings.get("final_report_selected_reaction_id", legacy_selected_reaction) or ""
    ).strip()
    if final_report_reaction_id not in settings[REACTION_CATALOG_SETTINGS_KEY]:
        final_report_reaction_id = legacy_selected_reaction
