def _collect_gl260_legends(fig: Optional[Figure]) -> List[Any]:
    """Collect gl260 legends.
    Used to gather gl260 legends into a structured payload."""
    if fig is None:
        return []
    legends: List[Any] = []
    seen = set()
    try:
        from matplotlib.legend import Legend
    except Exception:
        Legend = None

    # Closure captures _collect_gl260_legends local context to keep helper logic scoped and invoked directly within _collect_gl260_legends.
    def _is_legend(obj: Any) -> bool:
        """Check whether it is legend.
        Used to gate conditional behavior in the workflow."""
        if obj is None:
            return False
        if Legend is not None:
            return isinstance(obj, Legend)
        return obj.__class__.__name__ == "Legend"

    # Closure captures _collect_gl260_legends local context to keep helper logic scoped and invoked directly within _collect_gl260_legends.
    def _add_legend(obj: Any) -> None:
        """Perform add legend.
        Used to keep the workflow logic localized and testable."""
        if not _is_legend(obj):
            return
        obj_id = id(obj)
        if obj_id in seen:
            return
        seen.add(obj_id)
        legends.append(obj)

    try:
        # Iterate over getattr(fig, "legends", []) or [] to apply the per-item logic.
        for lg in getattr(fig, "legends", []) or []:
            _add_legend(lg)
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass
    try:
        # Iterate over getattr(fig, "axes", []) or [] to apply the per-item logic.
        for ax in getattr(fig, "axes", []) or []:
            try:
                _add_legend(ax.get_legend())
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                # Iterate over ax.get_children() to apply the per-item logic.
                for child in ax.get_children():
                    _add_legend(child)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass
    try:
        # Iterate over fig.get_children() to apply the per-item logic.
        for child in fig.get_children():
            _add_legend(child)
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass
    return legends


def _gl260_legend_role(legend: Any) -> Optional[str]:
    """Perform gl260 legend role.
    Used to keep the workflow logic localized and testable."""
    role = getattr(legend, "_gl260_legend_role", None)
    if isinstance(role, str):
        role_value = role.strip().lower()
        if role_value in {"main", "cycle"}:
            return role_value
    if getattr(legend, "_combined_main_legend", False):
        return "main"
    if getattr(legend, "_cycle_overlay_legend", False) or getattr(
        legend, "_combined_cycle_legend", False
    ):
        return "cycle"
    return None


def _legend_text_fontsize(legend: Any) -> Optional[float]:
    """Perform legend text fontsize.
    Used to keep the workflow logic localized and testable."""
    if legend is None:
        return None
    try:
        # Iterate over legend.get_texts() or [] to apply the per-item logic.
        for text in legend.get_texts() or []:
            try:
                size = float(text.get_fontsize())
            except Exception:
                continue
            if math.isfinite(size) and size > 0:
                return size
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass
    try:
        title = legend.get_title()
    except Exception:
        title = None
    if title:
        try:
            size = float(title.get_fontsize())
        except Exception:
            size = None
        if size is not None and math.isfinite(size) and size > 0:
            return size
    return None


def _legend_markerscale_value(legend: Any) -> Optional[float]:
    """Perform legend markerscale value.
    Used to keep the workflow logic localized and testable."""
    if legend is None:
        return None
    scale = getattr(legend, "_gl260_markerscale", None)
    if scale is None:
        getter = getattr(legend, "get_markerscale", None)
        if callable(getter):
            try:
                scale = getter()
            except Exception:
                scale = None
    if scale is None:
        scale = getattr(legend, "_markerscale", None)
    try:
        scale = float(scale)
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        return None
    if not math.isfinite(scale) or scale <= 0:
        return None
    return scale


def _apply_legend_markerscale(legend: Any, target_scale: float) -> None:
    """Apply legend markerscale.
    Used to apply legend markerscale changes to live state."""
    if legend is None:
        return
    try:
        target_scale = float(target_scale)
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        return
    if not math.isfinite(target_scale) or target_scale <= 0:
        return
    prev_scale = _legend_markerscale_value(legend)
    if prev_scale is None or not math.isfinite(prev_scale) or prev_scale <= 0:
        prev_scale = 1.0
    ratio = target_scale / prev_scale
    if abs(ratio - 1.0) < 1e-3:
        try:
            legend._gl260_markerscale = target_scale  # type: ignore[attr-defined]
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            if hasattr(legend, "set_markerscale"):
                legend.set_markerscale(target_scale)
            elif hasattr(legend, "_markerscale"):
                legend._markerscale = target_scale  # type: ignore[attr-defined]
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        return
    # Iterate over getattr(legend, "legendHandles", []) or [] to apply the per-item logic.
    for handle in getattr(legend, "legendHandles", []) or []:
        if handle is None:
            continue
        if hasattr(handle, "get_markersize") and hasattr(handle, "set_markersize"):
            try:
                handle.set_markersize(handle.get_markersize() * ratio)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        elif hasattr(handle, "get_sizes") and hasattr(handle, "set_sizes"):
            try:
                sizes = handle.get_sizes()
            except Exception:
                sizes = None
            if sizes is None:
                continue
            try:
                handle.set_sizes([float(s) * (ratio * ratio) for s in sizes])
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
    try:
        legend._gl260_markerscale = target_scale  # type: ignore[attr-defined]
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass
    try:
        if hasattr(legend, "set_markerscale"):
            legend.set_markerscale(target_scale)
        elif hasattr(legend, "_markerscale"):
            legend._markerscale = target_scale  # type: ignore[attr-defined]
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass


def _resolve_gl260_markerscale(
    legend: Any, target_fontsize: float, prev_fontsize: Optional[float]
) -> Optional[float]:
    """Resolve gl260 markerscale.
    Used to compute gl260 markerscale before rendering or export."""
    if legend is None:
        return None
    if getattr(legend, "_combined_main_legend", False):
        override = _coerce_float(settings.get("combined_legend_markerscale"))
        if override is not None:
            return override
    if getattr(legend, "_combined_cycle_legend", False):
        override = _coerce_float(settings.get("combined_cycle_legend_markerscale"))
        if override is not None:
            return override
    base_font = getattr(legend, "_gl260_markerscale_base_font", None)
    try:
        base_font = float(base_font)
    except Exception:
        base_font = None
    if base_font is not None and math.isfinite(base_font) and base_font > 0:
        return target_fontsize / base_font
    prev_scale = _legend_markerscale_value(legend)
    if prev_scale is None or not math.isfinite(prev_scale) or prev_scale <= 0:
        prev_scale = 1.0
    if prev_fontsize is None or not math.isfinite(prev_fontsize) or prev_fontsize <= 0:
        prev_fontsize = target_fontsize
    if not math.isfinite(target_fontsize) or target_fontsize <= 0:
        return prev_scale
    return prev_scale * (target_fontsize / prev_fontsize)


def _enforce_gl260_legend_sizing(
    fig: Optional[Figure],
    main_fontsize: float,
    cycle_fontsize: float,
    *,
    font_family: Optional[str] = None,
) -> None:
    """Perform enforce gl260 legend sizing.
    Used to keep the workflow logic localized and testable."""
    if fig is None:
        return
    try:
        main_fontsize = float(main_fontsize)
        cycle_fontsize = float(cycle_fontsize)
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        return
    if not math.isfinite(main_fontsize) or not math.isfinite(cycle_fontsize):
        return
    legends = _collect_gl260_legends(fig)
    if not legends:
        return
    family_value = (font_family or "").strip()
    prop_main = (
        font_manager.FontProperties(size=main_fontsize, family=family_value)
        if family_value
        else font_manager.FontProperties(size=main_fontsize)
    )
    prop_cycle = (
        font_manager.FontProperties(size=cycle_fontsize, family=family_value)
        if family_value
        else font_manager.FontProperties(size=cycle_fontsize)
    )
    legend_frame_kwargs = _legend_shadowbox_kwargs()
    legend_facecolor = legend_frame_kwargs.get("facecolor", DEFAULT_LEGEND_SHADOWBOX_FILL_COLOR)
    legend_edgecolor = legend_frame_kwargs.get("edgecolor", "#444")
    legend_alpha = _coerce_float(legend_frame_kwargs.get("framealpha"))
    if legend_alpha is None or not math.isfinite(legend_alpha):
        legend_alpha = 0.9
    # Iterate over legends to apply the per-item logic.
    for legend in legends:
        try:
            frame = legend.get_frame()
            if frame is not None:
                frame.set_facecolor(legend_facecolor)
                frame.set_edgecolor(legend_edgecolor)
                frame.set_alpha(legend_alpha)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        role = _gl260_legend_role(legend)
        if role == "main":
            target_fontsize = main_fontsize
            legend_prop = prop_main
        elif role == "cycle":
            target_fontsize = cycle_fontsize
            legend_prop = prop_cycle
        else:
            continue
        prev_fontsize = _legend_text_fontsize(legend)
        try:
            # Iterate over legend.get_texts() or [] to apply the per-item logic.
            for txt in legend.get_texts() or []:
                txt.set_fontsize(target_fontsize)
                if legend_prop is not None:
                    txt.set_fontproperties(legend_prop)
            title = legend.get_title()
            if title:
                title.set_fontsize(target_fontsize)
                if legend_prop is not None:
                    title.set_fontproperties(legend_prop)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        target_scale = _resolve_gl260_markerscale(
            legend, target_fontsize, prev_fontsize
        )
        if target_scale is not None:
            _apply_legend_markerscale(legend, target_scale)


def _wrap_legend_label(label: str, max_chars: int = 20) -> str:
    """Wrap one legend label for explicit row-wrapped legend layouts.

    Purpose:
        Convert a long legend label into multi-line text only when the caller has
        explicitly requested wrapped labels.
    Why:
        Main combined legends now distinguish row packing from text wrapping, so
        no-wrap auto-fit mode must be able to keep the original label text.
    Inputs:
        label: Raw legend label text.
        max_chars: Approximate maximum characters per wrapped line.
    Outputs:
        Trimmed and optionally wrapped label text.
    Side Effects:
        None.
    Exceptions:
        Invalid labels normalize to an empty string.
    """

    if not label:
        return ""
    trimmed = label.strip()
    if len(trimmed) <= max_chars:
        return trimmed
    return textwrap.fill(
        trimmed,
        width=max_chars,
        break_long_words=False,
        replace_whitespace=False,
    )


def _resolve_combined_main_legend_layout(
    labels: Sequence[Any],
    *,
    legend_wrap: bool,
    legend_rows: Any,
    figure_width_in: Optional[float],
    legend_fontsize: Any,
) -> Dict[str, Any]:
    """Resolve main combined-legend text and column packing.

    Purpose:
        Compute labels, columns, and spacing for the main combined plot legend.
    Why:
        Users expect disabled wrapping to preserve one readable row when it fits,
        while still allowing auto-fit fallback when the row would clip. This
        helper keeps display, preview, export, and in-place refresh behavior
        consistent.
    Inputs:
        labels: Legend label text values in display order.
        legend_wrap: Whether explicit row/text wrapping is enabled.
        legend_rows: Requested row count for explicit wrapping.
        figure_width_in: Figure width in inches used for no-wrap auto-fit.
        legend_fontsize: Legend font size in points.
    Outputs:
        Dict with `labels`, `ncol`, `rows`, `auto_fallback`, `columnspacing`, and
        `handletextpad` keys.
    Side Effects:
        None.
    Exceptions:
        Invalid numeric inputs fall back to bounded defaults.
    """
    normalized_labels = [str(label or "").strip() for label in labels]
    entry_count = len(normalized_labels)
    if entry_count <= 0:
        return {
            "labels": [],
            "ncol": 1,
            "rows": 1,
            "auto_fallback": False,
            "columnspacing": 1.0,
            "handletextpad": 0.5,
        }
    try:
        rows_value = int(legend_rows)
    except (TypeError, ValueError):
        rows_value = 2 if legend_wrap else 1
    rows_value = max(1, rows_value)
    try:
        font_value = float(legend_fontsize)
    except (TypeError, ValueError):
        font_value = DEFAULT_COMBINED_LEGEND_FONTSIZE
    if not math.isfinite(font_value) or font_value <= 0:
        font_value = DEFAULT_COMBINED_LEGEND_FONTSIZE
    try:
        fig_width_pts = max(float(figure_width_in or 0.0) * 72.0, 1.0)
    except (TypeError, ValueError):
        fig_width_pts = 1.0

    if legend_wrap:
        return {
            "labels": [_wrap_legend_label(label) for label in normalized_labels],
            "ncol": max(1, int(math.ceil(entry_count / float(rows_value)))),
            "rows": rows_value,
            "auto_fallback": False,
            "columnspacing": 1.0,
            "handletextpad": 0.5,
        }

    # Estimate the one-row legend footprint before drawing. The constants are
    # intentionally conservative: they model text width plus handle and gap
    # space well enough to decide whether a measured fallback is needed.
    estimated_text_pts = sum(
        len(label) * font_value * 0.52 for label in normalized_labels
    )
    estimated_handle_pts = entry_count * font_value * 2.35
    estimated_total_pts = estimated_text_pts + estimated_handle_pts
    safe_width_pts = max(fig_width_pts * 0.92, fig_width_pts - 36.0)
    if estimated_total_pts <= safe_width_pts or entry_count == 1:
        return {
            "labels": normalized_labels,
            "ncol": entry_count,
            "rows": 1,
            "auto_fallback": False,
            "columnspacing": 0.75,
            "handletextpad": 0.35,
        }

    try:
        max_auto_rows = int(settings.get("combined_legend_auto_fit_max_rows", 3))
    except Exception:
        max_auto_rows = 3
    max_auto_rows = max(2, min(6, max_auto_rows, entry_count))
    resolved_rows = max_auto_rows
    return {
        "labels": normalized_labels,
        "ncol": max(1, int(math.ceil(entry_count / float(resolved_rows)))),
        "rows": resolved_rows,
        "auto_fallback": True,
        "columnspacing": 0.75,
        "handletextpad": 0.35,
    }


def _normalize_legend_alignment(alignment: Optional[str]) -> str:
    """Normalize legend alignment.
    Used to keep legend alignment consistent across workflows and persistence."""

    candidate = (alignment or "").strip().lower()
    if candidate not in {"left", "center", "right"}:
        return "center"
    return candidate


def _measure_axis_label_extension(axis: Optional[Axes], renderer) -> float:
    """Perform measure axis label extension.
    Used to keep the workflow logic localized and testable."""

    if axis is None:
        return 0.0
    try:
        label = axis.yaxis.get_label()
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        return 0.0
    if label is None:
        return 0.0
    try:
        bbox = label.get_window_extent(renderer=renderer)
        if bbox is None:
            return 0.0
        fig_bbox = bbox.transformed(axis.figure.transFigure.inverted())
        axis_bottom = axis.get_position().y0
        return max(0.0, axis_bottom - fig_bbox.y0)
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        return 0.0


def _apply_legend_anchor_to_artist(
    legend_obj,
    anchor_values,
    *,
    target_ax: Optional[Axes] = None,
    transform=None,
    loc_override=None,
) -> bool:
    """Apply legend anchor to artist.
    Used to apply legend anchor to artist changes to live state."""
    if legend_obj is None:
        return False
    resolved_loc = _normalize_legend_loc_value(loc_override)
    if isinstance(resolved_loc, tuple):
        try:
            legend_obj.set_loc(resolved_loc)
        except Exception:
            try:
                legend_obj._loc = resolved_loc  # type: ignore[attr-defined]
            except Exception:
                pass
        return True
    anchor_pair = _validated_anchor_pair(anchor_values)
    if anchor_pair is None:
        return False
    if transform is None and target_ax is not None:
        transform = target_ax.transAxes
    if transform is None:
        try:
            transform = legend_obj.figure.transFigure
        except Exception:
            transform = None
    try:
        if transform is None:
            legend_obj.set_bbox_to_anchor(anchor_pair)
        else:
            legend_obj.set_bbox_to_anchor(anchor_pair, transform=transform)
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        return False
    if resolved_loc is not None:
        try:
            legend_obj.set_loc(resolved_loc)
        except Exception:
            try:
                legend_obj._loc = resolved_loc  # type: ignore[attr-defined]
            except Exception:
                pass
    return True


def _resolve_combined_cycle_ref_axis(
    fig: Optional[Figure],
    ax_main: Optional[Axes] = None,
    ax_right: Optional[Axes] = None,
    ax_deriv: Optional[Axes] = None,
    ref_axis_key: Optional[str] = None,
) -> Optional[Axes]:
    """Resolve combined cycle ref axis.
    Used to compute combined cycle ref axis before rendering or export."""
    ref_axis = _normalize_combined_cycle_ref_axis(ref_axis_key)
    if ref_axis == "main" and ax_main is not None:
        return ax_main
    if ref_axis == "right" and ax_right is not None:
        return ax_right
    if ref_axis == "deriv" and ax_deriv is not None:
        return ax_deriv
    if fig is None:
        return ax_main or ax_right or ax_deriv
    axes = []
    # Iterate over getattr(fig, "axes", []) or [] to apply the per-item logic.
    for axis in getattr(fig, "axes", []) or []:
        if axis is None:
            continue
        if getattr(axis, "_gl260_legend_only", False):
            continue
        axes.append(axis)
    role_map = {"main": "primary", "right": "right", "deriv": "third"}
    desired_role = role_map.get(ref_axis)
    if desired_role:
        # Iterate over axes to apply the per-item logic.
        for axis in axes:
            if getattr(axis, "_gl260_axis_role", None) == desired_role:
                return axis
    if ax_main is not None:
        return ax_main
    return axes[0] if axes else None


def _legend_loc_text(loc_value: Any) -> Optional[str]:
    """Perform legend loc text.
    Used to keep the workflow logic localized and testable."""
    loc_map = {
        0: "best",
        1: "upper right",
        2: "upper left",
        3: "lower left",
        4: "lower right",
        5: "right",
        6: "center left",
        7: "center right",
        8: "lower center",
        9: "upper center",
        10: "center",
    }
    normalized = _normalize_legend_loc_value(loc_value)
    if isinstance(normalized, tuple):
        return None
    if isinstance(normalized, int):
        loc_text = loc_map.get(normalized, "upper right")
    elif isinstance(normalized, str):
        loc_text = normalized.strip().lower() or "upper right"
    else:
        loc_text = "upper right"
    if loc_text == "best":
        loc_text = "upper right"
    return loc_text


def _axis_anchor_point_display(
    axis: Optional[Axes], corner: Optional[str], renderer
) -> Optional[Tuple[float, float]]:
    """Perform axis anchor point display.
    Used to keep the workflow logic localized and testable."""
    if axis is None:
        return None
    try:
        bbox = axis.get_window_extent(renderer=renderer)
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        return None
    if bbox is None:
        return None
    corner_key = _normalize_combined_cycle_ref_corner(corner)
    if corner_key == "upper right":
        return (bbox.x1, bbox.y1)
    if corner_key == "upper left":
        return (bbox.x0, bbox.y1)
    if corner_key == "lower right":
        return (bbox.x1, bbox.y0)
    if corner_key == "lower left":
        return (bbox.x0, bbox.y0)
    return ((bbox.x0 + bbox.x1) / 2.0, (bbox.y0 + bbox.y1) / 2.0)


def _legend_anchor_point_display(legend: Any, loc_value: Any, renderer) -> Optional[
    Tuple[float, float]
]:
    """Perform legend anchor point display.
    Used to keep the workflow logic localized and testable."""
    if legend is None:
        return None
    loc_text = _legend_loc_text(loc_value)
    if loc_text is None:
        return None
    try:
        bbox = legend.get_window_extent(renderer=renderer)
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        return None
    if bbox is None:
        return None
    x0, y0, x1, y1 = bbox.x0, bbox.y0, bbox.x1, bbox.y1
    cx = x0 + ((x1 - x0) / 2.0)
    cy = y0 + ((y1 - y0) / 2.0)
    if loc_text in {"upper left", "ul"}:
        return (x0, y1)
    if loc_text in {"upper center", "uc"}:
        return (cx, y1)
    if loc_text in {"upper right", "ur"}:
        return (x1, y1)
    if loc_text in {"lower left", "ll"}:
        return (x0, y0)
    if loc_text in {"lower center", "lc"}:
        return (cx, y0)
    if loc_text in {"lower right", "lr"}:
        return (x1, y0)
    if loc_text in {"center left", "cl", "left"}:
        return (x0, cy)
    if loc_text in {"center right", "cr", "right"}:
        return (x1, cy)
    return (cx, cy)


def _combined_cycle_axis_offset_values() -> tuple[float, float] | None:
    """Return combined cycle legend axis offsets.

    Purpose:
        Load persisted axis-offset values for the combined cycle legend.
    Why:
        Axis offsets reapply drag placement without introducing extra layout
        passes or altering the export pipeline.

    Args:
        None.

    Returns:
        Tuple of (dx, dy) offsets in pixels, or None when persistence is
        disabled or offsets are missing.

    Side Effects:
        None.

    Exceptions:
        Errors are handled internally and return None.
    """
    try:
        if settings.get("combined_cycle_legend_anchor_mode") == "loc_tuple":
            return None
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        return None
    if not bool(settings.get("combined_cycle_legend_persist_position", True)):
        # Persistence disabled: ignore stored offsets so refresh/rebuild uses defaults.
        return None
    dx = _coerce_float(settings.get("combined_cycle_legend_ref_dx_px"))
    dy = _coerce_float(settings.get("combined_cycle_legend_ref_dy_px"))
    if dx is None or dy is None:
        return None
    return (dx, dy)


def _combined_cycle_legend_identity_from_values(
    trace_key: Any,
    trace_label: Any,
    index: Any,
) -> str | None:
    """Build a stable identity for one combined cycle legend.

    Purpose:
        Resolve a settings key for per-primary cycle legend placement.
    Why:
        Multi-primary cycle legends are separate draggable artists, so their
        positions must persist independently across display and Plot Preview.
    Inputs:
        trace_key: Optional primary trace key from the legend payload.
        trace_label: Optional visible legend title such as ``Cylinder 1``.
        index: Optional zero-based legend index used as a final fallback.
    Outputs:
        String identity key, or None when no usable identity can be derived.
    Side Effects:
        None.
    Exceptions:
        Invalid values are ignored defensively.
    """
    for prefix, raw_value in (("key", trace_key), ("label", trace_label)):
        try:
            value = str(raw_value or "").strip()
        except Exception:
            value = ""
        if value:
            return f"{prefix}:{value}"
    try:
        index_value = int(index)
    except Exception:
        return None
    if index_value < 0:
        return None
    return f"index:{index_value}"


def _combined_cycle_legend_identity(
    legend: Any,
    *,
    fallback_index: int | None = None,
) -> str | None:
    """Resolve the persisted-position key for a cycle legend artist.

    Purpose:
        Identify an existing Matplotlib legend using metadata attached during
        cycle legend construction.
    Why:
        Preview-close synchronization needs to match each dragged legend back to
        the corresponding main-display legend after figures are rebuilt.
    Inputs:
        legend: Legend-like artist to inspect.
        fallback_index: Optional index assigned by the caller when metadata is
            unavailable.
    Outputs:
        String identity key, or None when the legend cannot be identified.
    Side Effects:
        None.
    Exceptions:
        Metadata and title lookup failures are ignored.
    """
    if legend is None:
        return None
    trace_key = getattr(legend, "_gl260_cycle_trace_key", None)
    trace_label = getattr(legend, "_gl260_cycle_trace_label", None)
    if not trace_label:
        try:
            title_obj = legend.get_title()
            trace_label = title_obj.get_text() if title_obj is not None else None
        except Exception:
            trace_label = None
    legend_index = getattr(legend, "_gl260_cycle_legend_index", fallback_index)
    return _combined_cycle_legend_identity_from_values(
        trace_key,
        trace_label,
        legend_index,
    )


def _combined_cycle_legend_positions_setting() -> dict[str, tuple[float, float]]:
    """Return valid per-legend combined cycle positions from settings.

    Purpose:
        Normalize the persisted mapping of cycle legend identity to axes-space
        lower-left coordinates.
    Why:
        Settings are JSON-backed and may contain stale or user-edited values;
        render paths need finite tuples only.
    Inputs:
        None.
    Outputs:
        Dict mapping legend identity strings to ``(x, y)`` axes tuples.
    Side Effects:
        None.
    Exceptions:
        Malformed entries are skipped.
    """
    raw_positions = settings.get("combined_cycle_legend_positions")
    if not isinstance(raw_positions, dict):
        return {}
    positions: dict[str, tuple[float, float]] = {}
    for raw_key, raw_loc in raw_positions.items():
        key = str(raw_key or "").strip()
        normalized_loc = _normalize_legend_loc_value(raw_loc)
        if not key or not isinstance(normalized_loc, tuple) or len(normalized_loc) != 2:
            continue
        try:
            x_val = float(normalized_loc[0])
            y_val = float(normalized_loc[1])
        except Exception:
            continue
        if not (math.isfinite(x_val) and math.isfinite(y_val)):
            continue
        positions[key] = (x_val, y_val)
    return positions


def _resolve_combined_cycle_legend_loc() -> Optional[Union[str, int, Tuple[float, float]]]:
    """Resolve combined cycle legend loc.
    Used to compute combined cycle legend loc before rendering or export."""
    loc_value = _normalize_legend_loc_value(settings.get("combined_cycle_legend_loc"))
    if loc_value is not None:
        return loc_value
    loc_choice = settings.get("combined_cycle_legend_loc_choice", "upper right")
    loc_choice_value = _normalize_legend_loc_value(loc_choice)
    return loc_choice_value or "upper right"


def _compute_cycle_legend_offsets_px(
    legend: Any,
    ref_axis: Optional[Axes],
    ref_corner: Optional[str],
    loc_value: Any,
    renderer,
) -> Optional[Tuple[float, float]]:
    """Compute cycle legend offsets px.
    Used to derive cycle legend offsets px for analysis or plotting."""
    ref_point = _axis_anchor_point_display(ref_axis, ref_corner, renderer)
    legend_point = _legend_anchor_point_display(legend, loc_value, renderer)
    if ref_point is None or legend_point is None:
        return None
    dx = legend_point[0] - ref_point[0]
    dy = legend_point[1] - ref_point[1]
    if not (math.isfinite(dx) and math.isfinite(dy)):
        return None
    return (dx, dy)


def _apply_cycle_legend_axis_offset(
    fig: Figure,
    legend: Any,
    ref_axis: Optional[Axes],
    ref_corner: Optional[str],
    dx: float,
    dy: float,
    loc_value: Any,
    *,
    allow_draw: bool = True,
) -> bool:
    """Apply cycle legend axis offset.
    Used to apply cycle legend axis offset changes to live state."""
    if fig is None or legend is None or ref_axis is None:
        return False
    if fig.canvas is None:
        FigureCanvasAgg(fig)
    if allow_draw:
        try:
            fig.canvas.draw()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
    try:
        renderer = fig.canvas.get_renderer()
    except Exception:
        renderer = None
    if renderer is None:
        return False
    ref_point = _axis_anchor_point_display(ref_axis, ref_corner, renderer)
    if ref_point is None:
        return False
    target_display = (ref_point[0] + dx, ref_point[1] + dy)
    try:
        target_axes = ref_axis.transAxes.inverted().transform(target_display)
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        return False
    loc_text = _legend_loc_text(loc_value)
    if loc_text is None:
        return False
    return _apply_legend_anchor_to_artist(
        legend,
        target_axes,
        transform=ref_axis.transAxes,
        loc_override=loc_text,
    )


def _position_combined_legend(
    fig: Figure,
    ax: Axes,
    legend_ax: Axes,
    legend,
    label_gap_points: float,
    bottom_margin_points: float,
    extra_axes: Optional[Sequence[Axes]] = None,
) -> None:
    """Perform position combined legend.
    Used to keep the workflow logic localized and testable."""

    fig_size = fig.get_size_inches()
    fig_height_in = max(float(fig_size[1]), 1.0)
    fig_height_px = max(fig_height_in * fig.dpi, 1.0)
    fig_height_pts = fig_height_in * 72.0
    gap_frac = (
        _sanitize_spacing_value(
            label_gap_points,
            DEFAULT_COMBINED_LEGEND_GAP_PTS,
            MIN_COMBINED_LEGEND_GAP_PTS,
            MAX_COMBINED_LEGEND_GAP_PTS,
        )
        / fig_height_pts
    )
    bottom_margin_frac = (
        _sanitize_spacing_value(
            bottom_margin_points,
            DEFAULT_COMBINED_LEGEND_MARGIN_PTS,
            MIN_COMBINED_LEGEND_MARGIN_PTS,
            MAX_COMBINED_LEGEND_MARGIN_PTS,
        )
        / fig_height_pts
    )

    renderer = None
    measured_fraction = 0.08
    try:
        canvas = FigureCanvasAgg(fig)
        canvas.draw()
        renderer = canvas.get_renderer()
        legend_bbox = legend.get_window_extent(renderer=renderer)
        measured_fraction = legend_bbox.height / fig_height_px
    except Exception:
        renderer = None
    legend_height = max(0.02, measured_fraction + 0.01)

    axes_to_measure: List[Axes] = [ax]
    if extra_axes:
        axes_to_measure.extend([extra for extra in extra_axes if extra is not None])
    max_label_extension = 0.0
    if renderer is not None:
        # Iterate over axes_to_measure to apply the per-item logic.
        for axis in axes_to_measure:
            max_label_extension = max(
                max_label_extension, _measure_axis_label_extension(axis, renderer)
            )

    main_pos = ax.get_position()
    total_available = max(main_pos.y1 - bottom_margin_frac, 0.3)
    min_main_height = 0.25
    remaining_height = total_available - (
        legend_height + gap_frac + max_label_extension
    )
    if remaining_height < min_main_height:
        deficit = min_main_height - remaining_height
        shrinkable = max(legend_height - 0.02, 0.0)
        reduction = min(deficit, shrinkable)
        legend_height -= reduction
        deficit -= reduction
        remaining_height = total_available - (
            legend_height + gap_frac + max_label_extension
        )
        if deficit > 0 and remaining_height < min_main_height:
            min_gap_frac = (
                (MIN_COMBINED_LEGEND_GAP_PTS / fig_height_pts)
                if fig_height_pts
                else 0.0
            )
            gap_reduction = min(deficit, max(gap_frac - min_gap_frac, 0.0))
            gap_frac = max(gap_frac - gap_reduction, min_gap_frac or 0.0)
            remaining_height = total_available - (
                legend_height + gap_frac + max_label_extension
            )
    main_height = max(remaining_height, 0.12)

    legend_bottom = bottom_margin_frac
    legend_ax.set_position([main_pos.x0, legend_bottom, main_pos.width, legend_height])
    legend_top = legend_bottom + legend_height
    ax_bottom = legend_top + gap_frac + max_label_extension
    ax_height = max(main_pos.y1 - ax_bottom, main_height)
    ax.set_position([main_pos.x0, ax_bottom, main_pos.width, ax_height])

    if extra_axes:
        new_pos = ax.get_position()
        # Iterate over extra_axes to apply the per-item logic.
        for axis in extra_axes:
            if axis is not None:
                axis.set_position(new_pos)


def _apply_combined_horizontal_padding(
    fig: Figure,
    primary_ax: Axes,
    legend_ax: Axes,
    extra_axes: Optional[Sequence[Axes]],
    left_pad_pct: float,
    right_pad_pct: float,
    export_pad_pts: float,
) -> None:
    """Apply combined horizontal padding.
    Used to apply combined horizontal padding changes to live state."""

    extra_axes = list(extra_axes) if extra_axes else []
    try:
        left_pad = max(float(left_pad_pct), 0.0) / 100.0
    except Exception:
        left_pad = 0.0
    try:
        right_pad = max(float(right_pad_pct), 0.0) / 100.0
    except Exception:
        right_pad = 0.0
    try:
        pad_pts = max(float(export_pad_pts), 0.0)
    except Exception:
        pad_pts = DEFAULT_COMBINED_EXPORT_PAD_PTS

    fig_w_in, fig_h_in = fig.get_size_inches()
    pad_frac_x = (pad_pts / 72.0) / fig_w_in if fig_w_in else 0.0
    pad_frac_y = (pad_pts / 72.0) / fig_h_in if fig_h_in else 0.0

    target_left = min(0.98, max(0.0, left_pad + pad_frac_x))
    target_right = max(0.02, min(1.0, 1.0 - right_pad - pad_frac_x))
    target_bottom = max(0.0, pad_frac_y)
    target_top = min(1.0, 1.0 - pad_frac_y)

    overflow_left = overflow_right = 0.0
    overflow_top = overflow_bottom = 0.0
    renderer = None
    try:
        canvas = FigureCanvasAgg(fig)
        canvas.draw()
        renderer = canvas.get_renderer()
    except Exception:
        renderer = None
    if renderer is not None:
        axes_to_check: List[Axes] = [primary_ax, legend_ax, *extra_axes]
        # Iterate over axes_to_check to apply the per-item logic.
        for axis in axes_to_check:
            if axis is None:
                continue
            try:
                tight_bbox = axis.get_tightbbox(renderer)
                if tight_bbox is None:
                    continue
                bbox_fig = tight_bbox.transformed(fig.transFigure.inverted())
                overflow_left = max(overflow_left, max(target_left - bbox_fig.x0, 0.0))
                overflow_right = max(
                    overflow_right, max(bbox_fig.x1 - target_right, 0.0)
                )
                overflow_bottom = max(
                    overflow_bottom, max(target_bottom - bbox_fig.y0, 0.0)
                )
                overflow_top = max(overflow_top, max(bbox_fig.y1 - target_top, 0.0))
            except Exception:
                continue
        title_artists = []
        # Iterate over ("_gl260_title_text", "_gl260_suptitle_text", "_suptitle") to apply the per-item logic.
        for attr in ("_gl260_title_text", "_gl260_suptitle_text", "_suptitle"):
            artist = getattr(fig, attr, None)
            if artist is None or artist in title_artists:
                continue
            title_artists.append(artist)
        # Iterate over title_artists to apply the per-item logic.
        for artist in title_artists:
            try:
                bbox = artist.get_window_extent(renderer=renderer)
                if bbox is None:
                    continue
                bbox_fig = bbox.transformed(fig.transFigure.inverted())
                overflow_left = max(overflow_left, max(target_left - bbox_fig.x0, 0.0))
                overflow_right = max(
                    overflow_right, max(bbox_fig.x1 - target_right, 0.0)
                )
                overflow_bottom = max(
                    overflow_bottom, max(target_bottom - bbox_fig.y0, 0.0)
                )
                overflow_top = max(overflow_top, max(bbox_fig.y1 - target_top, 0.0))
            except Exception:
                continue

    main_pos = primary_ax.get_position()
    legend_pos = legend_ax.get_position()
    total_left = overflow_left + left_pad
    total_right = overflow_right + right_pad
    min_width = 0.32
    target_width = max(main_pos.width - (total_left + total_right), min_width)
    max_x0 = max(target_left, target_right - target_width)
    new_x0 = min(max(main_pos.x0 + total_left - overflow_right, target_left), max_x0)

    min_height = 0.25
    target_height = max(main_pos.height - (overflow_bottom + overflow_top), min_height)
    max_y0 = max(target_bottom, target_top - target_height)
    new_y0 = min(
        max(main_pos.y0 + overflow_bottom - overflow_top, target_bottom), max_y0
    )

    primary_ax.set_position([new_x0, new_y0, target_width, target_height])
    legend_ax.set_position(
        [
            new_x0,
            legend_pos.y0 + overflow_bottom - overflow_top,
            target_width,
            legend_pos.height,
        ]
    )
    if extra_axes:
        # Iterate over extra_axes to apply the per-item logic.
        for axis in extra_axes:
            if axis is None:
                continue
            axis.set_position([new_x0, new_y0, target_width, target_height])


def _layout_health_debug_event(policy: Mapping[str, Any], message: str, *args: Any) -> None:
    """Emit one layout-health debug event under the `plotting.layout` category.

    Purpose:
        Centralize gated debug logging for the layout-health auto-fix engine.
    Why:
        The auto-fix pass can run frequently and should only emit diagnostics when
        both debug logging and the layout-health event toggle are enabled.
    Inputs:
        policy: Normalized layout-health policy mapping.
        message: Logger message format string.
        *args: Optional logger format arguments.
    Outputs:
        None.
    Side Effects:
        Writes one debug line to `_GL260_LOGGER` when gates are enabled.
    Exceptions:
        Logging failures are swallowed to preserve render stability.
    """
    try:
        if not bool(policy.get("layout_health_emit_debug_events", False)):
            return
        if not bool(settings.get("debug_enabled", False)):
            return
        debug_categories = settings.get("debug_categories")
        if not isinstance(debug_categories, Mapping):
            return
        if not bool(debug_categories.get("plotting.layout", False)):
            return
        _GL260_LOGGER.debug("[plotting.layout] " + str(message), *args)
    except Exception:
        # Best-effort guard; ignore logging failures during layout auto-fix.
        pass


def _layout_health_bbox_in_fig(fig: Figure, artist: Any, renderer: Any) -> Optional[Bbox]:
    """Return one artist bounding box transformed into figure coordinates.

    Purpose:
        Provide one shared bbox helper for layout-health checks/fixes.
    Why:
        Bbox extraction can fail for unsupported artists or stale renderers, and
        layout-health checks need safe best-effort behavior.
    Inputs:
        fig: Figure containing the artist.
        artist: Candidate Matplotlib artist to measure.
        renderer: Active renderer used for extent measurement.
    Outputs:
        Figure-space `Bbox` when measurable; otherwise None.
    Side Effects:
        None.
    Exceptions:
        Extent/transform failures return None.
    """
    if fig is None or artist is None or renderer is None:
        return None
    try:
        bbox = artist.get_window_extent(renderer=renderer)
    except Exception:
        return None
    if bbox is None:
        return None
    try:
        return bbox.transformed(fig.transFigure.inverted())
    except Exception:
        return None


def _layout_health_timeline_legends(fig: Figure) -> Dict[str, Any]:
    """Resolve role-tagged timeline legends for layout-health checks.

    Purpose:
        Collect the timeline top/bottom legends by explicit role metadata.
    Why:
        Cycle timeline plots keep top and bottom legends axis-local, so generic
        figure-level legend discovery can miss the legend that controls spacing.
    Inputs:
        fig: Figure to inspect.
    Outputs:
        Dict with `top` and `bottom` legend entries (values may be None).
    Side Effects:
        None.
    Exceptions:
        Legend-inspection failures are ignored.
    """

    resolved: Dict[str, Any] = {"top": None, "bottom": None}
    if fig is None:
        return resolved
    legends = _collect_gl260_legends(fig)
    for legend in legends:
        if legend is None:
            continue
        role_value = (
            str(getattr(legend, "_cycle_timeline_legend_role", "")).strip().lower()
        )
        if role_value == "top" and resolved["top"] is None:
            resolved["top"] = legend
        elif role_value == "bottom" and resolved["bottom"] is None:
            resolved["bottom"] = legend
        if resolved["top"] is not None and resolved["bottom"] is not None:
            break
    if resolved["top"] is not None and resolved["bottom"] is not None:
        return resolved
    try:
        axes = list(fig.get_axes())
    except Exception:
        axes = []
    for axis in axes:
        if axis is None:
            continue
        try:
            legend = axis.get_legend()
        except Exception:
            legend = None
        if legend is None:
            continue
        role_value = (
            str(getattr(legend, "_cycle_timeline_legend_role", "")).strip().lower()
        )
        if role_value == "top" and resolved["top"] is None:
            resolved["top"] = legend
        elif role_value == "bottom" and resolved["bottom"] is None:
            resolved["bottom"] = legend
        if resolved["top"] is not None and resolved["bottom"] is not None:
            break
    return resolved


def _layout_health_primary_legend(fig: Figure, plot_id: Optional[str] = None) -> Any:
    """Resolve the main plot legend artist for layout-health checks.

    Purpose:
        Select the non-cycle legend that controls main bottom spacing.
    Why:
        Combined plots can host both main and cycle legends; whitespace checks must
        target the main legend near the x-axis label.
    Inputs:
        fig: Figure to inspect.
        plot_id: Optional plot identifier for timeline-specific routing.
    Outputs:
        Legend artist or None when unavailable.
    Side Effects:
        None.
    Exceptions:
        Legend-inspection failures are ignored.
    """
    if fig is None:
        return None
    plot_id_norm = str(plot_id or "").strip().lower()
    if plot_id_norm == "fig_cycle_timeline":
        timeline_legends = _layout_health_timeline_legends(fig)
        if timeline_legends.get("bottom") is not None:
            return timeline_legends.get("bottom")
        if timeline_legends.get("top") is not None:
            return timeline_legends.get("top")
    for legend in list(getattr(fig, "legends", []) or []):
        if legend is None:
            continue
        if getattr(legend, "_cycle_overlay_legend", False):
            continue
        legend_role = str(getattr(legend, "_cycle_timeline_legend_role", "")).strip().lower()
        if legend_role in {"top", "bottom"}:
            # Timeline subplot legends are axis-local and should not be treated
            # as figure-level spacing anchors by the generic health fixer.
            continue
        return legend
    try:
        axes = list(fig.get_axes())
    except Exception:
        axes = []
    for axis in axes:
        if axis is None:
            continue
        try:
            legend = axis.get_legend()
        except Exception:
            legend = None
        if legend is None:
            continue
        if getattr(legend, "_cycle_overlay_legend", False):
            continue
        legend_role = str(getattr(legend, "_cycle_timeline_legend_role", "")).strip().lower()
        if legend_role in {"top", "bottom"}:
            # Timeline subplot legends are managed independently per role.
            continue
        return legend
    return None


def _layout_health_artist_has_visible_text(artist: Any) -> bool:
    """Return whether one text artist has visible non-empty label content.

    Purpose:
        Filter axis-label candidates to meaningful artists.
    Why:
        Some shared/twin axes expose empty x-label artists; selecting them makes
        legend/xlabel checks target the wrong geometry.
    Inputs:
        artist: Candidate text-like artist with `get_text`/`get_visible`.
    Outputs:
        bool: True when text is visible and non-empty.
    Side Effects:
        None.
    Exceptions:
        Returns False when accessors are unavailable.
    """
    if artist is None:
        return False
    try:
        if not bool(artist.get_visible()):
            return False
    except Exception:
        return False
    try:
        text_value = str(artist.get_text() or "").strip()
    except Exception:
        return False
    return bool(text_value)


def _layout_health_axis_for_role(fig: Figure, role: str) -> Any:
    """Resolve one visible axis by GL-260 role metadata.

    Purpose:
        Find timeline role-specific axes (`primary`, `right`, `third`) for
        artist-targeted layout checks.
    Why:
        Timeline layout logic uses role metadata to distinguish subplot duties.
    Inputs:
        fig: Figure containing candidate axes.
        role: Requested normalized role value.
    Outputs:
        Axis object or None when unavailable.
    Side Effects:
        None.
    Exceptions:
        Axis inspection failures are ignored.
    """
    if fig is None:
        return None
    role_norm = str(role or "").strip().lower()
    try:
        axes = list(fig.get_axes())
    except Exception:
        axes = []
    for axis in axes:
        if axis is None:
            continue
        if getattr(axis, "_gl260_legend_only", False):
            continue
        try:
            if not bool(axis.get_visible()):
                continue
        except Exception:
            continue
        axis_role = str(getattr(axis, "_gl260_axis_role", "")).strip().lower()
        if axis_role == role_norm:
            return axis
    return None


def _layout_health_authoritative_timeline_bottom(
    fig: Figure,
    mode: str,
    layout_mgr: Optional[Any],
) -> Optional[float]:
    """Return the authoritative profile bottom margin for timeline figures.

    Purpose:
        Detect when the Cycle Speciation Timeline display/export profile owns
        the subplot bottom margin.
    Why:
        Layout-health corrections run after profile application; without this
        guard they can overwrite the user-configured display/export margin and
        make the Matplotlib subplot tool report a different value than Plot
        Settings.
    Inputs:
        fig: Figure being inspected.
        mode: Layout mode string, expected to be `display` or `export`.
        layout_mgr: Optional `PlotLayoutManager` attached to the figure.
    Outputs:
        The authoritative bottom margin as a float when a timeline profile is
        active; otherwise None.
    Side Effects:
        None.
    Exceptions:
        Invalid or unavailable margin metadata returns None.
    """
    if fig is None or layout_mgr is None:
        return None
    mode_key = str(mode or "display").strip().lower()
    if mode_key not in {"display", "export"}:
        return None
    if (
        str(getattr(fig, "_gl260_plot_id", "") or "").strip().lower()
        != "fig_cycle_timeline"
    ):
        return None
    if not bool(getattr(layout_mgr, "margins_authoritative", False)):
        return None
    baseline_bottom = _safe_float(getattr(layout_mgr, "_baseline_bottom", None))
    if baseline_bottom is None or not math.isfinite(float(baseline_bottom)):
        return None
    return max(0.0, min(1.0, float(baseline_bottom)))


def _layout_health_primary_xlabel(fig: Figure, plot_id: Optional[str] = None) -> Any:
    """Resolve the primary x-label artist for layout-health checks.

    Purpose:
        Locate the x-label used for legend-gap and overlap diagnostics.
    Why:
        Combined and non-combined figures store xlabel artists differently; this
        helper keeps lookup consistent for the auto-fix engine.
    Inputs:
        fig: Figure to inspect.
        plot_id: Optional plot identifier for timeline-specific routing.
    Outputs:
        X-label artist or None when unavailable.
    Side Effects:
        None.
    Exceptions:
        Axis inspection failures are ignored.
    """
    if fig is None:
        return None
    artist = getattr(fig, "_gl260_xlabel_text", None)
    if _layout_health_artist_has_visible_text(artist):
        return artist
    plot_id_norm = str(plot_id or "").strip().lower()
    if plot_id_norm == "fig_cycle_timeline":
        timeline_bottom_axis = _layout_health_axis_for_role(fig, "right")
        if timeline_bottom_axis is not None:
            try:
                axis_xlabel = timeline_bottom_axis.xaxis.get_label()
            except Exception:
                axis_xlabel = None
            if _layout_health_artist_has_visible_text(axis_xlabel):
                return axis_xlabel
    try:
        axes = list(fig.get_axes())
    except Exception:
        axes = []
    first_xlabel = None
    for axis in axes:
        if axis is None:
            continue
        if getattr(axis, "_gl260_legend_only", False):
            continue
        try:
            axis_xlabel = axis.xaxis.get_label()
        except Exception:
            continue
        if axis_xlabel is None:
            continue
        if first_xlabel is None:
            first_xlabel = axis_xlabel
        if _layout_health_artist_has_visible_text(axis_xlabel):
            return axis_xlabel
    return first_xlabel


def _layout_health_axis_ticklabels_bbox(
    fig: Figure, axis_obj: Any, renderer: Any
) -> Optional[Bbox]:
    """Return the union bbox for one axis' tick labels in figure coordinates.

    Purpose:
        Measure the occupied footprint of tick labels for overlap checks.
    Why:
        Timeline right-axis label collision detection must compare label bounds
        against visible right-axis tick labels.
    Inputs:
        fig: Figure owning the axis.
        axis_obj: Axis object exposing `get_ticklabels`.
        renderer: Active renderer used for extent measurement.
    Outputs:
        Figure-space `Bbox` covering visible tick labels, else None.
    Side Effects:
        None.
    Exceptions:
        Tick-label extent failures are ignored per label.
    """
    if fig is None or axis_obj is None or renderer is None:
        return None
    try:
        ticklabels = list(axis_obj.get_ticklabels())
    except Exception:
        ticklabels = []
    bboxes: List[Bbox] = []
    for tick_label in ticklabels:
        if tick_label is None:
            continue
        try:
            if not tick_label.get_visible():
                continue
        except Exception:
            continue
        try:
            label_bbox = tick_label.get_window_extent(renderer=renderer)
        except Exception:
            label_bbox = None
        if label_bbox is None:
            continue
        try:
            bboxes.append(label_bbox.transformed(fig.transFigure.inverted()))
        except Exception:
            continue
    if not bboxes:
        return None
    try:
        return Bbox.union(bboxes)
    except Exception:
        return None


def _layout_health_primary_xticklabels_bbox(
    fig: Figure, plot_id: Optional[str], renderer: Any
) -> Optional[Bbox]:
    """Return primary x-axis tick-label bounds for layout-health checks.

    Purpose:
        Locate the visible bottom x tick labels that can collide with legends.
    Why:
        Plot Preview layout health must check x-axis tick-label collisions on
        all plot types, not only the cycle timeline's bottom subplot.
    Inputs:
        fig: Figure containing candidate axes.
        plot_id: Optional plot identifier used for timeline role routing.
        renderer: Active Matplotlib renderer used for text extent measurement.
    Outputs:
        Figure-space `Bbox` covering the selected x tick labels, or None.
    Side Effects:
        None.
    Exceptions:
        Axis inspection failures are ignored and treated as unavailable labels.
    """
    if fig is None or renderer is None:
        return None
    plot_id_norm = str(plot_id or "").strip().lower()
    if plot_id_norm == "fig_cycle_timeline":
        bottom_axis = _layout_health_axis_for_role(fig, "right")
        if bottom_axis is not None:
            return _layout_health_axis_ticklabels_bbox(fig, bottom_axis.xaxis, renderer)
    try:
        axes = list(fig.get_axes())
    except Exception:
        axes = []
    candidates: List[Tuple[float, Bbox]] = []
    for axis in axes:
        if axis is None or getattr(axis, "_gl260_legend_only", False):
            continue
        try:
            if not bool(axis.get_visible()):
                continue
        except Exception:
            continue
        bbox = _layout_health_axis_ticklabels_bbox(fig, axis.xaxis, renderer)
        if bbox is None:
            continue
        # Prefer the lowest visible x tick labels because they define bottom
        # spacing and collide with lower legends first.
        candidates.append((float(bbox.y0), bbox))
    if not candidates:
        return None
    candidates.sort(key=lambda item: item[0])
    return candidates[0][1]


def _format_cycle_legend_number(value: Any, precision: int = 2) -> str:
    """Format one numeric cycle-legend value with comma grouping.

    Purpose:
        Provide consistent display formatting for cycle legend numeric values.
    Why:
        Cycle summaries can exceed thousands and should remain readable without
        changing stored data or calculation precision.
    Inputs:
        value: Candidate numeric value to format.
        precision: Number of decimal places for finite floats.
    Outputs:
        Formatted text with comma thousands separators, or `N/A`.
    Side Effects:
        None.
    Exceptions:
        Invalid or non-finite values return `N/A`.
    """
    numeric_value = _safe_float(value, float("nan"))
    try:
        precision_value = max(0, int(precision))
    except Exception:
        precision_value = 2
    if numeric_value is None or not math.isfinite(float(numeric_value)):
        return "N/A"
    return f"{float(numeric_value):,.{precision_value}f}"


def _format_cycle_legend_count(value: Any) -> str:
    """Format one cycle count with comma grouping.

    Purpose:
        Keep cycle-count legend rows readable for large datasets.
    Why:
        Count display should use the same thousands separator policy as other
        cycle legend values while preserving integer semantics.
    Inputs:
        value: Candidate cycle count.
    Outputs:
        Integer count text with comma thousands separators, or `0`.
    Side Effects:
        None.
    Exceptions:
        Invalid values fall back to zero.
    """
    try:
        count_value = int(value)
    except Exception:
        count_value = 0
    return f"{count_value:,}"


def _combined_axis_semantic_from_key(value: Any) -> Optional[str]:
    """Return the semantic axis family for one combined plot dataset key.

    Purpose:
        Translate persisted combined-axis dataset keys into semantic layout
        buckets (`temperature`, `derivative`, or `primary`).
    Why:
        Combined Plot Settings can swap the inner and detached right axes, so
        layout-health fixes must target the data role instead of assuming that
        the `right` role always means temperature and `third` always means
        derivative.
    Inputs:
        value: Candidate combined dataset key such as `y2`, `z`, or `z2`.
    Outputs:
        Optional semantic axis token; None when the key is unknown.
    Side Effects:
        None.
    Exceptions:
        None; invalid values return None.
    """
    candidate = str(value or "").strip().lower()
    if candidate == "y2":
        return "derivative"
    if candidate in {"z", "z2"}:
        return "temperature"
    if candidate in {"y1", "y3"}:
        return "primary"
    return None


def _combined_axis_semantic_from_axis(axis: Any) -> Optional[str]:
    """Return semantic metadata stored on a combined plot axis.

    Purpose:
        Resolve the semantic family attached to a Matplotlib axis.
    Why:
        Layout-health measurement operates on rendered axes and needs a stable
        way to distinguish derivative and temperature labels after role swaps.
    Inputs:
        axis: Matplotlib axis object that may carry GL-260 metadata.
    Outputs:
        Optional semantic token (`temperature`, `derivative`, or `primary`).
    Side Effects:
        None.
    Exceptions:
        Attribute lookup failures return None.
    """
    try:
        semantic = str(getattr(axis, "_gl260_axis_semantic", "") or "").strip().lower()
    except Exception:
        semantic = ""
    if semantic in {"temperature", "derivative", "primary"}:
        return semantic
    return _combined_axis_semantic_from_key(
        getattr(axis, "_gl260_axis_dataset_key", None)
    )


def _layout_health_combined_axis_metrics(
    fig: Figure, renderer: Any
) -> Dict[str, Dict[str, Any]]:
    """Measure visible combined axis label, tick, and spine geometry.

    Purpose:
        Collect role, semantic, bbox, labelpad, and spine-offset data for the
        primary, inner right, and detached right axes of a combined figure.
    Why:
        Combined Plot Preview/export failures depend on actual rendered text
        bounds, not only configured padding values. This helper creates one
        deterministic geometry payload for auto-fix and diagnostics, including
        the primary pressure axis that can be clipped by a too-small left margin.
    Inputs:
        fig: Combined triple-axis figure to inspect.
        renderer: Active Matplotlib renderer used for bbox measurement.
    Outputs:
        Dict keyed by axis role (`primary`, `right`, `third`) with measured
        geometry fields, including label/tick boxes and right-spine coordinates
        where applicable.
    Side Effects:
        None.
    Exceptions:
        Invalid or hidden axes are skipped.
    """
    metrics: Dict[str, Dict[str, Any]] = {}
    if fig is None or renderer is None:
        return metrics
    for role in ("primary", "right", "third"):
        axis = _layout_health_axis_for_role(fig, role)
        if axis is None:
            continue
        try:
            axis_pos = axis.get_position()
        except Exception:
            axis_pos = None
        try:
            label_artist = axis.yaxis.get_label()
        except Exception:
            label_artist = None
        label_bbox = _layout_health_bbox_in_fig(fig, label_artist, renderer)
        ticks_bbox = _layout_health_axis_ticklabels_bbox(fig, axis.yaxis, renderer)
        spine_offset = None
        if role in {"right", "third"}:
            try:
                spine_pos = axis.spines["right"].get_position()
                if (
                    isinstance(spine_pos, tuple)
                    and len(spine_pos) >= 2
                    and str(spine_pos[0]).strip().lower() == "axes"
                ):
                    spine_offset = float(spine_pos[1])
            except Exception:
                spine_offset = None
        spine_x_fig = None
        if axis_pos is not None and spine_offset is not None:
            try:
                spine_x_fig = float(axis_pos.x0) + (
                    float(axis_pos.width) * float(spine_offset)
                )
            except Exception:
                spine_x_fig = None
        semantic = _combined_axis_semantic_from_axis(axis)
        metrics[role] = {
            "axis": axis,
            "axis_pos": axis_pos,
            "label_bbox": label_bbox,
            "ticks_bbox": ticks_bbox,
            "spine_offset": spine_offset,
            "spine_x_fig": spine_x_fig,
            "semantic": semantic,
            "labelpad": getattr(getattr(axis, "yaxis", None), "labelpad", None),
        }
    return metrics


def _layout_health_combined_right_axis_metrics(
    fig: Figure, renderer: Any
) -> Dict[str, Dict[str, Any]]:
    """Return combined right-side axis metrics for compatibility callers.

    Purpose:
        Provide the historical right/third-only geometry payload.
    Why:
        Older layout-health callers and regression tests expect this helper name
        to only expose right-side axes, while the newer full-axis helper also
        measures the primary pressure axis for left-margin clipping checks.
    Inputs:
        fig: Combined triple-axis figure to inspect.
        renderer: Active Matplotlib renderer used for bbox measurement.
    Outputs:
        Dict keyed by `right` and/or `third` with measured geometry fields.
    Side Effects:
        None.
    Exceptions:
        Invalid or hidden axes are skipped by the delegated helper.
    """
    all_metrics = _layout_health_combined_axis_metrics(fig, renderer)
    return {
        role: payload
        for role, payload in all_metrics.items()
        if role in {"right", "third"}
    }


def _layout_health_record_combined_suggestion(
    fig: Figure,
    mode: str,
    *,
    detached_spine_offset: Optional[float] = None,
    margins: Optional[Mapping[str, float]] = None,
    axis_labelpads: Optional[Mapping[str, float]] = None,
    xlabel_pad_pts: Optional[float] = None,
) -> Dict[str, Any]:
    """Store one non-persistent combined layout suggestion on the figure.

    Purpose:
        Preserve measured auto-fix outputs for later review/apply UI actions.
    Why:
        Combined render auto-fixes must improve the current figure immediately
        while leaving saved Plot Settings untouched until the user explicitly
        applies the suggestion.
    Inputs:
        fig: Combined plot figure receiving suggestion metadata.
        mode: Layout mode (`display` or `export`) that produced the suggestion.
        detached_spine_offset: Optional detached-axis spine offset in axes units.
        margins: Optional subplot margin payload.
        axis_labelpads: Optional semantic axis-label padding payload; supports
            `x`, `primary`, `right`, `third`, `temperature`, and `derivative`.
        xlabel_pad_pts: Optional x-label padding in points.
    Outputs:
        The mode-specific suggestion dict stored on the figure.
    Side Effects:
        Mutates `fig._gl260_combined_layout_suggestions`.
    Exceptions:
        Invalid values are ignored; an empty suggestion may be returned.
    """
    mode_key = "export" if str(mode or "").strip().lower() == "export" else "display"
    suggestions = getattr(fig, "_gl260_combined_layout_suggestions", None)
    if not isinstance(suggestions, dict):
        suggestions = {}
        try:
            fig._gl260_combined_layout_suggestions = suggestions  # type: ignore[attr-defined]
        except Exception:
            return {}
    suggestion = suggestions.setdefault(mode_key, {})
    if detached_spine_offset is not None:
        try:
            offset_value = float(detached_spine_offset)
        except Exception:
            offset_value = None
        if offset_value is not None and math.isfinite(offset_value):
            suggestion["detached_spine_offset"] = float(offset_value)
    if isinstance(margins, Mapping):
        current = suggestion.get("margins") if isinstance(suggestion, dict) else None
        next_margins = dict(current) if isinstance(current, Mapping) else {}
        for key in ("left", "right", "top", "bottom"):
            if key not in margins:
                continue
            try:
                value = float(margins[key])
            except Exception:
                continue
            if math.isfinite(value):
                next_margins[key] = max(0.0, min(1.0, value))
        if next_margins:
            suggestion["margins"] = next_margins
    if isinstance(axis_labelpads, Mapping):
        pads = suggestion.get("axis_labelpads")
        next_pads = dict(pads) if isinstance(pads, Mapping) else {}
        for key, raw_value in axis_labelpads.items():
            semantic_key = str(key or "").strip().lower()
            if semantic_key not in {
                "x",
                "primary",
                "temperature",
                "derivative",
                "right",
                "third",
            }:
                continue
            try:
                value = float(raw_value)
            except Exception:
                continue
            if math.isfinite(value):
                next_pads[semantic_key] = float(value)
        if next_pads:
            suggestion["axis_labelpads"] = next_pads
    if xlabel_pad_pts is not None:
        try:
            xlabel_pad_value = float(xlabel_pad_pts)
        except Exception:
            xlabel_pad_value = None
        if xlabel_pad_value is not None and math.isfinite(xlabel_pad_value):
            suggestion["xlabel_pad_pts"] = float(xlabel_pad_value)
    return suggestion


def _layout_health_bbox_overlap_area(lhs: Optional[Bbox], rhs: Optional[Bbox]) -> float:
    """Return overlap area between two figure-space bounding boxes.

    Purpose:
        Provide one shared overlap metric for layout conflict checks.
    Why:
        Timeline legend checks need deterministic overlap tests against xlabel and
        x-tick regions in addition to simple gap thresholds.
    Inputs:
        lhs: First figure-space bbox.
        rhs: Second figure-space bbox.
    Outputs:
        float: Non-negative overlap area in figure-fraction units.
    Side Effects:
        None.
    Exceptions:
        Invalid/missing boxes return 0.0.
    """
    if lhs is None or rhs is None:
        return 0.0
    overlap_x = max(
        0.0,
        min(float(lhs.x1), float(rhs.x1)) - max(float(lhs.x0), float(rhs.x0)),
    )
    overlap_y = max(
        0.0,
        min(float(lhs.y1), float(rhs.y1)) - max(float(lhs.y0), float(rhs.y0)),
    )
    return float(overlap_x * overlap_y)


def _layout_health_general_figure_audit(
    fig: Figure,
    plot_id: Optional[str],
    renderer: Any,
    *,
    fig_w_pts: float,
    fig_h_pts: float,
    min_gap_pts: float,
    max_gap_pts: float,
    min_axis_label_tick_gap_pts: float,
    max_axis_label_tick_gap_pts: float,
) -> Dict[str, Any]:
    """Audit one rendered figure for general layout conflicts.

    Purpose:
        Inspect visible axes, labels, tick labels, legends, and text artists for
        overlaps, clipping, and excessive spacing that specialized checks miss.
    Why:
        The Layout Health Wizard must be systematic across main plots, generated
        tabs, previews, and Advanced Speciation timelines instead of relying on a
        few plot-specific heuristics.
    Inputs:
        fig: Rendered figure to inspect.
        plot_id: Optional plot identifier for role-aware helper lookup.
        renderer: Active renderer used for bbox measurement.
        fig_w_pts/fig_h_pts: Figure dimensions in points.
        min_gap_pts/max_gap_pts: Desired x-label/tick gap bounds.
        min_axis_label_tick_gap_pts/max_axis_label_tick_gap_pts: Desired y-label
            to y-tick gap bounds.
    Outputs:
        Dict containing issue names and measured primary x-label/tick geometry.
    Side Effects:
        None.
    Exceptions:
        Artist inspection failures are ignored and represented as missing data.
    """
    audit: Dict[str, Any] = {
        "issues": [],
        "xlabel": None,
        "xticks_bbox": None,
        "xlabel_bbox": None,
        "xlabel_tick_gap_pts": None,
    }
    if fig is None or renderer is None:
        return audit

    def _add_issue(issue_name: str) -> None:
        """Add one unique audit issue name to the result payload.

        Purpose:
            Preserve first-seen issue ordering while avoiding duplicate reports.
        Why:
            The same artist conflict can be observed through multiple axes or
            helper paths, but wizard summaries should remain concise.
        Inputs:
            issue_name: Normalized layout issue token.
        Outputs:
            None.
        Side Effects:
            Mutates the local `audit["issues"]` list.
        Exceptions:
            None.
        """
        issues = audit.setdefault("issues", [])
        if issue_name not in issues:
            issues.append(issue_name)

    try:
        axes = list(fig.get_axes())
    except Exception:
        axes = []
    for axis in axes:
        if axis is None or getattr(axis, "_gl260_legend_only", False):
            continue
        try:
            if not bool(axis.get_visible()):
                continue
        except Exception:
            continue
        try:
            xlabel_artist = axis.xaxis.get_label()
        except Exception:
            xlabel_artist = None
        xlabel_bbox = _layout_health_bbox_in_fig(fig, xlabel_artist, renderer)
        xticks_bbox = _layout_health_axis_ticklabels_bbox(fig, axis.xaxis, renderer)
        if xlabel_bbox is not None and xticks_bbox is not None:
            gap_pts = float((xticks_bbox.y0 - xlabel_bbox.y1) * fig_h_pts)
            if audit["xlabel"] is None and _layout_health_artist_has_visible_text(
                xlabel_artist
            ):
                audit["xlabel"] = xlabel_artist
                audit["xlabel_bbox"] = xlabel_bbox
                audit["xticks_bbox"] = xticks_bbox
                audit["xlabel_tick_gap_pts"] = gap_pts
            if _layout_health_bbox_overlap_area(xlabel_bbox, xticks_bbox) > 1e-8:
                _add_issue("xlabel_xticklabels_overlap")
            elif gap_pts < float(min_gap_pts) - 0.25:
                _add_issue("xlabel_xticklabels_gap_low")
            elif gap_pts > float(max_gap_pts) + 0.25:
                _add_issue("xlabel_xticklabels_gap_high")
        try:
            ylabel_artist = axis.yaxis.get_label()
        except Exception:
            ylabel_artist = None
        ylabel_bbox = _layout_health_bbox_in_fig(fig, ylabel_artist, renderer)
        yticks_bbox = _layout_health_axis_ticklabels_bbox(fig, axis.yaxis, renderer)
        if ylabel_bbox is not None and yticks_bbox is not None:
            overlap = _layout_health_bbox_overlap_area(ylabel_bbox, yticks_bbox)
            label_center = float((ylabel_bbox.x0 + ylabel_bbox.x1) / 2.0)
            ticks_center = float((yticks_bbox.x0 + yticks_bbox.x1) / 2.0)
            if label_center >= ticks_center:
                gap_pts = float((ylabel_bbox.x0 - yticks_bbox.x1) * fig_w_pts)
            else:
                gap_pts = float((yticks_bbox.x0 - ylabel_bbox.x1) * fig_w_pts)
            if overlap > 1e-8 or gap_pts < float(min_axis_label_tick_gap_pts) - 0.25:
                _add_issue("axis_label_tick_overlap")
            elif gap_pts > float(max_axis_label_tick_gap_pts) + 0.25:
                _add_issue("axis_label_tick_gap_high")

    primary_xlabel = _layout_health_primary_xlabel(fig, plot_id=plot_id)
    primary_xticks_bbox = _layout_health_primary_xticklabels_bbox(
        fig, plot_id, renderer
    )
    primary_xlabel_bbox = _layout_health_bbox_in_fig(fig, primary_xlabel, renderer)
    if (
        _layout_health_artist_has_visible_text(primary_xlabel)
        and primary_xlabel_bbox is not None
        and primary_xticks_bbox is not None
    ):
        # Combined plots use a figure-level supxlabel, so axis-label scans alone
        # miss the reported x-label/tick-label collision.
        gap_pts = float((primary_xticks_bbox.y0 - primary_xlabel_bbox.y1) * fig_h_pts)
        if audit["xlabel"] is None:
            audit["xlabel"] = primary_xlabel
            audit["xlabel_bbox"] = primary_xlabel_bbox
            audit["xticks_bbox"] = primary_xticks_bbox
            audit["xlabel_tick_gap_pts"] = gap_pts
        if (
            _layout_health_bbox_overlap_area(primary_xlabel_bbox, primary_xticks_bbox)
            > 1e-8
        ):
            _add_issue("xlabel_xticklabels_overlap")
        elif gap_pts < float(min_gap_pts) - 0.25:
            _add_issue("xlabel_xticklabels_gap_low")
        elif gap_pts > float(max_gap_pts) + 0.25:
            _add_issue("xlabel_xticklabels_gap_high")

    break_labels = list(
        getattr(fig, "_gl260_combined_exclusion_break_label_artists", []) or []
    )
    if break_labels and primary_xticks_bbox is not None:
        break_label_gap_pts = None
        for break_label in break_labels:
            break_bbox = _layout_health_bbox_in_fig(fig, break_label, renderer)
            if break_bbox is None:
                continue
            gap_pts = float((primary_xticks_bbox.y0 - break_bbox.y1) * fig_h_pts)
            if break_label_gap_pts is None or gap_pts < break_label_gap_pts:
                break_label_gap_pts = gap_pts
            if _layout_health_bbox_overlap_area(break_bbox, primary_xticks_bbox) > 1e-8:
                _add_issue("combined_break_label_xticklabels_overlap")
            elif gap_pts < float(min_gap_pts) - 0.25:
                _add_issue("combined_break_label_xticklabels_gap_low")
        audit["break_label_tick_gap_pts"] = break_label_gap_pts

    for legend in _collect_gl260_legends(fig):
        bbox = _layout_health_bbox_in_fig(fig, legend, renderer)
        if bbox is None:
            continue
        if bbox.x0 < -0.001 or bbox.x1 > 1.001 or bbox.y0 < -0.001 or bbox.y1 > 1.001:
            _add_issue("legend_off_canvas")

    for text_artist in (
        getattr(fig, "_gl260_xlabel_text", None),
        getattr(fig, "_gl260_title_text", None),
        getattr(fig, "_gl260_suptitle_text", None),
        getattr(fig, "_suptitle", None),
    ):
        bbox = _layout_health_bbox_in_fig(fig, text_artist, renderer)
        if bbox is None:
            continue
        if bbox.x0 < -0.001 or bbox.x1 > 1.001 or bbox.y0 < -0.001 or bbox.y1 > 1.003:
            _add_issue("text_artist_off_canvas")
    return audit


def _layout_health_timeline_reclaim_bottom_whitespace_by_probe(
    fig: Figure,
    *,
    canvas: Any,
    layout_mgr: Optional[Any],
    bottom_legend: Any,
    bottom_axis: Any,
    max_bottom_whitespace_pts: float,
    fig_h_pts: float,
    min_gap_pts: float,
    allow_bottom_margin_adjust: bool = True,
) -> bool:
    """Reduce cycle timeline lower whitespace using bounded measured corrections.

    Purpose:
        Move the timeline bottom legend and subplot bottom margin only when a
        small measured correction proves the move reduces lower-band whitespace.
    Why:
        The Cycle Speciation Timeline can have a large blank band below the main
        legend, but exhaustive candidate probing performs many blocking canvas
        draws and makes the timeline tab and wizard sluggish.
    Inputs:
        fig: Timeline figure being corrected.
        canvas: Active Matplotlib canvas used for renderer measurements.
        layout_mgr: Optional `PlotLayoutManager` whose bottom baseline must stay
            synchronized with accepted margin probes.
        bottom_legend: Bottom timeline legend artist.
        bottom_axis: Lower timeline axis that owns the x label/tick labels.
        max_bottom_whitespace_pts: Configured whitespace ceiling in points.
        fig_h_pts: Figure height in points.
        min_gap_pts: Minimum safe legend-to-label/tick gap in points.
        allow_bottom_margin_adjust: Whether accepted probes may mutate the
            subplot bottom margin and layout-manager baseline.
    Outputs:
        bool: True when at least one measured correction was accepted.
    Side Effects:
        Mutates the bottom legend anchor for accepted corrections, then redraws
        the canvas. When `allow_bottom_margin_adjust` is True, also mutates
        `fig.subplotpars.bottom` and `layout_mgr._baseline_bottom`.
    Exceptions:
        Best-effort guards reject unmeasurable probes and return False.
    """

    if fig is None or canvas is None or bottom_legend is None or bottom_axis is None:
        return False

    def _current_bottom() -> Optional[float]:
        """Return the active layout-manager bottom baseline or subplot margin.

        Purpose:
            Resolve the value that a follow-up layout solve will actually apply.
        Why:
            Timeline profile margins are routed through `PlotLayoutManager`, so
            `subplots_adjust` alone is not authoritative after a solve.
        Inputs:
            None.
        Outputs:
            Optional float bottom margin in figure fraction.
        Side Effects:
            None.
        Exceptions:
            Returns None when margin values cannot be read.
        """
        if layout_mgr is not None:
            baseline = _safe_float(getattr(layout_mgr, "_baseline_bottom", None))
            if baseline is not None and math.isfinite(float(baseline)):
                return float(baseline)
        try:
            return float(fig.subplotpars.bottom)
        except Exception:
            return None

    def _apply_bottom(bottom_value: float) -> bool:
        """Apply one candidate bottom margin to the figure and layout manager.

        Purpose:
            Keep candidate probes on the same path used by real timeline renders.
        Why:
            Accepted settings must survive the next layout-manager solve instead
            of being overwritten by the previous baseline.
        Inputs:
            bottom_value: Candidate bottom margin in figure fraction.
        Outputs:
            bool: True when the candidate was applied and redrawn.
        Side Effects:
            Updates subplot margins, optional layout-manager baseline, and canvas.
        Exceptions:
            Returns False if Matplotlib or layout-manager operations fail.
        """
        try:
            if layout_mgr is not None:
                layout_mgr._baseline_bottom = float(bottom_value)
            fig.subplots_adjust(bottom=float(bottom_value))
            if layout_mgr is not None:
                layout_mgr.solve(max_passes=1, allow_draw=False)
            canvas.draw()
            return True
        except Exception:
            return False

    def _current_anchor() -> Optional[Tuple[float, float, float, float]]:
        """Return the bottom legend anchor in lower-axis coordinates.

        Purpose:
            Resolve the current legend placement used for measured anchor probes.
        Why:
            Some timeline states cannot hit the whitespace target by subplot
            margin alone; the legend anchor must move with the same measurement
            feedback loop.
        Inputs:
            None.
        Outputs:
            Optional `(x, y, width, height)` anchor tuple in axes coordinates.
        Side Effects:
            None.
        Exceptions:
            Returns None when the anchor cannot be normalized.
        """
        bbox_axes = _normalize_legend_bbox_anchor_value(
            getattr(bottom_legend, "_cycle_timeline_bbox_to_anchor_axes", None)
        )
        if bbox_axes is not None:
            return tuple(float(value) for value in bbox_axes)
        return (0.0, -0.04, 1.0, 0.2)

    def _apply_anchor(anchor_value: Tuple[float, float, float, float]) -> bool:
        """Apply one candidate bottom legend anchor and redraw.

        Purpose:
            Keep legend-anchor probes reversible and comparable to margin probes.
        Why:
            The lower blank band may be controlled by the legend floor rather than
            the subplot floor after the layout manager has already expanded axes.
        Inputs:
            anchor_value: `(x, y, width, height)` anchor in axes coordinates.
        Outputs:
            bool: True when the candidate anchor was applied and measured.
        Side Effects:
            Mutates the bottom legend anchor metadata and canvas draw state.
        Exceptions:
            Returns False when the legend anchor cannot be applied.
        """
        try:
            bottom_legend.set_loc("upper left")
        except Exception:
            pass
        try:
            bottom_legend.set_bbox_to_anchor(
                tuple(float(value) for value in anchor_value),
                transform=bottom_axis.transAxes,
            )
            bottom_legend._cycle_timeline_legend_role = "bottom"
            bottom_legend._cycle_timeline_bottom_wide_under_xaxis = True
            bottom_legend._cycle_timeline_bbox_to_anchor_axes = tuple(
                float(value) for value in anchor_value
            )
            if layout_mgr is not None:
                layout_mgr.solve(max_passes=1, allow_draw=False)
            canvas.draw()
            return True
        except Exception:
            return False

    def _measure() -> Optional[Dict[str, float]]:
        """Measure current lower-band whitespace and overlap safety.

        Purpose:
            Compare candidate moves using rendered legend/x-label/x-tick geometry.
        Why:
            The requested behavior depends on actual whitespace response, not a
            presumed relationship between margin direction and blank-space size.
        Inputs:
            None.
        Outputs:
            Dict with whitespace, overlap, and gap metrics, or None if unavailable.
        Side Effects:
            Forces a canvas draw for current artist extents.
        Exceptions:
            Returns None when renderer or artist bounds are unavailable.
        """
        try:
            canvas.draw()
            renderer = canvas.get_renderer()
        except Exception:
            return None
        if renderer is None:
            return None
        legend_bbox = _layout_health_bbox_in_fig(fig, bottom_legend, renderer)
        xlabel_bbox = _layout_health_bbox_in_fig(
            fig,
            bottom_axis.xaxis.get_label(),
            renderer,
        )
        xticks_bbox = _layout_health_axis_ticklabels_bbox(
            fig,
            bottom_axis.xaxis,
            renderer,
        )
        candidates = [
            float(bbox.y0)
            for bbox in (legend_bbox, xlabel_bbox, xticks_bbox)
            if bbox is not None
        ]
        if not candidates:
            return None
        overlap_area = 0.0
        min_gap = float("inf")
        if legend_bbox is not None and xlabel_bbox is not None:
            overlap_area += _layout_health_bbox_overlap_area(legend_bbox, xlabel_bbox)
            min_gap = min(min_gap, float((xlabel_bbox.y0 - legend_bbox.y1) * fig_h_pts))
        if legend_bbox is not None and xticks_bbox is not None:
            overlap_area += _layout_health_bbox_overlap_area(legend_bbox, xticks_bbox)
            min_gap = min(min_gap, float((xticks_bbox.y0 - legend_bbox.y1) * fig_h_pts))
        if not math.isfinite(min_gap):
            min_gap = float(min_gap_pts)
        return {
            "whitespace_pts": max(0.0, float(min(candidates) * fig_h_pts)),
            "overlap_area": float(overlap_area),
            "min_gap_pts": float(min_gap),
        }

    start_bottom = _current_bottom()
    if start_bottom is None:
        return False
    current_metrics = _measure()
    if current_metrics is None:
        return False
    target_pts = max(0.0, float(max_bottom_whitespace_pts))
    if float(current_metrics["whitespace_pts"]) <= target_pts + 0.25:
        return False

    accepted = False
    min_bottom = 0.02
    max_bottom = 0.62
    for _pass_idx in range(3):
        current_metrics = _measure()
        if current_metrics is None:
            break
        current_whitespace = float(current_metrics["whitespace_pts"])
        if current_whitespace <= target_pts + 0.25:
            break
        if float(current_metrics["overlap_area"]) > 1e-8:
            break
        if float(current_metrics["min_gap_pts"]) < float(min_gap_pts) - 0.25:
            break

        previous_whitespace = current_whitespace
        adjusted_this_pass = False
        anchor_now = _current_anchor()
        if anchor_now is not None:
            try:
                axis_pos = bottom_axis.get_position()
            except Exception:
                axis_pos = None
            axis_height = max(
                float(axis_pos.height) if axis_pos is not None else 0.0,
                1e-6,
            )
            whitespace_excess_frac = max(
                0.0,
                (current_whitespace - target_pts) / fig_h_pts,
            )
            anchor_delta = min(0.38, whitespace_excess_frac / axis_height)
            if anchor_delta > 1e-6:
                candidate_anchor = (
                    float(anchor_now[0]),
                    max(-0.95, min(0.18, float(anchor_now[1]) - anchor_delta)),
                    float(anchor_now[2]),
                    float(anchor_now[3]),
                )
                if _apply_anchor(candidate_anchor):
                    candidate_metrics = _measure()
                    if (
                        candidate_metrics is not None
                        and float(candidate_metrics["overlap_area"]) <= 1e-8
                        and float(candidate_metrics["min_gap_pts"])
                        >= float(min_gap_pts) - 0.25
                        and float(candidate_metrics["whitespace_pts"])
                        < previous_whitespace - 0.25
                    ):
                        accepted = True
                        adjusted_this_pass = True
                        previous_whitespace = float(candidate_metrics["whitespace_pts"])
                    else:
                        _apply_anchor(anchor_now)

        if allow_bottom_margin_adjust and previous_whitespace > target_pts + 0.25:
            current_bottom = _current_bottom()
            if current_bottom is None:
                break
            bottom_delta = min(
                0.08,
                max(0.0, (previous_whitespace - target_pts) / fig_h_pts),
            )
            candidate_bottom = max(
                min_bottom,
                min(max_bottom, float(current_bottom) - bottom_delta),
            )
            if candidate_bottom < float(current_bottom) - 1e-6:
                if _apply_bottom(candidate_bottom):
                    candidate_metrics = _measure()
                    if (
                        candidate_metrics is not None
                        and float(candidate_metrics["overlap_area"]) <= 1e-8
                        and float(candidate_metrics["min_gap_pts"])
                        >= float(min_gap_pts) - 0.25
                        and float(candidate_metrics["whitespace_pts"])
                        < previous_whitespace - 0.25
                    ):
                        accepted = True
                        adjusted_this_pass = True
                    else:
                        _apply_bottom(float(current_bottom))

        if not adjusted_this_pass:
            break

    return bool(accepted)


def layout_health_autofix(
    fig: Figure,
    plot_id: Optional[str],
    mode: str,
    policy: Optional[Mapping[str, Any]],
) -> Dict[str, Any]:
    """Detect and correct common figure layout-health failures in bounded passes.

    Purpose:
        Run a deterministic corrective pass after the primary layout solver.
    Why:
        Different canvas sizes and dense legend/title combinations can still
        produce whitespace, lower margin intrusions, overlap, and off-canvas
        artifacts after normal solves.
    Inputs:
        fig: Matplotlib figure to inspect/fix.
        plot_id: Plot identifier used for diagnostics policy decisions.
        mode: Layout mode (`display` or `export`).
        policy: Optional policy mapping with auto-fix toggles and thresholds.
    Outputs:
        Dict containing correction status, final-pass issues, accumulated
        detected issues, suggestions, and pass metadata.
    Side Effects:
        May adjust legend anchor Y, suptitle Y, subplot margins, and combined
        detached-axis spine offsets before re-solving figure layout through
        `PlotLayoutManager` or `subplots_adjust`. Combined-plot corrections,
        including primary-label left-margin clearance, bottom-margin changes for
        lower label-band overlap, and detached/secondary right-axis spacing, are
        stored as figure-local suggestions, not persisted settings.
    Exceptions:
        Uses best-effort guards around renderer and artist operations.
    """
    normalized_policy = _normalize_layout_health_settings(
        policy if isinstance(policy, Mapping) else settings
    )
    result: Dict[str, Any] = {
        "enabled": bool(normalized_policy.get("layout_health_autofix_enabled", True)),
        "applied": False,
        "passes": 0,
        "issues": [],
        "detected_issues": [],
        "plot_id": str(plot_id or "").strip(),
        "mode": str(mode or "display").strip().lower(),
    }
    plot_id_norm = str(plot_id or "").strip().lower()
    if fig is None or not result["enabled"]:
        return result
    autofix_started = time.perf_counter()

    try:
        canvas = fig.canvas
        if canvas is None or not hasattr(canvas, "get_renderer"):
            canvas = FigureCanvasAgg(fig)
            try:
                fig.set_canvas(canvas)
            except Exception:
                pass
    except Exception:
        canvas = None
    if canvas is None:
        return result

    strict_mode = bool(normalized_policy.get("layout_health_strict_mode", False))
    layout_health_context = (
        str(
            (policy.get("layout_health_context") if isinstance(policy, Mapping) else "")
            or ""
        )
        .strip()
        .lower()
    )
    if not layout_health_context:
        layout_health_context = (
            str(getattr(fig, "_gl260_layout_health_context", "") or "").strip().lower()
        )
    compare_context = layout_health_context == "compare"
    combined_mode = plot_id_norm == "fig_combined_triple_axis"
    min_gap_pts = float(normalized_policy.get("layout_health_min_gap_pts", 8.0))
    max_gap_pts = float(normalized_policy.get("layout_health_max_gap_pts", 28.0))
    legend_conflict_checks_enabled = bool(
        (
            policy.get("layout_health_check_legend_conflicts", True)
            if isinstance(policy, Mapping)
            else True
        )
    )
    x_axis_conflict_checks_enabled = bool(
        normalized_policy.get(
            "layout_health_check_x_axis_conflicts",
            DEFAULT_LAYOUT_HEALTH_CHECK_X_AXIS_CONFLICTS,
        )
    )
    axis_label_conflict_checks_enabled = bool(
        (
            policy.get("layout_health_check_axis_label_conflicts")
            if isinstance(policy, Mapping)
            else combined_mode
        )
    )
    if (
        combined_mode
        and isinstance(policy, Mapping)
        and "layout_health_check_axis_label_conflicts" not in policy
    ):
        axis_label_conflict_checks_enabled = True
    min_axis_label_tick_gap_pts = _safe_float(
        (
            policy.get("layout_health_min_axis_label_tick_gap_pts")
            if isinstance(policy, Mapping)
            else normalized_policy.get(
                "layout_health_min_axis_label_tick_gap_pts",
                DEFAULT_LAYOUT_HEALTH_MIN_AXIS_LABEL_TICK_GAP_PTS,
            )
        ),
        DEFAULT_LAYOUT_HEALTH_MIN_AXIS_LABEL_TICK_GAP_PTS,
    )
    if min_axis_label_tick_gap_pts is None or not math.isfinite(
        min_axis_label_tick_gap_pts
    ):
        min_axis_label_tick_gap_pts = DEFAULT_LAYOUT_HEALTH_MIN_AXIS_LABEL_TICK_GAP_PTS
    max_axis_label_tick_gap_pts = _safe_float(
        (
            policy.get("layout_health_max_axis_label_tick_gap_pts")
            if isinstance(policy, Mapping)
            else normalized_policy.get(
                "layout_health_max_axis_label_tick_gap_pts",
                DEFAULT_LAYOUT_HEALTH_MAX_AXIS_LABEL_TICK_GAP_PTS,
            )
        ),
        DEFAULT_LAYOUT_HEALTH_MAX_AXIS_LABEL_TICK_GAP_PTS,
    )
    if max_axis_label_tick_gap_pts is None or not math.isfinite(
        max_axis_label_tick_gap_pts
    ):
        max_axis_label_tick_gap_pts = DEFAULT_LAYOUT_HEALTH_MAX_AXIS_LABEL_TICK_GAP_PTS
    if strict_mode:
        min_gap_pts = max(min_gap_pts, 6.0)
        max_gap_pts = min(max_gap_pts, 20.0)
        min_axis_label_tick_gap_pts = max(min_axis_label_tick_gap_pts, 6.0)
        max_axis_label_tick_gap_pts = min(max_axis_label_tick_gap_pts, 18.0)
    if max_gap_pts < min_gap_pts:
        max_gap_pts = min_gap_pts
    if max_axis_label_tick_gap_pts < min_axis_label_tick_gap_pts:
        max_axis_label_tick_gap_pts = min_axis_label_tick_gap_pts
    if isinstance(policy, Mapping):
        if plot_id_norm == "fig_cycle_timeline":
            raw_max_bottom_whitespace = policy.get(
                "layout_health_max_timeline_bottom_whitespace_pts",
                policy.get("layout_health_max_bottom_whitespace_pts"),
            )
        else:
            raw_max_bottom_whitespace = policy.get(
                "layout_health_max_bottom_whitespace_pts",
                policy.get("layout_health_max_timeline_bottom_whitespace_pts"),
            )
    else:
        raw_max_bottom_whitespace = normalized_policy.get(
            "layout_health_max_bottom_whitespace_pts",
            DEFAULT_LAYOUT_HEALTH_MAX_BOTTOM_WHITESPACE_PTS,
        )
    max_bottom_whitespace_pts = _safe_float(
        raw_max_bottom_whitespace,
        DEFAULT_LAYOUT_HEALTH_MAX_BOTTOM_WHITESPACE_PTS,
    )
    if max_bottom_whitespace_pts is None or not math.isfinite(
        max_bottom_whitespace_pts
    ):
        max_bottom_whitespace_pts = DEFAULT_LAYOUT_HEALTH_MAX_BOTTOM_WHITESPACE_PTS
    max_bottom_whitespace_pts = max(6.0, min(160.0, float(max_bottom_whitespace_pts)))
    combined_edge_clearance_pts = _safe_float(
        (
            policy.get("combined_layout_health_edge_clearance_pts")
            if isinstance(policy, Mapping)
            else settings.get("combined_layout_health_edge_clearance_pts")
        ),
        10.0,
    )
    if combined_edge_clearance_pts is None or not math.isfinite(
        combined_edge_clearance_pts
    ):
        combined_edge_clearance_pts = 10.0
    combined_edge_clearance_pts = max(
        2.0,
        min(48.0, float(combined_edge_clearance_pts)),
    )

    max_passes = int(normalized_policy.get("layout_health_max_passes", 3))
    max_passes = max(
        MIN_LAYOUT_HEALTH_MAX_PASSES,
        min(MAX_LAYOUT_HEALTH_MAX_PASSES, max_passes),
    )
    min_axes_height = 0.36 if strict_mode else 0.31
    mode_norm = str(mode or "display").strip().lower()
    if mode_norm == "export":
        min_axes_height = max(0.28, min_axes_height - 0.04)

    layout_mgr = getattr(fig, "_gl260_layout_manager", None)
    authoritative_timeline_bottom = _layout_health_authoritative_timeline_bottom(
        fig,
        mode_norm,
        layout_mgr,
    )
    for pass_idx in range(max_passes):
        result["passes"] = int(pass_idx + 1)
        try:
            canvas.draw()
        except Exception:
            try:
                canvas.draw_idle()
                canvas.draw()
            except Exception:
                break
        try:
            renderer = canvas.get_renderer()
        except Exception:
            renderer = None
        if renderer is None:
            break

        fig_w_pts = max(float(fig.get_size_inches()[0]) * 72.0, 1.0)
        fig_h_pts = max(float(fig.get_size_inches()[1]) * 72.0, 1.0)
        legend = _layout_health_primary_legend(fig, plot_id=plot_id)
        xlabel = _layout_health_primary_xlabel(fig, plot_id=plot_id)
        title_artist = getattr(fig, "_gl260_title_text", None)
        suptitle_artist = getattr(fig, "_gl260_suptitle_text", None) or getattr(
            fig, "_suptitle", None
        )

        legend_bbox = _layout_health_bbox_in_fig(fig, legend, renderer)
        xlabel_bbox = _layout_health_bbox_in_fig(fig, xlabel, renderer)
        title_bbox = _layout_health_bbox_in_fig(fig, title_artist, renderer)
        suptitle_bbox = _layout_health_bbox_in_fig(fig, suptitle_artist, renderer)
        timeline_mode = plot_id_norm == "fig_cycle_timeline"
        timeline_legends = (
            _layout_health_timeline_legends(fig)
            if timeline_mode
            else {"top": None, "bottom": None}
        )
        timeline_top_legend = timeline_legends.get("top") if timeline_mode else None
        timeline_bottom_legend = (
            timeline_legends.get("bottom") if timeline_mode else None
        )
        if timeline_mode and timeline_bottom_legend is not None:
            legend = timeline_bottom_legend
            legend_bbox = _layout_health_bbox_in_fig(fig, legend, renderer)
        timeline_top_legend_bbox = (
            _layout_health_bbox_in_fig(fig, timeline_top_legend, renderer)
            if timeline_top_legend is not None
            else None
        )
        timeline_top_axis = (
            _layout_health_axis_for_role(fig, "primary") if timeline_mode else None
        )
        timeline_top_axis_pos = None
        if timeline_top_axis is not None:
            try:
                timeline_top_axis_pos = timeline_top_axis.get_position()
            except Exception:
                timeline_top_axis_pos = None
        timeline_bottom_axis = (
            _layout_health_axis_for_role(fig, "right") if timeline_mode else None
        )
        timeline_bottom_ticks_bbox = None
        if (
            timeline_mode
            and legend_conflict_checks_enabled
            and x_axis_conflict_checks_enabled
            and timeline_bottom_axis is not None
        ):
            timeline_bottom_ticks_bbox = _layout_health_axis_ticklabels_bbox(
                fig,
                timeline_bottom_axis.xaxis,
                renderer,
            )
        primary_xticks_bbox = (
            timeline_bottom_ticks_bbox
            if timeline_bottom_ticks_bbox is not None
            else (
                _layout_health_primary_xticklabels_bbox(fig, plot_id, renderer)
                if (legend_conflict_checks_enabled and x_axis_conflict_checks_enabled)
                else None
            )
        )
        timeline_right_axis = (
            _layout_health_axis_for_role(fig, "third")
            if (axis_label_conflict_checks_enabled and timeline_mode)
            else None
        )
        timeline_right_axis_pos = None
        timeline_right_label_bbox = None
        timeline_right_ticks_bbox = None
        if timeline_right_axis is not None:
            try:
                timeline_right_axis_pos = timeline_right_axis.get_position()
            except Exception:
                timeline_right_axis_pos = None
            try:
                timeline_right_label = timeline_right_axis.yaxis.get_label()
            except Exception:
                timeline_right_label = None
            timeline_right_label_bbox = _layout_health_bbox_in_fig(
                fig, timeline_right_label, renderer
            )
            timeline_right_ticks_bbox = _layout_health_axis_ticklabels_bbox(
                fig, timeline_right_axis.yaxis, renderer
            )
        combined_axis_metrics = (
            _layout_health_combined_axis_metrics(fig, renderer)
            if (axis_label_conflict_checks_enabled and combined_mode)
            else {}
        )
        combined_primary_metrics = combined_axis_metrics.get("primary", {})
        combined_right_metrics = combined_axis_metrics.get("right", {})
        combined_third_metrics = combined_axis_metrics.get("third", {})

        axes_positions: List[Bbox] = []
        try:
            for axis in fig.get_axes():
                if axis is None or getattr(axis, "_gl260_legend_only", False):
                    continue
                if not bool(axis.get_visible()):
                    continue
                axes_positions.append(axis.get_position())
        except Exception:
            axes_positions = []
        axes_union = Bbox.union(axes_positions) if axes_positions else None

        issues: List[str] = []
        gap_pts = None
        axis_label_tick_gap_pts = None
        combined_right_label_tick_gap_pts = None
        combined_third_label_tick_gap_pts = None
        combined_primary_label_edge_gap_pts = None
        combined_cross_axis_gap_pts = None
        combined_ticks_gap_pts = None
        combined_label_gap_pts = None
        combined_label_axis_gap_pts = None
        combined_right_margin_whitespace_pts = None
        bottom_whitespace_pts = None
        bottom_label_band_overlap_pts = None
        legend_xlabel_overlap_area = 0.0
        legend_xticks_overlap_area = 0.0
        general_audit = _layout_health_general_figure_audit(
            fig,
            plot_id,
            renderer,
            fig_w_pts=fig_w_pts,
            fig_h_pts=fig_h_pts,
            min_gap_pts=min_gap_pts,
            max_gap_pts=max_gap_pts,
            min_axis_label_tick_gap_pts=min_axis_label_tick_gap_pts,
            max_axis_label_tick_gap_pts=max_axis_label_tick_gap_pts,
        )
        for audit_issue in list(general_audit.get("issues", []) or []):
            if audit_issue not in issues:
                issues.append(str(audit_issue))
        if (
            legend_conflict_checks_enabled
            and legend_bbox is not None
            and xlabel_bbox is not None
        ):
            gap_pts = float((xlabel_bbox.y0 - legend_bbox.y1) * fig_h_pts)
            legend_xlabel_overlap_area = _layout_health_bbox_overlap_area(
                legend_bbox, xlabel_bbox
            )
            if (
                legend_xlabel_overlap_area > 1e-8
                and "legend_xlabel_overlap" not in issues
            ):
                issues.append("legend_xlabel_overlap")
            if gap_pts > max_gap_pts + 0.25:
                issues.append("legend_xlabel_gap_high")
            if gap_pts < min_gap_pts - 0.25:
                issues.append("legend_xlabel_gap_low")
        if (
            legend_conflict_checks_enabled
            and x_axis_conflict_checks_enabled
            and legend_bbox is not None
            and primary_xticks_bbox is not None
        ):
            legend_xticks_overlap_area = _layout_health_bbox_overlap_area(
                legend_bbox,
                primary_xticks_bbox,
            )
            if (
                legend_xticks_overlap_area > 1e-8
                and "legend_xticklabels_overlap" not in issues
            ):
                issues.append("legend_xticklabels_overlap")
            tick_gap_pts = float((primary_xticks_bbox.y0 - legend_bbox.y1) * fig_h_pts)
            if (
                tick_gap_pts < min_gap_pts - 0.25
                and "legend_xticklabels_gap_low" not in issues
            ):
                issues.append("legend_xticklabels_gap_low")
        if (
            legend_conflict_checks_enabled
            and legend_bbox is not None
            and (legend_bbox.y0 < -0.001 or legend_bbox.y1 > 1.001)
        ):
            issues.append("legend_off_canvas")
        bottom_band_candidates = []
        if legend_bbox is not None:
            bottom_band_candidates.append(float(legend_bbox.y0))
        if xlabel_bbox is not None:
            bottom_band_candidates.append(float(xlabel_bbox.y0))
        if primary_xticks_bbox is not None:
            bottom_band_candidates.append(float(primary_xticks_bbox.y0))
        if bottom_band_candidates:
            bottom_whitespace_pts = max(
                0.0, float(min(bottom_band_candidates) * fig_h_pts)
            )
            if bottom_whitespace_pts > float(max_bottom_whitespace_pts) + 0.25:
                issues.append(
                    "timeline_bottom_whitespace_high"
                    if timeline_mode
                    else "bottom_whitespace_high"
                )
        bottom_band_top_candidates = []
        if legend_bbox is not None:
            bottom_band_top_candidates.append(float(legend_bbox.y1))
        if xlabel_bbox is not None:
            bottom_band_top_candidates.append(float(xlabel_bbox.y1))
        if primary_xticks_bbox is not None:
            bottom_band_top_candidates.append(float(primary_xticks_bbox.y1))
        if axes_union is not None and bottom_band_top_candidates:
            # Detect when the subplot bottom margin has been applied before the
            # lower legend/x-label/tick band is accounted for.
            lower_band_top = max(bottom_band_top_candidates)
            bottom_label_band_overlap_pts = float(
                (lower_band_top + (float(min_gap_pts) / fig_h_pts) - axes_union.y0)
                * fig_h_pts
            )
            if bottom_label_band_overlap_pts > 0.25:
                issues.append(
                    "timeline_bottom_margin_label_band_overlap"
                    if timeline_mode
                    else "bottom_margin_label_band_overlap"
                )
        if (
            axis_label_conflict_checks_enabled
            and timeline_right_label_bbox is not None
            and timeline_right_ticks_bbox is not None
        ):
            axis_label_tick_gap_pts = float(
                (timeline_right_label_bbox.x0 - timeline_right_ticks_bbox.x1)
                * fig_w_pts
            )
            if axis_label_tick_gap_pts < float(min_axis_label_tick_gap_pts) - 0.25:
                issues.append("axis_label_tick_overlap")
            if axis_label_tick_gap_pts > float(max_axis_label_tick_gap_pts) + 0.25:
                issues.append("axis_label_tick_gap_high")
        if (
            axis_label_conflict_checks_enabled
            and timeline_right_label_bbox is not None
            and timeline_right_label_bbox.x1 > 1.001
        ):
            issues.append("axis_label_off_canvas_right")
        if (
            axis_label_conflict_checks_enabled
            and timeline_right_label_bbox is not None
            and timeline_right_label_bbox.x0 < -0.001
        ):
            issues.append("axis_label_off_canvas_left")
        if axis_label_conflict_checks_enabled and combined_mode:
            primary_label_bbox = combined_primary_metrics.get("label_bbox")
            right_label_bbox = combined_right_metrics.get("label_bbox")
            right_ticks_bbox = combined_right_metrics.get("ticks_bbox")
            third_label_bbox = combined_third_metrics.get("label_bbox")
            third_ticks_bbox = combined_third_metrics.get("ticks_bbox")
            third_spine_x_fig = combined_third_metrics.get("spine_x_fig")
            if primary_label_bbox is not None:
                combined_primary_label_edge_gap_pts = float(
                    primary_label_bbox.x0 * fig_w_pts
                )
                if (
                    combined_primary_label_edge_gap_pts
                    < float(combined_edge_clearance_pts) - 0.25
                ):
                    issues.append("combined_primary_axis_label_off_canvas_left")
            if right_label_bbox is not None and right_ticks_bbox is not None:
                combined_right_label_tick_gap_pts = float(
                    (right_label_bbox.x0 - right_ticks_bbox.x1) * fig_w_pts
                )
                if (
                    combined_right_label_tick_gap_pts
                    < float(min_axis_label_tick_gap_pts) - 0.25
                ):
                    issues.append("combined_right_axis_label_tick_overlap")
            if third_label_bbox is not None and third_ticks_bbox is not None:
                combined_third_label_tick_gap_pts = float(
                    (third_label_bbox.x0 - third_ticks_bbox.x1) * fig_w_pts
                )
                if (
                    combined_third_label_tick_gap_pts
                    < float(min_axis_label_tick_gap_pts) - 0.25
                ):
                    issues.append("combined_third_axis_label_tick_overlap")
                if (
                    combined_third_label_tick_gap_pts
                    > float(max_axis_label_tick_gap_pts) + 0.25
                ):
                    issues.append("combined_third_axis_label_tick_gap_high")
            if right_label_bbox is not None and third_ticks_bbox is not None:
                cross_overlap = _layout_health_bbox_overlap_area(
                    right_label_bbox,
                    third_ticks_bbox,
                )
                combined_cross_axis_gap_pts = float(
                    (third_ticks_bbox.x0 - right_label_bbox.x1) * fig_w_pts
                )
                if (
                    cross_overlap > 1e-8
                    or combined_cross_axis_gap_pts
                    < float(min_axis_label_tick_gap_pts) - 0.25
                ):
                    issues.append("combined_right_label_third_ticks_overlap")
                elif (
                    combined_cross_axis_gap_pts
                    > float(max_axis_label_tick_gap_pts) + 0.25
                ):
                    issues.append("combined_right_label_third_ticks_gap_high")
            if right_ticks_bbox is not None and third_ticks_bbox is not None:
                combined_ticks_gap_pts = float(
                    (third_ticks_bbox.x0 - right_ticks_bbox.x1) * fig_w_pts
                )
                if (
                    _layout_health_bbox_overlap_area(right_ticks_bbox, third_ticks_bbox)
                    > 1e-8
                    or combined_ticks_gap_pts
                    < float(min_axis_label_tick_gap_pts) - 0.25
                ):
                    issues.append("combined_right_ticks_third_ticks_overlap")
            if right_label_bbox is not None and third_spine_x_fig is not None:
                combined_label_axis_gap_pts = float(
                    (float(third_spine_x_fig) - right_label_bbox.x1) * fig_w_pts
                )
                if (
                    right_label_bbox.x0
                    <= float(third_spine_x_fig)
                    <= right_label_bbox.x1
                    or combined_label_axis_gap_pts
                    < float(min_axis_label_tick_gap_pts) - 0.25
                ):
                    issues.append("combined_right_label_third_axis_gap_low")
            if right_label_bbox is not None and third_label_bbox is not None:
                combined_label_gap_pts = float(
                    (third_label_bbox.x0 - right_label_bbox.x1) * fig_w_pts
                )
                if (
                    _layout_health_bbox_overlap_area(right_label_bbox, third_label_bbox)
                    > 1e-8
                    or combined_label_gap_pts
                    < float(min_axis_label_tick_gap_pts) - 0.25
                ):
                    issues.append("combined_right_label_third_label_overlap")
            for role_name, axis_metrics in combined_axis_metrics.items():
                label_bbox = axis_metrics.get("label_bbox")
                if label_bbox is None:
                    continue
                if label_bbox.x1 > 1.001:
                    issues.append(f"combined_{role_name}_axis_label_off_canvas_right")
                if label_bbox.x0 < -0.001:
                    issues.append(f"combined_{role_name}_axis_label_off_canvas_left")
            right_edge_candidates = []
            for axis_metrics in combined_axis_metrics.values():
                for key in ("label_bbox", "ticks_bbox"):
                    bbox = axis_metrics.get(key)
                    if bbox is not None:
                        right_edge_candidates.append(float(bbox.x1))
                spine_x_fig = axis_metrics.get("spine_x_fig")
                try:
                    if spine_x_fig is not None and math.isfinite(float(spine_x_fig)):
                        right_edge_candidates.append(float(spine_x_fig))
                except Exception:
                    pass
            if right_edge_candidates:
                # The detached axis may be valid but leave a wide unused band to
                # its right; detect that separately from label/tick collisions.
                rightmost_combined_edge = max(right_edge_candidates)
                combined_right_margin_whitespace_pts = max(
                    0.0,
                    (1.0 - float(rightmost_combined_edge)) * fig_w_pts,
                )
                try:
                    current_right_margin = float(fig.subplotpars.right)
                except Exception:
                    current_right_margin = 1.0
                if (
                    combined_right_margin_whitespace_pts
                    > float(combined_edge_clearance_pts) + 0.25
                    and current_right_margin < 0.992
                ):
                    issues.append("combined_right_margin_whitespace_high")
        if legend_conflict_checks_enabled and timeline_top_legend_bbox is not None:
            if (
                timeline_top_legend_bbox.y0 < -0.001
                or timeline_top_legend_bbox.y1 > 1.001
                or timeline_top_legend_bbox.x0 < -0.001
                or timeline_top_legend_bbox.x1 > 1.001
            ):
                if "timeline_top_legend_off_canvas" not in issues:
                    issues.append("timeline_top_legend_off_canvas")
            if timeline_top_axis_pos is not None:
                top_overlap = _layout_health_bbox_overlap_area(
                    timeline_top_legend_bbox,
                    timeline_top_axis_pos,
                )
                top_legend_area = max(
                    1e-9,
                    float(timeline_top_legend_bbox.x1 - timeline_top_legend_bbox.x0)
                    * float(timeline_top_legend_bbox.y1 - timeline_top_legend_bbox.y0),
                )
                overlap_ratio = float(top_overlap / top_legend_area)
                if (
                    overlap_ratio < 0.35
                    and "timeline_top_legend_outside_top_axis" not in issues
                ):
                    issues.append("timeline_top_legend_outside_top_axis")
        if title_bbox is not None and title_bbox.y1 > 1.003:
            issues.append("title_off_canvas")
        if suptitle_bbox is not None and suptitle_bbox.y1 > 1.003:
            issues.append("suptitle_off_canvas")
        if axes_union is not None and float(axes_union.height) < min_axes_height:
            issues.append("axes_over_compressed")
        if not issues:
            break

        result["issues"] = list(issues)
        detected_issues = result.setdefault("detected_issues", [])
        if not isinstance(detected_issues, list):
            detected_issues = []
            result["detected_issues"] = detected_issues
        for issue_name in issues:
            if issue_name not in detected_issues:
                detected_issues.append(issue_name)
        _layout_health_debug_event(
            normalized_policy,
            "Layout-health pass %s issues=%s plot_id=%s mode=%s gap_pts=%s bottom_whitespace_pts=%s",
            int(pass_idx + 1),
            ",".join(issues),
            str(plot_id or ""),
            mode_norm,
            "--" if gap_pts is None else f"{gap_pts:.2f}",
            ("--" if bottom_whitespace_pts is None else f"{bottom_whitespace_pts:.2f}"),
        )

        adjusted = False
        if (
            legend_conflict_checks_enabled
            and timeline_mode
            and timeline_bottom_legend is not None
            and legend_bbox is not None
        ):
            bottom_has_issue = any(
                issue_name in issues
                for issue_name in (
                    "legend_xlabel_overlap",
                    "legend_xlabel_gap_low",
                    "legend_xlabel_gap_high",
                    "legend_xticklabels_overlap",
                    "legend_xticklabels_gap_low",
                    "legend_off_canvas",
                )
            )
            if bottom_has_issue:
                bottom_axis = timeline_bottom_axis
                if bottom_axis is None:
                    bottom_axis = getattr(timeline_bottom_legend, "axes", None)
                wide_bottom_mode = bool(
                    getattr(
                        timeline_bottom_legend,
                        "_cycle_timeline_bottom_wide_under_xaxis",
                        False,
                    )
                )
                if bottom_axis is not None and wide_bottom_mode:
                    bbox_axes = _normalize_legend_bbox_anchor_value(
                        getattr(
                            timeline_bottom_legend,
                            "_cycle_timeline_bbox_to_anchor_axes",
                            None,
                        )
                    )
                    if bbox_axes is None:
                        bbox_axes = (0.0, -0.22, 1.0, 0.2)
                    anchor_x = float(bbox_axes[0])
                    anchor_y = float(bbox_axes[1])
                    anchor_w = float(bbox_axes[2])
                    anchor_h = float(bbox_axes[3])
                    shift_up_fig = 0.0
                    shift_down_fig = 0.0
                    target_gap_pts = max(
                        min_gap_pts, min(max_gap_pts, (min_gap_pts + max_gap_pts) / 2.0)
                    )
                    if gap_pts is not None and (
                        "legend_xlabel_overlap" in issues
                        or "legend_xlabel_gap_low" in issues
                    ):
                        shift_down_fig = max(
                            shift_down_fig,
                            max(0.0, float(target_gap_pts - gap_pts)) / fig_h_pts,
                        )
                    if gap_pts is not None and "legend_xlabel_gap_high" in issues:
                        shift_up_fig = max(
                            shift_up_fig,
                            max(0.0, float(gap_pts - target_gap_pts)) / fig_h_pts,
                        )
                    if timeline_bottom_ticks_bbox is not None and (
                        "legend_xticklabels_overlap" in issues
                        or "legend_xticklabels_gap_low" in issues
                    ):
                        required_down = float(
                            legend_bbox.y1 - timeline_bottom_ticks_bbox.y0
                        ) + (float(min_gap_pts) / fig_h_pts)
                        shift_down_fig = max(shift_down_fig, max(0.0, required_down))
                    if "legend_off_canvas" in issues:
                        if float(legend_bbox.y0) < 0.0:
                            shift_up_fig = max(
                                shift_up_fig,
                                abs(float(legend_bbox.y0)) + (2.0 / fig_h_pts),
                            )
                        if float(legend_bbox.y1) > 1.0:
                            shift_down_fig = max(
                                shift_down_fig,
                                abs(float(legend_bbox.y1 - 1.0)) + (2.0 / fig_h_pts),
                            )
                    axis_pos = None
                    try:
                        axis_pos = bottom_axis.get_position()
                    except Exception:
                        axis_pos = None
                    axis_height = max(
                        float(axis_pos.height) if axis_pos is not None else 0.0,
                        1e-6,
                    )
                    net_shift_axes = (shift_up_fig - shift_down_fig) / axis_height
                    if abs(net_shift_axes) > 1e-6:
                        anchor_y += max(-0.35, min(0.35, float(net_shift_axes)))
                    anchor_y = max(-0.55, min(0.18, anchor_y))
                    try:
                        timeline_bottom_legend.set_loc("upper left")
                    except Exception:
                        # Best-effort guard; ignore loc-override failures.
                        pass
                    try:
                        timeline_bottom_legend.set_bbox_to_anchor(
                            (anchor_x, anchor_y, anchor_w, anchor_h),
                            transform=bottom_axis.transAxes,
                        )
                        adjusted = True
                        try:
                            timeline_bottom_legend._cycle_timeline_bbox_to_anchor_axes = (
                                anchor_x,
                                anchor_y,
                                anchor_w,
                                anchor_h,
                            )
                        except Exception:
                            # Best-effort guard; ignore metadata write failures.
                            pass
                    except Exception:
                        # Best-effort guard; ignore legend-anchor failures.
                        pass
                elif bottom_axis is not None:
                    try:
                        timeline_bottom_legend.set_loc("upper right")
                    except Exception:
                        # Best-effort guard; ignore loc-override failures.
                        pass
                    try:
                        timeline_bottom_legend.set_bbox_to_anchor(
                            (0.98, 0.98),
                            transform=bottom_axis.transAxes,
                        )
                        adjusted = True
                    except Exception:
                        # Best-effort guard; ignore legend-anchor failures.
                        pass

        if (
            legend_conflict_checks_enabled
            and timeline_mode
            and timeline_top_legend is not None
            and any(
                top_issue in issues
                for top_issue in (
                    "timeline_top_legend_off_canvas",
                    "timeline_top_legend_outside_top_axis",
                )
            )
        ):
            if timeline_top_axis is not None:
                try:
                    timeline_top_legend.set_loc("upper left")
                except Exception:
                    # Best-effort guard; ignore loc-override failures.
                    pass
                try:
                    timeline_top_legend.set_bbox_to_anchor(
                        (0.02, 0.98),
                        transform=timeline_top_axis.transAxes,
                    )
                    adjusted = True
                except Exception:
                    # Best-effort guard; ignore legend-anchor failures.
                    pass

        legend_role_value = (
            str(getattr(legend, "_cycle_timeline_legend_role", "")).strip().lower()
            if legend is not None
            else ""
        )
        if (
            legend_conflict_checks_enabled
            and legend is not None
            and legend_bbox is not None
            and (not timeline_mode or legend_role_value not in {"top", "bottom"})
        ):
            anchor_x = 0.5
            anchor_y = float(legend_bbox.y0)
            if (
                hasattr(layout_mgr, "legend_anchor")
                and getattr(layout_mgr, "legend_anchor") is not None
            ):
                try:
                    legend_anchor_pair = tuple(getattr(layout_mgr, "legend_anchor"))
                    anchor_x = float(legend_anchor_pair[0])
                    anchor_y = float(legend_anchor_pair[1])
                except Exception:
                    pass
            elif (
                hasattr(layout_mgr, "legend_anchor_y")
                and getattr(layout_mgr, "legend_anchor_y") is not None
            ):
                try:
                    anchor_y = float(getattr(layout_mgr, "legend_anchor_y"))
                except Exception:
                    pass
            else:
                try:
                    bbox_anchor = legend.get_bbox_to_anchor()
                    if bbox_anchor is not None:
                        anchor_x = float(getattr(bbox_anchor, "x0", anchor_x))
                        anchor_y = float(getattr(bbox_anchor, "y0", anchor_y))
                except Exception:
                    pass

            combined_plot_band_shifted = False
            target_gap_pts = max(
                min_gap_pts, min(max_gap_pts, (min_gap_pts + max_gap_pts) / 2.0)
            )
            if (
                combined_mode
                and gap_pts is not None
                and math.isfinite(float(gap_pts))
                and "legend_xlabel_gap_high" in issues
            ):
                # For combined plots, a high legend/x-label gap is best fixed by
                # moving the axes band down so ticks and x-label follow the plot.
                gap_excess_frac = max(
                    0.0,
                    (float(gap_pts) - float(target_gap_pts)) / fig_h_pts,
                )
                if gap_excess_frac > 1e-5:
                    try:
                        baseline_bottom = (
                            _safe_float(getattr(layout_mgr, "_baseline_bottom", None))
                            if layout_mgr is not None
                            else None
                        )
                    except Exception:
                        baseline_bottom = None
                    if baseline_bottom is None:
                        try:
                            baseline_bottom = float(fig.subplotpars.bottom)
                        except Exception:
                            baseline_bottom = 0.0
                    target_bottom = max(
                        0.02,
                        float(baseline_bottom) - min(0.08, float(gap_excess_frac)),
                    )
                    if target_bottom < float(baseline_bottom) - 1e-6:
                        try:
                            if layout_mgr is not None:
                                layout_mgr._baseline_bottom = float(target_bottom)
                            fig.subplots_adjust(bottom=float(target_bottom))
                            adjusted = True
                            combined_plot_band_shifted = True
                            _layout_health_record_combined_suggestion(
                                fig,
                                mode_norm,
                                margins={"bottom": float(target_bottom)},
                            )
                        except Exception:
                            pass

            has_gap_issue = (
                "legend_xlabel_gap_high" in issues and not combined_plot_band_shifted
            ) or ("legend_xlabel_gap_low" in issues)
            if gap_pts is not None and has_gap_issue:
                if compare_context:
                    # Compare panes use compact canvases; keep gap correction gated to
                    # explicit gap issues to avoid fighting off-canvas recovery.
                    delta_gap_frac = (gap_pts - target_gap_pts) / fig_h_pts
                else:
                    delta_gap_frac = (gap_pts - target_gap_pts) / fig_h_pts
                if abs(delta_gap_frac) > 1e-4:
                    anchor_y += max(-0.08, min(0.08, float(delta_gap_frac)))
                    adjusted = True
            if primary_xticks_bbox is not None and (
                "legend_xticklabels_overlap" in issues
                or "legend_xticklabels_gap_low" in issues
            ):
                required_down = float(legend_bbox.y1 - primary_xticks_bbox.y0) + (
                    float(min_gap_pts) / fig_h_pts
                )
                if required_down > 1e-5:
                    anchor_y -= min(0.08, max(0.0, float(required_down)))
                    adjusted = True
            if "legend_off_canvas" in issues:
                if legend_bbox.y0 < 0.0:
                    anchor_y += min(
                        0.12, abs(float(legend_bbox.y0)) + (2.0 / fig_h_pts)
                    )
                    adjusted = True
                if legend_bbox.y1 > 1.0:
                    anchor_y -= min(
                        0.12, abs(float(legend_bbox.y1 - 1.0)) + (2.0 / fig_h_pts)
                    )
                    adjusted = True
            if "axes_over_compressed" in issues and strict_mode:
                anchor_y += 4.0 / fig_h_pts
                adjusted = True
            if compare_context:
                # Compare keeps the legend in the lower-band region; clamping
                # anchor_y tighter prevents repeated off-canvas drift loops.
                anchor_y = max(-0.02, min(0.28, float(anchor_y)))
            else:
                anchor_y = max(-0.12, min(1.12, float(anchor_y)))
            if adjusted:
                try:
                    legend.set_bbox_to_anchor(
                        (anchor_x, anchor_y), transform=fig.transFigure
                    )
                except Exception:
                    pass
                if layout_mgr is not None:
                    try:
                        layout_mgr.legend_anchor = (anchor_x, anchor_y)
                        layout_mgr.legend_anchor_y = anchor_y
                    except Exception:
                        pass

        if any(
            issue_name in issues
            for issue_name in (
                "combined_break_label_xticklabels_overlap",
                "combined_break_label_xticklabels_gap_low",
            )
        ):
            break_label_gap_pts = general_audit.get("break_label_tick_gap_pts")
            required_shift_pts = float(min_gap_pts)
            if break_label_gap_pts is not None:
                try:
                    required_shift_pts = max(
                        required_shift_pts,
                        float(min_gap_pts) - float(break_label_gap_pts),
                    )
                except Exception:
                    pass
            for break_label in list(
                getattr(
                    fig,
                    "_gl260_combined_exclusion_break_label_artists",
                    [],
                )
                or []
            ):
                try:
                    offset_x, offset_y = break_label.get_position()
                    break_label.set_position(
                        (float(offset_x), float(offset_y) - required_shift_pts)
                    )
                    result["applied"] = True
                except Exception:
                    continue
        if any(
            issue_name in issues
            for issue_name in (
                "xlabel_xticklabels_overlap",
                "xlabel_xticklabels_gap_low",
            )
        ):
            xlabel_artist = general_audit.get(
                "xlabel"
            ) or _layout_health_primary_xlabel(fig, plot_id=plot_id)
            xlabel_gap_pts = general_audit.get("xlabel_tick_gap_pts")
            required_shift = float(min_gap_pts) / fig_h_pts
            if xlabel_gap_pts is not None:
                try:
                    required_shift = max(
                        required_shift,
                        (float(min_gap_pts) - float(xlabel_gap_pts)) / fig_h_pts,
                    )
                except Exception:
                    required_shift = float(min_gap_pts) / fig_h_pts
            required_shift = max(0.002, min(0.05, required_shift))
            try:
                x_pos, y_pos = xlabel_artist.get_position()
                xlabel_artist.set_position(
                    (float(x_pos), float(y_pos) - required_shift)
                )
                adjusted = True
            except Exception:
                pass
            try:
                bottom_now = float(fig.subplotpars.bottom)
                target_bottom = min(0.32, bottom_now + required_shift)
                if authoritative_timeline_bottom is None:
                    fig.subplots_adjust(bottom=target_bottom)
                    if layout_mgr is not None:
                        layout_mgr._baseline_bottom = target_bottom
                    adjusted = True
                    if combined_mode:
                        current_xlabel_pad = None
                        if layout_mgr is not None:
                            current_xlabel_pad = getattr(
                                layout_mgr, "xlabel_pad_pts", None
                            )
                        _layout_health_record_combined_suggestion(
                            fig,
                            mode_norm,
                            margins={"bottom": float(target_bottom)},
                            xlabel_pad_pts=_safe_float(current_xlabel_pad, 0.0),
                            axis_labelpads={
                                "x": _safe_float(current_xlabel_pad, 0.0) or 0.0
                            },
                        )
            except Exception:
                pass

        if (
            (
                "timeline_bottom_margin_label_band_overlap" in issues
                or "bottom_margin_label_band_overlap" in issues
            )
            and bottom_label_band_overlap_pts is not None
            and math.isfinite(float(bottom_label_band_overlap_pts))
            and authoritative_timeline_bottom is None
        ):
            # Raise the axes bottom margin after measuring the rendered legend,
            # x-label, and x tick label band so the plot no longer intrudes into it.
            required_lift_frac = max(
                0.0,
                (float(bottom_label_band_overlap_pts) + 2.0) / fig_h_pts,
            )
            if required_lift_frac > 1e-5:
                try:
                    baseline_bottom = (
                        _safe_float(getattr(layout_mgr, "_baseline_bottom", None))
                        if layout_mgr is not None
                        else None
                    )
                except Exception:
                    baseline_bottom = None
                if baseline_bottom is None:
                    try:
                        baseline_bottom = float(fig.subplotpars.bottom)
                    except Exception:
                        baseline_bottom = 0.0
                target_bottom = min(
                    0.45,
                    max(float(baseline_bottom), 0.02)
                    + min(0.12, float(required_lift_frac)),
                )
                if target_bottom > float(baseline_bottom) + 1e-6:
                    try:
                        if layout_mgr is not None:
                            layout_mgr._baseline_bottom = float(target_bottom)
                        fig.subplots_adjust(bottom=float(target_bottom))
                        adjusted = True
                        if combined_mode:
                            current_xlabel_pad = None
                            if layout_mgr is not None:
                                current_xlabel_pad = getattr(
                                    layout_mgr,
                                    "xlabel_pad_pts",
                                    None,
                                )
                            _layout_health_record_combined_suggestion(
                                fig,
                                mode_norm,
                                margins={"bottom": float(target_bottom)},
                                xlabel_pad_pts=_safe_float(current_xlabel_pad, 0.0),
                                axis_labelpads={
                                    "x": _safe_float(current_xlabel_pad, 0.0) or 0.0
                                },
                            )
                    except Exception:
                        pass

        if (
            axis_label_conflict_checks_enabled
            and timeline_right_axis is not None
            and timeline_right_axis_pos is not None
            and timeline_right_label_bbox is not None
        ):
            needed_right_shift_fig = 0.0
            needed_left_shift_fig = 0.0
            if (
                timeline_right_ticks_bbox is not None
                and "axis_label_tick_overlap" in issues
            ):
                required_left = float(timeline_right_ticks_bbox.x1) + (
                    float(min_axis_label_tick_gap_pts) / fig_w_pts
                )
                needed_right_shift_fig = max(
                    0.0, required_left - float(timeline_right_label_bbox.x0)
                )
            if (
                timeline_right_ticks_bbox is not None
                and "axis_label_tick_gap_high" in issues
            ):
                max_allowed_left = float(timeline_right_ticks_bbox.x1) + (
                    float(max_axis_label_tick_gap_pts) / fig_w_pts
                )
                needed_left_shift_fig = max(
                    needed_left_shift_fig,
                    max(0.0, float(timeline_right_label_bbox.x0) - max_allowed_left),
                )
            if "axis_label_off_canvas_right" in issues:
                needed_left_shift_fig = max(
                    needed_left_shift_fig,
                    float(timeline_right_label_bbox.x1) - 1.0 + (2.0 / fig_w_pts),
                )
            if "axis_label_off_canvas_left" in issues:
                needed_right_shift_fig = max(
                    needed_right_shift_fig,
                    abs(float(timeline_right_label_bbox.x0)) + (2.0 / fig_w_pts),
                )
            shift_fig = needed_right_shift_fig - needed_left_shift_fig
            if abs(shift_fig) > 1e-6:
                shift_fig = max(-0.5, min(0.5, float(shift_fig)))
                axis_width = max(float(timeline_right_axis_pos.width), 1e-6)
                shift_axes = shift_fig / axis_width
                try:
                    current_x, current_y = (
                        timeline_right_axis.yaxis.label.get_position()
                    )
                except Exception:
                    current_x, current_y = (1.12, 0.5)
                new_x = max(0.9, min(2.2, float(current_x) + float(shift_axes)))
                try:
                    timeline_right_axis.yaxis.set_label_coords(new_x, float(current_y))
                    adjusted = True
                except Exception:
                    pass

        if (
            axis_label_conflict_checks_enabled
            and combined_mode
            and combined_axis_metrics
        ):
            primary_label_bbox = combined_primary_metrics.get("label_bbox")
            right_label_bbox = combined_right_metrics.get("label_bbox")
            right_ticks_bbox = combined_right_metrics.get("ticks_bbox")
            third_label_bbox = combined_third_metrics.get("label_bbox")
            third_ticks_bbox = combined_third_metrics.get("ticks_bbox")
            third_axis = combined_third_metrics.get("axis")
            third_axis_pos = combined_third_metrics.get("axis_pos")
            current_offset = combined_third_metrics.get("spine_offset")
            third_spine_x_fig = combined_third_metrics.get("spine_x_fig")
            offset_shift_axes = 0.0
            if (
                primary_label_bbox is not None
                and "combined_primary_axis_label_off_canvas_left" in issues
            ):
                left_clearance_frac = float(combined_edge_clearance_pts) / fig_w_pts
                needed_left_margin_shift = max(
                    0.0,
                    left_clearance_frac - float(primary_label_bbox.x0),
                )
                if needed_left_margin_shift > 1e-6:
                    try:
                        current_left = float(fig.subplotpars.left)
                    except Exception:
                        current_left = 0.12
                    target_left = min(
                        0.45,
                        max(current_left, current_left + needed_left_margin_shift),
                    )
                    if target_left > current_left + 1e-6:
                        try:
                            if layout_mgr is not None:
                                layout_mgr._baseline_left = target_left
                            fig.subplots_adjust(left=target_left)
                            adjusted = True
                            _layout_health_record_combined_suggestion(
                                fig,
                                mode_norm,
                                margins={"left": target_left},
                            )
                        except Exception:
                            pass
            if (
                third_axis is not None
                and third_axis_pos is not None
                and current_offset is not None
            ):
                axis_width = max(float(third_axis_pos.width), 1e-6)
                if (
                    right_label_bbox is not None
                    and third_ticks_bbox is not None
                    and (
                        "combined_right_label_third_ticks_overlap" in issues
                        or "combined_right_label_third_label_overlap" in issues
                    )
                ):
                    required_left = float(right_label_bbox.x1) + (
                        float(min_axis_label_tick_gap_pts) / fig_w_pts
                    )
                    needed_shift_fig = max(
                        0.0,
                        required_left - float(third_ticks_bbox.x0),
                    )
                    offset_shift_axes = max(
                        offset_shift_axes,
                        needed_shift_fig / axis_width,
                    )
                if (
                    third_label_bbox is not None
                    and third_ticks_bbox is not None
                    and "combined_third_axis_label_tick_overlap" in issues
                ):
                    required_label_left = float(third_ticks_bbox.x1) + (
                        float(min_axis_label_tick_gap_pts) / fig_w_pts
                    )
                    needed_shift_fig = max(
                        0.0,
                        required_label_left - float(third_label_bbox.x0),
                    )
                    offset_shift_axes = max(
                        offset_shift_axes,
                        needed_shift_fig / axis_width,
                    )
                if (
                    right_ticks_bbox is not None
                    and third_ticks_bbox is not None
                    and "combined_right_ticks_third_ticks_overlap" in issues
                ):
                    required_ticks_left = float(right_ticks_bbox.x1) + (
                        float(min_axis_label_tick_gap_pts) / fig_w_pts
                    )
                    needed_shift_fig = max(
                        0.0,
                        required_ticks_left - float(third_ticks_bbox.x0),
                    )
                    offset_shift_axes = max(
                        offset_shift_axes,
                        needed_shift_fig / axis_width,
                    )
                if (
                    right_label_bbox is not None
                    and third_spine_x_fig is not None
                    and "combined_right_label_third_axis_gap_low" in issues
                ):
                    required_axis_left = float(right_label_bbox.x1) + (
                        float(min_axis_label_tick_gap_pts) / fig_w_pts
                    )
                    needed_shift_fig = max(
                        0.0,
                        required_axis_left - float(third_spine_x_fig),
                    )
                    offset_shift_axes = max(
                        offset_shift_axes,
                        needed_shift_fig / axis_width,
                    )
                if (
                    right_label_bbox is not None
                    and third_label_bbox is not None
                    and "combined_right_label_third_label_overlap" in issues
                ):
                    required_label_left = float(right_label_bbox.x1) + (
                        float(min_axis_label_tick_gap_pts) / fig_w_pts
                    )
                    needed_shift_fig = max(
                        0.0,
                        required_label_left - float(third_label_bbox.x0),
                    )
                    offset_shift_axes = max(
                        offset_shift_axes,
                        needed_shift_fig / axis_width,
                    )
                if (
                    right_label_bbox is not None
                    and third_ticks_bbox is not None
                    and "combined_right_label_third_ticks_gap_high" in issues
                ):
                    max_allowed_left = float(right_label_bbox.x1) + (
                        float(max_axis_label_tick_gap_pts) / fig_w_pts
                    )
                    needed_shift_fig = min(
                        0.0,
                        max_allowed_left - float(third_ticks_bbox.x0),
                    )
                    offset_shift_axes = min(
                        offset_shift_axes,
                        needed_shift_fig / axis_width,
                    )
                if offset_shift_axes > 1e-6:
                    new_offset = max(
                        1.02,
                        min(
                            DEFAULT_COMBINED_LAYOUT_HEALTH_MAX_DETACHED_OFFSET,
                            float(current_offset) + float(offset_shift_axes),
                        ),
                    )
                elif offset_shift_axes < -1e-6:
                    new_offset = max(
                        1.02,
                        min(
                            DEFAULT_COMBINED_LAYOUT_HEALTH_MAX_DETACHED_OFFSET,
                            float(current_offset) + float(offset_shift_axes),
                        ),
                    )
                else:
                    new_offset = None
                if (
                    new_offset is not None
                    and abs(new_offset - float(current_offset)) > 1e-5
                ):
                    try:
                        third_axis.spines["right"].set_position(("axes", new_offset))
                        adjusted = True
                        _layout_health_record_combined_suggestion(
                            fig,
                            mode_norm,
                            detached_spine_offset=new_offset,
                        )
                    except Exception:
                        pass
            if any(
                issue_name in issues
                for issue_name in (
                    "combined_right_axis_label_off_canvas_right",
                    "combined_third_axis_label_off_canvas_right",
                )
            ):
                max_x1 = 0.0
                for axis_metrics in combined_axis_metrics.values():
                    label_bbox = axis_metrics.get("label_bbox")
                    ticks_bbox = axis_metrics.get("ticks_bbox")
                    for bbox in (label_bbox, ticks_bbox):
                        if bbox is None:
                            continue
                        max_x1 = max(max_x1, float(bbox.x1))
                if max_x1 > 1.0:
                    excess_frac = max_x1 - 1.0 + (2.0 / fig_w_pts)
                    try:
                        current_right = float(fig.subplotpars.right)
                    except Exception:
                        current_right = 0.9
                    target_right = max(0.55, min(0.98, current_right - excess_frac))
                    if target_right < current_right - 1e-6:
                        try:
                            if layout_mgr is not None:
                                layout_mgr._baseline_right = target_right
                            fig.subplots_adjust(right=target_right)
                            adjusted = True
                            _layout_health_record_combined_suggestion(
                                fig,
                                mode_norm,
                                margins={"right": target_right},
                            )
                        except Exception:
                            pass
            if (
                "combined_right_margin_whitespace_high" in issues
                and combined_right_margin_whitespace_pts is not None
                and math.isfinite(float(combined_right_margin_whitespace_pts))
            ):
                whitespace_excess_frac = max(
                    0.0,
                    (
                        float(combined_right_margin_whitespace_pts)
                        - float(combined_edge_clearance_pts)
                    )
                    / fig_w_pts,
                )
                if whitespace_excess_frac > 1e-5:
                    try:
                        current_right = float(fig.subplotpars.right)
                    except Exception:
                        current_right = 0.9
                    target_right = min(
                        0.992,
                        float(current_right) + min(0.10, float(whitespace_excess_frac)),
                    )
                    if target_right > float(current_right) + 1e-6:
                        try:
                            if layout_mgr is not None:
                                layout_mgr._baseline_right = target_right
                            fig.subplots_adjust(right=target_right)
                            adjusted = True
                            _layout_health_record_combined_suggestion(
                                fig,
                                mode_norm,
                                margins={"right": target_right},
                            )
                        except Exception:
                            pass
            if adjusted:
                semantic_pads: Dict[str, float] = {}
                for role_name, axis_metrics in combined_axis_metrics.items():
                    semantic = axis_metrics.get("semantic") or role_name
                    pad_value = axis_metrics.get("labelpad")
                    try:
                        pad_float = float(pad_value)
                    except Exception:
                        continue
                    if math.isfinite(pad_float):
                        semantic_pads[str(semantic)] = pad_float
                _layout_health_record_combined_suggestion(
                    fig,
                    mode_norm,
                    axis_labelpads=semantic_pads,
                )

        if suptitle_artist is not None and "suptitle_off_canvas" in issues:
            try:
                pos = suptitle_artist.get_position()
                suptitle_artist.set_position(
                    (float(pos[0]), float(pos[1]) - (4.0 / fig_h_pts))
                )
                if layout_mgr is not None:
                    try:
                        layout_mgr.suptitle_y = float(suptitle_artist.get_position()[1])
                    except Exception:
                        pass
                adjusted = True
            except Exception:
                pass

        if (
            "timeline_bottom_whitespace_high" in issues
            or "bottom_whitespace_high" in issues
            or (timeline_mode and "timeline_bottom_margin_label_band_overlap" in issues)
        ) and bottom_whitespace_pts is not None:
            skip_authoritative_combined_reclaim = bool(
                combined_mode
                and layout_mgr is not None
                and getattr(layout_mgr, "margins_authoritative", False)
                and _safe_float(getattr(layout_mgr, "_baseline_bottom", None))
                is not None
            )
            skip_authoritative_timeline_reclaim = (
                authoritative_timeline_bottom is not None
            )
            has_bottom_conflict_issue = any(
                issue_name in issues
                for issue_name in (
                    "legend_xlabel_overlap",
                    "legend_xlabel_gap_low",
                    "legend_xticklabels_overlap",
                    "legend_xticklabels_gap_low",
                    "legend_off_canvas",
                )
            )
            if skip_authoritative_combined_reclaim:
                _layout_health_record_combined_suggestion(
                    fig,
                    mode_norm,
                    margins={"bottom": float(fig.subplotpars.bottom)},
                )
            elif skip_authoritative_timeline_reclaim and has_bottom_conflict_issue:
                # Display timeline margins come directly from Plot Settings; keep
                # conflict repair to legend movement only so the subplot tool
                # continues to match the configured margin.
                pass
            elif not has_bottom_conflict_issue:
                timeline_probe_reclaim_applied = False
                if (
                    timeline_mode
                    and timeline_bottom_legend is not None
                    and legend_bbox is not None
                ):
                    bottom_axis = timeline_bottom_axis
                    if bottom_axis is None:
                        bottom_axis = getattr(timeline_bottom_legend, "axes", None)
                    whitespace_excess_pts = max(
                        0.0,
                        float(bottom_whitespace_pts) - float(max_bottom_whitespace_pts),
                    )
                    if bottom_axis is not None and whitespace_excess_pts > 0.25:
                        try:
                            axis_pos = bottom_axis.get_position()
                        except Exception:
                            axis_pos = None
                        axis_height = max(
                            float(axis_pos.height) if axis_pos is not None else 0.0,
                            1e-6,
                        )
                        bbox_axes = _normalize_legend_bbox_anchor_value(
                            getattr(
                                timeline_bottom_legend,
                                "_cycle_timeline_bbox_to_anchor_axes",
                                None,
                            )
                        )
                        if bbox_axes is None:
                            bbox_axes = (0.0, -0.04, 1.0, 0.2)
                        anchor_x = float(bbox_axes[0])
                        anchor_y = float(bbox_axes[1])
                        anchor_w = float(bbox_axes[2])
                        anchor_h = float(bbox_axes[3])
                        desired_floor = float(max_bottom_whitespace_pts) / fig_h_pts
                        legend_floor_excess = max(
                            0.0,
                            float(legend_bbox.y0) - float(desired_floor),
                        )
                        lower_by_axes = min(
                            0.35,
                            max(
                                legend_floor_excess,
                                float(whitespace_excess_pts) / fig_h_pts,
                            )
                            / axis_height,
                        )
                        if lower_by_axes > 1e-6:
                            anchor_y = max(-0.65, min(0.18, anchor_y - lower_by_axes))
                            try:
                                timeline_bottom_legend.set_loc("upper left")
                            except Exception:
                                # Best-effort guard; ignore loc-override failures.
                                pass
                            try:
                                timeline_bottom_legend.set_bbox_to_anchor(
                                    (anchor_x, anchor_y, anchor_w, anchor_h),
                                    transform=bottom_axis.transAxes,
                                )
                                timeline_bottom_legend._cycle_timeline_legend_role = (
                                    "bottom"
                                )
                                wide_attr = "_cycle_timeline_bottom_wide_under_xaxis"
                                setattr(timeline_bottom_legend, wide_attr, True)
                                bbox_attr = "_cycle_timeline_bbox_to_anchor_axes"
                                setattr(
                                    timeline_bottom_legend,
                                    bbox_attr,
                                    (anchor_x, anchor_y, anchor_w, anchor_h),
                                )
                                adjusted = True
                            except Exception:
                                # Best-effort guard; ignore legend-anchor failures.
                                pass
                        timeline_probe_reclaim_applied = (
                            _layout_health_timeline_reclaim_bottom_whitespace_by_probe(
                                fig,
                                canvas=canvas,
                                layout_mgr=layout_mgr,
                                bottom_legend=timeline_bottom_legend,
                                bottom_axis=bottom_axis,
                                max_bottom_whitespace_pts=max_bottom_whitespace_pts,
                                fig_h_pts=fig_h_pts,
                                min_gap_pts=min_gap_pts,
                                allow_bottom_margin_adjust=(
                                    authoritative_timeline_bottom is None
                                ),
                            )
                        )
                        if timeline_probe_reclaim_applied:
                            adjusted = True
                gap_ready_for_reclaim = gap_pts is not None and math.isfinite(
                    float(gap_pts)
                )
                geometry_ready_for_reclaim = legend_bbox is not None and (
                    (timeline_mode and not timeline_probe_reclaim_applied)
                    or (gap_ready_for_reclaim and primary_xticks_bbox is not None)
                )
                if geometry_ready_for_reclaim:
                    # Keep subplot expansion bounded to preserve label/legend safety
                    # while reclaiming large dead space below the bottom legend.
                    whitespace_excess_pts = max(
                        0.0,
                        float(bottom_whitespace_pts) - float(max_bottom_whitespace_pts),
                    )
                    shrink_bottom_frac = min(0.08, whitespace_excess_pts / fig_h_pts)
                    if gap_ready_for_reclaim and not timeline_mode:
                        # Gap metrics are optional for timeline whitespace-only
                        # reclaim, but when available they bound the move.
                        spare_gap_pts = max(
                            0.0,
                            float(gap_pts) - float(min_gap_pts) - 1.0,
                        )
                        shrink_bottom_frac = min(
                            shrink_bottom_frac,
                            spare_gap_pts / fig_h_pts,
                        )
                    if primary_xticks_bbox is not None and not timeline_mode:
                        tick_gap_pts_now = float(
                            (primary_xticks_bbox.y0 - legend_bbox.y1) * fig_h_pts
                        )
                        spare_tick_gap_pts = max(
                            0.0,
                            float(tick_gap_pts_now) - float(min_gap_pts) - 1.0,
                        )
                        shrink_bottom_frac = min(
                            shrink_bottom_frac,
                            spare_tick_gap_pts / fig_h_pts,
                        )
                    if shrink_bottom_frac > 1e-5:
                        baseline_bottom = None
                        if layout_mgr is not None:
                            try:
                                baseline_bottom = _safe_float(
                                    getattr(layout_mgr, "_baseline_bottom", None)
                                )
                            except Exception:
                                baseline_bottom = None
                        if baseline_bottom is None:
                            try:
                                baseline_bottom = float(fig.subplotpars.bottom)
                            except Exception:
                                baseline_bottom = 0.0
                        target_bottom = max(
                            0.02, float(baseline_bottom) - shrink_bottom_frac
                        )
                        if target_bottom < float(baseline_bottom) - 1e-6:
                            if authoritative_timeline_bottom is not None:
                                target_bottom = float(authoritative_timeline_bottom)
                            if layout_mgr is not None:
                                try:
                                    layout_mgr._baseline_bottom = float(target_bottom)
                                    if not combined_mode:
                                        fig.subplots_adjust(bottom=float(target_bottom))
                                    adjusted = True
                                    if combined_mode:
                                        _layout_health_record_combined_suggestion(
                                            fig,
                                            mode_norm,
                                            margins={"bottom": float(target_bottom)},
                                        )
                                except Exception:
                                    try:
                                        fig.subplots_adjust(bottom=float(target_bottom))
                                        adjusted = True
                                        if combined_mode:
                                            _layout_health_record_combined_suggestion(
                                                fig,
                                                mode_norm,
                                                margins={
                                                    "bottom": float(target_bottom)
                                                },
                                            )
                                    except Exception:
                                        pass
                            else:
                                try:
                                    fig.subplots_adjust(bottom=float(target_bottom))
                                    adjusted = True
                                    if combined_mode:
                                        _layout_health_record_combined_suggestion(
                                            fig,
                                            mode_norm,
                                            margins={"bottom": float(target_bottom)},
                                        )
                                except Exception:
                                    pass
                else:
                    # Require measurable gap geometry before reclaiming whitespace.
                    # This prevents reclaim from over-shrinking during transient
                    # passes where xlabel/tick bounds are not yet stable.
                    pass

        if "axes_over_compressed" in issues and layout_mgr is not None:
            try:
                layout_mgr.legend_gap_pts = max(
                    min_gap_pts, float(layout_mgr.legend_gap_pts) * 0.85
                )
                layout_mgr.legend_margin_pts = max(
                    2.0, float(layout_mgr.legend_margin_pts) * 0.9
                )
                adjusted = True
            except Exception:
                pass
        if "axes_over_compressed" in issues and layout_mgr is None:
            try:
                bottom_now = float(fig.subplotpars.bottom)
                fig.subplots_adjust(bottom=max(0.06, bottom_now - 0.012))
                adjusted = True
            except Exception:
                pass

        if not adjusted:
            break
        result["applied"] = True
        try:
            if layout_mgr is not None:
                layout_mgr.solve(max_passes=1, allow_draw=False)
            else:
                fig.canvas.draw_idle()
            if authoritative_timeline_bottom is not None:
                fig.subplots_adjust(bottom=float(authoritative_timeline_bottom))
        except Exception:
            pass

    try:
        result["elapsed_ms"] = (time.perf_counter() - autofix_started) * 1000.0
    except Exception:
        result["elapsed_ms"] = 0.0
    if combined_mode:
        suggestions = getattr(fig, "_gl260_combined_layout_suggestions", None)
        if isinstance(suggestions, Mapping):
            result["suggestions"] = copy.deepcopy(dict(suggestions))
    return result


class PlotLayoutManager:
    """Deterministic layout solver for combined triple-axis figures."""

    def __init__(
        self,
        fig: Figure,
        *,
        mode: str = "display",
        baseline_margins: Optional[Mapping[str, float]] = None,
        left_pad_pct: float = 0.0,
        right_pad_pct: float = 0.0,
        export_pad_pts: float = 0.0,
        margins_authoritative: bool = False,
        legend_gap_pts: float = DEFAULT_COMBINED_LEGEND_GAP_PTS,
        xlabel_tick_gap_pts: float = DEFAULT_COMBINED_XLABEL_TICK_GAP_PTS,
        legend_margin_pts: float = DEFAULT_COMBINED_LEGEND_MARGIN_PTS,
        title_pad_pts: float = DEFAULT_COMBINED_TITLE_PAD_PTS,
        suptitle_pad_pts: float = DEFAULT_COMBINED_SUPTITLE_PAD_PTS,
        suptitle_y: float = DEFAULT_COMBINED_SUPTITLE_Y,
        top_margin_pct: float = DEFAULT_COMBINED_TOP_MARGIN_PCT,
        legend_anchor: Optional[Tuple[float, float]] = None,
        legend_anchor_y: Optional[float] = None,
        xlabel_pad_pts: float = 0.0,
    ) -> None:
        """Initialize deterministic layout solving state for one figure.

        Purpose:
            Capture baseline bounds and spacing controls used by `solve`.
        Why:
            Layout workflows call this manager repeatedly for display/export
            solves, so inputs are normalized once at initialization.
        Inputs:
            fig: Target Matplotlib figure to manage.
            mode: Layout mode ("display" or "export").
            baseline_margins: Optional profile margins in figure fractions.
            left_pad_pct/right_pad_pct/export_pad_pts: Legacy padding controls.
            margins_authoritative: When True, profile margins are treated as
                primary bounds and padding/top-margin controls are safety-only.
            legend/title/xlabel spacing and anchor values: See parameter names.
        Outputs:
            None.
        Side Effects:
            Stores normalized layout parameters on the instance.
        Exceptions:
            Invalid numeric inputs are sanitized with best-effort fallbacks.
        """
        self.fig = fig
        self.mode = "export" if str(mode).lower() == "export" else "display"
        if baseline_margins is None:
            baseline_margins = {}
        self._baseline_left = None
        self._baseline_right = None
        self._baseline_top = None
        self._baseline_bottom = None
        # Iterate to apply the per-item logic.
        for key, attr in (
            ("left", "_baseline_left"),
            ("right", "_baseline_right"),
            ("top", "_baseline_top"),
            ("bottom", "_baseline_bottom"),
        ):
            try:
                raw = float(baseline_margins.get(key))
            except Exception:
                raw = None
            if raw is not None and math.isfinite(raw):
                setattr(self, attr, max(0.0, min(1.0, raw)))
        self.left_pad_pct = float(left_pad_pct or 0.0)
        self.right_pad_pct = float(right_pad_pct or 0.0)
        self.export_pad_pts = float(export_pad_pts or 0.0)
        self.margins_authoritative = bool(margins_authoritative)
        self.legend_gap_pts = float(legend_gap_pts or 0.0)
        self.xlabel_tick_gap_pts = float(xlabel_tick_gap_pts or 0.0)
        self.legend_margin_pts = float(legend_margin_pts or 0.0)
        self.title_pad_pts = float(title_pad_pts or 0.0)
        self.suptitle_pad_pts = float(suptitle_pad_pts or 0.0)
        self.suptitle_y = float(suptitle_y or DEFAULT_COMBINED_SUPTITLE_Y)
        self.top_margin_pct = float(top_margin_pct or DEFAULT_COMBINED_TOP_MARGIN_PCT)
        self.legend_anchor = _validated_anchor_pair(legend_anchor)
        self.legend_anchor_y = None
        if legend_anchor_y is not None:
            try:
                anchor_value = float(legend_anchor_y)
            except Exception:
                anchor_value = None
            if anchor_value is not None and math.isfinite(anchor_value):
                self.legend_anchor_y = max(-0.1, min(1.1, anchor_value))
        self.xlabel_pad_pts = float(xlabel_pad_pts or 0.0)
        self.legend_alignment = "center"
        self._axes: List[Axes] = []
        self._artists: Dict[str, Any] = {}

    def register_axes(self, *axes: Optional[Axes]) -> None:
        """Perform register axes.
        Used to keep the workflow logic localized and testable."""
        self._axes = [ax for ax in axes if ax is not None and ax.get_visible()]

    def register_artist(self, key: str, artist: Any) -> None:
        """Perform register artist.
        Used to keep the workflow logic localized and testable."""
        if artist is None:
            return
        self._artists[key] = artist

    def set_legend_alignment(self, alignment: str) -> None:
        """Set legend alignment.
        Used to persist legend alignment into the current state."""
        self.legend_alignment = _normalize_legend_alignment(alignment)

    def _get_renderer(self, allow_draw: bool = True):
        """Return renderer.
        Used to retrieve renderer for downstream logic."""
        canvas = self.fig.canvas
        if canvas is None:
            canvas = FigureCanvasAgg(self.fig)
            try:
                self.fig.set_canvas(canvas)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        if allow_draw:
            try:
                canvas.draw()
            except Exception:
                try:
                    canvas.draw_idle()
                    canvas.draw()
                except Exception:
                    pass
        try:
            return canvas.get_renderer()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            return None

    def _bbox_in_fig(self, artist: Any, renderer) -> Optional[Bbox]:
        """Perform bbox in fig.
        Used to keep the workflow logic localized and testable."""
        if artist is None or renderer is None:
            return None
        try:
            bbox = artist.get_window_extent(renderer=renderer)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            return None
        if bbox is None:
            return None
        try:
            return bbox.transformed(self.fig.transFigure.inverted())
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            return None

    def _axes_union_position(self) -> Optional[Bbox]:
        """Perform axes union position.
        Used to keep the workflow logic localized and testable."""
        positions = []
        registered = getattr(self.fig, "_gl260_layout_artists", {})
        extra_axes = (
            [artist for artist in registered.values() if isinstance(artist, Axes)]
            if isinstance(registered, Mapping)
            else []
        )
        # Inset colorbar axes are registered separately because they are not data axes.
        for ax in [*self._axes, *extra_axes]:
            try:
                if not ax.get_visible():
                    continue
                positions.append(ax.get_position())
            except Exception:
                continue
        if not positions:
            return None
        try:
            return Bbox.union(positions)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            return None

    def _axes_tight_union(self, renderer) -> Optional[Bbox]:
        """Perform axes tight union.
        Used to keep the workflow logic localized and testable."""
        bboxes = []
        registered = getattr(self.fig, "_gl260_layout_artists", {})
        extra_axes = (
            [artist for artist in registered.values() if isinstance(artist, Axes)]
            if isinstance(registered, Mapping)
            else []
        )
        # Include inset colorbar axes in measured bounds without assigning extra
        # external geometry to background images or LineCollections.
        for ax in [*self._axes, *extra_axes]:
            try:
                if not ax.get_visible():
                    continue
                tight = ax.get_tightbbox(renderer)
            except Exception:
                tight = None
            if tight is None:
                continue
            try:
                bboxes.append(tight.transformed(self.fig.transFigure.inverted()))
            except Exception:
                continue
        if not bboxes:
            return None
        try:
            return Bbox.union(bboxes)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            return None

    def _legend_anchor(
        self, pad: float, center_x: Optional[float] = None
    ) -> Tuple[str, float]:
        """Perform legend anchor.
        Used to keep the workflow logic localized and testable."""
        alignment = _normalize_legend_alignment(self.legend_alignment)
        if alignment == "left":
            return ("lower left", pad)
        if alignment == "right":
            return ("lower right", 1.0 - pad)
        if center_x is None:
            center_x = self.fig.subplotpars.left + (
                (self.fig.subplotpars.right - self.fig.subplotpars.left) / 2.0
            )
        return ("lower center", center_x)

    def solve(self, *, max_passes: int = 3, allow_draw: bool = True) -> None:
        """Run the deterministic layout solve across one or more passes.

        Purpose:
            Resolve subplot bounds and dependent artist positions.
        Why:
            Combined/core plots need reproducible geometry for display and export.
        Inputs:
            max_passes: Maximum adjustment passes before stopping.
            allow_draw: When True, renderer draws are permitted for measurements.
        Outputs:
            None.
        Side Effects:
            Updates subplot margins and artist anchor/position metadata.
        Exceptions:
            Uses best-effort guards around draw/bbox operations.
        """
        if not self._axes:
            return
        # Conservative margins: prioritize visibility over tightness.

        fig_w_in, fig_h_in = self.fig.get_size_inches()
        fig_w_in = max(float(fig_w_in), 1.0)
        fig_h_in = max(float(fig_h_in), 1.0)
        fig_h_pts = max(fig_h_in * 72.0, 1.0)

        pad_frac_x = 0.0
        pad_frac_y = 0.0
        if self.mode == "export":
            pad_frac_x = (self.export_pad_pts / 72.0) / fig_w_in
            pad_frac_y = (self.export_pad_pts / 72.0) / fig_h_in

        legend_xlabel_gap_frac = max(self.legend_gap_pts / fig_h_pts, 0.0)
        xlabel_tick_gap_frac = max(self.xlabel_tick_gap_pts / fig_h_pts, 0.0)
        legend_margin_frac = max(self.legend_margin_pts / fig_h_pts, 0.006)
        title_gap_frac = max(self.title_pad_pts / fig_h_pts, 0.01)
        suptitle_gap_frac = max(self.suptitle_pad_pts / fig_h_pts, 0.01)
        epsilon_frac = 3.0 / fig_h_pts
        xlabel_pad_frac = self.xlabel_pad_pts / fig_h_pts

        base_left = (
            self._baseline_left
            if self._baseline_left is not None
            else self.fig.subplotpars.left
        )
        base_right = (
            self._baseline_right
            if self._baseline_right is not None
            else self.fig.subplotpars.right
        )
        base_bottom = (
            self._baseline_bottom
            if self._baseline_bottom is not None
            else self.fig.subplotpars.bottom
        )
        base_top = (
            self._baseline_top
            if self._baseline_top is not None
            else self.fig.subplotpars.top
        )
        if self.margins_authoritative:
            # Authoritative mode honors profile margins as the primary bounds.
            left = max(base_left, 0.0)
            right = min(base_right, 1.0)
            bottom = max(base_bottom, 0.0)
            top = min(base_top, 1.0)
        else:
            left = max(
                base_left,
                self.left_pad_pct / 100.0 + pad_frac_x,
                0.08,
            )
            right = min(
                base_right,
                1.0 - self.right_pad_pct / 100.0 - pad_frac_x,
                0.98,
            )
            bottom = max(base_bottom, pad_frac_y, 0.1)
            top = min(
                base_top,
                max(0.6, 1.0 - (self.top_margin_pct / 100.0) - pad_frac_y),
            )
        # Keep a minimal valid solve area even when profile data is malformed.
        if right <= left + 0.05:
            right = min(1.0, left + 0.05)
            left = max(0.0, right - 0.05)
        if top <= bottom + 0.2:
            top = min(1.0, bottom + 0.2)
            bottom = max(0.0, top - 0.2)
        last_state = None

        title = self._artists.get("title")
        suptitle = self._artists.get("suptitle")
        xlabel = self._artists.get("xlabel")
        legend = self._artists.get("plot_legend")
        if legend is None:
            candidate_bottom = self._artists.get("plot_legend_bottom")
            candidate_role = (
                str(getattr(candidate_bottom, "_cycle_timeline_legend_role", ""))
                .strip()
                .lower()
            )
            if candidate_bottom is not None and candidate_role == "bottom":
                legend = candidate_bottom
        legend_role = (
            str(getattr(legend, "_cycle_timeline_legend_role", "")).strip().lower()
            if legend is not None
            else ""
        )
        legend_is_timeline_bottom = legend_role == "bottom"
        if legend_role == "top":
            # Defensive guard: top timeline subplot legends must stay axis-local
            # and should never route through the figure-level spacing solver.
            legend = None
            legend_is_timeline_bottom = False
        cycle_legend = self._artists.get("cycle_legend")
        primary_axis = self._axes[0] if self._axes else None
        xlabel_axis = primary_axis
        if legend_is_timeline_bottom and len(self._axes) > 1:
            # Timeline figures register the upper species axis first, but their
            # x-label belongs to the lower pH/uptake axis.
            xlabel_axis = self._axes[1]

        # Iterate over the configured range to apply the per-item logic.
        for _ in range(max_passes):
            self.fig.subplots_adjust(left=left, right=right, bottom=bottom, top=top)
            renderer = self._get_renderer(allow_draw)
            axes_bbox = self._axes_union_position()
            main_center_x = None
            if primary_axis is not None:
                try:
                    pos = primary_axis.get_position()
                    main_center_x = pos.x0 + (pos.width / 2.0)
                except Exception:
                    main_center_x = None

            if title is not None and axes_bbox is not None and axes_bbox.height > 0:
                title_bbox = self._bbox_in_fig(title, renderer)
                if title_bbox is not None:
                    desired_bottom = axes_bbox.y1 + title_gap_frac
                    desired_center = desired_bottom + (title_bbox.height / 2.0)
                    axes_y = (desired_center - axes_bbox.y0) / axes_bbox.height
                    try:
                        title.set_position((0.5, max(1.0, axes_y)))
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting the workflow.
                        pass

            if suptitle is not None:
                base_y = max(0.85, min(0.98, self.suptitle_y))
                try:
                    suptitle.set_y(base_y)
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
                if main_center_x is not None:
                    try:
                        suptitle.set_x(main_center_x)
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting the workflow.
                        pass

            anchor_x = None
            anchor_y = None
            if self.legend_anchor is not None:
                anchor_x, anchor_y = self.legend_anchor
            legend_anchor_y = max(legend_margin_frac, pad_frac_y)
            if anchor_y is not None:
                legend_anchor_y = max(legend_anchor_y, anchor_y)
            if self.legend_anchor_y is not None:
                legend_anchor_y = max(legend_anchor_y, self.legend_anchor_y)
            if legend is not None and not legend_is_timeline_bottom:
                loc = None
                if anchor_x is None:
                    loc, anchor_x = self._legend_anchor(
                        max(0.0, pad_frac_x), main_center_x
                    )
                try:
                    if loc is not None:
                        legend.set_loc(loc)
                    legend.set_bbox_to_anchor(
                        (anchor_x, legend_anchor_y),
                        transform=self.fig.transFigure,
                    )
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass

            renderer = self._get_renderer(allow_draw)
            legend_bbox = self._bbox_in_fig(legend, renderer) if legend else None
            if (
                legend is not None
                and legend_bbox is not None
                and not legend_is_timeline_bottom
            ):
                if legend_bbox.y0 < legend_anchor_y:
                    shift = legend_anchor_y - legend_bbox.y0
                    if anchor_x is None:
                        loc, anchor_x = self._legend_anchor(
                            max(0.0, pad_frac_x), main_center_x
                        )
                    try:
                        legend.set_bbox_to_anchor(
                            (anchor_x, legend_bbox.y0 + shift),
                            transform=self.fig.transFigure,
                        )
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting the workflow.
                        pass

            renderer = self._get_renderer(allow_draw)
            data_axes_tight = self._axes_tight_union(renderer)
            legend_bbox = self._bbox_in_fig(legend, renderer) if legend else None
            xlabel_bbox = self._bbox_in_fig(xlabel, renderer) if xlabel else None
            xlabel_axes_tight = None
            if xlabel_axis is not None:
                try:
                    xlabel_tight_bbox = xlabel_axis.get_tightbbox(renderer)
                except Exception:
                    xlabel_tight_bbox = None
                if xlabel_tight_bbox is not None:
                    try:
                        xlabel_axes_tight = xlabel_tight_bbox.transformed(
                            self.fig.transFigure.inverted()
                        )
                    except Exception:
                        xlabel_axes_tight = None
            xlabel_anchor_x = None
            if xlabel is not None:
                xlabel_height = xlabel_bbox.height if xlabel_bbox is not None else 0.02
                axes_ref = (
                    xlabel_axes_tight
                    if xlabel_axes_tight is not None
                    else data_axes_tight if data_axes_tight is not None else axes_bbox
                )
                if axes_ref is None:
                    baseline = (
                        legend_bbox.y1 if legend_bbox is not None else legend_anchor_y
                    )
                    desired_y = (
                        baseline + legend_xlabel_gap_frac + (xlabel_height / 2.0)
                    )
                    desired_y += xlabel_pad_frac
                else:
                    desired_y = (
                        axes_ref.y0 - xlabel_tick_gap_frac - (xlabel_height / 2.0)
                    )
                    desired_y += xlabel_pad_frac
                if legend_bbox is not None:
                    min_center = (
                        legend_bbox.y1 + legend_xlabel_gap_frac + (xlabel_height / 2.0)
                    )
                    if desired_y < min_center:
                        desired_y = min_center
                # Clamp xlabel center into the lower label band so malformed anchors
                # cannot push it into the data region on compact compare panes.
                band_floor = max(
                    pad_frac_y + (xlabel_height / 2.0) + epsilon_frac,
                    legend_margin_frac + (xlabel_height / 2.0),
                )
                if legend_bbox is not None:
                    band_floor = max(
                        band_floor,
                        legend_bbox.y1 + legend_xlabel_gap_frac + (xlabel_height / 2.0),
                    )
                upper_ref = axes_bbox.y0 if axes_bbox is not None else None
                if upper_ref is None and primary_axis is not None:
                    try:
                        upper_ref = primary_axis.get_position().y0
                    except Exception:
                        upper_ref = None
                if upper_ref is None:
                    upper_ref = 0.32
                band_ceiling = upper_ref - xlabel_tick_gap_frac - (xlabel_height / 2.0)
                if not math.isfinite(band_ceiling):
                    band_ceiling = band_floor + epsilon_frac
                if band_ceiling < band_floor:
                    band_ceiling = band_floor + epsilon_frac
                desired_y = max(band_floor, min(desired_y, band_ceiling))
                try:
                    xlabel_anchor_x = None
                    if xlabel_axis is not None:
                        try:
                            xlabel_pos = xlabel_axis.get_position()
                            xlabel_anchor_x = xlabel_pos.x0 + (xlabel_pos.width / 2.0)
                        except Exception:
                            xlabel_anchor_x = None
                    if xlabel_anchor_x is None:
                        xlabel_anchor_x = main_center_x
                    if xlabel_anchor_x is None:
                        xlabel_anchor_x = self.fig.subplotpars.left + (
                            (self.fig.subplotpars.right - self.fig.subplotpars.left)
                            / 2.0
                        )
                    xlabel.set_position((xlabel_anchor_x, desired_y))
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass

            renderer = self._get_renderer(allow_draw)
            legend_bbox = self._bbox_in_fig(legend, renderer) if legend else None
            xlabel_bbox = self._bbox_in_fig(xlabel, renderer) if xlabel else None
            if xlabel_bbox is not None and not self.margins_authoritative:
                bottom = max(bottom, xlabel_bbox.y1 + xlabel_tick_gap_frac)
            if legend_bbox is not None and xlabel_bbox is not None:
                gap = xlabel_bbox.y0 - legend_bbox.y1
                if gap < legend_xlabel_gap_frac:
                    shift = (legend_xlabel_gap_frac - gap) + epsilon_frac
                    try:
                        if xlabel_anchor_x is None:
                            xlabel_anchor_x = main_center_x
                            if xlabel_anchor_x is None:
                                xlabel_anchor_x = self.fig.subplotpars.left + (
                                    (
                                        self.fig.subplotpars.right
                                        - self.fig.subplotpars.left
                                    )
                                    / 2.0
                                )
                        xlabel.set_position(
                            (xlabel_anchor_x, xlabel.get_position()[1] + shift)
                        )
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting the workflow.
                        pass
                    renderer = self._get_renderer(allow_draw)
                    xlabel_bbox = (
                        self._bbox_in_fig(xlabel, renderer) if xlabel else None
                    )
                    if xlabel_bbox is not None and not self.margins_authoritative:
                        bottom = max(bottom, xlabel_bbox.y1 + xlabel_tick_gap_frac)
            renderer = self._get_renderer(allow_draw)
            title_bbox = self._bbox_in_fig(title, renderer) if title else None
            suptitle_bbox = self._bbox_in_fig(suptitle, renderer) if suptitle else None

            if suptitle is not None and suptitle_bbox is not None:
                if suptitle_bbox.y1 > 1.0 - pad_frac_y:
                    try:
                        suptitle.set_y(
                            suptitle.get_position()[1]
                            - (suptitle_bbox.y1 - (1.0 - pad_frac_y))
                        )
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting the workflow.
                        pass

            renderer = self._get_renderer(allow_draw)
            suptitle_bbox = self._bbox_in_fig(suptitle, renderer) if suptitle else None

            if (
                cycle_legend is not None
                and primary_axis is not None
                and axes_bbox is not None
            ):
                cycle_anchor_setting = _validated_anchor_pair(
                    settings.get("combined_cycle_legend_anchor")
                )
                if cycle_anchor_setting is None:
                    cycle_loc_choice = settings.get(
                        "combined_cycle_legend_loc_choice", "upper right"
                    )
                    normalized_cycle_loc = _normalize_legend_loc_value(cycle_loc_choice)
                    if normalized_cycle_loc is None:
                        normalized_cycle_loc = "upper right"
                    try:
                        if normalized_cycle_loc is not None:
                            cycle_legend.set_loc(normalized_cycle_loc)
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting the workflow.
                        pass

            renderer = self._get_renderer(allow_draw)
            data_axes_tight = self._axes_tight_union(renderer)
            if cycle_legend is not None:
                cycle_bbox = self._bbox_in_fig(cycle_legend, renderer)
            else:
                cycle_bbox = None
            if data_axes_tight is not None and cycle_bbox is not None:
                union_lr = Bbox.union([data_axes_tight, cycle_bbox])
            else:
                union_lr = (
                    data_axes_tight if data_axes_tight is not None else cycle_bbox
                )

            if union_lr is not None and not self.margins_authoritative:
                if union_lr.x0 < max(0.0, pad_frac_x):
                    left = min(
                        right - 0.1,
                        max(left + (max(0.0, pad_frac_x) - union_lr.x0), 0.05),
                    )
                if union_lr.x1 > 1.0 - max(0.0, pad_frac_x):
                    right = max(
                        left + 0.1,
                        min(
                            right - (union_lr.x1 - (1.0 - max(0.0, pad_frac_x))),
                            0.98,
                        ),
                    )
            if (
                data_axes_tight is not None
                and xlabel_bbox is not None
                and not self.margins_authoritative
            ):
                min_axes_bottom = xlabel_bbox.y1 + xlabel_tick_gap_frac
                if data_axes_tight.y0 < min_axes_bottom:
                    bottom = max(
                        bottom, bottom + (min_axes_bottom - data_axes_tight.y0)
                    )

            if (
                suptitle_bbox is not None
                and title_bbox is not None
                and suptitle_bbox.y0 < title_bbox.y1 + suptitle_gap_frac
                and not self.margins_authoritative
            ):
                overlap = (title_bbox.y1 + suptitle_gap_frac) - suptitle_bbox.y0
                top = max(bottom + 0.2, top - overlap)

            new_state = (
                round(left, 4),
                round(right, 4),
                round(bottom, 4),
                round(top, 4),
            )
            if new_state == last_state:
                break
            last_state = new_state
        plot_id_norm = str(
            getattr(self.fig, "_gl260_plot_id", "") or ""
        ).strip().lower()
        if plot_id_norm == "fig_cycle_timeline":
            # Timeline layout health runs through an explicit verifier; skipping
            # the implicit solve-time autofix avoids recursive draw-heavy passes.
            return
        if bool(getattr(self.fig, "_gl260_layout_health_active", False)):
            return
        try:
            self.fig._gl260_layout_health_active = True  # type: ignore[attr-defined]
            autofix_result = layout_health_autofix(
                self.fig,
                getattr(self.fig, "_gl260_plot_id", None),
                self.mode,
                settings,
            )
            self.fig._gl260_last_layout_health_result = autofix_result  # type: ignore[attr-defined]
        except Exception:
            # Best-effort guard; ignore auto-fix failures to preserve primary solve stability.
            pass
        finally:
            try:
                self.fig._gl260_layout_health_active = False  # type: ignore[attr-defined]
            except Exception:
                pass


def _resolve_combined_right_axis_bindings(
    dataset_meta: Mapping[str, Mapping[str, Any]],
    *,
    right_key: str,
    third_key: str,
    temp_axis_active: bool,
    deriv_axis_active: bool,
) -> Dict[str, Any]:
    """Resolve Combined right-axis role bindings for inner/outer axis positions.

    Purpose:
        Determine which dataset role (temperature/derivative) is assigned to the
        inner-right and outer-right axis positions.
    Why:
        Combined settings must honor user swaps between inner-right and outer-right
        datasets while preserving axis-type guardrails and availability checks.
    Inputs:
        dataset_meta: Per-dataset metadata keyed by dataset id (`y1`, `y2`, `z`, etc.).
        right_key: Requested dataset key for the inner-right axis.
        third_key: Requested dataset key for the outer-right axis.
        temp_axis_active: Whether temperature axis rendering is enabled/available.
        deriv_axis_active: Whether derivative axis rendering is enabled/available.
    Outputs:
        Dict containing resolved right/third axis role assignments and positions.
    Side Effects:
        None.
    Exceptions:
        Invalid keys or unavailable datasets fall back to available role defaults
        unless the outer-right axis is explicitly disabled with `"none"`.
    """
    third_axis_disabled = str(third_key or "").strip().lower() == "none"

    def _is_available(key: str) -> bool:
        """Check whether a dataset can populate a combined right-side axis.

        Purpose:
            Recognize both legacy single-series data and Columns-tab grouped
            trace entries when assigning temperature or derivative axes.
        Why:
            Grouped traces are the authoritative representation for multi-column
            selections, so ignoring them can remove valid detached axes in a
            full preview/export rebuild.
        Inputs:
            key: Dataset role key such as ``"y2"``, ``"z"``, or ``"z2"``.
        Outputs:
            True when the selected dataset has a direct series or at least one
            valid grouped trace entry; otherwise False.
        Side Effects:
            None.
        Exceptions:
            Malformed metadata is treated as unavailable.
        """
        meta = dataset_meta.get(key) or {}
        if not meta.get("selected"):
            return False
        if meta.get("series") is not None:
            return True
        entries = meta.get("entries")
        return bool(
            isinstance(entries, Sequence)
            and not isinstance(entries, (str, bytes))
            and any(
                isinstance(entry, Mapping) and entry.get("series") is not None
                for entry in entries
            )
        )

    temp_keys_available = [key for key in ("z", "z2") if _is_available(key)]
    temperature_available = bool(temp_axis_active and temp_keys_available)
    derivative_available = bool(deriv_axis_active and _is_available("y2"))

    def _requested_assignment(key: str) -> Optional[Tuple[str, str]]:
        """Translate one requested dataset key to a valid right-axis role assignment."""
        meta = dataset_meta.get(key) or {}
        axis_role = str(meta.get("axis_type", "primary")).strip().lower()
        if axis_role == "temperature":
            if not temperature_available:
                return None
            if key in temp_keys_available:
                return ("temperature", key)
            return ("temperature", temp_keys_available[0])
        if axis_role == "derivative":
            if not derivative_available:
                return None
            return ("derivative", "y2")
        return None

    requested_by_position = {
        "right": _requested_assignment(right_key),
        "third": None if third_axis_disabled else _requested_assignment(third_key),
    }
    assigned_by_position: Dict[str, Optional[Tuple[str, str]]] = {
        "right": None,
        "third": None,
    }
    used_roles: Set[str] = set()

    # First pass: honor explicit position requests when valid and non-duplicated.
    for position in ("right", "third"):
        requested = requested_by_position[position]
        if requested is None:
            continue
        role_name, dataset_key = requested
        if role_name in used_roles:
            continue
        assigned_by_position[position] = (role_name, dataset_key)
        used_roles.add(role_name)

    preferred_temp_key = None
    # Keep the originally requested temperature trace (z vs z2) when possible.
    for candidate in (right_key, third_key):
        if candidate in temp_keys_available:
            preferred_temp_key = candidate
            break
    if preferred_temp_key is None and temp_keys_available:
        preferred_temp_key = temp_keys_available[0]

    fallback_roles: List[Tuple[str, str]] = []
    if temperature_available and preferred_temp_key is not None:
        fallback_roles.append(("temperature", preferred_temp_key))
    if derivative_available:
        fallback_roles.append(("derivative", "y2"))

    # Second pass: fill any empty axis position from the remaining available roles.
    for position in ("right", "third"):
        if position == "third" and third_axis_disabled:
            continue
        if assigned_by_position[position] is not None:
            continue
        for role_name, dataset_key in fallback_roles:
            if role_name in used_roles:
                continue
            assigned_by_position[position] = (role_name, dataset_key)
            used_roles.add(role_name)
            break

    def _assignment_payload(
        assignment: Optional[Tuple[str, str]],
    ) -> Optional[Dict[str, Any]]:
        """Normalize one resolved assignment into metadata used by render paths."""
        if assignment is None:
            return None
        role_name, dataset_key = assignment
        meta = dataset_meta.get(dataset_key)
        if not isinstance(meta, Mapping):
            return None
        return {"role": role_name, "key": dataset_key, "meta": meta}

    right_payload = _assignment_payload(assigned_by_position["right"])
    third_payload = _assignment_payload(assigned_by_position["third"])
    role_positions: Dict[str, str] = {}
    if right_payload is not None:
        role_positions[str(right_payload["role"])] = "right"
    if third_payload is not None:
        role_positions[str(third_payload["role"])] = "third"

    return {
        "right": right_payload,
        "third": third_payload,
        "right_role": right_payload["role"] if right_payload is not None else None,
        "third_role": third_payload["role"] if third_payload is not None else None,
        "temperature_position": role_positions.get("temperature"),
        "derivative_position": role_positions.get("derivative"),
    }


def _normalize_combined_exclusion_ranges(value: Any) -> list[tuple[float, float]]:
    """Normalize reversible source-x exclusions for the combined plot.

    Purpose:
        Convert saved or newly selected ranges into sorted, merged finite pairs.
    Why:
        A canonical range list makes compression deterministic and prevents
        overlapping selections from subtracting time more than once.
    Inputs:
        value: Iterable of two-value range candidates in source x-axis units.
    Returns:
        Sorted non-overlapping ``(start, end)`` float pairs.
    Side Effects:
        None.
    Exceptions:
        Malformed or non-finite candidates are ignored.
    """
    candidates: list[tuple[float, float]] = []
    if not isinstance(value, Sequence) or isinstance(value, (str, bytes)):
        return candidates
    for item in value:
        if (
            not isinstance(item, Sequence)
            or isinstance(item, (str, bytes))
            or len(item) < 2
        ):
            continue
        start = _coerce_float(item[0])
        end = _coerce_float(item[1])
        if (
            start is None
            or end is None
            or not math.isfinite(start)
            or not math.isfinite(end)
        ):
            continue
        low, high = sorted((float(start), float(end)))
        if high - low > 1e-12:
            candidates.append((low, high))
    candidates.sort()
    merged: list[tuple[float, float]] = []
    for start, end in candidates:
        if merged and start <= merged[-1][1] + 1e-12:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))
    return merged


def _combined_exclusion_display_x(
    values: Any, ranges: list[tuple[float, float]]
) -> np.ndarray:
    """Map source x values to gap-compressed combined-plot coordinates.

    Purpose:
        Remove excluded spans from the rendered width while masking their samples.
    Why:
        The plot needs a compact visual break, while tick labels continue to
        represent the original stitched elapsed-time coordinates.
    Inputs:
        values: Numeric source x-array.
        ranges: Normalized excluded source x pairs.
    Returns:
        Float ndarray in compressed display coordinates; excluded samples are NaN.
    Side Effects:
        None.
    Exceptions:
        Non-numeric values become NaN through NumPy coercion.
    """
    try:
        source = np.asarray(values, dtype=float)
    except Exception:
        return np.asarray([], dtype=float)
    display = source.astype(float, copy=True)
    valid = np.isfinite(display)
    for start, end in ranges:
        hidden = valid & (source >= start) & (source <= end)
        display[hidden] = np.nan
        after = valid & (source > end)
        display[after] -= end - start
    return display


def _combined_exclusion_source_x(
    display_value: float, ranges: list[tuple[float, float]]
) -> float:
    """Invert a compressed combined-plot coordinate to source elapsed time.

    Purpose:
        Translate a display coordinate for source-range persistence and labeling.
    Why:
        The visible axis removes excluded width, but selections and labels must
        continue to use the elapsed time calculated during data stitching.
    Inputs:
        display_value: Current combined-plot x coordinate.
        ranges: Normalized excluded source x pairs.
    Returns:
        Source elapsed-time coordinate as a float.
    Side Effects:
        None.
    Exceptions:
        Non-finite input is returned unchanged.
    """
    if not math.isfinite(display_value):
        return display_value
    source = float(display_value)
    removed = 0.0
    for start, end in ranges:
        compressed_start = start - removed
        if display_value < compressed_start:
            break
        source += end - start
        removed += end - start
    return source


def _apply_combined_exclusion_time_axis(
    axis: Axes,
    ranges: Sequence[Tuple[float, float]],
    source_time_range: Tuple[float, float],
    auto_time_ticks: bool,
    major_tick: float,
    minor_tick: float,
) -> None:
    """Configure compressed x ticks to display original stitched elapsed time.

    Purpose:
        Position major and minor tick marks on the compacted plot while
        displaying source-time labels after one or more excluded intervals.
    Why:
        A normal locator interprets compressed positions as recalculated elapsed
        time, which incorrectly relabels data after an axis break.
    Inputs:
        axis: Primary combined Matplotlib axis.
        ranges: Normalized source-time exclusions.
        source_time_range: Minimum and maximum unmodified elapsed times.
        auto_time_ticks: Whether automatic major tick selection is enabled.
        major_tick: Manual major tick interval when automatic ticks are disabled.
        minor_tick: Manual minor tick interval when automatic ticks are disabled.
    Returns:
        None.
    Side Effects:
        Replaces x-axis locators and formatter on ``axis``.
    Exceptions:
        Invalid ranges or intervals fall back to Matplotlib's standard locators.
    """
    normalized = _normalize_combined_exclusion_ranges(ranges)
    if not normalized:
        return
    source_min, source_max = source_time_range
    if not (math.isfinite(source_min) and math.isfinite(source_max)):
        return
    if source_max < source_min:
        source_min, source_max = source_max, source_min
    try:
        segments: List[Tuple[float, float]] = []
        cursor = source_min
        for start, end in normalized:
            if start > cursor:
                segments.append((cursor, min(start, source_max)))
            cursor = max(cursor, end)
        if cursor < source_max:
            segments.append((cursor, source_max))
        total_visible_width = sum(
            max(0.0, high - low) for low, high in segments
        )
        major_candidates: List[float] = []
        minor_candidates: List[float] = []
        for low, high in segments:
            if high <= low:
                continue
            if auto_time_ticks:
                width_fraction = (high - low) / max(total_visible_width, 1e-12)
                major_locator = MaxNLocator(
                    nbins=max(2, min(5, round(2 + (width_fraction * 8)))),
                    min_n_ticks=2,
                )
            else:
                major_locator = MultipleLocator(major_tick)
            segment_major = major_locator.tick_values(low, high)
            segment_major = segment_major[
                (segment_major >= low - 1e-12) & (segment_major <= high + 1e-12)
            ]
            major_candidates.extend(float(value) for value in segment_major)
            if auto_time_ticks:
                for major_low, major_high in zip(
                    segment_major[:-1], segment_major[1:]
                ):
                    step = (float(major_high) - float(major_low)) / 5.0
                    minor_candidates.extend(
                        float(major_low) + (step * index)
                        for index in range(1, 5)
                    )
            else:
                segment_minor = MultipleLocator(minor_tick).tick_values(low, high)
                minor_candidates.extend(
                    float(value)
                    for value in segment_minor
                    if low - 1e-12 <= value <= high + 1e-12
                )
        major_source = np.asarray(sorted(set(major_candidates)), dtype=float)
        minor_source = np.asarray(sorted(set(minor_candidates)), dtype=float)
        major_display = _combined_exclusion_display_x(major_source, normalized)
        axis.xaxis.set_major_locator(
            FixedLocator(major_display[np.isfinite(major_display)])
        )
        minor_display = _combined_exclusion_display_x(minor_source, normalized)
        axis.xaxis.set_minor_locator(
            FixedLocator(minor_display[np.isfinite(minor_display)])
        )
        axis.xaxis.set_major_formatter(
            FuncFormatter(
                lambda value, _position: f"{_combined_exclusion_source_x(float(value), normalized):g}"
            )
        )
    except Exception:
        # Keep the established locator behavior if unusual user tick values fail.
        return


def _draw_combined_exclusion_break_labels(
    axis: Axes,
    ranges: Sequence[Tuple[float, float]],
    display_time_range: Tuple[float, float],
) -> None:
    """Draw source-time labels immediately before and after each axis break.

    Purpose:
        Make both sides of every compacted exclusion explicit to the viewer.
    Why:
        Major ticks can reasonably skip a narrow span, but a publication plot
        must still show the elapsed-time values that define the discontinuity.
    Inputs:
        axis: Primary combined Matplotlib axis.
        ranges: Normalized source-time exclusion pairs.
        display_time_range: Visible compressed x-axis limits.
    Returns:
        None.
    Side Effects:
        Adds two annotation artists per visible axis break.
    Exceptions:
        Malformed ranges are ignored after normalization.
    """
    normalized = _normalize_combined_exclusion_ranges(ranges)
    display_min, display_max = display_time_range
    removed = 0.0
    break_label_artists: List[Any] = []
    for start, end in normalized:
        join_x = start - removed
        removed += end - start
        if not (display_min < join_x < display_max):
            continue
        # Offset labels outward so the paired source values remain legible at
        # the single compressed coordinate occupied by the break marker.
        break_label_artists.append(
            axis.annotate(
                f"{start:.4g}",
                xy=(join_x, 0.0),
                xycoords=("data", "axes fraction"),
                xytext=(-5, -28),
                textcoords="offset points",
                ha="right",
                va="top",
                fontsize="small",
                annotation_clip=False,
            )
        )
        break_label_artists.append(
            axis.annotate(
                f"{end:.4g}",
                xy=(join_x, 0.0),
                xycoords=("data", "axes fraction"),
                xytext=(5, -28),
                textcoords="offset points",
                ha="left",
                va="top",
                fontsize="small",
                annotation_clip=False,
            )
        )
    try:
        axis.figure._gl260_combined_exclusion_break_label_artists = break_label_artists  # type: ignore[attr-defined]
    except Exception:
        pass


def build_combined_triple_axis_figure(
    min_time,
    max_time,
    min_y,
    max_y,
    twin_y_min,
    twin_y_max,
    deriv_y_min,
    deriv_y_max,
    auto_time_ticks,
    auto_y_ticks,
    auto_temp_ticks,
    auto_deriv_ticks,
    title_text,
    suptitle_text,
    xmaj_tick,
    xmin_tick,
    ymaj_tick,
    ymin_tick,
    twin_maj_tick,
    twin_min_tick,
    deriv_maj_tick,
    deriv_min_tick,
    enable_temp_axis,
    enable_deriv_axis,
    deriv_axis_offset,
    legend_wrap=False,
    legend_rows=None,
    legend_alignment="center",
    legend_label_gap_pts=DEFAULT_COMBINED_LEGEND_GAP_PTS,
    xlabel_tick_gap_pts=DEFAULT_COMBINED_XLABEL_TICK_GAP_PTS,
    legend_bottom_margin_pts=DEFAULT_COMBINED_LEGEND_MARGIN_PTS,
    left_pad_pct=DEFAULT_COMBINED_LEFT_PAD_PCT,
    right_pad_pct=DEFAULT_COMBINED_RIGHT_PAD_PCT,
    export_pad_pts=DEFAULT_COMBINED_EXPORT_PAD_PTS,
    suptitle_fontsize=DEFAULT_COMBINED_SUPTITLE_FONTSIZE,
    title_fontsize=DEFAULT_COMBINED_TITLE_FONTSIZE,
    label_fontsize_override=DEFAULT_COMBINED_LABEL_FONTSIZE,
    tick_fontsize_override=DEFAULT_COMBINED_TICK_FONTSIZE,
    legend_fontsize_override=DEFAULT_COMBINED_LEGEND_FONTSIZE,
    cycle_legend_fontsize_override=None,
    font_family: str = DEFAULT_COMBINED_FONT_FAMILY,
    title_pad_pts=DEFAULT_COMBINED_TITLE_PAD_PTS,
    suptitle_pad_pts=DEFAULT_COMBINED_SUPTITLE_PAD_PTS,
    suptitle_y=DEFAULT_COMBINED_SUPTITLE_Y,
    top_margin_pct=DEFAULT_COMBINED_TOP_MARGIN_PCT,
    baseline_margins=None,
    legend_anchor_y=None,
    xlabel_pad_pts=None,
    axis_label_overrides=None,
    labelpad_overrides=None,
    left_dataset_key="y1",
    right_dataset_key="z",
    third_dataset_key="y2",
    show_cycle_markers_on_core_plots=False,
    show_cycle_legend_on_core_plots=False,
    include_moles_in_core_plot_legend=False,
    include_zero_line: bool = True,
    legend_anchor=None,
    cycle_legend_anchor=None,
    legend_loc=None,
    cycle_legend_loc=None,
    cycle_legend_anchor_space=None,
    mode: str = "display",
    fig_size=None,
    render_ctx: Optional[RenderContext] = None,
):
    """Build the combined triple-axis figure for display/export workflows.

    Purpose:
        Assemble the combined triple-axis plot with legends, overlays, and layout
        rules that keep the interactive display and export pipeline aligned.
    Why:
        The combined plot is the authoritative multi-axis view; rebuilding it in
        one routine preserves consistent legend placement and export geometry.

    Args:
        min_time/max_time/etc.: Numeric axis limits and tick settings in data
            units; tick spacing values are floats.
        legend_anchor/cycle_legend_anchor: (x, y) tuple in normalized figure or
            axes fraction coordinates (0-1 with small tolerance).
        cycle_legend_anchor_space: "figure" or "axes" to interpret the anchor.
        mode: "display" or "export" to control layout solving behavior.
        fig_size: Optional (width, height) in inches for display rendering.
        render_ctx: Optional RenderContext payload for prepared data/overlays.

    Returns:
        Matplotlib Figure configured with axes, legends, and layout manager.

    Side Effects:
        Writes legend/axis metadata onto the Figure and may update settings when
        cycle legend offsets are migrated for export consistency.

    Exceptions:
        Internal rendering errors are caught and ignored to keep UI flows alive.
    """
    # Combined triple-axis pipeline: one primary axis shares the x-scale with
    # optional temperature/derivative axes, so preview and export stay aligned
    # while supporting detached right-side spines and overlay annotations.
    from matplotlib.ticker import AutoLocator, AutoMinorLocator, MultipleLocator

    mode_value = (mode or "display").strip().lower()
    if mode_value not in {"display", "export"}:
        mode_value = "display"
    include_zero_line = bool(include_zero_line)

    if mode_value == "export":
        target_figsize = (11.0, 8.5)
    else:
        target_figsize = tuple(fig_size) if fig_size else (11.0, 8.5)

    # Display/export separation: display follows the live canvas, export uses a
    # fixed size to avoid layout drift between preview and saved artifacts.
    fig = Figure(figsize=target_figsize)
    fig._gl260_plot_id = "fig_combined_triple_axis"  # type: ignore[attr-defined]
    fig._gl260_layout_mode = mode_value  # type: ignore[attr-defined]
    if mode_value == "export":
        fig.set_size_inches(target_figsize, forward=True)

    # Detached derivative axis uses an offset spine so the second right axis does
    # not collide with temperature labels or legends.
    try:
        offset_val = float(deriv_axis_offset or 1.12)
    except Exception:
        offset_val = 1.12
    if not math.isfinite(offset_val):
        offset_val = 1.12
    deriv_spine_offset = max(1.10, offset_val)

    ax = fig.add_subplot(1, 1, 1)
    try:
        ax._gl260_axis_role = "primary"
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass

    data_ctx = render_ctx.data_ctx if render_ctx else {}
    style_ctx = render_ctx.style_ctx if render_ctx else {}
    gates_ctx = render_ctx.gates_ctx if render_ctx else {}
    overlay_ctx = render_ctx.overlay_ctx if render_ctx else {}

    show_cycle_markers_on_core_plots = bool(
        gates_ctx.get("show_cycle_markers", show_cycle_markers_on_core_plots)
    )
    show_main_legend_on_core_plots = bool(gates_ctx.get("show_main_legend", True))
    show_cycle_legend_on_core_plots = bool(
        gates_ctx.get("show_cycle_legend", show_cycle_legend_on_core_plots)
    )
    include_moles_in_core_plot_legend = bool(
        gates_ctx.get("include_moles", include_moles_in_core_plot_legend)
    )

    scatter_config = style_ctx.get("scatter_config")
    scatter_series_configs = style_ctx.get("scatter_series_configs")

    series_map = data_ctx.get("series") or {}
    series_np = data_ctx.get("series_np") or {}
    selected_columns = data_ctx.get("selected_columns") or globals().get(
        "selected_columns", {}
    )

    x = series_np.get("x", series_map.get("x", globals().get("x")))
    y1 = series_np.get("y1", series_map.get("y1", globals().get("y1")))
    y2 = series_np.get("y2", series_map.get("y2", globals().get("y2")))
    y3 = series_np.get("y3", series_map.get("y3", globals().get("y3")))
    z = series_np.get("z", series_map.get("z", globals().get("z")))
    z2 = series_np.get("z2", series_map.get("z2", globals().get("z2")))
    exclusion_ranges = _normalize_combined_exclusion_ranges(
        data_ctx.get("combined_exclusion_ranges")
    )
    source_x = x
    if exclusion_ranges and x is not None:
        display_x = _combined_exclusion_display_x(x, exclusion_ranges)

        def _mask_excluded_series(values: Any) -> Any:
            """Mask one trace where the shared combined x-series is excluded.

            Purpose:
                Preserve source arrays while forcing Matplotlib to split lines at
                every omitted span in this display-only render.
            Why:
                Plotting a compressed x array alone would bridge the omitted data.
            Inputs:
                values: Trace values aligned with the shared x-series.
            Returns:
                Float ndarray with excluded rows set to NaN, or original values
                when alignment/coercion is unavailable.
            Side Effects:
                None.
            Exceptions:
                Conversion or shape failures retain the original series safely.
            """
            if values is None:
                return None
            try:
                masked = np.asarray(values, dtype=float).copy()
                if masked.shape != display_x.shape:
                    return values
                masked[~np.isfinite(display_x)] = np.nan
                return masked
            except Exception:
                return values

        x = display_x
        y1, y2, y3 = (
            _mask_excluded_series(y1),
            _mask_excluded_series(y2),
            _mask_excluded_series(y3),
        )
        z, z2 = _mask_excluded_series(z), _mask_excluded_series(z2)
        finite_x = x[np.isfinite(x)]
        if finite_x.size:
            time_range = (float(np.min(finite_x)), float(np.max(finite_x)))
        else:
            time_range = (min_time, max_time)
    else:
        time_range = (min_time, max_time)
    fmt = _format_axis_label
    svg_safe = _svg_safe_text
    handles = []
    line_map: Dict[str, Any] = {}
    ax_temp: Optional[Axes] = None
    ax_deriv: Optional[Axes] = None
    ax_overlay: Optional[Axes] = None
    label_overrides = (
        axis_label_overrides if isinstance(axis_label_overrides, dict) else {}
    )
    pad_overrides = labelpad_overrides if isinstance(labelpad_overrides, dict) else {}
    family_value = (font_family or "").strip()
    label_fontsize = _sanitize_spacing_value(
        label_fontsize_override,
        DEFAULT_COMBINED_LABEL_FONTSIZE,
        MIN_COMBINED_FONT_SIZE,
        MAX_COMBINED_FONT_SIZE,
    )
    tick_fontsize = _sanitize_spacing_value(
        tick_fontsize_override,
        DEFAULT_COMBINED_TICK_FONTSIZE,
        MIN_COMBINED_FONT_SIZE,
        MAX_COMBINED_FONT_SIZE,
    )
    suptitle_fontsize_value = _sanitize_spacing_value(
        suptitle_fontsize,
        DEFAULT_COMBINED_SUPTITLE_FONTSIZE,
        MIN_COMBINED_FONT_SIZE,
        MAX_COMBINED_FONT_SIZE,
    )
    title_fontsize_value = _sanitize_spacing_value(
        title_fontsize,
        DEFAULT_COMBINED_TITLE_FONTSIZE,
        MIN_COMBINED_FONT_SIZE,
        MAX_COMBINED_FONT_SIZE,
    )
    legend_fontsize_value = _sanitize_spacing_value(
        legend_fontsize_override,
        DEFAULT_COMBINED_LEGEND_FONTSIZE,
        MIN_COMBINED_FONT_SIZE,
        MAX_COMBINED_FONT_SIZE,
    )
    if cycle_legend_fontsize_override is None:
        cycle_legend_fontsize_override = legend_fontsize_value
    cycle_legend_fontsize_value = _sanitize_spacing_value(
        cycle_legend_fontsize_override,
        legend_fontsize_value,
        MIN_COMBINED_FONT_SIZE,
        MAX_COMBINED_FONT_SIZE,
    )
    legend_markerscale = _coerce_float(settings.get("combined_legend_markerscale"))
    if legend_markerscale is None:
        legend_markerscale = legend_fontsize_value / DEFAULT_COMBINED_LEGEND_FONTSIZE
    cycle_legend_markerscale = _coerce_float(
        settings.get("combined_cycle_legend_markerscale")
    )
    if cycle_legend_markerscale is None:
        cycle_legend_markerscale = (
            cycle_legend_fontsize_value / DEFAULT_COMBINED_LEGEND_FONTSIZE
        )

    def _fmt_safe(value: Any) -> str:
        """Perform fmt safe.
        Used to keep the workflow logic localized and testable."""
        return svg_safe(fmt(value))

    def _text_safe(value: Any) -> str:
        """Perform text safe.
        Used to keep the workflow logic localized and testable."""
        return svg_safe(value)

    def _label_or_default(key: str, default: str) -> str:
        """Return default value.
        Used by label or workflows to return value."""
        raw = label_overrides.get(key)
        if raw is None:
            return default
        text = str(raw).strip()
        return _fmt_safe(text) if text else default

    def _pad_or_default(key: str, default: float) -> float:
        """Pad or default.
        Used to add spacing to or default for layout alignment."""
        try:
            candidate = float(pad_overrides.get(key))
            if math.isfinite(candidate):
                return candidate
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        return default

    default_x_label = _fmt_safe(selected_columns.get("x", "Time"))
    x_label_text = _label_or_default("x", default_x_label)
    primary_labelpad = _pad_or_default("primary", yaxis_labelpad_amount)
    temp_labelpad = _pad_or_default("temperature", twinyaxis_labelpad_amount)
    deriv_labelpad = _pad_or_default("derivative", 15)
    left_pad_value = _sanitize_spacing_value(
        left_pad_pct,
        DEFAULT_COMBINED_LEFT_PAD_PCT,
        MIN_COMBINED_SIDE_PAD_PCT,
        MAX_COMBINED_SIDE_PAD_PCT,
    )
    right_pad_value = _sanitize_spacing_value(
        right_pad_pct,
        DEFAULT_COMBINED_RIGHT_PAD_PCT,
        MIN_COMBINED_SIDE_PAD_PCT,
        MAX_COMBINED_SIDE_PAD_PCT,
    )
    title_pad_value = _sanitize_spacing_value(
        title_pad_pts,
        DEFAULT_COMBINED_TITLE_PAD_PTS,
        MIN_COMBINED_TITLE_PAD_PTS,
        MAX_COMBINED_TITLE_PAD_PTS,
    )
    suptitle_pad_value = _sanitize_spacing_value(
        suptitle_pad_pts,
        DEFAULT_COMBINED_SUPTITLE_PAD_PTS,
        MIN_COMBINED_SUPTITLE_PAD_PTS,
        MAX_COMBINED_SUPTITLE_PAD_PTS,
    )
    suptitle_y_value = _sanitize_spacing_value(
        suptitle_y,
        DEFAULT_COMBINED_SUPTITLE_Y,
        MIN_COMBINED_SUPTITLE_Y,
        MAX_COMBINED_SUPTITLE_Y,
    )
    top_margin_value = _sanitize_spacing_value(
        top_margin_pct,
        DEFAULT_COMBINED_TOP_MARGIN_PCT,
        MIN_COMBINED_TOP_MARGIN_PCT,
        MAX_COMBINED_TOP_MARGIN_PCT,
    )
    try:
        xlabel_pad_value = float(xlabel_pad_pts) if xlabel_pad_pts is not None else 0.0
    except Exception:
        xlabel_pad_value = 0.0
    if not math.isfinite(xlabel_pad_value):
        xlabel_pad_value = 0.0

    def _apply_axis_ticks(axis, auto_flag, major_tick, minor_tick):
        """Apply axis ticks.
        Used to apply axis ticks changes to live state."""
        if auto_flag:
            axis.yaxis.set_major_locator(AutoLocator())
            axis.yaxis.set_minor_locator(AutoMinorLocator())
        else:
            axis.yaxis.set_major_locator(MultipleLocator(major_tick))
            axis.yaxis.set_minor_locator(MultipleLocator(minor_tick))
        axis.minorticks_on()
        axis.tick_params(
            axis="y", which="major", labelcolor="black", labelsize=tick_fontsize
        )

    def _apply_tick_font(axis):
        """Apply tick font.
        Used to apply tick font changes to live state."""
        if not family_value:
            return
        try:
            labels = list(axis.get_xticklabels()) + list(axis.get_yticklabels())
            # Iterate over labels to apply the per-item logic.
            for lbl in labels:
                lbl.set_fontfamily(family_value)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _position_extra_axis(axis, location):
        """Perform position extra axis.
        Used to keep the workflow logic localized and testable."""
        axis.set_frame_on(True)
        axis.patch.set_visible(False)
        # Iterate over values from axis.spines to apply the per-item logic.
        for spine in axis.spines.values():
            spine.set_visible(False)
        right_spine = axis.spines["right"]
        right_spine.set_visible(True)
        right_spine.set_position(("axes", location))
        right_spine.set_color("black")

    def _combined_render_debug(message: str, *args: Any) -> None:
        """Emit combined render debug logs when plotting.render is enabled.

        Purpose:
            Write deterministic verification logs for combined layering behavior.
        Why:
            Layering bugs are difficult to inspect without runtime logs showing
            axis order and per-artist z-order resolution.
        Inputs:
            message: Logger format string.
            *args: Format arguments consumed by the logger.
        Outputs:
            None.
        Side Effects:
            Writes to the module debug logger when debug/category gates are on.
        Exceptions:
            Logging errors are suppressed to preserve render stability.
        """
        try:
            if not bool(settings.get("debug_enabled", False)):
                return
            categories = settings.get("debug_categories")
            if not isinstance(categories, dict):
                return
            if not bool(categories.get("plotting.render", False)):
                return
            _GL260_LOGGER.debug("[plotting.render] " + message, *args)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _iter_artist_handles(artist_obj: Any) -> List[Any]:
        """Return a flat list of artist handles from one or many artist objects.

        Purpose:
            Normalize artist return values so z-order enforcement can apply to
            single artists and multi-artist series payloads.
        Why:
            Some render paths can evolve to return grouped artists; layering must
            still be enforced on every created artist.
        Inputs:
            artist_obj: One artist or a collection of artists.
        Outputs:
            Flat list of artist objects supporting matplotlib artist APIs.
        Side Effects:
            None.
        Exceptions:
            Non-iterable or unsupported values are safely ignored.
        """
        if artist_obj is None:
            return []
        if isinstance(artist_obj, (list, tuple, set)):
            artists: List[Any] = []
            # Iterate over artist_obj to flatten nested artist groups.
            for item in artist_obj:
                artists.extend(_iter_artist_handles(item))
            return artists
        return [artist_obj]

    def _apply_artist_zorder(artist_obj: Any, z_value: float) -> None:
        """Apply one z-order value to every artist associated with a series.

        Purpose:
            Enforce resolved trace layering on all artists created for a series.
        Why:
            Series can contain more than one artist, and each one must carry the
            same resolved z-order for deterministic stacking behavior.
        Inputs:
            artist_obj: One or many matplotlib artists for the series.
            z_value: Resolved z-order to apply.
        Outputs:
            None.
        Side Effects:
            Mutates artist z-order state.
        Exceptions:
            Artists without set_zorder are skipped.
        """
        # Iterate over flattened handles so every artist gets the resolved zorder.
        for artist_handle in _iter_artist_handles(artist_obj):
            setter = getattr(artist_handle, "set_zorder", None)
            if callable(setter):
                setter(z_value)

    label_y1 = _fmt_safe(selected_columns.get("y1", "y1"))
    label_y3 = _fmt_safe(selected_columns.get("y3", "y3"))
    label_y2 = _fmt_safe(selected_columns.get("y2", "Derivative"))
    label_z = _fmt_safe(selected_columns.get("z", "Temp"))
    label_z2 = _fmt_safe(selected_columns.get("z2", "Temp 2"))
    grouped_entries = {
        "y1": _trace_group_entries_from_context(
            data_ctx, "y1", fallback_series=y1, fallback_label=label_y1
        ),
        "y3": _trace_group_entries_from_context(
            data_ctx, "y3", fallback_series=y3, fallback_label=label_y3
        ),
        "y2": _trace_group_entries_from_context(
            data_ctx, "y2", fallback_series=y2, fallback_label=label_y2
        ),
        "z": _trace_group_entries_from_context(
            data_ctx, "z", fallback_series=z, fallback_label=label_z
        ),
        "z2": _trace_group_entries_from_context(
            data_ctx, "z2", fallback_series=z2, fallback_label=label_z2
        ),
    }
    if exclusion_ranges and x is not None:
        # Grouped traces bypass the canonical y variables, so apply the same
        # display-only NaN mask to keep every visible line discontinuous at gaps.
        for entries in grouped_entries.values():
            for entry in entries:
                entry["series"] = _mask_excluded_series(entry.get("series"))

    selected_map = {
        "y1": _is_selected(selected_columns.get("y1", "y1")),
        "y3": _is_selected(selected_columns.get("y3", "y3")),
        "y2": _is_selected(selected_columns.get("y2", "Derivative")),
        "z": _is_selected(selected_columns.get("z", "Temp")),
        "z2": _is_selected(selected_columns.get("z2", "Temp 2")),
    }

    dataset_meta = {
        "y1": {
            "series": y1,
            "label": label_y1,
            "color": "blue",
            "series_key": "y1",
            "axis_type": "primary",
            "selected": selected_map["y1"],
            "entries": grouped_entries["y1"],
        },
        "y3": {
            "series": y3,
            "label": label_y3,
            "color": "green",
            "series_key": "y3",
            "axis_type": "primary",
            "selected": selected_map["y3"],
            "entries": grouped_entries["y3"],
        },
        "y2": {
            "series": y2,
            "label": label_y2,
            "color": "red",
            "series_key": "y2",
            "axis_type": "derivative",
            "selected": selected_map["y2"],
            "entries": grouped_entries["y2"],
        },
        "z": {
            "series": z,
            "label": label_z,
            "color": "red",
            "series_key": "z",
            "axis_type": "temperature",
            "selected": selected_map["z"],
            "entries": grouped_entries["z"],
        },
        "z2": {
            "series": z2,
            "label": label_z2,
            "color": "orange",
            "series_key": "z2",
            "axis_type": "temperature",
            "selected": selected_map["z2"],
            "entries": grouped_entries["z2"],
        },
    }

    temperature_render_mode, temperature_visual = _resolve_temperature_visual_for_series(
        settings, x, z, z2
    )
    temperature_layout_artists: List[Any] = []
    linecolor_target_drawn = [False]
    calculation_trace = data_ctx.get("calculation_trace") or settings.get(
        "calculation_trace", {}
    )
    calculation_column = (
        str(calculation_trace.get("column") or "").strip()
        if isinstance(calculation_trace, Mapping)
        else ""
    )
    valid_dataset_keys: Set[str] = set(dataset_meta.keys())

    def _is_available(meta: Mapping[str, Any]) -> bool:
        """Check whether it is available.
        Used to gate conditional behavior in the workflow."""
        entries = meta.get("entries")
        if isinstance(entries, Sequence) and not isinstance(entries, (str, bytes)):
            return bool(entries)
        return bool(meta.get("series") is not None and meta.get("selected"))

    temp_axis_active = temperature_render_mode == "axis" and bool(enable_temp_axis) and (
        _is_available(dataset_meta["z"]) or _is_available(dataset_meta["z2"])
    )
    deriv_axis_active = bool(enable_deriv_axis) and _is_available(dataset_meta["y2"])

    def _resolve_dataset_key(
        value: Any, default_key: str, *, allow_none: bool = False
    ) -> str:
        """Resolve one combined render dataset key.

        Purpose:
            Normalize external render arguments to a supported dataset key.
        Why:
            Figure construction can be called by display, export, and tests, so
            it must validate keys independently of the Tk UI layer.
        Args:
            value: Raw requested dataset key.
            default_key: Fallback key used when `value` is invalid.
            allow_none: Preserve `"none"` for the optional outer-right axis.
        Returns:
            Canonical dataset key or `"none"` when allowed.
        Side Effects:
            None.
        Exceptions:
            None; invalid values fall back to `default_key`.
        """
        if value is None:
            return default_key
        candidate = str(value).strip().lower()
        if allow_none and candidate == "none":
            return "none"
        return candidate if candidate in valid_dataset_keys else default_key

    left_key = _resolve_dataset_key(left_dataset_key, "y1")
    right_key = _resolve_dataset_key(right_dataset_key, "z")
    third_key = _resolve_dataset_key(third_dataset_key, "y2", allow_none=True)

    def _axis_settings(meta: Mapping[str, Any]) -> Dict[str, Any]:
        """Perform axis settings.
        Used to keep the workflow logic localized and testable."""
        axis_kind = meta.get("axis_type", "primary")
        if axis_kind == "temperature":
            return {
                "ylim": (twin_y_min, twin_y_max),
                "auto": auto_temp_ticks,
                "maj": twin_maj_tick,
                "min": twin_min_tick,
                "label_key": "temperature",
                "labelpad": temp_labelpad,
            }
        if axis_kind == "derivative":
            return {
                "ylim": (deriv_y_min, deriv_y_max),
                "auto": auto_deriv_ticks,
                "maj": deriv_maj_tick,
                "min": deriv_min_tick,
                "label_key": "derivative",
                "labelpad": deriv_labelpad,
            }
        return {
            "ylim": (min_y, max_y),
            "auto": auto_y_ticks,
            "maj": ymaj_tick,
            "min": ymin_tick,
            "label_key": "primary",
            "labelpad": primary_labelpad,
        }

    def _axis_enabled(meta: Mapping[str, Any]) -> bool:
        """Determine whether a combined-axis dataset is eligible to render.

        Purpose:
            Apply selection and semantic-axis visibility gates to direct or
            grouped Columns-tab trace data.
        Why:
            A grouped trace can have no legacy role-level series while still
            being valid data for a detached temperature or derivative axis.
        Inputs:
            meta: Dataset metadata for one combined-axis candidate.
        Outputs:
            True when the selected dataset has renderable data and its semantic
            axis is enabled; otherwise False.
        Side Effects:
            None.
        Exceptions:
            Missing or malformed metadata resolves to False.
        """
        axis_kind = meta.get("axis_type", "primary")
        entries = meta.get("entries")
        has_renderable_data = meta.get("series") is not None or bool(
            isinstance(entries, Sequence)
            and not isinstance(entries, (str, bytes))
            and any(
                isinstance(entry, Mapping) and entry.get("series") is not None
                for entry in entries
            )
        )
        if not has_renderable_data or not meta.get("selected"):
            return False
        if axis_kind == "temperature":
            return temp_axis_active
        if axis_kind == "derivative":
            return deriv_axis_active
        return True

    default_zorders = {"y1": 2, "y3": 1, "y2": 3, "z": 3, "z2": 3}
    resolved_trace_zorders: Dict[str, float] = {}
    # Iterate over default_zorders to resolve effective z-order per trace key.
    for series_key, default_z in default_zorders.items():
        resolved_trace_zorders[series_key] = _resolve_effective_trace_zorder(
            default_z,
            series_key=series_key,
            scatter_series_configs=scatter_series_configs,
        )

    def _plot_dataset(
        ax_target: Axes, meta: Mapping[str, Any], *, axis_role: str
    ) -> Optional[Any]:
        """Render one dataset on its assigned combined-axis role.

        Purpose:
            Plot one selected data series and persist its artist for refresh and
            legend workflows.
        Why:
            Combined layering requires each trace to resolve one deterministic
            z-order and apply it consistently on every artist.
        Inputs:
            ax_target: Target Axes receiving the series artist(s).
            meta: Dataset metadata including series values, label, and series_key.
            axis_role: Combined-axis role name ("left", "right", or "third").
        Outputs:
            Primary artist handle for the rendered series, or None when skipped.
        Side Effects:
            Adds artists to the target Axes and updates line_map for reuse.
        Exceptions:
            Missing/invalid series data returns None without raising.
        """
        entries = meta.get("entries")
        if isinstance(entries, Sequence) and not isinstance(entries, (str, bytes)):
            trace_entries = [entry for entry in entries if isinstance(entry, Mapping)]
        else:
            trace_entries = []
        if not trace_entries:
            series = meta.get("series")
            if series is None or not meta.get("selected"):
                return None
            trace_entries = [
                {
                    "series": series,
                    "label": meta.get("label", ""),
                    "series_key": meta.get("series_key"),
                    "color": meta.get("color"),
                    "line_style": "--" if meta.get("series_key") == "z2" else None,
                    "index": 0,
                }
            ]
        rendered_artists: List[Any] = []
        for trace_entry in trace_entries:
            series = trace_entry.get("series")
            if series is None:
                continue
            series_key = trace_entry.get("series_key") or meta.get("series_key")
            trace_column = str(
                trace_entry.get("column") or trace_entry.get("source_column") or ""
            ).strip()
            is_calculation_trace = (
                str(meta.get("series_key") or "") == "y1"
                and not linecolor_target_drawn[0]
                and (not calculation_column or calculation_column == trace_column)
            )
            if (
                temperature_render_mode == "linecolor"
                and temperature_visual is not None
                and is_calculation_trace
            ):
                artist = draw_temperature_colored_pressure(
                    ax_target,
                    x,
                    series,
                    temperature_visual,
                    label=str(trace_entry.get("label") or meta.get("label") or "Pressure"),
                )
                if artist is not None:
                    linecolor_target_drawn[0] = True
                    try:
                        artist._gl260_series_key = series_key  # type: ignore[attr-defined]
                    except Exception:
                        pass
                    line_map[str(series_key)] = artist
                    rendered_artists.append(artist)
                    temperature_layout_artists.append(artist)
                    continue
            default_zorder = default_zorders.get(meta.get("series_key"), 2)
            resolved_zorder = _resolve_effective_trace_zorder(
                resolved_trace_zorders.get(meta.get("series_key"), default_zorder),
                series_key=series_key,
                scatter_series_configs=scatter_series_configs,
            )
            style_kwargs: Dict[str, Any] = {
                "zorder": resolved_zorder,
                "series_key": series_key,
            }
            line_style_value = trace_entry.get("line_style")
            if line_style_value:
                style_kwargs["line_style"] = line_style_value
            artist = _plot_series(
                ax_target,
                x,
                series,
                label=trace_entry.get("label", meta.get("label", "")),
                color=trace_entry.get("color", meta.get("color")),
                scatter_config=scatter_config,
                scatter_series_configs=scatter_series_configs,
                **style_kwargs,
            )
            if artist is None:
                continue
            _apply_artist_zorder(artist, resolved_zorder)
            artist_handles = _iter_artist_handles(artist)
            if not artist_handles:
                continue
            for idx, artist_handle in enumerate(artist_handles):
                actual_zorder = None
                getter = getattr(artist_handle, "get_zorder", None)
                if callable(getter):
                    try:
                        actual_zorder = float(getter())
                    except Exception:
                        actual_zorder = None
                actual_text = (
                    f"{actual_zorder:.6g}"
                    if actual_zorder is not None and math.isfinite(actual_zorder)
                    else "None"
                )
                _combined_render_debug(
                    "Combined trace artist series=%s axis_role=%s intended_z=%s actual_z=%s artist_index=%s",
                    series_key,
                    axis_role,
                    f"{resolved_zorder:.6g}",
                    actual_text,
                    idx,
                )
            primary_artist = artist_handles[0]
            if series_key:
                try:
                    primary_artist._gl260_series_key = series_key
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
                line_map[str(series_key)] = primary_artist
            rendered_artists.append(primary_artist)
        if not rendered_artists:
            return None
        return rendered_artists

    primary_meta = dataset_meta.get(left_key, dataset_meta["y1"])
    right_axis_bindings = _resolve_combined_right_axis_bindings(
        dataset_meta,
        right_key=right_key,
        third_key=third_key,
        temp_axis_active=temp_axis_active,
        deriv_axis_active=deriv_axis_active,
    )
    right_axis_assignment = right_axis_bindings.get("right")
    third_axis_assignment = right_axis_bindings.get("third")
    right_role = right_axis_bindings.get("right_role")
    third_role = right_axis_bindings.get("third_role")
    temp_axis_position = right_axis_bindings.get("temperature_position")
    deriv_axis_position = right_axis_bindings.get("derivative_position")

    def _axis_role_layer_zorder(
        series_keys: Sequence[str], role_bias: float, fallback: float
    ) -> float:
        """Resolve one combined-axis z-order from the role's active trace z-orders.

        Purpose:
            Compute deterministic axis-level draw order from effective per-trace
            z-order values for that axis role.
        Why:
            Matplotlib draws by Axes first, so cross-axis trace priority must
            influence each axis z-order to make foreground/background overrides
            consistent when traces live on different axes.
        Inputs:
            series_keys: Trace keys assigned to one axis role.
            role_bias: Small positive tie-breaker to keep equal-z axes stable.
            fallback: Fallback z-order when no active traces exist for the role.
        Outputs:
            Float axis z-order value for the role.
        Side Effects:
            None.
        Exceptions:
            Invalid/non-finite trace z-orders are ignored.
        """
        z_values: List[float] = []
        # Iterate over series_keys and collect active trace z-order values.
        for trace_key in series_keys:
            meta = dataset_meta.get(trace_key, {})
            if not _is_available(meta):
                continue
            candidate = resolved_trace_zorders.get(trace_key)
            if candidate is not None and math.isfinite(candidate):
                z_values.append(float(candidate))
        base_value = max(z_values) if z_values else float(fallback)
        return float(base_value + role_bias)

    right_axis_series_keys: Tuple[str, ...] = ()
    third_axis_series_keys: Tuple[str, ...] = ()
    if right_role == "temperature":
        right_axis_series_keys = ("z", "z2")
    elif right_role == "derivative":
        right_axis_series_keys = ("y2",)
    if third_role == "temperature":
        third_axis_series_keys = ("z", "z2")
    elif third_role == "derivative":
        third_axis_series_keys = ("y2",)

    axis_layer_zorders = {
        "left": _axis_role_layer_zorder(("y1", "y3"), role_bias=0.01, fallback=0.0),
        "right": _axis_role_layer_zorder(
            right_axis_series_keys, role_bias=0.02, fallback=0.0
        ),
        "third": _axis_role_layer_zorder(
            third_axis_series_keys, role_bias=0.03, fallback=0.0
        ),
    }
    axis_layer_zorders["overlay"] = max(axis_layer_zorders.values()) + 1000.0
    legend_layer_zorder = float(axis_layer_zorders["overlay"] + 1000.0)

    def _apply_combined_legend_layer(legend_obj: Any) -> None:
        """Force one combined-plot legend above all combined axes.

        Purpose:
            Apply a deterministic top-layer z-order to a combined plot legend.
        Why:
            Combined axes z-orders can exceed Matplotlib's default legend z-order,
            so legends must be explicitly lifted to stay visible.
        Inputs:
            legend_obj: Figure or axis legend artist to update.
        Outputs:
            None.
        Side Effects:
            Mutates legend z-order state when the artist supports set_zorder.
        Exceptions:
            Unsupported legend-like objects are ignored without raising.
        """
        if legend_obj is None:
            return
        setter = getattr(legend_obj, "set_zorder", None)
        if callable(setter):
            try:
                setter(legend_layer_zorder)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

    cycle_overlay = overlay_ctx.get("cycle_overlay")
    markers_overlay = overlay_ctx.get("markers", cycle_overlay)
    legend_overlay = overlay_ctx.get("cycle_legend", cycle_overlay)
    cycle_style = (
        get_cycle_trace_style() if (markers_overlay or legend_overlay) else None
    )
    moles_lines = overlay_ctx.get("moles_summary")
    if moles_lines is None and isinstance(cycle_overlay, dict):
        moles_lines = cycle_overlay.get("moles_lines")
    cycle_legend_overlays_raw = overlay_ctx.get("cycle_legend_overlays")
    if isinstance(cycle_legend_overlays_raw, Sequence) and not isinstance(
        cycle_legend_overlays_raw, (str, bytes)
    ):
        cycle_legend_overlays = [
            dict(item) for item in cycle_legend_overlays_raw if isinstance(item, Mapping)
        ]
    else:
        cycle_legend_overlays = []
    if not cycle_legend_overlays and isinstance(legend_overlay, Mapping):
        cycle_legend_overlays = [dict(legend_overlay)]

    try:
        overlay_has_data = False
        if isinstance(cycle_overlay, dict):
            overlay_has_data = bool(
                cycle_overlay.get("peak_points")
                or cycle_overlay.get("trough_points")
                or cycle_overlay.get("cycles")
            )
        fig._gl260_cycle_overlay_present = overlay_has_data  # type: ignore[attr-defined]
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass

    def _cycle_marker_artist(marker, color):
        """Perform cycle marker artist.
        Used to keep the workflow logic localized and testable."""
        size_val = None
        try:
            size_val = max(4.0, math.sqrt(float(cycle_style["marker_size"])))
        except Exception:
            size_val = 6.0
        return Line2D(
            [], [], linestyle="None", marker=marker, color=color, markersize=size_val
        )

    def _draw_cycle_markers(ax_target):
        """Render cycle markers on the dedicated combined overlay axis.

        Purpose:
            Draw cached cycle peak and trough points for combined plot overlays.
        Why:
            Overlay-axis rendering guarantees peak/trough markers stay above all
            data traces regardless of per-trace priority or numeric overrides.
        Inputs:
            ax_target: Overlay Axes receiving cycle marker scatter artists.
        Outputs:
            Tuple of (peak_artist, trough_artist), each possibly None.
        Side Effects:
            Adds marker scatter artists to the overlay axis.
        Exceptions:
            Returns (None, None) when cycle overlay data is unavailable.
        """
        if not (show_cycle_markers_on_core_plots and markers_overlay and cycle_style):
            return (None, None)
        cycle_marker_zorder = _compute_top_overlay_zorder(
            ax_target, min_z=CYCLE_MARKER_MIN_ZORDER, pad=CYCLE_MARKER_ZORDER_PAD
        )
        peak_artist = trough_artist = None
        def _visible_marker_points(points: Sequence[Any]) -> List[Tuple[float, float]]:
            """Return retained markers in the combined compressed x coordinate.

            Purpose/Why: Preserve alignment with display-compressed traces while
            cycle analysis continues to operate on unmodified source data.
            Inputs: Source-coordinate ``(x, y)`` marker pairs.
            Returns: Visible transformed marker pairs.
            Side Effects/Errors: None; malformed or excluded points are skipped.
            """
            visible: List[Tuple[float, float]] = []
            for point in points:
                try:
                    point_x, point_y = float(point[0]), float(point[1])
                except Exception:
                    continue
                mapped = _combined_exclusion_display_x([point_x], exclusion_ranges)
                if mapped.size and math.isfinite(float(mapped[0])):
                    visible.append((float(mapped[0]), point_y))
            return visible

        peaks = _visible_marker_points(markers_overlay.get("peak_points") or [])
        troughs = _visible_marker_points(markers_overlay.get("trough_points") or [])
        if peaks:
            px, py = zip(*peaks)
            peak_artist = ax_target.scatter(
                px,
                py,
                marker=cycle_style["peak_marker"],
                s=cycle_style["marker_size"],
                c=cycle_style["peak_color"],
                zorder=cycle_marker_zorder,
                label=_text_safe("Peak"),
            )
        if troughs:
            tx, ty = zip(*troughs)
            trough_artist = ax_target.scatter(
                tx,
                ty,
                marker=cycle_style["trough_marker"],
                s=cycle_style["marker_size"],
                c=cycle_style["trough_color"],
                zorder=cycle_marker_zorder,
                label=_text_safe("Trough"),
            )
        return peak_artist, trough_artist

    def _add_cycle_legend(
        ax_target,
        peak_artist,
        trough_artist,
        anchor=None,
        loc_override=None,
        anchor_space=None,
    ):
        """Add cycle summary legend artists to a combined plot.

        Purpose:
            Render active or per-primary-trace cycle summary legends on the
            combined triple-axis figure.
        Why:
            Combined plots support independent cycle legend placement and need
            trace-labeled summaries when multiple Primary Y traces are loaded.
        Inputs:
            Target/reference axis, optional peak/trough artists, and optional
            persisted anchor/location metadata.
        Outputs:
            The last created Matplotlib Legend, or None when legend display is off.
        Side Effects:
            Adds figure-level legends, applies layer metadata, and enables
            draggable handling where appropriate.
        Exceptions:
            Best-effort legend styling/metadata failures are caught locally.
        """
        if not (show_cycle_legend_on_core_plots and cycle_legend_overlays):
            return None
        legend_kwargs = {
            "fontsize": cycle_legend_fontsize_value,
            "prop": {"family": family_value, "size": cycle_legend_fontsize_value},
            "markerscale": cycle_legend_markerscale,
            **_legend_shadowbox_kwargs(),
        }
        loc_value = None
        if loc_override is not None:
            loc_value = _normalize_legend_loc_value(loc_override)
        if loc_value is None:
            loc_value = "upper right"
        if loc_value is not None:
            legend_kwargs["loc"] = loc_value
        anchor_value = _validated_anchor_pair(anchor)
        if anchor_value is None and isinstance(loc_value, str):
            loc_key = loc_value.strip().lower()
            anchor_map = {
                "upper right": (0.98, 0.98),
                "upper left": (0.02, 0.98),
                "lower right": (0.98, 0.02),
                "lower left": (0.02, 0.02),
                "center right": (0.98, 0.5),
                "center left": (0.02, 0.5),
                "upper center": (0.5, 0.98),
                "lower center": (0.5, 0.02),
                "center": (0.5, 0.5),
            }
            anchor_value = anchor_map.get(loc_key, (0.98, 0.98))
        if anchor_value is not None:
            legend_kwargs["bbox_to_anchor"] = anchor_value
        import matplotlib.patches as mpatches

        legends: List[Any] = []
        for legend_index, legend_payload in enumerate(cycle_legend_overlays):
            handles_cycle: List[Any] = []
            labels_cycle: List[str] = []
            if peak_artist is not None:
                handles_cycle.append(peak_artist)
                labels_cycle.append(_text_safe("Peak"))
            elif cycle_style:
                handles_cycle.append(
                    _cycle_marker_artist(
                        cycle_style["peak_marker"], cycle_style["peak_color"]
                    )
                )
                labels_cycle.append(_text_safe("Peak"))
            if trough_artist is not None:
                handles_cycle.append(trough_artist)
                labels_cycle.append(_text_safe("Trough"))
            elif cycle_style:
                handles_cycle.append(
                    _cycle_marker_artist(
                        cycle_style["trough_marker"], cycle_style["trough_color"]
                    )
                )
                labels_cycle.append(_text_safe("Trough"))
            cycles_list = legend_payload.get("cycles") or []
            total_drop_val = legend_payload.get("total_drop", 0.0)
            try:
                total_drop_val = float(total_drop_val)
            except Exception:
                total_drop_val = 0.0
            handles_cycle.append(Line2D([], [], color="none"))
            labels_cycle.append(
                _text_safe(f"Cycles: {_format_cycle_legend_count(len(cycles_list))}")
            )
            handles_cycle.append(mpatches.Patch(color="none"))
            labels_cycle.append(
                _text_safe(
                    f"Total ΔP: {_format_cycle_legend_number(total_drop_val, 2)} PSI"
                )
            )
            if include_moles_in_core_plot_legend:
                legend_moles = legend_payload.get("moles_lines")
                if legend_moles is None:
                    legend_moles = moles_lines
                # Iterate over legend_moles or [] to apply the per-item logic.
                for line in legend_moles or []:
                    handles_cycle.append(mpatches.Patch(color="none"))
                    labels_cycle.append(_text_safe(line))
            kwargs = dict(legend_kwargs)
            if legend_index > 0:
                offset_x = 0.02 if (legend_index % 2) else 0.98
                offset_y = max(0.02, 0.98 - (0.18 * legend_index))
                kwargs["loc"] = "upper left" if (legend_index % 2) else "upper right"
                kwargs["bbox_to_anchor"] = (offset_x, offset_y)
            title = str(legend_payload.get("trace_label") or "").strip()
            if title:
                kwargs["title"] = _text_safe(title)
            legend = fig.legend(handles_cycle, labels_cycle, **kwargs)
            if kwargs.get("bbox_to_anchor") is not None:
                try:
                    transform = None
                    if anchor_space == "axes" and ax_target is not None:
                        transform = ax_target.transAxes
                    elif anchor_space in {"figure", None}:
                        transform = fig.transFigure
                    if transform is None:
                        legend.set_bbox_to_anchor(kwargs.get("bbox_to_anchor"))
                    else:
                        legend.set_bbox_to_anchor(
                            kwargs.get("bbox_to_anchor"), transform=transform
                        )
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
            try:
                legend._cycle_overlay_legend = True  # type: ignore[attr-defined]
                legend._combined_cycle_legend = True  # type: ignore[attr-defined]
                legend._gl260_legend_role = "cycle"  # type: ignore[attr-defined]
                legend._gl260_cycle_legend_index = legend_index  # type: ignore[attr-defined]
                legend._gl260_cycle_trace_key = str(  # type: ignore[attr-defined]
                    legend_payload.get("trace_key") or ""
                ).strip()
                legend._gl260_cycle_trace_label = str(  # type: ignore[attr-defined]
                    legend_payload.get("trace_label") or ""
                ).strip()
                legend._gl260_markerscale = cycle_legend_markerscale  # type: ignore[attr-defined]
                legend._gl260_markerscale_base_font = (  # type: ignore[attr-defined]
                    DEFAULT_COMBINED_LEGEND_FONTSIZE
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            _apply_combined_legend_layer(legend)
            _make_legend_draggable(legend)
            legends.append(legend)
        return legends[-1] if legends else None

    primary_settings = _axis_settings(dataset_meta["y1"])

    # Iterate over ("y1", "y3") to apply the per-item logic.
    for key in ("y1", "y3"):
        artist = _plot_dataset(ax, dataset_meta[key], axis_role="left")
        if artist is not None:
            handles.extend(_iter_artist_handles(artist))

    ax.set_xlim(*time_range)
    if exclusion_ranges:
        fig._gl260_combined_exclusion_ranges = tuple(exclusion_ranges)  # type: ignore[attr-defined]
        fig._gl260_combined_source_x = source_x  # type: ignore[attr-defined]
        fig._gl260_combined_source_time_range = (min_time, max_time)  # type: ignore[attr-defined]
        # Short diagonal strokes identify where source elapsed time jumps across
        # a hidden range, rather than implying a continuous measurement.
        for start, end in exclusion_ranges:
            join_x = start - sum(
                prior_end - prior_start
                for prior_start, prior_end in exclusion_ranges
                if prior_end <= start
            )
            if time_range[0] < join_x < time_range[1]:
                ax.plot(
                    [join_x - 0.006, join_x + 0.006],
                    [-0.012, 0.012],
                    transform=ax.get_xaxis_transform(),
                    color="#4b5563",
                    clip_on=False,
                    linewidth=1.1,
                    zorder=10_000,
                )
        _draw_combined_exclusion_break_labels(
            ax,
            exclusion_ranges,
            time_range,
        )
    ax.set_ylim(*primary_settings["ylim"])
    if temperature_render_mode == "background" and temperature_visual is not None:
        background_artist = draw_temperature_background(ax, temperature_visual)
        if background_artist is not None:
            temperature_layout_artists.append(background_artist)
            register_layout_artist(fig, "temperature_background", background_artist)
    ax.set_zorder(axis_layer_zorders["left"])
    # Keep the primary axes background transparent so high-z primary layers never
    # occlude right/third-axis traces after dynamic axis z-order updates.
    ax.patch.set_visible(False)
    ax.set_facecolor("none")
    font_kwargs = {"fontsize": label_fontsize}
    if family_value:
        font_kwargs["fontfamily"] = family_value

    ax.set_ylabel(
        _label_or_default(primary_settings["label_key"], primary_meta.get("label", "")),
        labelpad=primary_settings["labelpad"],
        **font_kwargs,
    )
    title_display = _text_safe(title_text)

    axis_for_role: Dict[str, Axes] = {"primary": ax}
    show_derivative_zero_line = False
    derivative_zero_axis: Optional[Axes] = None

    right_axis_role = None
    right_axis_meta = None
    if isinstance(right_axis_assignment, Mapping):
        right_axis_role = right_axis_assignment.get("role")
        right_axis_meta = right_axis_assignment.get("meta")

    third_axis_role = None
    third_axis_meta = None
    if isinstance(third_axis_assignment, Mapping):
        third_axis_role = third_axis_assignment.get("role")
        third_axis_meta = third_axis_assignment.get("meta")

    # Inner-right axis always uses the "right" role, but dataset role can be
    # either temperature or derivative based on Combined settings.
    if isinstance(right_axis_meta, Mapping) and _axis_enabled(right_axis_meta):
        ax_temp = ax.twinx()
        try:
            ax_temp._gl260_axis_role = "right"
            ax_temp._gl260_axis_semantic = str(right_axis_role or "")
            ax_temp._gl260_axis_dataset_key = str(right_key or "")
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        _position_extra_axis(ax_temp, 1.0)
        ax_temp.tick_params(axis="x", which="both", bottom=False, labelbottom=False)

        right_settings = _axis_settings(right_axis_meta)

        ax_temp.set_ylim(*right_settings["ylim"])
        right_kwargs = {
            "color": "black",
            "rotation": -90,
            "labelpad": right_settings["labelpad"],
            "fontsize": label_fontsize,
        }
        if family_value:
            right_kwargs["fontfamily"] = family_value
        ax_temp.set_ylabel(
            _label_or_default(
                right_settings["label_key"], right_axis_meta.get("label", "")
            ),
            **right_kwargs,
        )
        ax_temp.tick_params(axis="y", labelcolor="black", labelsize=tick_fontsize)
        _apply_tick_font(ax_temp)
        _apply_axis_ticks(
            ax_temp,
            right_settings["auto"],
            right_settings["maj"],
            right_settings["min"],
        )
        ax_temp.set_zorder(axis_layer_zorders["right"])
        ax_temp.patch.set_visible(False)
        ax_temp.set_facecolor("none")
        if right_axis_role in {"temperature", "derivative"}:
            axis_for_role[str(right_axis_role)] = ax_temp
        if right_settings["label_key"] == "derivative":
            derivative_zero_axis = ax_temp

    # Outer-right axis always uses the "third" role, which may now host either
    # derivative or temperature depending on user axis-role selection.
    if isinstance(third_axis_meta, Mapping) and _axis_enabled(third_axis_meta):
        ax_deriv = ax.twinx()
        try:
            ax_deriv._gl260_axis_role = "third"
            ax_deriv._gl260_axis_semantic = str(third_axis_role or "")
            ax_deriv._gl260_axis_dataset_key = str(third_key or "")
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        _position_extra_axis(ax_deriv, deriv_spine_offset)
        ax_deriv.tick_params(axis="x", which="both", bottom=False, labelbottom=False)

        third_settings = _axis_settings(third_axis_meta)

        ax_deriv.set_ylim(*third_settings["ylim"])
        third_kwargs = {
            "color": "black",
            "rotation": -90,
            "labelpad": third_settings["labelpad"],
            "fontsize": label_fontsize,
        }
        if family_value:
            third_kwargs["fontfamily"] = family_value
        ax_deriv.set_ylabel(
            _label_or_default(
                third_settings["label_key"], third_axis_meta.get("label", "")
            ),
            **third_kwargs,
        )
        ax_deriv.tick_params(axis="y", labelcolor="black", labelsize=tick_fontsize)
        _apply_tick_font(ax_deriv)
        _apply_axis_ticks(
            ax_deriv,
            third_settings["auto"],
            third_settings["maj"],
            third_settings["min"],
        )
        ax_deriv.set_zorder(axis_layer_zorders["third"])
        ax_deriv.patch.set_visible(False)
        ax_deriv.set_facecolor("none")
        if third_axis_role in {"temperature", "derivative"}:
            axis_for_role[str(third_axis_role)] = ax_deriv
        if third_settings["label_key"] == "derivative":
            derivative_zero_axis = ax_deriv

    show_derivative_zero_line = bool(
        include_zero_line and derivative_zero_axis is not None
    )

    # Overlay axis carries only cycle markers and must render above all data axes.
    ax_overlay = ax.twinx()
    try:
        ax_overlay._gl260_axis_role = "overlay"
        ax_overlay._gl260_legend_only = True
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass
    ax_overlay.set_zorder(axis_layer_zorders["overlay"])
    ax_overlay.set_ylim(*ax.get_ylim())
    ax_overlay.set_autoscaley_on(False)
    ax_overlay.patch.set_visible(False)
    ax_overlay.set_facecolor("none")
    ax_overlay.set_frame_on(False)
    ax_overlay.tick_params(
        axis="both",
        which="both",
        left=False,
        right=False,
        bottom=False,
        top=False,
        labelleft=False,
        labelright=False,
        labelbottom=False,
        labeltop=False,
    )
    # Hide all overlay spines so only marker artists render on this axis.
    for spine in ax_overlay.spines.values():
        spine.set_visible(False)
    ax_overlay.yaxis.set_visible(False)
    ax_overlay.xaxis.set_visible(False)
    _ensure_combined_derivative_zero_line(
        fig,
        ax_overlay,
        derivative_zero_axis,
        visible=show_derivative_zero_line,
        zorder=6.0,
    )

    def _axis_zorder_text(axis: Optional[Axes]) -> str:
        """Return a debug-safe axis z-order string for logging.

        Purpose:
            Normalize axis z-order values into stable text for debug traces.
        Why:
            Layering verification logs should remain readable even when an axis
            is absent or reports non-finite values.
        Inputs:
            axis: Axis to inspect, or None when that axis is disabled.
        Outputs:
            String representation of the axis z-order.
        Side Effects:
            None.
        Exceptions:
            Returns "None" when the axis cannot provide a finite z-order.
        """
        if axis is None:
            return "None"
        try:
            z_value = float(axis.get_zorder())
        except Exception:
            return "None"
        if not math.isfinite(z_value):
            return "None"
        return f"{z_value:.6g}"

    _combined_render_debug(
        "Combined axes z-orders left=%s right=%s third=%s overlay=%s",
        _axis_zorder_text(ax),
        _axis_zorder_text(ax_temp),
        _axis_zorder_text(ax_deriv),
        _axis_zorder_text(ax_overlay),
    )

    temp_axis = axis_for_role.get("temperature")
    if temp_axis is not None:
        # Iterate over ("z", "z2") to apply the per-item logic.
        for key in ("z", "z2"):
            artist = _plot_dataset(
                temp_axis,
                dataset_meta[key],
                axis_role=str(temp_axis_position or "right"),
            )
            if artist is not None:
                handles.extend(_iter_artist_handles(artist))

    deriv_axis = axis_for_role.get("derivative")
    if deriv_axis is not None:
        artist = _plot_dataset(
            deriv_axis,
            dataset_meta["y2"],
            axis_role=str(deriv_axis_position or "third"),
        )
        if artist is not None:
            handles.extend(_iter_artist_handles(artist))

    if auto_time_ticks:
        ax.xaxis.set_major_locator(AutoLocator())
        ax.xaxis.set_minor_locator(AutoMinorLocator())
    else:
        ax.xaxis.set_major_locator(MultipleLocator(xmaj_tick))
        ax.xaxis.set_minor_locator(MultipleLocator(xmin_tick))

    if exclusion_ranges:
        _apply_combined_exclusion_time_axis(
            ax,
            exclusion_ranges,
            (float(min_time), float(max_time)),
            bool(auto_time_ticks),
            float(xmaj_tick),
            float(xmin_tick),
        )

    _apply_axis_ticks(
        ax,
        primary_settings["auto"],
        primary_settings["maj"],
        primary_settings["min"],
    )
    ax.tick_params(
        axis="both", which="major", labelcolor="black", labelsize=tick_fontsize
    )
    _apply_tick_font(ax)
    combined_peak_artist, combined_trough_artist = _draw_cycle_markers(ax_overlay)
    try:
        fig._gl260_cycle_marker_artists = {  # type: ignore[attr-defined]
            "peak": combined_peak_artist,
            "trough": combined_trough_artist,
        }
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass

    suptitle_display = _text_safe(suptitle_text)
    main_center_x = fig.subplotpars.left + (
        (fig.subplotpars.right - fig.subplotpars.left) / 2.0
    )
    try:
        pos = ax.get_position()
        main_center_x = pos.x0 + (pos.width / 2.0)
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass

    suptitle_artist = fig.suptitle(
        suptitle_display,
        fontsize=suptitle_fontsize_value,
        fontfamily=family_value if family_value else None,
        x=main_center_x,
    )
    title_artist = ax.set_title(
        title_display,
        fontsize=title_fontsize_value,
        pad=title_pad_value,
        fontfamily=family_value if family_value else None,
    )
    try:
        fig._gl260_title_text = title_artist  # type: ignore[attr-defined]
        fig._gl260_suptitle_text = suptitle_artist  # type: ignore[attr-defined]
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass

    # Figure-level xlabel keeps the legend pinned to the bottom zone.
    supxlabel = fig.supxlabel(
        x_label_text,
        fontsize=label_fontsize,
        fontfamily=family_value if family_value else None,
        x=main_center_x,
    )
    try:
        fig._gl260_xlabel_text = supxlabel  # type: ignore[attr-defined]
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass

    legend_labels = [_text_safe(handle.get_label()) for handle in handles]
    handles_filtered, labels_filtered = _filter_none_legend_entries(
        handles, legend_labels
    )
    if (
        handles_filtered
        and include_moles_in_core_plot_legend
        and not show_cycle_legend_on_core_plots
        and moles_lines
    ):
        import matplotlib.patches as mpatches

        # Iterate over moles_lines to apply the per-item logic.
        for line in moles_lines:
            handles_filtered.append(mpatches.Patch(color="none"))
            labels_filtered.append(_text_safe(line))
    legend_size = len(handles_filtered)
    main_legend = None
    if legend_size and show_main_legend_on_core_plots:
        try:
            figure_width = float(fig.get_size_inches()[0])
        except Exception:
            figure_width = None
        legend_layout = _resolve_combined_main_legend_layout(
            labels_filtered,
            legend_wrap=bool(legend_wrap),
            legend_rows=legend_rows,
            figure_width_in=figure_width,
            legend_fontsize=legend_fontsize_value,
        )
        main_legend = fig.legend(
            handles=handles_filtered,
            labels=legend_layout["labels"],
            loc="lower center",
            bbox_to_anchor=(main_center_x, 0.0),
            columnspacing=float(legend_layout["columnspacing"]),
            handletextpad=float(legend_layout["handletextpad"]),
            fontsize=legend_fontsize_value,
            prop={"family": family_value, "size": legend_fontsize_value},
            markerscale=legend_markerscale,
            ncol=int(legend_layout["ncol"]),
            **_legend_shadowbox_kwargs(),
        )
        try:
            main_legend._combined_main_legend = True  # type: ignore[attr-defined]
            main_legend._gl260_markerscale = legend_markerscale  # type: ignore[attr-defined]
            main_legend._gl260_legend_role = "main"  # type: ignore[attr-defined]
            main_legend._gl260_auto_fit_rows = int(legend_layout["rows"])  # type: ignore[attr-defined]
            main_legend._gl260_auto_fit_fallback = bool(  # type: ignore[attr-defined]
                legend_layout["auto_fallback"]
            )
            main_legend._gl260_markerscale_base_font = (  # type: ignore[attr-defined]
                DEFAULT_COMBINED_LEGEND_FONTSIZE
            )
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        _apply_combined_legend_layer(main_legend)
        if legend_anchor is not None:
            _apply_legend_anchor_to_artist(
                main_legend,
                legend_anchor,
                transform=fig.transFigure,
                loc_override=legend_loc,
            )
        elif legend_loc is not None:
            try:
                main_legend.set_loc(_normalize_legend_loc_value(legend_loc))
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

    cycle_loc_choices = {
        "upper right",
        "upper left",
        "lower right",
        "lower left",
        "center right",
        "center left",
        "upper center",
        "lower center",
        "center",
    }
    raw_cycle_loc_choice = settings.get(
        "combined_cycle_legend_loc_choice", "upper right"
    )
    if isinstance(raw_cycle_loc_choice, str):
        cycle_loc_choice = raw_cycle_loc_choice.strip().lower()
    else:
        cycle_loc_choice = str(raw_cycle_loc_choice).strip().lower()
    if cycle_loc_choice not in cycle_loc_choices:
        cycle_loc_choice = "upper right"

    # Cycle legend anchoring has two modes: direct anchor placement or axis-offset
    # capture for detached right spines. Offset mode wins to keep legend alignment
    # stable when the third axis is shifted.
    axis_offset_values = _combined_cycle_axis_offset_values()
    has_cycle_anchor = cycle_legend_anchor is not None and axis_offset_values is None
    cycle_anchor = cycle_legend_anchor if has_cycle_anchor else None
    cycle_loc_override = (
        cycle_legend_loc if cycle_legend_loc is not None else cycle_loc_choice
    )
    cycle_anchor_ref_axis = None
    if cycle_legend_anchor_space == "axes":
        # Preserve axis-space anchors by applying them against the configured
        # reference axis, matching export preview behavior.
        cycle_anchor_ref_axis = _resolve_combined_cycle_ref_axis(
            fig,
            ax_main=ax,
            ax_right=ax_temp,
            ax_deriv=ax_deriv,
            ref_axis_key=settings.get("combined_cycle_legend_ref_axis"),
        )
        if cycle_anchor_ref_axis is None:
            cycle_anchor_ref_axis = ax
    cycle_anchor_axis = cycle_anchor_ref_axis or ax
    cycle_legend = _add_cycle_legend(
        cycle_anchor_axis,
        combined_peak_artist,
        combined_trough_artist,
        anchor=cycle_anchor,
        loc_override=cycle_loc_override,
        anchor_space=cycle_legend_anchor_space,
    )
    if cycle_legend is not None and has_cycle_anchor:
        legend_transform = fig.transFigure
        if cycle_legend_anchor_space == "axes" and cycle_anchor_ref_axis is not None:
            legend_transform = cycle_anchor_ref_axis.transAxes
        _apply_legend_anchor_to_artist(
            cycle_legend,
            cycle_legend_anchor,
            transform=legend_transform,
            loc_override=cycle_loc_override,
        )
    if axis_offset_values is not None and cycle_legend is not None:
        try:
            # Apply offsets before layout solve so legend bboxes reflect drag placement.
            ref_axis = _resolve_combined_cycle_ref_axis(
                fig,
                ax_main=ax,
                ax_right=ax_temp,
                ax_deriv=ax_deriv,
                ref_axis_key=settings.get("combined_cycle_legend_ref_axis"),
            )
            loc_value = _resolve_combined_cycle_legend_loc()
            _apply_cycle_legend_axis_offset(
                fig,
                cycle_legend,
                ref_axis,
                settings.get("combined_cycle_legend_ref_corner"),
                axis_offset_values[0],
                axis_offset_values[1],
                loc_value,
                allow_draw=False,
            )
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
    # Enforce the final legend layer for both newly created and reused legend artists.
    # Iterate over _collect_gl260_legends(fig) to apply the per-item logic.
    for legend_artist in _collect_gl260_legends(fig):
        _apply_combined_legend_layer(legend_artist)

    # Layout solve: measure bboxes + adjust margins in a deterministic pass.
    layout_manager = PlotLayoutManager(
        fig,
        mode=mode_value,
        baseline_margins=baseline_margins,
        left_pad_pct=left_pad_value,
        right_pad_pct=right_pad_value,
        export_pad_pts=export_pad_pts,
        margins_authoritative=True,
        legend_gap_pts=legend_label_gap_pts,
        xlabel_tick_gap_pts=xlabel_tick_gap_pts,
        legend_margin_pts=legend_bottom_margin_pts,
        title_pad_pts=title_pad_value,
        suptitle_pad_pts=suptitle_pad_value,
        suptitle_y=suptitle_y_value,
        top_margin_pct=top_margin_value,
        legend_anchor=legend_anchor,
        legend_anchor_y=legend_anchor_y,
        xlabel_pad_pts=xlabel_pad_value,
    )
    # Register non-axis temperature artists before solving so the Layout Health
    # Wizard can discover their colorbar/inset geometry on every render target.
    for artist_index, temperature_artist in enumerate(temperature_layout_artists):
        register_layout_artist(
            fig,
            f"temperature_visual_{artist_index}",
            temperature_artist,
            layout_manager=layout_manager,
        )
    if temperature_render_mode != "axis" and temperature_visual is not None:
        create_temperature_colorbar(
            fig, ax, temperature_visual, layout_manager=layout_manager
        )
    layout_manager.register_axes(ax, ax_temp, ax_deriv)
    layout_manager.register_artist("title", title_artist)
    layout_manager.register_artist("suptitle", suptitle_artist)
    layout_manager.register_artist("xlabel", supxlabel)
    layout_manager.register_artist("plot_legend", main_legend)
    layout_manager.register_artist("cycle_legend", cycle_legend)
    layout_manager.set_legend_alignment(legend_alignment)
    fig._gl260_layout_manager = layout_manager  # type: ignore[attr-defined]
    # Export mode resolves full layout to lock bounding boxes; preview uses a
    # single-pass solve to avoid UI jitter while still honoring margins.
    if mode_value == "export":
        layout_manager.solve()
    else:
        layout_manager.solve(max_passes=1, allow_draw=False)
    fig._gl260_title_state = {
        "suptitle": suptitle_display,
        "title_fs": title_fontsize_value,
        "suptitle_fs": suptitle_fontsize_value,
        "font_family": family_value,
        "title_pad_pts": title_pad_value,
        "suptitle_pad_pts": suptitle_pad_value,
        "suptitle_y": suptitle_y_value,
    }

    if fig.canvas is None:
        FigureCanvasAgg(fig)
    try:
        if mode_value == "export":
            fig.canvas.draw()
        else:
            fig.canvas.draw_idle()
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass

    # Cycle legend offsets are normalized against a reference axis so detached
    # spines export consistently across DPI and canvas sizes.
    if cycle_legend is not None:
        ref_axis = _resolve_combined_cycle_ref_axis(
            fig,
            ax_main=ax,
            ax_right=ax_temp,
            ax_deriv=ax_deriv,
            ref_axis_key=settings.get("combined_cycle_legend_ref_axis"),
        )
        loc_value = _resolve_combined_cycle_legend_loc()
        # New axis-offset mode: apply precomputed offsets tied to the chosen
        # reference axis/corner to avoid drift between preview and export.
        if axis_offset_values is not None:
            _apply_cycle_legend_axis_offset(
                fig,
                cycle_legend,
                ref_axis,
                settings.get("combined_cycle_legend_ref_corner"),
                axis_offset_values[0],
                axis_offset_values[1],
                loc_value,
                allow_draw=(mode_value == "export"),
            )
        else:
            # Legacy anchor mode: capture offsets once and persist for stability.
            legacy_anchor = _validated_anchor_pair(
                settings.get("combined_cycle_legend_anchor")
            )
            if legacy_anchor is not None:
                try:
                    renderer = fig.canvas.get_renderer()
                except Exception:
                    renderer = None
                offsets = _compute_cycle_legend_offsets_px(
                    cycle_legend,
                    ref_axis,
                    settings.get("combined_cycle_legend_ref_corner"),
                    loc_value,
                    renderer,
                )
                if offsets is not None:
                    settings["combined_cycle_legend_ref_dx_px"] = offsets[0]
                    settings["combined_cycle_legend_ref_dy_px"] = offsets[1]
                    settings["combined_cycle_legend_anchor_mode"] = "axis_offset"
                    axis_offset_values = offsets
                    _apply_cycle_legend_axis_offset(
                        fig,
                        cycle_legend,
                        ref_axis,
                        settings.get("combined_cycle_legend_ref_corner"),
                        offsets[0],
                        offsets[1],
                        loc_value,
                        allow_draw=(mode_value == "export"),
                    )
                    try:
                        _save_settings_to_disk()
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting the workflow.
                        pass

    # Iterate over (ax, ax_temp, ax_deriv) to apply the per-item logic.
    for axis in (ax, ax_temp, ax_deriv):
        if axis is None:
            continue
        _enforce_axis_text_style(
            axis,
            font_family=family_value,
            tick_fontsize=tick_fontsize,
            label_fontsize=label_fontsize,
        )

    # Final pass: enforce y-axis label font family/size after all positioning.
    try:
        if mode_value == "export":
            fig.canvas.draw()
        else:
            fig.canvas.draw_idle()
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass
    y_label_sizes: List[float] = []
    # Iterate over (ax, ax_temp, ax_deriv) to apply the per-item logic.
    for axis in (ax, ax_temp, ax_deriv):
        if axis is None:
            continue
        try:
            label_obj = axis.yaxis.label
        except Exception:
            continue
        try:
            label_text = label_obj.get_text()
            if label_text and "°" in label_text and mathtext.is_math_text(label_text):
                label_obj.set_text(label_text.replace("$", ""))
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            label_obj.set_fontsize(label_fontsize)
            if family_value:
                label_obj.set_fontfamily(family_value)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            y_label_sizes.append(float(label_obj.get_fontsize()))
        except Exception:
            continue
    if y_label_sizes:
        try:
            min_size = min(y_label_sizes)
            max_size = max(y_label_sizes)
            if abs(max_size - min_size) > 0.01:
                print(
                    "[WARN] Combined axis y-label font sizes mismatch:",
                    [round(val, 2) for val in y_label_sizes],
                )
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _axis_tick_sizes(axis: Optional[Axes]) -> Set[float]:
        """Perform axis tick sizes.
        Used to keep the workflow logic localized and testable."""
        if axis is None:
            return set()
        sizes: Set[float] = set()
        # Iterate over axis.get_yticklabels() to apply the per-item logic.
        for tick in axis.get_yticklabels():
            text = tick.get_text()
            if not text or not text.strip():
                continue
            try:
                sizes.add(round(float(tick.get_fontsize()), 2))
            except Exception:
                continue
        return sizes

    def _axis_tick_families(axis: Optional[Axes]) -> Set[str]:
        """Perform axis tick families.
        Used to keep the workflow logic localized and testable."""
        if axis is None:
            return set()
        families: Set[str] = set()
        # Iterate over axis.get_yticklabels() to apply the per-item logic.
        for tick in axis.get_yticklabels():
            text = tick.get_text()
            if not text or not text.strip():
                continue
            try:
                family = tick.get_fontfamily()
            except Exception:
                continue
            if isinstance(family, (list, tuple)):
                if family:
                    families.add(str(family[0]))
            elif family:
                families.add(str(family))
        return families

    axes_to_check = [axis for axis in (ax, ax_temp, ax_deriv) if axis is not None]
    size_sets = [vals for vals in (_axis_tick_sizes(a) for a in axes_to_check) if vals]
    if len(size_sets) >= 2 and len({frozenset(vals) for vals in size_sets}) > 1:
        print(
            "[WARN] Combined axis tick font sizes mismatch:",
            [sorted(vals) for vals in size_sets],
        )
    family_sets = [
        vals for vals in (_axis_tick_families(a) for a in axes_to_check) if vals
    ]
    if len(family_sets) >= 2 and len({frozenset(vals) for vals in family_sets}) > 1:
        print(
            "[WARN] Combined axis tick font families mismatch:",
            [sorted(vals) for vals in family_sets],
        )

    try:
        fig._gl260_combined_line_map = line_map  # type: ignore[attr-defined]
        fig._gl260_combined_axes_map = {  # type: ignore[attr-defined]
            "primary": ax,
            "right": ax_temp,
            "third": ax_deriv,
            "overlay": ax_overlay,
        }
        fig._gl260_combined_axis_keys = {  # type: ignore[attr-defined]
            "left": left_key,
            "right": right_key,
            "third": third_key,
        }
        fig._gl260_combined_axis_semantics = {  # type: ignore[attr-defined]
            "right": right_axis_role,
            "third": third_axis_role,
        }
    except Exception:
        # Best-effort guard; ignore failures to avoid interrupting the workflow.
        pass

    return fig


def _debug_validate_svg_export(output_path: Optional[str] = None) -> Tuple[bool, str]:
    """Validate SVG export.
    Used by debug workflows to validate SVG export."""

    import xml.etree.ElementTree as ET

    target_path = output_path or os.path.join(
        tempfile.gettempdir(), "gl260_combined_svg_validation.svg"
    )
    sentinel = object()
    globals_snapshot: Dict[str, Any] = {
        key: globals().get(key, sentinel)
        # Iterate to apply the per-item logic.
        for key in (
            "x",
            "y1",
            "y2",
            "y3",
            "z",
            "z2",
            "selected_columns",
            "core_cycle_overlay",
        )
    }
    fig: Optional[Figure] = None
    try:
        globals().update(
            {
                "x": np.array([0.0, 1.0, 2.0]),
                "y1": np.array([1.0, 2.0, 3.0]),
                "y3": np.array([3.0, 2.0, 1.0]),
                "y2": np.array([0.0, -0.5, 0.5]),
                "z": np.array([25.0, 30.0, 28.0]),
                "z2": np.array([24.0, 29.0, 27.0]),
                "selected_columns": {
                    "x": "Elapsed Time & seconds",
                    "y1": "NaOH & CO2",
                    "y3": "Aux < Pressure >",
                    "y2": "dP/dt \"Rate\" 'Calc'",
                    "z": 'Temp "C" & Rising',
                    "z2": "Temp' Aux <Run>",
                },
                "core_cycle_overlay": None,
            }
        )
        fig = build_combined_triple_axis_figure(
            0.0,
            2.0,
            0.0,
            4.0,
            20.0,
            40.0,
            -2.0,
            2.0,
            True,
            True,
            True,
            True,
            'Validation Title & Check <Run> "Demo"',
            "Suptitle 'Quick' & Overview",
            1.0,
            0.5,
            1.0,
            0.5,
            5.0,
            1.0,
            0.5,
            0.25,
            True,
            True,
            1.1,
        )
        fig.savefig(target_path, format="svg")
        ET.parse(target_path)
        return True, target_path
    except Exception as exc:
        raise RuntimeError(f"SVG validation failed for {target_path}: {exc}") from exc
    finally:
        if fig is not None:
            try:
                plt.close(fig)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        # Iterate over items from globals_snapshot to apply the per-item logic.
        for key, original in globals_snapshot.items():
            if original is sentinel:
                globals().pop(key, None)
            else:
                globals()[key] = original


def _debug_with_fresh_settings(func):
    """Perform debug with fresh settings.
    Used to keep the workflow logic localized and testable."""
    settings_path = os.path.abspath(SETTINGS_FILE)
    backup_path = None
    if os.path.exists(settings_path):
        backup_path = f"{settings_path}.debug-backup"
        counter = 1
        # Repeat while os.path.exists(backup_path) to advance the looped workflow.
        while os.path.exists(backup_path):
            backup_path = f"{settings_path}.debug-backup-{counter}"
            counter += 1
        shutil.move(settings_path, backup_path)
    settings_snapshot = dict(settings)
    settings.clear()
    try:
        return func()
    finally:
        settings.clear()
        settings.update(settings_snapshot)
        if backup_path:
            try:
                if os.path.exists(settings_path):
                    created_path = f"{settings_path}.debug-created"
                    counter = 1
                    # Repeat while os.path.exists(created_path) to advance the looped workflow.
                    while os.path.exists(created_path):
                        created_path = f"{settings_path}.debug-created-{counter}"
                        counter += 1
                    shutil.move(settings_path, created_path)
                shutil.move(backup_path, settings_path)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass


def _debug_set_sol_value(app, key: str, value: Optional[float]) -> None:
    """Set sol value.
    Used by debug workflows to set sol value."""
    vars_map = getattr(app, "_solubility_vars", None)
    if not isinstance(vars_map, dict):
        raise RuntimeError("Solubility inputs are not initialized.")
    var = vars_map.get(key)
    if var is None:
        var = app._create_persistent_solubility_var(key, "")
        vars_map[key] = var
        app._solubility_vars = vars_map
    var.set("" if value is None else str(value))


def _debug_clear_sol_inputs(app) -> None:
    """Clear sol inputs.
    Used by debug workflows to clear sol inputs."""
    vars_map = getattr(app, "_solubility_vars", None)
    if not isinstance(vars_map, dict):
        raise RuntimeError("Solubility inputs are not initialized.")
    # Iterate over values from vars_map to apply the per-item logic.
    for var in vars_map.values():
        try:
            var.set("")
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass


def _debug_assert_scoped_none(form_data: Dict[str, Any], keys: Sequence[str]) -> None:
    """Perform debug assert scoped none.
    Used to keep the workflow logic localized and testable."""
    # Iterate over keys to apply the per-item logic.
    for key in keys:
        if form_data.get(key) not in (None, ""):
            raise AssertionError(f"Expected {key} to be None in scoped form data.")


def _debug_test_defaults_planning_scoped(app) -> Dict[str, Any]:
    """Perform debug test defaults planning scoped.
    Used to keep the workflow logic localized and testable."""
    # Closure captures _debug_test_defaults_planning_scoped local context to keep helper logic scoped and invoked directly within _debug_test_defaults_planning_scoped.
    def _run():
        """Run value.
        Used to execute value and coordinate results."""
        _debug_clear_sol_inputs(app)
        mode_var = getattr(app, "_sol_mode_var", None)
        if mode_var is not None:
            mode_var.set("nahco3_dissolution")
        try:
            app._select_sol_workflow_tab("Planning")
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        include_headspace_var = getattr(app, "_sol_include_headspace_var", None)
        if include_headspace_var is not None:
            include_headspace_var.set(True)
        limit_ionic_var = getattr(app, "_sol_limit_ionic_var", None)
        if limit_ionic_var is not None:
            limit_ionic_var.set(False)

        required_values = {
            "mass_naoh_g": 100.0,
            "water_mass_g": 1000.0,
            "temperature_c": 25.0,
            "planning_cycle_delta_p_psi": 250.0,
            "planning_headspace_pressure_high_psi": 750.0,
            "planning_headspace_volume_l": 1.0,
            "headspace_pco2_atm": 0.1,
            "headspace_kh_m_per_atm": 0.033,
        }
        # Iterate over items from required_values to apply the per-item logic.
        for key, value in required_values.items():
            _debug_set_sol_value(app, key, value)

        try:
            form_data = app._collect_solubility_form_data()
        except Exception as exc:
            raise AssertionError(f"Planning scoped test failed: {exc}") from exc
        _debug_assert_scoped_none(
            form_data,
            [
                "reaction_naoh_mass",
                "reaction_solution_volume",
                "reaction_co2_g",
                "reaction_final_ph",
                "reaction_slurry_ph",
                "reaction_target_ph",
                "measured_ph_cycle_index",
                "measured_ph_value",
                "failing_ph",
            ],
        )
        diagnostic_data = form_data.get("diagnostic_data") or {}
        _debug_assert_scoped_none(
            diagnostic_data,
            [
                "dried_ph",
                "slurry_ph",
                "target_ph",
                "sample_mass_g",
            ],
        )
        return form_data

    return _debug_with_fresh_settings(_run)


