    def _refresh_performance_diagnostics(self) -> None:
        """Refresh the Developer Tools performance/diagnostics text output.

        Purpose:
            Rebuild the performance panel content from current runtime state.
        Why:
            Users need both latest timing snapshots and live concurrency details
            when tuning worker settings.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Rewrites the diagnostics text widget content.
        Exceptions:
            Missing/destroyed widgets short-circuit safely.
        """
        output = getattr(self, "_perf_diag_output", None)
        if output is None or not output.winfo_exists():
            return
        enabled = bool(self._perf_diag_enabled_var.get())
        report = self._perf_diag_last_run
        active_report = (
            self._perf_diag_active_run
            if isinstance(self._perf_diag_active_run, dict)
            else None
        )
        if not enabled:
            body = "Diagnostics disabled."
        elif active_report is not None and active_report is not report:
            body = "Render in progress...\n\n" + self._format_performance_report(
                active_report
            )
        elif not report:
            body = "No diagnostics captured yet."
        else:
            body = self._format_performance_report(report)
        runtime_diag = self._format_runtime_concurrency_diagnostics()
        if runtime_diag:
            body = f"{body}\n\n{runtime_diag}"
        output.configure(state="normal")
        output.delete("1.0", tk.END)
        output.insert("end", body + "\n")
        output.configure(state="disabled")

    def _format_performance_report(self, report: Dict[str, Any]) -> str:
        """Format one captured performance report for display.

        Purpose:
            Convert a structured render performance payload into readable text.
        Why:
            The diagnostics UI requires a compact, stable format for stage-level
            timing and cache-path interpretation.
        Inputs:
            report: Captured performance payload from render workflows.
        Outputs:
            Multi-line report text.
        Side Effects:
            None.
        Exceptions:
            Missing fields are handled with safe defaults.
        """
        lines = []
        plot_kind = report.get("plot_kind") or "unknown"
        target = report.get("target") or "display"
        timestamp = report.get("timestamp") or ""
        lines.append(f"Plot: {plot_kind}")
        lines.append(f"Target: {target}")
        if timestamp:
            lines.append(f"Timestamp: {timestamp}")
        stages = report.get("stages") or {}
        lines.append("")
        for key in ("prepared", "cycle", "combined", "embed"):
            entry = stages.get(key)
            if not isinstance(entry, dict):
                continue
            ms = entry.get("ms")
            cache = entry.get("cache")
            path = entry.get("path")
            extra = entry.get("extra")
            if ms is None and key != "combined":
                continue
            line = f"{key}: {ms:.2f} ms" if ms is not None else f"{key}: in-progress"
            if cache:
                line += f" ({cache})"
            if path:
                line += f" [{path}]"
            if extra:
                line += f" {extra}"
            lines.append(line)
            if key == "combined":
                worker_ms = entry.get("worker_ms")
                build_ms = entry.get("build_ms")
                layout_ms = entry.get("layout_ms")
                install_ms = entry.get("install_ms")
                finalize_ms = entry.get("finalize_ms")
                ui_render_ms = entry.get("ui_render_ms")
                if worker_ms is not None:
                    lines.append(f"worker: {worker_ms:.2f} ms")
                if build_ms is not None:
                    lines.append(f"build: {build_ms:.2f} ms")
                if layout_ms is not None:
                    lines.append(f"layout: {layout_ms:.2f} ms")
                if install_ms is not None:
                    lines.append(f"install: {install_ms:.2f} ms")
                if finalize_ms is not None:
                    lines.append(f"finalize: {finalize_ms:.2f} ms")
                if ui_render_ms is not None:
                    lines.append(f"ui_render: {ui_render_ms:.2f} ms")
                if entry.get("auto_refresh_passes") is not None:
                    lines.append(
                        "auto_refresh_passes: %s"
                        % int(entry.get("auto_refresh_passes") or 0)
                    )
                if entry.get("auto_refresh_mode") is not None:
                    lines.append(
                        "auto_refresh_mode: %s"
                        % str(entry.get("auto_refresh_mode") or "")
                    )
                if entry.get("auto_refresh_target") is not None:
                    lines.append(
                        "auto_refresh_target: %s"
                        % int(entry.get("auto_refresh_target") or 0)
                    )
                if entry.get("series_prepare_workers") is not None:
                    lines.append(
                        "series_workers: %s"
                        % int(entry.get("series_prepare_workers") or 1)
                    )
                if entry.get("cycle_workers") is not None:
                    lines.append(
                        "cycle_workers: %s" % int(entry.get("cycle_workers") or 1)
                    )
                runner_start = entry.get("runner_start")
                runner_end = entry.get("runner_end")

                def _runner_diag_text(prefix: str, payload: Any) -> None:
                    """Append compact task-runner active/pending diagnostics text.

                    Purpose:
                        Render one compact diagnostics line for runner snapshots.
                    Why:
                        Combined render tuning needs active/pending visibility at
                        stage boundaries to confirm worker utilization.
                    Inputs:
                        prefix: Display label (`runner_start` / `runner_end`).
                        payload: Structured runner diagnostics bundle.
                    Outputs:
                        None.
                    Side Effects:
                        Appends a formatted line to `lines`.
                    Exceptions:
                        Invalid payloads are ignored.
                    """
                    if not isinstance(payload, dict):
                        return
                    task_diag = payload.get("task_runner") or {}
                    combined_diag = payload.get("combined_runner") or {}
                    lines.append(
                        (
                            "%s: task(active=%s pending=%s) "
                            "combined(active=%s pending=%s)"
                        )
                        % (
                            prefix,
                            task_diag.get("active"),
                            task_diag.get("pending"),
                            combined_diag.get("active"),
                            combined_diag.get("pending"),
                        )
                    )

                _runner_diag_text("runner_start", runner_start)
                _runner_diag_text("runner_end", runner_end)
        return "\n".join(lines)

    def _format_runtime_concurrency_diagnostics(self) -> str:
        """Build live concurrency diagnostics text for Developer Tools.

        Purpose:
            Surface task-runner worker/queue state alongside runtime no-GIL info.
        Why:
            Threading controls need immediate observability to confirm effective
            worker counts during render/startup workflows.
        Inputs:
            None.
        Outputs:
            Multi-line diagnostics string.
        Side Effects:
            None.
        Exceptions:
            Best-effort guards return fallback text on diagnostic failures.
        """
        lines: List[str] = ["Runtime Concurrency Diagnostics"]
        try:
            configured_workers = max(1, int(settings.get("dev_worker_threads", 1)))
        except Exception:
            configured_workers = 1
        configured_parallel = bool(settings.get("dev_enable_parallel_compute", False))
        lines.append(f"Configured worker threads: {configured_workers}")
        lines.append(f"Parallel compute enabled: {configured_parallel}")
        lines.append(f"Runtime no-GIL active: {bool(_is_runtime_gil_disabled())}")
        lines.append(f"CPU count: {int(os.cpu_count() or 1)}")

        def _append_runner(name: str, runner: Any) -> None:
            """Append one task-runner diagnostics block to the output list.

            Purpose:
                Keep diagnostics formatting consistent across multiple task runners.
            Why:
                The app uses separate runners for general tasks and combined render.
            Inputs:
                name: Display label for the task runner.
                runner: Runner object exposing `get_diagnostics`.
            Outputs:
                None.
            Side Effects:
                Appends formatted lines to the outer `lines` list.
            Exceptions:
                Missing/invalid diagnostics are handled with fallback text.
            """
            if runner is None or not hasattr(runner, "get_diagnostics"):
                lines.append(f"{name}: unavailable")
                return
            try:
                diag = runner.get_diagnostics()
            except Exception as exc:
                lines.append(f"{name}: diagnostics unavailable ({exc})")
                return
            lines.append(
                f"{name}: max_workers={diag.get('max_workers')} "
                f"live_threads={diag.get('live_threads')} "
                f"queue_depth={diag.get('queue_depth')}"
            )
            lines.append(
                f"{name}: tracked={diag.get('tracked_tasks')} "
                f"active={diag.get('active_tasks')} "
                f"pending={diag.get('pending_tasks')} "
                f"done={diag.get('done_tasks')}"
            )
            task_names = diag.get("task_names") or ()
            if task_names:
                lines.append(
                    f"{name}: task_names={', '.join(str(v) for v in task_names)}"
                )

        _append_runner("Task runner", getattr(self, "_task_runner", None))
        _append_runner(
            "Combined runner", getattr(self, "_combined_render_runner", None)
        )
        return "\n".join(lines)

    def _emit_startup_runtime_diagnostics_banner(self) -> None:
        """Emit one startup diagnostics banner for runtime and Rust backend state.

        Purpose:
            Provide an immediate startup-time summary of interpreter and optional
            Rust backend readiness.
        Why:
            Performance troubleshooting depends on confirming no-GIL runtime mode
            and Rust module status up front without opening Developer Tools.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Writes one banner line to stderr and debug logging.
        Exceptions:
            Best-effort guards suppress probe/log failures.
        """
        try:
            fp = _runtime_free_threading_fingerprint()
        except Exception:
            fp = {}
        gil_enabled = fp.get("gil_enabled")
        if gil_enabled is None:
            runtime_mode = "runtime-gil=unknown"
        else:
            runtime_mode = (
                "runtime-gil=enabled" if bool(gil_enabled) else "runtime-gil=disabled"
            )
        build_label = str(fp.get("build_label") or "Python runtime")

        rust_mode = _current_rust_backend_mode()
        rust_status = "module unavailable"
        if rust_mode == "python":
            rust_status = "python-only mode"
        else:
            if _RUST_BACKEND_IMPORT_ATTEMPTED:
                rust_module = globals().get("_RUST_BACKEND_MODULE", None)
                if rust_module is not None:
                    rust_status = "module ready"
                else:
                    rust_error = globals().get("_RUST_BACKEND_IMPORT_ERROR", None)
                    if rust_error is not None:
                        rust_status = "module unavailable (%s)" % type(rust_error).__name__
            else:
                rust_status = "not yet probed"
        banner = (
            f"Startup Runtime: {build_label} ({runtime_mode}) | "
            f"Rust backend: {rust_status}"
        )
        try:
            print(banner, file=sys.stderr)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        self._dbg("rust.backend", "%s", banner)

    def _record_performance_run(self, report: Dict[str, Any]) -> None:
        """Store a captured performance run and refresh diagnostics UI.

        Purpose:
            Preserve the latest render diagnostics payload for inspection.
        Why:
            Developer Tools should always show the most recent captured timings.
        Inputs:
            report: Structured performance payload from render workflows.
        Outputs:
            None.
        Side Effects:
            Updates in-memory performance snapshot and refreshes diagnostics text.
        Exceptions:
            None.
        """
        self._perf_diag_last_run = report
        self._emit_compact_performance_summary(report)
        self._refresh_performance_diagnostics()

    def _emit_compact_performance_summary(self, report: Dict[str, Any]) -> None:
        """Emit one compact terminal/debug summary line for combined renders.

        Purpose:
            Provide a single high-signal perf line per captured combined render.
        Why:
            Fast tuning loops need one scan-friendly summary instead of parsing
            the full diagnostics panel after each run.
        Inputs:
            report: Structured render-performance payload.
        Outputs:
            None.
        Side Effects:
            Writes summary text to stderr and debug logging.
        Exceptions:
            Best-effort guards suppress output failures.
        """
        if not isinstance(report, dict):
            return
        plot_kind = str(report.get("plot_kind") or "")
        if plot_kind not in {"fig_combined", "combined"}:
            return
        stages = report.get("stages") or {}
        combined = stages.get("combined") or {}
        if not isinstance(combined, dict):
            return
        parts = [
            "Combined render:",
            "worker=%.2fms" % float(combined.get("worker_ms", 0.0) or 0.0),
            "build=%.2fms" % float(combined.get("build_ms", 0.0) or 0.0),
            "layout=%.2fms" % float(combined.get("layout_ms", 0.0) or 0.0),
            "install=%.2fms" % float(combined.get("install_ms", 0.0) or 0.0),
            "finalize=%.2fms" % float(combined.get("finalize_ms", 0.0) or 0.0),
            "passes=%s" % int(combined.get("auto_refresh_passes", 0) or 0),
            "mode=%s" % str(combined.get("auto_refresh_mode") or ""),
        ]
        summary = " ".join(parts)
        try:
            print(summary, file=sys.stderr)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        self._dbg("perf.timing", "%s", summary)

    def _configure_debug_logging(self) -> None:
        """Configure debug logging handlers and levels.

        Purpose:
            Ensure logging output is wired consistently for debug categories.
        Why:
            Keeps debug output centralized and toggled via Developer Tools.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Adds/removes logging handlers and updates logger levels.
        Exceptions:
            Best-effort guards prevent logging setup from crashing the UI.
        """
        try:
            logger = _GL260_LOGGER
            enabled = bool(self._debug_enabled)
            file_enabled = bool(self._debug_file_logging_enabled)
            level = logging.DEBUG if enabled else logging.WARNING
            logger.setLevel(level)

            if self._debug_log_handler is None:
                handler = logging.StreamHandler()
                handler.setFormatter(
                    logging.Formatter("%(asctime)s [%(levelname)s] %(message)s")
                )
                self._debug_log_handler = handler
                logger.addHandler(handler)
            if self._debug_log_handler is not None:
                self._debug_log_handler.setLevel(level)

            if file_enabled:
                if self._debug_file_handler is None:
                    settings_dir = os.path.dirname(os.path.abspath(SETTINGS_FILE)) or "."
                    log_path = os.path.join(settings_dir, DEBUG_LOG_FILE)
                    handler = RotatingFileHandler(
                        log_path, maxBytes=1_000_000, backupCount=3, encoding="utf-8"
                    )
                    handler.setFormatter(
                        logging.Formatter("%(asctime)s [%(levelname)s] %(message)s")
                    )
                    self._debug_file_handler = handler
                    logger.addHandler(handler)
                if self._debug_file_handler is not None:
                    self._debug_file_handler.setLevel(level)
            elif self._debug_file_handler is not None:
                try:
                    logger.removeHandler(self._debug_file_handler)
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
                try:
                    self._debug_file_handler.close()
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
                self._debug_file_handler = None
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _persist_debug_settings(self) -> None:
        """Persist debug settings to disk.

        Purpose:
            Save debug-related settings immediately after a toggle change.
        Why:
            Ensures Developer Tools choices persist across restarts.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Writes to settings.json via the existing save pathway.
        Exceptions:
            Best-effort guard suppresses persistence errors.
        """
        settings["debug_enabled"] = bool(self._debug_enabled)
        settings["debug_categories"] = dict(self._debug_categories)
        settings["debug_file_logging_enabled"] = bool(
            self._debug_file_logging_enabled
        )
        try:
            _save_settings_to_disk()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _set_disable_startup_tab_cycling(self, enabled: bool) -> None:
        """Apply startup tab-cycling preference and persist it.

        Purpose:
            Update the Developer Tools toggle that controls startup warmup
            tab cycling.
        Why:
            Developers need a persistent way to keep startup splash visible while
            readiness is verified without notebook tab-selection churn.
        Inputs:
            enabled: True to disable startup tab cycling; False to keep warmup
                cycling.
        Outputs:
            None.
        Side Effects:
            Updates the Tk variable, writes
            `settings["dev_disable_startup_tab_cycling"]`, persists settings to
            disk, and emits a debug log message.
        Exceptions:
            Persistence and widget updates are guarded so toggle changes do not
            interrupt runtime interactions.
        """
        normalized_enabled = bool(enabled)
        settings["dev_disable_startup_tab_cycling"] = normalized_enabled
        toggle_var = getattr(self, "_dev_disable_startup_tab_cycling_var", None)
        if toggle_var is not None:
            try:
                toggle_var.set(normalized_enabled)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        try:
            _save_settings_to_disk()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        self._dbg(
            "ui.events",
            "Startup tab cycling preference updated: disabled=%s",
            normalized_enabled,
            once_key=None,
        )

    def _set_debug_enabled(self, enabled: bool) -> None:
        """Apply the global debug enable toggle.

        Purpose:
            Update global debug state from the Developer Tools menu.
        Why:
            Centralizes gating for all debug logging and perf instrumentation.
        Args:
            enabled: True to enable debug logging; False to disable it.
        Returns:
            None.
        Side Effects:
            Updates settings, logging configuration, and cached debug state.
        Exceptions:
            Best-effort guards prevent UI failures on invalid state.
        """
        self._debug_enabled = bool(enabled)
        if self._debug_enabled_var is not None:
            try:
                self._debug_enabled_var.set(self._debug_enabled)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        self._configure_debug_logging()
        self._persist_debug_settings()

    def _set_debug_file_logging_enabled(self, enabled: bool) -> None:
        """Apply the debug file logging toggle.

        Purpose:
            Enable or disable the rotating file handler for debug logs.
        Why:
            Lets developers capture debug output without console spam.
        Args:
            enabled: True to enable file logging; False to disable it.
        Returns:
            None.
        Side Effects:
            Updates settings and reconfigures logging handlers.
        Exceptions:
            Best-effort guards prevent UI failures on invalid state.
        """
        self._debug_file_logging_enabled = bool(enabled)
        if self._debug_file_logging_var is not None:
            try:
                self._debug_file_logging_var.set(self._debug_file_logging_enabled)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        self._configure_debug_logging()
        self._persist_debug_settings()

    def _set_debug_category_enabled(self, category: str, enabled: bool) -> None:
        """Apply a per-category debug toggle.

        Purpose:
            Update a single debug category based on the menu toggle state.
        Why:
            Allows selective debug output without enabling all categories.
        Args:
            category: Category key to update.
            enabled: True to enable the category; False to disable it.
        Returns:
            None.
        Side Effects:
            Updates settings and in-memory category state.
        Exceptions:
            Best-effort guards prevent UI failures on invalid input.
        """
        if category not in DEBUG_CATEGORIES:
            return
        self._debug_categories[category] = bool(enabled)
        var = self._debug_category_vars.get(category)
        if var is not None:
            try:
                var.set(bool(enabled))
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        self._persist_debug_settings()

    def _is_debug_category_enabled(self, category: str) -> bool:
        """Return whether a debug category is active.

        Purpose:
            Provide a cheap gate before emitting debug output.
        Why:
            Ensures debug logging is disabled by default and cheap when off.
        Args:
            category: Category key to evaluate.
        Returns:
            True when global debug and the category are enabled.
        Side Effects:
            None.
        Exceptions:
            None.
        """
        if not self._debug_enabled:
            return False
        return bool(self._debug_categories.get(category, False))

    def _log(
        self,
        category: str,
        level: int,
        msg: str,
        *args: Any,
        once_key: Optional[str] = None,
    ) -> None:
        """Emit a structured log message for a debug category.

        Purpose:
            Route debug output through the centralized logging backend.
        Why:
            Keeps debug output consistent and lazy-formatted across the app.
        Args:
            category: Category key that gates the log output.
            level: Logging level (e.g., logging.DEBUG).
            msg: Log message template using %-style placeholders.
            *args: Arguments for lazy formatting.
            once_key: Optional token for one-shot logging suppression.
        Returns:
            None.
        Side Effects:
            Writes to the configured logger when enabled.
        Exceptions:
            Best-effort guards suppress logging failures.
        """
        if not self._is_debug_category_enabled(category):
            return
        if once_key:
            token = (category, once_key)
            if token in self._debug_once:
                return
            self._debug_once.add(token)
        try:
            _GL260_LOGGER.log(level, "[%s] " + msg, category, *args)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _dbg(
        self, category: str, msg: str, *args: Any, once_key: Optional[str] = None
    ) -> None:
        """Emit a debug-level log for a category.

        Purpose:
            Provide a convenience wrapper for debug logging.
        Why:
            Keeps call sites concise while enforcing gating rules.
        Args:
            category: Category key that gates the log output.
            msg: Log message template using %-style placeholders.
            *args: Arguments for lazy formatting.
            once_key: Optional token for one-shot logging suppression.
        Returns:
            None.
        Side Effects:
            Writes to the configured logger when enabled.
        Exceptions:
            Best-effort guards suppress logging failures.
        """
        self._log(category, logging.DEBUG, msg, *args, once_key=once_key)

    def _dbg_exc(
        self, category: str, msg: str, exc: Optional[BaseException] = None
    ) -> None:
        """Emit a debug-level exception log for a category.

        Purpose:
            Capture exceptions with context when debug logging is enabled.
        Why:
            Helps diagnose failures without interrupting workflows.
        Args:
            category: Category key that gates the log output.
            msg: Message describing the exception context.
            exc: Optional exception to include; uses current traceback if None.
        Returns:
            None.
        Side Effects:
            Writes to the configured logger when enabled.
        Exceptions:
            Best-effort guards suppress logging failures.
        """
        if not self._is_debug_category_enabled(category):
            return
        try:
            if exc is not None:
                _GL260_LOGGER.exception("[%s] %s: %s", category, msg, exc)
            else:
                _GL260_LOGGER.exception("[%s] %s", category, msg)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _perf_record(self, category: str, label: str, value: float) -> None:
        """Record a performance metric sample.

        Purpose:
            Aggregate timing or counter values for later inspection.
        Why:
            Provides cheap profiling while avoiding per-event log spam.
        Args:
            category: Category key used for gating and grouping.
            label: Human-readable metric label.
            value: Sample value (seconds for timers, count for counters).
        Returns:
            None.
        Side Effects:
            Updates in-memory performance stats.
        Exceptions:
            Best-effort guards suppress aggregation failures.
        """
        if not self._debug_enabled:
            return
        if not (
            self._debug_categories.get("perf.timing", False)
            or self._debug_categories.get(category, False)
        ):
            return
        try:
            with self._perf_stats_lock:
                key = (category, label)
                stats = self._perf_stats.get(key)
                if stats is None:
                    stats = {"count": 0, "total": 0.0, "min": value, "max": value}
                    self._perf_stats[key] = stats
                stats["count"] = int(stats.get("count", 0)) + 1
                stats["total"] = float(stats.get("total", 0.0)) + float(value)
                stats["min"] = (
                    float(value)
                    if stats.get("min") is None
                    else min(float(stats["min"]), float(value))
                )
                stats["max"] = (
                    float(value)
                    if stats.get("max") is None
                    else max(float(stats["max"]), float(value))
                )
                stats["last"] = float(value)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _perf_count(self, category: str, label: str, delta: float = 1.0) -> None:
        """Record a counter increment for performance stats.

        Purpose:
            Aggregate hit/miss or event counters without logging each event.
        Why:
            Keeps cache and workflow stats cheap when enabled.
        Args:
            category: Category key used for gating and grouping.
            label: Human-readable metric label.
            delta: Amount to add to the counter.
        Returns:
            None.
        Side Effects:
            Updates in-memory performance stats.
        Exceptions:
            Best-effort guards suppress aggregation failures.
        """
        self._perf_record(category, label, float(delta))

    def _perf_time(
        self, category: str, label: str, once_key: Optional[str] = None
    ) -> Any:
        """Return a context manager that records elapsed time.

        Purpose:
            Time a code block when performance instrumentation is enabled.
        Why:
            Provides cheap timing without overhead when disabled.
        Args:
            category: Category key used for gating and grouping.
            label: Human-readable metric label.
            once_key: Optional token for one-shot timing suppression.
        Returns:
            A context manager that records elapsed time when enabled.
        Side Effects:
            Updates in-memory performance stats when enabled.
        Exceptions:
            Best-effort guards suppress timing failures.
        """
        if not self._debug_enabled:
            return self._perf_noop
        if not (
            self._debug_categories.get("perf.timing", False)
            or self._debug_categories.get(category, False)
        ):
            return self._perf_noop
        if once_key:
            token = (category, once_key)
            if token in self._debug_once:
                return self._perf_noop
            self._debug_once.add(token)

        class _PerfTimer:
            def __init__(self, app: "UnifiedApp", cat: str, lab: str) -> None:
                """Initialize the timer context.

                Purpose:
                    Store the timer context parameters for later recording.
                Why:
                    Keeps the timing logic encapsulated for perf tracking.
                Args:
                    app: UnifiedApp instance that receives the perf record.
                    cat: Category key for the perf stats.
                    lab: Label for the perf stats entry.
                Returns:
                    None.
                Side Effects:
                    Stores references to app and timing metadata.
                Exceptions:
                    None.
                """
                self._app = app
                self._cat = cat
                self._lab = lab
                self._start = None

            def __enter__(self):
                """Start timing the context block.

                Purpose:
                    Capture the start timestamp for elapsed time measurement.
                Why:
                    Allows consistent timing with minimal caller overhead.
                Args:
                    None.
                Returns:
                    Self, enabling 'as' usage in context managers.
                Side Effects:
                    Records the start time.
                Exceptions:
                    None.
                """
                self._start = time.perf_counter()
                return self

            def __exit__(self, exc_type, exc, tb):
                """Stop timing and record the elapsed duration.

                Purpose:
                    Finalize the timing and store the sample in perf stats.
                Why:
                    Ensures timers are aggregated without leaking exceptions.
                Args:
                    exc_type: Exception type if raised in the context block.
                    exc: Exception instance if raised in the context block.
                    tb: Traceback if raised in the context block.
                Returns:
                    False to propagate exceptions from the context block.
                Side Effects:
                    Updates performance stats with the elapsed duration.
                Exceptions:
                    None.
                """
                if self._start is None:
                    return False
                elapsed = time.perf_counter() - self._start
                self._app._perf_record(self._cat, self._lab, elapsed)
                return False

        return _PerfTimer(self, category, label)

    def _format_performance_stats(self) -> str:
        """Format aggregated performance stats for display.

        Purpose:
            Render the current performance counters/timers as readable text.
        Why:
            Supports the Developer Tools "Dump Performance Stats" action.
        Args:
            None.
        Returns:
            Multi-line string of formatted performance stats.
        Side Effects:
            None.
        Exceptions:
            Best-effort guards suppress formatting failures.
        """
        try:
            with self._perf_stats_lock:
                items = list(self._perf_stats.items())
        except Exception:
            items = []
        if not items:
            return "No performance stats captured."
        lines = []
        # Iterate over sorted items to apply the per-item logic.
        for (category, label), stats in sorted(items, key=lambda item: item[0]):
            count = int(stats.get("count", 0))
            total = float(stats.get("total", 0.0))
            min_val = stats.get("min")
            max_val = stats.get("max")
            last_val = stats.get("last")
            lines.append(
                f"{category} | {label}: "
                f"count={count} total={total:.6f} "
                f"min={min_val:.6f} max={max_val:.6f} last={last_val:.6f}"
            )
        return "\n".join(lines)

    def _dump_performance_stats(self) -> None:
        """Dump performance stats to the debug logger and UI.

        Purpose:
            Provide a quick snapshot of aggregated perf counters/timers.
        Why:
            Supports the Developer Tools action for performance inspection.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Logs to the debug logger and shows a messagebox summary.
        Exceptions:
            Best-effort guards suppress UI failures.
        """
        body = self._format_performance_stats()
        self._dbg("perf.timing", "Performance stats dump:\n%s", body, once_key=None)
        try:
            messagebox.showinfo("Performance Stats", body)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _dump_debug_settings(self) -> None:
        """Dump debug settings to the debug logger and UI.

        Purpose:
            Show the current debug enable state and category toggles.
        Why:
            Helps developers confirm which categories are active.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Logs to the debug logger and shows a messagebox summary.
        Exceptions:
            Best-effort guards suppress UI failures.
        """
        categories = [
            f"{name}={bool(self._debug_categories.get(name, False))}"
            for name in DEBUG_CATEGORIES
        ]
        lines = [
            f"debug_enabled={bool(self._debug_enabled)}",
            f"debug_file_logging_enabled={bool(self._debug_file_logging_enabled)}",
            "categories: " + ", ".join(categories),
        ]
        body = "\n".join(lines)
        self._dbg("ui.events", "Debug settings dump:\n%s", body, once_key=None)
        try:
            messagebox.showinfo("Debug Settings", body)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _clear_debug_once_guards(self) -> None:
        """Clear one-shot debug suppression tokens.

        Purpose:
            Reset the once-only debug guard cache for renewed logging.
        Why:
            Allows repeated debug output after it was suppressed once.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Clears the in-memory once-key cache.
        Exceptions:
            Best-effort guards suppress UI failures.
        """
        try:
            self._debug_once.clear()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        self._dbg("ui.events", "Debug once-guards cleared.")

    def _apply_combined_svg_export_controls(self) -> None:
        """Apply Developer Tools combined SVG export reduction controls.

        Purpose:
            Persist normalized SVG reduction mode, decimation budget, and raster
            DPI values from Developer Tools widgets.
        Why:
            Combined triple-axis SVG exports can become very large when all
            source samples and per-point markers remain vector geometry; these
            controls let users choose the reduction strategy explicitly.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Updates Tk variables, mutates `settings`, schedules settings
            persistence, and logs one debug message.
        Exceptions:
            Invalid widget values are sanitized to defaults or bounds.
        """
        raw_values = {
            COMBINED_SVG_REDUCTION_MODE_SETTINGS_KEY: (
                self._combined_svg_reduction_mode_var.get()
            ),
            COMBINED_SVG_MAX_POINTS_SETTINGS_KEY: (
                self._combined_svg_max_points_var.get()
            ),
            COMBINED_SVG_RASTER_DPI_SETTINGS_KEY: (
                self._combined_svg_raster_dpi_var.get()
            ),
        }
        normalized = _normalize_combined_svg_export_settings(raw_values)
        settings.update(normalized)
        self._combined_svg_reduction_mode_var.set(
            str(
                normalized.get(
                    COMBINED_SVG_REDUCTION_MODE_SETTINGS_KEY,
                    DEFAULT_COMBINED_SVG_REDUCTION_MODE,
                )
            )
        )
        self._combined_svg_max_points_var.set(
            int(
                normalized.get(
                    COMBINED_SVG_MAX_POINTS_SETTINGS_KEY,
                    DEFAULT_COMBINED_SVG_MAX_POINTS,
                )
            )
        )
        self._combined_svg_raster_dpi_var.set(
            int(
                normalized.get(
                    COMBINED_SVG_RASTER_DPI_SETTINGS_KEY,
                    DEFAULT_COMBINED_SVG_RASTER_DPI,
                )
            )
        )
        self._schedule_save_settings()
        mode_value = normalized[COMBINED_SVG_REDUCTION_MODE_SETTINGS_KEY]
        points_value = normalized[COMBINED_SVG_MAX_POINTS_SETTINGS_KEY]
        dpi_value = normalized[COMBINED_SVG_RASTER_DPI_SETTINGS_KEY]
        self._log_plot_tab_debug(
            "Combined SVG export settings applied: "
            f"mode={mode_value} max_points={points_value} raster_dpi={dpi_value}."
        )

    def _reset_combined_svg_export_defaults(self) -> None:
        """Reset combined SVG export reduction controls to default values.

        Purpose:
            Restore full-fidelity SVG export behavior from Developer Tools.
        Why:
            SVG size reduction modes are intentionally experimental/export-only,
            so developers need a single rollback action.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Updates SVG export control Tk variables and persists defaults.
        Exceptions:
            Persistence failures are handled by the shared apply helper.
        """
        self._combined_svg_reduction_mode_var.set(DEFAULT_COMBINED_SVG_REDUCTION_MODE)
        self._combined_svg_max_points_var.set(DEFAULT_COMBINED_SVG_MAX_POINTS)
        self._combined_svg_raster_dpi_var.set(DEFAULT_COMBINED_SVG_RASTER_DPI)
        self._apply_combined_svg_export_controls()

    def _combined_svg_decimation_indices(
        self,
        x_values: Any,
        y_values: Any,
        max_points: int,
        preserve_x_values: Any = None,
    ) -> np.ndarray | None:
        """Return decimation indices for one combined SVG export trace.

        Purpose:
            Select a bounded set of vector points while retaining endpoints,
            non-finite gap boundaries, global trace extrema, and cycle-marker
            anchors.
        Why:
            SVG file size scales with point/marker count; decimation should be
            deterministic and preserve visible discontinuities, global data
            maxima/minima, and cycle-marker attachment points.
        Inputs:
            x_values: Source X data sequence for one artist.
            y_values: Source Y data sequence aligned with `x_values`.
            max_points: Target maximum number of points to keep.
            preserve_x_values: Optional X coordinates whose nearest source points
                must remain in the reduced trace, such as cycle peak/trough
                marker anchors.
        Outputs:
            Numpy integer index array, or None when no decimation is needed.
        Side Effects:
            May call the optional Rust helper; no rebuild is required and Python
            fallback handles unavailable Rust paths.
        Exceptions:
            Malformed inputs return None without mutating the artist.
        """
        try:
            x_array = np.asarray(x_values).reshape(-1)
            y_array = np.asarray(y_values).reshape(-1)
        except Exception:
            return None
        if x_array.size <= max_points or x_array.size != y_array.size:
            return None
        safe_max = max(MIN_COMBINED_SVG_MAX_POINTS, int(max_points))
        step = int(math.ceil(float(x_array.size) / float(safe_max)))
        if step <= 1:
            return None
        required_idx: np.ndarray | None = None
        try:
            x_float = np.asarray(x_array, dtype=float)
            y_float = np.asarray(y_array, dtype=float)
            nonfinite_mask = ~np.isfinite(x_float) | ~np.isfinite(y_float)
            if nonfinite_mask.any():
                nonfinite_idx = np.flatnonzero(nonfinite_mask)
                neighbor_idx = np.unique(
                    np.concatenate(
                        [nonfinite_idx, nonfinite_idx - 1, nonfinite_idx + 1]
                    )
                )
                required_idx = neighbor_idx[
                    (neighbor_idx >= 0) & (neighbor_idx < x_array.size)
                ]
            finite_idx = np.flatnonzero(~nonfinite_mask)
            if finite_idx.size:
                # Keep the original extrema vertices so SVG reduction cannot
                # shift a trace's displayed minimum or maximum.
                finite_y = y_float[finite_idx]
                extrema_idx = finite_idx[
                    [int(np.argmin(finite_y)), int(np.argmax(finite_y))]
                ]
                required_idx = (
                    extrema_idx
                    if required_idx is None
                    else np.unique(np.concatenate([required_idx, extrema_idx]))
                )
        except Exception:
            required_idx = None
        if preserve_x_values is not None:
            try:
                x_float = np.asarray(x_array, dtype=float)
                anchor_x = np.asarray(preserve_x_values, dtype=float).reshape(-1)
                finite_x = np.isfinite(x_float)
                finite_anchor_x = anchor_x[np.isfinite(anchor_x)]
                if finite_x.any() and finite_anchor_x.size:
                    # Retain original vertices at cycle marker X values so SVG
                    # decimation cannot visually detach markers from the trace.
                    finite_indices = np.flatnonzero(finite_x)
                    preserved = [
                        int(
                            finite_indices[
                                int(np.argmin(np.abs(x_float[finite_indices] - anchor)))
                            ]
                        )
                        for anchor in np.unique(finite_anchor_x)
                    ]
                    if preserved:
                        marker_idx = np.asarray(preserved, dtype=int)
                        required_idx = (
                            marker_idx
                            if required_idx is None
                            else np.unique(np.concatenate([required_idx, marker_idx]))
                        )
            except Exception:
                # Malformed marker offsets must not prevent normal SVG export.
                pass
        rust_idx = _rust_combined_decimation_indices(
            data_len=int(x_array.size),
            step=int(step),
            required_indices=required_idx.tolist()
            if required_idx is not None and required_idx.size
            else None,
        )
        if rust_idx is not None:
            return rust_idx
        base_idx = np.arange(0, x_array.size, step, dtype=int)
        if base_idx.size == 0 or int(base_idx[-1]) != int(x_array.size - 1):
            base_idx = np.concatenate([base_idx, np.asarray([x_array.size - 1])])
        if required_idx is not None and required_idx.size:
            base_idx = np.unique(np.concatenate([base_idx, required_idx]))
        return np.asarray(sorted(set(int(idx) for idx in base_idx)), dtype=int)

    def _combined_svg_cycle_marker_x_values(self, fig: Figure | None) -> np.ndarray:
        """Return finite X coordinates used by combined cycle markers.

        Purpose:
            Read cycle peak/trough scatter offsets before SVG reduction.
        Why:
            The export decimator must retain the corresponding source vertices
            so reduced primary traces remain visually attached to their markers.
        Inputs:
            fig: Combined triple-axis export figure, or None.
        Outputs:
            One-dimensional float array of unique, finite marker X coordinates.
        Side Effects:
            None.
        Exceptions:
            Missing or malformed marker artists return an empty array.
        """
        if fig is None:
            return np.asarray([], dtype=float)
        marker_state = getattr(fig, "_gl260_cycle_marker_artists", None)
        if not isinstance(marker_state, Mapping):
            return np.asarray([], dtype=float)
        marker_x_values: list[np.ndarray] = []
        for marker_key in ("peak", "trough"):
            artist = marker_state.get(marker_key)
            offsets_getter = getattr(artist, "get_offsets", None)
            if not callable(offsets_getter):
                continue
            try:
                offsets = np.asarray(offsets_getter(), dtype=float)
                if offsets.ndim == 2 and offsets.shape[1] >= 2:
                    x_values = offsets[:, 0]
                    marker_x_values.append(x_values[np.isfinite(x_values)])
            except Exception:
                continue
        if not marker_x_values:
            return np.asarray([], dtype=float)
        return np.unique(np.concatenate(marker_x_values))

    def _iter_combined_svg_data_artists(self, fig: Figure | None) -> list[Any]:
        """Collect combined plot data artists eligible for SVG reduction.

        Purpose:
            Isolate heavy combined plot data artists from labels, legends, axes,
            and layout/editor helper artists.
        Why:
            SVG reduction must shrink data payloads without degrading vector text,
            tick labels, legends, or user-positioned layout elements.
        Inputs:
            fig: Combined triple-axis export figure.
        Outputs:
            List of Matplotlib artists that represent plotted data or cycle
            marker collections.
        Side Effects:
            None.
        Exceptions:
            Malformed figure/axes objects are skipped.
        """
        if fig is None:
            return []
        artists: list[Any] = []
        try:
            axes_list = list(fig.get_axes())
        except Exception:
            axes_list = []
        for axis in axes_list:
            if axis is None:
                continue
            for line in list(getattr(axis, "lines", []) or []):
                series_key = _normalize_trace_series_key(
                    getattr(line, "_gl260_series_key", ""), default=""
                )
                if series_key in SCATTER_SERIES_KEYS:
                    artists.append(line)
            for collection in list(getattr(axis, "collections", []) or []):
                series_key = _normalize_trace_series_key(
                    getattr(collection, "_gl260_series_key", ""), default=""
                )
                if series_key in SCATTER_SERIES_KEYS:
                    artists.append(collection)
                    continue
                offsets_getter = getattr(collection, "get_offsets", None)
                if not callable(offsets_getter):
                    continue
                try:
                    offsets = offsets_getter()
                    if offsets is not None and len(offsets) > 0:
                        artists.append(collection)
                except Exception:
                    continue
        return artists

    def _prepare_combined_svg_export_figure(
        self,
        fig: Figure | None,
    ) -> tuple[Figure | None, int]:
        """Apply selected combined SVG size-reduction policy before save.

        Purpose:
            Mutate a newly rebuilt combined export figure for SVG output only.
        Why:
            Combined SVG files can be dominated by per-point marker/vector data;
            applying the explicit Developer Tools policy keeps browser-loadable
            SVGs while preserving full-fidelity behavior by default.
        Inputs:
            fig: Combined export figure about to be saved as SVG.
        Outputs:
            Tuple of `(fig, dpi)` where `dpi` is the SVG save DPI to use when the
            selected policy needs rasterized data artists.
        Side Effects:
            Depending on mode, may remove markers from data lines, decimate line
            or scatter data arrays, or mark data artists rasterized.
        Exceptions:
            Artist-specific failures are skipped so SVG export can continue.
        """
        normalized = _normalize_combined_svg_export_settings(settings)
        settings.update(normalized)
        mode = str(
            normalized.get(
                COMBINED_SVG_REDUCTION_MODE_SETTINGS_KEY,
                DEFAULT_COMBINED_SVG_REDUCTION_MODE,
            )
        )
        max_points = int(
            normalized.get(
                COMBINED_SVG_MAX_POINTS_SETTINGS_KEY,
                DEFAULT_COMBINED_SVG_MAX_POINTS,
            )
        )
        raster_dpi = int(
            normalized.get(
                COMBINED_SVG_RASTER_DPI_SETTINGS_KEY,
                DEFAULT_COMBINED_SVG_RASTER_DPI,
            )
        )
        if fig is None or mode == COMBINED_SVG_REDUCTION_FULL:
            return fig, raster_dpi
        cycle_marker_x_values = self._combined_svg_cycle_marker_x_values(fig)
        for artist in self._iter_combined_svg_data_artists(fig):
            try:
                if mode == COMBINED_SVG_REDUCTION_RASTERIZE:
                    rasterized_setter = getattr(artist, "set_rasterized", None)
                    if callable(rasterized_setter):
                        rasterized_setter(True)
                    continue
                if isinstance(artist, Line2D):
                    if mode == COMBINED_SVG_REDUCTION_NO_MARKERS:
                        artist.set_marker("None")
                        continue
                    if mode == COMBINED_SVG_REDUCTION_DECIMATE:
                        axis = getattr(artist, "axes", None)
                        preserve_x_values = (
                            cycle_marker_x_values
                            if getattr(axis, "_gl260_axis_role", None) == "primary"
                            else None
                        )
                        idx = self._combined_svg_decimation_indices(
                            artist.get_xdata(orig=False),
                            artist.get_ydata(orig=False),
                            max_points,
                            preserve_x_values=preserve_x_values,
                        )
                        if idx is not None:
                            x_array = np.asarray(artist.get_xdata(orig=False)).reshape(
                                -1
                            )
                            y_array = np.asarray(artist.get_ydata(orig=False)).reshape(
                                -1
                            )
                            if x_array.size == y_array.size and idx.size:
                                artist.set_data(x_array[idx], y_array[idx])
                        continue
                offsets_getter = getattr(artist, "get_offsets", None)
                offsets_setter = getattr(artist, "set_offsets", None)
                if (
                    mode == COMBINED_SVG_REDUCTION_DECIMATE
                    and callable(offsets_getter)
                    and callable(offsets_setter)
                ):
                    offsets = np.asarray(offsets_getter())
                    if offsets.ndim == 2 and offsets.shape[0] > max_points:
                        axis = getattr(artist, "axes", None)
                        preserve_x_values = (
                            cycle_marker_x_values
                            if getattr(axis, "_gl260_axis_role", None) == "primary"
                            else None
                        )
                        idx = self._combined_svg_decimation_indices(
                            offsets[:, 0],
                            offsets[:, 1],
                            max_points,
                            preserve_x_values=preserve_x_values,
                        )
                        if idx is not None and idx.size:
                            offsets_setter(offsets[idx])
            except Exception:
                continue
        return fig, raster_dpi

    def _apply_layout_health_controls(self) -> None:
        """Apply Developer Tools layout-health control values to persisted settings.

        Purpose:
            Normalize and persist runtime layout-health policy toggles/thresholds.
        Why:
            The layout-health auto-fix engine must be explicitly controllable and
            stable across restarts from one Developer Tools surface.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Updates layout-health keys in `settings`, normalizes Tk variables to
            clamped values, and schedules settings persistence.
        Exceptions:
            Invalid widget values are sanitized to defaults.
        """
        raw_values = {
            "layout_health_autofix_enabled": bool(
                self._layout_health_autofix_enabled_var.get()
            ),
            "layout_health_strict_mode": bool(self._layout_health_strict_mode_var.get()),
            "layout_health_emit_debug_events": bool(
                self._layout_health_emit_debug_events_var.get()
            ),
            "layout_health_max_passes": self._layout_health_max_passes_var.get(),
            "layout_health_min_gap_pts": self._layout_health_min_gap_pts_var.get(),
            "layout_health_max_gap_pts": self._layout_health_max_gap_pts_var.get(),
            "layout_health_check_x_axis_conflicts": bool(
                self._layout_health_check_x_axis_conflicts_var.get()
            ),
            "layout_health_min_axis_label_tick_gap_pts": (
                self._layout_health_min_axis_label_tick_gap_pts_var.get()
            ),
            "layout_health_max_axis_label_tick_gap_pts": (
                self._layout_health_max_axis_label_tick_gap_pts_var.get()
            ),
            "layout_health_max_bottom_whitespace_pts": (
                self._layout_health_max_bottom_whitespace_pts_var.get()
            ),
        }
        normalized = _normalize_layout_health_settings(raw_values)
        settings.update(normalized)
        self._layout_health_autofix_enabled_var.set(
            bool(normalized.get("layout_health_autofix_enabled", True))
        )
        self._layout_health_strict_mode_var.set(
            bool(normalized.get("layout_health_strict_mode", False))
        )
        self._layout_health_emit_debug_events_var.set(
            bool(normalized.get("layout_health_emit_debug_events", False))
        )
        self._layout_health_max_passes_var.set(
            int(normalized.get("layout_health_max_passes", DEFAULT_LAYOUT_HEALTH_MAX_PASSES))
        )
        self._layout_health_min_gap_pts_var.set(
            float(
                normalized.get("layout_health_min_gap_pts", DEFAULT_LAYOUT_HEALTH_MIN_GAP_PTS)
            )
        )
        self._layout_health_max_gap_pts_var.set(
            float(
                normalized.get("layout_health_max_gap_pts", DEFAULT_LAYOUT_HEALTH_MAX_GAP_PTS)
            )
        )
        self._layout_health_check_x_axis_conflicts_var.set(
            bool(
                normalized.get(
                    "layout_health_check_x_axis_conflicts",
                    DEFAULT_LAYOUT_HEALTH_CHECK_X_AXIS_CONFLICTS,
                )
            )
        )
        self._layout_health_min_axis_label_tick_gap_pts_var.set(
            float(
                normalized.get(
                    "layout_health_min_axis_label_tick_gap_pts",
                    DEFAULT_LAYOUT_HEALTH_MIN_AXIS_LABEL_TICK_GAP_PTS,
                )
            )
        )
        self._layout_health_max_axis_label_tick_gap_pts_var.set(
            float(
                normalized.get(
                    "layout_health_max_axis_label_tick_gap_pts",
                    DEFAULT_LAYOUT_HEALTH_MAX_AXIS_LABEL_TICK_GAP_PTS,
                )
            )
        )
        self._layout_health_max_bottom_whitespace_pts_var.set(
            float(
                normalized.get(
                    "layout_health_max_bottom_whitespace_pts",
                    DEFAULT_LAYOUT_HEALTH_MAX_BOTTOM_WHITESPACE_PTS,
                )
            )
        )
        self._schedule_save_settings()

    def _reset_layout_health_defaults(self) -> None:
        """Reset layout-health Developer Tools controls to application defaults.

        Purpose:
            Restore canonical layout-health defaults after experimental tuning.
        Why:
            Developers need one-click rollback when testing strict/aggressive
            policies across different plot configurations.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Updates runtime variables, persists defaults, and emits one info dialog.
        Exceptions:
            Messagebox failures are ignored.
        """
        self._layout_health_autofix_enabled_var.set(DEFAULT_LAYOUT_HEALTH_AUTOFIX_ENABLED)
        self._layout_health_strict_mode_var.set(DEFAULT_LAYOUT_HEALTH_STRICT_MODE)
        self._layout_health_emit_debug_events_var.set(
            DEFAULT_LAYOUT_HEALTH_EMIT_DEBUG_EVENTS
        )
        self._layout_health_max_passes_var.set(DEFAULT_LAYOUT_HEALTH_MAX_PASSES)
        self._layout_health_min_gap_pts_var.set(DEFAULT_LAYOUT_HEALTH_MIN_GAP_PTS)
        self._layout_health_max_gap_pts_var.set(DEFAULT_LAYOUT_HEALTH_MAX_GAP_PTS)
        self._layout_health_check_x_axis_conflicts_var.set(
            DEFAULT_LAYOUT_HEALTH_CHECK_X_AXIS_CONFLICTS
        )
        self._layout_health_min_axis_label_tick_gap_pts_var.set(
            DEFAULT_LAYOUT_HEALTH_MIN_AXIS_LABEL_TICK_GAP_PTS
        )
        self._layout_health_max_axis_label_tick_gap_pts_var.set(
            DEFAULT_LAYOUT_HEALTH_MAX_AXIS_LABEL_TICK_GAP_PTS
        )
        self._layout_health_max_bottom_whitespace_pts_var.set(
            DEFAULT_LAYOUT_HEALTH_MAX_BOTTOM_WHITESPACE_PTS
        )
        self._apply_layout_health_controls()
        try:
            messagebox.showinfo(
                "Layout Health",
                "Layout-health defaults restored.",
                parent=getattr(self, "_developer_tools_dialog", None) or self,
            )
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _collect_active_figures_for_layout_health(self) -> List[Tuple[str, Figure]]:
        """Collect active figures targeted by the manual layout-health quick action.

        Purpose:
            Resolve which figure(s) should run an immediate layout-health check.
        Why:
            Developer quick actions should target the currently viewed plot context
            (active plot tab, Compare panes, or the embedded Advanced Speciation
            Analysis timeline) without requiring extra selection UI.
        Inputs:
            None.
        Outputs:
            List of `(plot_id, figure)` tuples to check.
        Side Effects:
            None.
        Exceptions:
            Widget/selection inspection failures fall back to an empty list.
        """
        figures: List[Tuple[str, Figure]] = []
        selected_tab_id = ""
        try:
            selected_tab_id = str(self.nb.select())
        except Exception:
            selected_tab_id = ""

        compare_tab = getattr(self, "tab_compare", None)
        if compare_tab is not None and selected_tab_id == str(compare_tab):
            panels = getattr(self, "_compare_panels", {})
            if isinstance(panels, Mapping):
                for side_key in ("A", "B"):
                    panel = panels.get(side_key) or {}
                    fig_obj = panel.get("figure")
                    if isinstance(fig_obj, Figure):
                        figures.append((f"fig_compare_{side_key.lower()}", fig_obj))
            return figures

        advanced_tab = getattr(self, "tab_solubility_new", None)
        if advanced_tab is not None and selected_tab_id == str(advanced_tab):
            timeline_fig = getattr(self, "_sol_cycle_spec_fig", None)
            if isinstance(timeline_fig, Figure):
                figures.append(("fig_cycle_timeline", timeline_fig))

        tabs = list(getattr(self, "_plot_tabs", []) or [])
        canvases = list(getattr(self, "_canvases", []) or [])
        for idx, tab in enumerate(tabs):
            if str(tab) != selected_tab_id:
                continue
            canvas = canvases[idx] if idx < len(canvases) else None
            fig_obj = getattr(canvas, "figure", None)
            if not isinstance(fig_obj, Figure):
                continue
            plot_id = str(
                getattr(tab, "_plot_id", None)
                or getattr(fig_obj, "_gl260_plot_id", None)
                or "active_plot"
            ).strip()
            figures.append((plot_id, fig_obj))
            break
        return figures

    def _run_layout_health_check_on_active_figure(self) -> None:
        """Run the layout-health auto-fix pass immediately on active figure(s).

        Purpose:
            Provide one manual verification/correction quick action in Developer Tools.
        Why:
            Developers need direct validation after tuning policy values without
            waiting for another full render cycle.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Runs `layout_health_autofix` on active figures, triggers redraws, and
            displays a brief summary dialog.
        Exceptions:
            Auto-fix failures are captured per figure and reported safely.
        """
        targets = self._collect_active_figures_for_layout_health()
        if not targets:
            try:
                messagebox.showinfo(
                    "Layout Health",
                    "No active figure is available for layout-health checks.",
                    parent=getattr(self, "_developer_tools_dialog", None) or self,
                )
            except Exception:
                pass
            return

        applied_count = 0
        lines: List[str] = []
        for plot_id, fig_obj in targets:
            mode_value = str(getattr(fig_obj, "_gl260_layout_mode", "display") or "display")
            try:
                result = layout_health_autofix(fig_obj, plot_id, mode_value, settings)
            except Exception as exc:
                lines.append(f"{plot_id}: failed ({type(exc).__name__})")
                continue
            if bool(result.get("applied", False)):
                applied_count += 1
            lines.append(
                f"{plot_id}: passes={int(result.get('passes', 0))} "
                f"applied={'yes' if bool(result.get('applied', False)) else 'no'} "
                f"issues={','.join(list(result.get('issues', []) or [])) or 'none'}"
            )
            try:
                fig_obj.canvas.draw_idle()
            except Exception:
                pass
        summary = "\n".join(lines)
        title = "Layout Health Check"
        body = (
            f"Checked {len(targets)} figure(s). Auto-fix applied to {applied_count}.\n\n{summary}"
        )
        try:
            messagebox.showinfo(
                title,
                body,
                parent=getattr(self, "_developer_tools_dialog", None) or self,
            )
        except Exception:
            pass

    def _resolve_layout_health_wizard_targets(
        self,
        *,
        plot_id: Optional[str] = None,
        fig: Optional[Figure] = None,
        canvas: Optional[Any] = None,
        parent: Optional[tk.Widget] = None,
    ) -> List[Dict[str, Any]]:
        """Resolve figure targets for the Layout Health Wizard.

        Purpose:
            Build a normalized target list from an explicit plot/preview context
            or from the currently selected plot tab.
        Why:
            The wizard is opened from Developer Tools, generated plot tabs, and
            preview windows; each entry point should feed the same check/apply
            pipeline without duplicating target-selection behavior.
        Inputs:
            plot_id: Optional plot identifier supplied by a button callback.
            fig: Optional explicit Matplotlib figure supplied by preview buttons.
            canvas: Optional canvas owning the figure for redraw callbacks.
            parent: Optional Tk parent used for modal ownership.
        Outputs:
            List of dictionaries containing `plot_id`, `fig`, `canvas`, and
            `parent` keys plus the resolved layout `mode`.
        Side Effects:
            None.
        Exceptions:
            Invalid explicit targets fall back to active-figure discovery.
        """
        targets: List[Dict[str, Any]] = []
        if isinstance(fig, Figure):
            resolved_plot_id = str(
                plot_id or getattr(fig, "_gl260_plot_id", None) or "active_plot"
            ).strip()
            if not resolved_plot_id:
                resolved_plot_id = "active_plot"
            mode_value = str(
                getattr(fig, "_gl260_layout_mode", None) or "display"
            ).strip().lower()
            if mode_value not in {"display", "export"}:
                mode_value = "display"
            resolved_canvas = (
                canvas if canvas is not None else getattr(fig, "canvas", None)
            )
            targets.append(
                {
                    "plot_id": resolved_plot_id,
                    "fig": fig,
                    "canvas": resolved_canvas,
                    "parent": parent,
                    "mode": mode_value,
                }
            )
            return targets

        for (
            active_plot_id,
            active_fig,
        ) in self._collect_active_figures_for_layout_health():
            if not isinstance(active_fig, Figure):
                continue
            mode_value = str(
                getattr(active_fig, "_gl260_layout_mode", "display") or "display"
            ).strip().lower()
            if mode_value not in {"display", "export"}:
                mode_value = "display"
            targets.append(
                {
                    "plot_id": str(active_plot_id or "active_plot").strip()
                    or "active_plot",
                    "fig": active_fig,
                    "canvas": getattr(active_fig, "canvas", None),
                    "parent": parent,
                    "mode": mode_value,
                }
            )
        return targets

    def _layout_health_wizard_policy_from_values(
        self,
        values: Mapping[str, Any],
        *,
        combined: bool = False,
        timeline: bool = False,
    ) -> Dict[str, Any]:
        """Build a layout-health policy from wizard control values.

        Purpose:
            Convert transient wizard controls into the policy shape consumed by
            `layout_health_autofix`.
        Why:
            Preview and apply actions should run the same bounded settings
            normalization used by Developer Tools while enabling combined-axis
            checks when the target is a combined triple-axis plot and timeline
            legend/label checks when the target is the cycle timeline.
        Inputs:
            values: Mapping of raw wizard control values.
            combined: Whether to enable combined right-axis collision checks.
            timeline: Whether to enable cycle timeline legend/x-label guards.
        Outputs:
            Dict suitable for `layout_health_autofix`.
        Side Effects:
            None.
        Exceptions:
            Invalid numeric values are normalized by `_normalize_layout_health_settings`.
        """
        base_policy = dict(settings if isinstance(settings, Mapping) else {})
        base_policy.update(dict(values if isinstance(values, Mapping) else {}))
        normalized = _normalize_layout_health_settings(base_policy)
        base_policy.update(normalized)
        if combined:
            base_policy.update(
                {
                    "layout_health_autofix_enabled": True,
                    "layout_health_check_axis_label_conflicts": True,
                }
            )
        if timeline:
            try:
                timeline_policy = self._cycle_timeline_layout_manager_policy(
                    self._get_cycle_plot_prefs()
                )
            except Exception:
                timeline_policy = {}
            max_bottom_whitespace = (
                _safe_float(
                    base_policy.get("layout_health_max_timeline_bottom_whitespace_pts"),
                    None,
                )
                or _safe_float(
                    base_policy.get("layout_health_max_bottom_whitespace_pts"),
                    None,
                )
                or _safe_float(
                    timeline_policy.get("layout_manager_max_bottom_whitespace_pts"),
                    DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MAX_BOTTOM_WHITESPACE_PTS,
                )
                or DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MAX_BOTTOM_WHITESPACE_PTS
            )
            base_policy.update(
                {
                    "layout_health_autofix_enabled": True,
                    "layout_health_context": "timeline",
                    "layout_health_check_legend_conflicts": bool(
                        timeline_policy.get(
                            "layout_manager_check_legend_conflicts",
                            True,
                        )
                    ),
                    "layout_health_check_axis_label_conflicts": bool(
                        timeline_policy.get(
                            "layout_manager_check_axis_label_conflicts",
                            True,
                        )
                    ),
                    "layout_health_min_gap_pts": float(
                        _safe_float(
                            base_policy.get(
                                "layout_health_min_gap_pts",
                                timeline_policy.get(
                                    "layout_manager_min_legend_xlabel_gap_pts",
                                    DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MIN_LEGEND_XLABEL_GAP_PTS,
                                ),
                            ),
                            DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MIN_LEGEND_XLABEL_GAP_PTS,
                        )
                        or DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MIN_LEGEND_XLABEL_GAP_PTS
                    ),
                    "layout_health_max_gap_pts": float(
                        _safe_float(
                            base_policy.get(
                                "layout_health_max_gap_pts",
                                timeline_policy.get(
                                    "layout_manager_max_legend_xlabel_gap_pts",
                                    DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MAX_LEGEND_XLABEL_GAP_PTS,
                                ),
                            ),
                            DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MAX_LEGEND_XLABEL_GAP_PTS,
                        )
                        or DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MAX_LEGEND_XLABEL_GAP_PTS
                    ),
                    "layout_health_min_axis_label_tick_gap_pts": float(
                        _safe_float(
                            base_policy.get(
                                "layout_health_min_axis_label_tick_gap_pts",
                                timeline_policy.get(
                                    "layout_manager_min_axis_label_tick_gap_pts",
                                    DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MIN_AXIS_LABEL_TICK_GAP_PTS,
                                ),
                            ),
                            DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MIN_AXIS_LABEL_TICK_GAP_PTS,
                        )
                        or DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MIN_AXIS_LABEL_TICK_GAP_PTS
                    ),
                    "layout_health_max_axis_label_tick_gap_pts": float(
                        _safe_float(
                            base_policy.get(
                                "layout_health_max_axis_label_tick_gap_pts",
                                timeline_policy.get(
                                    "layout_manager_max_axis_label_tick_gap_pts",
                                    DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MAX_AXIS_LABEL_TICK_GAP_PTS,
                                ),
                            ),
                            DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MAX_AXIS_LABEL_TICK_GAP_PTS,
                        )
                        or DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MAX_AXIS_LABEL_TICK_GAP_PTS
                    ),
                    "layout_health_max_timeline_bottom_whitespace_pts": float(
                        max_bottom_whitespace
                    ),
                    "layout_health_max_bottom_whitespace_pts": float(
                        max_bottom_whitespace
                    ),
                }
            )
        return base_policy

    def _run_layout_health_wizard_check(
        self,
        targets: Sequence[Mapping[str, Any]],
        policy_values: Mapping[str, Any],
    ) -> Tuple[List[str], int, bool]:
        """Run layout-health checks for wizard targets and summarize results.

        Purpose:
            Execute the measured health pass used by the Layout Health Wizard.
        Why:
            The same summary should drive initial wizard display, Preview Tweaks,
            and post-apply feedback.
        Inputs:
            targets: Normalized target dictionaries from
                `_resolve_layout_health_wizard_targets`.
            policy_values: Raw or normalized layout-health policy values.
        Outputs:
            Tuple of `(summary_lines, applied_count, has_combined_target)`.
        Side Effects:
            May mutate figure layout via `layout_health_autofix` and schedules
            redraws on available canvases. Cycle timeline targets also run the
            timeline-specific post-verifier so the wizard honors generated-tab
            legend placement constraints.
        Exceptions:
            Per-target failures are captured into summary lines.
        """
        lines: List[str] = []
        applied_count = 0
        has_combined_target = False
        for target in targets:
            fig_obj = target.get("fig")
            if not isinstance(fig_obj, Figure):
                continue
            plot_id_value = str(target.get("plot_id") or "active_plot").strip()
            plot_id_norm = plot_id_value.lower()
            combined_target = plot_id_norm == "fig_combined_triple_axis"
            timeline_target = plot_id_norm == "fig_cycle_timeline"
            has_combined_target = has_combined_target or combined_target
            mode_value = (
                str(
                    target.get("mode")
                    or getattr(fig_obj, "_gl260_layout_mode", "display")
                    or "display"
                )
                .strip()
                .lower()
            )
            if mode_value not in {"display", "export"}:
                mode_value = "display"
            policy = self._layout_health_wizard_policy_from_values(
                policy_values,
                combined=combined_target,
                timeline=timeline_target,
            )
            try:
                layout_mgr = getattr(fig_obj, "_gl260_layout_manager", None)
                if timeline_target and layout_mgr is not None:
                    try:
                        layout_mgr.solve(
                            max_passes=int(policy.get("layout_health_max_passes", 1)),
                            allow_draw=False,
                        )
                    except Exception:
                        # Timeline wizard checks remain best-effort so a stale
                        # manager cannot block regular layout health reporting.
                        pass
                try:
                    result = layout_health_autofix(
                        fig_obj,
                        plot_id_value,
                        mode_value,
                        policy,
                    )
                except Exception as autofix_exc:
                    result = {
                        "applied": False,
                        "passes": 0,
                        "issues": [f"autofix_failed_{type(autofix_exc).__name__}"],
                        "elapsed_ms": None,
                    }
                if timeline_target and not bool(result.get("applied", False)):
                    verify_fn = getattr(
                        self, "_run_cycle_timeline_layout_manager_verification", None
                    )
                    if callable(verify_fn):
                        try:
                            verification = verify_fn(
                                fig_obj,
                                mode=mode_value,
                                prefs=self._get_cycle_plot_prefs(),
                                show_splash=False,
                            )
                        except Exception as verify_exc:
                            verification = {
                                "health_result": {
                                    "applied": False,
                                    "issues": [
                                        f"timeline_verify_failed_{type(verify_exc).__name__}"
                                    ],
                                    "passes": result.get("passes", 0),
                                }
                            }
                        verify_result = (
                            verification.get("health_result")
                            if isinstance(verification, Mapping)
                            else None
                        )
                        if isinstance(verify_result, Mapping):
                            merged_result = dict(result)
                            if bool(verify_result.get("applied", False)):
                                merged_result["applied"] = True
                            if bool(
                                verify_result.get("postverify_guard_applied", False)
                            ):
                                merged_result["postverify_guard_applied"] = True
                                merged_result["applied"] = True
                            if verify_result.get("issues"):
                                merged_result["issues"] = verify_result.get("issues")
                            if verify_result.get("passes") is not None:
                                merged_result["passes"] = verify_result.get("passes")
                            result = merged_result
                    try:
                        self._reposition_cycle_timeline_centered_bottom_legends(fig_obj)
                    except Exception:
                        # Best-effort guard; keep wizard checks tolerant.
                        pass
                    capture_multi = getattr(
                        self, "_capture_cycle_timeline_legend_locs_from_fig", None
                    )
                    if callable(capture_multi):
                        try:
                            capture_multi(fig_obj, source="layout_health_wizard")
                        except Exception:
                            # Best-effort guard; ignore capture failures.
                            pass
            except Exception as exc:
                lines.append(f"{plot_id_value}: failed ({type(exc).__name__})")
                continue
            if bool(result.get("applied", False)):
                applied_count += 1
            issues = ",".join(list(result.get("issues", []) or [])) or "none"
            elapsed = result.get("elapsed_ms")
            elapsed_text = "--" if elapsed is None else f"{float(elapsed):.1f} ms"
            suggestion_note = ""
            if combined_target:
                suggestions_payload = result.get("suggestions")
                mode_suggestion = (
                    (suggestions_payload or {}).get(mode_value)
                    if isinstance(suggestions_payload, Mapping)
                    else None
                )
                margins_payload = (
                    mode_suggestion.get("margins")
                    if isinstance(mode_suggestion, Mapping)
                    else None
                )
                if isinstance(margins_payload, Mapping) and "bottom" in margins_payload:
                    suggestion_note = (
                        " suggestion=move plot band down via bottom margin"
                    )
            lines.append(
                f"{plot_id_value} ({mode_value}): passes={int(result.get('passes', 0))} "
                f"auto-fix={'yes' if bool(result.get('applied', False)) else 'no'} "
                f"issues={issues} elapsed={elapsed_text}{suggestion_note}"
            )
            target_canvas = target.get("canvas") or getattr(fig_obj, "canvas", None)
            if timeline_target:
                register_tracking = getattr(
                    self, "_register_cycle_timeline_generated_tab_legend_tracking", None
                )
                if callable(register_tracking):
                    try:
                        register_tracking(fig_obj, canvas=target_canvas)
                    except Exception:
                        # Best-effort guard; legend tracking is auxiliary to the check.
                        pass
            try:
                target_canvas.draw_idle()
            except Exception:
                try:
                    fig_obj.canvas.draw_idle()
                except Exception:
                    pass
        return lines, applied_count, has_combined_target

    def _open_layout_health_wizard(
        self,
        *,
        plot_id: Optional[str] = None,
        fig: Optional[Figure] = None,
        canvas: Optional[Any] = None,
        parent: Optional[tk.Widget] = None,
        source: str = "",
    ) -> None:
        """Open the manual Layout Health Wizard for active or explicit figures.

        Purpose:
            Provide a user-facing review and tweak workflow around layout-health
            checks for generated plot tabs and preview windows.
        Why:
            Automatic layout health can fix common problems, but users need an
            explicit place to inspect issues, run a persisted one-click autofix,
            tune layout thresholds, adjust combined spacing controls, or persist
            combined-layout suggestions.
        Inputs:
            plot_id: Optional plot identifier supplied by the invoking button.
            fig: Optional explicit target figure for preview-window calls.
            canvas: Optional target canvas for redraw after checks.
            parent: Optional Tk parent window for dialog ownership.
            source: Optional human-readable launch source for diagnostics.
        Outputs:
            None.
        Side Effects:
            Creates a Tk dialog, may run layout auto-fix previews, may run a
            persisted autofix action, may update global layout-health settings,
            may apply combined layout suggestions, and may schedule redraws.
        Exceptions:
            UI failures are reported with safe message boxes where possible.
        """
        targets = self._resolve_layout_health_wizard_targets(
            plot_id=plot_id,
            fig=fig,
            canvas=canvas,
            parent=parent,
        )
        source_norm = str(source or "").strip().lower()
        for target in targets:
            target["source"] = source_norm
            mode_value = str(target.get("mode") or "display").strip().lower()
            if source_norm == "combined_preview":
                mode_value = "export"
            if mode_value not in {"display", "export"}:
                mode_value = "display"
            target["mode"] = mode_value
        owner = parent or getattr(self, "_developer_tools_dialog", None) or self
        if not targets:
            try:
                messagebox.showinfo(
                    "Layout Health Wizard",
                    "No active figure is available for layout-health checks.",
                    parent=owner,
                )
            except Exception:
                pass
            return

        existing = getattr(self, "_layout_health_wizard_window", None)
        if existing is not None:
            try:
                if bool(existing.winfo_exists()):
                    existing.destroy()
            except Exception:
                pass

        normalized = _normalize_layout_health_settings(settings)
        win = tk.Toplevel(owner)
        win.title("Layout Health Wizard")
        win.transient(owner)
        win.minsize(560, 440)
        self._layout_health_wizard_window = win

        status_var = tk.StringVar(value="Running layout health check...")
        make_tweaks_var = tk.BooleanVar(value=False)
        autofix_var = tk.BooleanVar(
            value=bool(normalized.get("layout_health_autofix_enabled", True))
        )
        strict_var = tk.BooleanVar(
            value=bool(normalized.get("layout_health_strict_mode", False))
        )
        xaxis_var = tk.BooleanVar(
            value=bool(
                normalized.get(
                    "layout_health_check_x_axis_conflicts",
                    DEFAULT_LAYOUT_HEALTH_CHECK_X_AXIS_CONFLICTS,
                )
            )
        )
        passes_var = tk.IntVar(
            value=int(
                normalized.get(
                    "layout_health_max_passes", DEFAULT_LAYOUT_HEALTH_MAX_PASSES
                )
            )
        )
        min_gap_var = tk.DoubleVar(
            value=float(
                normalized.get(
                    "layout_health_min_gap_pts", DEFAULT_LAYOUT_HEALTH_MIN_GAP_PTS
                )
            )
        )
        max_gap_var = tk.DoubleVar(
            value=float(
                normalized.get(
                    "layout_health_max_gap_pts", DEFAULT_LAYOUT_HEALTH_MAX_GAP_PTS
                )
            )
        )
        min_axis_gap_var = tk.DoubleVar(
            value=float(
                normalized.get(
                    "layout_health_min_axis_label_tick_gap_pts",
                    DEFAULT_LAYOUT_HEALTH_MIN_AXIS_LABEL_TICK_GAP_PTS,
                )
            )
        )
        max_axis_gap_var = tk.DoubleVar(
            value=float(
                normalized.get(
                    "layout_health_max_axis_label_tick_gap_pts",
                    DEFAULT_LAYOUT_HEALTH_MAX_AXIS_LABEL_TICK_GAP_PTS,
                )
            )
        )
        bottom_space_var = tk.DoubleVar(
            value=float(
                normalized.get(
                    "layout_health_max_bottom_whitespace_pts",
                    DEFAULT_LAYOUT_HEALTH_MAX_BOTTOM_WHITESPACE_PTS,
                )
            )
        )
        has_combined_target = any(
            str(target.get("plot_id") or "").strip().lower()
            == "fig_combined_triple_axis"
            for target in targets
        )
        has_timeline_target = any(
            str(target.get("plot_id") or "").strip().lower() == "fig_cycle_timeline"
            for target in targets
        )
        combined_display_section = _layout_profile_section(
            _get_layout_profile("fig_combined_triple_axis"),
            "display",
        )
        combined_display_margins = _normalize_layout_margins(
            combined_display_section.get("margins"),
            _default_layout_margins("fig_combined_triple_axis", "display"),
        )
        combined_export_section = _layout_profile_section(
            _get_layout_profile("fig_combined_triple_axis"),
            "export",
        )
        combined_export_margins = _normalize_layout_margins(
            combined_export_section.get("margins"),
            _default_layout_margins("fig_combined_triple_axis", "export"),
        )
        combined_axis_pads = combined_display_section.get("axis_labelpads")
        if not isinstance(combined_axis_pads, Mapping):
            combined_axis_pads = {}
        combined_export_axis_pads = combined_export_section.get("axis_labelpads")
        if not isinstance(combined_export_axis_pads, Mapping):
            combined_export_axis_pads = {}
        try:
            combined_right_key_value = self.combined_y_right_key.get()
        except Exception:
            combined_right_key_value = settings.get("combined_y_right_key")
        combined_right_semantic = _combined_axis_semantic_from_key(
            combined_right_key_value
        )
        combined_margin_left_var = tk.DoubleVar(
            value=float(combined_display_margins.get("left", 0.07))
        )
        combined_margin_right_var = tk.DoubleVar(
            value=float(combined_display_margins.get("right", 0.93))
        )
        combined_margin_top_var = tk.DoubleVar(
            value=float(combined_display_margins.get("top", 0.90))
        )
        combined_margin_bottom_var = tk.DoubleVar(
            value=float(combined_display_margins.get("bottom", 0.16))
        )
        combined_xlabel_pad_var = tk.DoubleVar(
            value=float(
                _safe_float(
                    combined_display_section.get("xlabel_pad_pts"),
                    _safe_float(combined_axis_pads.get("x"), 0.0),
                )
                or 0.0
            )
        )
        combined_detached_offset_var = tk.DoubleVar(
            value=float(
                _safe_float(
                    combined_display_section.get("detached_spine_offset"),
                    settings.get("combined_deriv_axis_offset", 1.12),
                )
                or 1.12
            )
        )
        combined_detached_labelpad_var = tk.DoubleVar(
            value=float(
                _safe_float(
                    combined_display_section.get("detached_labelpad"),
                    settings.get("combined_deriv_labelpad", 20.0),
                )
                or 20.0
            )
        )
        combined_inner_right_labelpad_var = tk.DoubleVar(
            value=float(
                _safe_float(
                    combined_axis_pads.get("right"),
                    _safe_float(
                        combined_axis_pads.get(str(combined_right_semantic or "")),
                        settings.get(
                            "combined_temp_labelpad"
                            if combined_right_semantic == "temperature"
                            else "combined_deriv_labelpad",
                            20.0,
                        ),
                    ),
                )
                or 20.0
            )
        )
        combined_export_margin_left_var = tk.DoubleVar(
            value=float(combined_export_margins.get("left", 0.07))
        )
        combined_export_margin_right_var = tk.DoubleVar(
            value=float(combined_export_margins.get("right", 0.93))
        )
        combined_export_margin_top_var = tk.DoubleVar(
            value=float(combined_export_margins.get("top", 0.90))
        )
        combined_export_margin_bottom_var = tk.DoubleVar(
            value=float(combined_export_margins.get("bottom", 0.16))
        )
        combined_export_xlabel_pad_var = tk.DoubleVar(
            value=float(
                _safe_float(
                    combined_export_section.get("xlabel_pad_pts"),
                    _safe_float(combined_export_axis_pads.get("x"), 0.0),
                )
                or 0.0
            )
        )
        combined_export_detached_offset_var = tk.DoubleVar(
            value=float(
                _safe_float(
                    combined_export_section.get("detached_spine_offset"),
                    settings.get("combined_deriv_axis_offset", 1.12),
                )
                or 1.12
            )
        )
        combined_export_detached_labelpad_var = tk.DoubleVar(
            value=float(
                _safe_float(
                    combined_export_section.get("detached_labelpad"),
                    settings.get("combined_deriv_labelpad", 20.0),
                )
                or 20.0
            )
        )
        combined_export_inner_right_labelpad_var = tk.DoubleVar(
            value=float(
                _safe_float(
                    combined_export_axis_pads.get("right"),
                    _safe_float(
                        combined_export_axis_pads.get(
                            str(combined_right_semantic or "")
                        ),
                        settings.get(
                            "combined_temp_labelpad"
                            if combined_right_semantic == "temperature"
                            else "combined_deriv_labelpad",
                            20.0,
                        ),
                    ),
                )
                or 20.0
            )
        )
        timeline_prefs = self._get_cycle_plot_prefs() if has_timeline_target else {}
        timeline_axis_layout = (
            self._cycle_timeline_axis_layout_prefs(timeline_prefs)
            if has_timeline_target
            else {}
        )
        timeline_legend_layout = (
            self._normalize_cycle_timeline_legend_layout_prefs(timeline_prefs)
            if has_timeline_target
            else {}
        )
        timeline_wide_bottom_var = tk.BooleanVar(
            value=bool(
                timeline_prefs.get("export_bottom_legend_wide_under_xaxis", False)
            )
        )
        timeline_center_bottom_var = tk.BooleanVar(
            value=bool(timeline_prefs.get("bottom_legend_center_below_xlabel", False))
        )
        timeline_bottom_wrap_var = tk.BooleanVar(
            value=bool(timeline_legend_layout.get("timeline_bottom_legend_wrap", False))
        )
        timeline_bottom_rows_var = tk.IntVar(
            value=int(timeline_legend_layout.get("timeline_bottom_legend_rows", 2))
        )
        timeline_ph_labelpad_var = tk.DoubleVar(
            value=float(timeline_axis_layout.get("ph_axis_labelpad", 10.0))
        )
        timeline_ph_offset_var = tk.DoubleVar(
            value=float(timeline_axis_layout.get("ph_axis_spine_offset", 1.02))
        )
        timeline_pco2_labelpad_var = tk.DoubleVar(
            value=float(timeline_axis_layout.get("pco2_axis_labelpad", 10.0))
        )
        timeline_pco2_offset_var = tk.DoubleVar(
            value=float(timeline_axis_layout.get("pco2_axis_spine_offset", 1.12))
        )

        root = ttk.Frame(win, padding=12)
        root.pack(fill="both", expand=True)
        root.columnconfigure(0, weight=1)
        root.rowconfigure(2, weight=1)

        target_names = ", ".join(
            f"{str(target.get('plot_id') or 'active_plot')} "
            f"({str(target.get('mode') or 'display')})"
            for target in targets
        )
        ttk.Label(
            root,
            text=f"Target: {target_names}",
            anchor="w",
        ).grid(row=0, column=0, sticky="ew")
        ttk.Label(root, textvariable=status_var, anchor="w").grid(
            row=1, column=0, sticky="ew", pady=(6, 6)
        )

        details = tk.Text(root, height=8, wrap="word")
        details.grid(row=2, column=0, sticky="nsew", pady=(0, 10))
        details.configure(state="disabled")

        controls = ttk.LabelFrame(root, text="Tweaks")
        controls.grid(row=3, column=0, sticky="ew", pady=(0, 10))
        for col_idx in range(4):
            controls.columnconfigure(col_idx, weight=1 if col_idx in {1, 3} else 0)

        tweak_widgets: List[tk.Widget] = []
        tweak_toggle = ttk.Checkbutton(
            controls,
            text="Make tweaks before applying",
            variable=make_tweaks_var,
        )
        tweak_toggle.grid(
            row=0, column=0, columnspan=4, sticky="w", padx=8, pady=(8, 4)
        )
        ttk.Checkbutton(
            controls,
            text="Enable auto-fix",
            variable=autofix_var,
        ).grid(row=1, column=0, sticky="w", padx=8, pady=(0, 4))
        ttk.Checkbutton(
            controls,
            text="Strict mode",
            variable=strict_var,
        ).grid(row=1, column=2, sticky="w", padx=8, pady=(0, 4))
        ttk.Checkbutton(
            controls,
            text="Check X-axis tick/legend collisions",
            variable=xaxis_var,
        ).grid(row=2, column=0, columnspan=4, sticky="w", padx=8, pady=(0, 6))

        spin_specs = [
            (
                "Max passes:",
                passes_var,
                MIN_LAYOUT_HEALTH_MAX_PASSES,
                MAX_LAYOUT_HEALTH_MAX_PASSES,
                1,
            ),
            (
                "Min legend-xlabel gap:",
                min_gap_var,
                MIN_LAYOUT_HEALTH_GAP_PTS,
                MAX_LAYOUT_HEALTH_GAP_PTS,
                0.5,
            ),
            (
                "Max legend-xlabel gap:",
                max_gap_var,
                MIN_LAYOUT_HEALTH_GAP_PTS,
                MAX_LAYOUT_HEALTH_GAP_PTS,
                0.5,
            ),
            (
                "Min axis label-tick gap:",
                min_axis_gap_var,
                MIN_LAYOUT_HEALTH_GAP_PTS,
                MAX_LAYOUT_HEALTH_GAP_PTS,
                0.5,
            ),
            (
                "Max axis label-tick gap:",
                max_axis_gap_var,
                MIN_LAYOUT_HEALTH_GAP_PTS,
                MAX_LAYOUT_HEALTH_GAP_PTS,
                0.5,
            ),
            (
                "Max bottom whitespace:",
                bottom_space_var,
                MIN_LAYOUT_HEALTH_GAP_PTS,
                MAX_LAYOUT_HEALTH_GAP_PTS,
                0.5,
            ),
        ]
        for idx, (label, var, min_value, max_value, increment) in enumerate(spin_specs):
            row = 3 + (idx // 2)
            label_col = 0 if idx % 2 == 0 else 2
            value_col = 1 if idx % 2 == 0 else 3
            ttk.Label(controls, text=label).grid(
                row=row,
                column=label_col,
                sticky="w",
                padx=8,
                pady=(0, 6),
            )
            spin = ttk.Spinbox(
                controls,
                from_=min_value,
                to=max_value,
                increment=increment,
                textvariable=var,
                width=10,
            )
            spin.grid(row=row, column=value_col, sticky="w", padx=(0, 8), pady=(0, 6))
            tweak_widgets.append(spin)

        next_control_row = 3 + ((len(spin_specs) + 1) // 2)
        combined_widgets: List[tk.Widget] = []
        if has_combined_target:
            ttk.Separator(controls, orient="horizontal").grid(
                row=next_control_row,
                column=0,
                columnspan=4,
                sticky="ew",
                padx=8,
                pady=(4, 8),
            )
            ttk.Label(
                controls,
                text="Combined plot layout",
                font=("TkDefaultFont", 9, "bold"),
            ).grid(
                row=next_control_row + 1,
                column=0,
                columnspan=4,
                sticky="w",
                padx=8,
                pady=(0, 6),
            )

            def _build_combined_spin(
                row: int,
                label: str,
                var: tk.DoubleVar,
                min_value: float,
                max_value: float,
                increment: float,
                units: str,
            ) -> None:
                """Build one combined-layout tweak row in the health wizard.

                Purpose:
                    Add compact numeric controls for margins and axis spacing.
                Why:
                    Combined triple-axis fixes often require direct adjustment of
                    subplot bounds and detached-axis spacing, not only health
                    thresholds.
                Inputs:
                    row: Grid row for the control.
                    label: Human-readable label.
                    var: Tk variable backing the spinbox.
                    min_value/max_value/increment: Numeric spinbox constraints.
                    units: Short unit label displayed next to the control.
                Outputs:
                    None.
                Side Effects:
                    Adds widgets to the wizard controls frame and records them in
                    tweak widget collections for enable/disable behavior.
                Exceptions:
                    Tk widget creation errors propagate to the caller.
                """
                ttk.Label(controls, text=label).grid(
                    row=row,
                    column=0,
                    sticky="w",
                    padx=8,
                    pady=(0, 6),
                )
                spin = ttk.Spinbox(
                    controls,
                    from_=min_value,
                    to=max_value,
                    increment=increment,
                    textvariable=var,
                    width=10,
                )
                spin.grid(row=row, column=1, sticky="w", padx=(0, 8), pady=(0, 6))
                ttk.Label(controls, text=units).grid(
                    row=row,
                    column=2,
                    sticky="w",
                    padx=(0, 8),
                    pady=(0, 6),
                )
                combined_widgets.append(spin)
                tweak_widgets.append(spin)

            combined_row = next_control_row + 2
            _build_combined_spin(
                combined_row,
                "Display left margin",
                combined_margin_left_var,
                0.0,
                0.45,
                0.002,
                "figure",
            )
            _build_combined_spin(
                combined_row + 1,
                "Display right margin",
                combined_margin_right_var,
                0.55,
                1.0,
                0.002,
                "figure",
            )
            _build_combined_spin(
                combined_row + 2,
                "Display top margin",
                combined_margin_top_var,
                0.55,
                1.0,
                0.002,
                "figure",
            )
            _build_combined_spin(
                combined_row + 3,
                "Display bottom margin",
                combined_margin_bottom_var,
                0.02,
                0.45,
                0.002,
                "figure",
            )
            _build_combined_spin(
                combined_row + 4,
                "Display X-label pad",
                combined_xlabel_pad_var,
                -24.0,
                48.0,
                0.5,
                "pt",
            )
            _build_combined_spin(
                combined_row + 5,
                "Display second Y label pad",
                combined_inner_right_labelpad_var,
                -48.0,
                96.0,
                0.5,
                "pt",
            )
            _build_combined_spin(
                combined_row + 6,
                "Display detached axis offset",
                combined_detached_offset_var,
                0.0,
                2.2,
                0.02,
                "axes",
            )
            _build_combined_spin(
                combined_row + 7,
                "Display detached label pad",
                combined_detached_labelpad_var,
                -48.0,
                96.0,
                0.5,
                "pt",
            )
            _build_combined_spin(
                combined_row + 8,
                "Export left margin",
                combined_export_margin_left_var,
                0.0,
                0.45,
                0.002,
                "figure",
            )
            _build_combined_spin(
                combined_row + 9,
                "Export right margin",
                combined_export_margin_right_var,
                0.55,
                1.0,
                0.002,
                "figure",
            )
            _build_combined_spin(
                combined_row + 10,
                "Export top margin",
                combined_export_margin_top_var,
                0.55,
                1.0,
                0.002,
                "figure",
            )
            _build_combined_spin(
                combined_row + 11,
                "Export bottom margin",
                combined_export_margin_bottom_var,
                0.02,
                0.45,
                0.002,
                "figure",
            )
            _build_combined_spin(
                combined_row + 12,
                "Export X-label pad",
                combined_export_xlabel_pad_var,
                -24.0,
                48.0,
                0.5,
                "pt",
            )
            _build_combined_spin(
                combined_row + 13,
                "Export second Y label pad",
                combined_export_inner_right_labelpad_var,
                -48.0,
                96.0,
                0.5,
                "pt",
            )
            _build_combined_spin(
                combined_row + 14,
                "Export detached axis offset",
                combined_export_detached_offset_var,
                0.0,
                2.2,
                0.02,
                "axes",
            )
            _build_combined_spin(
                combined_row + 15,
                "Export detached label pad",
                combined_export_detached_labelpad_var,
                -48.0,
                96.0,
                0.5,
                "pt",
            )
            next_control_row = combined_row + 16

        timeline_widgets: List[tk.Widget] = []
        if has_timeline_target:
            ttk.Separator(controls, orient="horizontal").grid(
                row=next_control_row,
                column=0,
                columnspan=4,
                sticky="ew",
                padx=8,
                pady=(4, 8),
            )
            ttk.Label(
                controls,
                text="Cycle timeline layout",
                font=("TkDefaultFont", 9, "bold"),
            ).grid(
                row=next_control_row + 1,
                column=0,
                columnspan=4,
                sticky="w",
                padx=8,
                pady=(0, 6),
            )
            ttk.Checkbutton(
                controls,
                text="Use wide bottom legend under x-axis",
                variable=timeline_wide_bottom_var,
            ).grid(
                row=next_control_row + 2,
                column=0,
                columnspan=2,
                sticky="w",
                padx=8,
                pady=(0, 4),
            )
            ttk.Checkbutton(
                controls,
                text="Center bottom legend below x-axis label",
                variable=timeline_center_bottom_var,
            ).grid(
                row=next_control_row + 2,
                column=2,
                columnspan=2,
                sticky="w",
                padx=8,
                pady=(0, 4),
            )
            ttk.Checkbutton(
                controls,
                text="Wrap bottom legend into rows",
                variable=timeline_bottom_wrap_var,
            ).grid(
                row=next_control_row + 3,
                column=0,
                columnspan=4,
                sticky="w",
                padx=8,
                pady=(0, 6),
            )
            timeline_widgets.extend(
                [
                    child
                    for child in controls.winfo_children()
                    if child not in tweak_widgets and isinstance(child, ttk.Checkbutton)
                ][-3:]
            )

            def _build_timeline_spin(
                row: int,
                label: str,
                var: Any,
                min_value: float,
                max_value: float,
                increment: float,
                units: str,
            ) -> None:
                """Build one cycle-timeline tweak row in the health wizard.

                Purpose:
                    Add compact numeric controls for timeline legend and axis
                    spacing values.
                Why:
                    Cycle Timeline fixes may require tuning the bottom legend,
                    lower pH axis, and attached CO2 uptake axis together.
                Inputs:
                    row: Grid row for the control.
                    label: Human-readable label.
                    var: Tk variable backing the spinbox.
                    min_value/max_value/increment: Numeric spinbox constraints.
                    units: Short unit label displayed next to the control.
                Outputs:
                    None.
                Side Effects:
                    Adds widgets to the wizard controls frame and records them in
                    tweak widget collections for enable/disable behavior.
                Exceptions:
                    Tk widget creation errors propagate to the caller.
                """
                ttk.Label(controls, text=label).grid(
                    row=row,
                    column=0,
                    sticky="w",
                    padx=8,
                    pady=(0, 6),
                )
                spin = ttk.Spinbox(
                    controls,
                    from_=min_value,
                    to=max_value,
                    increment=increment,
                    textvariable=var,
                    width=10,
                )
                spin.grid(row=row, column=1, sticky="w", padx=(0, 8), pady=(0, 6))
                ttk.Label(controls, text=units).grid(
                    row=row,
                    column=2,
                    sticky="w",
                    padx=(0, 8),
                    pady=(0, 6),
                )
                tweak_widgets.append(spin)
                timeline_widgets.append(spin)

            timeline_row = next_control_row + 4
            _build_timeline_spin(
                timeline_row,
                "Bottom legend rows",
                timeline_bottom_rows_var,
                1,
                6,
                1,
                "rows",
            )
            _build_timeline_spin(
                timeline_row + 1,
                "pH axis label pad",
                timeline_ph_labelpad_var,
                0.0,
                48.0,
                0.5,
                "pt",
            )
            _build_timeline_spin(
                timeline_row + 2,
                "pH axis offset",
                timeline_ph_offset_var,
                0.9,
                1.25,
                0.01,
                "axes",
            )
            _build_timeline_spin(
                timeline_row + 3,
                "CO2 axis label pad",
                timeline_pco2_labelpad_var,
                0.0,
                48.0,
                0.5,
                "pt",
            )
            _build_timeline_spin(
                timeline_row + 4,
                "CO2 axis label x",
                timeline_pco2_offset_var,
                0.9,
                1.45,
                0.01,
                "axes",
            )

        for child in controls.winfo_children():
            if child is tweak_toggle:
                continue
            if isinstance(child, (ttk.Checkbutton, ttk.Spinbox)):
                tweak_widgets.append(child)

        def _var_value(var: Any, default: Any) -> Any:
            """Return one Tk variable value with a fallback for invalid entry text."""
            try:
                return var.get()
            except Exception:
                return default

        def _current_policy_values() -> Dict[str, Any]:
            """Collect current wizard values into a layout-health policy mapping."""
            return {
                "layout_health_autofix_enabled": bool(
                    _var_value(autofix_var, DEFAULT_LAYOUT_HEALTH_AUTOFIX_ENABLED)
                ),
                "layout_health_strict_mode": bool(
                    _var_value(strict_var, DEFAULT_LAYOUT_HEALTH_STRICT_MODE)
                ),
                "layout_health_max_passes": _var_value(
                    passes_var,
                    DEFAULT_LAYOUT_HEALTH_MAX_PASSES,
                ),
                "layout_health_min_gap_pts": _var_value(
                    min_gap_var,
                    DEFAULT_LAYOUT_HEALTH_MIN_GAP_PTS,
                ),
                "layout_health_max_gap_pts": _var_value(
                    max_gap_var,
                    DEFAULT_LAYOUT_HEALTH_MAX_GAP_PTS,
                ),
                "layout_health_check_x_axis_conflicts": bool(
                    _var_value(xaxis_var, DEFAULT_LAYOUT_HEALTH_CHECK_X_AXIS_CONFLICTS)
                ),
                "layout_health_min_axis_label_tick_gap_pts": _var_value(
                    min_axis_gap_var,
                    DEFAULT_LAYOUT_HEALTH_MIN_AXIS_LABEL_TICK_GAP_PTS,
                ),
                "layout_health_max_axis_label_tick_gap_pts": _var_value(
                    max_axis_gap_var,
                    DEFAULT_LAYOUT_HEALTH_MAX_AXIS_LABEL_TICK_GAP_PTS,
                ),
                "layout_health_max_bottom_whitespace_pts": _var_value(
                    bottom_space_var,
                    DEFAULT_LAYOUT_HEALTH_MAX_BOTTOM_WHITESPACE_PTS,
                ),
            }

        def _current_combined_layout_values() -> Dict[str, Dict[str, Any]]:
            """Collect staged combined layout values as suggestion payloads.

            Purpose:
                Translate wizard margin and spacing controls into the same
                display/export suggestion schema used by measured health checks.
            Why:
                The wizard should make direct spacing tweaks persist through the
                reviewed suggestion path instead of requiring a separate editor.
            Inputs:
                None.
            Outputs:
                Dict keyed by layout mode with margins, x-label pad, detached
                axis offset, inner-right label padding, and detached label
                padding values.
            Side Effects:
                None.
            Exceptions:
                Invalid widget values are normalized by layout profile helpers.
            """
            display_margins = _normalize_layout_margins(
                {
                    "left": _var_value(combined_margin_left_var, 0.07),
                    "right": _var_value(combined_margin_right_var, 0.93),
                    "top": _var_value(combined_margin_top_var, 0.90),
                    "bottom": _var_value(combined_margin_bottom_var, 0.16),
                },
                _default_layout_margins("fig_combined_triple_axis", "display"),
            )
            export_margins = _normalize_layout_margins(
                {
                    "left": _var_value(combined_export_margin_left_var, 0.07),
                    "right": _var_value(combined_export_margin_right_var, 0.93),
                    "top": _var_value(combined_export_margin_top_var, 0.90),
                    "bottom": _var_value(combined_export_margin_bottom_var, 0.16),
                },
                _default_layout_margins("fig_combined_triple_axis", "export"),
            )
            display_payload = {
                "margins": display_margins,
                "xlabel_pad_pts": _var_value(combined_xlabel_pad_var, 0.0),
                "detached_spine_offset": _var_value(
                    combined_detached_offset_var,
                    1.12,
                ),
                "detached_labelpad": _var_value(
                    combined_detached_labelpad_var,
                    20.0,
                ),
                "axis_labelpads": {
                    "x": _var_value(combined_xlabel_pad_var, 0.0),
                    "right": _var_value(combined_inner_right_labelpad_var, 20.0),
                    "third": _var_value(combined_detached_labelpad_var, 20.0),
                },
            }
            export_payload = {
                "margins": export_margins,
                "xlabel_pad_pts": _var_value(combined_export_xlabel_pad_var, 0.0),
                "detached_spine_offset": _var_value(
                    combined_export_detached_offset_var,
                    1.12,
                ),
                "detached_labelpad": _var_value(
                    combined_export_detached_labelpad_var,
                    20.0,
                ),
                "axis_labelpads": {
                    "x": _var_value(combined_export_xlabel_pad_var, 0.0),
                    "right": _var_value(
                        combined_export_inner_right_labelpad_var,
                        20.0,
                    ),
                    "third": _var_value(combined_export_detached_labelpad_var, 20.0),
                },
            }
            return {
                "display": display_payload,
                "export": export_payload,
            }

        def _current_timeline_layout_values() -> Dict[str, Any]:
            """Collect staged Cycle Timeline layout values for persistence.

            Purpose:
                Translate wizard controls into the existing `cycle_plot_prefs`
                keys used by the timeline renderer.
            Why:
                The layout wizard must be able to tune timeline-specific legend
                and axis spacing without requiring a separate settings dialog.
            Inputs:
                None.
            Outputs:
                Dict containing normalized timeline preference values.
            Side Effects:
                None.
            Exceptions:
                Invalid widget values are coerced by timeline preference readers.
            """
            return {
                "export_bottom_legend_wide_under_xaxis": bool(
                    _var_value(timeline_wide_bottom_var, False)
                ),
                "bottom_legend_center_below_xlabel": bool(
                    _var_value(timeline_center_bottom_var, False)
                ),
                "timeline_bottom_legend_wrap": bool(
                    _var_value(timeline_bottom_wrap_var, False)
                ),
                "timeline_bottom_legend_rows": int(
                    max(1, min(6, int(_var_value(timeline_bottom_rows_var, 2))))
                ),
                "ph_axis_labelpad": float(
                    _var_value(timeline_ph_labelpad_var, 10.0)
                ),
                "ph_axis_spine_offset": float(
                    _var_value(timeline_ph_offset_var, 1.02)
                ),
                "pco2_axis_labelpad": float(
                    _var_value(timeline_pco2_labelpad_var, 10.0)
                ),
                "pco2_axis_spine_offset": float(
                    _var_value(timeline_pco2_offset_var, 1.12)
                ),
            }

        def _current_timeline_manager_policy() -> Dict[str, Any]:
            """Build the Cycle Timeline manager policy from wizard controls.

            Purpose:
                Map generic wizard thresholds onto the timeline-specific layout
                manager preference keys.
            Why:
                Cycle Timeline display, generated-tab preview, and export paths
                read layout-manager policy from `cycle_plot_prefs`, not only the
                global layout-health settings.
            Inputs:
                None.
            Outputs:
                Dict suitable for `_apply_cycle_timeline_layout_manager_policy`.
            Side Effects:
                None.
            Exceptions:
                Invalid widget values are normalized by the apply helper.
            """
            return {
                "layout_manager_enabled": True,
                "layout_manager_strict_mode": bool(_var_value(strict_var, False)),
                "layout_manager_max_passes": int(_var_value(passes_var, 3)),
                "layout_manager_check_legend_conflicts": True,
                "layout_manager_check_axis_label_conflicts": True,
                "layout_manager_min_legend_xlabel_gap_pts": float(
                    _var_value(min_gap_var, DEFAULT_LAYOUT_HEALTH_MIN_GAP_PTS)
                ),
                "layout_manager_max_legend_xlabel_gap_pts": float(
                    _var_value(max_gap_var, DEFAULT_LAYOUT_HEALTH_MAX_GAP_PTS)
                ),
                "layout_manager_min_axis_label_tick_gap_pts": float(
                    _var_value(
                        min_axis_gap_var,
                        DEFAULT_LAYOUT_HEALTH_MIN_AXIS_LABEL_TICK_GAP_PTS,
                    )
                ),
                "layout_manager_max_axis_label_tick_gap_pts": float(
                    _var_value(
                        max_axis_gap_var,
                        DEFAULT_LAYOUT_HEALTH_MAX_AXIS_LABEL_TICK_GAP_PTS,
                    )
                ),
                "layout_manager_max_bottom_whitespace_pts": float(
                    _var_value(
                        bottom_space_var,
                        DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MAX_BOTTOM_WHITESPACE_PTS,
                    )
                ),
            }

        def _set_details(lines: Sequence[str]) -> None:
            """Replace the wizard details text with current check output."""
            details.configure(state="normal")
            details.delete("1.0", "end")
            details.insert("1.0", "\n".join(lines) if lines else "No results.")
            details.configure(state="disabled")

        def _set_tweak_state(*_args: Any) -> None:
            """Enable or disable tweak controls based on the user choice."""
            state_value = "normal" if bool(make_tweaks_var.get()) else "disabled"
            for widget in tweak_widgets:
                try:
                    widget.configure(state=state_value)
                except Exception:
                    pass

        def _run_preview() -> None:
            """Run the wizard preview check with current control values."""
            policy_values = _current_policy_values()
            lines, applied_count, has_combined = self._run_layout_health_wizard_check(
                targets,
                policy_values,
            )
            combined_note = (
                " Combined layout suggestions are available through Apply to Settings."
                if has_combined
                else ""
            )
            status_var.set(
                f"Checked {len(targets)} figure(s). "
                f"Auto-fix applied to {applied_count}."
                + combined_note
            )
            _set_details(lines)

        def _persist_policy_values(policy_values: Mapping[str, Any]) -> None:
            """Persist wizard policy controls into global layout-health settings.

            Purpose:
                Share one settings update path for Apply and one-click Autofix.
            Why:
                The wizard's controls should stay synchronized with Developer Tools
                variables regardless of which action commits the changes.
            Inputs:
                policy_values: Raw wizard policy payload from current controls.
            Outputs:
                None.
            Side Effects:
                Updates `settings`, mirrors Tk control variables, and schedules a
                settings save.
            Exceptions:
                Normalization handles invalid values using layout-health defaults.
            """
            normalized_policy = _normalize_layout_health_settings(policy_values)
            settings.update(normalized_policy)
            self._layout_health_autofix_enabled_var.set(
                bool(normalized_policy["layout_health_autofix_enabled"])
            )
            self._layout_health_strict_mode_var.set(
                bool(normalized_policy["layout_health_strict_mode"])
            )
            self._layout_health_max_passes_var.set(
                int(normalized_policy["layout_health_max_passes"])
            )
            self._layout_health_min_gap_pts_var.set(
                float(normalized_policy["layout_health_min_gap_pts"])
            )
            self._layout_health_max_gap_pts_var.set(
                float(normalized_policy["layout_health_max_gap_pts"])
            )
            self._layout_health_check_x_axis_conflicts_var.set(
                bool(normalized_policy["layout_health_check_x_axis_conflicts"])
            )
            self._layout_health_min_axis_label_tick_gap_pts_var.set(
                float(normalized_policy["layout_health_min_axis_label_tick_gap_pts"])
            )
            self._layout_health_max_axis_label_tick_gap_pts_var.set(
                float(normalized_policy["layout_health_max_axis_label_tick_gap_pts"])
            )
            self._layout_health_max_bottom_whitespace_pts_var.set(
                float(normalized_policy["layout_health_max_bottom_whitespace_pts"])
            )
            self._schedule_save_settings()

        def _combined_targets() -> List[Mapping[str, Any]]:
            """Return wizard targets that use the combined triple-axis layout.

            Purpose:
                Identify whether the current wizard action needs combined profile
                suggestion persistence.
            Why:
                Generic layout-health checks can redraw any figure, but only the
                combined triple-axis plot has display/export layout suggestions
                that map back into Plot Settings.
            Inputs:
                None.
            Outputs:
                List of target mappings for combined triple-axis figures.
            Side Effects:
                None.
            Exceptions:
                Missing or malformed target metadata is ignored.
            """
            return [
                target
                for target in targets
                if str(target.get("plot_id") or "").strip().lower()
                == "fig_combined_triple_axis"
            ]

        def _apply_combined_suggestions_from_wizard(
            *,
            include_tweaks: bool,
        ) -> bool:
            """Persist currently measured combined layout suggestions.

            Purpose:
                Commit measured auto-fix outputs and optional staged tweak values
                into the combined display/export layout profile.
            Why:
                Both Apply and Autofix need the same bridge from figure-local
                suggestions to Plot Settings values.
            Inputs:
                include_tweaks: When True, merge visible wizard tweak values over
                    measured suggestions.
            Outputs:
                True when combined Plot Settings changed.
            Side Effects:
                May run hidden export measurement, update settings, save them, and
                refresh the combined plot through the existing apply helper.
            Exceptions:
                Missing suggestions produce a no-op False result.
            """
            if not _combined_targets():
                return False
            suggestions = self._collect_combined_layout_suggestions(
                include_hidden_export_check=True
            )
            if bool(include_tweaks):
                staged_suggestions = _current_combined_layout_values()
                for mode_key, payload in staged_suggestions.items():
                    merged_payload = dict(suggestions.get(mode_key) or {})
                    merged_payload.update(payload)
                    suggestions[mode_key] = merged_payload
            if not suggestions:
                return False
            return self._apply_combined_layout_suggestions_to_settings(suggestions)

        def _apply_timeline_suggestions_from_wizard(
            *,
            include_tweaks: bool,
        ) -> bool:
            """Persist Cycle Timeline wizard policy and optional tweaks.

            Purpose:
                Commit the timeline layout-manager thresholds and visible
                timeline-specific controls into `cycle_plot_prefs`.
            Why:
                The generated Cycle Timeline tab and preview window rebuild from
                timeline preferences, so wizard fixes must persist there as well.
            Inputs:
                include_tweaks: When True, merge visible timeline legend/axis
                    controls in addition to manager thresholds.
            Outputs:
                True when timeline preferences or manager policy changed.
            Side Effects:
                Updates timeline preferences, saves settings, invalidates layout
                signatures, refreshes cycle views, syncs generated tab state, and
                may rebuild an open preview window.
            Exceptions:
                Best-effort guards preserve the wizard if refresh/save fails.
            """
            if not has_timeline_target:
                return False
            changed = bool(
                self._apply_cycle_timeline_layout_manager_policy(
                    _current_timeline_manager_policy(),
                    show_splash=True,
                )
            )
            if not bool(include_tweaks):
                return changed
            prefs = self._get_cycle_plot_prefs()
            before_payload = dict(prefs)
            prefs.update(_current_timeline_layout_values())
            prefs.update(self._normalize_cycle_timeline_legend_layout_prefs(prefs))
            self._cycle_plot_prefs = dict(prefs)
            settings_ref = getattr(self, "settings", None)
            if isinstance(settings_ref, dict):
                settings_ref["cycle_plot_prefs"] = dict(prefs)
            try:
                _save_settings_to_disk()
            except Exception:
                # Best-effort guard; ignore failures to keep the wizard responsive.
                pass
            direct_changed = before_payload != dict(prefs)
            changed = changed or direct_changed
            if direct_changed:
                self._cycle_timeline_display_layout_signature = None
                self._cycle_timeline_preview_layout_signature = None
                splash_session_id = None
                try:
                    splash_session_id = self._begin_solubility_loading_phase(
                        phase="timeline_layout_wizard_tweaks",
                        message="Refreshing Cycle Timeline layout...",
                        detail="Applying timeline legend and axis tweaks.",
                    )
                except Exception:
                    splash_session_id = None
                try:
                    self._refresh_cycle_views()
                except Exception:
                    # Best-effort guard; ignore refresh failures.
                    pass
                try:
                    self._sync_cycle_timeline_generated_tab_from_persisted_state(
                        "fig_cycle_timeline",
                        reason="layout_health_wizard_apply",
                        sync_elements=False,
                        sync_legends=True,
                    )
                except Exception:
                    # Best-effort guard; ignore generated-tab sync failures.
                    pass
                preview_window = getattr(self, "_cycle_timeline_preview_window", None)
                if preview_window is not None and bool(
                    getattr(preview_window, "winfo_exists", lambda: False)()
                ):
                    try:
                        self._open_cycle_timeline_plot_preview()
                    except Exception:
                        # Best-effort guard; ignore preview rebuild failures.
                        pass
                if splash_session_id is not None:
                    try:
                        self._complete_solubility_loading_phase(
                            splash_session_id,
                            message="Cycle Timeline layout refreshed.",
                            detail="Applying final redraw.",
                        )
                    except Exception:
                        # Best-effort guard; ignore splash completion failures.
                        pass
            return changed

        def _apply_to_settings() -> None:
            """Persist approved wizard tweaks or combined suggestions.

            Purpose:
                Commit current wizard policy controls and reviewed combined
                suggestions through the non-autofix Apply action.
            Why:
                Users may want to save threshold/tweak changes without running the
                one-click Autofix workflow.
            Inputs:
                None.
            Outputs:
                None.
            Side Effects:
                Updates layout-health settings, may update combined Plot Settings,
                reruns the preview check, and updates wizard status text.
            Exceptions:
                Apply helpers handle invalid values and no-op suggestion states.
            """
            policy_values = _current_policy_values()
            applied_combined = _apply_combined_suggestions_from_wizard(
                include_tweaks=bool(make_tweaks_var.get())
            )
            applied_timeline = _apply_timeline_suggestions_from_wizard(
                include_tweaks=bool(make_tweaks_var.get())
            )
            _persist_policy_values(policy_values)
            _run_preview()
            status_var.set(
                "Layout-health settings applied."
                + (" Combined layout suggestion applied." if applied_combined else "")
                + (" Cycle timeline settings applied." if applied_timeline else "")
            )

        def _autofix_now() -> None:
            """Run measured layout autofix and immediately persist its settings.

            Purpose:
                Provide the one-click wizard action that inspects the whole target
                figure, applies available fixes, and writes resulting layout values
                back to Plot Settings.
            Why:
                Users should not need to infer that Preview Tweaks plus Apply to
                Settings is required for measured auto-fix changes to persist.
            Inputs:
                None.
            Outputs:
                None.
            Side Effects:
                Enables auto-fix for this run, mutates target figure layout,
                persists combined layout suggestions, updates global policy
                settings, refreshes/redraws targets, and updates wizard text.
            Exceptions:
                Per-target check errors are captured by the shared check helper.
            """
            autofix_var.set(True)
            xaxis_var.set(True)
            policy_values = _current_policy_values()
            lines, applied_count, has_combined = self._run_layout_health_wizard_check(
                targets,
                policy_values,
            )
            applied_combined = _apply_combined_suggestions_from_wizard(
                include_tweaks=bool(make_tweaks_var.get())
            )
            applied_timeline = _apply_timeline_suggestions_from_wizard(
                include_tweaks=bool(make_tweaks_var.get())
            )
            _persist_policy_values(policy_values)
            _set_details(lines)
            status_var.set(
                f"Autofix checked {len(targets)} figure(s); "
                f"runtime fixes applied to {applied_count}."
                + (
                    " Combined Plot Settings updated."
                    if applied_combined
                    else (
                        " No combined settings changes were needed."
                        if has_combined
                        else ""
                    )
                )
                + (" Cycle Timeline settings updated." if applied_timeline else "")
            )

        def _reset_defaults() -> None:
            """Reset wizard controls to application layout-health defaults."""
            autofix_var.set(DEFAULT_LAYOUT_HEALTH_AUTOFIX_ENABLED)
            strict_var.set(DEFAULT_LAYOUT_HEALTH_STRICT_MODE)
            xaxis_var.set(DEFAULT_LAYOUT_HEALTH_CHECK_X_AXIS_CONFLICTS)
            passes_var.set(DEFAULT_LAYOUT_HEALTH_MAX_PASSES)
            min_gap_var.set(DEFAULT_LAYOUT_HEALTH_MIN_GAP_PTS)
            max_gap_var.set(DEFAULT_LAYOUT_HEALTH_MAX_GAP_PTS)
            min_axis_gap_var.set(DEFAULT_LAYOUT_HEALTH_MIN_AXIS_LABEL_TICK_GAP_PTS)
            max_axis_gap_var.set(DEFAULT_LAYOUT_HEALTH_MAX_AXIS_LABEL_TICK_GAP_PTS)
            bottom_space_var.set(DEFAULT_LAYOUT_HEALTH_MAX_BOTTOM_WHITESPACE_PTS)
            make_tweaks_var.set(True)
            _set_tweak_state()
            status_var.set("Defaults loaded. Preview or apply them when ready.")

        def _close() -> None:
            """Close the Layout Health Wizard and clear the window reference."""
            try:
                win.destroy()
            finally:
                if getattr(self, "_layout_health_wizard_window", None) is win:
                    self._layout_health_wizard_window = None

        make_tweaks_var.trace_add("write", _set_tweak_state)
        _set_tweak_state()

        buttons = ttk.Frame(root)
        buttons.grid(row=4, column=0, sticky="ew")
        ttk.Button(buttons, text="Preview Tweaks", command=_run_preview).pack(
            side="left", padx=(0, 6)
        )
        ttk.Button(buttons, text="Autofix", command=_autofix_now).pack(
            side="left", padx=(0, 6)
        )
        ttk.Button(buttons, text="Apply to Settings", command=_apply_to_settings).pack(
            side="left", padx=(0, 6)
        )
        ttk.Button(buttons, text="Reset Defaults", command=_reset_defaults).pack(
            side="left", padx=(0, 6)
        )
        ttk.Button(buttons, text="Close", command=_close).pack(side="right")
        win.protocol("WM_DELETE_WINDOW", _close)

        try:
            self._dbg(
                "ui.events",
                "Layout Health Wizard opened source=%s targets=%s",
                str(source or ""),
                target_names,
            )
        except Exception:
            pass
        _run_preview()

    def _apply_concurrency_controls(self) -> None:
        """Apply developer concurrency control values to live worker state.

        Purpose:
            Normalize and apply worker-thread controls from the Developer Tools UI.
        Why:
            Render precompute worker policy should react immediately to runtime
            tuning while preserving safe no-GIL/GIL behavior.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Updates persisted concurrency settings and calls
            `self._task_runner.set_max_workers(...)` and
            `self._combined_render_runner.set_max_workers(...)` with
            policy-resolved workers.
        Exceptions:
            Invalid UI values are normalized to safe defaults without raising.
        """
        try:
            threads = int(self._dev_worker_threads_var.get())
        except Exception:
            threads = 1
        threads = max(1, threads)
        enabled = bool(self._dev_parallel_compute_var.get())
        settings["dev_worker_threads"] = threads
        settings["dev_enable_parallel_compute"] = enabled
        self._dev_worker_threads_var.set(threads)
        worker_count = _resolve_render_worker_count(
            requested_workers=threads,
            parallel_enabled=enabled,
        )
        self._task_runner.set_max_workers(worker_count)
        self._combined_render_runner.set_max_workers(worker_count)
        self._schedule_save_settings()

    def _run_timeline_table_export_validation(self) -> None:
        """Run timeline table export validation.
        Used to execute timeline table export validation and coordinate results."""
        try:
            success, out_dir, outputs, errors = _dev_test_timeline_table_export()
        except Exception as exc:
            try:
                messagebox.showerror(
                    "Timeline Table Export Validation",
                    f"Validation crashed: {exc}",
                )
            except Exception:
                pass
            return
        files_text = "\n".join(str(path) for path in outputs) or "None"
        errors_text = "\n".join(errors) or "None"
        summary = (
            "Output folder:\n"
            f"{out_dir}\n\n"
            "Generated files:\n"
            f"{files_text}\n\n"
            "Failures:\n"
            f"{errors_text}"
        )
        title = "Timeline Table Export Validation"
        try:
            if success:
                messagebox.showinfo(title, summary)
            else:
                messagebox.showwarning(title, summary)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _run_solubility_regression(self) -> None:
        """Run solubility regression.
        Used to execute solubility regression and coordinate results."""

        self._open_regression_checks_dialog()

    def _on_solubility_regression_complete(self, success: bool, message: str) -> None:
        """Handle solubility regression complete.
        Used as an event callback for solubility regression complete."""

        self._sol_regression_task_id = None
        summary = (message or "").strip()
        if len(summary) > 2000:
            summary = summary[:2000].rstrip() + "\nâ€¦ (output truncated)"
        if success:
            title = "Solubility Regression Completed"
            body = summary or "Regression checks completed successfully."
            try:
                messagebox.showinfo(title, body)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        else:
            title = "Solubility Regression Failed"
            body = summary or "See console output for additional details."
            try:
                messagebox.showerror(title, body)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

    def _screen_font_multiplier(self):
        """Perform screen font multiplier.
        Used to keep the workflow logic localized and testable."""
        scale = getattr(self, "_ui_scale", 1.0) or 1.0
        if scale >= 1.0:
            return min(scale * 1.1, 2.5)
        return max(0.75, 1.0 - (1.0 - scale) * 0.4)

    def _geometry_fits_screen(self, geometry):
        """Perform geometry fits screen.
        Used to keep the workflow logic localized and testable."""
        if not geometry:
            return False
        try:
            size_part = geometry.split("+", 1)[0]
            width_str, height_str = size_part.split("x", 1)
            width = int(width_str)
            height = int(height_str)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            return False
        try:
            screen_w = self.winfo_screenwidth()
            screen_h = self.winfo_screenheight()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            return True
        return width <= screen_w and height <= screen_h

    def _apply_plot_elements_editor_geometry(
        self, editor: tk.Toplevel, ui_state: Mapping[str, Any]
    ) -> None:
        """Apply screen-safe geometry defaults for the Plot Elements editor.

        Purpose:
            Normalize persisted Plot Elements editor geometry before opening.
        Why:
            Persisted geometry can become oversized or partially off-screen after
            monitor/layout changes, which can hide key controls.
        Args:
            editor: Plot Elements toplevel window receiving geometry updates.
            ui_state: Persisted per-plot annotations UI state dictionary.
        Returns:
            None.
        Side Effects:
            Updates editor geometry and initial on-screen position.
        Exceptions:
            Uses best-effort guards so geometry issues do not block editor open.
        """
        min_w = int(self._scale_length(960))
        min_h = int(self._scale_length(620))
        preferred_w = int(self._scale_length(1160))
        preferred_h = int(self._scale_length(740))

        try:
            screen_w = int(editor.winfo_screenwidth())
            screen_h = int(editor.winfo_screenheight())
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            screen_w = 0
            screen_h = 0

        max_w = max(
            min_w, int(screen_w * 0.92) if screen_w > 0 else int(preferred_w)
        )
        max_h = max(
            min_h, int(screen_h * 0.90) if screen_h > 0 else int(preferred_h)
        )
        fallback_w = max(min_w, min(preferred_w, max_w))
        fallback_h = max(min_h, min(preferred_h, max_h))

        raw_geometry = (
            ui_state.get("editor_geometry") if isinstance(ui_state, Mapping) else None
        )
        parsed_width: Optional[int] = None
        parsed_height: Optional[int] = None
        parsed_x: Optional[int] = None
        parsed_y: Optional[int] = None
        if isinstance(raw_geometry, str):
            match = re.match(
                r"^\s*(\d+)x(\d+)(?:\+(-?\d+)\+(-?\d+))?\s*$", raw_geometry.strip()
            )
            if match is not None:
                try:
                    parsed_width = int(match.group(1))
                    parsed_height = int(match.group(2))
                    if match.group(3) is not None and match.group(4) is not None:
                        parsed_x = int(match.group(3))
                        parsed_y = int(match.group(4))
                except Exception:
                    parsed_width = None
                    parsed_height = None
                    parsed_x = None
                    parsed_y = None

        width = (
            fallback_w
            if parsed_width is None
            else max(min_w, min(max_w, int(parsed_width)))
        )
        height = (
            fallback_h
            if parsed_height is None
            else max(min_h, min(max_h, int(parsed_height)))
        )

        # Keep restored origin visible; otherwise center defaults for first open.
        if screen_w > 0 and screen_h > 0:
            max_x = max(0, screen_w - width)
            max_y = max(0, screen_h - height)
            if parsed_x is None or parsed_y is None:
                pos_x = max(0, int((screen_w - width) / 2))
                pos_y = max(0, int((screen_h - height) / 2))
            else:
                pos_x = max(0, min(max_x, int(parsed_x)))
                pos_y = max(0, min(max_y, int(parsed_y)))
        else:
            pos_x = 60 if parsed_x is None else max(0, int(parsed_x))
            pos_y = 60 if parsed_y is None else max(0, int(parsed_y))

        try:
            editor.geometry(f"{width}x{height}+{pos_x}+{pos_y}")
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            try:
                editor.geometry(f"{width}x{height}")
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

    def _apply_accessible_fonts(self, base_size=10, tab_bold=True):
        """Apply global accessible font settings and refresh dependent styles.

        Purpose:
            Recompute the active UI font family/size and apply them to ttk defaults.
        Why:
            The app supports zoom/font scaling and must keep text sizing coherent
            across controls, menus, toolbars, and notebook tabs.
        Inputs:
            base_size: Requested base font size before display scaling.
            tab_bold: Legacy flag for callers that previously preferred bold tabs.
                Main tabs now intentionally follow button-style typography.
        Outputs:
            None.
        Side Effects:
            Updates Tk named fonts, ttk styles, settings persistence, menu fonts,
            cycle button fonts, toolbar scaling, and main notebook tab styling.
        Exceptions:
            Best-effort guards avoid runtime interruption when toolkit operations fail.
        """
        PREFERRED_FONTS = [
            "Lexend Deca",
            "Atkinson Hyperlegible",
            "Verdana",
            "Tahoma",
            "Arial",
        ]

        try:
            available = set(tkfont.families(self))
        except Exception:
            available = set(tkfont.families())

        chosen = next((f for f in PREFERRED_FONTS if f in available), "Verdana")

        self._base_font_size = max(8, min(int(base_size), 24))
        self._ui_font_family = chosen
        multiplier = self._screen_font_multiplier()
        effective_size = max(8, min(int(round(self._base_font_size * multiplier)), 28))
        self._effective_font_size = effective_size
        self._tab_font_size = max(effective_size - 2, 8)

        base = tkfont.nametofont("TkDefaultFont")
        base.configure(family=chosen, size=effective_size)

        # Iterate to apply the per-item logic.
        for name in (
            "TkTextFont",
            "TkFixedFont",
            "TkMenuFont",
            "TkHeadingFont",
            "TkCaptionFont",
            "TkSmallCaptionFont",
            "TkIconFont",
            "TkTooltipFont",
        ):
            try:
                tkfont.nametofont(name).configure(family=chosen, size=effective_size)
            except tk.TclError:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

        style = ttk.Style(self)
        style.configure(".", font=base)
        button_padding = (
            self._scale_length(10),
            self._scale_length(6),
        )
        button_font_size = max(effective_size - 1, 8)
        style.configure(
            "TButton", font=(chosen, button_font_size), padding=button_padding
        )
        style.configure(
            "TMenubutton", font=(chosen, button_font_size), padding=button_padding
        )
        style.configure("TEntry", font=(chosen, effective_size))
        combo_font_size = max(effective_size - 1, 9)
        style.configure("TCombobox", font=(chosen, combo_font_size))

        style.configure("TLabelFrame.Label", font=(chosen, effective_size, "bold"))
        style.configure("Cycle.TButton", font=(chosen, self._tab_font_size))
        style.configure("CycleHint.TLabel", font=(chosen, self._tab_font_size))
        row_height = self._scale_length(28)
        style.configure(
            "Treeview",
            font=(chosen, max(effective_size - 2, 8)),
            rowheight=row_height,
        )
        style.configure(
            "Treeview.Heading",
            font=(chosen, max(effective_size - 1, 9)),
        )
        scrollbar_arrow = self._scale_length(14)
        style.configure("Vertical.TScrollbar", arrowsize=scrollbar_arrow)
        style.configure("Horizontal.TScrollbar", arrowsize=scrollbar_arrow)

        try:
            self.option_add("*TCombobox*Listbox.font", (chosen, combo_font_size))
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

        settings["ui_font_size"] = self._base_font_size
        self._apply_main_notebook_style(style=style)

        self._refresh_cycle_button_fonts()
        self._refresh_menu_fonts()
        self._apply_toolbar_scaling(getattr(self, "_cycle_toolbar", None))

    def _apply_main_notebook_style(self, style: Optional[ttk.Style] = None) -> None:
        """Apply typography and spacing for the top-level notebook tabs only.

        Purpose:
            Keep main app tab labels visually aligned with CTk-era button typography.
        Why:
            Stage UI migration introduced compact CTk button text sizing; top-level
            tab names should mirror that system without affecting nested notebooks.
        Inputs:
            style: Optional ttk style object to reuse; when omitted, a new instance is
                created for this app context.
        Outputs:
            None.
        Side Effects:
            Configures `Main.TNotebook` / `Main.TNotebook.Tab` style definitions and
            stores style-name attributes used when creating the main notebook widget.
        Exceptions:
            Best-effort guards protect against style/font resolution failures.
        """
        if style is None:
            style = ttk.Style(self)
        base_font = tkfont.nametofont("TkDefaultFont")
        tab_family = getattr(self, "_ui_font_family", base_font.actual("family"))
        effective_size = getattr(
            self, "_effective_font_size", max(int(base_font.actual("size")), 8)
        )
        button_text_size = max(int(effective_size) - 1, 8)
        tab_style_name = getattr(self, "_main_notebook_tab_style", "Main.TNotebook.Tab")
        notebook_style_name = getattr(self, "_main_notebook_style", "Main.TNotebook")
        self._main_notebook_tab_style = tab_style_name
        self._main_notebook_style = notebook_style_name
        tab_padding = (
            self._scale_length(8),
            self._scale_length(4),
            self._scale_length(8),
            self._scale_length(4),
        )
        tab_margins = tuple(self._scale_length(v) for v in (2, 2, 2, 0))
        style.configure(
            tab_style_name,
            font=(tab_family, button_text_size),
            padding=tab_padding,
        )
        style.configure(notebook_style_name, tabmargins=tab_margins)

    def _refresh_cycle_button_fonts(self):
        """Refresh cycle button fonts.
        Used to sync cycle button fonts with current settings."""
        btn_family = getattr(self, "_ui_font_family", "Verdana")
        default_base = getattr(self, "_default_font_size", 10)
        btn_size = getattr(self, "_tab_font_size", max(default_base - 2, 8))
        # Iterate over getattr(self, "_cycle_button_fonts", []) to apply the per-item logic.
        for font_obj in getattr(self, "_cycle_button_fonts", []):
            try:
                current = font_obj.actual()
                font_obj.configure(
                    family=btn_family,
                    size=btn_size,
                    weight=current.get("weight", "normal"),
                    slant=current.get("slant", "roman"),
                )
            except Exception:
                continue

    def _ensure_initial_data_tab_visible(self, _event=None):
        """Finalize Data-tab visibility once startup sequencing is complete.

        Purpose:
            Keep the Data tab selected and interactive after startup transitions.
        Why:
            Startup warmup now runs under splash gating, so this callback should
            only retry while splash is present and avoid visible tab cycling.
        Inputs:
            _event: Optional Tk event payload from `<Map>` or timer callbacks.
        Outputs:
            None.
        Side Effects:
            Clears timer bookkeeping, reschedules itself while splash exists, and
            finalizes Data-tab selection/focus once the notebook is ready.
        Exceptions:
            Best-effort guards prevent failures during early-launch widget churn.
        """
        _ = _event

        # Keep only one retry callback active to avoid stacked startup reschedules.
        after_id = getattr(self, "_initial_tab_after_id", None)
        if after_id is not None:
            try:
                self.after_cancel(after_id)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        self._initial_tab_after_id = None

        if getattr(self, "_initial_tab_shown", False):
            return

        startup_overlay = getattr(self, "_startup_loading_overlay", None)
        if startup_overlay is not None:
            try:
                if startup_overlay.winfo_exists():
                    try:
                        self._initial_tab_after_id = self.after(
                            150, self._ensure_initial_data_tab_visible
                        )
                    except Exception:
                        self._initial_tab_after_id = None
                    return
            except Exception:
                # Best-effort guard; continue with default flow.
                pass

        nb = getattr(self, "nb", None)
        data_tab = getattr(self, "tab_data", None)
        if (
            nb is None
            or data_tab is None
            or not getattr(nb, "winfo_exists", lambda: False)()
        ):
            try:
                self._initial_tab_after_id = self.after(
                    150, self._ensure_initial_data_tab_visible
                )
            except Exception:
                self._initial_tab_after_id = None
            return

        # Keep fallback behavior deterministic: finalize Data tab, no visible cycling.
        self._finalize_startup_to_data_tab()

    def _handle_font_increase(self, event):
        """Handle font increase.
        Used as an event callback for font increase."""
        self._adjust_ui_zoom(0.1)
        return "break"

    def _handle_font_decrease(self, event):
        """Handle font decrease.
        Used as an event callback for font decrease."""
        self._adjust_ui_zoom(-0.1)
        return "break"

    def _handle_font_reset(self, event):
        """Handle font reset.
        Used as an event callback for font reset."""
        self._set_global_scale(getattr(self, "_initial_ui_scale", 1.0), reflow=False)
        return "break"

    def _build_ui(self):
        """Build UI.
        Purpose: Assemble the main window layout and widget wiring.
        Why: Centralizes UI construction after state initialization.
        Inputs: None.
        Outputs: None.
        Side effects: Creates/grids widgets, stores widget references, and binds events.
        Exceptions: Best-effort guards are used internally; no intentional raises.
        """
        self._update_startup_loading_splash_progress(
            progress=16.0,
            message="Building Data, Columns, and Plot tabs...",
        )

        # Root uses grid: row 0 (Notebook) grows, row 1 (buttons) stays fixed

        self.grid_rowconfigure(0, weight=1)

        self.grid_rowconfigure(1, weight=0)

        self.grid_columnconfigure(0, weight=1)

        base_font = tkfont.nametofont("TkDefaultFont")

        # --- Bordered shell around the tab strip for a strong, black outline ---

        tabshell = tk.Frame(
            self,
            bd=2,
            relief="solid",
            highlightthickness=1,
            highlightbackground="black",
            highlightcolor="black",
        )

        tabshell.grid(row=0, column=0, sticky="nsew", padx=8, pady=8)

        # Notebook lives inside the bordered shell

        self._main_notebook_style = "Main.TNotebook"
        self._main_notebook_tab_style = "Main.TNotebook.Tab"
        self.nb = ttk.Notebook(tabshell, style=self._main_notebook_style)

        self.nb.pack(fill="both", expand=True)

        style = ttk.Style(self)
        self._apply_main_notebook_style(style=style)

        btn_font_family = getattr(self, "_ui_font_family", base_font.actual("family"))

        btn_font_size = getattr(
            self, "_tab_font_size", max(base_font.actual("size") - 2, 8)
        )

        cycle_pad = (self._scale_length(12), self._scale_length(8))
        style.configure(
            "Cycle.TButton",
            font=(btn_font_family, btn_font_size),  # same size as tab text
            padding=cycle_pad,
        )

        # Make the hint text match the tab/button font size

        style.configure(
            "CycleHint.TLabel",
            font=(
                btn_font_family,
                btn_font_size,
            ),  # same point size as tabs & Cycle buttons
        )

        # Tabs

        self.tab_data = ttk.Frame(self.nb)

        self.tab_columns = ttk.Frame(self.nb)

        self.tab_plot = ttk.Frame(self.nb)
        self._plot_settings_tab = self.tab_plot

        self.tab_cycle = ttk.Frame(self.nb)
        self.tab_reaction_dashboard = ttk.Frame(self.nb)
        self.tab_compare = ttk.Frame(self.nb)
        self.tab_ledger = ttk.Frame(self.nb)
        self.tab_solubility_new = ttk.Frame(self.nb)
        self.tab_final_report = ttk.Frame(self.nb)

        self.nb.add(self.tab_data, text="Data")

        self.nb.add(self.tab_columns, text="Columns")

        self.nb.add(self.tab_plot, text="Plot Settings")

        self.nb.add(self.tab_cycle, text="Cycle Analysis")
        self._cycle_tab_added = True
        self.nb.add(self.tab_reaction_dashboard, text="Reaction Dashboard")

        # Build the tabs we do have now

        self._build_tab_data()

        self._build_tab_columns()

        self._build_tab_plot()
        self._update_startup_loading_splash_progress(
            progress=34.0,
            message="Building deferred Cycle Analysis layout...",
        )

        # Cycle Analysis tab builds in deferred stages to reduce startup blocking.

        self._start_cycle_tab_build(defer=True)
        self._build_tab_reaction_dashboard()
        self._update_startup_loading_splash_progress(
            progress=44.0,
            message="Building secondary analysis tabs...",
        )

        self.nb.add(self.tab_compare, text="Compare")
