    def _log_plot_tab_debug(self, message: str):
        """Emit plot tab debug output.

        Purpose:
            Send plot tab lifecycle messages to the debug logger.
        Why:
            Helps trace plot tab refresh behavior without ad-hoc prints.
        Args:
            message: Debug message describing the plot tab event.
        Returns:
            None.
        Side Effects:
            Writes to the debug logger when plotting.render is enabled.
        Exceptions:
            Best-effort guards suppress logging failures.
        """
        self._dbg("plotting.render", "%s", message)

    def _finalize_matplotlib_canvas_layout(
        self,
        *,
        canvas,
        fig,
        tk_widget=None,
        keep_export_size: bool = False,
        trigger_resize_event: bool = True,
        force_draw: bool = False,
        finalize_intent: str = "full",
    ) -> None:
        """Finalize one Matplotlib canvas layout pass with intent-aware checks.

        Purpose:
            Apply final canvas sizing, optional layout solving, and draw dispatch.
        Why:
            Refresh paths now distinguish full layout-affecting refreshes from
            lightweight no-change/elements-only refreshes to reduce redundant
            layout-manager work while preserving fail-closed safety.
        Inputs:
            canvas: Target Matplotlib canvas.
            fig: Target Matplotlib figure.
            tk_widget: Optional Tk widget associated with the canvas.
            keep_export_size: When True, preserve current figure size in inches.
            trigger_resize_event: When True, emit one canvas resize event.
            force_draw: When True, perform one blocking draw at finalize end.
            finalize_intent: Finalize policy token (`full`, `elements_only`,
                or `no_change`) used to gate expensive layout verification.
        Outputs:
            None.
        Side Effects:
            May resize figure inches, solve layout-manager constraints, run
            timeline verification checks, trigger resize events, and draw canvas.
        Exceptions:
            Best-effort guards suppress resize/layout/draw failures.
        """
        if canvas is None or fig is None:
            return
        intent_value = str(finalize_intent or "full").strip().lower()
        if intent_value not in {"full", "elements_only", "no_change"}:
            intent_value = "full"
        run_layout_solver = intent_value == "full"
        run_timeline_verification = run_layout_solver

        def _measure(widget_obj):
            """Perform measure.
            Used to keep the workflow logic localized and testable."""
            width = height = 0
            try:
                width = int(widget_obj.winfo_width())
                height = int(widget_obj.winfo_height())
            except Exception:
                width = height = 0
            if width <= 1 or height <= 1:
                try:
                    width = int(widget_obj.winfo_reqwidth())
                    height = int(widget_obj.winfo_reqheight())
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
            return max(width, 1), max(height, 1)

        widget = tk_widget
        if widget is None:
            try:
                widget = canvas.get_tk_widget()
            except Exception:
                widget = None
            if widget is not None:
                try:
                    widget.update_idletasks()
                except Exception:
                    # Best-effort guard; ignore failures.
                    pass

        if not keep_export_size and widget is not None:
            widget_w, widget_h = _measure(widget)
            try:
                dpi = float(fig.get_dpi())
                if not math.isfinite(dpi) or dpi <= 0.0:
                    dpi = 100.0
            except Exception:
                dpi = 100.0
            target_w = max(widget_w / dpi, 1.0)
            target_h = max(widget_h / dpi, 1.0)
            try:
                cur_w, cur_h = fig.get_size_inches()
            except Exception:
                cur_w, cur_h = (0.0, 0.0)
            if abs(cur_w - target_w) > 1e-2 or abs(cur_h - target_h) > 1e-2:
                try:
                    fig.set_size_inches(target_w, target_h, forward=False)
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
            if (
                str(getattr(fig, "_gl260_plot_id", "") or "").strip().lower()
                == "fig_cycle_timeline"
            ):
                try:
                    self._refresh_cycle_timeline_axis_layout_for_figure(fig)
                except Exception:
                    # Best-effort guard; ignore timeline label refresh failures.
                    pass

        needs_draw = True
        try:
            renderer = canvas.get_renderer()
            if renderer is not None:
                needs_draw = False
        except Exception:
            needs_draw = True
        if (not force_draw) and needs_draw:
            try:
                canvas.draw()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

        if run_layout_solver:
            try:
                layout_mgr = getattr(fig, "_gl260_layout_manager", None)
                plot_id_for_solver = (
                    str(getattr(fig, "_gl260_plot_id", "") or "").strip().lower()
                )
                if layout_mgr is not None:
                    if plot_id_for_solver == "fig_cycle_timeline":
                        layout_mgr.solve(max_passes=1, allow_draw=False)
                    else:
                        layout_mgr.solve()
                else:
                    layout_health_autofix(
                        fig,
                        getattr(fig, "_gl260_plot_id", None),
                        getattr(fig, "_gl260_layout_mode", "display"),
                        settings,
                    )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        plot_id = str(getattr(fig, "_gl260_plot_id", "") or "").strip().lower()
        if plot_id == "fig_cycle_timeline" and run_timeline_verification:
            try:
                layout_mode = str(
                    getattr(fig, "_gl260_layout_mode", "display") or "display"
                )
                self._run_cycle_timeline_layout_manager_verification(
                    fig,
                    mode=layout_mode,
                    prefs=self._get_cycle_plot_prefs(),
                    show_splash=False,
                )
            except Exception:
                # Best-effort guard; ignore verification failures.
                pass

        if trigger_resize_event:
            try:
                canvas.resize_event()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

        if force_draw:
            try:
                canvas.draw()
                return
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        try:
            canvas.draw_idle()
        except Exception:
            try:
                canvas.draw()
            except Exception:
                pass

    def _refresh_canvas_display(self, frame, canvas, *, trigger_resize=True):
        """Refresh canvas display.
        Used to sync canvas display with current settings."""

        try:
            self.nb.select(frame)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        # Iterate over (frame, self.nb) to apply the per-item logic.
        for widget_obj in (frame, self.nb):
            try:
                widget_obj.update_idletasks()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        widget = None
        try:
            widget = canvas.get_tk_widget()
        except Exception:
            widget = None
        if widget is not None:
            try:
                widget.update_idletasks()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        fig = getattr(canvas, "figure", None)
        if fig is None:
            if trigger_resize:
                try:
                    canvas.resize_event()
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
            try:
                canvas.draw_idle()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return

        self._finalize_matplotlib_canvas_layout(
            canvas=canvas,
            fig=fig,
            tk_widget=widget,
            keep_export_size=False,
            trigger_resize_event=trigger_resize,
            force_draw=False,
        )

    def _install_plot_loading_overlay(
        self,
        frame,
        widget,
        *,
        message: str = "Loading plot...",
        detail: Optional[str] = None,
    ) -> None:
        """Install a loading overlay over a plot canvas.

        Purpose:
            Display a blocking overlay so the initial render is hidden.
        Why:
            Initial draws and async refreshes can take noticeable time; users
            need explicit stage feedback instead of a frozen-looking tab.
        Inputs:
            frame: Plot tab frame hosting the plot.
            widget: Tk widget returned by the FigureCanvasTkAgg.
            message: Overlay text to display for the loading state.
            detail: Optional detail text shown below the primary status message.
        Outputs:
            None.
        Side Effects:
            Creates and places overlay widgets, stores overlay references on the
            frame, and starts a heartbeat update loop while loading is active.
            When startup splash is active, records deferred overlay metadata and
            returns without creating an in-tab overlay.
        Exceptions:
            Overlay creation errors are caught to avoid UI interruption.
        """
        if frame is None or widget is None:
            return
        if self._is_startup_loading_active():
            # During startup, keep one visible loading surface and defer tab overlays.
            frame._plot_loading_pending_message = str(message or "Loading plot...")
            frame._plot_loading_pending_detail = str(detail or "").strip()
            return
        frame._plot_loading_pending_message = None
        frame._plot_loading_pending_detail = None
        overlay = getattr(frame, "_plot_loading_overlay", None)
        if overlay is not None:
            try:
                if overlay.winfo_exists():
                    overlay.lift()
                    # Preserve in-flight progress when reusing an existing overlay.
                    self._update_plot_loading_overlay_progress(
                        frame,
                        message=message,
                        detail=detail,
                        stage_key="queued",
                    )
                    return
            except Exception:
                overlay = None
        try:
            base_bg = frame.cget("background")
        except Exception:
            base_bg = None
        if not base_bg:
            try:
                base_bg = self.cget("background")
            except Exception:
                base_bg = None
        try:
            overlay = tk.Frame(frame, background=base_bg)
        except Exception:
            overlay = tk.Frame(frame)
        try:
            overlay.place(
                in_=widget, relx=0.0, rely=0.0, relwidth=1.0, relheight=1.0
            )
        except Exception:
            try:
                overlay.place(relx=0.0, rely=0.0, relwidth=1.0, relheight=1.0)
            except Exception:
                return
        label = None
        detail_label = None
        progress_var = None
        progress_bar = None
        percent_label = None
        try:
            content = ttk.Frame(overlay)
            content.place(relx=0.5, rely=0.5, anchor="center")
            label = ttk.Label(
                content,
                text=str(message or "Loading plot..."),
                width=48,
                anchor="center",
                justify="center",
            )
            label.pack(side="top", pady=(0, 8))
            detail_label = ttk.Label(
                content,
                text=str(detail or ""),
                justify="center",
                anchor="center",
                wraplength=360,
                width=48,
            )
            detail_label.pack(side="top", pady=(0, 8))
            progress_var = tk.DoubleVar(master=overlay, value=0.0)
            progress_bar = ttk.Progressbar(
                content,
                mode="determinate",
                length=260,
                maximum=100.0,
                variable=progress_var,
            )
            progress_bar.pack(side="top")
            percent_label = ttk.Label(content, text="0% | 0.00s", width=48)
            percent_label.pack(side="top", pady=(6, 0))
        except Exception:
            label = None
            detail_label = None
            progress_var = None
            progress_bar = None
            percent_label = None
        try:
            overlay.lift()
        except Exception:
            # Best-effort guard; ignore failures.
            pass
        frame._plot_loading_overlay = overlay
        frame._plot_loading_label = label
        frame._plot_loading_detail_label = detail_label
        frame._plot_loading_progress_var = progress_var
        frame._plot_loading_bar = progress_bar
        frame._plot_loading_progress_label = percent_label
        frame._plot_loading_progress_value = 0.0
        frame._plot_loading_stage_key = "queued"
        frame._plot_loading_started_at = time.monotonic()
        frame._plot_loading_detail_base = str(detail or "").strip()
        self._update_plot_loading_overlay_progress(
            frame,
            progress=5.0,
            message=message,
            detail=detail,
            stage_key="queued",
            reset=True,
        )

    def _resolve_plot_loading_stage_key(
        self,
        *,
        message: Optional[str],
        stage_key: Optional[str],
    ) -> str:
        """Resolve the normalized plot loading stage key.

        Purpose:
            Map existing progress messages into stable stage identifiers.
        Why:
            Heartbeat/detail updates should remain deterministic even when older
            call sites only provide plain status text.
        Inputs:
            message: Optional human-readable stage text.
            stage_key: Optional explicit stage key from call sites.
        Outputs:
            str: Normalized stage key.
        Side Effects:
            None.
        Exceptions:
            Invalid inputs fall back to `queued`.
        """
        if isinstance(stage_key, str) and stage_key.strip():
            return stage_key.strip().lower().replace(" ", "_")
        text = str(message or "").strip().lower()
        if not text:
            return "queued"
        if "failed" in text:
            return "failed"
        if "ready" in text:
            return "ready"
        if "preparing" in text:
            return "preparing_data"
        if "data prepared" in text:
            return "worker_compute"
        if "building" in text:
            return "building_figure"
        if "installing" in text:
            return "installing"
        if "pass 2" in text:
            return "auto_refresh_pass_2"
        if "pass 1" in text:
            return "auto_refresh_pass_1"
        if "finalizing" in text or "final layout" in text:
            return "finalizing"
        if "refresh" in text:
            return "refreshing"
        return "queued"

    def _format_wall_clock_elapsed(self, elapsed_seconds: Any) -> str:
        """Format elapsed monotonic seconds for real-time splash displays.

        Purpose:
            Provide one consistent elapsed-time formatter for all loading overlays.
        Why:
            Plot, preview, and startup splash timers should present the same
            wall-clock time style without pulse-based text.
        Inputs:
            elapsed_seconds: Elapsed duration in seconds.
        Outputs:
            str: Human-readable elapsed time with sub-second precision.
        Side Effects:
            None.
        Exceptions:
            Invalid values are coerced to `0.00s`.
        """
        try:
            elapsed_value = float(elapsed_seconds)
        except Exception:
            elapsed_value = 0.0
        if not math.isfinite(elapsed_value) or elapsed_value < 0.0:
            elapsed_value = 0.0
        if elapsed_value < 60.0:
            return f"{elapsed_value:0.2f}s"
        minutes, seconds = divmod(elapsed_value, 60.0)
        if minutes < 60.0:
            return f"{int(minutes):02d}:{seconds:05.2f}"
        hours, rem_minutes = divmod(int(minutes), 60)
        return f"{hours:02d}:{rem_minutes:02d}:{seconds:05.2f}"

    def _format_loading_progress_footer(
        self,
        progress_value: Any,
        elapsed_text: str,
    ) -> str:
        """Format one loading footer as `NN% | elapsed`.

        Purpose:
            Centralize the progress-footer text used by splash/loading surfaces.
        Why:
            A single formatter keeps timers visible in one stable location and
            avoids duplicating rapidly changing elapsed text into detail labels.
        Inputs:
            progress_value: Candidate determinate progress value in percent.
            elapsed_text: Already formatted elapsed-time string.
        Outputs:
            str: Progress footer text.
        Side Effects:
            None.
        Exceptions:
            Invalid progress values are coerced to zero.
        """
        try:
            percent_value = int(round(float(progress_value)))
        except Exception:
            percent_value = 0
        percent_value = max(0, min(100, percent_value))
        return f"{percent_value}% | {str(elapsed_text or '0.00s')}"

    def _format_loading_activity_footer(self, elapsed_text: str) -> str:
        """Format an indeterminate loading footer with live elapsed time.

        Purpose:
            Provide footer text for loading surfaces that use indeterminate bars.
        Why:
            Some workflows cannot report meaningful percent completion, but the
            timer still needs to remain live and visible in the footer area.
        Inputs:
            elapsed_text: Already formatted elapsed-time string.
        Outputs:
            str: Footer text for active indeterminate work.
        Side Effects:
            None.
        Exceptions:
            Missing elapsed text falls back to `0.00s`.
        """
        return f"Working | {str(elapsed_text or '0.00s')}"

    def _format_loading_stage_label(
        self,
        *,
        stage_key: Optional[str],
        message: Optional[str] = None,
    ) -> str:
        """Normalize one loading stage label for splash-detail presentation.

        Purpose:
            Produce a stable, readable stage label shared by splash controllers.
        Why:
            Progress/detail readouts should present consistent stage wording
            across startup, plot, preview, compare, and operation overlays.
        Inputs:
            stage_key: Optional normalized stage token.
            message: Optional fallback message when stage token is unavailable.
        Outputs:
            str: Human-readable stage label.
        Side Effects:
            None.
        Exceptions:
            Invalid values fall back to "Working".
        """
        normalized_stage = str(stage_key or "").strip().lower().replace(" ", "_")
        if normalized_stage:
            pieces = [piece for piece in normalized_stage.split("_") if piece]
            if pieces:
                return " ".join(piece.capitalize() for piece in pieces)
        message_text = str(message or "").strip()
        if message_text:
            compact = message_text.rstrip(".")
            if compact:
                return compact
        return "Working"

    def _resolve_loading_detail_base(
        self,
        *,
        current_detail_base: Any,
        stage_key: Optional[str],
        message: Optional[str],
        detail: Optional[str],
        clear_on_message: bool = True,
    ) -> str:
        """Resolve one splash detail-base message with stale-detail clearing.

        Purpose:
            Centralize detail text resolution for loading/splash controllers.
        Why:
            Without a shared resolver, stale detail text can persist across
            stage-message transitions and make progress readouts look frozen.
        Inputs:
            current_detail_base: Existing detail-base text cached by caller.
            stage_key: Optional normalized stage token for fallback text.
            message: Optional stage/status message.
            detail: Optional explicit detail payload.
            clear_on_message: When True, clears prior detail when message
                changes and no explicit detail is provided.
        Outputs:
            str: Resolved detail-base text before elapsed suffix composition.
        Side Effects:
            None.
        Exceptions:
            Invalid values are normalized to safe string defaults.
        """
        if detail is not None:
            resolved = str(detail).strip()
            if resolved:
                return resolved
        if clear_on_message and message is not None:
            return f"Stage: {self._format_loading_stage_label(stage_key=stage_key, message=message)}."
        existing = str(current_detail_base or "").strip()
        if existing:
            return existing
        return f"Stage: {self._format_loading_stage_label(stage_key=stage_key, message=message)}."

    def _compose_loading_detail_with_elapsed(
        self,
        *,
        detail_base: Any,
        stage_key: Optional[str],
        message: Optional[str],
        elapsed_text: str,
    ) -> str:
        """Compose stable splash detail text without footer timer duplication.

        Purpose:
            Build one consistent detail line for all splash/overlay controllers.
        Why:
            The live timer belongs in the progress footer; keeping detail text
            stable prevents repeated repainting from leaving stale status glyphs.
        Inputs:
            detail_base: Caller-resolved detail baseline text.
            stage_key: Optional normalized stage token.
            message: Optional stage/status message.
            elapsed_text: Formatted elapsed-time text, accepted for caller
                compatibility but intentionally not included in the detail line.
        Outputs:
            str: Detail text with a readable stage/detail baseline.
        Side Effects:
            None.
        Exceptions:
            Missing detail base falls back to a normalized stage label.
        """
        _ = elapsed_text
        base_text = str(detail_base or "").strip()
        if not base_text:
            base_text = self._resolve_loading_detail_base(
                current_detail_base="",
                stage_key=stage_key,
                message=message,
                detail=None,
                clear_on_message=False,
            )
        return base_text

    def _stop_plot_loading_overlay_heartbeat(self, frame) -> None:
        """Stop one plot loading overlay heartbeat timer.

        Purpose:
            Cancel the periodic heartbeat status updates for an overlay.
        Why:
            Overlay teardown and terminal states must not leave orphan timers.
        Inputs:
            frame: Plot tab frame owning heartbeat timer metadata.
        Outputs:
            None.
        Side Effects:
            Cancels the frame's scheduled `after` callback when present.
        Exceptions:
            Callback cancellation failures are ignored by design.
        """
        if frame is None:
            return
        after_id = getattr(frame, "_plot_loading_heartbeat_after_id", None)
        if after_id is None:
            return
        try:
            self.after_cancel(after_id)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        frame._plot_loading_heartbeat_after_id = None

    def _start_plot_loading_overlay_heartbeat(self, frame) -> None:
        """Start one plot loading overlay heartbeat timer.

        Purpose:
            Keep overlay detail text active during long compute phases.
        Why:
            Background rendering can look frozen unless elapsed activity is shown.
        Inputs:
            frame: Plot tab frame owning overlay state.
        Outputs:
            None.
        Side Effects:
            Schedules recurring `after` callbacks while loading remains active and
            updates the overlay detail label with real-time wall-clock elapsed text.
        Exceptions:
            Missing/destroyed widgets short-circuit safely.
        """
        if frame is None:
            return
        if getattr(frame, "_plot_loading_heartbeat_after_id", None) is not None:
            return

        def _tick() -> None:
            """Update one heartbeat detail cycle for the active overlay."""
            frame._plot_loading_heartbeat_after_id = None
            overlay = getattr(frame, "_plot_loading_overlay", None)
            if overlay is None:
                return
            try:
                if not overlay.winfo_exists():
                    return
            except Exception:
                return
            stage_key = str(getattr(frame, "_plot_loading_stage_key", "queued") or "queued")
            if stage_key in {"ready", "failed"}:
                return
            started_at = getattr(frame, "_plot_loading_started_at", None)
            if not isinstance(started_at, (int, float)):
                started_at = time.monotonic()
                frame._plot_loading_started_at = started_at
            elapsed = max(0.0, time.monotonic() - float(started_at))
            elapsed_text = self._format_wall_clock_elapsed(elapsed)
            base_detail = str(getattr(frame, "_plot_loading_detail_base", "") or "").strip()
            composed = self._compose_loading_detail_with_elapsed(
                detail_base=base_detail,
                stage_key=stage_key,
                message=None,
                elapsed_text=elapsed_text,
            )
            detail_label = getattr(frame, "_plot_loading_detail_label", None)
            if detail_label is not None:
                try:
                    detail_label.configure(text=composed)
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
            progress_label = getattr(frame, "_plot_loading_progress_label", None)
            if progress_label is not None:
                try:
                    progress_value = float(
                        getattr(frame, "_plot_loading_progress_value", 0.0) or 0.0
                    )
                except Exception:
                    progress_value = 0.0
                try:
                    progress_label.configure(
                        text=self._format_loading_progress_footer(
                            progress_value,
                            elapsed_text,
                        )
                    )
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
            try:
                frame._plot_loading_heartbeat_after_id = self.after(80, _tick)
            except Exception:
                frame._plot_loading_heartbeat_after_id = None

        _tick()

    def _clear_plot_loading_overlay(self, frame) -> None:
        """Clear a plot loading overlay if present.

        Purpose:
            Remove the blocking overlay once the stable render is ready.
        Why:
            Users should only see the final, correctly scaled plot.
        Inputs:
            frame: Plot tab frame hosting the plot.
        Outputs:
            None.
        Side Effects:
            Stops heartbeat timers, destroys overlay widgets, and clears stored
            references and pending overlay metadata.
        Exceptions:
            Overlay removal errors are guarded to keep the UI responsive.
        """
        if frame is None:
            return
        self._stop_plot_loading_overlay_heartbeat(frame)
        overlay = getattr(frame, "_plot_loading_overlay", None)
        if overlay is not None:
            try:
                overlay.place_forget()
            except Exception:
                # Best-effort guard; ignore failures.
                pass
            try:
                overlay.destroy()
            except Exception:
                # Best-effort guard; ignore failures.
                pass
        frame._plot_loading_overlay = None
        frame._plot_loading_label = None
        frame._plot_loading_detail_label = None
        frame._plot_loading_progress_var = None
        frame._plot_loading_bar = None
        frame._plot_loading_progress_label = None
        frame._plot_loading_progress_value = 0.0
        frame._plot_loading_stage_key = "ready"
        frame._plot_loading_started_at = None
        frame._plot_loading_detail_base = ""
        frame._plot_loading_pending_message = None
        frame._plot_loading_pending_detail = None

    def _update_plot_loading_overlay_progress(
        self,
        frame,
        *,
        progress: Optional[float] = None,
        message: Optional[str] = None,
        detail: Optional[str] = None,
        stage_key: Optional[str] = None,
        reset: bool = False,
    ) -> None:
        """Update one plot splash overlay with deterministic progress milestones.

        Purpose:
            Keep loading-overlay message, detail text, and progress synchronized
            with async plot-render milestones.
        Why:
            Core/combined render orchestration can fire callbacks out of order;
            monotonic progress and heartbeat updates prevent frozen-looking UI.
        Inputs:
            frame: Plot tab frame owning the active loading overlay widgets.
            progress: Optional new progress value in the 0..100 range.
            message: Optional overlay status text.
            detail: Optional detail text displayed under status message.
            stage_key: Optional normalized stage key for heartbeat behavior.
            reset: When True, resets tracked progress before applying updates.
        Outputs:
            None.
        Side Effects:
            Mutates overlay text/progress widgets, updates frame progress cache,
            and starts/stops heartbeat timers based on terminal stage states.
        Exceptions:
            Best-effort behavior; missing widgets are ignored.
        """
        if frame is None:
            return
        overlay = getattr(frame, "_plot_loading_overlay", None)
        if overlay is None:
            if self._is_startup_loading_active():
                if message is not None:
                    frame._plot_loading_pending_message = str(message)
                if detail is not None:
                    frame._plot_loading_pending_detail = str(detail)
            return
        try:
            if not overlay.winfo_exists():
                return
        except Exception:
            return
        if reset:
            try:
                frame._plot_loading_progress_value = 0.0
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            frame._plot_loading_started_at = time.monotonic()
            frame._plot_loading_detail_base = ""
        current_value = getattr(frame, "_plot_loading_progress_value", 0.0)
        try:
            current_value = float(current_value)
        except Exception:
            current_value = 0.0
        if not math.isfinite(current_value):
            current_value = 0.0
        target_value = current_value
        if progress is not None:
            try:
                candidate = float(progress)
            except Exception:
                candidate = current_value
            if not math.isfinite(candidate):
                candidate = current_value
            candidate = max(0.0, min(100.0, candidate))
            # Keep progress monotonic unless the caller explicitly requests reset.
            target_value = candidate if reset else max(current_value, candidate)
        normalized_stage = self._resolve_plot_loading_stage_key(
            message=message,
            stage_key=stage_key,
        )
        frame._plot_loading_stage_key = normalized_stage
        label = getattr(frame, "_plot_loading_label", None)
        if label is not None and message is not None:
            try:
                label.configure(text=str(message))
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        detail_base = self._resolve_loading_detail_base(
            current_detail_base=getattr(frame, "_plot_loading_detail_base", ""),
            stage_key=normalized_stage,
            message=message,
            detail=detail,
            clear_on_message=True,
        )
        frame._plot_loading_detail_base = detail_base
        detail_label = getattr(frame, "_plot_loading_detail_label", None)
        started_at = getattr(frame, "_plot_loading_started_at", None)
        if not isinstance(started_at, (int, float)):
            started_at = time.monotonic()
            frame._plot_loading_started_at = started_at
        elapsed_text = self._format_wall_clock_elapsed(
            max(0.0, time.monotonic() - float(started_at))
        )
        detail_text = self._compose_loading_detail_with_elapsed(
            detail_base=detail_base,
            stage_key=normalized_stage,
            message=message,
            elapsed_text=elapsed_text,
        )
        if detail_label is not None:
            try:
                detail_label.configure(text=detail_text)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        progress_var = getattr(frame, "_plot_loading_progress_var", None)
        if progress_var is not None:
            try:
                progress_var.set(float(target_value))
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        progress_bar = getattr(frame, "_plot_loading_bar", None)
        if progress_bar is not None:
            try:
                progress_bar.configure(value=float(target_value), maximum=100.0)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        percent_label = getattr(frame, "_plot_loading_progress_label", None)
        if percent_label is not None:
            try:
                percent_label.configure(
                    text=self._format_loading_progress_footer(
                        target_value,
                        elapsed_text,
                    )
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        try:
            frame._plot_loading_progress_value = float(target_value)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        if normalized_stage in {"ready", "failed"}:
            if isinstance(started_at, (int, float)):
                elapsed_value = max(0.0, time.monotonic() - float(started_at))
                elapsed_text = self._format_wall_clock_elapsed(elapsed_value)
                final_detail = self._compose_loading_detail_with_elapsed(
                    detail_base=getattr(frame, "_plot_loading_detail_base", ""),
                    stage_key=normalized_stage,
                    message=message,
                    elapsed_text=elapsed_text,
                )
                if detail_label is not None:
                    try:
                        detail_label.configure(text=final_detail)
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting the workflow.
                        pass
                if percent_label is not None:
                    try:
                        percent_label.configure(
                            text=self._format_loading_progress_footer(
                                target_value,
                                elapsed_text,
                            )
                        )
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting the workflow.
                        pass
            self._stop_plot_loading_overlay_heartbeat(frame)
        else:
            self._start_plot_loading_overlay_heartbeat(frame)
        try:
            overlay.lift()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _schedule_plot_auto_refresh(self, frame, canvas) -> None:
        """Schedule the one-time plot auto refresh after initial render.

        Purpose:
            Trigger a programmatic refresh using the same path as the Refresh button.
        Why:
            The refresh path applies stable geometry, ensuring the first visible
            render matches the manual Refresh output. Combined plots additionally
            require a second forced refresh pass before the overlay is cleared.
        Inputs:
            frame: Plot tab frame hosting the plot.
            canvas: FigureCanvasTkAgg displaying the figure.
        Outputs:
            None.
        Side Effects:
            Updates auto-refresh state, seeds combined refresh phase tracking,
            schedules an idle callback, and invokes refresh.
        Exceptions:
            Errors are caught to avoid UI interruption.
        """
        if frame is None or canvas is None:
            return
        if not getattr(frame, "_plot_auto_refresh_enabled", True):
            return
        state = getattr(frame, "_plot_auto_refresh_state", None)
        # Only schedule once per tab creation to prevent refresh recursion.
        if state not in (None, "pending"):
            return
        if not getattr(frame, "_plot_initial_render_complete", False):
            return
        plot_key = getattr(frame, "_plot_key", None)
        frame._plot_auto_refresh_state = "scheduled"
        if plot_key == "fig_combined":
            self._log_plot_tab_debug("Combined auto-refresh scheduled.")
            # Combined plots begin with phase 1; phase 2 is preference/decision driven.
            frame._plot_auto_refresh_phase = 1
        else:
            frame._plot_auto_refresh_phase = None
        after_id = getattr(frame, "_plot_auto_refresh_after_id", None)
        # Avoid duplicate idle callbacks if one is already queued.
        if after_id is not None:
            return

        def _run():
            """Trigger the plot auto refresh once layout is idle.

            Purpose:
                Enter the auto-refresh phase and invoke the shared refresh path.
            Why:
                Plot refreshes must use the manual refresh path for stable sizing.
            Inputs:
                None.
            Outputs:
                None.
            Side Effects:
                Updates auto-refresh state and rebuilds the plot.
            Exceptions:
                Errors are caught to avoid breaking the UI loop.
            """
            frame._plot_auto_refresh_after_id = None
            if getattr(frame, "_plot_auto_refresh_state", None) != "scheduled":
                return
            try:
                if not frame.winfo_exists():
                    self._clear_plot_loading_overlay(frame)
                    return
            except Exception:
                return
            try:
                widget = canvas.get_tk_widget()
                if widget is not None and not widget.winfo_exists():
                    self._clear_plot_loading_overlay(frame)
                    return
            except Exception:
                # Best-effort guard; ignore failures.
                pass
            frame._plot_auto_refresh_state = "refreshing"
            frame._plot_auto_refresh_in_progress = True
            # Use the same refresh path as the Refresh button.
            self._force_plot_refresh(frame, canvas, capture_combined_legend=True)

        try:
            frame._plot_auto_refresh_after_id = self.after_idle(_run)
        except Exception:
            _run()

    def _complete_plot_auto_refresh(self, frame) -> None:
        """Complete the plot auto refresh and reveal the plot.

        Purpose:
            Finalize auto refresh state and remove the loading overlay.
        Why:
            Ensures the first visible plot uses the refresh path output. Combined
            plots can run one or two refresh passes depending on adaptive decision
            signals and Plot Render Settings overrides before reveal.
        Inputs:
            frame: Plot tab frame hosting the plot.
        Outputs:
            None.
        Side Effects:
            Updates auto-refresh state, optionally schedules a second refresh
            pass for combined plots, and clears the loading overlay on completion.
        Exceptions:
            Errors are caught to avoid UI interruption.
        """
        if frame is None:
            return
        plot_key = getattr(frame, "_plot_key", None)
        if plot_key in {"fig1", "fig2"} and bool(
            getattr(frame, "_core_overlay_hold", False)
        ):
            self._finalize_core_overlay(frame)
            return
        if getattr(frame, "_plot_auto_refresh_state", None) != "refreshing":
            return
        phase = getattr(frame, "_plot_auto_refresh_phase", None)
        after_id = getattr(frame, "_plot_auto_refresh_after_id", None)
        if plot_key == "fig_combined":
            second_refresh_disabled = self._combined_second_refresh_disabled()
            if phase == 1:
                if second_refresh_disabled:
                    frame._plot_auto_refresh_phase = None
                    self._log_plot_tab_debug(
                        "Combined auto-refresh phase 2 skipped by Plot Render Settings."
                    )
                else:
                    frame._plot_auto_refresh_phase = 2

                    def _run_second_pass():
                        """Trigger the second combined refresh pass before reveal.

                        Purpose:
                            Run the same refresh path a second time for combined plots.
                        Why:
                            Combined layouts need two passes to fully stabilize margins.
                        Inputs:
                            None.
                        Outputs:
                            None.
                        Side Effects:
                            Invokes the shared refresh path and keeps the overlay visible.
                        Exceptions:
                            Errors are caught to avoid breaking the UI loop.
                        """
                        frame._plot_auto_refresh_after_id = None
                        if getattr(frame, "_plot_auto_refresh_state", None) != "refreshing":
                            return
                        if getattr(frame, "_plot_auto_refresh_phase", None) != 2:
                            return
                        try:
                            if not frame.winfo_exists():
                                self._clear_plot_loading_overlay(frame)
                                return
                        except Exception:
                            return
                        _, canvas = self._find_plot_tab_canvas(plot_key)
                        if canvas is None:
                            # Fail closed: avoid leaving the overlay stuck if the canvas
                            # is gone.
                            frame._plot_auto_refresh_state = "done"
                            frame._plot_auto_refresh_after_id = None
                            frame._plot_auto_refresh_in_progress = False
                            frame._plot_auto_refresh_phase = None
                            self._clear_plot_loading_overlay(frame)
                            return
                        # Use the same refresh path as the Refresh button.
                        self._force_plot_refresh(
                            frame,
                            canvas,
                            capture_combined_legend=True,
                        )

                    try:
                        frame._plot_auto_refresh_after_id = self.after_idle(
                            _run_second_pass
                        )
                    except Exception:
                        _run_second_pass()
                    return
            if phase == 2 and after_id is not None:
                # Second pass is queued; keep the overlay until it completes.
                return
            hold_overlay = bool(
                getattr(frame, "_post_first_draw_refresh_hold_overlay", False)
            )
            if hold_overlay:
                active_fig = self._resolve_combined_overlay_figure(frame)
                active_fig_id = id(active_fig) if active_fig is not None else None
                pending_apply = bool(
                    getattr(self, "_combined_cycle_legend_pending_apply", False)
                )
                pending_apply_fig_id = getattr(
                    self, "_combined_cycle_legend_pending_fig_id", None
                )
                pending_apply_for_active = pending_apply and (
                    active_fig_id is None or pending_apply_fig_id == active_fig_id
                )
                pending_completion_draw = bool(
                    getattr(frame, "_combined_overlay_completion_draw_pending", False)
                )
                pending_completion_fig_id = getattr(
                    frame, "_combined_overlay_completion_fig_id", None
                )
                pending_completion_for_active = pending_completion_draw and (
                    active_fig_id is None
                    or pending_completion_fig_id is None
                    or pending_completion_fig_id == active_fig_id
                )
                redraw_queued = bool(
                    getattr(active_fig, "_cycle_legend_redraw_queued", False)
                    if active_fig is not None
                    else False
                )
                if (
                    pending_apply_for_active
                    or pending_completion_for_active
                    or redraw_queued
                ):
                    self._log_plot_tab_debug(
                        "Combined auto-refresh completion deferred; hold=%s pending_apply=%s pending_draw_ack=%s redraw_queued=%s."
                        % (
                            hold_overlay,
                            pending_apply_for_active,
                            pending_completion_for_active,
                            redraw_queued,
                        )
                    )
                    return
        # Mark completion so the auto-refresh only runs once.
        frame._plot_auto_refresh_state = "done"
        frame._plot_auto_refresh_after_id = None
        frame._plot_auto_refresh_in_progress = False
        frame._plot_auto_refresh_phase = None
        if plot_key == "fig_combined":
            self._log_plot_tab_debug(
                "Combined auto-refresh complete; clearing loading overlay."
            )
        self._update_plot_loading_overlay_progress(
            frame,
            progress=100.0,
            message="Plot ready.",
            stage_key="ready",
        )
        self._clear_plot_loading_overlay(frame)

    def _finalize_combined_plot_display(
        self,
        frame,
        canvas,
        *,
        placement_state: dict[str, Any] | None = None,
    ) -> None:
        """Finalize the combined plot display with a deferred single-pass draw.

        Purpose:
            Apply final sizing, legend anchors, and tracking before drawing the
            combined plot once, then schedule the auto refresh if needed.
        Why:
            Combined plots depend on stable geometry; deferring avoids an initial
            incorrect render, and the auto refresh aligns with the manual Refresh
            render path before the overlay is removed.
        Inputs:
            frame: Plot tab frame hosting the combined plot.
            canvas: FigureCanvasTkAgg bound to the combined figure.
            placement_state: Optional plot element placement state to restore.
        Outputs:
            None.
        Side Effects:
            Defers render until widget geometry is ready, applies display layout
            settings and plot elements, restores legend anchors, registers drag
            tracking, retargets annotation controllers, triggers a single
            draw_idle, and defers the one-shot combined refresh until the first
            draw_event can invoke the manual Refresh callback. When completing a
            forced refresh, synchronously finalizes layout before deferring
            overlay removal to the post-refresh draw handler.
        Exceptions:
            Errors are caught defensively to keep UI workflows responsive.
        """
        if canvas is None:
            return
        fig = getattr(canvas, "figure", None)
        if fig is None:
            return
        plot_key = getattr(frame, "_plot_key", None)
        plot_id = getattr(frame, "_plot_id", None)
        if placement_state is None and plot_id:
            placement_state = self._capture_plot_element_placement_state(plot_id)
        widget = None
        try:
            widget = canvas.get_tk_widget()
        except Exception:
            widget = None
        if widget is not None:
            try:
                widget.update_idletasks()
            except Exception:
                # Best-effort guard; ignore failures.
                pass
            try:
                width_px = int(widget.winfo_width())
                height_px = int(widget.winfo_height())
            except Exception:
                width_px = 0
                height_px = 0
            if width_px <= 2 or height_px <= 2:
                # Defer finalization until geometry readiness is signaled by Tk.
                wait_state = (
                    getattr(frame, "_combined_finalize_geometry_wait", None)
                    if frame is not None
                    else None
                )
                if isinstance(wait_state, dict) and bool(wait_state.get("active")):
                    return

                next_wait_state: Dict[str, Any] = {
                    "active": True,
                    "frame_bind_id": None,
                    "widget_bind_id": None,
                    "timeout_after_id": None,
                }
                try:
                    if frame is not None:
                        frame._combined_finalize_geometry_wait = next_wait_state
                except Exception:
                    # Best-effort guard; ignore failures.
                    pass

                def _cleanup_waiters() -> None:
                    """Clean up temporary combined-finalize geometry wait handlers.

                    Purpose:
                        Remove one-shot callbacks used while waiting for geometry.
                    Why:
                        Cleanup avoids duplicate resume attempts and stale binds.
                    Inputs:
                        None.
                    Outputs:
                        None.
                    Side Effects:
                        Unbinds configure callbacks, cancels timeout callback, and
                        clears frame wait-state markers.
                    Exceptions:
                        Cleanup errors are ignored to keep UI flow resilient.
                    """
                    frame_bind_id = next_wait_state.get("frame_bind_id")
                    widget_bind_id = next_wait_state.get("widget_bind_id")
                    timeout_after_id = next_wait_state.get("timeout_after_id")
                    if frame_bind_id and frame is not None:
                        try:
                            frame.unbind("<Configure>", frame_bind_id)
                        except Exception:
                            # Best-effort guard; ignore failures.
                            pass
                    if widget_bind_id:
                        try:
                            widget.unbind("<Configure>", widget_bind_id)
                        except Exception:
                            # Best-effort guard; ignore failures.
                            pass
                    if timeout_after_id is not None:
                        try:
                            self.after_cancel(timeout_after_id)
                        except Exception:
                            # Best-effort guard; ignore failures.
                            pass
                    next_wait_state["active"] = False
                    if frame is not None:
                        try:
                            frame._combined_finalize_geometry_wait = None
                        except Exception:
                            # Best-effort guard; ignore failures.
                            pass

                def _resume_finalize(reason: str) -> None:
                    """Resume combined finalize flow after readiness or timeout.

                    Purpose:
                        Continue combined finalization once wait conditions resolve.
                    Why:
                        Finalization should continue immediately on readiness but
                        still fail-safe when readiness never arrives.
                    Inputs:
                        reason: Resume trigger source (`ready` or `timeout`).
                    Outputs:
                        None.
                    Side Effects:
                        Clears wait state and re-enters `_finalize_combined_plot_display`.
                    Exceptions:
                        Errors fall back to direct finalize invocation.
                    """
                    if not bool(next_wait_state.get("active")):
                        return
                    _cleanup_waiters()
                    if reason == "timeout":
                        self._log_plot_tab_debug(
                            "Combined finalize geometry wait timed out; proceeding with fallback sizing."
                        )
                    try:
                        self.after_idle(
                            lambda: self._finalize_combined_plot_display(
                                frame,
                                canvas,
                                placement_state=placement_state,
                            )
                        )
                    except Exception:
                        self._finalize_combined_plot_display(
                            frame,
                            canvas,
                            placement_state=placement_state,
                        )

                def _on_geometry_signal(_event: Any = None) -> None:
                    """Handle geometry events while waiting to finalize combined plot.

                    Purpose:
                        Probe live widget size on configure/idle notifications.
                    Why:
                        Combined finalization should react to real geometry readiness.
                    Inputs:
                        _event: Optional Tk event payload.
                    Outputs:
                        None.
                    Side Effects:
                        Triggers deferred finalize resume when geometry is usable.
                    Exceptions:
                        Probe failures are ignored and readiness remains pending.
                    """
                    try:
                        widget.update_idletasks()
                    except Exception:
                        # Best-effort guard; ignore failures.
                        pass
                    try:
                        ready_width = int(widget.winfo_width())
                        ready_height = int(widget.winfo_height())
                    except Exception:
                        ready_width = 0
                        ready_height = 0
                    if ready_width > 2 and ready_height > 2:
                        _resume_finalize("ready")

                try:
                    if frame is not None:
                        next_wait_state["frame_bind_id"] = frame.bind(
                            "<Configure>", _on_geometry_signal, add="+"
                        )
                except Exception:
                    next_wait_state["frame_bind_id"] = None
                try:
                    next_wait_state["widget_bind_id"] = widget.bind(
                        "<Configure>", _on_geometry_signal, add="+"
                    )
                except Exception:
                    next_wait_state["widget_bind_id"] = None
                try:
                    self.after_idle(_on_geometry_signal)
                except Exception:
                    _on_geometry_signal()
                try:
                    next_wait_state["timeout_after_id"] = self.after(
                        350, lambda: _resume_finalize("timeout")
                    )
                except Exception:
                    _resume_finalize("timeout")
                return

        def _render():
            """Perform deferred combined render.

            Purpose:
                Apply final geometry and legend anchoring before the single draw.
            Why:
                Combined plots must render once with final DPI/size and anchors.
            Inputs:
                None.
            Outputs:
                None.
            Side Effects:
                Updates figure size/DPI, applies anchors, registers legend tracking,
                restores placement state, and schedules draw_idle.
            Exceptions:
                Errors are caught to keep the UI responsive.
            """
            finalize_start = time.perf_counter()
            perf_run = getattr(frame, "_combined_perf_run", None)
            try:
                dpi = float(getattr(fig, "dpi", plt.rcParams.get("figure.dpi", 100.0)))
                if not math.isfinite(dpi) or dpi <= 0.0:
                    dpi = 100.0
            except Exception:
                dpi = 100.0
            target_width = None
            target_height = None
            if widget is not None:
                try:
                    widget.update_idletasks()
                except Exception:
                    # Best-effort guard; ignore failures.
                    pass
                try:
                    target_width = max(int(widget.winfo_width()), 1)
                    target_height = max(int(widget.winfo_height()), 1)
                except Exception:
                    target_width = None
                    target_height = None
            if target_width is None or target_height is None:
                try:
                    fig_size = self._compute_target_figsize_inches()
                except Exception:
                    fig_size = (11.0, 8.5)
                target_width = max(int(fig_size[0] * dpi), 1)
                target_height = max(int(fig_size[1] * dpi), 1)
            try:
                fig.set_dpi(dpi)
                fig.set_size_inches(
                    max(target_width / dpi, 1.0),
                    max(target_height / dpi, 1.0),
                    forward=False,
                )
            except Exception:
                # Best-effort guard; ignore failures.
                pass
            if plot_id:
                try:
                    self._update_plot_loading_overlay_progress(
                        frame,
                        progress=82.0,
                        message="Adding Plot Elements...",
                        stage_key="finalizing",
                    )
                    self._apply_display_settings_for_plot(fig, plot_id, canvas)
                except Exception:
                    # Best-effort guard; ignore failures.
                    pass
            try:
                self._apply_combined_saved_legend_anchors(fig)
            except Exception:
                # Best-effort guard; ignore failures.
                pass
            try:
                self._register_combined_legend_tracking(
                    fig,
                    force_draw=False,
                    defer_saved_anchor=False,
                )
            except Exception:
                # Best-effort guard; ignore failures.
                pass
            if plot_id and placement_state:
                try:
                    self._restore_plot_element_placement_state(plot_id, placement_state)
                except Exception:
                    # Best-effort guard; ignore failures.
                    pass
            try:
                frame._combined_render_ready = True
            except Exception:
                # Best-effort guard; ignore failures.
                pass
            was_initial_render = not getattr(
                frame, "_plot_initial_render_complete", False
            )
            draw_succeeded = False
            try:
                canvas.draw_idle()
                draw_succeeded = True
            except Exception:
                # Best-effort guard; ignore failures.
                pass
            if draw_succeeded and was_initial_render:
                try:
                    frame._plot_initial_render_complete = True
                except Exception:
                    # Best-effort guard; ignore failures.
                    pass
                auto_state = getattr(frame, "_plot_auto_refresh_state", None)
                if auto_state == "refreshing":
                    # Reset initial render state so auto-refresh scheduling can run.
                    frame._plot_auto_refresh_state = "pending"
                    frame._plot_auto_refresh_in_progress = False
                    frame._plot_auto_refresh_after_id = None
                if plot_key == "fig_combined":
                    # Combined plots refresh after the first draw_event; keep
                    # overlay state pending until that callback runs.
                    frame._plot_auto_refresh_state = "pending"
                    frame._plot_auto_refresh_in_progress = False
                    frame._plot_auto_refresh_after_id = None
                else:
                    self._schedule_plot_auto_refresh(frame, canvas)
            auto_state = getattr(frame, "_plot_auto_refresh_state", None)
            if auto_state == "refreshing" and not was_initial_render:
                # Apply the same finalize/draw logic as manual Refresh before revealing.
                hold_combined_overlay = bool(
                    plot_key == "fig_combined"
                    and getattr(frame, "_post_first_draw_refresh_hold_overlay", False)
                )
                if hold_combined_overlay:
                    try:
                        # Require one draw-confirmed acknowledgement for this refreshed figure.
                        frame._combined_overlay_completion_draw_pending = True
                        frame._combined_overlay_completion_fig_id = id(fig)
                    except Exception:
                        # Best-effort guard; ignore failures.
                        pass
                    self._log_plot_tab_debug(
                        "Combined refresh finalize armed draw-ack for fig_id=%s."
                        % id(fig)
                    )
                try:
                    self._update_plot_loading_overlay_progress(
                        frame,
                        progress=92.0,
                        message="Final Layout Adjustments...",
                        stage_key="finalizing",
                    )
                    self._finalize_matplotlib_canvas_layout(
                        canvas=canvas,
                        fig=fig,
                        tk_widget=widget,
                        keep_export_size=False,
                        trigger_resize_event=True,
                        force_draw=True,
                    )
                except Exception:
                    # Best-effort guard; ignore failures.
                    pass
                if hold_combined_overlay:
                    # Defer overlay removal for combined until the post-refresh draw.
                    frame._plot_auto_refresh_state = "pending"
                    frame._plot_auto_refresh_in_progress = False
                    frame._plot_auto_refresh_after_id = None
                    frame._plot_auto_refresh_phase = None
                else:
                    # Auto refresh completed; reveal the stabilized render.
                    self._complete_plot_auto_refresh(frame)
            if isinstance(perf_run, dict):
                stages = perf_run.setdefault("stages", {})
                combined_stage = stages.setdefault("combined", {})
                combined_stage["finalize_ms"] = (
                    time.perf_counter() - finalize_start
                ) * 1000.0

        self._with_loading_cursor(_render, widget=widget)

    def _finalize_plot_refresh(self, canvas, fig) -> None:
        """Refresh value.
        Used by finalize plot workflows to refresh value."""
        if canvas is None or fig is None:
            return
        try:
            layout_mgr = getattr(fig, "_gl260_layout_manager", None)
            if layout_mgr is not None:
                layout_mgr.solve()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            canvas.resize_event()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            canvas.draw()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _install_refreshed_figure_and_finalize(
        self, frame, canvas, new_fig, *, plot_id: Optional[str] = None
    ) -> None:
        """Install a refreshed figure on the canvas and finalize display.

        Purpose:
            Attach a new figure to the existing canvas and complete the
            display finalization for a refreshed plot.
        Why:
            Async render installs must bind the final figure before refresh
            so layout profiles and plot elements apply to the correct figure.
        Inputs:
            frame: Plot tab frame hosting the canvas.
            canvas: FigureCanvasTkAgg instance to update.
            new_fig: Rendered Matplotlib Figure to install.
            plot_id: Optional plot identifier for applying display settings.
        Outputs:
            None.
        Side Effects:
            Attaches the figure to the canvas, applies display settings,
            updates refresh progress stages for plot elements/final layout,
            triggers canvas resize/draw, and finalizes layout.
        Exceptions:
            Errors are caught to avoid interrupting UI workflows.
        """
        if canvas is None or new_fig is None:
            return
        self._log_plot_tab_debug("Installing refreshed figure onto canvas.")
        widget = None
        try:
            widget = canvas.get_tk_widget()
        except Exception:
            widget = None
        try:
            new_fig.set_canvas(canvas)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            canvas.figure = new_fig
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        if plot_id:
            try:
                self._update_plot_loading_overlay_progress(
                    frame,
                    progress=82.0,
                    message="Adding Plot Elements...",
                    stage_key="finalizing",
                )
                self._apply_display_settings_for_plot(new_fig, plot_id, canvas)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        try:
            self._update_plot_loading_overlay_progress(
                frame,
                progress=92.0,
                message="Final Layout Adjustments...",
                stage_key="finalizing",
            )
            self._finalize_matplotlib_canvas_layout(
                canvas=canvas,
                fig=new_fig,
                tk_widget=widget,
                keep_export_size=False,
                trigger_resize_event=True,
                force_draw=True,
            )
            self._log_plot_tab_debug(
                "Refreshed figure: deterministic finalize complete."
            )
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            canvas.draw_idle()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _install_rendered_plot_in_tab(
        self,
        frame,
        canvas,
        plot_key: str,
        fig: Figure,
        *,
        placement_state: dict[str, Any] | None = None,
    ) -> None:
        """Install a rendered figure into an existing plot tab.

        Purpose:
            Swap a newly rendered figure into its target tab/canvas.
        Why:
            Async rendering must reuse tabs to keep UI state and overlays intact.
        Inputs:
            frame: Plot tab frame hosting the canvas.
            canvas: FigureCanvasTkAgg instance to update.
            plot_key: Plot key identifier (e.g., "fig1", "fig_combined").
            fig: Rendered Matplotlib Figure to install.
            placement_state: Optional plot element placement state to restore.
        Outputs:
            None.
        Side Effects:
            Updates figure bindings, refreshes canvas display, retargets plot
            annotations, restores placement state, updates dirty flags, and
            clears loading overlays when auto-refresh is not pending/scheduled.
        Exceptions:
            Errors are caught to avoid interrupting UI workflows.
        """
        if frame is None or canvas is None or fig is None:
            return
        plot_id = self._plot_key_to_plot_id(plot_key)
        if not plot_id:
            plot_id = getattr(frame, "_plot_id", None)
        is_core_key = plot_key in {"fig1", "fig2"}
        if plot_id:
            try:
                self._teardown_layout_editor(plot_id, apply_changes=False)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        if is_core_key:
            was_real_core = bool(getattr(frame, "_core_real_figure_installed", False))
            is_real_core = self._is_real_core_figure(fig)
            overlay_exists = bool(
                getattr(frame, "_plot_loading_overlay", None) is not None
            )
            try:
                frame._core_real_figure_installed = is_real_core
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            if is_real_core and not was_real_core and overlay_exists:
                try:
                    frame._core_overlay_refresh_invoked_count = 0
                    frame._core_overlay_refresh_completed_count = 0
                    frame._core_overlay_layout_sig_baseline = None
                    frame._core_overlay_need_second_refresh = True
                    frame._core_overlay_target_refreshes = 2
                    frame._core_overlay_ready_seen = False
                    frame._core_overlay_second_refresh_scheduled = False
                    frame._core_overlay_hold = True
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
                self._log_plot_tab_debug(
                    "Core real figure installed for %s; reset overlay refresh orchestration."
                    % plot_key
                )
        if plot_key == "fig_combined":
            was_real_combined = bool(
                getattr(frame, "_combined_real_figure_installed", False)
            )
            is_real_combined = self._is_real_combined_figure(fig)
            try:
                fig.set_canvas(canvas)
            except Exception:
                # Best-effort guard; ignore failures.
                pass
            try:
                canvas.figure = fig
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                frame._combined_real_figure_installed = is_real_combined
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            if is_real_combined and not was_real_combined:
                # Reset one-shot post-first-draw refresh flags when transitioning
                # from placeholder to the first real combined figure.
                prior_finalize_after_id = getattr(
                    frame, "_combined_overlay_finalize_after_id", None
                )
                if prior_finalize_after_id is not None:
                    try:
                        self.after_cancel(prior_finalize_after_id)
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting the workflow.
                        pass
                try:
                    default_target_refreshes = (
                        self._combined_overlay_default_target_refreshes()
                    )
                    frame._post_first_draw_refresh_done = False
                    frame._post_first_draw_refresh_invoked = False
                    frame._post_first_draw_refresh_hold_overlay = (
                        self._combined_requires_post_first_draw_refresh()
                    )
                    frame._post_first_draw_refresh_retry_count = 0
                    frame._post_first_draw_refresh_waiting_for_command = False
                    frame._post_first_draw_refresh_command_bind_id = None
                    frame._post_first_draw_refresh_command_timeout_after_id = None
                    frame._combined_refresh_geometry_wait = None
                    frame._combined_finalize_geometry_wait = None
                    frame._combined_overlay_refresh_invoked_count = 0
                    frame._combined_overlay_refresh_completed_count = 0
                    frame._combined_overlay_layout_sig_baseline = None
                    frame._combined_overlay_decision_sig_baseline = None
                    frame._combined_overlay_decision_sig_last = None
                    frame._combined_overlay_data_sig_current = None
                    frame._combined_overlay_need_second_refresh = (
                        default_target_refreshes > 1
                    )
                    frame._combined_overlay_target_refreshes = default_target_refreshes
                    frame._combined_overlay_ready_seen = False
                    frame._combined_overlay_second_refresh_scheduled = False
                    frame._combined_placeholder_draw_logged = False
                    frame._combined_overlay_last_geometry_sig = None
                    frame._combined_overlay_stable_draw_count = 0
                    frame._combined_overlay_finalize_started_at = None
                    frame._combined_overlay_finalize_after_id = None
                    frame._combined_overlay_completion_draw_pending = False
                    frame._combined_overlay_completion_fig_id = None
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
                self._log_plot_tab_debug(
                    "Combined real figure installed; reset post-draw refresh orchestration."
                )
            try:
                self._finalize_combined_plot_display(
                    frame, canvas, placement_state=placement_state
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        else:
            try:
                self._install_refreshed_figure_and_finalize(
                    frame,
                    canvas,
                    fig,
                    plot_id=plot_id,
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            if plot_id and placement_state:
                try:
                    self._restore_plot_element_placement_state(plot_id, placement_state)
                except Exception:
                    # Best-effort guard; ignore failures.
                    pass
            if is_core_key and bool(getattr(frame, "_core_overlay_hold", False)):
                renderer_ok = False
                try:
                    renderer_ok = canvas.get_renderer() is not None
                except Exception:
                    renderer_ok = False
                if renderer_ok and not bool(
                    getattr(frame, "_core_overlay_ready_seen", False)
                ):
                    try:
                        frame._core_overlay_ready_seen = True
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting the workflow.
                        pass
                    self._log_plot_tab_debug(
                        "Core overlay ready signal observed for %s." % plot_key
                    )
                invoked_count = getattr(frame, "_core_overlay_refresh_invoked_count", 0)
                completed_before = getattr(
                    frame, "_core_overlay_refresh_completed_count", 0
                )
                try:
                    invoked_count = int(invoked_count)
                except Exception:
                    invoked_count = 0
                try:
                    completed_before = int(completed_before)
                except Exception:
                    completed_before = 0
                completed_count = completed_before
                if invoked_count > completed_before:
                    completed_count = self._mark_core_overlay_refresh_completed(
                        frame,
                        fig=fig,
                    )
                    target_refreshes = getattr(
                        frame, "_core_overlay_target_refreshes", 2
                    )
                    self._log_plot_tab_debug(
                        "Core auto-refresh completion recorded for %s: invoked=%s completed=%s target=%s."
                        % (
                            plot_key,
                            invoked_count,
                            completed_count,
                            target_refreshes,
                        )
                    )
                else:
                    self._log_plot_tab_debug(
                        "Core render install skipped completion count for %s: invoked=%s completed=%s."
                        % (
                            plot_key,
                            invoked_count,
                            completed_before,
                        )
                    )
                target_refreshes = getattr(frame, "_core_overlay_target_refreshes", 2)
                try:
                    target_refreshes = int(target_refreshes)
                except Exception:
                    target_refreshes = 2
                if target_refreshes <= 0:
                    target_refreshes = 1
                if invoked_count <= 0 and completed_count <= 0:
                    self._schedule_core_refresh_pass(
                        frame,
                        canvas,
                        pass_index=1,
                    )
                elif (
                    completed_count >= 1
                    and completed_count < target_refreshes
                    and not bool(
                        getattr(frame, "_core_overlay_second_refresh_scheduled", False)
                    )
                ):
                    self._schedule_core_refresh_pass(
                        frame,
                        canvas,
                        pass_index=2,
                    )
                self._finalize_core_overlay(frame)
        if plot_key == "fig_cycle_timeline_tab":
            try:
                timeline_fig = getattr(canvas, "figure", None) or fig
                self._register_cycle_timeline_generated_tab_legend_tracking(
                    timeline_fig,
                    canvas=canvas,
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        if plot_id:
            try:
                self._set_plot_dirty_flags(
                    plot_id,
                    dirty_data=False,
                    dirty_layout=False,
                    dirty_elements=False,
                    dirty_trace=False,
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                self._record_plot_refresh_signature_bundle(
                    frame,
                    plot_id=plot_id,
                    plot_key=plot_key,
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        auto_state = getattr(frame, "_plot_auto_refresh_state", None)
        auto_enabled = getattr(frame, "_plot_auto_refresh_enabled", True)
        combined_overlay_hold = bool(
            plot_key == "fig_combined"
            and getattr(frame, "_post_first_draw_refresh_hold_overlay", False)
        )
        if is_core_key and bool(getattr(frame, "_core_overlay_hold", False)):
            # Completion-based core orchestration keeps the overlay until done.
            pass
        elif auto_state == "refreshing" and not combined_overlay_hold:
            self._complete_plot_auto_refresh(frame)
        elif combined_overlay_hold and auto_state == "refreshing":
            # Combined overlay release is draw-event gated; keep generic
            # completion from clearing the splash before adaptive passes finish.
            pass
        elif auto_enabled and auto_state in {"pending", "scheduled"}:
            # Keep the overlay active until the forced refresh pipeline completes.
            pass
        else:
            self._clear_plot_loading_overlay(frame)

    def _compute_target_figsize_inches(self):
        """Compute target figsize inches.
        Used to derive target figsize inches for analysis or plotting."""
        width_px = 0
        height_px = 0

        widgets = [
            getattr(self, "tab_plot", None),
            getattr(self, "nb", None),
            self,
        ]

        # Iterate over widgets to apply the per-item logic.
        for widget in widgets:
            if widget is None:
                continue
            try:
                widget.update_idletasks()
            except Exception:
                # Best-effort guard; ignore failures.
                pass
            try:
                w = widget.winfo_width()
                h = widget.winfo_height()
            except Exception:
                continue
            if w and h:
                width_px = max(width_px, int(w))
                height_px = max(height_px, int(h))

        if width_px <= 0 or height_px <= 0:
            width_px, height_px = 1100, 800

        try:
            dpi = float(plt.rcParams.get("figure.dpi", 100.0))
            if not math.isfinite(dpi) or dpi <= 0.0:
                dpi = 100.0
        except Exception:
            dpi = 100.0

        width_in = max(width_px / dpi, 4.0)
        height_in = max(height_px / dpi, 3.0)
        return (width_in, height_in)

    def _is_real_core_figure(self, fig: Optional[Figure]) -> bool:
        """Return whether a figure is a real core render output."""
        if fig is None:
            return False
        return bool(getattr(fig, "_gl260_core_real_figure", False))

    def _mark_core_figure_real(self, fig: Optional[Figure]) -> None:
        """Mark a figure as a real core render output."""
        if fig is None:
            return
        try:
            fig._gl260_core_real_figure = True  # type: ignore[attr-defined]
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _core_layout_signature(self, fig: Optional[Figure]) -> Any:
        """Build a lightweight layout signature for core plots."""
        if fig is None:
            return None

        def _norm_num(value: Any) -> Any:
            try:
                value_f = float(value)
            except Exception:
                return value
            if not math.isfinite(value_f):
                return None
            return round(value_f, 4)

        def _norm_tuple(value: Any) -> Any:
            if isinstance(value, (list, tuple)):
                return tuple(_norm_num(item) for item in value)
            return _norm_num(value)

        try:
            size = fig.get_size_inches()
            size_sig = tuple(_norm_num(v) for v in size)
        except Exception:
            size_sig = None
        try:
            subplot = fig.subplotpars
            subplot_sig = (
                _norm_num(getattr(subplot, "left", None)),
                _norm_num(getattr(subplot, "right", None)),
                _norm_num(getattr(subplot, "bottom", None)),
                _norm_num(getattr(subplot, "top", None)),
                _norm_num(getattr(subplot, "wspace", None)),
                _norm_num(getattr(subplot, "hspace", None)),
            )
        except Exception:
            subplot_sig = None
        axes_sig: List[Any] = []
        try:
            for idx, ax in enumerate(list(getattr(fig, "axes", []) or [])):
                if getattr(ax, "_gl260_legend_only", False):
                    continue
                role = str(getattr(ax, "_gl260_axis_role", "") or "")
                try:
                    bounds = tuple(_norm_num(v) for v in ax.get_position().bounds)
                except Exception:
                    bounds = None
                try:
                    xlim = tuple(_norm_num(v) for v in ax.get_xlim())
                except Exception:
                    xlim = None
                try:
                    ylim = tuple(_norm_num(v) for v in ax.get_ylim())
                except Exception:
                    ylim = None
                axes_sig.append((idx, role, bounds, xlim, ylim))
        except Exception:
            axes_sig = []
        legend_sig: List[Any] = []
        try:
            legends = _collect_gl260_legends(fig)
        except Exception:
            legends = []
        for idx, legend in enumerate(legends):
            role = str(getattr(legend, "_gl260_legend_role", "") or "")
            try:
                loc_val = legend.get_loc()
            except Exception:
                loc_val = getattr(legend, "_loc", None)
            try:
                bbox = legend.get_bbox_to_anchor()
                bounds = (
                    tuple(_norm_num(v) for v in bbox.bounds)
                    if bbox is not None
                    else None
                )
            except Exception:
                bounds = None
            legend_sig.append((idx, role, _norm_tuple(loc_val), bounds))
        return (size_sig, subplot_sig, tuple(axes_sig), tuple(legend_sig))

    def _overlay_layout_decision_signature(self, fig: Optional[Figure]) -> Any:
        """Build a low-noise layout signature for adaptive refresh pass decisions.

        Purpose:
            Capture only geometry that materially affects whether a second
            refresh pass is needed before revealing the plot.
        Why:
            Overlay pass orchestration should react to structural layout changes
            only; data limits and legend bounds are noisy and can trigger
            unnecessary second passes.
        Inputs:
            fig: Matplotlib Figure being evaluated for adaptive refresh.
        Outputs:
            Tuple signature containing figure size, subplot parameters, and
            non-legend axis geometry/visibility; returns None when unavailable.
        Side Effects:
            None.
        Exceptions:
            Internal lookups are guarded; missing values degrade to None.
        """
        if fig is None:
            return None

        def _norm_num(value: Any) -> Any:
            """Normalize one numeric value for signature stability."""
            try:
                value_f = float(value)
            except Exception:
                return value
            if not math.isfinite(value_f):
                return None
            return round(value_f, 4)

        try:
            size = fig.get_size_inches()
            size_sig = tuple(_norm_num(v) for v in size)
        except Exception:
            size_sig = None
        try:
            subplot = fig.subplotpars
            subplot_sig = (
                _norm_num(getattr(subplot, "left", None)),
                _norm_num(getattr(subplot, "right", None)),
                _norm_num(getattr(subplot, "bottom", None)),
                _norm_num(getattr(subplot, "top", None)),
                _norm_num(getattr(subplot, "wspace", None)),
                _norm_num(getattr(subplot, "hspace", None)),
            )
        except Exception:
            subplot_sig = None

        axes_sig: List[Any] = []
        try:
            for idx, ax in enumerate(list(getattr(fig, "axes", []) or [])):
                if getattr(ax, "_gl260_legend_only", False):
                    continue
                role = str(getattr(ax, "_gl260_axis_role", "") or "")
                try:
                    visible = bool(ax.get_visible())
                except Exception:
                    visible = True
                try:
                    bounds = tuple(_norm_num(v) for v in ax.get_position().bounds)
                except Exception:
                    bounds = None
                axes_sig.append((idx, role, visible, bounds))
        except Exception:
            axes_sig = []

        return (size_sig, subplot_sig, tuple(axes_sig))

    def _capture_core_overlay_layout_baseline(
        self,
        frame: Optional[ttk.Frame],
        *,
        canvas: Optional[FigureCanvasTkAgg] = None,
    ) -> Any:
        """Capture the core overlay baseline used to decide if pass 2 is required.

        Purpose:
            Store the baseline layout signature before the first forced refresh.
        Why:
            Core overlay orchestration compares pass-1 output against this
            baseline to avoid unnecessary second passes.
        Inputs:
            frame: Plot tab frame storing core overlay refresh state.
            canvas: Optional canvas to resolve the active figure quickly.
        Outputs:
            The captured signature, or None when no figure is available.
        Side Effects:
            Persists baseline on frame as `_core_overlay_layout_sig_baseline`.
        Exceptions:
            Resolution and frame writes are guarded to keep UI flow resilient.
        """
        if frame is None:
            return None
        fig = getattr(canvas, "figure", None) if canvas is not None else None
        if fig is None:
            plot_key = str(getattr(frame, "_plot_key", "") or "")
            _, resolved_canvas = self._find_plot_tab_canvas(plot_key)
            fig = (
                getattr(resolved_canvas, "figure", None)
                if resolved_canvas is not None
                else None
            )
        baseline = self._overlay_layout_decision_signature(fig)
        try:
            frame._core_overlay_layout_sig_baseline = baseline
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        self._log_plot_tab_debug(
            "Core auto-refresh baseline captured for %s: available=%s."
            % (getattr(frame, "_plot_key", None), bool(baseline is not None))
        )
        return baseline

    def _mark_core_overlay_refresh_completed(
        self,
        frame: Optional[ttk.Frame],
        *,
        fig: Optional[Figure] = None,
    ) -> int:
        """Record one core refresh completion and derive the adaptive pass target.

        Purpose:
            Track completed refresh renders for core overlay release gating.
        Why:
            The first completed pass decides whether a second pass is necessary
            based on low-noise layout signature changes.
        Inputs:
            frame: Plot tab frame storing core overlay orchestration state.
            fig: Optional rendered figure for current-pass signature capture.
        Outputs:
            Integer completion count after increment.
        Side Effects:
            Updates completion counters and target refresh metadata on frame.
        Exceptions:
            Counter and state writes are guarded to avoid UI disruption.
        """
        if frame is None:
            return 0
        completed_count = getattr(frame, "_core_overlay_refresh_completed_count", 0)
        try:
            completed_count = int(completed_count)
        except Exception:
            completed_count = 0
        completed_count += 1
        try:
            frame._core_overlay_refresh_completed_count = completed_count
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

        if completed_count == 1:
            baseline_sig = getattr(frame, "_core_overlay_layout_sig_baseline", None)
            current_sig = self._overlay_layout_decision_signature(fig)
            need_second_refresh = False
            if baseline_sig is not None and current_sig is not None:
                need_second_refresh = baseline_sig != current_sig
            target_refreshes = 2 if need_second_refresh else 1
            try:
                frame._core_overlay_need_second_refresh = need_second_refresh
                frame._core_overlay_target_refreshes = target_refreshes
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            self._log_plot_tab_debug(
                "Core adaptive refresh decision for %s: need_second=%s target=%s baseline_available=%s current_available=%s."
                % (
                    getattr(frame, "_plot_key", None),
                    need_second_refresh,
                    target_refreshes,
                    baseline_sig is not None,
                    current_sig is not None,
                )
            )
        target_refreshes = getattr(frame, "_core_overlay_target_refreshes", 2)
        try:
            target_refreshes = int(target_refreshes)
        except Exception:
            target_refreshes = 2
        if target_refreshes <= 0:
            target_refreshes = 1
        milestone_value = 98.0 if completed_count >= target_refreshes else 90.0
        self._update_plot_loading_overlay_progress(
            frame,
            progress=milestone_value,
            message=(
                "Finalizing plot..."
                if completed_count >= target_refreshes
                else "Auto-refresh pass complete."
            ),
        )
        return completed_count

    def _finalize_core_overlay(
        self, frame: Optional[ttk.Frame], *, force_clear: bool = False
    ) -> None:
        """Finalize one core-plot loading overlay after refresh completion checks.

        Purpose:
            Clear a core plot loading overlay only after required refresh and
            readiness gates complete.
        Why:
            Core plots run staged auto-refresh passes; clearing early can expose
            intermediate geometry before the stable render is ready.
        Inputs:
            frame: Plot tab frame that owns the core overlay state.
            force_clear: When True, bypasses readiness counters and clears
                immediately.
        Outputs:
            None.
        Side Effects:
            Updates refresh state flags, writes terminal overlay status, and
            destroys overlay widgets when clearing.
        Exceptions:
            Best-effort guards ignore UI state errors to keep plotting responsive.
        """
        if frame is None:
            return
        hold_overlay = bool(getattr(frame, "_core_overlay_hold", False))
        if not hold_overlay and not force_clear:
            return
        completed_count = getattr(frame, "_core_overlay_refresh_completed_count", 0)
        try:
            completed_count = int(completed_count)
        except Exception:
            completed_count = 0
        target_refreshes = getattr(frame, "_core_overlay_target_refreshes", 2)
        try:
            target_refreshes = int(target_refreshes)
        except Exception:
            target_refreshes = 2
        if target_refreshes <= 0:
            target_refreshes = 1
        ready_seen = bool(getattr(frame, "_core_overlay_ready_seen", False))
        if not force_clear and (completed_count < target_refreshes or not ready_seen):
            self._log_plot_tab_debug(
                "Core overlay hold for %s: completed=%s target=%s ready_seen=%s."
                % (
                    getattr(frame, "_plot_key", None),
                    completed_count,
                    target_refreshes,
                    ready_seen,
                )
            )
            return
        try:
            frame._core_overlay_hold = False
            frame._core_overlay_second_refresh_scheduled = False
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            frame._plot_auto_refresh_state = "done"
            frame._plot_auto_refresh_after_id = None
            frame._plot_auto_refresh_in_progress = False
            frame._plot_auto_refresh_phase = None
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        self._log_plot_tab_debug(
            "Core auto-refresh overlay cleared for %s: completed=%s target=%s ready_seen=%s force=%s."
            % (
                getattr(frame, "_plot_key", None),
                completed_count,
                target_refreshes,
                ready_seen,
                force_clear,
            )
        )
        self._update_plot_loading_overlay_progress(
            frame,
            progress=100.0,
            message="Plot ready.",
            stage_key="ready",
        )
        self._clear_plot_loading_overlay(frame)

    def _schedule_core_refresh_pass(
        self,
        frame: Optional[ttk.Frame],
        canvas: Optional[FigureCanvasTkAgg],
        *,
        pass_index: int,
    ) -> None:
        """Schedule one core auto-refresh pass under overlay hold coordination.

        Purpose:
            Queue one refresh invocation for a core plot while an overlay hold is
            active.
        Why:
            Completion-based overlay behavior requires explicit pass scheduling so
            pass-1/pass-2 milestones are tracked deterministically.
        Inputs:
            frame: Plot tab frame that stores overlay/refresh state.
            canvas: Core plot canvas used for idle scheduling and widget checks.
            pass_index: One-based refresh pass number used for status messaging.
        Outputs:
            None.
        Side Effects:
            Registers idle callbacks, increments refresh counters, updates overlay
            progress text, and may force overlay finalization on failure paths.
        Exceptions:
            Widget or callback failures fail closed and clear overlays when needed.
        """
        if frame is None or canvas is None:
            return
        if not bool(getattr(frame, "_core_overlay_hold", False)):
            return
        after_id = getattr(frame, "_plot_auto_refresh_after_id", None)
        if after_id is not None:
            return
        try:
            if not frame.winfo_exists():
                self._finalize_core_overlay(frame, force_clear=True)
                return
        except Exception:
            self._finalize_core_overlay(frame, force_clear=True)
            return
        try:
            widget = canvas.get_tk_widget()
        except Exception:
            widget = None
        if widget is None:
            self._finalize_core_overlay(frame, force_clear=True)
            return
        try:
            if not widget.winfo_exists():
                self._finalize_core_overlay(frame, force_clear=True)
                return
        except Exception:
            self._finalize_core_overlay(frame, force_clear=True)
            return
        refresh_command = getattr(frame, "_refresh_command", None)
        if not callable(refresh_command):
            self._log_plot_tab_debug(
                "Core auto-refresh pass %s missing refresh command for %s; clearing overlay."
                % (pass_index, getattr(frame, "_plot_key", None))
            )
            self._finalize_core_overlay(frame, force_clear=True)
            return
        if (
            pass_index <= 1
            and getattr(frame, "_core_overlay_layout_sig_baseline", None) is None
        ):
            self._capture_core_overlay_layout_baseline(frame, canvas=canvas)
        if pass_index >= 2:
            try:
                frame._core_overlay_second_refresh_scheduled = True
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

        def _invoke_refresh() -> None:
            """Invoke one scheduled core refresh pass."""
            try:
                frame._plot_auto_refresh_after_id = None
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            if not bool(getattr(frame, "_core_overlay_hold", False)):
                return
            invoked_count = getattr(frame, "_core_overlay_refresh_invoked_count", 0)
            try:
                invoked_count = int(invoked_count)
            except Exception:
                invoked_count = 0
            invoked_count += 1
            try:
                frame._core_overlay_refresh_invoked_count = invoked_count
                frame._plot_auto_refresh_state = "refreshing"
                frame._plot_auto_refresh_in_progress = True
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            completed_count = getattr(frame, "_core_overlay_refresh_completed_count", 0)
            self._log_plot_tab_debug(
                "Core auto-refresh pass %s invoked for %s: invoked=%s completed=%s."
                % (
                    pass_index,
                    getattr(frame, "_plot_key", None),
                    invoked_count,
                    completed_count,
                )
            )
            self._update_plot_loading_overlay_progress(
                frame,
                progress=84.0 if pass_index <= 1 else 94.0,
                message=(
                    "Running auto-refresh pass 1..."
                    if pass_index <= 1
                    else "Running auto-refresh pass 2..."
                ),
                stage_key=(
                    "auto_refresh_pass_1" if pass_index <= 1 else "auto_refresh_pass_2"
                ),
            )
            try:
                refresh_command()
            except Exception:
                # Fail closed: avoid leaving the overlay stuck if refresh fails.
                self._finalize_core_overlay(frame, force_clear=True)

        try:
            frame._plot_auto_refresh_after_id = widget.after_idle(_invoke_refresh)
        except Exception:
            try:
                frame._plot_auto_refresh_after_id = self.after_idle(_invoke_refresh)
            except Exception:
                _invoke_refresh()

    def _is_real_combined_figure(self, fig: Optional[Figure]) -> bool:
        """Return whether a figure is a real combined render output."""
        if fig is None:
            return False
        return bool(getattr(fig, "_gl260_combined_real_figure", False))

    def _mark_combined_figure_real(self, fig: Optional[Figure]) -> None:
        """Mark a figure as a real combined render output."""
        if fig is None:
            return
        try:
            fig._gl260_combined_real_figure = True  # type: ignore[attr-defined]
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _combined_rendered_geometry_signature(self, fig: Optional[Figure]) -> Any:
        """Build a rendered-geometry signature for combined overlays."""
        if fig is None:
            return None

        def _norm_num(value: Any) -> Any:
            try:
                value_f = float(value)
            except Exception:
                return value
            if not math.isfinite(value_f):
                return None
            return round(value_f, 4)

        def _norm_tuple(value: Any) -> Any:
            if isinstance(value, (list, tuple)):
                return tuple(_norm_num(item) for item in value)
            return _norm_num(value)

        try:
            size = fig.get_size_inches()
            size_sig = tuple(_norm_num(v) for v in size)
        except Exception:
            size_sig = None
        try:
            subplot = fig.subplotpars
            subplot_sig = (
                _norm_num(getattr(subplot, "left", None)),
                _norm_num(getattr(subplot, "right", None)),
                _norm_num(getattr(subplot, "bottom", None)),
                _norm_num(getattr(subplot, "top", None)),
                _norm_num(getattr(subplot, "wspace", None)),
                _norm_num(getattr(subplot, "hspace", None)),
            )
        except Exception:
            subplot_sig = None
        axes_sig: List[Any] = []
        try:
            for idx, ax in enumerate(list(getattr(fig, "axes", []) or [])):
                if getattr(ax, "_gl260_legend_only", False):
                    continue
                role = str(getattr(ax, "_gl260_axis_role", "") or "")
                try:
                    bounds = tuple(_norm_num(v) for v in ax.get_position().bounds)
                except Exception:
                    bounds = None
                try:
                    xlim = tuple(_norm_num(v) for v in ax.get_xlim())
                except Exception:
                    xlim = None
                try:
                    ylim = tuple(_norm_num(v) for v in ax.get_ylim())
                except Exception:
                    ylim = None
                axes_sig.append((idx, role, bounds, xlim, ylim))
        except Exception:
            axes_sig = []
        legend_sig: List[Any] = []
        try:
            legends = _collect_gl260_legends(fig)
        except Exception:
            legends = []
        for idx, legend in enumerate(legends):
            role = str(getattr(legend, "_gl260_legend_role", "") or "")
            try:
                loc_val = legend.get_loc()
            except Exception:
                loc_val = getattr(legend, "_loc", None)
            try:
                bbox = legend.get_bbox_to_anchor()
                bounds = (
                    tuple(_norm_num(v) for v in bbox.bounds)
                    if bbox is not None
                    else None
                )
            except Exception:
                bounds = None
            legend_sig.append((idx, role, _norm_tuple(loc_val), bounds))
        return (size_sig, subplot_sig, tuple(axes_sig), tuple(legend_sig))

    def _resolve_combined_overlay_figure(
        self,
        frame: Optional[ttk.Frame],
        *,
        canvas: Optional[FigureCanvasTkAgg] = None,
        fig: Optional[Figure] = None,
    ) -> Optional[Figure]:
        """Resolve the active combined figure from direct or tab context."""
        if fig is not None:
            return fig
        resolved_fig = getattr(canvas, "figure", None) if canvas is not None else None
        if resolved_fig is not None:
            return resolved_fig
        if frame is not None:
            plot_key = str(getattr(frame, "_plot_key", "") or "")
            if plot_key:
                _, resolved_canvas = self._find_plot_tab_canvas(plot_key)
                resolved_fig = (
                    getattr(resolved_canvas, "figure", None)
                    if resolved_canvas is not None
                    else None
                )
                if resolved_fig is not None:
                    return resolved_fig
        _, resolved_canvas = self._find_plot_tab_canvas("fig_combined")
        if resolved_canvas is None:
            return None
        return getattr(resolved_canvas, "figure", None)

    def _combined_current_layout_sig(self) -> Any:
        """Return the most recent combined layout signature, if available."""
        state = (
            self._combined_plot_state
            if isinstance(self._combined_plot_state, dict)
            else {}
        )
        return self._combined_rendered_geometry_signature(state.get("fig"))

    def _combined_overlay_decision_signature(
        self,
        frame: Optional[ttk.Frame],
        *,
        canvas: Optional[FigureCanvasTkAgg] = None,
        fig: Optional[Figure] = None,
    ) -> Dict[str, Any]:
        """Build the combined adaptive-refresh decision signature bundle.

        Purpose:
            Collect the low-noise signals used to decide whether combined pass 2
            is required.
        Why:
            Combined overlay gating should avoid unconditional second refreshes
            while still failing closed when decision signals are incomplete.
        Inputs:
            frame: Plot tab frame that stores combined overlay orchestration state.
            canvas: Optional active canvas used to resolve the rendered figure.
            fig: Optional explicit figure override for signature collection.
        Outputs:
            Mapping with `data_sig`, `layout_sig`, `elements_sig`, and
            `geometry_sig`; values are None when unavailable.
        Side Effects:
            None.
        Exceptions:
            Resolution failures are guarded; missing values degrade to None.
        """
        active_fig = self._resolve_combined_overlay_figure(
            frame, canvas=canvas, fig=fig
        )
        state = (
            self._combined_plot_state
            if isinstance(self._combined_plot_state, dict)
            else {}
        )

        data_sig = None
        if frame is not None:
            data_sig = getattr(frame, "_combined_overlay_data_sig_current", None)
        if data_sig is None and active_fig is not None:
            data_sig = getattr(active_fig, "_gl260_combined_data_sig", None)

        layout_sig = getattr(active_fig, "_gl260_combined_layout_sig", None)
        state_fig = state.get("fig")
        if layout_sig is None and active_fig is not None and state_fig is active_fig:
            layout_sig = state.get("layout_sig")
        if layout_sig is None:
            layout_sig = self._combined_layout_state

        return {
            "data_sig": data_sig,
            "layout_sig": layout_sig,
            "elements_sig": self._plot_elements_signature("fig_combined_triple_axis"),
            "geometry_sig": self._overlay_layout_decision_signature(active_fig),
        }

    def _capture_combined_overlay_layout_baseline(
        self,
        frame: Optional[ttk.Frame],
        *,
        canvas: Optional[FigureCanvasTkAgg] = None,
        fig: Optional[Figure] = None,
    ) -> Any:
        """Capture the combined overlay baseline used by adaptive pass selection.

        Purpose:
            Store baseline geometry before the first post-draw combined refresh.
        Why:
            Combined overlay logic should request pass 2 only when material
            layout geometry changed after pass 1.
        Inputs:
            frame: Plot tab frame storing combined overlay state.
            canvas: Optional canvas used to resolve the active combined figure.
            fig: Optional explicit figure override for baseline capture.
        Outputs:
            Baseline decision-signature bundle, or None when unavailable.
        Side Effects:
            Persists baseline metadata on the frame for pass-target derivation.
        Exceptions:
            Resolution and state writes are guarded to avoid UI interruption.
        """
        if frame is None:
            return None
        baseline_bundle = self._combined_overlay_decision_signature(
            frame,
            canvas=canvas,
            fig=fig,
        )
        baseline = baseline_bundle.get("geometry_sig")
        try:
            frame._combined_overlay_layout_sig_baseline = baseline
            frame._combined_overlay_decision_sig_baseline = baseline_bundle
            frame._combined_overlay_decision_sig_last = baseline_bundle
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        self._log_plot_tab_debug(
            "Combined auto-refresh baseline captured: data=%s layout=%s elements=%s geometry=%s."
            % (
                baseline_bundle.get("data_sig") is not None,
                baseline_bundle.get("layout_sig") is not None,
                baseline_bundle.get("elements_sig") is not None,
                baseline_bundle.get("geometry_sig") is not None,
            )
        )
        return baseline_bundle

    def _mark_combined_overlay_refresh_completed(
        self,
        frame: Optional[ttk.Frame],
        *,
        fig: Optional[Figure] = None,
    ) -> int:
        """Record one combined refresh completion and compute adaptive pass count.

        Purpose:
            Maintain completion counters for combined overlay hold/release flow.
        Why:
            Combined plots should run a second pass only when data/layout/element
            changes also produce a material geometry shift; incomplete signal
            sets default to single-pass unless explicit instability is observed.
            This counter is consumed by
            draw-confirmed completion gating in the combined overlay flow.
        Inputs:
            frame: Plot tab frame storing combined overlay orchestration state.
            fig: Optional combined figure for current-pass signature capture.
        Outputs:
            Integer completion count after increment.
        Side Effects:
            Updates pass-target metadata and stores latest decision signatures on
            the frame after pass 1 completes.
        Exceptions:
            Counter and state writes are guarded to avoid UI disruption.
        """
        if frame is None:
            return 0
        completed_count = getattr(frame, "_combined_overlay_refresh_completed_count", 0)
        try:
            completed_count = int(completed_count)
        except Exception:
            completed_count = 0
        completed_count += 1
        try:
            frame._combined_overlay_refresh_completed_count = completed_count
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

        if completed_count == 1:
            refresh_mode = self._combined_refresh_mode()
            baseline_bundle = getattr(
                frame, "_combined_overlay_decision_sig_baseline", None
            )
            if not isinstance(baseline_bundle, dict):
                baseline_bundle = {
                    "data_sig": None,
                    "layout_sig": None,
                    "elements_sig": None,
                    "geometry_sig": getattr(
                        frame, "_combined_overlay_layout_sig_baseline", None
                    ),
                }
            current_bundle = self._combined_overlay_decision_signature(frame, fig=fig)
            try:
                frame._combined_overlay_decision_sig_last = current_bundle
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

            def _changed(key: str) -> Optional[bool]:
                """Compare one baseline/current signature field."""
                baseline_value = baseline_bundle.get(key)
                current_value = current_bundle.get(key)
                if baseline_value is None or current_value is None:
                    return None
                return baseline_value != current_value

            data_changed = _changed("data_sig")
            layout_changed = _changed("layout_sig")
            elements_changed = _changed("elements_sig")
            geometry_changed = _changed("geometry_sig")
            signals_complete = not any(
                value is None
                for value in (
                    data_changed,
                    layout_changed,
                    elements_changed,
                    geometry_changed,
                )
            )
            if refresh_mode == "single_pass":
                need_second_refresh = False
            elif refresh_mode == "two_pass":
                need_second_refresh = True
            elif signals_complete:
                if not any([data_changed, layout_changed, elements_changed]):
                    need_second_refresh = False
                else:
                    need_second_refresh = bool(geometry_changed)
            else:
                # Adaptive mode defaults to a single pass when decision signals
                # are incomplete; only explicit instability promotes pass 2.
                explicit_instability = bool(
                    geometry_changed is True
                    and any(
                        value is True
                        for value in (
                            data_changed,
                            layout_changed,
                            elements_changed,
                        )
                    )
                )
                need_second_refresh = explicit_instability
            target_refreshes = 2 if need_second_refresh else 1
            try:
                frame._combined_overlay_need_second_refresh = need_second_refresh
                frame._combined_overlay_target_refreshes = target_refreshes
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            self._log_plot_tab_debug(
                "Combined adaptive refresh decision: mode=%s need_second=%s target=%s data_changed=%s layout_changed=%s elements_changed=%s geometry_changed=%s signals_complete=%s."
                % (
                    refresh_mode,
                    need_second_refresh,
                    target_refreshes,
                    data_changed,
                    layout_changed,
                    elements_changed,
                    geometry_changed,
                    signals_complete,
                )
            )
            perf_run = getattr(frame, "_combined_perf_run", None)
            if isinstance(perf_run, dict):
                stages = perf_run.setdefault("stages", {})
                combined_stage = stages.setdefault("combined", {})
                combined_stage["auto_refresh_mode"] = refresh_mode
                combined_stage["auto_refresh_target"] = int(target_refreshes)
        perf_run = getattr(frame, "_combined_perf_run", None)
        if isinstance(perf_run, dict):
            stages = perf_run.setdefault("stages", {})
            combined_stage = stages.setdefault("combined", {})
            combined_stage["auto_refresh_passes"] = int(completed_count)
            self._record_performance_run(perf_run)
        target_refreshes = getattr(
            frame,
            "_combined_overlay_target_refreshes",
            self._combined_overlay_default_target_refreshes(),
        )
        try:
            target_refreshes = int(target_refreshes)
        except Exception:
            target_refreshes = self._combined_overlay_default_target_refreshes()
        if target_refreshes <= 0:
            target_refreshes = 1
        milestone_value = 98.0 if completed_count >= target_refreshes else 90.0
        self._update_plot_loading_overlay_progress(
            frame,
            progress=milestone_value,
            message=(
                "Finalizing combined plot..."
                if completed_count >= target_refreshes
                else "Combined auto-refresh pass complete."
            ),
        )
        return completed_count

    def _resolve_combined_initial_figsize_inches(
        self,
        frame: Optional[ttk.Frame] = None,
        canvas: Optional[FigureCanvasTkAgg] = None,
        *,
        timeout_ms: int = 250,
        poll_ms: int = 25,
    ) -> Tuple[float, float]:
        """Resolve initial combined figsize from the real canvas with a short bounded wait."""
        if frame is None or canvas is None:
            frame, canvas = self._find_plot_tab_canvas("fig_combined")
        return self._resolve_initial_canvas_figsize_inches(
            frame,
            canvas,
            timeout_ms=timeout_ms,
            poll_ms=poll_ms,
            tag="combined",
        )

    def _resolve_initial_canvas_figsize_inches(
        self,
        frame: Optional[ttk.Frame],
        canvas: Optional[FigureCanvasTkAgg],
        *,
        timeout_ms: int = 250,
        poll_ms: int = 25,
        tag: str = "plot",
    ) -> Tuple[float, float]:
        """Resolve initial canvas size using readiness signals with bounded fallback.

        Purpose:
            Determine the initial figure size from the live Tk canvas geometry.
        Why:
            Initial plot generation should use real widget dimensions without
            blocking on fixed sleep-based polling loops.
        Inputs:
            frame: Plot tab frame associated with the canvas.
            canvas: FigureCanvasTkAgg carrying the Tk widget.
            timeout_ms: Maximum wait for geometry readiness before fallback.
            poll_ms: Legacy compatibility parameter; retained for callers.
            tag: Debug label for readiness/fallback logging.
        Outputs:
            Tuple[float, float]: Figure size in inches.
        Side Effects:
            Registers temporary `<Configure>` and idle callbacks, runs bounded UI
            event processing, and emits debug log entries.
        Exceptions:
            Falls back to computed target figure size when readiness cannot be
            established within the bounded wait window.
        """
        fallback = self._compute_target_figsize_inches()
        if frame is None or canvas is None:
            self._log_plot_tab_debug(
                "%s initial figsize fallback: frame/canvas unavailable."
                % str(tag).capitalize()
            )
            return fallback
        try:
            widget = canvas.get_tk_widget()
        except Exception:
            widget = None
        if widget is None:
            self._log_plot_tab_debug(
                "%s initial figsize fallback: canvas widget unavailable."
                % str(tag).capitalize()
            )
            return fallback

        ready_state: Dict[str, int] = {"width_px": 0, "height_px": 0}

        def _probe_geometry() -> bool:
            """Probe current canvas widget geometry and update readiness state.

            Purpose:
                Sample Tk geometry from the notebook/frame/widget chain.
            Why:
                Initial canvas sizing should react to real geometry readiness
                instead of sleeping on fixed retry intervals.
            Inputs:
                None.
            Outputs:
                bool: True when usable dimensions were captured.
            Side Effects:
                Updates `ready_state` width/height values on successful probe.
            Exceptions:
                Failures are swallowed and treated as not-ready.
            """
            for widget_obj in (self.nb, frame, widget):
                try:
                    widget_obj.update_idletasks()
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
            try:
                width_px = int(widget.winfo_width())
                height_px = int(widget.winfo_height())
            except Exception:
                width_px = 0
                height_px = 0
            if width_px > 2 and height_px > 2:
                ready_state["width_px"] = width_px
                ready_state["height_px"] = height_px
                return True
            return False

        if _probe_geometry():
            width_px = int(ready_state.get("width_px", 0))
            height_px = int(ready_state.get("height_px", 0))
        else:
            readiness_event = threading.Event()
            wait_state: Dict[str, Any] = {
                "frame_bind_id": None,
                "widget_bind_id": None,
                "timeout_after_id": None,
            }

            def _cleanup_waiters() -> None:
                """Tear down temporary geometry listeners after readiness wait.

                Purpose:
                    Remove transient configure/timeout callbacks used for sizing.
                Why:
                    Listener cleanup prevents callback leaks and duplicate probes.
                Inputs:
                    None.
                Outputs:
                    None.
                Side Effects:
                    Unbinds frame/widget handlers and cancels timeout callbacks.
                Exceptions:
                    Cleanup errors are ignored to keep rendering resilient.
                """
                frame_bind_id = wait_state.get("frame_bind_id")
                widget_bind_id = wait_state.get("widget_bind_id")
                timeout_after_id = wait_state.get("timeout_after_id")
                if frame_bind_id:
                    try:
                        frame.unbind("<Configure>", frame_bind_id)
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting the workflow.
                        pass
                if widget_bind_id:
                    try:
                        widget.unbind("<Configure>", widget_bind_id)
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting the workflow.
                        pass
                if timeout_after_id is not None:
                    try:
                        self.after_cancel(timeout_after_id)
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting the workflow.
                        pass
                wait_state["frame_bind_id"] = None
                wait_state["widget_bind_id"] = None
                wait_state["timeout_after_id"] = None

            def _on_geometry_signal(_event: Any = None) -> None:
                """Handle configure/idle geometry events for readiness detection.

                Purpose:
                    Re-probe geometry when Tk signals a potential size change.
                Why:
                    Readiness should be event-driven so initial sizing responds as
                    soon as geometry is available.
                Inputs:
                    _event: Optional Tk event payload.
                Outputs:
                    None.
                Side Effects:
                    Sets the readiness event after a successful geometry probe.
                Exceptions:
                    Probe failures are ignored and leave readiness unchanged.
                """
                if _probe_geometry():
                    readiness_event.set()

            try:
                wait_state["frame_bind_id"] = frame.bind(
                    "<Configure>", _on_geometry_signal, add="+"
                )
            except Exception:
                wait_state["frame_bind_id"] = None
            try:
                wait_state["widget_bind_id"] = widget.bind(
                    "<Configure>", _on_geometry_signal, add="+"
                )
            except Exception:
                wait_state["widget_bind_id"] = None
            try:
                self.after_idle(_on_geometry_signal)
            except Exception:
                _on_geometry_signal()
            timeout_after_id = None
            try:
                timeout_after_id = self.after(max(1, int(timeout_ms)), readiness_event.set)
            except Exception:
                timeout_after_id = None
            wait_state["timeout_after_id"] = timeout_after_id

            # Process queued UI events until geometry becomes ready or timeout fires.
            # The event is driven by configure/idle callbacks; the wait loop is
            # only a bounded emergency path to keep this synchronous helper safe.
            deadline = time.monotonic() + max(float(timeout_ms), 1.0) / 1000.0 + 0.05
            while not readiness_event.is_set() and time.monotonic() < deadline:
                try:
                    self.update()
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    break
                if readiness_event.is_set():
                    break
                readiness_event.wait(max(float(poll_ms), 1.0) / 1000.0)
            _cleanup_waiters()
            width_px = int(ready_state.get("width_px", 0))
            height_px = int(ready_state.get("height_px", 0))

        if width_px <= 2 or height_px <= 2:
            self._log_plot_tab_debug(
                "%s initial figsize fallback: timed out waiting for canvas size."
                % str(tag).capitalize()
            )
            return fallback
        try:
            dpi = float(getattr(canvas.figure, "dpi", 100.0))
            if not math.isfinite(dpi) or dpi <= 0.0:
                dpi = 100.0
        except Exception:
            dpi = 100.0
        size = (max(width_px / dpi, 1.0), max(height_px / dpi, 1.0))
        self._log_plot_tab_debug(
            "%s initial figsize resolved from canvas: %sx%s px -> %.3fx%.3f in."
            % (str(tag).capitalize(), width_px, height_px, size[0], size[1])
        )
        return size

    def _resolve_initial_core_figsize_inches(
        self,
        plot_keys: Sequence[str],
        *,
        timeout_ms: int = 250,
        poll_ms: int = 25,
    ) -> Dict[str, Tuple[float, float]]:
        """Resolve initial core figsizes for selected core plot tabs."""
        sizes: Dict[str, Tuple[float, float]] = {}
        for key in [key for key in plot_keys if key in {"fig1", "fig2"}]:
            frame, canvas = self._find_plot_tab_canvas(key)
            if frame is None or canvas is None:
                continue
            sizes[key] = self._resolve_initial_canvas_figsize_inches(
                frame,
                canvas,
                timeout_ms=timeout_ms,
                poll_ms=poll_ms,
                tag=key,
            )
        return sizes

    def _generated_plot_tab_profiles(self) -> Dict[str, Dict[str, Any]]:
        """Return generated-plot-tab profile metadata keyed by plot key.

        Purpose:
            Centralize reusable plot-tab profile descriptors for non-core tabs.
        Why:
            New rendered plot tabs should share one registration path so future
            plot types can reuse the same tab/refresh/export plumbing without
            duplicating per-tab control wiring.
        Inputs:
            None.
        Outputs:
            Dict[str, Dict[str, Any]]: Mapping of plot-key to profile metadata.
        Side Effects:
            None.
        Exceptions:
            None.
        """
        return {
            REACTION_DASHBOARD_PLOT_KEY: {
                "plot_id": REACTION_DASHBOARD_PLOT_ID,
                "title": "Reaction Dashboard",
                "loading_message": "Loading Reaction Dashboard plot...",
                "refresh_message": "Refreshing Reaction Dashboard plot...",
                "combined_toolbar_parity": True,
                "internal_force_full_rebuild": False,
                "builder": self._build_reaction_dashboard_plot_tab_figure,
            },
            "fig_cycle_timeline_tab": {
                "plot_id": "fig_cycle_timeline",
                "title": "Cycle Speciation Timeline",
                "loading_message": "Loading cycle timeline plot...",
                "refresh_message": "Refreshing cycle timeline plot...",
                "combined_toolbar_parity": True,
                "internal_force_full_rebuild": False,
                "preview_callback": self._open_cycle_timeline_plot_preview,
                "builder": self._build_cycle_timeline_plot_tab_figure,
            },
        }

    def _plot_tab_profile(self, plot_key: Optional[str]) -> Optional[Dict[str, Any]]:
        """Resolve one generated-plot-tab profile for a plot key.

        Purpose:
            Retrieve normalized profile metadata for generated plot-tab behavior.
        Why:
            Callers need one helper to opt into profile-driven toolbar/refresh
            behavior without hard-coding each non-core plot key.
        Inputs:
            plot_key: Candidate plot-key identifier.
        Outputs:
            Optional[Dict[str, Any]]: Profile metadata when registered.
        Side Effects:
            None.
        Exceptions:
            Best-effort guards return None when profile metadata is unavailable.
        """
        key = str(plot_key or "").strip()
        if not key:
            return None
        try:
            profiles = self._generated_plot_tab_profiles()
        except Exception:
            profiles = {}
        profile = profiles.get(key)
        if not isinstance(profile, Mapping):
            return None
        return dict(profile)

    def _plot_tab_uses_combined_toolbar(self, plot_key: Optional[str]) -> bool:
        """Return whether one plot tab should use combined-style toolbar controls.

        Purpose:
            Centralize toolbar-parity decisions for generated plot-tab profiles.
        Why:
            Combined and selected generated tabs share the same topbar feature
            set, so control wiring should follow one deterministic helper.
        Inputs:
            plot_key: Candidate plot-key identifier.
        Outputs:
            bool: True when combined-style toolbar parity should be applied.
        Side Effects:
            None.
        Exceptions:
            None.
        """
        if str(plot_key or "").strip().lower() == "fig_combined":
            return True
        profile = self._plot_tab_profile(plot_key)
        return bool(isinstance(profile, Mapping) and profile.get("combined_toolbar_parity"))

    def _build_cycle_timeline_plot_tab_figure(
        self,
        *,
        mode: str,
        fig_size: Optional[Tuple[float, float]],
    ) -> Optional[Figure]:
        """Build the cycle timeline figure for generated notebook-tab workflows.

        Purpose:
            Reuse the timeline render pipeline for notebook-tab display/export.
        Why:
            The new timeline tab should use existing tested timeline build logic
            while selecting display/export layout mode explicitly.
        Inputs:
            mode: Render mode selector (`display` or `export`).
            fig_size: Optional target figure size in inches.
        Outputs:
            Optional[Figure]: Rendered timeline figure, or None when no data exists.
        Side Effects:
            Reads current workflow/timeline state to build figure output.
        Exceptions:
            Best-effort guards are handled by downstream builder methods.
        """
        mode_key = "export" if str(mode or "").strip().lower() == "export" else "display"
        resolved_size = fig_size
        if resolved_size is None:
            resolved_size = (11.0, 8.5) if mode_key == "export" else self._compute_target_figsize_inches()
        return self._build_cycle_timeline_export_figure(
            resolved_size,
            workflow_key=self._current_solubility_workflow(),
            preview_interactive_legend=False,
            layout_mode=mode_key,
        )

    def _build_generated_plot_tab_figure(
        self,
        plot_key: Optional[str],
        *,
        mode: str,
        fig_size: Optional[Tuple[float, float]] = None,
    ) -> Optional[Figure]:
        """Build one generated-plot-tab figure from registered profile metadata.

        Purpose:
            Dispatch generated-tab figure builds through registered profile hooks.
        Why:
            Profile-driven figure construction avoids ad-hoc per-plot branching.
        Inputs:
            plot_key: Registered generated plot-key identifier.
            mode: Render mode selector (`display` or `export`).
            fig_size: Optional target size in inches.
        Outputs:
            Optional[Figure]: Built figure or None when unavailable.
        Side Effects:
            Calls profile builder callback which may read live workflow state.
        Exceptions:
            Callback failures are guarded and return None.
        """
        profile = self._plot_tab_profile(plot_key)
        if not isinstance(profile, Mapping):
            return None
        builder = profile.get("builder")
        if not callable(builder):
            return None
        try:
            return builder(mode=mode, fig_size=fig_size)
        except Exception:
            return None

    def _refresh_generated_profile_plot_tab(
        self,
        frame: Any,
        canvas: Any,
        *,
        plot_key: Optional[str],
        plot_id: Optional[str],
        placement_state: Optional[Dict[str, Any]],
    ) -> bool:
        """Refresh one generated profile-backed plot tab using shared pipeline hooks.

        Purpose:
            Route non-core generated tabs through one refresh/install helper.
        Why:
            Profile-backed tabs should support the same refresh lifecycle without
            adding bespoke `_force_plot_refresh` branches per future plot type.
        Inputs:
            frame: Plot-tab frame to refresh.
            canvas: Matplotlib canvas bound to `frame`.
            plot_key: Generated plot-key identifier.
            plot_id: Plot identifier used for overlay/error metadata.
            placement_state: Optional plot-element placement state snapshot.
        Outputs:
            bool: True when this helper handled the refresh path.
        Side Effects:
            Rebuilds figure output and installs it into the active tab canvas,
            or marks refresh as failed when figure generation is unavailable.
        Exceptions:
            Best-effort guards return False only when the plot key is not
            profile-backed; runtime failures are handled as refresh failures.
        """
        profile = self._plot_tab_profile(plot_key)
        if not isinstance(profile, Mapping):
            return False
        refresh_tag = f"{str(plot_key or '').strip() or 'generated_plot'} refresh"
        fig_size = self._resolve_initial_canvas_figsize_inches(
            frame,
            canvas,
            timeout_ms=250,
            poll_ms=25,
            tag=refresh_tag,
        )
        fig = self._build_generated_plot_tab_figure(
            plot_key,
            mode="display",
            fig_size=fig_size,
        )
        if fig is None:
            self._update_plot_loading_overlay_progress(
                frame,
                progress=100.0,
                message="Plot rendering failed.",
                detail="Run a workflow before refreshing this plot tab.",
                stage_key="failed",
            )
            if getattr(frame, "_plot_auto_refresh_state", None) == "refreshing":
                self._complete_plot_auto_refresh(frame)
            else:
                self._clear_plot_loading_overlay(frame)
            return True
        self._update_plot_loading_overlay_progress(
            frame,
            progress=78.0,
            message="Installing refreshed figure...",
            stage_key="installing",
        )
        self._install_rendered_plot_in_tab(
            frame,
            canvas,
            str(plot_key or ""),
            fig,
            placement_state=placement_state,
        )
        return True

    def _is_advanced_plot_tab(self, frame: Any) -> bool:
        """Return whether one plot tab frame is wizard-backed.

        Purpose:
            Detect tabs created by the Advanced Plot Wizard.
        Why:
            Refresh/edit/export flows need to branch between core and wizard tab
            behavior without impacting existing core plot routes.
        Inputs:
            frame: Plot tab frame candidate.
        Outputs:
            bool: True when the frame stores an advanced-plot spec payload.
        Side Effects:
            None.
        Exceptions:
            None.
        """
        spec_payload = getattr(frame, "_advanced_plot_spec", None)
        return isinstance(spec_payload, Mapping)

    def _next_advanced_plot_identifiers(
        self, *, preview: bool = False
    ) -> Tuple[str, str]:
        """Return next plot-key/plot-id identifiers for advanced plot tabs.

        Purpose:
            Generate unique identifiers for custom wizard-generated plot tabs.
        Why:
            Custom tabs must support refresh/edit cycles without colliding with
            core plot IDs or other custom tabs.
        Inputs:
            preview: True to return deterministic preview identifiers.
        Outputs:
            Tuple[str, str]: `(plot_key, plot_id)` for the new tab.
        Side Effects:
            Increments the per-session advanced-plot counter for non-preview tabs.
        Exceptions:
            None.
        """
        if preview:
            return "advanced_plot_preview", "advanced_plot_preview"
        self._advanced_plot_tab_counter = int(self._advanced_plot_tab_counter) + 1
        suffix = f"{self._advanced_plot_tab_counter:04d}_{uuid.uuid4().hex[:6]}"
        return f"advanced_plot_{suffix}", f"advanced_plot_{suffix}"

    def _resolve_advanced_plot_profile_key(self) -> str:
        """Return profile key used for advanced-plot default recipe metadata.

        Purpose:
            Resolve the active profile identifier for per-profile wizard defaults.
        Why:
            Recipe ordering/default selections must follow workspace profile
            context while falling back to a stable global profile key.
        Inputs:
            None.
        Outputs:
            str: Profile key for defaults payload lookup.
        Side Effects:
            None.
        Exceptions:
            Profile resolution failures fall back to global key.
        """
        try:
            profile_name, _profile_path = self._resolve_current_workspace_profile(
                normalize=True, persist=False
            )
        except Exception:
            profile_name = None
        token = str(profile_name or "").strip()
        if token:
            return token
        return ADVANCED_PLOT_WIZARD_GLOBAL_PROFILE_KEY

    def _advanced_plot_recipe_library_payload(self) -> Dict[str, Any]:
        """Return normalized advanced-plot recipe library settings payload.

        Purpose:
            Read and normalize persisted global recipe-library data.
        Why:
            Wizard recipe controls depend on stable schema even after settings
            merges or legacy payloads.
        Inputs:
            None.
        Outputs:
            Dict[str, Any]: Normalized recipe library payload.
        Side Effects:
            Writes normalized payload back to settings when needed.
        Exceptions:
            None.
        """
        settings_ref = self._settings_dict()
        normalized = _normalize_advanced_plot_recipe_library_payload(
            settings_ref.get(ADVANCED_PLOT_WIZARD_RECIPE_LIBRARY_SETTINGS_KEY)
        )
        settings_ref[ADVANCED_PLOT_WIZARD_RECIPE_LIBRARY_SETTINGS_KEY] = normalized
        return normalized

    def _advanced_plot_profile_defaults_payload(self) -> Dict[str, Any]:
        """Return normalized profile-default metadata payload for recipes.

        Purpose:
            Read and normalize per-profile recipe defaults/order settings.
        Why:
            Wizard startup selection logic needs one consistent profile-default map.
        Inputs:
            None.
        Outputs:
            Dict[str, Any]: Normalized profile-default payload.
        Side Effects:
            Writes normalized payload back to settings when needed.
        Exceptions:
            None.
        """
        settings_ref = self._settings_dict()
        library_payload = self._advanced_plot_recipe_library_payload()
        normalized = _normalize_advanced_plot_profile_defaults_payload(
            settings_ref.get(ADVANCED_PLOT_WIZARD_PROFILE_DEFAULTS_SETTINGS_KEY),
            recipe_library=library_payload,
        )
        settings_ref[ADVANCED_PLOT_WIZARD_PROFILE_DEFAULTS_SETTINGS_KEY] = normalized
        return normalized

    def _advanced_plot_profile_defaults_entry(
        self, profile_key: Optional[str] = None
    ) -> Dict[str, Any]:
        """Return one normalized recipe-default entry for a profile.

        Purpose:
            Resolve profile-scoped default recipe ID and ordering metadata.
        Why:
            Wizard controls need one concise lookup for the active profile context.
        Inputs:
            profile_key: Optional explicit profile key override.
        Outputs:
            Dict[str, Any]: Normalized entry containing `default_recipe_id` and `recipe_order`.
        Side Effects:
            Persists missing profile entries into settings payload.
        Exceptions:
            None.
        """
        key = str(profile_key or self._resolve_advanced_plot_profile_key()).strip()
        if not key:
            key = ADVANCED_PLOT_WIZARD_GLOBAL_PROFILE_KEY
        payload = self._advanced_plot_profile_defaults_payload()
        profiles = payload.get("profiles", {})
        if not isinstance(profiles, dict):
            profiles = {}
            payload["profiles"] = profiles
        entry = profiles.get(key, {})
        if not isinstance(entry, Mapping):
            entry = {}
        normalized_entry = {
            "default_recipe_id": str(entry.get("default_recipe_id") or "").strip(),
            "recipe_order": [
                str(item).strip()
                for item in list(entry.get("recipe_order") or [])
                if str(item).strip()
            ],
        }
        profiles[key] = normalized_entry
        return normalized_entry

    def _advanced_plot_set_profile_defaults_entry(
        self,
        *,
        default_recipe_id: str,
        recipe_order: Sequence[str],
        profile_key: Optional[str] = None,
    ) -> None:
        """Persist one profile-scoped default recipe entry for the wizard.

        Purpose:
            Write profile-specific default recipe and ordering metadata.
        Why:
            Users expect profile-local recipe defaults to persist across sessions.
        Inputs:
            default_recipe_id: Preferred recipe ID for the profile.
            recipe_order: Ordered recipe ID list for profile-specific listing.
            profile_key: Optional explicit profile-key override.
        Outputs:
            None.
        Side Effects:
            Updates settings payload and schedules a settings save.
        Exceptions:
            None.
        """
        key = str(profile_key or self._resolve_advanced_plot_profile_key()).strip()
        if not key:
            key = ADVANCED_PLOT_WIZARD_GLOBAL_PROFILE_KEY
        payload = self._advanced_plot_profile_defaults_payload()
        profiles = payload.setdefault("profiles", {})
        if not isinstance(profiles, dict):
            profiles = {}
            payload["profiles"] = profiles
        clean_order = [str(item).strip() for item in list(recipe_order or []) if str(item).strip()]
        profiles[key] = {
            "default_recipe_id": str(default_recipe_id or "").strip(),
            "recipe_order": clean_order,
        }
        settings_ref = self._settings_dict()
        settings_ref[ADVANCED_PLOT_WIZARD_PROFILE_DEFAULTS_SETTINGS_KEY] = (
            _normalize_advanced_plot_profile_defaults_payload(
                payload,
                recipe_library=self._advanced_plot_recipe_library_payload(),
            )
        )
        try:
            self._schedule_save_settings()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _advanced_plot_source_frames(self) -> Dict[str, pd.DataFrame]:
        """Build source-scoped dataframes consumed by Advanced Plot Wizard v2.

        Purpose:
            Materialize stable plotting sources for sheet, timeline, and derived
            timeline metrics under one unified source registry contract.
        Why:
            Advanced Wizard v2 must allow users to plot observed/calculated series
            (e.g., calibrated pH and cumulative uptake) without manual dataframe
            reconstruction.
        Inputs:
            None.
        Outputs:
            Dict[str, pd.DataFrame]: Source map keyed by `sheet_active`,
            `timeline_analysis`, and `timeline_derived`.
        Side Effects:
            Reads workflow/timeline caches; does not mutate persisted state.
        Exceptions:
            Invalid timeline rows are skipped with best-effort normalization.
        """
        sheet_frame = (
            self.df.copy()
            if isinstance(self.df, pd.DataFrame)
            else pd.DataFrame()
        )
        workflow_key = str(self._current_solubility_workflow() or "").strip() or "Planning"
        timeline_rows = list(
            self._final_report_resolve_cycle_timeline_entries(workflow_key=workflow_key) or []
        )
        analysis_rows: List[Dict[str, Any]] = []
        for idx, row in enumerate(timeline_rows, start=1):
            if not isinstance(row, Mapping):
                continue
            fractions_map = row.get("fractions")
            if not isinstance(fractions_map, Mapping):
                fractions_map = {}
            cycle_id = _safe_float(row.get("cycle_id"))
            cycle_index = int(cycle_id) if cycle_id is not None and math.isfinite(cycle_id) else int(idx)
            co2_cycle_g = _safe_float(
                row.get("co2_mass_g")
                or row.get("co2_cycle_g")
                or row.get("original_cycle_co2_g")
            )
            if co2_cycle_g is None:
                co2_cycle_mol = _safe_float(row.get("actual_cycle_co2_mol") or row.get("co2_moles"))
                co2_cycle_g = (
                    float(co2_cycle_mol) * SOL_MW_CO2
                    if co2_cycle_mol is not None and math.isfinite(float(co2_cycle_mol))
                    else None
                )
            corrected_cycle_g = _safe_float(row.get("corrected_cycle_co2_g"))
            if corrected_cycle_g is None:
                corrected_cycle_mol = _safe_float(row.get("corrected_cycle_co2_mol"))
                corrected_cycle_g = (
                    float(corrected_cycle_mol) * SOL_MW_CO2
                    if corrected_cycle_mol is not None and math.isfinite(float(corrected_cycle_mol))
                    else None
                )
            corrected_cumulative_g = _safe_float(row.get("corrected_cumulative_co2_g"))
            if corrected_cumulative_g is None:
                corrected_cumulative_mol = _safe_float(row.get("corrected_cumulative_co2_mol"))
                corrected_cumulative_g = (
                    float(corrected_cumulative_mol) * SOL_MW_CO2
                    if corrected_cumulative_mol is not None and math.isfinite(float(corrected_cumulative_mol))
                    else None
                )
            cumulative_uptake_g = _safe_float(row.get("co2_g"))
            if cumulative_uptake_g is None and co2_cycle_g is not None:
                cumulative_uptake_g = float(co2_cycle_g)
            planning_cycle_mol = _safe_float(row.get("planning_cycle_co2_mol"))
            planning_cycle_g = (
                float(planning_cycle_mol) * SOL_MW_CO2
                if planning_cycle_mol is not None and math.isfinite(float(planning_cycle_mol))
                else None
            )
            calculated_ph = _safe_float(row.get("calculated_ph"))
            equilibrium_ph = _safe_float(
                row.get("equilibrium_ph")
                or row.get("ph")
                or row.get("solution_ph")
            )
            if calculated_ph is None:
                calculated_ph = equilibrium_ph
            calibrated_estimated_ph = _safe_float(
                row.get("calibrated_estimated_ph")
                or row.get("corrected_ph")
            )
            actual_observed_ph = _safe_float(
                row.get("actual_observed_ph")
                or row.get("analysis_anchor_measured_ph")
            )
            analysis_rows.append(
                {
                    "cycle_index": cycle_index,
                    "co2_cycle_g": co2_cycle_g,
                    "co2_cumulative_g": cumulative_uptake_g,
                    "corrected_cycle_co2_g": corrected_cycle_g,
                    "corrected_cumulative_co2_g": corrected_cumulative_g,
                    "corrected_cycle_co2_mol": (
                        corrected_cycle_g / SOL_MW_CO2
                        if corrected_cycle_g is not None and math.isfinite(float(corrected_cycle_g))
                        else _safe_float(row.get("corrected_cycle_co2_mol"))
                    ),
                    "corrected_cumulative_co2_mol": (
                        corrected_cumulative_g / SOL_MW_CO2
                        if corrected_cumulative_g is not None and math.isfinite(float(corrected_cumulative_g))
                        else _safe_float(row.get("corrected_cumulative_co2_mol"))
                    ),
                    "planning_cycle_co2_mol": planning_cycle_mol,
                    "planning_cycle_co2_g": planning_cycle_g,
                    "equilibrium_ph": equilibrium_ph,
                    "calculated_ph": calculated_ph,
                    "calibrated_estimated_ph": calibrated_estimated_ph,
                    "actual_observed_ph": actual_observed_ph,
                    "corrected_ph": _safe_float(row.get("corrected_ph")),
                    "h2co3_pct": _safe_float(fractions_map.get("H2CO3"), 0.0) * 100.0,
                    "hco3_pct": _safe_float(fractions_map.get("HCO3-"), 0.0) * 100.0,
                    "co3_pct": _safe_float(fractions_map.get("CO3^2-"), 0.0) * 100.0,
                }
            )
        timeline_analysis_frame = pd.DataFrame(analysis_rows)
        if not timeline_analysis_frame.empty:
            if "co2_cumulative_g" not in timeline_analysis_frame.columns:
                timeline_analysis_frame["co2_cumulative_g"] = np.nan
            if "co2_cycle_g" in timeline_analysis_frame.columns:
                running_total = 0.0
                rebuilt_cumulative: List[float] = []
                for raw_value in list(timeline_analysis_frame["co2_cycle_g"]):
                    value = _safe_float(raw_value)
                    if value is not None and math.isfinite(float(value)):
                        running_total += max(float(value), 0.0)
                    rebuilt_cumulative.append(float(running_total))
                missing_mask = timeline_analysis_frame["co2_cumulative_g"].isna()
                timeline_analysis_frame.loc[missing_mask, "co2_cumulative_g"] = np.array(
                    rebuilt_cumulative,
                    dtype=float,
                )[missing_mask.to_numpy()]
            sodium_series = self._resolve_cycle_timeline_sodium_speciation_series(
                timeline_rows,
                workflow_key=workflow_key,
            )
            for key, target_column in (
                ("naoh_pct", "timeline_naoh_pct"),
                ("na2co3_pct", "timeline_na2co3_pct"),
                ("nahco3_pct", "timeline_nahco3_pct"),
            ):
                values = list(sodium_series.get(key) or [])
                if len(values) < len(timeline_analysis_frame):
                    values = values + [float("nan")] * (
                        len(timeline_analysis_frame) - len(values)
                    )
                timeline_analysis_frame[target_column] = pd.Series(values[: len(timeline_analysis_frame)])
        derived_columns = [
            "cycle_index",
            "equilibrium_ph",
            "calculated_ph",
            "calibrated_estimated_ph",
            "actual_observed_ph",
            "corrected_ph",
            "co2_cycle_g",
            "co2_cumulative_g",
            "corrected_cycle_co2_g",
            "corrected_cumulative_co2_g",
            "corrected_cycle_co2_mol",
            "corrected_cumulative_co2_mol",
            "planning_cycle_co2_g",
            "planning_cycle_co2_mol",
            "timeline_naoh_pct",
            "timeline_na2co3_pct",
            "timeline_nahco3_pct",
        ]
        existing_derived_columns = [
            column
            for column in derived_columns
            if column in timeline_analysis_frame.columns
        ]
        timeline_derived_frame = (
            timeline_analysis_frame[existing_derived_columns].copy()
            if existing_derived_columns
            else pd.DataFrame(columns=derived_columns)
        )
        return {
            "sheet_active": sheet_frame,
            "timeline_analysis": timeline_analysis_frame,
            "timeline_derived": timeline_derived_frame,
        }

    def _advanced_plot_metric_catalog(
        self,
        source_frames: Optional[Mapping[str, pd.DataFrame]] = None,
    ) -> List[Dict[str, Any]]:
        """Return one normalized metric catalog for Advanced Plot Wizard v2 UI.

        Purpose:
            Build source-aware metric rows used by wizard selectors and layer editor.
        Why:
            Users need explicit observed/calculated/calibrated/derived metric labels
            instead of comma-separated raw column tokens.
        Inputs:
            source_frames: Optional pre-built source frame mapping.
        Outputs:
            List[Dict[str, Any]]: Metric catalog rows with ID/label/source/type metadata.
        Side Effects:
            None.
        Exceptions:
            Invalid frames are skipped safely.
        """
        frames_map = (
            dict(source_frames)
            if isinstance(source_frames, Mapping)
            else self._advanced_plot_source_frames()
        )
        label_overrides = {
            "equilibrium_ph": "Equilibrium pH (Guidance)",
            "calculated_ph": "Calculated pH",
            "calibrated_estimated_ph": "Calibrated estimated pH",
            "actual_observed_ph": "Actual observed pH (anchor)",
            "co2_cycle_g": "Cycle uptake (g)",
            "co2_cumulative_g": "Cumulative uptake (g)",
            "corrected_cycle_co2_g": "Corrected cycle uptake (g)",
            "corrected_cumulative_co2_g": "Corrected cumulative uptake (g)",
            "corrected_cycle_co2_mol": "Corrected cycle uptake (mol)",
            "corrected_cumulative_co2_mol": "Corrected cumulative uptake (mol)",
            "timeline_naoh_pct": "NaOH (%)",
            "timeline_na2co3_pct": "Na2CO3 (%)",
            "timeline_nahco3_pct": "NaHCO3 (%)",
        }

        def _observability(column_key: str) -> str:
            """Map one column key to observed/calculated/calibrated/derived class."""
            token = str(column_key or "").strip().lower()
            if "actual_observed" in token or "measured" in token:
                return "observed"
            if "calculated" in token or token == "equilibrium_ph":
                return "calculated"
            if "calibrated" in token or "corrected" in token:
                return "calibrated"
            return "derived"

        def _unit(column_key: str) -> str:
            """Infer one display unit token from a metric column key."""
            token = str(column_key or "").strip().lower()
            if token.endswith("_ph") or token == "equilibrium_ph":
                return "pH"
            if token.endswith("_pct") or "pct" in token:
                return "%"
            if token.endswith("_mol") or "_mol_" in token:
                return "mol"
            if token.endswith("_g") or "_mass_" in token:
                return "g"
            return ""

        catalog_rows: List[Dict[str, Any]] = []
        source_order = ["sheet_active", "timeline_analysis", "timeline_derived"]
        for source_id in source_order:
            frame = frames_map.get(source_id)
            if not isinstance(frame, pd.DataFrame):
                continue
            for column_name in list(frame.columns):
                column_key = str(column_name)
                series = frame[column_name]
                present = bool(series.notna().sum()) if hasattr(series, "notna") else False
                data_kind = "category"
                numeric_series = pd.to_numeric(series, errors="coerce")
                if bool(numeric_series.notna().sum()):
                    data_kind = "numeric"
                else:
                    datetime_series = pd.to_datetime(series, errors="coerce")
                    if bool(datetime_series.notna().sum()):
                        data_kind = "datetime"
                label = label_overrides.get(
                    column_key,
                    str(column_key).replace("_", " ").title(),
                )
                catalog_rows.append(
                    {
                        "metric_id": _advanced_plot_metric_id_from_column(column_key, source_id),
                        "label": label,
                        "source_id": source_id,
                        "column_key": column_key,
                        "data_kind": data_kind,
                        "units": _unit(column_key),
                        "observability": _observability(column_key),
                        "present": bool(present),
                    }
                )
        return catalog_rows

    def _build_advanced_plot_from_spec(
        self, spec: Optional[Mapping[str, Any]]
    ) -> Tuple[Figure, Dict[str, Any]]:
        """Build one advanced-plot Matplotlib figure from current dataframe state.

        Purpose:
            Validate and render a wizard specification using the active dataset.
        Why:
            Preview/create/refresh/export flows must share one render path.
        Inputs:
            spec: Raw or normalized advanced-plot specification payload.
        Outputs:
            Tuple[Figure, Dict[str, Any]]: Rendered figure and normalized spec.
        Side Effects:
            None.
        Exceptions:
            Raises ValueError when no dataset is loaded or spec validation fails.
        """
        normalized = _normalize_advanced_plot_recipe_spec_payload(spec)
        source_id = str(normalized.get("source_id") or "sheet_active").strip() or "sheet_active"
        source_frames = self._advanced_plot_source_frames()
        source_frame = source_frames.get(source_id)
        if not isinstance(source_frame, pd.DataFrame):
            source_frame = pd.DataFrame()
        if source_frame.empty:
            if source_id == "sheet_active":
                raise ValueError("Load and apply data columns before creating advanced plots.")
            raise ValueError(
                f"No data is currently available for advanced source '{source_id}'."
            )
        is_valid, message, normalized = _validate_advanced_plot_spec_for_dataframe(
            source_frame,
            normalized,
        )
        if not is_valid:
            raise ValueError(message)
        normalized["source_id"] = source_id
        fig = _render_advanced_plot_figure_from_dataframe(source_frame, normalized)
        return fig, normalized

    def _remove_plot_tab_by_plot_id(self, plot_id: str) -> bool:
        """Remove one plot tab by internal plot identifier.

        Purpose:
            Support deterministic replacement of wizard preview/custom tabs.
        Why:
            Edit/preview refresh flows target tabs by plot ID, not title text.
        Inputs:
            plot_id: Internal plot identifier for the tab to remove.
        Outputs:
            bool: True when a tab was found and removed.
        Side Effects:
            Delegates to title-based tab removal and destroys associated widgets.
        Exceptions:
            Best-effort guards suppress failures and return False.
        """
        if not plot_id:
            return False
        tabs = list(getattr(self, "_plot_tabs", []) or [])
        canvases = list(getattr(self, "_canvases", []) or [])
        for idx, tab in enumerate(tabs):
            if getattr(tab, "_plot_id", None) != plot_id:
                continue
            if str(plot_id or "") == "advanced_plot_preview":
                self._advanced_plot_preview_plot_id = None
            plot_key = getattr(tab, "_plot_key", None)
            if plot_key == "fig_combined":
                if self._combined_cycle_legend_capture_enabled():
                    try:
                        canvas_obj = canvases[idx] if idx < len(canvases) else None
                        self._capture_combined_legend_anchor_from_fig(
                            getattr(canvas_obj, "figure", None),
                            source="refresh",
                        )
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting the workflow.
                        pass
                self._invalidate_combined_plot_reuse_cache(
                    "remove_plot_tab_by_plot_id_combined"
                )
            if (
                plot_key == "fig_cycle_timeline_tab"
                or str(plot_id or "") == "fig_cycle_timeline"
            ):
                try:
                    self._teardown_cycle_timeline_generated_tab_legend_tracking()
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
            controller = self._plot_annotation_controllers.pop(plot_id, None)
            if controller is not None:
                try:
                    controller.disconnect()
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
            self._plot_annotation_panels.pop(plot_id, None)
            self._plot_dirty_flags.pop(plot_id, None)
            self._plot_annotation_retarget_signature_cache.pop(plot_id, None)
            self._plot_annotation_retarget_skip_counts.pop(plot_id, None)
            self._plot_layer_refresh_state.pop(plot_id, None)
            window = self._plot_element_windows.pop(plot_id, None)
            if window is not None:
                try:
                    window.destroy()
                except Exception:
                    pass
            self._teardown_layout_editor(plot_id, apply_changes=False)
            if getattr(self, "_plot_settings_target_id", None) == plot_id:
                try:
                    self._close_plot_settings_dialog()
                except Exception:
                    pass
            try:
                self.nb.forget(tab)
            except Exception:
                pass
            if idx < len(canvases):
                try:
                    canvas_widget = canvases[idx].get_tk_widget()
                    canvas_widget.destroy()
                except Exception:
                    pass
                try:
                    plt.close(getattr(canvases[idx], "figure", None))
                except Exception:
                    pass
            try:
                tab.destroy()
            except Exception:
                pass
            try:
                del self._plot_tabs[idx]
                if idx < len(self._canvases):
                    del self._canvases[idx]
            except Exception:
                pass
            return True
        return False

    def _create_or_update_advanced_plot_tab(
        self,
        spec: Mapping[str, Any],
        *,
        preview: bool = False,
        replace_plot_id: Optional[str] = None,
        recipe_id: str = "",
    ) -> Optional[ttk.Frame]:
        """Render one advanced-plot tab and optionally replace an existing tab.

        Purpose:
            Materialize wizard specs into custom notebook tabs for preview/edit.
        Why:
            Advanced plot workflow requires preview rendering and persistent
            editable tabs without affecting core combined plot tabs.
        Inputs:
            spec: Raw/normalized advanced-plot specification payload.
            preview: True for reusable preview tab behavior.
            replace_plot_id: Optional plot ID to replace in-place.
            recipe_id: Optional recipe ID associated with the rendered spec.
        Outputs:
            Optional[ttk.Frame]: Created tab frame or None on failure.
        Side Effects:
            May remove existing tabs, create new tabs, and update preview tracking.
        Exceptions:
            Render errors show dialogs and return None.
        """
        try:
            fig, normalized_spec = self._build_advanced_plot_from_spec(spec)
        except Exception as exc:
            try:
                messagebox.showerror("Advanced Plot Wizard", str(exc))
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return None

        family = str(normalized_spec.get("family") or "line").strip().lower()
        family_label = ADVANCED_PLOT_WIZARD_FAMILY_LABELS.get(family, family.title())
        title_token = str(normalized_spec.get("title") or "").strip()
        tab_title = title_token if title_token else f"Advanced Plot - {family_label}"
        plot_key: str
        plot_id: str
        if preview:
            plot_key, plot_id = self._next_advanced_plot_identifiers(preview=True)
            tab_title = f"Advanced Preview - {family_label}"
            replace_plot_id = replace_plot_id or self._advanced_plot_preview_plot_id
        elif replace_plot_id:
            plot_key, plot_id = self._next_advanced_plot_identifiers(preview=False)
            for tab in list(getattr(self, "_plot_tabs", []) or []):
                if getattr(tab, "_plot_id", None) == replace_plot_id:
                    candidate_key = str(getattr(tab, "_plot_key", "") or "").strip()
                    if candidate_key:
                        plot_key = candidate_key
                    plot_id = replace_plot_id
                    try:
                        existing_title = str(self.nb.tab(tab, "text") or "")
                        if existing_title:
                            tab_title = existing_title
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting the workflow.
                        pass
                    break
        else:
            plot_key, plot_id = self._next_advanced_plot_identifiers(preview=False)
        if replace_plot_id:
            try:
                self._remove_plot_tab_by_plot_id(str(replace_plot_id))
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        frame = self._add_plot_tab(
            tab_title,
            fig,
            plot_key=plot_key,
            auto_refresh=False,
            advanced_plot_spec=normalized_spec,
            advanced_plot_recipe_id=str(recipe_id or "").strip(),
            plot_id_override=plot_id,
        )
        if preview:
            self._advanced_plot_preview_plot_id = plot_id
        return frame

    def _refresh_advanced_plot_tab(
        self,
        frame: Any,
        _canvas: Any,
        *,
        refresh_reason: Optional[str] = None,
    ) -> None:
        """Refresh one advanced wizard tab by rebuilding from stored spec.

        Purpose:
            Re-render advanced custom tabs using current dataset values.
        Why:
            Custom tabs must support one-click refresh and wizard edit round-trip.
        Inputs:
            frame: Plot-tab frame carrying advanced-plot metadata.
            _canvas: Unused existing canvas reference kept for signature parity.
            refresh_reason: Optional reason text for future diagnostics.
        Outputs:
            None.
        Side Effects:
            Replaces the target tab with a newly rendered tab using the same ID.
        Exceptions:
            Render failures are surfaced via dialogs.
        """
        _ = (refresh_reason, _canvas)
        spec_payload = getattr(frame, "_advanced_plot_spec", None)
        if not isinstance(spec_payload, Mapping):
            return
        plot_id = str(getattr(frame, "_plot_id", "") or "").strip()
        recipe_id = str(getattr(frame, "_advanced_plot_recipe_id", "") or "").strip()
        self._create_or_update_advanced_plot_tab(
            dict(spec_payload),
            preview=(plot_id == "advanced_plot_preview"),
            replace_plot_id=plot_id or None,
            recipe_id=recipe_id,
        )

    def _open_advanced_plot_wizard(
        self,
        *,
        seed_spec: Optional[Mapping[str, Any]] = None,
        edit_plot_id: Optional[str] = None,
        seed_recipe_id: Optional[str] = None,
    ) -> None:
        """Open the Advanced Plot Studio dialog for layered v2 recipe editing.

        Purpose:
            Provide one studio-style editor for building and re-editing mixed-layer
            advanced plots from unified observed/calculated/derived metric sources.
        Why:
            Wizard v2 needs a source-aware metric catalog and layer stack editor
            while preserving existing preview/render and recipe workflows.
        Inputs:
            seed_spec: Optional initial spec payload for edit/reuse actions.
            edit_plot_id: Optional custom-tab plot ID to replace on Render.
            seed_recipe_id: Optional recipe ID to pre-select in recipe controls.
        Outputs:
            None.
        Side Effects:
            Creates studio UI, reads/writes recipe settings, and renders custom tabs.
        Exceptions:
            User/input/render errors are surfaced via message dialogs.
        """
        source_frames = self._advanced_plot_source_frames()
        source_order = ["sheet_active", "timeline_analysis", "timeline_derived"]
        available_sources = [
            source_id
            for source_id in source_order
            if isinstance(source_frames.get(source_id), pd.DataFrame)
            and not source_frames.get(source_id, pd.DataFrame()).empty
        ]
        if not available_sources:
            messagebox.showinfo(
                "Advanced Plot Studio",
                "No active plotting source is available yet. Load sheet data or run timeline analysis first.",
            )
            return

        existing = getattr(self, "_advanced_plot_wizard_window", None)
        if existing is not None and existing.winfo_exists():
            try:
                existing.destroy()
            except Exception:
                pass

        metric_catalog = self._advanced_plot_metric_catalog(source_frames)
        metric_catalog = [
            dict(row)
            for row in metric_catalog
            if isinstance(row, Mapping)
            and str(row.get("source_id") or "").strip() in source_order
        ]
        metric_by_id: Dict[str, Dict[str, Any]] = {}
        for row in metric_catalog:
            metric_id = str(row.get("metric_id") or "").strip()
            if metric_id:
                metric_by_id[metric_id] = row

        library_payload = self._advanced_plot_recipe_library_payload()
        recipes = [
            dict(row)
            for row in list(library_payload.get("recipes") or [])
            if isinstance(row, Mapping)
        ]
        recipe_by_id = {
            str(row.get("id") or "").strip(): row
            for row in recipes
            if str(row.get("id") or "").strip()
        }
        profile_defaults = self._advanced_plot_profile_defaults_entry()
        default_recipe_id = str(profile_defaults.get("default_recipe_id") or "").strip()
        selected_recipe_id = str(seed_recipe_id or default_recipe_id).strip()
        normalized_seed = _normalize_advanced_plot_recipe_spec_payload(seed_spec)
        if (
            not seed_spec
            and selected_recipe_id
            and selected_recipe_id in recipe_by_id
        ):
            normalized_seed = _normalize_advanced_plot_recipe_spec_payload(
                recipe_by_id[selected_recipe_id].get("spec")
            )
        if str(normalized_seed.get("source_id") or "").strip() not in available_sources:
            normalized_seed["source_id"] = available_sources[0]

        window = tk.Toplevel(self)
        window.title("Advanced Plot Studio")
        window.transient(self)
        window.resizable(True, True)
        window.minsize(self._scale_length(1120), self._scale_length(700))
        self._advanced_plot_wizard_window = window
        window.grid_columnconfigure(0, weight=1)
        window.grid_rowconfigure(1, weight=1)

        source_var = tk.StringVar(
            value=str(normalized_seed.get("source_id") or available_sources[0])
        )
        title_var = tk.StringVar(value=str(normalized_seed.get("title") or ""))
        suptitle_var = tk.StringVar(value=str(normalized_seed.get("suptitle") or ""))
        legend_var = tk.StringVar(value=str(normalized_seed.get("legend_mode") or "auto"))
        show_grid_var = tk.BooleanVar(value=bool(normalized_seed.get("show_grid", True)))
        facet_enabled_var = tk.BooleanVar(
            value=bool(normalized_seed.get("facet_enabled", False))
        )
        facet_topk_var = tk.StringVar(
            value=str(int(normalized_seed.get("facet_top_k", 0) or 0))
        )
        ncols_var = tk.StringVar(value=str(int(normalized_seed.get("ncols", 2) or 2)))
        fig_w_var = tk.StringVar(
            value=str(float(normalized_seed.get("fig_width", 11.0) or 11.0))
        )
        fig_h_var = tk.StringVar(
            value=str(float(normalized_seed.get("fig_height", 8.5) or 8.5))
        )
        recipe_var = tk.StringVar(value=selected_recipe_id)
        search_var = tk.StringVar(value="")
        status_var = tk.StringVar(
            value=(
                "Select source metrics on the left, build layers in the center, "
                "and tune style/axes in the inspector."
            )
        )

        x_metric_var = tk.StringVar(value="")
        facet_metric_var = tk.StringVar(value="")
        layer_family_var = tk.StringVar(value="line")
        layer_axis_var = tk.StringVar(value="left")
        layer_enabled_var = tk.BooleanVar(value=True)
        layer_label_var = tk.StringVar(value="")
        layer_y_metric_var = tk.StringVar(value="")
        layer_error_metric_var = tk.StringVar(value="")
        layer_category_metric_var = tk.StringVar(value="")
        layer_value_metric_var = tk.StringVar(value="")
        layer_weights_metric_var = tk.StringVar(value="")
        layer_marker_var = tk.StringVar(value="o")
        layer_color_var = tk.StringVar(value="")
        layer_linestyle_var = tk.StringVar(value="solid")
        layer_linewidth_var = tk.StringVar(value="1.6")
        layer_alpha_var = tk.StringVar(value="0.85")
        layer_bar_width_var = tk.StringVar(value="0.55")
        layer_zorder_var = tk.StringVar(value="2.0")
        layer_bins_var = tk.StringVar(value="20")
        layer_aggregation_var = tk.StringVar(value="mean")

        layer_state: List[Dict[str, Any]] = [
            dict(row)
            for row in list(normalized_seed.get("layers") or [])
            if isinstance(row, Mapping)
        ]
        if not layer_state:
            layer_state = [
                _normalize_advanced_plot_layer_payload(
                    {
                        "family": str(normalized_seed.get("family") or "line"),
                        "source_id": str(source_var.get() or "sheet_active"),
                    },
                    default_source_id=str(source_var.get() or "sheet_active"),
                    default_family=str(normalized_seed.get("family") or "line"),
                )
            ]
        active_layer_index = 0
        metric_option_maps: Dict[str, Dict[str, str]] = {
            "all": {},
            "numeric": {},
            "x": {},
            "facet": {},
        }
        catalog_metric_ids: List[str] = []

        def _source_frame() -> pd.DataFrame:
            """Return the currently selected source dataframe for validation/rendering."""
            source_id = str(source_var.get() or "").strip()
            frame = source_frames.get(source_id)
            return frame if isinstance(frame, pd.DataFrame) else pd.DataFrame()

        def _recipe_values() -> List[str]:
            """Return ordered recipe labels for the recipe combobox."""
            order = [
                str(item).strip()
                for item in list(profile_defaults.get("recipe_order") or [])
                if str(item).strip()
            ]
            ordered_rows: List[Mapping[str, Any]] = []
            seen: Set[str] = set()
            for recipe_id_value in order:
                row = recipe_by_id.get(recipe_id_value)
                if isinstance(row, Mapping):
                    ordered_rows.append(row)
                    seen.add(recipe_id_value)
            for row in recipes:
                recipe_id_value = str(row.get("id") or "").strip()
                if recipe_id_value and recipe_id_value not in seen:
                    ordered_rows.append(row)
                    seen.add(recipe_id_value)
            return [
                f"{str(item.get('id') or '').strip()} | {str(item.get('name') or '').strip()}"
                for item in ordered_rows
                if str(item.get("id") or "").strip()
            ]

        def _recipe_id(value: str) -> str:
            """Extract one recipe ID token from combobox display text."""
            token = str(value or "").strip()
            return token.split("|", 1)[0].strip() if "|" in token else token

        def _metric_display(metric_row: Mapping[str, Any]) -> str:
            """Build one readable metric label for catalog and combobox controls."""
            label = str(metric_row.get("label") or "").strip() or str(
                metric_row.get("column_key") or "Metric"
            ).strip()
            observability = str(metric_row.get("observability") or "derived").strip()
            units = str(metric_row.get("units") or "").strip()
            column_key = str(metric_row.get("column_key") or "").strip()
            suffix = f" [{units}]" if units else ""
            return f"[{observability}] {label} ({column_key}){suffix}"

        def _metrics_for_source(
            source_id: str,
            *,
            include_empty: bool = False,
        ) -> List[Dict[str, Any]]:
            """Return one ordered metric list for the selected source and search filter."""
            search_token = str(search_var.get() or "").strip().lower()
            observability_rank = {
                "observed": 0,
                "calculated": 1,
                "calibrated": 2,
                "derived": 3,
            }
            rows: List[Dict[str, Any]] = []
            for row in metric_catalog:
                if str(row.get("source_id") or "").strip() != source_id:
                    continue
                if not include_empty and not bool(row.get("present", False)):
                    continue
                if search_token:
                    haystack = " ".join(
                        [
                            str(row.get("label") or ""),
                            str(row.get("column_key") or ""),
                            str(row.get("observability") or ""),
                            str(row.get("units") or ""),
                        ]
                    ).lower()
                    if search_token not in haystack:
                        continue
                rows.append(dict(row))
            rows.sort(
                key=lambda item: (
                    int(observability_rank.get(str(item.get("observability") or ""), 9)),
                    str(item.get("label") or ""),
                    str(item.get("column_key") or ""),
                )
            )
            return rows

        def _set_combo_values(
            combo: ttk.Combobox,
            key: str,
            rows: Sequence[Mapping[str, Any]],
            *,
            numeric_only: bool = False,
            x_axis: bool = False,
        ) -> None:
            """Populate one metric combobox and store its display->metric mapping."""
            mapping: Dict[str, str] = {"(None)": ""}
            values: List[str] = ["(None)"]
            for row in rows:
                data_kind = str(row.get("data_kind") or "category").strip().lower()
                if numeric_only and data_kind != "numeric":
                    continue
                if x_axis and data_kind not in {"numeric", "datetime", "category"}:
                    continue
                metric_id = str(row.get("metric_id") or "").strip()
                if not metric_id:
                    continue
                display = _metric_display(row)
                dedupe_suffix = 2
                original_display = display
                while display in mapping:
                    display = f"{original_display} #{dedupe_suffix}"
                    dedupe_suffix += 1
                mapping[display] = metric_id
                values.append(display)
            metric_option_maps[key] = mapping
            combo.configure(values=values)
            current_value = str(combo.get() or "").strip()
            if current_value and current_value not in mapping:
                combo.set("(None)")
            elif not current_value:
                combo.set("(None)")

        def _metric_id_from_choice(choice_value: str, key: str) -> str:
            """Resolve one metric ID from a combobox/list choice value."""
            mapping = metric_option_maps.get(key) or {}
            return str(mapping.get(str(choice_value or "").strip(), "") or "").strip()

        def _choice_from_metric_id(metric_id: str, key: str) -> str:
            """Resolve one combobox display value from a metric ID."""
            mapping = metric_option_maps.get(key) or {}
            metric_token = str(metric_id or "").strip()
            if not metric_token:
                return "(None)"
            for display, candidate_id in mapping.items():
                if str(candidate_id or "").strip() == metric_token:
                    return display
            return "(None)"

        def _parse_float(
            raw_value: Any,
            default_value: float,
            *,
            min_value: Optional[float] = None,
            max_value: Optional[float] = None,
        ) -> float:
            """Parse one float UI token with optional min/max clamping."""
            try:
                parsed = float(raw_value)
            except Exception:
                parsed = float(default_value)
            if not math.isfinite(parsed):
                parsed = float(default_value)
            if min_value is not None:
                parsed = max(parsed, float(min_value))
            if max_value is not None:
                parsed = min(parsed, float(max_value))
            return float(parsed)

        def _parse_int(
            raw_value: Any,
            default_value: int,
            *,
            min_value: Optional[int] = None,
            max_value: Optional[int] = None,
        ) -> int:
            """Parse one integer UI token with optional min/max clamping."""
            try:
                parsed = int(float(raw_value))
            except Exception:
                parsed = int(default_value)
            if min_value is not None:
                parsed = max(parsed, int(min_value))
            if max_value is not None:
                parsed = min(parsed, int(max_value))
            return int(parsed)

        def _safe_active_layer_index() -> int:
            """Return one in-range active layer index for layer state operations."""
            nonlocal active_layer_index
            if not layer_state:
                active_layer_index = 0
                return 0
            active_layer_index = max(0, min(active_layer_index, len(layer_state) - 1))
            return active_layer_index

        def _current_source_metric_id(metric_id: Any, source_id: str) -> str:
            """Normalize one metric ID for the selected source and available columns."""
            frame = source_frames.get(source_id)
            columns = {
                str(col).strip()
                for col in list(frame.columns)
            } if isinstance(frame, pd.DataFrame) else set()
            _, column_key = _advanced_plot_metric_parts(
                metric_id,
                default_source=source_id,
            )
            if not column_key or column_key not in columns:
                return ""
            return _advanced_plot_metric_id_from_column(column_key, source_id)

        def _refresh_metric_controls() -> None:
            """Refresh all metric selectors and catalog controls for current source/search."""
            source_id = str(source_var.get() or "").strip()
            if source_id not in source_order:
                source_id = available_sources[0]
                source_var.set(source_id)
            rows = _metrics_for_source(source_id)
            _set_combo_values(x_metric_combo, "x", rows, x_axis=True)
            _set_combo_values(facet_metric_combo, "facet", rows)
            _set_combo_values(layer_y_combo, "numeric", rows, numeric_only=True)
            _set_combo_values(layer_error_combo, "numeric", rows, numeric_only=True)
            _set_combo_values(layer_category_combo, "all", rows)
            _set_combo_values(layer_value_combo, "numeric", rows, numeric_only=True)
            _set_combo_values(layer_weights_combo, "numeric", rows, numeric_only=True)
            _refresh_metric_catalog_list()

        def _load_layer_into_inspector(index_value: Optional[int] = None) -> None:
            """Load one layer payload into inspector controls."""
            nonlocal active_layer_index
            if index_value is not None:
                active_layer_index = int(index_value)
            idx = _safe_active_layer_index()
            if not layer_state:
                return
            layer = dict(layer_state[idx])
            layer_family_var.set(str(layer.get("family") or "line"))
            layer_axis_var.set(str(layer.get("axis_id") or "left"))
            layer_enabled_var.set(bool(layer.get("enabled", True)))
            layer_label_var.set(str(layer.get("label") or ""))
            layer_y_metric_var.set(
                _choice_from_metric_id(str(layer.get("y_metric_id") or ""), "numeric")
            )
            layer_error_metric_var.set(
                _choice_from_metric_id(str(layer.get("error_metric_id") or ""), "numeric")
            )
            layer_category_metric_var.set(
                _choice_from_metric_id(str(layer.get("category_metric_id") or ""), "all")
            )
            layer_value_metric_var.set(
                _choice_from_metric_id(str(layer.get("value_metric_id") or ""), "numeric")
            )
            layer_weights_metric_var.set(
                _choice_from_metric_id(str(layer.get("weights_metric_id") or ""), "numeric")
            )
            layer_marker_var.set(str(layer.get("marker") or "o"))
            layer_color_var.set(str(layer.get("color") or ""))
            layer_linestyle_var.set(str(layer.get("linestyle") or "solid"))
            layer_linewidth_var.set(str(float(layer.get("linewidth", 1.6) or 1.6)))
            layer_alpha_var.set(str(float(layer.get("alpha", 0.85) or 0.85)))
            layer_bar_width_var.set(str(float(layer.get("bar_width", 0.55) or 0.55)))
            layer_zorder_var.set(str(float(layer.get("zorder", 2.0) or 2.0)))
            layer_bins_var.set(str(int(layer.get("bins", 20) or 20)))
            layer_aggregation_var.set(str(layer.get("aggregation") or "mean"))

        def _commit_inspector_layer() -> None:
            """Write inspector control values back into the active layer payload."""
            idx = _safe_active_layer_index()
            if not layer_state:
                return
            source_id = str(source_var.get() or "sheet_active").strip() or "sheet_active"
            layer_payload = {
                "id": str(layer_state[idx].get("id") or f"layer_{idx + 1}").strip()
                or f"layer_{idx + 1}",
                "source_id": source_id,
                "family": str(layer_family_var.get() or "line").strip().lower() or "line",
                "axis_id": str(layer_axis_var.get() or "left").strip().lower() or "left",
                "enabled": bool(layer_enabled_var.get()),
                "label": str(layer_label_var.get() or "").strip(),
                "y_metric_id": _metric_id_from_choice(layer_y_metric_var.get(), "numeric"),
                "error_metric_id": _metric_id_from_choice(layer_error_metric_var.get(), "numeric"),
                "category_metric_id": _metric_id_from_choice(layer_category_metric_var.get(), "all"),
                "value_metric_id": _metric_id_from_choice(layer_value_metric_var.get(), "numeric"),
                "weights_metric_id": _metric_id_from_choice(layer_weights_metric_var.get(), "numeric"),
                "marker": str(layer_marker_var.get() or "o").strip() or "o",
                "color": str(layer_color_var.get() or "").strip(),
                "linestyle": str(layer_linestyle_var.get() or "solid").strip() or "solid",
                "linewidth": _parse_float(layer_linewidth_var.get(), 1.6, min_value=0.1, max_value=12.0),
                "alpha": _parse_float(layer_alpha_var.get(), 0.85, min_value=0.05, max_value=1.0),
                "bar_width": _parse_float(layer_bar_width_var.get(), 0.55, min_value=0.05, max_value=2.0),
                "zorder": _parse_float(layer_zorder_var.get(), 2.0, min_value=0.0, max_value=50.0),
                "bins": _parse_int(layer_bins_var.get(), 20, min_value=1, max_value=300),
                "aggregation": str(layer_aggregation_var.get() or "mean").strip().lower() or "mean",
            }
            layer_state[idx] = _normalize_advanced_plot_layer_payload(
                layer_payload,
                default_source_id=source_id,
                default_family=str(layer_family_var.get() or "line"),
            )
            _refresh_layer_list()

        def _refresh_layer_list() -> None:
            """Rebuild center-panel layer stack list from normalized layer state."""
            layer_listbox.delete(0, tk.END)
            for idx, layer in enumerate(layer_state, start=1):
                family = str(layer.get("family") or "line").strip().lower()
                family_label = ADVANCED_PLOT_WIZARD_FAMILY_LABELS.get(
                    family, family.title()
                )
                axis_id = str(layer.get("axis_id") or "left").strip().lower()
                enabled = bool(layer.get("enabled", True))
                label = str(layer.get("label") or "").strip()
                if not label:
                    _, y_column = _advanced_plot_metric_parts(
                        layer.get("y_metric_id"),
                        default_source=str(source_var.get() or "sheet_active"),
                    )
                    label = y_column or f"Layer {idx}"
                onoff = "ON" if enabled else "OFF"
                layer_listbox.insert(
                    tk.END,
                    f"{idx}. [{onoff}] {family_label} | {axis_id} | {label}",
                )
            idx = _safe_active_layer_index()
            if layer_state:
                layer_listbox.selection_clear(0, tk.END)
                layer_listbox.selection_set(idx)
                layer_listbox.activate(idx)

        def _selected_catalog_metric_id() -> str:
            """Return metric ID for current left-catalog selection."""
            selected = list(metric_listbox.curselection() or [])
            if not selected:
                return ""
            idx = int(selected[0])
            if idx < 0 or idx >= len(catalog_metric_ids):
                return ""
            return str(catalog_metric_ids[idx] or "").strip()

        def _refresh_metric_catalog_list() -> None:
            """Refresh left metric catalog list for source/search filters."""
            source_id = str(source_var.get() or "").strip()
            rows = _metrics_for_source(source_id, include_empty=True)
            metric_listbox.delete(0, tk.END)
            catalog_metric_ids.clear()
            for row in rows:
                metric_id = str(row.get("metric_id") or "").strip()
                if not metric_id:
                    continue
                display = _metric_display(row)
                if not bool(row.get("present", False)):
                    display = f"{display} [missing]"
                metric_listbox.insert(tk.END, display)
                catalog_metric_ids.append(metric_id)

        def _apply_metric_to_target(target: str) -> None:
            """Apply selected catalog metric to one target selector field."""
            metric_id = _selected_catalog_metric_id()
            if not metric_id:
                status_var.set("Select a metric from the catalog first.")
                return
            if target == "x":
                x_metric_var.set(_choice_from_metric_id(metric_id, "x"))
            elif target == "facet":
                facet_metric_var.set(_choice_from_metric_id(metric_id, "facet"))
            elif target == "y":
                layer_y_metric_var.set(_choice_from_metric_id(metric_id, "numeric"))
            elif target == "error":
                layer_error_metric_var.set(_choice_from_metric_id(metric_id, "numeric"))
            elif target == "category":
                layer_category_metric_var.set(_choice_from_metric_id(metric_id, "all"))
            elif target == "value":
                layer_value_metric_var.set(_choice_from_metric_id(metric_id, "numeric"))
            elif target == "weights":
                layer_weights_metric_var.set(_choice_from_metric_id(metric_id, "numeric"))
            _commit_inspector_layer()
            status_var.set("Metric assignment updated.")

        def _collect_spec() -> Dict[str, Any]:
            """Collect one normalized v2 advanced-plot spec from studio controls."""
            _commit_inspector_layer()
            source_id = str(source_var.get() or "sheet_active").strip() or "sheet_active"
            payload = {
                "schema_version": "v2",
                "source_id": source_id,
                "layers": list(layer_state),
                "x_metric_id": _metric_id_from_choice(x_metric_var.get(), "x"),
                "facet_metric_id": _metric_id_from_choice(facet_metric_var.get(), "facet"),
                "title": str(title_var.get() or "").strip(),
                "suptitle": str(suptitle_var.get() or "").strip(),
                "facet_enabled": bool(facet_enabled_var.get()),
                "facet_top_k": _parse_int(facet_topk_var.get(), 0, min_value=0, max_value=500),
                "ncols": _parse_int(ncols_var.get(), 2, min_value=1, max_value=6),
                "legend_mode": str(legend_var.get() or "auto").strip() or "auto",
                "show_grid": bool(show_grid_var.get()),
                "fig_width": _parse_float(fig_w_var.get(), 11.0, min_value=4.0, max_value=32.0),
                "fig_height": _parse_float(fig_h_var.get(), 8.5, min_value=3.0, max_value=24.0),
            }
            return _normalize_advanced_plot_recipe_spec_payload(payload)

        def _apply_spec(spec_payload: Mapping[str, Any]) -> None:
            """Apply one seed or recipe spec payload into studio controls."""
            nonlocal active_layer_index
            normalized = _normalize_advanced_plot_recipe_spec_payload(spec_payload)
            source_id = str(normalized.get("source_id") or "").strip()
            if source_id not in available_sources:
                source_id = available_sources[0]
            source_var.set(source_id)
            title_var.set(str(normalized.get("title") or ""))
            suptitle_var.set(str(normalized.get("suptitle") or ""))
            legend_var.set(str(normalized.get("legend_mode") or "auto"))
            show_grid_var.set(bool(normalized.get("show_grid", True)))
            facet_enabled_var.set(bool(normalized.get("facet_enabled", False)))
            facet_topk_var.set(str(int(normalized.get("facet_top_k", 0) or 0)))
            ncols_var.set(str(int(normalized.get("ncols", 2) or 2)))
            fig_w_var.set(str(float(normalized.get("fig_width", 11.0) or 11.0)))
            fig_h_var.set(str(float(normalized.get("fig_height", 8.5) or 8.5)))
            layer_state.clear()
            for row in list(normalized.get("layers") or []):
                if not isinstance(row, Mapping):
                    continue
                layer = dict(row)
                layer_source = source_id
                layer["source_id"] = layer_source
                # Keep source switching deterministic by remapping known columns
                # to the active source and clearing incompatible references.
                for metric_key in (
                    "y_metric_id",
                    "error_metric_id",
                    "category_metric_id",
                    "value_metric_id",
                    "weights_metric_id",
                ):
                    layer[metric_key] = _current_source_metric_id(
                        layer.get(metric_key),
                        layer_source,
                    )
                layer_state.append(
                    _normalize_advanced_plot_layer_payload(
                        layer,
                        default_source_id=layer_source,
                        default_family=str(layer.get("family") or "line"),
                    )
                )
            if not layer_state:
                layer_state.append(
                    _normalize_advanced_plot_layer_payload(
                        {"family": "line", "source_id": source_id},
                        default_source_id=source_id,
                        default_family="line",
                    )
                )
            _refresh_metric_controls()
            x_metric_var.set(
                _choice_from_metric_id(
                    _current_source_metric_id(normalized.get("x_metric_id"), source_id),
                    "x",
                )
            )
            facet_metric_var.set(
                _choice_from_metric_id(
                    _current_source_metric_id(normalized.get("facet_metric_id"), source_id),
                    "facet",
                )
            )
            active_layer_index = 0
            _refresh_layer_list()
            _load_layer_into_inspector(0)
            status_var.set("Spec loaded into Advanced Plot Studio.")

        def _on_source_change(*_args: Any) -> None:
            """Handle source selector updates and remap layer/global metric IDs."""
            source_id = str(source_var.get() or "").strip()
            if source_id not in available_sources:
                if available_sources:
                    source_var.set(available_sources[0])
                return
            for idx, layer in enumerate(layer_state):
                updated = dict(layer)
                updated["source_id"] = source_id
                for metric_key in (
                    "y_metric_id",
                    "error_metric_id",
                    "category_metric_id",
                    "value_metric_id",
                    "weights_metric_id",
                ):
                    updated[metric_key] = _current_source_metric_id(
                        updated.get(metric_key),
                        source_id,
                    )
                layer_state[idx] = _normalize_advanced_plot_layer_payload(
                    updated,
                    default_source_id=source_id,
                    default_family=str(updated.get("family") or "line"),
                )
            x_metric_id = _metric_id_from_choice(x_metric_var.get(), "x")
            facet_metric_id = _metric_id_from_choice(facet_metric_var.get(), "facet")
            _refresh_metric_controls()
            x_metric_var.set(_choice_from_metric_id(_current_source_metric_id(x_metric_id, source_id), "x"))
            facet_metric_var.set(
                _choice_from_metric_id(
                    _current_source_metric_id(facet_metric_id, source_id),
                    "facet",
                )
            )
            _refresh_layer_list()
            _load_layer_into_inspector(_safe_active_layer_index())

        def _on_layer_select(_event: Optional[Any] = None) -> None:
            """Handle user layer-stack selection changes."""
            nonlocal active_layer_index
            _commit_inspector_layer()
            selection = list(layer_listbox.curselection() or [])
            if not selection:
                return
            active_layer_index = int(selection[0])
            _load_layer_into_inspector(active_layer_index)

        def _add_layer(duplicate: bool = False) -> None:
            """Insert one new layer or duplicate the active layer."""
            nonlocal active_layer_index
            _commit_inspector_layer()
            source_id = str(source_var.get() or "sheet_active").strip() or "sheet_active"
            if duplicate and layer_state:
                base_layer = dict(layer_state[_safe_active_layer_index()])
                base_layer["id"] = f"layer_{uuid.uuid4().hex[:8]}"
                layer_state.insert(_safe_active_layer_index() + 1, base_layer)
                active_layer_index = min(
                    _safe_active_layer_index() + 1,
                    len(layer_state) - 1,
                )
            else:
                layer_state.append(
                    _normalize_advanced_plot_layer_payload(
                        {"family": "line", "source_id": source_id},
                        default_source_id=source_id,
                        default_family="line",
                    )
                )
                active_layer_index = len(layer_state) - 1
            _refresh_layer_list()
            _load_layer_into_inspector(active_layer_index)

        def _remove_layer() -> None:
            """Remove the selected layer while keeping at least one layer available."""
            nonlocal active_layer_index
            if len(layer_state) <= 1:
                status_var.set("At least one layer is required.")
                return
            idx = _safe_active_layer_index()
            layer_state.pop(idx)
            active_layer_index = max(0, min(idx, len(layer_state) - 1))
            _refresh_layer_list()
            _load_layer_into_inspector(active_layer_index)

        def _move_layer(direction: int) -> None:
            """Move the active layer up or down in the layer stack."""
            nonlocal active_layer_index
            _commit_inspector_layer()
            idx = _safe_active_layer_index()
            target = idx + int(direction)
            if target < 0 or target >= len(layer_state):
                return
            layer_state[idx], layer_state[target] = layer_state[target], layer_state[idx]
            active_layer_index = target
            _refresh_layer_list()
            _load_layer_into_inspector(active_layer_index)

        def _toggle_layer_enabled() -> None:
            """Toggle enabled state for the selected layer."""
            idx = _safe_active_layer_index()
            layer = dict(layer_state[idx])
            layer["enabled"] = not bool(layer.get("enabled", True))
            layer_state[idx] = _normalize_advanced_plot_layer_payload(
                layer,
                default_source_id=str(source_var.get() or "sheet_active"),
                default_family=str(layer.get("family") or "line"),
            )
            _load_layer_into_inspector(idx)
            _refresh_layer_list()

        def _load_recipe() -> None:
            """Load the selected persisted recipe into the studio editor."""
            recipe_id_token = _recipe_id(recipe_var.get())
            recipe_row = recipe_by_id.get(recipe_id_token) or {}
            _apply_spec(recipe_row.get("spec") or {})

        def _save_recipe() -> None:
            """Save current studio state as a normalized v2 recipe entry."""
            spec_payload = _collect_spec()
            frame = _source_frame()
            ok, msg, normalized = _validate_advanced_plot_spec_for_dataframe(
                frame,
                spec_payload,
            )
            if not ok:
                status_var.set(msg)
                messagebox.showwarning("Advanced Plot Studio", msg)
                return
            name = simpledialog.askstring(
                "Save Recipe",
                "Recipe name:",
                initialvalue=str(normalized.get("title") or "Advanced Plot Recipe"),
                parent=window,
            )
            name = str(name or "").strip()
            if not name:
                return
            recipe_id_token = _recipe_id(recipe_var.get())
            if not recipe_id_token or recipe_id_token not in recipe_by_id:
                recipe_id_token = f"recipe_{uuid.uuid4().hex[:12]}"
            row = {
                "id": recipe_id_token,
                "name": name,
                "spec": normalized,
                "updated_at": datetime.utcnow().isoformat(timespec="seconds") + "Z",
            }
            replaced = False
            for idx, item in enumerate(recipes):
                if str(item.get("id") or "").strip() == recipe_id_token:
                    recipes[idx] = row
                    replaced = True
                    break
            if not replaced:
                recipes.append(row)
            normalized_library = _normalize_advanced_plot_recipe_library_payload(
                {"recipes": recipes}
            )
            self._settings_dict()[
                ADVANCED_PLOT_WIZARD_RECIPE_LIBRARY_SETTINGS_KEY
            ] = normalized_library
            recipes[:] = [
                dict(item)
                for item in list(normalized_library.get("recipes") or [])
                if isinstance(item, Mapping)
            ]
            recipe_by_id.clear()
            recipe_by_id.update(
                {
                    str(item.get("id") or "").strip(): item
                    for item in recipes
                    if str(item.get("id") or "").strip()
                }
            )
            order = [
                item
                for item in list(profile_defaults.get("recipe_order") or [])
                if item in recipe_by_id and item != recipe_id_token
            ]
            order.insert(0, recipe_id_token)
            default_id = (
                str(profile_defaults.get("default_recipe_id") or "").strip()
                or recipe_id_token
            )
            self._advanced_plot_set_profile_defaults_entry(
                default_recipe_id=default_id,
                recipe_order=order,
            )
            profile_defaults["default_recipe_id"] = default_id
            profile_defaults["recipe_order"] = list(order)
            recipe_combo.configure(values=_recipe_values())
            recipe_var.set(f"{recipe_id_token} | {name}")
            status_var.set(f"Saved recipe '{name}'.")
            try:
                self._schedule_save_settings()
            except Exception:
                pass

        def _set_profile_default() -> None:
            """Set selected recipe as default for the active profile."""
            recipe_id_token = _recipe_id(recipe_var.get())
            if not recipe_id_token:
                status_var.set("Select a recipe before setting a profile default.")
                return
            order = [recipe_id_token] + [
                item
                for item in list(profile_defaults.get("recipe_order") or [])
                if item != recipe_id_token
            ]
            self._advanced_plot_set_profile_defaults_entry(
                default_recipe_id=recipe_id_token,
                recipe_order=order,
            )
            profile_defaults["default_recipe_id"] = recipe_id_token
            profile_defaults["recipe_order"] = list(order)
            status_var.set("Selected recipe is now the active profile default.")

        def _render(preview: bool) -> None:
            """Validate and render current studio spec to preview or custom tab."""
            spec_payload = _collect_spec()
            frame = _source_frame()
            ok, msg, normalized = _validate_advanced_plot_spec_for_dataframe(
                frame,
                spec_payload,
            )
            if not ok:
                status_var.set(msg)
                messagebox.showwarning("Advanced Plot Studio", msg)
                return
            recipe_id_token = _recipe_id(recipe_var.get())
            frame_obj = self._create_or_update_advanced_plot_tab(
                normalized,
                preview=preview,
                replace_plot_id=(
                    self._advanced_plot_preview_plot_id if preview else edit_plot_id
                ),
                recipe_id=recipe_id_token,
            )
            if frame_obj is not None:
                status_var.set(
                    "Preview rendered." if preview else "Custom layered plot rendered."
                )

