    def _profile_storage_dir(self) -> Optional[Path]:
        """Perform profile storage dir.
        Used to keep the workflow logic localized and testable."""
        base_dir = Path(__file__).resolve().parent
        profiles_dir = base_dir / "profiles"
        try:
            profiles_dir.mkdir(parents=True, exist_ok=True)
        except Exception as exc:
            messagebox.showerror(
                "Profiles",
                f"Could not create the profiles folder:\n{exc}",
            )
            return None
        return profiles_dir

    def _resolve_current_workspace_profile(
        self, *, normalize: bool = True, persist: bool = False
    ) -> Tuple[Optional[str], Optional[Path]]:
        """Resolve the currently tracked workspace profile.

        Purpose:
            Read, validate, and canonicalize the active profile identity from
            persisted settings.
        Why:
            The profile manager Save workflow depends on a reliable "current
            profile" target that survives app restarts and stale-file cases.
        Args:
            normalize: True to rewrite invalid/misaligned settings to canonical
                values (or clear them when invalid).
            persist: True to flush normalization changes to `settings.json`.
        Returns:
            Tuple of `(profile_name, profile_path)` when valid, else `(None, None)`.
        Side Effects:
            May mutate `settings["current_workspace_profile_name"]` and
            `settings["current_workspace_profile_path"]`.
        Exceptions:
            Filesystem/path resolution failures are treated as invalid state and
            clear current-profile settings when normalization is enabled.
        """
        raw_name = settings.get("current_workspace_profile_name", "")
        raw_path = str(settings.get("current_workspace_profile_path", "") or "").strip()
        safe_name = self._sanitize_profile_name(str(raw_name or ""))
        expected_path = _workspace_profile_expected_path(safe_name)
        is_valid = False
        if safe_name and expected_path is not None and expected_path.exists():
            expected_resolved = None
            try:
                expected_resolved = expected_path.resolve()
            except Exception:
                expected_resolved = None
            if expected_resolved is not None:
                if raw_path:
                    try:
                        is_valid = Path(raw_path).resolve() == expected_resolved
                    except Exception:
                        is_valid = False
                else:
                    # Accept legacy state that only stored a name and backfill path.
                    is_valid = True
        if not is_valid:
            changed = bool(raw_name) or bool(raw_path)
            if normalize and changed:
                settings["current_workspace_profile_name"] = ""
                settings["current_workspace_profile_path"] = ""
                if persist:
                    try:
                        _save_settings_to_disk()
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting the workflow.
                        pass
            return None, None
        canonical_path = str(expected_path)
        changed = (
            settings.get("current_workspace_profile_name") != safe_name
            or settings.get("current_workspace_profile_path") != canonical_path
        )
        if normalize and changed:
            settings["current_workspace_profile_name"] = safe_name
            settings["current_workspace_profile_path"] = canonical_path
            if persist:
                try:
                    _save_settings_to_disk()
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
        return safe_name, expected_path

    def _set_current_workspace_profile(self, name: str, *, persist: bool = True) -> None:
        """Set and optionally persist the current workspace profile.

        Purpose:
            Record which profile the active workspace represents.
        Why:
            The new Profile Manager Save action needs an explicit overwrite target
            and clear user feedback for what will be saved.
        Args:
            name: Profile name to track as current.
            persist: True to write updated keys to `settings.json` immediately.
        Returns:
            None.
        Side Effects:
            Updates current-profile keys in `settings`, may write settings to disk,
            and refreshes Current Profile UI labels when available.
        Exceptions:
            Invalid names or missing profile files clear current-profile state.
        """
        safe_name = self._sanitize_profile_name(name)
        expected_path = _workspace_profile_expected_path(safe_name)
        if not safe_name or expected_path is None or not expected_path.exists():
            self._clear_current_workspace_profile(persist=persist)
            return
        settings["current_workspace_profile_name"] = safe_name
        settings["current_workspace_profile_path"] = str(expected_path)
        if persist:
            try:
                _save_settings_to_disk()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        self._refresh_current_profile_section()

    def _clear_current_workspace_profile(self, *, persist: bool = True) -> None:
        """Clear the tracked current workspace profile.

        Purpose:
            Remove stale or deleted current-profile identity.
        Why:
            Save workflows must not silently target files that no longer exist.
        Args:
            persist: True to write cleared keys to `settings.json` immediately.
        Returns:
            None.
        Side Effects:
            Clears current-profile keys in `settings`, may write settings to disk,
            and refreshes Current Profile UI labels when available.
        Exceptions:
            None; disk write is best-effort.
        """
        settings["current_workspace_profile_name"] = ""
        settings["current_workspace_profile_path"] = ""
        if persist:
            try:
                _save_settings_to_disk()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        self._refresh_current_profile_section()

    def _refresh_current_profile_section(self) -> None:
        """Refresh Current Profile labels in the Profile Manager UI.

        Purpose:
            Synchronize displayed current-profile name/path with persisted state.
        Why:
            Users need an explicit visual confirmation of which profile Save will
            target.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Updates Tk StringVar values bound to the Profile Manager labels.
        Exceptions:
            Falls back to "Not set" labels when current-profile state is invalid.
        """
        profile_name, profile_path = self._resolve_current_workspace_profile(
            normalize=True, persist=False
        )
        display_name = profile_name if profile_name else "Not set"
        display_path = str(profile_path) if profile_path is not None else "Not set"
        name_var = getattr(self, "_profile_current_name_var", None)
        if isinstance(name_var, tk.StringVar):
            name_var.set(display_name)
        path_var = getattr(self, "_profile_current_path_var", None)
        if isinstance(path_var, tk.StringVar):
            path_var.set(display_path)
        data_name_var = getattr(self, "_data_current_profile_name_var", None)
        if isinstance(data_name_var, tk.StringVar):
            data_name_var.set(display_name)
        data_path_var = getattr(self, "_data_current_profile_path_var", None)
        if isinstance(data_path_var, tk.StringVar):
            data_path_var.set(display_path)

    def _sanitize_profile_name(self, name: str) -> str:
        """Sanitize profile name.
        Used to strip or normalize profile name before use."""
        if not isinstance(name, str):
            return ""
        cleaned = name.strip()
        cleaned = re.sub(r"[<>:\"/\\\\|?*]", "_", cleaned)
        cleaned = re.sub(r"\s+", " ", cleaned)
        cleaned = cleaned.strip(" .")
        return cleaned

    def _profile_path(self, name: str) -> Optional[Path]:
        """Perform profile path.
        Used to keep the workflow logic localized and testable."""
        profiles_dir = self._profile_storage_dir()
        if profiles_dir is None:
            return None
        safe_name = self._sanitize_profile_name(name)
        if not safe_name:
            return None
        return profiles_dir / f"{safe_name}.json"

    def _profile_timestamp(self) -> str:
        """Perform profile timestamp.
        Used to keep the workflow logic localized and testable."""
        return datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    def _read_profile_document(self, path: Path) -> Optional[Dict[str, Any]]:
        """Perform read profile document.
        Used to keep the workflow logic localized and testable."""
        try:
            with path.open("r", encoding="utf-8") as handle:
                payload = json.load(handle)
        except Exception as exc:
            messagebox.showerror("Profiles", f"Could not read profile:\n{exc}")
            return None
        if not isinstance(payload, dict):
            messagebox.showerror("Profiles", "Profile data is invalid.")
            return None
        return payload

    def _write_profile_document(
        self, path: Path, payload: Dict[str, Any], *, show_errors: bool = True
    ) -> bool:
        """Perform write profile document.
        Used to keep the workflow logic localized and testable."""
        try:
            with path.open("w", encoding="utf-8") as handle:
                json.dump(payload, handle, indent=2, sort_keys=True)
                handle.write("\n")
        except Exception as exc:
            if show_errors:
                messagebox.showerror("Profiles", f"Could not save profile:\n{exc}")
            return False
        return True

    def _list_profile_names(self) -> List[str]:
        """Perform list profile names.
        Used to keep the workflow logic localized and testable."""
        profiles_dir = self._profile_storage_dir()
        if profiles_dir is None or not profiles_dir.exists():
            return []
        names: List[str] = []
        # Iterate over profiles_dir.glob("*.json") to apply the per-item logic.
        for profile_path in profiles_dir.glob("*.json"):
            stem = profile_path.stem
            if stem in {"index", "_autosave_last_workspace"}:
                continue
            if stem.startswith("_"):
                continue
            names.append(stem)
        names.sort(key=lambda value: value.lower())
        return names

    def _refresh_profile_listbox(self, *, select_name: Optional[str] = None) -> None:
        """Refresh profile list selection and Current Profile labels.

        Purpose:
            Rebuild the profile listbox from disk and select the requested item.
        Why:
            Profile CRUD actions must keep list selection and current-profile
            status synchronized.
        Args:
            select_name: Optional profile name to select after refresh.
        Returns:
            None.
        Side Effects:
            Rewrites listbox rows, updates selection, and refreshes Current
            Profile label values.
        Exceptions:
            None.
        """
        listbox = getattr(self, "_profile_manager_listbox", None)
        if listbox is None:
            self._refresh_current_profile_section()
            return
        names = self._list_profile_names()
        target_name = select_name
        if not target_name:
            target_name, _ = self._resolve_current_workspace_profile(
                normalize=True, persist=False
            )
        listbox.delete(0, tk.END)
        # Iterate over names to apply the per-item logic.
        for name in names:
            listbox.insert(tk.END, name)
        if target_name and target_name in names:
            idx = names.index(target_name)
            listbox.selection_set(idx)
            listbox.see(idx)
        self._refresh_current_profile_section()

    def _selected_profile_name(self) -> Optional[str]:
        """Perform selected profile name.
        Used to keep the workflow logic localized and testable."""
        listbox = getattr(self, "_profile_manager_listbox", None)
        if listbox is None:
            return None
        selection = listbox.curselection()
        if not selection:
            return None
        return listbox.get(selection[0])

    def _open_profile_manager(self) -> None:
        """Open the Profiles Manager dialog.

        Purpose:
            Present the profile list and profile actions in a modal dialog.
        Why:
            Centralizes profile creation, load, and maintenance workflows.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Creates Tk widgets, measures profile-name content width to size the
            initial window geometry, binds callbacks, and captures dialog references.
        Exceptions:
            Best-effort guards keep UI focus and window creation resilient.
        """
        existing = getattr(self, "_profile_manager_window", None)
        if existing is not None and existing.winfo_exists():
            try:
                existing.deiconify()
                existing.lift()
                existing.focus_force()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return

        window = tk.Toplevel(self)
        window.title("Process Profiles")
        window.transient(self)
        window.resizable(True, True)
        self._profile_manager_window = window

        profile_names = self._list_profile_names()
        max_profile_name_chars = max(
            [len(str(name)) for name in profile_names] + [len("Profile Name")]
        )
        try:
            measure_font = tkfont.nametofont("TkDefaultFont")
        except Exception:
            measure_font = tkfont.Font(
                family=getattr(self, "_ui_font_family", "Verdana"), size=10
            )
        try:
            longest_profile_name_px = max(
                [int(measure_font.measure(str(name))) for name in profile_names]
                + [int(measure_font.measure("Profile Name"))]
            )
        except Exception:
            longest_profile_name_px = max_profile_name_chars * self._scale_length(8)

        # Closure captures _open_profile_manager state for callback wiring, kept nested to scope the handler, and invoked by bindings set in _open_profile_manager.
        def _close_window() -> None:
            """Close window.
            Used by UI actions to close window safely."""
            try:
                window.grab_release()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                window.destroy()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            self._profile_manager_window = None
            self._profile_manager_listbox = None

        window.protocol("WM_DELETE_WINDOW", _close_window)
        ctk_module = ctk
        if ctk_module is not None:
            container: Any = ctk_module.CTkFrame(window, corner_radius=10)
            container.grid(row=0, column=0, sticky="nsew", padx=12, pady=12)
        else:
            container = ttk.Frame(window, padding=12)
            container.grid(row=0, column=0, sticky="nsew")
        window.grid_rowconfigure(0, weight=1)
        window.grid_columnconfigure(0, weight=1)
        container.grid_rowconfigure(2, weight=1)
        container.grid_columnconfigure(0, weight=1)

        if ctk_module is not None:
            ctk_module.CTkLabel(
                container,
                text="Profiles",
                anchor="w",
                font=(getattr(self, "_ui_font_family", "Verdana"), 14, "bold"),
            ).grid(row=0, column=0, sticky="w")
        else:
            ttk.Label(container, text="Profiles").grid(row=0, column=0, sticky="w")

        current_shell: Any
        if ctk_module is not None:
            current_shell = ctk_module.CTkFrame(container, corner_radius=8)
            current_shell.grid(
                row=1, column=0, columnspan=3, sticky="ew", pady=(6, 0), padx=(0, 0)
            )
            current_shell.grid_columnconfigure(1, weight=1)
            ctk_module.CTkLabel(
                current_shell,
                text="Current Profile",
                anchor="w",
                font=(getattr(self, "_ui_font_family", "Verdana"), 12, "bold"),
            ).grid(row=0, column=0, columnspan=2, sticky="ew", padx=10, pady=(8, 2))
            ctk_module.CTkLabel(current_shell, text="Name:", anchor="w").grid(
                row=1, column=0, sticky="w", padx=(10, 8), pady=2
            )
            ctk_module.CTkLabel(
                current_shell,
                textvariable=self._profile_current_name_var,
                anchor="w",
            ).grid(row=1, column=1, sticky="ew", padx=(0, 10), pady=2)
            ctk_module.CTkLabel(current_shell, text="Path:", anchor="w").grid(
                row=2, column=0, sticky="nw", padx=(10, 8), pady=(2, 8)
            )
            ctk_module.CTkLabel(
                current_shell,
                textvariable=self._profile_current_path_var,
                anchor="w",
                justify="left",
                wraplength=self._scale_length(560),
            ).grid(row=2, column=1, sticky="ew", padx=(0, 10), pady=(2, 8))
        else:
            current_shell = ttk.Labelframe(container, text="Current Profile")
            current_shell.grid(row=1, column=0, columnspan=3, sticky="ew", pady=(6, 0))
            current_shell.grid_columnconfigure(1, weight=1)
            ttk.Label(current_shell, text="Name:").grid(
                row=0, column=0, sticky="w", padx=(8, 8), pady=2
            )
            ttk.Label(
                current_shell,
                textvariable=self._profile_current_name_var,
            ).grid(row=0, column=1, sticky="w", padx=(0, 8), pady=2)
            ttk.Label(current_shell, text="Path:").grid(
                row=1, column=0, sticky="nw", padx=(8, 8), pady=(2, 8)
            )
            ttk.Label(
                current_shell,
                textvariable=self._profile_current_path_var,
                justify="left",
                wraplength=self._scale_length(560),
            ).grid(row=1, column=1, sticky="w", padx=(0, 8), pady=(2, 8))

        list_shell: Any
        if ctk_module is not None:
            list_shell = ctk_module.CTkFrame(container, corner_radius=8)
            list_shell.grid(row=2, column=0, sticky="nsew", pady=(6, 0))
        else:
            list_shell = ttk.Frame(container)
            list_shell.grid(row=2, column=0, sticky="nsew", pady=(6, 0))
        list_shell.grid_rowconfigure(0, weight=1)
        list_shell.grid_columnconfigure(0, weight=1)

        listbox = tk.Listbox(
            list_shell,
            exportselection=False,
            height=10,
            width=max(36, min(96, max_profile_name_chars + 2)),
        )
        listbox.grid(row=0, column=0, sticky="nsew", padx=4, pady=4)

        if ctk_module is not None:
            appearance_mode = ""
            try:
                appearance_mode = str(ctk_module.get_appearance_mode() or "").lower()
            except Exception:
                appearance_mode = ""
            is_dark_mode = (
                appearance_mode == "dark"
                or _normalize_ui_display_mode(settings.get("ui_display_mode"))
                == DISPLAY_MODE_DARK
            )
            if is_dark_mode:
                colors = {
                    "background": "#1F252D",
                    "foreground": "#F1F3F5",
                    "selectbackground": "#2F80ED",
                    "selectforeground": "#FFFFFF",
                    "border": "#4A5568",
                }
            else:
                colors = {
                    "background": "#F6F8FA",
                    "foreground": "#111827",
                    "selectbackground": "#1F6FD1",
                    "selectforeground": "#FFFFFF",
                    "border": "#C7CDD3",
                }
            try:
                listbox.configure(
                    bg=colors["background"],
                    fg=colors["foreground"],
                    selectbackground=colors["selectbackground"],
                    selectforeground=colors["selectforeground"],
                    highlightthickness=1,
                    highlightbackground=colors["border"],
                    highlightcolor=colors["border"],
                    borderwidth=1,
                    relief="flat",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

        scroll = _ui_scrollbar(list_shell, orient="vertical", command=listbox.yview)
        scroll.grid(row=0, column=1, sticky="ns", pady=4)
        listbox.configure(yscrollcommand=scroll.set)
        self._profile_manager_listbox = listbox

        button_frame = (
            ctk_module.CTkFrame(container, fg_color="transparent")
            if ctk_module is not None
            else ttk.Frame(container)
        )
        button_frame.grid(row=2, column=2, sticky="n", padx=(12, 0))
        _ui_button(
            button_frame,
            text="New Profile",
            command=self._profile_new_blank,
        ).pack(fill="x", pady=2)
        _ui_button(
            button_frame,
            text="Save",
            command=self._profile_save_current,
        ).pack(fill="x", pady=2)
        _ui_button(
            button_frame,
            text="Save Current As...",
            command=self._profile_save_current_as,
        ).pack(fill="x", pady=2)
        _ui_button(
            button_frame,
            text="Load",
            command=self._profile_load_selected,
        ).pack(fill="x", pady=2)
        _ui_button(
            button_frame,
            text="Open Profile in New Program Copy",
            command=self._profile_open_selected_in_new_copy,
        ).pack(fill="x", pady=2)
        _ui_button(
            button_frame,
            text="Overwrite",
            command=self._profile_overwrite_selected,
        ).pack(fill="x", pady=2)
        _ui_button(
            button_frame,
            text="Rename",
            command=self._profile_rename_selected,
        ).pack(fill="x", pady=2)
        _ui_button(
            button_frame,
            text="Delete",
            command=self._profile_delete_selected,
        ).pack(fill="x", pady=2)
        if ctk_module is not None:
            ctk_module.CTkFrame(
                button_frame, height=1, corner_radius=0, fg_color=("#C7CDD3", "#4A5568")
            ).pack(fill="x", pady=(6, 6))
        else:
            ttk.Separator(button_frame, orient="horizontal").pack(fill="x", pady=(6, 6))
        _ui_button(
            button_frame,
            text="Export",
            command=self._profile_export_selected,
        ).pack(fill="x", pady=2)
        _ui_button(
            button_frame,
            text="Import",
            command=self._profile_import_profile,
        ).pack(fill="x", pady=2)

        _ui_checkbutton(
            container,
            text="Include dataset file path",
            variable=self._profile_include_path_var,
        ).grid(row=3, column=0, columnspan=3, sticky="w", pady=(8, 0))
        _ui_checkbutton(
            container,
            text="Keep plot settings for New Profile",
            variable=self._profile_keep_plot_settings_var,
        ).grid(row=4, column=0, columnspan=3, sticky="w", pady=(4, 0))

        try:
            self.update_idletasks()
            window.update_idletasks()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        measured_content_height = self._scale_length(560)
        try:
            # Measure rendered content so first-open height fits the full action column.
            measured_content_height = int(container.winfo_reqheight()) + self._scale_length(44)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

        min_list_px = self._scale_length(420)
        max_list_px = self._scale_length(980)
        measured_list_px = longest_profile_name_px + self._scale_length(56)
        # Clamp measured name width so long profiles improve visibility while
        # preserving screen-safe geometry on smaller displays.
        list_target_px = max(min_list_px, min(measured_list_px, max_list_px))
        button_col_reqwidth = self._scale_length(180)
        try:
            button_col_reqwidth = max(
                button_col_reqwidth, int(button_frame.winfo_reqwidth())
            )
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        min_dialog_width = self._scale_length(760)
        min_dialog_height = self._scale_length(520)
        preferred_dialog_width = (
            list_target_px + button_col_reqwidth + self._scale_length(72)
        )
        baseline_preferred_dialog_height = self._scale_length(560)
        preferred_dialog_height = max(
            baseline_preferred_dialog_height, measured_content_height
        )
        parent_width = int(getattr(self, "winfo_width", lambda: 0)() or 0)
        parent_height = int(getattr(self, "winfo_height", lambda: 0)() or 0)
        if parent_width <= 0:
            parent_width = int(window.winfo_screenwidth() * 0.9)
        if parent_height <= 0:
            parent_height = int(window.winfo_screenheight() * 0.9)
        max_dialog_width = max(min_dialog_width, int(parent_width * 0.95))
        max_dialog_height = max(min_dialog_height, int(parent_height * 0.92))
        dialog_width = max(
            min_dialog_width, min(preferred_dialog_width, max_dialog_width)
        )
        dialog_height = max(
            min_dialog_height, min(preferred_dialog_height, max_dialog_height)
        )
        try:
            root_x = int(self.winfo_rootx())
            root_y = int(self.winfo_rooty())
            parent_width_px = int(self.winfo_width() or dialog_width)
            parent_height_px = int(self.winfo_height() or dialog_height)
            pos_x = root_x + max((parent_width_px - dialog_width) // 2, 0)
            pos_y = root_y + max((parent_height_px - dialog_height) // 2, 0)
            window.geometry(f"{dialog_width}x{dialog_height}+{pos_x}+{pos_y}")
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            window.geometry(f"{dialog_width}x{dialog_height}")
        try:
            window.minsize(min_dialog_width, min_dialog_height)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

        self._refresh_current_profile_section()
        current_profile_name, _ = self._resolve_current_workspace_profile(
            normalize=True, persist=False
        )
        self._refresh_profile_listbox(select_name=current_profile_name)
        try:
            # Ensure geometry/list population is stable before enabling modal grab.
            window.update_idletasks()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            window.grab_set()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            window.lift()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            window.focus_force()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _profile_new_blank(self) -> None:
        """Create a new blank profile from startup-default workspace state.

        Purpose:
            Start a fresh analysis session and persist it as a profile snapshot.
        Why:
            Prevents stale state from leaking when switching to a new dataset,
            while allowing users to optionally keep tuned plot/layout settings.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Clears the workspace, optionally preserves/restores plot and layout
            settings, prompts the user, applies settings, and writes a profile
            document to disk.
        Exceptions:
            Best-effort guards prevent UI interruptions from blocking the workflow.
        """
        parent = getattr(self, "_profile_manager_window", None) or self
        if not messagebox.askyesno(
            "New Profile",
            "Creating a new profile clears the current workspace. Continue?",
            parent=parent,
        ):
            return
        keep_plot_settings = True
        keep_plot_settings_var = getattr(self, "_profile_keep_plot_settings_var", None)
        if keep_plot_settings_var is not None:
            try:
                keep_plot_settings = bool(keep_plot_settings_var.get())
            except Exception:
                keep_plot_settings = True
        preserved_plot_settings: Optional[Dict[str, Any]] = None
        preserved_layout_profiles: Optional[Dict[str, Any]] = None
        if keep_plot_settings:
            preserved_plot_settings = self._collect_profile_plot_settings()
            preserved_layout_profiles = copy.deepcopy(settings.get("layout_profiles", {}))
        self._autosave_last_workspace()
        self._reset_workspace_to_startup_defaults()
        # Restore preserved plot state only after baseline reset completes so
        # plot elements and annotation state still reset as intended.
        if keep_plot_settings:
            if isinstance(preserved_plot_settings, dict):
                self._apply_profile_plot_settings(preserved_plot_settings)
            if isinstance(preserved_layout_profiles, dict):
                self._apply_profile_layout_profiles(preserved_layout_profiles)
        config = self._prompt_new_profile_configuration(parent)
        if not config:
            return
        profile_name = config.get("profile_name")
        if not profile_name:
            return
        path = self._profile_path(profile_name)
        if path is None:
            return
        created_at = config.get("created_at")
        doc = self._build_profile_document(
            include_dataset_path=False,
            created_at=created_at,
        )
        payload = doc.get("payload")
        if isinstance(payload, dict):
            # Flag new profiles as dataset-optional to avoid relink prompts.
            payload["dataset_required"] = False
        if self._write_profile_document(path, doc):
            self._set_current_workspace_profile(profile_name, persist=True)
            self._refresh_profile_listbox(select_name=profile_name)

    def _prompt_new_profile_configuration(
        self, parent: tk.Misc
    ) -> dict[str, Any] | None:
        """Prompt for new profile configuration values.

        Purpose:
            Collect job-specific parameters before saving a blank profile.
        Why:
            New profiles should capture gas model and starting material inputs
            alongside the new suptitle metadata.
        Args:
            parent: Parent window used to scope the modal dialog.
        Returns:
            A configuration dict on success, or None if canceled.
        Side Effects:
            Creates a modal dialog, validates inputs, and applies values to state.
        Exceptions:
            Best-effort guards keep dialog flow resilient to UI errors.
        """
        window = tk.Toplevel(parent)
        window.title("New Profile Configuration")
        window.transient(parent)
        window.resizable(False, False)
        window.grab_set()

        result: dict[str, Any] = {"config": None}

        def _format_float(value: Any) -> str:
            """Format a numeric value for entry defaults.

            Purpose:
                Normalize numeric defaults for dialog entry widgets.
            Why:
                Keeps initial field values readable and consistent.
            Args:
                value: Value to format as a string.
            Returns:
                String representation or an empty string on failure.
            Side Effects:
                None.
            Exceptions:
                Returns an empty string when conversion fails.
            """
            try:
                return f"{float(value)}"
            except Exception:
                return ""

        def _parse_float(value: str, label: str) -> Optional[float]:
            """Parse a float input with user-facing validation.

            Purpose:
                Validate numeric fields before applying them to the workspace.
            Why:
                Ensures dialog inputs are numeric before running apply routines.
            Args:
                value: Raw string from the entry widget.
                label: Human-readable label for error messaging.
            Returns:
                Parsed float, or None when validation fails.
            Side Effects:
                Shows a message box on invalid input.
            Exceptions:
                None; invalid values return None.
            """
            try:
                parsed = float(value)
            except Exception:
                messagebox.showerror(
                    "Invalid Input",
                    f"Please enter a valid {label}.",
                    parent=window,
                )
                return None
            if not math.isfinite(parsed):
                messagebox.showerror(
                    "Invalid Input",
                    f"{label} must be a finite number.",
                    parent=window,
                )
                return None
            return parsed

        profile_name_var = tk.StringVar(value="")
        suptitle_var = tk.StringVar(value=str(self.suptitle_text.get() or ""))
        current_identifiers = self._collect_profile_identifiers()
        project_number_var = tk.StringVar(
            value=str(current_identifiers.get("project_number") or "")
        )
        batch_number_var = tk.StringVar(
            value=str(current_identifiers.get("batch_number") or "")
        )
        item_number_var = tk.StringVar(
            value=str(current_identifiers.get("item_number") or "")
        )

        gas_preset_var = tk.StringVar(value=str(self.v_gas.get() or ""))
        volume_var = tk.StringVar(value=_format_float(self.v_volume.get()))
        vdw_a_var = tk.StringVar(value=_format_float(self.v_a.get()))
        vdw_b_var = tk.StringVar(value=_format_float(self.v_b.get()))
        gas_molar_mass_var = tk.StringVar(
            value=_format_float(self.v_gas_molar_mass.get())
        )

        product_preset_var = tk.StringVar(value=str(self.v_product_preset.get() or ""))
        product_molar_mass_var = tk.StringVar(
            value=_format_float(self.v_product_molar_mass.get())
        )
        starting_mass_var = tk.StringVar(
            value=_format_float(self.v_starting_mass.get())
        )
        stoich_var = tk.StringVar(value=_format_float(self.v_starting_stoich.get()))

        ctk_module = ctk
        if ctk_module is not None:
            container: Any = ctk_module.CTkFrame(window, corner_radius=10)
            container.grid(row=0, column=0, sticky="nsew", padx=12, pady=12)
        else:
            container = ttk.Frame(window, padding=12)
            container.grid(row=0, column=0, sticky="nsew")
        window.grid_rowconfigure(0, weight=1)
        window.grid_columnconfigure(0, weight=1)

        def _make_section(parent_widget: Any, title: str) -> Tuple[Any, Any]:
            """Create one profile-configuration section with CTk/ttk compatibility.

            Purpose:
                Build titled section containers for the profile configuration form.
            Why:
                The dialog should mirror CTk styling where available while keeping
                a robust ttk fallback path.
            Args:
                parent_widget: Container widget that owns the section.
                title: Section title text.
            Returns:
                Tuple of `(section_widget, content_frame)` used for layout and child
                control placement.
            Side Effects:
                Creates widgets and applies basic column-weight configuration.
            Exceptions:
                None; callers receive fallback widgets when CTk is unavailable.
            """
            if ctk_module is not None:
                section_widget = ctk_module.CTkFrame(parent_widget, corner_radius=8)
                section_widget.grid_columnconfigure(0, weight=1)
                ctk_module.CTkLabel(
                    section_widget,
                    text=title,
                    anchor="w",
                    font=(getattr(self, "_ui_font_family", "Verdana"), 13, "bold"),
                ).grid(row=0, column=0, sticky="ew", padx=10, pady=(8, 4))
                content_frame: Any = ctk_module.CTkFrame(
                    section_widget, fg_color="transparent"
                )
                content_frame.grid(row=1, column=0, sticky="ew", padx=8, pady=(0, 8))
                content_frame.grid_columnconfigure(1, weight=1)
                return section_widget, content_frame
            section_widget = ttk.Labelframe(parent_widget, text=title)
            section_widget.grid_columnconfigure(1, weight=1)
            return section_widget, section_widget

        def _label(parent_widget: Any, text: str) -> Any:
            """Create one section label with CTk/ttk compatibility.

            Purpose:
                Standardize label construction for the profile configuration form.
            Why:
                The dialog uses mixed toolkit support and should keep one label
                call-site contract during CTk migration.
            Args:
                parent_widget: Widget that owns the label.
                text: Label text content.
            Returns:
                Constructed label widget instance.
            Side Effects:
                Creates one label widget in the dialog layout tree.
            Exceptions:
                None; ttk fallback is used when CTk is unavailable.
            """
            if ctk_module is not None:
                return ctk_module.CTkLabel(parent_widget, text=text, anchor="w")
            return ttk.Label(parent_widget, text=text)

        info_frame, info_body = _make_section(container, "Profile Info")
        info_frame.grid(row=0, column=0, sticky="ew", pady=(0, 8))

        _label(info_body, "Profile name").grid(
            row=0, column=0, sticky="w", padx=6, pady=4
        )
        name_entry = _ui_entry(info_body, textvariable=profile_name_var)
        name_entry.grid(row=0, column=1, sticky="ew", padx=6, pady=4)
        _label(info_body, "Suptitle (Job Information)").grid(
            row=1, column=0, sticky="w", padx=6, pady=4
        )
        _ui_entry(info_body, textvariable=suptitle_var).grid(
            row=1, column=1, sticky="ew", padx=6, pady=4
        )
        _label(info_body, "Project #").grid(row=2, column=0, sticky="w", padx=6, pady=4)
        _ui_entry(info_body, textvariable=project_number_var).grid(
            row=2, column=1, sticky="ew", padx=6, pady=4
        )
        _label(info_body, "Batch #").grid(row=3, column=0, sticky="w", padx=6, pady=4)
        _ui_entry(info_body, textvariable=batch_number_var).grid(
            row=3, column=1, sticky="ew", padx=6, pady=4
        )
        _label(info_body, "Item #").grid(row=4, column=0, sticky="w", padx=6, pady=4)
        _ui_entry(info_body, textvariable=item_number_var).grid(
            row=4, column=1, sticky="ew", padx=6, pady=4
        )

        vdw_frame, vdw_body = _make_section(container, "Gas Model (Van der Waals)")
        vdw_frame.grid(row=1, column=0, sticky="ew", pady=(0, 8))

        _label(vdw_body, "Preset").grid(row=0, column=0, sticky="w", padx=6, pady=4)
        gas_combo = _ui_combobox(
            vdw_body,
            textvariable=gas_preset_var,
            state="readonly",
            values=list(GAS_PRESETS.keys()),
        )
        gas_combo.grid(row=0, column=1, sticky="ew", padx=6, pady=4)

        _label(vdw_body, "Vessel Volume (L)").grid(
            row=1, column=0, sticky="w", padx=6, pady=4
        )
        _ui_entry(vdw_body, textvariable=volume_var).grid(
            row=1, column=1, sticky="ew", padx=6, pady=4
        )
        _label(vdw_body, "VDW a (L^2*atm/mol^2)").grid(
            row=2, column=0, sticky="w", padx=6, pady=4
        )
        _ui_entry(vdw_body, textvariable=vdw_a_var).grid(
            row=2, column=1, sticky="ew", padx=6, pady=4
        )
        _label(vdw_body, "VDW b (L/mol)").grid(
            row=3, column=0, sticky="w", padx=6, pady=4
        )
        _ui_entry(vdw_body, textvariable=vdw_b_var).grid(
            row=3, column=1, sticky="ew", padx=6, pady=4
        )
        _label(vdw_body, "Gaseous Reagent Molar Mass (g/mol)").grid(
            row=4, column=0, sticky="w", padx=6, pady=4
        )
        _ui_entry(vdw_body, textvariable=gas_molar_mass_var).grid(
            row=4, column=1, sticky="ew", padx=6, pady=4
        )

        reaction_catalog = _normalize_reaction_catalog(
            settings.get(REACTION_CATALOG_SETTINGS_KEY)
        )
        reaction_choices = list(reaction_catalog.keys())

        reagent_frame, reagent_body = _make_section(container, "Final Product Settings")
        reagent_frame.grid(row=2, column=0, sticky="ew", pady=(0, 8))

        _label(reagent_body, "Reaction").grid(row=0, column=0, sticky="w", padx=6, pady=4)
        product_combo = _ui_combobox(
            reagent_body,
            textvariable=product_preset_var,
            state="readonly",
            values=reaction_choices,
        )
        product_combo.grid(row=0, column=1, sticky="ew", padx=6, pady=4)

        _label(reagent_body, "Starting Material Molar Mass (g/mol)").grid(
            row=1, column=0, sticky="w", padx=6, pady=4
        )
        _ui_entry(reagent_body, textvariable=product_molar_mass_var).grid(
            row=1, column=1, sticky="ew", padx=6, pady=4
        )
        _label(reagent_body, "Starting Material Mass (g)").grid(
            row=2, column=0, sticky="w", padx=6, pady=4
        )
        _ui_entry(reagent_body, textvariable=starting_mass_var).grid(
            row=2, column=1, sticky="ew", padx=6, pady=4
        )
        _label(reagent_body, "Stoichiometry (mol gas per mol starting)").grid(
            row=3, column=0, sticky="w", padx=6, pady=4
        )
        _ui_entry(reagent_body, textvariable=stoich_var).grid(
            row=3, column=1, sticky="ew", padx=6, pady=4
        )

        buttons = (
            ctk_module.CTkFrame(container, fg_color="transparent")
            if ctk_module is not None
            else ttk.Frame(container)
        )
        buttons.grid(row=3, column=0, sticky="e", pady=(4, 0))

        def _close_window() -> None:
            """Close the configuration dialog safely.

            Purpose:
                Release modal grabs and destroy the dialog window.
            Why:
                Ensures the UI unblocks cleanly after dialog completion.
            Args:
                None.
            Returns:
                None.
            Side Effects:
                Releases grabs and destroys the dialog window.
            Exceptions:
                Best-effort guards suppress Tk errors during cleanup.
            """
            try:
                window.grab_release()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                window.destroy()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

        def _cancel() -> None:
            """Cancel the dialog and return no configuration.

            Purpose:
                Exit the dialog without applying any changes.
            Why:
                Allows users to abandon profile creation safely.
            Args:
                None.
            Returns:
                None.
            Side Effects:
                Clears the result payload and closes the dialog.
            Exceptions:
                None.
            """
            result["config"] = None
            _close_window()

        def _sync_gas_preset(*_) -> None:
            """Sync VDW fields when the gas preset selection changes.

            Purpose:
                Auto-populate VDW inputs based on the selected gas preset.
            Why:
                Reduces manual entry and keeps preset defaults consistent.
            Args:
                *_: Tk callback args (unused).
            Returns:
                None.
            Side Effects:
                Updates VDW field variables.
            Exceptions:
                Best-effort guards avoid interrupting the dialog flow.
            """
            choice = gas_preset_var.get()
            preset = GAS_PRESETS.get(choice)
            if preset:
                vdw_a_var.set(_format_float(preset.get("a")))
                vdw_b_var.set(_format_float(preset.get("b")))
            override = self._gas_preset_overrides.get(choice) or {}
            molar = override.get("molar_mass")
            if molar is None and preset is not None:
                molar = preset.get("molar_mass")
            try:
                molar_val = float(molar)
            except (TypeError, ValueError):
                molar_val = None
            if molar_val is not None and math.isfinite(molar_val) and molar_val > 0.0:
                gas_molar_mass_var.set(_format_float(molar_val))

        def _sync_product_preset(*_) -> None:
            """Sync starting material fields when the preset changes.

            Purpose:
                Auto-populate starting material molar mass from presets.
            Why:
                Keeps preset values consistent while allowing overrides.
            Args:
                *_: Tk callback args (unused).
            Returns:
                None.
            Side Effects:
                Updates the molar mass field variable.
            Exceptions:
                Best-effort guards avoid interrupting the dialog flow.
            """
            preset_key = product_preset_var.get()
            preset = _normalize_reaction_catalog_entry(
                reaction_catalog.get(preset_key), reaction_id=preset_key
            )
            product_molar_mass_var.set(
                _format_float(preset.get("starting_material_mw_g_mol"))
            )

        def _confirm() -> None:
            """Validate inputs and apply the configuration to the workspace.

            Purpose:
                Ensure dialog inputs are valid before saving a new profile.
            Why:
                Prevents invalid or incomplete profiles from being persisted.
            Args:
                None.
            Returns:
                None.
            Side Effects:
                Applies validated configuration to live state and closes the dialog.
            Exceptions:
                None.
            """
            raw_name = (profile_name_var.get() or "").strip()
            safe_name = self._sanitize_profile_name(raw_name)
            if not safe_name:
                messagebox.showerror(
                    "New Profile",
                    "Profile name cannot be empty.",
                    parent=window,
                )
                return
            profile_path = self._profile_path(safe_name)
            if profile_path is None:
                return
            created_at = None
            if profile_path.exists():
                if not messagebox.askyesno(
                    "Overwrite Profile?",
                    f"A profile named '{safe_name}' already exists. Overwrite it?",
                    parent=window,
                ):
                    return
                existing = self._read_profile_document(profile_path)
                if isinstance(existing, dict):
                    created_at = existing.get("created_at")

            vessel_volume = _parse_float(volume_var.get(), "vessel volume (L)")
            if vessel_volume is None:
                return
            vdw_a = _parse_float(vdw_a_var.get(), "VDW a")
            if vdw_a is None:
                return
            vdw_b = _parse_float(vdw_b_var.get(), "VDW b")
            if vdw_b is None:
                return
            gas_molar_mass = _parse_float(
                gas_molar_mass_var.get(), "gaseous reagent molar mass (g/mol)"
            )
            if gas_molar_mass is None:
                return
            product_molar_mass = _parse_float(
                product_molar_mass_var.get(),
                "starting material molar mass (g/mol)",
            )
            if product_molar_mass is None:
                return
            starting_mass = _parse_float(
                starting_mass_var.get(), "starting material mass (g)"
            )
            if starting_mass is None:
                return
            stoich_ratio = _parse_float(
                stoich_var.get(),
                "stoichiometry (mol gas per mol starting)",
            )
            if stoich_ratio is None:
                return
            project_number = str(project_number_var.get() or "").strip()
            batch_number = str(batch_number_var.get() or "").strip()
            item_number = str(item_number_var.get() or "").strip()
            if not project_number or not batch_number or not item_number:
                messagebox.showerror(
                    "New Profile",
                    "Project #, Batch #, and Item # are required.",
                    parent=window,
                )
                return

            gas_preset = gas_preset_var.get()
            if gas_preset not in GAS_PRESETS:
                gas_preset = next(iter(GAS_PRESETS))
            product_preset = product_preset_var.get()
            if product_preset not in reaction_catalog:
                product_preset = DEFAULT_SELECTED_REACTION_ID

            config = {
                "profile_name": safe_name,
                "created_at": created_at,
                "suptitle_text": (suptitle_var.get() or "").strip(),
                "gas_preset": gas_preset,
                "vessel_volume": vessel_volume,
                "vdw_a": vdw_a,
                "vdw_b": vdw_b,
                "gas_molar_mass": gas_molar_mass,
                "product_preset": product_preset,
                "product_molar_mass": product_molar_mass,
                "starting_mass": starting_mass,
                "stoich_ratio": stoich_ratio,
                "profile_identifiers": {
                    "project_number": project_number,
                    "batch_number": batch_number,
                    "item_number": item_number,
                },
            }
            if not self._apply_new_profile_configuration(config):
                return
            result["config"] = config
            _close_window()

        gas_preset_var.trace_add("write", _sync_gas_preset)
        product_preset_var.trace_add("write", _sync_product_preset)
        _sync_gas_preset()
        _sync_product_preset()

        _ui_button(buttons, text="Cancel", command=_cancel).pack(side="right")
        _ui_button(buttons, text="Create Profile", command=_confirm).pack(
            side="right", padx=(0, 8)
        )

        window.bind("<Escape>", lambda _event: _cancel())
        window.bind("<Return>", lambda _event: _confirm())
        window.protocol("WM_DELETE_WINDOW", _cancel)
        try:
            name_entry.focus_set()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

        window.wait_window()
        return result.get("config")

    def _apply_new_profile_configuration(self, config: dict[str, Any]) -> bool:
        """Apply new profile configuration values to the live workspace.

        Purpose:
            Persist dialog inputs into Tk variables and settings using existing
            validation workflows.
        Why:
            Ensures New Profile values are validated consistently with the rest
            of the application.
        Args:
            config: Dictionary of validated configuration values.
        Returns:
            True if the configuration was applied successfully, otherwise False.
        Side Effects:
            Updates Tk variables, settings, and triggers apply routines.
        Exceptions:
            Best-effort guards prevent validation errors from crashing the UI.
        """
        def _float_matches(expected: float, actual: Any) -> bool:
            """Compare floats with a small tolerance.

            Purpose:
                Validate that applied settings match dialog inputs.
            Why:
                Guards against invalid inputs that failed validation.
            Args:
                expected: Expected float value.
                actual: Actual value read from settings.
            Returns:
                True when values are within tolerance.
            Side Effects:
                None.
            Exceptions:
                Returns False when values cannot be coerced safely.
            """
            try:
                actual_val = float(actual)
            except Exception:
                return False
            if not math.isfinite(actual_val):
                return False
            return abs(float(expected) - actual_val) <= 1e-6

        suptitle_value = str(config.get("suptitle_text") or "")
        self.suptitle_text.set(suptitle_value)
        settings["suptitle_text"] = suptitle_value
        self._apply_profile_identifiers(config.get("profile_identifiers"))

        gas_preset = config.get("gas_preset") or self.v_gas.get()
        if gas_preset not in GAS_PRESETS:
            gas_preset = next(iter(GAS_PRESETS))
        self.v_gas.set(gas_preset)
        self.v_volume.set(float(config.get("vessel_volume", 0.0)))
        self.v_a.set(float(config.get("vdw_a", 0.0)))
        self.v_b.set(float(config.get("vdw_b", 0.0)))
        self.v_gas_molar_mass.set(float(config.get("gas_molar_mass", 0.0)))
        self.v_starting_mass.set(float(config.get("starting_mass", 0.0)))
        self._apply_vdw()

        product_preset = config.get("product_preset") or self.v_product_preset.get()
        if product_preset not in getattr(self, "_reaction_catalog", {}):
            product_preset = DEFAULT_SELECTED_REACTION_ID
        self._apply_reaction_entry_to_runtime(
            str(product_preset),
            preserve_starting_mass=False,
        )
        self.v_product_preset.set(product_preset)
        self.v_product_molar_mass.set(float(config.get("product_molar_mass", 0.0)))
        self.v_starting_mass.set(float(config.get("starting_mass", 0.0)))
        self.v_starting_stoich.set(float(config.get("stoich_ratio", 0.0)))
        self._apply_product_settings()

        if settings.get("vdw_gas") != gas_preset:
            messagebox.showerror(
                "New Profile",
                "Gas preset could not be applied. Check your inputs and try again.",
                parent=self,
            )
            return False
        if not _float_matches(config["vessel_volume"], settings.get("vessel_volume")):
            messagebox.showerror(
                "New Profile",
                "Vessel volume could not be applied. Check your inputs and try again.",
                parent=self,
            )
            return False
        if not _float_matches(config["vdw_a"], settings.get("vdw_a")):
            messagebox.showerror(
                "New Profile",
                "VDW a could not be applied. Check your inputs and try again.",
                parent=self,
            )
            return False
        if not _float_matches(config["vdw_b"], settings.get("vdw_b")):
            messagebox.showerror(
                "New Profile",
                "VDW b could not be applied. Check your inputs and try again.",
                parent=self,
            )
            return False
        if not _float_matches(
            config["gas_molar_mass"], settings.get("vdw_gas_molar_mass")
        ):
            messagebox.showerror(
                "New Profile",
                "Gas molar mass could not be applied. Check your inputs and try again.",
                parent=self,
            )
            return False
        if settings.get("starting_material_preset") != product_preset:
            messagebox.showerror(
                "New Profile",
                (
                    "Starting material preset could not be applied. "
                    "Check your inputs and try again."
                ),
                parent=self,
            )
            return False
        if not _float_matches(
            config["product_molar_mass"],
            settings.get("starting_material_mw_g_mol"),
        ):
            messagebox.showerror(
                "New Profile",
                "Starting material molar mass could not be applied.",
                parent=self,
            )
            return False
        if not _float_matches(
            config["starting_mass"], settings.get("starting_material_mass_g")
        ):
            messagebox.showerror(
                "New Profile",
                "Starting material mass could not be applied.",
                parent=self,
            )
            return False
        if not _float_matches(
            config["stoich_ratio"],
            settings.get("stoich_mol_gas_per_mol_starting"),
        ):
            messagebox.showerror(
                "New Profile",
                "Stoichiometry could not be applied. Check your inputs and try again.",
                parent=self,
            )
            return False

        try:
            self._update_auto_title_preview()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        return True

    def _build_profile_document(
        self,
        *,
        include_dataset_path: bool,
        created_at: Optional[str] = None,
    ) -> Dict[str, Any]:
        """Build profile document.
        Used to assemble profile document during UI or plot setup."""
        try:
            self._save_settings_dict(self._collect_plot_args())
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        payload = self._serialize_workspace_state(include_dataset_path)
        timestamp = self._profile_timestamp()
        return {
            "profile_version": 1,
            "created_at": created_at or timestamp,
            "updated_at": timestamp,
            "description": "",
            "payload": payload,
        }

    def _profile_save_current(self) -> None:
        """Save the active workspace to the tracked current profile.

        Purpose:
            Provide a one-click save path for the profile currently tied to the
            workspace.
        Why:
            Users need an explicit Save action that does not require selecting a
            list entry each time.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            May overwrite a profile JSON document, update current-profile
            tracking keys, and refresh profile manager UI state.
        Exceptions:
            Missing or invalid current-profile tracking falls back to Save As.
        """
        parent = getattr(self, "_profile_manager_window", None) or self
        current_name, current_path = self._resolve_current_workspace_profile(
            normalize=True, persist=True
        )
        if not current_name or current_path is None:
            messagebox.showinfo(
                "Profiles",
                "No current profile is set. Choose a profile name to save this workspace.",
                parent=parent,
            )
            self._profile_save_current_as()
            return
        if not current_path.exists():
            messagebox.showwarning(
                "Profiles",
                (
                    f"The current profile '{current_name}' could not be found.\n"
                    "Choose a profile name to save this workspace."
                ),
                parent=parent,
            )
            self._clear_current_workspace_profile(persist=True)
            self._refresh_profile_listbox()
            self._profile_save_current_as()
            return
        if not messagebox.askyesno(
            "Save Current Profile?",
            f"Overwrite current profile '{current_name}' with the current workspace?",
            parent=parent,
        ):
            return
        created_at = None
        existing = self._read_profile_document(current_path)
        if isinstance(existing, dict):
            created_at = existing.get("created_at")
        doc = self._build_profile_document(
            include_dataset_path=bool(self._profile_include_path_var.get()),
            created_at=created_at,
        )
        if self._write_profile_document(current_path, doc):
            self._set_current_workspace_profile(current_name, persist=True)
            self._refresh_profile_listbox(select_name=current_name)

    def _profile_save_current_silent(self) -> bool:
        """Save the tracked current profile without confirmation prompts.

        Purpose:
            Persist the active workspace immediately when launching a second app
            copy from Process Profiles.
        Why:
            Multi-window profile actions should preserve the current workspace
            before spawning another process without interruptive overwrite dialogs.
        Args:
            None.
        Returns:
            bool: True when a tracked current profile was saved successfully.
        Side Effects:
            Overwrites the currently tracked profile JSON document.
        Exceptions:
            Returns False if no current profile is tracked or write fails.
        """
        current_name, current_path = self._resolve_current_workspace_profile(
            normalize=True, persist=True
        )
        if not current_name or current_path is None or not current_path.exists():
            return False
        created_at = None
        existing = self._read_profile_document(current_path)
        if isinstance(existing, dict):
            created_at = existing.get("created_at")
        include_dataset = False
        include_var = getattr(self, "_profile_include_path_var", None)
        if include_var is not None:
            try:
                include_dataset = bool(include_var.get())
            except Exception:
                include_dataset = False
        doc = self._build_profile_document(
            include_dataset_path=include_dataset,
            created_at=created_at,
        )
        if not self._write_profile_document(current_path, doc):
            return False
        self._set_current_workspace_profile(current_name, persist=True)
        self._refresh_profile_listbox(select_name=current_name)
        return True

    def _profile_save_current_as(self) -> None:
        """Save the active workspace to a named profile.

        Purpose:
            Create a new profile or overwrite a named profile from current state.
        Why:
            Save As is the fallback when no current profile is set and allows
            explicit profile naming.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Prompts for a profile name, writes profile JSON, updates
            current-profile tracking, and refreshes profile manager UI.
        Exceptions:
            Invalid names and filesystem failures abort without partial writes.
        """
        parent = getattr(self, "_profile_manager_window", None) or self
        name = simpledialog.askstring("Save Profile", "Profile name:", parent=parent)
        if not name:
            return
        safe_name = self._sanitize_profile_name(name)
        if not safe_name:
            messagebox.showerror("Save Profile", "Profile name cannot be empty.")
            return
        path = self._profile_path(safe_name)
        if path is None:
            return
        created_at = None
        if path.exists():
            if not messagebox.askyesno(
                "Overwrite Profile?",
                f"A profile named '{safe_name}' already exists. Overwrite it?",
            ):
                return
            existing = self._read_profile_document(path)
            if isinstance(existing, dict):
                created_at = existing.get("created_at")
        doc = self._build_profile_document(
            include_dataset_path=bool(self._profile_include_path_var.get()),
            created_at=created_at,
        )
        if self._write_profile_document(path, doc):
            self._set_current_workspace_profile(safe_name, persist=True)
            self._refresh_profile_listbox(select_name=safe_name)

    def _profile_overwrite_selected(self) -> None:
        """Overwrite the selected profile with current workspace state.

        Purpose:
            Save current workspace data into the profile selected in the manager.
        Why:
            Users need a direct overwrite flow when targeting a specific profile
            from the list.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Prompts for overwrite confirmation, writes profile JSON, updates
            current-profile tracking, and refreshes manager UI.
        Exceptions:
            Invalid selection or write failures abort safely.
        """
        name = self._selected_profile_name()
        if not name:
            messagebox.showinfo("Profiles", "Select a profile to overwrite.")
            return
        if not messagebox.askyesno(
            "Overwrite Profile?",
            f"Overwrite '{name}' with the current workspace?",
        ):
            return
        path = self._profile_path(name)
        if path is None:
            return
        created_at = None
        if path.exists():
            existing = self._read_profile_document(path)
            if isinstance(existing, dict):
                created_at = existing.get("created_at")
        doc = self._build_profile_document(
            include_dataset_path=bool(self._profile_include_path_var.get()),
            created_at=created_at,
        )
        if self._write_profile_document(path, doc):
            self._set_current_workspace_profile(name, persist=True)
            self._refresh_profile_listbox(select_name=name)

    def _profile_rename_selected(self) -> None:
        """Rename the selected profile and sync current-profile tracking.

        Purpose:
            Change the stored profile filename for the selected entry.
        Why:
            Renaming should preserve current-profile identity when the renamed
            profile is the active workspace profile.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Renames profile files on disk, may update current-profile settings,
            and refreshes manager list selection.
        Exceptions:
            Existing-target and filesystem errors are reported and abort rename.
        """
        name = self._selected_profile_name()
        if not name:
            messagebox.showinfo("Profiles", "Select a profile to rename.")
            return
        current_name, _ = self._resolve_current_workspace_profile(
            normalize=True, persist=False
        )
        parent = getattr(self, "_profile_manager_window", None) or self
        new_name = simpledialog.askstring(
            "Rename Profile", "New profile name:", initialvalue=name, parent=parent
        )
        if not new_name:
            return
        safe_name = self._sanitize_profile_name(new_name)
        if not safe_name:
            messagebox.showerror("Rename Profile", "Profile name cannot be empty.")
            return
        if safe_name == name:
            return
        old_path = self._profile_path(name)
        new_path = self._profile_path(safe_name)
        if old_path is None or new_path is None:
            return
        if new_path.exists():
            messagebox.showerror(
                "Rename Profile", f"A profile named '{safe_name}' already exists."
            )
            return
        try:
            old_path.rename(new_path)
        except Exception as exc:
            messagebox.showerror("Rename Profile", f"Rename failed:\n{exc}")
            return
        if current_name == name:
            self._set_current_workspace_profile(safe_name, persist=True)
        self._refresh_profile_listbox(select_name=safe_name)

    def _profile_delete_selected(self) -> None:
        """Delete the selected profile and clear tracking when necessary.

        Purpose:
            Remove a profile document from the managed profiles directory.
        Why:
            Deleting the active profile must also clear current-profile state to
            prevent future Save actions from targeting a missing file.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Deletes a profile file, may clear current-profile settings, and
            refreshes the manager list.
        Exceptions:
            Filesystem delete failures are reported and leave state unchanged.
        """
        name = self._selected_profile_name()
        if not name:
            messagebox.showinfo("Profiles", "Select a profile to delete.")
            return
        current_name, _ = self._resolve_current_workspace_profile(
            normalize=True, persist=False
        )
        if not messagebox.askyesno(
            "Delete Profile?", f"Delete '{name}' permanently?"
        ):
            return
        path = self._profile_path(name)
        if path is None:
            return
        try:
            path.unlink()
        except Exception as exc:
            messagebox.showerror("Profiles", f"Could not delete profile:\n{exc}")
            return
        if current_name == name:
            self._clear_current_workspace_profile(persist=True)
        self._refresh_profile_listbox()

    def _profile_export_selected(self) -> None:
        """Export selected.
        Used by profile workflows to export selected."""
        name = self._selected_profile_name()
        if not name:
            messagebox.showinfo("Profiles", "Select a profile to export.")
            return
        source_path = self._profile_path(name)
        if source_path is None or not source_path.exists():
            messagebox.showerror("Profiles", "Selected profile could not be found.")
            return
        target_path = filedialog.asksaveasfilename(
            title="Export Profile",
            defaultextension=".json",
            filetypes=[("Profile JSON", "*.json"), ("All files", "*.*")],
            initialfile=f"{name}.json",
        )
        if not target_path:
            return
        try:
            shutil.copyfile(source_path, target_path)
        except Exception as exc:
            messagebox.showerror("Profiles", f"Export failed:\n{exc}")
            return
        messagebox.showinfo("Profiles", f"Profile exported to:\n{target_path}")

    def _profile_import_profile(self) -> None:
        """Import profile.
        Used by profile workflows to import profile."""
        source_path = filedialog.askopenfilename(
            title="Import Profile",
            filetypes=[("Profile JSON", "*.json"), ("All files", "*.*")],
        )
        if not source_path:
            return
        try:
            with open(source_path, "r", encoding="utf-8") as handle:
                data = json.load(handle)
        except Exception as exc:
            messagebox.showerror("Profiles", f"Could not read profile:\n{exc}")
            return
        if not isinstance(data, dict):
            messagebox.showerror("Profiles", "Profile data is invalid.")
            return
        if "payload" not in data:
            data = {
                "profile_version": 1,
                "created_at": self._profile_timestamp(),
                "updated_at": self._profile_timestamp(),
                "description": "",
                "payload": data,
            }
        name_guess = self._sanitize_profile_name(Path(source_path).stem)
        if not name_guess:
            name_guess = "Imported Profile"
        parent = getattr(self, "_profile_manager_window", None) or self
        name = simpledialog.askstring(
            "Import Profile",
            "Profile name:",
            initialvalue=name_guess,
            parent=parent,
        )
        if not name:
            return
        safe_name = self._sanitize_profile_name(name)
        if not safe_name:
            messagebox.showerror("Import Profile", "Profile name cannot be empty.")
            return
        path = self._profile_path(safe_name)
        if path is None:
            return
        if path.exists():
            if not messagebox.askyesno(
                "Overwrite Profile?",
                f"A profile named '{safe_name}' already exists. Overwrite it?",
            ):
                return
        data.setdefault("profile_version", 1)
        data.setdefault("created_at", self._profile_timestamp())
        data["updated_at"] = self._profile_timestamp()
        if self._write_profile_document(path, data):
            self._refresh_profile_listbox(select_name=safe_name)

    def _start_profile_load_splash(self, profile_name: str) -> None:
        """Start the shared splash lifecycle for Process Profiles load actions.

        Purpose:
            Open the operation splash and mark profile-load lifecycle as active.
        Why:
            Profile restore can include deferred column-apply work and needs one
            splash lifecycle that spans until restore completion.
        Args:
            profile_name: Selected profile name being restored.
        Returns:
            None.
        Side Effects:
            Updates profile-load splash state and shows shared operation splash UI.
        Exceptions:
            Splash rendering failures are handled by best-effort guards.
        """
        safe_name = str(profile_name or "").strip()
        self._profile_load_splash_active = True
        self._profile_load_splash_profile_name = safe_name
        self._show_operation_splash("Load Profile", context="profile_load")
        self._update_operation_splash(
            message=f"Loading profile '{safe_name}'...",
            progress=8.0,
            stage_key="load",
            detail="Preparing workspace restore pipeline.",
            reset=True,
        )

    def _finish_profile_load_splash(
        self,
        *,
        succeeded: bool,
        detail: str,
    ) -> None:
        """Complete the profile-load splash lifecycle and tear down shared splash.

        Purpose:
            Finalize profile-load splash state on success or failure.
        Why:
            Profile restore paths must always release splash resources cleanly.
        Args:
            succeeded: True when profile restore completed successfully.
            detail: Final detail text to display before splash teardown.
        Returns:
            None.
        Side Effects:
            Updates splash terminal stage and hides operation splash.
        Exceptions:
            Best-effort guards suppress teardown failures.
        """
        if not bool(getattr(self, "_profile_load_splash_active", False)):
            return
        self._profile_load_splash_active = False
        self._profile_load_splash_profile_name = ""
        final_stage = "ready" if succeeded else "failed"
        final_message = "Profile load complete." if succeeded else "Profile load failed."
        self._update_operation_splash(
            message=final_message,
            progress=100.0 if succeeded else 100.0,
            stage_key=final_stage,
            detail=str(detail or "").strip()
            or ("Workspace restored successfully." if succeeded else "Restore aborted."),
        )
        self._hide_operation_splash(context="profile_load")

    def _maybe_finish_profile_load_splash(
        self,
        *,
        succeeded: bool,
        detail: str,
        force: bool = False,
    ) -> bool:
        """Finish active profile-load splash when restore lifecycle has settled.

        Purpose:
            Gate splash teardown until profile restore and deferred apply work end.
        Why:
            Process Profiles load is now asynchronous in parts and should keep
            splash visible until `_profile_restore_pending` + apply flow complete.
        Args:
            succeeded: True for success completion path, False for failure.
            detail: Terminal detail text used by splash final stage.
            force: When True, bypasses pending/apply guards.
        Returns:
            True when splash was finalized, otherwise False.
        Side Effects:
            May close shared operation splash and clear profile-load splash flags.
        Exceptions:
            None.
        """
        if not bool(getattr(self, "_profile_load_splash_active", False)):
            return False
        if not force:
            if bool(getattr(self, "_is_applying_columns", False)):
                return False
            if bool(getattr(self, "_profile_restore_pending", None)):
                return False
        self._finish_profile_load_splash(succeeded=succeeded, detail=detail)
        return True

    def _load_profile_by_name(
        self,
        profile_name: str,
        *,
        prompt_replace: bool,
        show_errors: bool = True,
        use_splash: bool = True,
    ) -> bool:
        """Load one profile into the current workspace.

        Purpose:
            Centralize profile restore logic for interactive load, CLI load, and
            new-window profile launch workflows.
        Why:
            Reusing one restore path keeps profile identity, splash lifecycle, and
            error handling consistent across entry points.
        Args:
            profile_name: Managed profile name to load.
            prompt_replace: Whether to show the "replace current workspace" prompt.
            show_errors: Whether user-facing message boxes should be shown on errors.
            use_splash: Whether to show the profile-load splash lifecycle.
        Returns:
            bool: True when restore succeeded and current-profile tracking updated.
        Side Effects:
            May autosave current workspace, restore profile payload state, update
            current profile tracking, and refresh Process Profiles selection.
        Exceptions:
            Restore exceptions are handled locally and surfaced via dialogs when
            requested.
        """
        safe_name = self._sanitize_profile_name(profile_name)
        if not safe_name:
            if show_errors:
                try:
                    messagebox.showerror("Profiles", "Profile name is invalid.")
                except Exception:
                    pass
            return False
        path = self._profile_path(safe_name)
        if path is None or not path.exists():
            if show_errors:
                try:
                    messagebox.showerror(
                        "Profiles",
                        f"Profile '{safe_name}' could not be found.",
                    )
                except Exception:
                    pass
            return False
        if prompt_replace and not messagebox.askyesno(
            "Load Profile",
            "Loading a profile replaces the current workspace. Continue?",
        ):
            return False
        profile_doc: Optional[Dict[str, Any]] = None
        if show_errors:
            profile_doc = self._read_profile_document(path)
        else:
            profile_doc, _read_error = self._read_profile_document_silent(path)
        if not profile_doc:
            return False
        self._autosave_last_workspace()
        if use_splash:
            self._start_profile_load_splash(safe_name)
        restored = False
        prior_analysis_profile_target = getattr(
            self, "_analysis_profile_restore_target_name", None
        )
        self._analysis_profile_restore_target_name = safe_name
        try:
            restored = bool(self._restore_workspace_from_profile(profile_doc))
        except Exception as exc:
            if use_splash:
                self._finish_profile_load_splash(
                    succeeded=False,
                    detail=f"Unexpected restore error: {exc}",
                )
            if show_errors:
                try:
                    messagebox.showerror(
                        "Load Profile",
                        f"Profile restore failed unexpectedly.\n{exc}",
                    )
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
            return False
        finally:
            self._analysis_profile_restore_target_name = prior_analysis_profile_target
        if restored:
            self._set_current_workspace_profile(safe_name, persist=True)
            self._refresh_profile_listbox(select_name=safe_name)
            if use_splash:
                self._maybe_finish_profile_load_splash(
                    succeeded=True,
                    detail=f"Profile '{safe_name}' loaded.",
                )
            return True
        if use_splash:
            self._finish_profile_load_splash(
                succeeded=False,
                detail=f"Restore aborted for profile '{safe_name}'.",
            )
        return False

    def _profile_load_selected(self) -> None:
        """Load the selected profile into the active workspace.

        Purpose:
            Restore workspace state from the selected profile payload.
        Why:
            Loading a profile should establish that profile as the current Save
            target only after restore succeeds.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Prompts for confirmation, autosaves current workspace backup, restores
            profile state, and updates current-profile tracking on success.
        Exceptions:
            Invalid profile files or restore failures abort without changing
            current-profile identity.
        """
        name = self._selected_profile_name()
        if not name:
            messagebox.showinfo("Profiles", "Select a profile to load.")
            return
        self._load_profile_by_name(
            name,
            prompt_replace=True,
            show_errors=True,
            use_splash=True,
        )

    def _profile_open_selected_in_new_copy(self) -> None:
        """Launch a second GL-260 process and load the selected profile.

        Purpose:
            Open the selected Process Profile in a new program copy while keeping
            the current workspace open in the original window.
        Why:
            Operators need side-by-side profile review without replacing the
            active workspace.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            May save the current profile state, may prompt for Save As when no
            current profile exists, and launches a child Python process.
        Exceptions:
            Launch/save errors are reported and abort child-process startup.
        """
        name = self._selected_profile_name()
        parent = getattr(self, "_profile_manager_window", None) or self
        if not name:
            messagebox.showinfo("Profiles", "Select a profile to open.")
            return
        safe_name = self._sanitize_profile_name(name)
        path = self._profile_path(safe_name)
        if path is None or not path.exists():
            messagebox.showerror(
                "Profiles",
                f"Profile '{safe_name}' could not be found.",
                parent=parent,
            )
            return
        current_name, current_path = self._resolve_current_workspace_profile(
            normalize=True, persist=True
        )
        if current_name and current_path is not None and current_path.exists():
            if not self._profile_save_current_silent():
                messagebox.showerror(
                    "Open Profile",
                    "Could not auto-save the current profile before launch.",
                    parent=parent,
                )
                return
        else:
            messagebox.showinfo(
                "Open Profile",
                "Save the current workspace as a profile before opening a second copy.",
                parent=parent,
            )
            self._profile_save_current_as()
            current_name, current_path = self._resolve_current_workspace_profile(
                normalize=True, persist=True
            )
            if (
                not current_name
                or current_path is None
                or not current_path.exists()
            ):
                return
        executable = str(sys.executable or "").strip()
        script_path = Path(__file__).resolve()
        if not executable:
            messagebox.showerror(
                "Open Profile",
                "Unable to determine the Python executable for launching a new copy.",
                parent=parent,
            )
            return
        launch_args = [executable]
        if _supports_free_threading_build() and _current_gil_status() is False:
            launch_args.extend(["-X", "gil=0"])
        launch_args.extend([str(script_path), f"--open-profile={safe_name}"])
        try:
            subprocess.Popen(
                launch_args,
                cwd=str(script_path.parent),
                env=dict(os.environ),
            )
        except Exception as exc:
            messagebox.showerror(
                "Open Profile",
                f"Could not launch a new program copy:\n{exc}",
                parent=parent,
            )
            return

    def _load_profile_requested_via_cli(self, profile_name: str) -> None:
        """Restore a profile requested via `--open-profile` startup argument.

        Purpose:
            Support non-interactive startup loading for Profile Manager
            side-by-side launches.
        Why:
            The child process should open directly into the selected profile.
        Args:
            profile_name: Requested managed profile name.
        Returns:
            None.
        Side Effects:
            Attempts profile restore without replacement confirmation prompt.
        Exceptions:
            Failures are surfaced as a startup error message and leave app running.
        """
        safe_name = self._sanitize_profile_name(profile_name)
        if not safe_name:
            return
        restored = self._load_profile_by_name(
            safe_name,
            prompt_replace=False,
            show_errors=False,
            use_splash=True,
        )
        if restored:
            return
        try:
            messagebox.showerror(
                "Open Profile",
                (
                    f"Unable to auto-load profile '{safe_name}' from startup.\n"
                    "The application will continue with the current workspace."
                ),
                parent=self,
            )
        except Exception:
            pass

    def _collect_profile_plot_settings(self) -> Dict[str, Any]:
        """Collect profile plot settings.
        Used to gather profile plot settings into a structured payload."""
        keys = {
            "plot_generation_selection",
            "axis_auto_range",
            "axis_pad_pct",
            "min_time",
            "max_time",
            "min_y",
            "max_y",
            "twin_y_min",
            "twin_y_max",
            "deriv_y_min",
            "deriv_y_max",
            "auto_time_ticks",
            "auto_y_ticks",
            "auto_temp_ticks",
            "auto_deriv_ticks",
            "x_major_tick",
            "x_minor_tick",
            "y_major_tick",
            "y_minor_tick",
            "temp_major_tick",
            "temp_minor_tick",
            "deriv_major_tick",
            "deriv_minor_tick",
            "title_text",
            "suptitle_text",
            "enable_temp_axis",
            "enable_deriv_axis",
            "temperature_visualization",
            "temperature_source",
            "temperature_background",
            "temperature_line",
            "min_cycle_drop",
            "peak_prominence",
            "peak_distance",
            "peak_width",
            "peak_smoothing_window",
            "cycle_manual_snap_radius",
            "cycle_auto_refine_radius",
            "show_cycle_markers_on_core_plots",
            "show_cycle_legend_on_core_plots",
            "include_moles_in_core_plot_legend",
            "core_render_cycle_side_effects_mode",
            "scatter_enabled",
            "scatter_marker",
            "scatter_size",
            "scatter_color",
            "scatter_alpha",
            "scatter_edgecolor",
            "scatter_linewidth",
            "scatter_series",
            "cycle_trace",
            "core_legend_fontsize",
            "core_cycle_legend_fontsize",
            "core_plot_render_profiles",
            "combined_y_left_key",
            "combined_y_right_key",
            "combined_y_third_key",
            "combined_center_plot_legend",
        }
        snapshot: Dict[str, Any] = {}
        # Iterate over keys to apply the per-item logic.
        for key in keys:
            if key in settings:
                snapshot[key] = copy.deepcopy(settings.get(key))
        # Iterate over items from settings to apply the per-item logic.
        for key, value in settings.items():
            if key.startswith("combined_"):
                snapshot[key] = copy.deepcopy(value)
        return snapshot

    def _collect_profile_cycle_markers(self) -> Optional[Dict[str, Any]]:
        """Collect profile-local cycle marker overrides for persistence.

        Purpose:
            Capture manual cycle marker edits into profile payload storage.
        Why:
            Compare workflows now need profile-scoped marker correction
            persistence that survives app restarts and side-by-side reloads.
        Args:
            None.
        Returns:
            Normalized marker payload dict, or None when no manual payload exists.
        Side Effects:
            Saves the active trace marker state before collecting the profile
            payload.
        Exceptions:
            Invalid in-memory marker values are sanitized during normalization.
        """
        self._save_active_cycle_trace_marker_state()
        thresholds: Dict[str, Any] = {}
        # Collect threshold fields from live vars when available; fallback to settings.
        for key, var_name in (
            ("min_cycle_drop", "min_cycle_drop"),
            ("pk_prominence", "pk_prominence"),
            ("pk_distance", "pk_distance"),
            ("pk_width", "pk_width"),
            ("pk_smoothing_window", "pk_smoothing_window"),
            ("manual_snap_radius", "cycle_manual_snap_radius"),
            ("auto_refine_radius", "cycle_auto_refine_radius"),
        ):
            var_obj = getattr(self, var_name, None)
            if var_obj is not None:
                try:
                    thresholds[key] = var_obj.get()
                    continue
                except Exception:
                    pass
            settings_key = {
                "min_cycle_drop": "min_cycle_drop",
                "pk_prominence": "peak_prominence",
                "pk_distance": "peak_distance",
                "pk_width": "peak_width",
                "pk_smoothing_window": "peak_smoothing_window",
                "manual_snap_radius": "cycle_manual_snap_radius",
                "auto_refine_radius": "cycle_auto_refine_radius",
            }[key]
            thresholds[key] = settings.get(settings_key)

        def _safe_sorted_indices(raw_values: Any) -> List[int]:
            """Coerce marker payload values to sorted unique non-negative indices."""
            clean: Set[int] = set()
            if not isinstance(raw_values, (list, tuple, set)):
                return []
            # Iterate over values so malformed marker entries are ignored.
            for raw in raw_values:
                try:
                    idx = int(raw)
                except Exception:
                    continue
                if idx < 0:
                    continue
                clean.add(idx)
            return sorted(clean)

        payload = {
            "schema_version": 1,
            "auto_detect_enabled": bool(
                settings.get("cycle_auto_detect_enabled", True)
            ),
            "use_auto_markers_in_manual_mode": bool(
                settings.get("cycle_use_auto_markers_in_manual_edit_mode", True)
            ),
            "manual_revision": int(getattr(self, "_cycle_manual_revision", 0) or 0),
            "add_peaks": _safe_sorted_indices(
                getattr(self, "_add_peaks", set())
                or settings.get("cycle_manual_add_peaks", [])
                or []
            ),
            "add_troughs": _safe_sorted_indices(
                getattr(self, "_add_troughs", set())
                or settings.get("cycle_manual_add_troughs", [])
                or []
            ),
            "rm_peaks": _safe_sorted_indices(
                getattr(self, "_rm_peaks", set())
                or settings.get("cycle_manual_remove_peaks", [])
                or []
            ),
            "rm_troughs": _safe_sorted_indices(
                getattr(self, "_rm_troughs", set())
                or settings.get("cycle_manual_remove_troughs", [])
                or []
            ),
            "trace_marker_sets": {
                str(key): dict(_normalize_cycle_trace_marker_state(value))
                for key, value in getattr(self, "_cycle_trace_marker_store", {}).items()
                if str(key).strip()
            },
            "active_trace_key": str(
                getattr(self, "_cycle_active_primary_y_trace_key", "") or ""
            ),
            "thresholds": thresholds,
            "updated_at": datetime.now().isoformat(timespec="seconds"),
        }
        return _normalize_profile_cycle_markers(payload)

    def _capture_startup_profile_plot_settings(self) -> dict[str, Any]:
        """Capture startup plot settings for new profile resets.

        Purpose:
            Snapshot plot/cycle settings in their startup-default state.
        Why:
            New Profile must reset to a clean baseline that mirrors a fresh launch.
        Args:
            None.
        Returns:
            A plot settings payload compatible with profile save/load routines.
        Side Effects:
            None.
        Exceptions:
            Best-effort guards fall back to safe defaults on lookup failures.
        """
        payload: dict[str, Any] = {}

        payload["plot_generation_selection"] = {
            "fig1": bool(
                self._default_value_from_var(
                    getattr(self, "_plot_select_fig1_var", None), False
                )
            ),
            "fig2": bool(
                self._default_value_from_var(
                    getattr(self, "_plot_select_fig2_var", None), False
                )
            ),
            "fig_combined": bool(
                self._default_value_from_var(
                    getattr(self, "_plot_select_combined_var", None), True
                )
            ),
        }

        payload["axis_auto_range"] = {
            "time": bool(self._default_value_from_var(self.axis_auto_time, True)),
            "pressure": bool(
                self._default_value_from_var(self.axis_auto_pressure, True)
            ),
            "temperature": bool(
                self._default_value_from_var(self.axis_auto_temp, True)
            ),
            "derivative": bool(
                self._default_value_from_var(self.axis_auto_deriv, True)
            ),
        }

        key_map = (
            ("axis_pad_pct", "axis_pad_pct"),
            ("min_time", "min_time"),
            ("max_time", "max_time"),
            ("min_y", "min_y"),
            ("max_y", "max_y"),
            ("twin_y_min", "twin_y_min"),
            ("twin_y_max", "twin_y_max"),
            ("deriv_y_min", "deriv_y_min"),
            ("deriv_y_max", "deriv_y_max"),
            ("auto_time_ticks", "auto_time_ticks"),
            ("auto_y_ticks", "auto_y_ticks"),
            ("auto_temp_ticks", "auto_temp_ticks"),
            ("auto_deriv_ticks", "auto_deriv_ticks"),
            ("x_major_tick", "xmaj_tick"),
            ("x_minor_tick", "xmin_tick"),
            ("y_major_tick", "ymaj_tick"),
            ("y_minor_tick", "ymin_tick"),
            ("temp_major_tick", "temp_maj_tick"),
            ("temp_minor_tick", "temp_min_tick"),
            ("deriv_major_tick", "deriv_maj_tick"),
            ("deriv_minor_tick", "deriv_min_tick"),
            ("title_text", "title_text"),
            ("suptitle_text", "suptitle_text"),
            ("enable_temp_axis", "enable_temp_axis"),
            ("enable_deriv_axis", "enable_deriv_axis"),
            ("min_cycle_drop", "min_cycle_drop"),
            ("peak_prominence", "pk_prominence"),
            ("peak_distance", "pk_distance"),
            ("peak_width", "pk_width"),
            ("peak_smoothing_window", "pk_smoothing_window"),
            ("cycle_manual_snap_radius", "cycle_manual_snap_radius"),
            ("cycle_auto_refine_radius", "cycle_auto_refine_radius"),
            ("show_cycle_markers_on_core_plots", "show_cycle_markers_on_core"),
            ("show_cycle_legend_on_core_plots", "show_cycle_legend_on_core"),
            ("include_moles_in_core_plot_legend", "include_moles_core_legend"),
            (
                "core_render_cycle_side_effects_mode",
                "core_render_cycle_side_effects_mode",
            ),
            ("scatter_enabled", "scatter_enabled"),
            ("scatter_marker", "scatter_marker"),
            ("scatter_size", "scatter_size"),
            ("scatter_color", "scatter_color"),
            ("scatter_alpha", "scatter_alpha"),
            ("scatter_edgecolor", "scatter_edgecolor"),
            ("scatter_linewidth", "scatter_linewidth"),
            ("core_legend_fontsize", "core_legend_fontsize"),
            ("core_cycle_legend_fontsize", "core_cycle_legend_fontsize"),
            ("combined_y_left_key", "combined_y_left_key"),
            ("combined_y_right_key", "combined_y_right_key"),
            ("combined_y_third_key", "combined_y_third_key"),
            ("combined_include_zero_line", "combined_include_zero_line"),
            ("combined_center_plot_legend", "center_combined_plot_legend"),
        )
        # Iterate over the key map to ensure every profile-scoped setting is included.
        for key, attr in key_map:
            payload[key] = self._default_value_from_var(getattr(self, attr, None))

        stored_series = getattr(self, "_stored_scatter_series", None)
        payload["scatter_series"] = (
            copy.deepcopy(stored_series) if isinstance(stored_series, dict) else {}
        )

        payload["cycle_trace"] = (
            copy.deepcopy(cycle_trace_settings)
            if isinstance(cycle_trace_settings, dict)
            else {}
        )
        payload["core_plot_render_profiles"] = copy.deepcopy(
            _get_core_plot_render_profiles()
        )

        combined_defaults = {
            key: copy.deepcopy(value)
            # Iterate to apply the per-item logic.
            for key, value in settings.items()
            if key.startswith("combined_")
        }
        # Ensure optional combined-legend persistence keys are explicitly cleared.
        for key in (
            "combined_legend_anchor",
            "combined_legend_loc",
            "combined_cycle_legend_anchor",
            "combined_cycle_legend_loc",
            "combined_cycle_legend_anchor_space",
            "combined_cycle_legend_anchor_mode",
            "combined_cycle_legend_ref_dx_px",
            "combined_cycle_legend_ref_dy_px",
            "combined_cycle_legend_markerscale",
        ):
            combined_defaults.setdefault(key, copy.deepcopy(settings.get(key)))
        payload.update(combined_defaults)

        return payload

    def _default_profile_plot_settings_payload(self) -> dict[str, Any]:
        """Return the startup-default plot settings payload for a new profile.

        Purpose:
            Provide a deterministic baseline plot settings payload for resets.
        Why:
            New Profile must discard the current session state and restore
            startup defaults.
        Args:
            None.
        Returns:
            A deep-copied plot settings payload for profile application.
        Side Effects:
            None.
        Exceptions:
            Falls back to a fresh snapshot if the startup payload is unavailable.
        """
        startup_payload = getattr(self, "_startup_profile_plot_settings", None)
        if isinstance(startup_payload, dict):
            return copy.deepcopy(startup_payload)
        return copy.deepcopy(self._capture_startup_profile_plot_settings())

    def _collect_reaction_basis_payload(self) -> Dict[str, Any]:
        """Collect the active reaction-basis payload for profile persistence.

        Purpose:
            Serialize yield-basis fields used by Compare and cycle calculations.
        Why:
            Profile-to-profile yield comparisons need portable starting-material
            basis values independent of current app session defaults.
        Args:
            None.
        Returns:
            Dict with normalized reaction-basis values.
        Side Effects:
            None.
        Exceptions:
            Invalid numeric values are normalized to None.
        """

        def _opt_float(raw_value: Any) -> Optional[float]:
            """Return finite float or None for optional basis fields."""
            if raw_value in (None, ""):
                return None
            try:
                candidate = float(raw_value)
            except Exception:
                return None
            if not math.isfinite(candidate):
                return None
            return float(candidate)

        product_name = ""
        display_note = ""
        preset_key = ""
        try:
            product_name = str(self.v_starting_material_display_name.get() or "").strip()
            if not product_name:
                product_name = str(self.v_product_name.get() or "").strip()
        except Exception:
            product_name = str(settings.get("starting_material_display_name") or "").strip()
        try:
            display_note = str(self.v_starting_material_display_note.get() or "").strip()
        except Exception:
            display_note = str(settings.get("starting_material_display_note") or "").strip()
        try:
            preset_key = str(self.v_product_preset.get() or "").strip()
        except Exception:
            preset_key = str(settings.get("starting_material_preset") or "").strip()
        payload = {
            "reaction_id": preset_key or settings.get("selected_reaction_id", DEFAULT_SELECTED_REACTION_ID),
            "reaction_label": str(
                self._selected_reaction_catalog_entry(preset_key).get("reaction_label") or preset_key
            ).strip(),
            "starting_material_preset": preset_key,
            "starting_material_display_name": product_name,
            "starting_material_display_note": display_note,
            "starting_material_formula": str(
                settings.get("starting_material_formula", DEFAULT_STARTING_MATERIAL_FORMULA)
                or ""
            ).strip(),
            "starting_mass_g": _opt_float(
                settings.get(
                    "starting_material_mass_g",
                    settings.get("starting_mass", 0.0),
                )
            ),
            "starting_material_mw_g_mol": _opt_float(
                settings.get("starting_material_mw_g_mol")
            ),
            "gas_stoich_mol_per_mol_starting": _opt_float(
                settings.get("gas_stoich_mol_per_mol_starting")
            ),
            "stoich_mol_gas_per_mol_starting": _opt_float(
                settings.get("stoich_mol_gas_per_mol_starting")
            ),
            "gas_molar_mass": _opt_float(
                settings.get("vdw_gas_molar_mass", DEFAULT_GAS_MOLAR_MASS)
            ),
            "final_product_name": str(settings.get("final_product_name") or "").strip(),
            "final_product_formula": str(settings.get("final_product_formula") or "").strip(),
            "final_product_mw_g_mol": _opt_float(settings.get("final_product_mw_g_mol")),
            "product_stoich_mol_per_mol_starting": _opt_float(
                settings.get("product_stoich_mol_per_mol_starting")
            ),
            "yield_mode": str(settings.get("yield_mode", REACTION_YIELD_MODE_PRODUCT) or "").strip(),
            "product_formula": str(
                settings.get("starting_material_formula", DEFAULT_STARTING_MATERIAL_FORMULA)
                or ""
            ).strip(),
        }
        return _normalize_reaction_basis_payload(payload)

    def _collect_reaction_dashboard_state_payload(self) -> Dict[str, Any]:
        """Collect Reaction Dashboard UI values for profile persistence.

        Purpose:
            Serialize the visible Reaction Dashboard form state into a JSON-safe
            payload stored with workspace profiles.
        Why:
            Dashboard operators need selected templates, gas-source controls, pH
            preference, and typed inputs to survive explicit profile saves and
            startup autosave restores without rerunning calculations.
        Args:
            None.
        Returns:
            Dict containing template id, source mode, pH enablement, template input
            strings, and gas-source input strings.
        Side Effects:
            None.
        Exceptions:
            Widget variable read failures fall back to empty strings or defaults.
        """

        def _string_var_value(var: Any) -> str:
            """Return one Tk-like variable value as a JSON-safe string.

            Purpose:
                Read a dashboard field variable for profile serialization.
            Why:
                Profile JSON stores entry values as text so manual formatting and
                blank inputs round-trip without numeric coercion.
            Args:
                var: Tk-like variable exposing `get()`.
            Returns:
                String value suitable for JSON persistence.
            Side Effects:
                None.
            Exceptions:
                Read failures are normalized to an empty string.
            """
            try:
                value = var.get()
            except Exception:
                value = ""
            return "" if value is None else str(value)

        try:
            template_id = str(self._reaction_template_var.get() or "").strip()
        except Exception:
            template_id = str(
                settings.get(REACTION_DASHBOARD_SELECTED_TEMPLATE_KEY) or ""
            ).strip()
        if not template_id:
            try:
                template_id = str(
                    self._reaction_active_template().template_id or ""
                ).strip()
            except Exception:
                template_id = str(
                    settings.get(REACTION_DASHBOARD_SELECTED_TEMPLATE_KEY) or ""
                ).strip()

        source_mode = str(settings.get("reaction_dashboard_source_mode") or "").strip()
        try:
            source_mode = str(
                self._reaction_source_mode_var.get() or source_mode
            ).strip()
        except Exception:
            pass

        try:
            ph_enabled = bool(self._reaction_ph_enabled_var.get())
        except Exception:
            ph_enabled = False

        template_inputs = {
            str(key): _string_var_value(var)
            for key, var in getattr(self, "_reaction_input_vars", {}).items()
            if str(key)
        }
        source_inputs = {
            str(key): _string_var_value(var)
            for key, var in getattr(self, "_reaction_source_vars", {}).items()
            if str(key)
        }

        current_state = {
            "template_id": template_id,
            "source_mode": source_mode,
            "ph_enabled": ph_enabled,
            "template_inputs": template_inputs,
            "source_inputs": source_inputs,
        }
        try:
            active_run = self._ensure_reaction_dashboard_active_run()
            active_run.update(current_state)
            active_run["name"] = (
                str(self._reaction_run_name_var.get() or "Reaction run").strip()
                or "Reaction run"
            )
        except Exception:
            pass
        return _normalize_reaction_dashboard_state_payload(
            {
                **current_state,
                "runs": list(getattr(self, "_reaction_run_records", []) or []),
                "active_run_id": str(
                    getattr(self, "_reaction_active_run_id", "") or ""
                ),
            }
        )

    def _collect_profile_identifiers(self) -> Dict[str, str]:
        """Return normalized profile identifiers from runtime settings.

        Purpose:
            Provide one canonical accessor for persisted profile metadata fields.
        Why:
            Profile save/load and Ledger prefill workflows need a shared source for
            `Project #`, `Batch #`, and `Item #`.
        Args:
            None.
        Returns:
            Dict containing normalized profile identifier strings.
        Side Effects:
            None.
        Exceptions:
            Invalid settings payloads are normalized to empty-string defaults.
        """
        return _normalize_profile_identifiers(settings.get("profile_identifiers"))

    def _collect_profile_analysis_last_result(self) -> dict[str, Any] | None:
        """Return the profile-safe latest Analysis result envelope.

        Purpose:
            Capture the persisted Analysis run payload for profile serialization.
        Why:
            The current working profile is the long-lived workspace boundary, so
            the latest Analysis result must travel with that profile instead of
            living only in global settings.
        Args:
            None.
        Returns:
            Dict copy of the Analysis result envelope, or None when no valid
            result is available.
        Side Effects:
            None.
        Exceptions:
            Invalid or non-serializable values are sanitized out of the result.
        """
        persisted_result = settings.get(SOL_ANALYSIS_LAST_RESULT_SETTINGS_KEY)
        if not isinstance(persisted_result, Mapping):
            return None
        sanitized = self._sanitize_value_for_settings(dict(persisted_result))
        if not isinstance(sanitized, Mapping):
            return None
        analysis_result = sanitized.get("analysis_result")
        if not isinstance(analysis_result, Mapping):
            return None
        return dict(sanitized)

    def _apply_profile_analysis_last_result(
        self, analysis_last_result: Mapping[str, Any] | None
    ) -> None:
        """Install a profile-scoped Analysis result envelope into settings.

        Purpose:
            Make the loaded profile's latest Analysis run available to the
            existing context/signature-gated restore path.
        Why:
            Profile load occurs before current-profile settings are updated, so
            the profile payload must seed `sol_analysis_last_result_v2` directly
            while `_analysis_profile_restore_target_name` anchors the context.
        Args:
            analysis_last_result: Profile payload value for the latest Analysis
                result envelope.
        Returns:
            None.
        Side Effects:
            Updates `settings["sol_analysis_last_result_v2"]` and clears any
            in-memory Analysis result fingerprint.
        Exceptions:
            Malformed profile payloads clear the settings result safely.
        """
        sanitized = (
            self._sanitize_value_for_settings(dict(analysis_last_result))
            if isinstance(analysis_last_result, Mapping)
            else None
        )
        if isinstance(sanitized, Mapping) and isinstance(
            sanitized.get("analysis_result"), Mapping
        ):
            settings[SOL_ANALYSIS_LAST_RESULT_SETTINGS_KEY] = dict(sanitized)
        else:
            settings[SOL_ANALYSIS_LAST_RESULT_SETTINGS_KEY] = None
        self._analysis_result_context_fingerprint = None

    def _apply_profile_identifiers(self, identifiers: Optional[Mapping[str, Any]]) -> None:
        """Persist normalized profile identifiers into runtime settings.

        Purpose:
            Apply profile identifier metadata from dialogs or profile payloads.
        Why:
            Identifier values must survive New Profile, Save, and Load workflows.
        Args:
            identifiers: Optional mapping containing identifier string fields.
        Returns:
            None.
        Side Effects:
            Updates `settings["profile_identifiers"]`.
        Exceptions:
            Invalid payloads are normalized to empty-string defaults.
        """
        settings["profile_identifiers"] = _normalize_profile_identifiers(identifiers)

    def _serialize_workspace_state(self, include_dataset_path: bool) -> dict[str, Any]:
        """Serialize current workspace state into a profile payload.

        Purpose:
            Capture all profile-restorable workspace settings in one dict.
        Why:
            Save/overwrite/new-profile flows need one canonical persistence shape
            shared across profile write operations.
        Args:
            include_dataset_path: When True, include the current dataset path.
        Returns:
            Dict containing profile-restorable workspace state.
        Side Effects:
            None.
        Exceptions:
            None; callers handle any downstream serialization or I/O failures.
        """
        try:
            analysis_last_result = self._collect_profile_analysis_last_result()
        except Exception:
            # Lightweight harnesses and partial startup states may not expose the
            # Analysis persistence helper; omit the optional profile slot then.
            analysis_last_result = None
        payload: dict[str, Any] = {
            "multi_sheet_enabled": bool(self.multi_sheet_enabled),
            "selected_sheet": self.selected_sheet.get(),
            "selected_sheets": list(self.selected_sheets),
            "column_assignments": (
                dict(self.columns) if isinstance(self.columns, dict) else {}
            ),
            "per_sheet_mapping": self._get_per_sheet_column_map(),
            "plot_elements": copy.deepcopy(settings.get("plot_elements", {})),
            "plot_settings": self._collect_profile_plot_settings(),
            "column_trace_legend_labels": self._get_column_trace_legend_labels(),
            "layout_profiles": copy.deepcopy(settings.get("layout_profiles", {})),
            "final_report_settings": self._collect_final_report_state_from_ui(),
            "reaction_basis": self._collect_reaction_basis_payload(),
            "reaction_dashboard_state": (
                self._collect_reaction_dashboard_state_payload()
            ),
            "cycle_markers": self._collect_profile_cycle_markers(),
            "profile_identifiers": self._collect_profile_identifiers(),
            SOL_ANALYSIS_PROFILE_LAST_RESULT_PAYLOAD_KEY: analysis_last_result,
        }
        if include_dataset_path and self.file_path:
            payload["dataset_path"] = self.file_path
        return payload

    def _deserialize_workspace_state(self, payload: dict[str, Any]) -> dict[str, Any]:
        """Deserialize a profile payload into normalized workspace state.

        Purpose:
            Normalize profile payloads into a predictable workspace state dict.
        Why:
            Ensures profile load paths can reliably reset the UI and data model.
        Args:
            payload: Profile payload dictionary to parse.
        Returns:
            A normalized state dict used by profile restore logic.
        Side Effects:
            None.
        Exceptions:
            Returns an empty dict for invalid payloads instead of raising.
        """
        if not isinstance(payload, dict):
            return {}
        dataset_required = payload.get("dataset_required")
        if dataset_required is None:
            dataset_required = True
        state: dict[str, Any] = {
            "dataset_path": payload.get("dataset_path"),
            "dataset_required": bool(dataset_required),
            "multi_sheet_enabled": bool(payload.get("multi_sheet_enabled", False)),
            "selected_sheet": str(payload.get("selected_sheet") or ""),
            "selected_sheets": [
                str(name) for name in (payload.get("selected_sheets") or []) if name
            ],
            "column_assignments": dict(payload.get("column_assignments") or {}),
            "per_sheet_mapping": dict(payload.get("per_sheet_mapping") or {}),
            "plot_elements": dict(payload.get("plot_elements") or {}),
            "plot_settings": dict(payload.get("plot_settings") or {}),
            "column_trace_legend_labels": self._normalize_column_trace_legend_labels(
                payload.get("column_trace_legend_labels")
            ),
            "layout_profiles": dict(payload.get("layout_profiles") or {}),
            "final_report_settings": dict(payload.get("final_report_settings") or {}),
            "reaction_basis": dict(payload.get("reaction_basis") or {}),
            "reaction_dashboard_state": _normalize_reaction_dashboard_state_payload(
                payload.get("reaction_dashboard_state")
            ),
            "cycle_markers": _normalize_profile_cycle_markers(
                payload.get("cycle_markers")
            ),
            "profile_identifiers": _normalize_profile_identifiers(
                payload.get("profile_identifiers")
            ),
            SOL_ANALYSIS_PROFILE_LAST_RESULT_PAYLOAD_KEY: (
                dict(payload.get(SOL_ANALYSIS_PROFILE_LAST_RESULT_PAYLOAD_KEY))
                if isinstance(
                    payload.get(SOL_ANALYSIS_PROFILE_LAST_RESULT_PAYLOAD_KEY),
                    Mapping,
                )
                else None
            ),
        }
        return state

    def _apply_profile_cycle_markers(
        self, cycle_markers: Optional[Mapping[str, Any]]
    ) -> None:
        """Apply profile-scoped cycle marker edits to runtime state.

        Purpose:
            Restore persisted marker corrections into active cycle-analysis state.
        Why:
            Profile loading should reactivate marker corrections used by Compare
            and Cycle Analysis workflows without requiring manual re-entry.
        Args:
            cycle_markers: Optional profile cycle marker payload.
        Returns:
            None.
        Side Effects:
            Updates cycle-manual settings fields, the per-trace marker store, and
            in-memory marker sets.
        Exceptions:
            Invalid payloads clear manual marker overrides safely.
        """
        normalized = _normalize_profile_cycle_markers(cycle_markers)
        if normalized is None:
            add_peaks: List[int] = []
            add_troughs: List[int] = []
            rm_peaks: List[int] = []
            rm_troughs: List[int] = []
            trace_marker_sets: Dict[str, Dict[str, Any]] = {}
            active_trace_key = self._cycle_primary_y_trace_key(
                self._active_cycle_primary_y_column()
            )
            manual_revision = 0
            auto_detect_enabled = bool(settings.get("cycle_auto_detect_enabled", True))
            use_auto_markers_in_manual_mode = bool(
                settings.get("cycle_use_auto_markers_in_manual_edit_mode", True)
            )
            thresholds: Dict[str, Any] = {}
        else:
            add_peaks = list(normalized.get("add_peaks") or [])
            add_troughs = list(normalized.get("add_troughs") or [])
            rm_peaks = list(normalized.get("rm_peaks") or [])
            rm_troughs = list(normalized.get("rm_troughs") or [])
            trace_marker_sets = _normalize_cycle_trace_marker_store(
                normalized.get("trace_marker_sets")
            )
            active_trace_key = str(normalized.get("active_trace_key") or "").strip()
            manual_revision = int(normalized.get("manual_revision") or 0)
            auto_detect_enabled = bool(normalized.get("auto_detect_enabled", True))
            use_auto_markers_in_manual_mode = bool(
                normalized.get("use_auto_markers_in_manual_mode", True)
            )
            thresholds = dict(normalized.get("thresholds") or {})

        if not active_trace_key:
            active_trace_key = self._cycle_primary_y_trace_key(
                self._active_cycle_primary_y_column()
            )
        legacy_state = _normalize_cycle_trace_marker_state(
            {
                "add_peaks": add_peaks,
                "add_troughs": add_troughs,
                "rm_peaks": rm_peaks,
                "rm_troughs": rm_troughs,
                "manual_revision": manual_revision,
            }
        )
        if active_trace_key and active_trace_key not in trace_marker_sets:
            if _cycle_trace_marker_state_has_markers(legacy_state):
                trace_marker_sets[active_trace_key] = legacy_state
        self._cycle_trace_marker_store = dict(trace_marker_sets)
        self._cycle_active_primary_y_trace_key = active_trace_key

        settings["cycle_manual_add_peaks"] = list(add_peaks)
        settings["cycle_manual_add_troughs"] = list(add_troughs)
        settings["cycle_manual_remove_peaks"] = list(rm_peaks)
        settings["cycle_manual_remove_troughs"] = list(rm_troughs)
        settings["cycle_trace_marker_sets"] = {
            str(key): dict(_normalize_cycle_trace_marker_state(value))
            for key, value in self._cycle_trace_marker_store.items()
            if str(key).strip()
        }
        settings["cycle_active_primary_y_trace_key"] = active_trace_key
        active_column = self._cycle_primary_y_column_from_key(active_trace_key)
        if active_column:
            settings["calculation_trace"] = self._normalize_calculation_trace(
                self._get_column_trace_groups(),
                {"role": "y1", "column": active_column},
            )
        settings["cycle_auto_detect_enabled"] = bool(auto_detect_enabled)
        settings["cycle_use_auto_markers_in_manual_edit_mode"] = bool(
            use_auto_markers_in_manual_mode
        )

        # Apply marker sets directly so interactive cycle tools reflect loaded profile state.
        active_state = _normalize_cycle_trace_marker_state(
            self._cycle_trace_marker_store.get(active_trace_key, legacy_state)
        )
        self._auto_peaks = set(active_state.get("auto_peaks", []))
        self._auto_troughs = set(active_state.get("auto_troughs", []))
        self._add_peaks = set(active_state.get("add_peaks", []))
        self._add_troughs = set(active_state.get("add_troughs", []))
        self._rm_peaks = set(active_state.get("rm_peaks", []))
        self._rm_troughs = set(active_state.get("rm_troughs", []))
        self._cycle_manual_revision = int(
            max(0, active_state.get("manual_revision", 0) or 0)
        )
        self._preload_cycle_markers = {
            "add_peaks": list(active_state.get("add_peaks", [])),
            "add_troughs": list(active_state.get("add_troughs", [])),
            "rm_peaks": list(active_state.get("rm_peaks", [])),
            "rm_troughs": list(active_state.get("rm_troughs", [])),
        }
        self._sync_legacy_cycle_marker_settings()
        auto_detect_var = getattr(self, "auto_detect_cycles", None)
        if auto_detect_var is not None:
            try:
                auto_detect_var.set(bool(auto_detect_enabled))
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        use_auto_markers_var = getattr(
            self, "cycle_use_auto_markers_in_manual_edit_mode", None
        )
        if use_auto_markers_var is not None:
            try:
                use_auto_markers_var.set(bool(use_auto_markers_in_manual_mode))
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        try:
            self._refresh_cycle_auto_manual_mode_visibility()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        for key, var_name in (
            ("min_cycle_drop", "min_cycle_drop"),
            ("pk_prominence", "pk_prominence"),
            ("pk_distance", "pk_distance"),
            ("pk_width", "pk_width"),
            ("pk_smoothing_window", "pk_smoothing_window"),
            ("manual_snap_radius", "cycle_manual_snap_radius"),
            ("auto_refine_radius", "cycle_auto_refine_radius"),
        ):
            value = thresholds.get(key)
            if value in (None, ""):
                continue
            var_obj = getattr(self, var_name, None)
            if var_obj is None:
                continue
            try:
                var_obj.set(value)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

    def _apply_profile_column_trace_legend_labels(self, raw_labels: Any) -> None:
        """Apply profile-scoped Columns-tab custom legend labels.

        Purpose:
            Restore custom per-trace legend labels into runtime and settings state.
        Why:
            Multi-sheet refreshes and profile loads rebuild Columns UI state, so
            custom labels must be restored before column apply/reload paths run.
        Args:
            raw_labels: Candidate profile legend-label mapping.
        Returns:
            None.
        Side Effects:
            Mutates `_column_trace_legend_labels` and
            `settings["column_trace_legend_labels"]`.
        Exceptions:
            Invalid payloads are normalized to an empty mapping.
        """
        normalized = self._normalize_column_trace_legend_labels(raw_labels)
        self._column_trace_legend_labels = dict(normalized)
        settings["column_trace_legend_labels"] = dict(normalized)

    def _apply_profile_plot_settings(self, plot_settings: Dict[str, Any]) -> None:
        """Apply profile plot settings.
        Used to apply profile plot settings changes to live state."""
        if not isinstance(plot_settings, dict):
            return

        # Iterate over items from plot_settings to apply the per-item logic.
        for key, value in plot_settings.items():
            settings[key] = copy.deepcopy(value)
        settings["core_plot_render_profiles"] = _normalize_core_plot_render_profiles(
            plot_settings.get("core_plot_render_profiles"),
            seed_source=settings,
        )
        _legacy_core_profile = settings["core_plot_render_profiles"].get(
            CORE_RENDER_PROFILE_PLOT_IDS[0]
        )
        _write_legacy_core_legend_settings_from_profile(_legacy_core_profile)

        # Closure captures _apply_profile_plot_settings local context to keep helper logic scoped and invoked directly within _apply_profile_plot_settings.
        def _set_var(var: Optional[tk.Variable], value: Any) -> None:
            """Set var.
            Used to persist var into the current state."""
            if var is None:
                return
            try:
                var.set(value)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

        # Iterate to apply the per-item logic.
        for key, attr in (
            ("min_time", "min_time"),
            ("max_time", "max_time"),
            ("min_y", "min_y"),
            ("max_y", "max_y"),
            ("twin_y_min", "twin_y_min"),
            ("twin_y_max", "twin_y_max"),
            ("deriv_y_min", "deriv_y_min"),
            ("deriv_y_max", "deriv_y_max"),
            ("auto_time_ticks", "auto_time_ticks"),
            ("auto_y_ticks", "auto_y_ticks"),
            ("auto_temp_ticks", "auto_temp_ticks"),
            ("auto_deriv_ticks", "auto_deriv_ticks"),
            ("x_major_tick", "xmaj_tick"),
            ("x_minor_tick", "xmin_tick"),
            ("y_major_tick", "ymaj_tick"),
            ("y_minor_tick", "ymin_tick"),
            ("temp_major_tick", "temp_maj_tick"),
            ("temp_minor_tick", "temp_min_tick"),
            ("deriv_major_tick", "deriv_maj_tick"),
            ("deriv_minor_tick", "deriv_min_tick"),
            ("title_text", "title_text"),
            ("suptitle_text", "suptitle_text"),
            ("enable_temp_axis", "enable_temp_axis"),
            ("enable_deriv_axis", "enable_deriv_axis"),
            ("min_cycle_drop", "min_cycle_drop"),
            ("peak_prominence", "pk_prominence"),
            ("peak_distance", "pk_distance"),
            ("peak_width", "pk_width"),
            ("peak_smoothing_window", "pk_smoothing_window"),
            ("cycle_manual_snap_radius", "cycle_manual_snap_radius"),
            ("cycle_auto_refine_radius", "cycle_auto_refine_radius"),
            (
                "core_render_cycle_side_effects_mode",
                "core_render_cycle_side_effects_mode",
            ),
            ("core_legend_fontsize", "core_legend_fontsize"),
            ("core_cycle_legend_fontsize", "core_cycle_legend_fontsize"),
        ):
            if key in plot_settings:
                _set_var(getattr(self, attr, None), plot_settings.get(key))
        settings["core_render_cycle_side_effects_mode"] = (
            _normalize_core_render_cycle_side_effects_mode(
                settings.get("core_render_cycle_side_effects_mode", "auto")
            )
        )
        _set_var(
            getattr(self, "core_legend_fontsize", None),
            settings.get("core_legend_fontsize", label_fontsize),
        )
        _set_var(
            getattr(self, "core_cycle_legend_fontsize", None),
            settings.get(
                "core_cycle_legend_fontsize",
                settings.get("core_legend_fontsize", label_fontsize),
            ),
        )

        auto_range = plot_settings.get("axis_auto_range")
        if isinstance(auto_range, dict):
            _set_var(self.axis_auto_time, bool(auto_range.get("time", True)))
            _set_var(self.axis_auto_pressure, bool(auto_range.get("pressure", True)))
            _set_var(self.axis_auto_temp, bool(auto_range.get("temperature", True)))
            _set_var(self.axis_auto_deriv, bool(auto_range.get("derivative", True)))

        if "axis_pad_pct" in plot_settings:
            _set_var(self.axis_pad_pct, plot_settings.get("axis_pad_pct"))

        plot_selection = plot_settings.get("plot_generation_selection")
        if isinstance(plot_selection, dict):
            _set_var(self._plot_select_fig1_var, bool(plot_selection.get("fig1")))
            _set_var(self._plot_select_fig2_var, bool(plot_selection.get("fig2")))
            _set_var(
                self._plot_select_combined_var,
                bool(plot_selection.get("fig_combined")),
            )

        # Iterate to apply the per-item logic.
        for key, attr in (
            ("scatter_enabled", "scatter_enabled"),
            ("scatter_marker", "scatter_marker"),
            ("scatter_size", "scatter_size"),
            ("scatter_color", "scatter_color"),
            ("scatter_alpha", "scatter_alpha"),
            ("scatter_edgecolor", "scatter_edgecolor"),
            ("scatter_linewidth", "scatter_linewidth"),
        ):
            if key in plot_settings:
                _set_var(getattr(self, attr, None), plot_settings.get(key))

        if "scatter_series" in plot_settings:
            settings["scatter_series"] = copy.deepcopy(
                plot_settings.get("scatter_series") or {}
            )
        try:
            self._persist_scatter_settings()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

        cycle_trace = plot_settings.get("cycle_trace")
        if isinstance(cycle_trace, dict):
            try:
                self._persist_cycle_trace_settings(cycle_trace)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            # Iterate to apply the per-item logic.
            for key, attr in (
                ("line_color", "cycle_line_color"),
                ("line_style", "cycle_line_style"),
                ("line_width", "cycle_line_width"),
                ("peak_color", "cycle_peak_color"),
                ("trough_color", "cycle_trough_color"),
                ("peak_marker", "cycle_peak_marker"),
                ("trough_marker", "cycle_trough_marker"),
                ("marker_size", "cycle_marker_size"),
            ):
                if key in cycle_trace:
                    _set_var(getattr(self, attr, None), cycle_trace.get(key))

        # Iterate to apply the per-item logic.
        for key, attr in (
            ("combined_y_left_key", "combined_y_left_key"),
            ("combined_y_right_key", "combined_y_right_key"),
            ("combined_y_third_key", "combined_y_third_key"),
            ("combined_include_zero_line", "combined_include_zero_line"),
            ("combined_x_axis_label", "combined_x_axis_label"),
            ("combined_primary_axis_label", "combined_primary_axis_label"),
            ("combined_deriv_axis_label", "combined_deriv_axis_label"),
            ("combined_temp_axis_label", "combined_temp_axis_label"),
            ("combined_primary_labelpad", "combined_primary_labelpad"),
            ("combined_temp_labelpad", "combined_temp_labelpad"),
            ("combined_deriv_labelpad", "combined_deriv_labelpad"),
            ("combined_deriv_axis_offset", "combined_deriv_axis_offset"),
            ("combined_xlabel_tick_gap_pts", "combined_xlabel_tick_gap"),
            ("combined_left_pad_pct", "combined_left_padding_pct"),
            ("combined_right_pad_pct", "combined_right_padding_pct"),
            ("combined_title_pad_pts", "combined_title_pad_pts"),
            ("combined_suptitle_pad_pts", "combined_suptitle_pad_pts"),
            ("combined_suptitle_y", "combined_suptitle_y"),
            ("combined_top_margin_pct", "combined_top_margin_pct"),
            ("combined_export_pad_pts", "combined_export_pad_pts"),
            ("combined_suptitle_fontsize", "combined_suptitle_fontsize"),
            ("combined_title_fontsize", "combined_title_fontsize"),
            ("combined_label_fontsize", "combined_label_fontsize"),
            ("combined_tick_fontsize", "combined_tick_fontsize"),
            ("combined_legend_fontsize", "combined_legend_fontsize"),
            ("combined_cycle_legend_fontsize", "combined_cycle_legend_fontsize"),
            ("combined_font_family", "combined_font_family"),
            ("combined_legend_wrap", "combined_legend_wrap"),
            ("combined_legend_rows", "combined_legend_rows"),
            ("combined_legend_gap_pts", "combined_legend_label_gap"),
            ("combined_legend_bottom_margin_pts", "combined_legend_bottom_margin"),
            ("combined_legend_alignment", "combined_legend_alignment"),
            (
                "combined_legend_shadowbox_fill_color",
                "combined_legend_shadowbox_fill_color",
            ),
            ("combined_cycle_legend_loc_choice", "combined_cycle_legend_loc_choice"),
            ("combined_cycle_legend_ref_axis", "combined_cycle_legend_ref_axis"),
            ("combined_cycle_legend_ref_corner", "combined_cycle_legend_ref_corner"),
        ):
            if key in plot_settings:
                _set_var(getattr(self, attr, None), plot_settings.get(key))

        if "combined_center_plot_legend" in plot_settings:
            _set_var(
                getattr(self, "center_combined_plot_legend", None),
                bool(plot_settings.get("combined_center_plot_legend")),
            )

        legend_anchor = plot_settings.get("combined_legend_anchor")
        if isinstance(legend_anchor, (list, tuple)) and len(legend_anchor) == 2:
            self._combined_legend_anchor = (legend_anchor[0], legend_anchor[1])
        cycle_anchor = plot_settings.get("combined_cycle_legend_anchor")
        if isinstance(cycle_anchor, (list, tuple)) and len(cycle_anchor) == 2:
            self._combined_cycle_legend_anchor = (cycle_anchor[0], cycle_anchor[1])
        cycle_anchor_space = plot_settings.get("combined_cycle_legend_anchor_space")
        if isinstance(cycle_anchor_space, str):
            self._combined_cycle_legend_anchor_space = cycle_anchor_space

        try:
            self._sync_combined_axis_display()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            self._apply_combined_axis_preferences(skip_save=True)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        for _core_plot_id in CORE_RENDER_PROFILE_PLOT_IDS:
            try:
                self._mark_plot_layout_dirty(_core_plot_id)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

