    def _apply_profile_reaction_basis(self, reaction_basis: Dict[str, Any]) -> None:
        """Apply persisted reaction-basis values from a profile payload.

        Purpose:
            Restore starting-material basis values used by yield calculations.
        Why:
            Profile restore should preserve reaction basis so yield workflows and
            Compare calculations remain portable across sessions.
        Args:
            reaction_basis: Reaction-basis dict from profile payload.
        Returns:
            None.
        Side Effects:
            Updates settings and related Tk variables for basis fields.
        Exceptions:
            Invalid values are ignored via best-effort guards.
        """
        if not isinstance(reaction_basis, dict):
            return
        reaction_basis = _normalize_reaction_basis_payload(reaction_basis)

        def _opt_float(raw_value: Any) -> Optional[float]:
            """Return finite float or None for optional profile basis values."""
            if raw_value in (None, ""):
                return None
            try:
                candidate = float(raw_value)
            except Exception:
                return None
            if not math.isfinite(candidate):
                return None
            return float(candidate)

        def _set_var(var: Optional[tk.Variable], value: Any) -> None:
            """Safely set one Tk variable during reaction-basis restore."""
            if var is None or value is None:
                return
            try:
                var.set(value)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

        preset_key = str(
            reaction_basis.get("reaction_id")
            or reaction_basis.get("starting_material_preset")
            or ""
        ).strip()
        if preset_key:
            settings["selected_reaction_id"] = preset_key
            settings["starting_material_preset"] = preset_key
            _set_var(getattr(self, "v_product_preset", None), preset_key)

        display_name = str(
            reaction_basis.get("starting_material_display_name") or ""
        ).strip()
        display_note = str(
            reaction_basis.get("starting_material_display_note") or ""
        ).strip()
        settings["starting_material_display_name"] = display_name
        settings["starting_material_display_note"] = display_note
        _set_var(getattr(self, "v_starting_material_display_name", None), display_name)
        _set_var(getattr(self, "v_starting_material_display_note", None), display_note)

        starting_mass = _opt_float(reaction_basis.get("starting_mass_g"))
        if starting_mass is not None:
            settings["starting_material_mass_g"] = starting_mass
            settings["starting_mass"] = starting_mass
            settings["naoh_mass"] = starting_mass
            _set_var(getattr(self, "v_starting_mass", None), starting_mass)

        starting_mw = _opt_float(reaction_basis.get("starting_material_mw_g_mol"))
        if starting_mw is not None:
            settings["starting_material_mw_g_mol"] = starting_mw
            settings["product_molar_mass"] = starting_mw
            _set_var(getattr(self, "v_product_molar_mass", None), starting_mw)

        stoich_ratio = _opt_float(reaction_basis.get("stoich_mol_gas_per_mol_starting"))
        if stoich_ratio is not None:
            settings["stoich_mol_gas_per_mol_starting"] = stoich_ratio
            _set_var(getattr(self, "v_starting_stoich", None), stoich_ratio)
            _set_var(getattr(self, "v_gas_stoich", None), stoich_ratio)

        gas_molar_mass_value = _opt_float(reaction_basis.get("gas_molar_mass"))
        if gas_molar_mass_value is not None and gas_molar_mass_value > 0.0:
            settings["vdw_gas_molar_mass"] = gas_molar_mass_value
            _set_var(getattr(self, "v_gas_molar_mass", None), gas_molar_mass_value)

        product_formula = str(reaction_basis.get("product_formula") or "").strip()
        if product_formula:
            settings["starting_material_formula"] = product_formula
            settings["product_formula"] = product_formula

        final_product_name = str(reaction_basis.get("final_product_name") or "").strip()
        if final_product_name:
            settings["final_product_name"] = final_product_name
            _set_var(getattr(self, "v_final_product_name", None), final_product_name)
        final_product_formula = str(
            reaction_basis.get("final_product_formula") or ""
        ).strip()
        if final_product_formula:
            settings["final_product_formula"] = final_product_formula
            _set_var(
                getattr(self, "v_final_product_formula", None), final_product_formula
            )
        final_product_mw = _opt_float(reaction_basis.get("final_product_mw_g_mol"))
        if final_product_mw is not None:
            settings["final_product_mw_g_mol"] = final_product_mw
            _set_var(getattr(self, "v_final_product_molar_mass", None), final_product_mw)
        product_stoich = _opt_float(
            reaction_basis.get("product_stoich_mol_per_mol_starting")
        )
        if product_stoich is not None:
            settings["product_stoich_mol_per_mol_starting"] = product_stoich
            _set_var(getattr(self, "v_product_stoich", None), product_stoich)
        yield_mode = str(
            reaction_basis.get("yield_mode", REACTION_YIELD_MODE_PRODUCT) or ""
        ).strip()
        if yield_mode in REACTION_YIELD_MODE_CHOICES:
            settings["yield_mode"] = yield_mode
            _set_var(getattr(self, "v_yield_mode", None), yield_mode)

        try:
            self._refresh_reaction_preset_choices()
        except Exception:
            pass
        try:
            self._update_auto_title_preview()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _apply_profile_reaction_dashboard_state(
        self, dashboard_state: Optional[Mapping[str, Any]]
    ) -> None:
        """Apply persisted Reaction Dashboard profile state to live controls.

        Purpose:
            Restore saved dashboard template/source choices and visible entry
            values from a profile payload.
        Why:
            Profile restore rebuilds portions of the UI; applying dashboard inputs
            after template load prevents saved values from being overwritten by
            template defaults during restart or profile-load workflows.
        Args:
            dashboard_state: Optional profile mapping containing dashboard UI state.
        Returns:
            None.
        Side Effects:
            Updates Reaction Dashboard Tk variables, selected-template settings,
            source-mode settings, and dashboard warning/status labels.
        Exceptions:
            Missing widgets, unknown fields, or malformed profile values are ignored
            through best-effort guards.
        """
        normalized = _normalize_reaction_dashboard_state_payload(dashboard_state)
        if not normalized:
            return
        restored_runs = normalized.get("runs")
        if isinstance(restored_runs, Sequence) and not isinstance(
            restored_runs, (str, bytes)
        ):
            self._reaction_run_records = [
                dict(row) for row in restored_runs if isinstance(row, Mapping)
            ]
            self._reaction_active_run_id = str(normalized.get("active_run_id") or "")
            active_run = next(
                (
                    row
                    for row in self._reaction_run_records
                    if row.get("run_id") == self._reaction_active_run_id
                ),
                self._reaction_run_records[0] if self._reaction_run_records else {},
            )
            if isinstance(active_run, Mapping):
                normalized = dict(active_run)
            try:
                self._refresh_reaction_run_selector()
            except Exception:
                pass

        template: Optional[ReactionTemplate] = None
        template_id = str(normalized.get("template_id") or "").strip()
        templates = _reaction_dashboard_templates_from_settings(settings)
        if template_id and template_id in templates:
            template = templates[template_id]
            settings[REACTION_DASHBOARD_SELECTED_TEMPLATE_KEY] = template.template_id
            template_var = getattr(self, "_reaction_template_var", None)
            if template_var is not None:
                try:
                    template_var.set(template.template_id)
                except Exception:
                    pass
        else:
            try:
                template = self._reaction_active_template()
            except Exception:
                template = None

        source_mode = str(normalized.get("source_mode") or "").strip()
        if source_mode:
            settings["reaction_dashboard_source_mode"] = source_mode
            source_var = getattr(self, "_reaction_source_mode_var", None)
            if source_var is not None:
                try:
                    source_var.set(source_mode)
                except Exception:
                    pass
            display_var = getattr(self, "_reaction_source_display_var", None)
            source_label = getattr(self, "_reaction_source_key_to_label", {}).get(
                source_mode
            )
            if display_var is not None and source_label:
                try:
                    display_var.set(source_label)
                except Exception:
                    pass

        if template is not None:
            try:
                self._refresh_reaction_template_selector()
            except Exception:
                pass
            try:
                self._load_reaction_template_into_ui(template)
            except Exception:
                pass

        if "ph_enabled" in normalized:
            ph_var = getattr(self, "_reaction_ph_enabled_var", None)
            if ph_var is not None:
                try:
                    ph_var.set(bool(normalized.get("ph_enabled")))
                except Exception:
                    pass

        template_inputs = normalized.get("template_inputs")
        if isinstance(template_inputs, Mapping):
            for key, value in template_inputs.items():
                var = getattr(self, "_reaction_input_vars", {}).get(str(key))
                if var is None:
                    continue
                try:
                    var.set(str(value))
                except Exception:
                    pass

        source_inputs = normalized.get("source_inputs")
        if isinstance(source_inputs, Mapping):
            for key, value in source_inputs.items():
                var = getattr(self, "_reaction_source_vars", {}).get(str(key))
                if var is None:
                    continue
                try:
                    var.set(str(value))
                except Exception:
                    pass

    def _clear_workspace_state(self) -> None:
        """Clear in-memory workspace state before restore/load operations.

        Purpose:
            Reset dataset, column, plot, and workflow caches to a known baseline.
        Why:
            Profile/session restore must start from clean state so stale payloads
            cannot leak across dataset/profile boundaries.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Clears dataframe/sheet caches, column mappings, cycle payload caches,
            Analysis restore fingerprints, and auto-title runtime caches.
        Exceptions:
            Best-effort guards keep UI reset failures non-fatal.
        """
        self.df = None
        self.sheet_dfs = {}
        self.sheet_names = []
        self.file_path = ""
        self._sheet_names_loaded = False
        self._multi_sheet_lists_signature = None
        self._columns_schema_preview = []
        self._columns_schema_preview_sheet = None
        self._columns_schema_preview_path = None
        self._columns_applied = False
        self._last_applied_columns = None
        self._cycle_mask = None
        self._cycle_pending_range = None
        self._cached_cycle_markers = None
        self._preloaded_cycle_markers = None
        self._markers_seeded_from_cache = False
        self.columns = {}
        settings["columns"] = {}
        settings["per_sheet_column_map"] = {}
        settings["plot_elements"] = {}
        settings["layout_profiles"] = {}
        # Clear workflow cycle caches so stale Analysis payloads cannot survive
        # workspace/profile resets and bypass context-match restore guards.
        self._sol_cycle_payloads = {}
        self._sol_cycle_results_map = {}
        self._analysis_result_context_fingerprint = None
        self._analysis_profile_restore_target_name = None
        analysis_payload_cache = getattr(self, "_analysis_runtime_payload_cache", None)
        if isinstance(analysis_payload_cache, OrderedDict):
            analysis_payload_cache.clear()
        analysis_timeline_cache = getattr(self, "_analysis_runtime_timeline_cache", None)
        if isinstance(analysis_timeline_cache, OrderedDict):
            analysis_timeline_cache.clear()
        final_report_rows_cache = getattr(self, "_final_report_rows_cache", None)
        if isinstance(final_report_rows_cache, OrderedDict):
            final_report_rows_cache.clear()
        final_report_page_cache = getattr(self, "_final_report_page_build_cache", None)
        if isinstance(final_report_page_cache, OrderedDict):
            final_report_page_cache.clear()
        compare_cache = getattr(self, "_compare_render_context_cache", None)
        if isinstance(compare_cache, OrderedDict):
            compare_cache.clear()
        ledger_cache = getattr(self, "_ledger_sort_filter_cache", None)
        if isinstance(ledger_cache, OrderedDict):
            ledger_cache.clear()
        self._sol_cycle_payload = None
        self._sol_cycle_results = None
        self._analysis_reference_trace = None
        self._analysis_overlay_marker = None
        self._analysis_measured_ph_anchor = None
        self._analysis_uptake_correction = None
        self._analysis_corrected_uptake_series = None
        self._analysis_completion_from_measured_ph = None
        self._analysis_latest_cycle_corrected_speciation = None
        self._plot_elements = {}
        self._per_sheet_column_map_cache = None
        self._invalidate_auto_title_datetime_cache()
        try:
            preview_after_id = getattr(self, "_auto_title_preview_after_id", None)
            if preview_after_id is not None:
                self.after_cancel(preview_after_id)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        self._auto_title_preview_after_id = None
        try:
            self.selected_sheet.set("")
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            self._set_selected_sheets([], persist=False)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            self._set_multi_sheet_enabled(False, persist=False)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        entry = getattr(self, "e_file", None)
        if entry is not None:
            try:
                entry.delete(0, tk.END)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        try:
            self._clear_plot_tabs()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            self._clear_numeric_cache()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            self._render_cache.clear_prepared()
            self._render_cache.clear_cycles()
            self._render_cache.clear_cycle_segments()
            self._render_cache.clear_cycle_metrics()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        self._invalidate_auto_title_datetime_cache()
        try:
            self.lbl_status.config(text="No file loaded.")
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            self._refresh_columns_ui()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _reset_workspace_to_startup_defaults(self) -> None:
        """Reset the workspace to startup-default state for New Profile.

        Purpose:
            Clear dataset-bound state and restore plot/cycle/report defaults.
        Why:
            New Profile must begin from a clean baseline identical to a fresh launch.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Clears datasets and caches, updates settings, refreshes UI state, and
            resets annotations and report configuration.
        Exceptions:
            Best-effort guards prevent UI reset failures from interrupting the flow.
        """
        self._clear_workspace_state()

        default_plot_settings = self._default_profile_plot_settings_payload()
        self._apply_profile_plot_settings(default_plot_settings)

        settings["final_report"] = copy.deepcopy(FINAL_REPORT_DEFAULT_STATE)
        try:
            self._apply_final_report_state_to_ui(settings["final_report"])
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            self._refresh_final_report_preview()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

        # Clear annotation UI state so new profiles do not inherit stale defaults.
        settings["annotations_ui"] = _normalize_annotations_ui({})
        settings["plot_elements"] = _normalize_plot_elements({})
        self._plot_elements = settings["plot_elements"]
        try:
            self._annotation_store = AnnotationStore(settings)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

        # Reset cycle marker undo stacks to match a fresh session.
        self._cycle_marker_undo_stack = []
        self._cycle_marker_redo_stack = []
        self._cycle_marker_undo_lock = False

    def _resolve_profile_dataset_path(self, path: Optional[str]) -> Optional[str]:
        """Resolve profile dataset path.
        Used to compute profile dataset path before rendering or export."""
        candidate = (path or "").strip()
        if candidate and os.path.exists(candidate):
            return candidate
        if candidate:
            messagebox.showwarning(
                "Relink Dataset",
                "The dataset path stored in this profile cannot be found.\n"
                "Select the dataset file to continue.",
            )
        else:
            messagebox.showinfo(
                "Relink Dataset",
                "This profile does not include a dataset path.\n"
                "Select the dataset file to continue.",
            )
        new_path = filedialog.askopenfilename(
            title="Select Dataset File",
            filetypes=[("Excel Files", "*.xlsx *.xls")],
        )
        if not new_path:
            return None
        return new_path

    def _autosave_last_workspace(self) -> None:
        """Perform autosave last workspace.
        Used to keep the workflow logic localized and testable."""
        profiles_dir = self._profile_storage_dir()
        if profiles_dir is None:
            return
        path = profiles_dir / "_autosave_last_workspace.json"
        doc = self._build_profile_document(include_dataset_path=True)
        doc["description"] = "Autosave before loading a profile."
        self._write_profile_document(path, doc, show_errors=False)

    def _apply_column_selection(self, *, auto_refresh_axes: bool = False) -> None:
        """Apply column selection.
        Used to apply column selection changes to live state."""
        self._apply_columns(auto_refresh_axes=auto_refresh_axes)

    def _abort_deferred_profile_restore(
        self,
        *,
        detail: str,
        status_text: str,
    ) -> bool:
        """Abort a pending deferred profile restore without showing data dialogs.

        Purpose:
            Clear deferred restore state when apply-column validation cannot run.
        Why:
            Startup autosave restore can otherwise leave `_profile_restore_pending`
            set after a missing-data validation return, causing startup polling to
            wait forever.
        Args:
            detail: Diagnostic text recorded for the restore-abort lifecycle.
            status_text: Short status-bar message for the user-facing UI.
        Returns:
            True when a pending deferred restore was cleared; otherwise False.
        Side Effects:
            Clears pending restore state, records an abort reason, updates status UI,
            resets apply-state flags, and may finish the profile-load splash.
        Exceptions:
            UI update failures are suppressed so restore cleanup can complete.
        """
        pending = getattr(self, "_profile_restore_pending", None)
        if not isinstance(pending, dict):
            return False

        self._profile_restore_pending = None
        self._profile_restore_abort_reason = str(detail or "").strip()
        self._is_applying_columns = False
        try:
            self.lbl_status.config(text=str(status_text or "").strip())
        except Exception:
            # Best-effort guard; cleanup must not depend on optional status widgets.
            pass
        try:
            self._finish_profile_load_splash(
                succeeded=False,
                detail=str(detail or "").strip() or "Profile restore aborted.",
            )
        except Exception:
            # Best-effort guard; startup autosave restores may not use this splash.
            pass
        return True

    def _finalize_profile_restore(self) -> None:
        """Finalize deferred profile-restore state after data/apply completion.

        Purpose:
            Apply deferred layout/plot/report state and persist restored settings.
        Why:
            Profile load can defer parts of restoration until column apply and
            data reload complete; this method closes that lifecycle deterministically.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Applies pending restore payload, refreshes axis ranges, saves settings,
            and may finalize the profile-load splash lifecycle.
        Exceptions:
            Uses best-effort guards so restore finalization does not crash the UI.
        """
        pending = getattr(self, "_profile_restore_pending", None)
        if not isinstance(pending, dict):
            self._profile_restore_pending = None
            self._maybe_finish_profile_load_splash(
                succeeded=True,
                detail="Profile restore completed.",
                force=True,
            )
            return
        self._update_operation_splash(
            message="Finalizing profile restore...",
            progress=92.0,
            stage_key="finalize",
            detail="Applying plot/layout/report state after data restore.",
        )
        self._profile_restore_pending = None
        self._apply_profile_layout_profiles(pending.get("layout_profiles") or {})
        self._apply_profile_plot_elements(pending.get("plot_elements") or {})
        self._apply_profile_final_report_state(
            pending.get("final_report_settings") or {}
        )
        try:
            self._refresh_axis_ranges()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            self.save_settings()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            _save_settings_to_disk()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        self._maybe_finish_profile_load_splash(
            succeeded=True,
            detail="Workspace restore completed.",
            force=True,
        )

    def _normalize_profile_restore_sheet_selection(
        self,
        state: dict[str, Any],
    ) -> bool:
        """Normalize stored profile sheet selection against loaded workbook sheets.

        Purpose:
            Repair or reject the sheet-selection portion of a profile restore.
        Why:
            Autosave payloads can contain multi-sheet mode with no included sheets;
            restoring that shape directly triggers a modal validation loop during
            startup. A valid single selected sheet is enough to recover safely.
        Args:
            state: Mutable deserialized profile state being restored.
        Returns:
            True when the state has a valid sheet restore target; otherwise False.
        Side Effects:
            May mutate `state` to remove invalid sheet names or switch an empty
            multi-sheet restore to single-sheet mode.
        Exceptions:
            None; invalid or unavailable workbook sheet state returns False.
        """
        sheet_names = [
            str(name or "").strip()
            for name in getattr(self, "sheet_names", [])
            if str(name or "").strip()
        ]
        available = set(sheet_names)
        if not available:
            state["selected_sheets"] = []
            return False

        selected_sheets: list[str] = []
        seen: set[str] = set()
        for raw_name in state.get("selected_sheets") or []:
            sheet_name = str(raw_name or "").strip()
            if sheet_name and sheet_name in available and sheet_name not in seen:
                selected_sheets.append(sheet_name)
                seen.add(sheet_name)

        selected_sheet = str(state.get("selected_sheet") or "").strip()
        selected_sheet_valid = bool(selected_sheet and selected_sheet in available)
        if bool(state.get("multi_sheet_enabled", False)):
            if selected_sheets:
                state["selected_sheets"] = selected_sheets
                if not selected_sheet_valid:
                    state["selected_sheet"] = selected_sheets[0]
                return True
            if selected_sheet_valid:
                # Repair malformed autosaves by restoring the valid single sheet.
                state["multi_sheet_enabled"] = False
                state["selected_sheets"] = []
                state["selected_sheet"] = selected_sheet
                return True
            state["selected_sheets"] = []
            return False

        state["selected_sheets"] = []
        if selected_sheet_valid:
            state["selected_sheet"] = selected_sheet
            return True
        if selected_sheet:
            return False
        state["selected_sheet"] = sheet_names[0]
        return True

    def _restore_workspace_from_profile(self, profile_doc: dict[str, Any]) -> bool:
        """Restore the workspace from a stored profile document.

        Purpose:
            Load a profile payload and rehydrate workspace state consistently.
        Why:
            Profiles are the persistence boundary for long-lived analysis sessions.
        Args:
            profile_doc: Profile document containing metadata and payload state.
        Returns:
            True when restore succeeds, otherwise False.
        Side Effects:
            Clears current workspace, updates settings/UI, and may prompt for data.
        Exceptions:
            Best-effort guards prevent restore failures from crashing the UI.
        """
        payload = profile_doc.get("payload")
        state = self._deserialize_workspace_state(payload or {})
        if not state:
            messagebox.showerror("Load Profile", "Profile payload is invalid.")
            return False
        self._profile_restore_abort_reason = ""
        self._update_operation_splash(
            message="Applying profile settings...",
            progress=20.0,
            stage_key="restore",
            detail="Restoring profile metadata and workspace configuration.",
        )
        dataset_required = bool(state.get("dataset_required", True))
        if dataset_required:
            dataset_path = self._resolve_profile_dataset_path(state.get("dataset_path"))
            if not dataset_path:
                return False
            state["dataset_path"] = dataset_path

        self._clear_workspace_state()
        self._apply_profile_identifiers(state.get("profile_identifiers"))
        self._apply_profile_plot_settings(state.get("plot_settings") or {})
        self._apply_profile_reaction_basis(state.get("reaction_basis") or {})
        self._apply_profile_reaction_dashboard_state(
            state.get("reaction_dashboard_state") or {}
        )
        self._apply_profile_cycle_markers(state.get("cycle_markers"))
        self._apply_profile_analysis_last_result(
            state.get(SOL_ANALYSIS_PROFILE_LAST_RESULT_PAYLOAD_KEY)
        )
        self._apply_profile_column_trace_legend_labels(
            state.get("column_trace_legend_labels")
        )

        if not dataset_required:
            self._profile_restore_pending = {
                "plot_elements": state.get("plot_elements") or {},
                "layout_profiles": state.get("layout_profiles") or {},
                "final_report_settings": state.get("final_report_settings") or {},
            }
            self._update_operation_splash(
                message="Finalizing profile restore...",
                progress=85.0,
                stage_key="finalize",
                detail="Applying non-dataset profile state.",
            )
            try:
                self._finalize_profile_restore()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return True

        self.file_path = dataset_path
        settings["last_file_path"] = self.file_path
        entry = getattr(self, "e_file", None)
        if entry is not None:
            try:
                entry.delete(0, tk.END)
                entry.insert(0, self.file_path)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        try:
            self._load_sheet_names()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

        if not self._normalize_profile_restore_sheet_selection(state):
            self._update_operation_splash(
                message="Profile restore skipped.",
                progress=100.0,
                stage_key="failed",
                detail="Stored sheet selection is not available in the workbook.",
            )
            try:
                self.lbl_status.config(
                    text="Profile restore skipped: stored sheet selection is invalid."
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return False

        multi_sheet = bool(state.get("multi_sheet_enabled", False))
        try:
            self._set_multi_sheet_enabled(multi_sheet, persist=False)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

        if multi_sheet:
            try:
                self._set_selected_sheets(
                    state.get("selected_sheets") or [], persist=False
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                self._refresh_multi_sheet_lists()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        else:
            selected_sheet = (state.get("selected_sheet") or "").strip()
            if selected_sheet and selected_sheet in self.sheet_names:
                self.selected_sheet.set(selected_sheet)
            elif self.sheet_names:
                self.selected_sheet.set(self.sheet_names[0])

        columns_map = state.get("column_assignments")
        if isinstance(columns_map, dict):
            self.columns = dict(columns_map)
            settings["columns"] = dict(columns_map)
        else:
            self.columns = dict(settings.get("columns", {}))

        per_sheet_map = state.get("per_sheet_mapping")
        if isinstance(per_sheet_map, dict):
            settings["per_sheet_column_map"] = copy.deepcopy(per_sheet_map)
        else:
            settings["per_sheet_column_map"] = {}
        self._per_sheet_column_map_cache = None

        if multi_sheet:
            try:
                self._refresh_columns_ui()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        else:
            try:
                self._load_dataframe()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

        try:
            self._mark_columns_dirty(reason="profile load", allow_during_apply=True)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

        self._profile_restore_pending = {
            "plot_elements": state.get("plot_elements") or {},
            "layout_profiles": state.get("layout_profiles") or {},
            "final_report_settings": state.get("final_report_settings") or {},
        }

        self._update_operation_splash(
            message="Applying column selection...",
            progress=72.0,
            stage_key="apply_columns",
            detail="Waiting for deferred restore completion.",
        )
        self._apply_column_selection(auto_refresh_axes=True)
        abort_reason = str(
            getattr(self, "_profile_restore_abort_reason", "") or ""
        ).strip()
        if abort_reason:
            self._profile_restore_abort_reason = ""
            return False
        return True

    def _open_plot_settings_dialog(self, plot_id: Optional[str] = None) -> None:
        """Open the plot settings dialog for the selected plot.

        Purpose:
            Present per-plot layout, spacing, and legend controls in a modal window.
        Why:
            Keeps advanced plot layout tuning scoped to a dedicated dialog without
            overcrowding the main Plot Settings tab.
        Args:
            plot_id: Optional plot identifier; defaults to the combined plot if omitted.
        Returns:
            None.
        Side Effects:
            Builds Tk dialog widgets, binds callbacks, stores staged margin and
            combined-control variable links, and may update staged values.
        Exceptions:
            Best-effort guards keep dialog creation resilient to UI errors.
        """
        plot_id = plot_id or "fig_combined_triple_axis"
        is_combined = plot_id == "fig_combined_triple_axis"
        is_core = plot_id in {"fig_pressure_temp", "fig_pressure_derivative"}
        is_timeline = plot_id == "fig_cycle_timeline"
        cycle_overlay = None
        try:
            cycle_overlay = self._core_cycle_overlay_state()
        except Exception:
            cycle_overlay = None
        cycle_legend_available = bool(self.show_cycle_legend_on_core.get()) and bool(
            cycle_overlay
        )
        existing = getattr(self, "_plot_settings_window", None)
        if existing is not None and existing.winfo_exists():
            if getattr(self, "_plot_settings_target_id", None) == plot_id:
                try:
                    existing.deiconify()
                    existing.lift()
                    existing.focus_force()
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
                return
            try:
                existing.destroy()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            self._plot_settings_window = None
            self._plot_settings_target_id = None
            self._plot_settings_apply_callback = None
            self._plot_settings_has_pending_changes_callback = None

        window = tk.Toplevel(self)
        plot_label_map = {
            "fig_pressure_temp": "Figure 1: Pressure + Temperature",
            "fig_pressure_derivative": "Figure 2: Pressure + Derivative",
            "fig_combined_triple_axis": "Combined Triple-Axis",
            "fig_cycle_analysis": "Figure 3: Cycle Analysis",
            "fig_cycle_timeline": "Cycle Timeline",
        }
        display_label = plot_label_map.get(plot_id, plot_id)
        window.title(f"Plot Settings - {display_label}")
        window.transient(self)
        window.geometry("576x990")
        window.resizable(True, True)
        self._plot_settings_window = window
        self._plot_settings_target_id = plot_id
        self._plot_settings_apply_callback = None
        self._plot_settings_has_pending_changes_callback = None

        window.grid_rowconfigure(0, weight=1)
        window.grid_columnconfigure(0, weight=1)

        outer = ttk.Frame(window)
        outer.grid(row=0, column=0, sticky="nsew")
        outer.grid_rowconfigure(0, weight=1)
        outer.grid_rowconfigure(1, weight=0)
        outer.grid_rowconfigure(2, weight=0)
        outer.grid_columnconfigure(0, weight=1)

        scroll_shell = ttk.Frame(outer)
        scroll_shell.grid(row=0, column=0, sticky="nsew")
        scroll_shell.grid_rowconfigure(0, weight=1)
        scroll_shell.grid_columnconfigure(0, weight=1)

        canvas = tk.Canvas(scroll_shell, borderwidth=0, highlightthickness=0)
        vscroll = _ui_scrollbar(scroll_shell, orient="vertical", command=canvas.yview)
        canvas.configure(yscrollcommand=vscroll.set)
        canvas.grid(row=0, column=0, sticky="nsew")
        vscroll.grid(row=0, column=1, sticky="ns")

        container = ttk.Frame(canvas, padding=12)
        container_id = canvas.create_window((0, 0), window=container, anchor="nw")
        container.grid_columnconfigure(0, weight=1)
        ttk.Separator(outer, orient="horizontal").grid(row=1, column=0, sticky="ew")
        footer = ttk.Frame(outer, padding=(12, 8, 12, 10))
        footer.grid(row=2, column=0, sticky="ew")
        footer.grid_columnconfigure(0, weight=1)

        # Closure captures _open_plot_settings_dialog state for callback wiring, kept nested to scope the handler, and invoked by bindings set in _open_plot_settings_dialog.
        def _refresh_scroll_region(_event=None):
            """Refresh scroll region.
            Used to sync scroll region with current settings."""
            try:
                canvas.configure(scrollregion=canvas.bbox("all"))
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

        # Closure captures _open_plot_settings_dialog local context to keep helper logic scoped and invoked directly within _open_plot_settings_dialog.
        def _expand_width(event):
            """Perform expand width.
            Used to keep the workflow logic localized and testable."""
            try:
                canvas.itemconfigure(container_id, width=event.width)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

        container.bind("<Configure>", _refresh_scroll_region)
        canvas.bind("<Configure>", _expand_width)

        # Closure captures _open_plot_settings_dialog local context to keep helper logic scoped and invoked directly within _open_plot_settings_dialog.
        def _bind_mousewheel(widget):
            """Perform bind mousewheel.
            Used to keep the workflow logic localized and testable."""

            # Closure captures _bind_mousewheel state for callback wiring, kept nested to scope the handler, and invoked by bindings set in _bind_mousewheel.
            def _on_mousewheel(event):
                """Handle mousewheel.
                Used as an event callback for mousewheel."""
                delta = event.delta
                if delta == 0:
                    return
                step = -1 if delta > 0 else 1
                if abs(delta) >= 120:
                    step = int(-delta / 120)
                canvas.yview_scroll(step, "units")
                return "break"

            widget.bind("<MouseWheel>", _on_mousewheel, add="+")
            widget.bind(
                "<Button-4>", lambda _event: canvas.yview_scroll(-1, "units"), add="+"
            )
            widget.bind(
                "<Button-5>", lambda _event: canvas.yview_scroll(1, "units"), add="+"
            )
            # Iterate over widget.winfo_children() to apply the per-item logic.
            for child in widget.winfo_children():
                _bind_mousewheel(child)

        self.after_idle(lambda: _bind_mousewheel(container))

