            if (not cycle_legend_available) or is_core:
                ref_axis_menu.configure(state="disabled")
            ref_axis_menu.grid(row=12, column=1, sticky="w", pady=2)

            ref_corner_var = stage_vars[f"{key_prefix}_cycle_legend_ref_corner"]
