    def _cache_cycle_markers(self, peaks, troughs, mask):
        """Cache cycle markers for the currently selected Primary Y trace.

        Purpose:
            Store reusable marker indices for the active dataset and reactor
            pressure trace.
        Why:
            Cycle Analysis can switch among multiple Primary Y traces, so cached
            markers must only be reused for the same selected trace.
        Inputs:
            peaks: Effective peak marker indices.
            troughs: Effective trough marker indices.
            mask: Active Cycle Analysis inclusion mask.
        Outputs:
            None.
        Side Effects:
            Updates `settings["cycle_cached_markers"]`, `_cached_cycle_markers`,
            and writes settings to disk.
        Exceptions:
            Invalid file/column state returns without caching; save failures are
            ignored to avoid interrupting the UI workflow.
        """
        if not self.file_path or not self.columns:
            return

        try:
            path = os.path.abspath(self.file_path)
        except Exception:
            path = str(self.file_path)

        try:
            data_len = len(globals().get("x") or [])
        except Exception:
            data_len = 0

        try:
            mask_true = int(np.count_nonzero(mask)) if mask is not None else None
        except Exception:
            mask_true = None

        active_y1 = self._active_cycle_primary_y_column()
        cache = {
            "file": path,
            "sheet": self.selected_sheet.get() or "",
            "sheets": list(self.selected_sheets) if self.multi_sheet_enabled else None,
            "multi_sheet": bool(self.multi_sheet_enabled),
            "columns": {
                "x": self.columns.get("x"),
                "y1": active_y1 or self.columns.get("y1"),
            },
            "calculation_trace": dict(settings.get("calculation_trace") or {}),
            "data_len": int(data_len),
            "mask_true": mask_true,
            "peaks": sorted(int(p) for p in peaks),
            "troughs": sorted(int(t) for t in troughs),
            "peak_params": {
                "prominence": float(self.pk_prominence.get()),
                "distance": int(self.pk_distance.get()),
                "width": int(self.pk_width.get()),
            },
            "min_cycle_drop": float(self.min_cycle_drop.get()),
            "timestamp": time.time(),
        }

        settings["cycle_cached_markers"] = cache
        self._cached_cycle_markers = cache
        try:
            _save_settings_to_disk()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

