    def _debug_series_flow(self, stage: str, message: str) -> None:
        """Emit series-flow debug output with one-shot guards.

        Purpose:
            Track column/series lifecycle events for debugging.
        Why:
            Provides lightweight tracing of apply/refresh flows.
        Args:
            stage: Stage identifier for the series workflow.
            message: Detail message for the current stage.
        Returns:
            None.
        Side Effects:
            Writes to the debug logger when ui.events is enabled.
        Exceptions:
            Best-effort guards suppress logging failures.
        """
        apply_id = getattr(self, "_series_flow_apply_id", 0)
        seen = getattr(self, "_series_flow_debug_seen", set())
        token = (apply_id, stage)
        if token in seen:
            return
        seen.add(token)
        self._series_flow_debug_seen = seen
        self._dbg(
            "ui.events",
            "SeriesFlow %s %s %s",
            apply_id,
            stage,
            message,
        )

    def _mark_columns_dirty(
        self, reason: str = "", *, allow_during_apply: bool = False
    ):
        """Perform mark columns dirty.
        Used to keep the workflow logic localized and testable."""

        current_selection = None
        if getattr(self, "columns_vars", None):
            try:
                current_selection = {
                    key: var.get() for key, var in self.columns_vars.items()
                }
            except Exception:
                current_selection = None

        reason_label = (reason or "").strip() or "unspecified"
        y1_before = "y1" in globals()

        if getattr(self, "_is_applying_columns", False) and not allow_during_apply:
            self._debug_series_flow(
                f"dirty:{reason_label}",
                f"skipped apply_in_progress y1_present={y1_before}->{y1_before}",
            )
            return

        if (
            self._columns_applied
            and current_selection is not None
            and current_selection == getattr(self, "_last_applied_columns", None)
        ):
            return

        self._columns_applied = False
        self._last_applied_columns = None
        self._cycle_mask = None
        self._cycle_pending_range = None

        self._update_apply_columns_indicator("pending")

        # Clear cached global series so stale data isn't reused

        # Iterate over ("x", "y1", "y2", "y3", "z", "z2", "cycle_temp_series") to apply the per-item logic.
        for key in ("x", "y1", "y2", "y3", "z", "z2", "cycle_temp_series"):

            try:

                globals().pop(key)

            except KeyError:

                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        y1_after = "y1" in globals()
        self._debug_series_flow(
            f"dirty:{reason_label}",
            f"applied y1_present={y1_before}->{y1_after}",
        )

        if getattr(self, "_cycle_tab_added", False):

            self._show_cycle_apply_prompt()

        try:
            self._mark_plot_data_dirty()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _bind_vdw_dirty_traces(self) -> None:
        """Perform bind VDW dirty traces.
        Used to keep the workflow logic localized and testable."""
        # Closure captures _bind_vdw_dirty_traces state for callback wiring, kept nested to scope the handler, and invoked by bindings set in _bind_vdw_dirty_traces.
        def _on_change(*_):
            """Handle change.
            Used as an event callback for change."""
            self._mark_vdw_dirty(reason="input change")

        tracked_vars = (
            self.v_volume,
            self.v_a,
            self.v_b,
            self.v_gas_molar_mass,
        )
        # Iterate over tracked_vars to apply the per-item logic.
        for var in tracked_vars:
            try:
                handle = var.trace_add("write", _on_change)
            except Exception:
                continue
            self._vdw_trace_ids.append((var, handle))

    def _mark_vdw_dirty(self, reason: str = "") -> None:
        """Perform mark VDW dirty.
        Used to keep the workflow logic localized and testable."""
        _ = reason  # reserved for future logging
        self._update_apply_vdw_indicator("pending")

    def _on_gas_selected(self, *_):
        """Handle gas selected.
        Used as an event callback for gas selected."""

        choice = self.v_gas.get()

        preset = GAS_PRESETS.get(choice)

        if preset:

            # Set a & b to the preset values (entries remain editable)

            self.v_a.set(preset["a"])

            self.v_b.set(preset["b"])

        override = self._gas_preset_overrides.get(choice) or {}
        molar = override.get("molar_mass")

        if molar is None and preset is not None:
            molar = preset.get("molar_mass")

        try:
            molar_val = float(molar)
        except (TypeError, ValueError):
            molar_val = None

        if molar_val is not None and math.isfinite(molar_val) and molar_val > 0.0:
            self.v_gas_molar_mass.set(molar_val)

    def _selected_reaction_catalog_entry(
        self, reaction_id: Optional[str] = None
    ) -> Dict[str, Any]:
        """Return the normalized catalog entry for the selected reaction.

        Purpose:
            Provide one shared accessor for the active reaction entry.
        Why:
            Plot Settings, Analysis yield math, and Final Report metadata all
            need the same selected reaction payload.
        Inputs:
            reaction_id: Optional explicit reaction identifier override.
        Outputs:
            Dict[str, Any]: Canonical reaction entry.
        Side Effects:
            None.
        Exceptions:
            Missing ids fall back to the default custom entry.
        """
        reaction_key = str(
            reaction_id
            or self.v_product_preset.get()
            or self._selected_reaction_id_var.get()
            or DEFAULT_SELECTED_REACTION_ID
        ).strip()
        catalog = getattr(self, "_reaction_catalog", {}) or {}
        return _normalize_reaction_catalog_entry(
            catalog.get(reaction_key), reaction_id=reaction_key
        )

    def _reaction_basis_for_selection(
        self,
        reaction_id: Optional[str] = None,
    ) -> Dict[str, Any]:
        """Return one canonical reaction basis for a selected catalog entry.

        Purpose:
            Merge the saved reaction catalog entry with the current live settings.
        Why:
            Plot Settings should reflect unsaved edits for the active reaction,
            while Final Report metadata may target a different saved reaction.
        Inputs:
            reaction_id: Optional explicit reaction identifier override.
        Outputs:
            Dict[str, Any]: Canonical normalized reaction-basis payload.
        Side Effects:
            None.
        Exceptions:
            Missing reaction ids fall back to the default custom entry.
        """
        live_basis = dict(_reaction_basis_from_settings(settings))
        selected_reaction_id = str(
            settings.get("selected_reaction_id", DEFAULT_SELECTED_REACTION_ID) or ""
        ).strip() or DEFAULT_SELECTED_REACTION_ID
        entry = self._selected_reaction_catalog_entry(reaction_id)
        entry_reaction_id = str(
            entry.get("reaction_id") or DEFAULT_SELECTED_REACTION_ID
        ).strip() or DEFAULT_SELECTED_REACTION_ID
        if entry_reaction_id == selected_reaction_id:
            live_basis["reaction_id"] = entry_reaction_id
            live_basis["reaction_label"] = str(
                entry.get("reaction_label") or live_basis.get("reaction_label") or "Custom"
            ).strip() or "Custom"
            return _normalize_reaction_basis_payload(live_basis)
        # Non-active selections should use the saved catalog chemistry while
        # keeping the current run basis such as starting mass and gas MW.
        live_basis.update(
            {
                "reaction_id": entry_reaction_id,
                "reaction_label": entry.get("reaction_label"),
                "starting_material_display_name": entry.get(
                    "starting_material_display_name"
                ),
                "starting_material_display_note": entry.get(
                    "starting_material_display_note"
                ),
                "starting_material_formula": entry.get("starting_material_formula"),
                "starting_material_mw_g_mol": entry.get("starting_material_mw_g_mol"),
                "gas_stoich_mol_per_mol_starting": entry.get(
                    "gas_stoich_mol_per_mol_starting"
                ),
                "stoich_mol_gas_per_mol_starting": entry.get(
                    "gas_stoich_mol_per_mol_starting"
                ),
                "final_product_name": entry.get("final_product_name"),
                "final_product_formula": entry.get("final_product_formula"),
                "final_product_mw_g_mol": entry.get("final_product_mw_g_mol"),
                "product_stoich_mol_per_mol_starting": entry.get(
                    "product_stoich_mol_per_mol_starting"
                ),
                "yield_mode": entry.get("yield_mode"),
            }
        )
        return _normalize_reaction_basis_payload(live_basis)

    def _reaction_summary_text(self, reaction_id: Optional[str] = None) -> str:
        """Build one compact summary string for a reaction selection.

        Purpose:
            Present the active final-product chemistry in a readable UI summary.
        Why:
            The new Final Product Settings tile and Final Report selector need
            one shared, high-signal explanation of the selected chemistry basis.
        Inputs:
            reaction_id: Optional explicit reaction identifier override.
        Outputs:
            str: Multi-line human-readable summary string.
        Side Effects:
            None.
        Exceptions:
            Missing numeric inputs render as `--`.
        """
        basis = self._reaction_basis_for_selection(reaction_id)
        reaction_label = str(basis.get("reaction_label") or "Custom").strip() or "Custom"
        start_name = (
            str(basis.get("starting_material_display_name") or "").strip() or "--"
        )
        final_name = str(basis.get("final_product_name") or "").strip() or "--"
        start_mass = _reaction_basis_float(basis.get("starting_mass_g"))
        start_mw = _reaction_basis_float(basis.get("starting_material_mw_g_mol"))
        gas_stoich = _reaction_basis_float(basis.get("gas_stoich_mol_per_mol_starting"))
        product_stoich = _reaction_basis_float(
            basis.get("product_stoich_mol_per_mol_starting")
        )
        product_mw = _reaction_basis_float(basis.get("final_product_mw_g_mol"))
        theoretical_yield = compute_theoretical_product_yield_g(basis)
        return (
            f"{reaction_label}\n"
            f"Starting material: {start_name} | Basis: "
            f"{'--' if start_mass is None else f'{start_mass:.3g} g'} at "
            f"{'--' if start_mw is None else f'{start_mw:.3g} g/mol'}\n"
            f"Final product: {final_name} | Product MW: "
            f"{'--' if product_mw is None else f'{product_mw:.3g} g/mol'}\n"
            f"Gas stoich: {'--' if gas_stoich is None else f'{gas_stoich:.3g}'} mol gas/mol starting | "
            f"Product stoich: {'--' if product_stoich is None else f'{product_stoich:.3g}'} mol product/mol starting | "
            f"Theoretical yield: {'--' if theoretical_yield is None else f'{theoretical_yield:.2f} g'}"
        )

    def _refresh_reaction_selection_summary(self) -> None:
        """Refresh human-readable summary text for the selected reaction.

        Purpose:
            Echo the selected reaction basis and final-product target in the UI.
        Why:
            The new Final Product Settings tile should explain the active yield
            basis without forcing users to inspect every numeric field.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Updates reaction-selection summary StringVars when available.
        Exceptions:
            Missing vars are ignored.
        """
        selected_summary = self._reaction_summary_text(
            settings.get("selected_reaction_id", DEFAULT_SELECTED_REACTION_ID)
        )
        final_report_reaction_id = str(
            getattr(
                self,
                "_final_report_reaction_var",
                tk.StringVar(
                    value=settings.get(
                        "final_report_selected_reaction_id",
                        settings.get("selected_reaction_id", DEFAULT_SELECTED_REACTION_ID),
                    )
                ),
            ).get()
            or DEFAULT_SELECTED_REACTION_ID
        ).strip()
        final_report_summary = self._reaction_summary_text(final_report_reaction_id)
        summaries = {
            "_selected_reaction_summary_var": selected_summary,
            "_final_report_reaction_summary_var": final_report_summary,
        }
        for attr_name, summary_text in summaries.items():
            var = getattr(self, attr_name, None)
            if isinstance(var, tk.StringVar):
                try:
                    var.set(summary_text)
                except Exception:
                    pass
        label_var = getattr(self, "_selected_reaction_label_var", None)
        if isinstance(label_var, tk.StringVar):
            try:
                label_var.set(
                    str(
                        self._reaction_basis_for_selection(
                            settings.get(
                                "selected_reaction_id", DEFAULT_SELECTED_REACTION_ID
                            )
                        ).get("reaction_label")
                        or "Custom"
                    ).strip()
                    or "Custom"
                )
            except Exception:
                pass

    def _refresh_reaction_preset_choices(self) -> None:
        """Refresh reaction dropdown widgets from the persisted catalog.

        Purpose:
            Keep Plot Settings and Final Report selectors synchronized with the
            saved reaction catalog.
        Why:
            Users can now add/update reaction entries at runtime.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Updates combobox values and reaction summary strings.
        Exceptions:
            Missing widgets are ignored.
        """
        self._reaction_catalog = _normalize_reaction_catalog(
            settings.get(REACTION_CATALOG_SETTINGS_KEY)
        )
        settings[REACTION_CATALOG_SETTINGS_KEY] = self._reaction_catalog
        values = list(self._reaction_catalog.keys())
        for attr_name in ("_reaction_preset_combo", "_final_report_reaction_combo"):
            combo = getattr(self, attr_name, None)
            if combo is None:
                continue
            try:
                combo.configure(values=values)
            except Exception:
                pass
        if settings.get("selected_reaction_id") not in self._reaction_catalog:
            settings["selected_reaction_id"] = DEFAULT_SELECTED_REACTION_ID
        final_report_selected = settings.get(
            "final_report_selected_reaction_id",
            settings.get("selected_reaction_id", DEFAULT_SELECTED_REACTION_ID),
        )
        if final_report_selected not in self._reaction_catalog:
            final_report_selected = settings.get(
                "selected_reaction_id", DEFAULT_SELECTED_REACTION_ID
            )
            settings["final_report_selected_reaction_id"] = final_report_selected
        selected_var = getattr(self, "v_product_preset", None)
        if isinstance(selected_var, tk.Variable):
            try:
                selected_var.set(settings["selected_reaction_id"])
            except Exception:
                pass
        final_report_var = getattr(self, "_final_report_reaction_var", None)
        if isinstance(final_report_var, tk.Variable):
            try:
                final_report_var.set(final_report_selected)
            except Exception:
                pass
        self._refresh_reaction_selection_summary()

    def _apply_reaction_entry_to_runtime(
        self,
        reaction_id: str,
        *,
        preserve_starting_mass: bool = True,
    ) -> None:
        """Apply one reaction catalog entry into Tk vars, settings, and globals.

        Purpose:
            Synchronize the selected reaction into the live runtime state.
        Why:
            Yield math and Final Report metadata now depend on a shared reaction
            basis that must update immediately when a selection changes.
        Inputs:
            reaction_id: Selected reaction identifier.
            preserve_starting_mass: True to retain the user's existing starting
                mass instead of replacing it with the catalog default.
        Outputs:
            None.
        Side Effects:
            Updates Tk vars, settings, and downstream reaction summary state.
        Exceptions:
            Missing reaction ids fall back to the default custom entry.
        """
        entry = self._selected_reaction_catalog_entry(reaction_id)
        settings["selected_reaction_id"] = entry.get("reaction_id", DEFAULT_SELECTED_REACTION_ID)
        self._selected_reaction_id_var.set(settings["selected_reaction_id"])
        self.v_product_preset.set(settings["selected_reaction_id"])
        self.v_product_name.set(
            str(entry.get("starting_material_display_name") or "").strip()
        )
        self.v_starting_material_display_name.set(
            str(entry.get("starting_material_display_name") or "").strip()
        )
        self.v_starting_material_display_note.set(
            str(entry.get("starting_material_display_note") or "").strip()
        )
        try:
            self.v_product_molar_mass.set(
                float(entry.get("starting_material_mw_g_mol") or 0.0)
            )
        except Exception:
            pass
        if not preserve_starting_mass:
            try:
                self.v_starting_mass.set(float(entry.get("starting_mass_g") or 0.0))
            except Exception:
                pass
        try:
            self.v_starting_stoich.set(
                float(entry.get("gas_stoich_mol_per_mol_starting") or 0.0)
            )
        except Exception:
            pass
        try:
            self.v_gas_stoich.set(
                float(entry.get("gas_stoich_mol_per_mol_starting") or 0.0)
            )
        except Exception:
            pass
        try:
            self.v_final_product_molar_mass.set(
                float(entry.get("final_product_mw_g_mol") or 0.0)
            )
        except Exception:
            pass
        self.v_final_product_name.set(str(entry.get("final_product_name") or "").strip())
        self.v_final_product_formula.set(
            str(entry.get("final_product_formula") or "").strip()
        )
        try:
            self.v_product_stoich.set(
                float(entry.get("product_stoich_mol_per_mol_starting") or 0.0)
            )
        except Exception:
            pass
        self.v_yield_mode.set(
            str(entry.get("yield_mode") or REACTION_YIELD_MODE_PRODUCT)
        )
        settings["starting_material_preset"] = settings["selected_reaction_id"]
        settings["starting_material_formula"] = str(
            entry.get("starting_material_formula") or ""
        ).strip()
        settings["starting_material_name"] = str(
            entry.get("starting_material_display_name") or ""
        ).strip()
        settings["starting_material_display_name"] = self.v_starting_material_display_name.get().strip()
        settings["starting_material_display_note"] = self.v_starting_material_display_note.get().strip()
        settings["starting_material_mw_g_mol"] = self.v_product_molar_mass.get()
        settings["stoich_mol_gas_per_mol_starting"] = self.v_starting_stoich.get()
        settings["gas_stoich_mol_per_mol_starting"] = self.v_gas_stoich.get()
        settings["final_product_name"] = self.v_final_product_name.get().strip()
        settings["final_product_formula"] = self.v_final_product_formula.get().strip()
        settings["final_product_mw_g_mol"] = self.v_final_product_molar_mass.get()
        settings["product_stoich_mol_per_mol_starting"] = self.v_product_stoich.get()
        settings["yield_mode"] = self.v_yield_mode.get()
        if settings.get("final_report_selected_reaction_id") not in self._reaction_catalog:
            settings["final_report_selected_reaction_id"] = settings["selected_reaction_id"]
        self._refresh_reaction_selection_summary()

    def _save_current_reaction_catalog_entry(self, *, update_existing: bool) -> None:
        """Save current Final Product Settings fields into the reaction catalog.

        Purpose:
            Let users create or update reusable reaction entries from the current
            Plot Settings values.
        Why:
            v4.7.7 requires a persistent reaction dropdown that users can extend.
        Inputs:
            update_existing: True to update the selected custom entry; False to
                create a new custom catalog entry.
        Outputs:
            None.
        Side Effects:
            Prompts for confirmation/label, persists settings, refreshes dropdowns,
            and selects the saved entry.
        Exceptions:
            Best-effort dialogs are used for invalid or blocked operations.
        """
        selected_id = str(self.v_product_preset.get() or DEFAULT_SELECTED_REACTION_ID).strip()
        selected_entry = self._selected_reaction_catalog_entry(selected_id)
        if update_existing and bool(selected_entry.get("builtin")):
            try:
                messagebox.showinfo(
                    "Final Product Settings",
                    "Built-in reactions cannot be edited. Use 'Save As Reaction' to create a custom copy.",
                )
            except Exception:
                pass
            return
        default_label = str(selected_entry.get("reaction_label") or "").strip()
        prompt_title = "Update Reaction" if update_existing else "Save Reaction"
        prompt_text = (
            "Update the saved reaction label:"
            if update_existing
            else "Enter a label for the saved reaction:"
        )
        try:
            label = simpledialog.askstring(
                prompt_title,
                prompt_text,
                initialvalue=default_label or self._selected_reaction_label_var.get(),
                parent=self,
            )
        except Exception:
            label = None
        if label is None:
            return
        label = str(label or "").strip()
        if not label:
            try:
                messagebox.showwarning(
                    "Final Product Settings",
                    "Reaction label cannot be empty.",
                )
            except Exception:
                pass
            return
        reaction_id = selected_id
        if not update_existing:
            reaction_id = re.sub(r"[^a-z0-9]+", "_", label.lower()).strip("_")
            if not reaction_id:
                reaction_id = f"reaction_{int(time.time())}"
            base_id = reaction_id
            suffix = 2
            while reaction_id in self._reaction_catalog:
                reaction_id = f"{base_id}_{suffix}"
                suffix += 1
        entry = self._selected_reaction_catalog_entry(selected_id)
        entry.update(
            {
                "reaction_id": reaction_id,
                "reaction_label": label,
                "starting_material_display_name": self.v_starting_material_display_name.get().strip(),
                "starting_material_display_note": self.v_starting_material_display_note.get().strip(),
                "starting_material_formula": str(settings.get("starting_material_formula") or "").strip(),
                "starting_material_mw_g_mol": self.v_product_molar_mass.get(),
                "starting_mass_g": self.v_starting_mass.get(),
                "gas_molar_mass": self.v_gas_molar_mass.get(),
                "gas_stoich_mol_per_mol_starting": self.v_gas_stoich.get(),
                "final_product_name": self.v_final_product_name.get().strip(),
                "final_product_formula": self.v_final_product_formula.get().strip(),
                "final_product_mw_g_mol": self.v_final_product_molar_mass.get(),
                "product_stoich_mol_per_mol_starting": self.v_product_stoich.get(),
                "yield_mode": self.v_yield_mode.get(),
                "builtin": False,
            }
        )
        self._reaction_catalog[reaction_id] = _normalize_reaction_catalog_entry(
            entry, reaction_id=reaction_id
        )
        settings[REACTION_CATALOG_SETTINGS_KEY] = self._reaction_catalog
        settings["selected_reaction_id"] = reaction_id
        settings["starting_material_preset"] = reaction_id
        self.v_product_preset.set(reaction_id)
        self._refresh_reaction_preset_choices()
        try:
            _save_settings_to_disk()
        except Exception:
            pass
        self._apply_reaction_entry_to_runtime(reaction_id, preserve_starting_mass=True)

    def _on_product_selected(self, *_):
        """Handle product selected.
        Used as an event callback for product selected."""

        self._apply_reaction_entry_to_runtime(
            self.v_product_preset.get(), preserve_starting_mass=True
        )

        # update globals so subsequent analyses pick up the new values

        self._prepare_series_globals()

    def _apply_auto_state(self, auto_var, entries):
        """Apply auto state.
        Used to apply auto state changes to live state."""

        state = "disabled" if auto_var.get() else "normal"

        # Iterate over entries to apply the per-item logic.
        for e in entries:

            e.configure(state=state)

    def _wire_auto_to_entries(self, auto_var, entries):
        """Perform wire auto to entries.
        Used to keep the workflow logic localized and testable."""

        # call once now + whenever the checkbox flips

        # Closure captures _wire_auto_to_entries state for callback wiring, kept nested to scope the handler, and invoked by bindings set in _wire_auto_to_entries.
        def _on_change(*_):
            """Handle change.
            Used as an event callback for change."""

            self._apply_auto_state(auto_var, entries)

        auto_var.trace_add("write", _on_change)

    def _attach_tooltip(self, widget, text: str, delay_ms: int = 400):
        """Perform attach tooltip.
        Used to keep the workflow logic localized and testable."""

        tip_win = {"win": None}

        after_id = {"id": None}

        # Closure captures _attach_tooltip local context to keep helper logic scoped and invoked directly within _attach_tooltip.
        def show_tooltip():
            """Perform show tooltip.
            Used to keep the workflow logic localized and testable."""

            if tip_win["win"] or not widget.winfo_viewable():

                return

            x, y, cx, cy = (
                widget.bbox("insert")
                if widget.winfo_class() in ("Entry", "Text")
                else (0, 0, 0, 0)
            )

            x += widget.winfo_rootx() + 20

            y += widget.winfo_rooty() + 20

            tw = tk.Toplevel(widget)

            tw.wm_overrideredirect(True)

            tw.wm_geometry(f"+{x}+{y}")

            frm = ttk.Frame(tw, relief="solid", borderwidth=1)

            frm.pack(ipadx=6, ipady=4)

            lbl = ttk.Label(frm, text=text, justify="left", wraplength=360)

            lbl.pack()

            tip_win["win"] = tw

        # Closure captures _attach_tooltip local context to keep helper logic scoped and invoked directly within _attach_tooltip.
        def schedule_show(_e=None):
            """Schedule show.
            Used to queue show without blocking the UI."""

            cancel_show()

            after_id["id"] = widget.after(delay_ms, show_tooltip)

        # Closure captures _attach_tooltip state for callback wiring, kept nested to scope the handler, and invoked by bindings set in _attach_tooltip.
        def cancel_show(_e=None):
            """Perform cancel show.
            Used to keep the workflow logic localized and testable."""

            if after_id["id"]:
                widget.after_cancel(after_id["id"])

                after_id["id"] = None

            hide_tooltip()

        # Closure captures _attach_tooltip local context to keep helper logic scoped and invoked directly within _attach_tooltip.
        def hide_tooltip(_e=None):
            """Perform hide tooltip.
            Used to keep the workflow logic localized and testable."""

            if tip_win["win"] is not None:
                try:
                    tip_win["win"].destroy()

                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass

                tip_win["win"] = None

        widget.bind("<Enter>", schedule_show)

        widget.bind("<Leave>", cancel_show)

        widget.bind("<Motion>", schedule_show)

    def _clear_numeric_cache(self):
        """Clear cached numeric series values under a cache lock.

        Purpose:
            Reset memoized numeric series conversions.
        Why:
            Column remaps and data-source changes must invalidate old numeric
            conversions so downstream render/cycle paths do not reuse stale data.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Empties `self._numeric_cache`.
        Exceptions:
            Best-effort guards suppress lock/read failures.
        """
        lock = getattr(self, "_numeric_cache_lock", None)
        if lock is None:
            self._numeric_cache.clear()
            return
        try:
            with lock:
                self._numeric_cache.clear()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            self._numeric_cache.clear()

    def _register_var_default(self, var, default):
        """Return default value.
        Used by register var workflows to return value."""
        self._var_defaults[id(var)] = default

    def _default_value_from_var(
        self, var: tk.Variable | None, fallback: Any = None
    ) -> Any:
        """Return a stored default value for a Tk variable.

        Purpose:
            Resolve the startup default for a Tk variable when resetting state.
        Why:
            New Profile resets must use the original defaults, not the current values.
        Args:
            var: Tk variable to resolve.
            fallback: Value to use when no default is available.
        Returns:
            The stored default value or the fallback when unavailable.
        Side Effects:
            None.
        Exceptions:
            Returns the fallback when the variable cannot be read safely.
        """
        if var is None:
            return copy.deepcopy(fallback)
        var_id = id(var)
        if var_id in self._var_defaults:
            return copy.deepcopy(self._var_defaults[var_id])
        try:
            return copy.deepcopy(var.get())
        except Exception:
            # Best-effort guard; fall back to provided default.
            return copy.deepcopy(fallback)

    def _safe_get_var(self, var, cast=float):
        """Return var.
        Used by safe workflows to return var."""
        var_id = id(var)
        default = self._var_defaults.get(var_id)
        try:
            value = var.get()
        except tk.TclError:
            if default is None:
                raise
            var.set(default)
            return cast(default)

        try:
            casted = cast(value)
        except (TypeError, ValueError):
            if default is None:
                raise
            var.set(default)
            return cast(default)

        self._var_defaults[var_id] = casted
        return casted

    def _get_numeric_series(self, colname, *, dropna=False):
        """Return one numeric series with thread-safe shared-cache semantics.

        Purpose:
            Convert one dataframe column to numeric dtype and memoize the result.
        Why:
            Render and analysis workers repeatedly request the same numeric
            series; shared caching avoids redundant `pd.to_numeric` conversions.
            Cache access must be lock-protected for free-threaded runtimes.
        Inputs:
            colname: DataFrame column name to convert.
            dropna: When True, returns the dropna-filtered cached base series.
        Outputs:
            Optional pandas Series containing numeric values.
        Side Effects:
            Reads/writes `self._numeric_cache`.
        Exceptions:
            Conversion failures return None and are cached as None.
        """

        if self.df is None or not colname or colname == "None":
            return None

        key = (colname, bool(dropna))
        lock = getattr(self, "_numeric_cache_lock", None)

        if lock is not None:
            try:
                with lock:
                    if key in self._numeric_cache:
                        return self._numeric_cache[key]
            except Exception:
                # Best-effort guard; fall through to compute path.
                pass
        elif key in self._numeric_cache:
            return self._numeric_cache[key]

        if dropna:
            base = self._get_numeric_series(colname, dropna=False)

            if base is None:
                result = None

            else:
                cleaned = base.dropna()

                result = None if cleaned.empty else cleaned

        else:
            try:
                result = pd.to_numeric(self.df[colname], errors="coerce")

            except Exception:
                result = None

        if lock is not None:
            try:
                with lock:
                    sentinel = object()
                    existing = self._numeric_cache.get(key, sentinel)
                    if existing is not sentinel:
                        return existing
                    self._numeric_cache[key] = result
            except Exception:
                # Best-effort guard; fallback to unlocked assignment.
                self._numeric_cache[key] = result
        else:
            self._numeric_cache[key] = result

        return result

    def _get_title_type_choices(self) -> List[str]:
        """Return title type choices.
        Used to retrieve title type choices for downstream logic."""
        types = _normalize_title_type_list(settings.get("title_data_types"))
        settings["title_data_types"] = list(types)
        return types

    def _resolve_title_type_selection(self) -> str:
        """Resolve title type selection.
        Used to compute title type selection before rendering or export."""
        types = self._get_title_type_choices()
        selected = str(self.title_data_type_var.get() or "").strip()
        matched = None
        if selected:
            # Iterate over types to apply the per-item logic.
            for entry in types:
                if entry.casefold() == selected.casefold():
                    matched = entry
                    break
        if matched is None:
            matched = types[0]
        if matched != self.title_data_type_var.get():
            try:
                self.title_data_type_var.set(matched)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        settings["title_selected_type"] = matched
        return matched

    def _format_mmdd(self, dt_value: Any) -> str:
        """Format mmdd.
        Used to prepare mmdd for display or export."""
        try:
            return f"{dt_value.month}/{dt_value.day}"
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            return ""

    def _safe_format_template(
        self, template: str, tokens: Dict[str, Any]
    ) -> Tuple[bool, str]:
        """Format template.
        Used by safe workflows to format template."""
        try:
            return True, template.format(**tokens)
        except Exception as exc:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            return False, str(exc)

