    def _set_reaction_advanced_editor_visible(self, visible: bool) -> None:
        """Apply Advanced Template Editor visibility state.

        Purpose:
            Collapse or expand the template/species/step editor inside the
            redesigned Reaction Dashboard.
        Why:
            The operational dashboard should remain visually focused while still
            retaining access to custom template editing.
        Args:
            visible: True to show the editor body, False to hide it.
        Returns:
            None.
        Side Effects:
            Grids or removes the editor body and updates the toggle button text.
        Exceptions:
            Missing widgets are tolerated during startup and test harnesses.
        """
        self._reaction_advanced_editor_visible = bool(visible)
        body = getattr(self, "_reaction_advanced_editor_body", None)
        button = getattr(self, "_reaction_advanced_editor_button", None)
        if body is not None:
            try:
                if visible:
                    body.grid()
                else:
                    body.grid_remove()
            except Exception:
                pass
        if button is not None:
            try:
                button.configure(
                    text=(
                        "Hide Reaction Definition Manager"
                        if visible
                        else "Show Reaction Definition Manager"
                    )
                )
            except Exception:
                pass

    def _toggle_reaction_advanced_editor(self) -> None:
        """Toggle the Advanced Template Editor panel.

        Purpose:
            Provide the button callback for showing or hiding template editing.
        Why:
            Users should be able to access custom chemistry editing without making
            the dashboard’s main status workflow visually noisy.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Updates Advanced Template Editor visibility state.
        Exceptions:
            None.
        """
        self._set_reaction_advanced_editor_visible(
            not bool(getattr(self, "_reaction_advanced_editor_visible", False))
        )

    def _selected_reaction_cycle_focus_id(self) -> Optional[float]:
        """Return the selected Reaction Dashboard cycle focus id.

        Purpose:
            Normalize the visual dashboard cycle selector.
        Why:
            The dashboard defaults to latest while allowing cycle-specific
            inspection when imported Cycle Analysis rows are available.
        Args:
            None.
        Returns:
            Selected cycle id as float, or None for Latest/unavailable.
        Side Effects:
            None.
        Exceptions:
            Invalid selector text returns None.
        """
        try:
            label = str(self._reaction_cycle_focus_var.get() or "").strip()
        except Exception:
            return None
        if not label or label.lower() == "latest":
            return None
        match = re.search(r"[-+]?\d+(?:\.\d+)?", label)
        if not match:
            return None
        return _safe_float(match.group(0))

    def _on_reaction_cycle_focus_selected(self, _event: Any = None) -> None:
        """Refresh visual dashboard state after cycle-focus selection.

        Purpose:
            Re-render KPI, chart, and table highlights for the selected cycle.
        Why:
            Latest-plus-selector behavior should let operators inspect any
            imported cycle without rerunning the core calculation.
        Args:
            _event: Optional Tk combobox event.
        Returns:
            None.
        Side Effects:
            Updates visual dashboard widgets from the cached result.
        Exceptions:
            Missing cached results are ignored.
        """
        result = getattr(self, "_reaction_dashboard_last_result", None)
        if isinstance(result, Mapping):
            self._render_reaction_dashboard_result(result)

    def _refresh_reaction_cycle_selector(
        self, summary: Optional[Mapping[str, Any]] = None
    ) -> None:
        """Refresh cycle-focus selector values from the visual summary.

        Purpose:
            Populate the latest-plus-selector combobox after dashboard runs.
        Why:
            Imported Cycle Analysis rows should be directly selectable for
            cycle-specific dashboard inspection.
        Args:
            summary: Optional visual summary carrying `cycle_rows`.
        Returns:
            None.
        Side Effects:
            Updates combobox values and repairs invalid current selections.
        Exceptions:
            Missing combobox widgets are ignored.
        """
        combo = getattr(self, "_reaction_cycle_combo", None)
        if combo is None:
            return
        rows = (
            list(summary.get("cycle_rows") or [])
            if isinstance(summary, Mapping)
            else []
        )
        values = ["Latest"] + [
            f"Cycle {row.get('cycle_id')}"
            for row in rows
            if str(row.get("cycle_id") or "").strip()
        ]
        current = str(self._reaction_cycle_focus_var.get() or "Latest").strip()
        if current not in values:
            current = "Latest"
            self._reaction_cycle_focus_var.set(current)
        try:
            combo.configure(values=values)
        except Exception:
            pass

    def _draw_reaction_completion_gauge(
        self,
        completion_pct: Optional[float],
        *,
        status: str,
    ) -> None:
        """Draw the Reaction Dashboard completion gauge.

        Purpose:
            Render a compact visual completion indicator inside the dashboard.
        Why:
            Operators need a color-coded signal for reaction progress without
            opening the generated Matplotlib plot tab.
        Args:
            completion_pct: Completion percentage, or None when unavailable.
            status: Semantic status bucket controlling gauge color.
        Returns:
            None.
        Side Effects:
            Clears and redraws the completion canvas.
        Exceptions:
            Missing canvas/widgets are tolerated.
        """
        canvas = getattr(self, "_reaction_completion_canvas", None)
        if canvas is None:
            return
        try:
            canvas.delete("all")
            width = int(canvas.cget("width"))
            height = int(canvas.cget("height"))
        except Exception:
            return
        color = REACTION_DASHBOARD_STATUS_COLORS.get(
            status, REACTION_DASHBOARD_STATUS_COLORS["unavailable"]
        )
        x0, y0 = 24, 22
        x1, y1 = max(110, width - 24), max(100, height * 2 - 10)
        canvas.create_text(
            12,
            10,
            anchor="w",
            text="Completion",
            fill="#455a64",
            font=("TkDefaultFont", 9, "bold"),
        )
        canvas.create_arc(
            x0,
            y0,
            x1,
            y1,
            start=180,
            extent=-180,
            style="arc",
            width=12,
            outline="#d9d9d9",
        )
        value = _safe_float(completion_pct)
        if value is None or not math.isfinite(value):
            canvas.create_text(width / 2.0, height - 34, text="--", fill="#7f8c8d")
            return
        clamped = max(0.0, min(float(value), 100.0))
        canvas.create_arc(
            x0,
            y0,
            x1,
            y1,
            start=180,
            extent=-180.0 * (clamped / 100.0),
            style="arc",
            width=12,
            outline=color,
        )
        canvas.create_text(
            width / 2.0,
            height - 36,
            text=f"{clamped:.1f}%",
            fill=color,
            font=("TkDefaultFont", 13, "bold"),
        )

    def _draw_reaction_series_chart(
        self,
        canvas: Optional[tk.Canvas],
        rows: Sequence[Mapping[str, Any]],
        *,
        y_key: str,
        title: str,
        color: str,
    ) -> None:
        """Draw one compact Reaction Dashboard series chart.

        Purpose:
            Render cumulative gas/product or per-cycle delta trends using Tk
            canvas primitives.
        Why:
            The tab needs lightweight visual feedback without forcing users into
            a separate generated plot.
        Args:
            canvas: Target Tk canvas.
            rows: Ordered visual summary cycle rows.
            y_key: Row key to plot.
            title: Chart title text.
            color: Line/bar color.
        Returns:
            None.
        Side Effects:
            Clears and redraws the target canvas.
        Exceptions:
            Missing/invalid values draw an unavailable message instead of raising.
        """
        if canvas is None:
            return
        try:
            canvas.delete("all")
            width = int(canvas.cget("width"))
            height = int(canvas.cget("height"))
        except Exception:
            return
        canvas.create_text(
            12,
            10,
            anchor="w",
            text=title,
            fill="#455a64",
            font=("TkDefaultFont", 9, "bold"),
        )
        values = [
            _safe_float(row.get(y_key))
            for row in rows
            if isinstance(row, Mapping) and _safe_float(row.get(y_key)) is not None
        ]
        if len(values) < 2:
            canvas.create_text(
                width / 2.0,
                height / 2.0,
                text="Cycle data unavailable",
                fill="#7f8c8d",
            )
            return
        left, right = 28, max(60, width - 12)
        top, bottom = 28, max(60, height - 24)
        y_min = min(values)
        y_max = max(values)
        if abs(y_max - y_min) < 1e-12:
            y_min -= 0.5
            y_max += 0.5
        canvas.create_rectangle(left, top, right, bottom, outline="#cfd8dc")
        points: List[float] = []
        for index, value in enumerate(values):
            x_pos = left + (index / max(1, len(values) - 1)) * (right - left)
            y_pos = bottom - ((float(value) - y_min) / (y_max - y_min)) * (bottom - top)
            points.extend((x_pos, y_pos))
        if len(points) >= 4:
            canvas.create_line(*points, fill=color, width=2)
        for idx in range(0, len(points), 2):
            canvas.create_oval(
                points[idx] - 2.5,
                points[idx + 1] - 2.5,
                points[idx] + 2.5,
                points[idx + 1] + 2.5,
                fill=color,
                outline=color,
            )
        canvas.create_text(
            right,
            bottom + 10,
            anchor="e",
            text=f"Last: {values[-1]:.4g}",
            fill="#455a64",
            font=("TkDefaultFont", 8),
        )

    def _refresh_reaction_equation_widget(self, template: ReactionTemplate) -> None:
        """Render the active template equation with clickable species tokens.

        Purpose:
            Replace the old static equation text with a navigable reaction map.
        Why:
            Operators should be able to click a reactant/product and jump to the
            inputs that control that species instead of hunting through the form.
        Args:
            template: Active Reaction Dashboard template.
        Returns:
            None.
        Side Effects:
            Rewrites the equation Text widget, binds species tags, and updates the
            equation StringVar fallback used by tests and non-widget paths.
        Exceptions:
            Missing widgets are ignored so template loading remains robust.
        """
        lines = _reaction_template_equation_lines(template)
        self._reaction_equation_var.set("\n".join(lines))
        text_widget = getattr(self, "_reaction_equation_text", None)
        if text_widget is None:
            return
        try:
            text_widget.configure(state="normal")
            text_widget.delete("1.0", "end")
            text_widget.insert("1.0", "\n".join(lines))
            for tag in tuple(text_widget.tag_names()):
                if str(tag).startswith("species_"):
                    text_widget.tag_delete(tag)
            text_widget.tag_configure(
                "reaction_species_link",
                underline=True,
                foreground="#1b5e8f",
            )
            for species in template.species:
                species_text = _reaction_formula_display_text(species.formula)
                if not species_text:
                    continue
                tag_name = f"species_{species.species_id}"
                start = "1.0"
                while True:
                    pos = text_widget.search(species_text, start, stopindex="end")
                    if not pos:
                        break
                    end = f"{pos}+{len(species_text)}c"
                    text_widget.tag_add("reaction_species_link", pos, end)
                    text_widget.tag_add(tag_name, pos, end)
                    start = end
                text_widget.tag_bind(
                    tag_name,
                    "<Button-1>",
                    lambda _event, species_id=species.species_id: (
                        self._reaction_dashboard_focus_species(species_id)
                    ),
                )
                text_widget.tag_bind(
                    tag_name,
                    "<Enter>",
                    lambda _event: text_widget.configure(cursor="hand2"),
                )
                text_widget.tag_bind(
                    tag_name,
                    "<Leave>",
                    lambda _event: text_widget.configure(cursor="arrow"),
                )
            text_widget.configure(state="disabled")
        except Exception:
            try:
                text_widget.configure(state="disabled")
            except Exception:
                pass

    def _bind_reaction_dashboard_mousewheel_recursive(self, widget: Any) -> None:
        """Bind Reaction Dashboard descendants to the shared wheel dispatcher.

        Purpose:
            Allow mouse-wheel scrolling anywhere in the long Reaction Dashboard
            form, including over nested Text and Treeview controls.
        Why:
            Operators should not need to place the pointer over the narrow
            scrollbar, and rebuilt dashboard contents must not accumulate
            duplicate wheel bindings.
        Args:
            widget: Root widget whose descendants should receive wheel bindings.
        Returns:
            None.
        Side Effects:
            Adds Tk wheel-event bindings to unbound widgets and records widget
            identities in `_reaction_dashboard_mousewheel_bound`.
        Exceptions:
            Widget inspection/binding failures are ignored so tab construction
            remains best-effort.
        """
        if widget is None:
            return
        bound_ids = getattr(self, "_reaction_dashboard_mousewheel_bound", set())
        widget_id = str(widget)

        def _scroll_canvas(event: Any) -> Optional[str]:
            """Dispatch one dashboard wheel event through local-owner handoff."""
            return self._dispatch_canvas_mousewheel_with_handoff(
                event,
                canvas=getattr(self, "_reaction_dashboard_canvas", None),
                accumulator_attr="_reaction_dashboard_scroll_wheel_remainder",
            )

        try:
            if widget_id not in bound_ids:
                widget.bind("<MouseWheel>", _scroll_canvas, add="+")
                widget.bind("<Button-4>", _scroll_canvas, add="+")
                widget.bind("<Button-5>", _scroll_canvas, add="+")
                bound_ids.add(widget_id)
                self._reaction_dashboard_mousewheel_bound = bound_ids
        except Exception:
            pass
        try:
            children = list(widget.winfo_children())
        except Exception:
            children = []
        for child in children:
            self._bind_reaction_dashboard_mousewheel_recursive(child)

    def _reaction_dashboard_scroll_to_widget(self, widget: tk.Widget) -> None:
        """Scroll the Reaction Dashboard canvas so a target widget is visible.

        Purpose:
            Support equation-token navigation into the long dashboard form.
        Why:
            Clicking a species should move the operator directly to the relevant
            input row or species table location.
        Args:
            widget: Tk widget to bring into view.
        Returns:
            None.
        Side Effects:
            Adjusts the dashboard canvas y-view.
        Exceptions:
            Geometry lookup failures are ignored.
        """
        canvas = getattr(self, "_reaction_dashboard_canvas", None)
        inner = getattr(self, "_reaction_dashboard_inner", None)
        if canvas is None or inner is None:
            return
        try:
            canvas.update_idletasks()
            bbox = canvas.bbox("all")
            if not bbox:
                return
            y_value = max(widget.winfo_rooty() - inner.winfo_rooty() - 24, 0)
            total_height = max(float(bbox[3] - bbox[1]), 1.0)
            canvas.yview_moveto(min(max(float(y_value) / total_height, 0.0), 1.0))
        except Exception:
            pass

    def _reaction_dashboard_flash_input_label(self, field_id: str) -> None:
        """Briefly emphasize one Reaction Dashboard input label.

        Purpose:
            Provide visual confirmation after equation-token navigation.
        Why:
            Scrolling alone can be ambiguous in a dense scientific input surface.
        Args:
            field_id: Template input field id whose label should be emphasized.
        Returns:
            None.
        Side Effects:
            Temporarily changes a label style where supported by the active theme.
        Exceptions:
            Styling failures are ignored.
        """
        label = self._reaction_input_labels_by_field.get(field_id)
        if label is None:
            return
        try:
            previous_style = str(label.cget("style") or "")
            label.configure(style="Sol.Help.TLabel")
            label.after(1200, lambda: label.configure(style=previous_style))
        except Exception:
            pass

    def _reaction_dashboard_focus_species(self, species_id: str) -> None:
        """Focus dashboard controls related to one equation species.

        Purpose:
            Resolve a clicked equation token into the field row or species row
            that controls the selected species.
        Why:
            Interactive equation navigation makes the workflow more visual without
            changing the template editor data contract.
        Args:
            species_id: Stable species id from the active template.
        Returns:
            None.
        Side Effects:
            Scrolls the dashboard, focuses entries, updates selections, and writes
            operator status text.
        Exceptions:
            Missing fields fall back to species-tree selection when possible.
        """
        field_ids = self._reaction_input_fields_by_species.get(species_id, [])
        if field_ids:
            first_field = field_ids[0]
            widget = self._reaction_input_widgets_by_field.get(first_field)
            if widget is not None:
                self._reaction_dashboard_scroll_to_widget(widget)
                try:
                    widget.focus_set()
                    if hasattr(widget, "selection_range"):
                        widget.selection_range(0, "end")
                except Exception:
                    pass
                for field_id in field_ids:
                    self._reaction_dashboard_flash_input_label(field_id)
                self._reaction_warnings_var.set(
                    f"Focused inputs linked to {species_id}."
                )
                return
        tree = getattr(self, "_reaction_species_tree", None)
        if tree is not None and tree.exists(species_id):
            self._reaction_dashboard_scroll_to_widget(tree)
            try:
                tree.selection_set(species_id)
                tree.focus(species_id)
                tree.see(species_id)
            except Exception:
                pass
            self._reaction_warnings_var.set(
                f"Selected species row for {species_id}."
            )

    def _reaction_dashboard_validate_required_inputs(
        self, template: ReactionTemplate
    ) -> List[str]:
        """Return missing required Reaction Dashboard input labels.

        Purpose:
            Gate calculation on fields needed for accurate template math.
        Why:
            Required UX inputs should fail clearly before the Rust/Python compute
            path receives silent zero values.
        Args:
            template: Active template whose `ReactionInputField` rows are checked.
        Returns:
            List of human-readable missing field labels.
        Side Effects:
            Focuses the first missing field and briefly highlights its label.
        Exceptions:
            Widget lookup failures do not interrupt validation.
        """
        missing: List[str] = []
        first_missing_field = ""
        for field_spec in template.input_fields:
            if not field_spec.required:
                continue
            var = self._reaction_input_vars.get(field_spec.field_id)
            value = str(var.get() if var is not None else "").strip()
            parsed = _safe_float(value)
            if not value or parsed is None or not math.isfinite(parsed):
                missing.append("required reaction input")
                if not first_missing_field:
                    first_missing_field = field_spec.field_id
        if first_missing_field:
            widget = self._reaction_input_widgets_by_field.get(first_missing_field)
            if widget is not None:
                self._reaction_dashboard_scroll_to_widget(widget)
                try:
                    widget.focus_set()
                except Exception:
                    pass
            self._reaction_dashboard_flash_input_label(first_missing_field)
        return missing

    def _on_reaction_template_selected(self, _event: Any = None) -> None:
        """Handle Reaction Dashboard template selector changes.

        Purpose:
            Load the selected template into the editable dashboard controls.
        Why:
            The displayed inputs, species, steps, and KPI labels are template-owned.
        Args:
            _event: Optional Tk combobox event.
        Returns:
            None.
        Side Effects:
            Updates settings and repopulates template UI widgets.
        Exceptions:
            Invalid selections fall back to the first available template.
        """
        template = self._reaction_active_template()
        settings[REACTION_DASHBOARD_SELECTED_TEMPLATE_KEY] = template.template_id
        self._refresh_reaction_template_selector()
        self._load_reaction_template_into_ui(template)

    def _on_reaction_source_selected(self, _event: Any = None) -> None:
        """Persist the selected Reaction Dashboard gas-uptake source mode.

        Purpose:
            Translate the displayed source label back to the stable source key.
        Why:
            Run calculations need a deterministic source token while the UI shows
            readable labels.
        Args:
            _event: Optional Tk combobox event.
        Returns:
            None.
        Side Effects:
            Updates `_reaction_source_mode_var` and settings.
        Exceptions:
            Unknown labels fall back to the default source mode.
        """
        label = str(self._reaction_source_display_var.get() or "").strip()
        source_key = getattr(self, "_reaction_source_label_to_key", {}).get(
            label, REACTION_DASHBOARD_DEFAULT_SOURCE_MODE
        )
        self._reaction_source_mode_var.set(source_key)
        settings["reaction_dashboard_source_mode"] = source_key

    def _load_reaction_template_into_ui(self, template: ReactionTemplate) -> None:
        """Load one Reaction Dashboard template into editor widgets.

        Purpose:
            Populate input rows, species table, steps JSON, KPI labels, and pH
            default state from the selected template.
        Why:
            Template-driven behavior depends on every visible control reflecting
            the currently selected template contract, including the displayed
            reaction equation.
        Args:
            template: Template to render into the dashboard.
        Returns:
            None.
        Side Effects:
            Destroys/rebuilds input widgets and updates tree/text/equation widgets.
        Exceptions:
            Widget mutation failures are guarded where practical.
        """
        try:
            self._reaction_template_name_var.set(
                f"{template.name} ({'built-in' if template.readonly else 'custom'})"
            )
        except Exception:
            pass
        inputs_frame = getattr(self, "_reaction_inputs_frame", None)
        if inputs_frame is not None:
            for child in list(inputs_frame.winfo_children()):
                child.destroy()
            self._reaction_input_vars = {}
            self._reaction_input_widgets_by_field = {}
            self._reaction_input_labels_by_field = {}
            self._reaction_input_fields_by_species = {}
            grouped_fields: Dict[str, List[ReactionInputField]] = {}
            group_labels = {
                "charge": "Starting materials",
                "conditions": "Operating conditions",
                "results": "Measured outcome",
                "template": "Additional inputs",
            }

            def _operator_input_label(
                field_spec: ReactionInputField,
                group_key: str,
                ordinal: int,
            ) -> str:
                """Return a reaction-agnostic label for one operator input.

                Purpose:
                    Hide chemistry-specific field names from the live workspace.
                Why:
                    The dashboard is a reusable operator surface; the reaction
                    equation and definition own material identity, while the form
                    communicates the role of each required entry consistently.
                Args:
                    field_spec: Template field retained for units and validation.
                    group_key: Template grouping key for the input.
                    ordinal: One-based position within the visible group.
                Returns:
                    Generic operator-facing label.
                Side Effects:
                    None.
                Exceptions:
                    None.
                """
                _ = field_spec
                if group_key == "charge":
                    return f"Starting material {ordinal} amount"
                if group_key == "conditions":
                    return f"Operating condition {ordinal}"
                if group_key == "results":
                    return "Measured product mass"
                return f"Additional input {ordinal}"
            for field_spec in template.input_fields:
                grouped_fields.setdefault(field_spec.group or "template", []).append(
                    field_spec
                )
            ttk.Label(
                inputs_frame,
                text=(
                    "Enter amounts in the same order as the reaction equation. "
                    "The selected reaction definition controls units, validation, "
                    "and all material-balance calculations."
                ),
                wraplength=920,
                justify="left",
                style="Sol.Help.TLabel",
            ).grid(
                row=0,
                column=0,
                columnspan=3,
                sticky="ew",
                padx=8,
                pady=(6, 4),
            )
            row_idx = 1
            for group_key, fields in grouped_fields.items():
                heading = ttk.Label(
                    inputs_frame,
                    text=group_labels.get(
                        group_key, group_key.replace("_", " ").title()
                    ),
                    style="Sol.Help.TLabel",
                )
                heading.grid(
                    row=row_idx,
                    column=0,
                    columnspan=3,
                    sticky="w",
                    padx=8,
                    pady=(6 if row_idx else 2, 2),
                )
                row_idx += 1
                for field_ordinal, field_spec in enumerate(fields, start=1):
                    operator_label = _operator_input_label(
                        field_spec, group_key, field_ordinal
                    )
                    label_text = operator_label + (
                        " *" if field_spec.required else ""
                    )
                    label_widget = ttk.Label(inputs_frame, text=label_text)
                    label_widget.grid(
                        row=row_idx,
                        column=0,
                        sticky="w",
                        padx=8,
                        pady=2,
                    )
                    var = tk.StringVar(value=str(field_spec.default or ""))
                    self._reaction_input_vars[field_spec.field_id] = var
                    entry_widget = _ui_entry(inputs_frame, textvariable=var, width=18)
                    entry_widget.grid(
                        row=row_idx,
                        column=1,
                        sticky="ew",
                        padx=8,
                        pady=2,
                    )
                    units_widget = ttk.Label(inputs_frame, text=field_spec.units)
                    units_widget.grid(
                        row=row_idx,
                        column=2,
                        sticky="w",
                        padx=4,
                        pady=2,
                    )
                    tip = (
                        f"Enter {operator_label.lower()} in {field_spec.units}."
                        if field_spec.units
                        else f"Enter {operator_label.lower()}."
                    )
                    self._attach_tooltip(label_widget, tip)
                    self._attach_tooltip(entry_widget, tip)
                    self._reaction_input_widgets_by_field[field_spec.field_id] = (
                        entry_widget
                    )
                    self._reaction_input_labels_by_field[field_spec.field_id] = (
                        label_widget
                    )
                    if field_spec.target_species_id:
                        self._reaction_input_fields_by_species.setdefault(
                            field_spec.target_species_id, []
                        ).append(field_spec.field_id)
                    row_idx += 1
        species_tree = getattr(self, "_reaction_species_tree", None)
        if species_tree is not None:
            species_tree.delete(*species_tree.get_children())
            for species in template.species:
                species_tree.insert(
                    "",
                    "end",
                    iid=species.species_id,
                    values=(
                        species.species_id,
                        species.name,
                        species.formula,
                        species.phase,
                        species.role,
                        f"{species.molar_mass_g_mol:.6g}",
                        f"{species.initial_moles:.6g}",
                    ),
                )
        steps_text = getattr(self, "_reaction_steps_text", None)
        if steps_text is not None:
            steps_payload = [asdict(step) for step in template.steps]
            steps_text.delete("1.0", "end")
            steps_text.insert("1.0", json.dumps(steps_payload, indent=2))
        self._refresh_reaction_equation_widget(template)
        try:
            self._reaction_ph_enabled_var.set(
                bool(template.equilibrium.enabled_by_default)
            )
        except Exception:
            pass
        generic_kpi_placeholders = {
            "gas_uptake": "Reactant gas: --",
            "intermediate": "Intermediate balance: --",
            "product": "Expected product: --",
            "yield": "Measured yield: --",
            "completion": "Reaction completion: --",
            "ph": "Equilibrium estimate: --",
        }
        for key, label in generic_kpi_placeholders.items():
            var = self._reaction_kpi_vars.get(key)
            if isinstance(var, tk.StringVar):
                var.set(label)
        for key in ("source_backend", "limiting"):
            var = self._reaction_kpi_vars.get(key)
            if isinstance(var, tk.StringVar):
                var.set("--")
        self._reaction_backend_var.set("Backend: --")
        gas_meta = _reaction_dashboard_species_display(
            template, template.gas_species_id
        )
        product_meta = _reaction_dashboard_species_display(
            template, template.yield_basis.product_species_id
        )
        self._reaction_status_var.set(
            f"Ready: {template.name} | Gas: {gas_meta['display']} | Product: {product_meta['display']}"
        )
        self._reaction_next_action_var.set(
            "Enter required charge values, import Cycle Analysis or select a gas source, then run the dashboard."
        )
        status_label = getattr(self, "_reaction_status_label", None)
        if status_label is not None:
            try:
                status_label.configure(
                    fg=REACTION_DASHBOARD_STATUS_COLORS["unavailable"]
                )
            except Exception:
                pass
        self._refresh_reaction_cycle_selector({"cycle_rows": []})
        self._draw_reaction_completion_gauge(None, status="unavailable")
        self._draw_reaction_series_chart(
            getattr(self, "_reaction_trend_canvas", None),
            [],
            y_key="cumulative_gas_mol",
            title="Gas/Product Trend",
            color=REACTION_DASHBOARD_STATUS_COLORS["neutral"],
        )
        self._draw_reaction_series_chart(
            getattr(self, "_reaction_delta_canvas", None),
            [],
            y_key="gas_delta_mol",
            title="Per-Cycle Gas Delta",
            color=REACTION_DASHBOARD_STATUS_COLORS["watch"],
        )
        cycle_tree = getattr(self, "_reaction_cycle_tree", None)
        if cycle_tree is not None:
            try:
                cycle_tree.delete(*cycle_tree.get_children())
            except Exception:
                pass
        self._reaction_warnings_var.set(
            "Template loaded. Run calculation to populate metrics."
        )

    def _reaction_species_selected(self, _event: Any = None) -> None:
        """Populate species edit fields from the selected species row.

        Purpose:
            Make row editing deterministic without inline Treeview editing.
        Why:
            Tk Treeview does not provide native cell editing, so a small form keeps
            template edits explicit and recoverable.
        Args:
            _event: Optional selection event.
        Returns:
            None.
        Side Effects:
            Updates `_reaction_species_edit_vars`.
        Exceptions:
            Missing selection/widgets are ignored.
        """
        tree = getattr(self, "_reaction_species_tree", None)
        if tree is None:
            return
        selection = tree.selection()
        if not selection:
            return
        values = list(tree.item(selection[0], "values") or [])
        keys = list(getattr(self, "_reaction_species_edit_vars", {}).keys())
        for key, value in zip(keys, values, strict=False):
            try:
                self._reaction_species_edit_vars[key].set(str(value))
            except Exception:
                pass

    def _reaction_dashboard_add_or_update_species(self) -> None:
        """Add or update one species row in the Reaction Dashboard editor.

        Purpose:
            Let users adjust species metadata before saving a custom template.
        Why:
            Template editing should not require direct file edits for common
            species-row changes.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Mutates the species Treeview row set.
        Exceptions:
            Invalid numeric fields are reported through the warning label.
        """
        tree = getattr(self, "_reaction_species_tree", None)
        if tree is None:
            return
        values = {
            key: var.get().strip()
            for key, var in getattr(self, "_reaction_species_edit_vars", {}).items()
        }
        species_id = values.get("species_id", "")
        if not species_id:
            self._reaction_warnings_var.set("Species id is required.")
            return
        try:
            float(values.get("molar_mass_g_mol") or 0.0)
            float(values.get("initial_moles") or 0.0)
        except Exception:
            self._reaction_warnings_var.set(
                "Molar mass and initial moles must be numeric."
            )
            return
        row_values = tuple(
            values.get(key, "") for key in self._reaction_species_edit_vars
        )
        if tree.exists(species_id):
            tree.item(species_id, values=row_values)
        else:
            tree.insert("", "end", iid=species_id, values=row_values)
        self._reaction_warnings_var.set(
            "Species row updated. Save as a custom template to persist."
        )

    def _reaction_dashboard_remove_species(self) -> None:
        """Remove selected species rows from the Reaction Dashboard editor.

        Purpose:
            Support custom-template species cleanup from the UI.
        Why:
            Users need a direct way to adapt duplicated templates to other reaction
            schemes.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Deletes selected Treeview rows.
        Exceptions:
            Missing selection/widgets are ignored.
        """
        tree = getattr(self, "_reaction_species_tree", None)
        if tree is None:
            return
        for item in tree.selection():
            try:
                tree.delete(item)
            except Exception:
                continue
        self._reaction_warnings_var.set(
            "Species removed. Save as a custom template to persist."
        )

    def _reaction_dashboard_collect_species_rows(self) -> List[Dict[str, Any]]:
        """Collect species rows from the Reaction Dashboard species editor.

        Purpose:
            Convert Treeview values into compute/template species mappings.
        Why:
            Both custom-template persistence and run calculations need the same
            normalized species payload.
        Args:
            None.
        Returns:
            List of species dictionaries.
        Side Effects:
            None.
        Exceptions:
            Invalid numeric cells are normalized to zero.
        """
        tree = getattr(self, "_reaction_species_tree", None)
        rows: List[Dict[str, Any]] = []
        if tree is None:
            return rows
        for item in tree.get_children():
            values = list(tree.item(item, "values") or [])
            values += [""] * max(0, 7 - len(values))
            rows.append(
                {
                    "species_id": str(values[0]).strip(),
                    "name": str(values[1]).strip(),
                    "formula": str(values[2]).strip(),
                    "phase": str(values[3]).strip() or "solution",
                    "role": str(values[4]).strip() or "species",
                    "molar_mass_g_mol": _safe_float(values[5], 0.0) or 0.0,
                    "initial_moles": _safe_float(values[6], 0.0) or 0.0,
                    "charge": 0,
                }
            )
        return rows

    def _reaction_dashboard_steps_from_editor(self) -> List[Dict[str, Any]]:
        """Parse Reaction Dashboard step JSON from the editor.

        Purpose:
            Convert the editable linked-step JSON into a validated list payload.
        Why:
            Step stoichiometry is template-specific and must be easy to save into
            custom templates.
        Args:
            None.
        Returns:
            List of step dictionaries.
        Side Effects:
            None.
        Exceptions:
            JSON or shape errors raise ValueError for callers to surface.
        """
        text_widget = getattr(self, "_reaction_steps_text", None)
        if text_widget is None:
            return []
        raw_text = text_widget.get("1.0", "end").strip()
        payload = json.loads(raw_text or "[]")
        if not isinstance(payload, list):
            raise ValueError("Step JSON must be a list.")
        rows: List[Dict[str, Any]] = []
        for idx, row in enumerate(payload, start=1):
            if not isinstance(row, Mapping):
                raise ValueError(f"Step {idx} must be an object.")
            stoich = row.get("stoichiometry")
            if not isinstance(stoich, Mapping):
                raise ValueError(f"Step {idx} must include a stoichiometry object.")
            rows.append(
                {
                    "step_id": str(row.get("step_id") or row.get("id") or idx),
                    "name": str(row.get("name") or f"Step {idx}"),
                    "stoichiometry": {
                        str(key).strip(): float(value)
                        for key, value in dict(stoich).items()
                        if str(key).strip()
                    },
                    "description": str(row.get("description") or ""),
                }
            )
        return rows

    def _reaction_dashboard_template_from_editor(self) -> ReactionTemplate:
        """Build a custom Reaction Dashboard template from editor widgets.

        Purpose:
            Convert the current UI editor state into a typed template.
        Why:
            Custom template saving and JSON editing should use the same validation
            path as persisted template loading.
        Args:
            None.
        Returns:
            Validated `ReactionTemplate`.
        Side Effects:
            None.
        Exceptions:
            Raises ValueError when the edited template is invalid.
        """
        base = self._reaction_active_template()
        name = self._reaction_template_name_var.get().split(" (", 1)[0].strip()
        if not name:
            name = f"Custom {base.name}"
        template_id = re.sub(r"[^a-z0-9]+", "_", name.lower()).strip("_")
        if not template_id:
            template_id = f"custom_reaction_{int(time.time())}"
        if template_id in _builtin_reaction_templates():
            template_id = f"{template_id}_custom"
        payload = _reaction_template_to_dict(base)
        payload.update(
            {
                "template_id": template_id,
                "name": name,
                "readonly": False,
                "species": self._reaction_dashboard_collect_species_rows(),
                "steps": self._reaction_dashboard_steps_from_editor(),
            }
        )
        template = _reaction_template_from_dict(payload)
        if template is None:
            raise ValueError("Edited reaction template is invalid.")
        return template

    def _reaction_dashboard_unique_template_id(self, name: str) -> str:
        """Return a unique persisted identifier for a new reaction definition.

        Purpose:
            Prevent custom definitions from colliding with built-in or existing
            custom identifiers when they are created from a starter or JSON copy.
        Why:
            A collision previously made a new definition appear to save while the
            built-in filtering path discarded it from persistent custom storage.
        Args:
            name: Operator-supplied reaction-definition name.
        Returns:
            Lowercase identifier that is absent from the current template catalog.
        Side Effects:
            None.
        Exceptions:
            None.
        """
        stem = re.sub(r"[^a-z0-9]+", "_", str(name or "").lower()).strip("_")
        stem = stem or "custom_reaction"
        existing_ids = set(getattr(self, "_reaction_templates", {}) or {})
        existing_ids.update(_builtin_reaction_templates())
        candidate = stem
        suffix = 2
        while candidate in existing_ids:
            candidate = f"{stem}_{suffix}"
            suffix += 1
        return candidate

    def _reaction_dashboard_new_template(self) -> None:
        """Create a usable, chemistry-neutral starter reaction definition.

        Purpose:
            Give operators a direct path to add a reaction without first cloning
            or reverse-engineering the built-in chemistry template.
        Why:
            The definition manager must support reaction-agnostic work; a starter
            with generic material, gas, and product rows is easier to edit safely.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Adds and persists a new custom definition, selects it, and loads its
            generic editor fields into the workspace.
        Exceptions:
            Dialog cancellation leaves the active definition unchanged.
        """
        name = simpledialog.askstring(
            "New Reaction Definition",
            "Name this reaction definition:",
            parent=self,
            initialvalue="New reaction",
        )
        name = str(name or "").strip()
        if not name:
            return
        template_id = self._reaction_dashboard_unique_template_id(name)
        payload = {
            "template_id": template_id,
            "name": name,
            "version": "1.0",
            "description": "Generic editable reaction definition.",
            "readonly": False,
            "reaction_family": "custom",
            "gas_species_id": "reactant_gas",
            "species": [
                {
                    "species_id": "starting_material_1",
                    "name": "Starting material 1",
                    "formula": "",
                    "phase": "solid",
                    "role": "reactant",
                    "molar_mass_g_mol": 1.0,
                    "initial_moles": 0.0,
                },
                {
                    "species_id": "reactant_gas",
                    "name": "Reactant gas",
                    "formula": "",
                    "phase": "gas",
                    "role": "reactant",
                    "molar_mass_g_mol": 1.0,
                    "initial_moles": 0.0,
                },
                {
                    "species_id": "product",
                    "name": "Product",
                    "formula": "",
                    "phase": "solid",
                    "role": "product",
                    "molar_mass_g_mol": 1.0,
                    "initial_moles": 0.0,
                },
            ],
            "steps": [
                {
                    "step_id": "main_reaction",
                    "name": "Main reaction",
                    "stoichiometry": {
                        "starting_material_1": -1.0,
                        "reactant_gas": -1.0,
                        "product": 1.0,
                    },
                    "description": "Replace the default coefficients and materials.",
                }
            ],
            "input_fields": [
                {
                    "field_id": "starting_material_1_mass_g",
                    "label": "Starting material 1 amount",
                    "units": "g",
                    "default": "",
                    "required": True,
                    "target_species_id": "starting_material_1",
                    "quantity": "mass_g",
                    "group": "charge",
                },
                {
                    "field_id": "actual_product_mass_g",
                    "label": "Measured product mass",
                    "units": "g",
                    "default": "",
                    "required": False,
                    "target_species_id": "product",
                    "quantity": "actual_mass_g",
                    "group": "results",
                },
            ],
            "yield_basis": {
                "product_species_id": "product",
                "target_reactant_species_id": "starting_material_1",
                "actual_mass_field_id": "actual_product_mass_g",
                "label": "Product yield",
            },
            "equilibrium": {"enabled_by_default": False},
            "kpi_labels": {},
        }
        template = _reaction_template_from_dict(payload)
        if template is None:
            self._reaction_warnings_var.set("Unable to create the new reaction definition.")
            return
        self._reaction_templates[template.template_id] = template
        self._reaction_template_var.set(template.template_id)
        settings[REACTION_DASHBOARD_SELECTED_TEMPLATE_KEY] = template.template_id
        self._persist_reaction_custom_templates()
        self._refresh_reaction_template_selector()
        self._load_reaction_template_into_ui(template)
        self._reaction_warnings_var.set(
            "New reaction definition created. Update material names, molar masses, "
            "and reaction coefficients before running it."
        )

    def _reaction_dashboard_open_new_definition_wizard(self) -> None:
        """Open a guided form that creates and saves a simple reaction definition.

        Purpose:
            Replace the error-prone editor-first creation path with a short,
            chemistry-focused workflow that produces a valid template directly.
        Why:
            Most reactions can begin as one starting material plus one reactant
            gas producing one product; advanced JSON/species editing should not be
            required to create that baseline definition.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Opens a dialog and, on save, persists/selects a new custom definition.
        Exceptions:
            Invalid numeric entries remain in the dialog with a clear error message.
        """
        window = tk.Toplevel(self)
        window.title("New Reaction Definition")
        window.transient(self)
        window.resizable(False, False)
        host = ttk.Frame(window, padding=14)
        host.grid(sticky="nsew")
        host.grid_columnconfigure(1, weight=1)
        ttk.Label(
            host,
            text="Create a reaction in three steps",
            font=("TkDefaultFont", 11, "bold"),
        ).grid(row=0, column=0, columnspan=3, sticky="w")
        ttk.Label(
            host,
            text=(
                "Enter the starting material, reactant gas, and expected product. "
                "Use positive stoichiometric amounts; advanced definitions can be "
                "edited afterward if the reaction has additional steps."
            ),
            wraplength=620,
            justify="left",
            style="Sol.Help.TLabel",
        ).grid(row=1, column=0, columnspan=3, sticky="w", pady=(2, 10))
        fields = {
            "definition_name": tk.StringVar(value="New reaction"),
            "starting_name": tk.StringVar(value="Starting material"),
            "starting_formula": tk.StringVar(value=""),
            "starting_mw": tk.StringVar(value=""),
            "gas_name": tk.StringVar(value="Reactant gas"),
            "gas_formula": tk.StringVar(value=""),
            "gas_mw": tk.StringVar(value=""),
            "product_name": tk.StringVar(value="Product"),
            "product_formula": tk.StringVar(value=""),
            "product_mw": tk.StringVar(value=""),
            "starting_coeff": tk.StringVar(value="1"),
            "gas_coeff": tk.StringVar(value="1"),
            "product_coeff": tk.StringVar(value="1"),
        }
        ttk.Label(host, text="Reaction name").grid(row=2, column=0, sticky="w", pady=2)
        _ui_entry(host, textvariable=fields["definition_name"], width=42).grid(
            row=2, column=1, columnspan=2, sticky="ew", pady=2
        )
        headers = ("Role", "Name / formula", "Molar mass (g/mol)", "Stoichiometry")
        for column, header in enumerate(headers):
            ttk.Label(host, text=header, style="Sol.Help.TLabel").grid(
                row=3, column=column, sticky="w", padx=(0, 8), pady=(8, 2)
            )
        row_specs = (
            ("Starting material", "starting_name", "starting_formula", "starting_mw", "starting_coeff"),
            ("Reactant gas", "gas_name", "gas_formula", "gas_mw", "gas_coeff"),
            ("Expected product", "product_name", "product_formula", "product_mw", "product_coeff"),
        )
        for row_index, (role, name_key, formula_key, mw_key, coeff_key) in enumerate(row_specs, start=4):
            ttk.Label(host, text=role).grid(row=row_index, column=0, sticky="w", pady=2)
            name_formula = ttk.Frame(host)
            name_formula.grid(row=row_index, column=1, sticky="ew", padx=(0, 8), pady=2)
            name_formula.grid_columnconfigure(0, weight=1)
            _ui_entry(name_formula, textvariable=fields[name_key], width=28).grid(
                row=0, column=0, sticky="ew"
            )
            _ui_entry(name_formula, textvariable=fields[formula_key], width=10).grid(
                row=0, column=1, padx=(4, 0)
            )
            _ui_entry(host, textvariable=fields[mw_key], width=16).grid(
                row=row_index, column=2, sticky="w", padx=(0, 8), pady=2
            )
            _ui_entry(host, textvariable=fields[coeff_key], width=12).grid(
                row=row_index, column=3, sticky="w", pady=2
            )
        status = tk.StringVar(value="Formula entries are optional; molar masses are required.")
        ttk.Label(host, textvariable=status, style="Sol.Help.TLabel", wraplength=620).grid(
            row=7, column=0, columnspan=4, sticky="w", pady=(10, 4)
        )

        def _positive_value(key: str, label: str) -> float:
            """Read one required positive numeric wizard value."""
            value = _safe_float(fields[key].get())
            if value is None or not math.isfinite(value) or value <= 0.0:
                raise ValueError(f"{label} must be a positive number.")
            return float(value)

        def _save_definition() -> None:
            """Validate wizard inputs and persist the resulting reaction definition."""
            try:
                name = str(fields["definition_name"].get() or "").strip()
                starting_name = str(fields["starting_name"].get() or "").strip()
                gas_name = str(fields["gas_name"].get() or "").strip()
                product_name = str(fields["product_name"].get() or "").strip()
                if not all((name, starting_name, gas_name, product_name)):
                    raise ValueError("Provide a reaction name and names for all three materials.")
                starting_mw = _positive_value("starting_mw", "Starting-material molar mass")
                gas_mw = _positive_value("gas_mw", "Reactant-gas molar mass")
                product_mw = _positive_value("product_mw", "Product molar mass")
                starting_coeff = _positive_value("starting_coeff", "Starting-material stoichiometry")
                gas_coeff = _positive_value("gas_coeff", "Reactant-gas stoichiometry")
                product_coeff = _positive_value("product_coeff", "Product stoichiometry")
            except ValueError as exc:
                status.set(str(exc))
                return
            template_id = self._reaction_dashboard_unique_template_id(name)
            payload = {
                "template_id": template_id,
                "name": name,
                "version": "1.0",
                "description": "Created with the guided reaction-definition form.",
                "readonly": False,
                "reaction_family": "custom",
                "gas_species_id": "reactant_gas",
                "species": [
                    {"species_id": "starting_material", "name": starting_name, "formula": fields["starting_formula"].get().strip(), "phase": "solid", "role": "reactant", "molar_mass_g_mol": starting_mw, "initial_moles": 0.0},
                    {"species_id": "reactant_gas", "name": gas_name, "formula": fields["gas_formula"].get().strip(), "phase": "gas", "role": "reactant", "molar_mass_g_mol": gas_mw, "initial_moles": 0.0},
                    {"species_id": "product", "name": product_name, "formula": fields["product_formula"].get().strip(), "phase": "solid", "role": "product", "molar_mass_g_mol": product_mw, "initial_moles": 0.0},
                ],
                "steps": [{"step_id": "main_reaction", "name": "Main reaction", "stoichiometry": {"starting_material": -starting_coeff, "reactant_gas": -gas_coeff, "product": product_coeff}}],
                "input_fields": [
                    {"field_id": "starting_material_mass_g", "label": "Starting material amount", "units": "g", "default": "", "required": True, "target_species_id": "starting_material", "quantity": "mass_g", "group": "charge"},
                    {"field_id": "actual_product_mass_g", "label": "Measured product mass", "units": "g", "default": "", "required": False, "target_species_id": "product", "quantity": "actual_mass_g", "group": "results"},
                ],
                "yield_basis": {"product_species_id": "product", "target_reactant_species_id": "starting_material", "actual_mass_field_id": "actual_product_mass_g", "label": "Product yield"},
                "equilibrium": {"enabled_by_default": False},
                "kpi_labels": {},
            }
            template = _reaction_template_from_dict(payload)
            if template is None:
                status.set("The reaction definition could not be validated. Check the entered values.")
                return
            self._reaction_templates[template.template_id] = template
            self._reaction_template_var.set(template.template_id)
            settings[REACTION_DASHBOARD_SELECTED_TEMPLATE_KEY] = template.template_id
            self._persist_reaction_custom_templates()
            self._refresh_reaction_template_selector()
            self._load_reaction_template_into_ui(template)
            self._reaction_warnings_var.set(
                f"Created reaction definition: {template.name}. Enter the starting-material amount to begin."
            )
            window.destroy()

        buttons = ttk.Frame(host)
        buttons.grid(row=8, column=0, columnspan=4, sticky="e", pady=(6, 0))
        _ui_button(buttons, text="Cancel", command=window.destroy).grid(row=0, column=0, padx=(0, 6))
        _ui_button(buttons, text="Create Reaction", command=_save_definition).grid(row=0, column=1)

    def _persist_reaction_custom_templates(self) -> None:
        """Persist custom Reaction Dashboard templates to settings.

        Purpose:
            Write the non-built-in template catalog into settings.
        Why:
            Built-ins are code-defined, while custom templates must survive restart.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Updates `settings` and writes settings to disk.
        Exceptions:
            Settings write failures are guarded.
        """
        builtins = _builtin_reaction_templates()
        custom_payloads = [
            _reaction_template_to_dict(template)
            for template_id, template in (
                getattr(self, "_reaction_templates", {}) or {}
            ).items()
            if template_id not in builtins
        ]
        settings[REACTION_DASHBOARD_CUSTOM_TEMPLATES_KEY] = custom_payloads
        try:
            _save_settings_to_disk()
        except Exception:
            pass

    def _reaction_dashboard_save_custom_template(self) -> None:
        """Save the current Reaction Dashboard editor state as a custom template.

        Purpose:
            Let users persist a duplicated or edited reaction scheme.
        Why:
            The dashboard must work from templates, including user-defined future
            reactions beyond the starter sodium methoxide/CO workflow.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Updates the template catalog, settings, selector, and status label.
        Exceptions:
            Validation errors are displayed to the user.
        """
        try:
            template = self._reaction_dashboard_template_from_editor()
        except Exception as exc:
            self._reaction_warnings_var.set(f"Unable to save template: {exc}")
            return
        templates = dict(getattr(self, "_reaction_templates", {}) or {})
        templates[template.template_id] = template
        self._reaction_templates = templates
        self._reaction_template_var.set(template.template_id)
        settings[REACTION_DASHBOARD_SELECTED_TEMPLATE_KEY] = template.template_id
        self._persist_reaction_custom_templates()
        self._refresh_reaction_template_selector()
        self._load_reaction_template_into_ui(template)
        self._reaction_warnings_var.set(f"Saved custom template: {template.name}")

    def _reaction_dashboard_duplicate_template(self) -> None:
        """Create an editable custom copy of the active Reaction Dashboard template.

        Purpose:
            Seed a new custom template from a built-in or existing custom template.
        Why:
            Built-in templates should remain immutable while still being easy to
            adapt to adjacent reaction schemes.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Updates editor name/status fields; persistence occurs on Save Custom.
        Exceptions:
            None.
        """
        base = self._reaction_active_template()
        copy_name = f"Copy of {base.name}"
        self._reaction_template_name_var.set(copy_name)
        self._reaction_warnings_var.set(
            "Duplicate is editable. Adjust species/steps, then Save Custom Template."
        )

    def _reaction_dashboard_open_template_json_editor(self) -> None:
        """Open a JSON editor for full Reaction Dashboard template payloads.

        Purpose:
            Provide a complete template-editing escape hatch for advanced users.
        Why:
            Some future reactions may need new input fields, yield basis, or
            equilibrium rows before a dedicated form editor exists.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Opens a Toplevel editor and may persist a custom template.
        Exceptions:
            JSON/validation errors are displayed in the editor status.
        """
        source_template = self._reaction_active_template()
        base_payload = _reaction_template_to_dict(source_template)
        base_payload["name"] = f"Custom {source_template.name}"
        base_payload["template_id"] = self._reaction_dashboard_unique_template_id(
            base_payload["name"]
        )
        base_payload["readonly"] = False
        window = tk.Toplevel(self)
        window.title("Reaction Definition JSON Editor")
        window.transient(self)
        window.geometry("900x650")
        host = ttk.Frame(window, padding=8)
        host.pack(fill="both", expand=True)
        host.grid_rowconfigure(0, weight=1)
        host.grid_columnconfigure(0, weight=1)
        text = tk.Text(host, wrap="none")
        text.grid(row=0, column=0, sticky="nsew")
        text.insert("1.0", json.dumps(base_payload, indent=2))
        status = tk.StringVar(value="Edit JSON, then save as a new custom reaction definition.")
        ttk.Label(host, textvariable=status).grid(
            row=1, column=0, sticky="ew", pady=(6, 4)
        )

        def _save_from_json() -> None:
            """Validate and save the JSON editor payload as a custom template."""
            try:
                payload = json.loads(text.get("1.0", "end"))
                if isinstance(payload, dict):
                    payload["readonly"] = False
                template = (
                    _reaction_template_from_dict(payload)
                    if isinstance(payload, Mapping)
                    else None
                )
                if template is None:
                    raise ValueError("Template JSON is invalid.")
            except Exception as exc:
                status.set(f"Save failed: {exc}")
                return
            templates = dict(getattr(self, "_reaction_templates", {}) or {})
            templates[template.template_id] = template
            self._reaction_templates = templates
            self._reaction_template_var.set(template.template_id)
            settings[REACTION_DASHBOARD_SELECTED_TEMPLATE_KEY] = template.template_id
            self._persist_reaction_custom_templates()
            self._refresh_reaction_template_selector()
            self._load_reaction_template_into_ui(template)
            status.set(f"Saved custom template: {template.name}")

        _ui_button(host, text="Save Reaction Definition", command=_save_from_json).grid(
            row=2, column=0, sticky="w"
        )

    def _reaction_dashboard_import_cycle_payload(self) -> None:
        """Select Cycle Analysis as the Reaction Dashboard uptake source.

        Purpose:
            Make Cycle Analysis marker import a one-click source selection and
            refresh the dashboard when required inputs are valid.
        Why:
            Users should be able to reuse cycle markers and gas-uptake rows without
            copying numbers between tabs, and imported data should immediately
            drive the visual dashboard.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Updates source mode variables and status text.
        Exceptions:
            Missing cycle payload is reported through the warning label.
        """
        payload = getattr(self, "_cycle_last_transfer_payload", None)
        if not payload:
            self._reaction_warnings_var.set(
                "Run Cycle Analysis before importing cycle uptake into "
                "Reaction Dashboard."
            )
            return
        self._reaction_source_mode_var.set("cycle_payload")
        self._reaction_source_display_var.set(
            self._reaction_source_key_to_label.get(
                "cycle_payload", "Imported Cycle Analysis payload"
            )
        )
        self._reaction_warnings_var.set(
            "Cycle Analysis payload selected as uptake source. Refreshing dashboard."
        )
        self._reaction_cycle_focus_var.set("Latest")
        self._run_reaction_dashboard()

    def _reaction_dashboard_species_rows_with_inputs(
        self, template: ReactionTemplate
    ) -> Tuple[List[Dict[str, Any]], Optional[Dict[str, Any]]]:
        """Return species rows with reaction-definition inputs applied.

        Purpose:
            Convert template-specific starting-material values into initial
            species moles for the selected reaction definition.
        Why:
            Run calculations should respect template-specific required inputs
            while preserving editable species defaults and any definition-owned
            availability calculations.
        Args:
            template: Active reaction template.
        Returns:
            Tuple of species row mappings ready for Rust/Python compute and an
            optional input-derived diagnostic mapping.
        Side Effects:
            None.
        Exceptions:
            Invalid numeric values are treated as zero.
        """
        rows = self._reaction_dashboard_collect_species_rows()
        by_id = {row["species_id"]: row for row in rows}
        charge_basis: Optional[Dict[str, Any]] = None
        field_ids = {field.field_id for field in template.input_fields}
        has_charge_basis = {
            "sodium_metal_mass_g",
            "methanol_mass_g",
            "methanol_water_ppm_by_mass",
            "sodium_hydroxide_mass_g",
        }.issubset(field_ids)
        if has_charge_basis:
            explicit_naoh_mass_g = self._reaction_dashboard_input_float(
                "sodium_hydroxide_mass_g"
            )
            if not self._reaction_dashboard_input_text("sodium_hydroxide_mass_g"):
                explicit_naoh_mass_g = 0.0
            charge_basis = _run_reaction_solution_charge_core(
                sodium_metal_mass_g=self._reaction_dashboard_input_float(
                    "sodium_metal_mass_g"
                ),
                methanol_mass_g=self._reaction_dashboard_input_float(
                    "methanol_mass_g"
                ),
                water_ppm_by_mass=self._reaction_dashboard_input_float(
                    "methanol_water_ppm_by_mass"
                ),
                explicit_naoh_mass_g=explicit_naoh_mass_g,
            )
            charge_updates = {
                "sodium_methoxide": charge_basis.get("sodium_methoxide_mol"),
                "sodium_hydroxide": charge_basis.get("total_naoh_mol"),
                "methanol": charge_basis.get("remaining_methanol_mol"),
            }
            for species_id, value in charge_updates.items():
                target = by_id.get(species_id)
                parsed = _safe_float(value)
                if target is not None and parsed is not None:
                    target["initial_moles"] = max(float(parsed), 0.0)
        for field_spec in template.input_fields:
            if has_charge_basis and field_spec.field_id in {
                "sodium_metal_mass_g",
                "methanol_mass_g",
                "methanol_water_ppm_by_mass",
                "sodium_hydroxide_mass_g",
            }:
                continue
            if not field_spec.target_species_id:
                continue
            target = by_id.get(field_spec.target_species_id)
            if target is None:
                continue
            var = self._reaction_input_vars.get(field_spec.field_id)
            value = _safe_float(var.get() if var is not None else None)
            if value is None or not math.isfinite(value):
                continue
            if field_spec.quantity == "mass_g":
                mw_value = _safe_float(target.get("molar_mass_g_mol"), 0.0) or 0.0
                target["initial_moles"] = max(float(value) / max(mw_value, 1e-30), 0.0)
            elif field_spec.quantity == "moles":
                target["initial_moles"] = max(float(value), 0.0)
        return rows, charge_basis

    def _reaction_dashboard_input_text(self, key: str) -> str:
        """Return one Reaction Dashboard input/source value as trimmed text.

        Purpose:
            Preserve the difference between blank optional inputs and invalid
            numeric entries before float parsing collapses both to None.
        Why:
            The NaOH field is optional until the hydrolysis step begins; blank
            input should defer hydrolysis rather than fail validation or emit a
            charge-basis missing-value warning.
        Args:
            key: Input or source variable key.
        Returns:
            str: Trimmed widget value, or an empty string when unavailable.
        Side Effects:
            None.
        Exceptions:
            Missing variables or Tk read failures return an empty string.
        """
        var = self._reaction_input_vars.get(key) or self._reaction_source_vars.get(key)
        if var is None:
            return ""
        try:
            return str(var.get() or "").strip()
        except Exception:
            return ""

    def _reaction_dashboard_input_float(self, key: str) -> Optional[float]:
        """Return one Reaction Dashboard input value as an optional float.

        Purpose:
            Normalize mixed template/source input variables into numeric scalars.
        Why:
            Gas uptake, yield, and pH calculations share the same input values.
        Args:
            key: Input or source variable key.
        Returns:
            Parsed float or None.
        Side Effects:
            None.
        Exceptions:
            Invalid or missing values return None.
        """
        value = _safe_float(self._reaction_dashboard_input_text(key))
        if value is None or not math.isfinite(value):
            return None
        return float(value)

    def _reaction_dashboard_step_rows_for_available_inputs(
        self,
        template: ReactionTemplate,
        step_rows: Sequence[Mapping[str, Any]],
    ) -> Tuple[List[Dict[str, Any]], List[Dict[str, str]]]:
        """Filter dashboard step rows that require unavailable optional inputs.

        Purpose:
            Remove hydrolysis steps that consume explicit NaOH when the optional
            NaOH field is blank, and record a display-only deferred-step note.
        Why:
            First-step carbonylation analysis should be available before the
            operator has started or measured the second reaction step, while the
            Rust/Python compute core can keep receiving ordinary step rows.
        Args:
            template: Active Reaction Dashboard template.
            step_rows: Editable step row mappings from the dashboard editor.
        Returns:
            Tuple of filtered step row dictionaries and deferred-step metadata.
        Side Effects:
            None.
        Exceptions:
            Malformed step stoichiometry is left untouched unless it clearly
            consumes the optional NaOH species.
        """
        copied_steps = [dict(step) for step in step_rows if isinstance(step, Mapping)]
        naoh_field = next(
            (
                field
                for field in template.input_fields
                if field.field_id == "sodium_hydroxide_mass_g"
            ),
            None,
        )
        if naoh_field is None or self._reaction_dashboard_input_text(
            naoh_field.field_id
        ):
            return copied_steps, []
        naoh_species_id = str(naoh_field.target_species_id or "sodium_hydroxide")
        filtered_steps: List[Dict[str, Any]] = []
        deferred_steps: List[Dict[str, str]] = []
        for step in copied_steps:
            stoich = step.get("stoichiometry")
            consumes_naoh = False
            if isinstance(stoich, Mapping):
                amount = _safe_float(stoich.get(naoh_species_id))
                consumes_naoh = amount is not None and amount < 0.0
            if consumes_naoh:
                step_name = str(step.get("name") or step.get("step_id") or "Hydrolysis")
                deferred_steps.append(
                    {
                        "step_id": str(step.get("step_id") or ""),
                        "name": step_name,
                        "species_id": naoh_species_id,
                        "reason": (
                            f"{step_name} deferred until the required reaction input "
                            "is entered; final completion is not available."
                        ),
                    }
                )
                continue
            filtered_steps.append(step)
        return filtered_steps, deferred_steps

    def _reaction_dashboard_resolve_gas_uptake(
        self, template: ReactionTemplate, species_rows: Sequence[Mapping[str, Any]]
    ) -> Tuple[float, List[str]]:
        """Resolve reactant-gas uptake moles for one Reaction Dashboard run.

        Purpose:
            Convert the selected source mode into moles of the template gas species.
        Why:
            The dashboard supports imported cycle payloads, reactor pressure deltas,
            cylinder loss, and manual entry through one compute path.
        Args:
            template: Active reaction template.
            species_rows: Current species rows used to resolve gas molar mass.
        Returns:
            Tuple of gas uptake moles and warning strings.
        Side Effects:
            None.
        Exceptions:
            Invalid source data returns zero uptake with warnings.
        """
        warnings: List[str] = []
        gas_row = next(
            (
                row
                for row in species_rows
                if row.get("species_id") == template.gas_species_id
            ),
            {},
        )
        gas_mw = _safe_float(gas_row.get("molar_mass_g_mol"), 0.0) or 0.0
        source_mode = str(self._reaction_source_mode_var.get() or "").strip()
        if source_mode == "cycle_payload":
            payload = getattr(self, "_cycle_last_transfer_payload", None)
            if not isinstance(payload, Mapping):
                return 0.0, ["Cycle Analysis payload is unavailable."]
            moles = _safe_float(payload.get("total_moles_vdw"))
            if moles is None:
                moles = _safe_float(payload.get("total_moles_ideal"))
            if moles is None:
                return 0.0, ["Cycle payload does not include total gas moles."]
            return max(float(moles), 0.0), warnings
        if source_mode == "reactor_pressure":
            delta_psi = self._reaction_dashboard_input_float("reactor_delta_p_psi")
            volume_l = self._reaction_dashboard_input_float(
                "reactor_headspace_volume_l"
            )
            temp_c = self._reaction_dashboard_input_float("reactor_temperature_c")
            if delta_psi is None or volume_l is None:
                return 0.0, ["Provide reactor delta P and headspace volume."]
            temp_k = (temp_c if temp_c is not None else 25.0) + 273.15
            atm = max(delta_psi, 0.0) / 14.6959
            uptake_moles = max(
                (atm * max(volume_l, 0.0)) / (0.082057338 * temp_k),
                0.0,
            )
            return uptake_moles, warnings
        if source_mode == "cylinder_loss":
            start_g = self._reaction_dashboard_input_float("cylinder_start_mass_g")
            end_g = self._reaction_dashboard_input_float("cylinder_end_mass_g")
            if start_g is None or end_g is None or gas_mw <= 0.0:
                return 0.0, ["Provide cylinder start/end masses and gas molar mass."]
            return max(start_g - end_g, 0.0) / gas_mw, warnings
        manual_moles = self._reaction_dashboard_input_float("manual_gas_moles")
        if manual_moles is not None:
            return max(manual_moles, 0.0), warnings
        manual_mass = self._reaction_dashboard_input_float("manual_gas_mass_g")
        if manual_mass is not None and gas_mw > 0.0:
            return max(manual_mass, 0.0) / gas_mw, warnings
        return 0.0, ["Provide manual gas moles or gas mass."]

    def _run_reaction_dashboard(self) -> None:
        """Execute one Reaction Dashboard calculation.

        Purpose:
            Run uptake normalization, linked stoichiometry, yield/completion, and
            optional ChemPy pH calculation for the active template.
        Why:
            Users need one action that turns template + source inputs into clear
            reaction metrics without affecting Advanced Speciation workflows.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Updates result cache, cycle trend payload, KPI labels, table rows,
            warning text, and any already-open Reaction Dashboard plot tab.
        Exceptions:
            Compute errors are surfaced in the dashboard warning label.
        """
        try:
            template = self._reaction_active_template()
            missing_required = self._reaction_dashboard_validate_required_inputs(
                template
            )
            if missing_required:
                self._reaction_warnings_var.set(
                    "Required fields missing or invalid: " + ", ".join(missing_required)
                )
                return
            species_rows, charge_basis = (
                self._reaction_dashboard_species_rows_with_inputs(template)
            )
            raw_step_rows = self._reaction_dashboard_steps_from_editor()
            step_rows, deferred_steps = (
                self._reaction_dashboard_step_rows_for_available_inputs(
                    template, raw_step_rows
                )
            )
            gas_uptake_mol, source_warnings = (
                self._reaction_dashboard_resolve_gas_uptake(template, species_rows)
            )
            actual_mass = self._reaction_dashboard_input_float(
                template.yield_basis.actual_mass_field_id
            )
            core = _run_reaction_dashboard_core(
                species_rows,
                step_rows,
                gas_uptake_mol=gas_uptake_mol,
                gas_species_id=template.gas_species_id,
                yield_species_id=template.yield_basis.product_species_id,
                target_reactant_species_id=(
                    template.yield_basis.target_reactant_species_id
                ),
                actual_yield_mass_g=actual_mass,
            )
            liquid_volume = self._reaction_dashboard_input_float("liquid_volume_l")
            equilibrium = _solve_reaction_dashboard_equilibrium_with_chempy(
                template,
                enabled=bool(self._reaction_ph_enabled_var.get()),
                liquid_volume_l=liquid_volume,
                product_moles=_safe_float(core.get("yield_species_moles")),
            )
            cycle_series = _reaction_dashboard_cycle_metric_series(
                template,
                species_rows,
                step_rows,
                getattr(self, "_cycle_last_transfer_payload", None),
                actual_yield_mass_g=actual_mass,
                ph_enabled=bool(self._reaction_ph_enabled_var.get()),
                liquid_volume_l=liquid_volume,
            )
            result = {
                "template_id": template.template_id,
                "template_name": template.name,
                "source_mode": self._reaction_source_mode_var.get(),
                "core": core,
                "equilibrium": equilibrium,
                "cycle_series": cycle_series
                if self._reaction_source_mode_var.get() == "cycle_payload"
                else [],
                "charge_basis": charge_basis or {},
                "species_rows": species_rows,
                "step_rows": step_rows,
                "deferred_steps": deferred_steps,
                "warnings": list(source_warnings)
                + list((charge_basis or {}).get("warnings") or [])
                + list(core.get("warnings") or [])
                + list(equilibrium.get("warnings") or [])
                + [item["reason"] for item in deferred_steps],
            }
            result["visual_summary"] = _reaction_dashboard_visual_summary(
                template,
                result,
                selected_cycle_id=self._selected_reaction_cycle_focus_id(),
            )
        except Exception as exc:
            self._reaction_warnings_var.set(f"Reaction Dashboard run failed: {exc}")
            return
        self._reaction_dashboard_last_result = result
        # Keep the active record's in-memory audit snapshot current; persistence
        # remains explicit through Save or the existing profile-save workflow.
        active_run = self._ensure_reaction_dashboard_active_run()
        active_run.update(self._reaction_dashboard_current_run_fields())
        active_run["snapshot"] = self._reaction_dashboard_result_snapshot()
        self._render_reaction_dashboard_result(result)
        existing_frame, existing_canvas = self._find_plot_tab_canvas(
            REACTION_DASHBOARD_PLOT_KEY
        )
        if existing_frame is not None and existing_canvas is not None:
            self._refresh_plot_for_plot_id(
                REACTION_DASHBOARD_PLOT_ID,
                reason="Refreshing Reaction Dashboard plot...",
                rearm_overlay=True,
                capture_combined_legend=False,
                force_full_rebuild=False,
            )

    def _render_reaction_dashboard_result(self, result: Mapping[str, Any]) -> None:
        """Render one Reaction Dashboard result payload into the UI.

        Purpose:
            Populate KPI tiles, source/backend context, limiting species, result
            table, and warnings.
        Why:
            Calculation output should be scannable immediately after running.
        Args:
            result: Result mapping from `_run_reaction_dashboard`.
        Returns:
            None.
        Side Effects:
            Mutates StringVars and Treeview rows.
        Exceptions:
            Missing result fields render as placeholders.
        """
        core = result.get("core") if isinstance(result.get("core"), Mapping) else {}
        equilibrium = (
            result.get("equilibrium")
            if isinstance(result.get("equilibrium"), Mapping)
            else {}
        )
        charge_basis = (
            result.get("charge_basis")
            if isinstance(result.get("charge_basis"), Mapping)
            else {}
        )
        template = self._reaction_active_template()
        deferred_steps = [
            dict(item)
            for item in list(result.get("deferred_steps") or [])
            if isinstance(item, Mapping)
        ]
        final_deferred = bool(deferred_steps)

        def _fmt(value: Any, digits: int = 3, suffix: str = "") -> str:
            """Format an optional numeric result for compact KPI display."""
            parsed = _safe_float(value)
            if parsed is None or not math.isfinite(parsed):
                return "--"
            return f"{parsed:.{digits}f}{suffix}"

        self._reaction_kpi_vars["gas_uptake"].set(
            "Reactant gas measured: "
            f"{_fmt(core.get('gas_uptake_mol'), 4)} mol / "
            f"{_fmt(core.get('gas_uptake_g'), 2, ' g')}"
        )
        final_inventory = (
            core.get("final_inventory_mol")
            if isinstance(core.get("final_inventory_mol"), Mapping)
            else {}
        )
        intermediate_species = next(
            (
                species
                for species in template.species
                if str(species.role or "").strip().lower() == "intermediate"
            ),
            None,
        )
        intermediate_moles = (
            _safe_float(final_inventory.get(intermediate_species.species_id))
            if intermediate_species is not None
            else None
        )
        self._reaction_kpi_vars["intermediate"].set(
            "Intermediate balance: "
            f"{_fmt(intermediate_moles, 4)} mol"
        )
        product_value = (
            "deferred"
            if final_deferred
            else _fmt(core.get("theoretical_yield_g"), 2, " g")
        )
        yield_value = (
            "deferred" if final_deferred else _fmt(core.get("actual_yield_pct"), 1, "%")
        )
        completion_value = (
            "deferred" if final_deferred else _fmt(core.get("completion_pct"), 1, "%")
        )
        self._reaction_kpi_vars["product"].set(
            f"Expected product: {product_value}"
        )
        self._reaction_kpi_vars["yield"].set(
            f"Measured yield: {yield_value}"
        )
        self._reaction_kpi_vars["completion"].set(
            f"Reaction completion: {completion_value}"
        )
        self._reaction_kpi_vars["ph"].set(
            f"Equilibrium estimate: {_fmt(equilibrium.get('ph'), 2)}"
        )
        source_label = getattr(self, "_reaction_source_key_to_label", {}).get(
            str(result.get("source_mode") or ""),
            str(result.get("source_mode") or "--"),
        )
        self._reaction_kpi_vars["source_backend"].set(
            f"{source_label}\ncore={core.get('backend', '--')} | "
            f"inputs={charge_basis.get('backend', '--')} | "
            f"pH={equilibrium.get('backend', '--')}"
        )
        limiting_values: List[str] = []
        for step in list(core.get("step_results") or []):
            if not isinstance(step, Mapping):
                continue
            limiting_text = str(
                step.get("limiting_species") or step.get("limiting_species_id") or ""
            ).strip()
            if limiting_text and limiting_text not in limiting_values:
                limiting_values.append(limiting_text)
        self._reaction_kpi_vars["limiting"].set(
            "Limiting material: "
            + ("identified" if limiting_values else "not identified")
        )
        charge_text = (
            "Calculation basis: derived from starting-material entries"
            if charge_basis
            else "Calculation basis: --"
        )
        self._reaction_kpi_vars["charge_basis"].set(charge_text)
        self._reaction_charge_basis_var.set(charge_text)
        self._reaction_backend_var.set(
            f"Backend: core={core.get('backend', '--')} | "
            f"charge={charge_basis.get('backend', '--')} | "
            f"pH={equilibrium.get('backend', '--')}"
        )
        rows = [
            {
                "metric": "Reaction definition",
                "value": result.get("template_name", ""),
                "notes": result.get("template_id", ""),
            },
            {
                "metric": "Gas measurement source",
                "value": result.get("source_mode", ""),
                "notes": "Selected reactant-gas measurement source",
            },
            {
                "metric": "Expected product amount",
                "value": (
                    "deferred"
                    if final_deferred
                    else _fmt(core.get("yield_species_moles"), 6)
                ),
                "notes": "moles",
            },
            {
                "metric": "Expected product mass",
                "value": (
                    "deferred"
                    if final_deferred
                    else _fmt(core.get("theoretical_yield_g"), 3)
                ),
                "notes": "grams",
            },
            {
                "metric": "Measured yield",
                "value": (
                    "deferred"
                    if final_deferred
                    else _fmt(core.get("actual_yield_pct"), 2)
                ),
                "notes": "percent when measured product mass is entered",
            },
            {
                "metric": "Equilibrium pH",
                "value": _fmt(equilibrium.get("ph"), 3),
                "notes": "; ".join(equilibrium.get("warnings") or []),
            },
        ]
        for deferred_step in deferred_steps:
            rows.append(
                {
                    "metric": "Deferred reaction step",
                    "value": "Awaiting required input",
                    "notes": "Enter the highlighted required reaction input to calculate final completion.",
                }
            )
        for step in list(core.get("step_results") or []):
            if not isinstance(step, Mapping):
                continue
            limiting = step.get("limiting_species") or step.get("limiting_species_id")
            rows.append(
                {
                    "metric": str(step.get("name") or step.get("step_id")),
                    "value": _fmt(step.get("extent_mol"), 6),
                    "notes": f"Limiting: {limiting or '--'}",
                }
            )
        tree = getattr(self, "_reaction_results_tree", None)
        if tree is not None:
            tree.delete(*tree.get_children())
            for row in rows:
                tree.insert(
                    "",
                    "end",
                    values=(row["metric"], row["value"], row["notes"]),
                )
        visual_summary = _reaction_dashboard_visual_summary(
            template,
            result,
            selected_cycle_id=self._selected_reaction_cycle_focus_id(),
        )
        if isinstance(result, dict):
            result["visual_summary"] = visual_summary
        self._reaction_dashboard_visual_summary = visual_summary
        self._refresh_reaction_cycle_selector(visual_summary)
        gas_meta = visual_summary.get("gas") or {}
        product_meta = visual_summary.get("product") or {}
        status = str(visual_summary.get("cycle_status") or "unavailable")
        status_color = str(
            visual_summary.get("status_color")
            or REACTION_DASHBOARD_STATUS_COLORS["unavailable"]
        )
        status_label = getattr(self, "_reaction_status_label", None)
        if status_label is not None:
            try:
                status_label.configure(fg=status_color)
            except Exception:
                pass
        selected_cycle = visual_summary.get("selected_cycle_id")
        selected_cycle_float = _safe_float(selected_cycle)
        selected_text = (
            f"Cycle {selected_cycle_float:g}"
            if selected_cycle_float is not None
            else "Latest"
        )
        self._reaction_status_var.set(
            f"{status.title()}: {result.get('template_name', '')} | "
            f"Gas: {gas_meta.get('display', '--')} | Product: {product_meta.get('display', '--')} | "
            f"Focus: {selected_text}"
        )
        self._reaction_next_action_var.set(str(visual_summary.get("next_action") or ""))
        gas_mol = visual_summary.get("headline_gas_consumed_mol")
        gas_g = visual_summary.get("headline_gas_consumed_g")
        product_g = visual_summary.get("headline_product_mass_g")
        product_mol = visual_summary.get("headline_product_mol")
        completion_pct = visual_summary.get("completion_pct")
        self._reaction_kpi_vars["gas_uptake"].set(
            f"{gas_meta.get('display', 'Gas')}\n"
            f"Consumed {_fmt(gas_mol, 4)} mol | required {_fmt(core.get('gas_required_mol'), 4)} mol"
        )
        self._reaction_kpi_vars["product"].set(
            f"Theoretical {product_meta.get('display', 'product')}\n"
            f"{_fmt(product_g, 2, ' g')} / {_fmt(product_mol, 4)} mol"
        )
        self._reaction_kpi_vars["completion"].set(
            f"Completion: {_fmt(completion_pct, 1, '%')}\n"
            f"Trend: {(visual_summary.get('cycle_trend') or {}).get('label', '--')}"
        )
        self._reaction_kpi_vars["limiting"].set(
            f"Limiting: {visual_summary.get('limiting') or '--'}"
        )
        forecast = (
            visual_summary.get("forecast")
            if isinstance(visual_summary.get("forecast"), Mapping)
            else {}
        )
        remaining_cycles = _safe_float(forecast.get("remaining_cycles"))
        remaining_time = _safe_float(forecast.get("remaining_time"))
        average_remaining_cycles = _safe_float(forecast.get("average_remaining_cycles"))
        average_remaining_time = _safe_float(forecast.get("average_remaining_time"))
        time_unit = str(forecast.get("time_unit") or "").strip()
        forecast_note = str(forecast.get("confidence") or "")
        self._reaction_kpi_vars["forecast_cycles"].set(
            "Estimated remaining\n"
            + (f"~{remaining_cycles:.1f} cycles" if remaining_cycles is not None else "--")
        )
        self._reaction_kpi_vars["forecast_time"].set(
            "ETA — recent / all history\n"
            + (
                f"~{remaining_time:.2f} / {average_remaining_time:.2f} {time_unit}"
                if remaining_time is not None
                and average_remaining_time is not None
                and time_unit
                else f"~{remaining_time:.2f} {time_unit}"
                if remaining_time is not None and time_unit
                else "Time basis unavailable; see cycle estimates"
            )
        )
        self._reaction_kpi_vars["forecast_cycles"].set(
            "Remaining cycles — recent / all history\n"
            + (
                f"~{remaining_cycles:.1f} / {average_remaining_cycles:.1f}"
                if remaining_cycles is not None and average_remaining_cycles is not None
                else "--"
            )
        )
        inventory_tree = getattr(self, "_reaction_inventory_tree", None)
        if inventory_tree is not None:
            inventory_tree.delete(*inventory_tree.get_children())
            for row in list(visual_summary.get("material_inventory") or []):
                if not isinstance(row, Mapping):
                    continue
                inventory_tree.insert(
                    "",
                    "end",
                    values=(
                        row.get("material", "--"),
                        row.get("role", "--"),
                        f"{_fmt(row.get('starting_mol'), 4)} mol / {_fmt(row.get('starting_g'), 2, ' g')}",
                        f"{_fmt(row.get('consumed_mol'), 4)} mol",
                        f"{_fmt(row.get('remaining_mol'), 4)} mol / {_fmt(row.get('remaining_g'), 2, ' g')}",
                    ),
                )
        cycle_rows = [
            dict(row)
            for row in list(visual_summary.get("cycle_rows") or [])
            if isinstance(row, Mapping)
        ]
        cycle_tree = getattr(self, "_reaction_cycle_tree", None)
        if cycle_tree is not None:
            cycle_tree.delete(*cycle_tree.get_children())
            for row in cycle_rows:
                status_tag = str(row.get("status") or "watch")
                cycle_tree.insert(
                    "",
                    "end",
                    values=(
                        row.get("cycle_id", ""),
                        _fmt(row.get("gas_delta_mol"), 5),
                        _fmt(row.get("cumulative_gas_mol"), 5),
                        _fmt(row.get("completion_pct"), 1),
                        _fmt(row.get("product_mass_g"), 3),
                        row.get("trend", ""),
                        row.get("warnings", ""),
                    ),
                    tags=(status_tag,),
                )
        self._draw_reaction_completion_gauge(_safe_float(completion_pct), status=status)
        self._draw_reaction_series_chart(
            getattr(self, "_reaction_trend_canvas", None),
            cycle_rows,
            y_key="cumulative_gas_mol",
            title="Cumulative Gas Uptake",
            color=REACTION_DASHBOARD_STATUS_COLORS["neutral"],
        )
        self._draw_reaction_series_chart(
            getattr(self, "_reaction_delta_canvas", None),
            cycle_rows,
            y_key="gas_delta_mol",
            title="Per-Cycle Gas Delta",
            color=REACTION_DASHBOARD_STATUS_COLORS.get(
                (visual_summary.get("cycle_trend") or {}).get("status", "watch"),
                REACTION_DASHBOARD_STATUS_COLORS["watch"],
            ),
        )
        warnings = [
            str(item) for item in list(result.get("warnings") or []) if str(item)
        ]
        if forecast_note and remaining_cycles is None:
            warnings.append(f"Forecast: {forecast_note}")
        self._reaction_warnings_var.set(
            "Warnings: " + "; ".join(warnings) if warnings else "Calculation complete."
        )

    def _build_reaction_dashboard_plot_tab_figure(
        self,
        *,
        mode: str,
        fig_size: Optional[Tuple[float, float]],
    ) -> Optional[Figure]:
        """Build the Reaction Dashboard generated plot-tab figure.

        Purpose:
            Render cycle-derived reaction trends or final static reaction metrics
            into a Matplotlib figure.
        Why:
            Reaction Dashboard plots should share existing generated-tab toolbar,
            refresh, export, and layout behavior.
        Args:
            mode: Render mode selector (`display` or `export`).
            fig_size: Optional target figure size in inches.
        Returns:
            Matplotlib Figure, or None when no calculation exists.
        Side Effects:
            None.
        Exceptions:
            Invalid result payloads return None.
        """
        result = getattr(self, "_reaction_dashboard_last_result", None)
        if not isinstance(result, Mapping):
            return None
        core = result.get("core") if isinstance(result.get("core"), Mapping) else {}
        if not core:
            return None
        size = fig_size or ((11.0, 8.5) if mode == "export" else (9.0, 6.0))
        fig = Figure(figsize=size, dpi=100)
        fig._gl260_plot_id = REACTION_DASHBOARD_PLOT_ID  # type: ignore[attr-defined]
        trace_configs = self._trace_settings_store_for_plot_id(
            REACTION_DASHBOARD_PLOT_ID
        )

        def _trace_style(series_key: str, default_color: str) -> Dict[str, Any]:
            """Return effective style values for one Reaction Dashboard series.

            Purpose:
                Resolve plot-scoped Data Trace Settings into simple bar styling.
            Why:
                Reaction static charts use Matplotlib bars, so they need a small
                adapter around the shared line/scatter style settings.
            Inputs:
                series_key: Reaction trace key such as `reaction_inventory`.
                default_color: Fallback color when no override is configured.
            Outputs:
                Dict with enabled, color, and alpha display values.
            Side Effects:
                None.
            Exceptions:
                Invalid settings fall back through `_get_scatter_config`.
            """
            cfg = _get_scatter_config(
                series_key,
                scatter_series_configs=trace_configs,
            )
            overrides = cfg.get("_overrides", {})
            color = (
                str(cfg.get("color") or "").strip()
                if overrides.get("color")
                else default_color
            )
            return {
                "enabled": cfg.get("_visible_override") is not False,
                "color": color or default_color,
                "alpha": float(cfg.get("alpha", 1.0) or 1.0),
            }

        def _tag_bar_container(container: Any, series_key: str) -> None:
            """Attach trace metadata to bar patches for Plot Elements discovery.

            Purpose:
                Mark static bar artists with the same series keys used by line
                traces.
            Why:
                Plot Elements and Data Trace Settings discover available series
                from rendered artist metadata.
            Inputs:
                container: Matplotlib bar container returned by `bar`/`barh`.
                series_key: Reaction trace key to attach to every patch.
            Outputs:
                None.
            Side Effects:
                Mutates patch metadata on the provided container.
            Exceptions:
                Artist metadata failures are ignored.
            """
            for patch in list(getattr(container, "patches", []) or []):
                try:
                    patch._gl260_series_key = series_key
                except Exception:
                    # Best-effort guard; ignore metadata failures during rendering.
                    pass

        cycle_series = [
            dict(row)
            for row in list(result.get("cycle_series") or [])
            if isinstance(row, Mapping)
        ]
        if cycle_series:
            ax = fig.add_subplot(1, 1, 1)
            ax2 = ax.twinx()
            ax3 = ax.twinx()
            ax._gl260_axis_role = "primary"  # type: ignore[attr-defined]
            ax2._gl260_axis_role = "right"  # type: ignore[attr-defined]
            ax3._gl260_axis_role = "third"  # type: ignore[attr-defined]
            try:
                ax3.spines["right"].set_position(("axes", 1.12))
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            xs = [
                _safe_float(row.get("x"), float(idx)) or float(idx)
                for idx, row in enumerate(cycle_series, start=1)
            ]
            x_label = str(cycle_series[-1].get("x_label") or "Cycle").strip()
            uptake_values = [
                _safe_float(row.get("cumulative_gas_g")) for row in cycle_series
            ]
            uptake_units = "g"
            if not any(
                value is not None and math.isfinite(value) for value in uptake_values
            ):
                uptake_values = [
                    _safe_float(row.get("cumulative_gas_mol"), 0.0)
                    for row in cycle_series
                ]
                uptake_units = "mol"
            completion_values = [
                _safe_float(row.get("completion_pct"), float("nan"))
                for row in cycle_series
            ]
            yield_values = [
                _safe_float(row.get("yield_pct"), float("nan")) for row in cycle_series
            ]
            ph_values = [_safe_float(row.get("ph")) for row in cycle_series]
            product_values = [
                _safe_float(row.get("product_mass_g"), float("nan"))
                for row in cycle_series
            ]
            _plot_series(
                ax,
                xs,
                [
                    value if value is not None else float("nan")
                    for value in uptake_values
                ],
                label=f"Cumulative gas uptake ({uptake_units})",
                color="#2f6f8f",
                zorder=3,
                force_line=True,
                series_key="reaction_uptake",
                scatter_series_configs=trace_configs,
            )
            _plot_series(
                ax2,
                xs,
                [
                    value if value is not None else float("nan")
                    for value in completion_values
                ],
                label="Reaction completion (%)",
                color="#8f3f71",
                zorder=4,
                force_line=True,
                series_key="reaction_completion",
                scatter_series_configs=trace_configs,
            )
            _plot_series(
                ax2,
                xs,
                [
                    value if value is not None else float("nan")
                    for value in yield_values
                ],
                label="Yield estimate (%)",
                color="#5b7f33",
                zorder=4,
                force_line=True,
                series_key="reaction_yield",
                scatter_series_configs=trace_configs,
            )
            if any(value is not None and math.isfinite(value) for value in ph_values):
                _plot_series(
                    ax3,
                    xs,
                    [
                        value if value is not None else float("nan")
                        for value in ph_values
                    ],
                    label="Equilibrium pH",
                    color="#b45f06",
                    zorder=5,
                    force_line=True,
                    series_key="reaction_ph",
                    scatter_series_configs=trace_configs,
                )
                ax3.set_ylabel("Equilibrium pH")
            else:
                _plot_series(
                    ax3,
                    xs,
                    [
                        value if value is not None else float("nan")
                        for value in product_values
                    ],
                    label="Theoretical product (g)",
                    color="#3f5f8f",
                    zorder=5,
                    force_line=True,
                    series_key="reaction_product_mass",
                    scatter_series_configs=trace_configs,
                )
                ax3.set_ylabel("Theoretical product (g)")
            ax.set_xlabel(x_label)
            ax.set_ylabel(f"Cumulative gas uptake ({uptake_units})")
            ax2.set_ylabel("Completion / yield (%)")
            ax2.set_ylim(0.0, 105.0)
            ax.grid(True, alpha=0.28)
            handles: List[Any] = []
            labels: List[str] = []
            for axis in (ax, ax2, ax3):
                axis_handles, axis_labels = axis.get_legend_handles_labels()
                handles.extend(axis_handles)
                labels.extend(axis_labels)
            if handles:
                legend = ax.legend(
                    handles,
                    labels,
                    loc="best",
                    **_legend_shadowbox_kwargs(),
                )
                _make_legend_draggable(legend)
            ax.set_title("Reaction progress by cycle")
            fig.suptitle(str(result.get("template_name") or "Reaction Dashboard"))
            fig.tight_layout(rect=(0.0, 0.0, 0.84, 0.94))
            return fig

        ax_summary = fig.add_subplot(1, 3, 1)
        ax_extent = fig.add_subplot(1, 3, 2)
        ax_inventory = fig.add_subplot(1, 3, 3)
        ax_summary._gl260_axis_role = "primary"  # type: ignore[attr-defined]
        ax_extent._gl260_axis_role = "right"  # type: ignore[attr-defined]
        ax_inventory._gl260_axis_role = "third"  # type: ignore[attr-defined]
        steps = [
            row
            for row in list(core.get("step_results") or [])
            if isinstance(row, Mapping)
        ]
        summary_items = [
            ("Completion", _safe_float(core.get("completion_pct"))),
            ("Yield", _safe_float(core.get("actual_yield_pct"))),
            ("Product g", _safe_float(core.get("theoretical_yield_g"))),
        ]
        summary_labels = [item[0] for item in summary_items]
        summary_values = [item[1] or 0.0 for item in summary_items]
        summary_keys = (
            "reaction_completion",
            "reaction_yield",
            "reaction_product_mass",
        )
        summary_styles = (
            _trace_style("reaction_completion", "#8f3f71"),
            _trace_style("reaction_yield", "#5b7f33"),
            _trace_style("reaction_product_mass", "#3f5f8f"),
        )
        summary_bars = ax_summary.barh(
            summary_labels,
            summary_values,
            color=[style["color"] for style in summary_styles],
        )
        for patch, series_key, style in zip(
            list(summary_bars.patches), summary_keys, summary_styles, strict=False
        ):
            try:
                patch._gl260_series_key = series_key
                patch.set_alpha(style["alpha"])
                patch.set_visible(bool(style["enabled"]))
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        ax_summary.set_title("Final run metrics")
        ax_summary.set_xlabel("Value")
        step_names = [str(row.get("name") or row.get("step_id") or "") for row in steps]
        extents = [_safe_float(row.get("extent_mol"), 0.0) or 0.0 for row in steps]
        extent_style = _trace_style("reaction_extent", "#4c78a8")
        if extent_style["enabled"]:
            extent_bars = ax_extent.barh(
                step_names or ["No steps"],
                extents or [0.0],
                color=extent_style["color"],
                alpha=extent_style["alpha"],
            )
            _tag_bar_container(extent_bars, "reaction_extent")
        ax_extent.set_xlabel("Extent (mol)")
        ax_extent.set_title("Linked reaction extents")
        inventory = (
            core.get("final_inventory_mol")
            if isinstance(core.get("final_inventory_mol"), Mapping)
            else {}
        )
        inv_items = [
            (str(key), _safe_float(value, 0.0) or 0.0)
            for key, value in inventory.items()
            if (_safe_float(value, 0.0) or 0.0) > 1e-12
        ]
        inv_items = sorted(inv_items, key=lambda item: item[1], reverse=True)[:8]
        inventory_style = _trace_style("reaction_inventory", "#59a14f")
        if inventory_style["enabled"]:
            inventory_bars = ax_inventory.bar(
                [item[0] for item in inv_items] or ["No inventory"],
                [item[1] for item in inv_items] or [0.0],
                color=inventory_style["color"],
                alpha=inventory_style["alpha"],
            )
            _tag_bar_container(inventory_bars, "reaction_inventory")
        ax_inventory.set_ylabel("Final inventory (mol)")
        ax_inventory.set_title("Final species inventory")
        ax_inventory.tick_params(axis="x", rotation=45)
        title = str(result.get("template_name") or "Reaction Dashboard")
        fig.suptitle(title)
        fig.tight_layout()
        return fig

    def _open_reaction_dashboard_plot_in_new_tab(self) -> None:
        """Open Reaction Dashboard plot in the generated plot-tab pipeline.

        Purpose:
            Create or refresh the dedicated Reaction Dashboard plot tab.
        Why:
            Users requested plot opening behavior consistent with Advanced
            Speciation generated tabs.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Adds/selects a notebook plot tab or shows a user-facing message.
        Exceptions:
            UI failures are guarded.
        """
        if not isinstance(
            getattr(self, "_reaction_dashboard_last_result", None), Mapping
        ):
            try:
                messagebox.showinfo(
                    "Reaction Dashboard",
                    "Run the Reaction Dashboard before opening a plot tab.",
                )
            except Exception:
                pass
            return
        existing_frame, existing_canvas = self._find_plot_tab_canvas(
            REACTION_DASHBOARD_PLOT_KEY
        )
        if existing_frame is not None and existing_canvas is not None:
            try:
                self.nb.select(existing_frame)
            except Exception:
                pass
            self._refresh_plot_for_plot_id(
                REACTION_DASHBOARD_PLOT_ID,
                reason="Refreshing Reaction Dashboard plot...",
                rearm_overlay=True,
                capture_combined_legend=False,
                force_full_rebuild=False,
            )
            return
        fig = self._build_generated_plot_tab_figure(
            REACTION_DASHBOARD_PLOT_KEY,
            mode="display",
            fig_size=None,
        )
        if fig is None:
            return
        frame = self._add_plot_tab(
            "Reaction Dashboard",
            fig,
            plot_key=REACTION_DASHBOARD_PLOT_KEY,
            plot_id_override=REACTION_DASHBOARD_PLOT_ID,
        )
        try:
            self.nb.select(frame)
        except Exception:
            pass

    def _build_tab_solubility_new(self):
        """Build the solubility modeling tab UI.
        Purpose: Construct the scrollable Advanced Solubility workflow layout.
        Why: Centralize Planning/Analysis/Reprocessing input wiring and defaults.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            - Creates Tk widgets, binds callbacks, and populates solubility state.
            - Records default values and registers observers for input persistence.
        Exceptions:
            - Best-effort; returns early if the tab frame is unavailable.
        """
        frame = getattr(self, "tab_solubility_new", None)
        if frame is None:
            return
        self._initialize_shared_solubility_runtime_state()

        frame.grid_columnconfigure(0, weight=1)
        frame.grid_rowconfigure(0, weight=1)

        # Scrollable canvas: Tkinter requires a canvas window + inner frame so
        # large solubility panels can scroll without nesting full frames.
        container = ttk.Frame(frame)
        container.grid(row=0, column=0, sticky="nsew")
        container.grid_columnconfigure(0, weight=1)
        container.grid_rowconfigure(0, weight=1)

        canvas = tk.Canvas(container, highlightthickness=0)
        canvas.grid(row=0, column=0, sticky="nsew")
        scrollbar = _ui_scrollbar(container, orient="vertical", command=canvas.yview)
        scrollbar.grid(row=0, column=1, sticky="ns")
        canvas.configure(yscrollcommand=scrollbar.set)

        inner = ttk.Frame(canvas)
        window = canvas.create_window((0, 0), window=inner, anchor="nw")
        inner.grid_columnconfigure(0, weight=1)
        self._sol_scroll_canvas = canvas
        self._sol_scroll_inner = inner
        self._sol_scroll_window_id = window

        # Closure captures _build_tab_solubility_new state for callback wiring, kept nested to scope the handler, and invoked by bindings set in _build_tab_solubility_new.
        def _refresh_scroll(_event=None):
            """Refresh scroll.
            Used to sync scroll with current settings."""
            self._refresh_sol_workflow_layout()

        inner.bind("<Configure>", _refresh_scroll)

        # Closure captures _build_tab_solubility_new local context to keep helper logic scoped and invoked directly within _build_tab_solubility_new.
        def _expand_width(event):
            """Perform expand width.
            Used to keep the workflow logic localized and testable."""
            self._refresh_sol_workflow_layout(canvas_width=getattr(event, "width", None))

        canvas.bind("<Configure>", _expand_width)

        # Recursive wheel binding keeps one unified vertical scroll flow for the
        # entire Advanced Speciation tab while still allowing edge-aware handoff
        # from local Text/Tree widgets.
        def _bind_mousewheel(widget):
            """Perform bind mousewheel.
            Used to keep the workflow logic localized and testable."""

            def _scroll_canvas(event: Any) -> Optional[str]:
                """Dispatch wheel scrolling with local-owner edge handoff."""
                return self._dispatch_canvas_mousewheel_with_handoff(
                    event,
                    canvas=canvas,
                    accumulator_attr="_sol_scroll_wheel_remainder",
                )

            widget.bind("<MouseWheel>", _scroll_canvas, add="+")
            widget.bind("<Button-4>", _scroll_canvas, add="+")
            widget.bind("<Button-5>", _scroll_canvas, add="+")
            # Iterate over widget.winfo_children() to apply the per-item logic.
            for child in widget.winfo_children():
                _bind_mousewheel(child)

        self.after_idle(lambda: _bind_mousewheel(inner))

        ttk.Label(
            inner,
            text=(
                "Advanced Speciation & Equilibrium Engine (workflow preview) \u2014 "
                "plan, analyze, and reprocess batches with guided steps."
            ),
            wraplength=900,
            justify="left",
        ).grid(row=0, column=0, sticky="ew", padx=12, pady=(12, 6))

        mode_var = getattr(self, "_sol_mode_var", None)
        if mode_var is None:
            self._sol_mode_var = self._create_persistent_solubility_var(
                "sol_simulation_mode", SOL_DEFAULT_SIM_MODE
            )
            mode_var = self._sol_mode_var
            self._register_solubility_observer(mode_var)

        guidance_box = ttk.LabelFrame(inner, text="Guided Steps")
        guidance_box.grid(row=3, column=0, sticky="ew", padx=12, pady=6)
        guidance_box.grid_columnconfigure(0, weight=1)
        ttk.Label(
            guidance_box,
            textvariable=getattr(
                self,
                "_sol_mode_description_var",
                tk.StringVar(value="Select a simulation basis to view guided steps."),
            ),
            style="Sol.Help.TLabel",
            wraplength=900,
            justify="left",
        ).grid(row=0, column=0, sticky="ew", padx=8, pady=2)
        ttk.Label(
            guidance_box,
            textvariable=getattr(
                self,
                "_sol_mode_assumption_var",
                tk.StringVar(value="Assumptions will appear here."),
            ),
            style="Sol.Help.TLabel",
            wraplength=900,
            justify="left",
        ).grid(row=1, column=0, sticky="ew", padx=8, pady=2)
        self._sol_mode_expectation_var = tk.StringVar(
            value="Expectations will appear here."
        )
        ttk.Label(
            guidance_box,
            textvariable=self._sol_mode_expectation_var,
            style="Sol.Help.TLabel",
            wraplength=900,
            justify="left",
        ).grid(row=2, column=0, sticky="ew", padx=8, pady=2)
        ttk.Label(
            guidance_box,
            textvariable=getattr(
                self,
                "_sol_mode_steps_var",
                tk.StringVar(value="Checklist will appear here."),
            ),
            justify="left",
            wraplength=900,
        ).grid(row=3, column=0, sticky="ew", padx=8, pady=(0, 4))

        workflow_box = ttk.LabelFrame(inner, text="Workflow Inputs")
        workflow_box.grid(row=4, column=0, sticky="ew", padx=12, pady=6)
        workflow_box.grid_columnconfigure(0, weight=1)
        workflow_nb = ttk.Notebook(workflow_box)
        workflow_nb.grid(row=0, column=0, sticky="ew")
        self._sol_workflow_nb = workflow_nb
        workflow_tabs: Dict[str, ttk.Frame] = {}
        self._sol_workflow_tabs = workflow_tabs
        self._sol_temp_source_controls = {}
        self._sol_workflow_tile_layouts = []

        def _new_workflow_tile_layout(
            workflow_key: str,
            parent: ttk.Frame,
            *,
            row: int,
            padx: Tuple[int, int] = (8, 8),
            pady: Tuple[int, int] = (2, 4),
        ) -> Dict[str, Any]:
            """Create one workflow tile host descriptor and grid it into the tab.

            Purpose:
                Provide a shared host + metadata map for responsive tile cards.
            Why:
                Planning/Analysis/Reprocessing cards need centralized layout and
                wraplength refresh handling.
            Inputs:
                workflow_key: Workflow identifier owning this tile host.
                parent: Parent workflow tab/frame.
                row: Grid row where the tile host frame should be placed.
                padx: Horizontal host padding tuple.
                pady: Vertical host padding tuple.
            Outputs:
                Mutable descriptor map containing host/cards/wrap widgets.
            Side Effects:
                - Creates and grids a new host frame.
                - Appends descriptor into `_sol_workflow_tile_layouts`.
            Exceptions:
                None.
            """
            host = ttk.Frame(parent)
            host.grid(
                row=row,
                column=0,
                columnspan=2,
                sticky="ew",
                padx=padx,
                pady=pady,
            )
            host.grid_columnconfigure(0, weight=1)
            host.grid_columnconfigure(1, weight=1)
            layout = {
                "workflow_key": workflow_key,
                "host": host,
                "cards": [],
                "wrap_widgets": [],
            }
            layouts = getattr(self, "_sol_workflow_tile_layouts", [])
            if not isinstance(layouts, list):
                layouts = []
            layouts.append(layout)
            self._sol_workflow_tile_layouts = layouts
            return layout

        def _add_workflow_tile_card(
            layout: Mapping[str, Any],
            *,
            title: str,
            pady: Tuple[int, int] = (0, 0),
        ) -> ttk.LabelFrame:
            """Create one tile card inside a workflow tile host descriptor.

            Purpose:
                Standardize tile card creation for inputs/actions/KPI groups.
            Why:
                Consistent card containers simplify responsive re-grid behavior.
            Inputs:
                layout: Mutable tile-host descriptor map.
                title: Card title text.
                pady: Optional vertical internal padding hint.
            Outputs:
                The created card frame.
            Side Effects:
                Adds the new card to layout descriptor `cards`.
            Exceptions:
                None.
            """
            host = layout.get("host")
            card = ttk.LabelFrame(host, text=title)
            card.grid_columnconfigure(0, weight=1)
            if pady != (0, 0):
                card.grid_rowconfigure(0, pad=sum(pady))
            cards = layout.get("cards")
            if isinstance(cards, list):
                cards.append(card)
            return card

        def _register_wrap_widgets(layout: Mapping[str, Any], widgets: Sequence[Any]) -> None:
            """Append wraplength-managed widgets into one workflow tile layout."""
            wrap_widgets = layout.get("wrap_widgets")
            if not isinstance(wrap_widgets, list):
                return
            for widget in widgets or ():
                if widget is not None:
                    wrap_widgets.append(widget)

        # Closure captures _build_tab_solubility_new local context to keep helper logic scoped and invoked directly within _build_tab_solubility_new.
        def _workflow_input_specs(workflow_key: str):
            """Perform workflow input specs.
            Used to keep the workflow logic localized and testable."""
            workflow_meta = SOL_WORKFLOW_TEMPLATES.get(workflow_key, {})
            guide_mode = workflow_meta.get(
                "guide_mode", workflow_meta.get("mode_key", SOL_DEFAULT_SIM_MODE)
            )
            return _guide_workflow_specs(
                guide_mode,
                include_keys=workflow_meta.get("input_include_keys"),
                extra=workflow_meta.get("input_extra_fields"),
            )

        # Closure captures _build_tab_solubility_new state for callback wiring, kept nested to scope the handler, and invoked by bindings set in _build_tab_solubility_new.
        def _on_workflow_tab_changed(_event=None):
            """Handle workflow tab changed.
            Used as an event callback for workflow tab changed."""
            workflow_key = self._current_solubility_workflow()
            settings["sol_last_workflow"] = workflow_key
            try:
                self._schedule_save_settings()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            state = self._cycle_state_for(workflow_key)
            self._sol_cycle_payload = state.get("payload")
            self._sol_cycle_results = state.get("results")
            try:
                self._sync_workflow_model_state(
                    workflow_key, refresh_ui=True, save=False
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            self._refresh_sol_mode_guidance()
            self._update_cycle_solubility_widgets(
                state.get("results"), workflow_key=workflow_key
            )
            if workflow_key == "Planning":
                self._refresh_planning_model_fields_visibility()
            self._sync_target_slider_from_entry()
            self._refresh_analysis_sticky_action_bar(workflow_key)
            self._sol_output_workspace_update_profile_action_state()
            self._sol_output_workspace_apply_layout(persist_working=True)
            self._sol_workspace_analysis_table_apply_all_widths()
            self._refresh_sol_output_workspace_dense_analytics(
                workflow_key=workflow_key
            )
            self._refresh_sol_workflow_layout()

        workflow_nb.bind("<<NotebookTabChanged>>", _on_workflow_tab_changed)
        self.after_idle(self._refresh_sol_workflow_layout)

        # Closure captures _build_tab_solubility_new local context to keep helper logic scoped and invoked directly within _build_tab_solubility_new.
        def _ensure_sol_var(key: str, default: str = "") -> tk.StringVar:
            """Perform ensure sol var.
            Used to keep the workflow logic localized and testable."""
            vars_map = getattr(self, "_solubility_vars", {})
            var = vars_map.get(key)
            if var is None:
                var = self._create_persistent_solubility_var(key, default)
                vars_map[key] = var
                self._solubility_vars = vars_map
                self._register_solubility_observer(var)
            return var

        # Closure captures _build_tab_solubility_new local context to keep helper logic scoped and invoked directly within _build_tab_solubility_new.
        def _guide_workflow_specs(
            guide_key: str,
            *,
            include_keys: Optional[Sequence[str]] = None,
            extra: Optional[Sequence[Tuple[str, str, bool]]] = None,
        ) -> List[Tuple[str, str, bool]]:
            """Perform guide workflow specs.
            Used to keep the workflow logic localized and testable."""
            include_set = set(include_keys) if include_keys else None
            guide = SOL_MODE_INPUT_GUIDE.get(guide_key, SOL_MODE_INPUT_GUIDE["default"])
            specs: List[Tuple[str, str, bool]] = []
            seen: Set[str] = set()
            # Iterate over guide to apply the per-item logic.
            for spec in guide:
                optional = bool(spec.get("optional", False))
                spec_label = spec.get("label", "Field")
                # Iterate over spec.get("keys", []) to apply the per-item logic.
                for key in spec.get("keys", []):
                    if include_set is not None and key not in include_set:
                        continue
                    if key in seen:
                        continue
                    label = SOL_MODE_FIELD_LABELS.get(key, spec_label)
                    if optional:
                        label = f"{label} (optional)"
                    specs.append((key, label, not optional))
                    seen.add(key)
            if extra:
                # Iterate over extra to apply the per-item logic.
                for key, label, required in extra:
                    if key in seen:
                        continue
                    specs.append((key, label, required))
                    seen.add(key)
            return specs

        # Closure captures _build_tab_solubility_new local context to keep helper logic scoped and invoked directly within _build_tab_solubility_new.
        def _register_planning_field(
            field_id: str,
            frame: ttk.Frame,
            var: tk.Variable,
            entry: ttk.Entry,
        ) -> None:
            """Perform register planning field.
            Used to keep the workflow logic localized and testable."""
            registry = getattr(self, "_planning_field_registry", {})
            registry[field_id] = {"frame": frame, "var": var, "entry": entry}
            self._planning_field_registry = registry

        # Closure captures _build_tab_solubility_new local context to keep helper logic scoped and invoked directly within _build_tab_solubility_new.
        def _build_input_grid(
            parent: ttk.Frame,
            specs: Sequence[Tuple[str, str, bool]],
            *,
            start_row: int = 0,
            workflow_key: Optional[str] = None,
            default_entry_width: int = 14,
            entry_width_overrides: Optional[Mapping[str, int]] = None,
            expand_entry_keys: Optional[Sequence[str]] = None,
            compact_mode: bool = True,
            wrap_widgets: Optional[List[Any]] = None,
        ) -> int:
            """Build input grid.
            Purpose: Create labeled entry rows for workflow-specific inputs.
            Why: Reuse consistent input wiring across Planning/Analysis/Reprocessing tabs.
            Inputs:
                parent (ttk.Frame): Container to receive the input rows.
                specs (Sequence[Tuple[str, str, bool]]): Input key/label/required specs.
                start_row (int): Starting grid row index.
                workflow_key (Optional[str]): Workflow name for default handling.
                default_entry_width (int): Default entry width for compact inputs.
                entry_width_overrides (Optional[Mapping[str, int]]): Per-field width overrides.
                expand_entry_keys (Optional[Sequence[str]]): Keys that should stretch horizontally.
                compact_mode (bool): True for tighter spacing between rows.
            Outputs:
                int: Next row index after the grid is populated.
            Side Effects:
                - Creates Tk widgets and updates self._solubility_field_meta.
                - Applies cached Planning inputs or defaults when appropriate.
            Exceptions:
                - Best-effort; continues when widget construction fails.
            """
            parent.grid_columnconfigure(0, weight=1)
            row_cursor = start_row
            expand_keys = set(expand_entry_keys or ())
            width_overrides = dict(entry_width_overrides or {})
            y_pad = (1, 2) if compact_mode else (2, 4)
            # Iterate over specs to apply the per-item logic.
            for key, label, required in specs:
                row_frame = ttk.Frame(parent)
                row_frame.grid(
                    row=row_cursor,
                    column=0,
                    sticky="ew",
                    padx=8,
                    pady=y_pad,
                )
                row_frame.grid_columnconfigure(1, weight=1 if key in expand_keys else 0)
                label_widget = ttk.Label(
                    row_frame, text=label, style="Sol.FieldLabel.TLabel"
                )
                label_widget.grid(row=0, column=0, sticky="w", padx=(0, 8))
                if isinstance(wrap_widgets, list):
                    wrap_widgets.append(label_widget)
                var = _ensure_sol_var(key)
                entry_width = width_overrides.get(key, default_entry_width)
                entry = _ui_entry(row_frame, textvariable=var, width=entry_width)
                entry.grid(
                    row=0,
                    column=1,
                    sticky="ew" if key in expand_keys else "w",
                    padx=(0, 8),
                )
                default_value = SOL_PLANNING_DEFAULTS.get(key)
                self._record_solubility_default(key, default_value)
                try:
                    current_value = var.get().strip()
                except Exception:
                    current_value = ""
                if workflow_key == "Planning":
                    # Planning runs can rebuild fields; prefer cached values over defaults.
                    cached_inputs = getattr(self, "_planning_input_cache", {}) or {}
                    cached_value = cached_inputs.get(key)
                    if (
                        cached_value is not None
                        and str(cached_value).strip()
                        and not current_value
                    ):
                        var.set(str(cached_value))
                    elif (
                        default_value
                        and not current_value
                        and not getattr(self, "_planning_inputs_persisted", False)
                    ):
                        var.set(default_value)
                elif default_value and not current_value:
                    var.set(default_value)
                self._solubility_field_meta[key] = {
                    "label": label,
                    "required": required,
                    "entry": entry,
                    "frame": row_frame,
                }
                if workflow_key == "Planning":
                    _register_planning_field(key, row_frame, var, entry)
                help_text = SOL_MODE_FIELD_HELP.get(key)
                if help_text:
                    help_widget = ttk.Label(
                        row_frame,
                        text=help_text,
                        style="Sol.FieldHelp.TLabel",
                        wraplength=560,
                        justify="left",
                    )
                    help_widget.grid(
                        row=1,
                        column=0,
                        columnspan=2,
                        sticky="w",
                        pady=(0, 1 if compact_mode else 2),
                    )
                    if isinstance(wrap_widgets, list):
                        wrap_widgets.append(help_widget)
                row_cursor += 1
            return row_cursor

        # Closure captures _build_tab_solubility_new local context to keep helper logic scoped and invoked directly within _build_tab_solubility_new.
        def _insert_temperature_source_section(
            tab: ttk.Frame, workflow_key: str, row_index: int
        ) -> int:
            """Insert per-workflow temperature source controls.

            Purpose:
                Add Manual vs Columns Trace temperature source controls beneath
                workflow input fields.
            Why:
                Workflows need an explicit way to source temperature from either
                the manual temperature entry or Columns-tab trace mappings.
            Inputs:
                tab: Workflow tab frame receiving the controls.
                workflow_key: Workflow identifier (Planning/Analysis/Reprocessing).
                row_index: Grid row where the section should be inserted.
            Outputs:
                int: Next grid row index after inserting the section.
            Side Effects:
                - Creates mode/trace widgets and stores references for refreshes.
                - Initializes persistent source-mode and trace variables.
            Exceptions:
                Best-effort guards avoid interrupting tab construction.
            """
            layout = next(
                (
                    item
                    for item in (getattr(self, "_sol_workflow_tile_layouts", []) or [])
                    if isinstance(item, Mapping)
                    and str(item.get("workflow_key")) == workflow_key
                ),
                None,
            )
            if isinstance(layout, Mapping):
                source_box = _add_workflow_tile_card(layout, title="Temperature Source")
                next_row = row_index
            else:
                source_box = ttk.LabelFrame(tab, text="Temperature Source")
                source_box.grid(
                    row=row_index,
                    column=0,
                    columnspan=2,
                    sticky="ew",
                    padx=8,
                    pady=(2, 4),
                )
                next_row = row_index + 1
            source_box.grid_columnconfigure(2, weight=1)
            mode_var, trace_var = self._ensure_workflow_temp_source_vars(workflow_key)
            mode_label = ttk.Label(source_box, text="Source mode")
            mode_label.grid(
                row=0, column=0, sticky="w", padx=(8, 4), pady=(4, 2)
            )
            _ui_radiobutton(
                source_box,
                text="Manual",
                value=SOL_TEMP_SOURCE_MANUAL,
                variable=mode_var,
                command=lambda key=workflow_key: self._on_sol_temp_source_mode_changed(
                    key
                ),
            ).grid(row=0, column=1, sticky="w", padx=(0, 8), pady=(4, 2))
            _ui_radiobutton(
                source_box,
                text="Columns Trace",
                value=SOL_TEMP_SOURCE_TRACE,
                variable=mode_var,
                command=lambda key=workflow_key: self._on_sol_temp_source_mode_changed(
                    key
                ),
            ).grid(row=0, column=2, sticky="w", padx=(0, 8), pady=(4, 2))
            trace_label = ttk.Label(source_box, text="Trace key")
            trace_label.grid(
                row=1, column=0, sticky="w", padx=(8, 4), pady=(0, 2)
            )
            trace_combo = _ui_combobox(
                source_box,
                textvariable=trace_var,
                state="readonly",
                values=list(SOL_TEMP_TRACE_KEYS),
                width=22,
            )
            trace_combo.grid(row=1, column=1, columnspan=2, sticky="w", padx=(0, 8))
            trace_combo.bind(
                "<<ComboboxSelected>>",
                lambda event, key=workflow_key: self._on_sol_temp_trace_selected(
                    key, event
                ),
            )
            info_var = tk.StringVar(
                value="Manual mode uses the Temperature (°C) input in this workflow."
            )
            info_label = ttk.Label(
                source_box,
                textvariable=info_var,
                style="Sol.FieldHelp.TLabel",
                wraplength=560,
                justify="left",
            )
            info_label.grid(
                row=2,
                column=0,
                columnspan=3,
                sticky="w",
                padx=8,
                pady=(0, 4),
            )
            if isinstance(layout, Mapping):
                _register_wrap_widgets(layout, [mode_label, trace_label, info_label])
            controls = getattr(self, "_sol_temp_source_controls", {})
            controls[workflow_key] = {
                "trace_combo": trace_combo,
                "trace_info_var": info_var,
            }
            self._sol_temp_source_controls = controls
            self._refresh_sol_temperature_source_controls(workflow_key)
            if isinstance(layout, Mapping):
                self._refresh_sol_workflow_tile_layouts()
            return next_row

        # Closure captures _build_tab_solubility_new local context to keep helper logic scoped and invoked directly within _build_tab_solubility_new.
        def _insert_workflow_helper_section(tab, start_row):
            """Perform insert workflow helper section.
            Used to keep the workflow logic localized and testable."""
            row = start_row
            summary_var = getattr(
                self,
                "_sol_helper_summary_var",
                tk.StringVar(value="Select a simulation basis to see required inputs."),
            )
            ttk.Label(
                tab,
                textvariable=summary_var,
                style="Sol.Help.TLabel",
                wraplength=900,
                justify="left",
            ).grid(row=row, column=0, columnspan=2, sticky="ew", padx=8, pady=(4, 2))
            row += 1
            steps_var = getattr(
                self,
                "_sol_helper_steps_var",
                tk.StringVar(value="Checklist will appear after selecting a mode."),
            )
            ttk.Label(
                tab,
                textvariable=steps_var,
                wraplength=900,
                justify="left",
            ).grid(row=row, column=0, columnspan=2, sticky="ew", padx=8, pady=(0, 4))
            row += 1
            prompt_var = getattr(
                self,
                "_sol_prompt_var",
                tk.StringVar(value="Unable to determine prompt status."),
            )
            ttk.Label(
                tab,
                textvariable=prompt_var,
                style="Sol.Help.TLabel",
                wraplength=900,
                justify="left",
            ).grid(row=row, column=0, columnspan=2, sticky="ew", padx=8, pady=(0, 4))
            return row + 1

        def _workflow_spec_lookup(
            workflow_key: str,
        ) -> Dict[str, Tuple[str, bool]]:
            """Build a lookup map of workflow input specs keyed by field id.

            Purpose:
                Support per-tab grouped layouts without duplicating field metadata.
            Why:
                Grouped UI sections still need the canonical label/required flags
                from shared workflow templates.
            Args:
                workflow_key: Workflow identifier.
            Returns:
                Mapping of `{field_key: (label, required)}`.
            Side Effects:
                None.
            Exceptions:
                Unknown keys are omitted by caller-level filtering.
            """
            lookup: Dict[str, Tuple[str, bool]] = {}
            # Iterate over workflow specs to preserve canonical labels and required flags.
            for key, label, required in _workflow_input_specs(workflow_key):
                lookup[key] = (label, required)
            return lookup

        def _workflow_specs_for_keys(
            workflow_key: str, ordered_keys: Sequence[str]
        ) -> List[Tuple[str, str, bool]]:
            """Resolve ordered workflow specs for one grouped section.

            Purpose:
                Convert key-only section definitions into full input specs.
            Why:
                Group builders should remain declarative while preserving shared
                validation/default wiring from `_build_input_grid`.
            Args:
                workflow_key: Workflow identifier.
                ordered_keys: Ordered field keys for one section.
            Returns:
                Ordered `(key, label, required)` tuples for existing fields.
            Side Effects:
                None.
            Exceptions:
                Missing keys are skipped safely.
            """
            lookup = _workflow_spec_lookup(workflow_key)
            resolved: List[Tuple[str, str, bool]] = []
            # Iterate over ordered keys to preserve UX grouping order.
            for key in ordered_keys:
                item = lookup.get(key)
                if item is None:
                    continue
                label, required = item
                resolved.append((key, label, required))
            return resolved

        def _build_grouped_workflow_inputs(
            tab: ttk.Frame,
            *,
            workflow_key: str,
            start_row: int,
            groups: Sequence[Tuple[str, Sequence[str]]],
            default_entry_width: int,
            entry_width_overrides: Optional[Mapping[str, int]] = None,
            expand_entry_keys: Optional[Sequence[str]] = None,
        ) -> int:
            """Build grouped input sections for one workflow tab.

            Purpose:
                Render compact, domain-grouped input sections per workflow.
            Why:
                Each workflow has different operator focus and should not share a
                single wide, one-size-fits-all input block.
            Args:
                tab: Workflow tab container.
                workflow_key: Workflow identifier.
                start_row: Grid row where the first section is placed.
                groups: Ordered `(title, field_keys)` sections.
                default_entry_width: Default compact input width in characters.
                entry_width_overrides: Optional per-field width overrides.
                expand_entry_keys: Optional field keys that should stretch.
            Returns:
                int: Next row index after all grouped sections.
            Side Effects:
                Creates section containers and input rows.
            Exceptions:
                Empty groups are skipped safely.
            """
            layout: Optional[Dict[str, Any]] = None
            # Build each section in order so data entry follows workflow intent.
            for section_title, field_keys in groups:
                specs = _workflow_specs_for_keys(workflow_key, field_keys)
                if not specs:
                    continue
                if layout is None:
                    layout = _new_workflow_tile_layout(
                        workflow_key,
                        tab,
                        row=start_row,
                        padx=(8, 8),
                        pady=(2, 4),
                    )
                section = _add_workflow_tile_card(layout, title=section_title)
                _build_input_grid(
                    section,
                    specs,
                    start_row=0,
                    workflow_key=workflow_key,
                    default_entry_width=default_entry_width,
                    entry_width_overrides=entry_width_overrides,
                    expand_entry_keys=expand_entry_keys,
                    compact_mode=True,
                    wrap_widgets=layout.get("wrap_widgets"),
                )
            if layout is None:
                return start_row
            self._refresh_sol_workflow_tile_layouts()
            return start_row + 1

        available_models = list_speciation_models()
        if not available_models:
            available_models = [get_speciation_model(None)]
        self._workflow_model_display_map = OrderedDict(
            (f"{model.label} [{model.key}]", model.key) for model in available_models
        )
        self._workflow_model_vars = {}
        cycle_timeline_title_var = self._ensure_cycle_timeline_title_var()

        # Closure captures _build_tab_solubility_new local context to keep helper logic scoped and invoked directly within _build_tab_solubility_new.
        def _build_workflow_models_frame(parent: ttk.Frame, workflow_key: str) -> None:
            """Build workflow models frame.
            Used to assemble workflow models frame during UI or plot setup."""
            model_frame = ttk.LabelFrame(parent, text="Workflow Models")
            model_frame.grid(
                row=0, column=0, columnspan=2, sticky="ew", padx=8, pady=(6, 4)
            )
            model_frame.grid_columnconfigure(1, weight=1)
            spec_attr, ph_attr, use_attr = self._workflow_model_attribute_keys(
                workflow_key
            )
            spec_key = getattr(self, spec_attr, DEFAULT_SPEC_MODEL_KEY)
            ph_key = getattr(self, ph_attr, spec_key)
            spec_label = self._workflow_model_label_for_key(spec_key)
            ph_label = self._workflow_model_label_for_key(ph_key)
            spec_var = tk.StringVar(value=spec_label)
            ph_var = tk.StringVar(value=ph_label)
            use_same_var = tk.BooleanVar(value=bool(getattr(self, use_attr, True)))
            ttk.Label(model_frame, text="Speciation model").grid(
                row=0, column=0, sticky="w", padx=(8, 6), pady=2
            )
            spec_combo = _ui_combobox(
                model_frame,
                textvariable=spec_var,
                values=list(self._workflow_model_display_map.keys()),
                state="readonly",
                width=40,
            )
            spec_combo.grid(row=0, column=1, sticky="ew", padx=(0, 8), pady=2)
            spec_combo.bind(
                "<<ComboboxSelected>>",
                lambda event, key=workflow_key: self._on_select_workflow_spec_model(
                    key, event
                ),
            )
            _ui_checkbutton(
                model_frame,
                text="Use same model for speciation and predicted pH",
                variable=use_same_var,
                command=lambda key=workflow_key: self._toggle_workflow_same_model(key),
            ).grid(row=1, column=0, columnspan=2, sticky="w", padx=8, pady=(2, 4))
            ph_frame = ttk.Frame(model_frame)
            ph_frame.grid(
                row=2, column=0, columnspan=2, sticky="ew", padx=8, pady=(0, 2)
            )
            ph_frame.grid_columnconfigure(1, weight=1)
            ttk.Label(ph_frame, text="Predicted pH model").grid(
                row=0, column=0, sticky="w", padx=(0, 6), pady=2
            )
            ph_combo = _ui_combobox(
                ph_frame,
                textvariable=ph_var,
                values=list(self._workflow_model_display_map.keys()),
                state="readonly",
                width=40,
            )
            ph_combo.grid(row=0, column=1, sticky="ew", padx=(0, 8), pady=2)
            ph_combo.bind(
                "<<ComboboxSelected>>",
                lambda event, key=workflow_key: self._on_select_workflow_ph_model(
                    key, event
                ),
            )
            self._workflow_model_vars[workflow_key] = {
                "spec_var": spec_var,
                "ph_var": ph_var,
                "use_same_var": use_same_var,
                "ph_frame": ph_frame,
            }
            self._sync_workflow_model_state(workflow_key, refresh_ui=True, save=True)

        planning_tab = ttk.Frame(workflow_nb)
