        def _bind_workspace_wheel(widget: Any) -> None:
            """Bind workspace wheel routing with local-owner edge handoff."""

            def _scroll_workspace(event: Any) -> Optional[str]:
                """Dispatch one wheel event to local owner or workspace canvas."""
                return self._dispatch_canvas_mousewheel_with_handoff(
                    event,
                    canvas=workspace_canvas,
                    accumulator_attr="_sol_output_workspace_wheel_remainder",
                )

            try:
                widget.bind("<MouseWheel>", _scroll_workspace, add="+")
                widget.bind("<Button-4>", _scroll_workspace, add="+")
                widget.bind("<Button-5>", _scroll_workspace, add="+")
            except Exception:
                return
            try:
                children = list(widget.winfo_children())
            except Exception:
                children = []
            for child in children:
                _bind_workspace_wheel(child)

        def _create_workspace_panel(panel_id: str, title: str) -> ttk.Frame:
            """Create one draggable/resizable panel shell inside workspace canvas."""
            panel_shell = ttk.Frame(workspace_inner, borderwidth=1, relief="groove")
            panel_shell.grid_columnconfigure(0, weight=1)
            panel_shell.grid_rowconfigure(1, weight=1)
            header = ttk.Frame(panel_shell)
            header.grid(row=0, column=0, sticky="ew", padx=6, pady=(4, 2))
            header.grid_columnconfigure(0, weight=1)
            ttk.Label(header, text=title, style="Sol.FieldLabel.TLabel").grid(
                row=0, column=0, sticky="w"
            )
            hint_text = "Drag in Edit layout mode"
            hint_label = ttk.Label(
                header,
                text=hint_text,
                style="Sol.FieldHelp.TLabel",
            )
            hint_label.grid(row=0, column=1, sticky="e")
            hints = getattr(self, "_sol_output_workspace_panel_hints", {})
            if isinstance(hints, dict):
                hints[panel_id] = hint_label
            default_hints = getattr(
                self, "_sol_output_workspace_panel_hint_default_text", {}
            )
            if isinstance(default_hints, dict):
                default_hints[panel_id] = hint_text
            body = ttk.Frame(panel_shell)
            body.grid(row=1, column=0, sticky="nsew", padx=6, pady=(0, 2))
            body.grid_columnconfigure(0, weight=1)
            body.grid_rowconfigure(0, weight=1)
            resize_label = ttk.Label(panel_shell, text="Resize")
            resize_label.grid(row=2, column=0, sticky="e", padx=6, pady=(0, 4))
            header.bind(
                "<ButtonPress-1>",
                lambda event, pid=panel_id: self._sol_output_workspace_begin_interaction(
                    pid, event, mode="drag"
                ),
                add="+",
            )
            header.bind(
                "<B1-Motion>",
                self._sol_output_workspace_update_interaction,
                add="+",
            )
            header.bind(
                "<ButtonRelease-1>",
                self._sol_output_workspace_end_interaction,
                add="+",
            )
            resize_label.bind(
                "<ButtonPress-1>",
                lambda event, pid=panel_id: self._sol_output_workspace_begin_interaction(
                    pid, event, mode="resize"
                ),
                add="+",
            )
            resize_label.bind(
                "<B1-Motion>",
                self._sol_output_workspace_update_interaction,
                add="+",
            )
            resize_label.bind(
                "<ButtonRelease-1>",
                self._sol_output_workspace_end_interaction,
                add="+",
            )
            self._sol_output_workspace_panels[panel_id] = panel_shell
            return body

