    def _refresh_sol_model_info(self) -> None:
        """Refresh sol model info.
        Used to sync sol model info with current settings."""

        info_var = getattr(self, "_sol_model_info_var", None)
        if info_var is None:
            return
        try:
            model = get_speciation_model(getattr(self, "_sol_model_key", None))
        except KeyError:
            model = get_speciation_model(None)
        meta = getattr(model, "metadata", None)
        temperature_c = None
        params = (
            getattr(self, "_sol_last_form_data", {}).get("params")
            if getattr(self, "_sol_last_form_data", None)
            else None
        )
        if params is not None:
            temperature_c = params.temperature_c
        result = getattr(self, "_sol_last_result", None)
        ionic_strength = getattr(result, "ionic_strength", None) if result else None
        details = [model.description.strip()]
        warnings: List[str] = []
        if meta:
            details.append(f"Reference: {meta.reference}.")
            temp_range = getattr(meta, "temperature_range_c", None)
            if temp_range:
                details.append(
                    f"Valid between {temp_range[0]:.0f}-{temp_range[1]:.0f} Â°C."
                )
                if temperature_c is not None and not (
                    temp_range[0] <= temperature_c <= temp_range[1]
                ):
                    warnings.append(
                        f"Temperature {temperature_c:.1f} Â°C outside validated range."
                    )
            ionic_limit = getattr(meta, "ionic_strength_limit", None)
            if ionic_limit is not None:
                details.append(f"Ionic strength capped at {ionic_limit:.2f} M.")
                if ionic_strength is not None and ionic_strength > ionic_limit:
                    warnings.append(
                        f"Ionic strength {ionic_strength:.3f} M exceeds the model limit."
                    )
            notes = getattr(meta, "notes", "")
            if notes:
                details.append(notes.strip())
        info_text = " ".join(details)
        if warnings:
            info_text = f"{info_text} Warnings: {'; '.join(warnings)}"
        info_var.set(info_text)

    def _cycle_preserved_entries_and_total(
        self, *, prefix: str = CYCLE_TRACKER_NOTE_PREFIX
    ) -> Tuple[List[Dict[str, Any]], float]:
        """Perform cycle preserved entries and total.
        Used to keep the workflow logic localized and testable."""
        existing_entries = list(getattr(self, "_sol_tracking_entries", []))
        preserved = [
            record
            # Iterate to apply the per-item logic.
            for record in existing_entries
            if prefix not in str(record.get("notes", ""))
        ]
        running_total = 0.0
        # Iterate over preserved to apply the per-item logic.
        for record in preserved:
            val = _safe_float(record.get("co2_g"))
            if val is not None and math.isfinite(val):
                running_total = max(running_total, float(val))
        return preserved, running_total

    def _build_cycle_entries_from_payload(
        self,
        payload: Optional[Dict[str, Any]],
        *,
        starting_total: float = 0.0,
        timestamp: str,
        gas_molar_mass: Optional[float] = None,
        prefix: str = CYCLE_TRACKER_NOTE_PREFIX,
    ) -> Tuple[List[Dict[str, Any]], float]:
        """Build cycle entries from payload.
        Used to assemble cycle entries from payload during UI or plot setup."""
        if not payload:
            return [], starting_total
        running_total = float(starting_total or 0.0)
        try:
            gas_molar_mass = float(
                gas_molar_mass
                or payload.get("gas_molar_mass")
                or DEFAULT_GAS_MOLAR_MASS
            )
            if not math.isfinite(gas_molar_mass) or gas_molar_mass <= 0:
                raise ValueError
        except Exception:
            gas_molar_mass = DEFAULT_GAS_MOLAR_MASS
        entries: List[Dict[str, Any]] = []
        cycles = payload.get("cycle_transfer") or []
        # Iterate over indexed elements from cycles, 1 to apply the per-item logic.
        for idx, cycle in enumerate(cycles, 1):
            cycle_id = cycle.get("cycle_id", idx)
            mass = _safe_float(cycle.get("selected_mass_g"))
            if mass is None:
                mass = _safe_float(cycle.get("co2_mass_g"))
            if mass is None:
                moles_val = _safe_float(
                    cycle.get("selected_moles") or cycle.get("co2_moles")
                )
                if moles_val is not None and math.isfinite(moles_val):
                    mass = moles_val * gas_molar_mass
            if mass is None or not math.isfinite(mass) or mass <= 0:
                continue
            cumulative_mass = _safe_float(cycle.get("cumulative_co2_mass_g"))
            if cumulative_mass is not None and math.isfinite(cumulative_mass):
                running_total = float(cumulative_mass)
            else:
                running_total += float(mass)
            cycle_moles = _safe_float(
                cycle.get("selected_moles") or cycle.get("co2_moles")
            )
            deltaP = _safe_float(cycle.get("delta_pressure_psi") or cycle.get("deltaP"))
            temp_c = _safe_float(cycle.get("mean_temperature_c"))
            basis = cycle.get("moles_basis")
            note_parts = [prefix, f"Cycle {cycle_id}"]
            if deltaP is not None and math.isfinite(deltaP):
                note_parts.append(f"DeltaP {deltaP:.2f} PSI")
            if temp_c is not None and math.isfinite(temp_c):
                note_parts.append(f"T {temp_c:.1f} C")
            if basis:
                note_parts.append(f"Basis {basis}")
            entries.append(
                {
                    "timestamp": timestamp,
                    "co2_g": float(running_total),
                    "ph": None,
                    "notes": " | ".join(note_parts),
                    "cycle_id": cycle_id,
                    "cycle_mass_g": float(mass),
                    "cycle_moles": (
                        float(cycle_moles)
                        if cycle_moles is not None and math.isfinite(cycle_moles)
                        else None
                    ),
                    "delta_pressure_psi": deltaP,
                    "temperature_c": temp_c,
                    "basis": basis,
                }
            )
        return entries, running_total

    def _send_cycles_to_speciation_engine(self) -> None:
        """Perform send cycles to speciation engine.
        Used to keep the workflow logic localized and testable."""
        payload = getattr(self, "_cycle_last_transfer_payload", None)
        success = self._apply_cycle_payload_to_solubility(
            payload=payload,
            notify=True,
            run_simulation=False,
            workflow_key="Analysis",
        )
        if not success:
            return
        self._select_sol_workflow_tab("Analysis")
        self._run_analysis_scenario(skip_apply=True, action="run_analysis")

    def _send_cycles_to_reaction_tracker(self) -> None:
        """Perform send cycles to reaction tracker.
        Used to keep the workflow logic localized and testable."""
        payload = getattr(self, "_cycle_last_transfer_payload", None)
        if not payload:
            try:
                messagebox.showinfo(
                    "Cycle Analysis",
                    "Run Cycle Analysis before sending cycles to the Reaction Progress tracker.",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        cycles = payload.get("cycle_transfer") or []
        if not cycles:
            try:
                messagebox.showwarning(
                    "Cycle Analysis",
                    "No per-cycle data available. Re-run Cycle Analysis to refresh the transfer payload.",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        gas_molar_mass = payload.get("gas_molar_mass") or DEFAULT_GAS_MOLAR_MASS
        try:
            gas_molar_mass = float(gas_molar_mass)
            if not math.isfinite(gas_molar_mass) or gas_molar_mass <= 0:
                raise ValueError
        except Exception:
            gas_molar_mass = DEFAULT_GAS_MOLAR_MASS
        timestamp = payload.get("timestamp")
        if timestamp:
            try:
                timestamp = datetime.fromisoformat(str(timestamp)).strftime(
                    "%Y-%m-%d %H:%M"
                )
            except Exception:
                timestamp = str(timestamp)
        if not timestamp:
            timestamp = datetime.now().strftime("%Y-%m-%d %H:%M")
        preserved_entries, running_total = self._cycle_preserved_entries_and_total()
        imported_entries, _ = self._build_cycle_entries_from_payload(
            payload,
            starting_total=running_total,
            timestamp=timestamp,
            gas_molar_mass=gas_molar_mass,
        )
        if not imported_entries:
            try:
                messagebox.showwarning(
                    "Cycle Analysis",
                    "Unable to derive CO2 mass for any cycles. Check the analysis results.",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        combined = preserved_entries + imported_entries
        self._sol_tracking_entries = combined
        self._apply_sol_tracking_entries_to_structured()
        self._select_advanced_solubility_tab()
        try:
            messagebox.showinfo(
                "Cycle Analysis",
                f"{len(imported_entries)} cycle entries sent to the Reaction Progress tracker.",
            )
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _apply_cycle_payload_to_solubility(
        self,
        *,
        payload: dict[str, Any] | None = None,
        notify: bool = False,
        run_simulation: bool = True,
        workflow_key: str | None = None,
    ) -> bool:
        """Apply cycle payload to solubility.
        Purpose: Transfer Cycle Analysis payload data into solubility inputs/tracking.
        Why: Keep Analysis/Planning/Reprocessing workflows synchronized with cycle runs.
        Inputs:
            payload (dict[str, Any] | None): Cycle payload to apply (None uses last).
            notify (bool): When True, show user notifications for applied transfers.
            run_simulation (bool): When True, run the cycle simulation after applying.
            workflow_key (str | None): Target workflow key (None uses current).
        Outputs:
            bool: True if payload was applied; False if payload was missing/invalid.
        Side Effects:
            - Updates solubility Tk variables and cycle tracking state.
            - Stores payloads for the target workflow.
            - May trigger simulations or refresh cycle views.
        Exceptions:
            - Best-effort; handles notification/UI failures without raising.
        """
        payload = payload or getattr(self, "_cycle_last_transfer_payload", None)
        if not payload:
            if notify:
                try:
                    messagebox.showinfo(
                        "Cycle Analysis",
                        "Run Cycle Analysis before sending results "
                        "to Advanced Solubility.",
                    )
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the
                    # workflow.
                    pass
            return False
        workflow = workflow_key or self._current_solubility_workflow()

        moles = payload.get("total_moles_vdw")
        if moles is None:
            moles = payload.get("total_moles_ideal")
        gas_molar_mass = payload.get("gas_molar_mass") or DEFAULT_GAS_MOLAR_MASS
        if moles is None or gas_molar_mass is None:
            if notify:
                try:
                    messagebox.showwarning(
                        "Cycle Analysis",
                        "Unable to determine CO2 mass from the last run.",
                    )
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the
                    # workflow.
                    pass
            return False

        try:
            co2_g = float(moles) * float(gas_molar_mass)
        except Exception:
            co2_g = 0.0

        co2_autofilled = False
        target_var = self._solubility_vars.get("reaction_co2_charged_g")
        if target_var is not None:
            target_var.set(f"{co2_g:.2f}")
            co2_autofilled = True

        reaction_naoh_var = self._solubility_vars.get("reaction_naoh_mass_g")
        planning_naoh_var = self._solubility_vars.get("mass_naoh_g")
        if reaction_naoh_var is not None and planning_naoh_var is not None:
            try:
                naoh_value = float(reaction_naoh_var.get())
            except Exception:
                naoh_value = None
            if naoh_value is not None and math.isfinite(naoh_value) and naoh_value > 0:
                try:
                    planning_value = planning_naoh_var.get()
                except Exception:
                    planning_value = ""
                planning_str = "" if planning_value is None else str(planning_value)
                # Planning: do not overwrite user-entered NaOH mass after a run.
                if workflow != "Planning" or not planning_str.strip():
                    planning_naoh_var.set(f"{naoh_value:.4f}")

        timestamp = payload.get("timestamp")
        if timestamp:
            try:
                timestamp = datetime.fromisoformat(str(timestamp)).strftime(
                    "%Y-%m-%d %H:%M"
                )
            except Exception:
                timestamp = str(timestamp)
        if not timestamp:
            timestamp = datetime.now().strftime("%Y-%m-%d %H:%M")

        entry = {
            "timestamp": timestamp,
            "co2_g": co2_g,
            "ph": None,
            "notes": "Imported from Cycle Analysis",
        }
        preserved_entries, running_total = self._cycle_preserved_entries_and_total()
        imported_entries, _ = self._build_cycle_entries_from_payload(
            payload,
            starting_total=running_total,
            timestamp=timestamp,
            gas_molar_mass=gas_molar_mass,
        )
        if not imported_entries:
            if notify:
                try:
                    messagebox.showwarning(
                        "Cycle Analysis",
                        "Unable to derive CO2 mass for any cycles. "
                        "Check the analysis results.",
                    )
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the
                    # workflow.
                    pass
            return False

        combined = preserved_entries + imported_entries + [entry]
        self._sol_tracking_entries = combined
        self._apply_sol_tracking_entries_to_structured()
        self._select_advanced_solubility_tab()
        self._set_cycle_payload_for_workflow(workflow, payload)
        if run_simulation:
            self._run_cycle_solubility_simulation(
                payload=payload, notify=notify, workflow_key=workflow
            )
        elif workflow == self._current_solubility_workflow():
            self._refresh_cycle_views()
        if notify:
            try:
                messagebox.showinfo(
                    "Cycle Analysis",
                    f"{len(imported_entries)} cycle entries sent to the "
                    "Reaction Progress tracker.",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            if co2_autofilled:
                try:
                    messagebox.showinfo(
                        "Cycle Analysis",
                        f"Estimated {co2_g:.2f} g CO2 sent to Advanced Solubility.",
                    )
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the
                    # workflow.
                    pass
        return True

    def _send_cycle_to_solubility(self) -> None:
        """Import the latest cycle payload into Analysis and run selected options.

        Purpose:
            Transfer cycle-analysis results into the Advanced Speciation Analysis
            workflow and immediately dispatch the consolidated Analysis run path.
        Why:
            Import-triggered runs should honor the same relearn/ML/global-learning
            options as the primary Run Analysis button.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Applies the cycle payload, selects the Analysis tab, persists run
            options, and starts one Analysis workflow run.
        Exceptions:
            Downstream apply/run handlers present best-effort UI errors.
        """
        payload = getattr(self, "_cycle_last_transfer_payload", None)
        success = self._apply_cycle_payload_to_solubility(
            payload=payload,
            notify=True,
            run_simulation=False,
            workflow_key="Analysis",
        )
        if not success:
            return
        self._select_sol_workflow_tab("Analysis")
        option_state = self._analysis_run_option_state()
        self._on_analysis_run_option_changed()
        self._run_analysis_scenario(
            skip_apply=True,
            action=(
                "recompute_calibration"
                if bool(option_state["relearn_calibration"])
                else "run_analysis"
            ),
        )

    def _analysis_run_option_state(self) -> Dict[str, bool]:
        """Return normalized Analysis run option checkbox state.

        Purpose:
            Collect the consolidated Analysis run controls into one payload.
        Why:
            The single Run Analysis button needs deterministic dispatch settings
            without repeating Tk variable reads in each callback.
        Inputs:
            None.
        Outputs:
            Dict[str, bool]: Refresh, relearn, compatible-learning, and ML-apply
            flags for the next Analysis run.
        Side Effects:
            None.
        Exceptions:
            Invalid or unavailable Tk variables fall back to persisted defaults.
        """

        def _bool_var_value(
            attr_name: str,
            settings_key: str,
            default: bool,
        ) -> bool:
            """Read one optional BooleanVar with a settings-backed fallback."""
            var = getattr(self, attr_name, None)
            if isinstance(var, tk.BooleanVar):
                try:
                    return bool(var.get())
                except Exception:
                    pass
            return bool(self.settings.get(settings_key, default))

        return {
            "refresh_cycle_payload": _bool_var_value(
                "_analysis_refresh_cycle_payload_var",
                ANALYSIS_REFRESH_CYCLE_PAYLOAD_DEFAULT_SETTINGS_KEY,
                True,
            ),
            "relearn_calibration": _bool_var_value(
                "_analysis_relearn_calibration_var",
                ANALYSIS_RELEARN_CALIBRATION_DEFAULT_SETTINGS_KEY,
                True,
            ),
            "use_compatible_learning": _bool_var_value(
                "_speciation_anchor_learning_enabled_var",
                ANALYSIS_ANCHOR_LEARNING_ENABLED_SETTINGS_KEY,
                True,
            ),
            "apply_ml_correction": _bool_var_value(
                "_analysis_apply_ml_correction_var",
                ANALYSIS_APPLY_ML_CORRECTION_DEFAULT_SETTINGS_KEY,
                True,
            ),
        }

    def _on_analysis_run_option_changed(self) -> None:
        """Persist consolidated Analysis run option checkbox state.

        Purpose:
            Keep Analysis run options synchronized with settings immediately.
        Why:
            Users expect the single Run Analysis path to restore the same selected
            options across tab rebuilds and application restarts.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Updates settings keys and schedules a best-effort settings save.
        Exceptions:
            Settings-save failures are ignored to preserve UI responsiveness.
        """
        option_state = self._analysis_run_option_state()
        self.settings[ANALYSIS_REFRESH_CYCLE_PAYLOAD_DEFAULT_SETTINGS_KEY] = bool(
            option_state["refresh_cycle_payload"]
        )
        self.settings[ANALYSIS_RELEARN_CALIBRATION_DEFAULT_SETTINGS_KEY] = bool(
            option_state["relearn_calibration"]
        )
        self.settings[ANALYSIS_ANCHOR_LEARNING_ENABLED_SETTINGS_KEY] = bool(
            option_state["use_compatible_learning"]
        )
        self.settings[ANALYSIS_APPLY_ML_CORRECTION_DEFAULT_SETTINGS_KEY] = bool(
            option_state["apply_ml_correction"]
        )
        try:
            self._schedule_save_settings()
        except Exception:
            # Best-effort guard; option changes should not interrupt the UI.
            pass

    def _run_analysis_with_selected_options(self) -> None:
        """Run Analysis using the consolidated checkbox option state.

        Purpose:
            Replace separate run/recompute buttons with one option-driven action.
        Why:
            Analysis execution should be straightforward while still allowing
            operators to choose refresh, relearn, compatible-learning, and ML
            correction behavior.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Persists option state, selects Analysis, and dispatches one Analysis
            workflow run with the requested calibration semantics.
        Exceptions:
            Downstream run errors are handled by `_run_analysis_scenario`.
        """
        option_state = self._analysis_run_option_state()
        self._on_analysis_run_option_changed()
        action = (
            "recompute_calibration"
            if bool(option_state["relearn_calibration"])
            else "run_analysis"
        )
        self._run_analysis_scenario(
            skip_apply=not bool(option_state["refresh_cycle_payload"]),
            action=action,
        )

    def _recompute_analysis_uptake_calibration(self) -> None:
        """Re-run Analysis with measured-pH uptake calibration enabled.

        Purpose:
            Provide an explicit operator action to recompute calibration from the
            current measured-pH anchor/profile state.
        Why:
            Operators may update inputs and want deterministic recalculation
            without waiting for another workflow-triggered run.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Triggers one Analysis run and refreshes timeline/dashboard outputs.
        Exceptions:
            Best-effort guard keeps UI responsive if recompute dispatch fails.
        """
        if self._current_solubility_workflow() != "Analysis":
            self._select_sol_workflow_tab("Analysis")
        try:
            self._run_analysis_scenario(
                skip_apply=True,
                action="recompute_calibration",
            )
        except Exception as exc:
            try:
                messagebox.showerror(
                    "Analysis Calibration",
                    f"Unable to recompute uptake calibration.\n{exc}",
                )
            except Exception:
                pass

    def _on_analysis_apply_ml_toggle_changed(self) -> None:
        """Persist Analysis ML-apply toggle state for current and future runs.

        Purpose:
            Keep the per-run ML-correction apply preference synchronized between
            Analysis controls UI, settings persistence, and form snapshots.
        Why:
            Operators need one intuitive switch for whether ML-corrected pH is
            applied to the active Analysis run.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Updates persisted settings and schedules best-effort settings save.
        Exceptions:
            Settings-save failures are ignored to preserve UI responsiveness.
        """
        toggle_var = getattr(self, "_analysis_apply_ml_correction_var", None)
        enabled = True
        if isinstance(toggle_var, tk.BooleanVar):
            try:
                enabled = bool(toggle_var.get())
            except Exception:
                enabled = True
        self.settings[ANALYSIS_APPLY_ML_CORRECTION_DEFAULT_SETTINGS_KEY] = bool(enabled)
        try:
            self._schedule_save_settings()
        except Exception:
            pass

    def _import_cycle_to_reprocessing(self) -> None:
        """Import cycle to reprocessing.
        Used to ingest cycle to reprocessing into the application."""
        payload = getattr(self, "_cycle_last_transfer_payload", None)
        success = self._apply_cycle_payload_to_solubility(
            payload=payload,
            notify=True,
            run_simulation=False,
            workflow_key="Reprocessing",
        )
        if not success:
            return
        self._select_sol_workflow_tab("Reprocessing")
        self._run_reprocessing_scenario()
        self._run_cycle_solubility_simulation(
            payload=payload, notify=False, workflow_key="Reprocessing"
        )

    def _run_cycle_solubility_simulation(
        self,
        payload: Optional[Dict[str, Any]] = None,
        *,
        notify: bool = False,
        workflow_key: Optional[str] = None,
        loading_session_id: Optional[int] = None,
    ) -> None:
        """Run cycle solubility simulation.
        Purpose:
            Execute cycle-by-cycle speciation simulation for the active workflow.
        Why:
            Timeline table/plot rendering depends on cycle-resolved compute output.
        Inputs:
            payload: Optional prebuilt cycle payload to simulate.
            notify: When True, shows success/failure dialogs for this run.
            workflow_key: Optional explicit workflow override.
            loading_session_id: Optional active solubility loading session id to
                join so overlay teardown waits for timeline readiness.
        Outputs:
            None.
        Side Effects:
            Submits background cycle simulation work, updates per-workflow cycle
            state, updates timeline widgets, and updates loading-overlay stages.
        Exceptions:
            Validation and compute errors are surfaced in status text/dialogs and
            guarded so UI execution continues.
        """
        workflow = workflow_key or self._current_solubility_workflow()
        treat_excess_as_headspace = workflow == "Planning"
        payload = payload or self._get_cycle_payload_for_workflow(workflow)
        status_var = getattr(self, "_sol_cycle_status_var", None)
        self._ensure_rust_backend_for_workflow(status_var=status_var)
        if payload is None:
            if status_var is not None:
                status_var.set("No cycle dataset available. Run Cycle Analysis first.")
            return
        cycles = payload.get("cycle_transfer") or []
        if not cycles:
            if status_var is not None:
                status_var.set("Cycle payload did not include per-cycle data.")
            return
        planning_measured_note: Optional[str] = None
        try:
            form_data = getattr(self, "_sol_last_form_data", None)
            if form_data is None:
                form_data = self._collect_solubility_form_data()
                self._sol_last_form_data = form_data
            planning_measured_note = self._scrub_planning_measured_fields(form_data)
            params = form_data["params"]
        except Exception as exc:
            if status_var is not None:
                status_var.set(f"Unable to gather solubility inputs: {exc}")
            if notify:
                try:
                    messagebox.showwarning(
                        "Advanced Solubility Module",
                        f"Unable to gather solubility inputs: {exc}",
                    )
                except Exception:
                    pass
            return
        try:
            factor = float(
                getattr(self, "_sol_cycle_supersat_var", tk.DoubleVar(value=1.0)).get()
            )
        except Exception:
            factor = 1.0
        slurry_mode = bool(
            getattr(self, "_sol_cycle_slurry_var", tk.BooleanVar(value=True)).get()
        )
        # Always honor the currently selected speciation model for cycle simulations.
        # Cached form data may carry an older model_key if the user changed the selection
        # after the last solve; refresh it here so the timeline uses the live choice.
        available_models = {model.key for model in list_speciation_models()}
        spec_key, ph_key, use_same = self._resolve_workflow_model_keys(
            workflow, form_data
        )
        model_key = spec_key
        if model_key not in available_models:
            aqion_key = "aqion_closed"
            model_key = (
                aqion_key if aqion_key in available_models else DEFAULT_SPEC_MODEL_KEY
            )
            spec_key = model_key
            if use_same:
                ph_key = model_key
            elif ph_key not in available_models:
                ph_key = model_key
            self._sol_model_key = model_key
        setting_spec, setting_ph, setting_use = self._workflow_model_setting_keys(
            workflow
        )
        try:
            form_data[setting_spec.replace("sol_", "")] = spec_key
            form_data[setting_ph.replace("sol_", "")] = ph_key
            form_data[setting_use.replace("sol_", "")] = use_same
            form_data["workflow_spec_model_key"] = spec_key
            form_data["workflow_ph_model_key"] = ph_key
            form_data["workflow_use_same_model"] = use_same
            form_data["model_key"] = model_key
            if isinstance(self._sol_last_form_data, dict):
                self._sol_last_form_data["model_key"] = model_key
        except Exception:
            form_data = dict(form_data or {})
            form_data[setting_spec.replace("sol_", "")] = spec_key
            form_data[setting_ph.replace("sol_", "")] = ph_key
            form_data[setting_use.replace("sol_", "")] = use_same
            form_data["workflow_spec_model_key"] = spec_key
            form_data["workflow_ph_model_key"] = ph_key
            form_data["workflow_use_same_model"] = use_same
            form_data["model_key"] = model_key
            self._sol_last_form_data = form_data
        context_workflow_key = form_data.get("workflow_key") or workflow
        resolved_measurements = self._resolve_analysis_reaction_guidance_measurements(
            workflow_key=context_workflow_key,
            reaction_final_ph=form_data.get("reaction_final_ph"),
            reaction_slurry_ph=form_data.get("reaction_slurry_ph"),
            measured_ph_value=form_data.get("measured_ph_value"),
            measured_ph_cycle_index=form_data.get("measured_ph_cycle_index"),
            measured_ph_anchors=form_data.get("measured_ph_anchors"),
            measured_ph_anchor_enabled=bool(
                form_data.get("measured_ph_anchor_enabled", True)
            ),
            cycle_count=len(cycles),
        )
        naoh_mass_entry = form_data.get("reaction_naoh_mass")
        if naoh_mass_entry is None:
            naoh_mass_entry = form_data.get("naoh_mass_basis")
        solution_volume_entry = form_data.get("reaction_solution_volume")
        if solution_volume_entry is None:
            try:
                solution_volume_entry = params.solution_volume_l
            except Exception:
                solution_volume_entry = None
        reaction_context = {
            "naoh_mass_g": naoh_mass_entry,
            "solution_volume_l": solution_volume_entry,
            "target_ph": form_data.get("reaction_target_ph"),
            "measured_ph": resolved_measurements.get("measured_ph"),
            "slurry_ph": resolved_measurements.get("slurry_ph"),
            "reaction_final_ph": form_data.get("reaction_final_ph"),
            "reaction_slurry_ph": form_data.get("reaction_slurry_ph"),
            "measured_ph_cycle_index": form_data.get("measured_ph_cycle_index"),
            "measured_ph_anchors": form_data.get("measured_ph_anchors"),
            "measured_ph_anchor_enabled": bool(
                form_data.get("measured_ph_anchor_enabled", True)
            ),
            "temperature_c": params.temperature_c,
            "use_temp_adjusted_constants": params.use_temperature_adjusted_constants,
            "ionic_strength_cap": params.ionic_strength_cap,
            "workflow_key": context_workflow_key,
            "planning_cycle_delta_p_psi": form_data.get("planning_cycle_delta_p_psi"),
            "planning_headspace_volume_l": form_data.get("planning_headspace_volume_l"),
            "planning_headspace_pressure_high_psi": form_data.get(
                "planning_headspace_pressure_high_psi"
            ),
            "planning_cycle_co2_g": form_data.get("planning_cycle_co2_g"),
            "planning_stop_co2_added_g": form_data.get("planning_stop_co2_added_g"),
            "planning_stop_ph": form_data.get("planning_stop_ph"),
            "planning_measured_note": planning_measured_note,
        }
        workflow_key = context_workflow_key
        if workflow_key == "Reprocessing":
            diag = form_data.get("diagnostic_data") or {}
            reproc_guidance = getattr(self, "_sol_reaction_guidance", {}) or {}
            reproc_context = reproc_guidance.get("reprocessing_workflow") or {}
            reaction_context.update(
                {
                    "reprocessing_mode": True,
                    "batch_mass_g": params.mass_na_hco3_g,
                    "solvent_basis": form_data.get("solvent_basis"),
                    "solvent_basis_value": form_data.get("solvent_basis_value"),
                    "failing_ph": form_data.get("failing_ph"),
                    "target_ph": diag.get("target_ph"),
                    "recommended_co2_g": reproc_context.get("recommended_co2_g"),
                    "baseline_spec": reproc_context.get("baseline_spec"),
                    "target_spec": reproc_context.get("target_spec"),
                    "measured_alk_meq": diag.get("slurry_alk_meq_l"),
                    "dissolved_limit_moles": reproc_context.get(
                        "dissolved_limit_moles"
                    ),
                    "baseline_carbon_m": reproc_context.get("baseline_carbon_m"),
                }
            )
            # Ensure reprocessing context always has a baseline/target spec and CO2 capacity.
            failing_ph = form_data.get("failing_ph")
            target_ph_val = diag.get("target_ph")
            measured_alk = diag.get("slurry_alk_meq_l")
            baseline_spec_ctx = reaction_context.get("baseline_spec")
            target_spec_ctx = reaction_context.get("target_spec")
            rec_co2_g = reaction_context.get("recommended_co2_g")
            dissolved_limit_moles = reaction_context.get("dissolved_limit_moles")
            baseline_carbon_m = reaction_context.get("baseline_carbon_m")
            try:
                volume_l = max(params.volume_l(), 1e-9)
            except Exception:
                volume_l = max(params.solution_volume_l or 1e-9, 1e-9)
            constants = None
            try:
                constants = _resolve_solubility_constants(
                    params, math_logger=None, section="Reprocessing timeline constants"
                )
            except Exception:
                constants = None
            if baseline_spec_ctx is None and failing_ph is not None:
                try:
                    baseline_spec_ctx, baseline_carbon_m = (
                        _reprocessing_speciation_from_ph(
                            params,
                            failing_ph,
                            constants=constants,
                            measured_alk_meq=measured_alk,
                            math_section="Reprocessing baseline (timeline)",
                        )
                    )
                except Exception:
                    baseline_spec_ctx = baseline_spec_ctx or reproc_context.get(
                        "baseline_spec"
                    )
            if baseline_carbon_m is None and baseline_spec_ctx is not None:
                baseline_carbon_m = getattr(baseline_spec_ctx, "total_carbon_m", None)
            if target_spec_ctx is None and target_ph_val is not None:
                try:
                    target_spec_ctx, target_carbon = _reprocessing_speciation_from_ph(
                        params,
                        target_ph_val,
                        constants=constants,
                        measured_alk_meq=measured_alk,
                        math_section="Reprocessing target (timeline)",
                    )
                    if rec_co2_g is None and baseline_carbon_m is not None:
                        delta_m = max(target_carbon - baseline_carbon_m, 0.0) * volume_l
                        rec_co2_g = delta_m * SOL_MW_CO2
                        dissolved_limit_moles = max(
                            delta_m, dissolved_limit_moles or 0.0
                        )
                except Exception:
                    target_spec_ctx = target_spec_ctx or reproc_context.get(
                        "target_spec"
                    )
            if (
                dissolved_limit_moles is None
                and rec_co2_g is not None
                and math.isfinite(rec_co2_g)
            ):
                dissolved_limit_moles = max(rec_co2_g / SOL_MW_CO2, 0.0)
            reaction_context.update(
                {
                    "baseline_spec": baseline_spec_ctx,
                    "target_spec": target_spec_ctx,
                    "recommended_co2_g": rec_co2_g,
                    "baseline_carbon_m": baseline_carbon_m,
                    "dissolved_limit_moles": dissolved_limit_moles,
                }
            )
        if status_var is not None:
            status_var.set("Simulating cycles...")
        cycle_session_id = self._begin_solubility_loading_phase(
            phase="cycle_timeline",
            session_id=loading_session_id,
            message="Computing cycle timeline...",
            detail="Simulating per-cycle speciation and phase transitions.",
        )

        # Snapshot inputs for thread safety/no-GIL readiness.
        model_key_value = spec_key
        ph_model_key_value = ph_key
        model_options_snapshot = form_data.get("model_options")
        params_snapshot = params
        cycles_snapshot = list(cycles)
        reaction_context_snapshot = copy.deepcopy(reaction_context)
        cycle_columns_snapshot = tuple(getattr(self, "_sol_cycle_timeline_columns", ()))
        try:
            reaction_guidance_snapshot = copy.deepcopy(
                getattr(self, "_sol_reaction_guidance", {}) or {}
            )
        except Exception:
            reaction_guidance_snapshot = dict(
                getattr(self, "_sol_reaction_guidance", {}) or {}
            )
        try:
            form_data_snapshot = copy.deepcopy(form_data)
        except Exception:
            form_data_snapshot = dict(form_data or {})
        try:
            payload_snapshot = copy.deepcopy(payload)
        except Exception:
            payload_snapshot = dict(payload or {})

        def _compute_cycle_result() -> Dict[str, Any]:
            """Compute one cycle-timeline result bundle in the worker thread.

            Purpose:
                Execute the cycle simulation and any workflow-specific postcompute
                that should never block the Tk event loop.
            Why:
                Analysis mode needs planning-reference, forensic, and dashboard
                payloads prepared off the UI thread to prevent perceived hangs.
            Inputs:
                None. Uses outer-scope worker snapshots captured before submit.
            Outputs:
                Dict[str, Any]: Cycle simulation result, augmented with Analysis
                runtime payload when the active workflow is Analysis.
            Side Effects:
                None.
            Exceptions:
                Worker exceptions are allowed to propagate to `_on_err`.
            """
            try:
                spec_model_obj = get_speciation_model(model_key_value)
            except KeyError:
                spec_model_obj = get_speciation_model(None)
            try:
                ph_model_obj = get_speciation_model(ph_model_key_value)
            except KeyError:
                ph_model_obj = spec_model_obj
            cycle_result = solubility_simulate_cycle_timeline(
                params_snapshot,
                cycles_snapshot,
                supersaturation_factor=factor,
                slurry_mode=slurry_mode,
                reaction_context=reaction_context_snapshot,
                model=spec_model_obj,
                ph_model=ph_model_obj,
                model_options=model_options_snapshot,
                treat_excess_as_headspace=treat_excess_as_headspace,
            )
            if workflow_key == "Analysis":
                analysis_runtime = self._build_analysis_runtime_payload(
                    cycle_payload=payload_snapshot,
                    timeline_rows=cycle_result.get("timeline") or [],
                    form_data=form_data_snapshot,
                    reaction_guidance=reaction_guidance_snapshot,
                )
                cycle_result["timeline"] = list(analysis_runtime.get("timeline") or [])
                cycle_result["analysis_reference_trace"] = analysis_runtime.get(
                    "reference_trace"
                )
                cycle_result["analysis_overlay_marker"] = analysis_runtime.get(
                    "overlay_marker"
                )
                cycle_result["analysis_forensic_summary"] = analysis_runtime.get(
                    "forensic_summary"
                )
                cycle_result["analysis_measured_ph_anchor"] = analysis_runtime.get(
                    "measured_ph_anchor"
                )
                cycle_result["analysis_uptake_correction"] = analysis_runtime.get(
                    "uptake_correction"
                )
                cycle_result["analysis_corrected_uptake_series"] = analysis_runtime.get(
                    "corrected_uptake_series"
                )
                cycle_result["analysis_completion_from_measured_ph"] = analysis_runtime.get(
                    "completion_from_measured_ph"
                )
                cycle_result[
                    "analysis_latest_cycle_corrected_speciation"
                ] = analysis_runtime.get("latest_cycle_corrected_speciation")
                cycle_result["analysis_dashboard"] = analysis_runtime.get(
                    "dashboard_payload"
                )
                cycle_result["analysis_alignment_audit"] = analysis_runtime.get(
                    "analysis_alignment_audit"
                )
                cycle_result["analysis_consistency"] = analysis_runtime.get(
                    "analysis_consistency"
                )
                cycle_result["analysis_progress_text"] = analysis_runtime.get(
                    "progress_text"
                )
                cycle_result["analysis_regime_text"] = analysis_runtime.get(
                    "regime_text"
                )
                cycle_result["analysis_required_co2_text"] = analysis_runtime.get(
                    "required_co2_text"
                )
                cycle_result["analysis_co2_g_text"] = analysis_runtime.get(
                    "co2_g_text"
                )
                cycle_result["analysis_co2_mol_text"] = analysis_runtime.get(
                    "co2_mol_text"
                )
                cycle_result["analysis_mapped_ph_text"] = analysis_runtime.get(
                    "mapped_ph_text"
                )
                cycle_result["analysis_equivalence_text"] = analysis_runtime.get(
                    "equivalence_text"
                )
                cycle_result["analysis_planning_completion_text"] = (
                    analysis_runtime.get("planning_completion_text")
                )
                cycle_result["analysis_planning_final_co2_g_text"] = (
                    analysis_runtime.get("planning_final_co2_g_text")
                )
                cycle_result["analysis_consistency_status"] = analysis_runtime.get(
                    "analysis_consistency_status"
                )
                cycle_result["analysis_consistency_findings"] = analysis_runtime.get(
                    "analysis_consistency_findings"
                )
                cycle_result["analysis_consistency_recommendations"] = (
                    analysis_runtime.get("analysis_consistency_recommendations")
                )
                cycle_result["analysis_consistency_sanitized_warning_count"] = (
                    analysis_runtime.get("analysis_consistency_sanitized_warning_count")
                )
                cycle_result["analysis_input_signature"] = analysis_runtime.get(
                    "input_signature"
                )
                cycle_result["analysis_cycle_signature"] = analysis_runtime.get(
                    "cycle_signature"
                )
                cycle_result["analysis_reference_trace_source"] = analysis_runtime.get(
                    "analysis_reference_trace_source"
                )
                cycle_result["analysis_last_action"] = analysis_runtime.get(
                    "analysis_last_action"
                )
                cycle_result["ml_correction_applied"] = analysis_runtime.get(
                    "ml_correction_applied"
                )
                cycle_result["ml_training_sample_count"] = analysis_runtime.get(
                    "ml_training_sample_count"
                )
                cycle_result["ml_fit_error"] = analysis_runtime.get("ml_fit_error")
            try:
                normalized_timeline = _normalize_cycle_timeline_for_render(
                    cycle_result.get("timeline") or []
                )
                cycle_result["timeline_render_payload"] = (
                    self._build_cycle_timeline_render_payload(
                        normalized_timeline,
                        workflow_key=workflow_key,
                        reaction_guidance=reaction_guidance_snapshot,
                        columns=cycle_columns_snapshot,
                    )
                )
            except Exception:
                cycle_result["timeline_render_payload"] = None
            return cycle_result

        def _on_ok(result):
            """Apply one successful cycle worker result on the Tk thread.

            Purpose:
                Store per-workflow cycle outputs and hand the prepared payload to
                the shared timeline/dashboard UI refresh path.
            Why:
                Completion must update state in one place while keeping the worker
                result authoritative for Analysis postcompute.
            Inputs:
                result: Background result payload returned by `_compute_cycle_result`.
            Outputs:
                None.
            Side Effects:
                Updates workflow caches, loading-overlay stages, and timeline UI.
            Exceptions:
                Best-effort; downstream UI refresh handles its own guards.
            """
            if payload and payload.get("reference_ledgers"):
                result["planning_reference_ledgers"] = payload.get("reference_ledgers")
            target_workflow = workflow_key or workflow
            self._set_cycle_result_for_workflow(target_workflow, result)
            self._set_cycle_payload_for_workflow(target_workflow, payload)
            finalize_state = {"done": False}

            def _finalize_success() -> None:
                """Complete loading phase after staged timeline render confirms draw."""
                if bool(finalize_state.get("done")):
                    return
                finalize_state["done"] = True
                self._wait_for_cycle_timeline_render_ready(
                    on_ready=lambda: self._complete_solubility_loading_phase(
                        cycle_session_id,
                        message="Finalizing workflow layout...",
                        detail="Cycle timeline table and plot are ready.",
                    )
                )
                try:
                    self._maybe_auto_export_simulation_workbook(
                        workflow_key=target_workflow,
                        result_payload=result,
                    )
                except Exception:
                    # Best-effort guard; auto-export failures should not break completion.
                    pass
                if notify and result.get("timeline"):
                    try:
                        messagebox.showinfo(
                            "Advanced Solubility Module",
                            "Cycle-resolved solubility simulation completed.",
                        )
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting the workflow.
                        pass

            def _finalize_failure(exc: BaseException) -> None:
                """Fail closed when timeline rendering raises and force-hide overlay."""
                if bool(finalize_state.get("done")):
                    return
                finalize_state["done"] = True
                self._recover_from_cycle_timeline_render_failure(
                    session_id=cycle_session_id,
                    status_var=status_var,
                    error=exc,
                )

            try:
                self._update_solubility_loading_phase(
                    cycle_session_id,
                    message="Rendering timeline table/plot...",
                    detail="Applying cycle timeline rows and plotting workflow overlays.",
                )
                self._update_cycle_solubility_widgets(
                    result,
                    workflow_key=target_workflow,
                    on_render_complete=_finalize_success,
                )
            except Exception as exc:
                _finalize_failure(exc)

        def _on_err(exc):
            """Handle one failed cycle worker result on the Tk thread.

            Purpose:
                Surface cycle-simulation worker failures without leaving the
                loading overlay or status widgets in a stale state.
            Why:
                Background exceptions should degrade to user-visible status text
                rather than appearing as a frozen workflow.
            Inputs:
                exc: Worker exception raised during cycle simulation.
            Outputs:
                None.
            Side Effects:
                Updates status text, completes the loading phase, and may show a
                best-effort dialog when `notify` is enabled.
            Exceptions:
                Dialog failures are swallowed to preserve the UI loop.
            """
            if status_var is not None:
                status_var.set(f"Cycle simulation failed: {exc}")
            self._complete_solubility_loading_phase(
                cycle_session_id,
                message="Cycle timeline simulation failed.",
                detail="See error details in the status area.",
            )
            if notify:
                try:
                    messagebox.showerror(
                        "Advanced Solubility Module",
                        f"Cycle simulation failed:\n{exc}",
                    )
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass

        try:
            self._task_runner.submit(
                "cycle_solubility", _compute_cycle_result, _on_ok, _on_err
            )
        except Exception as exc:
            _on_err(exc)

    def _build_analysis_runtime_payload(
        self,
        *,
        cycle_payload: Optional[Mapping[str, Any]],
        timeline_rows: Sequence[Mapping[str, Any]],
        form_data: Optional[Mapping[str, Any]],
        reaction_guidance: Optional[Mapping[str, Any]] = None,
    ) -> Dict[str, Any]:
        """Build one worker-safe Analysis runtime payload.

        Purpose:
            Precompute Analysis reference, forensic, and dashboard artifacts away
            from the Tk main thread.
        Why:
            The Analysis workflow freezes when planning-reference and dashboard
            compute stays on the UI thread before or after the threaded cycle solve.
        Inputs:
            cycle_payload: Imported cycle payload for current-state CO2 totals.
            timeline_rows: Raw cycle-simulation timeline rows to augment.
            form_data: Analysis form snapshot captured before the worker starts.
            reaction_guidance: Optional guidance snapshot used to align dashboard
                requirement fields with the CO2 guidance model.
        Outputs:
            Dict[str, Any]: Analysis runtime payload containing augmented timeline,
            dashboard data, forensic summary, overlay metadata, and ready-to-render
            status strings.
        Side Effects:
            None.
        Exceptions:
            Best-effort; missing planning inputs degrade to placeholder messages
            without raising.
        """
        timeline = [
            dict(entry or {})
            for entry in (timeline_rows or [])
            if isinstance(entry, Mapping)
        ]
        payload_map = dict(cycle_payload) if isinstance(cycle_payload, Mapping) else {}
        form_snapshot = dict(form_data) if isinstance(form_data, Mapping) else {}
        source_timeline_rows = [
            entry for entry in (timeline_rows or ()) if isinstance(entry, Mapping)
        ]
        input_signature = self._analysis_signature_fingerprint(
            self._analysis_input_signature_payload(form_snapshot)
        )
        timeline_signature = str(
            self._analysis_cycle_signature_from_timeline(source_timeline_rows) or ""
        ).strip()
        timeline_cache = getattr(self, "_analysis_runtime_timeline_cache", None)
        timeline: List[Dict[str, Any]]
        if timeline_signature and isinstance(timeline_cache, OrderedDict):
            cached_rows = timeline_cache.get(timeline_signature)
            if isinstance(cached_rows, Sequence):
                timeline = [dict(row) for row in cached_rows if isinstance(row, Mapping)]
                timeline_cache.move_to_end(timeline_signature)
            else:
                timeline = [dict(entry or {}) for entry in source_timeline_rows]
                timeline_cache[timeline_signature] = [dict(row) for row in timeline]
                timeline_cache.move_to_end(timeline_signature)
                timeline_limit = max(
                    1,
                    int(
                        _normalize_perf_cache_limits(settings.get("perf_cache_limits")).get(
                            "analysis_timeline_rows", 10
                        )
                    ),
                )
                while len(timeline_cache) > timeline_limit:
                    timeline_cache.popitem(last=False)
        else:
            timeline = [dict(entry or {}) for entry in source_timeline_rows]
        guidance_signature = ""
        if isinstance(reaction_guidance, Mapping):
            try:
                guidance_signature = str(
                    self._analysis_signature_fingerprint(dict(reaction_guidance)) or ""
                ).strip()
            except Exception:
                guidance_signature = ""
        runtime_cache_key = str(
            self._analysis_signature_fingerprint(
                {
                    "workflow_key": str(form_snapshot.get("workflow_key") or "").strip(),
                    "profile_name": str(form_snapshot.get("profile_name") or "").strip(),
                    "input_signature": input_signature,
                    "cycle_signature": timeline_signature,
                    "timeline_len": int(len(timeline)),
                    "total_moles_vdw": _safe_float(payload_map.get("total_moles_vdw")),
                    "total_moles_ideal": _safe_float(payload_map.get("total_moles_ideal")),
                    "gas_molar_mass": _safe_float(payload_map.get("gas_molar_mass")),
                    "guidance_signature": guidance_signature,
                }
            )
            or ""
        ).strip()
        payload_cache = getattr(self, "_analysis_runtime_payload_cache", None)
        if runtime_cache_key and isinstance(payload_cache, OrderedDict):
            cached_runtime_payload = payload_cache.get(runtime_cache_key)
            if isinstance(cached_runtime_payload, Mapping):
                payload_cache.move_to_end(runtime_cache_key)
                try:
                    return copy.deepcopy(dict(cached_runtime_payload))
                except Exception:
                    return dict(cached_runtime_payload)
        runtime_payload: Dict[str, Any] = {
            "timeline": timeline,
            "reference_trace": None,
            "analysis_reference_trace_source": "unavailable",
            "analysis_last_action": str(form_snapshot.get("analysis_last_action") or "").strip(),
            "overlay_marker": None,
            "forensic_summary": {},
            "dashboard_payload": None,
            "measured_ph_anchor": None,
            "uptake_correction": None,
            "corrected_uptake_series": None,
            "completion_from_measured_ph": None,
            "latest_cycle_corrected_speciation": None,
            "analysis_alignment_audit": None,
            "progress_text": "Based on cycle analysis data, your reaction progress is unavailable.",
            "regime_text": "Regime: Unknown (pH unavailable)",
            "required_co2_text": "CO2 required for target pH: --",
            "co2_g_text": "CO2 uptake (raw cumulative): unavailable",
            "co2_mol_text": "--",
            "mapped_ph_text": (
                "pH sources | Primary (Actual observed anchor): -- | "
                "Secondary (Calibrated estimated / Calculated): -- / -- | "
                "Diagnostic (Plan cycle / Plan CO2 aligned): -- / --"
            ),
            "equivalence_text": "Equivalence completion: --",
            "planning_completion_text": "Planning target completion: --",
            "planning_final_co2_g_text": "--",
            "input_signature": "",
            "cycle_signature": "",
            "ml_correction_applied": False,
            "ml_training_sample_count": 0,
            "ml_fit_error": None,
            "analysis_consistency_status": "consistent",
            "analysis_consistency_findings": [],
            "analysis_consistency_recommendations": [],
            "analysis_consistency_sanitized_warning_count": 0,
        }
        runtime_payload["input_signature"] = input_signature

        moles = payload_map.get("total_moles_vdw")
        if moles is None:
            moles = payload_map.get("total_moles_ideal")
        gas_molar_mass = payload_map.get("gas_molar_mass") or DEFAULT_GAS_MOLAR_MASS
        current_co2_mol = None
        current_co2_g = None
        if moles is not None and gas_molar_mass is not None:
            try:
                current_co2_mol = float(moles)
                current_co2_g = current_co2_mol * float(gas_molar_mass)
            except Exception:
                current_co2_mol = None
                current_co2_g = None
        if (
            current_co2_g is not None
            and current_co2_mol is not None
            and math.isfinite(current_co2_g)
            and math.isfinite(current_co2_mol)
        ):
            runtime_payload["co2_g_text"] = (
                f"CO2 uptake (raw cumulative): {current_co2_g:.2f} g ({current_co2_mol:.4f} mol)"
            )
            runtime_payload["co2_mol_text"] = f"{current_co2_mol:.4f}"
        elif timeline:
            last_row = timeline[-1]
            current_co2_g = _safe_float(
                last_row.get("cumulative_co2_added_mass_g")
                or last_row.get("co2_g")
                or last_row.get("co2_mass_g")
            )
            current_co2_mol = _safe_float(
                last_row.get("cumulative_co2_added_moles")
                or last_row.get("co2_total_moles")
                or last_row.get("cumulative_co2_mol")
                or last_row.get("co2_moles")
            )
            if current_co2_mol is None and current_co2_g is not None:
                current_co2_mol = current_co2_g / SOL_MW_CO2
            if (
                current_co2_g is not None
                and current_co2_mol is not None
                and math.isfinite(current_co2_g)
                and math.isfinite(current_co2_mol)
            ):
                runtime_payload["co2_g_text"] = (
                    "CO2 uptake (raw cumulative): "
                    f"{current_co2_g:.2f} g ({current_co2_mol:.4f} mol)"
                )
                runtime_payload["co2_mol_text"] = f"{current_co2_mol:.4f}"

        planning_warning: Optional[str] = None
        trace: Optional[Dict[str, Any]] = None
        reference_trace_source = "unavailable"
        if form_snapshot.get("workflow_key") == "Analysis":
            cycle_trace = self._build_analysis_reference_trace_from_timeline(
                timeline,
                form_data=form_snapshot,
            )
            if isinstance(cycle_trace, Mapping) and (cycle_trace.get("x_co2_g_series") or []):
                trace = dict(cycle_trace)
                reference_trace_source = "analysis_cycle"
            else:
                try:
                    solver_inputs = self._prepare_solver_inputs(form_snapshot)
                except Exception as exc:
                    planning_warning = (
                        "Unable to generate Planning fallback reference curve; "
                        f"check Analysis inputs ({exc})."
                    )
                else:
                    planning_trace = self._build_planning_reference_trace_for_analysis(
                        form_snapshot, solver_inputs
                    )
                    if isinstance(planning_trace, dict) and planning_trace.get("warning"):
                        planning_warning = str(planning_trace.get("warning"))
                    if isinstance(planning_trace, Mapping) and (
                        planning_trace.get("x_co2_g_series") or []
                    ):
                        trace = dict(planning_trace)
                        reference_trace_source = "planning_fallback"
                if not (isinstance(trace, Mapping) and (trace.get("x_co2_g_series") or [])):
                    if planning_warning is None:
                        planning_warning = (
                            "Unable to generate Analysis cycle-derived or Planning fallback "
                            "reference curves from current inputs."
                        )
        runtime_payload["analysis_reference_trace_source"] = reference_trace_source

        mapped_ph: Optional[float] = None
        if trace and trace.get("x_co2_g_series"):
            runtime_payload["reference_trace"] = trace
            x_series = trace.get("x_co2_g_series") or []
            ph_series = trace.get("ph_series") or []
            final_co2_g = _safe_float(trace.get("final_co2_g"))
            eq_co2_g = _safe_float(trace.get("equivalence_co2_g"))
            mapped_x, mapped_ph, _ = _map_current_state_to_planning_curve(
                current_co2_g, x_series, ph_series
            )
            overall_pct = None
            if (
                current_co2_g is not None
                and final_co2_g is not None
                and math.isfinite(current_co2_g)
                and math.isfinite(final_co2_g)
                and final_co2_g > 0.0
            ):
                overall_pct = max(0.0, min(current_co2_g / final_co2_g, 1.0)) * 100.0
            eq_pct = None
            if (
                current_co2_g is not None
                and eq_co2_g is not None
                and math.isfinite(current_co2_g)
                and math.isfinite(eq_co2_g)
                and eq_co2_g > 0.0
            ):
                eq_pct = max(0.0, min(current_co2_g / eq_co2_g, 1.0)) * 100.0
            if overall_pct is not None:
                runtime_payload["progress_text"] = (
                    "Based on cycle analysis data, your reaction is "
                    f"{overall_pct:.1f}% complete."
                )
                runtime_payload["planning_completion_text"] = (
                    f"Planning target completion: {overall_pct:.1f}%"
                )
            else:
                runtime_payload["progress_text"] = (
                    "Based on cycle analysis data, your reaction progress is unavailable."
                )
            runtime_payload["regime_text"] = _analysis_regime_label(mapped_ph)
            if eq_pct is not None:
                runtime_payload["equivalence_text"] = (
                    f"Equivalence completion: {eq_pct:.1f}%"
                )
            if final_co2_g is not None and math.isfinite(final_co2_g):
                runtime_payload["planning_final_co2_g_text"] = f"{final_co2_g:.2f}"
            marker_label = "Current state (cycle-derived)"
            if overall_pct is not None:
                marker_label = f"{marker_label}\n{overall_pct:.1f}% complete"
            if (
                mapped_x is not None
                and mapped_ph is not None
                and math.isfinite(mapped_x)
                and math.isfinite(mapped_ph)
            ):
                runtime_payload["overlay_marker"] = {
                    "x": mapped_x,
                    "ph": mapped_ph,
                    "label": marker_label,
                }
        elif planning_warning:
            runtime_payload["progress_text"] = planning_warning

        # Build the expensive Analysis add-ons in the worker so Tk callbacks only
        # apply ready-to-render state rather than recomputing it on completion.
        augmented_timeline, forensic_summary = self._compute_analysis_forensic_timeline(
            timeline,
            reference_trace=trace,
        )
        calibrated_timeline, calibration_payload, anchor_payload = (
            self._apply_analysis_measured_ph_calibration(
                augmented_timeline,
                form_snapshot=form_snapshot,
                reference_trace=trace,
            )
        )
        runtime_payload["timeline"] = calibrated_timeline
        runtime_payload["cycle_signature"] = (
            self._analysis_cycle_signature_from_timeline(calibrated_timeline) or ""
        )
        runtime_payload["forensic_summary"] = forensic_summary
        runtime_payload["measured_ph_anchor"] = (
            dict(anchor_payload) if isinstance(anchor_payload, Mapping) else None
        )
        runtime_payload["uptake_correction"] = (
            dict(calibration_payload)
            if isinstance(calibration_payload, Mapping)
            else None
        )
        if isinstance(calibration_payload, Mapping):
            original_cycle_uptake_mol_series: List[float] = []
            for row in calibrated_timeline:
                cycle_mol = _safe_float(row.get("co2_moles"))
                if cycle_mol is None:
                    cycle_mol = _safe_float(row.get("co2_added_moles"))
                if cycle_mol is None:
                    cycle_mol = _safe_float(row.get("actual_cycle_co2_mol"))
                original_cycle_uptake_mol_series.append(max(0.0, float(cycle_mol or 0.0)))
            runtime_payload["corrected_uptake_series"] = {
                "original_cycle_uptake_mol_series": original_cycle_uptake_mol_series,
                "corrected_cycle_uptake_mol_series": list(
                    calibration_payload.get("corrected_cycle_uptake_mol_series") or []
                ),
                "corrected_cumulative_co2_mol_series": list(
                    calibration_payload.get("corrected_cumulative_co2_mol_series") or []
                ),
                "corrected_cycle_uptake_g_series": list(
                    calibration_payload.get("corrected_cycle_uptake_g_series") or []
                ),
                "corrected_cumulative_co2_g_series": list(
                    calibration_payload.get("corrected_cumulative_co2_g_series") or []
                ),
            }
            runtime_payload["completion_from_measured_ph"] = {
                "completion_pct": _safe_float(
                    calibration_payload.get("completion_from_measured_ph_pct")
                ),
                "co2_required_for_target_ph_mol": _safe_float(
                    calibration_payload.get("co2_required_for_target_ph_mol")
                ),
                "co2_required_for_target_ph_g": _safe_float(
                    calibration_payload.get("co2_required_for_target_ph_g")
                ),
                "corrected_cumulative_uptake_latest_mol": _safe_float(
                    calibration_payload.get("corrected_cumulative_uptake_latest_mol")
                ),
                "corrected_cumulative_uptake_latest_g": _safe_float(
                    calibration_payload.get("corrected_cumulative_uptake_latest_g")
                ),
            }
            runtime_payload["latest_cycle_corrected_speciation"] = dict(
                calibration_payload.get("latest_corrected_speciation") or {}
            )
        dashboard_form_snapshot = dict(form_snapshot)
        dashboard_form_snapshot["_analysis_uptake_correction"] = (
            dict(calibration_payload) if isinstance(calibration_payload, Mapping) else None
        )
        dashboard_form_snapshot["_analysis_reaction_guidance"] = (
            dict(reaction_guidance) if isinstance(reaction_guidance, Mapping) else None
        )
        dashboard_form_snapshot["_analysis_reference_trace_source"] = reference_trace_source
        dashboard_form_snapshot["_analysis_last_action"] = str(
            runtime_payload.get("analysis_last_action") or ""
        ).strip()
        runtime_payload["dashboard_payload"] = self._build_analysis_dashboard_data(
            calibrated_timeline,
            form_data=dashboard_form_snapshot,
        )
        alignment_audit = self._analysis_alignment_audit_and_reconcile(
            timeline_rows=calibrated_timeline,
            dashboard_payload=runtime_payload.get("dashboard_payload"),
            calibration_payload=(
                calibration_payload if isinstance(calibration_payload, Mapping) else None
            ),
        )
        runtime_payload["analysis_alignment_audit"] = dict(alignment_audit or {})
        consistency_audit = self._analysis_consistency_audit_and_sanitize(
            timeline_rows=calibrated_timeline,
            dashboard_payload=runtime_payload.get("dashboard_payload"),
            calibration_payload=(
                calibration_payload if isinstance(calibration_payload, Mapping) else None
            ),
        )
        runtime_payload["analysis_consistency"] = dict(consistency_audit or {})
        dashboard_payload = runtime_payload.get("dashboard_payload")
        summary = (
            dict(dashboard_payload.get("summary"))
            if isinstance(dashboard_payload, Mapping)
            and isinstance(dashboard_payload.get("summary"), Mapping)
            else {}
        )
        corrected_total_uptake_g = _safe_float(summary.get("corrected_total_uptake_g"))
        corrected_total_uptake_mol = _safe_float(summary.get("corrected_total_uptake_mol"))
        raw_total_uptake_g = _safe_float(summary.get("total_uptake_g"))
        raw_total_uptake_mol = _safe_float(summary.get("total_uptake_mol"))
        corrected_completion_pct = _safe_float(
            summary.get(
                "corrected_planning_completion_pct",
                summary.get("completion_from_measured_ph_pct"),
            )
        )
        raw_completion_pct = _safe_float(summary.get("planning_completion_pct"))
        corrected_eq_pct = _safe_float(summary.get("corrected_equivalence_completion_pct"))
        raw_eq_pct = _safe_float(summary.get("equivalence_completion_pct"))
        latest_corrected_ph = _safe_float(summary.get("latest_corrected_ph"))
        required_total_g = _safe_float(summary.get("co2_required_for_target_ph_g"))
        required_total_mol = _safe_float(summary.get("co2_required_for_target_ph_mol"))
        requirement_source = str(summary.get("co2_requirement_source") or "").strip().lower()
        runtime_payload["analysis_reference_trace_source"] = str(
            summary.get("analysis_reference_trace_source")
            or runtime_payload.get("analysis_reference_trace_source")
            or reference_trace_source
        ).strip() or "unavailable"
        runtime_payload["analysis_last_action"] = str(
            summary.get("analysis_last_action")
            or runtime_payload.get("analysis_last_action")
            or form_snapshot.get("analysis_last_action")
            or ""
        ).strip()
        runtime_payload["ml_correction_applied"] = bool(
            summary.get("ml_correction_applied", False)
        )
        runtime_payload["ml_training_sample_count"] = max(
            _safe_rust_int(summary.get("ml_training_sample_count"), 0),
            0,
        )
        runtime_payload["ml_fit_error"] = _safe_float(summary.get("ml_fit_error"))
        runtime_payload["analysis_consistency_status"] = str(
            summary.get("analysis_consistency_status") or "consistent"
        ).strip() or "consistent"
        runtime_payload["analysis_consistency_findings"] = list(
            summary.get("analysis_consistency_findings") or []
        )
        runtime_payload["analysis_consistency_recommendations"] = list(
            summary.get("analysis_consistency_recommendations") or []
        )
        runtime_payload["analysis_consistency_sanitized_warning_count"] = max(
            _safe_rust_int(summary.get("analysis_consistency_sanitized_warning_count"), 0),
            0,
        )

        if corrected_completion_pct is not None:
            runtime_payload["progress_text"] = (
                "Measured-pH anchored correction indicates corrected planning target "
                f"completion is {corrected_completion_pct:.1f}%."
            )
            if corrected_eq_pct is not None:
                runtime_payload["progress_text"] += (
                    f" Corrected equivalence completion is {corrected_eq_pct:.1f}%."
                )
        elif raw_completion_pct is not None:
            runtime_payload["progress_text"] = (
                "Based on cycle analysis data, your reaction is "
                f"{raw_completion_pct:.1f}% complete."
            )

        if corrected_completion_pct is not None:
            runtime_payload["planning_completion_text"] = (
                "Planning target completion (corrected): "
                f"{corrected_completion_pct:.1f}%"
            )
            if (
                raw_completion_pct is not None
                and abs(raw_completion_pct - corrected_completion_pct) > 1e-9
            ):
                runtime_payload["planning_completion_text"] += (
                    f" | raw {raw_completion_pct:.1f}%"
                )
        elif raw_completion_pct is not None:
            runtime_payload["planning_completion_text"] = (
                f"Planning target completion: {raw_completion_pct:.1f}%"
            )

        if corrected_eq_pct is not None:
            runtime_payload["equivalence_text"] = (
                f"Equivalence completion (corrected): {corrected_eq_pct:.1f}%"
            )
            if raw_eq_pct is not None and abs(raw_eq_pct - corrected_eq_pct) > 1e-9:
                runtime_payload["equivalence_text"] += f" | raw {raw_eq_pct:.1f}%"
        elif raw_eq_pct is not None:
            runtime_payload["equivalence_text"] = f"Equivalence completion: {raw_eq_pct:.1f}%"

        def _fmt_ph_source(value: Optional[float]) -> str:
            """Format one optional pH value for source-labeled runtime text."""
            if value is None or not math.isfinite(value):
                return "--"
            return f"{float(value):.2f}"

        actual_cycle_series = (
            list(dashboard_payload.get("actual_cycle_series") or [])
            if isinstance(dashboard_payload, Mapping)
            else []
        )
        reference_cycle_series = (
            list(dashboard_payload.get("reference_cycle_series") or [])
            if isinstance(dashboard_payload, Mapping)
            else []
        )
        comparison_series = (
            list(dashboard_payload.get("comparison_series") or [])
            if isinstance(dashboard_payload, Mapping)
            else []
        )
        latest_actual_row = (
            actual_cycle_series[-1]
            if actual_cycle_series
            and isinstance(actual_cycle_series[-1], Mapping)
            else {}
        )
        latest_reference_row = (
            reference_cycle_series[-1]
            if reference_cycle_series
            and isinstance(reference_cycle_series[-1], Mapping)
            else {}
        )
        latest_comparison_row = (
            comparison_series[-1]
            if comparison_series
            and isinstance(comparison_series[-1], Mapping)
            else {}
        )
        latest_row_channels = _analysis_ph_channels_from_row(latest_actual_row)
        latest_actual_observed_ph = _safe_float(summary.get("latest_actual_observed_ph"))
        if latest_actual_observed_ph is None:
            latest_actual_observed_ph = _safe_float(
                latest_row_channels.get("actual_observed_ph")
            )
        latest_calculated_ph = _safe_float(summary.get("latest_calculated_ph"))
        if latest_calculated_ph is None:
            latest_calculated_ph = _safe_float(latest_row_channels.get("calculated_ph"))
        latest_calibrated_estimated_ph = _safe_float(
            summary.get("latest_calibrated_estimated_ph")
        )
        if latest_calibrated_estimated_ph is None:
            latest_calibrated_estimated_ph = _safe_float(summary.get("latest_corrected_ph"))
        if latest_calibrated_estimated_ph is None:
            latest_calibrated_estimated_ph = _safe_float(
                latest_row_channels.get("calibrated_estimated_ph")
            )
        latest_plan_cycle_ph = _safe_float(summary.get("latest_plan_cycle_ph"))
        if latest_plan_cycle_ph is None:
            latest_plan_cycle_ph = _safe_float(latest_reference_row.get("ph"))
        latest_plan_co2_aligned_ph = _safe_float(summary.get("latest_plan_co2_aligned_ph"))
        if latest_plan_co2_aligned_ph is None:
            latest_plan_co2_aligned_ph = _safe_float(
                latest_comparison_row.get("reference_co2_aligned_ph")
            )
        if latest_plan_co2_aligned_ph is None and mapped_ph is not None and math.isfinite(mapped_ph):
            latest_plan_co2_aligned_ph = float(mapped_ph)
        primary_ph = latest_actual_observed_ph
        primary_source = "Actual observed anchor"
        if (
            primary_ph is None
            and latest_calibrated_estimated_ph is not None
            and math.isfinite(latest_calibrated_estimated_ph)
        ):
            primary_ph = float(latest_calibrated_estimated_ph)
            primary_source = "Calibrated estimated"
        if (
            primary_ph is None
            and latest_calculated_ph is not None
            and math.isfinite(latest_calculated_ph)
        ):
            primary_ph = float(latest_calculated_ph)
            primary_source = "Calculated"
        runtime_payload["regime_text"] = _analysis_regime_label(primary_ph)
        runtime_payload["mapped_ph_text"] = (
            f"pH sources | Primary ({primary_source}): {_fmt_ph_source(primary_ph)} | "
            "Secondary (Calibrated estimated / Calculated): "
            f"{_fmt_ph_source(latest_calibrated_estimated_ph)} / {_fmt_ph_source(latest_calculated_ph)} | "
            "Diagnostic (Plan cycle / Plan CO2 aligned): "
            f"{_fmt_ph_source(latest_plan_cycle_ph)} / "
            f"{_fmt_ph_source(latest_plan_co2_aligned_ph)}"
        )

        primary_total_g = (
            corrected_total_uptake_g
            if corrected_total_uptake_g is not None
            else raw_total_uptake_g
        )
        primary_total_mol = (
            corrected_total_uptake_mol
            if corrected_total_uptake_mol is not None
            else raw_total_uptake_mol
        )
        if primary_total_g is not None and primary_total_mol is None:
            primary_total_mol = primary_total_g / SOL_MW_CO2
        if (
            primary_total_g is not None
            and primary_total_mol is not None
            and math.isfinite(primary_total_g)
            and math.isfinite(primary_total_mol)
        ):
            runtime_payload["co2_g_text"] = (
                "CO2 uptake (corrected-primary cumulative): "
                f"{primary_total_g:.2f} g ({primary_total_mol:.4f} mol)"
            )
            if (
                corrected_total_uptake_g is not None
                and raw_total_uptake_g is not None
                and abs(raw_total_uptake_g - corrected_total_uptake_g) > 1e-9
            ):
                runtime_payload["co2_g_text"] += f" | raw {raw_total_uptake_g:.2f} g"
            runtime_payload["co2_mol_text"] = f"{primary_total_mol:.4f}"

        if required_total_g is not None and math.isfinite(required_total_g):
            requirement_source_label = {
                "guidance_model": "guidance model",
                "measured_ph_calibration": "measured-pH calibration",
                "planning_reference": "planning reference",
            }.get(requirement_source, "fallback/unknown")
            if required_total_mol is None:
                required_total_mol = required_total_g / SOL_MW_CO2
            if required_total_mol is not None and math.isfinite(required_total_mol):
                runtime_payload["required_co2_text"] = (
                    "CO2 required for target pH (target total): "
                    f"{required_total_g:.2f} g ({required_total_mol:.4f} mol)"
                )
                if primary_total_g is not None and math.isfinite(primary_total_g):
                    remaining_g = max(required_total_g - primary_total_g, 0.0)
                    remaining_mol = remaining_g / SOL_MW_CO2
                    runtime_payload["required_co2_text"] += (
                        f" | remaining {remaining_g:.2f} g ({remaining_mol:.4f} mol)"
                    )
                runtime_payload["required_co2_text"] += (
                    f" | source {requirement_source_label}"
                )
            runtime_payload["planning_final_co2_g_text"] = f"{required_total_g:.2f}"

        if (
            corrected_total_uptake_g is not None
            and latest_corrected_ph is not None
            and math.isfinite(corrected_total_uptake_g)
            and math.isfinite(latest_corrected_ph)
        ):
            marker_label = "Measured-anchor corrected state"
            if corrected_completion_pct is not None:
                marker_label += f"\nPlanning target {corrected_completion_pct:.1f}%"
            if corrected_eq_pct is not None:
                marker_label += f"\nEquivalence {corrected_eq_pct:.1f}%"
            runtime_payload["overlay_marker"] = {
                "x": corrected_total_uptake_g,
                "ph": latest_corrected_ph,
                "label": marker_label,
            }
        if runtime_cache_key and isinstance(payload_cache, OrderedDict):
            try:
                payload_cache[runtime_cache_key] = copy.deepcopy(runtime_payload)
            except Exception:
                payload_cache[runtime_cache_key] = dict(runtime_payload)
            payload_cache.move_to_end(runtime_cache_key)
            payload_limit = max(
                1,
                int(
                    _normalize_perf_cache_limits(settings.get("perf_cache_limits")).get(
                        "analysis_runtime_payload", 6
                    )
                ),
            )
            while len(payload_cache) > payload_limit:
                payload_cache.popitem(last=False)
        return runtime_payload

    def _apply_analysis_runtime_payload(
        self, result: Optional[Mapping[str, Any]]
    ) -> Optional[Dict[str, Any]]:
        """Apply precomputed Analysis runtime state to Tk-bound UI members.

        Purpose:
            Populate Analysis trace, overlay, KPI, and dashboard state from one
            worker-produced payload.
        Why:
            Keeping this method UI-only prevents the Tk thread from recomputing
            planning references, forensic metrics, and dashboard payloads.
        Inputs:
            result: Cycle-simulation result containing precomputed Analysis fields.
        Outputs:
            Optional[Dict[str, Any]]: Dashboard payload to pass into shared widget
            render helpers, or None when no dashboard data is available.
        Side Effects:
            Updates Analysis cache attributes and `StringVar` values.
        Exceptions:
            Missing payload fields fall back to placeholder strings.
        """
        result_map = result if isinstance(result, Mapping) else {}
        reference_trace = result_map.get("analysis_reference_trace")
        overlay_marker = result_map.get("analysis_overlay_marker")
        measured_anchor = result_map.get("analysis_measured_ph_anchor")
        uptake_correction = result_map.get("analysis_uptake_correction")
        corrected_uptake_series = result_map.get("analysis_corrected_uptake_series")
        completion_from_measured_ph = result_map.get("analysis_completion_from_measured_ph")
        latest_cycle_corrected_speciation = result_map.get(
            "analysis_latest_cycle_corrected_speciation"
        )
        alignment_audit = result_map.get("analysis_alignment_audit")
        consistency_audit = result_map.get("analysis_consistency")
        self._analysis_reference_trace_source = str(
            result_map.get("analysis_reference_trace_source") or ""
        ).strip()
        self._analysis_last_action = str(result_map.get("analysis_last_action") or "").strip()
        self._analysis_reference_trace = (
            dict(reference_trace) if isinstance(reference_trace, Mapping) else None
        )
        self._analysis_overlay_marker = (
            dict(overlay_marker) if isinstance(overlay_marker, Mapping) else None
        )
        self._analysis_measured_ph_anchor = (
            dict(measured_anchor) if isinstance(measured_anchor, Mapping) else None
        )
        self._analysis_uptake_correction = (
            dict(uptake_correction) if isinstance(uptake_correction, Mapping) else None
        )
        self._analysis_corrected_uptake_series = (
            dict(corrected_uptake_series)
            if isinstance(corrected_uptake_series, Mapping)
            else None
        )
        self._analysis_completion_from_measured_ph = (
            dict(completion_from_measured_ph)
            if isinstance(completion_from_measured_ph, Mapping)
            else None
        )
        self._analysis_latest_cycle_corrected_speciation = (
            dict(latest_cycle_corrected_speciation)
            if isinstance(latest_cycle_corrected_speciation, Mapping)
            else None
        )
        self._analysis_alignment_audit = (
            dict(alignment_audit) if isinstance(alignment_audit, Mapping) else None
        )
        self._analysis_consistency = (
            dict(consistency_audit) if isinstance(consistency_audit, Mapping) else None
        )
        self._refresh_speciation_anchor_learning_usage_status()
        if self._analysis_progress_pct_var is not None:
            self._analysis_progress_pct_var.set(
                str(
                    result_map.get("analysis_progress_text")
                    or "Based on cycle analysis data, your reaction progress is unavailable."
                )
            )
        if self._analysis_regime_var is not None:
            self._analysis_regime_var.set(
                str(result_map.get("analysis_regime_text") or "Regime: Unknown (pH unavailable)")
            )
        if self._analysis_required_co2_var is not None:
            self._analysis_required_co2_var.set(
                str(result_map.get("analysis_required_co2_text") or "CO2 required for target pH: --")
            )
        if self._analysis_co2_g_var is not None:
            self._analysis_co2_g_var.set(
                str(
                    result_map.get("analysis_co2_g_text")
                    or "CO2 uptake (raw cumulative): unavailable"
                )
            )
        if self._analysis_co2_mol_var is not None:
            self._analysis_co2_mol_var.set(
                str(result_map.get("analysis_co2_mol_text") or "--")
            )
        if self._analysis_mapped_ph_var is not None:
            self._analysis_mapped_ph_var.set(
                str(
                    result_map.get("analysis_mapped_ph_text")
                    or (
                        "pH sources | Primary (Actual observed anchor): -- | "
                        "Secondary (Calibrated estimated / Calculated): -- / -- | "
                        "Diagnostic (Plan cycle / Plan CO2 aligned): -- / --"
                    )
                )
            )
        if self._analysis_equivalence_pct_var is not None:
            self._analysis_equivalence_pct_var.set(
                str(result_map.get("analysis_equivalence_text") or "Equivalence completion: --")
            )
        if self._analysis_planning_completion_var is not None:
            self._analysis_planning_completion_var.set(
                str(
                    result_map.get("analysis_planning_completion_text")
                    or "Planning target completion: --"
                )
            )
        if self._analysis_planning_final_co2_g_var is not None:
            self._analysis_planning_final_co2_g_var.set(
                str(result_map.get("analysis_planning_final_co2_g_text") or "--")
            )
        forensic_summary = result_map.get("analysis_forensic_summary")
        self._apply_analysis_forensic_summary(
            forensic_summary if isinstance(forensic_summary, Mapping) else {}
        )
        dashboard_payload = result_map.get("analysis_dashboard")
        return dict(dashboard_payload) if isinstance(dashboard_payload, Mapping) else None

    def _update_cycle_solubility_widgets(
        self,
        result: Optional[Dict[str, Any]],
        *,
        workflow_key: Optional[str] = None,
        on_render_complete: Optional[Callable[[], None]] = None,
    ) -> None:
        """Refresh cycle timeline widgets and Analysis dashboard state.

        Purpose:
            Render cycle timeline rows, summary/status text, and Analysis
            forensic/dashboard overlays from the latest simulation output.
        Why:
            Cycle simulation completion should immediately update all dependent
            workflow surfaces from one synchronized payload.
        Inputs:
            result: Cycle simulation result payload, including timeline rows.
            workflow_key: Optional workflow override for routed UI behavior.
            on_render_complete: Optional callback invoked after staged tree/callout
                rendering completes.
        Outputs:
            None.
        Side Effects:
            Updates timeline tables, status labels, forensic KPIs, structured
            payload cache, cycle-spec view, and Analysis dashboard widgets.
        Exceptions:
            Best-effort guards prevent UI refresh interruption on widget errors.
        """
        status_var = getattr(self, "_sol_cycle_status_var", None)
        summary_var = getattr(self, "_sol_cycle_summary_var", None)
        workflow = workflow_key or self._current_solubility_workflow()
        result_map = dict(result or {})
        if workflow == "Analysis":
            migrated_result, migrated = self._analysis_maybe_migrate_persisted_result(
                result_map
            )
            if migrated:
                result_map = dict(migrated_result)
                self._set_cycle_result_for_workflow("Analysis", result_map)
        timeline = list(result_map.get("timeline") or [])
        render_payload_raw = result_map.get("timeline_render_payload")
        if isinstance(render_payload_raw, Mapping):
            render_payload = dict(render_payload_raw)
        else:
            normalized_timeline = _normalize_cycle_timeline_for_render(timeline)
            render_payload = self._build_cycle_timeline_render_payload(
                normalized_timeline,
                workflow_key=workflow,
            )
        dashboard_payload: Optional[Dict[str, Any]] = None
        if workflow == "Analysis":
            dashboard_payload = self._apply_analysis_runtime_payload(result)
        else:
            self._analysis_reference_trace = None
            self._analysis_overlay_marker = None
            self._analysis_measured_ph_anchor = None
            self._analysis_uptake_correction = None
            self._analysis_corrected_uptake_series = None
            self._analysis_completion_from_measured_ph = None
            self._analysis_latest_cycle_corrected_speciation = None
            self._analysis_alignment_audit = None
            self._analysis_consistency = None
            self._reset_analysis_forensic_summary_vars()
        rows = list(render_payload.get("tree_rows") or [])
        row_count = int(render_payload.get("display_row_count") or len(rows))
        if status_var is not None:
            if row_count <= 0:
                if (
                    workflow_key or self._current_solubility_workflow()
                ) == "Reprocessing":
                    status_var.set(
                        "Import cycles to view the timeline. Showing pass/fail speciation preview."
                    )
                else:
                    status_var.set(
                        "Cycle simulation produced no usable rows. Check for solver errors."
                    )
            else:
                mode = "Slurry" if result.get("slurry_mode") else "Solution"
                status_var.set(
                    f"{row_count} cycles simulated ({mode}, factor {result.get('supersaturation_factor', 1.0):.2f})."
                )
        if summary_var is not None:
            if row_count <= 0:
                if (
                    workflow_key or self._current_solubility_workflow()
                ) == "Reprocessing":
                    summary_var.set(
                        "Cycle timeline unavailable until cycles are imported."
                    )
                else:
                    summary_var.set("Cycle timeline unavailable.")
            else:
                final_ph = result.get("equilibrium_ph", result.get("final_ph"))
                final_solid = result.get("final_solid_mass_g")
                total_mol = result.get("total_added_moles", 0.0)
                summary_var.set(
                    "Total CO2 added (cycles): "
                    f"{total_mol:.4f} mol ({total_mol * SOL_MW_CO2:.2f} g). "
                    f"Final slurry solids â‰ˆ {final_solid or 0.0:.2f} g NaHCOâ‚ƒ "
                    f"at equilibrium pH {final_ph or float('nan'):.2f}."
                )
        structured = getattr(self, "_sol_last_structured", None)
        if isinstance(structured, dict):
            updated_structured = dict(structured)
            updated_structured["cycle_timeline"] = timeline
            updated_structured["cycle_timeline_render_payload"] = render_payload
            if workflow == "Analysis":
                updated_structured["analysis_dashboard"] = dashboard_payload
            else:
                updated_structured["analysis_dashboard"] = None
            self._sol_last_structured = updated_structured
        self._dbg(
            "plotting.render",
            "cycle_timeline_caller_cycle_sim workflow=%s timeline_rows=%s",
            workflow,
            row_count,
        )
        self._update_analysis_dashboard(
            dashboard_payload,
            workflow_key=workflow,
        )
        self._apply_cycle_timeline_render_payload_staged(
            render_payload,
            workflow_key=workflow,
            on_complete=on_render_complete,
        )

    def _reset_analysis_forensic_summary_vars(self) -> None:
        """Reset forensic Analysis KPI strings to placeholder values.

        Purpose:
            Keep KPI text coherent when non-Analysis workflows run or no
            comparison data is available.
        Why:
            Forensic KPI labels should never display stale values from prior runs.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Updates Analysis KPI `StringVar` values.
        Exceptions:
            Missing vars are ignored.
        """
        if self._analysis_ph_error_cycle_var is not None:
            self._analysis_ph_error_cycle_var.set(
                "pH residuals (cycle aligned): MAE -- | RMSE --"
            )
        if self._analysis_ph_error_co2_var is not None:
            self._analysis_ph_error_co2_var.set(
                "pH residuals (CO2 aligned): MAE -- | RMSE --"
            )
        if self._analysis_gas_delta_var is not None:
            self._analysis_gas_delta_var.set("Gas uptake delta: --")
        if self._analysis_carbonate_delta_var is not None:
            self._analysis_carbonate_delta_var.set("Carbonate/bicarbonate delta: --")
        if self._analysis_equivalence_gap_var is not None:
            self._analysis_equivalence_gap_var.set(
                "Equivalence cycle delta: -- | Completion gap: --"
            )

    def _apply_analysis_forensic_summary(self, summary: Mapping[str, Any]) -> None:
        """Apply forensic Analysis summary metrics to UI string variables.

        Purpose:
            Render aggregate comparison metrics produced by forensic timeline
            augmentation.
        Why:
            Analysis mode should surface concise KPI deltas without requiring users
            to scan the full timeline table.
        Args:
            summary: Forensic summary metrics dictionary.
        Returns:
            None.
        Side Effects:
            Updates Analysis KPI `StringVar` text values.
        Exceptions:
            Missing/invalid summary values fall back to placeholder text.
        """
        if not isinstance(summary, Mapping):
            self._reset_analysis_forensic_summary_vars()
            return
        mae_cycle = _safe_float(summary.get("ph_mae_cycle"))
        rmse_cycle = _safe_float(summary.get("ph_rmse_cycle"))
        mae_co2 = _safe_float(summary.get("ph_mae_co2"))
        rmse_co2 = _safe_float(summary.get("ph_rmse_co2"))
        gas_delta_mol = _safe_float(summary.get("gas_delta_mol"))
        gas_delta_g = _safe_float(summary.get("gas_delta_g"))
        gas_delta_pct = _safe_float(summary.get("gas_delta_pct"))
        hco3_delta = _safe_float(summary.get("hco3_delta_pct"))
        co3_delta = _safe_float(summary.get("co3_delta_pct"))
        eq_cycle_delta = _safe_float(summary.get("equivalence_cycle_delta"))
        completion_gap_pct = _safe_float(summary.get("completion_gap_pct"))

        if self._analysis_ph_error_cycle_var is not None:
            if mae_cycle is not None and rmse_cycle is not None:
                self._analysis_ph_error_cycle_var.set(
                    f"pH residuals (cycle aligned): MAE {mae_cycle:.3f} | RMSE {rmse_cycle:.3f}"
                )
            else:
                self._analysis_ph_error_cycle_var.set(
                    "pH residuals (cycle aligned): MAE -- | RMSE --"
                )
        if self._analysis_ph_error_co2_var is not None:
            if mae_co2 is not None and rmse_co2 is not None:
                self._analysis_ph_error_co2_var.set(
                    f"pH residuals (CO2 aligned): MAE {mae_co2:.3f} | RMSE {rmse_co2:.3f}"
                )
            else:
                self._analysis_ph_error_co2_var.set(
                    "pH residuals (CO2 aligned): MAE -- | RMSE --"
                )
        if self._analysis_gas_delta_var is not None:
            if gas_delta_mol is not None and gas_delta_g is not None and gas_delta_pct is not None:
                self._analysis_gas_delta_var.set(
                    "Gas uptake delta (actual - planning): "
                    f"{gas_delta_mol:+.4f} mol ({gas_delta_g:+.2f} g, {gas_delta_pct:+.1f}%)."
                )
            else:
                self._analysis_gas_delta_var.set("Gas uptake delta: --")
        if self._analysis_carbonate_delta_var is not None:
            if hco3_delta is not None and co3_delta is not None:
                self._analysis_carbonate_delta_var.set(
                    "Final species delta vs planning (CO2 aligned): "
                    f"HCO3- {hco3_delta:+.2f} pts | CO3^2- {co3_delta:+.2f} pts."
                )
            else:
                self._analysis_carbonate_delta_var.set("Carbonate/bicarbonate delta: --")
        if self._analysis_equivalence_gap_var is not None:
            eq_delta_text = "--" if eq_cycle_delta is None else f"{eq_cycle_delta:+.1f} cycles"
            gap_text = "--" if completion_gap_pct is None else f"{completion_gap_pct:+.1f}%"
            self._analysis_equivalence_gap_var.set(
                f"Equivalence cycle delta: {eq_delta_text} | Completion gap: {gap_text}"
            )

    def _analysis_interpolate_reference_series(
        self,
        x_value: Optional[float],
        x_series: Sequence[float],
        y_series: Sequence[Optional[float]],
    ) -> Tuple[Optional[float], str]:
        """Interpolate a reference series by cumulative CO2.

        Purpose:
            Provide CO2-aligned comparison values for forensic analysis metrics.
        Why:
            Cycle-index alignment alone cannot explain uptake timing drift.
        Args:
            x_value: Actual cumulative CO2 (g) for the current row.
            x_series: Planning cumulative CO2 reference series.
            y_series: Planning target series to interpolate.
        Returns:
            Tuple[Optional[float], str]: Interpolated value and quality flag.
        Side Effects:
            None.
        Exceptions:
            Invalid series/value inputs return `(None, quality_flag)`.
        """
        use_rust = False
        rust_mode = _current_rust_backend_mode()
        if rust_mode == "auto":
            benchmark = _synthetic_analysis_interpolate_reference_payload()
            use_rust = _resolve_rust_kernel_auto_policy(
                "analysis_interpolate_reference_series_core",
                rust_runner=lambda: _rust_analysis_interpolate_reference_series_core(
                    benchmark["x_value"],
                    benchmark["x_series"],
                    benchmark["y_series"],
                ),
                python_runner=lambda: _python_analysis_interpolate_reference_series_core(
                    benchmark["x_value"],
                    benchmark["x_series"],
                    benchmark["y_series"],
                ),
                parity_checker=_rust_analysis_interpolate_reference_series_core_parity,
            )
        elif rust_mode != "python":
            use_rust = True

        core_payload = (
            _rust_analysis_interpolate_reference_series_core(x_value, x_series, y_series)
            if use_rust
            else None
        )
        if not isinstance(core_payload, Mapping):
            core_payload = _python_analysis_interpolate_reference_series_core(
                x_value, x_series, y_series
            )
        mapped_value = _safe_float(core_payload.get("value"))
        quality_flag = str(core_payload.get("flag") or "").strip()
        if quality_flag not in {"ok", "sparse_reference", "out_of_range"}:
            quality_flag = "sparse_reference"
        return mapped_value, quality_flag

    def _analysis_residual_metrics(
        self, values: Sequence[Optional[float]]
    ) -> Tuple[Optional[float], Optional[float]]:
        """Compute MAE and RMSE from residual values.

        Purpose:
            Summarize pH residual dispersion for Analysis KPI reporting.
        Why:
            MAE and RMSE together reveal average and large-error behavior.
        Args:
            values: Residual sequence (actual - planning).
        Returns:
            Tuple[Optional[float], Optional[float]]: `(mae, rmse)` or `(None, None)`.
        Side Effects:
            None.
        Exceptions:
            Non-finite values are ignored.
        """
        finite_values = [
            float(v)
            for v in values or []
            if v is not None and math.isfinite(float(v))
        ]
        if not finite_values:
            return None, None
        abs_vals = [abs(v) for v in finite_values]
        mae = sum(abs_vals) / len(abs_vals)
        rmse = math.sqrt(sum(v * v for v in finite_values) / len(finite_values))
        return mae, rmse

    def _analysis_profile_key(self) -> str:
        """Return one normalized profile identifier for anchor-learning audit fields.

        Purpose:
            Resolve the active profile identifier used to annotate global
            measured-pH anchor and learning-history records.
        Why:
            Cross-profile anchor learning is globally shared, but each record
            still needs profile provenance for diagnostics and reset controls.
        Inputs:
            None.
        Outputs:
            str: Sanitized active profile key or `__default__` fallback.
        Side Effects:
            None.
        Exceptions:
            Best-effort; invalid profile names fall back to `__default__`.
        """
        raw_name = str(settings.get("current_workspace_profile_name") or "").strip()
        sanitizer = getattr(self, "_sanitize_profile_name", None)
        if callable(sanitizer):
            try:
                raw_name = str(sanitizer(raw_name) or "").strip()
            except Exception:
                raw_name = raw_name.strip()
        return raw_name or "__default__"

    def _analysis_anchor_learning_controls(
        self,
        form_snapshot: Optional[Mapping[str, Any]] = None,
    ) -> Dict[str, Any]:
        """Return normalized Analysis anchor-learning controls.

        Purpose:
            Resolve one normalized learning-controls payload used by Analysis
            calibration and runtime diagnostics.
        Why:
            UI settings and worker snapshots must drive identical control values.
        Inputs:
            form_snapshot: Optional form payload that may carry control overrides.
        Outputs:
            Dict[str, Any]: Normalized learning-enabled flag, terminal pH band,
            and objective weight.
        Side Effects:
            None.
        Exceptions:
            Invalid override values fall back to persisted/default settings.
        """
        source: Dict[str, Any] = dict(self.settings or {})
        if isinstance(form_snapshot, Mapping):
            for key in (
                ANALYSIS_ANCHOR_LEARNING_ENABLED_SETTINGS_KEY,
                ANALYSIS_TERMINAL_PH_RANGE_LOW_SETTINGS_KEY,
                ANALYSIS_TERMINAL_PH_RANGE_HIGH_SETTINGS_KEY,
                ANALYSIS_TERMINAL_PH_WEIGHT_SETTINGS_KEY,
                "learning_enabled",
                "terminal_ph_range_low",
                "terminal_ph_range_high",
                "terminal_ph_weight",
            ):
                if key in form_snapshot:
                    source[key] = form_snapshot.get(key)
        return _normalize_analysis_anchor_learning_controls(source)

    def _analysis_calibration_basis_signature(
        self, form_snapshot: Mapping[str, Any]
    ) -> Dict[str, Any]:
        """Build one stable chemistry-basis signature for calibration invalidation.

        Purpose:
            Fingerprint the core Analysis chemistry basis for calibration reuse.
        Why:
            Stored factors should be ignored when the model or chemistry basis
            changed materially between runs.
        Inputs:
            form_snapshot: Analysis form payload used for runtime execution.
        Outputs:
            Dict with normalized chemistry-basis fields.
        Side Effects:
            None.
        Exceptions:
            None.
        """
        params = form_snapshot.get("params")
        temperature_c = (
            _safe_float(getattr(params, "temperature_c", None))
            if params is not None
            else _safe_float(form_snapshot.get("temperature_c"))
        )
        return {
            "reaction_naoh_mass": _safe_float(form_snapshot.get("reaction_naoh_mass")),
            "reaction_solution_volume": _safe_float(
                form_snapshot.get("reaction_solution_volume")
            ),
            "reaction_target_ph": _safe_float(form_snapshot.get("reaction_target_ph")),
            "temperature_c": _safe_float(temperature_c, 25.0),
            "naoh_concentration_mol_l": self._analysis_basis_signature_naoh_concentration_mol_l(
                {
                    "reaction_naoh_mass": _safe_float(
                        form_snapshot.get("reaction_naoh_mass")
                    ),
                    "reaction_solution_volume": _safe_float(
                        form_snapshot.get("reaction_solution_volume")
                    ),
                }
            ),
        }

    def _analysis_basis_signature_naoh_concentration_mol_l(
        self, basis_signature: Optional[Mapping[str, Any]]
    ) -> Optional[float]:
        """Compute NaOH concentration basis in mol/L for compatibility gating.

        Purpose:
            Resolve one normalized NaOH concentration from basis-signature fields.
        Why:
            Cross-profile anchor reuse uses concentration-relative delta gating.
        Inputs:
            basis_signature: Optional chemistry-basis mapping.
        Outputs:
            Optional[float]: NaOH concentration in mol/L when resolvable.
        Side Effects:
            None.
        Exceptions:
            Invalid/missing basis fields return None.
        """
        if not isinstance(basis_signature, Mapping):
            return None
        direct_value = _safe_float(basis_signature.get("naoh_concentration_mol_l"))
        if direct_value is not None and math.isfinite(float(direct_value)) and direct_value > 0.0:
            return float(direct_value)
        naoh_mass = _safe_float(basis_signature.get("reaction_naoh_mass"))
        solution_volume = _safe_float(basis_signature.get("reaction_solution_volume"))
        if (
            naoh_mass is None
            or solution_volume is None
            or not math.isfinite(float(naoh_mass))
            or not math.isfinite(float(solution_volume))
            or naoh_mass <= 0.0
            or solution_volume <= 0.0
        ):
            return None
        return float(naoh_mass) / SOL_MW_NAOH / float(solution_volume)

    def _analysis_initialize_global_anchor_learning_state(self) -> None:
        """Initialize global anchor/history stores and migrate legacy profile cache.

        Purpose:
            Build v4.12.0 global measured-pH anchor learning state at startup.
        Why:
            Anchor learning is no longer profile-scoped; legacy profile cache data
            must be migrated into global reusable stores.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Normalizes/persists global settings keys and keeps legacy cache only
            as migration input for backward compatibility.
        Exceptions:
            Invalid payloads are ignored safely.
        """
        settings_map = self.settings if isinstance(self.settings, dict) else settings

        def _normalize_anchor_row(
            raw: Mapping[str, Any],
            *,
            profile_key_default: str,
            model_key_default: str,
            basis_default: Optional[Mapping[str, Any]] = None,
            source_default: str = "global",
            timestamp_default: Optional[str] = None,
        ) -> Optional[Dict[str, Any]]:
            """Normalize one anchor library row into the global schema."""
            if not isinstance(raw, Mapping):
                return None
            cycle_value = _safe_rust_int(
                raw.get("cycle_index", raw.get("measured_ph_cycle_index")),
                -1,
            )
            measured_ph = _safe_float(raw.get("measured_ph", raw.get("measured_ph_value")))
            if (
                cycle_value is None
                or cycle_value <= 0
                or measured_ph is None
                or not math.isfinite(float(measured_ph))
                or not (0.0 < float(measured_ph) < 14.0)
            ):
                return None
            basis_map = dict(basis_default or {})
            if isinstance(raw.get("basis_signature"), Mapping):
                basis_map.update(dict(raw.get("basis_signature")))
            reaction_naoh_mass = _safe_float(
                raw.get("reaction_naoh_mass", basis_map.get("reaction_naoh_mass"))
            )
            reaction_solution_volume = _safe_float(
                raw.get(
                    "reaction_solution_volume", basis_map.get("reaction_solution_volume")
                )
            )
            reaction_target_ph = _safe_float(
                raw.get("reaction_target_ph", basis_map.get("reaction_target_ph"))
            )
            temperature_c = _safe_float(raw.get("temperature_c", basis_map.get("temperature_c")))
            if temperature_c is None or not math.isfinite(float(temperature_c)):
                temperature_c = 25.0
            naoh_concentration = _safe_float(raw.get("naoh_concentration_mol_l"))
            if (
                naoh_concentration is None
                or not math.isfinite(float(naoh_concentration))
                or naoh_concentration <= 0.0
            ):
                naoh_concentration = self._analysis_basis_signature_naoh_concentration_mol_l(
                    {
                        "reaction_naoh_mass": reaction_naoh_mass,
                        "reaction_solution_volume": reaction_solution_volume,
                    }
                )
            return {
                "profile_key": (
                    str(raw.get("profile_key") or profile_key_default).strip()
                    or "__default__"
                ),
                "model_key": str(raw.get("model_key") or model_key_default).strip(),
                "cycle_index": int(cycle_value),
                "measured_ph": float(measured_ph),
                "source": str(raw.get("source") or source_default).strip().lower()
                or source_default,
                "reaction_naoh_mass": _safe_float(reaction_naoh_mass),
                "reaction_solution_volume": _safe_float(reaction_solution_volume),
                "reaction_target_ph": _safe_float(reaction_target_ph),
                "naoh_concentration_mol_l": _safe_float(naoh_concentration),
                "temperature_c": _safe_float(temperature_c, 25.0),
                "updated_at": str(
                    raw.get("updated_at")
                    or timestamp_default
                    or datetime.now().isoformat(timespec="seconds")
                ).strip()
                or datetime.now().isoformat(timespec="seconds"),
            }

        def _normalize_history_row(
            raw: Mapping[str, Any],
            *,
            profile_key_default: str,
            model_key_default: str,
            basis_default: Optional[Mapping[str, Any]] = None,
            source_default: str = "analysis_calibration",
            timestamp_default: Optional[str] = None,
        ) -> Optional[Dict[str, Any]]:
            """Normalize one history row into the global prior-learning schema."""
            if not isinstance(raw, Mapping):
                return None
            factors: List[float] = []
            for value in raw.get("cycle_factor_series") or []:
                factor = _safe_float(value)
                if factor is None or not math.isfinite(float(factor)):
                    continue
                factors.append(float(factor))
            if not factors:
                return None
            basis_map = dict(basis_default or {})
            if isinstance(raw.get("basis_signature"), Mapping):
                basis_map.update(dict(raw.get("basis_signature")))
            model_key_value = str(raw.get("model_key") or model_key_default).strip()
            if not model_key_value:
                return None
            anchors_raw = raw.get("anchors") or []
            anchors_rows, _anchor_errors = _normalize_analysis_measured_ph_anchors(
                anchors_raw if isinstance(anchors_raw, Sequence) else [],
                cycle_count=0,
                allow_out_of_range=True,
            )
            if not anchors_rows:
                anchor_cycle = _safe_rust_int(raw.get("anchor_cycle_index"), -1)
                anchor_ph = _safe_float(raw.get("anchor_measured_ph"))
                if (
                    anchor_cycle is not None
                    and anchor_cycle > 0
                    and anchor_ph is not None
                    and math.isfinite(float(anchor_ph))
                ):
                    anchors_rows = [
                        {
                            "cycle_index": int(anchor_cycle),
                            "measured_ph": float(anchor_ph),
                            "source": "legacy",
                        }
                    ]
            if not anchors_rows:
                return None
            reaction_naoh_mass = _safe_float(
                raw.get("reaction_naoh_mass", basis_map.get("reaction_naoh_mass"))
            )
            reaction_solution_volume = _safe_float(
                raw.get(
                    "reaction_solution_volume", basis_map.get("reaction_solution_volume")
                )
            )
            reaction_target_ph = _safe_float(
                raw.get("reaction_target_ph", basis_map.get("reaction_target_ph"))
            )
            temperature_c = _safe_float(raw.get("temperature_c", basis_map.get("temperature_c")))
            if temperature_c is None or not math.isfinite(float(temperature_c)):
                temperature_c = 25.0
            naoh_concentration = _safe_float(raw.get("naoh_concentration_mol_l"))
            if (
                naoh_concentration is None
                or not math.isfinite(float(naoh_concentration))
                or naoh_concentration <= 0.0
            ):
                naoh_concentration = self._analysis_basis_signature_naoh_concentration_mol_l(
                    {
                        "reaction_naoh_mass": reaction_naoh_mass,
                        "reaction_solution_volume": reaction_solution_volume,
                    }
                )
            latest_anchor = anchors_rows[-1]
            return {
                "profile_key": (
                    str(raw.get("profile_key") or profile_key_default).strip()
                    or "__default__"
                ),
                "model_key": model_key_value,
                "source": str(raw.get("source") or source_default).strip().lower()
                or source_default,
                "reaction_naoh_mass": _safe_float(reaction_naoh_mass),
                "reaction_solution_volume": _safe_float(reaction_solution_volume),
                "reaction_target_ph": _safe_float(reaction_target_ph),
                "naoh_concentration_mol_l": _safe_float(naoh_concentration),
                "temperature_c": _safe_float(temperature_c, 25.0),
                "anchor_cycle_index": int(latest_anchor.get("cycle_index") or 0),
                "anchor_measured_ph": _safe_float(latest_anchor.get("measured_ph")),
                "anchors": [dict(row) for row in anchors_rows],
                "alpha_pre": _safe_float(raw.get("alpha_pre")),
                "alpha_post": _safe_float(raw.get("alpha_post")),
                "split_cycle_index": _safe_rust_int(raw.get("split_cycle_index"), -1),
                "cycle_factor_series": list(factors),
                "updated_at": str(
                    raw.get("updated_at")
                    or timestamp_default
                    or datetime.now().isoformat(timespec="seconds")
                ).strip()
                or datetime.now().isoformat(timespec="seconds"),
            }

        legacy_cache: Dict[str, Dict[str, Any]] = {}
        legacy_raw = settings_map.get(ANALYSIS_UPTAKE_CALIBRATION_SETTINGS_KEY, {})
        if isinstance(legacy_raw, Mapping):
            for key, value in legacy_raw.items():
                if isinstance(value, Mapping):
                    legacy_cache[str(key)] = dict(value)
        self._analysis_uptake_calibration_profiles = dict(legacy_cache)

        library_rows: List[Dict[str, Any]] = []
        history_rows: List[Dict[str, Any]] = []
        raw_library = settings_map.get(
            ANALYSIS_GLOBAL_MEASURED_PH_ANCHOR_LIBRARY_SETTINGS_KEY
        )
        if isinstance(raw_library, Sequence):
            for row in raw_library:
                if not isinstance(row, Mapping):
                    continue
                normalized = _normalize_anchor_row(
                    row,
                    profile_key_default="__default__",
                    model_key_default=str(row.get("model_key") or "").strip(),
                    basis_default=row.get("basis_signature")
                    if isinstance(row.get("basis_signature"), Mapping)
                    else None,
                    source_default="global",
                )
                if normalized is not None and normalized.get("model_key"):
                    library_rows.append(normalized)
        raw_history = settings_map.get(ANALYSIS_ANCHOR_LEARNING_HISTORY_SETTINGS_KEY)
        if isinstance(raw_history, Sequence):
            for row in raw_history:
                if not isinstance(row, Mapping):
                    continue
                normalized = _normalize_history_row(
                    row,
                    profile_key_default="__default__",
                    model_key_default=str(row.get("model_key") or "").strip(),
                    basis_default=row.get("basis_signature")
                    if isinstance(row.get("basis_signature"), Mapping)
                    else None,
                    source_default="analysis_calibration",
                )
                if normalized is not None:
                    history_rows.append(normalized)

        for profile_key, profile_row in legacy_cache.items():
            model_key = str(profile_row.get("model_key") or "").strip()
            basis_signature = (
                dict(profile_row.get("basis_signature"))
                if isinstance(profile_row.get("basis_signature"), Mapping)
                else {}
            )
            updated_at = str(profile_row.get("updated_at") or "").strip()
            if model_key:
                for anchor in profile_row.get("anchors") or []:
                    if not isinstance(anchor, Mapping):
                        continue
                    normalized_anchor = _normalize_anchor_row(
                        anchor,
                        profile_key_default=profile_key,
                        model_key_default=model_key,
                        basis_default=basis_signature,
                        source_default="legacy_migrated",
                        timestamp_default=updated_at,
                    )
                    if normalized_anchor is not None:
                        library_rows.append(normalized_anchor)
                if not (profile_row.get("anchors") or []):
                    normalized_anchor = _normalize_anchor_row(
                        profile_row,
                        profile_key_default=profile_key,
                        model_key_default=model_key,
                        basis_default=basis_signature,
                        source_default="legacy_migrated",
                        timestamp_default=updated_at,
                    )
                    if normalized_anchor is not None:
                        library_rows.append(normalized_anchor)

                history_source = profile_row.get("history")
                if isinstance(history_source, Sequence):
                    candidates = [row for row in history_source if isinstance(row, Mapping)]
                else:
                    candidates = []
                if not candidates and profile_row.get("cycle_factor_series"):
                    candidates = [profile_row]
                for candidate in candidates:
                    normalized_history = _normalize_history_row(
                        candidate,
                        profile_key_default=profile_key,
                        model_key_default=model_key,
                        basis_default=basis_signature,
                        source_default="legacy_migrated",
                        timestamp_default=updated_at,
                    )
                    if normalized_history is not None:
                        history_rows.append(normalized_history)

        dedup_library: Dict[Tuple[Any, ...], Dict[str, Any]] = {}
        for row in library_rows:
            key = (
                str(row.get("profile_key") or "__default__"),
                str(row.get("model_key") or ""),
                int(row.get("cycle_index") or 0),
                round(float(row.get("measured_ph") or 0.0), 5),
                round(float(_safe_float(row.get("naoh_concentration_mol_l"), 0.0) or 0.0), 8),
                round(float(_safe_float(row.get("temperature_c"), 25.0) or 25.0), 4),
            )
            previous = dedup_library.get(key)
            previous_ts = str(previous.get("updated_at") or "") if previous else ""
            current_ts = str(row.get("updated_at") or "")
            if previous is None or current_ts >= previous_ts:
                dedup_library[key] = dict(row)
        merged_library = list(dedup_library.values())
        merged_library.sort(key=lambda row: str(row.get("updated_at") or ""))
        if len(merged_library) > ANALYSIS_GLOBAL_ANCHOR_LIBRARY_LIMIT:
            merged_library = merged_library[-ANALYSIS_GLOBAL_ANCHOR_LIBRARY_LIMIT :]

        dedup_history: Dict[Tuple[Any, ...], Dict[str, Any]] = {}
        for row in history_rows:
            factors = row.get("cycle_factor_series") or []
            if not isinstance(factors, Sequence) or not factors:
                continue
            row_key = (
                str(row.get("profile_key") or "__default__"),
                str(row.get("model_key") or ""),
                int(row.get("anchor_cycle_index") or 0),
                round(float(_safe_float(row.get("anchor_measured_ph"), 0.0) or 0.0), 5),
                int(len(factors)),
                round(float(_safe_float(factors[0], 0.0) or 0.0), 8),
                round(float(_safe_float(factors[-1], 0.0) or 0.0), 8),
                str(row.get("updated_at") or ""),
            )
            dedup_history[row_key] = dict(row)
        merged_history = list(dedup_history.values())
        merged_history.sort(key=lambda row: str(row.get("updated_at") or ""))
        if len(merged_history) > ANALYSIS_GLOBAL_ANCHOR_HISTORY_LIMIT:
            merged_history = merged_history[-ANALYSIS_GLOBAL_ANCHOR_HISTORY_LIMIT :]

        self._analysis_global_measured_ph_anchor_library = list(merged_library)
        self._analysis_anchor_learning_history = list(merged_history)
        settings_map[ANALYSIS_GLOBAL_MEASURED_PH_ANCHOR_LIBRARY_SETTINGS_KEY] = list(
            merged_library
        )
        settings_map[ANALYSIS_ANCHOR_LEARNING_HISTORY_SETTINGS_KEY] = list(
            merged_history
        )

    def _analysis_store_profile_calibration(
        self,
        *,
        model_key: str,
        basis_signature: Mapping[str, Any],
        calibration_payload: Mapping[str, Any],
    ) -> None:
        """Persist one successful Analysis calibration into global learning stores.

        Purpose:
            Store calibration anchors/history for cross-profile global reuse.
        Why:
            Measured-pH anchors entered in any profile should improve future
            profile predictions when chemistry is compatible.
        Inputs:
            model_key: Active predicted-pH model key at calibration time.
            basis_signature: Normalized chemistry-basis signature.
            calibration_payload: Full calibration result payload.
        Outputs:
            None.
        Side Effects:
            Updates in-memory global anchor library/history and persisted settings.
        Exceptions:
            Invalid payloads are ignored.
        """
        if not isinstance(calibration_payload, Mapping):
            return
        if str(calibration_payload.get("solver_status") or "").strip().lower() != "ok":
            return
        anchor_rows, _ = _normalize_analysis_measured_ph_anchors(
            calibration_payload.get("anchors") or [],
            cycle_count=0,
        )
        if not anchor_rows:
            legacy_cycle = _safe_rust_int(calibration_payload.get("anchor_cycle_index"), -1)
            legacy_ph = _safe_float(calibration_payload.get("anchor_measured_ph"))
            if (
                legacy_cycle is not None
                and legacy_cycle > 0
                and legacy_ph is not None
                and math.isfinite(float(legacy_ph))
            ):
                anchor_rows = [
                    {
                        "cycle_index": int(legacy_cycle),
                        "measured_ph": float(legacy_ph),
                        "source": "legacy",
                    }
                ]
        if not anchor_rows:
            return
        cycle_factor_series: List[float] = []
        for raw_factor in calibration_payload.get("cycle_factor_series") or []:
            factor_value = _safe_float(raw_factor)
            if factor_value is None or not math.isfinite(float(factor_value)):
                continue
            cycle_factor_series.append(float(factor_value))
        if not cycle_factor_series:
            return
        timestamp = datetime.now().isoformat(timespec="seconds")
        profile_key = self._analysis_profile_key()
        basis_map = dict(basis_signature or {})
        basis_concentration = self._analysis_basis_signature_naoh_concentration_mol_l(
            basis_map
        )
        basis_temperature = _safe_float(basis_map.get("temperature_c"), 25.0)
        basis_naoh_mass = _safe_float(basis_map.get("reaction_naoh_mass"))
        basis_solution_volume = _safe_float(basis_map.get("reaction_solution_volume"))
        basis_target_ph = _safe_float(basis_map.get("reaction_target_ph"))

        library_rows = list(
            getattr(self, "_analysis_global_measured_ph_anchor_library", []) or []
        )
        for anchor_row in anchor_rows:
            cycle_value = _safe_rust_int(anchor_row.get("cycle_index"), -1)
            measured_ph = _safe_float(anchor_row.get("measured_ph"))
            if (
                cycle_value is None
                or cycle_value <= 0
                or measured_ph is None
                or not math.isfinite(float(measured_ph))
            ):
                continue
            library_rows.append(
                {
                    "profile_key": profile_key,
                    "model_key": str(model_key or ""),
                    "cycle_index": int(cycle_value),
                    "measured_ph": float(measured_ph),
                    "source": str(anchor_row.get("source") or "manual").strip().lower()
                    or "manual",
                    "reaction_naoh_mass": basis_naoh_mass,
                    "reaction_solution_volume": basis_solution_volume,
                    "reaction_target_ph": basis_target_ph,
                    "naoh_concentration_mol_l": basis_concentration,
                    "temperature_c": basis_temperature,
                    "updated_at": timestamp,
                }
            )

        dedup_library: Dict[Tuple[Any, ...], Dict[str, Any]] = {}
        for row in library_rows:
            if not isinstance(row, Mapping):
                continue
            cycle_value = _safe_rust_int(row.get("cycle_index"), -1)
            measured_ph = _safe_float(row.get("measured_ph"))
            if (
                cycle_value is None
                or cycle_value <= 0
                or measured_ph is None
                or not math.isfinite(float(measured_ph))
            ):
                continue
            row_key = (
                str(row.get("profile_key") or "__default__").strip() or "__default__",
                str(row.get("model_key") or "").strip(),
                int(cycle_value),
                round(float(measured_ph), 5),
                round(
                    float(_safe_float(row.get("naoh_concentration_mol_l"), 0.0) or 0.0),
                    8,
                ),
                round(float(_safe_float(row.get("temperature_c"), 25.0) or 25.0), 4),
            )
            previous = dedup_library.get(row_key)
            previous_ts = str(previous.get("updated_at") or "") if previous else ""
            current_ts = str(row.get("updated_at") or "")
            if previous is None or current_ts >= previous_ts:
                dedup_library[row_key] = dict(row)
        merged_library = list(dedup_library.values())
        merged_library.sort(key=lambda row: str(row.get("updated_at") or ""))
        if len(merged_library) > ANALYSIS_GLOBAL_ANCHOR_LIBRARY_LIMIT:
            merged_library = merged_library[-ANALYSIS_GLOBAL_ANCHOR_LIBRARY_LIMIT :]

        history_rows = list(getattr(self, "_analysis_anchor_learning_history", []) or [])
        history_rows.append(
            {
                "profile_key": profile_key,
                "model_key": str(model_key or ""),
                "source": "analysis_calibration",
                "reaction_naoh_mass": basis_naoh_mass,
                "reaction_solution_volume": basis_solution_volume,
                "reaction_target_ph": basis_target_ph,
                "naoh_concentration_mol_l": basis_concentration,
                "temperature_c": basis_temperature,
                "anchor_cycle_index": int(anchor_rows[-1]["cycle_index"]),
                "anchor_measured_ph": float(anchor_rows[-1]["measured_ph"]),
                "anchors": [dict(row) for row in anchor_rows],
                "alpha_pre": _safe_float(calibration_payload.get("alpha_pre")),
                "alpha_post": _safe_float(calibration_payload.get("alpha_post")),
                "split_cycle_index": _safe_rust_int(
                    calibration_payload.get("split_cycle_index"), -1
                ),
                "cycle_factor_series": list(cycle_factor_series),
                "updated_at": timestamp,
            }
        )
        dedup_history: Dict[Tuple[Any, ...], Dict[str, Any]] = {}
        for row in history_rows:
            if not isinstance(row, Mapping):
                continue
            factors = row.get("cycle_factor_series") or []
            if not isinstance(factors, Sequence):
                continue
            normalized_factors: List[float] = []
            for raw in factors:
                value = _safe_float(raw)
                if value is None or not math.isfinite(float(value)):
                    continue
                normalized_factors.append(float(value))
            if not normalized_factors:
                continue
            anchor_cycle = _safe_rust_int(row.get("anchor_cycle_index"), -1)
            anchor_ph = _safe_float(row.get("anchor_measured_ph"))
            if (
                anchor_cycle is None
                or anchor_cycle <= 0
                or anchor_ph is None
                or not math.isfinite(float(anchor_ph))
            ):
                continue
            row_key = (
                str(row.get("profile_key") or "__default__").strip() or "__default__",
                str(row.get("model_key") or "").strip(),
                int(anchor_cycle),
                round(float(anchor_ph), 5),
                int(len(normalized_factors)),
                round(float(normalized_factors[0]), 8),
                round(float(normalized_factors[-1]), 8),
                str(row.get("updated_at") or ""),
            )
            normalized_row = dict(row)
            normalized_row["cycle_factor_series"] = list(normalized_factors)
            dedup_history[row_key] = normalized_row
        merged_history = list(dedup_history.values())
        merged_history.sort(key=lambda row: str(row.get("updated_at") or ""))
        if len(merged_history) > ANALYSIS_GLOBAL_ANCHOR_HISTORY_LIMIT:
            merged_history = merged_history[-ANALYSIS_GLOBAL_ANCHOR_HISTORY_LIMIT :]

        self._analysis_global_measured_ph_anchor_library = list(merged_library)
        self._analysis_anchor_learning_history = list(merged_history)
        self.settings[ANALYSIS_GLOBAL_MEASURED_PH_ANCHOR_LIBRARY_SETTINGS_KEY] = list(
            merged_library
        )
        self.settings[ANALYSIS_ANCHOR_LEARNING_HISTORY_SETTINGS_KEY] = list(
            merged_history
        )
        self._refresh_speciation_anchor_learning_usage_status()
        try:
            self._schedule_save_settings()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _analysis_profile_record_matches_signature(
        self,
        *,
        record: Mapping[str, Any],
        model_key: str,
        basis_signature: Mapping[str, Any],
    ) -> bool:
        """Return whether one global-learning row is chemistry compatible.

        Purpose:
            Apply v4.12.0 global anchor-learning compatibility gate rules.
        Why:
            Cross-profile learning should reuse only moderately similar chemistry.
        Inputs:
            record: Candidate global anchor/history row.
            model_key: Active predicted-pH model key.
            basis_signature: Active chemistry-basis signature map.
        Outputs:
            bool indicating whether the record is compatible.
        Side Effects:
            None.
        Exceptions:
            Invalid record schema returns False.
        """
        if not isinstance(record, Mapping):
            return False
        if str(record.get("model_key") or "").strip() != str(model_key or "").strip():
            return False
        current_conc = self._analysis_basis_signature_naoh_concentration_mol_l(
            basis_signature
        )
        record_conc = _safe_float(record.get("naoh_concentration_mol_l"))
        if (
            current_conc is None
            or record_conc is None
            or not math.isfinite(float(current_conc))
            or not math.isfinite(float(record_conc))
            or current_conc <= 0.0
            or record_conc <= 0.0
        ):
            return False
        rel_delta = abs(float(record_conc) - float(current_conc)) / max(
            abs(float(current_conc)), 1e-12
        )
        if rel_delta > ANALYSIS_GLOBAL_ANCHOR_COMPAT_NAOH_REL_DELTA_MAX:
            return False
        current_temp = _safe_float(basis_signature.get("temperature_c"))
        record_temp = _safe_float(record.get("temperature_c"))
        if (
            current_temp is None
            or record_temp is None
            or not math.isfinite(float(current_temp))
            or not math.isfinite(float(record_temp))
        ):
            return False
        return (
            abs(float(record_temp) - float(current_temp))
            <= ANALYSIS_GLOBAL_ANCHOR_COMPAT_TEMPERATURE_DELTA_C_MAX
        )

    def _analysis_resolve_measured_anchors(
        self,
        *,
        form_snapshot: Mapping[str, Any],
        row_count: int,
        model_key: str,
        basis_signature: Mapping[str, Any],
    ) -> List[Dict[str, Any]]:
        """Resolve current-run measured-pH anchors with global-learning diagnostics.

        Purpose:
            Build one normalized hard-anchor list for Analysis uptake calibration.
        Why:
            Manual/profile-entered anchors should constrain the current solve,
            while compatible global observations remain soft learning context so
            stale cross-profile pH points cannot force a local discontinuity.
        Inputs:
            form_snapshot: Analysis form payload.
            row_count: Available timeline cycle count.
            model_key: Active predicted-pH model key.
            basis_signature: Current chemistry-basis signature.
        Outputs:
            List of normalized current-run anchor rows sorted by cycle index.
        Side Effects:
            Updates `_analysis_last_anchor_resolution_meta` diagnostics with
            manual/global source counts for the current run.
        Exceptions:
            Invalid rows are filtered out.
        """
        anchor_enabled = bool(form_snapshot.get("measured_ph_anchor_enabled", True))
        if not anchor_enabled:
            self._analysis_last_anchor_resolution_meta = {
                "manual_anchor_count": 0,
                "global_compatible_anchor_count": 0,
                "resolved_anchor_count": 0,
                "resolved_anchor_source_counts": {},
            }
            return []
        candidate_rows: List[Dict[str, Any]] = []
        for row in form_snapshot.get("measured_ph_anchors") or []:
            if not isinstance(row, Mapping):
                continue
            candidate_rows.append(
                {
                    "cycle_index": row.get(
                        "cycle_index", row.get("measured_ph_cycle_index")
                    ),
                    "measured_ph": row.get("measured_ph", row.get("measured_ph_value")),
                    "source": str(row.get("source") or "manual"),
                }
            )
        measured_ph_value = _safe_float(form_snapshot.get("measured_ph_value"))
        cycle_index_raw = form_snapshot.get("measured_ph_cycle_index")
        cycle_index = None
        if cycle_index_raw not in (None, ""):
            try:
                cycle_index = int(round(float(cycle_index_raw)))
            except Exception:
                cycle_index = None
        if measured_ph_value is not None and cycle_index is not None and cycle_index > 0:
            candidate_rows.append(
                {
                    "cycle_index": cycle_index,
                    "measured_ph": measured_ph_value,
                    "source": "legacy",
                }
            )
        manual_rows, _manual_errors = _normalize_analysis_measured_ph_anchors(
            candidate_rows,
            cycle_count=row_count,
        )
        learning_controls = self._analysis_anchor_learning_controls(form_snapshot)
        use_compatible_learning = bool(learning_controls.get("learning_enabled", True))
        global_rows: List[Dict[str, Any]] = []
        library_rows = (
            getattr(self, "_analysis_global_measured_ph_anchor_library", []) or []
        )

        def _row_matches_current_basis(row: Mapping[str, Any]) -> bool:
            """Return whether one cached global row matches this run's chemistry.

            Purpose:
                Inline the compatibility gate with run-level constants captured
                once outside the library scan.
            Why:
                Anchor libraries can retain many historical rows; avoiding
                repeated concentration/temperature resolution keeps Analysis
                refresh cost proportional to the cache size with low overhead.
            Inputs:
                row: Candidate global measured-pH anchor row.
            Outputs:
                bool: True when the row is compatible with the current model,
                NaOH concentration, and temperature tolerance.
            Side Effects:
                None.
            Exceptions:
                Invalid or non-finite row fields return False.
            """
            if str(row.get("model_key") or "").strip() != current_model_key:
                return False
            record_conc = _safe_float(row.get("naoh_concentration_mol_l"))
            if (
                current_conc is None
                or record_conc is None
                or not math.isfinite(float(current_conc))
                or not math.isfinite(float(record_conc))
                or current_conc <= 0.0
                or record_conc <= 0.0
            ):
                return False
            rel_delta = abs(float(record_conc) - float(current_conc)) / max(
                abs(float(current_conc)), 1e-12
            )
            if rel_delta > ANALYSIS_GLOBAL_ANCHOR_COMPAT_NAOH_REL_DELTA_MAX:
                return False
            record_temp = _safe_float(row.get("temperature_c"))
            if (
                current_temp is None
                or record_temp is None
                or not math.isfinite(float(current_temp))
                or not math.isfinite(float(record_temp))
            ):
                return False
            return (
                abs(float(record_temp) - float(current_temp))
                <= ANALYSIS_GLOBAL_ANCHOR_COMPAT_TEMPERATURE_DELTA_C_MAX
            )

        if use_compatible_learning and isinstance(library_rows, Sequence):
            current_model_key = str(model_key or "").strip()
            current_conc = self._analysis_basis_signature_naoh_concentration_mol_l(
                basis_signature
            )
            current_temp = _safe_float(basis_signature.get("temperature_c"))
            for row in library_rows:
                if not hasattr(row, "get"):
                    continue
                if not _row_matches_current_basis(row):
                    continue
                global_rows.append(
                    {
                        "cycle_index": row.get("cycle_index"),
                        "measured_ph": row.get("measured_ph"),
                        "source": "global_inherited",
                    }
                )
        normalized_global, _global_errors = _normalize_analysis_measured_ph_anchors(
            global_rows,
            cycle_count=row_count,
        )
        resolved_rows, _resolved_errors = _normalize_analysis_measured_ph_anchors(
            list(manual_rows),
            cycle_count=row_count,
        )
        source_counts: Dict[str, int] = {}
        for row in resolved_rows:
            source_key = str(row.get("source") or "unknown").strip().lower() or "unknown"
            source_counts[source_key] = source_counts.get(source_key, 0) + 1
        self._analysis_last_anchor_resolution_meta = {
            "manual_anchor_count": int(len(manual_rows)),
            "global_compatible_anchor_count": int(len(normalized_global)),
            "global_soft_prior_anchor_count": int(len(normalized_global)),
            "resolved_anchor_count": int(len(resolved_rows)),
            "resolved_anchor_source_counts": dict(source_counts),
        }
        return resolved_rows

    def _analysis_resolve_profile_learning_prior(
        self,
        *,
        row_count: int,
        model_key: str,
        basis_signature: Mapping[str, Any],
    ) -> Tuple[List[float], int, Dict[str, Any]]:
        """Resolve global-learning prior factors for compatible chemistry history.

        Purpose:
            Derive one bounded prior factor curve for the next calibration solve.
        Why:
            Compatible calibrations from any profile should seed future solves.
        Inputs:
            row_count: Number of available timeline cycles.
            model_key: Active predicted-pH model key.
            basis_signature: Active chemistry-basis signature.
        Outputs:
            Tuple of `(prior_cycle_factor_series, sample_count, diagnostics)`.
        Side Effects:
            None.
        Exceptions:
            Invalid history rows are skipped.
        """
        if row_count <= 0:
            return [], 0, {"profile_sample_counts": {}, "points_used": 0}
        history_rows = getattr(self, "_analysis_anchor_learning_history", []) or []
        if not isinstance(history_rows, Sequence):
            return [], 0, {"profile_sample_counts": {}, "points_used": 0}
        totals: List[float] = [0.0 for _ in range(row_count)]
        counts: List[int] = [0 for _ in range(row_count)]
        sample_count = 0
        points_used = 0
        profile_sample_counts: Dict[str, int] = {}
        for history_row in history_rows:
            if not isinstance(history_row, Mapping):
                continue
            if not self._analysis_profile_record_matches_signature(
                record=history_row,
                model_key=model_key,
                basis_signature=basis_signature,
            ):
                continue
            factors = history_row.get("cycle_factor_series") or []
            if not isinstance(factors, Sequence):
                continue
            used = False
            for idx in range(min(row_count, len(factors))):
                factor_value = _safe_float(factors[idx])
                if factor_value is None or not math.isfinite(float(factor_value)):
                    continue
                totals[idx] += float(factor_value)
                counts[idx] += 1
                used = True
                points_used += 1
            if used:
                sample_count += 1
                profile_key = (
                    str(history_row.get("profile_key") or "__default__").strip()
                    or "__default__"
                )
                profile_sample_counts[profile_key] = (
                    profile_sample_counts.get(profile_key, 0) + 1
                )
        if sample_count <= 0:
            return [], 0, {"profile_sample_counts": {}, "points_used": 0}
        prior_series: List[float] = []
        last_value = 1.0
        for idx in range(row_count):
            if counts[idx] > 0:
                last_value = totals[idx] / counts[idx]
            prior_series.append(last_value)
        return prior_series, sample_count, {
            "profile_sample_counts": dict(profile_sample_counts),
            "points_used": int(points_used),
        }

    def _analysis_ml_feature_map_for_cycle(
        self,
        *,
        cycle_index: int,
        row_count: int,
        baseline_corrected_ph: Optional[float],
        cycle_uptake_mol: Optional[float],
        cumulative_uptake_mol: Optional[float],
        anchor_cycle_index: Optional[int],
        basis_signature: Mapping[str, Any],
    ) -> Dict[str, float]:
        """Build one deterministic feature map for ML residual correction.

        Purpose:
            Encode per-cycle chemistry/progression context into a compact numeric
            feature map consumed by the Analysis residual ML model.
        Why:
            ML correction should learn residual structure from cycle position and
            chemistry context rather than only piecewise scale factors.
        Inputs:
            cycle_index: 1-based cycle index.
            row_count: Total available cycle rows.
            baseline_corrected_ph: Baseline calibrated pH before ML residual.
            cycle_uptake_mol: Baseline corrected cycle uptake in mol.
            cumulative_uptake_mol: Baseline corrected cumulative uptake in mol.
            anchor_cycle_index: Primary anchor cycle index, when available.
            basis_signature: Chemistry-basis signature for compatibility features.
        Outputs:
            Dict[str, float]: Numeric feature map keyed by
            `ANALYSIS_ML_FEATURE_NAMES`.
        Side Effects:
            None.
        Exceptions:
            Invalid values are normalized to finite defaults.
        """
        safe_row_count = max(int(row_count or 0), 1)
        safe_cycle = max(int(cycle_index or 0), 1)
        cycle_ratio = min(max(float(safe_cycle) / float(safe_row_count), 0.0), 1.0)
        anchor_cycle = _safe_rust_int(anchor_cycle_index, -1)
        if anchor_cycle is None or anchor_cycle <= 0:
            anchor_distance = 0.0
        else:
            anchor_distance = min(
                abs(float(safe_cycle - anchor_cycle)) / float(safe_row_count),
                1.0,
            )
        naoh_conc = self._analysis_basis_signature_naoh_concentration_mol_l(basis_signature)
        temperature_c = _safe_float(basis_signature.get("temperature_c"), 25.0)
        return {
            "cycle_index": float(safe_cycle),
            "cycle_ratio": float(cycle_ratio),
            "baseline_corrected_ph": _safe_float(baseline_corrected_ph, 0.0),
            "cycle_uptake_mol": max(_safe_float(cycle_uptake_mol, 0.0), 0.0),
            "cumulative_uptake_mol": max(_safe_float(cumulative_uptake_mol, 0.0), 0.0),
            "anchor_distance": float(anchor_distance),
            "naoh_concentration_mol_l": max(_safe_float(naoh_conc, 0.0), 0.0),
            "temperature_c": _safe_float(temperature_c, 25.0),
        }

    @staticmethod
    def _analysis_ml_vector_from_feature_map(
        feature_map: Mapping[str, Any],
    ) -> List[float]:
        """Project ML feature mapping into fixed-order numeric vector.

        Purpose:
            Convert feature maps into deterministic vector order for model fit
            and prediction.
        Why:
            Persisted models and runtime prediction must share one stable feature
            ordering contract.
        Inputs:
            feature_map: Mapping containing per-feature numeric values.
        Outputs:
            List[float]: Ordered feature vector using
            `ANALYSIS_ML_FEATURE_NAMES`.
        Side Effects:
            None.
        Exceptions:
            Missing/non-finite values are normalized to zero.
        """
        vector: List[float] = []
        for key in ANALYSIS_ML_FEATURE_NAMES:
            value = _safe_float(feature_map.get(key), 0.0)
            if value is None or not math.isfinite(float(value)):
                value = 0.0
            vector.append(float(value))
        return vector

    @staticmethod
    def _analysis_ml_predict_from_model_state(
        model_state: Mapping[str, Any],
        feature_vector: Sequence[float],
    ) -> Optional[float]:
        """Predict one residual value from persisted ML model state.

        Purpose:
            Apply one fitted residual model to a single cycle feature vector.
        Why:
            Analysis runtime needs deterministic model reuse for compatible
            chemistry contexts when retraining is not requested.
        Inputs:
            model_state: Persisted model payload containing normalization and
                coefficient arrays.
            feature_vector: Ordered numeric feature vector.
        Outputs:
            Optional[float]: Predicted pH residual, or None when model state is
            invalid.
        Side Effects:
            None.
        Exceptions:
            Invalid state schema returns None.
        """
        if not isinstance(model_state, Mapping):
            return None
        means = list(model_state.get("feature_means") or [])
        scales = list(model_state.get("feature_scales") or [])
        coeffs = list(model_state.get("coefficients") or [])
        if not (
            len(means) == len(scales) == len(coeffs) == len(feature_vector)
            and len(feature_vector) == len(ANALYSIS_ML_FEATURE_NAMES)
        ):
            return None
        intercept = _safe_float(model_state.get("intercept"), 0.0)
        if intercept is None or not math.isfinite(float(intercept)):
            intercept = 0.0
        residual = float(intercept)
        for idx, raw_value in enumerate(feature_vector):
            value = _safe_float(raw_value, 0.0)
            mean = _safe_float(means[idx], 0.0)
            scale = _safe_float(scales[idx], 1.0)
            coeff = _safe_float(coeffs[idx], 0.0)
            if value is None or not math.isfinite(float(value)):
                value = 0.0
            if mean is None or not math.isfinite(float(mean)):
                mean = 0.0
            if scale is None or not math.isfinite(float(scale)) or abs(float(scale)) <= 1e-12:
                scale = 1.0
            if coeff is None or not math.isfinite(float(coeff)):
                coeff = 0.0
            residual += ((float(value) - float(mean)) / float(scale)) * float(coeff)
        return residual if math.isfinite(float(residual)) else None

    def _analysis_apply_hybrid_ml_correction(
        self,
        *,
        rows: Sequence[Mapping[str, Any]],
        calibration_payload: Mapping[str, Any],
        anchor_rows: Sequence[Mapping[str, Any]],
        model_key: str,
        basis_signature: Mapping[str, Any],
        apply_ml_correction: bool,
        allow_retraining: bool,
        anchor_fit_tolerance_ph: float,
    ) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
        """Apply hybrid residual ML correction on top of baseline calibration.

        Purpose:
            Run Analysis pH correction stage as baseline calibration plus an ML
            residual model, with deterministic chemistry-gated global reuse.
        Why:
            Piecewise calibration alone can leave structured residual errors; a
            residual learner improves alignment while preserving fail-closed
            fallback to baseline behavior.
        Inputs:
            rows: Analysis timeline rows for this run.
            calibration_payload: Baseline measured-anchor calibration payload.
            anchor_rows: Normalized measured-pH anchors for this run.
            model_key: Active pH model key.
            basis_signature: Chemistry signature for compatibility gating.
            apply_ml_correction: Whether ML-corrected pH should be applied now.
            allow_retraining: True when action semantics permit retraining.
            anchor_fit_tolerance_ph: Absolute pH tolerance used to guard anchor
                fit acceptance for ML-adjusted series.
        Outputs:
            Tuple of `(rows, calibration_payload)` including ML diagnostics,
            additive ML fields, and optional corrected-series replacement.
        Side Effects:
            May update global ML training/model settings when retraining is
            enabled and a valid model is fit.
        Exceptions:
            Any ML-stage error fails closed to baseline calibration with explicit
            status metadata.
        """
        rows_out = [dict(row or {}) for row in rows if isinstance(row, Mapping)]
        payload = dict(calibration_payload or {})
        payload["ml_correction_applied"] = False
        payload["ml_training_sample_count"] = 0
        payload["ml_fit_error"] = None
        payload["ml_model_version"] = str(
            self.settings.get(
                ANALYSIS_ML_MODEL_VERSION_SETTINGS_KEY, ANALYSIS_ML_MODEL_VERSION
            )
            or ANALYSIS_ML_MODEL_VERSION
        ).strip() or ANALYSIS_ML_MODEL_VERSION
        payload["ml_correction_status"] = "baseline_only"
        payload["ml_model_source"] = "none"
        payload["ml_failure_reason"] = ""
        payload["ml_corrected_ph_series"] = []
        payload["ml_corrected_fraction_series"] = []
        tolerance_ph = _safe_float(
            anchor_fit_tolerance_ph, ANALYSIS_ANCHOR_FIT_TOLERANCE_PH_DEFAULT
        )
        if tolerance_ph is None or not math.isfinite(float(tolerance_ph)):
            tolerance_ph = ANALYSIS_ANCHOR_FIT_TOLERANCE_PH_DEFAULT
        tolerance_ph = float(max(0.01, min(float(tolerance_ph), 1.00)))
        payload["anchor_fit_tolerance_ph"] = tolerance_ph
        payload["baseline_anchor_mae_ph"] = None
        payload["ml_anchor_mae_ph"] = None
        payload["ml_anchor_guard_pass"] = None
        payload["ml_anchor_guard_details"] = []
        if not rows_out:
            payload["ml_correction_status"] = "baseline_only_empty_rows"
            return rows_out, payload
        baseline_ph_series = [
            _safe_float(value)
            for value in list(payload.get("corrected_ph_series") or [])
        ]
        if len(baseline_ph_series) != len(rows_out):
            payload["ml_correction_status"] = "baseline_only_missing_ph_series"
            return rows_out, payload

        baseline_cycle_uptake_mol = [
            _safe_float(value)
            for value in list(payload.get("corrected_cycle_uptake_mol_series") or [])
        ]
        baseline_cumulative_uptake_mol = [
            _safe_float(value)
            for value in list(payload.get("corrected_cumulative_co2_mol_series") or [])
        ]
        if len(baseline_cycle_uptake_mol) != len(rows_out):
            baseline_cycle_uptake_mol = [
                _safe_float(row.get("corrected_cycle_co2_mol"))
                if _safe_float(row.get("corrected_cycle_co2_mol")) is not None
                else _safe_float(row.get("co2_moles"))
                for row in rows_out
            ]
        if len(baseline_cumulative_uptake_mol) != len(rows_out):
            baseline_cumulative_uptake_mol = []
            running_mol = 0.0
            for idx, row in enumerate(rows_out):
                cumulative_mol = _safe_float(row.get("corrected_cumulative_co2_mol"))
                if cumulative_mol is None:
                    cycle_mol = (
                        baseline_cycle_uptake_mol[idx]
                        if idx < len(baseline_cycle_uptake_mol)
                        else None
                    )
                    running_mol += max(_safe_float(cycle_mol, 0.0), 0.0)
                    cumulative_mol = running_mol
                else:
                    running_mol = max(float(cumulative_mol), 0.0)
                baseline_cumulative_uptake_mol.append(float(cumulative_mol))

        normalized_anchor_rows, _anchor_errors = _normalize_analysis_measured_ph_anchors(
            anchor_rows or [],
            cycle_count=len(rows_out),
        )
        primary_anchor_cycle = (
            _safe_rust_int(normalized_anchor_rows[-1].get("cycle_index"), -1)
            if normalized_anchor_rows
            else None
        )
        profile_key = self._analysis_profile_key()
        basis_naoh_conc = self._analysis_basis_signature_naoh_concentration_mol_l(
            basis_signature
        )
        basis_temp_c = _safe_float(basis_signature.get("temperature_c"), 25.0)
        now_iso = datetime.now().isoformat(timespec="seconds")
        model_version = payload["ml_model_version"]

        current_training_rows: List[Dict[str, Any]] = []
        for anchor in normalized_anchor_rows:
            cycle_idx = _safe_rust_int(anchor.get("cycle_index"), -1)
            measured_ph = _safe_float(anchor.get("measured_ph"))
            if (
                cycle_idx is None
                or cycle_idx <= 0
                or cycle_idx > len(rows_out)
                or measured_ph is None
                or not math.isfinite(float(measured_ph))
            ):
                continue
            baseline_ph = _safe_float(baseline_ph_series[cycle_idx - 1])
            if baseline_ph is None or not math.isfinite(float(baseline_ph)):
                continue
            feature_map = self._analysis_ml_feature_map_for_cycle(
                cycle_index=int(cycle_idx),
                row_count=len(rows_out),
                baseline_corrected_ph=baseline_ph,
                cycle_uptake_mol=(
                    baseline_cycle_uptake_mol[cycle_idx - 1]
                    if cycle_idx - 1 < len(baseline_cycle_uptake_mol)
                    else None
                ),
                cumulative_uptake_mol=(
                    baseline_cumulative_uptake_mol[cycle_idx - 1]
                    if cycle_idx - 1 < len(baseline_cumulative_uptake_mol)
                    else None
                ),
                anchor_cycle_index=primary_anchor_cycle,
                basis_signature=basis_signature,
            )
            residual = float(measured_ph) - float(baseline_ph)
            current_training_rows.append(
                {
                    "profile_key": profile_key,
                    "model_key": str(model_key or "").strip(),
                    "source": str(anchor.get("source") or "manual").strip().lower()
                    or "manual",
                    "cycle_index": int(cycle_idx),
                    "measured_ph": float(measured_ph),
                    "baseline_corrected_ph": float(baseline_ph),
                    "residual": float(residual),
                    "feature_map": dict(feature_map),
                    "naoh_concentration_mol_l": _safe_float(basis_naoh_conc),
                    "temperature_c": _safe_float(basis_temp_c, 25.0),
                    "updated_at": now_iso,
                    "model_version": model_version,
                }
            )

        compatible_training_rows: List[Dict[str, Any]] = []
        for row in list(getattr(self, "_analysis_ml_training_store", []) or []):
            if not isinstance(row, Mapping):
                continue
            if str(row.get("model_version") or model_version).strip() != model_version:
                continue
            if not self._analysis_profile_record_matches_signature(
                record=row,
                model_key=model_key,
                basis_signature=basis_signature,
            ):
                continue
            compatible_training_rows.append(dict(row))
        compatible_models: List[Dict[str, Any]] = []
        model_state_rows = (
            list((getattr(self, "_analysis_ml_model_state", {}) or {}).get("models") or [])
            if isinstance(getattr(self, "_analysis_ml_model_state", None), Mapping)
            else []
        )
        for model_row in model_state_rows:
            if not isinstance(model_row, Mapping):
                continue
            if str(model_row.get("model_version") or model_version).strip() != model_version:
                continue
            if not self._analysis_profile_record_matches_signature(
                record=model_row,
                model_key=model_key,
                basis_signature=basis_signature,
            ):
                continue
            compatible_models.append(dict(model_row))
        compatible_models.sort(key=lambda row: str(row.get("updated_at") or ""))
        active_model_state: Optional[Dict[str, Any]] = (
            dict(compatible_models[-1]) if compatible_models else None
        )

        if allow_retraining:
            training_rows_for_fit = list(compatible_training_rows) + list(current_training_rows)
            x_rows: List[List[float]] = []
            y_values: List[float] = []
            for row in training_rows_for_fit:
                feature_map = row.get("feature_map")
                residual = _safe_float(row.get("residual"))
                if not isinstance(feature_map, Mapping):
                    continue
                if residual is None or not math.isfinite(float(residual)):
                    continue
                feature_vector = self._analysis_ml_vector_from_feature_map(feature_map)
                x_rows.append(feature_vector)
                y_values.append(float(residual))
            if len(x_rows) >= 2:
                try:
                    x_matrix = np.array(x_rows, dtype=float)
                    y_array = np.array(y_values, dtype=float)
                    feature_means = np.mean(x_matrix, axis=0)
                    feature_scales = np.std(x_matrix, axis=0)
                    feature_scales = np.where(feature_scales <= 1e-12, 1.0, feature_scales)
                    x_norm = (x_matrix - feature_means) / feature_scales
                    ridge_lambda = 0.35
                    gram = np.matmul(x_norm.T, x_norm)
                    rhs = np.matmul(x_norm.T, y_array)
                    coeffs = np.linalg.solve(
                        gram + (ridge_lambda * np.eye(x_norm.shape[1], dtype=float)),
                        rhs,
                    )
                    intercept = float(np.mean(y_array) - np.dot(np.mean(x_norm, axis=0), coeffs))
                    y_pred = intercept + np.matmul(x_norm, coeffs)
                    fit_rmse = float(
                        math.sqrt(
                            max(
                                float(np.mean((y_array - y_pred) ** 2)),
                                0.0,
                            )
                        )
                    )
                    active_model_state = {
                        "profile_key": profile_key,
                        "model_key": str(model_key or "").strip(),
                        "source": "analysis_ml_residual_ridge",
                        "naoh_concentration_mol_l": _safe_float(basis_naoh_conc),
                        "temperature_c": _safe_float(basis_temp_c, 25.0),
                        "feature_names": list(ANALYSIS_ML_FEATURE_NAMES),
                        "feature_means": [float(value) for value in feature_means],
                        "feature_scales": [float(value) for value in feature_scales],
                        "coefficients": [float(value) for value in coeffs],
                        "intercept": float(intercept),
                        "lambda": float(ridge_lambda),
                        "sample_count": int(len(y_values)),
                        "fit_rmse": fit_rmse,
                        "updated_at": now_iso,
                        "model_version": model_version,
                    }
                    payload["ml_training_sample_count"] = int(len(y_values))
                    payload["ml_fit_error"] = fit_rmse
                    payload["ml_model_source"] = "retrained_current_run"
                    payload["ml_correction_status"] = (
                        "model_ready_apply_on"
                        if apply_ml_correction
                        else "model_ready_apply_off"
                    )
                    persisted_training = list(
                        getattr(self, "_analysis_ml_training_store", []) or []
                    ) + list(current_training_rows)
                    dedup_training: Dict[Tuple[Any, ...], Dict[str, Any]] = {}
                    for row in persisted_training:
                        if not isinstance(row, Mapping):
                            continue
                        cycle_idx = _safe_rust_int(row.get("cycle_index"), -1)
                        measured_ph = _safe_float(row.get("measured_ph"))
                        baseline_ph = _safe_float(row.get("baseline_corrected_ph"))
                        if (
                            cycle_idx is None
                            or cycle_idx <= 0
                            or measured_ph is None
                            or baseline_ph is None
                        ):
                            continue
                        row_key = (
                            str(row.get("profile_key") or "__default__").strip()
                            or "__default__",
                            str(row.get("model_key") or "").strip(),
                            int(cycle_idx),
                            round(float(measured_ph), 4),
                            round(float(baseline_ph), 4),
                            round(
                                float(
                                    _safe_float(row.get("naoh_concentration_mol_l"), 0.0)
                                    or 0.0
                                ),
                                6,
                            ),
                            round(float(_safe_float(row.get("temperature_c"), 25.0) or 25.0), 3),
                        )
                        previous = dedup_training.get(row_key)
                        previous_ts = str(previous.get("updated_at") or "") if previous else ""
                        current_ts = str(row.get("updated_at") or "")
                        if previous is None or current_ts >= previous_ts:
                            dedup_training[row_key] = dict(row)
                    merged_training = list(dedup_training.values())
                    merged_training.sort(key=lambda row: str(row.get("updated_at") or ""))
                    self._analysis_ml_training_store = merged_training[
                        -ANALYSIS_ML_TRAINING_STORE_LIMIT:
                    ]
                    ml_state_map = (
                        dict(getattr(self, "_analysis_ml_model_state", {}) or {})
                        if isinstance(getattr(self, "_analysis_ml_model_state", None), Mapping)
                        else {}
                    )
                    models = [
                        dict(row)
                        for row in (ml_state_map.get("models") or [])
                        if isinstance(row, Mapping)
                    ]
                    models.append(dict(active_model_state))
                    models.sort(key=lambda row: str(row.get("updated_at") or ""))
                    ml_state_map["models"] = models[-ANALYSIS_ML_MODEL_STATE_LIMIT:]
                    self._analysis_ml_model_state = ml_state_map
                    self.settings[ANALYSIS_ML_TRAINING_STORE_SETTINGS_KEY] = list(
                        self._analysis_ml_training_store
                    )
                    self.settings[ANALYSIS_ML_MODEL_STATE_SETTINGS_KEY] = dict(
                        self._analysis_ml_model_state
                    )
                    self.settings[ANALYSIS_ML_MODEL_VERSION_SETTINGS_KEY] = model_version
                    try:
                        self._schedule_save_settings()
                    except Exception:
                        pass
                except Exception as exc:
                    payload["ml_failure_reason"] = str(exc)
                    payload["ml_correction_status"] = "baseline_only_ml_fit_failed"
                    active_model_state = None
            elif active_model_state is None:
                payload["ml_correction_status"] = "baseline_only_insufficient_training"
        else:
            if active_model_state is not None:
                payload["ml_training_sample_count"] = max(
                    _safe_rust_int(active_model_state.get("sample_count"), 0),
                    0,
                )
                payload["ml_fit_error"] = _safe_float(active_model_state.get("fit_rmse"))
                payload["ml_model_source"] = "saved_global_model"
                payload["ml_correction_status"] = (
                    "model_ready_apply_on"
                    if apply_ml_correction
                    else "model_ready_apply_off"
                )
            else:
                payload["ml_correction_status"] = "baseline_only_no_saved_model"

        if not isinstance(active_model_state, Mapping):
            return rows_out, payload

        ml_corrected_ph_series: List[Optional[float]] = []
        ml_corrected_fraction_series: List[Dict[str, float]] = []
        monotonic_adjusted = False
        for idx, baseline_ph in enumerate(baseline_ph_series, start=1):
            baseline_value = _safe_float(baseline_ph)
            if baseline_value is None or not math.isfinite(float(baseline_value)):
                ml_corrected_ph_series.append(None)
                ml_corrected_fraction_series.append({"H2CO3": 0.0, "HCO3-": 0.0, "CO3^2-": 0.0})
                continue
            feature_map = self._analysis_ml_feature_map_for_cycle(
                cycle_index=idx,
                row_count=len(rows_out),
                baseline_corrected_ph=baseline_value,
                cycle_uptake_mol=(
                    baseline_cycle_uptake_mol[idx - 1]
                    if idx - 1 < len(baseline_cycle_uptake_mol)
                    else None
                ),
                cumulative_uptake_mol=(
                    baseline_cumulative_uptake_mol[idx - 1]
                    if idx - 1 < len(baseline_cumulative_uptake_mol)
                    else None
                ),
                anchor_cycle_index=primary_anchor_cycle,
                basis_signature=basis_signature,
            )
            feature_vector = self._analysis_ml_vector_from_feature_map(feature_map)
            predicted_residual = self._analysis_ml_predict_from_model_state(
                active_model_state,
                feature_vector,
            )
            if predicted_residual is None:
                corrected_ph = float(baseline_value)
            else:
                corrected_ph = float(baseline_value) + float(predicted_residual)
            corrected_ph = min(max(corrected_ph, 0.0), 14.0)
            ml_corrected_ph_series.append(corrected_ph)
            ml_corrected_fraction_series.append(
                dict(self._analysis_dashboard_fraction_fallback(corrected_ph))
            )
            rows_out[idx - 1]["ml_corrected_ph"] = corrected_ph
            rows_out[idx - 1]["ml_corrected_fractions"] = dict(
                ml_corrected_fraction_series[-1]
            )
        monotonic_adjusted = _enforce_analysis_nonincreasing_ph_series(
            ml_corrected_ph_series
        )
        if monotonic_adjusted:
            ml_corrected_fraction_series = [
                (
                    dict(self._analysis_dashboard_fraction_fallback(value))
                    if _safe_float(value) is not None
                    else {"H2CO3": 0.0, "HCO3-": 0.0, "CO3^2-": 0.0}
                )
                for value in ml_corrected_ph_series
            ]
            for idx, corrected_ph in enumerate(ml_corrected_ph_series):
                if idx >= len(rows_out):
                    break
                rows_out[idx]["ml_corrected_ph"] = _safe_float(corrected_ph)
                rows_out[idx]["ml_corrected_fractions"] = dict(
                    ml_corrected_fraction_series[idx]
                )

        payload["ml_corrected_ph_series"] = list(ml_corrected_ph_series)
        payload["ml_corrected_fraction_series"] = list(ml_corrected_fraction_series)
        payload["ml_monotonic_ph_adjusted"] = bool(monotonic_adjusted)
        baseline_anchor_abs_errors: List[float] = []
        ml_anchor_abs_errors: List[float] = []
        guard_details: List[Dict[str, Any]] = []
        for anchor in normalized_anchor_rows:
            cycle_idx = _safe_rust_int(anchor.get("cycle_index"), -1)
            measured_ph = _safe_float(anchor.get("measured_ph"))
            if (
                cycle_idx is None
                or cycle_idx <= 0
                or measured_ph is None
                or cycle_idx > len(baseline_ph_series)
                or cycle_idx > len(ml_corrected_ph_series)
            ):
                continue
            baseline_at_anchor = _safe_float(baseline_ph_series[cycle_idx - 1])
            ml_at_anchor = _safe_float(ml_corrected_ph_series[cycle_idx - 1])
            if baseline_at_anchor is None or ml_at_anchor is None:
                continue
            baseline_abs = abs(float(measured_ph) - float(baseline_at_anchor))
            ml_abs = abs(float(measured_ph) - float(ml_at_anchor))
            baseline_anchor_abs_errors.append(float(baseline_abs))
            ml_anchor_abs_errors.append(float(ml_abs))
            guard_details.append(
                {
                    "cycle_index": int(cycle_idx),
                    "measured_ph": float(measured_ph),
                    "baseline_abs_error_ph": float(baseline_abs),
                    "ml_abs_error_ph": float(ml_abs),
                    "within_tolerance_after_ml": bool(ml_abs <= tolerance_ph + 1e-12),
                }
            )
        baseline_anchor_mae = (
            (sum(baseline_anchor_abs_errors) / len(baseline_anchor_abs_errors))
            if baseline_anchor_abs_errors
            else None
        )
        ml_anchor_mae = (
            (sum(ml_anchor_abs_errors) / len(ml_anchor_abs_errors))
            if ml_anchor_abs_errors
            else None
        )
        tolerance_breach = any(
            error > tolerance_ph + 1e-12 for error in ml_anchor_abs_errors
        )
        mae_regression = (
            baseline_anchor_mae is not None
            and ml_anchor_mae is not None
            and ml_anchor_mae > baseline_anchor_mae + 1e-12
        )
        anchor_guard_pass = not (mae_regression or tolerance_breach)
        payload["baseline_anchor_mae_ph"] = _safe_float(baseline_anchor_mae)
        payload["ml_anchor_mae_ph"] = _safe_float(ml_anchor_mae)
        payload["ml_anchor_guard_pass"] = bool(anchor_guard_pass)
        payload["ml_anchor_guard_details"] = guard_details
        payload["ml_anchor_guard_tolerance_breach"] = bool(tolerance_breach)
        payload["ml_anchor_guard_mae_regression"] = bool(mae_regression)
        if apply_ml_correction and not anchor_guard_pass:
            payload["ml_correction_applied"] = False
            payload["ml_correction_status"] = "baseline_only_ml_rejected_anchor_guard"
            if mae_regression:
                payload["ml_failure_reason"] = (
                    "ML correction rejected: anchor MAE worsened vs baseline."
                )
            elif tolerance_breach:
                payload["ml_failure_reason"] = (
                    "ML correction rejected: anchor tolerance exceeded."
                )
        elif apply_ml_correction:
            payload["corrected_ph_series"] = list(ml_corrected_ph_series)
            payload["corrected_fraction_series"] = list(ml_corrected_fraction_series)
            latest_ph = (
                _safe_float(ml_corrected_ph_series[-1])
                if ml_corrected_ph_series
                else None
            )
            latest_fractions = (
                dict(ml_corrected_fraction_series[-1])
                if ml_corrected_fraction_series
                else {"H2CO3": 0.0, "HCO3-": 0.0, "CO3^2-": 0.0}
            )
            payload["latest_corrected_speciation"] = {
                "ph": latest_ph,
                "fractions": latest_fractions,
            }
            payload["ml_correction_applied"] = True
            payload["ml_correction_status"] = "applied"
            payload["ml_failure_reason"] = ""
        else:
            payload["ml_correction_applied"] = False
            if payload.get("ml_correction_status") == "baseline_only":
                payload["ml_correction_status"] = "computed_not_applied"
        return rows_out, payload

    def _resolve_analysis_reaction_guidance_measurements(
        self,
        *,
        workflow_key: Optional[str],
        reaction_final_ph: Optional[float],
        reaction_slurry_ph: Optional[float],
        measured_ph_value: Optional[float],
        measured_ph_cycle_index: Optional[int],
        measured_ph_anchors: Optional[Sequence[Mapping[str, Any]]] = None,
        measured_ph_anchor_enabled: bool = True,
        cycle_count: Optional[int] = None,
    ) -> Dict[str, Optional[float]]:
        """Resolve measured/slurry pH inputs for Analysis reaction-guidance calls.

        Purpose:
            Build one normalized measured-pH input pair consumed by
            `analyze_bicarbonate_reaction`.
        Why:
            Analysis warnings should honor final/slurry fields first, then use the
            measured-pH anchor only as a valid-cycle fallback.
        Inputs:
            workflow_key: Active workflow key; anchor fallback applies only to
                Analysis.
            reaction_final_ph: Final-product pH input.
            reaction_slurry_ph: Slurry pH input.
            measured_ph_value: Measured-pH anchor value.
            measured_ph_cycle_index: Cycle index where anchor was measured.
            measured_ph_anchors: Optional measured-pH anchor list from form payload.
            measured_ph_anchor_enabled: Whether anchor fallback is enabled.
            cycle_count: Available cycle count for anchor index validation.
        Outputs:
            Dict[str, Optional[float]] with `measured_ph` and `slurry_ph`.
        Side Effects:
            None.
        Exceptions:
            Invalid numeric values are handled as missing.
        """
        final_ph = _safe_float(reaction_final_ph)
        slurry_ph = _safe_float(reaction_slurry_ph)
        if final_ph is not None:
            return {"measured_ph": final_ph, "slurry_ph": slurry_ph}
        if slurry_ph is not None:
            return {"measured_ph": None, "slurry_ph": slurry_ph}
        if str(workflow_key or "") != "Analysis":
            return {"measured_ph": None, "slurry_ph": None}
        if not bool(measured_ph_anchor_enabled):
            return {"measured_ph": None, "slurry_ph": None}
        normalized_anchors, _ = _normalize_analysis_measured_ph_anchors(
            measured_ph_anchors or [],
            cycle_count=_safe_rust_int(cycle_count, -1),
        )
        if normalized_anchors:
            anchor_row = normalized_anchors[-1]
            return {
                "measured_ph": _safe_float(anchor_row.get("measured_ph")),
                "slurry_ph": None,
            }
        anchor_ph = _safe_float(measured_ph_value)
        if anchor_ph is None or not math.isfinite(anchor_ph):
            return {"measured_ph": None, "slurry_ph": None}
        anchor_cycle = _safe_rust_int(measured_ph_cycle_index, -1)
        if anchor_cycle <= 0:
            return {"measured_ph": None, "slurry_ph": None}
        resolved_cycle_count = _safe_rust_int(cycle_count, -1)
        # Anchor fallback is only valid when the selected cycle is in-range.
        if resolved_cycle_count > 0 and anchor_cycle > resolved_cycle_count:
            return {"measured_ph": None, "slurry_ph": None}
        return {"measured_ph": anchor_ph, "slurry_ph": None}

    def _analysis_resolve_measured_anchor(
        self,
        *,
        form_snapshot: Mapping[str, Any],
        row_count: int,
        model_key: str,
        basis_signature: Mapping[str, Any],
    ) -> Optional[Dict[str, Any]]:
        """Resolve measured-pH anchor from live form inputs or global anchor state.

        Purpose:
            Choose one valid measured-pH anchor for Analysis calibration.
        Why:
            The workflow supports explicit user anchor entry plus compatible
            cross-profile global anchor reuse when form anchors are omitted.
        Inputs:
            form_snapshot: Analysis form payload.
            row_count: Available timeline cycle count.
            model_key: Active predicted-pH model key.
            basis_signature: Current chemistry-basis signature.
        Outputs:
            Optional anchor payload with `cycle_index`, `measured_ph`, and `source`.
        Side Effects:
            None.
        Exceptions:
            Invalid anchors are ignored.
        """
        anchor_rows = self._analysis_resolve_measured_anchors(
            form_snapshot=form_snapshot,
            row_count=row_count,
            model_key=model_key,
            basis_signature=basis_signature,
        )
        if not anchor_rows:
            return None
        return dict(anchor_rows[-1])

    def _analysis_reference_shaped_corrected_ph_repair(
        self,
        *,
        rows: Sequence[Mapping[str, Any]],
        reference_trace: Optional[Mapping[str, Any]],
        anchor_rows: Sequence[Mapping[str, Any]],
        terminal_ph_low: float,
        terminal_ph_high: float,
        initial_naoh_mol: Optional[float] = None,
        solution_volume_l: Optional[float] = None,
        temperature_c: Optional[float] = None,
        corrected_cumulative_co2_mol_series: Optional[Sequence[Any]] = None,
        corrected_cumulative_co2_g_series: Optional[Sequence[Any]] = None,
    ) -> Dict[str, Any]:
        """Build an anchor-adjusted corrected pH series from CO2-aligned reference pH.

        Purpose:
            Recover a chemistry-shaped corrected pH trace when calibration output
            is visibly invalid, such as a pseudo high-pH line ending near pH 11.
        Why:
            Corrected pH should follow the same carbonate/CO2 shape as the
            CO2-aligned reference trace while bending toward measured pH anchors.
        Inputs:
            rows: Analysis timeline rows in cycle order.
            reference_trace: Planning/reference trace containing CO2 and pH series.
            anchor_rows: Normalized measured-pH anchors with 1-based cycle indexes.
            terminal_ph_low: Lower terminal corrected-pH target bound.
            terminal_ph_high: Upper terminal corrected-pH target bound.
            initial_naoh_mol: Initial NaOH moles for strong-base seeding.
            solution_volume_l: Process liquor volume in liters.
            temperature_c: Process temperature in Celsius.
            corrected_cumulative_co2_mol_series: Corrected cumulative CO2 uptake
                in moles, aligned to rows.
            corrected_cumulative_co2_g_series: Corrected cumulative CO2 uptake
                in grams, aligned to rows.
        Outputs:
            Dict with `status`, repaired pH series, repaired fraction series, and
            diagnostic metadata. `status` is `ok` only when repair data is usable.
        Side Effects:
            None.
        Exceptions:
            Invalid or sparse reference data returns `status=unavailable`.
        """
        row_list = [dict(row or {}) for row in rows if isinstance(row, Mapping)]
        reference_map = (
            dict(reference_trace or {}) if isinstance(reference_trace, Mapping) else {}
        )
        ref_x = list(reference_map.get("x_co2_g_series") or [])
        ref_ph = list(reference_map.get("ph_series") or [])
        if not row_list or len(ref_x) < 2 or len(ref_ph) < 2:
            return {"status": "unavailable", "reason": "missing_reference_trace"}

        corrected_cumulative_mol = [
            _safe_float(value) for value in list(corrected_cumulative_co2_mol_series or [])
        ]
        corrected_cumulative_g = [
            _safe_float(value) for value in list(corrected_cumulative_co2_g_series or [])
        ]
        base_series: List[Optional[float]] = []
        base_cumulative_g: List[Optional[float]] = []
        for idx, row in enumerate(row_list):
            corrected_mol = (
                corrected_cumulative_mol[idx]
                if idx < len(corrected_cumulative_mol)
                else _safe_float(row.get("corrected_cumulative_co2_mol"))
            )
            corrected_g = (
                corrected_cumulative_g[idx]
                if idx < len(corrected_cumulative_g)
                else _safe_float(row.get("corrected_cumulative_co2_g"))
            )
            if corrected_mol is None and corrected_g is not None:
                corrected_mol = corrected_g / SOL_MW_CO2
            if corrected_g is None and corrected_mol is not None:
                corrected_g = corrected_mol * SOL_MW_CO2
            if corrected_g is None:
                corrected_g = (
                    _safe_float(row.get("co2_g"))
                    or _safe_float(row.get("cumulative_co2_added_mass_g"))
                    or _safe_float(row.get("co2_mass_g"))
                    or 0.0
                )
            base_cumulative_g.append(_safe_float(corrected_g))
            strong_base_ph = _analysis_strong_base_ph_from_corrected_co2(
                initial_naoh_mol=initial_naoh_mol,
                solution_volume_l=solution_volume_l,
                corrected_cumulative_co2_mol=corrected_mol,
                temperature_c=temperature_c,
            )
            if strong_base_ph is not None:
                base_series.append(strong_base_ph)
                continue
            ph_value, _quality = self._analysis_interpolate_reference_series(
                corrected_g,
                ref_x,
                ref_ph,
            )
            base_series.append(_safe_float(ph_value))

        finite_base = [
            float(value)
            for value in base_series
            if value is not None and math.isfinite(float(value))
        ]
        if not finite_base:
            return {"status": "unavailable", "reason": "no_finite_reference_ph"}

        normalized_anchors, _anchor_errors = _normalize_analysis_measured_ph_anchors(
            anchor_rows or [],
            cycle_count=len(row_list),
        )
        anchor_points: List[Tuple[int, float]] = []
        for anchor in normalized_anchors:
            cycle_idx = _safe_rust_int(anchor.get("cycle_index"), -1)
            measured_ph = _safe_float(anchor.get("measured_ph"))
            if (
                cycle_idx is None
                or cycle_idx <= 0
                or cycle_idx > len(base_series)
                or measured_ph is None
                or not math.isfinite(float(measured_ph))
            ):
                continue
            base_at_anchor = _safe_float(base_series[cycle_idx - 1])
            if base_at_anchor is None or not math.isfinite(float(base_at_anchor)):
                continue
            anchor_points.append(
                (int(cycle_idx), float(measured_ph) - float(base_at_anchor))
            )

        low = _safe_float(terminal_ph_low)
        high = _safe_float(terminal_ph_high)
        if low is None or high is None:
            low, high = 7.8, 8.4
        if high < low:
            low, high = high, low
        terminal_mid = (float(low) + float(high)) / 2.0
        terminal_target_g: Optional[float] = None
        ref_pairs: List[Tuple[float, float]] = []
        for raw_x, raw_ph in zip(ref_x, ref_ph, strict=False):
            x_value = _safe_float(raw_x)
            ph_value = _safe_float(raw_ph)
            if (
                x_value is None
                or ph_value is None
                or not math.isfinite(float(x_value))
                or not math.isfinite(float(ph_value))
            ):
                continue
            ref_pairs.append((float(x_value), float(ph_value)))
        ref_pairs.sort(key=lambda item: item[0])
        for (left_x, left_ph), (right_x, right_ph) in zip(
            ref_pairs,
            ref_pairs[1:],
            strict=False,
        ):
            if left_ph == terminal_mid:
                terminal_target_g = left_x
                break
            if (left_ph - terminal_mid) * (right_ph - terminal_mid) <= 0.0:
                span = right_ph - left_ph
                if abs(span) <= 1e-12:
                    terminal_target_g = right_x
                else:
                    ratio = (terminal_mid - left_ph) / span
                    terminal_target_g = left_x + ((right_x - left_x) * ratio)
                break
        if terminal_target_g is None and ref_pairs:
            terminal_target_g = ref_pairs[-1][0]
        final_reference_g = _safe_float(
            reference_map.get("final_co2_g", reference_map.get("target_co2_g"))
        )
        if (
            final_reference_g is not None
            and math.isfinite(float(final_reference_g))
            and (
                terminal_target_g is None
                or float(final_reference_g) > float(terminal_target_g)
            )
        ):
            # The target dose, when known, is the physical endpoint for residual
            # decay; an interpolated pH crossing can occur earlier on sparse rows.
            terminal_target_g = float(final_reference_g)
        terminal_residual = 0.0
        anchor_points.sort(key=lambda item: item[0])

        def _residual_for_cycle(cycle_idx: int) -> float:
            """Return interpolated anchor residual for one 1-based cycle index.

            Purpose:
                Blend measured-pH anchor residuals onto the model/reference pH
                trace without forcing the last observed cycle to the target pH.
            Why:
                A late anchor should inform the remaining trace, but pH 8.1 is
                only chemically plausible once the CO2 reference curve reaches
                that target uptake.
            Inputs:
                cycle_idx: 1-based timeline cycle index.
            Outputs:
                float residual in pH units to add to the reference-shaped pH.
            Side Effects:
                None.
            Exceptions:
                Invalid/missing cumulative CO2 values fall back to cycle-span
                interpolation.
            """
            if not anchor_points:
                return 0.0
            first_cycle, first_residual = anchor_points[0]
            if cycle_idx <= first_cycle:
                span = max(first_cycle - 1, 1)
                return float(first_residual) * max(
                    0.0,
                    min((cycle_idx - 1) / span, 1.0),
                )
            for (left_cycle, left_residual), (right_cycle, right_residual) in zip(
                anchor_points,
                anchor_points[1:],
                strict=False,
            ):
                if left_cycle <= cycle_idx <= right_cycle:
                    span = max(right_cycle - left_cycle, 1)
                    ratio = max(0.0, min((cycle_idx - left_cycle) / span, 1.0))
                    return float(left_residual) + (
                        (float(right_residual) - float(left_residual)) * ratio
                    )
            last_cycle, last_residual = anchor_points[-1]
            last_cumulative = (
                _safe_float(base_cumulative_g[last_cycle - 1])
                if last_cycle - 1 < len(base_cumulative_g)
                else None
            )
            current_cumulative = (
                _safe_float(base_cumulative_g[cycle_idx - 1])
                if cycle_idx - 1 < len(base_cumulative_g)
                else None
            )
            if (
                terminal_target_g is not None
                and last_cumulative is not None
                and current_cumulative is not None
                and math.isfinite(float(terminal_target_g))
                and math.isfinite(float(last_cumulative))
                and math.isfinite(float(current_cumulative))
                and float(terminal_target_g) > float(last_cumulative) + 1e-9
            ):
                ratio = max(
                    0.0,
                    min(
                        (float(current_cumulative) - float(last_cumulative))
                        / (float(terminal_target_g) - float(last_cumulative)),
                        1.0,
                    ),
                )
            else:
                tail_span = max(len(base_series) - last_cycle, 1)
                ratio = max(0.0, min((cycle_idx - last_cycle) / tail_span, 1.0))
            return float(last_residual) + (
                (float(terminal_residual) - float(last_residual)) * ratio
            )

        repaired_series: List[Optional[float]] = []
        for idx, base_ph in enumerate(base_series, start=1):
            base_value = _safe_float(base_ph)
            if base_value is None or not math.isfinite(float(base_value)):
                repaired_series.append(None)
                continue
            repaired_series.append(
                _clamp_analysis_corrected_ph_value(
                    float(base_value) + _residual_for_cycle(idx)
                )
            )
        drop_floor_series: List[float] = [0.0]
        for previous_base, current_base in zip(
            base_series,
            base_series[1:],
            strict=False,
        ):
            previous_value = _safe_float(previous_base)
            current_value = _safe_float(current_base)
            if (
                previous_value is None
                or current_value is None
                or not math.isfinite(float(previous_value))
                or not math.isfinite(float(current_value))
            ):
                drop_floor_series.append(0.0)
                continue
            # Carry a fraction of the equilibrium/reference slope through repair
            # so residual blending cannot erase CO2-driven pH movement.
            drop_floor_series.append(
                max(0.003, (float(previous_value) - float(current_value)) * 0.15)
            )
        monotonic_adjusted = _enforce_analysis_contextual_ph_descent(
            repaired_series,
            cumulative_co2_series=base_cumulative_g,
            drop_floor_series=drop_floor_series,
        )
        fraction_series = [
            (
                dict(self._analysis_dashboard_fraction_fallback(value))
                if _safe_float(value) is not None
                else {"H2CO3": 0.0, "HCO3-": 0.0, "CO3^2-": 0.0}
            )
            for value in repaired_series
        ]
        endpoint = _safe_float(repaired_series[-1]) if repaired_series else None
        return {
            "status": "ok",
            "corrected_ph_series": repaired_series,
            "corrected_fraction_series": fraction_series,
            "endpoint_ph": endpoint,
            "anchor_residual_points": [
                {"cycle_index": cycle, "residual_ph": residual}
                for cycle, residual in anchor_points
            ],
            "terminal_residual_ph": terminal_residual,
            "monotonic_adjusted": bool(monotonic_adjusted),
        }

    def _analysis_corrected_ph_needs_reference_shape_repair(
        self,
        *,
        calibration_payload: Mapping[str, Any],
        reference_trace: Optional[Mapping[str, Any]],
        terminal_ph_low: float,
        terminal_ph_high: float,
        initial_naoh_mol: Optional[float] = None,
        solution_volume_l: Optional[float] = None,
        temperature_c: Optional[float] = None,
    ) -> bool:
        """Return whether corrected pH should be rebuilt from reference shape.

        Purpose:
            Catch accepted calibration payloads that do not satisfy the corrected
            pH contract before chart/export rows are populated.
        Why:
            Endpoint pH near 11, a high-pH pseudo trace, an over-flat terminal
            trace, a local high-point/drop break, or a corrected pH value that
            falls materially below its own CO2-aligned reference should fail
            closed to a CO2-aligned, anchor-adjusted trace instead of being
            displayed.
        Inputs:
            calibration_payload: Candidate corrected-pH calibration payload.
            reference_trace: Reference trace used to determine whether endpoint
                chemistry should be near the terminal band.
            terminal_ph_low: Lower terminal target bound.
            terminal_ph_high: Upper terminal target bound.
            initial_naoh_mol: Initial NaOH moles used to detect low-pH starts
                while free hydroxide remains.
            solution_volume_l: Process liquor volume in liters.
            temperature_c: Process temperature in Celsius for pKw.
        Outputs:
            bool: True when reference-shaped repair should replace the series.
        Side Effects:
            None.
        Exceptions:
            Invalid payload shapes request repair only when reference data exists.
        """
        corrected = [
            _safe_float(value)
            for value in list(calibration_payload.get("corrected_ph_series") or [])
        ]
        finite_corrected = [
            float(value)
            for value in corrected
            if value is not None and math.isfinite(float(value))
        ]
        if not finite_corrected:
            return True
        reference_map = (
            dict(reference_trace or {}) if isinstance(reference_trace, Mapping) else {}
        )
        ref_ph = [
            _safe_float(value) for value in list(reference_map.get("ph_series") or [])
        ]
        finite_reference = [
            float(value)
            for value in ref_ph
            if value is not None and math.isfinite(float(value))
        ]
        if not finite_reference:
            return False
        low = _safe_float(terminal_ph_low, 7.8)
        high = _safe_float(terminal_ph_high, 8.4)
        if high < low:
            low, high = high, low
        endpoint = finite_corrected[-1]
        reference_endpoint = finite_reference[-1]
        endpoint_distance = (
            low - endpoint
            if endpoint < low
            else endpoint - high
            if endpoint > high
            else 0.0
        )
        reference_endpoint_distance = (
            low - reference_endpoint
            if reference_endpoint < low
            else reference_endpoint - high
            if reference_endpoint > high
            else 0.0
        )
        starts_pseudo_high = finite_corrected[0] >= 13.0 and endpoint >= 10.0
        endpoint_bad_while_reference_ok = (
            endpoint_distance > 0.75 and reference_endpoint_distance <= 0.75
        )
        corrected_cumulative_mol = [
            _safe_float(value)
            for value in list(
                calibration_payload.get("corrected_cumulative_co2_mol_series") or []
            )
        ]
        starts_too_low_for_free_naoh = False
        for idx, corrected_value in enumerate(corrected):
            if corrected_value is None or idx >= len(corrected_cumulative_mol):
                continue
            expected_strong = _analysis_strong_base_ph_from_corrected_co2(
                initial_naoh_mol=initial_naoh_mol,
                solution_volume_l=solution_volume_l,
                corrected_cumulative_co2_mol=corrected_cumulative_mol[idx],
                temperature_c=temperature_c,
            )
            if expected_strong is not None and corrected_value < expected_strong - 0.75:
                starts_too_low_for_free_naoh = True
                break
        corrected_cumulative_g = [
            _safe_float(value)
            for value in list(
                calibration_payload.get("corrected_cumulative_co2_g_series") or []
            )
        ]
        if not corrected_cumulative_g and corrected_cumulative_mol:
            corrected_cumulative_g = [
                (
                    float(value) * SOL_MW_CO2
                    if value is not None and math.isfinite(float(value))
                    else None
                )
                for value in corrected_cumulative_mol
            ]
        ref_x = [
            _safe_float(value)
            for value in list(reference_map.get("x_co2_g_series") or [])
        ]
        aligned_reference: List[Optional[float]] = []
        for idx, corrected_value in enumerate(corrected):
            if corrected_value is None or idx >= len(corrected_cumulative_g):
                aligned_reference.append(None)
                continue
            aligned_x = corrected_cumulative_g[idx]
            if aligned_x is None or not math.isfinite(float(aligned_x)):
                aligned_reference.append(None)
                continue
            reference_value, _quality = self._analysis_interpolate_reference_series(
                float(aligned_x),
                ref_x,
                ref_ph,
            )
            aligned_reference.append(_safe_float(reference_value))

        over_flat_relative_to_reference = False
        finite_pairs: List[Tuple[float, float]] = []
        for corrected_value, reference_value in zip(
            corrected,
            aligned_reference,
            strict=False,
        ):
            corrected_float = _safe_float(corrected_value)
            reference_float = _safe_float(reference_value)
            if (
                corrected_float is None
                or reference_float is None
                or not math.isfinite(float(corrected_float))
                or not math.isfinite(float(reference_float))
            ):
                continue
            finite_pairs.append((float(corrected_float), float(reference_float)))
        if len(finite_pairs) >= 4:
            corrected_range = max(value[0] for value in finite_pairs) - min(
                value[0] for value in finite_pairs
            )
            reference_range = max(value[1] for value in finite_pairs) - min(
                value[1] for value in finite_pairs
            )
            # A terminal-band plateau can pass endpoint checks while losing the
            # CO2-aligned curve shape; reject it only when reference movement is
            # substantially larger than corrected movement.
            over_flat_relative_to_reference = (
                corrected_range < 0.35
                and reference_range > 0.65
                and corrected_range < reference_range * 0.45
            )
            if not over_flat_relative_to_reference:
                for window_size in (4, 5):
                    if len(finite_pairs) < window_size:
                        continue
                    for start_idx in range(0, len(finite_pairs) - window_size + 1):
                        window = finite_pairs[start_idx : start_idx + window_size]
                        corrected_window_range = max(item[0] for item in window) - min(
                            item[0] for item in window
                        )
                        reference_window_range = max(item[1] for item in window) - min(
                            item[1] for item in window
                        )
                        if (
                            corrected_window_range <= 0.04
                            and reference_window_range >= 0.18
                        ):
                            over_flat_relative_to_reference = True
                            break
                    if over_flat_relative_to_reference:
                        break
        local_shape_break = False
        corrected_below_reference_break = False
        anchor_cycle_indexes = {
            _safe_rust_int(anchor.get("cycle_index"), -1)
            for anchor in list(calibration_payload.get("anchors") or [])
            if isinstance(anchor, Mapping)
        }
        primary_anchor_index = _safe_rust_int(
            calibration_payload.get("anchor_cycle_index"), -1
        )
        if primary_anchor_index and primary_anchor_index > 0:
            anchor_cycle_indexes.add(primary_anchor_index)
        for idx, corrected_value in enumerate(corrected):
            corrected_float = _safe_float(corrected_value)
            reference_float = (
                _safe_float(aligned_reference[idx])
                if idx < len(aligned_reference)
                else None
            )
            if (
                corrected_float is None
                or reference_float is None
                or not math.isfinite(float(corrected_float))
                or not math.isfinite(float(reference_float))
            ):
                continue
            cycle_idx = idx + 1
            if cycle_idx in anchor_cycle_indexes:
                continue
            corrected_mol = (
                corrected_cumulative_mol[idx]
                if idx < len(corrected_cumulative_mol)
                else None
            )
            expected_strong = _analysis_strong_base_ph_from_corrected_co2(
                initial_naoh_mol=initial_naoh_mol,
                solution_volume_l=solution_volume_l,
                corrected_cumulative_co2_mol=corrected_mol,
                temperature_c=temperature_c,
            )
            if expected_strong is not None:
                continue
            divergence = float(corrected_float) - float(reference_float)
            previous_corrected = (
                _safe_float(corrected[idx - 1])
                if idx > 0 and idx - 1 < len(corrected)
                else None
            )
            previous_reference = (
                _safe_float(aligned_reference[idx - 1])
                if idx > 0 and idx - 1 < len(aligned_reference)
                else None
            )
            next_corrected = (
                _safe_float(corrected[idx + 1])
                if idx + 1 < len(corrected)
                else None
            )
            next_reference = (
                _safe_float(aligned_reference[idx + 1])
                if idx + 1 < len(aligned_reference)
                else None
            )
            abrupt_corrected_drop = (
                next_corrected is not None
                and math.isfinite(float(next_corrected))
                and float(corrected_float) - float(next_corrected) > 0.5
            )
            reference_drop = (
                float(reference_float) - float(next_reference)
                if next_reference is not None and math.isfinite(float(next_reference))
                else 0.0
            )
            if divergence > 0.45 and (
                abrupt_corrected_drop or reference_drop < 0.35
            ):
                local_shape_break = True
                break
            below_reference_gap = float(reference_float) - float(corrected_float)
            previous_corrected_drop = (
                float(previous_corrected) - float(corrected_float)
                if previous_corrected is not None
                and math.isfinite(float(previous_corrected))
                else 0.0
            )
            previous_reference_drop = (
                float(previous_reference) - float(reference_float)
                if previous_reference is not None
                and math.isfinite(float(previous_reference))
                else 0.0
            )
            # Corrected CO2 is already the x-axis for `reference_float`; a lower
            # corrected pH than that reference requires either an anchor or a
            # similarly steep reference drop. Otherwise terminal/ML bias has
            # over-acidified the corrected trace.
            if below_reference_gap > 0.25 and (
                previous_corrected_drop > max(0.45, previous_reference_drop + 0.25)
                or reference_drop < 0.35
            ):
                corrected_below_reference_break = True
                break
        return bool(
            starts_pseudo_high
            or endpoint_bad_while_reference_ok
            or starts_too_low_for_free_naoh
            or over_flat_relative_to_reference
            or local_shape_break
            or corrected_below_reference_break
        )

    def _apply_analysis_measured_ph_calibration(
        self,
        timeline_rows: Sequence[Mapping[str, Any]],
        *,
        form_snapshot: Mapping[str, Any],
        reference_trace: Optional[Mapping[str, Any]],
    ) -> Tuple[List[Dict[str, Any]], Optional[Dict[str, Any]], Optional[Dict[str, Any]]]:
        """Apply measured-pH anchored uptake calibration to Analysis timeline rows.

        Purpose:
            Preserve Cycle Analysis uptake as the raw timeline channel while
            publishing the independently corrected uptake, pH, and speciation
            series produced by measured-anchor calibration.
        Why:
            Raw and corrected CO2 must remain distinct so operators can compare
            Cycle Analysis uptake against the uptake basis used by corrected
            chemistry. Corrected pH is evaluated on the same CO2-aligned reference
            chemistry as the raw Analysis pH channel so calibration does not
            switch chemistry contexts at carbonate equivalence. Calculated pH at
            corrected CO2 remains a reference-curve diagnostic, not a copy of
            corrected pH.
        Inputs:
            timeline_rows: Forensic-augmented Analysis timeline rows.
            form_snapshot: Analysis form payload captured before worker execution.
            reference_trace: Planning reference trace used for completion context.
        Outputs:
            Tuple of `(timeline_rows, calibration_payload, anchor_payload)`.
        Side Effects:
            Persists successful calibration payloads by active profile key.
        Exceptions:
            Invalid or unavailable anchors return rows unchanged.
        """
        rows = [dict(entry or {}) for entry in (timeline_rows or []) if isinstance(entry, Mapping)]
        if not rows:
            return rows, None, None
        if str(form_snapshot.get("workflow_key") or "") != "Analysis":
            return rows, None, None
        _spec_key, ph_model_key, _use_same = self._resolve_workflow_model_keys(
            "Analysis", dict(form_snapshot)
        )
        basis_signature = self._analysis_calibration_basis_signature(form_snapshot)
        anchor_rows = self._analysis_resolve_measured_anchors(
            form_snapshot=form_snapshot,
            row_count=len(rows),
            model_key=ph_model_key,
            basis_signature=basis_signature,
        )
        if not anchor_rows:
            return rows, None, None
        anchor_payload: Dict[str, Any] = dict(anchor_rows[-1])
        anchor_payload["anchors"] = [dict(row) for row in anchor_rows]

        cycle_uptake_series: List[float] = []
        for row in rows:
            cycle_mol = _safe_float(row.get("co2_moles"))
            if cycle_mol is None:
                cycle_mol = _safe_float(row.get("co2_added_moles"))
            if cycle_mol is None:
                cycle_mol = _safe_float(row.get("actual_cycle_co2_mol"))
            cycle_uptake_series.append(max(0.0, float(cycle_mol or 0.0)))
        if not cycle_uptake_series:
            return rows, None, None

        initial_naoh_mol = None
        reaction_naoh_mass = _safe_float(form_snapshot.get("reaction_naoh_mass"))
        if reaction_naoh_mass is not None and reaction_naoh_mass > 0.0:
            initial_naoh_mol = reaction_naoh_mass / SOL_MW_NAOH
        solution_volume_l = _safe_float(form_snapshot.get("reaction_solution_volume"))
        params = form_snapshot.get("params")
        if solution_volume_l is None and params is not None:
            solution_volume_l = _safe_float(getattr(params, "solution_volume_l", None))
        temperature_c = (
            _safe_float(getattr(params, "temperature_c", None))
            if params is not None
            else _safe_float(form_snapshot.get("temperature_c"), 25.0)
        )
        if temperature_c is None:
            temperature_c = 25.0
        reference_map = dict(reference_trace) if isinstance(reference_trace, Mapping) else {}
        reference_total_mol = None
        ref_cum_series = reference_map.get("cumulative_co2_mol_series") or []
        if isinstance(ref_cum_series, Sequence) and ref_cum_series:
            reference_total_mol = _safe_float(ref_cum_series[-1])
        if reference_total_mol is None:
            final_co2_g = _safe_float(reference_map.get("final_co2_g"))
            if final_co2_g is not None:
                reference_total_mol = final_co2_g / SOL_MW_CO2
        equivalence_co2_mol = None
        equivalence_co2_g = _safe_float(reference_map.get("equivalence_co2_g"))
        if equivalence_co2_g is not None:
            equivalence_co2_mol = equivalence_co2_g / SOL_MW_CO2
        equivalence_cycle_index = _safe_rust_int(
            reference_map.get("equivalence_index"), -1
        )
        if equivalence_cycle_index is not None and equivalence_cycle_index >= 0:
            equivalence_cycle_index = int(equivalence_cycle_index) + 1
        else:
            equivalence_cycle_index = None
        if equivalence_cycle_index is None:
            equivalence_cycle_index = next(
                (
                    idx
                    for idx, row in enumerate(rows, start=1)
                    if _safe_float(row.get("co2_g")) is not None
                    and equivalence_co2_g is not None
                    and _safe_float(row.get("co2_g")) >= equivalence_co2_g
                ),
                None,
            )
        target_ph = _safe_float(form_snapshot.get("reaction_target_ph"))
        learning_controls = self._analysis_anchor_learning_controls(form_snapshot)
        learning_enabled = bool(learning_controls["learning_enabled"])
        terminal_ph_low = float(learning_controls["terminal_ph_range_low"])
        terminal_ph_high = float(learning_controls["terminal_ph_range_high"])
        terminal_ph_weight = float(learning_controls["terminal_ph_weight"])
        compact_pitzer_params = None
        if ph_model_key == "naoh_co2_pitzer_hmw":
            compact_pitzer_params = _compact_pitzer_params_for_rust(_NAOH_PITZER_PARAMS)
        if learning_enabled:
            prior_cycle_factor_series, prior_sample_count, prior_diagnostics = (
                self._analysis_resolve_profile_learning_prior(
                    row_count=len(rows),
                    model_key=ph_model_key,
                    basis_signature=basis_signature,
                )
            )
        else:
            prior_cycle_factor_series, prior_sample_count, prior_diagnostics = (
                [],
                0,
                {"profile_sample_counts": {}, "points_used": 0},
            )
        calibration_payload = None
        if _current_rust_backend_mode() != "python":
            calibration_payload = _rust_measured_ph_uptake_calibration_core(
                model_key=ph_model_key,
                cycle_uptake_mol_series=cycle_uptake_series,
                anchor_cycle_index=int(anchor_payload["cycle_index"]),
                measured_ph=float(anchor_payload["measured_ph"]),
                equivalence_cycle_index=equivalence_cycle_index,
                target_ph=target_ph,
                initial_naoh_mol=initial_naoh_mol,
                solution_volume_l=solution_volume_l,
                temperature_c=temperature_c,
                planning_reference_total_mol=reference_total_mol,
                equivalence_co2_mol=equivalence_co2_mol,
                pitzer_params=compact_pitzer_params,
                anchors=anchor_rows,
                prior_cycle_factor_series=prior_cycle_factor_series,
                prior_sample_count=prior_sample_count,
                learning_enabled=learning_enabled,
                terminal_ph_range_low=terminal_ph_low,
                terminal_ph_range_high=terminal_ph_high,
                terminal_ph_weight=terminal_ph_weight,
            )
        rust_status = (
            str(calibration_payload.get("solver_status") or "").strip().lower()
            if isinstance(calibration_payload, Mapping)
            else ""
        )
        if not isinstance(calibration_payload, Mapping) or rust_status != "ok":
            calibration_payload = _python_multi_anchor_measured_ph_uptake_calibration_core(
                model_key=ph_model_key,
                cycle_uptake_mol_series=cycle_uptake_series,
                anchors=anchor_rows,
                equivalence_cycle_index=equivalence_cycle_index,
                target_ph=target_ph,
                initial_naoh_mol=initial_naoh_mol,
                solution_volume_l=solution_volume_l,
                temperature_c=temperature_c,
                planning_reference_total_mol=reference_total_mol,
                equivalence_co2_mol=equivalence_co2_mol,
                prior_cycle_factor_series=prior_cycle_factor_series,
                prior_sample_count=prior_sample_count,
                learning_enabled=learning_enabled,
                terminal_ph_range_low=terminal_ph_low,
                terminal_ph_range_high=terminal_ph_high,
                terminal_ph_weight=terminal_ph_weight,
            )
        if not isinstance(calibration_payload, Mapping):
            return rows, None, anchor_payload
        if str(calibration_payload.get("solver_status") or "").lower() != "ok":
            return rows, dict(calibration_payload), anchor_payload
        calibration_payload = dict(calibration_payload)
        calibration_payload["learning_enabled"] = learning_enabled
        calibration_payload["terminal_ph_range_low"] = terminal_ph_low
        calibration_payload["terminal_ph_range_high"] = terminal_ph_high
        calibration_payload["terminal_ph_weight"] = terminal_ph_weight
        # Keep the solver-corrected uptake series intact; the unmodified Cycle
        # Analysis uptake remains available on each row's raw CO2 fields.
        calibration_payload["uptake_correction_mode"] = "measured_ph_uptake_calibration"
        calibration_payload["uptake_scaling_applied"] = True
        calibration_payload["alpha_applies_to"] = "corrected uptake and pH"
        anchor_resolution_meta = dict(
            getattr(self, "_analysis_last_anchor_resolution_meta", {}) or {}
        )
        calibration_payload["global_anchor_learning"] = {
            "scope": "global_cross_profile",
            "manual_anchor_count": _safe_rust_int(
                anchor_resolution_meta.get("manual_anchor_count"), 0
            ),
            "compatible_global_anchor_count": _safe_rust_int(
                anchor_resolution_meta.get("global_compatible_anchor_count"), 0
            ),
            "resolved_anchor_source_counts": dict(
                anchor_resolution_meta.get("resolved_anchor_source_counts") or {}
            ),
            "prior_sample_profile_counts": dict(
                prior_diagnostics.get("profile_sample_counts") or {}
            )
            if isinstance(prior_diagnostics, Mapping)
            else {},
            "prior_cycle_factor_points_used": _safe_rust_int(
                (
                    prior_diagnostics.get("points_used")
                    if isinstance(prior_diagnostics, Mapping)
                    else 0
                ),
                0,
            ),
            "prior_sample_count": int(max(prior_sample_count, 0)),
        }
        primary_reference_payload = self._analysis_reference_shaped_corrected_ph_repair(
            rows=rows,
            reference_trace=reference_trace,
            anchor_rows=anchor_rows,
            terminal_ph_low=terminal_ph_low,
            terminal_ph_high=terminal_ph_high,
            initial_naoh_mol=initial_naoh_mol,
            solution_volume_l=solution_volume_l,
            temperature_c=temperature_c,
            corrected_cumulative_co2_mol_series=calibration_payload.get(
                "corrected_cumulative_co2_mol_series"
            ),
            corrected_cumulative_co2_g_series=calibration_payload.get(
                "corrected_cumulative_co2_g_series"
            ),
        )
        if str(primary_reference_payload.get("status") or "").strip().lower() == "ok":
            primary_ph = list(
                primary_reference_payload.get("corrected_ph_series") or []
            )
            primary_fractions = list(
                primary_reference_payload.get("corrected_fraction_series") or []
            )
            if len(primary_ph) == len(rows):
                calibration_payload["baseline_solver_corrected_ph_series"] = list(
                    calibration_payload.get("corrected_ph_series") or []
                )
                calibration_payload["corrected_ph_series"] = primary_ph
                calibration_payload["corrected_fraction_series"] = primary_fractions
                calibration_payload["latest_corrected_speciation"] = {
                    "ph": _safe_float(primary_reference_payload.get("endpoint_ph")),
                    "fractions": (
                        dict(primary_fractions[-1])
                        if primary_fractions
                        and isinstance(primary_fractions[-1], Mapping)
                        else {"H2CO3": 0.0, "HCO3-": 0.0, "CO3^2-": 0.0}
                    ),
                }
                calibration_payload["reference_shape_primary"] = dict(
                    primary_reference_payload
                )
                calibration_payload["reference_shape_primary_applied"] = True
            else:
                calibration_payload["reference_shape_primary_applied"] = False
                calibration_payload["reference_shape_primary_reason"] = (
                    "reference-shaped pH length did not match timeline rows"
                )
        else:
            calibration_payload["reference_shape_primary_applied"] = False
            calibration_payload["reference_shape_primary_reason"] = str(
                primary_reference_payload.get("reason") or "reference shape unavailable"
            )
        apply_ml_correction = bool(
            form_snapshot.get(
                "analysis_apply_ml_correction",
                self.settings.get(ANALYSIS_APPLY_ML_CORRECTION_DEFAULT_SETTINGS_KEY, True),
            )
        )
        anchor_fit_tolerance_ph = _safe_float(
            form_snapshot.get("analysis_anchor_fit_tolerance_ph")
        )
        if anchor_fit_tolerance_ph is None:
            anchor_fit_tolerance_ph = self._analysis_anchor_fit_tolerance_ph()
        action_token = str(form_snapshot.get("analysis_last_action") or "").strip().lower()
        allow_ml_retraining = action_token == "recompute_calibration"
        rows, calibration_payload = self._analysis_apply_hybrid_ml_correction(
            rows=rows,
            calibration_payload=calibration_payload,
            anchor_rows=anchor_rows,
            model_key=ph_model_key,
            basis_signature=basis_signature,
            apply_ml_correction=apply_ml_correction,
            allow_retraining=allow_ml_retraining,
            anchor_fit_tolerance_ph=float(anchor_fit_tolerance_ph),
        )
        if self._analysis_corrected_ph_needs_reference_shape_repair(
            calibration_payload=calibration_payload,
            reference_trace=reference_trace,
            terminal_ph_low=terminal_ph_low,
            terminal_ph_high=terminal_ph_high,
            initial_naoh_mol=initial_naoh_mol,
            solution_volume_l=solution_volume_l,
            temperature_c=temperature_c,
        ):
            repair_payload = self._analysis_reference_shaped_corrected_ph_repair(
                rows=rows,
                reference_trace=reference_trace,
                anchor_rows=anchor_rows,
                terminal_ph_low=terminal_ph_low,
                terminal_ph_high=terminal_ph_high,
                initial_naoh_mol=initial_naoh_mol,
                solution_volume_l=solution_volume_l,
                temperature_c=temperature_c,
                corrected_cumulative_co2_mol_series=calibration_payload.get(
                    "corrected_cumulative_co2_mol_series"
                ),
                corrected_cumulative_co2_g_series=calibration_payload.get(
                    "corrected_cumulative_co2_g_series"
                ),
            )
            if str(repair_payload.get("status") or "").strip().lower() == "ok":
                repaired_ph = list(repair_payload.get("corrected_ph_series") or [])
                repaired_fractions = list(
                    repair_payload.get("corrected_fraction_series") or []
                )
                calibration_payload["corrected_ph_series"] = repaired_ph
                calibration_payload["corrected_fraction_series"] = repaired_fractions
                calibration_payload["latest_corrected_speciation"] = {
                    "ph": _safe_float(repair_payload.get("endpoint_ph")),
                    "fractions": (
                        dict(repaired_fractions[-1])
                    if repaired_fractions
                    and isinstance(repaired_fractions[-1], Mapping)
                        else {"H2CO3": 0.0, "HCO3-": 0.0, "CO3^2-": 0.0}
                    ),
                }
                endpoint_ph = _safe_float(repair_payload.get("endpoint_ph"))
                endpoint_distance = None
                if endpoint_ph is not None and math.isfinite(float(endpoint_ph)):
                    if endpoint_ph < terminal_ph_low:
                        endpoint_distance = terminal_ph_low - endpoint_ph
                    elif endpoint_ph > terminal_ph_high:
                        endpoint_distance = endpoint_ph - terminal_ph_high
                    else:
                        endpoint_distance = 0.0
                terminal_penalty_raw = (
                    float(endpoint_distance) ** 2
                    if endpoint_distance is not None
                    else None
                )
                terminal_penalty_weighted = (
                    terminal_penalty_raw * terminal_ph_weight
                    if terminal_penalty_raw is not None
                    else None
                )
                calibration_payload["endpoint_diagnostics"] = {
                    "endpoint_ph": endpoint_ph,
                    "in_terminal_band": bool(
                        endpoint_ph is not None
                        and terminal_ph_low <= float(endpoint_ph) <= terminal_ph_high
                    ),
                    "distance_to_terminal_band": endpoint_distance,
                    "terminal_penalty_raw": terminal_penalty_raw,
                    "terminal_penalty_weighted": terminal_penalty_weighted,
                }
                calibration_payload["reference_shape_repair"] = dict(repair_payload)
                calibration_payload["corrected_ph_repair_applied"] = True
                calibration_payload["corrected_ph_repair_reason"] = (
                    "corrected pH endpoint/shape failed chemistry acceptance gate"
                )
            else:
                calibration_payload["corrected_ph_repair_applied"] = False
                calibration_payload["corrected_ph_repair_reason"] = str(
                    repair_payload.get("reason") or "reference repair unavailable"
                )
        corrected_cycle_mol = list(
            calibration_payload.get("corrected_cycle_uptake_mol_series") or []
        )
        corrected_cycle_g = list(
            calibration_payload.get("corrected_cycle_uptake_g_series") or []
        )
        corrected_cumulative_mol = list(
            calibration_payload.get("corrected_cumulative_co2_mol_series") or []
        )
        corrected_cumulative_g = list(
            calibration_payload.get("corrected_cumulative_co2_g_series") or []
        )
        corrected_ph = list(calibration_payload.get("corrected_ph_series") or [])
        corrected_fractions = list(
            calibration_payload.get("corrected_fraction_series") or []
        )
        ml_corrected_ph_series = list(
            calibration_payload.get("ml_corrected_ph_series") or []
        )
        ml_corrected_fraction_series = list(
            calibration_payload.get("ml_corrected_fraction_series") or []
        )
        calibrated_anchor_rows, _ = _normalize_analysis_measured_ph_anchors(
            calibration_payload.get("anchors") or anchor_rows,
            cycle_count=len(rows),
        )
        anchor_lookup: dict[int, dict[str, Any]] = {}
        for anchor_row in calibrated_anchor_rows:
            cycle_idx = _safe_rust_int(anchor_row.get("cycle_index"), -1)
            measured_value = _safe_float(anchor_row.get("measured_ph"))
            if (
                cycle_idx is None
                or cycle_idx <= 0
                or measured_value is None
                or not math.isfinite(float(measured_value))
            ):
                continue
            anchor_lookup[int(cycle_idx)] = {
                "measured_ph": float(measured_value),
                "source": str(anchor_row.get("source") or "manual").strip().lower()
                or "manual",
            }
        primary_anchor_cycle = int(anchor_payload["cycle_index"])

        ref_x_for_corrected_calc = list(reference_map.get("x_co2_g_series") or [])
        ref_ph_for_corrected_calc = list(reference_map.get("ph_series") or [])

        # Preserve original series while injecting calibrated values for side-by-side
        # review and downstream plotting/export usage.
        for idx, row in enumerate(rows):
            raw_cycle_mol = _safe_float(row.get("co2_moles"))
            if raw_cycle_mol is None:
                raw_cycle_mol = _safe_float(row.get("co2_added_moles"))
            raw_cycle_g = _safe_float(row.get("co2_mass_g"))
            if raw_cycle_g is None and raw_cycle_mol is not None:
                raw_cycle_g = raw_cycle_mol * SOL_MW_CO2
            row["original_cycle_co2_mol"] = raw_cycle_mol
            row["original_cycle_co2_g"] = raw_cycle_g
            row["corrected_cycle_co2_mol"] = (
                _safe_float(corrected_cycle_mol[idx])
                if idx < len(corrected_cycle_mol)
                else None
            )
            row["corrected_cycle_co2_g"] = (
                _safe_float(corrected_cycle_g[idx])
                if idx < len(corrected_cycle_g)
                else None
            )
            row["corrected_cumulative_co2_mol"] = (
                _safe_float(corrected_cumulative_mol[idx])
                if idx < len(corrected_cumulative_mol)
                else None
            )
            row["corrected_cumulative_co2_g"] = (
                _safe_float(corrected_cumulative_g[idx])
                if idx < len(corrected_cumulative_g)
                else None
            )
            row["corrected_ph"] = (
                _safe_float(corrected_ph[idx]) if idx < len(corrected_ph) else None
            )
            if idx < len(corrected_fractions) and isinstance(
                corrected_fractions[idx], Mapping
            ):
                row["corrected_fractions"] = {
                    "H2CO3": max(
                        _safe_float(corrected_fractions[idx].get("H2CO3"), 0.0), 0.0
                    ),
                    "HCO3-": max(
                        _safe_float(corrected_fractions[idx].get("HCO3-"), 0.0), 0.0
                    ),
                    "CO3^2-": max(
                        _safe_float(corrected_fractions[idx].get("CO3^2-"), 0.0), 0.0
                    ),
                }
            row["ml_corrected_ph"] = (
                _safe_float(ml_corrected_ph_series[idx])
                if idx < len(ml_corrected_ph_series)
                else None
            )
            if idx < len(ml_corrected_fraction_series) and isinstance(
                ml_corrected_fraction_series[idx], Mapping
            ):
                row["ml_corrected_fractions"] = {
                    "H2CO3": max(
                        _safe_float(ml_corrected_fraction_series[idx].get("H2CO3"), 0.0),
                        0.0,
                    ),
                    "HCO3-": max(
                        _safe_float(ml_corrected_fraction_series[idx].get("HCO3-"), 0.0),
                        0.0,
                    ),
                    "CO3^2-": max(
                        _safe_float(ml_corrected_fraction_series[idx].get("CO3^2-"), 0.0),
                        0.0,
                    ),
                }
            row_cycle_index = _analysis_timeline_row_cycle_index(row, idx + 1)
            row_anchor = (
                anchor_lookup.get(row_cycle_index)
                if row_cycle_index is not None
                else None
            )
            if row_anchor is not None:
                row["analysis_anchor_measured_ph"] = _safe_float(
                    row_anchor.get("measured_ph")
                )
                row["analysis_anchor_cycle_index"] = row_cycle_index
                row["analysis_anchor_source"] = str(
                    row_anchor.get("source") or "manual"
                ).strip().lower() or "manual"
            else:
                row["analysis_anchor_measured_ph"] = None
                row["analysis_anchor_cycle_index"] = primary_anchor_cycle
                row["analysis_anchor_source"] = None
            row_channels = _analysis_ph_channels_from_row(row)
            row["calculated_ph"] = row_channels.get("calculated_ph")
            row["calibrated_estimated_ph"] = row_channels.get("calibrated_estimated_ph")
            row["actual_observed_ph"] = row_channels.get("actual_observed_ph")
            raw_calculated_ph = _safe_float(row.get("calculated_ph"))
            if raw_calculated_ph is None:
                raw_calculated_ph = _safe_float(row.get("planning_co2_aligned_ph"))
            corrected_calculated_ph = None
            corrected_calc_x_g = _safe_float(row.get("corrected_cumulative_co2_g"))
            if corrected_calc_x_g is None:
                corrected_calc_mol = _safe_float(row.get("corrected_cumulative_co2_mol"))
                if corrected_calc_mol is not None:
                    corrected_calc_x_g = float(corrected_calc_mol) * SOL_MW_CO2
            if (
                corrected_calc_x_g is not None
                and len(ref_x_for_corrected_calc) >= 2
                and len(ref_ph_for_corrected_calc) >= 2
            ):
                corrected_calculated_ph, corrected_calc_quality = (
                    self._analysis_interpolate_reference_series(
                        corrected_calc_x_g,
                        ref_x_for_corrected_calc,
                        ref_ph_for_corrected_calc,
                    )
                )
                row["calculated_ph_corrected_co2_quality"] = corrected_calc_quality
            if corrected_calculated_ph is None:
                row["calculated_ph_corrected_co2_quality"] = "unavailable"
            row["calculated_ph_raw_co2"] = raw_calculated_ph
            row["calculated_ph_corrected_co2"] = corrected_calculated_ph
            row["calculated_ph_corrected_minus_raw_delta"] = (
                corrected_calculated_ph - raw_calculated_ph
                if raw_calculated_ph is not None
                and corrected_calculated_ph is not None
                else None
            )

        self._analysis_store_profile_calibration(
            model_key=ph_model_key,
            basis_signature=basis_signature,
            calibration_payload=calibration_payload,
        )
        return rows, calibration_payload, anchor_payload

    def _analysis_alignment_audit_and_reconcile(
        self,
        *,
        timeline_rows: Sequence[Mapping[str, Any]],
        dashboard_payload: Optional[Mapping[str, Any]],
        calibration_payload: Optional[Mapping[str, Any]],
    ) -> Dict[str, Any]:
        """Audit and reconcile Analysis output alignment across runtime surfaces.

        Purpose:
            Compare corrected timeline tail values with dashboard summary fields
            and auto-reconcile mismatches using corrected-primary precedence.
        Why:
            Analysis outputs should remain coherent across timeline, dashboard,
            snapshot, and warning narratives even after partial fallback paths.
        Inputs:
            timeline_rows: Calibrated timeline rows.
            dashboard_payload: Dashboard payload candidate to audit in-place.
            calibration_payload: Optional measured-pH calibration payload.
        Outputs:
            Dict[str, Any]: Alignment audit status, mismatch details, and warnings.
        Side Effects:
            Mutates `dashboard_payload["summary"]` reconciliation targets when
            mismatches are detected.
        Exceptions:
            Invalid payload shapes degrade to warn-only skipped audit status.
        """
        if not isinstance(dashboard_payload, Mapping):
            return {
                "status": "skipped",
                "mismatch_count": 0,
                "mismatches": [],
                "warnings": ["Alignment audit skipped: dashboard payload unavailable."],
            }
        summary = (
            dict(dashboard_payload.get("summary"))
            if isinstance(dashboard_payload.get("summary"), Mapping)
            else {}
        )
        rows = [dict(row or {}) for row in timeline_rows or [] if isinstance(row, Mapping)]
        mismatches: List[Dict[str, Any]] = []

        def _value_mismatch(left: Optional[float], right: Optional[float]) -> bool:
            """Return whether two optional float values should be treated as mismatched."""
            left_value = _safe_float(left)
            right_value = _safe_float(right)
            if left_value is None or right_value is None:
                return left_value is not None or right_value is not None
            return not _chemistry_float_close(
                float(left_value),
                float(right_value),
                rel_tol=5e-5,
                abs_tol=1e-9,
            )

        def _record_mismatch(
            field: str,
            expected_value: Optional[float],
            actual_value: Optional[float],
        ) -> None:
            """Append one mismatch row to the audit payload."""
            mismatches.append(
                {
                    "field": field,
                    "expected": _safe_float(expected_value),
                    "actual": _safe_float(actual_value),
                }
            )

        latest_row = rows[-1] if rows else {}
        timeline_corrected_g = _safe_float(latest_row.get("corrected_cumulative_co2_g"))
        timeline_corrected_mol = _safe_float(latest_row.get("corrected_cumulative_co2_mol"))
        timeline_corrected_ph = _safe_float(latest_row.get("corrected_ph"))
        if timeline_corrected_g is not None:
            summary_value = _safe_float(summary.get("corrected_total_uptake_g"))
            if _value_mismatch(timeline_corrected_g, summary_value):
                _record_mismatch(
                    "corrected_total_uptake_g",
                    timeline_corrected_g,
                    summary_value,
                )
            summary["corrected_total_uptake_g"] = timeline_corrected_g
        if timeline_corrected_mol is not None:
            summary_value = _safe_float(summary.get("corrected_total_uptake_mol"))
            if _value_mismatch(timeline_corrected_mol, summary_value):
                _record_mismatch(
                    "corrected_total_uptake_mol",
                    timeline_corrected_mol,
                    summary_value,
                )
            summary["corrected_total_uptake_mol"] = timeline_corrected_mol
        if timeline_corrected_ph is not None:
            summary_value = _safe_float(summary.get("latest_corrected_ph"))
            if _value_mismatch(timeline_corrected_ph, summary_value):
                _record_mismatch(
                    "latest_corrected_ph",
                    timeline_corrected_ph,
                    summary_value,
                )
            summary["latest_corrected_ph"] = timeline_corrected_ph

        selected_cycle_id = None
        get_state = getattr(self, "_analysis_dashboard_get_state", None)
        parse_selector = getattr(self, "_analysis_dashboard_parse_cycle_selector", None)
        if callable(get_state):
            try:
                state = get_state()
            except Exception:
                state = {}
            if isinstance(state, Mapping):
                selected_token = state.get("selected_cycle", "latest")
                if callable(parse_selector):
                    try:
                        selected_token = parse_selector(selected_token)
                    except Exception:
                        selected_token = selected_token
                if isinstance(selected_token, (int, float)) and math.isfinite(
                    float(selected_token)
                ):
                    parsed_selected = int(float(selected_token))
                    if parsed_selected > 0:
                        selected_cycle_id = parsed_selected
        actual_rows = list(dashboard_payload.get("actual_cycle_series") or [])
        reference_rows = list(dashboard_payload.get("reference_cycle_series") or [])
        comparison_rows = list(dashboard_payload.get("comparison_series") or [])

        def _row_for_cycle(
            rows_for_cycle: Sequence[Mapping[str, Any]],
            cycle_id: Optional[int],
        ) -> Optional[Mapping[str, Any]]:
            """Resolve one row by cycle id with best-effort type coercion."""
            if cycle_id is None:
                return None
            for candidate in rows_for_cycle:
                if not isinstance(candidate, Mapping):
                    continue
                try:
                    parsed_cycle = int(float(candidate.get("cycle_id")))
                except Exception:
                    continue
                if parsed_cycle == int(cycle_id):
                    return candidate
            return None

        selected_actual_row = _row_for_cycle(actual_rows, selected_cycle_id)
        selected_reference_row = _row_for_cycle(reference_rows, selected_cycle_id)
        selected_comparison_row = _row_for_cycle(comparison_rows, selected_cycle_id)
        if selected_actual_row is None and actual_rows:
            selected_actual_row = actual_rows[-1]
        if selected_reference_row is None and reference_rows:
            selected_reference_row = reference_rows[-1]
        if selected_comparison_row is None and comparison_rows:
            selected_comparison_row = comparison_rows[-1]
        selected_actual_channels = _analysis_ph_channels_from_row(
            selected_actual_row if isinstance(selected_actual_row, Mapping) else None
        )
        selected_actual_ph = _safe_float(selected_actual_channels.get("actual_observed_ph"))
        selected_calculated_ph = _safe_float(selected_actual_channels.get("calculated_ph"))
        selected_calibrated_ph = _safe_float(
            selected_actual_channels.get("calibrated_estimated_ph")
        )
        selected_reference_ph = (
            _safe_float(selected_reference_row.get("ph"))
            if isinstance(selected_reference_row, Mapping)
            else None
        )
        selected_co2_aligned_ph = (
            _safe_float(selected_comparison_row.get("reference_co2_aligned_ph"))
            if isinstance(selected_comparison_row, Mapping)
            else None
        )
        if selected_actual_ph is not None:
            summary_value = _safe_float(summary.get("latest_actual_ph"))
            if _value_mismatch(selected_actual_ph, summary_value):
                _record_mismatch("latest_actual_ph", selected_actual_ph, summary_value)
            summary["latest_actual_ph"] = selected_actual_ph
            summary["latest_actual_observed_ph"] = selected_actual_ph
        if selected_calculated_ph is not None:
            summary_value = _safe_float(summary.get("latest_calculated_ph"))
            if _value_mismatch(selected_calculated_ph, summary_value):
                _record_mismatch(
                    "latest_calculated_ph",
                    selected_calculated_ph,
                    summary_value,
                )
            summary["latest_calculated_ph"] = selected_calculated_ph
        if selected_calibrated_ph is not None:
            summary_value = _safe_float(summary.get("latest_calibrated_estimated_ph"))
            if _value_mismatch(selected_calibrated_ph, summary_value):
                _record_mismatch(
                    "latest_calibrated_estimated_ph",
                    selected_calibrated_ph,
                    summary_value,
                )
            summary["latest_calibrated_estimated_ph"] = selected_calibrated_ph
        if selected_reference_ph is not None:
            summary_value = _safe_float(summary.get("latest_plan_cycle_ph"))
            if _value_mismatch(selected_reference_ph, summary_value):
                _record_mismatch("latest_plan_cycle_ph", selected_reference_ph, summary_value)
            summary["latest_plan_cycle_ph"] = selected_reference_ph
        if selected_co2_aligned_ph is not None:
            summary_value = _safe_float(summary.get("latest_plan_co2_aligned_ph"))
            if _value_mismatch(selected_co2_aligned_ph, summary_value):
                _record_mismatch(
                    "latest_plan_co2_aligned_ph",
                    selected_co2_aligned_ph,
                    summary_value,
                )
            summary["latest_plan_co2_aligned_ph"] = selected_co2_aligned_ph
        if selected_cycle_id is not None:
            summary["selected_cycle_id"] = int(selected_cycle_id)

        if isinstance(calibration_payload, Mapping):
            requirement_source = str(summary.get("co2_requirement_source") or "").strip().lower()
            for key in (
                "completion_from_measured_ph_pct",
                "co2_required_for_target_ph_g",
                "co2_required_for_target_ph_mol",
                "anchor_residual_before",
                "anchor_residual_after",
                "alpha_pre",
                "alpha_post",
            ):
                if (
                    requirement_source == "guidance_model"
                    and key in {"co2_required_for_target_ph_g", "co2_required_for_target_ph_mol"}
                ):
                    continue
                calibrated_value = _safe_float(calibration_payload.get(key))
                if calibrated_value is None:
                    continue
                summary_value = _safe_float(summary.get(key))
                if _value_mismatch(calibrated_value, summary_value):
                    _record_mismatch(key, calibrated_value, summary_value)
                summary[key] = calibrated_value
            latest_corrected = calibration_payload.get("latest_corrected_speciation")
            if isinstance(latest_corrected, Mapping):
                corrected_ph = _safe_float(latest_corrected.get("ph"))
                if corrected_ph is not None:
                    summary["latest_corrected_ph"] = corrected_ph
                corrected_fractions = latest_corrected.get("fractions")
                if isinstance(corrected_fractions, Mapping):
                    summary["latest_corrected_fractions"] = dict(corrected_fractions)

        status = "ok" if not mismatches else "reconciled"
        warnings: List[str] = []
        if mismatches:
            warnings.append(
                "Alignment audit reconciled "
                f"{len(mismatches)} mismatch(es) using corrected-primary precedence."
            )
            for mismatch in mismatches[:5]:
                warnings.append(
                    f"{mismatch['field']}: expected {mismatch['expected']} | actual {mismatch['actual']}."
                )
        summary_warnings = [
            str(item)
            for item in (summary.get("warnings") or [])
            if str(item).strip()
        ]
        if warnings:
            summary_warnings.extend([f"Alignment audit: {item}" for item in warnings])
        summary["warnings"] = summary_warnings
        summary["alignment_audit_status"] = status
        summary["alignment_audit_mismatch_count"] = len(mismatches)

        # Keep payload dict updates explicit and in-place for downstream consumers.
        dashboard_payload["summary"] = summary
        audit_payload = {
            "status": status,
            "mismatch_count": len(mismatches),
            "mismatches": mismatches,
            "warnings": warnings,
        }
        dashboard_payload["alignment_audit"] = audit_payload
        return audit_payload

    def _analysis_consistency_audit_and_sanitize(
        self,
        *,
        timeline_rows: Sequence[Mapping[str, Any]],
        dashboard_payload: Optional[Mapping[str, Any]],
        calibration_payload: Optional[Mapping[str, Any]],
    ) -> Dict[str, Any]:
        """Audit Analysis outputs for chemistry consistency and sanitize messaging.

        Purpose:
            Detect contradictions across pH channels, CO2 ledger values, and
            anchor fit; then replace contradiction-prone raw warnings with clear
            operator diagnostics.
        Why:
            Analysis surfaces must not present conflicting chemical narratives
            when anchors/calibration indicate a different regime than raw solver
            edge states.
        Inputs:
            timeline_rows: Calibrated timeline rows to audit/mutate in-place.
            dashboard_payload: Dashboard payload carrying summary and series rows.
            calibration_payload: Optional calibration payload with anchor metadata.
        Outputs:
            Dict[str, Any]: Consistency status, findings, and remediation details.
        Side Effects:
            Mutates timeline/dashboard warning text and consistency flags.
        Exceptions:
            Invalid payloads degrade safely to a skipped audit result.
        """
        if not isinstance(dashboard_payload, Mapping):
            return {
                "status": "skipped",
                "severity": "info",
                "issue_codes": [],
                "affected_cycles": [],
                "findings": [],
                "recommended_actions": [],
                "sanitized_warnings": [],
                "sanitized_warning_count": 0,
            }
        summary = (
            dict(dashboard_payload.get("summary"))
            if isinstance(dashboard_payload.get("summary"), Mapping)
            else {}
        )
        tolerance_ph = _safe_float(summary.get("analysis_anchor_fit_tolerance_ph"))
        if tolerance_ph is None:
            tolerance_ph = _safe_float(
                calibration_payload.get("anchor_fit_tolerance_ph")
                if isinstance(calibration_payload, Mapping)
                else None
            )
        if tolerance_ph is None:
            tolerance_ph = self._analysis_anchor_fit_tolerance_ph()
        tolerance_ph = float(max(0.01, min(float(tolerance_ph), 1.00)))
        summary["analysis_anchor_fit_tolerance_ph"] = tolerance_ph

        cycle_rows: List[Dict[str, Any]] = [
            row if isinstance(row, dict) else dict(row or {})
            for row in (timeline_rows or [])
            if isinstance(row, Mapping)
        ]
        actual_series = list(dashboard_payload.get("actual_cycle_series") or [])
        actual_by_cycle: Dict[int, Dict[str, Any]] = {}
        for actual_row in actual_series:
            if not isinstance(actual_row, Mapping):
                continue
            cycle_id = _safe_rust_int(actual_row.get("cycle_id"), -1)
            if cycle_id is None or cycle_id <= 0:
                continue
            actual_by_cycle[int(cycle_id)] = (
                actual_row if isinstance(actual_row, dict) else dict(actual_row)
            )

        findings: List[Dict[str, Any]] = []
        recommended_actions: List[str] = []
        recommended_seen: Set[str] = set()
        sanitized_warnings: List[str] = []
        issue_codes_seen: Set[str] = set()
        affected_cycles_seen: Set[int] = set()
        sanitized_count = 0
        additional_required_g = _safe_float(summary.get("additional_co2_required_g"))
        if additional_required_g is None:
            required_total_g = _safe_float(summary.get("co2_required_for_target_ph_g"))
            corrected_total_g = _safe_float(summary.get("corrected_total_uptake_g"))
            if required_total_g is not None and corrected_total_g is not None:
                additional_required_g = max(required_total_g - corrected_total_g, 0.0)

        def _add_recommendation(text: str) -> None:
            """Append one unique remediation recommendation."""
            token = str(text or "").strip()
            if not token or token in recommended_seen:
                return
            recommended_seen.add(token)
            recommended_actions.append(token)

        def _record_finding(
            *,
            cycle_id: Optional[int],
            issue_code: str,
            severity: str,
            detail: str,
        ) -> None:
            """Append one structured consistency finding row."""
            findings.append(
                {
                    "cycle_id": int(cycle_id) if cycle_id is not None else None,
                    "issue_code": str(issue_code),
                    "severity": str(severity),
                    "detail": str(detail),
                }
            )
            issue_codes_seen.add(str(issue_code))
            if cycle_id is not None:
                affected_cycles_seen.add(int(cycle_id))

        for row in cycle_rows:
            cycle_id = _safe_rust_int(row.get("cycle_id"), -1)
            cycle_id_value = int(cycle_id) if cycle_id is not None and cycle_id > 0 else None
            channels = _analysis_ph_channels_from_row(row)
            calculated_ph = _safe_float(channels.get("calculated_ph"))
            calibrated_ph = _safe_float(channels.get("calibrated_estimated_ph"))
            actual_observed_ph = _safe_float(channels.get("actual_observed_ph"))
            warnings_list = row.get("warnings")
            if isinstance(warnings_list, Sequence) and not isinstance(
                warnings_list, (str, bytes, bytearray)
            ):
                warnings = [str(item).strip() for item in warnings_list if str(item).strip()]
            elif isinstance(warnings_list, str) and warnings_list.strip():
                warnings = [warnings_list.strip()]
            else:
                warnings = []
            warning_codes = list(row.get("warning_codes") or [])
            consistency_flags = set(
                str(item).strip()
                for item in list(row.get("consistency_flags") or [])
                if str(item).strip()
            )

            added_mol = _safe_float(row.get("co2_added_moles"))
            consumed_mol = _safe_float(row.get("co2_consumed_moles"))
            unconsumed_mol = _safe_float(row.get("co2_unconsumed_moles"))
            if (
                added_mol is not None
                and consumed_mol is not None
                and unconsumed_mol is not None
                and math.isfinite(added_mol)
                and math.isfinite(consumed_mol)
                and math.isfinite(unconsumed_mol)
            ):
                imbalance = abs(float(added_mol) - (float(consumed_mol) + float(unconsumed_mol)))
                imbalance_tol = max(1e-9, abs(float(added_mol)) * 1e-4)
                if imbalance > imbalance_tol:
                    consistency_flags.add("mass_balance_mismatch")
                    _record_finding(
                        cycle_id=cycle_id_value,
                        issue_code="mass_balance_mismatch",
                        severity="watch",
                        detail=(
                            "CO2 cycle balance mismatch: added does not equal "
                            "consumed + unconsumed within tolerance."
                        ),
                    )
                    _add_recommendation(
                        "Verify cycle uptake/import values and rerun Analysis calibration."
                    )

            ledger_naoh_remaining = _safe_float(row.get("ledger_naoh_remaining_mol"), 0.0)
            raw_low_ph_flag = (
                ("raw_low_ph_while_naoh" in warning_codes)
                or (
                    ledger_naoh_remaining is not None
                    and ledger_naoh_remaining > 1e-6
                    and calculated_ph is not None
                    and calculated_ph < 8.0
                )
            )
            if raw_low_ph_flag:
                consistency_flags.add("raw_low_ph_while_naoh")
                context_ph = (
                    actual_observed_ph
                    if actual_observed_ph is not None
                    else calibrated_ph
                )
                remaining_large = (
                    additional_required_g is not None and float(additional_required_g) > 1.0
                )
                non_acidic_context = (
                    context_ph is not None and math.isfinite(context_ph) and context_ph >= 8.0
                )
                if remaining_large and non_acidic_context:
                    consistency_flags.add("low_ph_naoh_contradiction")
                    _record_finding(
                        cycle_id=cycle_id_value,
                        issue_code="low_ph_naoh_contradiction",
                        severity="contradiction",
                        detail=(
                            "Raw calculated pH dropped below 8 while NaOH remained, "
                            "but anchor/calibrated context and CO2 remaining indicate "
                            "the system is still in expected alkaline progression."
                        ),
                    )
                    _add_recommendation(
                        "Use anchor-calibrated pH as primary context and verify CO2 ledger/source channels."
                    )
                    _add_recommendation(
                        "Recompute calibration after confirming cycle uptake and anchor entries."
                    )
                    if ANALYSIS_CONSISTENCY_LOW_PH_WARNING_TEXT in warnings:
                        warnings = [
                            row_text
                            for row_text in warnings
                            if row_text != ANALYSIS_CONSISTENCY_LOW_PH_WARNING_TEXT
                        ]
                        sanitized_count += 1
                    replacement = (
                        "Chemistry consistency check: raw low-pH + residual-NaOH "
                        "contradiction detected; using anchor/calibrated context."
                    )
                    if replacement not in warnings:
                        warnings.append(replacement)
                        sanitized_warnings.append(
                            f"Cycle {cycle_id_value or '--'}: {replacement}"
                        )
                else:
                    _record_finding(
                        cycle_id=cycle_id_value,
                        issue_code="raw_low_ph_while_naoh_watch",
                        severity="watch",
                        detail=(
                            "Raw calculated pH < 8 with residual NaOH; check cycle "
                            "uptake and reaction-input consistency."
                        ),
                    )
                    _add_recommendation(
                        "Review cycle-level CO2 uptake and pressure-derived moles for this region."
                    )

            if (
                actual_observed_ph is not None
                and calibrated_ph is not None
                and math.isfinite(actual_observed_ph)
                and math.isfinite(calibrated_ph)
            ):
                anchor_residual_abs = abs(float(calibrated_ph) - float(actual_observed_ph))
                if anchor_residual_abs > tolerance_ph + 1e-12:
                    consistency_flags.add("anchor_fit_outside_tolerance")
                    severity = (
                        "contradiction"
                        if anchor_residual_abs > (tolerance_ph * 1.5)
                        else "watch"
                    )
                    _record_finding(
                        cycle_id=cycle_id_value,
                        issue_code="anchor_fit_outside_tolerance",
                        severity=severity,
                        detail=(
                            f"Calibrated pH differs from anchor by {anchor_residual_abs:.3f}, "
                            f"exceeding tolerance ±{tolerance_ph:.2f}."
                        ),
                    )
                    _add_recommendation(
                        "Adjust anchor-fit tolerance or add more representative anchors before trusting extrapolated tails."
                    )

            row["warnings"] = warnings
            row["consistency_flags"] = sorted(consistency_flags)
            row["calculated_ph"] = _safe_float(channels.get("calculated_ph"))
            row["calibrated_estimated_ph"] = _safe_float(
                channels.get("calibrated_estimated_ph")
            )
            row["actual_observed_ph"] = _safe_float(channels.get("actual_observed_ph"))
            row["consistency_status"] = "consistent"
            if "low_ph_naoh_contradiction" in consistency_flags:
                row["consistency_status"] = "contradiction"
            elif consistency_flags:
                row["consistency_status"] = "watch"
            if cycle_id_value is not None and cycle_id_value in actual_by_cycle:
                actual_row = actual_by_cycle[cycle_id_value]
                existing_actual_channels = _analysis_ph_channels_from_row(actual_row)
                actual_row["warnings"] = list(warnings)
                actual_row["consistency_flags"] = list(row["consistency_flags"])
                actual_row["consistency_status"] = row["consistency_status"]
                calculated_value = _safe_float(row.get("calculated_ph"))
                if calculated_value is None:
                    calculated_value = _safe_float(existing_actual_channels.get("calculated_ph"))
                calibrated_value = _safe_float(row.get("calibrated_estimated_ph"))
                if calibrated_value is None:
                    calibrated_value = _safe_float(
                        existing_actual_channels.get("calibrated_estimated_ph")
                    )
                actual_observed_value = _safe_float(row.get("actual_observed_ph"))
                if actual_observed_value is None:
                    actual_observed_value = _safe_float(
                        existing_actual_channels.get("actual_observed_ph")
                    )
                actual_row["calculated_ph"] = calculated_value
                actual_row["calibrated_estimated_ph"] = calibrated_value
                actual_row["actual_observed_ph"] = actual_observed_value

        has_contradiction = any(
            str(item.get("severity") or "").lower() == "contradiction"
            for item in findings
            if isinstance(item, Mapping)
        )
        has_watch = any(
            str(item.get("severity") or "").lower() == "watch"
            for item in findings
            if isinstance(item, Mapping)
        )
        status = "consistent"
        severity = "info"
        if has_contradiction:
            status = "contradiction"
            severity = "high"
        elif has_watch:
            status = "watch"
            severity = "medium"

        consistency_payload = {
            "status": status,
            "severity": severity,
            "issue_codes": sorted(issue_codes_seen),
            "affected_cycles": sorted(affected_cycles_seen),
            "findings": findings,
            "recommended_actions": recommended_actions,
            "sanitized_warnings": sanitized_warnings,
            "sanitized_warning_count": int(sanitized_count),
        }
        summary["analysis_consistency_status"] = status
        summary["analysis_consistency_severity"] = severity
        summary["analysis_consistency_findings"] = findings
        summary["analysis_consistency_recommendations"] = recommended_actions
        summary["analysis_consistency_sanitized_warning_count"] = int(sanitized_count)
        summary["analysis_consistency_issue_codes"] = sorted(issue_codes_seen)
        summary["analysis_consistency_affected_cycles"] = sorted(affected_cycles_seen)
        dashboard_payload["summary"] = summary
        dashboard_payload["analysis_consistency"] = dict(consistency_payload)
        if actual_series:
            ordered_actual: List[Dict[str, Any]] = []
            for row in actual_series:
                if not isinstance(row, Mapping):
                    continue
                cycle_id = _safe_rust_int(row.get("cycle_id"), -1)
                if cycle_id is None or cycle_id <= 0 or int(cycle_id) not in actual_by_cycle:
                    ordered_actual.append(dict(row))
                else:
                    ordered_actual.append(dict(actual_by_cycle[int(cycle_id)]))
            dashboard_payload["actual_cycle_series"] = ordered_actual
        return consistency_payload

    def _compute_analysis_forensic_timeline(
        self,
        timeline_rows: Sequence[Mapping[str, Any]],
        *,
        reference_trace: Optional[Mapping[str, Any]] = None,
    ) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
        """Augment Analysis timeline rows with forensic comparison fields.

        Purpose:
            Attach planning-vs-actual deltas to each cycle row and compute summary
            metrics for the Analysis forensic KPI panel.
        Why:
            Advanced Analysis mode is intended to diagnose reaction behavior, not
            just display standalone cycle snapshots.
        Args:
            timeline_rows: Existing cycle timeline rows from the Analysis workflow.
            reference_trace: Optional precomputed planning-reference trace to use
                instead of reading the live UI cache.
        Returns:
            Tuple of `(augmented_rows, summary_metrics)`. When `timeline_rows`
            is empty, summary values are returned as unavailable (`None`).
        Side Effects:
            None.
        Exceptions:
            Missing planning reference data produces sparse/out-of-range flags
            without raising.
        """
        rows: List[Dict[str, Any]] = [dict(entry or {}) for entry in (timeline_rows or [])]
        # Maintain stable summary keys so callers/UI bindings can always read one schema.
        empty_summary: Dict[str, Any] = {
            "ph_mae_cycle": None,
            "ph_rmse_cycle": None,
            "ph_mae_co2": None,
            "ph_rmse_co2": None,
            "pH_MAE_cycle": None,
            "pH_RMSE_cycle": None,
            "pH_MAE_co2": None,
            "pH_RMSE_co2": None,
            "gas_delta_mol": None,
            "gas_delta_g": None,
            "gas_delta_pct": None,
            "hco3_delta_pct": None,
            "co3_delta_pct": None,
            "equivalence_cycle_delta": None,
            "completion_gap_pct": None,
        }
        if not rows:
            return rows, dict(empty_summary)
        reference = (
            dict(reference_trace)
            if isinstance(reference_trace, Mapping)
            else (getattr(self, "_analysis_reference_trace", None) or {})
        )
        ref_x = list(reference.get("x_co2_g_series") or [])
        ref_ph = list(reference.get("ph_series") or [])
        ref_cycle_mol = list(reference.get("cycle_co2_mol_series") or [])
        ref_hco3 = list(reference.get("hco3_series") or [])
        ref_co3 = list(reference.get("co3_series") or [])
        ref_cum_mol = list(reference.get("cumulative_co2_mol_series") or [])
        eq_co2_g = _safe_float(reference.get("equivalence_co2_g"))
        eq_planning_index = reference.get("equivalence_index")
        if eq_planning_index is not None:
            try:
                eq_planning_cycle = int(eq_planning_index) + 1
            except Exception:
                eq_planning_cycle = None
        else:
            eq_planning_cycle = None

        cycle_residuals: List[Optional[float]] = []
        co2_residuals: List[Optional[float]] = []
        actual_equiv_cycle: Optional[int] = None

        # Compare every Analysis cycle row against planning references using both alignments.
        for idx, entry in enumerate(rows):
            co2_total_g = (
                _safe_float(entry.get("co2_g"))
                or _safe_float(entry.get("cumulative_co2_added_mass_g"))
                or _safe_float(entry.get("co2_mass_g"))
                or 0.0
            )
            actual_ph = _safe_float(
                entry.get("ph")
                if entry.get("ph") not in (None, "")
                else (
                    entry.get("actual_ph")
                    if entry.get("actual_ph") not in (None, "")
                    else entry.get("solution_ph")
                )
            )
            actual_cycle_mol = _safe_float(entry.get("co2_moles"))
            if actual_cycle_mol is None:
                actual_cycle_mol = _safe_float(entry.get("co2_added_moles"))

            planning_cycle_ph = (
                _safe_float(ref_ph[idx]) if idx < len(ref_ph) else None
            )
            planning_cycle_co2_mol = (
                _safe_float(ref_cycle_mol[idx]) if idx < len(ref_cycle_mol) else None
            )
            planning_cycle_hco3 = _safe_float(ref_hco3[idx]) if idx < len(ref_hco3) else None
            planning_cycle_co3 = _safe_float(ref_co3[idx]) if idx < len(ref_co3) else None

            planning_co2_aligned_ph, ph_alignment_flag = self._analysis_interpolate_reference_series(
                co2_total_g, ref_x, ref_ph
            )
            planning_hco3_aligned, hco3_alignment_flag = self._analysis_interpolate_reference_series(
                co2_total_g, ref_x, ref_hco3
            )
            planning_co3_aligned, co3_alignment_flag = self._analysis_interpolate_reference_series(
                co2_total_g, ref_x, ref_co3
            )

            if "out_of_range" in (
                ph_alignment_flag,
                hco3_alignment_flag,
                co3_alignment_flag,
            ):
                quality_flag = "out_of_range"
            elif "sparse_reference" in (
                ph_alignment_flag,
                hco3_alignment_flag,
                co3_alignment_flag,
            ):
                quality_flag = "sparse_reference"
            else:
                quality_flag = "ok"

            ph_delta_cycle = (
                (actual_ph - planning_cycle_ph)
                if actual_ph is not None and planning_cycle_ph is not None
                else None
            )
            ph_delta_co2 = (
                (actual_ph - planning_co2_aligned_ph)
                if actual_ph is not None and planning_co2_aligned_ph is not None
                else None
            )
            cycle_residuals.append(ph_delta_cycle)
            co2_residuals.append(ph_delta_co2)

            co2_mol_delta = (
                (actual_cycle_mol - planning_cycle_co2_mol)
                if actual_cycle_mol is not None and planning_cycle_co2_mol is not None
                else None
            )
            if (
                co2_mol_delta is not None
                and planning_cycle_co2_mol is not None
                and abs(planning_cycle_co2_mol) > 1e-12
            ):
                co2_mol_delta_pct = (co2_mol_delta / planning_cycle_co2_mol) * 100.0
            else:
                co2_mol_delta_pct = None

            actual_fractions = entry.get("fractions") or {}
            actual_hco3_pct = _safe_float(actual_fractions.get("HCO3-"), 0.0) * 100.0
            actual_co3_pct = _safe_float(actual_fractions.get("CO3^2-"), 0.0) * 100.0
            planning_hco3_pct = (
                planning_hco3_aligned * 100.0
                if planning_hco3_aligned is not None
                else (
                    planning_cycle_hco3 * 100.0 if planning_cycle_hco3 is not None else None
                )
            )
            planning_co3_pct = (
                planning_co3_aligned * 100.0
                if planning_co3_aligned is not None
                else (
                    planning_cycle_co3 * 100.0 if planning_cycle_co3 is not None else None
                )
            )
            hco3_pct_delta = (
                (actual_hco3_pct - planning_hco3_pct)
                if planning_hco3_pct is not None
                else None
            )
            co3_pct_delta = (
                (actual_co3_pct - planning_co3_pct)
                if planning_co3_pct is not None
                else None
            )

            entry["planning_cycle_ph"] = planning_cycle_ph
            entry["planning_co2_aligned_ph"] = planning_co2_aligned_ph
            entry["actual_ph"] = actual_ph
            entry["ph"] = actual_ph
            entry["ph_delta_cycle"] = ph_delta_cycle
            entry["ph_delta_co2"] = ph_delta_co2
            entry["actual_cycle_co2_mol"] = actual_cycle_mol
            entry["planning_cycle_co2_mol"] = planning_cycle_co2_mol
            entry["co2_mol_delta"] = co2_mol_delta
            entry["co2_mol_delta_pct"] = co2_mol_delta_pct
            entry["actual_hco3_pct"] = actual_hco3_pct
            entry["actual_co3_pct"] = actual_co3_pct
            entry["planning_hco3_pct"] = planning_hco3_pct
            entry["planning_co3_pct"] = planning_co3_pct
            entry["hco3_pct_delta"] = hco3_pct_delta
            entry["co3_pct_delta"] = co3_pct_delta
            entry["alignment_quality_flag"] = quality_flag

            if actual_equiv_cycle is None and eq_co2_g is not None and co2_total_g >= eq_co2_g:
                actual_equiv_cycle = idx + 1

        mae_cycle, rmse_cycle = self._analysis_residual_metrics(cycle_residuals)
        mae_co2, rmse_co2 = self._analysis_residual_metrics(co2_residuals)
        last_row = rows[-1] if rows else {}
        actual_total_mol = (
            _safe_float(last_row.get("cumulative_co2_added_moles"))
            or _safe_float(last_row.get("co2_total_moles"))
            or _safe_float(last_row.get("cumulative_co2_added_mass_g"), 0.0) / SOL_MW_CO2
            or 0.0
        )
        planning_total_mol = _safe_float(ref_cum_mol[-1]) if ref_cum_mol else None
        if (
            planning_total_mol is None
            and ref_x
            and math.isfinite(_safe_float(ref_x[-1], float("nan")))
        ):
            planning_total_mol = _safe_float(ref_x[-1], 0.0) / SOL_MW_CO2
        gas_delta_mol = (
            (actual_total_mol - planning_total_mol)
            if planning_total_mol is not None
            else None
        )
        gas_delta_g = (
            gas_delta_mol * SOL_MW_CO2 if gas_delta_mol is not None else None
        )
        if (
            gas_delta_mol is not None
            and planning_total_mol is not None
            and abs(planning_total_mol) > 1e-12
        ):
            gas_delta_pct = (gas_delta_mol / planning_total_mol) * 100.0
        else:
            gas_delta_pct = None

        completion_gap_pct = None
        if planning_total_mol is not None and planning_total_mol > 1e-12:
            completion_pct = max(0.0, min(actual_total_mol / planning_total_mol, 1.0)) * 100.0
            completion_gap_pct = completion_pct - 100.0

        hco3_delta_final = _safe_float(last_row.get("hco3_pct_delta"))
        co3_delta_final = _safe_float(last_row.get("co3_pct_delta"))
        if (
            actual_equiv_cycle is not None
            and eq_planning_cycle is not None
        ):
            equivalence_cycle_delta = float(actual_equiv_cycle - eq_planning_cycle)
        else:
            equivalence_cycle_delta = None

        summary = dict(empty_summary)
        summary.update(
            {
                "ph_mae_cycle": mae_cycle,
                "ph_rmse_cycle": rmse_cycle,
                "ph_mae_co2": mae_co2,
                "ph_rmse_co2": rmse_co2,
                "pH_MAE_cycle": mae_cycle,
                "pH_RMSE_cycle": rmse_cycle,
                "pH_MAE_co2": mae_co2,
                "pH_RMSE_co2": rmse_co2,
                "gas_delta_mol": gas_delta_mol,
                "gas_delta_g": gas_delta_g,
                "gas_delta_pct": gas_delta_pct,
                "hco3_delta_pct": hco3_delta_final,
                "co3_delta_pct": co3_delta_final,
                "equivalence_cycle_delta": equivalence_cycle_delta,
                "completion_gap_pct": completion_gap_pct,
            }
        )
        return rows, summary

    def _collect_planning_timeline_legend_entries(
        self, axes: Sequence[Any]
    ) -> Tuple[List[Any], List[str]]:
        """Collect cycle timeline legend entries across all axes.

        Purpose:
            Gather unique legend handles/labels from timeline axes.
        Why:
            The timeline view now uses one consolidated legend for every
            workflow mode (Planning/Analysis/Reprocessing) and export.
        Inputs:
            axes (Sequence[Any]): Axes to scan for legend entries.
        Outputs:
            Tuple[List[Any], List[str]]: Handles and labels in display order.
        Side Effects:
            None.
        Exceptions:
            - Best-effort; skips axes that fail to report legend entries.
        """
        handles: List[Any] = []
        labels: List[str] = []
        # Collect handles across axes so timeline legends stay consolidated.
        for axis in axes:
            try:
                axis_handles, axis_labels = axis.get_legend_handles_labels()
            except Exception:
                continue
            for handle, label in zip(axis_handles, axis_labels):
                if not label or label.startswith("_") or label in labels:
                    continue
                handles.append(handle)
                labels.append(label)
        return handles, labels

    def _cycle_timeline_legend_entries_for_role(
        self, *, ax: Any, ax2: Any, ax3: Any, role: str
    ) -> Tuple[List[Any], List[str], Any]:
        """Collect legend entries for one cycle timeline subplot role.

        Purpose:
            Partition timeline legend labels into top and bottom subplot channels.
        Why:
            Timeline display/export now renders draggable legends per subplot.
            The bottom subplot uses `twinx`, so drag pick-events resolve on the
            top-most twin axis; hosting the bottom legend there keeps preview
            dragging functional.
        Inputs:
            ax: Top sodium-speciation axis.
            ax2: Bottom pH axis.
            ax3: Bottom cycle-uptake secondary axis.
            role: Legend role (`top` or `bottom`).
        Outputs:
            Tuple of `(handles, labels, host_axis)` for requested role.
        Side Effects:
            None.
        Exceptions:
            Unknown roles fall back to top-axis collection.
        """
        normalized_role = str(role or "top").strip().lower()
        if normalized_role == "bottom":
            handles, labels = self._collect_planning_timeline_legend_entries((ax2, ax3))
            # On twinx stacks, Matplotlib pick-events target the top-most twin.
            host_axis = ax3 if ax3 is not None else ax2
            return handles, labels, host_axis
        handles, labels = self._collect_planning_timeline_legend_entries((ax,))
        return handles, labels, ax

    def _cycle_timeline_legend_default_loc_for_role(self, role: str) -> str:
        """Return default in-axes legend location for one timeline subplot role.

        Purpose:
            Provide deterministic starting locations for top/bottom legends.
        Why:
            Separate legends should avoid immediate overlap in shared figures.
        Inputs:
            role: Legend role (`top` or `bottom`).
        Outputs:
            str: Default legend location string.
        Side Effects:
            None.
        Exceptions:
            Unknown roles default to top placement.
        """
        normalized_role = str(role or "top").strip().lower()
        if normalized_role == "bottom":
            return "upper right"
        return "upper left"

    def _mark_cycle_timeline_subplot_legend(self, legend: Any, role: str) -> Any:
        """Tag one legend with a cycle timeline subplot role.

        Purpose:
            Persist explicit legend role metadata on timeline legends.
        Why:
            Preview-close capture/apply must target top and bottom legends
            independently.
        Inputs:
            legend: Candidate Matplotlib legend artist.
            role: Legend role (`top` or `bottom`).
        Outputs:
            Any: Same legend object when available, otherwise None.
        Side Effects:
            Adds role metadata attributes on the legend artist.
        Exceptions:
            Best-effort guards suppress metadata write failures.
        """
        legend = _mark_timeline_main_legend_artist(legend)
        if legend is None:
            return None
        normalized_role = "bottom" if str(role or "").strip().lower() == "bottom" else "top"
        try:
            legend._cycle_timeline_legend_role = normalized_role
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        return legend

    def _cycle_timeline_legend_needs_outside_fallback(
        self,
        legend: Any,
        fig: Optional[Figure],
        host_axis: Any,
    ) -> bool:
        """Return whether one timeline legend should move outside-right.

        Purpose:
            Detect crowded/off-canvas in-axes legends and trigger fallback.
        Why:
            Legends should remain readable when subplot interiors are too dense.
        Inputs:
            legend: Candidate legend artist.
            fig: Figure owning the legend.
            host_axis: Axis the legend belongs to.
        Outputs:
            bool: True when outside-right fallback should be used.
        Side Effects:
            May trigger one canvas draw for bbox measurement.
        Exceptions:
            Measurement failures return False.
        """
        if legend is None or fig is None or host_axis is None:
            return False
        if bool(getattr(legend, "_cycle_timeline_bottom_center_below_xlabel", False)):
            return False
        if bool(getattr(legend, "_cycle_timeline_bottom_wide_under_xaxis", False)):
            # Wide-under-x-axis mode is an explicit bottom-legend layout and
            # should not be auto-converted to the outside-right fallback.
            return False
        canvas = getattr(fig, "canvas", None)
        if canvas is None:
            try:
                canvas = FigureCanvasAgg(fig)
                fig.set_canvas(canvas)
            except Exception:
                return False
        try:
            canvas.draw()
            renderer = canvas.get_renderer()
            legend_bbox = legend.get_window_extent(renderer=renderer).transformed(
                fig.transFigure.inverted()
            )
            axis_bbox = host_axis.get_position()
        except Exception:
            return False
        legend_width = float(legend_bbox.x1 - legend_bbox.x0)
        legend_height = float(legend_bbox.y1 - legend_bbox.y0)
        axis_width = float(axis_bbox.x1 - axis_bbox.x0)
        axis_height = float(axis_bbox.y1 - axis_bbox.y0)
        if (
            not math.isfinite(legend_width)
            or not math.isfinite(legend_height)
            or not math.isfinite(axis_width)
            or not math.isfinite(axis_height)
            or axis_width <= 0.0
            or axis_height <= 0.0
        ):
            return False
        if not self._cycle_timeline_legend_is_on_canvas(legend, fig):
            return True
        width_ratio = legend_width / axis_width
        height_ratio = legend_height / axis_height
        if width_ratio >= 0.52 or height_ratio >= 0.52:
            return True
        return False

    def _reserve_cycle_timeline_bottom_wide_legend_margin(
        self,
        *,
        fig: Optional[Figure],
        host_axis: Any,
        legend: Any,
    ) -> None:
        """Reserve bottom subplot margin when bottom legend uses wide bbox mode.

        Purpose:
            Keep the draggable wide bottom timeline legend visible after layout.
        Why:
            Bbox-dragged legends can move below the subplot when bottom margin is
            too small; margin expansion should only occur when clipping is detected.
        Inputs:
            fig: Figure containing the timeline axes.
            host_axis: Axis that hosts the bottom legend.
            legend: Bottom legend artist.
        Outputs:
            None.
        Side Effects:
            May increase figure `subplots_adjust(bottom=...)` margin.
        Exceptions:
            Best-effort guards suppress renderer/layout failures.
        """
        if fig is None or host_axis is None or legend is None:
            return
        layout_mgr = getattr(fig, "_gl260_layout_manager", None)
        if (
            _layout_health_authoritative_timeline_bottom(
                fig,
                getattr(fig, "_gl260_layout_mode", "display"),
                layout_mgr,
            )
            is not None
        ):
            return
        if not bool(getattr(legend, "_cycle_timeline_bottom_wide_under_xaxis", False)):
            return
        canvas = getattr(fig, "canvas", None)
        if canvas is None:
            try:
                canvas = FigureCanvasAgg(fig)
                fig.set_canvas(canvas)
            except Exception:
                return
        try:
            canvas.draw()
            renderer = canvas.get_renderer()
            legend_bbox = legend.get_window_extent(renderer=renderer).transformed(
                fig.transFigure.inverted()
            )
        except Exception:
            return
        try:
            current_bottom = float(getattr(fig.subplotpars, "bottom", 0.0))
        except Exception:
            current_bottom = 0.0
        try:
            xlabel_artist = _layout_health_primary_xlabel(
                fig, plot_id="fig_cycle_timeline"
            )
        except Exception:
            xlabel_artist = None
        xlabel_bbox = _layout_health_bbox_in_fig(fig, xlabel_artist, renderer)
        xticks_bbox = _layout_health_axis_ticklabels_bbox(
            fig, host_axis.xaxis, renderer
        )
        fig_h_pts = max(float(fig.get_size_inches()[1]) * 72.0, 1.0)
        needs_bottom_floor = False
        if legend_bbox is not None and xlabel_bbox is not None:
            # Keep the minimum label band clear when wide timeline legends are active.
            xlabel_gap_pts = float((xlabel_bbox.y0 - legend_bbox.y1) * fig_h_pts)
            if (
                _layout_health_bbox_overlap_area(legend_bbox, xlabel_bbox) > 1e-8
                or xlabel_gap_pts
                < DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MIN_LEGEND_XLABEL_GAP_PTS
            ):
                needs_bottom_floor = True
        if legend_bbox is not None and xticks_bbox is not None:
            xtick_gap_pts = float((xticks_bbox.y0 - legend_bbox.y1) * fig_h_pts)
            if (
                _layout_health_bbox_overlap_area(legend_bbox, xticks_bbox) > 1e-8
                or xtick_gap_pts
                < DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MIN_LEGEND_XLABEL_GAP_PTS
            ):
                needs_bottom_floor = True
        if needs_bottom_floor and current_bottom < 0.24:
            try:
                fig.subplots_adjust(bottom=0.24)
                canvas.draw()
                renderer = canvas.get_renderer()
                legend_bbox = legend.get_window_extent(renderer=renderer).transformed(
                    fig.transFigure.inverted()
                )
                current_bottom = float(getattr(fig.subplotpars, "bottom", 0.0))
            except Exception:
                # Best-effort guard; ignore floor-reservation failures.
                pass
        if not math.isfinite(float(legend_bbox.y0)):
            return
        if float(legend_bbox.y0) >= 0.0:
            return
        needed_extra = min(0.12, abs(float(legend_bbox.y0)) + 0.02)
        target_bottom = min(
            0.38,
            max(current_bottom, 0.04) + needed_extra,
        )
        try:
            fig.subplots_adjust(bottom=target_bottom)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _cycle_timeline_sodium_pct_from_corrected_co2(
        self,
        corrected_cumulative_co2_mol: Optional[float],
        total_sodium_mol: Optional[float],
    ) -> Tuple[Optional[float], Optional[float], Optional[float]]:
        """Resolve sodium-speciation percentages from corrected cumulative CO2.

        Purpose:
            Convert corrected cumulative CO2 uptake into sodium-speciation
            percentages for NaOH/Na2CO3/NaHCO3 timeline rendering.
        Why:
            Analysis timeline top-panel visualization should reflect measured-pH
            anchor corrected uptake progression before falling back to simulation
            ledger state. Near bicarbonate capacity, it must use the same finite
            reactive-carbon transition as corrected Pitzer pH so the two plots do
            not describe different equilibrium states.
        Inputs:
            corrected_cumulative_co2_mol: Corrected cumulative CO2 uptake in mol.
            total_sodium_mol: Total sodium inventory in mol (Na basis).
        Outputs:
            Tuple containing `% NaOH`, `% Na2CO3`, `% NaHCO3` on a sodium basis.
        Side Effects:
            None.
        Exceptions:
            Returns `(None, None, None)` when inputs are unavailable/invalid.
        """
        corrected_mol = _safe_float(corrected_cumulative_co2_mol)
        sodium_total = _safe_float(total_sodium_mol)
        if (
            corrected_mol is None
            or sodium_total is None
            or not math.isfinite(corrected_mol)
            or not math.isfinite(sodium_total)
            or sodium_total <= 0.0
        ):
            return None, None, None
        corrected_mol = max(float(corrected_mol), 0.0)
        sodium_total = max(float(sodium_total), 0.0)
        reactive_carbon_resolver = getattr(
            _NAOH_PITZER_MODULE,
            "_effective_reactive_carbon",
            None,
        )
        if callable(reactive_carbon_resolver):
            # Match the corrected-pH inventory contract: late-cycle charged CO2
            # that remains in transport/headspace cannot advance liquid species.
            resolved_reactive_mol = _safe_float(
                reactive_carbon_resolver(corrected_mol, sodium_total)
            )
            if resolved_reactive_mol is not None and math.isfinite(
                float(resolved_reactive_mol)
            ):
                corrected_mol = max(float(resolved_reactive_mol), 0.0)
        naoh_mol = 0.0
        na2co3_mol = 0.0
        nahco3_mol = 0.0
        equivalence_split = sodium_total / 2.0
        if corrected_mol <= equivalence_split:
            naoh_mol = max(sodium_total - (2.0 * corrected_mol), 0.0)
            na2co3_mol = max(corrected_mol, 0.0)
            nahco3_mol = 0.0
        elif corrected_mol <= sodium_total:
            naoh_mol = 0.0
            na2co3_mol = max(sodium_total - corrected_mol, 0.0)
            nahco3_mol = max((2.0 * corrected_mol) - sodium_total, 0.0)
        else:
            naoh_mol = 0.0
            na2co3_mol = 0.0
            nahco3_mol = sodium_total
        naoh_pct = (naoh_mol / sodium_total) * 100.0
        na2co3_pct = ((2.0 * na2co3_mol) / sodium_total) * 100.0
        nahco3_pct = (nahco3_mol / sodium_total) * 100.0
        total_pct = max(naoh_pct + na2co3_pct + nahco3_pct, 0.0)
        if total_pct <= 0.0:
            return 0.0, 0.0, 0.0
        # Normalize to exactly 100% to avoid floating-point drift across cycles.
        return (
            max(naoh_pct, 0.0) * 100.0 / total_pct,
            max(na2co3_pct, 0.0) * 100.0 / total_pct,
            max(nahco3_pct, 0.0) * 100.0 / total_pct,
        )

    def _resolve_cycle_timeline_sodium_speciation_series(
        self,
        timeline_rows: Sequence[Mapping[str, Any]],
        *,
        workflow_key: Optional[str] = None,
    ) -> Dict[str, Any]:
        """Resolve per-cycle sodium-speciation percentages for timeline top panel.

        Purpose:
            Produce `% NaOH`, `% Na2CO3`, and `% NaHCO3` arrays for the cycle
            timeline top panel in display and export renderers.
        Why:
            The top panel should communicate sodium-speciation progression per
            cycle, using measured-pH corrected uptake in Analysis mode when
            available, then falling back to simulation-ledger state.
        Inputs:
            timeline_rows: Cycle timeline entries used by display/export plots.
            workflow_key: Optional workflow override for source precedence.
        Outputs:
            Dict[str, Any]: Sodium percentage arrays and source metadata.
        Side Effects:
            None.
        Exceptions:
            Invalid/missing values are normalized to safe zeroed percentages.
        """
        rows: List[Dict[str, Any]] = [
            dict(entry or {}) for entry in (timeline_rows or []) if isinstance(entry, Mapping)
        ]
        workflow = str(workflow_key or self._current_solubility_workflow() or "")
        ledger_total_candidates: List[float] = []
        for row in rows:
            row_naoh = _safe_float(row.get("ledger_naoh_remaining_mol"))
            row_na2co3 = _safe_float(row.get("ledger_na2co3_mol"))
            row_nahco3 = _safe_float(row.get("ledger_nahco3_mol"))
            if row_naoh is None and row_na2co3 is None and row_nahco3 is None:
                continue
            total_na = (
                max(float(row_naoh or 0.0), 0.0)
                + (2.0 * max(float(row_na2co3 or 0.0), 0.0))
                + max(float(row_nahco3 or 0.0), 0.0)
            )
            if math.isfinite(total_na) and total_na > 0.0:
                ledger_total_candidates.append(float(total_na))
        total_sodium_mol = max(ledger_total_candidates) if ledger_total_candidates else None
        analysis_mode = workflow == "Analysis"
        corrected_anchor_available = False
        if (
            analysis_mode
            and total_sodium_mol is not None
            and math.isfinite(float(total_sodium_mol))
            and float(total_sodium_mol) > 0.0
        ):
            for row in rows:
                corrected_cumulative_mol = _safe_float(row.get("corrected_cumulative_co2_mol"))
                if corrected_cumulative_mol is None:
                    corrected_cumulative_g = _safe_float(
                        row.get("corrected_cumulative_co2_g")
                    )
                    if corrected_cumulative_g is not None:
                        corrected_cumulative_mol = corrected_cumulative_g / SOL_MW_CO2
                if (
                    corrected_cumulative_mol is not None
                    and math.isfinite(float(corrected_cumulative_mol))
                ):
                    corrected_anchor_available = True
                    break
            if not corrected_anchor_available:
                for row in rows:
                    corrected_cycle_mol = _safe_float(row.get("corrected_cycle_co2_mol"))
                    if corrected_cycle_mol is None:
                        corrected_cycle_g = _safe_float(row.get("corrected_cycle_co2_g"))
                        if corrected_cycle_g is not None:
                            corrected_cycle_mol = corrected_cycle_g / SOL_MW_CO2
                    if corrected_cycle_mol is not None and math.isfinite(float(corrected_cycle_mol)):
                        corrected_anchor_available = True
                        break
        naoh_series: List[float] = []
        na2co3_series: List[float] = []
        nahco3_series: List[float] = []
        source_series: List[str] = []
        running_corrected_cumulative_mol = 0.0
        running_corrected_active = False
        for row in rows:
            row_naoh = _safe_float(row.get("ledger_naoh_remaining_mol"))
            row_na2co3 = _safe_float(row.get("ledger_na2co3_mol"))
            row_nahco3 = _safe_float(row.get("ledger_nahco3_mol"))
            ledger_naoh_pct: Optional[float] = None
            ledger_na2co3_pct: Optional[float] = None
            ledger_nahco3_pct: Optional[float] = None
            if row_naoh is not None or row_na2co3 is not None or row_nahco3 is not None:
                ledger_total_na = (
                    max(float(row_naoh or 0.0), 0.0)
                    + (2.0 * max(float(row_na2co3 or 0.0), 0.0))
                    + max(float(row_nahco3 or 0.0), 0.0)
                )
                if ledger_total_na > 0.0 and math.isfinite(ledger_total_na):
                    ledger_naoh_pct = max(float(row_naoh or 0.0), 0.0) / ledger_total_na * 100.0
                    ledger_na2co3_pct = (
                        2.0 * max(float(row_na2co3 or 0.0), 0.0) / ledger_total_na * 100.0
                    )
                    ledger_nahco3_pct = (
                        max(float(row_nahco3 or 0.0), 0.0) / ledger_total_na * 100.0
                    )
            resolved_naoh_pct = ledger_naoh_pct
            resolved_na2co3_pct = ledger_na2co3_pct
            resolved_nahco3_pct = ledger_nahco3_pct
            source_token = "simulation_ledger"
            if corrected_anchor_available and analysis_mode:
                corrected_cumulative_mol = _safe_float(row.get("corrected_cumulative_co2_mol"))
                if corrected_cumulative_mol is None:
                    corrected_cumulative_g = _safe_float(
                        row.get("corrected_cumulative_co2_g")
                    )
                    if corrected_cumulative_g is not None:
                        corrected_cumulative_mol = corrected_cumulative_g / SOL_MW_CO2
                if (
                    corrected_cumulative_mol is None
                    and running_corrected_active
                ):
                    corrected_cumulative_mol = running_corrected_cumulative_mol
                if corrected_cumulative_mol is None:
                    corrected_cycle_mol = _safe_float(row.get("corrected_cycle_co2_mol"))
                    if corrected_cycle_mol is None:
                        corrected_cycle_g = _safe_float(row.get("corrected_cycle_co2_g"))
                        if corrected_cycle_g is not None:
                            corrected_cycle_mol = corrected_cycle_g / SOL_MW_CO2
                    if corrected_cycle_mol is not None and math.isfinite(float(corrected_cycle_mol)):
                        running_corrected_cumulative_mol += max(float(corrected_cycle_mol), 0.0)
                        corrected_cumulative_mol = running_corrected_cumulative_mol
                        running_corrected_active = True
                elif math.isfinite(float(corrected_cumulative_mol)):
                    running_corrected_cumulative_mol = max(float(corrected_cumulative_mol), 0.0)
                    running_corrected_active = True
                corrected_pct = UnifiedApp._cycle_timeline_sodium_pct_from_corrected_co2(
                    self,
                    corrected_cumulative_mol,
                    total_sodium_mol,
                )
                if all(value is not None for value in corrected_pct):
                    resolved_naoh_pct = float(corrected_pct[0])
                    resolved_na2co3_pct = float(corrected_pct[1])
                    resolved_nahco3_pct = float(corrected_pct[2])
                    source_token = "corrected_anchor"
            if (
                resolved_naoh_pct is None
                or resolved_na2co3_pct is None
                or resolved_nahco3_pct is None
            ):
                if total_sodium_mol is not None and float(total_sodium_mol) > 0.0:
                    resolved_naoh_pct = 100.0
                    resolved_na2co3_pct = 0.0
                    resolved_nahco3_pct = 0.0
                    source_token = "default_naoh"
                else:
                    resolved_naoh_pct = 0.0
                    resolved_na2co3_pct = 0.0
                    resolved_nahco3_pct = 0.0
                    source_token = "unavailable"
            total_pct = (
                max(float(resolved_naoh_pct), 0.0)
                + max(float(resolved_na2co3_pct), 0.0)
                + max(float(resolved_nahco3_pct), 0.0)
            )
            if total_pct > 0.0 and math.isfinite(total_pct):
                resolved_naoh_pct = max(float(resolved_naoh_pct), 0.0) * 100.0 / total_pct
                resolved_na2co3_pct = max(float(resolved_na2co3_pct), 0.0) * 100.0 / total_pct
                resolved_nahco3_pct = max(float(resolved_nahco3_pct), 0.0) * 100.0 / total_pct
            else:
                resolved_naoh_pct = 0.0
                resolved_na2co3_pct = 0.0
                resolved_nahco3_pct = 0.0
            naoh_series.append(float(resolved_naoh_pct))
            na2co3_series.append(float(resolved_na2co3_pct))
            nahco3_series.append(float(resolved_nahco3_pct))
            source_series.append(source_token)
        source_mode = "simulation_ledger"
        if any(token == "corrected_anchor" for token in source_series):
            source_mode = "corrected_anchor"
        elif any(token == "default_naoh" for token in source_series):
            source_mode = "default_naoh"
        elif any(token == "unavailable" for token in source_series):
            source_mode = "unavailable"
        return {
            "naoh_pct": naoh_series,
            "na2co3_pct": na2co3_series,
            "nahco3_pct": nahco3_series,
            "source_mode": source_mode,
            "source_by_cycle": source_series,
            "total_sodium_mol": total_sodium_mol,
        }

    def _mark_cycle_timeline_main_legend(self, legend: Any, role: str = "top") -> Any:
        """Tag one timeline legend as canonical for its subplot role.

        Purpose:
            Normalize timeline legend metadata for top/bottom sync discovery.
        Why:
            Timeline figures can contain multiple legends that must be captured
            independently across display/preview/export flows.
        Inputs:
            legend: Candidate Matplotlib legend artist.
            role: Legend role (`top` or `bottom`).
        Outputs:
            Any: Tagged legend reference, or None when input is missing.
        Side Effects:
            Mutates legend metadata attributes used by legend sync helpers.
        Exceptions:
            Best-effort; metadata write failures are ignored.
        """
        return UnifiedApp._mark_cycle_timeline_subplot_legend(self, legend, role)

    def _planning_timeline_legend_loc(
        self,
        role: str = "top",
    ) -> Optional[Any]:
        """Return current cycle timeline legend location for one subplot role.

        Purpose:
            Reuse user-dragged timeline legend placement in export figures.
        Why:
            Timeline exports should reflect display/preview legend placement for
            both top and bottom subplot legends.
        Inputs:
            role: Legend role (`top` or `bottom`).
        Outputs:
            Optional legend location override for the requested role. Wide bottom
            legends may return a `{"loc", "bbox_to_anchor"}` mapping.
        Side Effects:
            None.
        Exceptions:
            Best-effort guards return None when lookup fails.
        """
        normalized_role = "bottom" if str(role or "").strip().lower() == "bottom" else "top"
        overrides = getattr(self, "_cycle_timeline_legend_loc_overrides", None)
        override_raw = None
        if isinstance(overrides, Mapping):
            override_raw = overrides.get(normalized_role)
        if normalized_role == "top" and override_raw is None:
            override_raw = getattr(self, "_cycle_timeline_legend_loc_override", None)
        override_position = _normalize_cycle_timeline_legend_position(override_raw)
        if override_position is not None:
            override_bbox = _normalize_legend_bbox_anchor_value(
                override_position.get("bbox_to_anchor")
            )
            if override_bbox is not None:
                return {
                    "loc": override_position.get("loc"),
                    "bbox_to_anchor": override_bbox,
                }
            return override_position.get("loc")
        legend_attr = (
            "_planning_timeline_bottom_legend"
            if normalized_role == "bottom"
            else "_planning_timeline_legend"
        )
        legend = getattr(self, legend_attr, None)
        if legend is None:
            return None
        try:
            resolved = legend.get_loc()
        except Exception:
            resolved = getattr(legend, "_loc", None)
        resolved_loc = _normalize_cycle_timeline_legend_loc_value(resolved)
        if bool(getattr(legend, "_cycle_timeline_bottom_wide_under_xaxis", False)):
            bbox_value = UnifiedApp._cycle_timeline_legend_bbox_axes(
                self,
                legend,
                host_axis=getattr(legend, "axes", None),
            )
            if bbox_value is not None:
                return {"loc": resolved_loc, "bbox_to_anchor": bbox_value}
        return resolved_loc

    def _cycle_timeline_legend_bbox_axes(
        self,
        legend: Any,
        *,
        host_axis: Any,
    ) -> Optional[Union[Tuple[float, float], Tuple[float, float, float, float]]]:
        """Resolve one legend bbox anchor in host-axis coordinates.

        Purpose:
            Capture draggable legend bbox placement in normalized axis space.
        Why:
            Bbox drag mode (wide bottom legend) requires persisted bbox semantics.
        Inputs:
            legend: Legend artist to inspect.
            host_axis: Axis used as the anchor transform space.
        Outputs:
            Optional `(x, y)` or `(x, y, w, h)` tuple in host-axis coordinates.
        Side Effects:
            None.
        Exceptions:
            Returns None when bbox extraction fails.
        """
        if legend is None or host_axis is None:
            return None
        try:
            bbox_value = legend.get_bbox_to_anchor()
        except Exception:
            bbox_value = None
        if bbox_value is None:
            return None
        try:
            bbox_axes = bbox_value.transformed(host_axis.transAxes.inverted())
            bounds = tuple(float(item) for item in bbox_axes.bounds)
        except Exception:
            return None
        if len(bounds) < 4 or not all(math.isfinite(item) for item in bounds[:4]):
            return None
        x0, y0, width, height = bounds[:4]
        if abs(width) <= 1e-9 and abs(height) <= 1e-9:
            return (x0, y0)
        return (x0, y0, width, height)

    def _get_cycle_timeline_main_legend(
        self, fig: Optional[Figure], role: str = "top"
    ) -> Any:
        """Return one canonical cycle timeline legend for the requested role.

        Purpose:
            Resolve one authoritative timeline legend from mixed legend sets.
        Why:
            Timeline figures include top/bottom legends that must sync
            independently across preview close and export paths.
        Inputs:
            fig: Figure that may contain timeline legends.
            role: Requested legend role (`top` or `bottom`).
        Outputs:
            Any: Canonical timeline legend for the requested role, or None.
        Side Effects:
            None.
        Exceptions:
            Best-effort guards return None on discovery failures.
        """
        if fig is None:
            return None
        normalized_role = "bottom" if str(role or "").strip().lower() == "bottom" else "top"
        try:
            legends = _collect_gl260_legends(fig)
        except Exception:
            legends = []
        if not legends:
            return None
        # Prefer explicit role tags when available.
        for legend in legends:
            if str(getattr(legend, "_cycle_timeline_legend_role", "")).strip().lower() == normalized_role:
                return legend
        # Backward-compatible fallback for legacy single-legend metadata.
        for legend in legends:
            if bool(getattr(legend, "_cycle_timeline_main_legend", False)):
                return legend
        ranked: List[Tuple[int, Any]] = []
        for legend in legends:
            score = 0
            role_value = _gl260_legend_role(legend)
            if role_value == "main":
                score += 10
            legend_role = str(getattr(legend, "_cycle_timeline_legend_role", "")).strip().lower()
            if legend_role == normalized_role:
                score += 35
            axis = getattr(legend, "axes", None)
            axis_ylabel = ""
            axis_title = ""
            if axis is not None:
                try:
                    axis_ylabel = str(axis.get_ylabel() or "").strip().lower()
                except Exception:
                    axis_ylabel = ""
                try:
                    axis_title = str(axis.get_title() or "").strip().lower()
                except Exception:
                    axis_title = ""
            if normalized_role == "top":
                if "carbon species" in axis_ylabel or "sodium species" in axis_ylabel:
                    score += 20
            else:
                if "actual vs planning ph" in axis_ylabel:
                    score += 20
                if "cycle co$_2$ uptake" in axis_ylabel:
                    score += 15
            if "pressure context" in axis_title:
                score -= 15
            try:
                label_values = [
                    str(text.get_text() or "").strip().lower()
                    for text in (legend.get_texts() or [])
                ]
            except Exception:
                label_values = []
            if any(
                label
                in {
                    "h2co3",
                    "hco3-",
                    "co3^2-",
                    "naoh (%)",
                    "na2co3 (%)",
                    "nahco3 (%)",
                    "naoh",
                    "na2co3",
                    "nahco3",
                    "actual / predicted ph",
                }
                for label in label_values
            ):
                score += 5
            if normalized_role == "top":
                if any(
                    label in {"naoh (%)", "na2co3 (%)", "nahco3 (%)", "h2co3", "hco3-", "co3^2-"}
                    for label in label_values
                ):
                    score += 12
            else:
                if any(
                    label
                    in {
                        "actual / predicted ph",
                        "corrected ph",
                        "measured ph anchor",
                        "planning (cycle aligned)",
                        "planning (co2 aligned)",
                        "actual cycle co2 (g)",
                        "corrected cycle co2 (g)",
                        "planning cycle co2 (g)",
                    }
                    for label in label_values
                ):
                    score += 12
            if score > 0:
                ranked.append((score, legend))
        if ranked:
            ranked.sort(key=lambda item: item[0], reverse=True)
            return ranked[0][1]
        return legends[0]

    def _capture_cycle_timeline_legend_loc_from_fig(
        self,
        fig: Optional[Figure],
        *,
        source: str = "auto",
        role: str = "top",
    ) -> Optional[Any]:
        """Capture one timeline subplot-legend location from one figure.

        Purpose:
            Persist runtime legend location for timeline preview/display parity.
        Why:
            Timeline preview closes should propagate user-dragged top/bottom
            legend positions to display and subsequent exports in-session.
        Inputs:
            fig: Figure to inspect for the requested timeline legend.
            source: Capture context label ("auto"/"sync"/"drag"/etc.) for debug.
            role: Legend role (`top` or `bottom`).
        Outputs:
            Optional normalized legend location payload for downstream reuse.
        Side Effects:
            Updates in-memory legend-location override for requested role.
        Exceptions:
            Best-effort guards return None when capture fails.
        """
        _ = source
        normalized_role = "bottom" if str(role or "").strip().lower() == "bottom" else "top"
        legend_resolver = getattr(self, "_get_cycle_timeline_main_legend", None)
        if callable(legend_resolver):
            try:
                legend = legend_resolver(fig, role=normalized_role)
            except TypeError:
                legend = legend_resolver(fig)
        else:
            legend = UnifiedApp._get_cycle_timeline_main_legend(
                self, fig, role=normalized_role
            )
        if legend is None:
            return None
        try:
            loc_value = legend.get_loc()
        except Exception:
            loc_value = getattr(legend, "_loc", None)
        position = _normalize_cycle_timeline_legend_position({"loc": loc_value})
        if position is None:
            return None
        if bool(getattr(legend, "_cycle_timeline_bottom_wide_under_xaxis", False)):
            bbox_value = UnifiedApp._cycle_timeline_legend_bbox_axes(
                self,
                legend,
                host_axis=getattr(legend, "axes", None),
            )
            if bbox_value is not None:
                position["bbox_to_anchor"] = bbox_value
        stored_value: Any
        if _normalize_legend_bbox_anchor_value(position.get("bbox_to_anchor")) is not None:
            stored_value = {
                "loc": position.get("loc"),
                "bbox_to_anchor": position.get("bbox_to_anchor"),
            }
        else:
            stored_value = position.get("loc")
        if stored_value is None:
            return None
        overrides = getattr(self, "_cycle_timeline_legend_loc_overrides", None)
        if not isinstance(overrides, dict):
            overrides = {"top": None, "bottom": None}
            self._cycle_timeline_legend_loc_overrides = overrides
        overrides[normalized_role] = stored_value
        if normalized_role == "top":
            self._cycle_timeline_legend_loc_override = (
                _normalize_cycle_timeline_legend_loc_value(position.get("loc"))
            )
        return stored_value

    def _capture_cycle_timeline_legend_locs_from_fig(
        self, fig: Optional[Figure], *, source: str = "auto"
    ) -> Dict[str, Optional[Any]]:
        """Capture top and bottom timeline legend locations from one figure.

        Purpose:
            Collect both subplot legend locations during preview-close sync.
        Why:
            Timeline preview now supports independent draggable legends per subplot.
        Inputs:
            fig: Timeline figure to inspect.
            source: Capture context label for debug/trace parity.
        Outputs:
            Dict[str, Optional[...]]: Captured locations keyed by `top`/`bottom`.
        Side Effects:
            Updates role-specific in-memory legend location overrides.
        Exceptions:
            Missing legends return `None` per role.
        """
        return {
            "top": self._capture_cycle_timeline_legend_loc_from_fig(
                fig, source=source, role="top"
            ),
            "bottom": self._capture_cycle_timeline_legend_loc_from_fig(
                fig, source=source, role="bottom"
            ),
        }

    def _apply_cycle_timeline_legend_loc_to_display(
        self,
        loc: Optional[Any],
        *,
        role: str = "top",
    ) -> None:
        """Apply one captured timeline legend location onto the display figure.

        Purpose:
            Keep display timeline legend position synchronized after preview close.
        Why:
            Timeline users expect preview drag placement to become the live display
            placement immediately after closing preview for each subplot legend.
        Inputs:
            loc: Captured legend location payload to apply.
            role: Legend role (`top` or `bottom`).
        Outputs:
            None.
        Side Effects:
            Updates role-specific legend override, refreshes display legend
            placement, and schedules one display-canvas redraw.
        Exceptions:
            Best-effort guards suppress legend rebuild/apply failures.
        """
        position = _normalize_cycle_timeline_legend_position(loc)
        if position is None:
            return
        normalized_loc = _normalize_cycle_timeline_legend_loc_value(
            position.get("loc")
        )
        bbox_override = _normalize_legend_bbox_anchor_value(
            position.get("bbox_to_anchor")
        )
        normalized_role = "bottom" if str(role or "").strip().lower() == "bottom" else "top"
        overrides = getattr(self, "_cycle_timeline_legend_loc_overrides", None)
        if not isinstance(overrides, dict):
            overrides = {"top": None, "bottom": None}
            self._cycle_timeline_legend_loc_overrides = overrides
        if bbox_override is not None:
            overrides[normalized_role] = {
                "loc": normalized_loc,
                "bbox_to_anchor": bbox_override,
            }
        else:
            overrides[normalized_role] = normalized_loc
        if normalized_role == "top":
            self._cycle_timeline_legend_loc_override = normalized_loc
        prefs = self._get_cycle_plot_prefs()
        wide_bottom_mode = bool(
            normalized_role == "bottom"
            and prefs.get("export_bottom_legend_wide_under_xaxis", False)
        )
        centered_bottom_mode = bool(
            normalized_role == "bottom"
            and prefs.get("bottom_legend_center_below_xlabel", False)
        )
        if centered_bottom_mode:
            wide_bottom_mode = False
        if not bool(prefs.get("show_main_legend", True)):
            return
        ax = getattr(self, "_sol_cycle_spec_ax", None)
        ax2 = getattr(self, "_sol_cycle_spec_ax2", None)
        ax3 = getattr(self, "_sol_cycle_spec_ax3", None)
        canvas = getattr(self, "_sol_cycle_spec_canvas", None)
        if ax is None or ax2 is None or ax3 is None or canvas is None:
            return
        role_entry_builder = getattr(self, "_cycle_timeline_legend_entries_for_role", None)
        if callable(role_entry_builder):
            handles, labels, host_axis = role_entry_builder(
                ax=ax,
                ax2=ax2,
                ax3=ax3,
                role=normalized_role,
            )
        else:
            legacy_handles, legacy_labels = self._collect_planning_timeline_legend_entries(
                (ax, ax2, ax3)
            )
            handles, labels, host_axis = legacy_handles, legacy_labels, ax
        if not handles:
            return
        legend_attr = (
            "_planning_timeline_bottom_legend"
            if normalized_role == "bottom"
            else "_planning_timeline_legend"
        )
        legend = self._refresh_planning_timeline_legend(
            getattr(self, legend_attr, None),
            handles,
            labels,
            host_axis,
            legend_loc=(
                {"loc": normalized_loc, "bbox_to_anchor": bbox_override}
                if bbox_override is not None
                else normalized_loc
            ),
            role=normalized_role,
            wide_under_xaxis=wide_bottom_mode,
            center_below_xlabel=centered_bottom_mode,
        )
        ensure_legend_on_canvas = getattr(
            self, "_ensure_cycle_timeline_legend_on_canvas", None
        )
        if callable(ensure_legend_on_canvas):
            legend = ensure_legend_on_canvas(
                fig=host_axis.figure if host_axis is not None else None,
                host_axis=host_axis,
                handles=handles,
                labels=labels,
                legend=legend,
                preferred_loc=(
                    {"loc": normalized_loc, "bbox_to_anchor": bbox_override}
                    if bbox_override is not None
                    else normalized_loc
                ),
                role=normalized_role,
                wide_under_xaxis=wide_bottom_mode,
                center_below_xlabel=centered_bottom_mode,
            )
        legend = UnifiedApp._mark_cycle_timeline_main_legend(
            self, legend, role=normalized_role
        )
        if legend is None:
            return
        if wide_bottom_mode:
            reserve_margin = getattr(
                self, "_reserve_cycle_timeline_bottom_wide_legend_margin", None
            )
            if callable(reserve_margin):
                reserve_margin(
                    fig=host_axis.figure if host_axis is not None else None,
                    host_axis=host_axis,
                    legend=legend,
                )
        setattr(self, legend_attr, legend)
        _make_legend_draggable(
            legend,
            enabled=not centered_bottom_mode,
            update_mode=("bbox" if wide_bottom_mode else "loc"),
        )
        try:
            canvas.draw_idle()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _apply_cycle_timeline_legend_locs_to_display(
        self,
        locations: Mapping[str, Optional[Any]],
    ) -> None:
        """Apply captured top/bottom timeline legend locations to display axes.

        Purpose:
            Synchronize both subplot legend locations after preview close.
        Why:
            Top and bottom timeline legends are draggable and persisted separately.
        Inputs:
            locations: Mapping with optional `top`/`bottom` legend locations.
        Outputs:
            None.
        Side Effects:
            Updates role-specific legend overrides and display legend artists.
        Exceptions:
            Missing/invalid entries are ignored.
        """
        if not isinstance(locations, Mapping):
            return
        for role_key in ("top", "bottom"):
            self._apply_cycle_timeline_legend_loc_to_display(
                locations.get(role_key),
                role=role_key,
            )

    def _refresh_planning_timeline_legend(
        self,
        legend: Any,
        handles: Sequence[Any],
        labels: Sequence[str],
        host_axis: Any,
        *,
        legend_loc: Optional[Any] = None,
        role: str = "top",
        outside_right: bool = False,
        wide_under_xaxis: bool = False,
        center_below_xlabel: bool = False,
    ) -> Any:
        """Refresh one cycle timeline subplot legend in place.

        Purpose:
            Update timeline legend entries while preserving valid drag state.
        Why:
            Timeline refreshes can carry stale/cross-figure legend handles after
            preview/export rebuilds; stale handles must be recreated safely.
        Inputs:
            legend (Any): Existing legend instance to update.
            handles (Sequence[Any]): Legend handles to display.
            labels (Sequence[str]): Legend labels to display.
            host_axis (Any): Axis hosting the legend.
            legend_loc: Optional preferred legend location for rebuild/update.
                Accepts loc-only values or `{"loc", "bbox_to_anchor"}` payloads.
            role: Legend role (`top` or `bottom`).
            outside_right: True to place legend outside-right of subplot.
            wide_under_xaxis: True to render the bottom legend as a wide,
                multi-column bar below the x-axis.
            center_below_xlabel: True to center the bottom legend below the
                x-axis label and keep it fixed instead of draggable.
        Outputs:
            Any: Active legend object when successful, else None.
        Side Effects:
            - Reattaches the legend to the host axis.
            - Rebuilds the legend when stale/cross-figure state is detected.
        Exceptions:
            - Best-effort; ignores legend update failures.
        """
        if host_axis is None:
            return None
        position = _normalize_cycle_timeline_legend_position(legend_loc)
        normalized_loc = _normalize_cycle_timeline_legend_loc_value(
            position.get("loc") if isinstance(position, Mapping) else legend_loc
        )
        bbox_override = _normalize_legend_bbox_anchor_value(
            position.get("bbox_to_anchor") if isinstance(position, Mapping) else None
        )
        host_fig = getattr(host_axis, "figure", None)
        normalized_role = "bottom" if str(role or "").strip().lower() == "bottom" else "top"
        wide_bottom_mode = bool(
            wide_under_xaxis and normalized_role == "bottom" and not outside_right
        )
        centered_bottom_mode = bool(
            center_below_xlabel and normalized_role == "bottom" and not outside_right
        )
        if centered_bottom_mode:
            wide_bottom_mode = False
        wide_ncol = None
        centered_ncol = None
        centered_bottom_bbox = (0.5, -0.46)
        wide_bottom_bbox = (
            _normalize_legend_bbox_anchor_value(bbox_override)
            if wide_bottom_mode
            else None
        )
        if wide_bottom_bbox is None:
            wide_bottom_bbox = (0.0, -0.22, 1.0, 0.2)
        entry_count = max(1, len(labels))
        default_ncol: Optional[int] = None
        if wide_bottom_mode:
            target_rows = 1 if entry_count <= 4 else 2 if entry_count <= 10 else 3
            default_ncol = max(1, int(math.ceil(entry_count / float(target_rows))))
        elif centered_bottom_mode:
            default_ncol = max(1, min(entry_count, 4))
        legend_labels, resolved_ncol, _legend_wrap, _legend_rows = (
            UnifiedApp._cycle_timeline_legend_layout_for_role(
                self,
                labels,
                role=normalized_role,
                default_ncol=default_ncol,
            )
        )
        if wide_bottom_mode:
            wide_ncol = resolved_ncol
        if centered_bottom_mode:
            centered_ncol = resolved_ncol
        legend_stale = False
        if legend is not None:
            legend_fig = getattr(legend, "figure", None)
            if host_fig is not None and legend_fig is not None and legend_fig is not host_fig:
                legend_stale = True
            legend_axes = getattr(legend, "axes", None)
            if (
                host_fig is not None
                and legend_axes is not None
                and legend_axes not in list(getattr(host_fig, "axes", []) or [])
            ):
                legend_stale = True
        if legend_stale:
            try:
                legend.remove()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            legend = None
        if legend is not None:
            prior_layout = (
                bool(getattr(legend, "_cycle_timeline_legend_wrap", False)),
                getattr(legend, "_cycle_timeline_legend_ncol", None),
                getattr(legend, "_cycle_timeline_legend_rows", None),
            )
            next_layout = (bool(_legend_wrap), resolved_ncol, _legend_rows)
            if prior_layout != next_layout:
                try:
                    legend.remove()
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
                legend = None
        if wide_bottom_mode and legend is not None:
            # Wide mode depends on ncol/mode kwargs; force rebuild so those
            # structural legend options remain deterministic across refreshes.
            try:
                legend.remove()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            legend = None
        if centered_bottom_mode and legend is not None:
            # Centered mode depends on fixed bbox/ncol kwargs; force rebuild so
            # stale draggable/wide legend structure is not retained.
            try:
                legend.remove()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            legend = None
        if legend is None:
            try:
                loc_to_use = (
                    normalized_loc
                    if normalized_loc is not None
                    else UnifiedApp._cycle_timeline_legend_default_loc_for_role(
                        self, normalized_role
                    )
                )
                legend_kwargs = {}
                if outside_right:
                    if resolved_ncol is not None:
                        legend_kwargs["ncol"] = resolved_ncol
                    legend_kwargs.update(
                        {
                            "loc": "upper left",
                            "bbox_to_anchor": (1.02, 1.0),
                            "borderaxespad": 0.0,
                        }
                    )
                elif wide_bottom_mode:
                    legend_kwargs.update(
                        {
                            "loc": "upper left",
                            "bbox_to_anchor": wide_bottom_bbox,
                            "borderaxespad": 0.0,
                            "mode": "expand",
                            "ncol": max(1, int(wide_ncol or 1)),
                            "columnspacing": 1.1,
                            "labelspacing": 0.55,
                            "handletextpad": 0.6,
                        }
                    )
                elif centered_bottom_mode:
                    legend_kwargs.update(
                        {
                            "loc": "upper center",
                            "bbox_to_anchor": centered_bottom_bbox,
                            "borderaxespad": 0.0,
                            "ncol": max(1, int(centered_ncol or 1)),
                            "columnspacing": 1.1,
                            "labelspacing": 0.55,
                            "handletextpad": 0.6,
                        }
                    )
                elif bbox_override is not None:
                    legend_kwargs.update(
                        {
                            "loc": loc_to_use if loc_to_use is not None else "upper left",
                            "bbox_to_anchor": bbox_override,
                            "borderaxespad": 0.0,
                        }
                    )
                else:
                    legend_kwargs["loc"] = loc_to_use
                    if resolved_ncol is not None:
                        legend_kwargs["ncol"] = resolved_ncol
                legend = host_axis.legend(
                    handles=list(handles),
                    labels=list(legend_labels),
                    fontsize=8,
                    **legend_kwargs,
                    **_legend_shadowbox_kwargs(),
                )
            except Exception:
                return None
            legend = UnifiedApp._mark_cycle_timeline_main_legend(
                self, legend, role=normalized_role
            )
            try:
                legend._cycle_timeline_bottom_wide_under_xaxis = bool(wide_bottom_mode)
                legend._cycle_timeline_bottom_center_below_xlabel = bool(
                    centered_bottom_mode
                )
                legend._cycle_timeline_bottom_wide_ncol = wide_ncol
                legend._cycle_timeline_bottom_center_ncol = centered_ncol
                legend._cycle_timeline_legend_wrap = bool(_legend_wrap)
                legend._cycle_timeline_legend_rows = int(_legend_rows)
                legend._cycle_timeline_legend_ncol = resolved_ncol
                legend._cycle_timeline_bbox_to_anchor_axes = (
                    centered_bottom_bbox
                    if centered_bottom_mode
                    else wide_bottom_bbox if wide_bottom_mode else bbox_override
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            if centered_bottom_mode:
                UnifiedApp._position_cycle_timeline_centered_bottom_legend(
                    self,
                    fig=host_fig,
                    host_axis=host_axis,
                    legend=legend,
                )
            return legend
        try:
            host_axis.add_artist(legend)
            host_axis.legend_ = legend
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        if outside_right:
            try:
                legend.set_loc("upper left")
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                legend.set_bbox_to_anchor((1.02, 1.0), transform=host_axis.transAxes)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        elif wide_bottom_mode:
            try:
                legend.set_loc("upper left")
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                legend.set_bbox_to_anchor(wide_bottom_bbox, transform=host_axis.transAxes)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        elif centered_bottom_mode:
            try:
                legend.set_loc("upper center")
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                legend.set_bbox_to_anchor(
                    centered_bottom_bbox, transform=host_axis.transAxes
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        elif bbox_override is not None:
            if normalized_loc is not None:
                try:
                    legend.set_loc(normalized_loc)
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
            try:
                legend.set_bbox_to_anchor(bbox_override, transform=host_axis.transAxes)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        elif normalized_loc is not None:
            try:
                legend.set_loc(normalized_loc)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                legend.set_bbox_to_anchor(None)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        try:
            legend.set_visible(True)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            markerfirst = getattr(legend, "_markerfirst", True)
            # Update the legend box in place to preserve drag position.
            legend._init_legend_box(
                list(handles), list(legend_labels), markerfirst=markerfirst
            )
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        legend = UnifiedApp._mark_cycle_timeline_main_legend(
            self, legend, role=normalized_role
        )
        try:
            legend._cycle_timeline_bottom_wide_under_xaxis = bool(wide_bottom_mode)
            legend._cycle_timeline_bottom_center_below_xlabel = bool(
                centered_bottom_mode
            )
            legend._cycle_timeline_bottom_wide_ncol = wide_ncol
            legend._cycle_timeline_bottom_center_ncol = centered_ncol
            legend._cycle_timeline_legend_wrap = bool(_legend_wrap)
            legend._cycle_timeline_legend_rows = int(_legend_rows)
            legend._cycle_timeline_legend_ncol = resolved_ncol
            legend._cycle_timeline_bbox_to_anchor_axes = (
                centered_bottom_bbox
                if centered_bottom_mode
                else wide_bottom_bbox if wide_bottom_mode else bbox_override
            )
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        if centered_bottom_mode:
            UnifiedApp._position_cycle_timeline_centered_bottom_legend(
                self,
                fig=host_fig,
                host_axis=host_axis,
                legend=legend,
            )
        return legend

    def _position_cycle_timeline_centered_bottom_legend(
        self,
        *,
        fig: Optional[Figure],
        host_axis: Any,
        legend: Any,
    ) -> None:
        """Position the fixed bottom timeline legend below the x-axis label.

        Purpose:
            Move the fixed centered bottom legend using measured text/legend
            geometry instead of a hard-coded axis offset.
        Why:
            Different label sizes, wrapping, and legend row counts change the
            required bottom band, so placement must be renderer-driven.
        Inputs:
            fig: Timeline figure containing the legend.
            host_axis: Bottom/twin axis hosting the bottom legend.
            legend: Bottom legend artist to reposition.
        Outputs:
            None.
        Side Effects:
            May increase the figure bottom margin and updates the legend bbox
            anchor in host-axis coordinates.
        Exceptions:
            Measurement failures are ignored safely.
        """
        if fig is None or host_axis is None or legend is None:
            return
        canvas = getattr(fig, "canvas", None)
        if canvas is None:
            try:
                canvas = FigureCanvasAgg(fig)
                fig.set_canvas(canvas)
            except Exception:
                return
        for _pass_index in range(3):
            try:
                canvas.draw()
                renderer = canvas.get_renderer()
                legend_bbox = legend.get_window_extent(renderer=renderer).transformed(
                    fig.transFigure.inverted()
                )
                axis_bbox = host_axis.get_position()
            except Exception:
                return
            try:
                xlabel_artist = _layout_health_primary_xlabel(
                    fig, plot_id="fig_cycle_timeline"
                )
            except Exception:
                xlabel_artist = None
            if xlabel_artist is None:
                try:
                    xlabel_artist = host_axis.xaxis.get_label()
                except Exception:
                    xlabel_artist = None
            xlabel_bbox = _layout_health_bbox_in_fig(fig, xlabel_artist, renderer)
            if xlabel_bbox is None:
                try:
                    xlabel_bbox = host_axis.xaxis.label.get_window_extent(
                        renderer=renderer
                    ).transformed(fig.transFigure.inverted())
                except Exception:
                    xlabel_bbox = None
            fig_h_pts = max(float(fig.get_size_inches()[1]) * 72.0, 1.0)
            min_gap = (
                DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MIN_LEGEND_XLABEL_GAP_PTS
                / fig_h_pts
            )
            label_floor = float(axis_bbox.y0)
            if xlabel_bbox is not None:
                label_floor = min(label_floor, float(xlabel_bbox.y0))
            target_top = label_floor - min_gap
            if axis_bbox.height <= 0.0:
                return
            target_y_axes = (target_top - float(axis_bbox.y0)) / float(axis_bbox.height)
            try:
                legend.set_loc("upper center")
                legend.set_bbox_to_anchor(
                    (0.5, float(target_y_axes)), transform=host_axis.transAxes
                )
                legend._cycle_timeline_bbox_to_anchor_axes = (0.5, float(target_y_axes))
            except Exception:
                return
            try:
                canvas.draw()
                renderer = canvas.get_renderer()
                legend_bbox = legend.get_window_extent(renderer=renderer).transformed(
                    fig.transFigure.inverted()
                )
            except Exception:
                return
            if float(legend_bbox.y0) >= 0.012:
                return
            try:
                current_bottom = float(getattr(fig.subplotpars, "bottom", 0.0))
            except Exception:
                current_bottom = 0.0
            needed = min(0.18, abs(float(legend_bbox.y0)) + 0.03)
            target_bottom = min(0.48, max(current_bottom, 0.12) + needed)
            if target_bottom <= current_bottom + 1e-6:
                return
            try:
                fig.subplots_adjust(bottom=target_bottom)
            except Exception:
                return

    def _reposition_cycle_timeline_centered_bottom_legends(
        self,
        fig: Optional[Figure],
    ) -> bool:
        """Reposition centered bottom timeline legends after layout changes.

        Purpose:
            Re-apply measured centered-bottom placement for any role-tagged bottom
            timeline legend in the figure.
        Why:
            Plot Preview, generated tabs, and layout-health passes can resize or
            re-solve the figure after the legend is first created; centered mode
            must be connected to those final plot surfaces, not only the initial
            export builder.
        Inputs:
            fig: Candidate cycle timeline figure.
        Outputs:
            bool: True when at least one centered bottom legend was adjusted.
        Side Effects:
            May update subplot bottom margin and bottom legend bbox anchor.
        Exceptions:
            Best-effort guards skip malformed figures/legends.
        """
        if fig is None:
            return False
        try:
            legends = _layout_health_timeline_legends(fig)
        except Exception:
            legends = {}
        bottom_legend = legends.get("bottom") if isinstance(legends, Mapping) else None
        if bottom_legend is None:
            return False
        prefs = self._get_cycle_plot_prefs()
        centered = bool(
            prefs.get("bottom_legend_center_below_xlabel", False)
            or getattr(
                bottom_legend, "_cycle_timeline_bottom_center_below_xlabel", False
            )
        )
        if not centered:
            return False
        host_axis = getattr(bottom_legend, "axes", None)
        if host_axis is None:
            return False
        try:
            bottom_legend._cycle_timeline_bottom_center_below_xlabel = True
            bottom_legend._cycle_timeline_bottom_wide_under_xaxis = False
            bottom_legend.set_loc("upper center")
        except Exception:
            # Best-effort guard; continue with measured positioning when possible.
            pass
        self._position_cycle_timeline_centered_bottom_legend(
            fig=fig,
            host_axis=host_axis,
            legend=bottom_legend,
        )
        try:
            _make_legend_draggable(bottom_legend, enabled=False)
        except Exception:
            # Best-effort guard; ignore drag-state update failures.
            pass
        return True

    def _cycle_timeline_legend_is_on_canvas(
        self,
        legend: Any,
        fig: Optional[Figure],
    ) -> bool:
        """Return whether a cycle timeline legend currently intersects the figure.

        Purpose:
            Validate that the timeline main legend remains visible after layout.
        Why:
            Generic layout solves can move timeline legends off-canvas in some
            Analysis preview/export paths.
        Inputs:
            legend: Candidate legend artist.
            fig: Figure owning the legend.
        Outputs:
            bool: True when legend bbox intersects figure bounds.
        Side Effects:
            May trigger one canvas draw for bbox measurement.
        Exceptions:
            Returns False when renderer/bbox resolution fails.
        """
        if legend is None or fig is None:
            return False
        canvas = getattr(fig, "canvas", None)
        if canvas is None:
            try:
                canvas = FigureCanvasAgg(fig)
                fig.set_canvas(canvas)
            except Exception:
                return False
        try:
            canvas.draw()
        except Exception:
            try:
                canvas.draw_idle()
                canvas.draw()
            except Exception:
                return False
        try:
            renderer = canvas.get_renderer()
        except Exception:
            return False
        try:
            bbox = legend.get_window_extent(renderer=renderer)
            bbox_fig = bbox.transformed(fig.transFigure.inverted())
        except Exception:
            return False
        coords = (
            float(bbox_fig.x0),
            float(bbox_fig.y0),
            float(bbox_fig.x1),
            float(bbox_fig.y1),
        )
        if not all(math.isfinite(value) for value in coords):
            return False
        x0, y0, x1, y1 = coords
        if x1 <= x0 or y1 <= y0:
            return False
        return bool(x1 > 0.0 and x0 < 1.0 and y1 > 0.0 and y0 < 1.0)

    def _ensure_cycle_timeline_legend_on_canvas(
        self,
        *,
        fig: Optional[Figure],
        host_axis: Any,
        handles: Sequence[Any],
        labels: Sequence[str],
        legend: Any,
        preferred_loc: Optional[Union[str, int, Tuple[float, float]]] = None,
        role: str = "top",
        wide_under_xaxis: bool = False,
        center_below_xlabel: bool = False,
    ) -> Any:
        """Ensure one timeline subplot legend remains visible/readable.

        Purpose:
            Keep top/bottom timeline legends visible after layout passes.
        Why:
            Layout and drag state can push legends off-canvas or overcrowd data
            regions; this guard recovers to in-axes or outside-right placement.
        Inputs:
            fig: Figure containing the timeline legend.
            host_axis: Axis used to host/rebuild the legend.
            handles: Consolidated legend handles.
            labels: Consolidated legend labels.
            legend: Current legend instance.
            preferred_loc: Preferred legend location to preserve if valid.
            role: Legend role (`top` or `bottom`).
            wide_under_xaxis: True to keep bottom legend in the dedicated
                wide-under-x-axis layout.
            center_below_xlabel: True to keep the bottom legend fixed below the
                x-axis label.
        Outputs:
            Any: Visible on-canvas legend instance, or None when unavailable.
        Side Effects:
            May remove and recreate the legend.
        Exceptions:
            Best-effort guards return the last known legend when rebuild fails.
        """
        if fig is None or host_axis is None:
            return legend
        if not handles:
            return legend
        loc_value = _normalize_cycle_timeline_legend_loc_value(preferred_loc)
        if loc_value is None:
            loc_value = UnifiedApp._cycle_timeline_legend_default_loc_for_role(self, role)
        wide_bottom_mode = bool(
            wide_under_xaxis and str(role or "").strip().lower() == "bottom"
        )
        centered_bottom_mode = bool(
            center_below_xlabel and str(role or "").strip().lower() == "bottom"
        )
        if centered_bottom_mode:
            wide_bottom_mode = False
        if legend is None:
            legend = UnifiedApp._refresh_planning_timeline_legend(
                self,
                legend,
                handles,
                labels,
                host_axis,
                legend_loc=loc_value,
                role=role,
                wide_under_xaxis=wide_bottom_mode,
                center_below_xlabel=centered_bottom_mode,
            )
            if legend is not None and self._cycle_timeline_legend_is_on_canvas(legend, fig):
                return legend
        legend_on_canvas = (
            legend is not None and self._cycle_timeline_legend_is_on_canvas(legend, fig)
        )
        if wide_bottom_mode:
            # Keep the bottom legend in wide mode even when dense layouts would
            # normally trigger outside-right fallback handling.
            reserve_margin = getattr(
                self, "_reserve_cycle_timeline_bottom_wide_legend_margin", None
            )
            if callable(reserve_margin):
                reserve_margin(fig=fig, host_axis=host_axis, legend=legend)
            if legend_on_canvas:
                return legend
            if legend is not None:
                try:
                    legend.remove()
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
            try:
                rebuilt_wide = UnifiedApp._refresh_planning_timeline_legend(
                    self,
                    None,
                    handles,
                    labels,
                    host_axis,
                    legend_loc=loc_value,
                    role=role,
                    wide_under_xaxis=True,
                )
            except Exception:
                rebuilt_wide = None
            if rebuilt_wide is not None:
                if callable(reserve_margin):
                    reserve_margin(fig=fig, host_axis=host_axis, legend=rebuilt_wide)
                return rebuilt_wide
            return legend
        if centered_bottom_mode:
            if legend is not None:
                UnifiedApp._position_cycle_timeline_centered_bottom_legend(
                    self,
                    fig=fig,
                    host_axis=host_axis,
                    legend=legend,
                )
                legend_on_canvas = self._cycle_timeline_legend_is_on_canvas(
                    legend, fig
                )
            if legend_on_canvas:
                return legend
            if legend is not None:
                try:
                    legend.remove()
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
            try:
                rebuilt_center = UnifiedApp._refresh_planning_timeline_legend(
                    self,
                    None,
                    handles,
                    labels,
                    host_axis,
                    legend_loc=loc_value,
                    role=role,
                    center_below_xlabel=True,
                )
            except Exception:
                rebuilt_center = None
            return rebuilt_center if rebuilt_center is not None else legend
        if legend_on_canvas and not UnifiedApp._cycle_timeline_legend_needs_outside_fallback(
            self, legend, fig, host_axis
        ):
            return legend
        if legend is not None:
            try:
                legend.remove()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        try:
            rebuilt = UnifiedApp._refresh_planning_timeline_legend(
                self,
                None,
                handles,
                labels,
                host_axis,
                legend_loc=loc_value,
                role=role,
                wide_under_xaxis=wide_bottom_mode,
                center_below_xlabel=centered_bottom_mode,
            )
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            return legend
        if rebuilt is None:
            return legend
        if self._cycle_timeline_legend_is_on_canvas(rebuilt, fig):
            if not UnifiedApp._cycle_timeline_legend_needs_outside_fallback(
                self, rebuilt, fig, host_axis
            ):
                return rebuilt
        try:
            rebuilt.remove()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            outside_legend = UnifiedApp._refresh_planning_timeline_legend(
                self,
                None,
                handles,
                labels,
                host_axis,
                legend_loc=loc_value,
                role=role,
                outside_right=True,
                wide_under_xaxis=wide_bottom_mode,
                center_below_xlabel=centered_bottom_mode,
            )
        except Exception:
            outside_legend = None
        if outside_legend is not None and self._cycle_timeline_legend_is_on_canvas(
            outside_legend, fig
        ):
            return outside_legend
        try:
            if outside_legend is not None:
                outside_legend.remove()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        safe_loc = UnifiedApp._cycle_timeline_legend_default_loc_for_role(self, role)
        try:
            safe_legend = UnifiedApp._refresh_planning_timeline_legend(
                self,
                None,
                handles,
                labels,
                host_axis,
                legend_loc=safe_loc,
                role=role,
                wide_under_xaxis=wide_bottom_mode,
                center_below_xlabel=centered_bottom_mode,
            )
        except Exception:
            safe_legend = None
        if safe_legend is not None and self._cycle_timeline_legend_is_on_canvas(
            safe_legend, fig
        ):
            return safe_legend
        if safe_legend is not None:
            return safe_legend
        if rebuilt is not None:
            return rebuilt
        return legend

    def _build_cycle_timeline_subplot_legends(
        self,
        *,
        fig: Optional[Figure],
        ax: Any,
        ax2: Any,
        ax3: Any,
        show_main_legend: bool,
        preview_interactive_legend: bool = False,
        update_session_refs: bool = False,
    ) -> Dict[str, Any]:
        """Build or refresh top and bottom timeline legends with shared policy.

        Purpose:
            Centralize legend creation for display/preview/export parity.
        Why:
            Top and bottom subplot legends must share the same fallback, drag, and
            sync behavior across all timeline rendering targets.
        Inputs:
            fig: Figure owning the timeline axes.
            ax: Top sodium-speciation axis.
            ax2: Bottom pH axis.
            ax3: Bottom uptake axis.
            show_main_legend: Whether legends should be visible.
            preview_interactive_legend: Enable drag mode for preview figures.
            update_session_refs: Store legends on app instance for display sync.
        Outputs:
            Dict[str, Any]: Role-keyed legend map (`top`, `bottom`).
        Side Effects:
            May update runtime legend references and register layout artists.
        Exceptions:
            Best-effort guards suppress per-legend failures.
        """
        if fig is None or ax is None or ax2 is None or ax3 is None:
            return {"top": None, "bottom": None}
        role_to_attr = {
            "top": "_planning_timeline_legend",
            "bottom": "_planning_timeline_bottom_legend",
        }
        legends: Dict[str, Any] = {"top": None, "bottom": None}
        ensure_legend_on_canvas = getattr(self, "_ensure_cycle_timeline_legend_on_canvas", None)
        prefs_map = getattr(self, "_cycle_plot_prefs", None)
        if not isinstance(prefs_map, dict):
            # Fall back to the preference accessor for lightweight harnesses that
            # expose timeline prefs without a persisted `_cycle_plot_prefs` cache.
            prefs_reader = getattr(self, "_get_cycle_plot_prefs", None)
            if callable(prefs_reader):
                try:
                    prefs_map = prefs_reader()
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    prefs_map = {}
        if not isinstance(prefs_map, dict):
            prefs_map = {}
        wide_bottom_enabled = bool(
            prefs_map.get("export_bottom_legend_wide_under_xaxis", False)
        )
        center_bottom_enabled = bool(
            prefs_map.get("bottom_legend_center_below_xlabel", False)
        )
        for role_key in ("top", "bottom"):
            wide_bottom_mode = bool(role_key == "bottom" and wide_bottom_enabled)
            centered_bottom_mode = bool(role_key == "bottom" and center_bottom_enabled)
            if centered_bottom_mode:
                wide_bottom_mode = False
            handles, labels, host_axis = UnifiedApp._cycle_timeline_legend_entries_for_role(
                self,
                ax=ax,
                ax2=ax2,
                ax3=ax3,
                role=role_key,
            )
            legend = getattr(self, role_to_attr[role_key], None) if update_session_refs else None
            if not show_main_legend or not handles:
                if legend is not None:
                    try:
                        legend.set_visible(False)
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting the workflow.
                        pass
                legends[role_key] = legend
                if update_session_refs:
                    setattr(self, role_to_attr[role_key], legend)
                continue
            legend_loc_fn = getattr(self, "_planning_timeline_legend_loc", None)
            if callable(legend_loc_fn):
                try:
                    legend_loc = legend_loc_fn(role=role_key)
                except TypeError:
                    legend_loc = legend_loc_fn()
            else:
                legend_loc = None
            if legend_loc is None:
                legend_loc = UnifiedApp._cycle_timeline_legend_default_loc_for_role(
                    self, role_key
                )
            legend = UnifiedApp._refresh_planning_timeline_legend(
                self,
                legend,
                handles,
                labels,
                host_axis,
                legend_loc=legend_loc,
                role=role_key,
                wide_under_xaxis=wide_bottom_mode,
                center_below_xlabel=centered_bottom_mode,
            )
            if callable(ensure_legend_on_canvas):
                legend = ensure_legend_on_canvas(
                    fig=fig,
                    host_axis=host_axis,
                    handles=handles,
                    labels=labels,
                    legend=legend,
                    preferred_loc=legend_loc,
                    role=role_key,
                    wide_under_xaxis=wide_bottom_mode,
                    center_below_xlabel=centered_bottom_mode,
                )
            legend = UnifiedApp._mark_cycle_timeline_main_legend(
                self, legend, role=role_key
            )
            if wide_bottom_mode and legend is not None:
                reserve_margin = getattr(
                    self, "_reserve_cycle_timeline_bottom_wide_legend_margin", None
                )
                if callable(reserve_margin):
                    reserve_margin(fig=fig, host_axis=host_axis, legend=legend)
            if centered_bottom_mode and legend is not None:
                UnifiedApp._position_cycle_timeline_centered_bottom_legend(
                    self,
                    fig=fig,
                    host_axis=host_axis,
                    legend=legend,
                )
            if legend is not None:
                try:
                    legend.set_visible(True)
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
                drag_update_mode = "bbox" if wide_bottom_mode else "loc"
                drag_enabled = not centered_bottom_mode
                _make_legend_draggable(
                    legend, enabled=drag_enabled, update_mode=drag_update_mode
                )
                if preview_interactive_legend:
                    _make_legend_draggable(
                        legend, enabled=drag_enabled, update_mode=drag_update_mode
                    )
                layout_mgr = getattr(fig, "_gl260_layout_manager", None)
                if layout_mgr is not None:
                    fig_plot_id = str(getattr(fig, "_gl260_plot_id", "") or "").strip().lower()
                    if role_key == "bottom":
                        artist_key = "plot_legend_bottom"
                    elif fig_plot_id == "fig_cycle_timeline":
                        # Timeline top legends are axis-local; avoid mapping to the
                        # generic figure-level `plot_legend` channel.
                        artist_key = "plot_legend_top"
                    else:
                        artist_key = "plot_legend"
                    try:
                        layout_mgr.register_artist(artist_key, legend)
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting the workflow.
                        pass
            legends[role_key] = legend
            if update_session_refs:
                setattr(self, role_to_attr[role_key], legend)
        layout_mgr = getattr(fig, "_gl260_layout_manager", None)
        fig_plot_id = str(getattr(fig, "_gl260_plot_id", "") or "").strip().lower()
        if layout_mgr is not None and fig_plot_id == "fig_cycle_timeline":
            try:
                layout_mgr.solve(max_passes=1, allow_draw=False)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        if update_session_refs:
            self._planning_timeline_legend = legends.get("top")
            self._planning_timeline_bottom_legend = legends.get("bottom")
        return legends

    def _ensure_cycle_timeline_annotation_controller(self) -> None:
        """Ensure timeline plot-elements controller is attached to display canvas.

        Purpose:
            Create or retarget the plot-elements controller for the main cycle
            timeline display figure.
        Why:
            Timeline preview and timeline plot-element edits share one persisted
            plot-id store and must stay bound to the latest display canvas.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Applies timeline layout profile/plot elements and binds controller
            callbacks to the timeline display canvas.
        Exceptions:
            Best-effort guards suppress controller/layout failures.
        """
        fig = getattr(self, "_sol_cycle_spec_fig", None)
        canvas = getattr(self, "_sol_cycle_spec_canvas", None)
        if fig is None or canvas is None:
            return
        try:
            self._apply_display_settings_for_plot(fig, "fig_cycle_timeline", canvas)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _resolve_cycle_timeline_view_entries(
        self,
        timeline: Sequence[Mapping[str, Any]],
        *,
        workflow_key: Optional[str] = None,
        reaction_guidance: Optional[Mapping[str, Any]] = None,
    ) -> Tuple[List[Dict[str, Any]], bool]:
        """Resolve view-ready timeline entries, including Reprocessing previews.

        Purpose:
            Build the timeline row sequence used by table/callout/plot renderers.
        Why:
            Reprocessing can render a pass/fail preview even when imported cycles
            are not available; centralized resolution keeps table/plot/callout
            behavior aligned.
        Inputs:
            timeline: Raw timeline row payload sequence.
            workflow_key: Optional workflow override.
            reaction_guidance: Optional guidance payload override.
        Outputs:
            Tuple[List[Dict[str, Any]], bool]: `(timeline_rows, preview_mode)`.
        Side Effects:
            None.
        Exceptions:
            Invalid row shapes are skipped.
        """
        workflow = workflow_key or self._current_solubility_workflow()
        resolved_timeline = [
            dict(entry) for entry in (timeline or []) if isinstance(entry, Mapping)
        ]
        guidance = (
            dict(reaction_guidance)
            if isinstance(reaction_guidance, Mapping)
            else (getattr(self, "_sol_reaction_guidance", {}) or {})
        )
        preview_mode = False
        if workflow == "Reprocessing" and not resolved_timeline:
            reproc = guidance.get("reprocessing_workflow") or {}
            baseline_spec = reproc.get("baseline_spec")
            target_spec = reproc.get("target_spec")
            recommended_co2 = reproc.get("recommended_co2_g")
            target_ph_hint = reproc.get("target_ph")
            fail_ph = reproc.get("failing_ph")

            def _spec_value(spec: Any, key: str, default: Any = None) -> Any:
                """Resolve one scalar value from Mapping/object spec payloads."""
                if spec is None:
                    return default
                if isinstance(spec, Mapping):
                    return spec.get(key, default)
                return getattr(spec, key, default)

            def _spec_fractions(spec: Any) -> Dict[str, float]:
                """Resolve carbonate fractions from Mapping/object spec payloads."""
                if spec is None:
                    return {}
                if isinstance(spec, Mapping):
                    return spec.get("fractional_carbon", {}) or spec.get(
                        "fractions", {}
                    )
                return getattr(spec, "fractional_carbon", {}) or {}

            def _spec_moles(spec: Any) -> Dict[str, float]:
                """Resolve species moles from Mapping/object spec payloads."""
                if spec is None:
                    return {}
                if isinstance(spec, Mapping):
                    return spec.get("moles", {}) or {}
                return getattr(spec, "moles", {}) or {}

            preview_entries: List[Dict[str, Any]] = []
            if baseline_spec is not None:
                base_moles = _spec_moles(baseline_spec)
                preview_entries.append(
                    {
                        "cycle_id": "Fail",
                        "co2_g": 0.0,
                        "co2_mass_g": 0.0,
                        "co2_to_target_g": recommended_co2,
                        "solution_ph": _spec_value(
                            baseline_spec, "ph", default=fail_ph
                        ),
                        "fractions": _spec_fractions(baseline_spec),
                        "solid_na2co3_g": base_moles.get("CO3^2-", 0.0) * SOL_MW_NA2CO3,
                        "solid_nahco3_g": base_moles.get("HCO3-", 0.0) * SOL_MW_NAHCO3,
                    }
                )
            if target_spec is not None:
                target_moles = _spec_moles(target_spec)
                preview_entries.append(
                    {
                        "cycle_id": "Pass",
                        "co2_g": recommended_co2 or 0.0,
                        "co2_mass_g": recommended_co2 or 0.0,
                        "co2_to_target_g": 0.0,
                        "solution_ph": _spec_value(
                            target_spec, "ph", default=target_ph_hint
                        ),
                        "fractions": _spec_fractions(target_spec),
                        "solid_na2co3_g": target_moles.get("CO3^2-", 0.0)
                        * SOL_MW_NA2CO3,
                        "solid_nahco3_g": target_moles.get("HCO3-", 0.0)
                        * SOL_MW_NAHCO3,
                    }
                )
            if preview_entries:
                resolved_timeline = preview_entries
                preview_mode = True
        return resolved_timeline, preview_mode

    def _build_cycle_timeline_render_payload(
        self,
        timeline: Sequence[Mapping[str, Any]],
        *,
        workflow_key: Optional[str] = None,
        reaction_guidance: Optional[Mapping[str, Any]] = None,
        columns: Optional[Sequence[str]] = None,
    ) -> Dict[str, Any]:
        """Build one worker-safe cycle timeline render payload.

        Purpose:
            Prepare table/callout render rows and export cache payload outside the
            Tk event loop.
        Why:
            Large timeline updates can freeze the UI when row/callout formatting
            happens synchronously on the main thread.
        Inputs:
            timeline: Raw timeline rows to normalize/format.
            workflow_key: Optional workflow override.
            reaction_guidance: Optional guidance payload override.
            columns: Optional table column order override.
        Outputs:
            Dict[str, Any]: Render payload containing timeline rows, table rows,
            full export rows/headers, and callout text lines.
        Side Effects:
            None.
        Exceptions:
            Invalid row values are normalized defensively.
        """
        workflow = workflow_key or self._current_solubility_workflow()
        guidance = (
            dict(reaction_guidance)
            if isinstance(reaction_guidance, Mapping)
            else (getattr(self, "_sol_reaction_guidance", {}) or {})
        )
        column_order = (
            tuple(columns)
            if isinstance(columns, Sequence)
            else tuple(getattr(self, "_sol_cycle_timeline_columns", ()))
        )
        resolved_timeline, preview_mode = self._resolve_cycle_timeline_view_entries(
            timeline,
            workflow_key=workflow,
            reaction_guidance=guidance,
        )
        if workflow == "Analysis":
            raw_calculated_series = [
                _safe_float(
                    entry.get(
                        "calculated_ph",
                        entry.get(
                            "calculated_ph_raw_co2",
                            entry.get(
                                "planning_co2_aligned_ph",
                                entry.get("equilibrium_ph", entry.get("ph")),
                            ),
                        ),
                    )
                )
                for entry in resolved_timeline
                if isinstance(entry, Mapping)
            ]
            corrected_calculated_series = [
                _safe_float(
                    entry.get("calculated_ph_corrected_co2")
                )
                for entry in resolved_timeline
                if isinstance(entry, Mapping)
            ]
            corrected_cumulative_series = [
                _safe_float(entry.get("corrected_cumulative_co2_g"))
                for entry in resolved_timeline
                if isinstance(entry, Mapping)
            ]
            # The explicit calculated-pH comparison columns must reveal small
            # CO2-driven pH movement even when legacy two-decimal fields look flat.
            _enforce_analysis_contextual_ph_descent(
                corrected_calculated_series,
                cumulative_co2_series=corrected_cumulative_series,
                min_drop_after_uptake=0.003,
            )
            series_idx = 0
            for entry in resolved_timeline:
                if not isinstance(entry, dict):
                    continue
                raw_value = (
                    raw_calculated_series[series_idx]
                    if series_idx < len(raw_calculated_series)
                    else None
                )
                corrected_value = (
                    corrected_calculated_series[series_idx]
                    if series_idx < len(corrected_calculated_series)
                    else None
                )
                entry["calculated_ph_raw_co2"] = _safe_float(raw_value)
                entry["calculated_ph_corrected_co2"] = _safe_float(corrected_value)
                entry["calculated_ph_corrected_minus_raw_delta"] = (
                    corrected_value - raw_value
                    if raw_value is not None and corrected_value is not None
                    else None
                )
                series_idx += 1
        full_column_pairs = (
            ("cycle", "Cycle"),
            ("co2_cycle_g", "CO2 per cycle (g)"),
            ("corrected_cycle_co2_g", "Corrected CO2 per cycle (g)"),
            ("co2_g", "CO2 total (g)"),
            ("corrected_cumulative_co2_g", "Corrected CO2 total (g)"),
            ("co2_to_target", "CO2 to target (g)"),
            ("equilibrium_ph", "Equilibrium pH (Guidance)"),
            ("corrected_ph", "Corrected pH"),
            ("calculated_ph", "Calculated pH (model)"),
            ("calculated_ph_raw_co2", "Calculated pH (Cycle Analysis CO2)"),
            ("calculated_ph_corrected_co2", "Calculated pH (corrected CO2)"),
            ("calculated_ph_corrected_minus_raw_delta", "ΔpH corrected-raw"),
            ("calibrated_estimated_ph", "Calibrated estimated pH"),
            ("actual_observed_ph", "Actual observed pH (anchor)"),
            ("planning_cycle_ph", "Reference pH (cycle)"),
            ("planning_co2_aligned_ph", "Reference pH (CO2 aligned)"),
            ("ph_delta_cycle", "ΔpH (cycle)"),
            ("ph_delta_co2", "ΔpH (CO2)"),
            ("pco2_atm", "pCO2 (atm)"),
            ("h2co3_pct", "H2CO3 %"),
            ("hco3_pct", "HCO3- %"),
            ("co3_pct", "CO3^2- %"),
            ("actual_cycle_co2_mol", "Actual cycle CO2 (mol)"),
            ("planning_cycle_co2_mol", "Planning cycle CO2 (mol)"),
            ("co2_mol_delta", "ΔCO2 cycle (mol)"),
            ("co2_mol_delta_pct", "ΔCO2 cycle (%)"),
            ("actual_hco3_pct", "Actual HCO3- %"),
            ("actual_co3_pct", "Actual CO3^2- %"),
            ("planning_hco3_pct", "Planning HCO3- %"),
            ("planning_co3_pct", "Planning CO3^2- %"),
            ("hco3_pct_delta", "ΔHCO3- pts"),
            ("co3_pct_delta", "ΔCO3^2- pts"),
            ("alignment_quality_flag", "Alignment quality"),
            ("consistency_status", "Consistency status"),
            ("consistency_flags", "Consistency flags"),
            ("solid_na2co3_g", "Solid Na2CO3 (g)"),
            ("solid_nahco3_g", "Solid NaHCO3 (g)"),
            ("warnings", "Notes"),
        )
        recommended_co2 = _safe_float(guidance.get("recommended_co2_g"))
        full_row_maps: List[Dict[str, Any]] = []
        tree_rows: List[Dict[str, Any]] = []
        callout_lines: List[str] = []
        for entry in resolved_timeline:
            if entry.get("error"):
                continue
            fractions = entry.get("fractions") or {}
            warnings = entry.get("warnings") or []
            if not isinstance(warnings, Sequence) or isinstance(
                warnings, (str, bytes, bytearray)
            ):
                warnings = [warnings] if warnings else []
            warnings_list = [str(item).strip() for item in warnings if str(item).strip()]
            raw_cycle_mass = (
                _safe_float(entry.get("co2_mass_g"))
                or _safe_float(entry.get("original_cycle_co2_g"))
                or _safe_float(entry.get("co2_cycle_g"))
                or 0.0
            )
            corrected_cycle_mass = _safe_float(entry.get("corrected_cycle_co2_g"))
            corrected_cumulative_mass = _safe_float(entry.get("corrected_cumulative_co2_g"))
            co2_total = (
                _safe_float(entry.get("co2_g"))
                or _safe_float(entry.get("co2_mass_g"))
                or 0.0
            )
            ph_value = _safe_float(
                entry.get(
                    "equilibrium_ph",
                    entry.get("ph", entry.get("actual_ph", entry.get("solution_ph"))),
                )
            )
            remaining_value = _safe_float(entry.get("co2_to_target_g"))
            pco2_value = _safe_float(entry.get("pco2_atm"))
            planning_cycle_ph = _safe_float(entry.get("planning_cycle_ph"))
            planning_co2_aligned_ph = _safe_float(entry.get("planning_co2_aligned_ph"))
            ph_delta_cycle = _safe_float(entry.get("ph_delta_cycle"))
            ph_delta_co2 = _safe_float(entry.get("ph_delta_co2"))
            corrected_ph = _safe_float(entry.get("corrected_ph"))
            calculated_ph = _safe_float(
                entry.get(
                    "calculated_ph",
                    entry.get(
                        "equilibrium_ph",
                        entry.get("ph", entry.get("actual_ph", entry.get("solution_ph"))),
                    ),
                )
            )
            raw_calculated_ph = _safe_float(
                entry.get(
                    "calculated_ph",
                    entry.get(
                        "calculated_ph_raw_co2",
                        entry.get("planning_co2_aligned_ph", calculated_ph),
                    ),
                )
            )
            corrected_calculated_ph = _safe_float(
                entry.get("calculated_ph_corrected_co2")
            )
            calculated_delta = _safe_float(
                entry.get("calculated_ph_corrected_minus_raw_delta")
            )
            if (
                calculated_delta is None
                and raw_calculated_ph is not None
                and corrected_calculated_ph is not None
            ):
                calculated_delta = corrected_calculated_ph - raw_calculated_ph
            calibrated_estimated_ph = _safe_float(
                entry.get("calibrated_estimated_ph", entry.get("corrected_ph"))
            )
            actual_observed_ph = _safe_float(
                entry.get("actual_observed_ph", entry.get("analysis_anchor_measured_ph"))
            )
            consistency_status = str(entry.get("consistency_status") or "").strip()
            consistency_flags = [
                str(item).strip()
                for item in list(entry.get("consistency_flags") or [])
                if str(item).strip()
            ]
            actual_cycle_co2_mol = _safe_float(entry.get("actual_cycle_co2_mol"))
            planning_cycle_co2_mol = _safe_float(entry.get("planning_cycle_co2_mol"))
            co2_mol_delta = _safe_float(entry.get("co2_mol_delta"))
            co2_mol_delta_pct = _safe_float(entry.get("co2_mol_delta_pct"))
            actual_hco3_pct = _safe_float(entry.get("actual_hco3_pct"))
            actual_co3_pct = _safe_float(entry.get("actual_co3_pct"))
            planning_hco3_pct = _safe_float(entry.get("planning_hco3_pct"))
            planning_co3_pct = _safe_float(entry.get("planning_co3_pct"))
            hco3_pct_delta = _safe_float(entry.get("hco3_pct_delta"))
            co3_pct_delta = _safe_float(entry.get("co3_pct_delta"))
            measured_anchor_ph = _safe_float(entry.get("analysis_anchor_measured_ph"))
            row_map = {
                "cycle": str(entry.get("cycle_id")),
                "co2_cycle_g": f"{raw_cycle_mass:.2f}",
                "corrected_cycle_co2_g": (
                    f"{corrected_cycle_mass:.2f}"
                    if corrected_cycle_mass is not None
                    else ""
                ),
                "co2_g": f"{co2_total:.2f}",
                "corrected_cumulative_co2_g": (
                    f"{corrected_cumulative_mass:.2f}"
                    if corrected_cumulative_mass is not None
                    else ""
                ),
                "co2_to_target": (
                    f"{remaining_value:.2f}" if remaining_value is not None else ""
                ),
                "equilibrium_ph": f"{ph_value:.2f}" if ph_value is not None else "",
                "ph": f"{ph_value:.2f}" if ph_value is not None else "",
                "corrected_ph": (
                    f"{corrected_ph:.3f}" if corrected_ph is not None else ""
                ),
                "calculated_ph": (
                    f"{calculated_ph:.3f}" if calculated_ph is not None else ""
                ),
                "calculated_ph_raw_co2": (
                    f"{raw_calculated_ph:.3f}"
                    if raw_calculated_ph is not None
                    else ""
                ),
                "calculated_ph_corrected_co2": (
                    f"{corrected_calculated_ph:.3f}"
                    if corrected_calculated_ph is not None
                    else ""
                ),
                "calculated_ph_corrected_minus_raw_delta": (
                    f"{calculated_delta:+.3f}" if calculated_delta is not None else ""
                ),
                "calibrated_estimated_ph": (
                    f"{calibrated_estimated_ph:.2f}"
                    if calibrated_estimated_ph is not None
                    else ""
                ),
                "actual_observed_ph": (
                    f"{actual_observed_ph:.2f}" if actual_observed_ph is not None else ""
                ),
                "planning_cycle_ph": (
                    f"{planning_cycle_ph:.2f}" if planning_cycle_ph is not None else ""
                ),
                "planning_co2_aligned_ph": (
                    f"{planning_co2_aligned_ph:.2f}"
                    if planning_co2_aligned_ph is not None
                    else ""
                ),
                "ph_delta_cycle": (
                    f"{ph_delta_cycle:+.3f}" if ph_delta_cycle is not None else ""
                ),
                "ph_delta_co2": (
                    f"{ph_delta_co2:+.3f}" if ph_delta_co2 is not None else ""
                ),
                "pco2_atm": f"{pco2_value:.3g}" if pco2_value is not None else "",
                "h2co3_pct": f"{_safe_float(fractions.get('H2CO3'), 0.0) * 100:.1f}",
                "hco3_pct": f"{_safe_float(fractions.get('HCO3-'), 0.0) * 100:.1f}",
                "co3_pct": f"{_safe_float(fractions.get('CO3^2-'), 0.0) * 100:.1f}",
                "actual_cycle_co2_mol": (
                    f"{actual_cycle_co2_mol:.4f}"
                    if actual_cycle_co2_mol is not None
                    else ""
                ),
                "planning_cycle_co2_mol": (
                    f"{planning_cycle_co2_mol:.4f}"
                    if planning_cycle_co2_mol is not None
                    else ""
                ),
                "co2_mol_delta": (
                    f"{co2_mol_delta:+.4f}" if co2_mol_delta is not None else ""
                ),
                "co2_mol_delta_pct": (
                    f"{co2_mol_delta_pct:+.1f}" if co2_mol_delta_pct is not None else ""
                ),
                "actual_hco3_pct": (
                    f"{actual_hco3_pct:.2f}" if actual_hco3_pct is not None else ""
                ),
                "actual_co3_pct": (
                    f"{actual_co3_pct:.2f}" if actual_co3_pct is not None else ""
                ),
                "planning_hco3_pct": (
                    f"{planning_hco3_pct:.2f}" if planning_hco3_pct is not None else ""
                ),
                "planning_co3_pct": (
                    f"{planning_co3_pct:.2f}" if planning_co3_pct is not None else ""
                ),
                "hco3_pct_delta": (
                    f"{hco3_pct_delta:+.2f}" if hco3_pct_delta is not None else ""
                ),
                "co3_pct_delta": (
                    f"{co3_pct_delta:+.2f}" if co3_pct_delta is not None else ""
                ),
                "alignment_quality_flag": str(entry.get("alignment_quality_flag") or ""),
                "consistency_status": consistency_status,
                "consistency_flags": ", ".join(consistency_flags),
                "solid_na2co3_g": f"{_safe_float(entry.get('solid_na2co3_g'), 0.0):.2f}",
                "solid_nahco3_g": f"{_safe_float(entry.get('solid_nahco3_g'), 0.0):.2f}",
                "warnings": " | ".join(warnings_list),
            }
            full_row_maps.append(row_map)
            tree_rows.append({key: row_map.get(key, "") for key in column_order})
            ph_text = f"{ph_value:.2f}" if ph_value is not None else "n/a"
            callout_line = (
                f"Cycle {entry.get('cycle_id')}: "
                f"{co2_total:.2f} g cumulative CO2 | equilibrium pH {ph_text}"
            )
            if remaining_value is None and recommended_co2 is not None:
                remaining_value = max(0.0, recommended_co2 - co2_total)
            if remaining_value is not None:
                callout_line += f" | CO2 to target: {remaining_value:.2f} g"
            if measured_anchor_ph is not None:
                callout_line += f" | Measured pH anchor: {measured_anchor_ph:.2f}"
            if consistency_status:
                callout_line += f" | Consistency: {consistency_status}"
            if warnings_list:
                callout_line += f" (warnings: {'; '.join(warnings_list)})"
            if workflow == "Analysis":
                analysis_bits: List[str] = []
                if planning_cycle_ph is not None:
                    analysis_bits.append(f"plan(cycle) pH {planning_cycle_ph:.2f}")
                if planning_co2_aligned_ph is not None:
                    analysis_bits.append(f"plan(CO2) pH {planning_co2_aligned_ph:.2f}")
                if corrected_ph is not None:
                    analysis_bits.append(f"corrected pH {corrected_ph:.3f}")
                if raw_calculated_ph is not None:
                    analysis_bits.append(f"calc(raw CO2) pH {raw_calculated_ph:.2f}")
                if corrected_calculated_ph is not None:
                    analysis_bits.append(
                        f"calc(corrected CO2) pH {corrected_calculated_ph:.2f}"
                    )
                if calculated_delta is not None:
                    analysis_bits.append(f"Δcalc pH {calculated_delta:+.3f}")
                if corrected_cycle_mass is not None:
                    analysis_bits.append(f"corrected cycle CO2 {corrected_cycle_mass:.2f} g")
                if ph_delta_cycle is not None:
                    analysis_bits.append(f"ΔpH cycle {ph_delta_cycle:+.3f}")
                if ph_delta_co2 is not None:
                    analysis_bits.append(f"ΔpH CO2 {ph_delta_co2:+.3f}")
                if analysis_bits:
                    callout_line += " | " + ", ".join(analysis_bits)
            callout_lines.append(callout_line)
        show_tree = not (
            workflow == "Reprocessing" and (preview_mode or not resolved_timeline)
        )
        if not callout_lines:
            callout_lines = ["No cycle speciation data available."]
        return {
            "workflow": workflow,
            "timeline": resolved_timeline,
            "preview_mode": preview_mode,
            "columns": column_order,
            "tree_rows": tree_rows,
            "show_tree": show_tree,
            "display_row_count": len(tree_rows) if show_tree else 0,
            "full_column_pairs": full_column_pairs,
            "full_columns": tuple(
                column_id for column_id, _header in full_column_pairs
            ),
            "full_headers": [header for _column_id, header in full_column_pairs],
            "full_rows": [
                [row_map.get(column_id, "") for column_id, _header in full_column_pairs]
                for row_map in full_row_maps
            ],
            "callout_lines": callout_lines,
            "reaction_guidance": guidance,
        }

    def _apply_cycle_timeline_tree_rows_in_chunks(
        self,
        tree: Optional[ttk.Treeview],
        rows: Sequence[Mapping[str, Any]],
        columns: Sequence[str],
        *,
        chunk_size: int = 200,
        on_complete: Optional[Callable[[], None]] = None,
    ) -> None:
        """Apply timeline Treeview rows in event-loop-friendly chunks.

        Purpose:
            Insert timeline rows without monopolizing the Tk main thread.
        Why:
            Large row batches can freeze the interface and stall loading overlay
            animation if inserted in one synchronous loop.
        Inputs:
            tree: Target timeline Treeview widget.
            rows: Timeline table row dictionaries.
            columns: Target column order.
            chunk_size: Maximum rows inserted per event-loop turn.
            on_complete: Optional callback invoked after final chunk.
        Outputs:
            None.
        Side Effects:
            Clears/repopulates `tree` and schedules chunk callbacks via `after`.
        Exceptions:
            Widget errors fail closed and still invoke `on_complete`.
        """

        def _finish() -> None:
            """Run completion callback once tree chunk insertion finishes."""
            if callable(on_complete):
                try:
                    on_complete()
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass

        if tree is None:
            _finish()
            return
        column_order = tuple(str(col) for col in (columns or ()))
        normalized_rows = [dict(row) for row in rows or () if isinstance(row, Mapping)]
        try:
            for child in tree.get_children():
                tree.delete(child)
        except Exception:
            _finish()
            return
        if not normalized_rows:
            _finish()
            return
        chunk_limit = max(1, int(chunk_size))
        state = {"offset": 0}

        def _insert_chunk() -> None:
            """Insert the next tree row chunk and reschedule while work remains."""
            try:
                if not tree.winfo_exists():
                    _finish()
                    return
            except Exception:
                _finish()
                return
            start = int(state["offset"])
            end = min(start + chunk_limit, len(normalized_rows))
            for row_map in normalized_rows[start:end]:
                values = [
                    _repair_mojibake_text(row_map.get(col, "")) for col in column_order
                ]
                try:
                    tree.insert("", "end", values=values)
                except Exception:
                    continue
            state["offset"] = end
            if end >= len(normalized_rows):
                _finish()
                return
            try:
                self.after(0, _insert_chunk)
            except Exception:
                _finish()

        try:
            self.after(0, _insert_chunk)
        except Exception:
            _insert_chunk()

    def _apply_cycle_callout_lines_in_chunks(
        self,
        *,
        lines: Sequence[str],
        chunk_size: int = 120,
        on_complete: Optional[Callable[[], None]] = None,
    ) -> None:
        """Apply timeline callout text lines in event-loop-friendly chunks.

        Purpose:
            Insert timeline callout lines without blocking Tk repaint/input events.
        Why:
            Large callout text payloads can freeze navigation and progress
            animation when inserted in one synchronous block.
        Inputs:
            lines: Callout text lines to render.
            chunk_size: Maximum callout lines inserted per event-loop turn.
            on_complete: Optional callback invoked when insertion completes.
        Outputs:
            None.
        Side Effects:
            Rewrites callout text widget contents using scheduled `after` chunks.
        Exceptions:
            Widget errors fail closed and still invoke `on_complete`.
        """
        callout = getattr(self, "_sol_cycle_callouts", None)

        def _finish() -> None:
            """Finalize callout render and run completion callback once."""
            if callable(on_complete):
                try:
                    on_complete()
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass

        if callout is None:
            _finish()
            return
        try:
            if not callout.winfo_exists():
                _finish()
                return
        except Exception:
            _finish()
            return
        try:
            view_state = callout.yview()
            visible_span = view_state[1] - view_state[0]
            stick_to_bottom = (1.0 - view_state[1]) <= max(0.02, visible_span * 0.25)
            preserve_top = view_state[0]
        except Exception:
            stick_to_bottom = True
            preserve_top = 0.0
        lines_to_insert = [str(line or "") for line in (lines or ())]
        if not lines_to_insert:
            lines_to_insert = ["No cycle speciation data available."]
        try:
            callout.configure(state="normal")
            callout.delete("1.0", "end")
        except Exception:
            _finish()
            return
        chunk_limit = max(1, int(chunk_size))
        state = {"offset": 0}

        def _finalize_widget_state() -> None:
            """Restore callout widget state/scroll after chunk insertion completes."""
            try:
                callout.configure(state="disabled")
            except Exception:
                pass
            try:
                if stick_to_bottom:
                    callout.see("end")
                else:
                    callout.yview_moveto(preserve_top)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            _finish()

        def _insert_chunk() -> None:
            """Insert one callout text chunk and reschedule while pending."""
            try:
                if not callout.winfo_exists():
                    _finish()
                    return
            except Exception:
                _finish()
                return
            start = int(state["offset"])
            end = min(start + chunk_limit, len(lines_to_insert))
            for line in lines_to_insert[start:end]:
                try:
                    callout.insert("end", f"{line}\n")
                except Exception:
                    continue
            state["offset"] = end
            if end < len(lines_to_insert):
                try:
                    self.after(0, _insert_chunk)
                except Exception:
                    _finalize_widget_state()
                return
            _finalize_widget_state()

        try:
            self.after(0, _insert_chunk)
        except Exception:
            _insert_chunk()

    def _apply_cycle_timeline_render_payload_staged(
        self,
        payload: Mapping[str, Any],
        *,
        workflow_key: Optional[str] = None,
        on_complete: Optional[Callable[[], None]] = None,
    ) -> None:
        """Apply cycle timeline table/callout/plot updates in staged chunks.

        Purpose:
            Render timeline UI surfaces while yielding control to the Tk event loop.
        Why:
            Staging prevents long synchronous updates from freezing the workflow UI.
        Inputs:
            payload: Prebuilt timeline render payload.
            workflow_key: Optional workflow override.
            on_complete: Optional callback after staged render completes.
        Outputs:
            None.
        Side Effects:
            Updates export cache rows, tree visibility/state, timeline plot, and
            callout text using chunked `after` scheduling.
        Exceptions:
            Any staged callback failures still attempt to invoke `on_complete`.
        """
        payload_map = dict(payload or {})
        workflow = workflow_key or str(payload_map.get("workflow") or "")
        if not workflow:
            workflow = self._current_solubility_workflow()
        timeline_rows = list(payload_map.get("timeline") or [])
        columns = tuple(
            payload_map.get("columns") or getattr(self, "_sol_cycle_timeline_columns", ())
        )
        tree_rows = list(payload_map.get("tree_rows") or [])
        if workflow == "Analysis" and timeline_rows:
            needs_calculated_ph_migration = "calculated_ph" not in columns
            if not needs_calculated_ph_migration:
                for entry in timeline_rows:
                    if not isinstance(entry, Mapping):
                        continue
                    model_ph = _safe_float(entry.get("calculated_ph"))
                    raw_trace_ph = _safe_float(entry.get("calculated_ph_raw_co2"))
                    if (
                        model_ph is not None
                        and raw_trace_ph is not None
                        and not _chemistry_float_close(
                            model_ph,
                            raw_trace_ph,
                            rel_tol=5e-5,
                            abs_tol=1e-8,
                        )
                    ):
                        needs_calculated_ph_migration = True
                        break
            if needs_calculated_ph_migration:
                # Older persisted payloads stored the CO2-aligned reference in
                # the calculated-pH trace slot; rebuild the render-only surface
                # from timeline rows so profile reloads show the corrected split.
                payload_map = self._build_cycle_timeline_render_payload(
                    timeline_rows,
                    workflow_key=workflow,
                    reaction_guidance=getattr(self, "_sol_reaction_guidance", {}) or {},
                    columns=getattr(self, "_sol_cycle_timeline_columns", ()),
                )
                timeline_rows = list(payload_map.get("timeline") or [])
                columns = tuple(
                    payload_map.get("columns")
                    or getattr(self, "_sol_cycle_timeline_columns", ())
                )
                tree_rows = list(payload_map.get("tree_rows") or [])
        show_tree = bool(payload_map.get("show_tree", True))
        display_row_count = int(payload_map.get("display_row_count") or 0)
        self._sol_cycle_timeline_full_columns = tuple(payload_map.get("full_columns") or ())
        self._sol_cycle_timeline_full_headers = list(payload_map.get("full_headers") or [])
        self._sol_cycle_timeline_full_rows = list(payload_map.get("full_rows") or [])
        self._set_timeline_action_state(bool(self._sol_cycle_timeline_full_rows))
        self._toggle_cycle_tree_visibility(show_tree)
        self._resize_cycle_timeline_tree(display_row_count)
        self._update_cycle_spec_view(
            timeline_rows,
            workflow_key=workflow,
            render_payload=payload_map,
            skip_tree=True,
            skip_callout=True,
        )

        def _finish() -> None:
            """Finalize staged payload apply and invoke completion callback."""
            self._refresh_cycle_comparison_explorer()
            try:
                self._refresh_sol_workflow_layout()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            if callable(on_complete):
                try:
                    on_complete()
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass

        self._apply_cycle_timeline_tree_rows_in_chunks(
            getattr(self, "_sol_cycle_tree", None)
            or getattr(self, "_sol_cycle_timeline_tree", None),
            tree_rows if show_tree else [],
            columns,
            chunk_size=200,
            on_complete=lambda: self._apply_cycle_callout_lines_in_chunks(
                lines=payload_map.get("callout_lines") or [],
                chunk_size=120,
                on_complete=_finish,
            ),
        )

    def _update_cycle_spec_view(
        self,
        timeline: Sequence[Dict[str, Any]],
        *,
        workflow_key: Optional[str] = None,
        render_payload: Optional[Mapping[str, Any]] = None,
        skip_tree: bool = False,
        skip_callout: bool = False,
    ) -> None:
        """Update cycle spec view.
        Purpose: Render the cycle timeline plot and associated callouts.
        Why: Keep the on-screen cycle speciation view aligned with the latest results.
        Inputs:
            timeline (Sequence[Dict[str, Any]]): Cycle timeline rows to plot.
            workflow_key (Optional[str]): Workflow identifier for plot context.
            render_payload: Optional prebuilt payload from worker-safe normalization.
            skip_tree: When True, skip Treeview updates (staged render path).
            skip_callout: When True, skip callout text updates (staged render path).
        Outputs:
            None.
        Side Effects:
            - Clears and redraws axes, legends, and callout widgets.
            - Updates top/bottom cycle timeline legends in place.
            - Rebinds plot-elements controller state to timeline display canvas.
        Exceptions:
            - Best-effort; exits early when plot widgets are unavailable.
        """
        workflow = workflow_key or self._current_solubility_workflow()
        reaction_guidance = getattr(self, "_sol_reaction_guidance", {}) or {}
        payload_map = dict(render_payload) if isinstance(render_payload, Mapping) else {}
        if not payload_map:
            payload_map = self._build_cycle_timeline_render_payload(
                timeline,
                workflow_key=workflow,
                reaction_guidance=reaction_guidance,
                columns=getattr(self, "_sol_cycle_timeline_columns", ()),
            )
        timeline = list(payload_map.get("timeline") or [])
        timeline_row_count = int(len(timeline))
        self._dbg(
            "plotting.render",
            "cycle_timeline_ui_start workflow=%s timeline_rows=%s skip_tree=%s skip_callout=%s",
            workflow,
            timeline_row_count,
            bool(skip_tree),
            bool(skip_callout),
        )
        preview_mode = bool(payload_map.get("preview_mode"))
        tree = getattr(self, "_sol_cycle_timeline_tree", None)
        columns = tuple(
            payload_map.get("columns") or getattr(self, "_sol_cycle_timeline_columns", ())
        )
        rows = list(payload_map.get("tree_rows") or [])
        full_rows = list(payload_map.get("full_rows") or [])
        full_columns = tuple(payload_map.get("full_columns") or ())
        full_headers = list(payload_map.get("full_headers") or [])
        target_ph = reaction_guidance.get("target_ph")
        show_tree = not (workflow == "Reprocessing" and (preview_mode or not timeline))
        self._sol_cycle_timeline_full_columns = full_columns
        self._sol_cycle_timeline_full_headers = full_headers
        self._sol_cycle_timeline_full_rows = full_rows
        if tree is not None and not skip_tree:
            if show_tree:
                self._populate_treeview(tree, rows, columns)
            else:
                self._populate_treeview(tree, [], columns)
            self._toggle_cycle_tree_visibility(show_tree)
            self._resize_cycle_timeline_tree(len(rows) if show_tree else 0)
        self._set_timeline_action_state(bool(self._sol_cycle_timeline_full_rows))

        ax = getattr(self, "_sol_cycle_spec_ax", None)
        ax2 = getattr(self, "_sol_cycle_spec_ax2", None)
        ax3 = getattr(self, "_sol_cycle_spec_ax3", None)
        canvas = getattr(self, "_sol_cycle_spec_canvas", None)
        if ax is None or ax2 is None or ax3 is None or canvas is None:
            self._dbg(
                "plotting.render",
                "cycle_timeline_ui_done workflow=%s timeline_rows=%s stage=no_plot_widgets",
                workflow,
                timeline_row_count,
            )
            return
        ax.clear()
        ax2.clear()
        ax3.clear()
        prefs = self._get_cycle_plot_prefs()
        timeline_bar_color = str(prefs.get("timeline_bar_color") or "").strip() or "#8ecae6"
        timeline_bar_alpha = _safe_float(
            prefs.get("timeline_bar_alpha"),
            DEFAULT_CYCLE_TIMELINE_BAR_ALPHA,
        )
        if timeline_bar_alpha is None or not math.isfinite(timeline_bar_alpha):
            timeline_bar_alpha = DEFAULT_CYCLE_TIMELINE_BAR_ALPHA
        timeline_bar_alpha = max(0.0, min(1.0, float(timeline_bar_alpha)))
        timeline_bar_label_fontsize = _safe_float(
            prefs.get("timeline_bar_label_fontsize"),
            DEFAULT_CYCLE_TIMELINE_BAR_LABEL_FONTSIZE,
        )
        if (
            timeline_bar_label_fontsize is None
            or not math.isfinite(timeline_bar_label_fontsize)
        ):
            timeline_bar_label_fontsize = DEFAULT_CYCLE_TIMELINE_BAR_LABEL_FONTSIZE
        timeline_bar_label_fontsize = max(4.0, min(48.0, float(timeline_bar_label_fontsize)))
        timeline_bar_label_color = (
            str(prefs.get("timeline_bar_label_color") or "").strip()
            or DEFAULT_CYCLE_TIMELINE_BAR_LABEL_COLOR
        )
        axis_layout_getter = getattr(self, "_cycle_timeline_axis_layout_prefs", None)
        if callable(axis_layout_getter):
            axis_layout = axis_layout_getter(prefs)
        else:
            axis_layout = {
                "ph_axis_labelpad": float(prefs.get("ph_axis_labelpad", 10.0)),
                "ph_axis_spine_offset": float(prefs.get("ph_axis_spine_offset", 1.02)),
                "pco2_axis_labelpad": float(prefs.get("pco2_axis_labelpad", 10.0)),
                "pco2_axis_spine_offset": float(prefs.get("pco2_axis_spine_offset", 1.12)),
            }
        ax.set_ylabel("Sodium species (%)", fontsize=11, labelpad=10)
        title_text = UnifiedApp._cycle_timeline_effective_render_title_text(self, prefs)
        ax.set_title(title_text, fontsize=11, pad=8)
        ax.tick_params(axis="both", labelsize=9, pad=4)
        ax2.set_xlabel("Cycle", fontsize=11, labelpad=8)
        try:
            # Timeline layout checks must target the lower subplot xlabel rather
            # than the shared top-axis empty label.
            ax.figure._gl260_xlabel_text = ax2.xaxis.get_label()  # type: ignore[attr-defined]
            ax.figure._gl260_plot_id = "fig_cycle_timeline"  # type: ignore[attr-defined]
            ax.figure._gl260_layout_mode = "display"  # type: ignore[attr-defined]
        except Exception:
            # Best-effort guard; ignore metadata tagging failures.
            pass
        apply_axis_layout = getattr(self, "_apply_cycle_timeline_axis_layout", None)
        if callable(apply_axis_layout):
            apply_axis_layout(
                ax2,
                ax3,
                axis_layout=axis_layout,
            )
        else:
            ax2.set_ylabel(
                "Equilibrium / corrected / reference pH",
                fontsize=11,
                labelpad=axis_layout.get("ph_axis_labelpad", 10.0),
            )
            ax2.tick_params(axis="both", labelsize=9, pad=4)
            resolve_label_x = getattr(self, "_resolve_cycle_timeline_uptake_label_x", None)
            if callable(resolve_label_x):
                cycle_label_x = resolve_label_x(
                    axis_layout,
                    uptake_labelpad=float(axis_layout.get("pco2_axis_labelpad", 10.0)),
                    ax3=ax3,
                )
            else:
                base_label_x = _safe_float(axis_layout.get("pco2_axis_spine_offset"), 1.12)
                if base_label_x is None or not math.isfinite(base_label_x):
                    base_label_x = 1.12
                fig_w_pts = max(float(ax.figure.get_size_inches()[0]) * 72.0, 1.0)
                cycle_label_x = max(
                    1.0,
                    min(
                        1.8,
                        float(base_label_x)
                        + (float(axis_layout.get("pco2_axis_labelpad", 10.0)) / fig_w_pts),
                    ),
                )
            ax3.set_ylabel(
                "Cycle CO$_2$ uptake (g)",
                fontsize=11,
                labelpad=axis_layout.get("pco2_axis_labelpad", 10.0),
                rotation=-90,
            )
            ax3.spines["right"].set_position(("axes", 1.0))
            ax3.yaxis.set_label_position("right")
            ax3.yaxis.tick_right()
            ax3.yaxis.set_label_coords(cycle_label_x, 0.5)
            ax3.tick_params(axis="both", labelsize=8, pad=3)
        try:
            ax._gl260_axis_role = "primary"
            ax2._gl260_axis_role = "right"
            ax3._gl260_axis_role = "third"
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        if not timeline:
            ax.text(0.5, 0.5, "No cycle data", ha="center", va="center")
            ax2.text(
                0.5,
                0.5,
                "Run a timeline simulation to preview speciation.",
                ha="center",
                va="center",
            )
            for legend_attr in ("_planning_timeline_legend", "_planning_timeline_bottom_legend"):
                legend = getattr(self, legend_attr, None)
                if legend is None:
                    continue
                try:
                    legend.set_visible(False)
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
            try:
                self._upsert_cycle_timeline_auto_current_state_plot_element(
                    marker_x=None,
                    marker_ph=None,
                    label_text=None,
                    axis=ax2,
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            self._ensure_cycle_timeline_annotation_controller()
            canvas.draw_idle()
            self._dbg(
                "plotting.render",
                "cycle_timeline_plot_done workflow=%s timeline_rows=%s",
                workflow,
                0,
            )
            if skip_callout:
                self._refresh_cycle_comparison_explorer()
                try:
                    self._refresh_sol_workflow_layout()
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
                self._dbg(
                    "plotting.render",
                    "cycle_timeline_ui_done workflow=%s timeline_rows=%s",
                    workflow,
                    0,
                )
                return
            callout = getattr(self, "_sol_cycle_callouts", None)
            if callout is not None:
                try:
                    callout.configure(state="normal")
                    callout.delete("1.0", "end")
                    callout.insert("end", "No cycle speciation data available.\n")
                    callout.configure(state="disabled")
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
            self._refresh_cycle_comparison_explorer()
            try:
                self._refresh_sol_workflow_layout()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            self._dbg(
                "plotting.render",
                "cycle_timeline_ui_done workflow=%s timeline_rows=%s",
                workflow,
                0,
            )
            return
        xs = []
        ph_values = []
        corrected_ph_values: List[float] = []
        calculated_raw_ph_values: List[float] = []
        calculated_corrected_ph_values: List[float] = []
        cycle_uptake_values: List[float] = []
        corrected_cycle_uptake_values: List[float] = []
        planning_cycle_uptake_values: List[float] = []
        measured_anchor_x: List[float] = []
        measured_anchor_y: List[float] = []
        # Iterate over timeline to apply the per-item logic.
        for idx, entry in enumerate(timeline, start=1):
            cycle_id_value = _safe_float(entry.get("cycle_id"))
            xs.append(cycle_id_value if cycle_id_value is not None else float(idx))
            ph = _safe_float(
                entry.get(
                    "equilibrium_ph",
                    entry.get("ph", entry.get("actual_ph", entry.get("solution_ph"))),
                )
            )
            ph_values.append(ph if ph is not None else float("nan"))
            corrected_ph_val = _safe_float(entry.get("corrected_ph"))
            corrected_ph_values.append(
                corrected_ph_val if corrected_ph_val is not None else float("nan")
            )
            raw_calculated_ph_val = _safe_float(
                entry.get(
                    "calculated_ph",
                    entry.get(
                        "calculated_ph_raw_co2",
                        entry.get("planning_co2_aligned_ph", ph),
                    ),
                )
            )
            calculated_raw_ph_values.append(
                raw_calculated_ph_val
                if raw_calculated_ph_val is not None
                else float("nan")
            )
            corrected_calculated_ph_val = _safe_float(
                entry.get("calculated_ph_corrected_co2")
            )
            calculated_corrected_ph_values.append(
                corrected_calculated_ph_val
                if corrected_calculated_ph_val is not None
                else float("nan")
            )
            cycle_uptake_values.append(_safe_float(entry.get("co2_mass_g"), 0.0))
            corrected_cycle_uptake_g = _safe_float(entry.get("corrected_cycle_co2_g"))
            if corrected_cycle_uptake_g is None:
                corrected_cycle_uptake_mol = _safe_float(
                    entry.get("corrected_cycle_co2_mol")
                )
                corrected_cycle_uptake_g = (
                    corrected_cycle_uptake_mol * SOL_MW_CO2
                    if corrected_cycle_uptake_mol is not None
                    else float("nan")
                )
            corrected_cycle_uptake_values.append(
                corrected_cycle_uptake_g
                if corrected_cycle_uptake_g is not None
                else float("nan")
            )
            planning_cycle_co2_mol = _safe_float(entry.get("planning_cycle_co2_mol"))
            planning_cycle_uptake_values.append(
                (planning_cycle_co2_mol * SOL_MW_CO2)
                if planning_cycle_co2_mol is not None
                else float("nan")
            )
            measured_anchor_ph = _safe_float(entry.get("analysis_anchor_measured_ph"))
            anchor_source = entry.get("analysis_anchor_source")
            if (
                measured_anchor_ph is not None
                and math.isfinite(measured_anchor_ph)
                and _analysis_anchor_source_allows_timeline_marker(anchor_source)
            ):
                measured_anchor_x.append(xs[-1])
                measured_anchor_y.append(measured_anchor_ph)
        sodium_series = UnifiedApp._resolve_cycle_timeline_sodium_speciation_series(
            self,
            timeline,
            workflow_key=workflow,
        )
        naoh_vals = list(sodium_series.get("naoh_pct") or [])
        na2co3_vals = list(sodium_series.get("na2co3_pct") or [])
        nahco3_vals = list(sodium_series.get("nahco3_pct") or [])
        if len(naoh_vals) != len(xs):
            naoh_vals = (naoh_vals + [0.0] * len(xs))[: len(xs)]
        if len(na2co3_vals) != len(xs):
            na2co3_vals = (na2co3_vals + [0.0] * len(xs))[: len(xs)]
        if len(nahco3_vals) != len(xs):
            nahco3_vals = (nahco3_vals + [0.0] * len(xs))[: len(xs)]
        timeline_trace_settings = self._trace_settings_store_for_plot_id(
            "fig_cycle_timeline"
        )
        timeline_catalog = self._cycle_timeline_trace_catalog()

        def _timeline_trace_config(
            trace_key: str,
            defaults: Optional[Mapping[str, Any]] = None,
        ) -> Dict[str, Any]:
            """Return merged display trace settings for one timeline series.

            Purpose:
                Combine catalog defaults with persisted Data Trace Settings.
            Why:
                The embedded timeline display must honor the same per-trace
                controls used by generated-tab, preview, and export figures.
            Inputs:
                trace_key: Timeline series identifier.
                defaults: Optional default style/configuration mapping.
            Outputs:
                Dict[str, Any]: Merged trace configuration with normalized
                `enabled` state.
            Side Effects:
                None.
            Exceptions:
                Invalid persisted payloads fall back to defaults.
            """
            merged: Dict[str, Any] = dict(defaults or {})
            stored_cfg = timeline_trace_settings.get(trace_key, {})
            if isinstance(stored_cfg, Mapping):
                merged.update(dict(stored_cfg))
            merged["enabled"] = bool(
                stored_cfg.get("enabled", True)
                if isinstance(stored_cfg, Mapping)
                else True
            )
            return merged

        def _timeline_trace_defaults(trace_key: str) -> Dict[str, Any]:
            """Resolve default display trace styling from the timeline catalog.

            Purpose:
                Read the default styling contract for one timeline trace.
            Why:
                Keeping defaults catalog-driven prevents embedded display styling
                from drifting away from export/preview renderers.
            Inputs:
                trace_key: Timeline series identifier.
            Outputs:
                Dict[str, Any]: Default style mapping for the trace, or an empty
                mapping when no catalog entry exists.
            Side Effects:
                None.
            Exceptions:
                Malformed catalog entries safely return an empty mapping.
            """
            entry = timeline_catalog.get(trace_key, {})
            defaults = entry.get("defaults") if isinstance(entry, Mapping) else {}
            return dict(defaults) if isinstance(defaults, Mapping) else {}

        def _timeline_trace_color(
            trace_config: Mapping[str, Any], fallback: str
        ) -> str:
            """Resolve the display color for one timeline trace.

            Purpose:
                Select a Matplotlib color from trace settings with fallback.
            Why:
                Data Trace Settings color overrides must apply on the embedded
                timeline display.
            Inputs:
                trace_config: Merged trace configuration mapping.
                fallback: Default color when no override is configured.
            Outputs:
                str: Color token passed to Matplotlib.
            Side Effects:
                None.
            Exceptions:
                Blank override values fall back without raising.
            """
            return str(trace_config.get("color") or fallback).strip() or str(fallback)

        def _timeline_trace_linestyle(
            trace_config: Mapping[str, Any],
            fallback: str,
        ) -> str:
            """Resolve the display linestyle for one timeline trace.

            Purpose:
                Convert persisted line-style names to Matplotlib linestyle values.
            Why:
                Timeline display traces need the same line-style semantics as
                generated/export timeline figures.
            Inputs:
                trace_config: Merged trace configuration mapping.
                fallback: Default line-style token.
            Outputs:
                str: Matplotlib-compatible linestyle value.
            Side Effects:
                None.
            Exceptions:
                Unknown styles fall back to the supplied default.
            """
            style_value = _canonicalize_linestyle_name(trace_config.get("linestyle"))
            if not style_value:
                style_value = _canonicalize_linestyle_name(fallback) or "solid"
            if style_value == "None":
                return "None"
            return _resolve_linestyle_value(style_value)

        def _timeline_trace_marker_size(
            trace_config: Mapping[str, Any],
            fallback: float,
        ) -> float:
            """Resolve display marker size from Data Trace Settings.

            Purpose:
                Convert persisted scatter-size style values to marker points.
            Why:
                Timeline line markers share the Data Trace Settings size field
                with other plot types while Matplotlib expects point units.
            Inputs:
                trace_config: Merged trace configuration mapping.
                fallback: Marker size in points when no valid override exists.
            Outputs:
                float: Marker size in points.
            Side Effects:
                None.
            Exceptions:
                Non-positive or non-finite overrides fall back safely.
            """
            size_override = _safe_float(trace_config.get("size"))
            if (
                size_override is None
                or not math.isfinite(size_override)
                or size_override <= 0.0
            ):
                return float(fallback)
            return float(max(0.5, math.sqrt(float(size_override))))

        def _timeline_trace_label(trace_key: str, fallback: str) -> str:
            """Resolve the display legend label for one timeline trace.

            Purpose:
                Fetch the user-facing trace label from the timeline catalog.
            Why:
                Embedded display legends must use the same labels shown in Data
                Trace Settings and generated/export figures.
            Inputs:
                trace_key: Timeline series identifier.
                fallback: Label used when the catalog entry is unavailable.
            Outputs:
                str: Legend label text.
            Side Effects:
                None.
            Exceptions:
                Missing or malformed catalog values use the fallback label.
            """
            entry = timeline_catalog.get(trace_key, {})
            label = (
                str(entry.get("label") or "").strip()
                if isinstance(entry, Mapping)
                else ""
            )
            return label or fallback

        def _timeline_trace_line_points(
            trace_config: Mapping[str, Any],
            x_values: Sequence[float],
            y_values: Sequence[float],
        ) -> Tuple[List[float], List[float]]:
            """Apply enabled and start-cycle masking to display trace points.

            Purpose:
                Build x/y arrays for a timeline trace after visibility filtering.
            Why:
                Data Trace Settings can disable a trace or delay it until a
                configured cycle number without changing the source timeline data.
            Inputs:
                trace_config: Merged trace configuration mapping.
                x_values: Candidate cycle x-values.
                y_values: Candidate trace y-values.
            Outputs:
                Tuple[List[float], List[float]]: Filtered x/y arrays with
                pre-threshold y-values represented as NaN gaps.
            Side Effects:
                None.
            Exceptions:
                Invalid numeric inputs are skipped or converted to NaN gaps.
            """
            if not bool(trace_config.get("enabled", True)):
                return [], []
            start_x_value = _safe_float(trace_config.get("start_x"))
            out_x: List[float] = []
            out_y: List[float] = []
            for x_val, y_val in zip(x_values, y_values):
                finite_x = _safe_float(x_val)
                finite_y = _safe_float(y_val)
                if finite_x is None or not math.isfinite(finite_x):
                    continue
                out_x.append(float(finite_x))
                if start_x_value is not None and finite_x < float(start_x_value):
                    out_y.append(float("nan"))
                elif finite_y is None or not math.isfinite(finite_y):
                    out_y.append(float("nan"))
                else:
                    out_y.append(float(finite_y))
            return out_x, out_y

        def _tag_timeline_artist(artist_obj: Any, trace_key: str) -> Any:
            """Attach Data Trace Settings metadata to one display artist.

            Purpose:
                Tag Matplotlib artists with the timeline series key.
            Why:
                Later Data Trace Settings discovery reads artist metadata from
                live figures to keep dialog rows tied to rendered traces.
            Inputs:
                artist_obj: Matplotlib artist to tag.
                trace_key: Timeline series identifier.
            Outputs:
                Any: The original artist reference, or None for missing input.
            Side Effects:
                Mutates the artist by setting `_gl260_series_key`.
            Exceptions:
                Metadata write failures are ignored safely.
            """
            if artist_obj is None:
                return None
            try:
                artist_obj._gl260_series_key = str(trace_key)
            except Exception:
                # Best-effort guard; ignore artist metadata failures.
                pass
            return artist_obj

        sodium_species = [
            ("timeline_naoh_pct", "NaOH (%)", naoh_vals, "#4c72b0"),
            ("timeline_na2co3_pct", "Na2CO3 (%)", na2co3_vals, "#dd8452"),
            ("timeline_nahco3_pct", "NaHCO3 (%)", nahco3_vals, "#55a868"),
        ]
        stack_inputs: List[List[float]] = []
        stack_colors: List[str] = []
        for trace_key, _label, values, fallback_color in sodium_species:
            trace_cfg = _timeline_trace_config(
                trace_key, _timeline_trace_defaults(trace_key)
            )
            start_x_value = _safe_float(trace_cfg.get("start_x"))
            prepared: List[float] = []
            for x_val, value in zip(xs, values):
                finite_x = _safe_float(x_val)
                finite_y = _safe_float(value, 0.0)
                if (
                    finite_x is None
                    or not math.isfinite(finite_x)
                    or not bool(trace_cfg.get("enabled", True))
                    or (start_x_value is not None and finite_x < float(start_x_value))
                ):
                    prepared.append(0.0)
                    continue
                prepared.append(max(0.0, float(finite_y)))
            stack_inputs.append(prepared)
            stack_colors.append(_timeline_trace_color(trace_cfg, fallback_color))
        stack_artists = ax.stackplot(xs, *stack_inputs, colors=stack_colors, alpha=0.35)
        for idx, artist in enumerate(list(stack_artists or [])):
            if idx < len(sodium_species):
                _tag_timeline_artist(artist, sodium_species[idx][0])
        # Draw line overlays on top of stacked fills so cycle-by-cycle shifts remain legible.
        for trace_key, fallback_label, values, fallback_color in sodium_species:
            trace_cfg = _timeline_trace_config(
                trace_key, _timeline_trace_defaults(trace_key)
            )
            plot_x, plot_y = _timeline_trace_line_points(trace_cfg, xs, values)
            if not plot_x:
                continue
            line_artist = ax.plot(
                plot_x,
                plot_y,
                label=_timeline_trace_label(trace_key, fallback_label),
                color=_timeline_trace_color(trace_cfg, fallback_color),
                linestyle=_timeline_trace_linestyle(trace_cfg, "solid"),
                marker=str(trace_cfg.get("marker") or "") or None,
                markersize=_timeline_trace_marker_size(trace_cfg, 4.0),
                linewidth=max(0.1, float(_safe_float(trace_cfg.get("linewidth"), 1.5))),
                zorder=float(_safe_float(trace_cfg.get("zorder"), 2.0)),
            )
            _tag_timeline_artist(line_artist[0] if line_artist else None, trace_key)
        species_min = prefs.get("species_min")
        species_max = prefs.get("species_max")
        if species_min is not None or species_max is not None:
            ax.set_ylim(
                species_min if species_min is not None else 0.0,
                species_max if species_max is not None else 100.0,
            )
        else:
            ax.set_ylim(0, 100)
        ax.grid(True, alpha=0.3)
        series_count = len(xs)
        marker_stride = (
            max(1, int(math.ceil(series_count / 120.0))) if series_count > 120 else None
        )
        eq_cfg = _timeline_trace_config(
            "timeline_equilibrium_ph",
            _timeline_trace_defaults("timeline_equilibrium_ph"),
        )
        eq_x, eq_y = _timeline_trace_line_points(eq_cfg, xs, ph_values)
        if eq_x:
            eq_artist = ax2.plot(
                eq_x,
                eq_y,
                color=_timeline_trace_color(eq_cfg, "#c44e52"),
                marker=str(eq_cfg.get("marker") or "o"),
                markevery=marker_stride,
                markersize=_timeline_trace_marker_size(
                    eq_cfg, 3.4 if marker_stride is not None else 4.0
                ),
                linewidth=max(0.1, float(_safe_float(eq_cfg.get("linewidth"), 1.5))),
                linestyle=_timeline_trace_linestyle(eq_cfg, "solid"),
                label=_timeline_trace_label(
                    "timeline_equilibrium_ph",
                    "Equilibrium pH (Guidance)",
                ),
                zorder=float(_safe_float(eq_cfg.get("zorder"), 3.0)),
            )
            _tag_timeline_artist(
                eq_artist[0] if eq_artist else None,
                "timeline_equilibrium_ph",
            )
        if workflow == "Analysis" and any(
            math.isfinite(value) for value in corrected_ph_values
        ):
            corrected_cfg = _timeline_trace_config(
                "timeline_corrected_ph",
                _timeline_trace_defaults("timeline_corrected_ph"),
            )
            corrected_x, corrected_y = _timeline_trace_line_points(
                corrected_cfg, xs, corrected_ph_values
            )
            if corrected_x:
                corrected_artist = ax2.plot(
                    corrected_x,
                    corrected_y,
                    color=_timeline_trace_color(corrected_cfg, "#9467bd"),
                    marker=str(corrected_cfg.get("marker") or "^"),
                    markevery=marker_stride,
                    markersize=_timeline_trace_marker_size(
                        corrected_cfg, 3.0 if marker_stride is not None else 3.8
                    ),
                    linewidth=max(
                        0.1,
                        float(_safe_float(corrected_cfg.get("linewidth"), 1.3)),
                    ),
                    linestyle=_timeline_trace_linestyle(corrected_cfg, "solid"),
                    label=_timeline_trace_label("timeline_corrected_ph", "Corrected pH"),
                    zorder=float(_safe_float(corrected_cfg.get("zorder"), 4.0)),
                )
                _tag_timeline_artist(
                    corrected_artist[0] if corrected_artist else None,
                    "timeline_corrected_ph",
                )
        if workflow == "Analysis" and any(
            math.isfinite(value) for value in calculated_raw_ph_values
        ):
            raw_calc_cfg = _timeline_trace_config(
                "timeline_calculated_ph_raw_co2",
                _timeline_trace_defaults("timeline_calculated_ph_raw_co2"),
            )
            raw_calc_x, raw_calc_y = _timeline_trace_line_points(
                raw_calc_cfg, xs, calculated_raw_ph_values
            )
            if raw_calc_x:
                raw_calc_artist = ax2.plot(
                    raw_calc_x,
                    raw_calc_y,
                    color=_timeline_trace_color(raw_calc_cfg, "#4e79a7"),
                    marker=str(raw_calc_cfg.get("marker") or "v"),
                    markevery=marker_stride,
                    markersize=_timeline_trace_marker_size(
                        raw_calc_cfg, 2.8 if marker_stride is not None else 3.5
                    ),
                    linewidth=max(
                        0.1,
                        float(_safe_float(raw_calc_cfg.get("linewidth"), 1.2)),
                    ),
                    linestyle=_timeline_trace_linestyle(raw_calc_cfg, "-."),
                    label=_timeline_trace_label(
                        "timeline_calculated_ph_raw_co2",
                        "Calculated pH (model)",
                    ),
                    zorder=float(_safe_float(raw_calc_cfg.get("zorder"), 3.2)),
                )
                _tag_timeline_artist(
                    raw_calc_artist[0] if raw_calc_artist else None,
                    "timeline_calculated_ph_raw_co2",
                )
        if workflow == "Analysis" and any(
            math.isfinite(value) for value in calculated_corrected_ph_values
        ):
            corrected_calc_cfg = _timeline_trace_config(
                "timeline_calculated_ph_corrected_co2",
                _timeline_trace_defaults("timeline_calculated_ph_corrected_co2"),
            )
            corrected_calc_x, corrected_calc_y = _timeline_trace_line_points(
                corrected_calc_cfg, xs, calculated_corrected_ph_values
            )
            if corrected_calc_x:
                corrected_calc_artist = ax2.plot(
                    corrected_calc_x,
                    corrected_calc_y,
                    color=_timeline_trace_color(corrected_calc_cfg, "#8f63b8"),
                    marker=str(corrected_calc_cfg.get("marker") or "1"),
                    markevery=marker_stride,
                    markersize=_timeline_trace_marker_size(
                        corrected_calc_cfg, 3.0 if marker_stride is not None else 3.8
                    ),
                    linewidth=max(
                        0.1,
                        float(_safe_float(corrected_calc_cfg.get("linewidth"), 1.2)),
                    ),
                    linestyle=_timeline_trace_linestyle(corrected_calc_cfg, "--"),
                    label=_timeline_trace_label(
                        "timeline_calculated_ph_corrected_co2",
                        "Calculated pH (corrected CO2)",
                    ),
                    zorder=float(_safe_float(corrected_calc_cfg.get("zorder"), 4.2)),
                )
                _tag_timeline_artist(
                    corrected_calc_artist[0] if corrected_calc_artist else None,
                    "timeline_calculated_ph_corrected_co2",
                )
        if workflow == "Analysis" and measured_anchor_x and measured_anchor_y:
            anchor_cfg = _timeline_trace_config(
                "timeline_measured_ph_anchor",
                _timeline_trace_defaults("timeline_measured_ph_anchor"),
            )
            anchor_x, anchor_y = _timeline_trace_line_points(
                anchor_cfg, measured_anchor_x, measured_anchor_y
            )
            if anchor_x:
                anchor_artist = ax2.scatter(
                    anchor_x,
                    anchor_y,
                    s=max(12.0, float(_safe_float(anchor_cfg.get("size"), 65.0))),
                    color=_timeline_trace_color(anchor_cfg, "#111111"),
                    marker=str(anchor_cfg.get("marker") or "X"),
                    linewidths=max(
                        0.0,
                        float(_safe_float(anchor_cfg.get("linewidth"), 0.6)),
                    ),
                    edgecolor="#f0f0f0",
                    label=_timeline_trace_label(
                        "timeline_measured_ph_anchor",
                        "Measured pH anchor",
                    ),
                    zorder=float(_safe_float(anchor_cfg.get("zorder"), 6.0)),
                )
                _tag_timeline_artist(anchor_artist, "timeline_measured_ph_anchor")
        use_uptake_line_mode = series_count > 400
        actual_cfg = _timeline_trace_config(
            "timeline_actual_cycle_co2",
            _timeline_trace_defaults("timeline_actual_cycle_co2"),
        )
        actual_x, actual_y = _timeline_trace_line_points(
            actual_cfg, xs, cycle_uptake_values
        )
        if actual_x and use_uptake_line_mode:
            actual_artist = ax3.plot(
                actual_x,
                actual_y,
                color=_timeline_trace_color(actual_cfg, "#8ecae6"),
                linewidth=max(
                    0.1, float(_safe_float(actual_cfg.get("linewidth"), 1.2))
                ),
                marker=str(actual_cfg.get("marker") or "o"),
                markevery=marker_stride,
                markersize=_timeline_trace_marker_size(
                    actual_cfg, 2.8 if marker_stride is not None else 3.5
                ),
                alpha=0.75,
                linestyle=_timeline_trace_linestyle(actual_cfg, "solid"),
                label=_timeline_trace_label(
                    "timeline_actual_cycle_co2",
                    "Actual cycle CO2 (g)",
                ),
                zorder=float(_safe_float(actual_cfg.get("zorder"), 2.0)),
            )
            _tag_timeline_artist(
                actual_artist[0] if actual_artist else None,
                "timeline_actual_cycle_co2",
            )
        elif actual_x:
            bar_x: List[float] = []
            bar_y: List[float] = []
            for x_value, y_value in zip(actual_x, actual_y):
                finite_y = _safe_float(y_value)
                if finite_y is None or not math.isfinite(finite_y):
                    continue
                bar_x.append(float(x_value))
                bar_y.append(float(finite_y))
            if bar_x:
                bar_container = ax3.bar(
                    bar_x,
                    bar_y,
                    width=0.55,
                    color=_timeline_trace_color(actual_cfg, timeline_bar_color),
                    alpha=timeline_bar_alpha,
                    label=_timeline_trace_label(
                        "timeline_actual_cycle_co2",
                        "Actual cycle CO2 (g)",
                    ),
                    zorder=float(_safe_float(actual_cfg.get("zorder"), 2.0)),
                )
                for patch_artist in list(bar_container.patches or []):
                    _tag_timeline_artist(patch_artist, "timeline_actual_cycle_co2")
        auto_current_state_x: Optional[float] = None
        auto_current_state_ph: Optional[float] = None
        auto_current_state_label: Optional[str] = None
        cycle_label_payloads: List[Dict[str, Any]] = []
        uptake_label_payloads: List[Dict[str, Any]] = []
        if workflow == "Analysis":
            cycle_pairs = [
                (x_val, _safe_float(entry.get("planning_cycle_ph")))
                for x_val, entry in zip(xs, timeline)
            ]
            cycle_pairs = [
                (x_val, ph_val)
                for x_val, ph_val in cycle_pairs
                if ph_val is not None and math.isfinite(ph_val)
            ]
            if cycle_pairs:
                ref_xs, ref_phs = zip(*cycle_pairs)
                ref_cycle_cfg = _timeline_trace_config(
                    "timeline_reference_ph_cycle",
                    _timeline_trace_defaults("timeline_reference_ph_cycle"),
                )
                ref_cycle_x, ref_cycle_y = _timeline_trace_line_points(
                    ref_cycle_cfg, list(ref_xs), list(ref_phs)
                )
                if ref_cycle_x:
                    ref_cycle_artist = ax2.plot(
                        ref_cycle_x,
                        ref_cycle_y,
                        color=_timeline_trace_color(ref_cycle_cfg, "#7a7a7a"),
                        alpha=0.75,
                        linestyle=_timeline_trace_linestyle(ref_cycle_cfg, "--"),
                        marker=str(ref_cycle_cfg.get("marker") or "s"),
                        markevery=marker_stride,
                        markersize=_timeline_trace_marker_size(
                            ref_cycle_cfg, 3.0 if marker_stride is not None else 4.0
                        ),
                        linewidth=max(
                            0.1,
                            float(_safe_float(ref_cycle_cfg.get("linewidth"), 1.4)),
                        ),
                        label=_timeline_trace_label(
                            "timeline_reference_ph_cycle",
                            "Reference pH (cycle)",
                        ),
                        zorder=float(_safe_float(ref_cycle_cfg.get("zorder"), 2.0)),
                    )
                    _tag_timeline_artist(
                        ref_cycle_artist[0] if ref_cycle_artist else None,
                        "timeline_reference_ph_cycle",
                    )
            aligned_pairs = [
                (
                    x_val,
                    _safe_float(entry.get("planning_co2_aligned_ph")),
                )
                for x_val, entry in zip(xs, timeline)
            ]
            aligned_pairs = [
                (x_val, ph_val)
                for x_val, ph_val in aligned_pairs
                if ph_val is not None and math.isfinite(ph_val)
            ]
            if aligned_pairs:
                aligned_xs, aligned_phs = zip(*aligned_pairs)
                ref_align_cfg = _timeline_trace_config(
                    "timeline_reference_ph_co2_aligned",
                    _timeline_trace_defaults("timeline_reference_ph_co2_aligned"),
                )
                ref_align_x, ref_align_y = _timeline_trace_line_points(
                    ref_align_cfg, list(aligned_xs), list(aligned_phs)
                )
                if ref_align_x:
                    ref_align_artist = ax2.plot(
                        ref_align_x,
                        ref_align_y,
                        color=_timeline_trace_color(ref_align_cfg, "#2f4b7c"),
                        linestyle=_timeline_trace_linestyle(ref_align_cfg, ":"),
                        linewidth=max(
                            0.1,
                            float(_safe_float(ref_align_cfg.get("linewidth"), 1.2)),
                        ),
                        marker=str(ref_align_cfg.get("marker") or "."),
                        markevery=marker_stride,
                        markersize=_timeline_trace_marker_size(ref_align_cfg, 2.8),
                        label=_timeline_trace_label(
                            "timeline_reference_ph_co2_aligned",
                            "Reference pH (CO2 aligned)",
                        ),
                        zorder=float(_safe_float(ref_align_cfg.get("zorder"), 3.0)),
                    )
                    _tag_timeline_artist(
                        ref_align_artist[0] if ref_align_artist else None,
                        "timeline_reference_ph_co2_aligned",
                    )
            if any(math.isfinite(value) for value in planning_cycle_uptake_values):
                plan_cfg = _timeline_trace_config(
                    "timeline_planning_cycle_co2",
                    _timeline_trace_defaults("timeline_planning_cycle_co2"),
                )
                plan_x, plan_y = _timeline_trace_line_points(
                    plan_cfg, xs, planning_cycle_uptake_values
                )
                if plan_x:
                    plan_artist = ax3.plot(
                        plan_x,
                        plan_y,
                        color=_timeline_trace_color(plan_cfg, "#1b7b6b"),
                        linewidth=max(
                            0.1,
                            float(_safe_float(plan_cfg.get("linewidth"), 1.3)),
                        ),
                        marker=str(plan_cfg.get("marker") or "D"),
                        markevery=marker_stride,
                        markersize=_timeline_trace_marker_size(
                            plan_cfg, 3.0 if marker_stride is not None else 3.5
                        ),
                        linestyle=_timeline_trace_linestyle(plan_cfg, "solid"),
                        label=_timeline_trace_label(
                            "timeline_planning_cycle_co2",
                            "Planning cycle CO2 (g)",
                        ),
                        zorder=float(_safe_float(plan_cfg.get("zorder"), 3.0)),
                    )
                    _tag_timeline_artist(
                        plan_artist[0] if plan_artist else None,
                        "timeline_planning_cycle_co2",
                    )
            if any(math.isfinite(value) for value in corrected_cycle_uptake_values):
                corrected_cycle_cfg = _timeline_trace_config(
                    "timeline_corrected_cycle_co2",
                    _timeline_trace_defaults("timeline_corrected_cycle_co2"),
                )
                corrected_cycle_x, corrected_cycle_y = _timeline_trace_line_points(
                    corrected_cycle_cfg, xs, corrected_cycle_uptake_values
                )
                if corrected_cycle_x:
                    corrected_cycle_artist = ax3.plot(
                        corrected_cycle_x,
                        corrected_cycle_y,
                        color=_timeline_trace_color(corrected_cycle_cfg, "#7a5195"),
                        linewidth=max(
                            0.1,
                            float(
                                _safe_float(
                                    corrected_cycle_cfg.get("linewidth"), 1.4
                                )
                            ),
                        ),
                        marker=str(corrected_cycle_cfg.get("marker") or "P"),
                        markevery=marker_stride,
                        markersize=_timeline_trace_marker_size(
                            corrected_cycle_cfg,
                            2.8 if marker_stride is not None else 3.4,
                        ),
                        linestyle=_timeline_trace_linestyle(
                            corrected_cycle_cfg, "solid"
                        ),
                        label=_timeline_trace_label(
                            "timeline_corrected_cycle_co2",
                            "Corrected cycle CO2 (g)",
                        ),
                        zorder=float(
                            _safe_float(corrected_cycle_cfg.get("zorder"), 4.0)
                        ),
                    )
                    _tag_timeline_artist(
                        corrected_cycle_artist[0] if corrected_cycle_artist else None,
                        "timeline_corrected_cycle_co2",
                    )
            marker = getattr(self, "_analysis_overlay_marker", None) or {}
            marker_resolver = getattr(
                self,
                "_resolve_cycle_timeline_current_state_marker",
                None,
            )
            if callable(marker_resolver):
                marker_payload = marker_resolver(
                    timeline,
                    xs,
                    marker,
                )
            else:
                marker_payload = (
                    UnifiedApp._resolve_cycle_timeline_current_state_marker(
                        self,
                        timeline,
                        xs,
                        marker,
                    )
                )
            current_state_cfg = _timeline_trace_config(
                "timeline_current_state",
                _timeline_trace_defaults("timeline_current_state"),
            )
            if marker_payload is not None and bool(
                current_state_cfg.get("enabled", True)
            ):
                auto_current_state_x = float(marker_payload["x"])
                auto_current_state_ph = float(marker_payload["ph"])
                auto_current_state_label = str(marker_payload["label"])
            annotate_step = max(1, int(max(len(timeline), 1) / 12))
            for idx, (x_val, uptake_val, entry) in enumerate(
                zip(xs, cycle_uptake_values, timeline)
            ):
                if idx % annotate_step != 0:
                    continue
                if uptake_val is None or not math.isfinite(uptake_val):
                    continue
                uptake_label_payloads.append(
                    {
                        "id_suffix": f"{idx}_{entry.get('cycle_id')}",
                        "x": float(x_val),
                        "y": float(uptake_val),
                        "text": f"{float(uptake_val):.2f} g",
                    }
                )
        max_uptake = max(
            [0.25]
            + [float(value) for value in cycle_uptake_values]
            + [
                float(value)
                for value in corrected_cycle_uptake_values
                if value is not None and math.isfinite(value)
            ]
        )
        max_plan_uptake = max(
            [0.0]
            + [
                float(value)
                for value in planning_cycle_uptake_values
                if value is not None and math.isfinite(value)
            ]
        )
        ax3.set_ylim(0.0, max(max_uptake, max_plan_uptake) * 1.25)
        ph_min = prefs.get("ph_min")
        ph_max = prefs.get("ph_max")
        if ph_min is not None or ph_max is not None:
            ax2.set_ylim(
                ph_min if ph_min is not None else 6.0,
                ph_max if ph_max is not None else 15.5,
            )
        else:
            ax2.set_ylim(6.0, 15.5)
        if target_ph is not None:
            ax2.axhline(target_ph, color="#2a9d8f", linestyle="--", linewidth=1.25)
            ax2.text(
                0.98,
                target_ph,
                f"Target pH {target_ph:.2f}",
                va="bottom",
                ha="right",
                fontsize=7,
                color="#2a9d8f",
            )
        # Keep pH label density bounded so dense timelines stay responsive.
        ph_label_budget = min(120, max(len(xs), 1))
        ph_label_step = max(1, int(math.ceil(max(len(xs), 1) / float(ph_label_budget))))
        for idx, (x, ph, entry) in enumerate(zip(xs, ph_values, timeline)):
            if idx % ph_label_step != 0:
                continue
            if not math.isfinite(ph):
                continue
            cycle_label_payloads.append(
                {
                    "id_suffix": f"{idx}_{entry.get('cycle_id')}",
                    "x": float(x),
                    "y": float(ph),
                    "text": f"{entry.get('cycle_id')}",
                }
            )
        selected_cycle_id = self._analysis_dashboard_selected_cycle_id()
        if selected_cycle_id is not None:
            try:
                selected_x = float(selected_cycle_id)
            except Exception:
                selected_x = None
            if selected_x is not None:
                ax.axvline(selected_x, color="#444444", linewidth=1.0, alpha=0.35)
                ax2.axvline(selected_x, color="#444444", linewidth=1.0, alpha=0.35)
        eq_cycle = _safe_float(
            ((getattr(self, "_analysis_dashboard_data", None) or {}).get("summary") or {}).get(
                "equivalence_cycle_actual"
            )
        )
        if eq_cycle is not None:
            ax.axvline(eq_cycle, color="#f28e2b", linestyle="--", linewidth=1.0)
            ax2.axvline(eq_cycle, color="#f28e2b", linestyle="--", linewidth=1.0)
        apply_x_range = getattr(self, "_apply_cycle_timeline_x_axis_range", None)
        if callable(apply_x_range):
            apply_x_range((ax, ax2, ax3), xs, prefs)
        try:
            self._upsert_cycle_timeline_auto_label_plot_elements(
                fig=ax.figure,
                cycle_axis=ax2,
                uptake_axis=ax3,
                cycle_labels=cycle_label_payloads,
                uptake_labels=uptake_label_payloads,
                cycle_fontsize=7.0,
                uptake_fontsize=timeline_bar_label_fontsize,
                uptake_color=timeline_bar_label_color,
            )
        except Exception:
            # Best-effort guard; label overlays should not block timeline rendering.
            pass
        try:
            self._upsert_cycle_timeline_auto_current_state_plot_element(
                marker_x=auto_current_state_x,
                marker_ph=auto_current_state_ph,
                label_text=auto_current_state_label,
                axis=ax2,
            )
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        show_main_legend = bool(prefs.get("show_main_legend", True))
        UnifiedApp._build_cycle_timeline_subplot_legends(
            self,
            fig=ax.figure,
            ax=ax,
            ax2=ax2,
            ax3=ax3,
            show_main_legend=show_main_legend,
            preview_interactive_legend=False,
            update_session_refs=True,
        )
        layout_verify_fn = getattr(
            self, "_run_cycle_timeline_layout_manager_verification", None
        )
        if callable(layout_verify_fn):
            layout_verify_fn(
                ax.figure,
                mode="display",
                prefs=prefs,
                show_splash=True,
                splash_message="Verifying cycle timeline layout...",
                splash_detail=(
                    "Checking legend/label spacing before updating the rendered timeline."
                ),
            )
        self._ensure_cycle_timeline_annotation_controller()
        canvas.draw_idle()
        self._dbg(
            "plotting.render",
            "cycle_timeline_plot_done workflow=%s timeline_rows=%s",
            workflow,
            timeline_row_count,
        )

        if skip_callout:
            self._refresh_cycle_comparison_explorer()
            try:
                self._refresh_sol_workflow_layout()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            self._dbg(
                "plotting.render",
                "cycle_timeline_ui_done workflow=%s timeline_rows=%s",
                workflow,
                timeline_row_count,
            )
            return

        callout = getattr(self, "_sol_cycle_callouts", None)
        if callout is None:
            self._dbg(
                "plotting.render",
                "cycle_timeline_ui_done workflow=%s timeline_rows=%s stage=no_callout_widget",
                workflow,
                timeline_row_count,
            )
            return
        try:
            view_state = callout.yview()
            visible_span = view_state[1] - view_state[0]
            stick_to_bottom = (1.0 - view_state[1]) <= max(0.02, visible_span * 0.25)
            preserve_top = view_state[0]
        except Exception:
            stick_to_bottom = True
            preserve_top = 0.0
        callout.configure(state="normal")
        callout.delete("1.0", "end")
        callout_lines = list(payload_map.get("callout_lines") or [])
        for line in callout_lines or ["No cycle speciation data available."]:
            callout.insert("end", f"{line}\n")
        callout.configure(state="disabled")
        try:
            if stick_to_bottom:
                callout.see("end")
            else:
                callout.yview_moveto(preserve_top)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        self._refresh_cycle_comparison_explorer()
        try:
            self._refresh_sol_workflow_layout()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        self._dbg(
            "plotting.render",
            "cycle_timeline_ui_done workflow=%s timeline_rows=%s",
            workflow,
            timeline_row_count,
        )

    def _resize_cycle_timeline_tree(self, row_count: int) -> None:
        """Perform resize cycle timeline tree.
        Used to keep the workflow logic localized and testable."""
        tree = getattr(self, "_sol_cycle_timeline_tree", None)
        if tree is None:
            return
        try:
            current_height = int(tree.cget("height"))
        except Exception:
            current_height = 8
        try:
            base_height = 8
            max_height = 28
            desired = base_height if row_count <= 0 else min(max_height, row_count + 2)
            if row_count > 0:
                desired = max(desired, current_height)
            tree.configure(height=desired)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _set_timeline_action_state(self, enabled: bool) -> None:
        """Enable or disable cycle timeline action buttons.

        Purpose:
            Keep timeline export, preview, layout, and editing buttons aligned
            with whether Analysis/Reprocessing timeline data is available.
        Why:
            Disabled actions prevent users from opening empty timeline surfaces
            before a workflow produces renderable results.
        Inputs:
            enabled: True to enable timeline actions, False to disable them.
        Outputs:
            None.
        Side Effects:
            Mutates Tk button states for timeline actions when those buttons exist.
        Exceptions:
            Widget update failures are ignored per button.
        """
        state = "normal" if enabled else "disabled"
        # Iterate to apply the per-item logic.
        for attr in (
            "_sol_cycle_export_csv_btn",
            "_sol_cycle_export_workbook_btn",
            "_sol_cycle_preview_plot_btn",
            "_sol_cycle_trace_settings_btn",
            "_sol_cycle_open_tab_btn",
            "_sol_cycle_layout_manager_btn",
            "_sol_cycle_layout_health_btn",
            "_sol_cycle_export_plot_btn",
            "_sol_cycle_export_table_btn",
            "_sol_cycle_plot_elements_btn",
            "_sol_cycle_expand_btn",
        ):
            btn = getattr(self, attr, None)
            if btn is None:
                continue
            try:
                btn.configure(state=state)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

    def _scroll_callouts_to_latest(self) -> None:
        """Perform scroll callouts to latest.
        Used to keep the workflow logic localized and testable."""
        callout = getattr(self, "_sol_cycle_callouts", None)
        if callout is None:
            return
        try:
            callout.see("end")
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _get_current_timeline_table_data(
        self,
    ) -> Tuple[List[str], List[List[Any]], List[str]]:
        """Return current timeline table data.
        Used to retrieve current timeline table data for downstream logic."""
        full_columns = list(getattr(self, "_sol_cycle_timeline_full_columns", ()))
        full_headers = list(getattr(self, "_sol_cycle_timeline_full_headers", ()))
        full_rows = list(getattr(self, "_sol_cycle_timeline_full_rows", ()))
        if full_columns and full_headers and full_rows:
            return full_headers, full_rows, full_columns
        tree = getattr(self, "_sol_cycle_timeline_tree", None)
        column_ids = list(getattr(self, "_sol_cycle_timeline_columns", ()))
        if tree is None or not column_ids:
            return [], [], []
        headers: List[str] = []
        # Iterate over column_ids to apply the per-item logic.
        for col in column_ids:
            try:
                label = tree.heading(col).get("text") or str(col)
            except Exception:
                label = str(col)
            headers.append(label)
        rows: List[List[Any]] = []
        try:
            children = tree.get_children("")
        except Exception:
            children = []
        # Iterate over children to apply the per-item logic.
        for iid in children:
            try:
                values = list(tree.item(iid).get("values", []))
            except Exception:
                values = []
            padded = values + [""] * (len(column_ids) - len(values))
            rows.append(padded[: len(column_ids)])
        return headers, rows, column_ids

    def _open_timeline_export_options(self) -> None:
        """Open timeline export options.
        Used by UI actions to open timeline export options."""
        headers, _rows, column_ids = self._get_current_timeline_table_data()
        if not column_ids:
            try:
                messagebox.showinfo(
                    "Cycle Speciation Timeline",
                    "Timeline columns are unavailable until a workflow is run.",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        existing = getattr(self, "_timeline_export_opts_win", None)
        if existing is not None and existing.winfo_exists():
            existing.deiconify()
            existing.lift()
            return

        settings_ref = self._settings_dict()
        enabled_map = settings_ref.get("timeline_table_columns_enabled")
        if not isinstance(enabled_map, dict):
            enabled_map = {}
        normalized_map = {
            col_id: bool(enabled_map.get(col_id, True)) for col_id in column_ids
        }
        orientation = settings_ref.get("timeline_table_export_orientation", "portrait")
        if orientation not in {"portrait", "landscape"}:
            orientation = "portrait"
        acs_quality = bool(settings_ref.get("timeline_table_export_acs_quality", False))

        window = tk.Toplevel(self)
        window.title("Timeline Table Export Options")
        window.transient(self)
        window.resizable(False, False)
        window.protocol("WM_DELETE_WINDOW", window.destroy)
        self._timeline_export_opts_win = window

        container = ttk.Frame(window, padding=10)
        container.grid(row=0, column=0, sticky="nsew")
        container.columnconfigure(0, weight=1)

        ttk.Label(container, text="Select columns to include:").grid(
            row=0, column=0, sticky="w"
        )
        columns_frame = ttk.Frame(container)
        columns_frame.grid(row=1, column=0, sticky="w", pady=(4, 8))

        vars_by_id: Dict[str, tk.BooleanVar] = {}
        # Iterate over indexed elements from zip(column_ids, headers to apply the per-item logic.
        for idx, (col_id, header) in enumerate(zip(column_ids, headers)):
            var = tk.BooleanVar(value=normalized_map.get(col_id, True))
            vars_by_id[col_id] = var
            ttk.Checkbutton(columns_frame, text=header, variable=var).grid(
                row=idx, column=0, sticky="w", pady=2
            )

        ttk.Label(container, text="Page orientation:").grid(row=2, column=0, sticky="w")
        orientation_var = tk.StringVar(value=orientation)
        orientation_frame = ttk.Frame(container)
        orientation_frame.grid(row=3, column=0, sticky="w", pady=(4, 8))
        ttk.Radiobutton(
            orientation_frame,
            text="Portrait (8.5 x 11 in)",
            value="portrait",
            variable=orientation_var,
        ).grid(row=0, column=0, sticky="w", pady=2)
        ttk.Radiobutton(
            orientation_frame,
            text="Landscape (11 x 8.5 in)",
            value="landscape",
            variable=orientation_var,
        ).grid(row=1, column=0, sticky="w", pady=2)

        acs_var = tk.BooleanVar(value=acs_quality)
        ttk.Checkbutton(
            container,
            text="ACS publication-quality styling",
            variable=acs_var,
        ).grid(row=4, column=0, sticky="w", pady=(2, 8))

        button_frame = ttk.Frame(container)
        button_frame.grid(row=5, column=0, sticky="e")

        # Closure captures _open_timeline_export_options state for callback wiring, kept nested to scope the handler, and invoked by bindings set in _open_timeline_export_options.
        def _apply() -> None:
            """Apply value.
            Used to apply value changes to live state."""
            new_map = {col_id: var.get() for col_id, var in vars_by_id.items()}
            if not any(new_map.values()):
                try:
                    messagebox.showwarning(
                        "Timeline Export Options",
                        "Select at least one column to export.",
                    )
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
                return
            settings_ref["timeline_table_columns_enabled"] = new_map
            settings_ref["timeline_table_export_orientation"] = orientation_var.get()
            settings_ref["timeline_table_export_acs_quality"] = bool(acs_var.get())
            try:
                self._schedule_save_settings()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                window.destroy()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

        ttk.Button(button_frame, text="Cancel", command=window.destroy).grid(
            row=0, column=0, padx=4
        )
        ttk.Button(button_frame, text="Apply", command=_apply).grid(
            row=0, column=1, padx=4
        )

    def _open_simulation_export_workbook_options(self) -> None:
        """Open workbook export options for simulation timeline appends.

        Purpose:
            Configure workbook path, sheet mapping, and auto-export behavior.
        Why:
            v4.12.1 workbook export supports active workflow appends and optional
            auto-export after successful simulation completion.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Opens a modal options dialog and persists settings changes.
        Exceptions:
            Best-effort guards suppress widget/dialog failures.
        """
        existing = getattr(self, "_simulation_export_opts_win", None)
        if existing is not None and existing.winfo_exists():
            existing.deiconify()
            existing.lift()
            return
        mapping = self._simulation_export_workbook_mapping_settings()
        workbook_var = tk.StringVar(value=str(mapping.get("workbook_path") or ""))
        auto_export_var = tk.BooleanVar(value=bool(mapping.get("auto_export_enabled", False)))
        include_metadata_var = tk.BooleanVar(value=bool(mapping.get("include_metadata", True)))
        sheet_map = dict(mapping.get("per_workflow_sheet_map") or {})
        sheet_vars = {
            key: tk.StringVar(
                value=str(
                    sheet_map.get(
                        key,
                        SIMULATION_EXPORT_DEFAULT_WORKFLOW_SHEET_MAP.get(key, "Simulation Data"),
                    )
                    or ""
                )
            )
            for key in SIMULATION_EXPORT_WORKFLOW_KEYS
        }

        window = tk.Toplevel(self)
        window.title("Simulation Workbook Export Options")
        window.transient(self)
        window.resizable(False, False)
        window.protocol("WM_DELETE_WINDOW", window.destroy)
        self._simulation_export_opts_win = window

        body = ttk.Frame(window, padding=12)
        body.grid(row=0, column=0, sticky="nsew")
        body.grid_columnconfigure(1, weight=1)
        ttk.Label(body, text="Destination Workbook").grid(row=0, column=0, sticky="w", pady=3)
        _ui_entry(body, textvariable=workbook_var).grid(row=0, column=1, sticky="ew", pady=3)

        def _browse_workbook() -> None:
            """Prompt user for export destination workbook path."""
            candidate = filedialog.askopenfilename(
                title="Select Master Workbook",
                filetypes=[("Excel files", "*.xlsx *.xlsm *.xltx *.xltm")],
            )
            if candidate:
                workbook_var.set(candidate)

        _ui_button(body, text="Browse...", command=_browse_workbook).grid(
            row=0, column=2, padx=(8, 0), pady=3
        )
        _ui_checkbutton(
            body,
            text="Enable auto-export on successful simulation run",
            variable=auto_export_var,
        ).grid(row=1, column=0, columnspan=3, sticky="w", pady=(8, 3))
        _ui_checkbutton(
            body,
            text="Include export metadata columns",
            variable=include_metadata_var,
        ).grid(row=2, column=0, columnspan=3, sticky="w", pady=3)

        ttk.Label(
            body,
            text="Workflow Sheet Mapping",
            font=(self._ui_font_family if hasattr(self, "_ui_font_family") else "Segoe UI", 10, "bold"),
        ).grid(row=3, column=0, columnspan=3, sticky="w", pady=(10, 4))
        start_row = 4
        for idx, workflow_key in enumerate(SIMULATION_EXPORT_WORKFLOW_KEYS):
            ttk.Label(body, text=f"{workflow_key}").grid(
                row=start_row + idx, column=0, sticky="w", pady=2
            )
            _ui_entry(body, textvariable=sheet_vars[workflow_key]).grid(
                row=start_row + idx, column=1, columnspan=2, sticky="ew", pady=2
            )

        footer = ttk.Frame(body)
        footer.grid(row=start_row + len(SIMULATION_EXPORT_WORKFLOW_KEYS), column=0, columnspan=3, sticky="e", pady=(12, 0))

        def _apply_options() -> None:
            """Persist workbook export options and close dialog."""
            next_mapping = dict(mapping)
            next_mapping["workbook_path"] = str(workbook_var.get() or "").strip()
            next_mapping["auto_export_enabled"] = bool(auto_export_var.get())
            next_mapping["include_metadata"] = bool(include_metadata_var.get())
            next_mapping["per_workflow_sheet_map"] = {
                key: _normalize_simulation_export_sheet_label(
                    sheet_vars[key].get(),
                    fallback=SIMULATION_EXPORT_DEFAULT_WORKFLOW_SHEET_MAP.get(key, "Simulation Data"),
                )
                for key in SIMULATION_EXPORT_WORKFLOW_KEYS
            }
            settings_ref = self._settings_dict()
            settings_ref[SIMULATION_EXPORT_WORKBOOK_COLUMN_MAPPING_SETTINGS_KEY] = (
                _normalize_simulation_export_workbook_mapping_payload(next_mapping)
            )
            try:
                self._schedule_save_settings()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                window.destroy()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

        ttk.Button(footer, text="Cancel", command=window.destroy).grid(row=0, column=0, padx=4)
        ttk.Button(footer, text="Apply", command=_apply_options).grid(row=0, column=1, padx=4)

    def _open_timeline_viewer(self) -> None:
        """Open timeline viewer.
        Used by UI actions to open timeline viewer."""

        headers, rows, column_ids = self._get_current_timeline_table_data()
        if not rows:
            try:
                messagebox.showinfo(
                    "Cycle Speciation Timeline",
                    "Run a workflow to generate timeline results before expanding the table.",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        window = tk.Toplevel(self)
        window.title("Cycle Speciation Timeline Viewer")
        window.geometry("1100x600")
        container = ttk.Frame(window)
        container.pack(fill="both", expand=True, padx=8, pady=8)
        container.grid_rowconfigure(0, weight=1)
        container.grid_columnconfigure(0, weight=1)
        tree = ttk.Treeview(
            container, columns=column_ids, show="headings", height=min(len(rows), 20)
        )
        # Iterate over paired elements from multiple sequences to apply the per-item logic.
        for col_id, header in zip(column_ids, headers):
            tree.heading(col_id, text=header)
            tree.column(col_id, anchor="center", width=140)
        yscroll = ttk.Scrollbar(container, orient="vertical", command=tree.yview)
        xscroll = ttk.Scrollbar(container, orient="horizontal", command=tree.xview)
        tree.configure(yscrollcommand=yscroll.set, xscrollcommand=xscroll.set)
        tree.grid(row=0, column=0, sticky="nsew")
        yscroll.grid(row=0, column=1, sticky="ns")
        xscroll.grid(row=1, column=0, sticky="ew")
        # Iterate over rows to apply the per-item logic.
        for row in rows:
            tree.insert("", "end", values=row)
        try:
            window.transient(self)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        window.focus_set()

    def _normalize_cycle_timeline_subplot_style_prefs(
        self, prefs_source: Optional[Mapping[str, Any]] = None
    ) -> Dict[str, Any]:
        """Normalize cycle-timeline subplot style preferences.

        Purpose:
            Sanitize bottom-subplot styling keys stored under `cycle_plot_prefs`.
        Why:
            Timeline styling controls accept free-form user input and legacy
            settings payloads, so rendering paths need one deterministic
            normalization contract.
        Inputs:
            prefs_source: Optional preference mapping containing timeline style keys.
        Outputs:
            Dict[str, Any]: Normalized style payload with validated values for:
            `timeline_bar_color`, `timeline_bar_alpha`,
            `timeline_bar_label_fontsize`, and `timeline_bar_label_color`.
        Side Effects:
            None.
        Exceptions:
            Invalid values fall back to stable defaults.
        """
        source = prefs_source if isinstance(prefs_source, Mapping) else {}
        bar_color_raw = str(source.get("timeline_bar_color") or "").strip()
        bar_color = DEFAULT_CYCLE_TIMELINE_BAR_COLOR
        if bar_color_raw:
            try:
                from matplotlib import colors as mcolors

                if mcolors.is_color_like(bar_color_raw):
                    bar_color = _normalize_mpl_color(bar_color_raw) or ""
            except Exception:
                normalized_candidate = _normalize_mpl_color(bar_color_raw)
                bar_color = (
                    normalized_candidate
                    if normalized_candidate
                    else DEFAULT_CYCLE_TIMELINE_BAR_COLOR
                )
        bar_alpha = _safe_float(
            source.get("timeline_bar_alpha"),
            DEFAULT_CYCLE_TIMELINE_BAR_ALPHA,
        )
        if bar_alpha is None or not math.isfinite(bar_alpha):
            bar_alpha = DEFAULT_CYCLE_TIMELINE_BAR_ALPHA
        bar_alpha = max(0.0, min(1.0, float(bar_alpha)))
        bar_label_fontsize = _safe_float(
            source.get("timeline_bar_label_fontsize"),
            DEFAULT_CYCLE_TIMELINE_BAR_LABEL_FONTSIZE,
        )
        if bar_label_fontsize is None or not math.isfinite(bar_label_fontsize):
            bar_label_fontsize = DEFAULT_CYCLE_TIMELINE_BAR_LABEL_FONTSIZE
        bar_label_fontsize = max(4.0, min(48.0, float(bar_label_fontsize)))
        bar_label_color_raw = str(source.get("timeline_bar_label_color") or "").strip()
        bar_label_color = DEFAULT_CYCLE_TIMELINE_BAR_LABEL_COLOR
        if bar_label_color_raw:
            try:
                from matplotlib import colors as mcolors

                if mcolors.is_color_like(bar_label_color_raw):
                    bar_label_color = (
                        _normalize_mpl_color(bar_label_color_raw)
                        or DEFAULT_CYCLE_TIMELINE_BAR_LABEL_COLOR
                    )
            except Exception:
                normalized_label_color = _normalize_mpl_color(bar_label_color_raw)
                if normalized_label_color:
                    bar_label_color = normalized_label_color
        return {
            "timeline_bar_color": str(bar_color),
            "timeline_bar_alpha": float(bar_alpha),
            "timeline_bar_label_fontsize": float(bar_label_fontsize),
            "timeline_bar_label_color": str(bar_label_color),
        }

    def _normalize_cycle_timeline_legend_layout_prefs(
        self, prefs_source: Optional[Mapping[str, Any]] = None
    ) -> Dict[str, Any]:
        """Normalize cycle-timeline legend wrapping and row preferences.

        Purpose:
            Sanitize the top/bottom timeline legend layout keys stored under
            `cycle_plot_prefs`.
        Why:
            Generated-tab Plot Settings and focused Cycle Timeline settings both
            need the same legend row/wrap contract used by rendering paths.
        Inputs:
            prefs_source: Optional preference mapping containing legend layout keys.
        Outputs:
            Dict with boolean wrap flags and clamped row counts for both timeline
            subplot legends.
        Side Effects:
            None.
        Exceptions:
            Invalid values fall back to stable defaults.
        """
        source = prefs_source if isinstance(prefs_source, Mapping) else {}

        def _rows_for(key: str) -> int:
            """Return a clamped legend row count from one preference key."""
            try:
                rows_value = int(source.get(key, 2))
            except Exception:
                rows_value = 2
            return max(1, min(8, rows_value))

        return {
            "timeline_top_legend_wrap": bool(
                source.get("timeline_top_legend_wrap", False)
            ),
            "timeline_top_legend_rows": _rows_for("timeline_top_legend_rows"),
            "timeline_bottom_legend_wrap": bool(
                source.get("timeline_bottom_legend_wrap", False)
            ),
            "timeline_bottom_legend_rows": _rows_for("timeline_bottom_legend_rows"),
        }

    def _cycle_timeline_legend_layout_for_role(
        self,
        labels: Sequence[str],
        *,
        role: str,
        default_ncol: Optional[int] = None,
        prefs: Optional[Mapping[str, Any]] = None,
    ) -> Tuple[List[str], Optional[int], bool, int]:
        """Return labels and column count for one timeline subplot legend.

        Purpose:
            Apply combined-style row and wrapping settings to timeline legends.
        Why:
            Display, generated tabs, preview, and export must interpret timeline
            legend layout preferences identically.
        Inputs:
            labels: Legend labels before optional wrapping.
            role: Legend role (`top` or `bottom`).
            default_ncol: Column count used when wrapping is disabled.
            prefs: Optional cycle timeline preferences.
        Outputs:
            Tuple of `(labels, ncol, wrap_enabled, rows)` for legend creation.
        Side Effects:
            None.
        Exceptions:
            Invalid preferences are normalized by fallback defaults.
        """
        normalized_role = (
            "bottom" if str(role or "").strip().lower() == "bottom" else "top"
        )
        if isinstance(prefs, Mapping):
            prefs_map = prefs
        else:
            prefs_reader = getattr(self, "_get_cycle_plot_prefs", None)
            prefs_map = prefs_reader() if callable(prefs_reader) else {}
        layout = UnifiedApp._normalize_cycle_timeline_legend_layout_prefs(
            self, prefs_map
        )
        wrap_key = f"timeline_{normalized_role}_legend_wrap"
        rows_key = f"timeline_{normalized_role}_legend_rows"
        wrap_enabled = bool(layout.get(wrap_key, False))
        rows = max(1, int(layout.get(rows_key, 2)))
        resolved_labels = [str(label) for label in labels]
        if not wrap_enabled:
            return resolved_labels, default_ncol, False, rows
        resolved_labels = [_wrap_legend_label(label) for label in resolved_labels]
        ncol = max(1, int(math.ceil(max(1, len(resolved_labels)) / float(rows))))
        return resolved_labels, ncol, True, rows

    def _merge_cycle_timeline_plot_settings_prefs(
        self,
        base_prefs: Mapping[str, Any],
        *,
        subplot_style: Optional[Mapping[str, Any]] = None,
        legend_layout: Optional[Mapping[str, Any]] = None,
    ) -> Dict[str, Any]:
        """Merge staged Cycle Timeline Plot Settings into full preferences.

        Purpose:
            Apply Plot Settings dialog changes without dropping unrelated timeline
            preference keys.
        Why:
            Timeline trace settings, axis ranges, titles, and layout-manager state
            live in the same `cycle_plot_prefs` mapping as subplot style controls.
        Inputs:
            base_prefs: Existing full cycle timeline preferences.
            subplot_style: Optional staged bottom-subplot style controls.
            legend_layout: Optional staged legend layout controls.
        Outputs:
            Full preference mapping with only supplied staged sections updated.
        Side Effects:
            None.
        Exceptions:
            Invalid staged values are normalized to safe defaults.
        """
        merged = dict(base_prefs or {})
        if isinstance(subplot_style, Mapping):
            merged.update(
                self._normalize_cycle_timeline_subplot_style_prefs(subplot_style)
            )
        if isinstance(legend_layout, Mapping):
            if "bottom_legend_center_below_xlabel" in legend_layout:
                merged["bottom_legend_center_below_xlabel"] = bool(
                    legend_layout.get("bottom_legend_center_below_xlabel", False)
                )
            legend_source = dict(merged)
            legend_source.update(dict(legend_layout))
            merged.update(
                self._normalize_cycle_timeline_legend_layout_prefs(legend_source)
            )
        merged["bottom_legend_center_below_xlabel"] = bool(
            merged.get("bottom_legend_center_below_xlabel", False)
        )
        return merged

    def _get_cycle_plot_prefs(self) -> Dict[str, Any]:
        """Return normalized cycle timeline plotting preferences.

        Purpose:
            Resolve one canonical preference payload for cycle timeline rendering.
        Why:
            Timeline renderers and dialogs share settings state that must remain
            backward-compatible with legacy snapshots and deterministic across
            refresh/restart boundaries.
        Inputs:
            None.
        Outputs:
            Dict[str, Any]: Normalized cycle timeline preferences.
        Side Effects:
            Persists normalized preference state back into runtime settings and
            schedules settings-save callbacks.
        Exceptions:
            Settings persistence failures are guarded to keep UI flows responsive.
        """
        default_title = self._cycle_timeline_default_title_text()
        defaults = {
            "species_min": None,
            "species_max": None,
            "cycle_x_min": None,
            "cycle_x_max": None,
            "ph_min": None,
            "ph_max": None,
            "show_main_legend": True,
            "show_legend": True,
            "trace_series": {},
            "export_bottom_legend_wide_under_xaxis": False,
            "bottom_legend_center_below_xlabel": False,
            "timeline_top_legend_wrap": False,
            "timeline_top_legend_rows": 2,
            "timeline_bottom_legend_wrap": False,
            "timeline_bottom_legend_rows": 2,
            "export_title": default_title,
            "ph_axis_labelpad": 10.0,
            "ph_axis_spine_offset": 1.02,
            "pco2_axis_labelpad": 10.0,
            "pco2_axis_spine_offset": 1.12,
            "timeline_bar_color": DEFAULT_CYCLE_TIMELINE_BAR_COLOR,
            "timeline_bar_alpha": DEFAULT_CYCLE_TIMELINE_BAR_ALPHA,
            "timeline_bar_label_fontsize": DEFAULT_CYCLE_TIMELINE_BAR_LABEL_FONTSIZE,
            "timeline_bar_label_color": DEFAULT_CYCLE_TIMELINE_BAR_LABEL_COLOR,
            "layout_manager_enabled": DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_ENABLED,
            "layout_manager_strict_mode": DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_STRICT_MODE,
            "layout_manager_max_passes": DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MAX_PASSES,
            "layout_manager_check_legend_conflicts": DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_CHECK_LEGEND_CONFLICTS,
            "layout_manager_check_axis_label_conflicts": DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_CHECK_AXIS_LABEL_CONFLICTS,
            "layout_manager_min_legend_xlabel_gap_pts": DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MIN_LEGEND_XLABEL_GAP_PTS,
            "layout_manager_max_legend_xlabel_gap_pts": DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MAX_LEGEND_XLABEL_GAP_PTS,
            "layout_manager_min_axis_label_tick_gap_pts": DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MIN_AXIS_LABEL_TICK_GAP_PTS,
            "layout_manager_max_axis_label_tick_gap_pts": DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MAX_AXIS_LABEL_TICK_GAP_PTS,
        }
        prefs = getattr(self, "_cycle_plot_prefs", {}) or {}
        merged = dict(defaults)
        if isinstance(prefs, dict):
            merged.update({k: prefs.get(k, v) for k, v in defaults.items()})
            if prefs.get("show_main_legend") is None and "show_legend" in prefs:
                legacy_legend_pref = prefs.get("show_legend")
                if legacy_legend_pref is True:
                    merged["show_main_legend"] = True
        merged["show_main_legend"] = bool(merged.get("show_main_legend", True))
        # Keep the legacy key mirrored for backward-compatible settings snapshots.
        merged["show_legend"] = bool(merged.get("show_main_legend", True))
        merged["trace_series"] = self._sanitize_series_settings_dict(
            merged.get("trace_series")
            if isinstance(merged.get("trace_series"), Mapping)
            else {}
        )
        merged["export_bottom_legend_wide_under_xaxis"] = bool(
            merged.get("export_bottom_legend_wide_under_xaxis", False)
        )
        merged["bottom_legend_center_below_xlabel"] = bool(
            merged.get("bottom_legend_center_below_xlabel", False)
        )
        merged.update(self._normalize_cycle_timeline_legend_layout_prefs(merged))
        for range_key in ("cycle_x_min", "cycle_x_max"):
            range_value = _safe_float(merged.get(range_key))
            merged[range_key] = (
                float(range_value)
                if range_value is not None and math.isfinite(float(range_value))
                else None
            )
        merged.update(_normalize_cycle_timeline_layout_manager_settings(merged))
        merged.update(self._normalize_cycle_timeline_subplot_style_prefs(merged))
        title_text = (merged.get("export_title") or "").strip()
        merged["export_title"] = title_text or default_title
        self._cycle_plot_prefs = merged
        settings = getattr(self, "settings", None)
        if isinstance(settings, dict):
            settings["cycle_plot_prefs"] = merged
            try:
                self._schedule_save_settings()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        return merged

    def _cycle_timeline_resolved_xlim(
        self,
        prefs: Mapping[str, Any],
        xs: Sequence[Any],
    ) -> Optional[Tuple[float, float]]:
        """Resolve effective Cycle Timeline x-axis limits.

        Purpose:
            Convert optional timeline x-range preferences into a valid x-limit.
        Why:
            Display/export paths need identical range behavior while preserving
            auto-range fallback for blank or invalid settings.
        Inputs:
            prefs: Cycle timeline preference mapping.
            xs: Plotted cycle x-values used for auto fallback bounds.
        Outputs:
            Optional `(xmin, xmax)` tuple, or None when automatic limits apply.
        Side Effects:
            None.
        Exceptions:
            Invalid/non-finite bounds return None.
        """
        prefs_map = prefs if isinstance(prefs, Mapping) else {}
        pref_min = _safe_float(prefs_map.get("cycle_x_min"))
        pref_max = _safe_float(prefs_map.get("cycle_x_max"))
        finite_xs: List[float] = []
        for value in xs or []:
            numeric = _safe_float(value)
            if numeric is not None and math.isfinite(float(numeric)):
                finite_xs.append(float(numeric))
        if pref_min is None and pref_max is None:
            return None
        if not finite_xs and (pref_min is None or pref_max is None):
            return None
        resolved_min = float(pref_min) if pref_min is not None else min(finite_xs)
        resolved_max = float(pref_max) if pref_max is not None else max(finite_xs)
        if not math.isfinite(resolved_min) or not math.isfinite(resolved_max):
            return None
        if resolved_min >= resolved_max:
            return None
        return resolved_min, resolved_max

    def _apply_cycle_timeline_x_axis_range(
        self,
        axes: Sequence[Any],
        xs: Sequence[Any],
        prefs: Mapping[str, Any],
    ) -> Optional[Tuple[float, float]]:
        """Apply configured Cycle Timeline x-axis limits to every subplot axis.

        Purpose:
            Keep top, pH, and CO2 timeline panels aligned under one x-range.
        Why:
            User-controlled cycle ranges must render consistently in display,
            generated-tab, preview, and export figures.
        Inputs:
            axes: Axes that share the cycle x-domain.
            xs: Plotted cycle x-values for auto-bound fallback.
            prefs: Cycle timeline preference mapping.
        Outputs:
            Applied `(xmin, xmax)` tuple, or None when automatic range remains.
        Side Effects:
            Mutates x-limits on each provided axis when a valid range is present.
        Exceptions:
            Best-effort guards skip axes that fail limit writes.
        """
        xlim = self._cycle_timeline_resolved_xlim(prefs, xs)
        if xlim is None:
            return None
        for axis in axes or ():
            if axis is None:
                continue
            try:
                axis.set_xlim(float(xlim[0]), float(xlim[1]))
            except Exception:
                # Best-effort guard; invalid axes should not interrupt rendering.
                continue
        return xlim

    def _cycle_timeline_default_title_text(self) -> str:
        """Return the default cycle timeline title from Job Information.

        Purpose:
            Build the canonical fallback title for the cycle timeline plot.
        Why:
            Timeline title defaults must align with the Job Information context.
        Inputs:
            None.
        Outputs:
            str: Non-empty title in `<Job Information> Reaction Simulation` format.
        Side Effects:
            None.
        Exceptions:
            Missing settings/UI state falls back to a stable placeholder label.
        """
        job_information = ""
        suptitle_var = getattr(self, "suptitle_text", None)
        suptitle_getter = getattr(suptitle_var, "get", None)
        if callable(suptitle_getter):
            try:
                job_information = str(suptitle_getter() or "").strip()
            except Exception:
                job_information = ""
        if not job_information:
            settings_ref = getattr(self, "settings", None)
            if isinstance(settings_ref, Mapping):
                job_information = str(settings_ref.get("suptitle_text") or "").strip()
        if not job_information:
            job_information = "Job Information"
        return f"{job_information} Reaction Simulation"

    def _redraw_cycle_timeline_title_lightweight(self, title_text: str) -> None:
        """Apply a title-only redraw for the visible cycle timeline plot.

        Purpose:
            Update displayed timeline title text without rebuilding timeline data.
        Why:
            Title edits should be responsive and must not trigger full tree/dashboard
            refresh loops.
        Inputs:
            title_text: Normalized title text to render.
        Outputs:
            None.
        Side Effects:
            Mutates cycle timeline axis title and schedules one canvas draw.
        Exceptions:
            Best-effort guards ignore stale canvas/axis handles.
        """
        axis = getattr(self, "_sol_cycle_spec_ax", None)
        canvas = getattr(self, "_sol_cycle_spec_canvas", None)
        if axis is None or canvas is None:
            return
        try:
            axis.set_title(str(title_text or ""), fontsize=11, pad=8)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            return
        try:
            canvas.draw_idle()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _commit_cycle_timeline_title_edit(self, _event: Optional[Any] = None) -> None:
        """Commit one shared cycle timeline title edit into settings and plot state.

        Purpose:
            Persist timeline title edits only on explicit commit events.
        Why:
            Per-keystroke commits can trigger expensive refresh cascades and
            re-entrant Treeview selection churn in Analysis mode.
        Inputs:
            _event: Optional Tk event payload from `<Return>`/`<FocusOut>`.
        Outputs:
            None.
        Side Effects:
            Updates shared title variable, cycle plot preferences, settings save
            scheduling, and title-only timeline redraw.
        Exceptions:
            Best-effort guards suppress commit failures and keep UI responsive.
        """
        if bool(getattr(self, "_cycle_timeline_title_syncing", False)):
            return
        if bool(getattr(self, "_cycle_timeline_title_commit_inflight", False)):
            return
        title_var = getattr(self, "_cycle_timeline_title_var", None)
        title_getter = getattr(title_var, "get", None)
        title_setter = getattr(title_var, "set", None)
        if not callable(title_getter) or not callable(title_setter):
            return
        self._cycle_timeline_title_commit_inflight = True
        try:
            try:
                raw_title = str(title_getter() or "").strip()
            except Exception:
                raw_title = ""
            normalized_title = raw_title or self._cycle_timeline_default_title_text()
            if raw_title != normalized_title:
                self._cycle_timeline_title_syncing = True
                try:
                    title_setter(normalized_title)
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
                self._cycle_timeline_title_syncing = False
            prefs = self._get_cycle_plot_prefs()
            if str(prefs.get("export_title") or "").strip() != normalized_title:
                prefs["export_title"] = normalized_title
                self._cycle_plot_prefs = prefs
                settings_ref = getattr(self, "settings", None)
                if isinstance(settings_ref, dict):
                    settings_ref["cycle_plot_prefs"] = prefs
                    try:
                        self._schedule_save_settings()
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting the workflow.
                        pass
            self._redraw_cycle_timeline_title_lightweight(normalized_title)
        finally:
            self._cycle_timeline_title_commit_inflight = False

    def _bind_cycle_timeline_title_commit_handlers(self, entry_widget: Any) -> None:
        """Bind timeline-title commit handlers to one input widget.

        Purpose:
            Wire commit-on-enter/focus-out behavior for shared title inputs.
        Why:
            Title persistence is intentionally commit-based to prevent heavy
            per-keystroke refresh loops.
        Inputs:
            entry_widget: Tk/CTk entry-like widget bound to title StringVar.
        Outputs:
            None.
        Side Effects:
            Registers `<Return>` and `<FocusOut>` event bindings.
        Exceptions:
            Missing/unsupported widgets are ignored.
        """
        if entry_widget is None:
            return
        binder = getattr(entry_widget, "bind", None)
        if not callable(binder):
            return
        try:
            binder("<Return>", self._commit_cycle_timeline_title_edit, add="+")
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            binder("<FocusOut>", self._commit_cycle_timeline_title_edit, add="+")
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _cycle_timeline_title_text(
        self, prefs: Optional[Mapping[str, Any]] = None
    ) -> str:
        """Return the normalized cycle timeline title text.

        Purpose:
            Resolve one canonical cycle timeline title string for display/export.
        Why:
            Planning, Analysis, and Reprocessing inputs must share one title source
            so timeline plot rendering and exports stay synchronized.
        Inputs:
            prefs: Optional pre-fetched cycle plot preference mapping.
        Outputs:
            str: Non-empty timeline title text.
        Side Effects:
            None.
        Exceptions:
            Uses safe fallback defaults when preference lookup fails.
        """
        prefs_map = dict(prefs or self._get_cycle_plot_prefs())
        raw_title = str(prefs_map.get("export_title") or "").strip()
        return raw_title or self._cycle_timeline_default_title_text()

    def _cycle_timeline_effective_render_title_text(
        self,
        prefs: Optional[Mapping[str, Any]] = None,
        *,
        preview: bool = False,
    ) -> str:
        """Return cycle timeline render title with auto-title parity when enabled.

        Purpose:
            Resolve the title string rendered on cycle timeline figures.
        Why:
            Cycle timeline display/export/preview should honor the same Plot
            Settings auto-title behavior as the combined triple-axis plot while
            preserving manual timeline title persistence.
        Inputs:
            prefs: Optional cycle-plot preference mapping used to resolve the
                manual timeline title seed (`export_title`).
            preview: When True, request preview-safe auto-title resolution that
                suppresses non-critical warning side effects.
        Outputs:
            str: Non-empty effective title text used for timeline rendering.
        Side Effects:
            May trigger auto-title warning emission when preview is False and
            auto-title resolution reports recoverable data/template issues.
        Exceptions:
            Falls back to manual timeline title when resolver hooks are missing
            or auto-title resolution raises.
        """
        manual_title = UnifiedApp._cycle_timeline_title_text(self, prefs)
        resolver = getattr(self, "_resolve_effective_title", None)
        if not callable(resolver):
            return manual_title
        try:
            resolved_title = str(
                resolver(manual_title, preview=bool(preview)) or ""
            ).strip()
        except TypeError:
            try:
                resolved_title = str(resolver(manual_title) or "").strip()
            except Exception:
                resolved_title = ""
        except Exception:
            resolved_title = ""
        return resolved_title or manual_title

    def _cycle_timeline_render_suptitle_text(self) -> str:
        """Return cycle timeline suptitle text from UI/settings with safe fallback.

        Purpose:
            Resolve the shared timeline suptitle rendered above cycle timeline
            figures.
        Why:
            Timeline preview/export should follow the same global Job Information
            suptitle source used by the core and combined plot pipelines.
        Inputs:
            None.
        Outputs:
            str: Trimmed suptitle text (empty string when no source is present).
        Side Effects:
            None.
        Exceptions:
            Getter and mapping access failures are guarded; resolution falls back
            to lower-priority sources.
        """
        suptitle_var = getattr(self, "suptitle_text", None)
        suptitle_getter = getattr(suptitle_var, "get", None)
        if callable(suptitle_getter):
            try:
                suptitle_text = str(suptitle_getter() or "").strip()
            except Exception:
                suptitle_text = ""
            if suptitle_text:
                return suptitle_text
        settings_ref = getattr(self, "settings", None)
        if isinstance(settings_ref, Mapping):
            settings_text = str(settings_ref.get("suptitle_text") or "").strip()
            if settings_text:
                return settings_text
        settings_global = globals().get("settings")
        if isinstance(settings_global, Mapping):
            return str(settings_global.get("suptitle_text") or "").strip()
        return ""

    def _ensure_cycle_timeline_title_var(self) -> tk.StringVar:
        """Return the shared cycle timeline title variable.

        Purpose:
            Create/reuse one Tk variable that drives timeline title edits across
            all Advanced Speciation workflow input tabs and settings dialogs.
        Why:
            A shared variable keeps Planning/Analysis/Reprocessing title controls
            synchronized while persisting into `cycle_plot_prefs`.
        Inputs:
            None.
        Outputs:
            tk.StringVar: Shared title variable bound to timeline title controls.
        Side Effects:
            - Creates and stores `_cycle_timeline_title_var` when missing.
            - Synchronizes value from persisted timeline title preferences.
        Exceptions:
            Best-effort guards prevent UI interruptions on sync failures.
        """
        existing_var = getattr(self, "_cycle_timeline_title_var", None)
        desired_title = self._cycle_timeline_title_text()
        if not isinstance(existing_var, tk.StringVar):
            existing_var = tk.StringVar(value=desired_title)
            self._cycle_timeline_title_var = existing_var
            self._cycle_timeline_title_trace = None
            return existing_var
        try:
            current_title = str(existing_var.get() or "").strip()
        except Exception:
            current_title = ""
        if current_title != desired_title:
            self._cycle_timeline_title_syncing = True
            try:
                existing_var.set(desired_title)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            self._cycle_timeline_title_syncing = False
        return existing_var

    def _cycle_timeline_axis_layout_prefs(
        self, prefs: Optional[Mapping[str, Any]] = None
    ) -> Dict[str, float]:
        """Return normalized axis spacing controls for the timeline plot.

        Purpose:
            Resolve second/third y-axis spacing overrides for timeline rendering.
        Why:
            Timeline settings expose pH and cycle-uptake axis label spacing
            controls that must be applied consistently in display/export figures.
        Inputs:
            prefs: Optional pre-fetched cycle plot preference mapping.
        Outputs:
            Dict[str, float]: Normalized numeric spacing values for axis label pads
            and legacy compatibility offsets.
        Side Effects:
            None.
        Exceptions:
            Invalid values fall back to historical default spacing.
        """
        prefs_map = dict(prefs or self._get_cycle_plot_prefs())

        def _normalize_value(
            key: str,
            fallback: float,
            *,
            min_value: Optional[float] = None,
            max_value: Optional[float] = None,
        ) -> float:
            """Normalize one timeline axis spacing value.

            Purpose:
                Coerce a persisted preference into a finite float.
            Why:
                Timeline axis spacing controls accept free-form text and can be
                missing/invalid in older settings snapshots.
            Inputs:
                key: Preference key to resolve.
                fallback: Fallback float used when value is invalid.
            Outputs:
                float: Finite spacing value for renderer use.
            Side Effects:
                None.
            Exceptions:
                Returns fallback when conversion fails.
            """
            try:
                value = float(prefs_map.get(key))
            except Exception:
                value = float(fallback)
            if not math.isfinite(value):
                value = float(fallback)
            if min_value is not None:
                value = max(float(min_value), value)
            if max_value is not None:
                value = min(float(max_value), value)
            return float(value)

        return {
            "ph_axis_labelpad": _normalize_value(
                "ph_axis_labelpad",
                10.0,
                min_value=0.0,
                max_value=48.0,
            ),
            "ph_axis_spine_offset": _normalize_value(
                "ph_axis_spine_offset",
                1.02,
                min_value=0.9,
                max_value=1.25,
            ),
            "pco2_axis_labelpad": _normalize_value(
                "pco2_axis_labelpad",
                10.0,
                min_value=0.0,
                max_value=48.0,
            ),
            "pco2_axis_spine_offset": _normalize_value(
                "pco2_axis_spine_offset",
                1.12,
                min_value=0.9,
                max_value=1.45,
            ),
        }

    def _cycle_timeline_layout_manager_policy(
        self, prefs: Optional[Mapping[str, Any]] = None
    ) -> Dict[str, Any]:
        """Return normalized timeline layout-manager policy controls.

        Purpose:
            Resolve one canonical policy payload for timeline layout verification.
        Why:
            Timeline layout manager controls are persisted in `cycle_plot_prefs`
            and must be normalized identically for display/preview/export solves.
        Inputs:
            prefs: Optional pre-fetched cycle plot preference mapping.
        Outputs:
            Dict containing normalized manager policy values.
        Side Effects:
            None.
        Exceptions:
            Invalid values are coerced by shared normalization helpers.
        """
        prefs_map = dict(prefs or self._get_cycle_plot_prefs())
        return _normalize_cycle_timeline_layout_manager_settings(prefs_map)

    def _resolve_cycle_timeline_uptake_label_x(
        self,
        axis_layout: Mapping[str, Any],
        *,
        uptake_labelpad: float,
        ax3: Optional[Any] = None,
    ) -> float:
        """Resolve the final attached uptake-axis label x-position in axes units.

        Purpose:
            Convert timeline spacing controls into one deterministic x-position for
            the attached right-side uptake-axis label.
        Why:
            `set_label_coords` bypasses default `labelpad` behavior, so explicit
            x-position calculation is required for the CO2 label padding control
            to have visible effect.
        Inputs:
            axis_layout: Resolved timeline axis-layout mapping.
            uptake_labelpad: Normalized uptake-axis label padding in points.
            ax3: Optional uptake-axis instance for geometry-aware conversion.
        Outputs:
            float: Attached-axis label x-position in axes coordinates.
        Side Effects:
            None.
        Exceptions:
            Falls back to sane defaults when figure geometry is unavailable.
        """
        base_x = _safe_float(axis_layout.get("pco2_axis_spine_offset"), 1.12)
        if base_x is None or not math.isfinite(base_x):
            base_x = 1.12
        fig_ref = None
        if ax3 is not None:
            fig_ref = getattr(ax3, "figure", None)
        fig_w_pts = None
        if fig_ref is not None:
            try:
                fig_w_pts = max(float(fig_ref.get_size_inches()[0]) * 72.0, 1.0)
            except Exception:
                fig_w_pts = None
        if fig_w_pts is None:
            fig_w_pts = max(11.0 * 72.0, 1.0)
        pad_offset_axes = float(uptake_labelpad) / float(fig_w_pts)
        label_x = float(base_x) + pad_offset_axes
        return max(1.0, min(1.8, label_x))

    def _cycle_timeline_layout_signature(
        self,
        fig: Figure,
        *,
        mode: str,
        prefs: Optional[Mapping[str, Any]] = None,
    ) -> Tuple[Any, ...]:
        """Build one deterministic signature for timeline layout-manager changes.

        Purpose:
            Detect settings/layout changes that require splash-backed revalidation.
        Why:
            Timeline render paths should only show blocking layout verification when
            inputs materially affecting collision/spacing behavior have changed.
        Inputs:
            fig: Timeline target figure used for geometry-dependent signature data.
            mode: Layout mode (`display` or `export`).
            prefs: Optional pre-fetched timeline preference mapping.
        Outputs:
            Tuple signature capturing policy/layout/legend/geometry dependencies.
        Side Effects:
            None.
        Exceptions:
            Missing figure geometry falls back to default size values.
        """
        mode_key = "export" if str(mode).strip().lower() == "export" else "display"
        prefs_map = dict(prefs or self._get_cycle_plot_prefs())
        axis_layout = self._cycle_timeline_axis_layout_prefs(prefs_map)
        policy = self._cycle_timeline_layout_manager_policy(prefs_map)
        layout_profile = _get_layout_profile("fig_cycle_timeline")
        section = _layout_profile_section(layout_profile, mode_key)
        margins = section.get("margins") if isinstance(section.get("margins"), Mapping) else {}
        axis_labelpads = (
            section.get("axis_labelpads")
            if isinstance(section.get("axis_labelpads"), Mapping)
            else {}
        )
        try:
            fig_size = tuple(round(float(v), 4) for v in fig.get_size_inches())
        except Exception:
            fig_size = (0.0, 0.0)
        legend_mode = (
            bool(prefs_map.get("show_main_legend", True)),
            bool(prefs_map.get("export_bottom_legend_wide_under_xaxis", False)),
        )
        normalized_margins = tuple(
            (
                key,
                round(float(margins.get(key, 0.0) or 0.0), 6),
            )
            for key in ("left", "right", "top", "bottom")
        )
        normalized_axis_labelpads = tuple(
            (str(key), round(float(value), 6))
            for key, value in sorted(
                (
                    (key, value)
                    for key, value in axis_labelpads.items()
                    if _safe_float(value) is not None
                ),
                key=lambda item: str(item[0]),
            )
        )
        return (
            mode_key,
            fig_size,
            legend_mode,
            tuple(sorted((str(key), bool(value)) for key, value in policy.items() if isinstance(value, bool))),
            tuple(
                sorted(
                    (
                        (str(key), round(float(value), 6))
                        for key, value in policy.items()
                        if isinstance(value, (int, float)) and not isinstance(value, bool)
                    ),
                    key=lambda item: item[0],
                )
            ),
            tuple(
                sorted(
                    (str(key), round(float(value), 6))
                    for key, value in axis_layout.items()
                )
            ),
            normalized_margins,
            normalized_axis_labelpads,
            round(float(_safe_float(section.get("xlabel_pad_pts"), 0.0) or 0.0), 6),
            round(float(_safe_float(section.get("legend_anchor_y"), 0.0) or 0.0), 6),
            str(section.get("legend_loc") or ""),
            tuple(_validated_anchor_pair(section.get("legend_anchor")) or ()),
            tuple(_validated_anchor_pair(section.get("cycle_legend_anchor")) or ()),
            str(section.get("cycle_legend_loc") or ""),
            round(float(_safe_float(section.get("detached_spine_offset"), 0.0) or 0.0), 6),
            round(float(_safe_float(section.get("detached_labelpad"), 0.0) or 0.0), 6),
        )

    def _cycle_timeline_overlap_metrics(self, fig: Optional[Figure]) -> Dict[str, Any]:
        """Measure timeline bottom-legend overlap against xlabel and x tick labels.

        Purpose:
            Provide one deterministic overlap diagnostic payload for timeline figures.
        Why:
            Export/preview/finalize stages need a common metric source to confirm
            that bottom legends do not overlap lower-axis labels after layout solves.
        Inputs:
            fig: Timeline figure to inspect.
        Outputs:
            Dict[str, Any]: Overlap areas, gaps, bottom whitespace, and conflict booleans.
        Side Effects:
            May read timeline layout-manager settings and trigger one canvas draw
            to compute text/legend bounding boxes.
        Exceptions:
            Best-effort guards return safe defaults when artists are unavailable.
        """
        try:
            policy = self._cycle_timeline_layout_manager_policy(
                self._get_cycle_plot_prefs()
            )
        except Exception:
            policy = {}
        max_whitespace_setting = _safe_float(
            (
                policy.get("layout_manager_max_bottom_whitespace_pts")
                if isinstance(policy, Mapping)
                else None
            ),
            DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MAX_BOTTOM_WHITESPACE_PTS,
        )
        if max_whitespace_setting is None or not math.isfinite(
            float(max_whitespace_setting)
        ):
            max_whitespace_setting = (
                DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MAX_BOTTOM_WHITESPACE_PTS
            )
        max_whitespace_setting = max(6.0, min(160.0, float(max_whitespace_setting)))
        metrics: Dict[str, Any] = {
            "legend_xlabel_overlap_area": 0.0,
            "legend_xticklabels_overlap_area": 0.0,
            "legend_xlabel_gap_pts": None,
            "legend_xticklabels_gap_pts": None,
            "bottom_band_whitespace_pts": None,
            "bottom_band_whitespace_excess_pts": None,
            "bottom_band_whitespace_max_pts": float(max_whitespace_setting),
            "bottom_band_whitespace_high": False,
            "has_conflict": False,
            "has_legend": False,
            "has_xlabel": False,
            "has_xticklabels": False,
        }
        if fig is None:
            return metrics
        try:
            canvas = fig.canvas
            if canvas is None:
                canvas = FigureCanvasAgg(fig)
                fig.set_canvas(canvas)
            canvas.draw()
            renderer = canvas.get_renderer()
        except Exception:
            return metrics
        if renderer is None:
            return metrics
        try:
            legends = _layout_health_timeline_legends(fig)
        except Exception:
            legends = {"top": None, "bottom": None}
        legend = legends.get("bottom") if isinstance(legends, Mapping) else None
        if legend is None:
            return metrics
        metrics["has_legend"] = True
        fig_h_pts = max(float(fig.get_size_inches()[1]) * 72.0, 1.0)
        legend_bbox = _layout_health_bbox_in_fig(fig, legend, renderer)
        xlabel_artist = _layout_health_primary_xlabel(fig, plot_id="fig_cycle_timeline")
        xlabel_bbox = _layout_health_bbox_in_fig(fig, xlabel_artist, renderer)
        bottom_band_candidates: List[float] = []
        if legend_bbox is not None:
            bottom_band_candidates.append(float(legend_bbox.y0))
        if xlabel_bbox is not None and legend_bbox is not None:
            metrics["has_xlabel"] = True
            overlap = _layout_health_bbox_overlap_area(legend_bbox, xlabel_bbox)
            metrics["legend_xlabel_overlap_area"] = float(overlap)
            metrics["legend_xlabel_gap_pts"] = float(
                (xlabel_bbox.y0 - legend_bbox.y1) * fig_h_pts
            )
        if xlabel_bbox is not None:
            bottom_band_candidates.append(float(xlabel_bbox.y0))
        bottom_axis = _layout_health_axis_for_role(fig, "right")
        xticks_bbox = (
            _layout_health_axis_ticklabels_bbox(fig, bottom_axis.xaxis, renderer)
            if bottom_axis is not None
            else None
        )
        if xticks_bbox is not None and legend_bbox is not None:
            metrics["has_xticklabels"] = True
            tick_overlap = _layout_health_bbox_overlap_area(legend_bbox, xticks_bbox)
            metrics["legend_xticklabels_overlap_area"] = float(tick_overlap)
            metrics["legend_xticklabels_gap_pts"] = float(
                (xticks_bbox.y0 - legend_bbox.y1) * fig_h_pts
            )
        if xticks_bbox is not None:
            bottom_band_candidates.append(float(xticks_bbox.y0))
        if bottom_band_candidates:
            band_floor = min(bottom_band_candidates)
            bottom_whitespace_pts = max(0.0, float(band_floor) * fig_h_pts)
            max_whitespace_pts = float(max_whitespace_setting)
            metrics["bottom_band_whitespace_pts"] = float(bottom_whitespace_pts)
            metrics["bottom_band_whitespace_max_pts"] = float(max_whitespace_pts)
            metrics["bottom_band_whitespace_excess_pts"] = max(
                0.0,
                float(bottom_whitespace_pts - max_whitespace_pts),
            )
            metrics["bottom_band_whitespace_high"] = bool(
                bottom_whitespace_pts > max_whitespace_pts + 0.25
            )
        metrics["has_conflict"] = bool(
            float(metrics["legend_xlabel_overlap_area"]) > 1e-8
            or float(metrics["legend_xticklabels_overlap_area"]) > 1e-8
        )
        return metrics

    def _dbg_cycle_timeline_overlap_checkpoint(
        self,
        fig: Optional[Figure],
        *,
        stage: str,
    ) -> Dict[str, Any]:
        """Log timeline legend-overlap diagnostics for one render checkpoint.

        Purpose:
            Emit lightweight overlap metrics at key timeline render stages.
        Why:
            Persistent overlap regressions are easier to diagnose with per-stage
            overlap telemetry in the existing plotting debug channel.
        Inputs:
            fig: Timeline figure to inspect.
            stage: Named checkpoint (`build`, `profile`, `verify`, `finalize`, etc.).
        Outputs:
            Dict[str, Any]: Measured overlap metric payload.
        Side Effects:
            Writes one debug event when `plotting.render` diagnostics are enabled.
        Exceptions:
            Best-effort guards suppress logging/measurement failures.
        """
        metrics = self._cycle_timeline_overlap_metrics(fig)
        try:
            self._dbg(
                "plotting.render",
                "cycle_timeline_overlap stage=%s conflict=%s xlabel_overlap=%.6f xtick_overlap=%.6f xlabel_gap_pts=%s xtick_gap_pts=%s bottom_whitespace_pts=%s bottom_whitespace_high=%s",
                str(stage or "").strip() or "unknown",
                bool(metrics.get("has_conflict", False)),
                float(metrics.get("legend_xlabel_overlap_area", 0.0) or 0.0),
                float(metrics.get("legend_xticklabels_overlap_area", 0.0) or 0.0),
                (
                    "--"
                    if metrics.get("legend_xlabel_gap_pts") is None
                    else f"{float(metrics.get('legend_xlabel_gap_pts')):.2f}"
                ),
                (
                    "--"
                    if metrics.get("legend_xticklabels_gap_pts") is None
                    else f"{float(metrics.get('legend_xticklabels_gap_pts')):.2f}"
                ),
                (
                    "--"
                    if metrics.get("bottom_band_whitespace_pts") is None
                    else f"{float(metrics.get('bottom_band_whitespace_pts')):.2f}"
                ),
                bool(metrics.get("bottom_band_whitespace_high", False)),
            )
        except Exception:
            # Best-effort guard; ignore logging failures to avoid interrupting render.
            pass
        return metrics

    def _force_cycle_timeline_bottom_legend_safe_anchor(
        self, fig: Optional[Figure]
    ) -> bool:
        """Apply a deterministic bottom-wide legend anchor fallback for timelines.

        Purpose:
            Recover from persistent bottom-legend/xlabel overlap, x-tick overlap,
            or excessive lower-band whitespace.
        Why:
            In rare dense layouts, auto-fix can converge to unstable legend anchors;
            this fallback enforces wide-under-x-axis placement plus a margin floor
            so display and generated-tab timeline legends stay in the intended band.
        Inputs:
            fig: Timeline figure to adjust.
        Outputs:
            bool: True when a fallback anchor was successfully applied.
        Side Effects:
            Updates bottom legend anchor metadata and may expand subplot bottom
            margin when no authoritative display profile margin is active.
        Exceptions:
            Best-effort guards skip invalid legends/axes and return False.
        """
        if fig is None:
            return False
        try:
            legends = _layout_health_timeline_legends(fig)
        except Exception:
            legends = {"top": None, "bottom": None}
        bottom_legend = legends.get("bottom") if isinstance(legends, Mapping) else None
        if bottom_legend is None:
            return False
        host_axis = getattr(bottom_legend, "axes", None)
        if host_axis is None:
            return False
        prefs = self._get_cycle_plot_prefs()
        if bool(prefs.get("bottom_legend_center_below_xlabel", False)):
            try:
                bottom_legend.set_loc("upper center")
                bottom_legend._cycle_timeline_legend_role = "bottom"
                bottom_legend._cycle_timeline_bottom_center_below_xlabel = True
                bottom_legend._cycle_timeline_bottom_wide_under_xaxis = False
                self._position_cycle_timeline_centered_bottom_legend(
                    fig=fig,
                    host_axis=host_axis,
                    legend=bottom_legend,
                )
                return True
            except Exception:
                return False
        safe_bbox_axes = (0.0, -0.22, 1.0, 0.2)
        applied = False
        try:
            bottom_legend.set_loc("upper left")
        except Exception:
            pass
        try:
            bottom_legend.set_bbox_to_anchor(
                safe_bbox_axes, transform=host_axis.transAxes
            )
            applied = True
        except Exception:
            applied = False
        if not applied:
            return False
        try:
            bottom_legend._cycle_timeline_legend_role = "bottom"
            bottom_legend._cycle_timeline_bottom_wide_under_xaxis = True
            bottom_legend._cycle_timeline_bbox_to_anchor_axes = safe_bbox_axes
        except Exception:
            # Best-effort guard; ignore metadata assignment failures.
            pass
        layout_mgr = getattr(fig, "_gl260_layout_manager", None)
        authoritative_bottom = _layout_health_authoritative_timeline_bottom(
            fig,
            getattr(fig, "_gl260_layout_mode", "display"),
            layout_mgr,
        )
        if authoritative_bottom is not None:
            try:
                fig.subplots_adjust(bottom=float(authoritative_bottom))
            except Exception:
                # Best-effort guard; keep fallback tolerant.
                pass
            return True
        try:
            # Conflict-recovery mode may need one immediate floor reservation so
            # follow-up solves start from a non-overlapping baseline.
            bottom_now = float(getattr(fig.subplotpars, "bottom", 0.0))
            if bottom_now < 0.24:
                fig.subplots_adjust(bottom=0.24)
        except Exception:
            # Best-effort guard; ignore margin update failures.
            pass
        reserve_margin = getattr(
            self, "_reserve_cycle_timeline_bottom_wide_legend_margin", None
        )
        if callable(reserve_margin):
            try:
                reserve_margin(fig=fig, host_axis=host_axis, legend=bottom_legend)
            except Exception:
                # Best-effort guard; ignore fallback-margin failures.
                pass
        return True

    def _run_cycle_timeline_layout_manager_verification(
        self,
        fig: Figure,
        *,
        mode: str,
        prefs: Optional[Mapping[str, Any]] = None,
        show_splash: bool = False,
        splash_message: str = "Verifying timeline layout...",
        splash_detail: str = "Resolving overlapping labels and legends.",
    ) -> Dict[str, Any]:
        """Run timeline layout-manager verification with optional splash gating.

        Purpose:
            Re-solve timeline layout and run bounded conflict auto-fix checks.
        Why:
            Timeline display and preview should validate spacing conflicts before
            reveal when layout-driving settings change.
        Inputs:
            fig: Timeline figure to verify.
            mode: Layout mode (`display` or `export`).
            prefs: Optional pre-fetched cycle plot preference mapping.
            show_splash: Whether to show blocking Advanced Speciation splash.
            splash_message: Primary splash status message.
            splash_detail: Secondary splash detail message.
        Outputs:
            Dict containing `signature_changed`, `policy`, and `health_result`.
        Side Effects:
            May run deterministic layout solves, auto-fix checks, and splash
            overlay show/hide updates.
        Exceptions:
            Best-effort guards preserve render stability on verification errors.
        """
        if fig is None:
            return {
                "signature_changed": False,
                "policy": {},
                "health_result": {},
                "signature": None,
            }
        mode_key = "export" if str(mode).strip().lower() == "export" else "display"
        prefs_map = dict(prefs or self._get_cycle_plot_prefs())
        policy = self._cycle_timeline_layout_manager_policy(prefs_map)
        signature = self._cycle_timeline_layout_signature(
            fig,
            mode=mode_key,
            prefs=prefs_map,
        )
        if mode_key == "display":
            previous_signature = getattr(
                self, "_cycle_timeline_display_layout_signature", None
            )
        else:
            previous_signature = getattr(
                self, "_cycle_timeline_preview_layout_signature", None
            )
        signature_changed = signature != previous_signature
        if mode_key == "display":
            self._cycle_timeline_display_layout_signature = signature
        else:
            self._cycle_timeline_preview_layout_signature = signature
        if not bool(policy.get("layout_manager_enabled", True)):
            return {
                "signature_changed": signature_changed,
                "policy": policy,
                "health_result": {},
                "signature": signature,
            }
        quick_probe_metrics: Dict[str, Any] = {}
        if not signature_changed:
            try:
                quick_probe_metrics = self._cycle_timeline_overlap_metrics(fig)
            except Exception:
                quick_probe_metrics = {}
            quick_probe_has_conflict = bool(
                quick_probe_metrics.get("has_conflict", False)
            )
            quick_probe_whitespace_high = bool(
                quick_probe_metrics.get("bottom_band_whitespace_high", False)
            )
            if not quick_probe_has_conflict and not quick_probe_whitespace_high:
                self._dbg(
                    "plotting.render",
                    "cycle_timeline_verify_short_circuit mode=%s signature_changed=%s quick_conflict=%s quick_whitespace_high=%s",
                    mode_key,
                    signature_changed,
                    quick_probe_has_conflict,
                    quick_probe_whitespace_high,
                )
                return {
                    "signature_changed": signature_changed,
                    "policy": policy,
                    "health_result": {
                        "skipped_verification": True,
                        "reason": "signature_unchanged_quick_probe_clean",
                        "quick_probe_metrics": dict(quick_probe_metrics),
                    },
                    "signature": signature,
                }
        splash_session_id = None
        if show_splash and signature_changed:
            try:
                splash_session_id = self._begin_solubility_loading_phase(
                    phase="timeline_layout_manager",
                    message=str(splash_message),
                    detail=str(splash_detail),
                )
            except Exception:
                splash_session_id = None
        health_result: Dict[str, Any] = {}
        try:
            layout_mgr = getattr(fig, "_gl260_layout_manager", None)
            authoritative_bottom = _layout_health_authoritative_timeline_bottom(
                fig,
                mode_key,
                layout_mgr,
            )
            if layout_mgr is not None:
                try:
                    layout_mgr.solve(
                        max_passes=int(policy.get("layout_manager_max_passes", 1)),
                        allow_draw=False,
                    )
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
            health_policy = dict(settings if isinstance(settings, Mapping) else {})
            health_policy.update(
                {
                    "layout_health_autofix_enabled": True,
                    "layout_health_strict_mode": bool(
                        policy.get("layout_manager_strict_mode", False)
                    ),
                    "layout_health_max_passes": int(
                        policy.get("layout_manager_max_passes", 3)
                    ),
                    "layout_health_min_gap_pts": float(
                        policy.get("layout_manager_min_legend_xlabel_gap_pts", 8.0)
                    ),
                    "layout_health_max_gap_pts": float(
                        policy.get("layout_manager_max_legend_xlabel_gap_pts", 28.0)
                    ),
                    "layout_health_context": "timeline",
                    "layout_health_check_legend_conflicts": bool(
                        policy.get("layout_manager_check_legend_conflicts", True)
                    ),
                    "layout_health_check_axis_label_conflicts": bool(
                        policy.get("layout_manager_check_axis_label_conflicts", True)
                    ),
                    "layout_health_min_axis_label_tick_gap_pts": float(
                        policy.get(
                            "layout_manager_min_axis_label_tick_gap_pts",
                            DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MIN_AXIS_LABEL_TICK_GAP_PTS,
                        )
                    ),
                    "layout_health_max_axis_label_tick_gap_pts": float(
                        policy.get(
                            "layout_manager_max_axis_label_tick_gap_pts",
                            DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MAX_AXIS_LABEL_TICK_GAP_PTS,
                        )
                    ),
                    "layout_health_max_timeline_bottom_whitespace_pts": float(
                        _safe_float(
                            policy.get("layout_manager_max_bottom_whitespace_pts"),
                            DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MAX_BOTTOM_WHITESPACE_PTS,
                        )
                        or DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MAX_BOTTOM_WHITESPACE_PTS
                    ),
                }
            )
            try:
                health_result = layout_health_autofix(
                    fig,
                    "fig_cycle_timeline",
                    mode_key,
                    health_policy,
                )
            except Exception:
                health_result = {}
            if authoritative_bottom is not None:
                try:
                    fig.subplots_adjust(bottom=float(authoritative_bottom))
                except Exception:
                    # Best-effort guard; keep verification tolerant.
                    pass
            try:
                self._reposition_cycle_timeline_centered_bottom_legends(fig)
            except Exception:
                # Best-effort guard; keep layout verification tolerant.
                pass
            overlap_metrics = self._dbg_cycle_timeline_overlap_checkpoint(
                fig,
                stage=f"verify_post_autofix_{mode_key}",
            )
            # Export mode runs deterministic anchor handling during export-prepare;
            # keep verification overlap metrics diagnostic-only to avoid duplicate
            # retry/guard passes in export control flow.
            overlap_has_conflict = bool(overlap_metrics.get("has_conflict", False))
            overlap_whitespace_high = bool(
                overlap_metrics.get("bottom_band_whitespace_high", False)
            )
            if mode_key != "export" and (
                overlap_has_conflict
                or (overlap_whitespace_high and authoritative_bottom is None)
            ):
                forced = self._force_cycle_timeline_bottom_legend_safe_anchor(fig)
                if forced:
                    self._dbg(
                        "plotting.render",
                        "cycle_timeline_postverify_guard_applied mode=%s reason=%s",
                        mode_key,
                        (
                            "legend_overlap"
                            if overlap_has_conflict
                            else "bottom_whitespace"
                        ),
                    )
                    try:
                        if layout_mgr is not None:
                            layout_mgr.solve(
                                max_passes=int(
                                    policy.get("layout_manager_max_passes", 1)
                                ),
                                allow_draw=False,
                            )
                    except Exception:
                        # Best-effort guard; ignore solve failures for fallback guard.
                        pass
                    try:
                        health_result = layout_health_autofix(
                            fig,
                            "fig_cycle_timeline",
                            mode_key,
                            health_policy,
                        )
                    except Exception:
                        # Best-effort guard; keep prior health payload on retry failure.
                        pass
                    if authoritative_bottom is not None:
                        try:
                            fig.subplots_adjust(bottom=float(authoritative_bottom))
                        except Exception:
                            # Best-effort guard; keep fallback guard tolerant.
                            pass
                    try:
                        self._reposition_cycle_timeline_centered_bottom_legends(fig)
                    except Exception:
                        # Best-effort guard; keep fallback guard tolerant.
                        pass
                    guard_metrics = self._dbg_cycle_timeline_overlap_checkpoint(
                        fig,
                        stage=f"verify_post_guard_{mode_key}",
                    )
                    if isinstance(health_result, Mapping):
                        augmented_health = dict(health_result)
                        augmented_health["postverify_guard_applied"] = True
                        augmented_health["postverify_guard_metrics"] = dict(
                            guard_metrics
                        )
                        health_result = augmented_health
            if (
                str(getattr(fig, "_gl260_plot_id", "") or "").strip().lower()
                == "fig_cycle_timeline"
                and isinstance(health_result, Mapping)
                and bool(health_result.get("applied", False))
            ):
                # Persist corrected top/bottom timeline legend positions so
                # display/preview/export remain synchronized in-session.
                capture_multi = getattr(
                    self, "_capture_cycle_timeline_legend_locs_from_fig", None
                )
                if callable(capture_multi):
                    try:
                        capture_multi(fig, source="layout_manager_autofix")
                    except Exception:
                        # Best-effort guard; ignore capture failures.
                        pass
        finally:
            if splash_session_id is not None:
                try:
                    self._complete_solubility_loading_phase(
                        splash_session_id,
                        message="Timeline layout verified.",
                        detail="Applying final timeline draw.",
                    )
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
        return {
            "signature_changed": signature_changed,
            "policy": policy,
            "health_result": health_result,
            "signature": signature,
        }

    def _apply_cycle_timeline_axis_layout(
        self,
        ax2: Any,
        ax3: Any,
        *,
        axis_layout: Optional[Mapping[str, Any]] = None,
    ) -> Dict[str, float]:
        """Apply normalized lower-panel timeline axis labels and spacing.

        Purpose:
            Centralize cycle timeline pH/uptake-axis layout behavior.
        Why:
            Display and export renderers must use one axis-spacing path so
            the lower-panel secondary uptake axis stays attached and consistent.
        Inputs:
            ax2: Lower-panel pH axis.
            ax3: Lower-panel secondary uptake axis.
            axis_layout: Optional pre-resolved spacing mapping.
        Outputs:
            Dict[str, float]: Applied normalized spacing values.
        Side Effects:
            Updates lower-panel y-axis labels, pads, and attached right spine.
        Exceptions:
            Best-effort guards suppress axis update failures.
        """
        resolved_layout = self._cycle_timeline_axis_layout_prefs(axis_layout)
        ph_labelpad = float(resolved_layout.get("ph_axis_labelpad", 10.0))
        uptake_labelpad = float(resolved_layout.get("pco2_axis_labelpad", 10.0))
        uptake_label_x = self._resolve_cycle_timeline_uptake_label_x(
            resolved_layout,
            uptake_labelpad=uptake_labelpad,
            ax3=ax3,
        )
        try:
            ax2.set_ylabel(
                "Equilibrium / corrected / reference pH", fontsize=11, labelpad=ph_labelpad
            )
            ax2.tick_params(axis="both", labelsize=9, pad=4)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            ax3.set_ylabel(
                "Cycle CO$_2$ uptake (g)",
                fontsize=11,
                labelpad=uptake_labelpad,
                rotation=-90,
            )
            ax3.spines["right"].set_position(("axes", 1.0))
            ax3.yaxis.set_label_position("right")
            ax3.yaxis.tick_right()
            ax3.yaxis.set_label_coords(uptake_label_x, 0.5)
            ax3.tick_params(axis="both", labelsize=8, pad=3)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        return {
            "ph_axis_labelpad": ph_labelpad,
            "ph_axis_spine_offset": float(resolved_layout.get("ph_axis_spine_offset", 1.02)),
            "pco2_axis_labelpad": uptake_labelpad,
            # Keep legacy key for backward-compatible settings payload shape.
            "pco2_axis_spine_offset": uptake_label_x,
        }

    def _refresh_cycle_timeline_axis_layout_for_figure(
        self,
        fig: Optional[Figure],
        *,
        prefs: Optional[Mapping[str, Any]] = None,
    ) -> Optional[Dict[str, float]]:
        """Reapply cycle timeline lower-axis spacing for the current figure size.

        Purpose:
            Recompute pH and CO2 uptake axis label coordinates after a display
            figure has been resized by its Tk canvas.
        Why:
            The CO2 uptake label uses explicit axes coordinates derived from
            figure width; generated tabs can resize after the figure builder runs,
            leaving the right-side label off-canvas unless it is recalculated.
        Inputs:
            fig: Candidate cycle timeline figure whose lower axes should be
                refreshed.
            prefs: Optional cycle-plot preference mapping used to avoid a second
                settings lookup when the caller already has normalized prefs.
        Outputs:
            Optional[Dict[str, float]]: Applied axis layout values, or None when
            the target is not a resolvable cycle timeline figure.
        Side Effects:
            Mutates the lower pH axis and CO2 uptake twinx axis label pads,
            spine placement, label coordinates, and tick parameters.
        Exceptions:
            Best-effort guards return None when the figure/axes are unavailable.
        """
        if fig is None:
            return None
        if str(getattr(fig, "_gl260_plot_id", "") or "").strip().lower() != (
            "fig_cycle_timeline"
        ):
            return None
        try:
            _ax, ax2, ax3 = self._cycle_timeline_axes_from_fig(fig)
        except Exception:
            ax2 = ax3 = None
        if ax2 is None or ax3 is None:
            return None
        try:
            prefs_map = dict(prefs or self._get_cycle_plot_prefs())
            axis_layout = self._cycle_timeline_axis_layout_prefs(prefs_map)
            return self._apply_cycle_timeline_axis_layout(
                ax2,
                ax3,
                axis_layout=axis_layout,
            )
        except Exception:
            # Best-effort guard; a failed refresh should not block plot display.
            return None

    def _cycle_timeline_layout_manager_policies_equal(
        self, lhs: Mapping[str, Any], rhs: Mapping[str, Any]
    ) -> bool:
        """Return whether two normalized timeline layout-manager policies match.

        Purpose:
            Compare two timeline layout-manager payloads using stable key rules.
        Why:
            Policy apply paths should only trigger splash-backed rebuilds when
            effective layout-manager controls materially changed.
        Inputs:
            lhs: First normalized policy mapping.
            rhs: Second normalized policy mapping.
        Outputs:
            bool: True when all comparable controls are equivalent.
        Side Effects:
            None.
        Exceptions:
            Numeric comparisons use tolerant float deltas for stability.
        """
        comparable_keys = {
            "layout_manager_enabled",
            "layout_manager_strict_mode",
            "layout_manager_max_passes",
            "layout_manager_check_legend_conflicts",
            "layout_manager_check_axis_label_conflicts",
            "layout_manager_min_legend_xlabel_gap_pts",
            "layout_manager_max_legend_xlabel_gap_pts",
            "layout_manager_min_axis_label_tick_gap_pts",
            "layout_manager_max_axis_label_tick_gap_pts",
        }
        for key in comparable_keys:
            left_value = lhs.get(key)
            right_value = rhs.get(key)
            if isinstance(left_value, bool) or isinstance(right_value, bool):
                if bool(left_value) != bool(right_value):
                    return False
                continue
            if isinstance(left_value, (int, float)) or isinstance(
                right_value, (int, float)
            ):
                if abs(float(left_value or 0.0) - float(right_value or 0.0)) > 1e-9:
                    return False
                continue
            if left_value != right_value:
                return False
        return True

    def _apply_cycle_timeline_layout_manager_policy(
        self, new_policy: Mapping[str, Any], *, show_splash: bool = False
    ) -> bool:
        """Persist timeline layout-manager policy and refresh affected render paths.

        Purpose:
            Apply normalized timeline layout-manager controls into runtime and
            persisted settings.
        Why:
            Display and preview flows must rebuild under splash/overlay gating when
            layout-manager policy changes.
        Inputs:
            new_policy: Candidate timeline layout-manager policy mapping.
            show_splash: Whether to show a blocking timeline refresh splash while
                affected display/preview figures are rebuilt.
        Outputs:
            bool: True when the effective policy changed.
        Side Effects:
            Updates `cycle_plot_prefs`, schedules settings save, invalidates
            timeline layout signatures, refreshes display timeline, and rebuilds
            open preview windows.
        Exceptions:
            Best-effort guards prevent refresh failures from interrupting policy apply.
        """
        normalized_policy = _normalize_cycle_timeline_layout_manager_settings(
            new_policy
        )
        existing_prefs = self._get_cycle_plot_prefs()
        current_policy = self._cycle_timeline_layout_manager_policy(existing_prefs)
        changed = not self._cycle_timeline_layout_manager_policies_equal(
            normalized_policy,
            current_policy,
        )
        updated_prefs = dict(existing_prefs)
        updated_prefs.update(normalized_policy)
        self._cycle_plot_prefs = updated_prefs
        settings_ref = getattr(self, "settings", None)
        if isinstance(settings_ref, dict):
            settings_ref["cycle_plot_prefs"] = dict(updated_prefs)
            try:
                self._schedule_save_settings()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        if changed:
            # Force next render/preview pass to treat policy change as a
            # new layout signature and reveal behind splash verification.
            self._cycle_timeline_display_layout_signature = None
            self._cycle_timeline_preview_layout_signature = None
            splash_session_id = None
            if show_splash:
                try:
                    splash_session_id = self._begin_solubility_loading_phase(
                        phase="timeline_layout_wizard_apply",
                        message="Refreshing Cycle Timeline layout...",
                        detail="Applying layout-health settings behind this splash.",
                    )
                except Exception:
                    splash_session_id = None
            try:
                self._refresh_cycle_views()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                self._sync_cycle_timeline_generated_tab_from_persisted_state(
                    "fig_cycle_timeline",
                    reason="cycle_timeline_plot_settings_apply",
                    sync_elements=False,
                    sync_legends=True,
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            preview_window = getattr(self, "_cycle_timeline_preview_window", None)
            if preview_window is not None and bool(
                getattr(preview_window, "winfo_exists", lambda: False)()
            ):
                try:
                    self._open_cycle_timeline_plot_preview()
                except Exception:
                    # Best-effort guard; ignore preview rebuild failures.
                    pass
            if splash_session_id is not None:
                try:
                    self._complete_solubility_loading_phase(
                        splash_session_id,
                        message="Cycle Timeline layout refreshed.",
                        detail="Applying final redraw.",
                    )
                except Exception:
                    # Best-effort guard; ignore splash completion failures.
                    pass
        return changed

    def _reset_cycle_timeline_plot_layout(self) -> None:
        """Reset only user-adjustable Cycle Timeline layout placement state.

        Purpose:
            Provide a focused recovery action for timeline layout drift.
        Why:
            Users need to clear dragged legend/textbox positions and layout-manager
            overrides without losing axis ranges, title text, trace styles, or
            legend visibility preferences.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Clears runtime legend overrides, restores the auto current-state
            marker/label elements to their latest computed positions, resets
            layout-manager policy keys to defaults, persists settings, and
            refreshes timeline views.
        Exceptions:
            Best-effort guards keep the dialog responsive if a refresh/save fails.
        """
        self._cycle_timeline_legend_loc_override = None
        self._cycle_timeline_legend_loc_overrides = {"top": None, "bottom": None}
        prefs = self._get_cycle_plot_prefs()
        layout_defaults = _normalize_cycle_timeline_layout_manager_settings({})
        for key, value in layout_defaults.items():
            prefs[key] = value
        settings_ref = self._settings_dict()
        elements_map = settings_ref.get("plot_elements")
        if isinstance(elements_map, dict):
            raw_elements = elements_map.get("fig_cycle_timeline")
            if isinstance(raw_elements, list):
                updated_elements: List[Dict[str, Any]] = []
                for element in raw_elements:
                    if not isinstance(element, Mapping):
                        continue
                    updated = dict(element)
                    if str(updated.get("id") or "") in {
                        CYCLE_TIMELINE_AUTO_CURRENT_STATE_ELEMENT_ID,
                        CYCLE_TIMELINE_AUTO_CURRENT_STATE_MARKER_ELEMENT_ID,
                    }:
                        geometry = (
                            dict(updated.get("geometry") or {})
                            if isinstance(updated.get("geometry"), Mapping)
                            else {}
                        )
                        auto_x = _coerce_float(geometry.get("_auto_x"))
                        auto_y = _coerce_float(geometry.get("_auto_y"))
                        if auto_x is not None and auto_y is not None:
                            geometry["x"] = float(auto_x)
                            geometry["y"] = float(auto_y)
                        geometry["_manual_position"] = False
                        updated["geometry"] = geometry
                    updated_elements.append(updated)
                normalized = _normalize_plot_elements(
                    {"fig_cycle_timeline": updated_elements}
                ).get("fig_cycle_timeline", [])
                elements_map["fig_cycle_timeline"] = normalized
                self._plot_elements = elements_map
                annotation_store = getattr(self, "_annotation_store", None)
                if annotation_store is not None:
                    try:
                        annotation_store.set_elements("fig_cycle_timeline", normalized)
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting reset.
                        pass
        self._cycle_plot_prefs = prefs
        if isinstance(settings_ref, dict):
            settings_ref["cycle_plot_prefs"] = prefs
        try:
            _save_settings_to_disk()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting reset.
            pass
        try:
            self._refresh_cycle_views()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting reset.
            pass

    def _open_cycle_plot_options(self) -> None:
        """Open the Cycle Timeline Plot Settings dialog.

        Purpose:
            Expose focused cycle timeline plot controls for axis ranges, title, and
            second/third y-axis spacing plus timeline legend presentation.
        Why:
            Users need timeline-specific controls equivalent to key combined plot
            spacing options without opening the full combined Plot Settings dialog.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Creates one settings toplevel, persists preference edits, and refreshes
            timeline views when Apply/Reset actions run.
        Exceptions:
            Best-effort guards keep dialog actions resilient.
        """

        # Closure captures _open_cycle_plot_options state for callback wiring, kept nested to scope the handler, and invoked by bindings set in _open_cycle_plot_options.
        def _close() -> None:
            """Close value.
            Used by UI actions to close value safely."""
            if hasattr(self, "_cycle_plot_opts_win"):
                try:
                    self._cycle_plot_opts_win.destroy()
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
                self._cycle_plot_opts_win = None

        if getattr(self, "_cycle_plot_opts_win", None):
            try:
                self._cycle_plot_opts_win.lift()
                return
            except Exception:
                self._cycle_plot_opts_win = None

        prefs = self._get_cycle_plot_prefs()
        axis_layout = self._cycle_timeline_axis_layout_prefs(prefs)
        title_var = self._ensure_cycle_timeline_title_var()
        show_main_legend_var = tk.BooleanVar(
            value=bool(prefs.get("show_main_legend", True))
        )
        wide_bottom_legend_var = tk.BooleanVar(
            value=bool(prefs.get("export_bottom_legend_wide_under_xaxis", False))
        )
        center_bottom_legend_var = tk.BooleanVar(
            value=bool(prefs.get("bottom_legend_center_below_xlabel", False))
        )
        legend_layout_prefs = self._normalize_cycle_timeline_legend_layout_prefs(
            prefs
        )
        top_legend_wrap_var = tk.BooleanVar(
            value=bool(legend_layout_prefs.get("timeline_top_legend_wrap", False))
        )
        bottom_legend_wrap_var = tk.BooleanVar(
            value=bool(legend_layout_prefs.get("timeline_bottom_legend_wrap", False))
        )
        top = tk.Toplevel(self)
        top.title("Cycle Timeline Plot Settings")
        top.resizable(False, False)
        self._cycle_plot_opts_win = top

        # Closure captures _open_cycle_plot_options local context to keep helper logic scoped and invoked directly within _open_cycle_plot_options.
        def _make_entry(row: int, label: str, initial: Optional[float]) -> tk.StringVar:
            """Perform make entry.
            Used to keep the workflow logic localized and testable."""
            ttk.Label(top, text=label).grid(
                row=row, column=0, sticky="w", padx=6, pady=4
            )
            var = tk.StringVar(value="" if initial is None else f"{initial}")
            ttk.Entry(top, textvariable=var, width=10).grid(
                row=row, column=1, sticky="w", padx=6, pady=4
            )
            return var

        species_min_var = _make_entry(0, "Species y-min", prefs.get("species_min"))
        species_max_var = _make_entry(1, "Species y-max", prefs.get("species_max"))
        cycle_x_min_var = _make_entry(2, "Cycle x-min", prefs.get("cycle_x_min"))
        cycle_x_max_var = _make_entry(3, "Cycle x-max", prefs.get("cycle_x_max"))
        ph_min_var = _make_entry(4, "pH y-min", prefs.get("ph_min"))
        ph_max_var = _make_entry(5, "pH y-max", prefs.get("ph_max"))
        ph_axis_labelpad_var = _make_entry(
            6,
            "pH axis label padding",
            axis_layout.get("ph_axis_labelpad"),
        )
        ph_axis_spine_offset_var = _make_entry(
            7,
            "pH axis offset (axes units)",
            axis_layout.get("ph_axis_spine_offset"),
        )
        pco2_axis_labelpad_var = _make_entry(
            8,
            "Cycle CO2 axis label padding",
            axis_layout.get("pco2_axis_labelpad"),
        )
        top_legend_rows_var = _make_entry(
            9,
            "Top legend rows",
            legend_layout_prefs.get("timeline_top_legend_rows", 2),
        )
        bottom_legend_rows_var = _make_entry(
            10,
            "Bottom legend rows",
            legend_layout_prefs.get("timeline_bottom_legend_rows", 2),
        )
        ttk.Label(top, text="Cycle timeline title").grid(
            row=11, column=0, sticky="w", padx=6, pady=4
        )
        _ui_entry(top, textvariable=title_var, width=32).grid(
            row=11, column=1, sticky="w", padx=6, pady=4
        )
        ttk.Checkbutton(
            top,
            text="Show main plotting legend (shadowbox)",
            variable=show_main_legend_var,
        ).grid(row=12, column=0, columnspan=2, sticky="w", padx=6, pady=(2, 4))
        ttk.Checkbutton(
            top,
            text="Use wide bottom legend under x-axis (on-screen + preview + export)",
            variable=wide_bottom_legend_var,
        ).grid(row=13, column=0, columnspan=2, sticky="w", padx=6, pady=(2, 4))
        ttk.Checkbutton(
            top,
            text="Center bottom legend below x-axis label (fixed)",
            variable=center_bottom_legend_var,
        ).grid(row=14, column=0, columnspan=2, sticky="w", padx=6, pady=(2, 4))
        ttk.Checkbutton(
            top,
            text="Wrap top legend into rows",
            variable=top_legend_wrap_var,
        ).grid(row=15, column=0, columnspan=2, sticky="w", padx=6, pady=(2, 4))
        ttk.Checkbutton(
            top,
            text="Wrap bottom legend into rows",
            variable=bottom_legend_wrap_var,
        ).grid(row=16, column=0, columnspan=2, sticky="w", padx=6, pady=(2, 4))
        ttk.Label(
            top,
            text="This title is shared across Planning, Analysis, and Reprocessing.",
        ).grid(row=17, column=0, columnspan=2, sticky="w", padx=6, pady=(0, 4))
        ttk.Label(top, text="Used for on-screen timeline and exports.").grid(
            row=18, column=0, columnspan=2, sticky="w", padx=6, pady=(0, 4)
        )
        ttk.Label(
            top,
            text="(Legacy show-legend setting is mirrored automatically.)",
        ).grid(row=19, column=0, columnspan=2, sticky="w", padx=6, pady=(0, 4))

        # Closure captures _open_cycle_plot_options local context to keep helper logic scoped and invoked directly within _open_cycle_plot_options.
        def _parse_field(var: tk.StringVar) -> Optional[float]:
            """Parse field.
            Used to interpret field inputs safely."""
            raw = var.get().strip()
            if not raw:
                return None
            try:
                value = float(raw)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                return None
            if not math.isfinite(value):
                return None
            return value

        # Closure captures _open_cycle_plot_options state for callback wiring, kept nested to scope the handler, and invoked by bindings set in _open_cycle_plot_options.
        def _apply(reset: bool = False) -> None:
            """Apply value.
            Used to apply value changes to live state."""
            new_prefs = self._get_cycle_plot_prefs()
            default_title = self._cycle_timeline_default_title_text()
            if reset:
                new_prefs.update(
                    {
                        "species_min": None,
                        "species_max": None,
                        "cycle_x_min": None,
                        "cycle_x_max": None,
                        "ph_min": None,
                        "ph_max": None,
                        "show_main_legend": True,
                        "show_legend": True,
                        "export_bottom_legend_wide_under_xaxis": False,
                        "bottom_legend_center_below_xlabel": False,
                        "timeline_top_legend_wrap": False,
                        "timeline_top_legend_rows": 2,
                        "timeline_bottom_legend_wrap": False,
                        "timeline_bottom_legend_rows": 2,
                        "export_title": default_title,
                        "ph_axis_labelpad": 10.0,
                        "ph_axis_spine_offset": 1.02,
                        "pco2_axis_labelpad": 10.0,
                        "pco2_axis_spine_offset": 1.12,
                    }
                )
            else:
                resolved_title = str(title_var.get() or "").strip()
                resolved_title = resolved_title or default_title
                ph_axis_labelpad = _parse_field(ph_axis_labelpad_var)
                ph_axis_offset = _parse_field(ph_axis_spine_offset_var)
                pco2_axis_labelpad = _parse_field(pco2_axis_labelpad_var)
                new_prefs.update(
                    {
                        "species_min": _parse_field(species_min_var),
                        "species_max": _parse_field(species_max_var),
                        "cycle_x_min": _parse_field(cycle_x_min_var),
                        "cycle_x_max": _parse_field(cycle_x_max_var),
                        "ph_min": _parse_field(ph_min_var),
                        "ph_max": _parse_field(ph_max_var),
                        "show_main_legend": bool(show_main_legend_var.get()),
                        "show_legend": bool(show_main_legend_var.get()),
                        "export_bottom_legend_wide_under_xaxis": bool(
                            wide_bottom_legend_var.get()
                        ),
                        "bottom_legend_center_below_xlabel": bool(
                            center_bottom_legend_var.get()
                        ),
                        "timeline_top_legend_wrap": bool(top_legend_wrap_var.get()),
                        "timeline_top_legend_rows": _parse_field(top_legend_rows_var),
                        "timeline_bottom_legend_wrap": bool(
                            bottom_legend_wrap_var.get()
                        ),
                        "timeline_bottom_legend_rows": _parse_field(
                            bottom_legend_rows_var
                        ),
                        "export_title": resolved_title,
                        "ph_axis_labelpad": (
                            ph_axis_labelpad if ph_axis_labelpad is not None else 10.0
                        ),
                        "ph_axis_spine_offset": (
                            ph_axis_offset if ph_axis_offset is not None else 1.02
                        ),
                        "pco2_axis_labelpad": (
                            pco2_axis_labelpad
                            if pco2_axis_labelpad is not None
                            else 10.0
                        ),
                        # Preserve legacy detached-axis offset key for backward-safe reads.
                        "pco2_axis_spine_offset": float(
                            new_prefs.get("pco2_axis_spine_offset", 1.12)
                        ),
                    }
                )
            new_prefs["show_main_legend"] = bool(
                new_prefs.get("show_main_legend", True)
            )
            new_prefs["show_legend"] = bool(new_prefs["show_main_legend"])
            new_prefs["export_bottom_legend_wide_under_xaxis"] = bool(
                new_prefs.get("export_bottom_legend_wide_under_xaxis", False)
            )
            new_prefs["bottom_legend_center_below_xlabel"] = bool(
                new_prefs.get("bottom_legend_center_below_xlabel", False)
            )
            new_prefs.update(
                self._normalize_cycle_timeline_legend_layout_prefs(new_prefs)
            )
            if (
                _safe_float(new_prefs.get("cycle_x_min")) is not None
                and _safe_float(new_prefs.get("cycle_x_max")) is not None
                and float(new_prefs["cycle_x_min"]) >= float(new_prefs["cycle_x_max"])
            ):
                new_prefs["cycle_x_min"] = None
                new_prefs["cycle_x_max"] = None
            try:
                show_main_legend_var.set(bool(new_prefs["show_main_legend"]))
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                wide_bottom_legend_var.set(
                    bool(new_prefs["export_bottom_legend_wide_under_xaxis"])
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                center_bottom_legend_var.set(
                    bool(new_prefs["bottom_legend_center_below_xlabel"])
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                top_legend_wrap_var.set(
                    bool(new_prefs.get("timeline_top_legend_wrap", False))
                )
                bottom_legend_wrap_var.set(
                    bool(new_prefs.get("timeline_bottom_legend_wrap", False))
                )
                top_legend_rows_var.set(
                    str(int(new_prefs.get("timeline_top_legend_rows", 2)))
                )
                bottom_legend_rows_var.set(
                    str(int(new_prefs.get("timeline_bottom_legend_rows", 2)))
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            self._cycle_plot_prefs = new_prefs
            settings = getattr(self, "settings", None)
            if isinstance(settings, dict):
                settings["cycle_plot_prefs"] = new_prefs
                try:
                    _save_settings_to_disk()
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
            shared_title_var = self._ensure_cycle_timeline_title_var()
            normalized_title = str(new_prefs.get("export_title") or "").strip()
            normalized_title = normalized_title or default_title
            self._cycle_timeline_title_syncing = True
            try:
                shared_title_var.set(normalized_title)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            self._cycle_timeline_title_syncing = False
            try:
                self._refresh_cycle_views()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

        btn_frame = ttk.Frame(top)
        btn_frame.grid(row=20, column=0, columnspan=2, sticky="e", padx=6, pady=6)
        ttk.Button(btn_frame, text="Apply", command=lambda: _apply(False)).grid(
            row=0, column=0, padx=4
        )
        ttk.Button(btn_frame, text="Reset to Auto", command=lambda: _apply(True)).grid(
            row=0, column=1, padx=4
        )
        ttk.Button(
            btn_frame,
            text="Reset plot layout",
            command=self._reset_cycle_timeline_plot_layout,
        ).grid(row=0, column=2, padx=4)
        ttk.Button(btn_frame, text="Close", command=_close).grid(
            row=0, column=3, padx=4
        )

        top.protocol("WM_DELETE_WINDOW", _close)

    def _open_cycle_timeline_layout_manager(self) -> None:
        """Open the Cycle Timeline layout-manager controls dialog.

        Purpose:
            Expose timeline-specific conflict detection and solve aggressiveness.
        Why:
            Users need direct controls for timeline legend/label collision checks
            without opening global developer layout-health controls.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Creates one dialog, persists policy preferences, refreshes timeline
            render output, and rebuilds open preview windows when policy changes.
        Exceptions:
            Best-effort guards keep the dialog resilient to widget failures.
        """
        existing = getattr(self, "_cycle_timeline_layout_manager_window", None)
        if existing is not None and bool(getattr(existing, "winfo_exists", lambda: False)()):
            try:
                existing.deiconify()
                existing.lift()
                existing.focus_force()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return

        prefs = self._get_cycle_plot_prefs()
        policy = self._cycle_timeline_layout_manager_policy(prefs)
        window = tk.Toplevel(self)
        window.title("Cycle Timeline Layout Manager")
        window.transient(self)
        window.resizable(False, False)
        self._cycle_timeline_layout_manager_window = window

        container = ttk.Frame(window, padding=12)
        container.grid(row=0, column=0, sticky="nsew")
        container.grid_columnconfigure(1, weight=1)

        stage_vars: Dict[str, tk.Variable] = {
            "layout_manager_enabled": tk.BooleanVar(
                value=bool(policy.get("layout_manager_enabled", True))
            ),
            "layout_manager_strict_mode": tk.BooleanVar(
                value=bool(policy.get("layout_manager_strict_mode", False))
            ),
            "layout_manager_check_legend_conflicts": tk.BooleanVar(
                value=bool(policy.get("layout_manager_check_legend_conflicts", True))
            ),
            "layout_manager_check_axis_label_conflicts": tk.BooleanVar(
                value=bool(policy.get("layout_manager_check_axis_label_conflicts", True))
            ),
            "layout_manager_max_passes": tk.IntVar(
                value=int(policy.get("layout_manager_max_passes", 3))
            ),
            "layout_manager_min_legend_xlabel_gap_pts": tk.DoubleVar(
                value=float(policy.get("layout_manager_min_legend_xlabel_gap_pts", 8.0))
            ),
            "layout_manager_max_legend_xlabel_gap_pts": tk.DoubleVar(
                value=float(policy.get("layout_manager_max_legend_xlabel_gap_pts", 28.0))
            ),
            "layout_manager_min_axis_label_tick_gap_pts": tk.DoubleVar(
                value=float(
                    policy.get(
                        "layout_manager_min_axis_label_tick_gap_pts",
                        DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MIN_AXIS_LABEL_TICK_GAP_PTS,
                    )
                )
            ),
            "layout_manager_max_axis_label_tick_gap_pts": tk.DoubleVar(
                value=float(
                    policy.get(
                        "layout_manager_max_axis_label_tick_gap_pts",
                        DEFAULT_CYCLE_TIMELINE_LAYOUT_MANAGER_MAX_AXIS_LABEL_TICK_GAP_PTS,
                    )
                )
            ),
        }

        ttk.Label(
            container,
            text=(
                "Tune timeline layout conflict checks and bounded solve behavior for "
                "display and Plot Preview."
            ),
            justify="left",
            wraplength=520,
        ).grid(row=0, column=0, columnspan=3, sticky="w", pady=(0, 8))

        ttk.Checkbutton(
            container,
            text="Enable timeline layout manager verification",
            variable=stage_vars["layout_manager_enabled"],
        ).grid(row=1, column=0, columnspan=3, sticky="w", pady=(0, 4))
        ttk.Checkbutton(
            container,
            text="Strict mode (denser overlap prevention)",
            variable=stage_vars["layout_manager_strict_mode"],
        ).grid(row=2, column=0, columnspan=3, sticky="w", pady=(0, 4))
        ttk.Checkbutton(
            container,
            text="Check legend/x-label conflicts",
            variable=stage_vars["layout_manager_check_legend_conflicts"],
        ).grid(row=3, column=0, columnspan=3, sticky="w", pady=(0, 2))
        ttk.Checkbutton(
            container,
            text="Check right-axis label/tick conflicts",
            variable=stage_vars["layout_manager_check_axis_label_conflicts"],
        ).grid(row=4, column=0, columnspan=3, sticky="w", pady=(0, 8))

        def _build_numeric_row(
            row: int,
            label: str,
            key: str,
            *,
            minimum: float,
            maximum: float,
            increment: float,
            units: str,
        ) -> None:
            """Build one numeric input row for timeline layout-manager controls."""
            var = stage_vars.get(key)
            if var is None:
                return
            ttk.Label(container, text=label).grid(
                row=row, column=0, sticky="w", padx=(0, 8), pady=2
            )
            spin = ttk.Spinbox(
                container,
                from_=minimum,
                to=maximum,
                increment=increment,
                textvariable=var,
                width=10,
            )
            spin.grid(row=row, column=1, sticky="w", pady=2)
            ttk.Label(container, text=units).grid(
                row=row, column=2, sticky="w", padx=(6, 0), pady=2
            )

        _build_numeric_row(
            5,
            "Max solve passes",
            "layout_manager_max_passes",
            minimum=MIN_CYCLE_TIMELINE_LAYOUT_MANAGER_MAX_PASSES,
            maximum=MAX_CYCLE_TIMELINE_LAYOUT_MANAGER_MAX_PASSES,
            increment=1.0,
            units="passes",
        )
        _build_numeric_row(
            6,
            "Min legend-xlabel gap",
            "layout_manager_min_legend_xlabel_gap_pts",
            minimum=MIN_CYCLE_TIMELINE_LAYOUT_MANAGER_GAP_PTS,
            maximum=MAX_CYCLE_TIMELINE_LAYOUT_MANAGER_GAP_PTS,
            increment=0.5,
            units="pt",
        )
        _build_numeric_row(
            7,
            "Max legend-xlabel gap",
            "layout_manager_max_legend_xlabel_gap_pts",
            minimum=MIN_CYCLE_TIMELINE_LAYOUT_MANAGER_GAP_PTS,
            maximum=MAX_CYCLE_TIMELINE_LAYOUT_MANAGER_GAP_PTS,
            increment=0.5,
            units="pt",
        )
        _build_numeric_row(
            8,
            "Min axis-label/tick gap",
            "layout_manager_min_axis_label_tick_gap_pts",
            minimum=MIN_CYCLE_TIMELINE_LAYOUT_MANAGER_GAP_PTS,
            maximum=MAX_CYCLE_TIMELINE_LAYOUT_MANAGER_GAP_PTS,
            increment=0.5,
            units="pt",
        )
        _build_numeric_row(
            9,
            "Max axis-label/tick gap",
            "layout_manager_max_axis_label_tick_gap_pts",
            minimum=MIN_CYCLE_TIMELINE_LAYOUT_MANAGER_GAP_PTS,
            maximum=MAX_CYCLE_TIMELINE_LAYOUT_MANAGER_GAP_PTS,
            increment=0.5,
            units="pt",
        )

        def _collect_stage_policy() -> Dict[str, Any]:
            """Collect and normalize staged layout-manager values from dialog controls."""
            payload: Dict[str, Any] = {}
            for key, variable in stage_vars.items():
                getter = getattr(variable, "get", None)
                if not callable(getter):
                    continue
                try:
                    payload[key] = getter()
                except Exception:
                    continue
            return _normalize_cycle_timeline_layout_manager_settings(payload)

        def _close_window() -> None:
            """Close the timeline layout-manager dialog safely."""
            try:
                window.destroy()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            self._cycle_timeline_layout_manager_window = None

        def _apply_stage(close_after: bool = False) -> None:
            """Persist staged timeline layout-manager settings and refresh active views."""
            new_policy = _collect_stage_policy()
            self._apply_cycle_timeline_layout_manager_policy(new_policy)
            if close_after:
                _close_window()

        def _reset_to_defaults() -> None:
            """Reset staged timeline layout-manager controls to default values."""
            defaults = _normalize_cycle_timeline_layout_manager_settings({})
            for key, value in defaults.items():
                variable = stage_vars.get(key)
                setter = getattr(variable, "set", None)
                if variable is None or not callable(setter):
                    continue
                try:
                    setter(value)
                except Exception:
                    continue

        actions = ttk.Frame(container)
        actions.grid(row=10, column=0, columnspan=3, sticky="e", pady=(10, 0))
        ttk.Button(actions, text="Reset", command=_reset_to_defaults).pack(
            side="left", padx=(0, 6)
        )
        ttk.Button(actions, text="Apply", command=lambda: _apply_stage(False)).pack(
            side="left", padx=(0, 6)
        )
        ttk.Button(
            actions, text="Apply + Close", command=lambda: _apply_stage(True)
        ).pack(side="left", padx=(0, 6))
        ttk.Button(actions, text="Close", command=_close_window).pack(side="left")
        window.protocol("WM_DELETE_WINDOW", _close_window)

    def _toggle_cycle_tree_visibility(self, show: bool) -> None:
        """Toggle cycle tree visibility.
        Used to flip cycle tree visibility and refresh dependent views."""
        frame = getattr(self, "_sol_cycle_tree_frame", None)
        if frame is None:
            return
        try:
            if show:
                frame.grid()
            else:
                frame.grid_remove()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _refresh_cycle_views(
        self, timeline: Optional[Sequence[Dict[str, Any]]] = None
    ) -> None:
        """Refresh cycle timeline plot and simulation overlays for the active workflow.

        Purpose:
            Re-render cycle timeline surfaces from either explicit timeline rows
            or the latest cached workflow result payload.
        Why:
            Multiple callbacks can request a cycle redraw; centralized refresh
            keeps timeline and simulation overlays synchronized.
        Inputs:
            timeline: Optional explicit cycle timeline rows.
        Outputs:
            None.
        Side Effects:
            Updates the cycle timeline plot/callout view and simulation overlay.
        Exceptions:
            Downstream render helpers retain best-effort guards.
        """

        render_payload: Optional[Mapping[str, Any]] = None
        if timeline is None:
            state_result = self._get_cycle_result_for_workflow(
                self._current_solubility_workflow()
            )
            cycle_results = state_result or {}
            candidate_payload = cycle_results.get("timeline_render_payload")
            if not isinstance(candidate_payload, Mapping):
                candidate_payload = cycle_results.get("cycle_timeline_render_payload")
            if isinstance(candidate_payload, Mapping):
                payload_timeline = candidate_payload.get("timeline")
                if isinstance(payload_timeline, Sequence) and not isinstance(
                    payload_timeline, (str, bytes)
                ):
                    render_payload = candidate_payload
                    timeline = payload_timeline
                else:
                    timeline = cycle_results.get("timeline", [])
            else:
                timeline = cycle_results.get("timeline", [])
        self._dbg(
            "plotting.render",
            "cycle_timeline_caller_refresh_cycle_views workflow=%s timeline_rows=%s",
            self._current_solubility_workflow(),
            int(len(timeline or [])),
        )
        self._update_cycle_spec_view(
            timeline,
            workflow_key=self._current_solubility_workflow(),
            render_payload=render_payload,
        )
        self._update_sol_simulation_plot(
            getattr(self, "_sol_reaction_guidance", {}) or {},
            getattr(self, "_sol_tracking_entries", []),
        )

    def _open_cycle_timeline_plot_elements_editor(self) -> None:
        """Open the Plot Elements editor for the cycle timeline display plot.

        Purpose:
            Expose direct plot-element editing controls for the cycle timeline.
        Why:
            Timeline workflows now support persistent plot elements and preview
            synchronization, so users need a first-class editor entry point.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Opens/reuses the plot-elements editor bound to `fig_cycle_timeline`.
        Exceptions:
            Best-effort guards prevent UI interruption when timeline canvas is
            unavailable.
        """
        fig = getattr(self, "_sol_cycle_spec_fig", None)
        canvas = getattr(self, "_sol_cycle_spec_canvas", None)
        if fig is None or canvas is None:
            return
        self._ensure_cycle_timeline_annotation_controller()
        try:
            self._open_plot_elements_editor(fig, canvas, "fig_cycle_timeline")
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _resolve_cycle_timeline_preview_stage_key(
        self,
        *,
        message: Optional[str],
        progress_value: float,
    ) -> str:
        """Resolve a normalized stage token for cycle timeline preview loading.

        Purpose:
            Map preview status messages and progress to stable stage categories.
        Why:
            Heartbeat timers need deterministic terminal-state detection and
            readable fallback detail labels.
        Inputs:
            message: Optional preview status message.
            progress_value: Current determinate progress in the 0..100 range.
        Outputs:
            str: Canonical stage key.
        Side Effects:
            None.
        Exceptions:
            Invalid inputs fall back to `queued`.
        """
        if float(progress_value) >= 100.0:
            return "ready"
        text = str(message or "").strip().lower()
        if not text:
            return "queued"
        if "fail" in text or "error" in text or "unavailable" in text:
            return "failed"
        if "ready" in text:
            return "ready"
        if "final" in text:
            return "finalizing"
        if "add" in text or "install" in text:
            return "installing"
        if "build" in text:
            return "building"
        if "open" in text:
            return "opening"
        return "queued"

    def _stop_cycle_timeline_preview_loading_timer(self) -> None:
        """Stop cycle timeline preview loading heartbeat updates.

        Purpose:
            Cancel the scheduled timer callback used for elapsed updates.
        Why:
            Preview hide/close paths must not leave orphan `after` callbacks.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Cancels one pending Tk timer callback when present.
        Exceptions:
            Cancellation failures are ignored by design.
        """
        after_id = getattr(self, "_cycle_timeline_preview_timer_after_id", None)
        if after_id is None:
            return
        try:
            self.after_cancel(after_id)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        self._cycle_timeline_preview_timer_after_id = None

    def _start_cycle_timeline_preview_loading_timer(self) -> None:
        """Start cycle timeline preview loading heartbeat updates.

        Purpose:
            Keep preview overlay elapsed/progress text live between stage events.
        Why:
            Without heartbeat updates, timeline preview can look frozen while
            long build/finalize steps run.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Schedules recurring Tk callbacks while preview loading is active.
        Exceptions:
            Missing/destroyed overlay widgets short-circuit safely.
        """
        if getattr(self, "_cycle_timeline_preview_timer_after_id", None) is not None:
            return

        def _tick() -> None:
            """Refresh one cycle timeline preview loading heartbeat frame."""
            self._cycle_timeline_preview_timer_after_id = None
            overlay = getattr(self, "_cycle_timeline_preview_overlay", None)
            if overlay is None:
                return
            try:
                if not overlay.winfo_exists():
                    return
            except Exception:
                return
            started_at = getattr(self, "_cycle_timeline_preview_started_at", None)
            if not isinstance(started_at, (int, float)):
                started_at = time.monotonic()
                self._cycle_timeline_preview_started_at = float(started_at)
            elapsed_text = self._format_wall_clock_elapsed(
                max(0.0, time.monotonic() - float(started_at))
            )
            stage_key = str(
                getattr(self, "_cycle_timeline_preview_stage_key", "queued") or "queued"
            )
            message_base = str(
                getattr(self, "_cycle_timeline_preview_message_base", "") or ""
            ).strip()
            detail_base = str(
                getattr(self, "_cycle_timeline_preview_detail_base", "") or ""
            ).strip()
            detail_line = self._compose_loading_detail_with_elapsed(
                detail_base=detail_base,
                stage_key=stage_key,
                message=message_base or None,
                elapsed_text=elapsed_text,
            )
            composed_message = (
                f"{message_base}\n{detail_line}" if message_base else detail_line
            )
            label = getattr(self, "_cycle_timeline_preview_overlay_label", None)
            if label is not None:
                try:
                    label.configure(text=composed_message)
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
            progress_value = getattr(
                self, "_cycle_timeline_preview_progress_value", 0.0
            )
            try:
                progress_value = float(progress_value)
            except Exception:
                progress_value = 0.0
            progress_label = getattr(
                self, "_cycle_timeline_preview_overlay_progress_label", None
            )
            if progress_label is not None:
                try:
                    progress_label.configure(
                        text=self._format_loading_progress_footer(
                            progress_value,
                            elapsed_text,
                        )
                    )
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
            if progress_value >= 100.0 or stage_key in {"ready", "failed"}:
                return
            try:
                self._cycle_timeline_preview_timer_after_id = self.after(100, _tick)
            except Exception:
                self._cycle_timeline_preview_timer_after_id = None

        _tick()

    def _set_cycle_timeline_preview_loading_state(
        self,
        *,
        progress: Optional[float] = None,
        message: Optional[str] = None,
        reset: bool = False,
        show: bool = True,
    ) -> None:
        """Update cycle timeline Plot Preview overlay progress and status text.

        Purpose:
            Keep cycle timeline preview overlay feedback synchronized with preview
            build/install stages.
        Why:
            Timeline preview should mirror combined preview loading feedback so
            users can track rendering progress deterministically.
        Inputs:
            progress: Optional 0..100 progress value.
            message: Optional stage message for overlay label.
            reset: True to reset cached progress/message before updates.
            show: True to keep overlay visible after the update.
        Outputs:
            None.
        Side Effects:
            Updates overlay label/progress bar and visibility in preview window.
        Exceptions:
            Best-effort guards ignore stale/destroyed overlay widgets.
        """
        overlay = getattr(self, "_cycle_timeline_preview_overlay", None)
        if overlay is None:
            return
        try:
            if not overlay.winfo_exists():
                return
        except Exception:
            return
        if reset:
            self._cycle_timeline_preview_progress_value = 0.0
            self._cycle_timeline_preview_started_at = time.monotonic()
            self._cycle_timeline_preview_message_base = ""
            self._cycle_timeline_preview_detail_base = ""
            self._cycle_timeline_preview_stage_key = "queued"
        current_value = getattr(self, "_cycle_timeline_preview_progress_value", 0.0)
        try:
            current_value = float(current_value)
        except Exception:
            current_value = 0.0
        if not math.isfinite(current_value):
            current_value = 0.0
        target_value = current_value
        if progress is not None:
            try:
                parsed = float(progress)
            except Exception:
                parsed = current_value
            if not math.isfinite(parsed):
                parsed = current_value
            parsed = max(0.0, min(100.0, parsed))
            target_value = parsed if reset else max(current_value, parsed)
        message_base = str(
            getattr(self, "_cycle_timeline_preview_message_base", "") or ""
        ).strip()
        if message is not None:
            message_base = str(message).strip()
            self._cycle_timeline_preview_message_base = message_base
        normalized_stage = self._resolve_cycle_timeline_preview_stage_key(
            message=message_base or message,
            progress_value=target_value,
        )
        self._cycle_timeline_preview_stage_key = normalized_stage
        self._cycle_timeline_preview_detail_base = self._resolve_loading_detail_base(
            current_detail_base=getattr(
                self, "_cycle_timeline_preview_detail_base", ""
            ),
            stage_key=normalized_stage,
            message=message_base or message,
            detail=None,
            clear_on_message=message is not None,
        )
        started_at = getattr(self, "_cycle_timeline_preview_started_at", None)
        if not isinstance(started_at, (int, float)):
            started_at = time.monotonic()
            self._cycle_timeline_preview_started_at = float(started_at)
        elapsed_text = self._format_wall_clock_elapsed(
            max(0.0, time.monotonic() - float(started_at))
        )
        detail_line = self._compose_loading_detail_with_elapsed(
            detail_base=getattr(self, "_cycle_timeline_preview_detail_base", ""),
            stage_key=normalized_stage,
            message=message_base or message,
            elapsed_text=elapsed_text,
        )
        label = getattr(self, "_cycle_timeline_preview_overlay_label", None)
        if label is not None:
            try:
                if message_base:
                    label.configure(text=f"{message_base}\n{detail_line}")
                else:
                    label.configure(text=detail_line)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        progress_var = getattr(
            self, "_cycle_timeline_preview_overlay_progress_var", None
        )
        if progress_var is not None:
            try:
                progress_var.set(float(target_value))
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        progress_label = getattr(
            self, "_cycle_timeline_preview_overlay_progress_label", None
        )
        if progress_label is not None:
            try:
                progress_label.configure(
                    text=self._format_loading_progress_footer(
                        target_value,
                        elapsed_text,
                    )
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        self._cycle_timeline_preview_progress_value = float(target_value)
        if target_value >= 100.0 or normalized_stage in {"ready", "failed"}:
            self._stop_cycle_timeline_preview_loading_timer()
        else:
            self._start_cycle_timeline_preview_loading_timer()
        if show:
            try:
                overlay.place(relx=0.0, rely=0.0, relwidth=1.0, relheight=1.0)
                overlay.lift()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        window = getattr(self, "_cycle_timeline_preview_window", None)
        if window is not None:
            try:
                window.update_idletasks()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

    def _hide_cycle_timeline_preview_loading(self) -> None:
        """Hide the cycle timeline Plot Preview overlay.

        Purpose:
            Clear timeline preview splash UI after success/failure handling.
        Why:
            Overlay teardown should be centralized so preview paths stay
            deterministic and avoid stale loading layers.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Stops preview loading heartbeat callbacks and calls `place_forget()`
            on the cycle timeline preview overlay.
        Exceptions:
            Best-effort guards ignore missing/stale overlay widgets.
        """
        self._stop_cycle_timeline_preview_loading_timer()
        overlay = getattr(self, "_cycle_timeline_preview_overlay", None)
        if overlay is None:
            return
        try:
            overlay.place_forget()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _teardown_cycle_timeline_preview_annotation_controller(
        self, *, clear_dirty_flag: bool
    ) -> None:
        """Disconnect and clear cycle timeline preview annotation controller.

        Purpose:
            Remove preview-only annotation event hooks during preview rebuild/close.
        Why:
            Preview canvas swaps and window teardown must not leak stale Matplotlib
            callback bindings.
        Inputs:
            clear_dirty_flag: True to clear pending preview-change sync markers.
        Outputs:
            None.
        Side Effects:
            Disconnects controller and resets preview controller attributes.
        Exceptions:
            Best-effort guards suppress disconnect failures.
        """
        controller = getattr(
            self, "_cycle_timeline_preview_annotation_controller", None
        )
        if controller is not None:
            try:
                controller.disconnect()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        self._cycle_timeline_preview_annotation_controller = None
        if clear_dirty_flag:
            self._cycle_timeline_preview_plot_id = None
            self._cycle_timeline_preview_elements_changed = False

    def _teardown_cycle_timeline_preview_legend_tracking(self) -> None:
        """Disconnect cycle timeline preview legend-tracking callbacks.

        Purpose:
            Remove preview legend drag event handlers before canvas/figure swaps.
        Why:
            Preview rebuild and close paths can replace canvases, so stale event
            callbacks must be disconnected to avoid duplicate capture behavior.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Disconnects Matplotlib callbacks and clears preview drag state.
        Exceptions:
            Best-effort guards suppress disconnect failures.
        """
        prior_canvas = getattr(self, "_cycle_timeline_preview_legend_canvas", None)
        prior_cids = getattr(self, "_cycle_timeline_preview_legend_event_cids", None)
        if not isinstance(prior_cids, Mapping):
            prior_cids = {}
        if prior_canvas is not None:
            for cid in prior_cids.values():
                if not cid:
                    continue
                try:
                    prior_canvas.mpl_disconnect(cid)
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
        self._cycle_timeline_preview_legend_canvas = None
        self._cycle_timeline_preview_legend_event_cids = {}
        self._cycle_timeline_preview_legend_drag_active = False
        self._cycle_timeline_preview_legend_drag_moved = False
        self._cycle_timeline_preview_legend_drag_start_xy = None
        self._cycle_timeline_preview_legend_drag_target = None

    def _register_cycle_timeline_preview_legend_tracking(
        self,
        fig: Optional[Figure],
        *,
        canvas: Optional[Any] = None,
    ) -> None:
        """Register timeline preview legend drag callbacks with close parity.

        Purpose:
            Capture cycle timeline legend positions on preview drag release.
        Why:
            Preview-close sync must preserve user legend drags using the same
            drag lifecycle semantics as the combined plot workflow.
        Inputs:
            fig: Timeline preview figure whose legends should be tracked.
            canvas: Optional Matplotlib canvas; defaults to `fig.canvas`.
        Outputs:
            None.
        Side Effects:
            Enables draggable timeline legends and binds press/move/release
            callbacks that capture role-specific legend overrides.
        Exceptions:
            Best-effort guards suppress callback wiring failures.
        """
        self._teardown_cycle_timeline_preview_legend_tracking()
        if fig is None:
            return
        canvas_ref = canvas if canvas is not None else getattr(fig, "canvas", None)
        if canvas_ref is None:
            return
        legends = []
        try:
            legends = _collect_gl260_legends(fig)
        except Exception:
            legends = []
        role_legends = []
        for legend in legends:
            role_value = str(getattr(legend, "_cycle_timeline_legend_role", "")).strip().lower()
            if role_value not in {"top", "bottom"}:
                continue
            role_legends.append(legend)
            if bool(
                getattr(legend, "_cycle_timeline_bottom_center_below_xlabel", False)
            ):
                _make_legend_draggable(legend, enabled=False)
                continue
            update_mode = (
                "bbox"
                if bool(getattr(legend, "_cycle_timeline_bottom_wide_under_xaxis", False))
                else "loc"
            )
            _make_legend_draggable(legend, enabled=True, update_mode=update_mode)
        if not role_legends:
            return

        self._cycle_timeline_preview_legend_drag_active = False
        self._cycle_timeline_preview_legend_drag_moved = False
        self._cycle_timeline_preview_legend_drag_start_xy = None
        self._cycle_timeline_preview_legend_drag_target = None

        def _on_press(_event: Any = None) -> None:
            """Handle one preview legend mouse-press event.

            Purpose:
                Start drag tracking when the press hits a role-tagged legend.
            Why:
                Release capture should only run for true legend drags.
            Inputs:
                _event: Matplotlib mouse-press event payload.
            Outputs:
                None.
            Side Effects:
                Seeds drag-state flags and starting pointer coordinates.
            Exceptions:
                Invalid event payloads are ignored.
            """
            self._cycle_timeline_preview_legend_drag_active = False
            self._cycle_timeline_preview_legend_drag_moved = False
            self._cycle_timeline_preview_legend_drag_start_xy = None
            self._cycle_timeline_preview_legend_drag_target = None
            if _event is None:
                return
            event_button = getattr(_event, "button", None)
            if event_button not in (None, 1):
                return
            event_x = getattr(_event, "x", None)
            event_y = getattr(_event, "y", None)
            if event_x is None or event_y is None:
                return
            for legend in role_legends:
                try:
                    contains, _details = legend.contains(_event)
                except Exception:
                    contains = False
                if not bool(contains):
                    continue
                self._cycle_timeline_preview_legend_drag_active = True
                self._cycle_timeline_preview_legend_drag_start_xy = (
                    float(event_x),
                    float(event_y),
                )
                self._cycle_timeline_preview_legend_drag_target = legend
                return

        def _on_motion(_event: Any = None) -> None:
            """Handle one preview legend mouse-motion event.

            Purpose:
                Mark drag movement once pointer motion exceeds click jitter.
            Why:
                Avoid false-positive drag captures from simple clicks.
            Inputs:
                _event: Matplotlib mouse-motion event payload.
            Outputs:
                None.
            Side Effects:
                Updates moved-state when drag distance passes threshold.
            Exceptions:
                Invalid event payloads are ignored.
            """
            if not bool(getattr(self, "_cycle_timeline_preview_legend_drag_active", False)):
                return
            start_xy = getattr(self, "_cycle_timeline_preview_legend_drag_start_xy", None)
            event_x = getattr(_event, "x", None)
            event_y = getattr(_event, "y", None)
            if start_xy is None or event_x is None or event_y is None:
                return
            dx = float(event_x) - float(start_xy[0])
            dy = float(event_y) - float(start_xy[1])
            if ((dx * dx) + (dy * dy)) < 9.0:
                return
            self._cycle_timeline_preview_legend_drag_moved = True

        def _on_release(_event: Any = None) -> None:
            """Handle one preview legend mouse-release event.

            Purpose:
                Persist timeline legend overrides after a completed drag.
            Why:
                Preview-close sync and export should reflect in-session drag
                placement for both top and bottom timeline legends.
            Inputs:
                _event: Matplotlib mouse-release event payload (unused).
            Outputs:
                None.
            Side Effects:
                Captures role-specific legend overrides with `source="drag"`.
            Exceptions:
                Best-effort guards suppress capture failures.
            """
            _ = _event
            try:
                if not bool(getattr(self, "_cycle_timeline_preview_legend_drag_active", False)):
                    return
                if not bool(getattr(self, "_cycle_timeline_preview_legend_drag_moved", False)):
                    return
                preview_fig = getattr(self, "_cycle_timeline_preview_fig", None)
                if preview_fig is not fig:
                    return
                capture_multi = getattr(
                    self, "_capture_cycle_timeline_legend_locs_from_fig", None
                )
                if callable(capture_multi):
                    capture_multi(fig, source="drag")
                else:
                    self._capture_cycle_timeline_legend_loc_from_fig(
                        fig,
                        source="drag",
                    )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            finally:
                self._cycle_timeline_preview_legend_drag_active = False
                self._cycle_timeline_preview_legend_drag_moved = False
                self._cycle_timeline_preview_legend_drag_start_xy = None
                self._cycle_timeline_preview_legend_drag_target = None

        try:
            press_cid = canvas_ref.mpl_connect("button_press_event", _on_press)
            motion_cid = canvas_ref.mpl_connect("motion_notify_event", _on_motion)
            release_cid = canvas_ref.mpl_connect("button_release_event", _on_release)
        except Exception:
            self._cycle_timeline_preview_legend_event_cids = {}
            self._cycle_timeline_preview_legend_canvas = None
            return
        self._cycle_timeline_preview_legend_canvas = canvas_ref
        self._cycle_timeline_preview_legend_event_cids = {
            "button_press_event": press_cid,
            "motion_notify_event": motion_cid,
            "button_release_event": release_cid,
        }

    def _on_cycle_timeline_preview_elements_changed(self, plot_id: str) -> None:
        """Track timeline Plot Preview element edits for close-time sync.

        Purpose:
            Mark preview element edits so they can be pushed to display on close.
        Why:
            Requested behavior keeps display synchronization explicit at preview
            close rather than on every drag event.
        Inputs:
            plot_id: Plot identifier reported by preview annotation controller.
        Outputs:
            None.
        Side Effects:
            Sets preview dirty flags and marks plot-elements dirty for plot id.
        Exceptions:
            Best-effort guards suppress dirty-flag errors.
        """
        if not plot_id:
            return
        self._cycle_timeline_preview_plot_id = plot_id
        self._cycle_timeline_preview_elements_changed = True
        try:
            self._mark_plot_elements_dirty(plot_id)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _install_cycle_timeline_preview_annotation_controller(
        self,
        fig: Optional[Figure],
        canvas: Optional[FigureCanvasTkAgg],
        *,
        plot_id: str,
    ) -> None:
        """Attach preview-only plot-elements controller for timeline preview.

        Purpose:
            Enable element drag/edit interactions inside cycle timeline preview.
        Why:
            Preview adjustments should persist to the shared plot-elements store and
            sync back to display when the preview closes.
        Inputs:
            fig: Preview figure.
            canvas: Preview canvas.
            plot_id: Plot identifier for persisted element storage.
        Outputs:
            None.
        Side Effects:
            Replaces any existing preview controller and binds event callbacks.
        Exceptions:
            Best-effort guards keep preview usable when controller setup fails.
        """
        self._teardown_cycle_timeline_preview_annotation_controller(
            clear_dirty_flag=False
        )
        if fig is None or canvas is None or not plot_id:
            return
        try:
            axes_map = self._resolve_plot_element_axes(fig)
        except Exception:
            axes_map = {}
        try:
            axis_labels = self._plot_element_axis_labels(fig)
        except Exception:
            axis_labels = {}
        try:
            trace_choices = self._plot_element_trace_option_pairs(plot_id, fig=fig)
        except Exception:
            trace_choices = _trace_series_option_pairs()
        try:
            controller = PlotAnnotationsController(
                plot_id,
                fig,
                canvas,
                self._annotation_store,
                self._annotation_renderer,
                axes_map,
                axis_labels,
                trace_choices=trace_choices,
                on_elements_changed=self._on_cycle_timeline_preview_elements_changed,
            )
            controller.set_mode("select")
            controller.cancel_place_element()
            self._cycle_timeline_preview_annotation_controller = controller
            self._cycle_timeline_preview_plot_id = plot_id
        except Exception:
            self._cycle_timeline_preview_annotation_controller = None

    def _sync_cycle_timeline_preview_elements_to_display(
        self,
        plot_id: str,
        *,
        retarget_controller: bool = True,
    ) -> None:
        """Apply timeline element edits to the main cycle timeline display plot.

        Purpose:
            Synchronize persisted timeline element edits into the visible timeline plot.
        Why:
            Timeline editing can happen from preview and generated-tab surfaces,
            and the Advanced Speciation timeline display must stay synchronized.
        Inputs:
            plot_id: Plot identifier whose timeline elements changed.
            retarget_controller: When True, retarget the shared Plot Elements
                controller to the display canvas before rendering.
        Outputs:
            None.
        Side Effects:
            Re-renders plot elements on the display timeline figure/canvas and
            refreshes an open plot-elements panel for the same plot id.
        Exceptions:
            Best-effort guards keep close workflow resilient on sync failures.
        """
        if not plot_id:
            return
        display_fig = getattr(self, "_sol_cycle_spec_fig", None)
        display_canvas = getattr(self, "_sol_cycle_spec_canvas", None)
        if display_fig is None or display_canvas is None:
            return
        controller = self._plot_annotation_controllers.get(plot_id)
        if controller is not None and retarget_controller:
            try:
                axes_map = self._resolve_plot_element_axes(display_fig)
            except Exception:
                axes_map = {}
            try:
                axis_labels = self._plot_element_axis_labels(display_fig)
            except Exception:
                axis_labels = {}
            try:
                controller.set_target(display_fig, display_canvas)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                controller.update_axis_map(display_fig, axes_map, axis_labels)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                controller.render()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            panel = self._plot_annotation_panels.get(plot_id)
            if panel is not None:
                try:
                    panel.refresh()
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
        else:
            try:
                self._apply_plot_elements(display_fig, plot_id)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        try:
            display_canvas.draw_idle()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _cycle_timeline_axes_from_fig(
        self, fig: Optional[Figure]
    ) -> Tuple[Any, Any, Any]:
        """Return the role-tagged Cycle Timeline axes from one figure.

        Purpose:
            Resolve the sodium, pH, and uptake axes from generated/preview figures.
        Why:
            Legend and Plot Elements sync paths need to apply persisted timeline
            state to whichever visible surface owns the current figure.
        Inputs:
            fig: Candidate Cycle Timeline figure.
        Outputs:
            Tuple `(ax, ax2, ax3)` where missing roles are returned as None.
        Side Effects:
            None.
        Exceptions:
            Invalid figures return a tuple of None values.
        """
        if fig is None:
            return None, None, None
        primary_axis = None
        right_axis = None
        third_axis = None
        for axis in list(getattr(fig, "axes", []) or []):
            role = str(getattr(axis, "_gl260_axis_role", "") or "").strip().lower()
            if role == "primary" and primary_axis is None:
                primary_axis = axis
            elif role == "right" and right_axis is None:
                right_axis = axis
            elif role == "third" and third_axis is None:
                third_axis = axis
        return primary_axis, right_axis, third_axis

    def _sync_cycle_timeline_generated_tab_from_persisted_state(
        self,
        plot_id: str,
        *,
        force_full_rebuild: bool = False,
        reason: str = "",
        sync_elements: bool = True,
        sync_legends: bool = True,
    ) -> None:
        """Apply persisted Cycle Timeline state to the generated notebook tab.

        Purpose:
            Back-propagate preview/settings/element changes to the new-tab Cycle
            Timeline surface without requiring the user to press Refresh.
        Why:
            The combined triple-axis workflow updates the visible tab after preview
            edits; timeline preview close must do the same for parity.
        Inputs:
            plot_id: Timeline plot identifier.
            force_full_rebuild: True to rebuild the generated tab through the
                normal refresh pipeline.
            reason: Optional refresh/sync reason label.
            sync_elements: True to reapply Plot Elements on the tab figure.
            sync_legends: True to rebuild role-specific legends from persisted
                overrides and layout preferences.
        Outputs:
            None.
        Side Effects:
            May refresh the generated tab, retarget the Plot Elements controller,
            rebuild legends, and redraw the tab canvas.
        Exceptions:
            Best-effort guards keep callers resilient when the generated tab is
            not open.
        """
        if str(plot_id or "").strip() != "fig_cycle_timeline":
            return
        if force_full_rebuild:
            self._refresh_plot_for_plot_id(
                "fig_cycle_timeline",
                reason=reason or "Refreshing Cycle Timeline...",
                rearm_overlay=True,
                capture_combined_legend=False,
                force_full_rebuild=True,
            )
            return
        try:
            _frame, tab_canvas = self._find_plot_tab_canvas("fig_cycle_timeline_tab")
        except Exception:
            tab_canvas = None
        tab_fig = getattr(tab_canvas, "figure", None)
        if tab_canvas is None or tab_fig is None:
            return
        if sync_elements:
            controller = self._plot_annotation_controllers.get(plot_id)
            if controller is not None:
                try:
                    axes_map = self._resolve_plot_element_axes(tab_fig)
                    axis_labels = self._plot_element_axis_labels(tab_fig)
                    controller.set_target(tab_fig, tab_canvas)
                    controller.update_axis_map(tab_fig, axes_map, axis_labels)
                    controller.render()
                except Exception:
                    try:
                        self._apply_plot_elements(tab_fig, plot_id)
                    except Exception:
                        pass
            else:
                try:
                    self._apply_plot_elements(tab_fig, plot_id)
                except Exception:
                    pass
        if sync_legends:
            ax, ax2, ax3 = self._cycle_timeline_axes_from_fig(tab_fig)
            if ax is not None and ax2 is not None and ax3 is not None:
                prefs = self._get_cycle_plot_prefs()
                try:
                    self._build_cycle_timeline_subplot_legends(
                        fig=tab_fig,
                        ax=ax,
                        ax2=ax2,
                        ax3=ax3,
                        show_main_legend=bool(prefs.get("show_main_legend", True)),
                        preview_interactive_legend=False,
                        update_session_refs=False,
                    )
                    self._reposition_cycle_timeline_centered_bottom_legends(tab_fig)
                    self._register_cycle_timeline_generated_tab_legend_tracking(
                        tab_fig,
                        canvas=tab_canvas,
                    )
                except Exception:
                    pass
        try:
            tab_canvas.draw_idle()
        except Exception:
            pass

    def _sync_cycle_timeline_visible_surfaces_from_persisted_state(
        self,
        plot_id: str = "fig_cycle_timeline",
        *,
        reason: str = "",
        force_generated_rebuild: bool = False,
        retarget_display_controller: bool = True,
        sync_elements: bool = True,
        sync_legends: bool = True,
    ) -> None:
        """Apply persisted Cycle Timeline state to all visible timeline surfaces.

        Purpose:
            Provide one sync contract for settings, Data Trace, Plot Elements, and
            preview-close workflows.
        Why:
            Timeline display and generated-tab surfaces previously used separate
            update paths, causing preview edits to appear on one surface but not
            the other.
        Inputs:
            plot_id: Timeline plot identifier.
            reason: Optional diagnostic label.
            force_generated_rebuild: True when trace-affecting changes require a
                generated-tab rebuild.
            retarget_display_controller: True to retarget the shared Plot Elements
                controller to the Advanced Speciation display before rendering.
            sync_elements: True to reapply Plot Elements.
            sync_legends: True to refresh role-specific legends.
        Outputs:
            None.
        Side Effects:
            Updates Advanced Speciation display and generated tab surfaces when
            present.
        Exceptions:
            Individual surface sync failures are ignored.
        """
        if str(plot_id or "").strip() != "fig_cycle_timeline":
            return
        if sync_elements:
            try:
                self._sync_cycle_timeline_preview_elements_to_display(
                    plot_id,
                    retarget_controller=retarget_display_controller,
                )
            except Exception:
                pass
        if sync_legends:
            try:
                display_fig = getattr(self, "_sol_cycle_spec_fig", None)
                layout_verify_fn = getattr(
                    self, "_run_cycle_timeline_layout_manager_verification", None
                )
                if callable(layout_verify_fn) and display_fig is not None:
                    layout_verify_fn(
                        display_fig,
                        mode="display",
                        prefs=self._get_cycle_plot_prefs(),
                        show_splash=False,
                    )
            except Exception:
                pass
        self._sync_cycle_timeline_generated_tab_from_persisted_state(
            plot_id,
            force_full_rebuild=force_generated_rebuild,
            reason=reason,
            sync_elements=sync_elements,
            sync_legends=sync_legends,
        )

    def _close_cycle_timeline_plot_preview_window(self, _event: Any = None) -> None:
        """Close cycle timeline Plot Preview and sync element edits on close.

        Purpose:
            Tear down timeline preview resources safely.
        Why:
            Preview callbacks and interactive controllers must be cleaned up, and
            requested behavior syncs element edits back to display at close time.
        Inputs:
            _event: Optional Tk event payload from window destroy hook.
        Outputs:
            None.
        Side Effects:
            Destroys preview figure/widgets, clears preview state, and applies
            pending plot-element edits plus timeline legend placement to display.
        Exceptions:
            Best-effort guards suppress cleanup and sync exceptions.
        """
        window = getattr(self, "_cycle_timeline_preview_window", None)
        if window is None:
            return
        if _event is not None and getattr(_event, "widget", None) is not window:
            return
        if bool(getattr(self, "_cycle_timeline_preview_closing", False)):
            return
        self._cycle_timeline_preview_closing = True
        self._stop_cycle_timeline_preview_loading_timer()
        try:
            self._cycle_timeline_preview_request_token += 1
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        preview_plot_id = getattr(self, "_cycle_timeline_preview_plot_id", None)
        preview_elements_changed = bool(
            getattr(self, "_cycle_timeline_preview_elements_changed", False)
        )
        self._teardown_cycle_timeline_preview_annotation_controller(
            clear_dirty_flag=False
        )
        preview_fig = getattr(self, "_cycle_timeline_preview_fig", None)
        captured_preview_locs: Dict[str, Optional[Any]] = {"top": None, "bottom": None}
        if preview_fig is not None:
            try:
                capture_multi = getattr(
                    self, "_capture_cycle_timeline_legend_locs_from_fig", None
                )
                if callable(capture_multi):
                    captured_preview_locs = capture_multi(preview_fig, source="sync")
                else:
                    single_capture = self._capture_cycle_timeline_legend_loc_from_fig(
                        preview_fig,
                        source="sync",
                    )
                    captured_preview_locs = {"top": single_capture, "bottom": None}
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                captured_preview_locs = {"top": None, "bottom": None}
            if any(value is not None for value in captured_preview_locs.values()):
                try:
                    apply_multi = getattr(
                        self, "_apply_cycle_timeline_legend_locs_to_display", None
                    )
                    if callable(apply_multi):
                        apply_multi(captured_preview_locs)
                    else:
                        self._apply_cycle_timeline_legend_loc_to_display(
                            captured_preview_locs.get("top")
                        )
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
                try:
                    display_fig = getattr(self, "_sol_cycle_spec_fig", None)
                    layout_verify_fn = getattr(
                        self, "_run_cycle_timeline_layout_manager_verification", None
                    )
                    if callable(layout_verify_fn) and display_fig is not None:
                        layout_verify_fn(
                            display_fig,
                            mode="display",
                            prefs=self._get_cycle_plot_prefs(),
                            show_splash=False,
                        )
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
                try:
                    display_fig = getattr(self, "_sol_cycle_spec_fig", None)
                    capture_multi = getattr(
                        self, "_capture_cycle_timeline_legend_locs_from_fig", None
                    )
                    if callable(capture_multi):
                        capture_multi(display_fig, source="sync")
                    else:
                        self._capture_cycle_timeline_legend_loc_from_fig(
                            display_fig,
                            source="sync",
                        )
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
                try:
                    self._sync_cycle_timeline_generated_tab_from_persisted_state(
                        "fig_cycle_timeline",
                        reason="cycle_timeline_preview_legend_close",
                        sync_elements=False,
                        sync_legends=True,
                    )
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
            try:
                self._teardown_cycle_timeline_preview_legend_tracking()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                plt.close(preview_fig)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        else:
            try:
                self._teardown_cycle_timeline_preview_legend_tracking()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        try:
            if _event is None and window.winfo_exists():
                window.destroy()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        self._cycle_timeline_preview_window = None
        self._cycle_timeline_preview_host = None
        self._cycle_timeline_preview_content = None
        self._cycle_timeline_preview_overlay = None
        self._cycle_timeline_preview_overlay_label = None
        self._cycle_timeline_preview_overlay_progress_var = None
        self._cycle_timeline_preview_overlay_progress_label = None
        self._cycle_timeline_preview_canvas = None
        self._cycle_timeline_preview_toolbar = None
        self._cycle_timeline_preview_layout_controls = None
        self._cycle_timeline_preview_fig = None
        self._cycle_timeline_preview_progress_value = 0.0
        self._cycle_timeline_preview_started_at = None
        self._cycle_timeline_preview_message_base = ""
        self._cycle_timeline_preview_detail_base = ""
        self._cycle_timeline_preview_stage_key = "ready"
        self._cycle_timeline_preview_timer_after_id = None
        if preview_elements_changed and preview_plot_id:
            try:
                force_rebuild = (
                    self._plot_elements_trace_behavior_signature(preview_plot_id)
                    != ()
                )
                self._sync_cycle_timeline_visible_surfaces_from_persisted_state(
                    preview_plot_id,
                    reason="cycle_timeline_preview_elements_close",
                    force_generated_rebuild=force_rebuild,
                    sync_elements=True,
                    sync_legends=False,
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        self._teardown_cycle_timeline_preview_annotation_controller(
            clear_dirty_flag=True
        )
        self._cycle_timeline_preview_closing = False

    def _open_cycle_timeline_plot_in_new_tab(self) -> None:
        """Open cycle timeline in main plot notebook using generated-tab pipeline.

        Purpose:
            Render cycle timeline into the main notebook as a generated plot tab.
        Why:
            Advanced Speciation should reuse the tested generated-tab pipeline
            (toolbar/splash/refresh/export/layout plumbing) instead of duplicating
            a separate render path.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Builds/reuses one dedicated timeline tab in the main plot notebook,
            refreshes existing tab content when already open, and shows guarded
            user feedback when timeline data is unavailable.
        Exceptions:
            Dialog and tab-routing failures are guarded to keep UI responsive.
        """
        plot_key = "fig_cycle_timeline_tab"
        profile = self._plot_tab_profile(plot_key)
        if not isinstance(profile, Mapping):
            try:
                messagebox.showerror(
                    "Cycle Speciation Timeline",
                    "Timeline plot profile is unavailable in this build.",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        plot_id = str(
            profile.get("plot_id") or self._plot_key_to_plot_id(plot_key) or ""
        ).strip()
        if not plot_id:
            plot_id = "fig_cycle_timeline"
        tab_title = str(profile.get("title") or "Cycle Speciation Timeline").strip()
        if not tab_title:
            tab_title = "Cycle Speciation Timeline"
        refresh_message = str(profile.get("refresh_message") or "").strip()
        if not refresh_message:
            refresh_message = "Refreshing cycle timeline plot..."
        existing_frame, existing_canvas = self._find_plot_tab_canvas(plot_key)
        if existing_frame is not None and existing_canvas is not None:
            try:
                self.nb.select(existing_frame)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            if plot_id:
                self._refresh_plot_for_plot_id(
                    plot_id,
                    reason=refresh_message,
                    rearm_overlay=True,
                    capture_combined_legend=False,
                    force_full_rebuild=False,
                )
            else:
                self._force_plot_refresh(
                    existing_frame,
                    existing_canvas,
                    capture_combined_legend=False,
                    refresh_reason=refresh_message,
                )
            return
        fig_size = None
        try:
            fig_size = self._compute_target_figsize_inches()
        except Exception:
            fig_size = None
        fig = self._build_generated_plot_tab_figure(
            plot_key,
            mode="display",
            fig_size=fig_size,
        )
        if fig is None:
            try:
                messagebox.showinfo(
                    "Cycle Speciation Timeline",
                    "Run a workflow to generate cycle timeline data before opening a new plot tab.",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        if plot_id:
            try:
                self._remove_plot_tab_by_plot_id(plot_id)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        frame = self._add_plot_tab(
            tab_title,
            fig,
            plot_key=plot_key,
            plot_id_override=plot_id,
        )
        try:
            self.nb.select(frame)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _open_cycle_timeline_plot_preview(self) -> None:
        """Open cycle timeline Plot Preview with plot-element editing support.

        Purpose:
            Render an export-sized (11x8.5) timeline preview with toolbar controls
            and interactive plot-element dragging.
        Why:
            Timeline users need the same preview/edit workflow available on the
            combined triple-axis plot before committing layout adjustments.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Creates/reuses preview window, builds preview figure, installs preview
            plot-elements controller, and updates loading overlay states.
        Exceptions:
            Failures are surfaced to users and preview overlay is cleared.
        """
        preview_plot_id = "fig_cycle_timeline"
        window = getattr(self, "_cycle_timeline_preview_window", None)
        if window is None or not bool(getattr(window, "winfo_exists", lambda: False)()):
            window = tk.Toplevel(self)
            window.title("Cycle Timeline Plot Preview (Export 11x8.5)")
            window.transient(self)
            host = ttk.Frame(window)
            host.pack(fill="both", expand=True)
            content = ttk.Frame(host)
            content.pack(fill="both", expand=True)
            try:
                base_bg = window.cget("background")
            except Exception:
                base_bg = None
            overlay = tk.Frame(host, background=base_bg)
            center = ttk.Frame(overlay)
            center.place(relx=0.5, rely=0.5, anchor="center")
            label = ttk.Label(
                center,
                text="Opening Preview...",
                width=48,
                anchor="center",
                justify="center",
            )
            label.pack(side="top", pady=(0, 8))
            progress_var = tk.DoubleVar(master=overlay, value=0.0)
            ttk.Progressbar(
                center,
                mode="determinate",
                length=260,
                maximum=100.0,
                variable=progress_var,
            ).pack(side="top")
            progress_label = ttk.Label(center, text="0% | 0.00s", width=48)
            progress_label.pack(side="top", pady=(6, 0))
            overlay.place(relx=0.0, rely=0.0, relwidth=1.0, relheight=1.0)
            overlay.place_forget()
            self._cycle_timeline_preview_window = window
            self._cycle_timeline_preview_host = host
            self._cycle_timeline_preview_content = content
            self._cycle_timeline_preview_overlay = overlay
            self._cycle_timeline_preview_overlay_label = label
            self._cycle_timeline_preview_overlay_progress_var = progress_var
            self._cycle_timeline_preview_overlay_progress_label = progress_label
            self._cycle_timeline_preview_progress_value = 0.0
            self._cycle_timeline_preview_started_at = None
            self._cycle_timeline_preview_message_base = ""
            self._cycle_timeline_preview_detail_base = ""
            self._cycle_timeline_preview_stage_key = "queued"
            self._cycle_timeline_preview_timer_after_id = None
            self._cycle_timeline_preview_canvas = None
            self._cycle_timeline_preview_toolbar = None
            window.protocol(
                "WM_DELETE_WINDOW", self._close_cycle_timeline_plot_preview_window
            )
            window.bind(
                "<Destroy>",
                self._close_cycle_timeline_plot_preview_window,
                add="+",
            )
        else:
            try:
                window.deiconify()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        try:
            window.lift()
            window.focus_force()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

        self._cycle_timeline_preview_request_token += 1
        request_token = int(getattr(self, "_cycle_timeline_preview_request_token", 0))
        self._set_cycle_timeline_preview_loading_state(
            progress=10.0, message="Opening Preview...", reset=True, show=True
        )
        self._set_cycle_timeline_preview_loading_state(
            progress=45.0, message="Building Preview Figure..."
        )
        try:
            display_fig = getattr(self, "_sol_cycle_spec_fig", None)
            capture_multi = getattr(
                self, "_capture_cycle_timeline_legend_locs_from_fig", None
            )
            if callable(capture_multi):
                capture_multi(display_fig, source="sync")
            else:
                self._capture_cycle_timeline_legend_loc_from_fig(
                    display_fig,
                    source="sync",
                )
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        fig = self._build_cycle_timeline_export_figure(
            (11.0, 8.5),
            workflow_key=self._current_solubility_workflow(),
            preview_interactive_legend=True,
        )
        if fig is None:
            self._set_cycle_timeline_preview_loading_state(
                progress=100.0,
                message="Preview unavailable. Run a workflow first.",
            )
            self._hide_cycle_timeline_preview_loading()
            try:
                messagebox.showinfo(
                    "Cycle Timeline Plot Preview",
                    "Run a workflow to generate cycle timeline data before opening preview.",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        active_window = getattr(self, "_cycle_timeline_preview_window", None)
        if (
            request_token != getattr(self, "_cycle_timeline_preview_request_token", 0)
            or active_window is None
            or not bool(getattr(active_window, "winfo_exists", lambda: False)())
        ):
            try:
                plt.close(fig)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        content = getattr(self, "_cycle_timeline_preview_content", None)
        if content is None:
            try:
                plt.close(fig)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        self._teardown_cycle_timeline_preview_annotation_controller(
            clear_dirty_flag=False
        )
        self._teardown_cycle_timeline_preview_legend_tracking()
        old_toolbar = getattr(self, "_cycle_timeline_preview_toolbar", None)
        if old_toolbar is not None:
            try:
                old_toolbar.destroy()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        old_layout_controls = getattr(
            self,
            "_cycle_timeline_preview_layout_controls",
            None,
        )
        if old_layout_controls is not None:
            try:
                old_layout_controls.destroy()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        old_canvas = getattr(self, "_cycle_timeline_preview_canvas", None)
        if old_canvas is not None:
            try:
                old_widget = old_canvas.get_tk_widget()
            except Exception:
                old_widget = None
            if old_widget is not None:
                try:
                    old_widget.destroy()
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
        old_fig = getattr(self, "_cycle_timeline_preview_fig", None)
        if old_fig is not None and old_fig is not fig:
            try:
                plt.close(old_fig)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        self._set_cycle_timeline_preview_loading_state(
            progress=72.0, message="Adding Plot Elements..."
        )
        try:
            self._apply_gl260_legend_sizing(
                fig,
                plot_id=preview_plot_id,
                plot_key="fig_cycle_timeline_preview",
            )
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            preview_overlap_debug = bool(
                self._is_debug_category_enabled("plotting.render")
            )
        except Exception:
            preview_overlap_debug = False
        if preview_overlap_debug:
            self._dbg_cycle_timeline_overlap_checkpoint(
                fig,
                stage="preview_window_post_export_builder",
            )
        canvas = FigureCanvasTkAgg(fig, master=content)
        toolbar = NavigationToolbar2Tk(canvas, content)
        toolbar.update()
        toolbar.pack(side="top", fill="x")
        layout_controls = ttk.Frame(content, padding=(6, 2, 6, 4))
        layout_controls.pack(side="top", fill="x")
        ttk.Button(
            layout_controls,
            text="Open Layout Health Wizard",
            command=lambda: self._open_layout_health_wizard(
                plot_id=preview_plot_id,
                fig=fig,
                canvas=canvas,
                parent=window,
                source="cycle_timeline_preview",
            ),
        ).pack(side="left")
        widget = canvas.get_tk_widget()
        widget.pack(fill="both", expand=True)
        self._cycle_timeline_preview_canvas = canvas
        self._cycle_timeline_preview_toolbar = toolbar
        self._cycle_timeline_preview_layout_controls = layout_controls
        self._cycle_timeline_preview_fig = fig
        self._set_cycle_timeline_preview_loading_state(
            progress=92.0, message="Final Layout Adjustments..."
        )
        try:
            self._finalize_matplotlib_canvas_layout(
                canvas=canvas,
                fig=fig,
                tk_widget=widget,
                keep_export_size=True,
                trigger_resize_event=False,
                force_draw=True,
            )
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            self._reposition_cycle_timeline_centered_bottom_legends(fig)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting preview reveal.
            pass
        if preview_overlap_debug:
            self._dbg_cycle_timeline_overlap_checkpoint(
                fig,
                stage="preview_window_post_finalize",
            )
        try:
            self._install_cycle_timeline_preview_annotation_controller(
                fig,
                canvas,
                plot_id=preview_plot_id,
            )
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            self._register_cycle_timeline_preview_legend_tracking(
                fig,
                canvas=canvas,
            )
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        self._set_cycle_timeline_preview_loading_state(
            progress=100.0, message="Preview Ready."
        )
        self._hide_cycle_timeline_preview_loading()

    def _build_simulation_export_dataframe_contract(
        self,
        timeline_rows: Sequence[Mapping[str, Any]],
        *,
        workflow_key: Optional[str],
    ) -> Dict[str, Any]:
        """Build a normalized simulation-export dataframe contract (scaffold).

        Purpose:
            Define one stable table schema for future master-workbook export.
        Why:
            v4.12.0 introduces scaffold-only infrastructure for writing calculated
            simulation traces into workbook columns in a later release.
        Inputs:
            timeline_rows: Timeline/calculated rows from active workflow output.
            workflow_key: Optional workflow identifier for metadata tagging.
        Outputs:
            Dict containing contract metadata, columns, records, and DataFrame.
        Side Effects:
            None.
        Exceptions:
            Invalid rows are skipped during schema normalization.
        """
        columns = [
            "workflow_key",
            "cycle_index",
            "co2_cycle_g",
            "co2_cumulative_g",
            "equilibrium_ph",
            "final_ph",
            "ph_observed",
            "ph_corrected",
            "pco2_atm",
            "h2co3_pct",
            "hco3_pct",
            "co3_pct",
            "corrected_cycle_co2_g",
            "corrected_cumulative_co2_g",
        ]
        export_rows: List[Dict[str, Any]] = []
        for idx, row in enumerate(timeline_rows or [], start=1):
            if not isinstance(row, Mapping):
                continue
            fractions = row.get("fractions")
            if not isinstance(fractions, Mapping):
                fractions = {}
            cycle_index = _safe_rust_int(row.get("cycle_id"), idx)
            equilibrium_ph = _safe_float(
                row.get("equilibrium_ph", row.get("ph", row.get("solution_ph")))
            )
            export_rows.append(
                {
                    "workflow_key": str(workflow_key or "").strip() or self._current_solubility_workflow(),
                    "cycle_index": cycle_index,
                    "co2_cycle_g": _safe_float(
                        row.get("co2_mass_g", row.get("co2_added_mass_g"))
                    ),
                    "co2_cumulative_g": _safe_float(
                        row.get("co2_g", row.get("cumulative_co2_added_mass_g"))
                    ),
                    "equilibrium_ph": equilibrium_ph,
                    "final_ph": equilibrium_ph,
                    "ph_observed": equilibrium_ph,
                    "ph_corrected": _safe_float(row.get("corrected_ph")),
                    "pco2_atm": _safe_float(row.get("pco2_atm")),
                    "h2co3_pct": _safe_float(fractions.get("H2CO3")) * 100.0
                    if _safe_float(fractions.get("H2CO3")) is not None
                    else None,
                    "hco3_pct": _safe_float(fractions.get("HCO3-")) * 100.0
                    if _safe_float(fractions.get("HCO3-")) is not None
                    else None,
                    "co3_pct": _safe_float(fractions.get("CO3^2-")) * 100.0
                    if _safe_float(fractions.get("CO3^2-")) is not None
                    else None,
                    "corrected_cycle_co2_g": _safe_float(row.get("corrected_cycle_co2_g")),
                    "corrected_cumulative_co2_g": _safe_float(
                        row.get("corrected_cumulative_co2_g")
                    ),
                }
            )
        frame = pd.DataFrame(export_rows, columns=columns)
        return {
            "contract_version": SIMULATION_EXPORT_SCHEMA_CONTRACT_VERSION,
            "columns": list(columns),
            "records": export_rows,
            "dataframe": frame,
        }

    def _simulation_export_workbook_mapping_settings(self) -> Dict[str, Any]:
        """Return normalized workbook-export settings for simulation data appends.

        Purpose:
            Resolve workbook destination/sheet/mapping preferences for simulation export.
        Why:
            Manual and auto-export paths need one stable settings payload that
            remains compatible with legacy scaffold keys.
        Inputs:
            None.
        Outputs:
            Dict[str, Any]: Normalized workbook-export settings payload.
        Side Effects:
            Writes normalized payload back into settings for schema stability.
        Exceptions:
            None.
        """
        settings_ref = self._settings_dict()
        normalized = _normalize_simulation_export_workbook_mapping_payload(
            settings_ref.get(SIMULATION_EXPORT_WORKBOOK_COLUMN_MAPPING_SETTINGS_KEY)
        )
        settings_ref[SIMULATION_EXPORT_WORKBOOK_COLUMN_MAPPING_SETTINGS_KEY] = normalized
        return normalized

    def _build_simulation_export_dataframe_with_metadata(
        self,
        timeline_rows: Sequence[Mapping[str, Any]],
        *,
        workflow_key: str,
        run_id: str,
    ) -> Tuple[pd.DataFrame, Dict[str, Any]]:
        """Build one export dataframe enriched with required metadata columns.

        Purpose:
            Prepare timeline export rows for workbook append writes.
        Why:
            Workbook export rows must include timestamp/workflow/run-contract metadata
            in addition to normalized timeline contract fields.
        Inputs:
            timeline_rows: Timeline rows from cycle simulation output.
            workflow_key: Active workflow key for export metadata.
            run_id: Per-export run identifier.
        Outputs:
            Tuple[pd.DataFrame, Dict[str, Any]]: DataFrame ready for workbook
            append and the original contract payload.
        Side Effects:
            Updates `_last_simulation_export_contract`.
        Exceptions:
            None.
        """
        contract = self._build_simulation_export_dataframe_contract(
            timeline_rows,
            workflow_key=workflow_key,
        )
        frame = contract.get("dataframe")
        if not isinstance(frame, pd.DataFrame):
            frame = pd.DataFrame(columns=list(contract.get("columns") or []))
        export_frame = frame.copy()
        exported_at = datetime.utcnow().isoformat(timespec="seconds") + "Z"
        export_frame["exported_at_utc"] = exported_at
        export_frame["workflow_key"] = str(workflow_key or "").strip()
        export_frame["simulation_run_id"] = str(run_id or "").strip()
        export_frame["contract_version"] = str(
            contract.get("contract_version") or SIMULATION_EXPORT_SCHEMA_CONTRACT_VERSION
        )
        return export_frame, contract

    def _resolve_simulation_export_destination_workbook(
        self,
        mapping_settings: Mapping[str, Any],
        *,
        prompt_if_needed: bool,
    ) -> Optional[str]:
        """Resolve destination workbook path for simulation export workflows.

        Purpose:
            Pick the workbook destination from active workbook context/settings.
        Why:
            Manual and auto-export require consistent active-workbook-first fallback
            behavior with optional picker fallback when missing.
        Inputs:
            mapping_settings: Normalized workbook-export settings payload.
            prompt_if_needed: True to show file-picker fallback when unresolved.
        Outputs:
            Optional[str]: Resolved workbook path, or None when unavailable.
        Side Effects:
            May open a file picker and persist updated workbook path to settings.
        Exceptions:
            Dialog failures degrade to None.
        """
        path = ""
        active_path = str(getattr(self, "file_path", "") or "").strip()
        if active_path.lower().endswith((".xlsx", ".xlsm", ".xltx", ".xltm")) and os.path.exists(active_path):
            path = active_path
        if not path:
            candidate = str(mapping_settings.get("workbook_path") or "").strip()
            if candidate and os.path.exists(candidate):
                path = candidate
        if not path and prompt_if_needed:
            try:
                candidate = filedialog.askopenfilename(
                    title="Select Master Workbook for Simulation Export",
                    filetypes=[("Excel files", "*.xlsx *.xlsm *.xltx *.xltm")],
                )
            except Exception:
                candidate = ""
            if candidate and os.path.exists(candidate):
                path = candidate
        if path:
            settings_ref = self._settings_dict()
            mapping_copy = dict(mapping_settings)
            mapping_copy["workbook_path"] = path
            settings_ref[SIMULATION_EXPORT_WORKBOOK_COLUMN_MAPPING_SETTINGS_KEY] = (
                _normalize_simulation_export_workbook_mapping_payload(mapping_copy)
            )
            try:
                self._schedule_save_settings()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        return path or None

    def _export_simulation_timeline_to_master_workbook(
        self,
        *,
        workflow_key: Optional[str] = None,
        prompt_for_workbook: bool = True,
        show_success_dialog: bool = True,
        source: str = "manual",
    ) -> Optional[Dict[str, Any]]:
        """Export active workflow simulation timeline rows into master workbook.

        Purpose:
            Append active workflow simulation rows to its configured workbook sheet.
        Why:
            v4.12.1 requires production workbook export for timeline simulation
            outputs with header-mapping/column-extension behavior.
        Inputs:
            workflow_key: Optional workflow override; defaults to active workflow.
            prompt_for_workbook: True to use picker fallback when destination missing.
            show_success_dialog: True to display a completion dialog.
            source: Export trigger source token (`manual` or `auto`).
        Outputs:
            Optional[Dict[str, Any]]: Export result diagnostics or None when skipped/failed.
        Side Effects:
            Appends rows into workbook sheets and updates export tracking settings.
        Exceptions:
            Errors are surfaced via dialogs and return None.
        """
        target_workflow = str(workflow_key or self._current_solubility_workflow()).strip()
        if target_workflow not in SIMULATION_EXPORT_WORKFLOW_KEYS:
            target_workflow = self._current_solubility_workflow()
        result = self._get_cycle_result_for_workflow(target_workflow) or {}
        timeline = result.get("timeline") or []
        if not timeline:
            if show_success_dialog:
                try:
                    messagebox.showinfo(
                        "Advanced Solubility Module",
                        "Run the cycle simulation before exporting workbook data.",
                    )
                except Exception:
                    pass
            return None

        mapping_settings = self._simulation_export_workbook_mapping_settings()
        destination = self._resolve_simulation_export_destination_workbook(
            mapping_settings,
            prompt_if_needed=prompt_for_workbook,
        )
        if not destination:
            if show_success_dialog:
                messagebox.showwarning(
                    "Advanced Solubility Module",
                    "No destination workbook was selected.",
                )
            return None
        sheet_map = dict(mapping_settings.get("per_workflow_sheet_map") or {})
        sheet_name = _normalize_simulation_export_sheet_label(
            sheet_map.get(target_workflow),
            fallback=SIMULATION_EXPORT_DEFAULT_WORKFLOW_SHEET_MAP.get(
                target_workflow, "Simulation Data"
            ),
        )
        run_id = (
            f"{target_workflow.lower()}_"
            f"{datetime.utcnow().strftime('%Y%m%dT%H%M%S')}_{uuid.uuid4().hex[:8]}"
        )
        export_df, contract = self._build_simulation_export_dataframe_with_metadata(
            timeline,
            workflow_key=target_workflow,
            run_id=run_id,
        )
        self._last_simulation_export_contract = contract
        column_map = mapping_settings.get("column_map")
        try:
            write_result = _append_dataframe_to_workbook_sheet_with_header_mapping(
                destination,
                sheet_name,
                export_df,
                column_map=column_map if isinstance(column_map, Mapping) else None,
            )
        except Exception as exc:
            messagebox.showerror(
                "Advanced Solubility Module",
                f"Workbook export failed: {exc}",
            )
            return None
        write_result = dict(write_result or {})
        write_result.update(
            {
                "workflow_key": target_workflow,
                "destination_workbook": destination,
                "source": source,
            }
        )
        self._last_simulation_export_run_id = run_id
        self._last_simulation_export_report = write_result
        if show_success_dialog:
            try:
                messagebox.showinfo(
                    "Advanced Solubility Module",
                    (
                        f"Simulation rows exported to '{write_result.get('sheet_name')}'.\n"
                        f"Rows appended: {write_result.get('rows_appended', 0)}"
                    ),
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        return write_result

    def _maybe_auto_export_simulation_workbook(
        self,
        *,
        workflow_key: str,
        result_payload: Optional[Mapping[str, Any]],
    ) -> None:
        """Attempt auto-export after successful simulation completion.

        Purpose:
            Run optional workbook export only when simulation completed successfully.
        Why:
            Auto-export must trigger on successful completion paths and remain off
            by default.
        Inputs:
            workflow_key: Workflow key of the completed simulation.
            result_payload: Simulation payload used to confirm timeline availability.
        Outputs:
            None.
        Side Effects:
            May append rows into workbook and update status text.
        Exceptions:
            Errors are captured to avoid interrupting completion callbacks.
        """
        mapping = self._simulation_export_workbook_mapping_settings()
        if not bool(mapping.get("auto_export_enabled", False)):
            return
        if not isinstance(result_payload, Mapping) or not (result_payload.get("timeline") or []):
            return
        try:
            export_result = self._export_simulation_timeline_to_master_workbook(
                workflow_key=workflow_key,
                prompt_for_workbook=True,
                show_success_dialog=False,
                source="auto",
            )
        except Exception:
            export_result = None
        if export_result:
            status_var = getattr(self, "_sol_status_var", None)
            setter = getattr(status_var, "set", None)
            if callable(setter):
                setter(
                    f"Auto-exported simulation rows to '{export_result.get('sheet_name')}'."
                )

    def _combined_calculated_trace_extension_hook(
        self, *, workflow_key: Optional[str]
    ) -> List[Dict[str, Any]]:
        """Return future calculated-trace extension descriptors (scaffold only).

        Purpose:
            Reserve a stable extension hook for adding calculated traces to the
            combined triple-axis plot in a future release.
        Why:
            v4.12.0 intentionally ships schema/hook scaffolding without exposing
            full advanced plotting wizard UI behavior yet.
        Inputs:
            workflow_key: Optional active workflow context.
        Outputs:
            List of calculated-trace descriptors; currently empty.
        Side Effects:
            None.
        Exceptions:
            None.
        """
        enabled = bool(
            self.settings.get(COMBINED_CALCULATED_TRACE_EXTENSIONS_ENABLED_SETTINGS_KEY, False)
        )
        if not enabled:
            return []
        return []

    def _export_cycle_timeline_csv(self) -> None:
        """Export cycle timeline rows to CSV with equilibrium-primary pH fields.

        Purpose:
            Persist the active workflow timeline payload for external review and
            downstream workbook/report workflows.
        Why:
            Timeline exports must now treat equilibrium-guidance pH as canonical
            while preserving legacy final-pH aliases for compatibility.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Opens a save-file dialog and writes one CSV file.
        Exceptions:
            Export failures are surfaced in message boxes and do not raise.
        """
        result = self._get_cycle_result_for_workflow(
            self._current_solubility_workflow()
        )
        timeline = (result or {}).get("timeline") or []
        if not timeline:
            try:
                messagebox.showinfo(
                    "Advanced Solubility Module",
                    "Run the cycle simulation before exporting.",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        # Scaffold-only v4.12.0 contract build for future workbook-column export.
        self._last_simulation_export_contract = (
            self._build_simulation_export_dataframe_contract(
                timeline,
                workflow_key=self._current_solubility_workflow(),
            )
        )
        path = filedialog.asksaveasfilename(
            title="Export Cycle Timeline",
            defaultextension=".csv",
            filetypes=[("CSV file", "*.csv")],
            initialfile="cycle_solubility_timeline.csv",
        )
        if not path:
            return
        fieldnames = [
            "cycle_id",
            "temperature_c",
            "delta_pressure_psi",
            "peak_pressure_psi",
            "trough_pressure_psi",
            "co2_moles",
            "co2_mass_g",
            "co2_added_moles",
            "co2_added_mass_g",
            "co2_consumed_moles",
            "co2_consumed_mass_g",
            "co2_unconsumed_moles",
            "co2_unconsumed_mass_g",
            "co2_total_moles",
            "co2_g",
            "cumulative_co2_added_moles",
            "cumulative_co2_added_mass_g",
            "cumulative_co2_consumed_moles",
            "cumulative_co2_consumed_mass_g",
            "cumulative_co2_unconsumed_moles",
            "cumulative_co2_unconsumed_mass_g",
            "co2_to_target_g",
            "equilibrium_ph",
            "calculated_ph",
            "calibrated_estimated_ph",
            "actual_observed_ph",
            "final_ph",
            "final_pH",
            "solution_ph",
            "speciation_ph",
            "ionic_strength",
            "dissolved_mass_g",
            "effective_dissolved_mass_g",
            "solid_mass_g",
            "solid_na2co3_g",
            "solid_nahco3_g",
            "na2co3_total_mol",
            "nahco3_total_mol",
            "na2co3_dissolved_mol",
            "na2co3_solid_mol",
            "nahco3_dissolved_mol",
            "nahco3_solid_mol",
            "na2co3_dissolved_g",
            "nahco3_dissolved_g",
            "saturation_index",
            "headspace_pressure_psi",
            "pco2_atm",
            "headspace_co2_mol",
            "headspace_co2_g",
            "supersaturated",
            "regime",
            "planning_cycle_ph",
            "planning_co2_aligned_ph",
            "ph_delta_cycle",
            "ph_delta_co2",
            "actual_cycle_co2_mol",
            "planning_cycle_co2_mol",
            "co2_mol_delta",
            "co2_mol_delta_pct",
            "actual_hco3_pct",
            "actual_co3_pct",
            "planning_hco3_pct",
            "planning_co3_pct",
            "hco3_pct_delta",
            "co3_pct_delta",
            "alignment_quality_flag",
            "consistency_status",
            "consistency_flags",
            "error",
        ]
        try:
            with open(path, "w", newline="", encoding="utf-8") as handle:
                writer = csv.DictWriter(handle, fieldnames=fieldnames)
                writer.writeheader()
                # Iterate over timeline to apply the per-item logic.
                for row in timeline:
                    equilibrium_ph = _safe_float(
                        row.get("equilibrium_ph", row.get("ph", row.get("solution_ph")))
                    )
                    row_map = dict(row)
                    row_map["equilibrium_ph"] = equilibrium_ph
                    row_map["final_ph"] = equilibrium_ph
                    row_map["final_pH"] = equilibrium_ph
                    row_map["solution_ph"] = equilibrium_ph
                    row_map["speciation_ph"] = equilibrium_ph
                    writer.writerow({key: row_map.get(key, "") for key in fieldnames})
        except Exception as exc:
            try:
                messagebox.showerror(
                    "Advanced Solubility Module",
                    f"Failed to export timeline: {exc}",
                )
            except Exception:
                pass
            return
        try:
            messagebox.showinfo(
                "Advanced Solubility Module",
                f"Cycle timeline exported to {path}",
            )
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _resolve_generated_profile_export_figure(
        self,
        *,
        plot_key: Optional[str],
        plot_id: Optional[str],
        fig_size: Tuple[float, float],
    ) -> Tuple[Optional[Figure], bool, bool]:
        """Resolve one generated-tab export figure source and postprocess policy.

        Purpose:
            Centralize generated-tab export figure selection into one helper.
        Why:
            Timeline generated-tab exports need preview-source parity and must
            skip generic post-build re-application steps that can reintroduce
            spacing/whitespace drift after timeline-specific export preparation.
        Inputs:
            plot_key: Generated-tab plot key used for profile routing.
            plot_id: Plot identifier associated with the generated tab.
            fig_size: Target export figure size in inches for rebuild paths.
        Outputs:
            Tuple[Optional[Figure], bool, bool]: `(figure, close_after_save,
            skip_generic_postprocess)` where `skip_generic_postprocess` marks
            figure sources that already own/export-finalize their layout.
        Side Effects:
            May build a new export figure for generated tabs.
        Exceptions:
            Best-effort guards return `None` figure when build paths fail.
        """
        target_plot_key = str(plot_key or "").strip()
        target_plot_id = str(plot_id or "").strip()
        is_timeline_generated_tab = (
            target_plot_key == "fig_cycle_timeline_tab"
            or target_plot_id == "fig_cycle_timeline"
        )
        if is_timeline_generated_tab:
            workflow_key = self._current_solubility_workflow()
            resolve_export_fig = getattr(
                self, "_resolve_cycle_timeline_export_plot_figure", None
            )
            if callable(resolve_export_fig):
                fig, close_after_save = resolve_export_fig(
                    workflow_key=workflow_key
                )
            else:
                fig = self._build_cycle_timeline_export_figure(
                    fig_size, workflow_key=workflow_key
                )
                close_after_save = True
            return fig, bool(close_after_save), True
        fig = self._build_generated_plot_tab_figure(
            target_plot_key,
            mode="export",
            fig_size=fig_size,
        )
        return fig, True, False

    def _resolve_cycle_timeline_export_plot_figure(
        self,
        *,
        workflow_key: Optional[str],
    ) -> Tuple[Optional[Figure], bool]:
        """Resolve the figure source used by cycle timeline export.

        Purpose:
            Choose whether export should serialize the live preview figure or a
            freshly rebuilt export figure.
        Why:
            Preview-toolbar save writes the preview figure directly; matching that
            source when preview is open prevents spacing drift between the two save
            entry points.
        Inputs:
            workflow_key: Active workflow key used to validate preview parity.
        Outputs:
            Tuple[Optional[Figure], bool]: `(figure, close_after_save)` where
            `close_after_save` is True only for transient rebuilt figures.
        Side Effects:
            None.
        Exceptions:
            Best-effort guards fall back to rebuild behavior when preview state is
            unavailable, invalid, or workflow-mismatched.
        """
        active_workflow_key = str(workflow_key or "").strip()
        preview_fig = getattr(self, "_cycle_timeline_preview_fig", None)
        preview_window = getattr(self, "_cycle_timeline_preview_window", None)
        preview_window_open = False
        if preview_window is not None:
            try:
                preview_window_open = bool(
                    getattr(preview_window, "winfo_exists", lambda: False)()
                )
            except Exception:
                preview_window_open = False
        preview_workflow_key = str(
            getattr(preview_fig, "_gl260_cycle_timeline_workflow_key", "") or ""
        ).strip()
        preview_trace_signature = getattr(
            preview_fig,
            "_gl260_cycle_timeline_trace_signature",
            None,
        )
        current_trace_signature = None
        try:
            current_trace_signature = self._normalize_plot_refresh_signature_value(
                self._trace_settings_store_for_plot_id("fig_cycle_timeline")
            )
        except Exception:
            current_trace_signature = None
        if (
            preview_window_open
            and preview_fig is not None
            and preview_workflow_key == active_workflow_key
            and preview_trace_signature == current_trace_signature
        ):
            return preview_fig, False
        rebuilt_fig = self._build_cycle_timeline_export_figure(
            (11.0, 8.5), workflow_key=workflow_key
        )
        return rebuilt_fig, True

    def _export_cycle_timeline_plot(self) -> None:
        """Export the cycle-speciation timeline plot as PNG/PDF/SVG.

        Purpose:
            Save the rendered cycle timeline chart to a user-selected file path.
        Why:
            Operators use this artifact for review/reporting; exported labels must
            preserve repaired unicode symbols.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Captures display legend overrides, resolves preview/rebuild export
            source, opens a save dialog, shows determinate export progress,
            compacts export-only bottom whitespace, writes one file, and closes
            only transient rebuilt figures.
        Exceptions:
            Export errors are surfaced via message boxes and do not raise.
        """
        workflow_key = self._current_solubility_workflow()
        try:
            display_fig = getattr(self, "_sol_cycle_spec_fig", None)
            capture_multi = getattr(
                self, "_capture_cycle_timeline_legend_locs_from_fig", None
            )
            if callable(capture_multi):
                capture_multi(display_fig, source="sync")
            else:
                self._capture_cycle_timeline_legend_loc_from_fig(
                    display_fig,
                    source="sync",
                )
        except Exception:
            # Best-effort guard; legend capture failures should not block export.
            pass
        close_after_save = True
        resolve_export_fig = getattr(self, "_resolve_cycle_timeline_export_plot_figure", None)
        if callable(resolve_export_fig):
            fig, close_after_save = resolve_export_fig(workflow_key=workflow_key)
        else:
            fig = self._build_cycle_timeline_export_figure(
                (11.0, 8.5), workflow_key=workflow_key
            )
            close_after_save = True
        if fig is None:
            try:
                messagebox.showinfo(
                    "Cycle Speciation Timeline",
                    "Run the cycle simulation before exporting the plot.",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        path = filedialog.asksaveasfilename(
            title="Export Cycle Timeline Plot",
            defaultextension=".png",
            filetypes=[("PNG", "*.png"), ("PDF", "*.pdf"), ("SVG", "*.svg")],
            initialfile="cycle_speciation_timeline.png",
        )
        if not path:
            if close_after_save:
                try:
                    plt.close(fig)
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
            return
        export_splash_context = "cycle_timeline_plot_export"
        self._show_operation_splash(
            "Export Cycle Speciation Timeline",
            context=export_splash_context,
        )
        self._update_operation_splash(
            message="Preparing timeline plot export...",
            progress=12.0,
            stage_key="queued",
            detail="Resolving timeline figure layout before save.",
            reset=True,
        )
        try:
            fig_canvas = getattr(fig, "canvas", None)
            if fig_canvas is not None:
                try:
                    self._update_operation_splash(
                        message="Drawing timeline export figure...",
                        progress=35.0,
                        stage_key="render",
                        detail="Rendering final labels, legends, and plot geometry.",
                    )
                    fig_canvas.draw()
                except Exception:
                    # Best-effort guard; ignore draw failures before save.
                    pass
            prepare_export_figure = getattr(
                self, "_prepare_cycle_timeline_export_figure_for_save", None
            )
            if callable(prepare_export_figure):
                self._update_operation_splash(
                    message="Finalizing timeline export layout...",
                    progress=60.0,
                    stage_key="render",
                    detail="Compacting bottom margin while preserving legend clearance.",
                )
                prepared_fig = prepare_export_figure(
                    fig,
                    plot_key="fig_cycle_timeline",
                )
                if prepared_fig is not None:
                    fig = prepared_fig
            _sanitize_figure_text_artists(fig)
            export_dpi = self._get_export_dpi()
            self._update_operation_splash(
                message="Writing timeline plot export...",
                progress=82.0,
                stage_key="save",
                detail=f"Saving {os.path.basename(path)}.",
            )
            if path.lower().endswith(".pdf"):
                fig.savefig(path, format="pdf", dpi=export_dpi)
            elif path.lower().endswith(".svg"):
                fig.savefig(path, format="svg", dpi=export_dpi)
            else:
                fig.savefig(path, format="png", dpi=export_dpi)
            self._update_operation_splash(
                message="Timeline plot export complete.",
                progress=100.0,
                stage_key="ready",
                detail=f"Wrote {os.path.basename(path)}.",
            )
        except Exception as exc:
            self._update_operation_splash(
                message="Timeline plot export failed.",
                progress=100.0,
                stage_key="failed",
                detail=str(exc),
            )
            try:
                messagebox.showerror(
                    "Cycle Speciation Timeline",
                    f"Failed to export timeline plot: {exc}",
                )
            except Exception:
                pass
            return
        finally:
            self._hide_operation_splash(context=export_splash_context)
            if close_after_save:
                try:
                    plt.close(fig)
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
        try:
            messagebox.showinfo(
                "Cycle Speciation Timeline",
                f"Timeline plot exported to {path}",
            )
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _export_cycle_timeline_table(self) -> None:
        """Export the cycle timeline table in PDF/PNG/LaTeX formats.

        Purpose:
            Persist formatted cycle timeline table pages for downstream sharing.
        Why:
            Timeline table exports are a key reporting surface and must remain
            unicode-clean in headings/cell text.
        Inputs:
            None.
        Outputs:
            None.
        Side Effects:
            Opens save dialogs, generates one or more table figures, and writes
            artifacts to disk.
        Exceptions:
            Build/save failures are reported via message boxes.
        """
        settings_ref = self._settings_dict()
        headers, rows, column_ids = self._get_current_timeline_table_data()
        if not rows:
            try:
                messagebox.showinfo(
                    "Cycle Speciation Timeline",
                    "Run a workflow to generate the Cycle Speciation Timeline before exporting the table.",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        initial_dir = settings_ref.get("timeline_table_export_dir") or os.getcwd()
        path = filedialog.asksaveasfilename(
            title="Export Cycle Timeline Table",
            defaultextension="",
            filetypes=[
                ("PDF", "*.pdf"),
                ("PNG", "*.png"),
                ("LaTeX", "*.tex"),
                ("All files", "*.*"),
            ],
            initialfile=f"cycle_speciation_timeline_table_{timestamp}",
            initialdir=initial_dir,
        )
        if not path:
            return
        try:
            settings_ref["timeline_table_export_dir"] = str(Path(path).parent)
            self._schedule_save_settings()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

        target_path = Path(path)
        suffix = target_path.suffix.lower()
        if suffix not in {".pdf", ".png", ".tex"}:
            target_path = target_path.with_suffix(".pdf")
            suffix = ".pdf"
        if suffix == ".pdf":
            target_format = "pdf"
        elif suffix == ".png":
            target_format = "png"
        else:
            target_format = "tex"

        enabled_map = settings_ref.get("timeline_table_columns_enabled")
        if not isinstance(enabled_map, dict):
            enabled_map = {}
        selected_indices = [
            idx
            # Iterate to apply the per-item logic.
            for idx, col_id in enumerate(column_ids)
            if bool(enabled_map.get(col_id, True))
        ]
        if not selected_indices:
            try:
                messagebox.showwarning(
                    "Cycle Speciation Timeline",
                    "Export options disable all columns. Enable at least one column.",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        export_headers = [headers[idx] for idx in selected_indices]
        export_rows = [
            [row[idx] if idx < len(row) else "" for idx in selected_indices]
            # Iterate to apply the per-item logic.
            for row in rows
        ]
        export_column_ids = [column_ids[idx] for idx in selected_indices]
        orientation = settings_ref.get("timeline_table_export_orientation", "portrait")
        if orientation not in {"portrait", "landscape"}:
            orientation = "portrait"
        acs_quality = bool(settings_ref.get("timeline_table_export_acs_quality", False))

        numeric_specs: Dict[str, Union[int, str]] = {
            "COâ‚‚ per cycle (g)": 2,
            "COâ‚‚ total (g)": 2,
            "COâ‚‚ to target (g)": 2,
            "Predicted pH": 2,
            "pCOâ‚‚ (atm)": "sig3",
            "Hâ‚‚COâ‚ƒ %": 1,
            "HCOâ‚ƒ- %": 1,
            "COâ‚ƒÂ²- %": 1,
            "Solid Naâ‚‚COâ‚ƒ (g)": 2,
            "Solid NaHCOâ‚ƒ (g)": 2,
        }
        placeholder_map = {
            "CHEMCO2": r"CO$_2$",
            "CHEMHCO3": r"HCO$_3^{-}$",
            "CHEMCO3": r"CO$_3^{2-}$",
            "CHEMH2CO3": r"H$_2$CO$_3$",
            "CHEMNA2CO3": r"Na$_2$CO$_3$",
            "CHEMNAHCO3": r"NaHCO$_3$",
            "CHEMNA": r"Na$^{+}$",
            "CHEMPCO2": r"pCO$_2$",
        }
        placeholder_patterns = [
            (r"COâ‚‚|CO2", "CHEMCO2"),
            (r"HCOâ‚ƒ-?|HCO3-?", "CHEMHCO3"),
            (r"COâ‚ƒÂ²-|CO3--|CO3\\^?2-?", "CHEMCO3"),
            (r"Hâ‚‚COâ‚ƒ|H2CO3", "CHEMH2CO3"),
            (r"Naâ‚‚COâ‚ƒ|Na2CO3", "CHEMNA2CO3"),
            (r"NaHCOâ‚ƒ|NaHCO3", "CHEMNAHCO3"),
            (r"Na\\+|Naâº|Na\\^\\+|Na\\^\\{\\+\\}", "CHEMNA"),
            (r"pCOâ‚‚|pCO2", "CHEMPCO2"),
        ]

        # Closure captures _export_cycle_timeline_table local context to keep helper logic scoped and invoked directly within _export_cycle_timeline_table.
        def _escape_text(text: str) -> str:
            """Perform escape text.
            Used to keep the workflow logic localized and testable."""
            safe = text
            # Iterate to apply the per-item logic.
            for char, esc in {
                "\\": r"\\",
                "&": r"\&",
                "%": r"\%",
                "$": r"\$",
                "#": r"\#",
                "_": r"\_",
                "{": r"\{",
                "}": r"\}",
                "~": r"\textasciitilde{}",
                "^": r"\^{}",
            }.items():
                safe = safe.replace(char, esc)
            return safe

        # Closure captures _export_cycle_timeline_table local context to keep helper logic scoped and invoked directly within _export_cycle_timeline_table.
        def _placeholderize(value: Any) -> str:
            """Perform placeholderize.
            Used to keep the workflow logic localized and testable."""
            text = "" if value is None else str(value)
            # Iterate over placeholder_patterns to apply the per-item logic.
            for pattern, token in placeholder_patterns:
                try:
                    text = re.sub(pattern, token, text)
                except re.error:
                    continue
            return _escape_text(text)

        # Closure captures _export_cycle_timeline_table local context to keep helper logic scoped and invoked directly within _export_cycle_timeline_table.
        def _replace_placeholders(text: str) -> str:
            """Perform replace placeholders.
            Used to keep the workflow logic localized and testable."""
            result = text
            # Iterate over items from placeholder_map to apply the per-item logic.
            for token, latex in placeholder_map.items():
                result = result.replace(token, latex)
            return result

        # Closure captures _export_cycle_timeline_table local context to keep helper logic scoped and invoked directly within _export_cycle_timeline_table.
        def _build_latex_doc(latex_table: str, include_inputenc: bool) -> str:
            """Build latex doc.
            Used to assemble latex doc during UI or plot setup."""
            inputenc = ""
            if include_inputenc:
                inputenc = "\\usepackage[utf8]{inputenc}\n\\usepackage[T1]{fontenc}\n"
            return _replace_placeholders(
                textwrap.dedent(
                    f"""
                    \\documentclass[11pt]{{article}}
                    {inputenc}\\usepackage[margin=0.85in]{{geometry}}
                    \\usepackage{{booktabs}}
                    \\usepackage{{longtable}}
                    \\usepackage{{array}}
                    \\usepackage{{caption}}
                    \\usepackage{{mathptmx}}
                    \\begin{{document}}
                    {latex_table}
                    \\end{{document}}
                    """
                )
            )

        subtitle_parts = []
        workflow_key = self._current_solubility_workflow()
        if workflow_key:
            subtitle_parts.append(f"Workflow: {workflow_key}")
        try:
            spec_key, ph_key, use_same = self._resolve_workflow_model_keys(workflow_key)
            subtitle_parts.append(
                f"Speciation model: {self._workflow_model_label_for_key(spec_key)}"
            )
            ph_label = (
                "Same as speciation model"
                if use_same
                else self._workflow_model_label_for_key(ph_key)
            )
            subtitle_parts.append(f"Predicted pH model: {ph_label}")
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        subtitle_text = " | ".join(subtitle_parts)
        export_dpi = max(1, self._get_export_dpi())
        output_dir = target_path.parent

        # Legacy LaTeX/longtable exports degraded Unicode labels and produced unstable
        # wrapping for long Notes while requiring external toolchains.
        if target_format in {"pdf", "png"}:
            try:
                figures = _render_timeline_table_matplotlib_pages(
                    export_headers,
                    export_rows,
                    numeric_specs,
                    CYCLE_TIMELINE_EXPORT_DEFAULT_TITLE,
                    subtitle_text,
                    export_dpi,
                    orientation=orientation,
                    column_ids=export_column_ids,
                    font_family=settings_ref.get("font_family"),
                    acs_quality=acs_quality,
                )
            except Exception as exc:
                try:
                    messagebox.showerror(
                        "Cycle Speciation Timeline",
                        f"Matplotlib export failed (render): {exc}\n"
                        f"Output folder: {output_dir}",
                    )
                except Exception:
                    pass
                return
            if not figures:
                try:
                    messagebox.showerror(
                        "Cycle Speciation Timeline",
                        "Matplotlib export failed (render): no pages were generated.\n"
                        f"Output folder: {output_dir}",
                    )
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
                return
            saved_paths: List[Path] = []
            try:
                if target_format == "pdf":
                    with PdfPages(target_path) as pdf:
                        # Iterate over figures to apply the per-item logic.
                        for fig in figures:
                            _sanitize_figure_text_artists(fig)
                            pdf.savefig(fig)
                            plt.close(fig)
                    saved_paths.append(target_path)
                    messagebox.showinfo(
                        "Cycle Speciation Timeline",
                        f"Timeline table exported to {target_path}",
                    )
                else:
                    base_path = target_path
                    if len(figures) == 1:
                        fig = figures[0]
                        _sanitize_figure_text_artists(fig)
                        fig.savefig(base_path, dpi=export_dpi)
                        plt.close(fig)
                        saved_paths.append(base_path)
                    else:
                        stem = base_path.with_suffix("")
                        # Iterate over indexed elements from figures, start=1 to apply the per-item logic.
                        for idx, fig in enumerate(figures, start=1):
                            page_path = stem.parent / f"{stem.name}_p{idx:02d}.png"
                            _sanitize_figure_text_artists(fig)
                            fig.savefig(page_path, dpi=export_dpi)
                            plt.close(fig)
                            saved_paths.append(page_path)
                    if len(saved_paths) == 1:
                        messagebox.showinfo(
                            "Cycle Speciation Timeline",
                            f"Timeline table exported to {saved_paths[0]}",
                        )
                    else:
                        messagebox.showinfo(
                            "Cycle Speciation Timeline",
                            f"Timeline table exported to {saved_paths[0].parent}\n"
                            f"Saved {len(saved_paths)} pages with suffixes _p01, _p02, ...",
                        )
            except Exception as exc:
                # Iterate over figures to apply the per-item logic.
                for fig in figures:
                    try:
                        plt.close(fig)
                    except Exception:
                        pass
                partial = [str(path) for path in saved_paths]
                if target_path.exists() and str(target_path) not in partial:
                    partial.append(str(target_path))
                partial_text = ""
                if partial:
                    partial_text = "\nSaved partial artifacts:\n" + "\n".join(partial)
                try:
                    messagebox.showerror(
                        "Cycle Speciation Timeline",
                        f"Matplotlib export failed (save): {exc}\n"
                        f"Output folder: {output_dir}{partial_text}",
                    )
                except Exception:
                    pass
            return

        try:
            df = pd.DataFrame(export_rows, columns=export_headers)
            label_map = {col: _placeholderize(col) for col in export_headers}
            text_columns = [col for col in export_headers if col not in numeric_specs]
            # Iterate over text_columns to apply the per-item logic.
            for col in text_columns:
                df[col] = [_placeholderize(val) for val in df[col]]
            # Iterate over items from numeric_specs to apply the per-item logic.
            for col, decimals in numeric_specs.items():
                if col in df.columns:
                    df[col] = pd.to_numeric(df[col], errors="coerce")

            gt_module = _get_great_tables_module()
            if gt_module is None:
                raise ModuleNotFoundError(
                    _great_tables_missing_message("timeline table export")
                )
            timeline_table = gt_module.GT(df)
            timeline_table = timeline_table.cols_label(label_map)
            numeric_columns = [col for col in numeric_specs if col in df.columns]
            if numeric_columns:
                timeline_table = timeline_table.cols_align(
                    columns=numeric_columns, align="right"
                )
            if text_columns:
                timeline_table = timeline_table.cols_align(
                    columns=text_columns, align="left"
                )
            two_dec_cols = [
                col
                # Iterate to apply the per-item logic.
                for col, dec in numeric_specs.items()
                if dec == 2 and col in df.columns
            ]
            one_dec_cols = [
                col
                # Iterate to apply the per-item logic.
                for col, dec in numeric_specs.items()
                if dec == 1 and col in df.columns
            ]
            three_dec_cols = [
                col
                # Iterate to apply the per-item logic.
                for col, dec in numeric_specs.items()
                if dec == 3 and col in df.columns
            ]
            sig3_cols = [
                col
                # Iterate to apply the per-item logic.
                for col, dec in numeric_specs.items()
                if dec == "sig3" and col in df.columns
            ]
            if two_dec_cols:
                timeline_table = timeline_table.fmt_number(
                    columns=two_dec_cols, decimals=2
                )
            if one_dec_cols:
                timeline_table = timeline_table.fmt_number(
                    columns=one_dec_cols, decimals=1
                )
            if three_dec_cols:
                timeline_table = timeline_table.fmt_number(
                    columns=three_dec_cols, decimals=3
                )
            if sig3_cols:
                timeline_table = timeline_table.fmt(
                    fns=lambda value: (
                        ""
                        if value is None
                        or (isinstance(value, float) and math.isnan(value))
                        else f"{float(value):.3g}"
                    ),
                    columns=sig3_cols,
                )
            timeline_table = timeline_table.opt_row_striping()
            timeline_table = timeline_table.opt_align_table_header(align="center")
            timeline_table = timeline_table.opt_horizontal_padding(2)
            timeline_table = timeline_table.opt_vertical_padding(2)
            timeline_table = timeline_table.sub_missing(
                columns=export_headers, missing_text=""
            )
            if subtitle_text:
                timeline_table = timeline_table.tab_header(
                    title="Cycle Speciation Timeline",
                    subtitle=_placeholderize(subtitle_text),
                )
            else:
                timeline_table = timeline_table.tab_header(
                    title="Cycle Speciation Timeline"
                )
            latex_table = timeline_table.as_latex(use_longtable=True)
        except Exception as exc:
            try:
                messagebox.showerror(
                    "Cycle Speciation Timeline",
                    f"LaTeX source export failed (build): {exc}\n"
                    f"Output folder: {output_dir}",
                )
            except Exception:
                pass
            return

        latex_table = _replace_placeholders(latex_table)
        latex_doc = _build_latex_doc(latex_table, include_inputenc=True)

        if target_format == "tex":
            try:
                target_path.write_text(latex_doc, encoding="utf-8")
                messagebox.showinfo(
                    "Cycle Speciation Timeline",
                    f"LaTeX source saved to {target_path}",
                )
            except Exception as exc:
                try:
                    messagebox.showerror(
                        "Cycle Speciation Timeline",
                        f"LaTeX source export failed (write): {exc}\n"
                        f"Output folder: {output_dir}",
                    )
                except Exception:
                    pass
            return

    def _run_inverse_co2_design(self) -> None:
        """Run inverse CO2 design.
        Used to execute inverse CO2 design and coordinate results."""
        summary_var = getattr(self, "_sol_inverse_summary_var", None)
        if summary_var is None:
            return
        self._ensure_rust_backend_for_workflow(status_var=summary_var)
        try:
            form_data = getattr(self, "_sol_last_form_data", None)
            if form_data is None:
                form_data = self._collect_solubility_form_data()
                self._sol_last_form_data = form_data
        except Exception as exc:
            summary_var.set(f"Unable to gather inputs: {exc}")
            try:
                messagebox.showwarning(
                    "Advanced Solubility Module",
                    f"Unable to gather inputs: {exc}",
                )
            except Exception:
                pass
            return
        reaction_naoh_mass = form_data.get("reaction_naoh_mass")
        reaction_solution_volume = form_data.get("reaction_solution_volume")
        reaction_co2_g = form_data.get("reaction_co2_g")
        reaction_final_ph = form_data.get("reaction_final_ph")
        reaction_slurry_ph = form_data.get("reaction_slurry_ph")
        reaction_target_ph = form_data.get("reaction_target_ph")
        measurement_ph = (
            reaction_final_ph if reaction_final_ph is not None else (reaction_slurry_ph)
        )
        if reaction_naoh_mass is None or reaction_solution_volume is None:
            summary_var.set("Set the NaOH charge and process liquor volume first.")
            return
        if measurement_ph is None:
            summary_var.set("Enter a final product pH or slurry pH measurement.")
            return
        guidance = analyze_bicarbonate_reaction(
            naoh_mass_g=reaction_naoh_mass,
            co2_charged_g=reaction_co2_g,
            solution_volume_l=reaction_solution_volume,
            measured_ph=reaction_final_ph,
            slurry_ph=reaction_slurry_ph,
            target_ph=reaction_target_ph,
            temperature_c=form_data["params"].temperature_c,
            use_temp_adjusted_constants=form_data[
                "params"
            ].use_temperature_adjusted_constants,
            ionic_strength_cap=form_data["params"].ionic_strength_cap,
        )
        if not guidance:
            summary_var.set(
                "Unable to evaluate the dosing ledger with the provided inputs."
            )
            return
        ledger = guidance.get("ledger") or {}
        na2_mol = max(float(ledger.get("na2co3_mol", 0.0)), 0.0)
        nah_mol = max(float(ledger.get("nahco3_mol", 0.0)), 0.0)
        total_carbon = na2_mol + nah_mol
        current_purity = nah_mol / total_carbon if total_carbon > 0 else 0.0
        try:
            purity_pct = float(self._sol_inverse_purity_var.get() or 99.5)
        except Exception:
            purity_pct = 99.5
        target_purity = max(0.0, min(purity_pct / 100.0, 0.9999))
        if target_purity <= current_purity or na2_mol <= 0:
            summary_var.set(
                f"Current NaHCOâ‚ƒ purity â‰ˆ {current_purity*100:.2f}% (target {target_purity*100:.2f}%). "
                "No additional COâ‚‚ required."
            )
            return
        denominator = 2.0 - target_purity
        numerator = target_purity * total_carbon - nah_mol
        conversion_mol = max(0.0, numerator / denominator)
        conversion_mol = min(conversion_mol, na2_mol)
        supersat_factor = 1.0
        if bool(getattr(self, "_sol_inverse_supersat_var", tk.BooleanVar()).get()):
            try:
                supersat_factor = float(
                    getattr(
                        self,
                        "_sol_inverse_supersat_factor_var",
                        tk.StringVar(value="1.05"),
                    ).get()
                )
            except Exception:
                supersat_factor = 1.0
            supersat_factor = max(1.0, supersat_factor)
        recommended_mol = min(conversion_mol * supersat_factor, na2_mol)
        recommended_g = recommended_mol * SOL_MW_CO2
        projected_purity = (
            (nah_mol + 2.0 * recommended_mol)
            / (na2_mol - recommended_mol + nah_mol + 2.0 * recommended_mol)
            if (na2_mol + nah_mol) > 0
            else 0.0
        )
        summary_lines = [
            f"Current NaHCOâ‚ƒ purity â‰ˆ {current_purity*100:.2f}% with "
            f"{na2_mol:.4f} mol Naâ‚‚COâ‚ƒ and {nah_mol:.4f} mol NaHCOâ‚ƒ.",
            f"Target purity: {target_purity*100:.2f}% (supersaturation factor {supersat_factor:.2f}).",
            f"Recommended additional COâ‚‚: {recommended_mol:.4f} mol ({recommended_g:.2f} g).",
            f"Projected purity after dosing â‰ˆ {projected_purity*100:.2f}% "
            "assuming complete conversion of the indicated Naâ‚‚COâ‚ƒ.",
        ]
        if guidance.get("warnings"):
            summary_lines.append("Ledger warnings: " + "; ".join(guidance["warnings"]))
        summary_var.set("\n".join(summary_lines))

    def _refresh_solubility_scenario_choices(self) -> None:
        """Refresh solubility scenario choices.
        Used to sync solubility scenario choices with current settings."""
        combo = getattr(self, "_sol_preset_combo", None)
        if combo is None:
            return
        stored = settings.setdefault("solubility_scenarios", {})
        values = list(SOLUBILITY_PRESETS.keys()) + sorted(stored.keys())
        combo["values"] = values

    def _on_select_solubility_preset(self, _event=None) -> None:
        """Handle select solubility preset.
        Used as an event callback for select solubility preset."""
        name = self._sol_preset_combo.get()
        if not name:
            return
        desc_var = getattr(self, "_sol_preset_description_var", None)
        if desc_var is None:
            return
        if name in SOLUBILITY_PRESETS:
            desc_var.set(SOLUBILITY_PRESETS[name].get("description", "Preset loaded."))
        else:
            desc_var.set("User-defined scenario.")

    def _load_selected_solubility_preset(self) -> None:
        """Load selected solubility preset.
        Used when restoring selected solubility preset from storage."""
        name = self._sol_preset_combo.get()
        if not name:
            try:
                messagebox.showinfo(
                    "Advanced Solubility Module", "Select a preset before loading."
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        self._apply_solubility_preset_by_name(name)

    def _apply_solubility_preset_by_name(self, name: str) -> None:
        """Apply solubility preset by name.
        Used to apply solubility preset by name changes to live state."""
        values: Optional[Dict[str, Any]] = None
        if name in SOLUBILITY_PRESETS:
            values = SOLUBILITY_PRESETS[name].get("values")
        else:
            values = settings.setdefault("solubility_scenarios", {}).get(name)
        if not values:
            return
        # Iterate over items from self._solubility_vars to apply the per-item logic.
        for key, var in self._solubility_vars.items():
            if key not in values:
                continue
            value = values[key]
            var.set("" if value is None else str(value))
        if "use_temperature_adjusted_constants" in values:
            self._sol_use_temp_adjust_var.set(
                bool(values["use_temperature_adjusted_constants"])
            )
        if "limit_ionic_strength" in values:
            self._sol_limit_ionic_var.set(bool(values["limit_ionic_strength"]))
        if "include_headspace" in values:
            self._sol_include_headspace_var.set(bool(values["include_headspace"]))
        if "solvent_basis_mode" in values:
            self._solvent_mode_var.set(str(values["solvent_basis_mode"]))
        # Iterate to apply the per-item logic.
        for key, target in [
            ("sens_mass_enabled", self._sol_sens_mass_var),
            ("sens_solvent_enabled", self._sol_sens_solvent_var),
            ("sens_temp_enabled", self._sol_sens_temp_var),
        ]:
            if key in values:
                target.set(bool(values[key]))
        self._apply_solvent_basis_state()
        self._sync_solvent_entries()
        self._toggle_ionic_cap_state()
        self._toggle_headspace_fields()

    def _collect_solubility_snapshot(self) -> Dict[str, Any]:
        """Collect solubility snapshot.
        Used to gather solubility snapshot into a structured payload."""
        snapshot: Dict[str, Any] = {}
        # Iterate over items from self._solubility_vars to apply the per-item logic.
        for key, var in self._solubility_vars.items():
            raw = var.get().strip()
            if not raw:
                snapshot[key] = None
                continue
            try:
                snapshot[key] = float(raw)
            except ValueError:
                snapshot[key] = raw
        snapshot["use_temperature_adjusted_constants"] = bool(
            self._sol_use_temp_adjust_var.get()
        )
        snapshot["limit_ionic_strength"] = bool(self._sol_limit_ionic_var.get())
        snapshot["include_headspace"] = bool(self._sol_include_headspace_var.get())
        snapshot["sens_mass_enabled"] = bool(self._sol_sens_mass_var.get())
        snapshot["sens_solvent_enabled"] = bool(self._sol_sens_solvent_var.get())
        snapshot["sens_temp_enabled"] = bool(self._sol_sens_temp_var.get())
        snapshot["solvent_basis_mode"] = self._solvent_mode_var.get()
        return snapshot

    def _slider_target_keys(self) -> List[str]:
        """Perform slider target keys.
        Used to keep the workflow logic localized and testable."""
        workflow_key = self._current_solubility_workflow()
        if workflow_key == "Planning":
            return ["forced_ph_target"]
        if workflow_key == "Analysis":
            return ["reaction_target_ph", "forced_ph_target"]
        if workflow_key == "Reprocessing":
            return ["diag_target_ph"]
        return ["forced_ph_target", "reaction_target_ph", "diag_target_ph"]

    def _save_solubility_scenario(self) -> None:
        """Save solubility scenario.
        Used when persisting solubility scenario to storage."""
        name = self._sol_scenario_name_var.get().strip()
        if not name:
            try:
                messagebox.showwarning(
                    "Advanced Solubility Module",
                    "Provide a scenario name before saving.",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        snapshot = self._collect_solubility_snapshot()
        settings.setdefault("solubility_scenarios", {})[name] = snapshot
        try:
            _save_settings_to_disk()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        self._refresh_solubility_scenario_choices()
        self._sol_scenario_name_var.set("")
        try:
            messagebox.showinfo(
                "Advanced Solubility Module", f"Scenario '{name}' saved successfully."
            )
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _apply_solvent_basis_state(self, *_args) -> None:
        """Apply solvent basis state.
        Used to apply solvent basis state changes to live state."""
        mode = getattr(self, "_solvent_mode_var", None)
        if mode is None:
            return
        mode_value = mode.get()
        water_entry = self._solubility_field_meta.get("water_mass_g", {}).get("entry")
        volume_entry = self._solubility_field_meta.get("solution_volume_l", {}).get(
            "entry"
        )
        if water_entry:
            water_entry.configure(
                state="normal" if mode_value == "mass" else "disabled"
            )
        if volume_entry:
            volume_entry.configure(
                state="normal" if mode_value == "volume" else "disabled"
            )

    def _sync_solvent_entries(self, *_args) -> None:
        """Perform sync solvent entries.
        Used to keep the workflow logic localized and testable."""
        if self._solvent_sync_lock:
            return
        water_var = self._solubility_vars.get("water_mass_g")
        volume_var = self._solubility_vars.get("solution_volume_l")
        mode = getattr(self, "_solvent_mode_var", None)
        if not water_var or not volume_var or mode is None:
            return
        try:
            self._solvent_sync_lock = True
            if mode.get() == "mass":
                mass = float(water_var.get() or 0)
                if mass > 0:
                    volume = (mass / SOL_WATER_DENSITY_25C_G_PER_ML) / 1000.0
                    volume_var.set(f"{volume:.6f}")
            else:
                volume = float(volume_var.get() or 0)
                if volume > 0:
                    mass = volume * 1000.0 * SOL_WATER_DENSITY_25C_G_PER_ML
                    water_var.set(f"{mass:.3f}")
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        finally:
            self._solvent_sync_lock = False

    def _toggle_ionic_cap_state(self) -> None:
        """Toggle ionic cap state.
        Used to flip ionic cap state and refresh dependent views."""
        entry = getattr(self, "_sol_ionic_cap_entry", None)
        if entry is None:
            return
        state = "normal" if self._sol_limit_ionic_var.get() else "disabled"
        entry.configure(state=state)

    def _toggle_headspace_fields(self) -> None:
        """Toggle headspace fields.
        Used to flip headspace fields and refresh dependent views."""
        enable = bool(self._sol_include_headspace_var.get())
        # Iterate to apply the per-item logic.
        for entry in (
            getattr(self, "_sol_headspace_pco2_entry", None),
            getattr(self, "_sol_headspace_kh_entry", None),
        ):
            if entry is not None:
                entry.configure(state="normal" if enable else "disabled")

    def _on_solubility_forced_slider(self, value: str) -> None:
        """Handle solubility forced slider.
        Used as an event callback for solubility forced slider."""
        try:
            target_value = float(value)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            return
        try:
            self._forced_slider_lock = True
            # Update all mapped target fields so Analysis mode cannot persist a stale
            # forced target that diverges from the visible slider state.
            for key in self._slider_target_keys():
                var = self._solubility_vars.get(key)
                if var is None:
                    continue
                var.set(f"{target_value:.2f}")
        finally:
            self._forced_slider_lock = False
        display_var = getattr(self, "_sol_target_ph_display_var", None)
        if display_var is not None:
            display_var.set(f"Target pH slider: {target_value:.2f}")

    def _sync_target_slider_from_entry(self, *_args) -> None:
        """Perform sync target slider from entry.
        Used to keep the workflow logic localized and testable."""
        if self._forced_slider_lock:
            return
        slider = getattr(self, "_sol_forced_slider", None)
        if slider is None:
            return
        target_value: Optional[float] = None
        # Iterate over self._slider_target_keys() to apply the per-item logic.
        for key in self._slider_target_keys():
            var = self._solubility_vars.get(key)
            if var is None:
                continue
            try:
                candidate = float(var.get())
            except Exception:
                continue
            target_value = candidate
            break
        if target_value is None:
            return
        slider.set(max(6.5, min(9.5, target_value)))
        display_var = getattr(self, "_sol_target_ph_display_var", None)
        if display_var is not None:
            display_var.set(f"Target pH slider: {target_value:.2f}")

    def _sync_planning_mass(self, *_args) -> None:
        """Perform sync planning mass.
        Used to keep the workflow logic localized and testable."""
        if getattr(self, "_planning_mass_lock", False):
            return
        naoh_var = self._solubility_vars.get("mass_naoh_g")
        nahco3_var = self._solubility_vars.get("mass_na_hco3_g")
        if naoh_var is None or nahco3_var is None:
            return
        try:
            value = float(naoh_var.get())
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            return
        try:
            self._planning_mass_lock = True
            equivalent = value * SOL_MW_NAHCO3 / SOL_MW_NAOH
            nahco3_var.set(f"{equivalent:.4f}")
        finally:
            self._planning_mass_lock = False

    def _on_diag_target_slider(self, value: str) -> None:
        """Handle diag target slider.
        Used as an event callback for diag target slider."""
        var = self._solubility_vars.get("diag_target_ph")
        if var is None:
            return
        try:
            var.set(f"{float(value):.2f}")
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _sync_diag_target_slider_from_entry(self, *_args) -> None:
        """Perform sync diag target slider from entry.
        Used to keep the workflow logic localized and testable."""
        slider = getattr(self, "_diag_target_slider", None)
        var = self._solubility_vars.get("diag_target_ph")
        if slider is None or var is None:
            return
        try:
            value = float(var.get())
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            return
        slider.set(min(max(value, 6.5), 9.0))

    def _solubility_summary_widgets(self) -> List[tk.Text]:
        """Return available solubility summary text widgets.

        Purpose:
            Resolve the active summary text widgets across legacy/new layouts.
        Why:
            Summary copy/export/update flows must remain functional even when
            legacy tab widgets are absent.
        Args:
            None.
        Returns:
            List[tk.Text]: Existing summary text widgets, ordered by priority.
        Side Effects:
            None.
        Exceptions:
            Widget liveness checks are guarded and skip invalid references.
        """
        widgets: List[tk.Text] = []
        # Prefer the Advanced summary widget but keep legacy compatibility.
        for attr_name in ("_solubility_summary_new", "_solubility_summary"):
            widget = getattr(self, attr_name, None)
            if widget is None:
                continue
            try:
                if widget.winfo_exists():
                    widgets.append(widget)
            except Exception:
                # Best-effort guard; skip invalid widget handles.
                pass
        return widgets

    def _read_solubility_summary_text(self) -> str:
        """Return the current solubility summary text from any active widget.

        Purpose:
            Read text from whichever summary widget is currently available.
        Why:
            Copy/export actions should not fail just because one widget tree is
            missing after legacy tab de-integration.
        Args:
            None.
        Returns:
            str: Trimmed summary text, or an empty string when unavailable.
        Side Effects:
            None.
        Exceptions:
            Widget read failures are handled and treated as empty content.
        """
        # Iterate over available widgets and return the first non-empty summary.
        for widget in self._solubility_summary_widgets():
            try:
                text = widget.get("1.0", "end").strip()
            except Exception:
                text = ""
            if text:
                return text
        return ""

    def _copy_solubility_summary(self) -> None:
        """Copy the current solubility summary text to the clipboard.

        Purpose:
            Export summary text quickly for downstream notes/reporting.
        Why:
            The active summary source can be the Advanced widget (or legacy
            widget if present), and copy should work in either case.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Writes text to the system clipboard and shows a status dialog.
        Exceptions:
            Best-effort; clipboard/UI errors are ignored.
        """
        text = self._read_solubility_summary_text()
        if not text:
            return
        try:
            self.clipboard_clear()
            self.clipboard_append(text)
            messagebox.showinfo(
                "Advanced Solubility Module", "Summary copied to clipboard."
            )
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _export_solubility_csv(self) -> None:
        """Export solubility CSV.
        Used to serialize solubility CSV for external workflows."""
        structured = getattr(self, "_sol_last_structured", None)
        if not structured:
            try:
                messagebox.showwarning(
                    "Advanced Solubility Module",
                    "Run the solubility analysis before exporting data.",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        path = filedialog.asksaveasfilename(
            title="Export Solubility Species CSV",
            defaultextension=".csv",
            filetypes=[("CSV files", "*.csv")],
            initialfile="solubility_species.csv",
        )
        if not path:
            return
        # Export pipeline serializes the latest structured solver payload.
        rows = structured.get("species_rows", [])
        if not rows:
            try:
                messagebox.showinfo(
                    "Advanced Solubility Module", "No species data available to export."
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        try:
            with open(path, "w", newline="", encoding="utf-8") as handle:
                writer = csv.DictWriter(handle, fieldnames=self._sol_species_columns)
                writer.writeheader()
                # Iterate over rows to apply the per-item logic.
                for row in rows:
                    writer.writerow(row)
                timeline = structured.get("cycle_timeline") or []
                if timeline:
                    handle.write("\nCycle timeline\n")
                    timeline_fields = [
                        "cycle_id",
                        "co2_total_g",
                        "solution_ph",
                        "h2co3_pct",
                        "hco3_pct",
                        "co3_pct",
                        "warnings",
                    ]
                    timeline_writer = csv.DictWriter(handle, fieldnames=timeline_fields)
                    timeline_writer.writeheader()
                    # Iterate over timeline to apply the per-item logic.
                    for entry in timeline:
                        fractions = entry.get("fractions") or {}
                        warnings = entry.get("warnings") or []
                        ph_val = entry.get("solution_ph")
                        timeline_writer.writerow(
                            {
                                "cycle_id": entry.get("cycle_id", ""),
                                "co2_total_g": f"{entry.get('co2_g', 0.0):.2f}",
                                "solution_ph": (
                                    f"{ph_val:.2f}" if ph_val is not None else ""
                                ),
                                "h2co3_pct": f"{fractions.get('H2CO3', 0.0) * 100:.1f}",
                                "hco3_pct": f"{fractions.get('HCO3-', 0.0) * 100:.1f}",
                                "co3_pct": f"{fractions.get('CO3^2-', 0.0) * 100:.1f}",
                                "warnings": " | ".join(warnings),
                            }
                        )
        except Exception as exc:
            try:
                messagebox.showerror(
                    "Advanced Solubility Module",
                    f"Failed to export CSV: {exc}",
                )
            except Exception:
                pass

    def _export_solubility_json(self) -> None:
        """Export solubility JSON.
        Used to serialize solubility JSON for external workflows."""
        structured = getattr(self, "_sol_last_structured", None)
        if not structured:
            try:
                messagebox.showwarning(
                    "Advanced Solubility Module",
                    "Run the solubility analysis before exporting data.",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        path = filedialog.asksaveasfilename(
            title="Export Solubility Summary JSON",
            defaultextension=".json",
            filetypes=[("JSON files", "*.json")],
            initialfile="solubility_summary.json",
        )
        if not path:
            return
        try:
            with open(path, "w", encoding="utf-8") as handle:
                json.dump(structured, handle, indent=2, ensure_ascii=False)
        except Exception as exc:
            try:
                messagebox.showerror(
                    "Advanced Solubility Module",
                    f"Failed to export JSON: {exc}",
                )
            except Exception:
                pass

