    def _compare_selected_pair_key(self) -> str:
        """Return the current order-sensitive Compare profile pair key.

        Purpose:
            Resolve the active A/B pair identifier for Compare pair-scoped state.
        Why:
            Plot-element and title overrides in Compare are now persisted per pair.
        Args:
            None.
        Returns:
            Stable pair key string for current A/B selections.
        Side Effects:
            None.
        Exceptions:
            Missing selector vars normalize to empty names.
        """
        profile_a_name = (
            str(self.compare_profile_a_var.get() or "")
            if hasattr(self, "compare_profile_a_var")
            else ""
        )
        profile_b_name = (
            str(self.compare_profile_b_var.get() or "")
            if hasattr(self, "compare_profile_b_var")
            else ""
        )
        return _compare_pair_key(profile_a_name, profile_b_name)

    def _compare_resolve_side_plot_settings_override(
        self, side_key: str
    ) -> Dict[str, Any]:
        """Resolve compare-only plot-settings overrides for one side.

        Purpose:
            Load pair+side Compare overrides captured via quick Plot Settings.
        Why:
            Compare quick settings must persist per selected pair and side without
            mutating profile/global plot defaults.
        Args:
            side_key: Compare side token (`"A"` or `"B"`).
        Returns:
            Normalized side override payload.
        Side Effects:
            None.
        Exceptions:
            Invalid side keys or malformed settings return an empty payload.
        """
        side_token = str(side_key or "").strip().upper()
        if side_token not in {"A", "B"}:
            return {}
        pair_key = self._compare_selected_pair_key()
        by_pair = _normalize_compare_side_plot_settings_overrides_by_pair(
            getattr(self, "_compare_side_plot_settings_overrides_by_pair", {})
        )
        payload = (
            (by_pair.get(pair_key) or {}).get(side_token)
            if isinstance(by_pair.get(pair_key), Mapping)
            else {}
        )
        return _normalize_compare_side_plot_settings_override(payload)

    def _compare_store_side_plot_settings_override(
        self,
        side_key: str,
        payload: Mapping[str, Any],
        *,
        persist_state: bool,
    ) -> None:
        """Store compare-only plot-settings overrides for one side.

        Purpose:
            Persist side-scoped quick Plot Settings values under the active pair.
        Why:
            Compare side tuning should survive reloads while remaining isolated
            from workspace/global settings.
        Args:
            side_key: Compare side token (`"A"` or `"B"`).
            payload: Candidate side override payload.
            persist_state: When True, persist Compare state to settings.
        Returns:
            None.
        Side Effects:
            Updates `_compare_side_plot_settings_overrides_by_pair`.
        Exceptions:
            Invalid side keys are ignored.
        """
        side_token = str(side_key or "").strip().upper()
        if side_token not in {"A", "B"}:
            return
        pair_key = self._compare_selected_pair_key()
        by_pair = _normalize_compare_side_plot_settings_overrides_by_pair(
            getattr(self, "_compare_side_plot_settings_overrides_by_pair", {})
        )
        side_payload = _normalize_compare_side_plot_settings_override(payload)
        pair_payload = dict((by_pair.get(pair_key) or {}))
        if side_payload:
            pair_payload[side_token] = side_payload
        else:
            pair_payload.pop(side_token, None)
        if pair_payload:
            by_pair[pair_key] = pair_payload
        else:
            by_pair.pop(pair_key, None)
        self._compare_side_plot_settings_overrides_by_pair = by_pair
        if persist_state:
            self._compare_persist_state()

    def _compare_resolve_side_layout_override(self, side_key: str) -> Dict[str, Any]:
        """Resolve compare-only layout-profile overrides for one side.

        Purpose:
            Load pair+side layout overrides captured from quick Plot Settings.
        Why:
            Compare-side dialog edits should remain pair-local and deterministic.
        Args:
            side_key: Compare side token (`"A"` or `"B"`).
        Returns:
            Normalized layout profile payload.
        Side Effects:
            None.
        Exceptions:
            Invalid side keys or malformed data return default profile payload.
        """
        side_token = str(side_key or "").strip().upper()
        if side_token not in {"A", "B"}:
            return {}
        pair_key = self._compare_selected_pair_key()
        by_pair = _normalize_compare_side_layout_overrides_by_pair(
            getattr(self, "_compare_side_layout_overrides_by_pair", {})
        )
        pair_payload = by_pair.get(pair_key)
        pair_payload = pair_payload if isinstance(pair_payload, Mapping) else {}
        side_payload = pair_payload.get(side_token)
        if not isinstance(side_payload, Mapping):
            return {}
        return _normalize_layout_profile(side_payload, "fig_combined_triple_axis")

    def _compare_store_side_layout_override(
        self,
        side_key: str,
        layout_profile: Mapping[str, Any],
        *,
        persist_state: bool,
    ) -> None:
        """Store compare-only layout-profile overrides for one side.

        Purpose:
            Persist side layout adjustments from quick Plot Settings under pair scope.
        Why:
            Compare render parity requires side-local layout state independent of
            profile/global layout defaults.
        Args:
            side_key: Compare side token (`"A"` or `"B"`).
            layout_profile: Candidate layout profile payload.
            persist_state: When True, persist Compare state to settings.
        Returns:
            None.
        Side Effects:
            Updates `_compare_side_layout_overrides_by_pair`.
        Exceptions:
            Invalid side keys are ignored.
        """
        side_token = str(side_key or "").strip().upper()
        if side_token not in {"A", "B"}:
            return
        pair_key = self._compare_selected_pair_key()
        by_pair = _normalize_compare_side_layout_overrides_by_pair(
            getattr(self, "_compare_side_layout_overrides_by_pair", {})
        )
        pair_payload = dict((by_pair.get(pair_key) or {}))
        pair_payload[side_token] = _normalize_layout_profile(
            dict(layout_profile or {}),
            "fig_combined_triple_axis",
        )
        by_pair[pair_key] = pair_payload
        self._compare_side_layout_overrides_by_pair = by_pair
        if persist_state:
            self._compare_persist_state()

    def _compare_side_plot_editor_margins_is_explicit(self, side_key: str) -> bool:
        """Return whether side plot-editor margins were explicitly stored.

        Purpose:
            Differentiate saved side margins from implicit defaults.
        Why:
            Compare render should only force plot-editor margins when the user
            explicitly captured side margins for that pair+side.
        Args:
            side_key: Compare side token (`"A"` or `"B"`).
        Returns:
            True when explicit margins exist for this pair+side.
        Side Effects:
            None.
        Exceptions:
            Invalid side keys return False.
        """
        side_token = str(side_key or "").strip().upper()
        if side_token not in {"A", "B"}:
            return False
        pair_key = self._compare_selected_pair_key()
        by_pair = _normalize_compare_plot_editor_margins_by_pair(
            getattr(self, "_compare_plot_editor_margins_by_pair", {})
        )
        pair_payload = by_pair.get(pair_key)
        if not isinstance(pair_payload, Mapping):
            return False
        return side_token in pair_payload

    def _compare_capture_combined_runtime_snapshot(self) -> Dict[str, Any]:
        """Capture global combined-plot runtime state for temporary compare staging.

        Purpose:
            Snapshot mutable combined settings/Tk vars before compare-side dialogs
            stage side-local values.
        Why:
            Quick Plot Settings in Compare must not leak staged values into the
            main Plot tab workspace.
        Args:
            None.
        Returns:
            Snapshot payload containing settings, layout profiles, and Tk values.
        Side Effects:
            None.
        Exceptions:
            Missing variables are handled gracefully.
        """
        sentinel = object()
        settings_snapshot = copy.deepcopy(dict(settings))
        tk_snapshot: Dict[str, Any] = {}
        attrs_snapshot: Dict[str, Any] = {}
        # Snapshot all Tk variables so compare popup staging cannot leak into the
        # main workspace even when full Plot Settings controls are edited.
        for attr_name, var_obj in dict(getattr(self, "__dict__", {})).items():
            if not isinstance(var_obj, tk.Variable):
                continue
            try:
                tk_snapshot[attr_name] = copy.deepcopy(var_obj.get())
            except Exception:
                tk_snapshot[attr_name] = sentinel
        for attr_name in (
            "_combined_legend_anchor",
            "_combined_legend_loc",
            "_combined_cycle_legend_anchor",
            "_combined_cycle_legend_loc",
            "_combined_cycle_legend_anchor_space",
        ):
            attrs_snapshot[attr_name] = copy.deepcopy(getattr(self, attr_name, sentinel))
        return {
            "sentinel": sentinel,
            "settings": settings_snapshot,
            "tk": tk_snapshot,
            "attrs": attrs_snapshot,
        }

    def _compare_restore_combined_runtime_snapshot(
        self, snapshot: Mapping[str, Any]
    ) -> None:
        """Restore global combined-plot runtime state after compare staging.

        Purpose:
            Revert temporary compare-side runtime staging changes.
        Why:
            Compare-side quick settings must not mutate main-tab/global defaults.
        Args:
            snapshot: Snapshot payload from `_compare_capture_combined_runtime_snapshot`.
        Returns:
            None.
        Side Effects:
            Restores settings and Tk variable values.
        Exceptions:
            Missing keys/widgets are ignored safely.
        """
        if not isinstance(snapshot, Mapping):
            return
        sentinel = snapshot.get("sentinel")
        settings_payload = snapshot.get("settings")
        settings_payload = settings_payload if isinstance(settings_payload, Mapping) else {}
        settings.clear()
        settings.update(copy.deepcopy(dict(settings_payload)))
        tk_payload = snapshot.get("tk")
        tk_payload = tk_payload if isinstance(tk_payload, Mapping) else {}
        for attr_name, value in tk_payload.items():
            var_obj = getattr(self, attr_name, None)
            if not isinstance(var_obj, tk.Variable):
                continue
            if value is sentinel:
                continue
            try:
                var_obj.set(copy.deepcopy(value))
            except Exception:
                continue
        attrs_payload = snapshot.get("attrs")
        attrs_payload = attrs_payload if isinstance(attrs_payload, Mapping) else {}
        for attr_name, value in attrs_payload.items():
            if value is sentinel:
                continue
            try:
                setattr(self, str(attr_name), copy.deepcopy(value))
            except Exception:
                continue

    def _compare_apply_effective_side_settings_to_runtime(
        self,
        side_key: str,
        bundle: Mapping[str, Any],
    ) -> None:
        """Stage effective compare-side settings into runtime globals/Tk vars.

        Purpose:
            Prefill the full Plot Settings dialog with side-local effective values.
        Why:
            Compare users need quick Plot Settings edits based on loaded side state,
            not unrelated current workspace settings.
        Args:
            side_key: Compare side token (`"A"` or `"B"`).
            bundle: Loaded compare bundle for this side.
        Returns:
            None.
        Side Effects:
            Temporarily mutates `settings` and combined Tk vars.
        Exceptions:
            Malformed inputs degrade safely using defaults.
        """
        side_token = str(side_key or "").strip().upper()
        profile_exact_mode = bool(self._compare_profile_exact_mode_active())
        compare_state = _normalize_compare_tab_settings(settings.get("compare_tab"))
        use_profile_layout = (
            True
            if profile_exact_mode
            else bool(
                self.compare_use_profile_layout_var.get()
                if hasattr(self, "compare_use_profile_layout_var")
                else compare_state.get("use_profile_layout", False)
            )
        )
        compare_preset_values: Dict[str, Any] = {}
        compare_layout_overrides: Dict[str, Any] = {}
        if not profile_exact_mode:
            custom_presets = _normalize_compare_custom_plot_presets(
                getattr(
                    self,
                    "_compare_custom_plot_presets",
                    compare_state.get("custom_plot_presets"),
                )
            )
            selected_preset_name = str(
                self.compare_plot_preset_var.get()
                if hasattr(self, "compare_plot_preset_var")
                else compare_state.get("plot_preset_name")
                or DEFAULT_COMPARE_PLOT_PRESET_NAME
            ).strip()
            compare_preset_values = _resolve_compare_plot_preset_values(
                selected_preset_name,
                custom_presets=custom_presets,
            )
            compare_layout_overrides = _normalize_compare_layout_overrides(
                getattr(
                    self,
                    "_compare_layout_overrides",
                    compare_state.get("layout_overrides"),
                )
            )
        side_plot_override = self._compare_resolve_side_plot_settings_override(side_token)
        combined_payload: Dict[str, Any] = {}
        combined_payload.update(dict(bundle.get("plot_settings") or {}))
        if not profile_exact_mode:
            combined_payload.update(compare_preset_values)
            combined_payload.update(compare_layout_overrides)
        combined_payload.update(side_plot_override)
        self._apply_profile_plot_settings(dict(combined_payload))
        auto_title_var_bindings = (
            ("auto_title_enabled", "auto_title_enabled_var"),
            ("auto_title_source", "auto_title_source_var"),
            ("auto_title_day_mode", "auto_title_day_mode_var"),
            ("auto_title_template", "auto_title_template_var"),
            ("title_selected_type", "title_data_type_var"),
        )
        # Stage auto-title controls so the popup mirrors full per-profile settings.
        for setting_key, attr_name in auto_title_var_bindings:
            if setting_key not in combined_payload:
                continue
            var_obj = getattr(self, attr_name, None)
            if var_obj is None:
                continue
            try:
                var_obj.set(copy.deepcopy(combined_payload.get(setting_key)))
            except Exception:
                continue

        profile_layouts = bundle.get("layout_profiles") or {}
        profile_layout_source: Any = {}
        if use_profile_layout and isinstance(profile_layouts, Mapping):
            profile_layout_source = profile_layouts.get("fig_combined_triple_axis", {})
        resolved_layout_profile = _normalize_layout_profile(
            profile_layout_source,
            "fig_combined_triple_axis",
        )
        side_layout_override = self._compare_resolve_side_layout_override(side_token)
        if isinstance(side_layout_override, Mapping) and side_layout_override:
            side_layout_profile = _normalize_layout_profile(
                side_layout_override, "fig_combined_triple_axis"
            )
            for mode_key in ("display", "export"):
                section = _layout_profile_section(resolved_layout_profile, mode_key)
                side_section = _layout_profile_section(side_layout_profile, mode_key)
                for layout_key in (
                    "title_xy",
                    "suptitle_xy",
                    "legend_anchor",
                    "legend_anchor_y",
                    "legend_loc",
                    "cycle_legend_anchor",
                    "cycle_legend_loc",
                    "xlabel_pad_pts",
                    "detached_spine_offset",
                    "detached_labelpad",
                ):
                    section[layout_key] = copy.deepcopy(side_section.get(layout_key))
                section["axis_labelpads"] = copy.deepcopy(
                    side_section.get("axis_labelpads") or {}
                )
            resolved_layout_profile["mirror_detached_labelpad"] = bool(
                side_layout_profile.get("mirror_detached_labelpad", False)
            )
        display_section = _layout_profile_section(resolved_layout_profile, "display")
        if not profile_exact_mode:
            for layout_key in COMPARE_LAYOUT_PROFILE_SECTION_KEYS:
                if layout_key not in compare_layout_overrides:
                    continue
                display_section[layout_key] = copy.deepcopy(
                    compare_layout_overrides.get(layout_key)
                )
        if not use_profile_layout:
            for mode_key in ("display", "export"):
                section = _layout_profile_section(resolved_layout_profile, mode_key)
                for key in COMPARE_LAYOUT_RESET_KEYS_WHEN_PROFILE_LAYOUT_DISABLED:
                    section[key] = None
                section["axis_labelpads"] = {}

        if self._compare_side_plot_editor_margins_is_explicit(side_token):
            default_display_margins = _default_layout_margins(
                "fig_combined_triple_axis",
                "display",
            )
            side_margin_override = _normalize_compare_plot_editor_margins(
                self._compare_resolve_side_plot_editor_margins(side_token),
                defaults=default_display_margins,
            )
            display_section["margins"] = _normalize_layout_margins(
                side_margin_override or default_display_margins,
                default_display_margins,
            )
        merged_layouts = _normalize_layout_profiles(settings.get("layout_profiles"))
        merged_layouts["fig_combined_triple_axis"] = resolved_layout_profile
        settings["layout_profiles"] = merged_layouts

    def _compare_collect_side_plot_settings_payload(self) -> Dict[str, Any]:
        """Collect one full compare-side Plot Settings payload from runtime state.

        Purpose:
            Capture full Plot Settings values after compare-side popup apply.
        Why:
            Side popup applies must persist all user-visible plot settings in
            compare state so reopen/rerender parity matches what the user edited.
        Args:
            None.
        Returns:
            Dict containing compare-side plot-settings override values.
        Side Effects:
            None.
        Exceptions:
            Missing helper methods degrade safely to direct settings capture.
        """
        payload: Dict[str, Any] = {}
        collect_fn = getattr(self, "_collect_profile_plot_settings", None)
        if callable(collect_fn):
            try:
                collected = collect_fn()
            except Exception:
                collected = {}
            if isinstance(collected, Mapping):
                payload.update(copy.deepcopy(dict(collected)))
        for key in COMPARE_SIDE_PLOT_SETTINGS_CAPTURE_KEYS:
            if key not in settings:
                continue
            payload[key] = copy.deepcopy(settings.get(key))
        return payload

    def _compare_capture_side_plot_settings_from_runtime(self, side_key: str) -> None:
        """Capture compare-side quick Plot Settings values from runtime state.

        Purpose:
            Extract and persist compare-only side overrides after dialog apply.
        Why:
            The full Plot Settings dialog commits into runtime globals; Compare
            needs to redirect those edits into pair+side compare state.
        Args:
            side_key: Compare side token (`"A"` or `"B"`).
        Returns:
            None.
        Side Effects:
            Updates compare-side settings/layout override maps.
        Exceptions:
            Missing layout profile/settings values are handled safely.
        """
        side_payload = self._compare_collect_side_plot_settings_payload()
        self._compare_store_side_plot_settings_override(
            side_key,
            side_payload,
            persist_state=False,
        )
        layout_profile = _normalize_layout_profile(
            _get_layout_profile("fig_combined_triple_axis"),
            "fig_combined_triple_axis",
        )
        self._compare_store_side_layout_override(
            side_key,
            layout_profile,
            persist_state=False,
        )
        display_section = _layout_profile_section(layout_profile, "display")
        display_margins = display_section.get("margins")
        if isinstance(display_margins, Mapping):
            self._compare_store_side_plot_editor_margins(
                side_key,
                display_margins,
                persist_state=False,
            )

    def _compare_build_effective_bundle_with_side_overrides(
        self,
        side_key: str,
        bundle: Mapping[str, Any],
    ) -> Dict[str, Any]:
        """Build one compare-side bundle with persisted pair+side overrides applied.

        Purpose:
            Merge compare-scoped side overrides into a loaded profile bundle.
        Why:
            Compare rendering is profile-bundle driven; side popup edits must be
            materialized in the bundle payload so profile-exact render paths still
            reflect compare-scoped overrides.
        Args:
            side_key: Compare side token (`"A"` or `"B"`).
            bundle: Loaded compare bundle for this side.
        Returns:
            Dict containing the effective side bundle payload.
        Side Effects:
            None.
        Exceptions:
            Invalid side keys or malformed bundles return a shallow copy.
        """
        side_token = str(side_key or "").strip().upper()
        bundle_copy = dict(bundle or {})
        if side_token not in {"A", "B"}:
            return bundle_copy

        state_payload = bundle_copy.get("state")
        state_payload = state_payload if isinstance(state_payload, Mapping) else {}
        base_plot_settings_source = state_payload.get("plot_settings")
        if not isinstance(base_plot_settings_source, Mapping):
            base_plot_settings_source = bundle_copy.get("plot_settings")
        base_plot_settings = (
            copy.deepcopy(dict(base_plot_settings_source))
            if isinstance(base_plot_settings_source, Mapping)
            else {}
        )
        side_plot_override = self._compare_resolve_side_plot_settings_override(side_token)
        effective_plot_settings = copy.deepcopy(base_plot_settings)
        effective_plot_settings.update(copy.deepcopy(side_plot_override))

        base_layout_profiles_source = state_payload.get("layout_profiles")
        if not isinstance(base_layout_profiles_source, Mapping):
            base_layout_profiles_source = bundle_copy.get("layout_profiles")
        effective_layout_profiles = _normalize_layout_profiles(base_layout_profiles_source)
        side_layout_override = self._compare_resolve_side_layout_override(side_token)
        if isinstance(side_layout_override, Mapping) and side_layout_override:
            effective_layout_profiles["fig_combined_triple_axis"] = _normalize_layout_profile(
                side_layout_override,
                "fig_combined_triple_axis",
            )

        args_keys = (
            "min_time",
            "max_time",
            "min_y",
            "max_y",
            "twin_y_min",
            "twin_y_max",
            "deriv_y_min",
            "deriv_y_max",
            "auto_time_ticks",
            "auto_y_ticks",
            "auto_temp_ticks",
            "auto_deriv_ticks",
            "title_text",
            "suptitle_text",
            "x_major_tick",
            "x_minor_tick",
            "y_major_tick",
            "y_minor_tick",
            "temp_major_tick",
            "temp_minor_tick",
            "deriv_major_tick",
            "deriv_minor_tick",
            "enable_temp_axis",
            "enable_deriv_axis",
            "min_cycle_drop",
            "peak_prominence",
            "peak_distance",
            "peak_width",
            "show_cycle_markers_on_core_plots",
            "show_cycle_legend_on_core_plots",
            "include_moles_in_core_plot_legend",
        )
        effective_args = list(bundle_copy.get("args") or ())
        if len(effective_args) < len(args_keys):
            effective_args.extend([""] * (len(args_keys) - len(effective_args)))
        effective_compare_title = str(
            bundle_copy.get("effective_compare_title") or ""
        ).strip()
        for idx, key in enumerate(args_keys):
            if key not in effective_plot_settings:
                continue
            if key in {"title_text", "suptitle_text"} and not str(
                effective_plot_settings.get(key) or ""
            ).strip():
                # Keep previously resolved profile title identity when override
                # payloads carry blank title fields.
                continue
            effective_args[idx] = copy.deepcopy(effective_plot_settings.get(key))
        profile_name = str(bundle_copy.get("profile_name") or "").strip()
        dataset_stem = ""
        try:
            dataset_stem = Path(str(bundle_copy.get("dataset_path") or "")).stem.strip()
        except Exception:
            dataset_stem = ""
        override_title_text = str(side_plot_override.get("title_text") or "").strip()
        override_suptitle_text = str(side_plot_override.get("suptitle_text") or "").strip()
        if len(effective_args) > 12:
            if override_title_text:
                effective_args[12] = override_title_text
            else:
                resolved_title = str(effective_args[12] or "").strip()
                effective_args[12] = (
                    resolved_title
                    or effective_compare_title
                    or profile_name
                    or dataset_stem
                    or "Profile"
                )
        if len(effective_args) > 13:
            if override_suptitle_text:
                effective_args[13] = override_suptitle_text
            else:
                resolved_suptitle = str(effective_args[13] or "").strip()
                effective_args[13] = (
                    resolved_suptitle or dataset_stem or profile_name or "Profile"
                )

        bundle_copy["plot_settings"] = effective_plot_settings
        bundle_copy["layout_profiles"] = copy.deepcopy(effective_layout_profiles)
        bundle_copy["args"] = tuple(effective_args)
        bundle_copy["state"] = copy.deepcopy(dict(state_payload))
        return bundle_copy

    def _compare_refresh_side_bundle_with_compare_overrides(self, side_key: str) -> bool:
        """Refresh one loaded Compare side bundle with persisted side overrides.

        Purpose:
            Keep loaded Compare side bundles synchronized with pair+side override
            maps stored in `compare_tab`.
        Why:
            `Load Profiles` and side Plot Settings apply should immediately reflect
            compare-scoped side edits without mutating profile files.
        Args:
            side_key: Compare side token (`"A"` or `"B"`).
        Returns:
            True when a side bundle was refreshed; otherwise False.
        Side Effects:
            Updates in-memory side bundle/title metadata for the selected side.
        Exceptions:
            Missing panel/bundle state returns False safely.
        """
        side_token = str(side_key or "").strip().upper()
        if side_token not in {"A", "B"}:
            return False
        panels = getattr(self, "_compare_panels", {})
        panel = (panels or {}).get(side_token) if isinstance(panels, Mapping) else None
        panel = panel if isinstance(panel, Mapping) else {}
        bundle = panel.get("bundle")
        if not isinstance(bundle, Mapping):
            return False
        effective_bundle = self._compare_build_effective_bundle_with_side_overrides(
            side_token,
            bundle,
        )
        panel["bundle"] = effective_bundle
        title_defaults = self._compare_profile_title_defaults(side_token, effective_bundle)
        panel["title_text"] = str(title_defaults.get("title_text") or "").strip()
        panel["suptitle_text"] = str(title_defaults.get("suptitle_text") or "").strip()
        title_var = panel.get("title_var")
        if isinstance(title_var, tk.StringVar):
            display_title = panel["title_text"] or "--"
            display_suptitle = panel["suptitle_text"] or "--"
            title_var.set(f"Title: {display_title}\nSuptitle: {display_suptitle}")
        return True

    def _compare_finalize_side_plot_settings_apply(self, side_key: str) -> None:
        """Finalize one Compare side Plot Settings apply into render-visible state.

        Purpose:
            Commit compare-scoped side Plot Settings edits after dialog apply.
        Why:
            Compare side popup applies must persist pair+side overrides, refresh the
            side bundle, rerender the target side, and resync shared x-axis state.
        Args:
            side_key: Compare side token (`"A"` or `"B"`).
        Returns:
            None.
        Side Effects:
            Persists compare state, refreshes side bundle payload, rerenders one
            side, updates lock-x linkage, and refreshes diagnostics text.
        Exceptions:
            Invalid side tokens are ignored safely.
        """
        side_token = str(side_key or "").strip().upper()
        if side_token not in {"A", "B"}:
            return
        self._compare_persist_state()
        self._compare_refresh_side_bundle_with_compare_overrides(side_token)
        self._compare_render_profile_side(side_token, reason="side_plot_settings")
        self._compare_apply_locked_x_axis(redraw_mode="idle")
        self._compare_refresh_diagnostics_panel()

    def _open_compare_side_plot_settings_dialog(self, side_key: str) -> None:
        """Open full Plot Settings dialog scoped to one Compare side.

        Purpose:
            Provide side-local access to full combined Plot Settings controls.
        Why:
            Compare users need rapid side-by-side tuning without leaving Compare
            and without mutating global/profile defaults.
        Args:
            side_key: Compare side token (`"A"` or `"B"`).
        Returns:
            None.
        Side Effects:
            Opens Plot Settings dialog, captures compare-only pair+side overrides,
            rerenders target side, and persists Compare state.
        Exceptions:
            Missing side bundle shows an informational message.
        """
        side_token = str(side_key or "").strip().upper()
        if side_token not in {"A", "B"}:
            return
        existing_windows = getattr(self, "_compare_side_plot_settings_windows", None)
        if not isinstance(existing_windows, dict):
            existing_windows = {}
            self._compare_side_plot_settings_windows = existing_windows
        existing = existing_windows.get(side_token)
        if existing is not None and existing.winfo_exists():
            try:
                existing.deiconify()
                existing.lift()
                existing.focus_force()
            except Exception:
                pass
            return

        panels = getattr(self, "_compare_panels", {})
        panel = (panels or {}).get(side_token) if isinstance(panels, Mapping) else None
        panel = panel if isinstance(panel, Mapping) else {}
        bundle = panel.get("bundle")
        if not isinstance(bundle, Mapping):
            try:
                messagebox.showinfo(
                    "Compare Plot Settings",
                    (
                        f"Load and render Profile {side_token} before opening "
                        "side Plot Settings."
                    ),
                )
            except Exception:
                pass
            return

        snapshot = self._compare_capture_combined_runtime_snapshot()
        try:
            self._compare_apply_effective_side_settings_to_runtime(side_token, bundle)
            self._open_plot_settings_dialog("fig_combined_triple_axis")
        finally:
            self._compare_restore_combined_runtime_snapshot(snapshot)
        dialog = getattr(self, "_plot_settings_window", None)
        if dialog is None or not dialog.winfo_exists():
            return
        existing_windows[side_token] = dialog
        try:
            dialog.title(f"Compare Side {side_token} Plot Settings")
        except Exception:
            pass

        prior_apply_callback = getattr(self, "_plot_settings_apply_callback", None)
        if not callable(prior_apply_callback):
            return

        def _compare_side_apply(
            close_after: bool = False,
            *,
            refresh_after_apply: bool = True,
        ) -> bool:
            """Apply compare-side Plot Settings edits without global persistence.

            Purpose:
                Wrap base Plot Settings apply to redirect changes into Compare-only
                pair+side override maps.
            Why:
                Full dialog apply commits globally by default; Compare requires
                side-local behavior for quick tuning.
            Inputs:
                close_after: When True, close dialog after applying.
                refresh_after_apply: Unused in wrapper; retained for callback parity.
            Outputs:
                bool: True when staged values were applied.
            Side Effects:
                Captures side overrides, restores runtime snapshot, rerenders side.
            Exceptions:
                Apply errors return False and restore runtime snapshot safely.
            """
            _ = refresh_after_apply
            save_fn = globals().get("_save_settings_to_disk")
            globals()["_save_settings_to_disk"] = lambda: None
            try:
                applied = bool(
                    prior_apply_callback(
                        close_after=False,
                        refresh_after_apply=False,
                    )
                )
            except Exception:
                applied = False
            finally:
                if callable(save_fn):
                    globals()["_save_settings_to_disk"] = save_fn
                else:
                    globals().pop("_save_settings_to_disk", None)

            if applied:
                self._compare_capture_side_plot_settings_from_runtime(side_token)
            self._compare_restore_combined_runtime_snapshot(snapshot)
            if applied:
                self._compare_finalize_side_plot_settings_apply(side_token)
            if close_after:
                self._close_plot_settings_dialog()
                existing_windows.pop(side_token, None)
            return applied

        self._plot_settings_apply_callback = _compare_side_apply
        dialog.protocol(
            "WM_DELETE_WINDOW",
            lambda: _compare_side_apply(close_after=True, refresh_after_apply=False),
        )

    def _compare_default_plot_editor_margins(self) -> Dict[str, float]:
        """Return default subplot margins used by Compare plot-editor controls.

        Purpose:
            Provide one deterministic baseline for Compare editor margin staging.
        Why:
            Margin editor persistence and reset actions must share one canonical
            fallback independent of any malformed persisted values.
        Args:
            None.
        Returns:
            Dict containing normalized `left/right/top/bottom` subplot fractions.
        Side Effects:
            None.
        Exceptions:
            None.
        """
        defaults = _default_layout_margins("fig_combined_triple_axis", "display")
        return {
            key: float(defaults.get(key))
            for key in COMPARE_PLOT_EDITOR_MARGIN_KEYS
            if key in defaults
        }

    def _compare_resolve_side_plot_editor_margins(self, side_key: str) -> Dict[str, float]:
        """Resolve effective persisted plot-editor margins for one Compare side.

        Purpose:
            Retrieve one side's pair-scoped margin overrides for compare rendering.
        Why:
            Compare per-side editor values must survive session reloads and pair
            switches without leaking between unrelated profile pairs.
        Args:
            side_key: Compare side token (`"A"` or `"B"`).
        Returns:
            Dict containing resolved `left/right/top/bottom` values.
        Side Effects:
            None.
        Exceptions:
            Missing/invalid persisted payloads fall back to app defaults.
        """
        side_token = str(side_key or "").strip().upper()
        defaults = self._compare_default_plot_editor_margins()
        if side_token not in {"A", "B"}:
            return dict(defaults)
        pair_key = self._compare_selected_pair_key()
        by_pair = _normalize_compare_plot_editor_margins_by_pair(
            getattr(self, "_compare_plot_editor_margins_by_pair", {})
        )
        side_map = dict((by_pair.get(pair_key) or {}))
        normalized = _normalize_compare_plot_editor_margins(
            side_map.get(side_token),
            defaults=defaults,
        )
        return dict(normalized or defaults)

    def _compare_store_side_plot_editor_margins(
        self,
        side_key: str,
        margins: Mapping[str, Any],
        *,
        persist_state: bool,
    ) -> None:
        """Store one side's plot-editor margins under the current Compare pair key.

        Purpose:
            Persist margin editor values in Compare pair-scoped settings state.
        Why:
            Side-by-side plot editor adjustments must remain isolated by pair and
            side to preserve deterministic user intent.
        Args:
            side_key: Compare side token (`"A"` or `"B"`).
            margins: Candidate margin mapping with `left/right/top/bottom`.
            persist_state: When True, write Compare settings to disk-backed state.
        Returns:
            None.
        Side Effects:
            Updates `_compare_plot_editor_margins_by_pair`; may persist settings.
        Exceptions:
            Invalid side keys are ignored; malformed margins are sanitized.
        """
        side_token = str(side_key or "").strip().upper()
        if side_token not in {"A", "B"}:
            return
        defaults = self._compare_default_plot_editor_margins()
        normalized = _normalize_compare_plot_editor_margins(
            margins,
            defaults=defaults,
        )
        if normalized is None:
            normalized = defaults
        pair_key = self._compare_selected_pair_key()
        by_pair = _normalize_compare_plot_editor_margins_by_pair(
            getattr(self, "_compare_plot_editor_margins_by_pair", {})
        )
        side_map = dict((by_pair.get(pair_key) or {}))
        side_map[side_token] = dict(normalized)
        by_pair[pair_key] = side_map
        self._compare_plot_editor_margins_by_pair = by_pair
        if persist_state:
            self._compare_persist_state()

    def _compare_apply_side_plot_editor_margins(
        self,
        side_key: str,
        margins: Mapping[str, Any],
        *,
        rerender_side: bool,
        persist_state: bool,
    ) -> None:
        """Apply and optionally rerender one side after plot-editor margin updates.

        Purpose:
            Centralize side margin update routing for Compare plot-editor actions.
        Why:
            Editor actions must update state, rerender selected side, and preserve
            lock-x synchronization using one deterministic path.
        Args:
            side_key: Compare side token (`"A"` or `"B"`).
            margins: Candidate `left/right/top/bottom` mapping.
            rerender_side: When True, rerender the target side immediately.
            persist_state: When True, persist updated Compare state.
        Returns:
            None.
        Side Effects:
            Persists side margins and may rerender one compare pane.
        Exceptions:
            Missing pane state is handled as no-op.
        """
        side_token = str(side_key or "").strip().upper()
        self._compare_store_side_plot_editor_margins(
            side_token,
            margins,
            persist_state=persist_state,
        )
        if not rerender_side:
            return
        panels = getattr(self, "_compare_panels", {})
        panel = (panels or {}).get(side_token) if isinstance(panels, Mapping) else None
        panel = panel if isinstance(panel, Mapping) else {}
        if isinstance(panel.get("bundle"), Mapping):
            self._compare_render_profile_side(side_token, reason="plot_editor")
            self._compare_apply_locked_x_axis(redraw_mode="idle")
            self._compare_refresh_diagnostics_panel()

    def _compare_build_plot_editor_preview_figure(
        self,
        side_key: str,
        *,
        fig_size: Optional[Tuple[float, float]] = None,
    ) -> Optional[Figure]:
        """Rebuild a compare-side preview figure for the plot editor window.

        Purpose:
            Generate a deterministic side preview using the same render stack as
            side-by-side Compare panes.
        Why:
            Serialized figure cloning can drift detached-axis offsets/font sizes
            and clip labels in the editor popup.
        Args:
            side_key: Compare side token (`"A"` or `"B"`).
            fig_size: Optional target figure size in inches.
        Returns:
            Rebuilt preview figure, or None when side bundle is unavailable.
        Side Effects:
            Temporarily stages compare render settings in global runtime state.
        Exceptions:
            Build failures return None safely.
        """
        side_token = str(side_key or "").strip().upper()
        if side_token not in {"A", "B"}:
            return None
        panels = getattr(self, "_compare_panels", {})
        panel = (panels or {}).get(side_token) if isinstance(panels, Mapping) else None
        panel = panel if isinstance(panel, Mapping) else {}
        bundle = panel.get("bundle")
        if not isinstance(bundle, Mapping):
            return None
        bundle_dict = dict(bundle)
        try:
            render_ctx, _rows, _total, _meta = self._compare_build_render_context_from_bundle(
                bundle_dict,
                side_key=side_token,
            )
        except Exception:
            return None

        compare_state = _normalize_compare_tab_settings(settings.get("compare_tab"))
        use_profile_layout = bool(
            self.compare_use_profile_layout_var.get()
            if hasattr(self, "compare_use_profile_layout_var")
            else compare_state.get("use_profile_layout", False)
        )
        custom_presets = _normalize_compare_custom_plot_presets(
            getattr(
                self,
                "_compare_custom_plot_presets",
                compare_state.get("custom_plot_presets"),
            )
        )
        selected_preset_name = str(
            self.compare_plot_preset_var.get()
            if hasattr(self, "compare_plot_preset_var")
            else compare_state.get("plot_preset_name")
            or DEFAULT_COMPARE_PLOT_PRESET_NAME
        ).strip()
        compare_preset_values = _resolve_compare_plot_preset_values(
            selected_preset_name,
            custom_presets=custom_presets,
        )
        compare_layout_overrides = _normalize_compare_layout_overrides(
            getattr(
                self,
                "_compare_layout_overrides",
                compare_state.get("layout_overrides"),
            )
        )
        pair_plot_elements_override = self._compare_effective_pair_plot_elements_override()
        side_plot_settings_override = self._compare_resolve_side_plot_settings_override(
            side_token
        )
        side_layout_override = self._compare_resolve_side_layout_override(side_token)
        side_override_map = (
            pair_plot_elements_override.get("side_overrides")
            if isinstance(pair_plot_elements_override, Mapping)
            else {}
        )
        side_override_map = (
            side_override_map if isinstance(side_override_map, Mapping) else {}
        )
        side_plot_override = (
            side_override_map.get(side_token)
            if isinstance(side_override_map.get(side_token), Mapping)
            else {}
        )
        retain_profile_elements = bool(
            pair_plot_elements_override.get("retain_profile_elements", True)
            if isinstance(pair_plot_elements_override, Mapping)
            else True
        )
        hide_text_family = bool(
            pair_plot_elements_override.get("hide_text_family", False)
            if isinstance(pair_plot_elements_override, Mapping)
            else False
        )

        prior_df = getattr(self, "df", None)
        prior_combined_state = getattr(self, "_combined_plot_state", None)
        prior_combined_layout_state = getattr(self, "_combined_layout_state", None)
        prior_combined_layout_dirty = getattr(self, "_combined_layout_dirty", False)
        prior_combined_legend_anchor = getattr(self, "_combined_legend_anchor", None)
        prior_combined_legend_loc = getattr(self, "_combined_legend_loc", None)
        prior_layout_profiles = settings.get("layout_profiles")
        sentinel = object()
        overridden_keys: Dict[str, Any] = {}
        overridden_tk_vars: Dict[str, Any] = {}
        args_for_render = list(bundle_dict.get("args") or ())
        if len(args_for_render) < 14:
            args_for_render.extend([""] * (14 - len(args_for_render)))
        default_titles = self._compare_profile_title_defaults(side_token, bundle_dict)
        override_title_text = str(side_plot_override.get("title_text") or "").strip()
        override_suptitle_text = str(side_plot_override.get("suptitle_text") or "").strip()
        args_for_render[12] = override_title_text or str(
            default_titles.get("title_text") or ""
        ).strip()
        args_for_render[13] = override_suptitle_text or str(
            default_titles.get("suptitle_text") or ""
        ).strip()

        def _override_tk_var(setting_key: str, var_attr_name: str, payload: Mapping[str, Any]) -> None:
            """Temporarily apply one compare payload value to a Tk variable."""
            if setting_key not in payload:
                return
            var_obj = getattr(self, var_attr_name, None)
            if var_obj is None:
                return
            if var_attr_name not in overridden_tk_vars:
                try:
                    overridden_tk_vars[var_attr_name] = var_obj.get()
                except Exception:
                    overridden_tk_vars[var_attr_name] = sentinel
            try:
                var_obj.set(payload.get(setting_key))
            except Exception:
                pass

        fig: Optional[Figure] = None
        try:
            profile_plot_settings = dict(bundle_dict.get("plot_settings") or {})
            for key, value in profile_plot_settings.items():
                overridden_keys[key] = settings.get(key, sentinel)
                settings[key] = copy.deepcopy(value)
            for key, value in compare_preset_values.items():
                if key not in overridden_keys:
                    overridden_keys[key] = settings.get(key, sentinel)
                settings[key] = copy.deepcopy(value)
            for key, value in compare_layout_overrides.items():
                if key not in overridden_keys:
                    overridden_keys[key] = settings.get(key, sentinel)
                settings[key] = copy.deepcopy(value)
            for key, value in side_plot_settings_override.items():
                if key not in overridden_keys:
                    overridden_keys[key] = settings.get(key, sentinel)
                settings[key] = copy.deepcopy(value)
            for setting_key, attr_name in COMPARE_SIDE_PLOT_SETTINGS_TK_BINDINGS:
                _override_tk_var(setting_key, attr_name, compare_preset_values)
                _override_tk_var(setting_key, attr_name, compare_layout_overrides)
                _override_tk_var(setting_key, attr_name, side_plot_settings_override)

            merged_elements = (
                copy.deepcopy(settings.get("plot_elements"))
                if isinstance(settings.get("plot_elements"), dict)
                else {}
            )
            profile_elements_map = bundle_dict.get("plot_elements")
            profile_elements_map = (
                profile_elements_map if isinstance(profile_elements_map, Mapping) else {}
            )
            profile_elements_raw = (
                list(profile_elements_map.get("fig_combined_triple_axis") or [])
                if retain_profile_elements
                else []
            )
            normalized_profile_elements = _normalize_plot_elements(
                {"fig_combined_triple_axis": profile_elements_raw}
            ).get("fig_combined_triple_axis", [])
            if hide_text_family:
                filtered_elements: List[Dict[str, Any]] = []
                for element in normalized_profile_elements:
                    if not isinstance(element, Mapping):
                        continue
                    raw_type = str(element.get("type") or "").strip().lower()
                    canonical_type = _canonicalize_annotation_type(raw_type) or raw_type
                    if canonical_type in {"text", "callout"}:
                        continue
                    filtered_elements.append(dict(element))
                normalized_profile_elements = filtered_elements
            merged_elements["fig_combined_triple_axis"] = copy.deepcopy(
                normalized_profile_elements
            )
            overridden_keys["plot_elements"] = settings.get("plot_elements", sentinel)
            settings["plot_elements"] = merged_elements
            overridden_keys["layout_health_context"] = settings.get(
                "layout_health_context", sentinel
            )
            settings["layout_health_context"] = "compare"
            self._combined_legend_anchor = None
            self._combined_legend_loc = None

            profile_layouts = bundle_dict.get("layout_profiles") or {}
            profile_layout_source: Any = {}
            if use_profile_layout and isinstance(profile_layouts, Mapping):
                profile_layout_source = profile_layouts.get("fig_combined_triple_axis", {})
            resolved_layout_profile = _normalize_layout_profile(
                profile_layout_source,
                "fig_combined_triple_axis",
            )
            if isinstance(side_layout_override, Mapping) and side_layout_override:
                side_layout_profile = _normalize_layout_profile(
                    side_layout_override, "fig_combined_triple_axis"
                )
                for mode_key in ("display", "export"):
                    section = _layout_profile_section(resolved_layout_profile, mode_key)
                    side_section = _layout_profile_section(side_layout_profile, mode_key)
                    for layout_key in (
                        "title_xy",
                        "suptitle_xy",
                        "legend_anchor",
                        "legend_anchor_y",
                        "legend_loc",
                        "cycle_legend_anchor",
                        "cycle_legend_loc",
                        "xlabel_pad_pts",
                        "detached_spine_offset",
                        "detached_labelpad",
                    ):
                        section[layout_key] = copy.deepcopy(side_section.get(layout_key))
                    section["axis_labelpads"] = copy.deepcopy(
                        side_section.get("axis_labelpads") or {}
                    )
                resolved_layout_profile["mirror_detached_labelpad"] = bool(
                    side_layout_profile.get("mirror_detached_labelpad", False)
                )
            display_section = _layout_profile_section(resolved_layout_profile, "display")
            default_display_margins = _default_layout_margins(
                "fig_combined_triple_axis", "display"
            )
            if self._compare_side_plot_editor_margins_is_explicit(side_token):
                side_margin_override = _normalize_compare_plot_editor_margins(
                    self._compare_resolve_side_plot_editor_margins(side_token),
                    defaults=default_display_margins,
                )
                display_section["margins"] = _normalize_layout_margins(
                    side_margin_override or default_display_margins,
                    default_display_margins,
                )
            for layout_key in COMPARE_LAYOUT_PROFILE_SECTION_KEYS:
                if layout_key not in compare_layout_overrides:
                    continue
                display_section[layout_key] = copy.deepcopy(
                    compare_layout_overrides.get(layout_key)
                )
            if not use_profile_layout:
                for mode_key in ("display", "export"):
                    section = _layout_profile_section(resolved_layout_profile, mode_key)
                    for key in COMPARE_LAYOUT_RESET_KEYS_WHEN_PROFILE_LAYOUT_DISABLED:
                        section[key] = None
                    section["axis_labelpads"] = {}
            merged_layouts = _normalize_layout_profiles(prior_layout_profiles)
            merged_layouts["fig_combined_triple_axis"] = resolved_layout_profile
            settings["layout_profiles"] = merged_layouts
            for layout_key in COMPARE_LAYOUT_ANCHOR_KEYS:
                if layout_key not in overridden_keys:
                    overridden_keys[layout_key] = settings.get(layout_key, sentinel)
                settings.pop(layout_key, None)

            self.df = bundle_dict.get("df_reference")
            fig = self._build_combined_triple_axis_from_state(
                args=tuple(args_for_render),
                fig_size=fig_size or self._compare_resolve_figsize_for_panel(side_token),
                mode="display",
                reuse=False,
                canvas=None,
                render_ctx=render_ctx,
                perf_run=None,
            )
        except Exception:
            fig = None
        finally:
            for key, prior_value in overridden_keys.items():
                if prior_value is sentinel:
                    settings.pop(key, None)
                else:
                    settings[key] = prior_value
            if prior_layout_profiles is None:
                settings.pop("layout_profiles", None)
            else:
                settings["layout_profiles"] = prior_layout_profiles
            for attr_name, prior_value in overridden_tk_vars.items():
                var_obj = getattr(self, attr_name, None)
                if var_obj is None:
                    continue
                if prior_value is sentinel:
                    continue
                try:
                    var_obj.set(prior_value)
                except Exception:
                    continue
            self.df = prior_df
            self._combined_plot_state = prior_combined_state
            self._combined_layout_state = prior_combined_layout_state
            self._combined_layout_dirty = prior_combined_layout_dirty
            self._combined_legend_anchor = prior_combined_legend_anchor
            self._combined_legend_loc = prior_combined_legend_loc
        if fig is not None:
            try:
                fig._gl260_layout_health_context = "compare"  # type: ignore[attr-defined]
            except Exception:
                pass
            self._compare_main_legend_visibility_guard(fig)
        return fig

    def _compare_clone_figure_for_plot_editor(
        self,
        source_fig: Optional[Figure],
        *,
        side_key: Optional[str] = None,
        fig_size: Optional[Tuple[float, float]] = None,
    ) -> Optional[Figure]:
        """Rebuild a Compare plot-editor preview figure (legacy clone wrapper).

        Purpose:
            Preserve historical clone-call sites while routing to deterministic
            side preview rebuild logic.
        Why:
            Pickle-based cloning causes detached-axis/label clipping drift.
        Args:
            source_fig: Legacy source figure argument (unused in rebuild path).
            side_key: Compare side token used to rebuild from side bundle context.
            fig_size: Optional preview figure size override in inches.
        Returns:
            Rebuilt preview figure when side bundle/render context is available.
        Side Effects:
            None.
        Exceptions:
            Missing side key/bundle returns None.
        """
        _ = source_fig
        if not side_key:
            return None
        return self._compare_build_plot_editor_preview_figure(
            side_key,
            fig_size=fig_size,
        )

    def _open_compare_side_plot_editor(self, side_key: str) -> None:
        """Open the per-side Compare plot editor with toolbar and margin controls.

        Purpose:
            Provide one side-local workspace to tune subplot margins interactively.
        Why:
            Compare panes are compact and require manual margin controls that persist
            per selected A/B pair and side.
        Args:
            side_key: Compare side token (`"A"` or `"B"`).
        Returns:
            None.
        Side Effects:
            Creates one editor window, updates persisted side margins, and may
            rerender one compare pane when Apply+Rerender is used.
        Exceptions:
            Missing side figures show an informational prompt.
        """
        side_token = str(side_key or "").strip().upper()
        if side_token not in {"A", "B"}:
            return
        windows = getattr(self, "_compare_plot_editor_windows", None)
        if not isinstance(windows, dict):
            windows = {}
            self._compare_plot_editor_windows = windows
        existing = windows.get(side_token)
        if existing is not None and existing.winfo_exists():
            try:
                existing.deiconify()
                existing.lift()
                existing.focus_force()
            except Exception:
                pass
            return

        panels = getattr(self, "_compare_panels", {})
        panel = (panels or {}).get(side_token) if isinstance(panels, Mapping) else None
        panel = panel if isinstance(panel, Mapping) else {}
        if not isinstance(panel.get("bundle"), Mapping):
            try:
                messagebox.showinfo(
                    "Compare Plot Editor",
                    f"Load and render Profile {side_token} before opening the plot editor.",
                )
            except Exception:
                pass
            return
        preview_fig = self._compare_build_plot_editor_preview_figure(
            side_token,
            fig_size=(8.6, 4.8),
        )
        if preview_fig is None:
            preview_fig = Figure(figsize=(8.6, 4.8), dpi=100)
            preview_axis = preview_fig.add_subplot(111)
            preview_axis.text(
                0.5,
                0.5,
                "Preview rebuild unavailable.\nApply + Rerender to regenerate preview.",
                ha="center",
                va="center",
            )
            preview_axis.set_axis_off()

        window = tk.Toplevel(self)
        window.title(f"Compare Plot Editor - Side {side_token}")
        window.transient(self)
        window.geometry("1280x760")
        window.grid_rowconfigure(0, weight=1)
        window.grid_columnconfigure(0, weight=1)
        windows[side_token] = window

        root = ttk.Frame(window, padding=10)
        root.grid(row=0, column=0, sticky="nsew")
        root.grid_rowconfigure(1, weight=1)
        root.grid_columnconfigure(0, weight=1)

        ttk.Label(
            root,
            text=(
                "Use toolbar and controls to tune subplot margins for this side. "
                "Captured values persist per selected A/B pair.\n"
                "Comparison report uses side-by-side panes as the output source."
            ),
            justify="left",
            anchor="w",
        ).grid(row=0, column=0, sticky="ew", pady=(0, 8))

        main_body = ttk.Frame(root)
        main_body.grid(row=1, column=0, sticky="nsew")
        main_body.grid_rowconfigure(0, weight=1)
        main_body.grid_columnconfigure(0, weight=4)
        main_body.grid_columnconfigure(1, weight=0)

        preview_shell = ttk.Frame(main_body)
        preview_shell.grid(row=0, column=0, sticky="nsew", padx=(0, 10))
        preview_shell.grid_rowconfigure(1, weight=1)
        preview_shell.grid_columnconfigure(0, weight=1)
        preview_canvas = FigureCanvasTkAgg(preview_fig, master=preview_shell)
        toolbar = NavigationToolbar2Tk(preview_canvas, preview_shell, pack_toolbar=False)
        toolbar.update()
        toolbar.grid(row=0, column=0, sticky="ew")
        self._apply_toolbar_scaling(toolbar)
        preview_widget = preview_canvas.get_tk_widget()
        preview_widget.grid(row=1, column=0, sticky="nsew")
        preview_figure_ref: Dict[str, Figure] = {"figure": preview_fig}

        def _current_preview_figure() -> Figure:
            """Return the current preview figure used by editor callbacks.

            Purpose:
                Resolve the active preview figure after rerender-triggered refreshes.
            Why:
                Plot-editor apply+rerender replaces the preview figure object, so
                callbacks must dereference the latest figure each time.
            Args:
                None.
            Returns:
                Active preview figure instance.
            Side Effects:
                None.
            Exceptions:
                None.
            """
            return preview_figure_ref["figure"]

        controls = ttk.LabelFrame(main_body, text="Margins")
        controls.grid(row=0, column=1, sticky="ns")
        controls.grid_columnconfigure(1, weight=1)
        defaults = self._compare_default_plot_editor_margins()
        resolved = self._compare_resolve_side_plot_editor_margins(side_token)
        staged_vars: Dict[str, tk.DoubleVar] = {
            key: tk.DoubleVar(value=float(resolved.get(key, defaults.get(key, 0.0))))
            for key in COMPARE_PLOT_EDITOR_MARGIN_KEYS
        }

        def _collect_staged_margins() -> Dict[str, float]:
            """Collect one normalized margins payload from staged editor controls."""
            payload: Dict[str, float] = {}
            for margin_key in COMPARE_PLOT_EDITOR_MARGIN_KEYS:
                var_obj = staged_vars.get(margin_key)
                if var_obj is None:
                    continue
                try:
                    payload[margin_key] = float(var_obj.get())
                except Exception:
                    continue
            normalized = _normalize_compare_plot_editor_margins(
                payload,
                defaults=defaults,
            )
            return dict(normalized or defaults)

        def _apply_preview_margins(*, redraw: bool) -> None:
            """Apply staged margins to the preview figure and optionally redraw."""
            margins_payload = _collect_staged_margins()
            preview_local = _current_preview_figure()
            try:
                preview_local.subplots_adjust(**margins_payload)
            except Exception:
                pass
            layout_mgr = getattr(preview_local, "_gl260_layout_manager", None)
            if layout_mgr is not None:
                try:
                    layout_mgr._baseline_left = float(margins_payload.get("left"))
                    layout_mgr._baseline_right = float(margins_payload.get("right"))
                    layout_mgr._baseline_top = float(margins_payload.get("top"))
                    layout_mgr._baseline_bottom = float(margins_payload.get("bottom"))
                    layout_mgr.solve(max_passes=1, allow_draw=False)
                except Exception:
                    pass
            if not redraw:
                return
            try:
                preview_canvas.draw_idle()
            except Exception:
                try:
                    preview_canvas.draw()
                except Exception:
                    pass

        def _capture_current_margins() -> None:
            """Capture the preview figure's current subplotpars into staged controls."""
            preview_local = _current_preview_figure()
            subplotpars = getattr(preview_local, "subplotpars", None)
            if subplotpars is None:
                return
            for margin_key in COMPARE_PLOT_EDITOR_MARGIN_KEYS:
                var_obj = staged_vars.get(margin_key)
                if var_obj is None:
                    continue
                try:
                    var_obj.set(float(getattr(subplotpars, margin_key)))
                except Exception:
                    continue
            _apply_preview_margins(redraw=True)

        def _reset_defaults() -> None:
            """Reset staged controls to Compare default margins for this plot type."""
            for margin_key in COMPARE_PLOT_EDITOR_MARGIN_KEYS:
                var_obj = staged_vars.get(margin_key)
                if var_obj is None:
                    continue
                try:
                    var_obj.set(float(defaults.get(margin_key, 0.0)))
                except Exception:
                    continue
            _apply_preview_margins(redraw=True)

        def _apply_to_compare(*, rerender: bool) -> None:
            """Commit staged margins to Compare state and optionally rerender side."""
            self._compare_apply_side_plot_editor_margins(
                side_token,
                _collect_staged_margins(),
                rerender_side=rerender,
                persist_state=True,
            )
            if rerender:
                try:
                    preview_widget.update_idletasks()
                    width_px = int(preview_widget.winfo_width() or 0)
                    height_px = int(preview_widget.winfo_height() or 0)
                except Exception:
                    width_px = 0
                    height_px = 0
                try:
                    dpi = float(preview_canvas.figure.get_dpi() or 100.0)
                except Exception:
                    dpi = 100.0
                if dpi <= 0.0 or not math.isfinite(dpi):
                    dpi = 100.0
                fallback_fig = _current_preview_figure()
                try:
                    fallback_size = tuple(fallback_fig.get_size_inches())
                except Exception:
                    fallback_size = (8.6, 4.8)
                target_size = (
                    max(width_px / dpi, 2.0),
                    max(height_px / dpi, 2.0),
                ) if width_px > 2 and height_px > 2 else fallback_size
                rebuilt = self._compare_build_plot_editor_preview_figure(
                    side_token,
                    fig_size=target_size,
                )
                if rebuilt is None:
                    return
                preview_figure_ref["figure"] = rebuilt
                try:
                    rebuilt.set_canvas(preview_canvas)
                except Exception:
                    pass
                try:
                    preview_canvas.figure = rebuilt
                except Exception:
                    pass
                try:
                    toolbar.update()
                except Exception:
                    pass
                _capture_current_margins()
                try:
                    preview_canvas.draw_idle()
                except Exception:
                    pass

        row_idx = 0
        for margin_key, label_text in (
            ("left", "Left"),
            ("right", "Right"),
            ("top", "Top"),
            ("bottom", "Bottom"),
        ):
            ttk.Label(controls, text=label_text).grid(
                row=row_idx,
                column=0,
                sticky="w",
                padx=(8, 6),
                pady=(6 if row_idx == 0 else 2, 2),
            )
            spin = ttk.Spinbox(
                controls,
                from_=0.0,
                to=1.0,
                increment=0.005,
                textvariable=staged_vars[margin_key],
                width=10,
                command=lambda: _apply_preview_margins(redraw=True),
            )
            spin.grid(
                row=row_idx,
                column=1,
                sticky="ew",
                padx=(0, 8),
                pady=(6 if row_idx == 0 else 2, 2),
            )
            spin.bind("<FocusOut>", lambda _event: _apply_preview_margins(redraw=True))
            spin.bind("<Return>", lambda _event: _apply_preview_margins(redraw=True))
            row_idx += 1

        actions = ttk.Frame(controls)
        actions.grid(
            row=row_idx,
            column=0,
            columnspan=2,
            sticky="ew",
            padx=8,
            pady=(10, 8),
        )
        actions.grid_columnconfigure(0, weight=1)
        self._compare_make_button(
            actions,
            text="Capture Current Margins",
            command=_capture_current_margins,
            compact=True,
        ).grid(row=0, column=0, sticky="ew", pady=(0, 4))
        self._compare_make_button(
            actions,
            text="Apply",
            command=lambda: _apply_to_compare(rerender=False),
            compact=True,
        ).grid(row=1, column=0, sticky="ew", pady=2)
        self._compare_make_button(
            actions,
            text="Apply + Rerender",
            command=lambda: _apply_to_compare(rerender=True),
            compact=True,
        ).grid(row=2, column=0, sticky="ew", pady=2)
        self._compare_make_button(
            actions,
            text="Reset",
            command=_reset_defaults,
            compact=True,
        ).grid(row=3, column=0, sticky="ew", pady=2)

        def _close_window() -> None:
            """Close this side editor window and release stored window references."""
            try:
                window.destroy()
            except Exception:
                pass
            windows.pop(side_token, None)

        window.protocol("WM_DELETE_WINDOW", _close_window)
        _capture_current_margins()

    def _compare_profile_title_defaults(
        self,
        side_key: str,
        bundle: Optional[Mapping[str, Any]],
    ) -> Dict[str, str]:
        """Resolve fallback title/suptitle strings for one Compare side.

        Purpose:
            Provide deterministic fallback plot titles for Compare-side controls.
        Why:
            Compare should retain profile identity text even when a profile omits
            explicit title/suptitle settings; when available, Compare should prefer
            pre-resolved profile auto-title output for title parity.
        Args:
            side_key: Compare side key (`"A"` or `"B"`).
            bundle: Optional loaded compare bundle for this side.
        Returns:
            Dict containing `title_text` and `suptitle_text`.
        Side Effects:
            None.
        Exceptions:
            Missing/invalid bundle values fall back to profile selector text.
        """
        profile_name = ""
        dataset_stem = ""
        effective_compare_title = ""
        args = ()
        if isinstance(bundle, Mapping):
            profile_name = str(bundle.get("profile_name") or "").strip()
            dataset_path = str(bundle.get("dataset_path") or "").strip()
            if dataset_path:
                try:
                    dataset_stem = Path(dataset_path).stem.strip()
                except Exception:
                    dataset_stem = ""
            effective_compare_title = str(
                bundle.get("effective_compare_title") or ""
            ).strip()
            args = tuple(bundle.get("args") or ())
        if not profile_name:
            if side_key == "A" and hasattr(self, "compare_profile_a_var"):
                profile_name = str(self.compare_profile_a_var.get() or "").strip()
            elif side_key == "B" and hasattr(self, "compare_profile_b_var"):
                profile_name = str(self.compare_profile_b_var.get() or "").strip()
        title_text = str(args[12] if len(args) > 12 else "").strip()
        if not title_text:
            title_text = effective_compare_title
        suptitle_text = str(args[13] if len(args) > 13 else "").strip()
        if not title_text:
            title_text = profile_name or f"Profile {side_key}"
        if not suptitle_text:
            suptitle_text = dataset_stem or profile_name or f"Profile {side_key}"
        return {"title_text": title_text, "suptitle_text": suptitle_text}

    def _compare_resolve_effective_profile_title(
        self,
        *,
        manual_title: str,
        state: Mapping[str, Any],
        plot_settings: Mapping[str, Any],
        data_bundle: Mapping[str, Any],
    ) -> str:
        """Resolve one Compare bundle title with the same auto-title path as Plot Settings.

        Purpose:
            Compute the profile title used by Compare using profile-local auto-title
            settings and profile-local data context.
        Why:
            Compare side labels and report metadata should match the auto-generated
            title seen in that profile's Plot Settings tab.
        Args:
            manual_title: Profile-saved manual title text from plot settings.
            state: Deserialized profile payload used to recover column assignments.
            plot_settings: Profile plot-settings mapping (auto-title options included).
            data_bundle: Prepared Compare data payload containing `df_reference` and
                `data_ctx` metadata.
        Returns:
            Effective title text resolved through `_resolve_effective_title`.
        Side Effects:
            Temporarily stages data/title state (`df`, `columns`, `_stitched_dt_col`,
            auto-title Tk vars, `settings` title keys, and auto-title view cache),
            then restores all prior values.
        Exceptions:
            Any staging or resolution failure falls back to the input manual title.
        """
        manual_title_text = str(manual_title or "").strip()
        if not isinstance(plot_settings, Mapping):
            return manual_title_text

        resolver = getattr(self, "_resolve_effective_title", None)
        if not callable(resolver):
            return manual_title_text

        required_var_attrs = (
            "auto_title_enabled_var",
            "auto_title_source_var",
            "auto_title_day_mode_var",
            "auto_title_template_var",
            "title_data_type_var",
        )
        for attr_name in required_var_attrs:
            if getattr(self, attr_name, None) is None:
                return manual_title_text

        sentinel = object()
        prior_df = getattr(self, "df", None)
        prior_columns = getattr(self, "columns", sentinel)
        prior_stitched_dt_col = getattr(self, "_stitched_dt_col", sentinel)
        prior_cache = copy.deepcopy(getattr(self, "_auto_title_view_cache", {}))
        prior_title_types = copy.deepcopy(settings.get("title_data_types", sentinel))
        prior_selected_type = settings.get("title_selected_type", sentinel)
        prior_var_values: Dict[str, Any] = {}

        data_ctx = data_bundle.get("data_ctx")
        data_ctx = data_ctx if isinstance(data_ctx, Mapping) else {}
        selected_columns = data_ctx.get("selected_columns")
        selected_columns = selected_columns if isinstance(selected_columns, Mapping) else {}
        columns_snapshot = state.get("column_assignments")
        columns_snapshot = (
            columns_snapshot if isinstance(columns_snapshot, Mapping) else selected_columns
        )
        staged_columns = dict(columns_snapshot)

        staged_df = data_bundle.get("df_reference")
        if not isinstance(staged_df, pd.DataFrame):
            staged_df = prior_df

        title_type_choices = _normalize_title_type_list(
            plot_settings.get("title_data_types")
        )
        if not title_type_choices:
            title_type_choices = _normalize_title_type_list(settings.get("title_data_types"))
        selected_type = str(plot_settings.get("title_selected_type") or "").strip()
        if selected_type:
            matched_type = None
            # Iterate over title_type_choices to preserve case-insensitive profile selection.
            for candidate in title_type_choices:
                if str(candidate).casefold() == selected_type.casefold():
                    matched_type = candidate
                    break
            if matched_type is None:
                title_type_choices.append(selected_type)
                matched_type = selected_type
            selected_type = matched_type
        if not selected_type:
            selected_type = title_type_choices[0]

        source_value = str(
            plot_settings.get(
                "auto_title_source",
                settings.get("auto_title_source", AUTO_TITLE_SOURCE_FULL),
            )
            or AUTO_TITLE_SOURCE_FULL
        ).strip().lower()
        if source_value not in AUTO_TITLE_SOURCES:
            source_value = AUTO_TITLE_SOURCE_FULL
        day_mode_value = str(
            plot_settings.get(
                "auto_title_day_mode",
                settings.get("auto_title_day_mode", AUTO_TITLE_DAY_DIFF),
            )
            or AUTO_TITLE_DAY_DIFF
        ).strip().lower()
        if day_mode_value not in AUTO_TITLE_DAY_MODES:
            day_mode_value = AUTO_TITLE_DAY_DIFF
        template_value = str(
            plot_settings.get(
                "auto_title_template",
                settings.get("auto_title_template", DEFAULT_AUTO_TITLE_TEMPLATE),
            )
            or ""
        ).strip()
        if not template_value:
            template_value = DEFAULT_AUTO_TITLE_TEMPLATE
        enabled_value = bool(plot_settings.get("auto_title_enabled", False))

        try:
            for attr_name in required_var_attrs:
                var_obj = getattr(self, attr_name, None)
                if var_obj is None:
                    continue
                try:
                    prior_var_values[attr_name] = var_obj.get()
                except Exception:
                    prior_var_values[attr_name] = sentinel

            self.df = staged_df
            self.columns = staged_columns
            if prior_stitched_dt_col is not sentinel:
                self._stitched_dt_col = prior_stitched_dt_col  # type: ignore[attr-defined]
            settings["title_data_types"] = list(title_type_choices)
            settings["title_selected_type"] = selected_type
            self._auto_title_view_cache = {}
            try:
                self.auto_title_enabled_var.set(enabled_value)
                self.auto_title_source_var.set(source_value)
                self.auto_title_day_mode_var.set(day_mode_value)
                self.auto_title_template_var.set(template_value)
                self.title_data_type_var.set(selected_type)
            except Exception:
                return manual_title_text

            resolved = str(resolver(manual_title_text, preview=True) or "").strip()
            return resolved or manual_title_text
        except Exception:
            return manual_title_text
        finally:
            self.df = prior_df
            if prior_columns is sentinel:
                try:
                    delattr(self, "columns")
                except Exception:
                    pass
            else:
                self.columns = prior_columns
            if prior_stitched_dt_col is not sentinel:
                self._stitched_dt_col = prior_stitched_dt_col  # type: ignore[attr-defined]
            if prior_title_types is sentinel:
                settings.pop("title_data_types", None)
            else:
                settings["title_data_types"] = prior_title_types
            if prior_selected_type is sentinel:
                settings.pop("title_selected_type", None)
            else:
                settings["title_selected_type"] = prior_selected_type
            self._auto_title_view_cache = (
                prior_cache if isinstance(prior_cache, dict) else {}
            )
            for attr_name in required_var_attrs:
                var_obj = getattr(self, attr_name, None)
                if var_obj is None:
                    continue
                prior_value = prior_var_values.get(attr_name, sentinel)
                if prior_value is sentinel:
                    continue
                try:
                    var_obj.set(prior_value)
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting workflow.
                    pass

    def _compare_default_pair_plot_elements_override(self) -> Dict[str, Any]:
        """Build default Compare pair override payload from loaded side bundles.

        Purpose:
            Seed pair override defaults from currently loaded profile identities.
        Why:
            Plot Elements reset and first-open paths should show profile-native
            title/suptitle values without inheriting unrelated workspace state.
        Args:
            None.
        Returns:
            Normalized pair override payload.
        Side Effects:
            None.
        Exceptions:
            Missing bundles fall back to selector-based side identity text.
        """
        defaults = _default_compare_plot_elements_pair_override()
        panels = getattr(self, "_compare_panels", {}) if isinstance(getattr(self, "_compare_panels", {}), dict) else {}
        for side_key in ("A", "B"):
            bundle = (panels.get(side_key) or {}).get("bundle")
            side_defaults = self._compare_profile_title_defaults(
                side_key, bundle if isinstance(bundle, Mapping) else None
            )
            defaults["side_overrides"][side_key] = {
                "title_text": str(side_defaults.get("title_text") or "").strip(),
                "suptitle_text": str(side_defaults.get("suptitle_text") or "").strip(),
            }
        return _normalize_compare_plot_elements_pair_override(defaults)

    def _compare_effective_pair_plot_elements_override(self) -> Dict[str, Any]:
        """Resolve effective Compare pair override payload for current A/B pair.

        Purpose:
            Merge persisted pair-scoped overrides with loaded-profile defaults.
        Why:
            Compare Plot Elements dialog and renderer need one consistent payload
            regardless of whether this pair has saved overrides yet, and new pairs
            should default to text-element removal for less clutter in Compare.
        Args:
            None.
        Returns:
            Normalized effective pair override payload.
        Side Effects:
            None.
        Exceptions:
            Invalid persisted payloads are normalized safely.
        """
        pair_key = self._compare_selected_pair_key()
        by_pair = _normalize_compare_plot_elements_overrides_by_pair(
            getattr(self, "_compare_plot_elements_overrides_by_pair", {})
        )
        effective = self._compare_default_pair_plot_elements_override()
        # New/unsaved pairs default to hidden text-family elements in Compare so
        # side-by-side views prioritize traces, spans, and masks.
        effective["hide_text_family"] = True
        persisted = by_pair.get(pair_key)
        if isinstance(persisted, Mapping):
            persisted_norm = _normalize_compare_plot_elements_pair_override(persisted)
            effective["retain_profile_elements"] = bool(
                persisted_norm.get("retain_profile_elements", True)
            )
            effective["hide_text_family"] = bool(
                persisted_norm.get("hide_text_family", False)
            )
            side_overrides = persisted_norm.get("side_overrides")
            side_overrides = side_overrides if isinstance(side_overrides, Mapping) else {}
            for side_key in ("A", "B"):
                payload = side_overrides.get(side_key)
                payload = payload if isinstance(payload, Mapping) else {}
                effective["side_overrides"][side_key] = {
                    "title_text": str(payload.get("title_text") or "").strip(),
                    "suptitle_text": str(payload.get("suptitle_text") or "").strip(),
                }
        return _normalize_compare_plot_elements_pair_override(effective)

    def _compare_store_pair_plot_elements_override(
        self,
        payload: Mapping[str, Any],
        *,
        persist_state: bool,
    ) -> None:
        """Store Plot Elements override payload for the current Compare pair.

        Purpose:
            Persist one pair-scoped compare override entry into in-memory state.
        Why:
            Compare rendering now honors per-pair title/suptitle and element filters.
        Args:
            payload: Pair override payload to store.
            persist_state: When True, write compare state to settings.
        Returns:
            None.
        Side Effects:
            Updates `_compare_plot_elements_overrides_by_pair`; may persist settings.
        Exceptions:
            Invalid payload values are normalized.
        """
        pair_key = self._compare_selected_pair_key()
        by_pair = _normalize_compare_plot_elements_overrides_by_pair(
            getattr(self, "_compare_plot_elements_overrides_by_pair", {})
        )
        by_pair[pair_key] = _normalize_compare_plot_elements_pair_override(payload)
        self._compare_plot_elements_overrides_by_pair = by_pair
        if persist_state:
            self._compare_persist_state()

    def _open_compare_plot_elements_dialog(self) -> None:
        """Open Compare pair-scoped Plot Elements fallback controls dialog.

        Purpose:
            Allow manual title/suptitle overrides and plot-element policies per pair.
        Why:
            Compare panes require per-profile fallback controls when saved profile
            plot elements or title fields are absent/legacy.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Creates one dialog, updates pair-scoped compare settings, and rerenders
            loaded compare panes when settings are applied.
        Exceptions:
            Missing pair selection shows an informational prompt.
        """
        profile_a_name = (
            str(self.compare_profile_a_var.get() or "")
            if hasattr(self, "compare_profile_a_var")
            else ""
        ).strip()
        profile_b_name = (
            str(self.compare_profile_b_var.get() or "")
            if hasattr(self, "compare_profile_b_var")
            else ""
        ).strip()
        if not profile_a_name and not profile_b_name:
            try:
                messagebox.showinfo(
                    "Compare Plot Elements",
                    "Select at least one Compare profile before editing Plot Elements.",
                )
            except Exception:
                pass
            return
        existing = getattr(self, "_compare_plot_elements_window", None)
        if existing is not None and existing.winfo_exists():
            try:
                existing.deiconify()
                existing.lift()
                existing.focus_force()
            except Exception:
                pass
            return

        effective = self._compare_effective_pair_plot_elements_override()
        side_overrides = dict(effective.get("side_overrides") or {})
        side_a = dict(side_overrides.get("A") or {})
        side_b = dict(side_overrides.get("B") or {})

        window = tk.Toplevel(self)
        window.title("Compare Plot Elements")
        window.transient(self)
        window.resizable(False, False)
        self._compare_plot_elements_window = window

        body = ttk.Frame(window, padding=12)
        body.grid(row=0, column=0, sticky="nsew")
        body.grid_columnconfigure(1, weight=1)
        body.grid_columnconfigure(3, weight=1)

        ttk.Label(
            body,
            text=(
                "Configure pair-scoped fallback titles and profile plot-element "
                "retention for Compare side-by-side rendering."
            ),
            justify="left",
            anchor="w",
            wraplength=640,
        ).grid(row=0, column=0, columnspan=4, sticky="ew", pady=(0, 10))

        side_a_title_var = tk.StringVar(value=str(side_a.get("title_text") or ""))
        side_a_suptitle_var = tk.StringVar(value=str(side_a.get("suptitle_text") or ""))
        side_b_title_var = tk.StringVar(value=str(side_b.get("title_text") or ""))
        side_b_suptitle_var = tk.StringVar(value=str(side_b.get("suptitle_text") or ""))
        retain_var = tk.BooleanVar(
            value=bool(effective.get("retain_profile_elements", True))
        )
        hide_text_family_var = tk.BooleanVar(
            value=bool(effective.get("hide_text_family", False))
        )

        ttk.Label(body, text="Side A Title").grid(
            row=1, column=0, sticky="w", padx=(0, 6), pady=2
        )
        ttk.Entry(body, textvariable=side_a_title_var, width=48).grid(
            row=1, column=1, sticky="ew", pady=2, padx=(0, 12)
        )
        ttk.Label(body, text="Side B Title").grid(
            row=1, column=2, sticky="w", padx=(0, 6), pady=2
        )
        ttk.Entry(body, textvariable=side_b_title_var, width=48).grid(
            row=1, column=3, sticky="ew", pady=2
        )

        ttk.Label(body, text="Side A Suptitle").grid(
            row=2, column=0, sticky="w", padx=(0, 6), pady=2
        )
        ttk.Entry(body, textvariable=side_a_suptitle_var, width=48).grid(
            row=2, column=1, sticky="ew", pady=2, padx=(0, 12)
        )
        ttk.Label(body, text="Side B Suptitle").grid(
            row=2, column=2, sticky="w", padx=(0, 6), pady=2
        )
        ttk.Entry(body, textvariable=side_b_suptitle_var, width=48).grid(
            row=2, column=3, sticky="ew", pady=2
        )

        ttk.Checkbutton(
            body,
            text="Retain saved profile plot elements",
            variable=retain_var,
        ).grid(row=3, column=0, columnspan=4, sticky="w", pady=(8, 2))
        ttk.Checkbutton(
            body,
            text="Hide text-family elements (keep spans/masks)",
            variable=hide_text_family_var,
        ).grid(row=4, column=0, columnspan=4, sticky="w", pady=(0, 8))

        actions = ttk.Frame(body)
        actions.grid(row=5, column=0, columnspan=4, sticky="e")

        def _collect_payload() -> Dict[str, Any]:
            """Collect one normalized pair override payload from staged controls."""
            payload = {
                "retain_profile_elements": bool(retain_var.get()),
                "hide_text_family": bool(hide_text_family_var.get()),
                "side_overrides": {
                    "A": {
                        "title_text": str(side_a_title_var.get() or "").strip(),
                        "suptitle_text": str(side_a_suptitle_var.get() or "").strip(),
                    },
                    "B": {
                        "title_text": str(side_b_title_var.get() or "").strip(),
                        "suptitle_text": str(side_b_suptitle_var.get() or "").strip(),
                    },
                },
            }
            return _normalize_compare_plot_elements_pair_override(payload)

        def _apply(close_after: bool) -> None:
            """Apply staged pair override payload and optionally close the dialog."""
            self._compare_store_pair_plot_elements_override(
                _collect_payload(),
                persist_state=True,
            )
            self._compare_refresh_loaded_sides_async(
                reason="plot_elements",
                show_overlay=True,
                on_complete=self._compare_refresh_diagnostics_panel,
            )
            if close_after:
                _close_window()

        def _reset_to_loaded_profile() -> None:
            """Reset staged fields to loaded-profile defaults for this pair."""
            defaults = self._compare_default_pair_plot_elements_override()
            side_defaults = dict(defaults.get("side_overrides") or {})
            side_a_defaults = dict(side_defaults.get("A") or {})
            side_b_defaults = dict(side_defaults.get("B") or {})
            side_a_title_var.set(str(side_a_defaults.get("title_text") or ""))
            side_a_suptitle_var.set(str(side_a_defaults.get("suptitle_text") or ""))
            side_b_title_var.set(str(side_b_defaults.get("title_text") or ""))
            side_b_suptitle_var.set(str(side_b_defaults.get("suptitle_text") or ""))
            retain_var.set(bool(defaults.get("retain_profile_elements", True)))
            hide_text_family_var.set(bool(defaults.get("hide_text_family", False)))

        def _close_window() -> None:
            """Close the Compare Plot Elements dialog safely."""
            try:
                window.destroy()
            except Exception:
                pass
            self._compare_plot_elements_window = None

        self._compare_make_button(
            actions,
            text="Reset to Loaded Profile",
            command=_reset_to_loaded_profile,
            compact=True,
        ).pack(side="left", padx=(0, 8))
        self._compare_make_button(
            actions,
            text="Apply",
            command=lambda: _apply(False),
            compact=True,
        ).pack(side="left", padx=(0, 8))
        self._compare_make_button(
            actions,
            text="Apply + Close",
            command=lambda: _apply(True),
            compact=True,
        ).pack(side="left", padx=(0, 8))
        self._compare_make_button(
            actions,
            text="Close",
            command=_close_window,
            compact=True,
        ).pack(side="left")

        window.protocol("WM_DELETE_WINDOW", _close_window)

    def _compare_swap_profiles(self) -> None:
        """Swap Compare profile A/B selections and reload staged profile bundles.

        Purpose:
            Provide one-click reversal of left/right profile assignment.
        Why:
            Users often need to invert visual orientation without reselecting
            each profile manually.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Updates selector variables and reloads Compare-side profile bundles
            without triggering comparison rendering.
        Exceptions:
            None.
        """
        a_name = str(self.compare_profile_a_var.get() or "")
        b_name = str(self.compare_profile_b_var.get() or "")
        self.compare_profile_a_var.set(b_name)
        self.compare_profile_b_var.set(a_name)
        self._compare_load_selected_profiles()

    def _compare_parse_float_entry(self, raw_value: Any) -> Optional[float]:
        """Parse one optional non-negative float from Compare input text.

        Purpose:
            Normalize optional numeric Compare fields (mass/yield basis inputs).
        Why:
            Live calculations and persistence should reject invalid/negative
            values while preserving blank optional fields.
        Args:
            raw_value: Candidate text or numeric value from UI/settings.
        Returns:
            Parsed non-negative float, or None for blank/invalid input.
        Side Effects:
            None.
        Exceptions:
            Parsing failures return None.
        """
        if raw_value in (None, ""):
            return None
        try:
            candidate = float(raw_value)
        except Exception:
            return None
        if not math.isfinite(candidate) or candidate < 0.0:
            return None
        return float(candidate)

    def _compare_persist_state(self) -> None:
        """Persist Compare selector and yield-input state to settings.

        Purpose:
            Save current Compare form state for session restore.
        Why:
            Users should return to the same Compare selection and yield inputs on
            restart without manual re-entry.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Updates `settings["compare_tab"]` and schedules settings save.
        Exceptions:
            Save scheduling failures are ignored.
        """
        compare_state = _normalize_compare_tab_settings(settings.get("compare_tab"))
        self._persist_compare_split_from_widget(save=False)
        refreshed_state = _normalize_compare_tab_settings(settings.get("compare_tab"))
        split_frac_value = refreshed_state.get(
            "split_frac", compare_state.get("split_frac", DEFAULT_COMPARE_SPLIT_FRAC)
        )
        custom_presets = _normalize_compare_custom_plot_presets(
            getattr(self, "_compare_custom_plot_presets", compare_state.get("custom_plot_presets"))
        )
        preset_name = str(self.compare_plot_preset_var.get() or "").strip()
        builtins = _builtin_compare_plot_presets()
        if preset_name not in custom_presets and preset_name not in builtins:
            preset_name = (
                DEFAULT_COMPARE_PLOT_PRESET_NAME
                if DEFAULT_COMPARE_PLOT_PRESET_NAME in builtins
                else next(iter(builtins), DEFAULT_COMPARE_PLOT_PRESET_NAME)
            )
        preset_values = _resolve_compare_plot_preset_values(
            preset_name,
            custom_presets=custom_presets,
        )
        layout_overrides = _normalize_compare_layout_overrides(
            getattr(self, "_compare_layout_overrides", compare_state.get("layout_overrides"))
        )
        plot_editor_margins_by_pair = _normalize_compare_plot_editor_margins_by_pair(
            getattr(
                self,
                "_compare_plot_editor_margins_by_pair",
                compare_state.get("plot_editor_margins_by_pair"),
            )
        )
        side_plot_settings_overrides_by_pair = (
            _normalize_compare_side_plot_settings_overrides_by_pair(
                getattr(
                    self,
                    "_compare_side_plot_settings_overrides_by_pair",
                    compare_state.get("side_plot_settings_overrides_by_pair"),
                )
            )
        )
        side_layout_overrides_by_pair = (
            _normalize_compare_side_layout_overrides_by_pair(
                getattr(
                    self,
                    "_compare_side_layout_overrides_by_pair",
                    compare_state.get("side_layout_overrides_by_pair"),
                )
            )
        )
        marker_overrides = _normalize_compare_marker_overrides(
            getattr(self, "_compare_marker_overrides", compare_state.get("marker_overrides"))
        )
        plot_elements_overrides_by_pair = (
            _normalize_compare_plot_elements_overrides_by_pair(
                getattr(
                    self,
                    "_compare_plot_elements_overrides_by_pair",
                    compare_state.get("plot_elements_overrides_by_pair"),
                )
            )
        )
        report_preferences = _normalize_compare_report_preferences(
            getattr(self, "_compare_report_preferences", compare_state.get("report_preferences"))
        )
        cycle_table_view_mode = _normalize_compare_cycle_table_view_mode(
            getattr(self, "_compare_cycle_table_active_view_mode", "standard"),
            default="standard",
        )
        cycle_table_view_profiles = _normalize_compare_cycle_table_view_profiles(
            getattr(
                self,
                "_compare_cycle_table_view_profiles",
                compare_state.get("cycle_table_view_profiles"),
            )
        )
        self._compare_cycle_table_active_view_mode = cycle_table_view_mode
        self._compare_cycle_table_view_profiles = dict(cycle_table_view_profiles)
        self._compare_layout_overrides = dict(layout_overrides)
        self._compare_plot_editor_margins_by_pair = dict(plot_editor_margins_by_pair)
        self._compare_side_plot_settings_overrides_by_pair = dict(
            side_plot_settings_overrides_by_pair
        )
        self._compare_side_layout_overrides_by_pair = dict(side_layout_overrides_by_pair)
        self._compare_marker_overrides = dict(marker_overrides)
        self._compare_plot_elements_overrides_by_pair = dict(
            plot_elements_overrides_by_pair
        )
        self._compare_report_preferences = dict(report_preferences)
        self._compare_custom_plot_presets = dict(custom_presets)
        settings["compare_tab"] = _normalize_compare_tab_settings(
            {
                "profile_a_name": self.compare_profile_a_var.get(),
                "profile_b_name": self.compare_profile_b_var.get(),
                "isolated_mass_a_g": self._compare_parse_float_entry(
                    self.compare_isolated_mass_a_var.get()
                ),
                "isolated_mass_b_g": self._compare_parse_float_entry(
                    self.compare_isolated_mass_b_var.get()
                ),
                "yield_basis_mode": self.compare_yield_mode_var.get(),
                "yield_override": {
                    "starting_mass_g": self._compare_parse_float_entry(
                        self.compare_override_starting_mass_var.get()
                    ),
                    "starting_material_mw_g_mol": self._compare_parse_float_entry(
                        self.compare_override_mw_var.get()
                    ),
                    "stoich_mol_gas_per_mol_starting": self._compare_parse_float_entry(
                        self.compare_override_stoich_var.get()
                    ),
                    "gas_molar_mass": self._compare_parse_float_entry(
                        self.compare_override_gas_mw_var.get()
                    ),
                },
                "lock_x_axis": bool(self.compare_lock_x_axis_var.get()),
                "split_frac": split_frac_value,
                "use_profile_layout": bool(self.compare_use_profile_layout_var.get()),
                "show_main_legend": bool(self.compare_show_main_legend_var.get()),
                "show_cycle_legend": bool(self.compare_show_cycle_legend_var.get()),
                "plot_preset_name": preset_name,
                "plot_preset_values": preset_values,
                "custom_plot_presets": custom_presets,
                "layout_overrides": layout_overrides,
                "plot_editor_margins_by_pair": plot_editor_margins_by_pair,
                "side_plot_settings_overrides_by_pair": side_plot_settings_overrides_by_pair,
                "side_layout_overrides_by_pair": side_layout_overrides_by_pair,
                "marker_overrides": marker_overrides,
                "plot_elements_overrides_by_pair": plot_elements_overrides_by_pair,
                "report_preferences": report_preferences,
                "cycle_table_view_mode": cycle_table_view_mode,
                "cycle_table_view_profiles": cycle_table_view_profiles,
            }
        )
        try:
            self._schedule_save_settings()
        except Exception:
            pass

    def _compare_sync_plot_preset_choices(self) -> None:
        """Refresh compare preset combobox values from built-in and custom sets.

        Purpose:
            Keep compare preset selector choices synchronized with custom preset
            create/delete actions.
        Why:
            Preset management mutates available names at runtime and the combobox
            must reflect the updated source-of-truth list.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Updates the compare preset combobox `values` and local name cache.
        Exceptions:
            Missing combobox widget is ignored.
        """
        builtins = list(_builtin_compare_plot_presets().keys())
        custom_presets = _normalize_compare_custom_plot_presets(
            getattr(self, "_compare_custom_plot_presets", {})
        )
        custom_names = [name for name in sorted(custom_presets) if name not in builtins]
        choices = builtins + custom_names
        self._compare_plot_preset_names = choices
        combo = getattr(self, "_compare_plot_preset_combo", None)
        if combo is not None:
            try:
                combo.configure(values=choices)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

    def _compare_capture_current_plot_preset_values(self) -> Dict[str, Any]:
        """Capture one compare preset payload from current combined settings.

        Purpose:
            Build a custom compare preset from live combined spacing/font values.
        Why:
            Users can tune combined settings elsewhere, then save that visual
            result as a compare-tab preset for repeatable reuse.
        Args:
            None.
        Returns:
            Normalized compare preset payload dict.
        Side Effects:
            None.
        Exceptions:
            Missing keys fall back to compare default preset values.
        """
        payload: Dict[str, Any] = {}
        # Iterate over compare preset keys and capture matching live settings.
        for key in COMPARE_PLOT_PRESET_KEYS:
            payload[key] = copy.deepcopy(settings.get(key))
        return _normalize_compare_plot_preset_values(
            payload,
            fallback=_default_compare_plot_preset_values(),
        )

    def _compare_apply_plot_preset_selection(
        self,
        *,
        rerender_loaded: bool,
        persist_state: bool,
    ) -> None:
        """Apply selected compare preset and optionally rerender loaded panes.

        Purpose:
            Resolve the active compare preset and trigger any required redraws.
        Why:
            Compare readability controls must take effect immediately when users
            switch presets.
        Args:
            rerender_loaded: When True, rerender loaded compare panes.
            persist_state: When True, persist updated compare state to settings.
        Returns:
            None.
        Side Effects:
            May refresh combobox choices, rerender compare panes, and persist state.
        Exceptions:
            Invalid selections fall back to default preset safely.
        """
        custom_presets = _normalize_compare_custom_plot_presets(
            getattr(self, "_compare_custom_plot_presets", {})
        )
        self._compare_custom_plot_presets = dict(custom_presets)
        self._compare_sync_plot_preset_choices()
        builtins = _builtin_compare_plot_presets()
        preset_name = str(self.compare_plot_preset_var.get() or "").strip()
        if preset_name not in custom_presets and preset_name not in builtins:
            preset_name = (
                DEFAULT_COMPARE_PLOT_PRESET_NAME
                if DEFAULT_COMPARE_PLOT_PRESET_NAME in builtins
                else next(iter(builtins), DEFAULT_COMPARE_PLOT_PRESET_NAME)
            )
            self.compare_plot_preset_var.set(preset_name)
        if persist_state:
            self._compare_persist_state()
        if not rerender_loaded:
            self._compare_update_status_chips()
            return
        self._compare_refresh_loaded_sides_async(
            reason="preset",
            show_overlay=True,
            on_complete=self._compare_refresh_diagnostics_panel,
        )

    def _compare_save_plot_preset(self) -> None:
        """Save one custom compare preset from current combined settings.

        Purpose:
            Persist a named compare preset captured from live combined settings.
        Why:
            Users need reusable compare-visibility tuning beyond built-in presets.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Prompts for a preset name, writes custom preset state, and rerenders
            compare panes with the saved preset selected.
        Exceptions:
            Invalid/cancelled name input is ignored.
        """
        preset_name = simpledialog.askstring(
            "Save Compare Preset",
            "Preset name:",
            parent=self,
        )
        if preset_name is None:
            return
        preset_name = str(preset_name or "").strip()
        if not preset_name:
            try:
                messagebox.showerror("Save Compare Preset", "Preset name cannot be empty.")
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        builtins = _builtin_compare_plot_presets()
        if preset_name in builtins:
            try:
                messagebox.showerror(
                    "Save Compare Preset",
                    "Built-in preset names cannot be overwritten.",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        custom_presets = _normalize_compare_custom_plot_presets(
            getattr(self, "_compare_custom_plot_presets", {})
        )
        if (
            preset_name not in custom_presets
            and len(custom_presets) >= MAX_COMPARE_CUSTOM_PRESETS
        ):
            try:
                messagebox.showerror(
                    "Save Compare Preset",
                    f"Preset limit reached ({MAX_COMPARE_CUSTOM_PRESETS}). Delete one first.",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        custom_presets[preset_name] = self._compare_capture_current_plot_preset_values()
        self._compare_custom_plot_presets = custom_presets
        self._compare_sync_plot_preset_choices()
        self.compare_plot_preset_var.set(preset_name)
        self._compare_apply_plot_preset_selection(
            rerender_loaded=True,
            persist_state=True,
        )

    def _compare_delete_plot_preset(self) -> None:
        """Delete one selected custom compare preset.

        Purpose:
            Remove obsolete compare presets from persisted custom preset state.
        Why:
            Compare preset management requires in-tab cleanup controls.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Updates custom preset mapping, resets active preset if deleted, and
            rerenders loaded compare panes using the fallback preset.
        Exceptions:
            Built-in presets are protected from deletion.
        """
        preset_name = str(self.compare_plot_preset_var.get() or "").strip()
        if not preset_name:
            return
        builtins = _builtin_compare_plot_presets()
        if preset_name in builtins:
            try:
                messagebox.showinfo(
                    "Delete Compare Preset",
                    "Built-in presets cannot be deleted.",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        custom_presets = _normalize_compare_custom_plot_presets(
            getattr(self, "_compare_custom_plot_presets", {})
        )
        if preset_name not in custom_presets:
            return
        confirm = messagebox.askyesno(
            "Delete Compare Preset",
            f"Delete compare preset '{preset_name}'?",
        )
        if not confirm:
            return
        custom_presets.pop(preset_name, None)
        self._compare_custom_plot_presets = custom_presets
        self._compare_sync_plot_preset_choices()
        fallback_name = (
            DEFAULT_COMPARE_PLOT_PRESET_NAME
            if DEFAULT_COMPARE_PLOT_PRESET_NAME in builtins
            else next(iter(builtins), DEFAULT_COMPARE_PLOT_PRESET_NAME)
        )
        self.compare_plot_preset_var.set(fallback_name)
        self._compare_apply_plot_preset_selection(
            rerender_loaded=True,
            persist_state=True,
        )

    def _compare_apply_layout_mode_change(self) -> None:
        """Apply compare layout-mode toggle and rerender loaded panes.

        Purpose:
            React to compare layout-source toggle changes.
        Why:
            Switching between profile anchors and compare-normalized layout should
            be immediately visible in both compare panes.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Persists state and rerenders any loaded compare panes.
        Exceptions:
            Missing panes are ignored.
        """
        self._compare_persist_state()
        self._compare_refresh_loaded_sides_async(
            reason="layout_mode",
            show_overlay=True,
            on_complete=self._compare_refresh_diagnostics_panel,
        )

    def _compare_set_current_profile_for_side(self, side_key: str) -> None:
        """Assign the current workspace profile to one compare side and load.

        Purpose:
            Provide quick-load helpers that pull the active workspace profile into
            compare side A or B.
        Why:
            Compare setup is faster when users can reuse the current workspace
            profile without reselecting it manually.
        Args:
            side_key: Compare side key (`"A"` or `"B"`).
        Returns:
            None.
        Side Effects:
            Updates compare profile selector state and reloads staged compare
            profile bundles without triggering comparison rendering.
        Exceptions:
            Missing current workspace profile shows a user-facing info dialog.
        """
        if side_key not in {"A", "B"}:
            return
        profile_name, _profile_path = self._resolve_current_workspace_profile(
            normalize=True,
            persist=False,
        )
        if not profile_name:
            try:
                messagebox.showinfo(
                    "Compare Quick Load",
                    "No current workspace profile is set.",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        if side_key == "A":
            self.compare_profile_a_var.set(profile_name)
        else:
            self.compare_profile_b_var.set(profile_name)
        self._compare_load_selected_profiles()

    def _compare_collect_current_cycle_marker_payload(
        self,
        *,
        side_key: Optional[str] = None,
    ) -> Optional[Dict[str, Any]]:
        """Collect marker edits from one side-scoped Compare Cycle Analysis window.

        Purpose:
            Return the latest marker payload from side A/B compare marker editor.
        Why:
            Compare marker pull must read side-matched window state without using
            or replacing the main workspace Cycle Analysis session.
        Args:
            side_key: Compare side key (`"A"` or `"B"`).
        Returns:
            Normalized marker payload dict, or None when no side payload exists.
        Side Effects:
            None.
        Exceptions:
            Invalid or missing payloads return None.
        """
        side_token = str(side_key or "").strip().upper()
        if side_token not in {"A", "B"}:
            return None
        states = (
            getattr(self, "_compare_cycle_editor_states", {})
            if isinstance(getattr(self, "_compare_cycle_editor_states", {}), dict)
            else {}
        )
        state = states.get(side_token) if isinstance(states, Mapping) else None
        payload = state.get("payload") if isinstance(state, Mapping) else None
        normalized = _normalize_profile_cycle_markers(payload)
        return copy.deepcopy(normalized) if normalized is not None else None

    def _compare_save_marker_payload_to_profile(
        self,
        profile_name: str,
        marker_payload: Mapping[str, Any],
    ) -> bool:
        """Persist one cycle-marker payload into a saved profile document.

        Purpose:
            Save manual marker corrections for future Compare and profile loads.
        Why:
            Corrected peak/trough assignments should be reusable across sessions.
        Args:
            profile_name: Target profile name to update.
            marker_payload: Normalized marker payload to persist.
        Returns:
            True when profile write succeeds, otherwise False.
        Side Effects:
            Reads/writes one profile JSON document and updates in-memory compare
            bundles for matching profile names.
        Exceptions:
            Read/write failures return False.
        """
        safe_profile = str(profile_name or "").strip()
        normalized_payload = _normalize_profile_cycle_markers(marker_payload)
        if not safe_profile or normalized_payload is None:
            return False
        profile_path = self._profile_path(safe_profile)
        if profile_path is None or not profile_path.exists():
            return False
        profile_doc = self._read_profile_document(profile_path)
        if not isinstance(profile_doc, dict):
            return False
        payload = profile_doc.get("payload")
        if not isinstance(payload, dict):
            return False
        payload["cycle_markers"] = normalized_payload
        plot_settings = payload.get("plot_settings")
        if not isinstance(plot_settings, dict):
            plot_settings = {}
            payload["plot_settings"] = plot_settings
        plot_settings["cycle_manual_add_peaks"] = list(
            normalized_payload.get("add_peaks") or []
        )
        plot_settings["cycle_manual_add_troughs"] = list(
            normalized_payload.get("add_troughs") or []
        )
        plot_settings["cycle_manual_remove_peaks"] = list(
            normalized_payload.get("rm_peaks") or []
        )
        plot_settings["cycle_manual_remove_troughs"] = list(
            normalized_payload.get("rm_troughs") or []
        )
        plot_settings["cycle_auto_detect_enabled"] = bool(
            normalized_payload.get("auto_detect_enabled", True)
        )
        plot_settings["cycle_use_auto_markers_in_manual_edit_mode"] = bool(
            normalized_payload.get("use_auto_markers_in_manual_mode", True)
        )
        thresholds_payload = dict(normalized_payload.get("thresholds") or {})
        threshold_map = (
            ("min_cycle_drop", "min_cycle_drop"),
            ("pk_prominence", "peak_prominence"),
            ("pk_distance", "peak_distance"),
            ("pk_width", "peak_width"),
        )
        for source_key, target_key in threshold_map:
            value = thresholds_payload.get(source_key)
            if value in (None, ""):
                continue
            plot_settings[target_key] = value
        profile_doc["payload"] = payload
        profile_doc["updated_at"] = self._profile_timestamp()
        if not self._write_profile_document(profile_path, profile_doc):
            return False

        panels = getattr(self, "_compare_panels", {}) if isinstance(getattr(self, "_compare_panels", {}), dict) else {}
        for side_key in ("A", "B"):
            panel = panels.get(side_key) or {}
            bundle = panel.get("bundle")
            if not isinstance(bundle, dict):
                continue
            if str(bundle.get("profile_name") or "").strip() != safe_profile:
                continue
            bundle["cycle_markers"] = copy.deepcopy(normalized_payload)
            bundle_plot_settings = bundle.get("plot_settings")
            if isinstance(bundle_plot_settings, dict):
                bundle_plot_settings["cycle_auto_detect_enabled"] = bool(
                    normalized_payload.get("auto_detect_enabled", True)
                )
                bundle_plot_settings["cycle_use_auto_markers_in_manual_edit_mode"] = bool(
                    normalized_payload.get("use_auto_markers_in_manual_mode", True)
                )
        return True

    def _compare_open_profile_in_cycle_analysis(self, side_key: str) -> bool:
        """Open one side-scoped marker assignment Cycle Analysis window.

        Purpose:
            Launch/focus a dedicated side-specific cycle marker assignment window.
        Why:
            Compare marker editing must not replace the active workspace profile.
        Args:
            side_key: Compare side key (`"A"` or `"B"`).
        Returns:
            True when the side editor window is opened or focused.
        Side Effects:
            Creates/updates one side-scoped toplevel editor and caches marker
            payload state for `Pull Current Markers`.
        Exceptions:
            Missing side data returns False.
        """
        side_token = str(side_key or "").strip().upper()
        if side_token not in {"A", "B"}:
            return False
        panels = getattr(self, "_compare_panels", {})
        panel = (panels.get(side_token) or {}) if isinstance(panels, dict) else {}
        bundle = panel.get("bundle")
        if not isinstance(bundle, Mapping):
            return False
        profile_name = str(bundle.get("profile_name") or "").strip()
        if not profile_name:
            profile_var = (
                self.compare_profile_a_var
                if side_token == "A"
                else self.compare_profile_b_var
            )
            profile_name = str(profile_var.get() or "").strip()

        editor_states = (
            getattr(self, "_compare_cycle_editor_states", {})
            if isinstance(getattr(self, "_compare_cycle_editor_states", {}), dict)
            else {}
        )
        self._compare_cycle_editor_states = editor_states
        existing_state = editor_states.get(side_token) or {}
        existing_window = existing_state.get("window")
        if existing_window is not None and bool(
            getattr(existing_window, "winfo_exists", lambda: False)()
        ):
            try:
                existing_window.deiconify()
                existing_window.lift()
                existing_window.focus_force()
                return True
            except Exception:
                pass

        data_ctx = bundle.get("data_ctx")
        data_ctx = data_ctx if isinstance(data_ctx, Mapping) else {}
        series_np = data_ctx.get("series_np")
        series_np = series_np if isinstance(series_np, Mapping) else {}
        series_map = data_ctx.get("series")
        series_map = series_map if isinstance(series_map, Mapping) else {}
        x_source = series_np.get("x", series_map.get("x"))
        y_source = series_np.get("y1", series_map.get("y1"))
        if x_source is None or y_source is None:
            return False
        try:
            x_all = np.asarray(x_source, dtype=float).reshape(-1)
            y_all = np.asarray(y_source, dtype=float).reshape(-1)
        except Exception:
            return False
        data_len = int(min(x_all.size, y_all.size))
        if data_len <= 1:
            return False
        x_all = x_all[:data_len]
        y_all = y_all[:data_len]
        valid_mask = np.isfinite(x_all) & np.isfinite(y_all)
        if int(np.count_nonzero(valid_mask)) < 2:
            return False
        valid_indices = np.asarray(np.where(valid_mask)[0], dtype=int)

        plot_settings = bundle.get("plot_settings")
        plot_settings = plot_settings if isinstance(plot_settings, Mapping) else {}

        saved_payload = _normalize_profile_cycle_markers(existing_state.get("payload"))
        compare_override_payload = _normalize_profile_cycle_markers(
            (getattr(self, "_compare_marker_overrides", {}) or {}).get(side_token)
        )
        profile_payload = _normalize_profile_cycle_markers(bundle.get("cycle_markers"))
        marker_payload = saved_payload or compare_override_payload or profile_payload

        min_drop_default = float(
            plot_settings.get("min_cycle_drop", settings.get("min_cycle_drop", 0.0))
            or 0.0
        )
        prominence_default = float(
            plot_settings.get("peak_prominence", settings.get("peak_prominence", 1.0))
            or 1.0
        )
        distance_default = max(
            1,
            int(plot_settings.get("peak_distance", settings.get("peak_distance", 1)) or 1),
        )
        width_default = max(
            1,
            int(plot_settings.get("peak_width", settings.get("peak_width", 1)) or 1),
        )
        smoothing_default = _normalize_cycle_window(
            plot_settings.get(
                "peak_smoothing_window", settings.get("peak_smoothing_window", 1)
            )
        )
        manual_snap_default = _normalize_cycle_window(
            plot_settings.get(
                "cycle_manual_snap_radius",
                settings.get("cycle_manual_snap_radius", 0),
            ),
            allow_zero=True,
        )
        auto_refine_default = max(
            1,
            int(
                plot_settings.get(
                    "cycle_auto_refine_radius",
                    settings.get("cycle_auto_refine_radius", 6),
                )
                or 6
            ),
        )
        auto_default = bool(
            plot_settings.get(
                "cycle_auto_detect_enabled",
                settings.get("cycle_auto_detect_enabled", True),
            )
        )
        use_auto_markers_in_manual_mode_default = bool(
            plot_settings.get(
                "cycle_use_auto_markers_in_manual_edit_mode",
                settings.get("cycle_use_auto_markers_in_manual_edit_mode", True),
            )
        )
        manual_revision = 0
        add_peaks: Set[int] = set()
        add_troughs: Set[int] = set()
        rm_peaks: Set[int] = set()
        rm_troughs: Set[int] = set()
        if marker_payload is not None:
            auto_default = bool(marker_payload.get("auto_detect_enabled", auto_default))
            use_auto_markers_in_manual_mode_default = bool(
                marker_payload.get(
                    "use_auto_markers_in_manual_mode",
                    use_auto_markers_in_manual_mode_default,
                )
            )
            add_peaks = set(marker_payload.get("add_peaks") or [])
            add_troughs = set(marker_payload.get("add_troughs") or [])
            rm_peaks = set(marker_payload.get("rm_peaks") or [])
            rm_troughs = set(marker_payload.get("rm_troughs") or [])
            manual_revision = int(marker_payload.get("manual_revision") or 0)
            thresholds = dict(marker_payload.get("thresholds") or {})
            if thresholds.get("min_cycle_drop") is not None:
                min_drop_default = float(thresholds["min_cycle_drop"])
            if thresholds.get("pk_prominence") is not None:
                prominence_default = float(thresholds["pk_prominence"])
            if thresholds.get("pk_distance") is not None:
                distance_default = max(1, int(thresholds["pk_distance"]))
            if thresholds.get("pk_width") is not None:
                width_default = max(1, int(thresholds["pk_width"]))
            if thresholds.get("pk_smoothing_window") is not None:
                smoothing_default = _normalize_cycle_window(
                    thresholds["pk_smoothing_window"]
                )
            if thresholds.get("manual_snap_radius") is not None:
                manual_snap_default = _normalize_cycle_window(
                    thresholds["manual_snap_radius"], allow_zero=True
                )
            if thresholds.get("auto_refine_radius") is not None:
                auto_refine_default = max(
                    1, int(thresholds["auto_refine_radius"] or auto_refine_default)
                )

        base_snapshot = self._compare_cycle_snapshot_from_plot_settings(
            plot_settings,
            side_key=side_token,
            profile_cycle_markers=bundle.get("cycle_markers"),
        )
        base_snapshot["cycle_mask"] = np.ones(data_len, dtype=bool)
        fingerprint = DataFingerprint(
            file_path=str(bundle.get("dataset_path") or ""),
            sheet_key=tuple(bundle.get("sheet_key") or ()),
            columns_key=tuple(bundle.get("columns_key") or ()),
            cycle_temp_column=str(
                data_ctx.get("cycle_temp_column", CYCLE_TEMP_DEFAULT_LABEL)
                or CYCLE_TEMP_DEFAULT_LABEL
            ),
            elapsed_unit=str(self._elapsed_unit_label() or ""),
            multi_sheet=bool(bundle.get("multi_sheet", False)),
            prep_signature=tuple(bundle.get("prep_signature") or ()),
        )

        window = tk.Toplevel(self)
        window.title(f"Compare Cycle Analysis - Side {side_token}")
        window.transient(self)
        window.geometry("980x620")
        window.grid_rowconfigure(0, weight=1)
        window.grid_columnconfigure(1, weight=1)

        controls = ttk.Frame(window, padding=10)
        controls.grid(row=0, column=0, sticky="nsw")
        controls.grid_columnconfigure(0, weight=1)

        mode_var = tk.StringVar(value="add_peak")
        auto_detect_var = tk.BooleanVar(value=bool(auto_default))
        use_auto_markers_in_manual_mode_var = tk.BooleanVar(
            value=bool(use_auto_markers_in_manual_mode_default)
        )
        min_drop_var = tk.StringVar(value=f"{float(min_drop_default):.6g}")
        prominence_var = tk.StringVar(value=f"{float(prominence_default):.6g}")
        distance_var = tk.StringVar(value=str(int(distance_default)))
        width_var = tk.StringVar(value=str(int(width_default)))
        smoothing_var = tk.StringVar(value=str(int(smoothing_default)))
        manual_snap_var = tk.StringVar(value=str(int(manual_snap_default)))
        auto_refine_var = tk.StringVar(value=str(int(auto_refine_default)))
        status_var = tk.StringVar(value="")
        summary_var = tk.StringVar(value="")

        state: Dict[str, Any] = {
            "window": window,
            "profile_name": profile_name,
            "bundle": bundle,
            "payload": marker_payload,
            "add_peaks": set(int(v) for v in add_peaks),
            "add_troughs": set(int(v) for v in add_troughs),
            "rm_peaks": set(int(v) for v in rm_peaks),
            "rm_troughs": set(int(v) for v in rm_troughs),
            "manual_revision": int(max(0, manual_revision)),
            "use_auto_markers_in_manual_mode": bool(
                use_auto_markers_in_manual_mode_default
            ),
            "latest_overlay": {},
            "latest_cycle_rows": [],
            "series_gap_metrics": {},
            "preview": None,
        }

        ttk.Label(
            controls,
            text=(
                f"Profile: {profile_name or '--'}\n"
                f"Side: {side_token}\n\n"
                "Click the plot to assign markers using the selected mode."
            ),
            justify="left",
            anchor="w",
            wraplength=250,
        ).grid(row=0, column=0, sticky="ew", pady=(0, 8))

        mode_frame = ttk.LabelFrame(controls, text="Click Mode")
        mode_frame.grid(row=1, column=0, sticky="ew", pady=(0, 8))
        mode_options = (
            ("Add Peak", "add_peak"),
            ("Add Trough", "add_trough"),
            ("Remove Peak", "remove_peak"),
            ("Remove Trough", "remove_trough"),
        )
        for row_idx, (label, value) in enumerate(mode_options):
            ttk.Radiobutton(
                mode_frame,
                text=label,
                value=value,
                variable=mode_var,
            ).grid(row=row_idx, column=0, sticky="w", padx=6, pady=2)

        auto_detect_chk = ttk.Checkbutton(
            controls,
            text="Enable auto-detect",
            variable=auto_detect_var,
            command=lambda: (
                _refresh_side_editor_hybrid_visibility(),
                _render_overlay(),
            ),
        )
        auto_detect_chk.grid(row=2, column=0, sticky="w", pady=(0, 4))

        use_auto_markers_chk = ttk.Checkbutton(
            controls,
            text="Use automatic peak/troughs in manual edit mode",
            variable=use_auto_markers_in_manual_mode_var,
            command=lambda: _render_overlay(),
        )
        use_auto_markers_chk.grid(row=3, column=0, sticky="w", pady=(0, 8))

        threshold_frame = ttk.LabelFrame(controls, text="Thresholds")
        threshold_frame.grid(row=4, column=0, sticky="ew", pady=(0, 8))
        threshold_rows = (
            ("Min dP", min_drop_var),
            ("Prominence", prominence_var),
            ("Distance", distance_var),
            ("Width", width_var),
            ("Smoothing", smoothing_var),
            ("Manual Snap", manual_snap_var),
            ("Auto Refine", auto_refine_var),
        )
        for row_idx, (label, var_obj) in enumerate(threshold_rows):
            ttk.Label(threshold_frame, text=label).grid(
                row=row_idx, column=0, sticky="w", padx=(6, 6), pady=2
            )
            ttk.Entry(threshold_frame, textvariable=var_obj, width=12).grid(
                row=row_idx, column=1, sticky="w", padx=(0, 6), pady=2
            )

        ttk.Label(
            controls,
            textvariable=status_var,
            justify="left",
            anchor="w",
            wraplength=250,
        ).grid(row=5, column=0, sticky="ew", pady=(0, 6))
        ttk.Label(
            controls,
            textvariable=summary_var,
            justify="left",
            anchor="w",
            wraplength=250,
        ).grid(row=6, column=0, sticky="ew", pady=(0, 10))

        plot_shell = ttk.Frame(window, padding=(0, 10, 10, 10))
        plot_shell.grid(row=0, column=1, sticky="nsew")
        plot_shell.grid_rowconfigure(1, weight=1)
        plot_shell.grid_columnconfigure(0, weight=1)
        fig = Figure(figsize=(8.2, 5.6), dpi=100)
        ax = fig.add_subplot(111)
        canvas = FigureCanvasTkAgg(fig, master=plot_shell)
        toolbar = NavigationToolbar2Tk(canvas, plot_shell, pack_toolbar=False)
        toolbar.update()
        toolbar.grid(row=0, column=0, sticky="ew")
        self._apply_toolbar_scaling(toolbar)
        canvas_widget = canvas.get_tk_widget()
        canvas_widget.grid(row=1, column=0, sticky="nsew")

        action_row = ttk.Frame(controls)
        action_row.grid(row=7, column=0, sticky="ew")

        def _refresh_side_editor_hybrid_visibility() -> None:
            """Show or hide the side-editor hybrid toggle from auto-detect state.

            Purpose:
                Keep side-editor controls aligned with active marker-detection mode.
            Why:
                Hybrid manual-edit behavior only applies when auto-detection is enabled.
            Args:
                None.
            Returns:
                None.
            Side Effects:
                Grids or hides the `Use automatic peak/troughs in manual edit mode`
                checkbox in the side editor.
            Exceptions:
                UI lookup failures are handled with best-effort guards.
            """
            try:
                auto_enabled = bool(auto_detect_var.get())
            except Exception:
                auto_enabled = True
            try:
                if auto_enabled:
                    if not bool(use_auto_markers_chk.winfo_ismapped()):
                        use_auto_markers_chk.grid()
                else:
                    if bool(use_auto_markers_chk.winfo_ismapped()):
                        use_auto_markers_chk.grid_remove()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

        def _safe_float(var_obj: tk.StringVar, default_value: float) -> float:
            """Parse one float control value with safe fallback."""
            try:
                parsed = float(var_obj.get())
            except Exception:
                parsed = float(default_value)
            return float(parsed) if math.isfinite(parsed) else float(default_value)

        def _safe_int(var_obj: tk.StringVar, default_value: int) -> int:
            """Parse one positive integer control value with safe fallback."""
            try:
                parsed = int(float(var_obj.get()))
            except Exception:
                parsed = int(default_value)
            return max(1, int(parsed))

        def _safe_window(var_obj: tk.StringVar, default_value: int, *, allow_zero: bool = False) -> int:
            """Parse one cycle window control value with shared normalization rules.

            Purpose:
                Keep side-editor smoothing/snap/refine controls aligned with the
                main Cycle Analysis settings normalization behavior.
            Why:
                Compare-side manual corrections should use the same window policy
                as the primary Cycle Analysis workflow.
            Args:
                var_obj: Tk string variable backing the editor control.
                default_value: Fallback integer used when parsing fails.
                allow_zero: Preserve `0` when the control supports an auto mode.
            Returns:
                Sanitized integer window value.
            Side Effects:
                None.
            Exceptions:
                Invalid inputs fall back to `default_value`.
            """
            try:
                parsed = var_obj.get()
            except Exception:
                parsed = default_value
            return _normalize_cycle_window(parsed, allow_zero=allow_zero)

        def _current_snapshot() -> Dict[str, Any]:
            """Build a side-editor cycle snapshot for deterministic recompute calls.

            Purpose:
                Collect marker and threshold state for one compare-side recompute pass.
            Why:
                Compare side rendering must avoid reading stale/implicit state.
            Args:
                None.
            Returns:
                Snapshot dict compatible with `_resolve_cycle_context`.
            Side Effects:
                None.
            Exceptions:
                Invalid control values are sanitized by helper coercion functions.
            """
            snapshot = dict(base_snapshot)
            snapshot["auto_enabled"] = bool(auto_detect_var.get())
            snapshot["use_auto_markers_in_manual_mode"] = bool(
                use_auto_markers_in_manual_mode_var.get()
            )
            snapshot["min_cycle_drop"] = _safe_float(min_drop_var, min_drop_default)
            snapshot["prominence"] = _safe_float(prominence_var, prominence_default)
            snapshot["distance"] = _safe_int(distance_var, distance_default)
            snapshot["width"] = _safe_int(width_var, width_default)
            snapshot["smoothing_window"] = _safe_window(
                smoothing_var, smoothing_default
            )
            snapshot["manual_snap_radius"] = _safe_window(
                manual_snap_var, manual_snap_default, allow_zero=True
            )
            snapshot["auto_refine_radius"] = max(
                1, _safe_window(auto_refine_var, auto_refine_default)
            )
            snapshot["add_peaks"] = set(state.get("add_peaks") or set())
            snapshot["add_troughs"] = set(state.get("add_troughs") or set())
            snapshot["rm_peaks"] = set(state.get("rm_peaks") or set())
            snapshot["rm_troughs"] = set(state.get("rm_troughs") or set())
            snapshot["manual_revision"] = int(max(0, state.get("manual_revision") or 0))
            snapshot["cycle_mask"] = np.ones(data_len, dtype=bool)
            return snapshot

        def _build_payload() -> Optional[Dict[str, Any]]:
            """Create normalized side-editor marker payload from current controls.

            Purpose:
                Serialize side-editor marker edits and threshold settings.
            Why:
                Compare override application and profile saves rely on one
                normalized payload contract.
            Args:
                None.
            Returns:
                Normalized payload dict, or None when payload is effectively empty.
            Side Effects:
                None.
            Exceptions:
                Invalid values are normalized through `_normalize_profile_cycle_markers`.
            """
            payload = {
                "schema_version": 1,
                "auto_detect_enabled": bool(auto_detect_var.get()),
                "use_auto_markers_in_manual_mode": bool(
                    use_auto_markers_in_manual_mode_var.get()
                ),
                "manual_revision": int(max(0, state.get("manual_revision") or 0)),
                "add_peaks": sorted(int(v) for v in (state.get("add_peaks") or set())),
                "add_troughs": sorted(
                    int(v) for v in (state.get("add_troughs") or set())
                ),
                "rm_peaks": sorted(int(v) for v in (state.get("rm_peaks") or set())),
                "rm_troughs": sorted(int(v) for v in (state.get("rm_troughs") or set())),
                "thresholds": {
                    "min_cycle_drop": _safe_float(min_drop_var, min_drop_default),
                    "pk_prominence": _safe_float(prominence_var, prominence_default),
                    "pk_distance": _safe_int(distance_var, distance_default),
                    "pk_width": _safe_int(width_var, width_default),
                    "pk_smoothing_window": _safe_window(
                        smoothing_var, smoothing_default
                    ),
                    "manual_snap_radius": _safe_window(
                        manual_snap_var, manual_snap_default, allow_zero=True
                    ),
                    "auto_refine_radius": max(
                        1, _safe_window(auto_refine_var, auto_refine_default)
                    ),
                },
                "source_profile_name": profile_name,
                "updated_at": datetime.now().isoformat(timespec="seconds"),
            }
            return _normalize_profile_cycle_markers(payload)

        def _update_summary_from_overlay(overlay: Mapping[str, Any]) -> None:
            """Update side editor summary text from current overlay payload.

            Purpose:
                Render compare-side cycle counts and uptake totals for the editor.
            Why:
                Marker edits can create large cycle counts, so the summary uses the
                same comma-grouped display policy as cycle legends.
            Args:
                overlay: Current cycle overlay payload for one Compare side.
            Returns:
                None.
            Side Effects:
                Mutates the side editor summary `StringVar`.
            Exceptions:
                Invalid numeric values are shown as placeholder text.
            """
            cycles = list(overlay.get("cycles") or [])
            total_drop = self._compare_parse_float_entry(overlay.get("total_drop"))
            total_drop_text = (
                "--"
                if total_drop is None
                else f"{_format_cycle_legend_number(total_drop, 2)} PSI"
            )
            peaks_count = len(list(overlay.get("peaks_idx") or []))
            troughs_count = len(list(overlay.get("troughs_idx") or []))
            auto_peaks_count = len(list(overlay.get("auto_peaks") or []))
            auto_troughs_count = len(list(overlay.get("auto_troughs") or []))
            add_peak_count = len(list((state.get("add_peaks") or set())))
            add_trough_count = len(list((state.get("add_troughs") or set())))
            rm_peak_count = len(list((state.get("rm_peaks") or set())))
            rm_trough_count = len(list((state.get("rm_troughs") or set())))
            summary_var.set(
                f"Cycles: {_format_cycle_legend_count(len(cycles))}\n"
                f"Peaks: {_format_cycle_legend_count(peaks_count)}  |  "
                f"Troughs: {_format_cycle_legend_count(troughs_count)}\n"
                f"Auto P/T: {_format_cycle_legend_count(auto_peaks_count)}/"
                f"{_format_cycle_legend_count(auto_troughs_count)}  |  "
                f"Add P/T: {_format_cycle_legend_count(add_peak_count)}/"
                f"{_format_cycle_legend_count(add_trough_count)}\n"
                f"Remove P/T: {_format_cycle_legend_count(rm_peak_count)}/"
                f"{_format_cycle_legend_count(rm_trough_count)}\n"
                f"Total dP: {total_drop_text}"
            )

        def _render_overlay() -> None:
            """Recompute and draw cycle overlay for current side editor settings.

            Purpose:
                Refresh one side-specific marker-assignment plot and summary state.
            Why:
                Compare-side marker editing needs deterministic visual feedback that
                preserves data discontinuities for stitched/gapped profiles.
            Args:
                None.
            Returns:
                None.
            Side Effects:
                Updates side editor cache state, redraws plot artists, and emits
                cycle-editor diagnostics for collaborative debugging.
            Exceptions:
                Cycle-context resolution failures are converted into status text.
            """
            try:
                _cycle_ctx, overlay_ctx = self._resolve_cycle_context(
                    data_ctx,
                    fingerprint,
                    perf=None,
                    snapshot=_current_snapshot(),
                )
            except Exception as exc:
                status_var.set(f"Cycle recompute failed: {type(exc).__name__}")
                return
            cycle_overlay = (
                overlay_ctx.get("cycle_overlay")
                if isinstance(overlay_ctx, Mapping)
                else None
            )
            cycle_overlay = cycle_overlay if isinstance(cycle_overlay, Mapping) else {}
            cycle_rows, _synth = self._compare_extract_cycle_rows_from_overlay(
                cycle_overlay,
                data_ctx=data_ctx,
            )
            state["latest_overlay"] = dict(cycle_overlay)
            state["latest_cycle_rows"] = list(cycle_rows or [])
            state["use_auto_markers_in_manual_mode"] = bool(
                use_auto_markers_in_manual_mode_var.get()
            )
            normalized_payload = _build_payload()
            state["payload"] = normalized_payload
            editor_states[side_token] = state
            self._compare_cycle_editor_states = editor_states

            ax.clear()
            x_plot = np.asarray(x_all, dtype=float)
            y_plot = np.asarray(y_all, dtype=float)
            non_finite = ~(np.isfinite(x_plot) & np.isfinite(y_plot))
            if int(np.count_nonzero(non_finite)) > 0:
                # Preserve explicit trace breaks by keeping separator rows as NaN.
                x_plot[non_finite] = np.nan
                y_plot[non_finite] = np.nan
            ax.plot(
                x_plot,
                y_plot,
                color="#1565c0",
                linewidth=1.2,
                label="Pressure (PSI)",
            )
            peak_points = list(cycle_overlay.get("peak_points") or [])
            trough_points = list(cycle_overlay.get("trough_points") or [])
            if peak_points:
                px = np.asarray([float(p[0]) for p in peak_points], dtype=float)
                py = np.asarray([float(p[1]) for p in peak_points], dtype=float)
                finite = np.isfinite(px) & np.isfinite(py)
                ax.scatter(
                    px[finite],
                    py[finite],
                    marker="^",
                    s=28,
                    color="#2e7d32",
                    label="Peak",
                    zorder=4,
                )
            if trough_points:
                tx = np.asarray([float(p[0]) for p in trough_points], dtype=float)
                ty = np.asarray([float(p[1]) for p in trough_points], dtype=float)
                finite = np.isfinite(tx) & np.isfinite(ty)
                ax.scatter(
                    tx[finite],
                    ty[finite],
                    marker="v",
                    s=28,
                    color="#1565c0",
                    label="Trough",
                    zorder=4,
                )
            x_label = str((data_ctx.get("selected_columns") or {}).get("x") or "Elapsed Time")
            ax.set_xlabel(x_label.replace("_", " "))
            ax.set_ylabel("Pressure (PSI)")
            ax.set_title(f"Compare Side {side_token} Marker Assignment")
            ax.grid(True, alpha=0.25, linewidth=0.5)
            preview_payload = state.get("preview")
            if isinstance(preview_payload, Mapping):
                preview_x = self._compare_parse_float_entry(preview_payload.get("x"))
                preview_y = self._compare_parse_float_entry(preview_payload.get("y"))
                preview_mode = str(preview_payload.get("mode") or "")
                if preview_x is not None and preview_y is not None:
                    ax.scatter(
                        [preview_x],
                        [preview_y],
                        marker="^" if preview_mode == "add_peak" else "v",
                        s=84,
                        facecolors="none",
                        edgecolors="#f57c00",
                        linewidths=1.4,
                        label="Preview",
                        zorder=5,
                    )
            try:
                ax.legend(loc="upper right", **_legend_shadowbox_kwargs())
            except Exception:
                pass
            canvas.draw_idle()
            gap_metrics = self._compare_series_gap_metrics(x_all, y_all)
            state["series_gap_metrics"] = dict(gap_metrics)
            _update_summary_from_overlay(cycle_overlay)
            status_var.set(
                f"Mode: {str(mode_var.get() or '').replace('_', ' ').title()}  |  "
                f"Manual revision: {int(state.get('manual_revision') or 0)}  |  "
                f"Hybrid: {'On' if bool(use_auto_markers_in_manual_mode_var.get()) else 'Off'}  |  "
                f"Auto P/T: {len(list(cycle_overlay.get('auto_peaks') or []))}/"
                f"{len(list(cycle_overlay.get('auto_troughs') or []))}"
            )
            self._compare_log_cycle_editor_event(
                side_key=side_token,
                event_name="recompute",
                payload={
                    "cycles": len(list(cycle_overlay.get("cycles") or [])),
                    "peaks": len(list(cycle_overlay.get("peaks_idx") or [])),
                    "troughs": len(list(cycle_overlay.get("troughs_idx") or [])),
                    "manual_revision": int(state.get("manual_revision") or 0),
                    "use_auto_markers_in_manual_mode": bool(
                        use_auto_markers_in_manual_mode_var.get()
                    ),
                    "series_gaps": gap_metrics,
                },
            )

        def _resolve_side_marker_candidate(
            x_value: float, y_value: Optional[float], mode_value: str
        ) -> Optional[Dict[str, Any]]:
            """Resolve one side-editor marker candidate using the shared snap policy.

            Purpose:
                Keep compare-side add/remove marker workflows aligned with the main
                Cycle Analysis snapping implementation.
            Why:
                Sharp extrema should resolve to the same peak/trough regardless of
                which editor window the user clicked in.
            Args:
                x_value: Cursor x-coordinate in data units.
                y_value: Optional cursor y-coordinate in data units.
                mode_value: Active side-editor mode token.
            Returns:
                Snapped candidate payload, or None when no valid candidate exists.
            Side Effects:
                None.
            Exceptions:
                Invalid coordinates or unsupported modes return None.
            """
            if not math.isfinite(x_value):
                return None
            prefer_peak = mode_value in {"add_peak", "remove_peak"}
            if mode_value not in {
                "add_peak",
                "add_trough",
                "remove_peak",
                "remove_trough",
            }:
                return None
            return _resolve_cycle_manual_candidate(
                x_all,
                y_all,
                valid_mask,
                x_target=float(x_value),
                y_target=y_value,
                prefer_peak=prefer_peak,
                snap_radius=_safe_window(
                    manual_snap_var, manual_snap_default, allow_zero=True
                ),
                smoothing_window=_safe_window(smoothing_var, smoothing_default),
            )

        def _update_side_preview(event: Any) -> None:
            """Refresh the side-editor hover preview marker for add modes only.

            Purpose:
                Show the snapped peak/trough candidate before a manual edit commits.
            Why:
                Preview feedback makes auto-then-tweak workflows faster and reduces
                accidental marker placement on steep flanks.
            Args:
                event: Matplotlib motion event from the side-editor canvas.
            Returns:
                None.
            Side Effects:
                Updates `state["preview"]` and schedules one canvas redraw.
            Exceptions:
                Invalid or out-of-axes events clear the preview silently.
            """
            mode_value = str(mode_var.get() or "").strip().lower()
            if (
                event is None
                or event.inaxes is not ax
                or event.xdata is None
                or mode_value not in {"add_peak", "add_trough"}
            ):
                if state.get("preview") is not None:
                    state["preview"] = None
                    canvas.draw_idle()
                return
            candidate = _resolve_side_marker_candidate(
                float(event.xdata), getattr(event, "ydata", None), mode_value
            )
            if candidate is None:
                if state.get("preview") is not None:
                    state["preview"] = None
                    canvas.draw_idle()
                return
            candidate["mode"] = mode_value
            previous = state.get("preview")
            if previous == candidate:
                return
            state["preview"] = dict(candidate)
            canvas.draw_idle()

        def _on_click(event: Any) -> None:
            """Handle mouse clicks for side-specific marker assignment edits."""
            if event is None or event.inaxes is not ax:
                return
            if event.xdata is None:
                return
            mode_value = str(mode_var.get() or "").strip().lower()
            candidate = _resolve_side_marker_candidate(
                float(event.xdata), getattr(event, "ydata", None), mode_value
            )
            if candidate is None:
                return
            nearest_idx = int(candidate.get("index", -1))
            if nearest_idx < 0:
                return
            if mode_value == "add_peak":
                state["add_peaks"].add(int(nearest_idx))
                state["rm_peaks"].discard(int(nearest_idx))
            elif mode_value == "add_trough":
                state["add_troughs"].add(int(nearest_idx))
                state["rm_troughs"].discard(int(nearest_idx))
            elif mode_value == "remove_peak":
                state["rm_peaks"].add(int(nearest_idx))
                state["add_peaks"].discard(int(nearest_idx))
            elif mode_value == "remove_trough":
                state["rm_troughs"].add(int(nearest_idx))
                state["add_troughs"].discard(int(nearest_idx))
            else:
                return
            state["manual_revision"] = int(max(0, state.get("manual_revision") or 0)) + 1
            state["preview"] = dict(candidate)
            _render_overlay()

        def _reset_to_starting_payload() -> None:
            """Reset side-editor marker state back to initial payload values.

            Purpose:
                Restore the side editor to its opening marker/threshold baseline.
            Why:
                Users need a deterministic escape hatch after iterative edits.
            Args:
                None.
            Returns:
                None.
            Side Effects:
                Rewrites marker sets, threshold controls, and mode toggles before
                triggering one overlay refresh.
            Exceptions:
                Invalid payload fields fall back to profile/setting defaults.
            """
            base_payload = _normalize_profile_cycle_markers(marker_payload)
            state["add_peaks"] = set(base_payload.get("add_peaks") or []) if base_payload else set()
            state["add_troughs"] = set(base_payload.get("add_troughs") or []) if base_payload else set()
            state["rm_peaks"] = set(base_payload.get("rm_peaks") or []) if base_payload else set()
            state["rm_troughs"] = set(base_payload.get("rm_troughs") or []) if base_payload else set()
            state["manual_revision"] = int(base_payload.get("manual_revision") or 0) if base_payload else 0
            if base_payload is not None:
                thresholds_payload = dict(base_payload.get("thresholds") or {})
                if thresholds_payload.get("min_cycle_drop") is not None:
                    min_drop_var.set(f"{float(thresholds_payload.get('min_cycle_drop')):.6g}")
                else:
                    min_drop_var.set(f"{float(min_drop_default):.6g}")
                if thresholds_payload.get("pk_prominence") is not None:
                    prominence_var.set(
                        f"{float(thresholds_payload.get('pk_prominence')):.6g}"
                    )
                else:
                    prominence_var.set(f"{float(prominence_default):.6g}")
                if thresholds_payload.get("pk_distance") is not None:
                    distance_var.set(str(max(1, int(thresholds_payload.get("pk_distance")))))
                else:
                    distance_var.set(str(int(distance_default)))
                if thresholds_payload.get("pk_width") is not None:
                    width_var.set(str(max(1, int(thresholds_payload.get("pk_width")))))
                else:
                    width_var.set(str(int(width_default)))
                if thresholds_payload.get("pk_smoothing_window") is not None:
                    smoothing_var.set(
                        str(
                            _normalize_cycle_window(
                                thresholds_payload.get("pk_smoothing_window")
                            )
                        )
                    )
                else:
                    smoothing_var.set(str(int(smoothing_default)))
                if thresholds_payload.get("manual_snap_radius") is not None:
                    manual_snap_var.set(
                        str(
                            _normalize_cycle_window(
                                thresholds_payload.get("manual_snap_radius"),
                                allow_zero=True,
                            )
                        )
                    )
                else:
                    manual_snap_var.set(str(int(manual_snap_default)))
                if thresholds_payload.get("auto_refine_radius") is not None:
                    auto_refine_var.set(
                        str(max(1, int(thresholds_payload.get("auto_refine_radius"))))
                    )
                else:
                    auto_refine_var.set(str(int(auto_refine_default)))
                auto_detect_var.set(bool(base_payload.get("auto_detect_enabled", auto_default)))
                use_auto_markers_in_manual_mode_var.set(
                    bool(
                        base_payload.get(
                            "use_auto_markers_in_manual_mode",
                            use_auto_markers_in_manual_mode_default,
                        )
                    )
                )
            else:
                min_drop_var.set(f"{float(min_drop_default):.6g}")
                prominence_var.set(f"{float(prominence_default):.6g}")
                distance_var.set(str(int(distance_default)))
                width_var.set(str(int(width_default)))
                smoothing_var.set(str(int(smoothing_default)))
                manual_snap_var.set(str(int(manual_snap_default)))
                auto_refine_var.set(str(int(auto_refine_default)))
                auto_detect_var.set(bool(auto_default))
                use_auto_markers_in_manual_mode_var.set(
                    bool(use_auto_markers_in_manual_mode_default)
                )
            _refresh_side_editor_hybrid_visibility()
            _render_overlay()

        def _close_window() -> None:
            """Close side editor window while retaining last payload state."""
            state["window"] = None
            editor_states[side_token] = state
            self._compare_cycle_editor_states = editor_states
            try:
                window.destroy()
            except Exception:
                pass

        self._compare_make_button(
            action_row,
            text="Recompute",
            command=_render_overlay,
            compact=True,
        ).pack(side="left", padx=(0, 6))
        self._compare_make_button(
            action_row,
            text="Reset",
            command=_reset_to_starting_payload,
            compact=True,
        ).pack(side="left", padx=(0, 6))
        self._compare_make_button(
            action_row,
            text="Close",
            command=_close_window,
            compact=True,
        ).pack(side="left")

        try:
            canvas.mpl_connect("button_press_event", _on_click)
            canvas.mpl_connect("motion_notify_event", _update_side_preview)
        except Exception:
            pass
        window.protocol("WM_DELETE_WINDOW", _close_window)
        editor_states[side_token] = state
        self._compare_cycle_editor_states = editor_states
        _refresh_side_editor_hybrid_visibility()
        _render_overlay()
        self._compare_log_cycle_editor_event(
            side_key=side_token,
            event_name="editor_window_ready",
            payload={"profile_name": profile_name},
        )
        return True

    def _open_compare_marker_editor(self, side_key: str) -> None:
        """Open Compare-side marker correction popup for one profile side.

        Purpose:
            Provide fast marker-correction workflows from Compare side A/B.
        Why:
            One profile can require manual peak/trough correction before accurate
            uptake comparison; this popup links Cycle Analysis and Compare apply.
        Args:
            side_key: Compare side key (`"A"` or `"B"`).
        Returns:
            None.
        Side Effects:
            Opens modal popup, launches/focuses side-scoped marker editor windows,
            updates compare marker overrides, and can persist marker payloads to
            profiles.
        Exceptions:
            Invalid side keys or missing profile selections show user feedback.
        """
        if side_key not in {"A", "B"}:
            return
        profile_name = str(
            (self.compare_profile_a_var if side_key == "A" else self.compare_profile_b_var).get()
            or ""
        ).strip()
        if not profile_name:
            try:
                messagebox.showinfo(
                    "Compare Marker Editor",
                    f"Select a profile for side {side_key} first.",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return

        dialog = tk.Toplevel(self)
        dialog.title(f"Compare Marker Editor - Side {side_key}")
        dialog.transient(self)
        dialog.resizable(False, False)
        dialog.grid_columnconfigure(0, weight=1)

        staged_payload: Dict[str, Optional[Dict[str, Any]]] = {
            "value": _normalize_profile_cycle_markers(
                (getattr(self, "_compare_marker_overrides", {}) or {}).get(side_key)
            )
        }
        status_var = tk.StringVar(value="")
        summary_var = tk.StringVar(value="")
        save_profile_var = tk.BooleanVar(value=False)

        def _format_payload_summary(payload: Optional[Mapping[str, Any]]) -> str:
            """Build one compact marker payload summary string for popup display."""
            normalized = _normalize_profile_cycle_markers(payload)
            if normalized is None:
                return "Source: none (profile auto-detect only)"
            thresholds_payload = dict(normalized.get("thresholds") or {})
            return (
                f"Source: compare override\n"
                f"Add peaks: {len(normalized.get('add_peaks') or [])}  |  "
                f"Add troughs: {len(normalized.get('add_troughs') or [])}\n"
                f"Remove peaks: {len(normalized.get('rm_peaks') or [])}  |  "
                f"Remove troughs: {len(normalized.get('rm_troughs') or [])}\n"
                f"Auto-detect: {'On' if normalized.get('auto_detect_enabled', True) else 'Off'}  |  "
                f"Hybrid manual mode: {'On' if normalized.get('use_auto_markers_in_manual_mode', True) else 'Off'}  |  "
                f"min_drop: {thresholds_payload.get('min_cycle_drop', '--')}"
            )

        def _refresh_summary() -> None:
            """Refresh staged marker summary and profile status text."""
            summary_var.set(_format_payload_summary(staged_payload.get("value")))
            status_var.set(
                f"Target profile: {profile_name}  |  Side: {side_key}"
            )

        def _pull_from_cycle_analysis() -> None:
            """Pull side-editor marker edits into staged Compare override payload.

            Purpose:
                Import the latest marker payload from the side-specific cycle editor.
            Why:
                Compare marker correction must consume side-matched edits without
                relying on the main workspace Cycle Analysis state.
            Args:
                None.
            Returns:
                None.
            Side Effects:
                Updates staged override payload, refreshes popup summary text, and
                emits one cycle-editor diagnostics event.
            Exceptions:
                Missing side window/editor payload updates status text and exits.
            """
            current_payload = self._compare_collect_current_cycle_marker_payload(
                side_key=side_key
            )
            if current_payload is None:
                status_var.set(
                    "No side-matched Cycle Analysis window state found. Open Side "
                    f"{side_key} first, edit markers, then pull."
                )
                self._compare_log_cycle_editor_event(
                    side_key=side_key,
                    event_name="pull_missing_editor_state",
                    payload={"profile_name": profile_name},
                )
                return
            staged_payload["value"] = current_payload
            _refresh_summary()
            status_var.set("Pulled markers from side-specific Cycle Analysis window.")
            self._compare_log_cycle_editor_event(
                side_key=side_key,
                event_name="pull_markers",
                payload={
                    "profile_name": profile_name,
                    "manual_revision": int(current_payload.get("manual_revision") or 0),
                    "add_peaks": len(list(current_payload.get("add_peaks") or [])),
                    "add_troughs": len(list(current_payload.get("add_troughs") or [])),
                    "rm_peaks": len(list(current_payload.get("rm_peaks") or [])),
                    "rm_troughs": len(list(current_payload.get("rm_troughs") or [])),
                },
            )

        def _open_cycle_analysis() -> None:
            """Open/focus the side-specific cycle editor window for marker reassignment.

            Purpose:
                Launch the side-targeted Cycle Analysis editor from marker popup flow.
            Why:
                Compare marker correction requires isolated side editing so the
                workspace profile context is not replaced.
            Args:
                None.
            Returns:
                None.
            Side Effects:
                Opens/focuses side editor window, updates popup status text, and
                emits one cycle-editor diagnostics event.
            Exceptions:
                Window launch failures update status text and continue safely.
            """
            opened = self._compare_open_profile_in_cycle_analysis(side_key)
            if opened:
                status_var.set(
                    f"Opened side {side_key} Cycle Analysis window for '{profile_name}'. "
                    "Reassign markers, then pull."
                )
                self._compare_log_cycle_editor_event(
                    side_key=side_key,
                    event_name="open_side_editor",
                    payload={"profile_name": profile_name, "opened": True},
                )
            else:
                status_var.set("Could not open profile in Cycle Analysis.")
                self._compare_log_cycle_editor_event(
                    side_key=side_key,
                    event_name="open_side_editor",
                    payload={"profile_name": profile_name, "opened": False},
                )

        def _apply_to_compare(save_to_profile: bool, close_after: bool) -> None:
            """Apply staged marker payload to Compare and optionally persist to profile.

            Purpose:
                Commit staged marker overrides to the selected Compare side.
            Why:
                Marker correction workflows require explicit apply semantics with
                optional profile persistence for reuse.
            Args:
                save_to_profile: True to persist payload into the profile JSON.
                close_after: True to close popup after apply.
            Returns:
                None.
            Side Effects:
                Updates compare override state, optionally writes profile data,
                schedules Compare rerender, and emits cycle-editor diagnostics.
            Exceptions:
                Profile save failures are surfaced through status text.
            """
            normalized = _normalize_profile_cycle_markers(staged_payload.get("value"))
            marker_overrides = _normalize_compare_marker_overrides(
                getattr(self, "_compare_marker_overrides", {})
            )
            marker_overrides[side_key] = normalized
            self._compare_marker_overrides = dict(marker_overrides)
            save_requested = bool(save_to_profile or save_profile_var.get())
            if save_requested and normalized is not None:
                saved = self._compare_save_marker_payload_to_profile(
                    profile_name, normalized
                )
                if not saved:
                    status_var.set("Apply succeeded, but profile save failed.")
                else:
                    status_var.set("Applied marker override and saved to profile.")
            else:
                status_var.set("Applied marker override to Compare.")
            self._compare_persist_state()
            self._compare_refresh_loaded_sides_async(
                reason="marker_override",
                show_overlay=True,
                on_complete=self._compare_refresh_diagnostics_panel,
            )
            self._compare_log_cycle_editor_event(
                side_key=side_key,
                event_name="apply_override",
                payload={
                    "profile_name": profile_name,
                    "saved_to_profile": bool(save_requested and normalized is not None),
                    "override_present": bool(normalized is not None),
                    "manual_revision": int((normalized or {}).get("manual_revision") or 0),
                    "use_auto_markers_in_manual_mode": bool(
                        (normalized or {}).get("use_auto_markers_in_manual_mode", True)
                    ),
                    "close_after": bool(close_after),
                },
            )
            if close_after:
                try:
                    dialog.destroy()
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass

        ttk.Label(
            dialog,
            text=(
                "Use Cycle Analysis to reassign peak/trough markers, then pull and apply "
                "the corrected marker set to this Compare side."
            ),
            justify="left",
            anchor="w",
            wraplength=520,
        ).grid(row=0, column=0, sticky="ew", padx=10, pady=(10, 6))
        ttk.Label(
            dialog,
            textvariable=status_var,
            justify="left",
            anchor="w",
        ).grid(row=1, column=0, sticky="ew", padx=10, pady=(0, 4))
        ttk.Label(
            dialog,
            textvariable=summary_var,
            justify="left",
            anchor="w",
            wraplength=520,
        ).grid(row=2, column=0, sticky="ew", padx=10, pady=(0, 8))

        actions = ttk.Frame(dialog)
        actions.grid(row=3, column=0, sticky="ew", padx=10, pady=(0, 8))
        self._compare_make_button(
            actions,
            text="Open In Cycle Analysis",
            command=_open_cycle_analysis,
            compact=True,
        ).pack(side="left")
        self._compare_make_button(
            actions,
            text="Pull Current Markers",
            command=_pull_from_cycle_analysis,
            compact=True,
        ).pack(side="left", padx=(6, 0))
        self._compare_make_button(
            actions,
            text="Reset Override",
            command=lambda: (
                staged_payload.__setitem__("value", None),
                _refresh_summary(),
            ),
            compact=True,
        ).pack(side="left", padx=(6, 0))

        ttk.Checkbutton(
            dialog,
            text="Save applied markers to this profile",
            variable=save_profile_var,
        ).grid(row=4, column=0, sticky="w", padx=10, pady=(0, 8))

        apply_row = ttk.Frame(dialog)
        apply_row.grid(row=5, column=0, sticky="e", padx=10, pady=(0, 10))
        self._compare_make_button(
            apply_row,
            text="Apply to Compare",
            command=lambda: _apply_to_compare(False, False),
            compact=True,
        ).pack(side="right", padx=(6, 0))
        self._compare_make_button(
            apply_row,
            text="Apply + Save Profile",
            command=lambda: _apply_to_compare(True, True),
            compact=True,
        ).pack(side="right", padx=(6, 0))
        self._compare_make_button(
            apply_row,
            text="Close",
            command=dialog.destroy,
            compact=True,
        ).pack(side="right")

        _refresh_summary()
        try:
            dialog.grab_set()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _on_compare_paned_release(self, _event: Optional[tk.Event] = None) -> None:
        """Persist compare vertical split ratio after user sash drag.

        Purpose:
            Capture compare pane split changes when the user releases the sash.
        Why:
            Compare should reopen with the same plot/table height balance users
            selected previously.
        Args:
            _event: Tk event payload from sash release callback.
        Returns:
            None.
        Side Effects:
            Updates compare split fraction in settings and schedules one lightweight
            resize pass for both compare panes.
        Exceptions:
            Geometry access failures are ignored.
        """
        _ = _event
        self._persist_compare_split_from_widget(save=True)
        self._compare_sync_tab_canvas_geometry()
        self._compare_update_split_persist_debounced()
        self._compare_schedule_resize("A")
        self._compare_schedule_resize("B")

    def _compare_min_bottom_pane_height_px(self) -> int:
        """Resolve the minimum visible Compare bottom-pane height in pixels.

        Purpose:
            Protect the Per-Cycle uptake section from being collapsed by sash drags.
        Why:
            Compare split persistence alone cannot guarantee the uptake pane stays
            visible when users drag the sash aggressively toward the bottom.
        Args:
            None.
        Returns:
            Minimum bottom-pane height in pixels.
        Side Effects:
            Reads widget requested heights when available.
        Exceptions:
            Widget geometry failures fall back to a safe constant minimum.
        """
        minimum_px = int(DEFAULT_COMPARE_MIN_BOTTOM_PANE_HEIGHT_PX)
        tree = getattr(self, "_compare_cycle_tree", None)
        if tree is not None:
            try:
                tree.update_idletasks()
                tree_req = int(tree.winfo_reqheight() or 0)
            except Exception:
                tree_req = 0
            if tree_req > 0:
                # Include label-frame chrome + view-mode/action row headroom.
                minimum_px = max(minimum_px, tree_req + 88)
        return max(180, int(minimum_px))

    def _compare_clamp_split_frac_for_visibility(
        self,
        split_frac: Any,
        *,
        total_height: Optional[int] = None,
    ) -> float:
        """Normalize compare split fraction using minimal safety bounds.

        Purpose:
            Keep persisted compare split ratios finite and within near-full range.
        Why:
            Compare users need free sash dragging without forced snapback while
            still avoiding invalid zero/NaN split values.
        Args:
            split_frac: Candidate split fraction (`top_height / total_height`).
            total_height: Optional paned-widget height retained for API compatibility.
        Returns:
            Normalized split fraction suitable for sash positioning and persistence.
        Side Effects:
            None.
        Exceptions:
            Invalid numeric values fall back to default split ratio.
        """
        _ = total_height
        return _normalize_compare_split_frac(
            split_frac, default=DEFAULT_COMPARE_SPLIT_FRAC
        )

    def _apply_initial_compare_split(self) -> None:
        """Restore the initial compare vertical split ratio on tab build.

        Purpose:
            Apply the persisted compare split ratio after pane geometry resolves.
        Why:
            Tk paned geometry can be unavailable at first layout pass, requiring
            deferred retries for deterministic sash restoration.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Moves compare sash position based on persisted split fraction.
        Exceptions:
            Widget lifecycle races are handled with best-effort retries.
        """
        compare_state = _normalize_compare_tab_settings(settings.get("compare_tab"))
        split_frac = _normalize_compare_split_frac(
            compare_state.get("split_frac", DEFAULT_COMPARE_SPLIT_FRAC),
            default=DEFAULT_COMPARE_SPLIT_FRAC,
        )
        settings["compare_tab"] = compare_state

        def _apply_with_retries(remaining: int) -> None:
            """Apply one compare split position attempt after geometry settles."""
            paned = getattr(self, "_compare_paned", None)
            if paned is None or not paned.winfo_exists():
                return
            total_height = int(paned.winfo_height() or 0)
            if total_height <= 1:
                if remaining > 0:
                    self.after(70, lambda: _apply_with_retries(remaining - 1))
                return
            clamped_frac = self._compare_clamp_split_frac_for_visibility(
                split_frac,
                total_height=total_height,
            )
            try:
                paned.sashpos(0, int(round(total_height * clamped_frac)))
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            self._compare_sync_tab_canvas_geometry()

        self.after_idle(lambda: _apply_with_retries(10))
        self.after(250, lambda: _apply_with_retries(6))
        self.after(600, lambda: _apply_with_retries(3))

    def _persist_compare_split_from_widget(self, *, save: bool = True) -> Optional[float]:
        """Persist compare pane split ratio derived from current paned geometry.

        Purpose:
            Convert current compare sash position into normalized split fraction.
        Why:
            Compare split persistence is shared by sash-release callbacks and
            general compare-state persistence calls.
        Args:
            save: When True, schedule settings save after updating split state.
        Returns:
            Persisted split fraction, or None when geometry is unavailable.
        Side Effects:
            Mutates `settings["compare_tab"]["split_frac"]`.
        Exceptions:
            Invalid paned geometry values are ignored.
        """
        paned = getattr(self, "_compare_paned", None)
        if paned is None or not paned.winfo_exists():
            return None
        try:
            total_height = int(paned.winfo_height() or 0)
            if total_height <= 1:
                return None
            split_frac = float(paned.sashpos(0)) / float(total_height)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            return None
        clamped_split = self._compare_clamp_split_frac_for_visibility(
            split_frac,
            total_height=total_height,
        )
        if abs(float(clamped_split) - float(split_frac)) > 1e-6:
            try:
                paned.sashpos(0, int(round(total_height * float(clamped_split))))
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        split_frac = float(clamped_split)
        compare_state = _normalize_compare_tab_settings(settings.get("compare_tab"))
        compare_state["split_frac"] = _normalize_compare_split_frac(
            split_frac,
            default=compare_state.get("split_frac", DEFAULT_COMPARE_SPLIT_FRAC),
        )
        settings["compare_tab"] = compare_state
        if not save:
            return split_frac
        try:
            self._schedule_save_settings()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        return split_frac

    def _compare_schedule_resize(self, side_key: str) -> None:
        """Debounce one lightweight compare resize refresh after geometry changes.

        Purpose:
            Coalesce resize bursts into one geometry-only redraw pass.
        Why:
            Full Compare rerenders during drag can block Tk for long periods.
            A lightweight pass preserves responsiveness while keeping layout stable.
        Args:
            side_key: Compare side key ("A" or "B").
        Returns:
            None.
        Side Effects:
            Tracks dirty sides and schedules one deferred compare resize callback.
        Exceptions:
            Missing callbacks are ignored.
        """
        if side_key not in {"A", "B"}:
            return
        pending_sides = getattr(self, "_compare_resize_pending_sides", None)
        if not isinstance(pending_sides, set):
            pending_sides = set()
            self._compare_resize_pending_sides = pending_sides
        pending_sides.add(side_key)
        prior_after = getattr(self, "_compare_resize_after_id", None)
        if prior_after is not None:
            try:
                self.after_cancel(prior_after)
            except Exception:
                pass
            self._compare_resize_after_id = None

        def _run() -> None:
            """Run one queued compare resize refresh pass."""
            self._compare_resize_after_id = None
            sides = set(getattr(self, "_compare_resize_pending_sides", set()) or set())
            self._compare_resize_pending_sides = set()
            if not sides:
                return
            self._compare_refresh_resized_panes(sides)

        try:
            self._compare_resize_after_id = self.after(180, _run)
        except Exception:
            _run()

    def _compare_refresh_resized_panes(self, side_keys: Iterable[str]) -> None:
        """Refresh loaded compare panes using geometry-only redraw work.

        Purpose:
            Apply one lightweight resize refresh for dirty compare panes.
        Why:
            Resize interactions should not trigger full profile rerender work.
        Args:
            side_keys: Iterable containing dirty compare side keys ("A"/"B").
        Returns:
            None.
        Side Effects:
            Re-solves layout against current widget size and queues non-blocking
            redraws; may reapply locked x-axis limits using idle draws.
        Exceptions:
            Missing panes/widgets are skipped without raising.
        """
        dirty = {str(side or "").strip().upper() for side in side_keys}
        if not dirty:
            return
        panels = getattr(self, "_compare_panels", {})
        if not isinstance(panels, dict):
            return
        # Geometry-only refresh: keep existing figures and avoid expensive full rebuilds.
        for side_key in ("A", "B"):
            if side_key not in dirty:
                continue
            panel = panels.get(side_key) or {}
            if not isinstance(panel.get("bundle"), dict):
                continue
            fig = panel.get("figure")
            canvas = panel.get("canvas")
            widget = panel.get("widget")
            if fig is None or canvas is None or widget is None:
                continue
            self._finalize_matplotlib_canvas_layout(
                canvas=canvas,
                fig=fig,
                tk_widget=widget,
                keep_export_size=False,
                trigger_resize_event=False,
                force_draw=False,
            )
        self._compare_apply_locked_x_axis(redraw_mode="idle")

    def _compare_compute_theoretical_yield_g(
        self, basis: Mapping[str, Any]
    ) -> Optional[float]:
        """Compute theoretical product yield mass from one basis mapping.

        Purpose:
            Derive theoretical isolate mass in grams for yield comparison.
        Why:
            Compare yield math must map basis parameters to one consistent mass.
        Args:
            basis: Mapping containing starting mass, MW, stoichiometry, gas MW.
        Returns:
            Theoretical mass in grams, or None when inputs are incomplete/invalid.
        Side Effects:
            None.
        Exceptions:
            Invalid numeric values return None.
        """
        payload = _normalize_reaction_basis_payload(dict(basis or {}))
        return compute_theoretical_product_yield_g(payload)

    def _compare_resolve_reaction_basis(
        self, bundle: Optional[Dict[str, Any]]
    ) -> Dict[str, Any]:
        """Resolve active reaction basis for one Compare side.

        Purpose:
            Select effective yield-basis inputs for A/B yield calculations.
        Why:
            Compare supports auto profile basis and local override modes.
        Args:
            bundle: Optional loaded profile bundle for one compare side.
        Returns:
            Dict containing resolved basis fields.
        Side Effects:
            None.
        Exceptions:
            Invalid mode/values fall back to app defaults.
        """
        mode_value = str(self.compare_yield_mode_var.get() or "auto").strip().lower()
        fallback_basis = {
            "reaction_id": settings.get("selected_reaction_id", DEFAULT_SELECTED_REACTION_ID),
            "starting_mass_g": settings.get(
                "starting_material_mass_g", settings.get("starting_mass", 0.0)
            ),
            "starting_material_mw_g_mol": settings.get("starting_material_mw_g_mol"),
            "final_product_name": settings.get("final_product_name"),
            "final_product_formula": settings.get("final_product_formula"),
            "final_product_mw_g_mol": settings.get("final_product_mw_g_mol"),
            "product_stoich_mol_per_mol_starting": settings.get(
                "product_stoich_mol_per_mol_starting"
            ),
            "gas_stoich_mol_per_mol_starting": settings.get(
                "gas_stoich_mol_per_mol_starting"
            ),
            "stoich_mol_gas_per_mol_starting": settings.get(
                "stoich_mol_gas_per_mol_starting"
            ),
            "gas_molar_mass": settings.get("vdw_gas_molar_mass", DEFAULT_GAS_MOLAR_MASS),
            "yield_mode": settings.get("yield_mode", REACTION_YIELD_MODE_PRODUCT),
        }
        if mode_value == "override":
            return _normalize_reaction_basis_payload(
                {
                    "reaction_id": settings.get("selected_reaction_id", DEFAULT_SELECTED_REACTION_ID),
                "starting_mass_g": self._compare_parse_float_entry(
                    self.compare_override_starting_mass_var.get()
                ),
                "starting_material_mw_g_mol": self._compare_parse_float_entry(
                    self.compare_override_mw_var.get()
                ),
                "stoich_mol_gas_per_mol_starting": self._compare_parse_float_entry(
                    self.compare_override_stoich_var.get()
                ),
                "gas_molar_mass": self._compare_parse_float_entry(
                    self.compare_override_gas_mw_var.get()
                ),
                    "final_product_name": settings.get("final_product_name"),
                    "final_product_formula": settings.get("final_product_formula"),
                    "final_product_mw_g_mol": settings.get("final_product_mw_g_mol"),
                    "product_stoich_mol_per_mol_starting": settings.get(
                        "product_stoich_mol_per_mol_starting"
                    ),
                    "yield_mode": settings.get("yield_mode", REACTION_YIELD_MODE_PRODUCT),
                }
            )
        payload_basis = {}
        if isinstance(bundle, dict):
            payload_basis = dict(bundle.get("reaction_basis") or {})
        resolved = dict(fallback_basis)
        for key in (
            "reaction_id",
            "starting_mass_g",
            "starting_material_mw_g_mol",
            "final_product_name",
            "final_product_formula",
            "final_product_mw_g_mol",
            "product_stoich_mol_per_mol_starting",
            "gas_stoich_mol_per_mol_starting",
            "stoich_mol_gas_per_mol_starting",
            "gas_molar_mass",
            "yield_mode",
        ):
            if payload_basis.get(key) not in (None, ""):
                resolved[key] = payload_basis.get(key)
        return _normalize_reaction_basis_payload(resolved)

    def _compare_refresh_yield_summary(self) -> None:
        """Recompute and render Compare yield summary text.

        Purpose:
            Update theoretical/actual yield outputs for both selected profiles.
        Why:
            Yield results must respond immediately to profile or input changes.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Updates Compare yield summary label text.
        Exceptions:
            Invalid numeric inputs are treated as missing values.
        """
        bundle_a = (self._compare_panels.get("A") or {}).get("bundle")
        bundle_b = (self._compare_panels.get("B") or {}).get("bundle")
        iso_a = self._compare_parse_float_entry(self.compare_isolated_mass_a_var.get())
        iso_b = self._compare_parse_float_entry(self.compare_isolated_mass_b_var.get())
        basis_a = self._compare_resolve_reaction_basis(bundle_a)
        basis_b = self._compare_resolve_reaction_basis(bundle_b)
        theo_a = self._compare_compute_theoretical_yield_g(basis_a)
        theo_b = self._compare_compute_theoretical_yield_g(basis_b)
        actual_a = None
        actual_b = None
        if iso_a is not None and theo_a not in (None, 0.0):
            actual_a = (iso_a / float(theo_a)) * 100.0
        if iso_b is not None and theo_b not in (None, 0.0):
            actual_b = (iso_b / float(theo_b)) * 100.0
        lines = [
            f"Profile A theoretical: {'--' if theo_a is None else f'{theo_a:.4f} g'}",
            f"Profile B theoretical: {'--' if theo_b is None else f'{theo_b:.4f} g'}",
            f"Profile A actual yield: {'--' if actual_a is None else f'{actual_a:.2f}%'}",
            f"Profile B actual yield: {'--' if actual_b is None else f'{actual_b:.2f}%'}",
        ]
        if actual_a is not None and actual_b is not None:
            lines.append(f"Yield delta (B - A): {actual_b - actual_a:+.2f}%")
        if iso_a is not None and iso_b is not None:
            lines.append(f"Isolated mass delta (B - A): {iso_b - iso_a:+.4f} g")
        self._compare_yield_summary_var.set("\n".join(lines))
        kpi_a_var = getattr(self, "_compare_yield_kpi_a_var", None)
        if isinstance(kpi_a_var, tk.StringVar):
            kpi_a_var.set(
                "A: "
                + (
                    "missing isolated mass/theoretical basis"
                    if actual_a is None
                    else f"{actual_a:.2f}% actual  |  {theo_a:.4f} g theoretical"
                )
            )
        kpi_b_var = getattr(self, "_compare_yield_kpi_b_var", None)
        if isinstance(kpi_b_var, tk.StringVar):
            kpi_b_var.set(
                "B: "
                + (
                    "missing isolated mass/theoretical basis"
                    if actual_b is None
                    else f"{actual_b:.2f}% actual  |  {theo_b:.4f} g theoretical"
                )
            )
        kpi_delta_var = getattr(self, "_compare_yield_kpi_delta_var", None)
        if isinstance(kpi_delta_var, tk.StringVar):
            if actual_a is not None and actual_b is not None:
                delta_color_hint = "higher" if (actual_b - actual_a) > 0 else "lower"
                kpi_delta_var.set(
                    f"Delta (B-A): {actual_b - actual_a:+.2f}% ({delta_color_hint} B yield)"
                )
            else:
                kpi_delta_var.set("Delta (B-A): --")
        warning_var = getattr(self, "_compare_yield_warning_var", None)
        if isinstance(warning_var, tk.StringVar):
            warnings: List[str] = []
            if theo_a in (None, 0.0):
                warnings.append("Profile A theoretical basis is incomplete.")
            if theo_b in (None, 0.0):
                warnings.append("Profile B theoretical basis is incomplete.")
            if iso_a is None:
                warnings.append("Profile A isolated mass is missing.")
            if iso_b is None:
                warnings.append("Profile B isolated mass is missing.")
            warning_var.set(" ".join(warnings))

    def _compare_update_side_diagnostics(
        self,
        side_key: str,
        *,
        profile_name: Optional[str] = None,
        dataset_path: Optional[str] = None,
        status: Optional[str] = None,
        detail: Optional[str] = None,
        cycle_count: Optional[int] = None,
        total_drop_g: Optional[float] = None,
        render_success: Optional[bool] = None,
        cycle_fallback_used: Optional[bool] = None,
        cycle_rows_synthesized: Optional[bool] = None,
        cycle_compute_backend: Optional[str] = None,
    ) -> None:
        """Update one Compare-side diagnostics payload.

        Purpose:
            Persist side-specific load/render diagnostics in one mutable payload.
        Why:
            Compare load now handles A/B sides independently, so users need clear
            per-side diagnostics for dataset resolution, load state, and render state.
        Args:
            side_key: Compare side key ("A" or "B").
            profile_name: Optional selected profile name for this side.
            dataset_path: Optional resolved dataset path for this side.
            status: Optional side status text (for example, Loaded, Failed).
            detail: Optional side detail/error text.
            cycle_count: Optional rendered cycle count.
            total_drop_g: Optional rendered total uptake mass in grams.
            render_success: Optional rendered-success flag for summary reporting.
            cycle_fallback_used: Optional flag indicating auto cycle fallback use.
            cycle_rows_synthesized: Optional flag for synthesized cycle rows.
            cycle_compute_backend: Optional cycle compute backend label.
        Returns:
            None.
        Side Effects:
            Mutates `self._compare_load_diagnostics_state`.
        Exceptions:
            Invalid side keys are ignored.
        """
        if side_key not in {"A", "B"}:
            return
        state = dict(getattr(self, "_compare_load_diagnostics_state", {}) or {})
        side_payload = dict(state.get(side_key) or {})
        updates = {
            "profile_name": profile_name,
            "dataset_path": dataset_path,
            "status": status,
            "detail": detail,
            "cycle_count": cycle_count,
            "total_drop_g": total_drop_g,
            "render_success": render_success,
            "cycle_fallback_used": cycle_fallback_used,
            "cycle_rows_synthesized": cycle_rows_synthesized,
            "cycle_compute_backend": (
                str(cycle_compute_backend).strip().lower()
                if cycle_compute_backend is not None
                else None
            ),
        }
        for key, value in updates.items():
            if value is not None:
                side_payload[key] = value
        state[side_key] = side_payload
        self._compare_load_diagnostics_state = state

    def _compare_refresh_diagnostics_panel(self) -> None:
        """Rebuild the Compare diagnostics text panel.

        Purpose:
            Render a user-facing diagnostics summary for the latest Compare load.
        Why:
            A/B loads can fail independently; diagnostics should expose side-level
            outcomes and resolved dataset sources without opening logs.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Updates `_compare_diagnostics_var` text in the Compare tab.
        Exceptions:
            Missing diagnostics variable is treated as no-op.
        """
        var = getattr(self, "_compare_diagnostics_var", None)
        if not isinstance(var, tk.StringVar):
            return
        state = dict(getattr(self, "_compare_load_diagnostics_state", {}) or {})
        summary = str(state.get("summary") or "No compare load activity yet.").strip()
        lines = [summary]
        for side_key in ("A", "B"):
            side_payload = dict(state.get(side_key) or {})
            profile_name = str(side_payload.get("profile_name") or "--").strip() or "--"
            status_text = str(side_payload.get("status") or "Idle").strip() or "Idle"
            detail_text = str(side_payload.get("detail") or "").strip()
            dataset_path = str(side_payload.get("dataset_path") or "").strip()
            cycle_count = side_payload.get("cycle_count")
            total_drop_g = self._compare_parse_float_entry(side_payload.get("total_drop_g"))
            cycle_fallback_used = bool(side_payload.get("cycle_fallback_used", False))
            cycle_rows_synthesized = bool(
                side_payload.get("cycle_rows_synthesized", False)
            )
            cycle_compute_backend = str(
                side_payload.get("cycle_compute_backend") or ""
            ).strip()
            lines.append("")
            lines.append(f"Profile {side_key}: {profile_name}")
            lines.append(f"Status: {status_text}")
            if detail_text:
                lines.append(f"Detail: {detail_text}")
            if dataset_path:
                lines.append(f"Dataset: {dataset_path}")
            if cycle_count is not None:
                lines.append(f"Cycles: {int(cycle_count)}")
            if total_drop_g is not None:
                lines.append(f"Total dP uptake: {float(total_drop_g):.4f} g")
            if cycle_compute_backend:
                lines.append(f"Cycle compute backend: {cycle_compute_backend}")
            if cycle_fallback_used:
                lines.append("Cycle fallback: auto-detect replay used")
            if cycle_rows_synthesized:
                lines.append("Cycle rows: synthesized from analysis payload")
        var.set("\n".join(lines))

    def _compare_series_gap_metrics(self, x_values: Any, y_values: Any) -> Dict[str, Any]:
        """Compute finite/break segment diagnostics for one Compare pressure series.

        Purpose:
            Quantify trace continuity characteristics used by side-cycle editor
            debugging for whitespace and gap investigations.
        Why:
            Compare side plots must preserve non-finite separators as visual breaks;
            explicit metrics make hidden continuity issues detectable from logs.
        Args:
            x_values: Candidate x-axis sequence for one side profile.
            y_values: Candidate y-axis sequence for one side profile.
        Returns:
            Dict containing point totals, finite-pair counts, non-finite break
            rows, and contiguous finite segment count.
        Side Effects:
            None.
        Exceptions:
            Invalid array payloads return zeroed metrics.
        """
        metrics: Dict[str, Any] = {
            "total_points": 0,
            "finite_pairs": 0,
            "break_rows": 0,
            "finite_segments": 0,
        }
        try:
            x_arr = np.asarray(x_values, dtype=float).reshape(-1)
            y_arr = np.asarray(y_values, dtype=float).reshape(-1)
        except Exception:
            return metrics
        pair_len = int(min(x_arr.size, y_arr.size))
        if pair_len <= 0:
            return metrics
        x_arr = x_arr[:pair_len]
        y_arr = y_arr[:pair_len]
        finite_pairs = np.isfinite(x_arr) & np.isfinite(y_arr)
        finite_count = int(np.count_nonzero(finite_pairs))
        metrics["total_points"] = pair_len
        metrics["finite_pairs"] = finite_count
        metrics["break_rows"] = int(pair_len - finite_count)
        if finite_count <= 0:
            return metrics
        finite_int = finite_pairs.astype(np.int8, copy=False)
        # Count contiguous finite runs to verify that NaN separators are retained.
        transitions = np.diff(finite_int, prepend=np.array([0], dtype=np.int8))
        metrics["finite_segments"] = int(np.count_nonzero(transitions == 1))
        return metrics

    def _compare_figure_whitespace_metrics(self, fig: Optional[Figure]) -> Dict[str, Any]:
        """Compute whitespace diagnostics for one rendered Compare figure.

        Purpose:
            Measure legend/x-label gap and axes compression metrics for one pane.
        Why:
            The persistent Compare whitespace issue requires direct, repeatable
            measurements rather than visual-only inspection.
        Args:
            fig: Candidate rendered figure from one Compare panel.
        Returns:
            Dict containing computed whitespace metrics and latest layout-health
            auto-fix metadata when available.
        Side Effects:
            May trigger one canvas draw to obtain a renderer.
        Exceptions:
            Renderer/artist failures return partial metrics.
        """
        metrics: Dict[str, Any] = {
            "plot_id": "",
            "legend_xlabel_gap_pts": None,
            "axes_union_height_frac": None,
            "legend_bbox_fig": None,
            "xlabel_bbox_fig": None,
            "subplotpars": None,
            "layout_health_passes": None,
            "layout_health_issues": [],
            "layout_health_applied": None,
        }
        if fig is None:
            return metrics
        metrics["plot_id"] = str(getattr(fig, "_gl260_plot_id", "") or "")
        canvas = getattr(fig, "canvas", None)
        if canvas is None:
            try:
                canvas = FigureCanvasAgg(fig)
                fig.set_canvas(canvas)
            except Exception:
                canvas = None
        if canvas is None:
            return metrics
        try:
            canvas.draw()
            renderer = canvas.get_renderer()
        except Exception:
            return metrics
        plot_id = str(getattr(fig, "_gl260_plot_id", "") or "")
        legend = _layout_health_primary_legend(fig, plot_id=plot_id)
        xlabel = _layout_health_primary_xlabel(fig, plot_id=plot_id)
        legend_bbox = _layout_health_bbox_in_fig(fig, legend, renderer)
        xlabel_bbox = _layout_health_bbox_in_fig(fig, xlabel, renderer)
        try:
            fig_h_pts = max(float(fig.get_size_inches()[1]) * 72.0, 1.0)
        except Exception:
            fig_h_pts = 1.0
        if legend_bbox is not None and xlabel_bbox is not None:
            metrics["legend_xlabel_gap_pts"] = float(
                (xlabel_bbox.y0 - legend_bbox.y1) * fig_h_pts
            )
        if legend_bbox is not None:
            metrics["legend_bbox_fig"] = {
                "x0": float(legend_bbox.x0),
                "y0": float(legend_bbox.y0),
                "x1": float(legend_bbox.x1),
                "y1": float(legend_bbox.y1),
            }
        if xlabel_bbox is not None:
            metrics["xlabel_bbox_fig"] = {
                "x0": float(xlabel_bbox.x0),
                "y0": float(xlabel_bbox.y0),
                "x1": float(xlabel_bbox.x1),
                "y1": float(xlabel_bbox.y1),
            }
        axes_positions: List[Bbox] = []
        try:
            for axis in fig.get_axes():
                if axis is None or getattr(axis, "_gl260_legend_only", False):
                    continue
                if not bool(axis.get_visible()):
                    continue
                axes_positions.append(axis.get_position())
        except Exception:
            axes_positions = []
        if axes_positions:
            try:
                axes_union = Bbox.union(axes_positions)
                metrics["axes_union_height_frac"] = float(axes_union.height)
            except Exception:
                metrics["axes_union_height_frac"] = None
        try:
            subplotpars = getattr(fig, "subplotpars", None)
            if subplotpars is not None:
                metrics["subplotpars"] = {
                    "left": float(subplotpars.left),
                    "right": float(subplotpars.right),
                    "top": float(subplotpars.top),
                    "bottom": float(subplotpars.bottom),
                }
        except Exception:
            metrics["subplotpars"] = None
        layout_result = getattr(fig, "_gl260_last_layout_health_result", None)
        if isinstance(layout_result, Mapping):
            metrics["layout_health_passes"] = int(layout_result.get("passes", 0))
            metrics["layout_health_issues"] = list(layout_result.get("issues") or [])
            metrics["layout_health_applied"] = bool(layout_result.get("applied", False))
        return metrics

    def _compare_collect_debug_snapshot(self) -> Dict[str, Any]:
        """Build one structured Compare diagnostics snapshot for debugging.

        Purpose:
            Consolidate Compare runtime state into one serializable diagnostics payload.
        Why:
            Whitespace and cycle-editor issues cross multiple state holders
            (panes, diagnostics, markers, layout overrides), requiring one
            consistent snapshot for troubleshooting.
        Args:
            None.
        Returns:
            Dict containing compare panels, whitespace metrics, marker override
            state, cycle-editor cache, and current diagnostics summary payload.
        Side Effects:
            None.
        Exceptions:
            Invalid intermediate state is sanitized into safe defaults.
        """
        snapshot: Dict[str, Any] = {
            "summary": str(
                (getattr(self, "_compare_load_diagnostics_state", {}) or {}).get(
                    "summary", ""
                )
                or ""
            ).strip(),
            "preset_name": str(
                self.compare_plot_preset_var.get()
                if hasattr(self, "compare_plot_preset_var")
                else ""
            ).strip(),
            "layout_overrides": _normalize_compare_layout_overrides(
                getattr(self, "_compare_layout_overrides", {})
            ),
            "plot_editor_margins_by_pair": _normalize_compare_plot_editor_margins_by_pair(
                getattr(self, "_compare_plot_editor_margins_by_pair", {})
            ),
            "marker_overrides": {},
            "panels": {},
            "cycle_editor_states": {},
        }
        marker_overrides = _normalize_compare_marker_overrides(
            getattr(self, "_compare_marker_overrides", {})
        )
        for side_key in ("A", "B"):
            payload = _normalize_profile_cycle_markers(marker_overrides.get(side_key))
            snapshot["marker_overrides"][side_key] = {
                "present": bool(payload is not None),
                "add_peaks": len(list((payload or {}).get("add_peaks") or [])),
                "add_troughs": len(list((payload or {}).get("add_troughs") or [])),
                "rm_peaks": len(list((payload or {}).get("rm_peaks") or [])),
                "rm_troughs": len(list((payload or {}).get("rm_troughs") or [])),
                "manual_revision": int((payload or {}).get("manual_revision") or 0),
                "auto_detect_enabled": bool(
                    (payload or {}).get("auto_detect_enabled", True)
                ),
                "use_auto_markers_in_manual_mode": bool(
                    (payload or {}).get("use_auto_markers_in_manual_mode", True)
                ),
            }
        panels = getattr(self, "_compare_panels", {})
        panels = panels if isinstance(panels, Mapping) else {}
        diagnostics_state = dict(getattr(self, "_compare_load_diagnostics_state", {}) or {})
        for side_key in ("A", "B"):
            panel = panels.get(side_key) if isinstance(panels, Mapping) else None
            panel = panel if isinstance(panel, Mapping) else {}
            bundle = panel.get("bundle")
            bundle = bundle if isinstance(bundle, Mapping) else {}
            panel_payload: Dict[str, Any] = {
                "profile_name": str(bundle.get("profile_name") or "").strip(),
                "dataset_path": str(bundle.get("dataset_path") or "").strip(),
                "render_success": bool(panel.get("render_success", False)),
                "render_error_message": str(panel.get("render_error_message") or "").strip(),
                "cycle_count": len(list(panel.get("cycle_rows") or [])),
                "total_drop_g": self._compare_parse_float_entry(panel.get("total_drop")),
                "cycle_fallback_used": bool(panel.get("cycle_fallback_used", False)),
                "cycle_rows_synthesized": bool(
                    panel.get("cycle_rows_synthesized", False)
                ),
                "cycle_compute_backend": str(panel.get("cycle_compute_backend") or "").strip(),
                "diag_status": str(
                    (diagnostics_state.get(side_key) or {}).get("status") or ""
                ).strip(),
                "diag_detail": str(
                    (diagnostics_state.get(side_key) or {}).get("detail") or ""
                ).strip(),
            }
            panel_payload["whitespace"] = self._compare_figure_whitespace_metrics(
                panel.get("figure") if isinstance(panel, Mapping) else None
            )
            data_ctx = bundle.get("data_ctx") if isinstance(bundle, Mapping) else {}
            data_ctx = data_ctx if isinstance(data_ctx, Mapping) else {}
            series_np = data_ctx.get("series_np")
            series_np = series_np if isinstance(series_np, Mapping) else {}
            series_map = data_ctx.get("series")
            series_map = series_map if isinstance(series_map, Mapping) else {}
            panel_payload["series_gaps"] = self._compare_series_gap_metrics(
                series_np.get("x", series_map.get("x")),
                series_np.get("y1", series_map.get("y1")),
            )
            snapshot["panels"][side_key] = panel_payload
        editor_states = getattr(self, "_compare_cycle_editor_states", {})
        editor_states = editor_states if isinstance(editor_states, Mapping) else {}
        for side_key in ("A", "B"):
            editor_state = editor_states.get(side_key)
            editor_state = editor_state if isinstance(editor_state, Mapping) else {}
            payload = _normalize_profile_cycle_markers(editor_state.get("payload"))
            snapshot["cycle_editor_states"][side_key] = {
                "window_open": bool(
                    (editor_state.get("window") is not None)
                    and bool(
                        getattr(editor_state.get("window"), "winfo_exists", lambda: False)()
                    )
                ),
                "profile_name": str(editor_state.get("profile_name") or "").strip(),
                "manual_revision": int((payload or {}).get("manual_revision") or 0),
                "add_peaks": len(list((payload or {}).get("add_peaks") or [])),
                "add_troughs": len(list((payload or {}).get("add_troughs") or [])),
                "rm_peaks": len(list((payload or {}).get("rm_peaks") or [])),
                "rm_troughs": len(list((payload or {}).get("rm_troughs") or [])),
                "use_auto_markers_in_manual_mode": bool(
                    (payload or {}).get("use_auto_markers_in_manual_mode", True)
                ),
                "latest_cycle_rows": len(list(editor_state.get("latest_cycle_rows") or [])),
                "series_gaps": dict(editor_state.get("series_gap_metrics") or {}),
            }
        return snapshot

    def _compare_emit_debug_report(
        self,
        *,
        header: str,
        category: str,
        payload: Mapping[str, Any],
    ) -> None:
        """Emit one Compare diagnostics report to stderr and debug logger.

        Purpose:
            Centralize Compare debug report emission across UI actions and hooks.
        Why:
            Troubleshooting sessions require guaranteed terminal output even when
            debug categories are disabled, while still supporting category-gated logs.
        Args:
            header: Human-readable report title.
            category: Debug category key for `_dbg` routing.
            payload: Structured diagnostics payload to serialize.
        Returns:
            None.
        Side Effects:
            Prints one JSON payload to stderr and emits one `_dbg` entry.
        Exceptions:
            Serialization/output failures are handled best-effort.
        """
        report = {
            "header": str(header or "").strip(),
            "timestamp": datetime.now().isoformat(timespec="seconds"),
            "payload": dict(payload or {}),
        }
        try:
            serialized = json.dumps(report, ensure_ascii=False, default=str, sort_keys=True)
        except Exception:
            serialized = str(report)
        try:
            print(serialized, file=sys.stderr)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        self._dbg(category, "%s", serialized, once_key=None)

    def _compare_dump_debug_snapshot(self) -> None:
        """Emit one full Compare state snapshot for collaborative debugging.

        Purpose:
            Provide an on-demand dump action for current Compare state.
        Why:
            Debugging whitespace/marker issues needs one explicit state capture
            without waiting for automatic render events.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Writes a structured diagnostics report to stderr/debug log.
        Exceptions:
            Snapshot collection failures are reported with best-effort payloads.
        """
        try:
            payload = self._compare_collect_debug_snapshot()
        except Exception as exc:
            payload = {"error": f"snapshot_failed:{type(exc).__name__}"}
        self._compare_emit_debug_report(
            header="Compare Snapshot",
            category="compare.render",
            payload=payload,
        )

    def _compare_dump_debug_whitespace(self) -> None:
        """Emit focused Compare whitespace diagnostics for both render panes.

        Purpose:
            Produce a compact report of pane whitespace metrics and layout-health state.
        Why:
            The Compare whitespace defect requires frequent metric checks while
            adjusting layout settings and rerendering.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Writes a structured diagnostics report to stderr/debug log.
        Exceptions:
            Missing panes/figures are tolerated and reported as empty metrics.
        """
        payload: Dict[str, Any] = {"panes": {}}
        panels = getattr(self, "_compare_panels", {})
        panels = panels if isinstance(panels, Mapping) else {}
        for side_key in ("A", "B"):
            panel = panels.get(side_key) if isinstance(panels, Mapping) else None
            panel = panel if isinstance(panel, Mapping) else {}
            payload["panes"][side_key] = self._compare_figure_whitespace_metrics(
                panel.get("figure")
            )
        self._compare_emit_debug_report(
            header="Compare Whitespace",
            category="compare.whitespace",
            payload=payload,
        )

    def _compare_dump_cycle_editor_state(self) -> None:
        """Emit side Compare cycle-editor state for marker-assignment debugging.

        Purpose:
            Provide direct visibility into side editor marker payloads and revisions.
        Why:
            Marker correction issues are easiest to diagnose with explicit side cache
            dumps rather than inferring from popup text.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Writes a structured diagnostics report to stderr/debug log.
        Exceptions:
            Invalid/missing editor state is normalized to empty defaults.
        """
        payload = {"cycle_editor_states": self._compare_collect_debug_snapshot().get("cycle_editor_states", {})}
        self._compare_emit_debug_report(
            header="Compare Cycle Editor State",
            category="compare.cycle_editor",
            payload=payload,
        )

    def _compare_log_profile_load_event(
        self,
        *,
        side_key: str,
        profile_name: str,
        load_ctx: Mapping[str, Any],
    ) -> None:
        """Emit one focused profile-load diagnostics event for Compare.

        Purpose:
            Log side-local profile load outcomes at the point of bundle staging.
        Why:
            Load-stage diagnostics are needed to separate data-loading failures
            from later render/layout issues.
        Args:
            side_key: Compare side key (`"A"` or `"B"`).
            profile_name: Profile requested by the user for this side.
            load_ctx: Result payload returned by `_compare_load_profile_bundle_for_side`.
        Returns:
            None.
        Side Effects:
            Writes one structured diagnostics report to stderr/debug log.
        Exceptions:
            Invalid payload values are normalized to safe strings.
        """
        payload = {
            "side": str(side_key or "").strip().upper(),
            "requested_profile": str(profile_name or "").strip(),
            "resolved_profile": str(load_ctx.get("profile_name") or "").strip(),
            "status": str(load_ctx.get("status") or "").strip(),
            "status_label": str(load_ctx.get("status_label") or "").strip(),
            "detail": str(load_ctx.get("detail") or "").strip(),
            "dataset_path": str(load_ctx.get("dataset_path") or "").strip(),
            "bundle_ready": isinstance(load_ctx.get("bundle"), Mapping),
        }
        self._compare_emit_debug_report(
            header="Compare Profile Load",
            category="compare.render",
            payload=payload,
        )

    def _compare_log_render_context_event(
        self,
        *,
        side_key: str,
        bundle: Mapping[str, Any],
        cycle_rows: Sequence[Mapping[str, Any]],
        total_drop: Optional[float],
        metadata: Mapping[str, Any],
    ) -> None:
        """Emit one focused render-context diagnostics event for Compare.

        Purpose:
            Capture cycle extraction/render-context outputs before pane rendering.
        Why:
            Distinguishes cycle-context issues from draw/layout faults when Compare
            output diverges from main Cycle Analysis behavior.
        Args:
            side_key: Compare side key (`"A"` or `"B"`).
            bundle: Active compare profile bundle.
            cycle_rows: Extracted cycle-transfer rows for this side.
            total_drop: Optional total drop/uptake value.
            metadata: Extraction metadata produced by context builder.
        Returns:
            None.
        Side Effects:
            Writes one structured diagnostics report to stderr/debug log.
        Exceptions:
            Invalid values are sanitized to safe defaults.
        """
        payload = {
            "side": str(side_key or "").strip().upper(),
            "profile_name": str(bundle.get("profile_name") or "").strip(),
            "dataset_path": str(bundle.get("dataset_path") or "").strip(),
            "cycle_rows": int(len(list(cycle_rows or []))),
            "total_drop": self._compare_parse_float_entry(total_drop),
            "cycle_fallback_used": bool(metadata.get("cycle_fallback_used", False)),
            "cycle_rows_synthesized": bool(
                metadata.get("cycle_rows_synthesized", False)
            ),
            "cycle_compute_backend": str(
                metadata.get("cycle_compute_backend") or ""
            ).strip(),
            "segmentation_backend": str(
                metadata.get("segmentation_backend") or ""
            ).strip(),
            "metrics_backend": str(metadata.get("metrics_backend") or "").strip(),
        }
        self._compare_emit_debug_report(
            header="Compare Render Context",
            category="compare.render",
            payload=payload,
        )

    def _compare_log_render_completion_event(self, side_key: str) -> None:
        """Emit one focused Compare pane render completion diagnostics event.

        Purpose:
            Capture pane-level render success/error and whitespace metrics.
        Why:
            Allows direct correlation between render outcomes and measured
            whitespace state for each side.
        Args:
            side_key: Compare side key (`"A"` or `"B"`).
        Returns:
            None.
        Side Effects:
            Writes one structured diagnostics report to stderr/debug log.
        Exceptions:
            Missing panel state is normalized to defaults.
        """
        panels = getattr(self, "_compare_panels", {})
        panels = panels if isinstance(panels, Mapping) else {}
        panel = panels.get(side_key) if isinstance(panels, Mapping) else None
        panel = panel if isinstance(panel, Mapping) else {}
        bundle = panel.get("bundle")
        bundle = bundle if isinstance(bundle, Mapping) else {}
        payload = {
            "side": str(side_key or "").strip().upper(),
            "profile_name": str(bundle.get("profile_name") or "").strip(),
            "render_success": bool(panel.get("render_success", False)),
            "render_error_message": str(panel.get("render_error_message") or "").strip(),
            "cycle_count": len(list(panel.get("cycle_rows") or [])),
            "total_drop_g": self._compare_parse_float_entry(panel.get("total_drop")),
            "cycle_fallback_used": bool(panel.get("cycle_fallback_used", False)),
            "cycle_rows_synthesized": bool(panel.get("cycle_rows_synthesized", False)),
            "cycle_compute_backend": str(panel.get("cycle_compute_backend") or "").strip(),
            "whitespace": self._compare_figure_whitespace_metrics(panel.get("figure")),
        }
        self._compare_emit_debug_report(
            header="Compare Render Completion",
            category="compare.render",
            payload=payload,
        )

    def _compare_log_cycle_editor_event(
        self,
        *,
        side_key: str,
        event_name: str,
        payload: Optional[Mapping[str, Any]] = None,
    ) -> None:
        """Emit one side-cycle-editor diagnostics event.

        Purpose:
            Record key marker-editor transitions (recompute/pull/apply) for Compare.
        Why:
            Marker correction debugging requires explicit event traces tied to side
            and payload state transitions.
        Args:
            side_key: Compare side key (`"A"` or `"B"`).
            event_name: Short event token describing the editor action.
            payload: Optional event-specific diagnostics payload.
        Returns:
            None.
        Side Effects:
            Writes one structured diagnostics report to stderr/debug log.
        Exceptions:
            Missing payload is normalized to an empty mapping.
        """
        report = {
            "side": str(side_key or "").strip().upper(),
            "event": str(event_name or "").strip(),
        }
        if isinstance(payload, Mapping):
            report.update(dict(payload))
        self._compare_emit_debug_report(
            header="Compare Cycle Editor Event",
            category="compare.cycle_editor",
            payload=report,
        )

    def _compare_show_load_splash(self, title: str) -> None:
        """Show the Compare in-tab splash overlay with determinate progress.

        Purpose:
            Present one full-tab loading overlay while Compare workflows run.
        Why:
            Compare loads and layout-apply refreshes can be expensive; the tab
            should stay responsive while avoiding half-rendered intermediate UI.
        Args:
            title: Overlay heading text for the current compare action.
        Returns:
            None.
        Side Effects:
            Creates or reuses the in-tab overlay widgets and resets progress/
            timer state.
        Exceptions:
            Widget construction/placement failures are handled best-effort.
        """
        window = getattr(self, "_compare_load_splash_window", None)
        if window is not None and bool(
            getattr(window, "winfo_exists", lambda: False)()
        ):
            try:
                window.lift()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            self._compare_update_load_splash(
                message="Preparing Compare load...",
                progress=5.0,
                stage_key="queued",
                detail="Initializing profile load pipeline",
                reset=True,
            )
            return

        host = getattr(self, "tab_compare", None) or self
        try:
            base_bg = host.cget("background")
        except Exception:
            base_bg = None
        try:
            window = tk.Frame(host, background=base_bg)
        except Exception:
            window = tk.Frame(host)
        try:
            window.place(relx=0.0, rely=0.0, relwidth=1.0, relheight=1.0)
        except Exception:
            return
        container = ttk.Frame(window, padding=12)
        container.place(relx=0.5, rely=0.5, anchor="center")
        label = ttk.Label(
            container,
            text=f"{title}\nPreparing Compare load...",
            justify="left",
            anchor="w",
            width=56,
        )
        label.pack(fill="x")
        detail_label = ttk.Label(
            container,
            text="",
            justify="left",
            anchor="w",
            wraplength=420,
            width=56,
        )
        detail_label.pack(fill="x", pady=(6, 6))
        progress_var = tk.DoubleVar(master=host, value=0.0)
        ttk.Progressbar(
            container,
            mode="determinate",
            length=320,
            maximum=100.0,
            variable=progress_var,
        ).pack(fill="x", pady=(10, 0))
        progress_label = ttk.Label(container, text="0% | 0.00s", width=56)
        progress_label.pack(anchor="e", pady=(6, 0))

        self._compare_load_splash_window = window
        self._compare_load_splash_label = label
        self._compare_load_splash_detail_label = detail_label
        self._compare_load_splash_progress_var = progress_var
        self._compare_load_splash_progress_label = progress_label
        self._compare_load_splash_stage_key = "queued"
        self._compare_load_splash_started_at = time.monotonic()
        self._compare_load_splash_detail_base = ""
        self._compare_load_splash_heartbeat_after_id = None
        try:
            window.lift()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        self._compare_update_load_splash(
            message="Preparing Compare load...",
            progress=5.0,
            stage_key="queued",
            detail="Initializing profile load pipeline",
            reset=True,
        )

    def _compare_resolve_load_splash_stage_key(
        self,
        *,
        message: Optional[str],
        stage_key: Optional[str],
    ) -> str:
        """Resolve one normalized Compare load splash stage key.

        Purpose:
            Normalize explicit or message-derived splash stage identifiers.
        Why:
            Stage normalization keeps heartbeat/progress behavior deterministic
            across compare load orchestration and side-level fallback paths.
        Args:
            message: Optional user-facing status message.
            stage_key: Optional explicit stage token.
        Returns:
            Canonical stage key string.
        Side Effects:
            None.
        Exceptions:
            Invalid values fall back to `queued`.
        """
        if isinstance(stage_key, str) and stage_key.strip():
            return stage_key.strip().lower().replace(" ", "_")
        text = str(message or "").strip().lower()
        if not text:
            return "queued"
        if "failed" in text:
            return "failed"
        if "ready" in text or "final" in text:
            return "ready"
        if "render" in text:
            return "render"
        if "table" in text or "yield" in text:
            return "refresh"
        if "load" in text:
            return "load"
        return "queued"

    def _compare_stop_load_splash_heartbeat(self) -> None:
        """Stop the Compare splash elapsed-time heartbeat timer.

        Purpose:
            Cancel scheduled splash timer callbacks during terminal states.
        Why:
            Splash teardown and ready/failed states must not leave orphan timers.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Cancels one scheduled `after` callback when present.
        Exceptions:
            Cancellation failures are ignored by design.
        """
        after_id = getattr(self, "_compare_load_splash_heartbeat_after_id", None)
        if after_id is None:
            return
        try:
            self.after_cancel(after_id)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        self._compare_load_splash_heartbeat_after_id = None

    def _compare_start_load_splash_heartbeat(self) -> None:
        """Start the Compare splash elapsed-time heartbeat timer.

        Purpose:
            Keep splash detail text synchronized with live wall-clock elapsed time.
        Why:
            Profile I/O and rendering may take multiple seconds and should show
            visible in-progress activity.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Schedules recurring timer callbacks while splash is active.
        Exceptions:
            Missing or destroyed widgets short-circuit safely.
        """
        if getattr(self, "_compare_load_splash_heartbeat_after_id", None) is not None:
            return

        def _tick() -> None:
            """Update Compare splash elapsed detail text for one timer tick."""
            self._compare_load_splash_heartbeat_after_id = None
            window = getattr(self, "_compare_load_splash_window", None)
            if window is None:
                return
            try:
                if not window.winfo_exists():
                    return
            except Exception:
                return
            stage_key = str(
                getattr(self, "_compare_load_splash_stage_key", "queued") or "queued"
            )
            if stage_key in {"ready", "failed"}:
                return
            started_at = getattr(self, "_compare_load_splash_started_at", None)
            if not isinstance(started_at, (int, float)):
                started_at = time.monotonic()
                self._compare_load_splash_started_at = float(started_at)
            elapsed = max(0.0, time.monotonic() - float(started_at))
            elapsed_text = self._format_wall_clock_elapsed(elapsed)
            detail_base = str(
                getattr(self, "_compare_load_splash_detail_base", "") or ""
            ).strip()
            detail_text = self._compose_loading_detail_with_elapsed(
                detail_base=detail_base,
                stage_key=stage_key,
                message=None,
                elapsed_text=elapsed_text,
            )
            detail_label = getattr(self, "_compare_load_splash_detail_label", None)
            if detail_label is not None:
                try:
                    detail_label.configure(text=detail_text)
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
            progress_label = getattr(self, "_compare_load_splash_progress_label", None)
            if progress_label is not None:
                progress_var = getattr(self, "_compare_load_splash_progress_var", None)
                progress_value = 0.0
                if progress_var is not None:
                    try:
                        progress_value = float(progress_var.get())
                    except Exception:
                        progress_value = 0.0
                try:
                    progress_label.configure(
                        text=self._format_loading_progress_footer(
                            progress_value,
                            elapsed_text,
                        )
                    )
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
            try:
                self._compare_load_splash_heartbeat_after_id = self.after(100, _tick)
            except Exception:
                self._compare_load_splash_heartbeat_after_id = None

        _tick()

    def _compare_update_load_splash(
        self,
        *,
        message: Optional[str] = None,
        progress: Optional[float] = None,
        detail: Optional[str] = None,
        stage_key: Optional[str] = None,
        reset: bool = False,
    ) -> None:
        """Update Compare load splash text/progress with stage-aware semantics.

        Purpose:
            Mutate Compare splash labels and determinate progress for each stage.
        Why:
            Compare load orchestrates multiple side-level phases that must report
            deterministic, monotonic progress and stage detail.
        Args:
            message: Optional splash status text.
            progress: Optional progress value in the 0..100 range.
            detail: Optional detail text shown under status.
            stage_key: Optional explicit normalized stage key.
            reset: When True, reset elapsed/progress baseline before update.
        Returns:
            None.
        Side Effects:
            Updates splash widgets/state and starts/stops heartbeat timers.
        Exceptions:
            Widget update failures are suppressed best-effort.
        """
        window = getattr(self, "_compare_load_splash_window", None)
        if window is None or not bool(getattr(window, "winfo_exists", lambda: False)()):
            return
        progress_var = getattr(self, "_compare_load_splash_progress_var", None)
        current_value = 0.0
        if progress_var is not None:
            try:
                current_value = float(progress_var.get())
            except Exception:
                current_value = 0.0
        if not math.isfinite(current_value):
            current_value = 0.0
        if reset:
            current_value = 0.0
            self._compare_load_splash_started_at = time.monotonic()
            self._compare_load_splash_detail_base = ""
        if message is not None:
            label = getattr(self, "_compare_load_splash_label", None)
            if label is not None:
                try:
                    label.configure(text=str(message).strip() or "Working...")
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
        normalized_stage = self._compare_resolve_load_splash_stage_key(
            message=message,
            stage_key=stage_key,
        )
        self._compare_load_splash_stage_key = normalized_stage
        self._compare_load_splash_detail_base = self._resolve_loading_detail_base(
            current_detail_base=getattr(self, "_compare_load_splash_detail_base", ""),
            stage_key=normalized_stage,
            message=message,
            detail=detail,
            clear_on_message=True,
        )
        if progress is not None:
            try:
                candidate_value = max(0.0, min(100.0, float(progress)))
            except Exception:
                candidate_value = 0.0
            target_value = (
                candidate_value if reset else max(current_value, candidate_value)
            )
            if progress_var is not None:
                try:
                    progress_var.set(target_value)
                    current_value = float(target_value)
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
        detail_label = getattr(self, "_compare_load_splash_detail_label", None)
        detail_base = str(
            getattr(self, "_compare_load_splash_detail_base", "") or ""
        ).strip()
        started_at = getattr(self, "_compare_load_splash_started_at", None)
        if not isinstance(started_at, (int, float)):
            started_at = time.monotonic()
            self._compare_load_splash_started_at = float(started_at)
        elapsed_text = self._format_wall_clock_elapsed(
            max(0.0, time.monotonic() - float(started_at))
        )
        composed_detail = self._compose_loading_detail_with_elapsed(
            detail_base=detail_base,
            stage_key=normalized_stage,
            message=message,
            elapsed_text=elapsed_text,
        )
        if detail_label is not None:
            try:
                detail_label.configure(text=composed_detail)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        progress_label = getattr(self, "_compare_load_splash_progress_label", None)
        if progress_label is not None:
            try:
                progress_label.configure(
                    text=self._format_loading_progress_footer(
                        current_value,
                        elapsed_text,
                    )
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        if normalized_stage in {"ready", "failed"}:
            self._compare_stop_load_splash_heartbeat()
        else:
            self._compare_start_load_splash_heartbeat()
        try:
            window.update_idletasks()
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _compare_hide_load_splash(self) -> None:
        """Hide and destroy the Compare load splash safely.

        Purpose:
            Tear down Compare splash UI and clear splash runtime references.
        Why:
            Compare load completion and failure paths must always release modal
            grabs and timer callbacks.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Stops heartbeat timers, releases modal grab, destroys splash widgets,
            and clears Compare splash state attributes.
        Exceptions:
            Teardown failures are handled best-effort.
        """
        self._compare_stop_load_splash_heartbeat()
        window = getattr(self, "_compare_load_splash_window", None)
        if window is not None:
            try:
                window.place_forget()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                window.destroy()
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
        self._compare_load_splash_window = None
        self._compare_load_splash_label = None
        self._compare_load_splash_detail_label = None
        self._compare_load_splash_progress_var = None
        self._compare_load_splash_progress_label = None
        self._compare_load_splash_stage_key = "ready"
        self._compare_load_splash_started_at = None
        self._compare_load_splash_detail_base = ""
        self._compare_load_splash_heartbeat_after_id = None

    def _compare_load_selected_profiles(self) -> None:
        """Load selected compare profiles without running comparison rendering.

        Purpose:
            Resolve selected profile names into Compare-side bundles.
        Why:
            Compare execution is now explicit; loading should stage inputs only
            while `Run Comparison` controls when rendering/table work runs.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Updates side bundle caches, refreshes diagnostics, resets Compare
            output surfaces/title metadata to manual-run placeholders, and
            persists state.
        Exceptions:
            Missing/invalid profiles are handled per side without aborting.
        """
        profile_a = str(self.compare_profile_a_var.get() or "").strip()
        profile_b = str(self.compare_profile_b_var.get() or "").strip()
        self._compare_refresh_profile_choices()
        if not bool(getattr(self, "_compare_rust_preflight_done", False)):
            try:
                self._ensure_rust_backend_for_workflow()
            except Exception:
                # Best-effort guard; Compare continues with Python fallback paths.
                pass
            self._compare_rust_preflight_done = True
        self._compare_load_diagnostics_state = {
            "A": {},
            "B": {},
            "summary": "Loading Compare profiles...",
        }
        self._compare_refresh_diagnostics_panel()
        self._compare_show_load_splash("Loading Compare Profiles")
        try:
            self._compare_update_load_splash(
                message="Initializing Compare load...",
                progress=8.0,
                stage_key="initialize",
                detail="Preparing side-by-side profile load stages.",
                reset=True,
            )

            for side_key, profile_name, progress_value in (
                ("A", profile_a, 24.0),
                ("B", profile_b, 44.0),
            ):
                panel = self._compare_panels.get(side_key) or {}
                if not profile_name:
                    panel["bundle"] = None
                    panel["title_text"] = ""
                    panel["suptitle_text"] = ""
                    panel["cycle_rows"] = []
                    panel["total_drop"] = None
                    panel["cycle_fallback_used"] = False
                    panel["cycle_rows_synthesized"] = False
                    panel["cycle_compute_backend"] = ""
                    panel["load_error_message"] = "No profile selected."
                    panel["render_success"] = False
                    panel["render_error_message"] = "No profile selected."
                    self._compare_update_side_status(side_key, "No profile selected.")
                    title_var = panel.get("title_var")
                    if isinstance(title_var, tk.StringVar):
                        title_var.set("Title: --\nSuptitle: --")
                    self._compare_update_side_diagnostics(
                        side_key,
                        profile_name="",
                        status="Not selected",
                        detail="Select a saved profile and click Load Profiles.",
                        render_success=False,
                    )
                    self._compare_log_profile_load_event(
                        side_key=side_key,
                        profile_name="",
                        load_ctx={
                            "profile_name": "",
                            "status": "not_selected",
                            "status_label": "Not selected",
                            "detail": "Select a saved profile and click Load Profiles.",
                            "dataset_path": "",
                            "bundle": None,
                        },
                    )
                    self._compare_refresh_diagnostics_panel()
                    continue

                self._compare_update_load_splash(
                    message=f"Loading Profile {side_key}...",
                    progress=progress_value,
                    stage_key=f"load_{side_key.lower()}",
                    detail=f"Resolving profile '{profile_name}'.",
                )
                load_ctx = self._compare_load_profile_bundle_for_side(
                    side_key,
                    profile_name,
                    prompt_relink=True,
                )
                self._compare_log_profile_load_event(
                    side_key=side_key,
                    profile_name=profile_name,
                    load_ctx=load_ctx,
                )
                bundle = load_ctx.get("bundle")
                ui_status = str(load_ctx.get("ui_status") or "Profile load failed.").strip()
                panel["bundle"] = bundle if isinstance(bundle, dict) else None
                if panel["bundle"] is not None:
                    self._compare_refresh_side_bundle_with_compare_overrides(side_key)
                panel["cycle_rows"] = []
                panel["total_drop"] = None
                panel["cycle_fallback_used"] = False
                panel["cycle_rows_synthesized"] = False
                panel["cycle_compute_backend"] = ""
                panel["render_success"] = False
                if panel["bundle"] is None:
                    panel["title_text"] = ""
                    panel["suptitle_text"] = ""
                    panel["load_error_message"] = ui_status
                    panel["render_error_message"] = ui_status
                    self._compare_update_side_status(side_key, ui_status)
                    title_var = panel.get("title_var")
                    if isinstance(title_var, tk.StringVar):
                        title_var.set("Title: --\nSuptitle: --")
                else:
                    title_defaults = self._compare_profile_title_defaults(
                        side_key, panel["bundle"]
                    )
                    panel["title_text"] = str(
                        title_defaults.get("title_text") or ""
                    ).strip()
                    panel["suptitle_text"] = str(
                        title_defaults.get("suptitle_text") or ""
                    ).strip()
                    panel["load_error_message"] = "Profile loaded. Click Run Comparison."
                    panel["render_error_message"] = "Profile loaded. Click Run Comparison."
                    self._compare_update_side_status(
                        side_key, "Profile loaded. Click Run Comparison."
                    )
                    title_var = panel.get("title_var")
                    if isinstance(title_var, tk.StringVar):
                        display_title = panel["title_text"] or "--"
                        display_suptitle = panel["suptitle_text"] or "--"
                        title_var.set(
                            f"Title: {display_title}\nSuptitle: {display_suptitle}"
                        )
                detail_text = str(load_ctx.get("detail") or "").strip()
                if panel["bundle"] is not None and not detail_text:
                    detail_text = "Profile loaded. Click Run Comparison to render this side."
                self._compare_update_side_diagnostics(
                    side_key,
                    profile_name=str(load_ctx.get("profile_name") or profile_name),
                    dataset_path=str(load_ctx.get("dataset_path") or ""),
                    status=str(load_ctx.get("status_label") or "Load failed"),
                    detail=detail_text,
                    render_success=False,
                )
                self._compare_refresh_diagnostics_panel()
        except Exception as exc:
            self._compare_update_load_splash(
                message="Compare load failed.",
                progress=100.0,
                stage_key="failed",
                detail=f"{type(exc).__name__}: {exc}",
            )
            self._compare_hide_load_splash()
            return

        loaded_count = sum(
            1
            for side_key in ("A", "B")
            if isinstance((self._compare_panels.get(side_key) or {}).get("bundle"), dict)
        )
        if loaded_count == 2:
            summary = "Compare profiles loaded: both sides ready. Click Run Comparison."
        elif loaded_count == 1:
            summary = "Compare profiles loaded: one side ready. Click Run Comparison."
        else:
            summary = "No compare profiles loaded. Select profiles, then click Load Profiles."
        diagnostics_state = dict(getattr(self, "_compare_load_diagnostics_state", {}) or {})
        diagnostics_state["summary"] = summary
        self._compare_load_diagnostics_state = diagnostics_state
        self._compare_refresh_diagnostics_panel()
        self._compare_reset_outputs_for_manual_run()
        self._compare_persist_state()
        self._compare_update_load_splash(
            message="Compare profiles loaded.",
            progress=100.0,
            stage_key="ready",
            detail=summary,
        )
        self._compare_hide_load_splash()

    def _compare_reset_outputs_for_manual_run(self) -> None:
        """Reset Compare outputs after load-only actions and show run placeholders.

        Purpose:
            Clear stale rendered outputs before the next explicit comparison run.
        Why:
            Loading profiles should not keep stale plots/tables visible when
            rendering now requires an explicit `Run Comparison` action.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Replaces side figures with placeholder text, clears compare cycle
            caches, refreshes side title blocks, table/yield summaries, and
            updates status chips.
        Exceptions:
            Missing widgets are handled best-effort.
        """
        panels = getattr(self, "_compare_panels", {})
        if not isinstance(panels, dict):
            return
        for side_key in ("A", "B"):
            panel = panels.get(side_key) or {}
            if not isinstance(panel, dict):
                continue
            has_bundle = isinstance(panel.get("bundle"), dict)
            load_error_message = str(panel.get("load_error_message") or "").strip()
            placeholder_text = (
                "Profile loaded. Click Run Comparison."
                if has_bundle
                else (load_error_message or "No profile selected.")
            )
            panel["cycle_rows"] = []
            panel["total_drop"] = None
            panel["cycle_fallback_used"] = False
            panel["cycle_rows_synthesized"] = False
            panel["cycle_compute_backend"] = ""
            panel["render_success"] = False
            panel["render_error_message"] = placeholder_text
            self._compare_update_side_status(side_key, placeholder_text)
            if has_bundle:
                title_defaults = self._compare_profile_title_defaults(
                    side_key, panel.get("bundle")
                )
                panel["title_text"] = str(title_defaults.get("title_text") or "").strip()
                panel["suptitle_text"] = str(
                    title_defaults.get("suptitle_text") or ""
                ).strip()
            else:
                panel["title_text"] = ""
                panel["suptitle_text"] = ""
            title_var = panel.get("title_var")
            if isinstance(title_var, tk.StringVar):
                display_title = str(panel.get("title_text") or "").strip() or "--"
                display_suptitle = str(panel.get("suptitle_text") or "").strip() or "--"
                title_var.set(f"Title: {display_title}\nSuptitle: {display_suptitle}")

            canvas = panel.get("canvas")
            widget = panel.get("widget")
            if canvas is None or widget is None:
                continue
            fig = Figure(figsize=(5.0, 3.2), dpi=100)
            ax = fig.add_subplot(111)
            ax.text(0.5, 0.5, placeholder_text, ha="center", va="center")
            ax.set_axis_off()
            try:
                fig.set_canvas(canvas)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                canvas.figure = fig
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                fig._gl260_layout_health_context = "compare"  # type: ignore[attr-defined]
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            self._finalize_matplotlib_canvas_layout(
                canvas=canvas,
                fig=fig,
                tk_widget=widget,
                keep_export_size=False,
                trigger_resize_event=True,
                force_draw=True,
            )
            panel["figure"] = fig
        self._compare_cycle_table_rows = []
        self._compare_refresh_cycle_table()
        self._compare_refresh_yield_summary()
        self._compare_update_status_chips()

    def _compare_finalize_render_diagnostics_summary(
        self, *, summary_prefix: str = "Compare run completed"
    ) -> None:
        """Finalize Compare diagnostics after one explicit comparison run.

        Purpose:
            Consolidate per-side render outcomes into diagnostics summary text.
        Why:
            Manual runs and async refresh completion both need one canonical
            diagnostics finalization path.
        Args:
            summary_prefix: Prefix label used for summary status text.
        Returns:
            None.
        Side Effects:
            Updates per-side diagnostics fields and overall summary text.
        Exceptions:
            Missing panel/diagnostic state is handled best-effort.
        """
        loaded_count = 0
        rendered_count = 0
        for side_key in ("A", "B"):
            panel = self._compare_panels.get(side_key) or {}
            if not isinstance(panel.get("bundle"), dict):
                continue
            loaded_count += 1
            cycle_count = int(len(panel.get("cycle_rows") or []))
            total_drop_value = self._compare_parse_float_entry(panel.get("total_drop"))
            cycle_fallback_used = bool(panel.get("cycle_fallback_used", False))
            cycle_rows_synthesized = bool(panel.get("cycle_rows_synthesized", False))
            cycle_compute_backend = str(panel.get("cycle_compute_backend") or "").strip()
            render_success = bool(panel.get("render_success", False))
            if render_success:
                rendered_count += 1
            status_label = "Rendered" if render_success else "Render failed"
            detail_text = str(panel.get("render_error_message") or "").strip()
            self._compare_update_side_diagnostics(
                side_key,
                status=status_label,
                detail=detail_text,
                cycle_count=cycle_count,
                total_drop_g=total_drop_value,
                render_success=render_success,
                cycle_fallback_used=cycle_fallback_used,
                cycle_rows_synthesized=cycle_rows_synthesized,
                cycle_compute_backend=cycle_compute_backend,
            )

        if loaded_count <= 0:
            summary = f"{summary_prefix}: no loaded profiles to render."
        elif rendered_count == loaded_count == 2:
            summary = f"{summary_prefix}: both profiles rendered successfully."
        elif rendered_count == loaded_count == 1:
            summary = f"{summary_prefix}: one loaded profile rendered successfully."
        elif rendered_count > 0:
            summary = (
                f"{summary_prefix}: partial success "
                f"({rendered_count}/{loaded_count} loaded profile(s) rendered)."
            )
        else:
            summary = f"{summary_prefix}: no successful profile renders."
        diagnostics_state = dict(getattr(self, "_compare_load_diagnostics_state", {}) or {})
        diagnostics_state["summary"] = summary
        self._compare_load_diagnostics_state = diagnostics_state
        self._compare_refresh_diagnostics_panel()

    def _compare_run_comparison(self) -> None:
        """Run comparison rendering for currently loaded Compare profile bundles.

        Purpose:
            Execute plot/table/yield refresh for loaded compare sides on demand.
        Why:
            Compare rendering is now explicit and should be user-triggered via
            one dedicated action rather than implicit load-side effects.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Starts async compare render work, updates diagnostics summary, and
            refreshes Compare plot/table/yield outputs on completion.
        Exceptions:
            Missing loaded profiles is handled with user-facing guidance.
        """
        panels = getattr(self, "_compare_panels", {})
        loaded_sides = [
            side_key
            for side_key in ("A", "B")
            if isinstance((panels.get(side_key) or {}).get("bundle"), dict)
        ]
        if not loaded_sides:
            try:
                messagebox.showinfo(
                    "Run Comparison",
                    "Load at least one profile first, then click Run Comparison.",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        diagnostics_state = dict(getattr(self, "_compare_load_diagnostics_state", {}) or {})
        diagnostics_state["summary"] = "Running comparison..."
        self._compare_load_diagnostics_state = diagnostics_state
        self._compare_refresh_diagnostics_panel()
        self._compare_refresh_loaded_sides_async(
            reason="manual_run",
            show_overlay=True,
            on_complete=lambda: self._compare_finalize_render_diagnostics_summary(
                summary_prefix="Compare run completed"
            ),
        )

    def _compare_build_profile_bundle_from_state(
        self,
        *,
        profile_name: str,
        profile_path: Path,
        state: Mapping[str, Any],
        dataset_path: str,
    ) -> Optional[Dict[str, Any]]:
        """Build one normalized Compare bundle from profile state and dataset path.

        Purpose:
            Convert profile payload state into a compare-ready render bundle.
        Why:
            Compare and Ledger flows both need the same isolated bundle assembly.
        Args:
            profile_name: Saved profile name associated with the payload.
            profile_path: Path to the profile JSON document.
            state: Deserialized profile workspace state.
            dataset_path: Resolved dataset path for profile data loading.
        Returns:
            Compare bundle dict (including `effective_compare_title`), or None when
            data context prep fails.
        Side Effects:
            Reads workbook sheets while preparing data context.
        Exceptions:
            Invalid state/data content returns None.
        """
        plot_settings = dict(state.get("plot_settings") or {})
        data_bundle = self._compare_build_profile_data_context(
            dataset_path=dataset_path,
            state=state,
            plot_settings=plot_settings,
        )
        if data_bundle is None:
            return None
        args_keys = (
            "min_time",
            "max_time",
            "min_y",
            "max_y",
            "twin_y_min",
            "twin_y_max",
            "deriv_y_min",
            "deriv_y_max",
            "auto_time_ticks",
            "auto_y_ticks",
            "auto_temp_ticks",
            "auto_deriv_ticks",
            "title_text",
            "suptitle_text",
            "x_major_tick",
            "x_minor_tick",
            "y_major_tick",
            "y_minor_tick",
            "temp_major_tick",
            "temp_minor_tick",
            "deriv_major_tick",
            "deriv_minor_tick",
            "enable_temp_axis",
            "enable_deriv_axis",
            "min_cycle_drop",
            "peak_prominence",
            "peak_distance",
            "peak_width",
            "show_cycle_markers_on_core_plots",
            "show_cycle_legend_on_core_plots",
            "include_moles_in_core_plot_legend",
        )
        baseline_payload = {}
        try:
            baseline_payload = self._default_profile_plot_settings_payload()
        except Exception:
            baseline_payload = {}
        if not isinstance(baseline_payload, Mapping):
            baseline_payload = {}
        resolved_args: List[Any] = []
        for key in args_keys:
            if key in plot_settings:
                resolved_args.append(copy.deepcopy(plot_settings.get(key)))
                continue
            # Compare should not inherit workspace title/suptitle text when a
            # profile omits those fields; keep them blank until profile-identity
            # fallback is applied below.
            if key in {"title_text", "suptitle_text"}:
                resolved_args.append("")
                continue
            if key in baseline_payload:
                resolved_args.append(copy.deepcopy(baseline_payload.get(key)))
                continue
            resolved_args.append(copy.deepcopy(settings.get(key)))
        safe_profile_name = str(profile_name or "").strip()
        dataset_stem = ""
        try:
            dataset_stem = Path(str(dataset_path or "")).stem.strip()
        except Exception:
            dataset_stem = ""
        effective_compare_title = self._compare_resolve_effective_profile_title(
            manual_title=str(plot_settings.get("title_text") or ""),
            state=state,
            plot_settings=plot_settings,
            data_bundle=data_bundle,
        )
        effective_compare_title = str(effective_compare_title or "").strip()
        if len(resolved_args) > 12:
            title_text = str(resolved_args[12] or "").strip()
            resolved_args[12] = (
                effective_compare_title
                or title_text
                or safe_profile_name
                or dataset_stem
                or "Profile"
            )
        if len(resolved_args) > 13:
            suptitle_text = str(resolved_args[13] or "").strip()
            resolved_args[13] = (
                suptitle_text or dataset_stem or safe_profile_name or "Profile"
            )
        return {
            "profile_name": str(profile_name or "").strip(),
            "profile_path": str(profile_path),
            "dataset_path": str(dataset_path),
            "state": dict(state or {}),
            "plot_settings": plot_settings,
            "reaction_basis": dict(state.get("reaction_basis") or {}),
            "cycle_markers": _normalize_profile_cycle_markers(
                state.get("cycle_markers")
            ),
            "plot_elements": copy.deepcopy(state.get("plot_elements") or {}),
            "layout_profiles": copy.deepcopy(state.get("layout_profiles") or {}),
            "data_ctx": data_bundle["data_ctx"],
            "df_reference": data_bundle["df_reference"],
            "sheet_key": tuple(data_bundle.get("sheet_key") or ()),
            "columns_key": tuple(data_bundle.get("columns_key") or ()),
            "prep_signature": tuple(data_bundle.get("prep_signature") or ()),
            "multi_sheet": bool(data_bundle.get("multi_sheet")),
            "effective_compare_title": effective_compare_title,
            "args": tuple(resolved_args),
            "cycle_rows": [],
            "total_drop": None,
        }

    def _compare_load_profile_bundle_for_side(
        self,
        side_key: str,
        profile_name: str,
        *,
        prompt_relink: bool,
    ) -> Dict[str, Any]:
        """Load one Compare side bundle with explicit status and dataset recovery.

        Purpose:
            Resolve one side's profile into a compare bundle plus diagnostics.
        Why:
            Compare loads must tolerate side-level failures and keep loading the
            other side while reporting clear reasons in diagnostics.
        Args:
            side_key: Compare side key ("A" or "B").
            profile_name: Saved profile name selected for this side.
            prompt_relink: When True, prompt for dataset relink if path is missing.
        Returns:
            Dict containing bundle/status/detail/profile-path diagnostics.
        Side Effects:
            Reads profile/data files and may show relink dialogs.
        Exceptions:
            Failures are captured in returned status payload.
        """
        resolved_name = str(profile_name or "").strip()
        result: Dict[str, Any] = {
            "profile_name": resolved_name,
            "dataset_path": "",
            "status_label": "Load failed",
            "status": "failed",
            "detail": "",
            "ui_status": "Profile load failed.",
            "bundle": None,
        }
        if not resolved_name:
            result["status_label"] = "Not selected"
            result["status"] = "not_selected"
            result["detail"] = "No profile selected for this side."
            result["ui_status"] = "No profile selected."
            return result

        profile_path = self._profile_path(resolved_name)
        if profile_path is None or not profile_path.exists():
            result["detail"] = f"Profile '{resolved_name}' was not found."
            result["ui_status"] = f"Profile {side_key}: profile not found."
            return result

        doc = self._read_profile_document(profile_path)
        if not isinstance(doc, dict):
            result["detail"] = f"Profile '{resolved_name}' could not be read."
            result["ui_status"] = f"Profile {side_key}: profile read failed."
            return result

        state = self._deserialize_workspace_state(doc.get("payload") or {})
        if not state:
            result["detail"] = f"Profile '{resolved_name}' payload is invalid."
            result["ui_status"] = f"Profile {side_key}: profile payload invalid."
            return result

        dataset_path = str(state.get("dataset_path") or "").strip()
        if not dataset_path or not os.path.exists(dataset_path):
            if prompt_relink:
                self._compare_update_load_splash(
                    message=f"Relinking Profile {side_key} dataset...",
                    stage_key="relink_dataset",
                    detail=f"Waiting for dataset relink for '{resolved_name}'.",
                )
                splash_window = getattr(self, "_compare_load_splash_window", None)
                # Release the splash grab while file dialogs are open so native
                # picker windows can receive focus and input.
                if splash_window is not None:
                    try:
                        splash_window.grab_release()
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting workflow.
                        pass
                try:
                    dataset_path = str(
                        self._resolve_profile_dataset_path(dataset_path) or ""
                    ).strip()
                finally:
                    if splash_window is not None and bool(
                        getattr(splash_window, "winfo_exists", lambda: False)()
                    ):
                        try:
                            splash_window.grab_set()
                        except Exception:
                            # Best-effort guard; ignore failures to avoid interrupting workflow.
                            pass
            if not dataset_path or not os.path.exists(dataset_path):
                result["detail"] = (
                    f"Dataset path could not be resolved for profile '{resolved_name}'."
                )
                result["ui_status"] = f"Profile {side_key}: dataset path unresolved."
                return result

        bundle = self._compare_build_profile_bundle_from_state(
            profile_name=resolved_name,
            profile_path=profile_path,
            state=state,
            dataset_path=dataset_path,
        )
        if not isinstance(bundle, dict):
            result["detail"] = (
                f"Data preparation failed for profile '{resolved_name}' dataset."
            )
            result["ui_status"] = f"Profile {side_key}: data preparation failed."
            return result

        result["dataset_path"] = dataset_path
        result["status_label"] = "Loaded"
        result["status"] = "loaded"
        result["detail"] = "Profile loaded successfully."
        result["ui_status"] = f"Profile {side_key}: loaded '{resolved_name}'."
        result["bundle"] = bundle
        return result

    def _compare_load_profile_bundle(
        self, profile_name: str
    ) -> Optional[Dict[str, Any]]:
        """Load and normalize one profile payload for Compare rendering.

        Purpose:
            Build an isolated compare bundle from a saved profile.
        Why:
            Compare rendering should not mutate active workspace state.
        Args:
            profile_name: Saved profile name to load.
        Returns:
            Compare bundle dict, or None when loading/prep fails.
        Side Effects:
            Reads profile file and source dataset from disk.
        Exceptions:
            Invalid profile/state/data paths return None.
        """
        load_ctx = self._compare_load_profile_bundle_for_side(
            "A",
            profile_name,
            prompt_relink=False,
        )
        bundle = load_ctx.get("bundle")
        return dict(bundle) if isinstance(bundle, dict) else None

    def _compare_build_profile_data_context(
        self,
        *,
        dataset_path: str,
        state: Mapping[str, Any],
        plot_settings: Mapping[str, Any],
    ) -> Optional[Dict[str, Any]]:
        """Build prepared data context payload for one Compare profile.

        Purpose:
            Convert profile state + dataset into render-ready data context.
        Why:
            Compare must reuse the combined-render context pipeline with profile
            local data, columns, and sheet mode.
        Args:
            dataset_path: Source workbook path from profile payload.
            state: Deserialized profile workspace state.
            plot_settings: Profile plot settings snapshot.
        Returns:
            Context dict with data and fingerprint metadata, or None on failure.
        Side Effects:
            Reads source workbook sheets for selected profile mode.
        Exceptions:
            Data loading/preparation failures return None.
        """
        multi_sheet = bool(state.get("multi_sheet_enabled"))
        if multi_sheet:
            return self._compare_build_multi_sheet_data_context(
                dataset_path=dataset_path,
                state=state,
                plot_settings=plot_settings,
            )
        return self._compare_build_single_sheet_data_context(
            dataset_path=dataset_path,
            state=state,
            plot_settings=plot_settings,
        )

    def _compare_build_single_sheet_data_context(
        self,
        *,
        dataset_path: str,
        state: Mapping[str, Any],
        plot_settings: Mapping[str, Any],
    ) -> Optional[Dict[str, Any]]:
        """Build Compare data context for single-sheet profile payloads.

        Purpose:
            Prepare selected-series arrays for single-sheet compare rendering.
        Why:
            Single-sheet profiles need deterministic data extraction that matches
            existing plotting assumptions.
        Args:
            dataset_path: Source workbook path.
            state: Profile state payload.
            plot_settings: Profile plot settings mapping.
        Returns:
            Data-context payload dict, or None when loading/prep fails.
        Side Effects:
            Reads one sheet from the source workbook.
        Exceptions:
            Missing sheets/columns or prep failures return None.
        """
        sheet_name = str(state.get("selected_sheet") or "").strip()
        if not sheet_name:
            try:
                names = _read_excel_sheet_names(dataset_path)
                sheet_name = names[0] if names else ""
            except Exception:
                sheet_name = ""
        if not sheet_name:
            return None
        try:
            df = _read_excel_dataframe(dataset_path, sheet_name)
        except Exception:
            return None

        columns_snapshot = dict(state.get("column_assignments") or {})
        selected_columns = dict(columns_snapshot)
        series_map: Dict[str, Any] = {}

        def _numeric_series(frame: pd.DataFrame, colname: str) -> Optional[pd.Series]:
            """Return one numeric series from column name."""
            if not colname or colname == "None" or colname not in frame.columns:
                return None
            try:
                return pd.to_numeric(frame[colname], errors="coerce")
            except Exception:
                return None

        dt_col = str(columns_snapshot.get("dt") or "").strip()
        x_col = str(columns_snapshot.get("x") or "").strip()
        if x_col and x_col in df.columns:
            series_map["x"] = _numeric_series(df, x_col)
        elif dt_col and dt_col in df.columns:
            try:
                dt_values = pd.to_datetime(df[dt_col], errors="coerce")
                t0 = dt_values.min()
                if pd.notna(t0):
                    elapsed_days = (dt_values - t0).dt.total_seconds() / 86400.0
                    series_map["x"] = pd.to_numeric(elapsed_days, errors="coerce")
                    selected_columns["x"] = self._elapsed_axis_label()
                else:
                    series_map["x"] = None
            except Exception:
                series_map["x"] = None
        else:
            series_map["x"] = None

        for key in ("y1", "y2", "y3", "z", "z2"):
            col = str(columns_snapshot.get(key) or "").strip()
            series_map[key] = _numeric_series(df, col)

        cycle_temp_col = str(
            plot_settings.get(
                "cycle_temp_column",
                settings.get("cycle_temp_column", CYCLE_TEMP_DEFAULT_LABEL),
            )
            or ""
        )
        cycle_temp_series = (
            _numeric_series(df, cycle_temp_col)
            if cycle_temp_col and cycle_temp_col != CYCLE_TEMP_DEFAULT_LABEL
            else None
        )
        payload = self._compare_build_series_payload_from_series_map(
            selected_columns=selected_columns,
            series_map=series_map,
            cycle_temp_column=cycle_temp_col,
            cycle_temp_series=cycle_temp_series,
        )
        return {
            "data_ctx": payload,
            "df_reference": df,
            "sheet_key": (sheet_name,),
            "columns_key": tuple(
                sorted(
                    (str(key), str(columns_snapshot.get(key) or ""))
                    for key in columns_snapshot
                )
            ),
            "prep_signature": (),
            "multi_sheet": False,
        }

    def _compare_build_multi_sheet_data_context(
        self,
        *,
        dataset_path: str,
        state: Mapping[str, Any],
        plot_settings: Mapping[str, Any],
    ) -> Optional[Dict[str, Any]]:
        """Build Compare data context for multi-sheet profile payloads.

        Purpose:
            Prepare stitched series arrays across ordered profile sheets.
        Why:
            Multi-sheet profiles require one unified series context for combined
            rendering and cycle segmentation.
        Args:
            dataset_path: Source workbook path.
            state: Profile state payload.
            plot_settings: Profile plot settings mapping.
        Returns:
            Data-context payload dict, or None on read/prep failure.
        Side Effects:
            Reads multiple workbook sheets and concatenates selected series.
        Exceptions:
            Missing sheets/columns or prep failures return None.
        """
        selected_sheets = [
            str(name) for name in (state.get("selected_sheets") or []) if name
        ]
        if not selected_sheets:
            return self._compare_build_single_sheet_data_context(
                dataset_path=dataset_path,
                state=state,
                plot_settings=plot_settings,
            )
        columns_snapshot = dict(state.get("column_assignments") or {})
        per_sheet_map = dict(state.get("per_sheet_mapping") or {})
        sheet_dfs: Dict[str, pd.DataFrame] = {}
        for sheet_name in selected_sheets:
            try:
                sheet_dfs[sheet_name] = _read_excel_dataframe(dataset_path, sheet_name)
            except Exception:
                return None

        def _effective_map(sheet_name: str) -> Dict[str, str]:
            """Merge global and per-sheet mapping dictionaries."""
            merged = dict(columns_snapshot)
            override = per_sheet_map.get(sheet_name)
            if isinstance(override, dict):
                for key, value in override.items():
                    value_s = str(value or "").strip()
                    if value_s:
                        merged[str(key)] = value_s
            return merged

        elapsed_unit_seconds = float(
            ELAPSED_UNIT_SECONDS.get(self._elapsed_unit_label(), 86400.0)
        )
        dt_series_parts: Dict[str, pd.Series] = {}
        t0_candidates: List[pd.Timestamp] = []
        for sheet_name in selected_sheets:
            frame = sheet_dfs[sheet_name]
            mapping = _effective_map(sheet_name)
            dt_col = str(mapping.get("dt") or "").strip()
            if dt_col and dt_col in frame.columns:
                dt_series = pd.to_datetime(frame[dt_col], errors="coerce")
            else:
                dt_series = pd.Series([pd.NaT] * len(frame))
            dt_series_parts[sheet_name] = dt_series
            dt_min = dt_series.min()
            if pd.notna(dt_min):
                t0_candidates.append(dt_min)
        stitched_uses_elapsed = bool(t0_candidates)
        t0_value = min(t0_candidates) if t0_candidates else None

        series_map: Dict[str, Any] = {}
        selected_columns = dict(columns_snapshot)
        if stitched_uses_elapsed:
            selected_columns["x"] = self._elapsed_axis_label()

        for key in ("x", "y1", "y2", "y3", "z", "z2"):
            parts: List[pd.Series] = []
            for idx, sheet_name in enumerate(selected_sheets):
                frame = sheet_dfs[sheet_name]
                mapping = _effective_map(sheet_name)
                if key == "x" and stitched_uses_elapsed and t0_value is not None:
                    dt_values = dt_series_parts.get(sheet_name)
                    try:
                        elapsed_values = (
                            (dt_values - t0_value).dt.total_seconds()
                            / elapsed_unit_seconds
                        )
                        part = pd.to_numeric(elapsed_values, errors="coerce")
                    except Exception:
                        part = pd.Series([np.nan] * len(frame), dtype=float)
                else:
                    col_name = str(mapping.get(key) or "").strip()
                    if (
                        not col_name
                        or col_name == "None"
                        or col_name not in frame.columns
                    ):
                        part = pd.Series([np.nan] * len(frame), dtype=float)
                    else:
                        try:
                            part = pd.to_numeric(frame[col_name], errors="coerce")
                        except Exception:
                            part = pd.Series([np.nan] * len(frame), dtype=float)
                parts.append(part)
                if idx < len(selected_sheets) - 1:
                    parts.append(pd.Series([np.nan], dtype=float))
            series_map[key] = pd.concat(parts, ignore_index=True) if parts else None

        cycle_temp_col = str(
            plot_settings.get(
                "cycle_temp_column",
                settings.get("cycle_temp_column", CYCLE_TEMP_DEFAULT_LABEL),
            )
            or ""
        )
        cycle_temp_series = None
        if cycle_temp_col and cycle_temp_col != CYCLE_TEMP_DEFAULT_LABEL:
            temp_parts: List[pd.Series] = []
            for idx, sheet_name in enumerate(selected_sheets):
                frame = sheet_dfs[sheet_name]
                if cycle_temp_col in frame.columns:
                    part = pd.to_numeric(frame[cycle_temp_col], errors="coerce")
                else:
                    part = pd.Series([np.nan] * len(frame), dtype=float)
                temp_parts.append(part)
                if idx < len(selected_sheets) - 1:
                    temp_parts.append(pd.Series([np.nan], dtype=float))
            cycle_temp_series = pd.concat(temp_parts, ignore_index=True)

        payload = self._compare_build_series_payload_from_series_map(
            selected_columns=selected_columns,
            series_map=series_map,
            cycle_temp_column=cycle_temp_col,
            cycle_temp_series=cycle_temp_series,
        )
        df_reference = pd.DataFrame({"x": series_map.get("x")})
        return {
            "data_ctx": payload,
            "df_reference": df_reference,
            "sheet_key": tuple(selected_sheets),
            "columns_key": tuple(
                sorted(
                    (str(key), str(columns_snapshot.get(key) or ""))
                    for key in columns_snapshot
                )
            ),
            "prep_signature": (),
            "multi_sheet": True,
        }

    def _compare_build_series_payload_from_series_map(
        self,
        *,
        selected_columns: Mapping[str, Any],
        series_map: Mapping[str, Any],
        cycle_temp_column: str,
        cycle_temp_series: Optional[pd.Series],
    ) -> Dict[str, Any]:
        """Build compare `data_ctx` payload from resolved series arrays.

        Purpose:
            Assemble the canonical data context consumed by render/cycle helpers.
        Why:
            Compare rendering and cycle metrics share one expected payload schema.
        Args:
            selected_columns: Selected column labels map.
            series_map: Prepared series map for x/y/z channels.
            cycle_temp_column: Cycle temperature column label.
            cycle_temp_series: Optional cycle temperature series payload.
        Returns:
            `data_ctx` dict containing typed arrays and metadata.
        Side Effects:
            None.
        Exceptions:
            Invalid arrays are normalized to safe fallback values.
        """
        requested_workers_raw = None
        parallel_enabled_raw = None
        if hasattr(self, "_dev_worker_threads_var"):
            try:
                requested_workers_raw = int(self._dev_worker_threads_var.get())
            except Exception:
                requested_workers_raw = None
        if hasattr(self, "_dev_parallel_compute_var"):
            try:
                parallel_enabled_raw = bool(self._dev_parallel_compute_var.get())
            except Exception:
                parallel_enabled_raw = None
        requested_workers_value, parallel_enabled_value = _resolve_cycle_parallel_controls(
            requested_workers=requested_workers_raw,
            parallel_enabled=parallel_enabled_raw,
        )
        payload = {
            "selected_columns": dict(selected_columns or {}),
            "series": dict(series_map or {}),
            "cycle_temp_column": str(cycle_temp_column or CYCLE_TEMP_DEFAULT_LABEL),
            "cycle_temp_series": cycle_temp_series,
            "series_prepare_workers": 1,
            "series_prepare_parallel": False,
            "series_prepare_requested_workers": int(max(1, requested_workers_value)),
            "series_prepare_parallel_enabled": bool(parallel_enabled_value),
        }
        series_np: Dict[str, Any] = {}
        series_nan_mask: Dict[str, Any] = {}
        series_valid_mask: Dict[str, Any] = {}
        for key in ("x", "y1", "y2", "y3", "z", "z2"):
            values = payload["series"].get(key)
            if values is None:
                series_np[key] = None
                continue
            try:
                arr = np.asarray(values, dtype=float)
            except Exception:
                try:
                    arr = np.asarray(values)
                except Exception:
                    arr = None
            series_np[key] = arr
            if arr is None:
                continue
            try:
                nan_mask = np.asarray(pd.isna(arr), dtype=bool).reshape(-1)
            except Exception:
                nan_mask = None
            if nan_mask is not None:
                series_nan_mask[key] = nan_mask
                series_valid_mask[key] = ~nan_mask
        payload["series_np"] = series_np
        payload["series_nan_mask"] = series_nan_mask
        payload["series_valid_mask"] = series_valid_mask
        x_values = payload["series"].get("x")
        payload["data_len"] = int(len(x_values)) if x_values is not None else 0
        payload["volume"] = settings.get("vessel_volume", 1.0)
        payload["a_const"] = settings.get("vdw_a", 1.39)
        payload["b_const"] = settings.get("vdw_b", 0.0391)
        payload["starting_mass_g"] = settings.get("starting_material_mass_g", 0.0)
        payload["starting_material_mass_g"] = payload["starting_mass_g"]
        payload["gas_molar_mass"] = settings.get(
            "vdw_gas_molar_mass", DEFAULT_GAS_MOLAR_MASS
        )
        payload["starting_material_display_name"] = str(
            settings.get("starting_material_display_name")
            or settings.get("product_name")
            or ""
        ).strip()
        payload["starting_material_display_note"] = str(
            settings.get("starting_material_display_note") or ""
        ).strip()
        payload["starting_material_name"] = payload["starting_material_display_name"]
        payload["product_name"] = payload["starting_material_display_name"]
        payload["starting_material_formula"] = str(
            settings.get(
                "starting_material_formula", DEFAULT_STARTING_MATERIAL_FORMULA
            )
            or ""
        )
        payload["product_formula"] = payload["starting_material_formula"]
        payload["starting_material_mw_g_mol"] = settings.get("starting_material_mw_g_mol")
        payload["product_molar_mass"] = payload["starting_material_mw_g_mol"]
        payload["stoich_mol_gas_per_mol_starting"] = settings.get(
            "stoich_mol_gas_per_mol_starting"
        )
        return payload

    def _compare_cycle_snapshot_from_plot_settings(
        self,
        plot_settings: Mapping[str, Any],
        *,
        side_key: Optional[str] = None,
        profile_cycle_markers: Optional[Mapping[str, Any]] = None,
    ) -> Dict[str, Any]:
        """Build cycle-analysis snapshot from profile plot settings.

        Purpose:
            Derive cycle-detection options for Compare-side metric computation.
        Why:
            Compare should respect the profile's persisted cycle detection settings.
        Args:
            plot_settings: Profile plot settings mapping.
        Returns:
            Snapshot dict compatible with `_resolve_cycle_context`.
        Side Effects:
            None.
        Exceptions:
            Invalid numeric values fall back to safe defaults.
        """
        requested_workers_raw = None
        parallel_enabled_raw = None
        if hasattr(self, "_dev_worker_threads_var"):
            try:
                requested_workers_raw = int(self._dev_worker_threads_var.get())
            except Exception:
                requested_workers_raw = None
        if hasattr(self, "_dev_parallel_compute_var"):
            try:
                parallel_enabled_raw = bool(self._dev_parallel_compute_var.get())
            except Exception:
                parallel_enabled_raw = None
        requested_workers_value, parallel_enabled_value = _resolve_cycle_parallel_controls(
            requested_workers=requested_workers_raw,
            parallel_enabled=parallel_enabled_raw,
        )
        def _safe_index_set(raw_values: Any) -> Set[int]:
            """Normalize one marker-index payload into a safe integer set."""
            if not isinstance(raw_values, (list, tuple, set)):
                return set()
            safe: Set[int] = set()
            # Iterate over marker values so malformed payload entries are ignored.
            for raw in raw_values:
                try:
                    idx = int(raw)
                except Exception:
                    continue
                if idx < 0:
                    continue
                safe.add(idx)
            return safe

        auto_enabled = bool(
            plot_settings.get(
                "cycle_auto_detect_enabled",
                settings.get("cycle_auto_detect_enabled", True),
            )
        )
        use_auto_markers_in_manual_mode = bool(
            plot_settings.get(
                "cycle_use_auto_markers_in_manual_edit_mode",
                settings.get("cycle_use_auto_markers_in_manual_edit_mode", True),
            )
        )
        prominence = float(
            plot_settings.get("peak_prominence", settings.get("peak_prominence", 1.0))
            or 1.0
        )
        distance = max(
            1,
            int(plot_settings.get("peak_distance", settings.get("peak_distance", 1)) or 1),
        )
        width = max(
            1,
            int(plot_settings.get("peak_width", settings.get("peak_width", 1)) or 1),
        )
        smoothing_window = _normalize_cycle_window(
            plot_settings.get(
                "peak_smoothing_window", settings.get("peak_smoothing_window", 1)
            )
        )
        manual_snap_radius = _normalize_cycle_window(
            plot_settings.get(
                "cycle_manual_snap_radius",
                settings.get("cycle_manual_snap_radius", 0),
            ),
            allow_zero=True,
        )
        auto_refine_radius = max(
            1,
            int(
                plot_settings.get(
                    "cycle_auto_refine_radius",
                    settings.get("cycle_auto_refine_radius", 6),
                )
                or 6
            ),
        )
        min_cycle_drop = float(
            plot_settings.get("min_cycle_drop", settings.get("min_cycle_drop", 0.0))
            or 0.0
        )
        add_peaks = _safe_index_set(
            plot_settings.get("cycle_manual_add_peaks", settings.get("cycle_manual_add_peaks", []))
        )
        add_troughs = _safe_index_set(
            plot_settings.get(
                "cycle_manual_add_troughs", settings.get("cycle_manual_add_troughs", [])
            )
        )
        rm_peaks = _safe_index_set(
            plot_settings.get(
                "cycle_manual_remove_peaks", settings.get("cycle_manual_remove_peaks", [])
            )
        )
        rm_troughs = _safe_index_set(
            plot_settings.get(
                "cycle_manual_remove_troughs",
                settings.get("cycle_manual_remove_troughs", []),
            )
        )
        manual_revision = 0

        profile_marker_payload = _normalize_profile_cycle_markers(profile_cycle_markers)
        compare_marker_payload = None
        if isinstance(side_key, str) and side_key in {"A", "B"}:
            compare_marker_payload = _normalize_profile_cycle_markers(
                (getattr(self, "_compare_marker_overrides", {}) or {}).get(side_key)
            )
        effective_marker_payload = compare_marker_payload or profile_marker_payload
        if effective_marker_payload is not None:
            auto_enabled = bool(
                effective_marker_payload.get("auto_detect_enabled", auto_enabled)
            )
            use_auto_markers_in_manual_mode = bool(
                effective_marker_payload.get(
                    "use_auto_markers_in_manual_mode",
                    use_auto_markers_in_manual_mode,
                )
            )
            add_peaks = set(effective_marker_payload.get("add_peaks") or [])
            add_troughs = set(effective_marker_payload.get("add_troughs") or [])
            rm_peaks = set(effective_marker_payload.get("rm_peaks") or [])
            rm_troughs = set(effective_marker_payload.get("rm_troughs") or [])
            manual_revision = int(effective_marker_payload.get("manual_revision") or 0)
            thresholds_payload = dict(effective_marker_payload.get("thresholds") or {})
            if thresholds_payload.get("min_cycle_drop") is not None:
                min_cycle_drop = float(thresholds_payload["min_cycle_drop"])
            if thresholds_payload.get("pk_prominence") is not None:
                prominence = float(thresholds_payload["pk_prominence"])
            if thresholds_payload.get("pk_distance") is not None:
                distance = max(1, int(thresholds_payload["pk_distance"]))
            if thresholds_payload.get("pk_width") is not None:
                width = max(1, int(thresholds_payload["pk_width"]))
            if thresholds_payload.get("pk_smoothing_window") is not None:
                smoothing_window = _normalize_cycle_window(
                    thresholds_payload["pk_smoothing_window"]
                )
            if thresholds_payload.get("manual_snap_radius") is not None:
                manual_snap_radius = _normalize_cycle_window(
                    thresholds_payload["manual_snap_radius"], allow_zero=True
                )
            if thresholds_payload.get("auto_refine_radius") is not None:
                auto_refine_radius = max(
                    1, int(thresholds_payload["auto_refine_radius"] or auto_refine_radius)
                )

        return {
            "auto_enabled": bool(auto_enabled),
            "use_auto_markers_in_manual_mode": bool(use_auto_markers_in_manual_mode),
            "prominence": float(prominence),
            "distance": int(distance),
            "width": int(width),
            "smoothing_window": int(smoothing_window),
            "manual_snap_radius": int(manual_snap_radius),
            "auto_refine_radius": int(auto_refine_radius),
            "min_cycle_drop": float(min_cycle_drop),
            "ignore_min_drop": bool(plot_settings.get("ignore_min_drop", False)),
            "manual_revision": int(max(0, manual_revision)),
            "auto_peaks": set(),
            "auto_troughs": set(),
            "add_peaks": set(add_peaks),
            "add_troughs": set(add_troughs),
            "rm_peaks": set(rm_peaks),
            "rm_troughs": set(rm_troughs),
            "requested_workers": int(max(1, requested_workers_value)),
            "parallel_enabled": bool(parallel_enabled_value),
            "runtime_no_gil": bool(_is_runtime_gil_disabled()),
            "cycle_mask": None,
        }

    def _compare_synthesize_cycle_rows_from_analysis_payload(
        self,
        analysis_payload: Mapping[str, Any],
        *,
        gas_molar_mass: Optional[float],
    ) -> List[Dict[str, Any]]:
        """Synthesize cycle-transfer rows from analysis per-cycle payload rows.

        Purpose:
            Rebuild compare table-compatible cycle transfer rows when direct
            transfer rows are absent from cycle overlay payloads.
        Why:
            Some payload variants persist only per-cycle moles statistics, which
            left compare uptake rows empty despite valid cycle analysis data.
        Args:
            analysis_payload: Cycle overlay analysis payload mapping.
            gas_molar_mass: Optional gas molar mass (g/mol) for mass conversion.
        Returns:
            List of synthesized cycle-transfer style rows.
        Side Effects:
            None.
        Exceptions:
            Invalid rows are skipped safely.
        """
        per_cycle_rows = list(
            (analysis_payload or {}).get("per_cycle") or []
        )
        if not per_cycle_rows:
            return []
        try:
            gas_mw = float(gas_molar_mass)
        except Exception:
            gas_mw = float("nan")
        if not math.isfinite(gas_mw) or gas_mw <= 0.0:
            gas_mw = float("nan")
        cumulative_moles = 0.0
        synthesized: List[Dict[str, Any]] = []
        # Reconstruct transfer-like rows so compare table logic can stay shared.
        for idx, row in enumerate(per_cycle_rows, start=1):
            if not isinstance(row, Mapping):
                continue
            try:
                n_vdw = float(row.get("n_vdw", float("nan")))
            except Exception:
                n_vdw = float("nan")
            try:
                n_ideal = float(row.get("n_ideal", float("nan")))
            except Exception:
                n_ideal = float("nan")
            use_vdw = math.isfinite(n_vdw) and n_vdw >= 0.0
            selected_moles = n_vdw if use_vdw else n_ideal
            if not math.isfinite(selected_moles) or selected_moles < 0.0:
                selected_moles = float("nan")
            if math.isfinite(selected_moles):
                cumulative_moles += selected_moles
            selected_mass = (
                (selected_moles * gas_mw)
                if (math.isfinite(selected_moles) and math.isfinite(gas_mw))
                else None
            )
            cumulative_mass = (
                cumulative_moles * gas_mw if math.isfinite(gas_mw) else None
            )
            synthesized.append(
                {
                    "cycle_id": int(idx),
                    "moles_basis": "vdw" if use_vdw else "ideal",
                    "moles_ideal": n_ideal if math.isfinite(n_ideal) else None,
                    "moles_vdw": n_vdw if math.isfinite(n_vdw) else None,
                    "selected_moles": (
                        selected_moles if math.isfinite(selected_moles) else None
                    ),
                    "selected_mass_g": selected_mass,
                    "cumulative_moles": cumulative_moles,
                    "cumulative_co2_moles": cumulative_moles,
                    "cumulative_co2_mass_g": cumulative_mass,
                    "delta_pressure_psi": row.get("deltaP"),
                    "mean_temperature_c": row.get("T_mean_C"),
                }
            )
        return synthesized

    def _compare_extract_cycle_rows_from_overlay(
        self,
        cycle_overlay: Mapping[str, Any],
        *,
        data_ctx: Optional[Mapping[str, Any]] = None,
    ) -> Tuple[List[Dict[str, Any]], bool]:
        """Extract compare cycle rows from overlay payload with synthesis fallback.

        Purpose:
            Resolve cycle rows for compare table generation from mixed overlay
            payload schemas.
        Why:
            Compare must handle both direct transfer-row payloads and analysis-only
            payload variants that omit `cycle_transfer`.
        Args:
            cycle_overlay: Cycle overlay mapping from cycle context resolution.
            data_ctx: Optional prepared data context used for gas MW fallback.
        Returns:
            Tuple of `(cycle_rows, synthesized_flag)`.
        Side Effects:
            None.
        Exceptions:
            Invalid overlay payloads return an empty result.
        """
        if not isinstance(cycle_overlay, Mapping):
            return [], False
        payload = cycle_overlay.get("payload") or {}
        cycle_rows = list(payload.get("cycle_transfer") or [])
        if cycle_rows:
            return cycle_rows, False
        analysis_payload = cycle_overlay.get("analysis_payload") or {}
        gas_molar_mass = payload.get("gas_molar_mass")
        if gas_molar_mass in (None, "") and isinstance(data_ctx, Mapping):
            gas_molar_mass = data_ctx.get("gas_molar_mass")
        synthesized = self._compare_synthesize_cycle_rows_from_analysis_payload(
            analysis_payload,
            gas_molar_mass=gas_molar_mass,
        )
        return synthesized, bool(synthesized)

    def _compare_build_render_context_from_bundle(
        self,
        bundle: Dict[str, Any],
        *,
        side_key: Optional[str] = None,
    ) -> Tuple[RenderContext, List[Dict[str, Any]], Optional[float], Dict[str, Any]]:
        """Build render context and cycle-transfer payload for one compare bundle.

        Purpose:
            Produce full render context needed by combined display rendering.
        Why:
            Compare panes need isolated contexts derived from each profile bundle.
        Args:
            bundle: Compare profile bundle.
        Returns:
            Tuple of render context, cycle-transfer rows, total uptake value, and
            cycle extraction diagnostics metadata.
        Side Effects:
            Computes cycle context/overlays via shared cycle resolver.
        Exceptions:
            Context-resolution failures propagate to caller for pane-level handling.
        """
        data_ctx = bundle.get("data_ctx") or {}
        plot_settings = bundle.get("plot_settings") or {}
        fingerprint = DataFingerprint(
            file_path=str(bundle.get("dataset_path") or ""),
            sheet_key=tuple(bundle.get("sheet_key") or ()),
            columns_key=tuple(bundle.get("columns_key") or ()),
            cycle_temp_column=str(
                data_ctx.get("cycle_temp_column", CYCLE_TEMP_DEFAULT_LABEL)
                or CYCLE_TEMP_DEFAULT_LABEL
            ),
            elapsed_unit=str(self._elapsed_unit_label() or ""),
            multi_sheet=bool(bundle.get("multi_sheet", False)),
            prep_signature=tuple(bundle.get("prep_signature") or ()),
        )
        snapshot = self._compare_cycle_snapshot_from_plot_settings(
            plot_settings,
            side_key=side_key,
            profile_cycle_markers=bundle.get("cycle_markers"),
        )
        data_len = int(data_ctx.get("data_len") or 0)
        if data_len <= 0:
            x_values = (data_ctx.get("series_np") or {}).get("x")
            if x_values is not None:
                try:
                    data_len = int(np.asarray(x_values).size)
                except Exception:
                    data_len = 0
        # Compare must never inherit the main-tab cycle mask; always provide an
        # explicit full-range mask for this side's profile-local data context.
        snapshot["cycle_mask"] = (
            np.ones(data_len, dtype=bool) if data_len > 0 else np.zeros(0, dtype=bool)
        )
        cycle_ctx, overlay_ctx = self._resolve_cycle_context(
            data_ctx,
            fingerprint,
            perf=None,
            snapshot=snapshot,
        )
        cycle_overlay = (overlay_ctx or {}).get("cycle_overlay")
        cycle_rows, synthesized_rows = self._compare_extract_cycle_rows_from_overlay(
            cycle_overlay or {},
            data_ctx=data_ctx,
        )
        cycle_fallback_used = False
        if not cycle_rows:
            # Force one compare-local auto-detect retry when no rows are produced.
            fallback_snapshot = dict(snapshot)
            fallback_snapshot["auto_enabled"] = True
            fallback_snapshot["use_auto_markers_in_manual_mode"] = True
            fallback_snapshot["add_peaks"] = set()
            fallback_snapshot["add_troughs"] = set()
            fallback_snapshot["rm_peaks"] = set()
            fallback_snapshot["rm_troughs"] = set()
            fallback_snapshot["manual_revision"] = 0
            cycle_ctx_fallback, overlay_ctx_fallback = self._resolve_cycle_context(
                data_ctx,
                fingerprint,
                perf=None,
                snapshot=fallback_snapshot,
            )
            cycle_overlay_fallback = (overlay_ctx_fallback or {}).get("cycle_overlay")
            fallback_rows, fallback_synthesized = self._compare_extract_cycle_rows_from_overlay(
                cycle_overlay_fallback or {},
                data_ctx=data_ctx,
            )
            if fallback_rows:
                cycle_fallback_used = True
                synthesized_rows = bool(fallback_synthesized)
                cycle_rows = list(fallback_rows)
                cycle_ctx = cycle_ctx_fallback
                overlay_ctx = overlay_ctx_fallback
                cycle_overlay = cycle_overlay_fallback

        args = tuple(bundle.get("args") or ())
        show_cycle_markers = bool(args[-3]) if len(args) >= 3 else False
        compare_state = _normalize_compare_tab_settings(settings.get("compare_tab"))
        show_main_legend = bool(
            self.compare_show_main_legend_var.get()
            if hasattr(self, "compare_show_main_legend_var")
            else compare_state.get("show_main_legend", True)
        )
        show_cycle_legend = bool(
            self.compare_show_cycle_legend_var.get()
            if hasattr(self, "compare_show_cycle_legend_var")
            else compare_state.get("show_cycle_legend", True)
        )
        include_moles = bool(args[-1]) if len(args) >= 1 else False
        overlay_ctx = dict(overlay_ctx or {})
        overlay_ctx["markers"] = cycle_overlay if show_cycle_markers else None
        overlay_ctx["cycle_legend"] = cycle_overlay if show_cycle_legend else None
        overlay_ctx["moles_summary"] = (
            overlay_ctx.get("moles_summary") if include_moles else None
        )
        cycle_payload = (
            dict(cycle_overlay.get("payload") or {})
            if isinstance(cycle_overlay, Mapping)
            else {}
        )
        segmentation_backend = str(
            cycle_ctx.get("segmentation_backend")
            or cycle_payload.get("segmentation_backend")
            or "python"
        ).strip().lower()
        metrics_backend = str(
            cycle_ctx.get("metrics_backend")
            or cycle_payload.get("metrics_backend")
            or "python"
        ).strip().lower()
        cycle_compute_backend = str(
            cycle_ctx.get("cycle_compute_backend")
            or cycle_payload.get("cycle_compute_backend")
            or (
                "rust"
                if (segmentation_backend == "rust" or metrics_backend == "rust")
                else "python"
            )
        ).strip().lower()
        gates_ctx = {
            "show_cycle_markers": show_cycle_markers,
            "show_main_legend": show_main_legend,
            "show_cycle_legend": show_cycle_legend,
            "include_moles": include_moles,
        }
        scatter_config = {
            "enabled": bool(
                plot_settings.get(
                    "scatter_enabled", settings.get("scatter_enabled", False)
                )
            ),
            "marker": str(
                plot_settings.get("scatter_marker", settings.get("scatter_marker", "o"))
                or "o"
            ),
            "size": float(
                plot_settings.get("scatter_size", settings.get("scatter_size", 24.0))
                or 24.0
            ),
            "color": str(
                plot_settings.get("scatter_color", settings.get("scatter_color", "")) or ""
            ).strip(),
            "alpha": float(
                plot_settings.get("scatter_alpha", settings.get("scatter_alpha", 1.0))
                or 1.0
            ),
            "edgecolor": str(
                plot_settings.get(
                    "scatter_edgecolor", settings.get("scatter_edgecolor", "")
                )
                or ""
            ).strip(),
            "linewidth": float(
                plot_settings.get(
                    "scatter_linewidth", settings.get("scatter_linewidth", 0.0)
                )
                or 0.0
            ),
            "linestyle": "",
        }
        render_ctx = RenderContext(
            data_ctx=data_ctx,
            cycle_ctx=cycle_ctx,
            overlay_ctx=overlay_ctx,
            gates_ctx=gates_ctx,
            style_ctx={
                "scatter_config": scatter_config,
                "scatter_series_configs": self._sanitize_series_settings_dict(
                    plot_settings.get("scatter_series")
                ),
                "font_family": settings.get("font_family"),
                "core_legend_fontsize": plot_settings.get(
                    "core_legend_fontsize", settings.get("core_legend_fontsize")
                ),
                "core_cycle_legend_fontsize": plot_settings.get(
                    "core_cycle_legend_fontsize",
                    settings.get("core_cycle_legend_fontsize"),
                ),
                "core_plot_render_profiles": copy.deepcopy(
                    plot_settings.get("core_plot_render_profiles")
                    or settings.get("core_plot_render_profiles")
                    or _get_core_plot_render_profiles()
                ),
            },
            layout_ctx={
                "plot_id": "fig_combined_triple_axis",
                "profile": _get_layout_profile("fig_combined_triple_axis"),
                "target": "display",
            },
            plot_elements_ctx={
                "plot_id": "fig_combined_triple_axis",
                "elements": {},
            },
        )
        total_drop = None
        if isinstance(cycle_overlay, dict):
            try:
                total_drop = float(cycle_overlay.get("total_drop", 0.0))
            except Exception:
                total_drop = None
        if total_drop is None and cycle_rows:
            last_row = dict(cycle_rows[-1] or {})
            total_drop = self._compare_cycle_cumulative_mass_value(last_row)
        metadata = {
            "cycle_fallback_used": bool(cycle_fallback_used),
            "cycle_rows_synthesized": bool(synthesized_rows),
            "cycle_compute_backend": cycle_compute_backend,
            "segmentation_backend": segmentation_backend,
            "metrics_backend": metrics_backend,
        }
        self._compare_log_render_context_event(
            side_key=str(side_key or "").strip().upper() or "?",
            bundle=bundle,
            cycle_rows=cycle_rows,
            total_drop=total_drop,
            metadata=metadata,
        )
        return render_ctx, list(cycle_rows or []), total_drop, metadata

    def _compare_resolve_figsize_for_panel(self, side_key: str) -> Tuple[float, float]:
        """Resolve target figure size in inches for one Compare panel.

        Purpose:
            Convert current pane widget geometry into figure-size inches.
        Why:
            Rebuild-on-resize should match panel dimensions to avoid clipping or
            overlap drift.
        Args:
            side_key: Compare side key ("A" or "B").
        Returns:
            `(width_in, height_in)` tuple for figure rendering.
        Side Effects:
            None.
        Exceptions:
            Geometry/DPI failures fall back to default target figure size.
        """
        panel = self._compare_panels.get(side_key) or {}
        widget = panel.get("widget")
        fallback = self._compute_target_figsize_inches()
        if widget is None:
            return fallback
        try:
            widget.update_idletasks()
            width_px = int(widget.winfo_width())
            height_px = int(widget.winfo_height())
        except Exception:
            return fallback
        if width_px <= 2 or height_px <= 2:
            return fallback
        try:
            dpi = float(plt.rcParams.get("figure.dpi", 100.0))
            if not math.isfinite(dpi) or dpi <= 0.0:
                dpi = 100.0
        except Exception:
            dpi = 100.0
        return (max(width_px / dpi, 2.0), max(height_px / dpi, 2.0))

    def _compare_update_side_status(self, side_key: str, message: str) -> None:
        """Update one Compare-pane status message label.

        Purpose:
            Centralize pane status text updates.
        Why:
            Compare rendering needs consistent local feedback for each pane.
        Args:
            side_key: Compare side key ("A" or "B").
            message: Status text to display.
        Returns:
            None.
        Side Effects:
            Mutates pane `StringVar` status label value.
        Exceptions:
            Missing pane/status variable is ignored.
        """
        panel = self._compare_panels.get(side_key) or {}
        status_var = panel.get("status_var")
        if isinstance(status_var, tk.StringVar):
            status_var.set(str(message or ""))

    def _compare_update_status_chips(self) -> None:
        """Refresh Compare status-chip text for backend/marker/report readiness.

        Purpose:
            Expose compact runtime health cues directly in the Compare controls.
        Why:
            Sodium bicarbonate run review needs immediate confidence signals for
            backend path, marker source precedence, and report readiness.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Updates `_compare_status_chip_var` text in the Compare tab.
        Exceptions:
            Missing status variable is treated as no-op.
        """
        chip_var = getattr(self, "_compare_status_chip_var", None)
        if not isinstance(chip_var, tk.StringVar):
            return
        panels = getattr(self, "_compare_panels", {}) if isinstance(getattr(self, "_compare_panels", {}), dict) else {}
        backend_tokens = {
            str((panels.get(side_key) or {}).get("cycle_compute_backend") or "").strip().lower()
            for side_key in ("A", "B")
        }
        backend_tokens.discard("")
        if "rust" in backend_tokens:
            backend_text = "Rust accelerated"
        elif backend_tokens:
            backend_text = "Python fallback"
        else:
            backend_text = "awaiting load"

        marker_source = "profile detection"
        marker_overrides = _normalize_compare_marker_overrides(
            getattr(self, "_compare_marker_overrides", {})
        )
        if marker_overrides.get("A") or marker_overrides.get("B"):
            marker_source = "compare override"
        else:
            for side_key in ("A", "B"):
                panel = panels.get(side_key) or {}
                bundle = panel.get("bundle") if isinstance(panel, dict) else None
                if isinstance(bundle, Mapping) and _normalize_profile_cycle_markers(
                    bundle.get("cycle_markers")
                ):
                    marker_source = "profile cycle_markers"
                    break

        ready_count = sum(
            1
            for side_key in ("A", "B")
            if bool((panels.get(side_key) or {}).get("render_success"))
        )
        report_ready_text = (
            "ready"
            if ready_count == 2
            else "partial"
            if ready_count == 1
            else "waiting for Profile A + B"
        )
        chip_var.set(
            f"Backend: {backend_text}  |  Marker source: {marker_source}  |  "
            f"Report readiness: {report_ready_text}"
        )

    def _compare_render_context_cache_limit(self) -> int:
        """Return Compare render-context cache capacity from perf settings.

        Purpose:
            Centralize bounded cache capacity for prepared Compare contexts.
        Why:
            Compare refreshes may rebuild identical side contexts repeatedly.
        Inputs:
            None.
        Outputs:
            int: Maximum cached prepared contexts.
        Side Effects:
            None.
        Exceptions:
            Invalid settings values fall back to defaults.
        """
        limits = _normalize_perf_cache_limits(settings.get("perf_cache_limits"))
        return max(1, int(limits.get("compare_render_context", 6)))

    def _compare_render_context_cache_key(
        self,
        *,
        side_key: str,
        bundle: Mapping[str, Any],
    ) -> str:
        """Build one deterministic cache key for Compare prepared contexts.

        Purpose:
            Canonicalize side/bundle state into a stable prepared-context key.
        Why:
            Context-prep caching must invalidate when profile data/settings change.
        Inputs:
            side_key: Compare side token (`A` or `B`).
            bundle: Compare bundle mapping for this side.
        Outputs:
            str: Deterministic cache key string.
        Side Effects:
            None.
        Exceptions:
            Serialization failures degrade to an empty key.
        """
        payload = {
            "side": str(side_key or "").strip().upper(),
            "dataset_path": str(bundle.get("dataset_path") or "").strip(),
            "sheet_key": list(bundle.get("sheet_key") or ()),
            "columns_key": list(bundle.get("columns_key") or ()),
            "prep_signature": list(bundle.get("prep_signature") or ()),
            "profile_name": str(bundle.get("profile_name") or "").strip(),
            "args": list(bundle.get("args") or ()),
            "cycle_markers": _normalize_profile_cycle_markers(bundle.get("cycle_markers")),
            "plot_settings": dict(bundle.get("plot_settings") or {}),
        }
        return str(self._analysis_signature_fingerprint(payload) or "").strip()

    def _compare_render_context_cache_get(
        self,
        cache_key: str,
    ) -> Optional[Tuple[RenderContext, List[Dict[str, Any]], Optional[float], Dict[str, Any]]]:
        """Return one cached Compare prepared-context payload by key.

        Purpose:
            Reuse prepared Compare contexts across repeated refresh requests.
        Why:
            Context prep includes cycle extraction and can dominate refresh time.
        Inputs:
            cache_key: Deterministic cache key.
        Outputs:
            Optional prepared payload tuple.
        Side Effects:
            Touches LRU ordering on cache hits.
        Exceptions:
            Invalid cache entries are ignored.
        """
        key = str(cache_key or "").strip()
        if not key:
            return None
        cache_map = getattr(self, "_compare_render_context_cache", None)
        if not isinstance(cache_map, OrderedDict):
            return None
        cached = cache_map.get(key)
        if not isinstance(cached, tuple) or len(cached) != 4:
            return None
        cache_map.move_to_end(key)
        return cached

    def _compare_render_context_cache_set(
        self,
        cache_key: str,
        payload: Tuple[RenderContext, List[Dict[str, Any]], Optional[float], Dict[str, Any]],
    ) -> None:
        """Store one prepared Compare context payload in the bounded LRU cache.

        Purpose:
            Persist prepared side contexts for repeated Compare refreshes.
        Why:
            Reusing prepared contexts reduces UI stalls during compare updates.
        Inputs:
            cache_key: Deterministic prepared-context key.
            payload: Prepared payload tuple from compare context builder.
        Outputs:
            None.
        Side Effects:
            Mutates compare context cache and evicts oldest entries.
        Exceptions:
            Invalid cache keys/payloads are ignored.
        """
        key = str(cache_key or "").strip()
        if not key:
            return
        cache_map = getattr(self, "_compare_render_context_cache", None)
        if not isinstance(cache_map, OrderedDict):
            return
        cache_map[key] = payload
        cache_map.move_to_end(key)
        limit = self._compare_render_context_cache_limit()
        while len(cache_map) > limit:
            cache_map.popitem(last=False)

    def _compare_refresh_loaded_sides_async(
        self,
        *,
        reason: str,
        show_overlay: bool,
        on_complete: Optional[Callable[[], None]] = None,
    ) -> None:
        """Refresh loaded Compare sides with background cycle-context prep.

        Purpose:
            Keep Compare rendering responsive by offloading per-side prep work.
        Why:
            Cycle context and profile-level extraction can be expensive and should
            run off the UI thread while overlays communicate progress.
        Args:
            reason: Render-reason token used for status messaging.
            show_overlay: When True, shows the in-tab Compare loading overlay.
            on_complete: Optional completion callback after refresh finalization.
        Returns:
            None.
        Side Effects:
            Submits worker tasks, updates overlay progress, rerenders side figures,
            refreshes table/yield outputs, and updates status chips.
        Exceptions:
            Worker failures are captured per side without aborting sibling renders.
        """
        panels = getattr(self, "_compare_panels", {})
        loaded_sides = [
            side_key
            for side_key in ("A", "B")
            if isinstance((panels or {}).get(side_key), dict)
            and isinstance(((panels or {}).get(side_key) or {}).get("bundle"), dict)
        ]
        if not loaded_sides:
            if show_overlay:
                # Guard against stale overlays when callers requested an overlaid
                # refresh but no side is currently loaded.
                self._compare_hide_load_splash()
            self._compare_update_status_chips()
            if callable(on_complete):
                on_complete()
            return

        self._compare_render_request_token = int(
            getattr(self, "_compare_render_request_token", 0)
        ) + 1
        request_token = int(self._compare_render_request_token)
        self._compare_render_jobs_active = int(len(loaded_sides))
        if show_overlay:
            self._compare_show_load_splash("Applying Compare changes")
            self._compare_update_load_splash(
                message="Preparing Compare render...",
                progress=8.0,
                stage_key="queued",
                detail=f"Queued {len(loaded_sides)} side render(s).",
                reset=True,
            )

        def _finalize_if_current() -> None:
            """Finalize one compare refresh request when all side jobs complete."""
            if request_token != int(getattr(self, "_compare_render_request_token", 0)):
                return
            self._compare_render_jobs_active = 0
            self._compare_apply_locked_x_axis()
            self._compare_refresh_cycle_table()
            self._compare_refresh_yield_summary()
            self._compare_persist_state()
            self._compare_update_status_chips()
            if show_overlay:
                self._compare_update_load_splash(
                    message="Compare render complete.",
                    progress=100.0,
                    stage_key="ready",
                    detail=f"Applied {len(loaded_sides)} side render(s).",
                )
                self._compare_hide_load_splash()
            if callable(on_complete):
                on_complete()

        def _mark_side_done() -> None:
            """Decrement active-side counter and finalize when no jobs remain."""
            if request_token != int(getattr(self, "_compare_render_request_token", 0)):
                return
            self._compare_render_jobs_active = max(
                0, int(getattr(self, "_compare_render_jobs_active", 0)) - 1
            )
            if int(getattr(self, "_compare_render_jobs_active", 0)) == 0:
                _finalize_if_current()

        runner = getattr(self, "_combined_render_runner", None)
        if runner is None or not hasattr(runner, "submit"):
            runner = getattr(self, "_task_runner", None)

        if runner is None or not hasattr(runner, "submit"):
            for idx, side_key in enumerate(loaded_sides, start=1):
                if show_overlay:
                    self._compare_update_load_splash(
                        message=f"Rendering Profile {side_key}...",
                        progress=12.0 + (idx * (72.0 / max(1, len(loaded_sides)))),
                        stage_key=f"render_{side_key.lower()}",
                        detail=f"Installing combined figure for side {side_key}.",
                    )
                prepared_payload = None
                panel_local = (panels or {}).get(side_key) or {}
                bundle_map = (
                    panel_local.get("bundle")
                    if isinstance(panel_local, Mapping)
                    else None
                )
                if isinstance(bundle_map, Mapping):
                    cache_key = self._compare_render_context_cache_key(
                        side_key=side_key,
                        bundle=bundle_map,
                    )
                    prepared_payload = self._compare_render_context_cache_get(cache_key)
                    if prepared_payload is None:
                        try:
                            prepared_payload = self._compare_build_render_context_from_bundle(
                                dict(bundle_map),
                                side_key=side_key,
                            )
                        except Exception:
                            prepared_payload = None
                        else:
                            self._compare_render_context_cache_set(
                                cache_key,
                                prepared_payload,
                            )
                self._compare_render_profile_side(
                    side_key,
                    reason=reason,
                    prepared=prepared_payload,
                )
            _finalize_if_current()
            return

        for idx, side_key in enumerate(loaded_sides, start=1):
            panel = (panels or {}).get(side_key) or {}
            bundle_map = panel.get("bundle") if isinstance(panel, Mapping) else None
            bundle = dict(bundle_map) if isinstance(bundle_map, Mapping) else {}
            prepared_cache_key = self._compare_render_context_cache_key(
                side_key=side_key,
                bundle=bundle,
            )

            def _worker(
                side_token: str = side_key,
                bundle_snapshot: Dict[str, Any] = bundle,
                cache_key_token: str = prepared_cache_key,
            ) -> Dict[str, Any]:
                """Build compare render context in the worker thread."""
                if not isinstance(bundle_snapshot, dict):
                    return {"ok": False, "error": "No compare bundle loaded."}
                cached_prepared = self._compare_render_context_cache_get(cache_key_token)
                if cached_prepared is not None:
                    return {
                        "ok": True,
                        "prepared": cached_prepared,
                        "cache_key": cache_key_token,
                    }
                try:
                    prepared = self._compare_build_render_context_from_bundle(
                        bundle_snapshot,
                        side_key=side_token,
                    )
                except Exception as exc:
                    return {
                        "ok": False,
                        "error": f"{type(exc).__name__}: {exc}",
                    }
                return {
                    "ok": True,
                    "prepared": prepared,
                    "cache_key": cache_key_token,
                }

            def _on_ok(
                payload: Dict[str, Any],
                *,
                side_token: str = side_key,
                side_idx: int = idx,
            ) -> None:
                """Install one async compare side render result on the UI thread."""
                if request_token != int(getattr(self, "_compare_render_request_token", 0)):
                    return
                if show_overlay:
                    self._compare_update_load_splash(
                        message=f"Rendering Profile {side_token}...",
                        progress=12.0
                        + (side_idx * (72.0 / max(1, len(loaded_sides)))),
                        stage_key=f"render_{side_token.lower()}",
                        detail=f"Installing combined figure for side {side_token}.",
                    )
                if bool((payload or {}).get("ok")) and (payload or {}).get("prepared"):
                    cache_key_token = str((payload or {}).get("cache_key") or "").strip()
                    prepared_payload = (payload or {}).get("prepared")
                    if cache_key_token and isinstance(prepared_payload, tuple):
                        self._compare_render_context_cache_set(
                            cache_key_token,
                            prepared_payload,
                        )
                    self._compare_render_profile_side(
                        side_token,
                        reason=reason,
                        prepared=prepared_payload,
                    )
                else:
                    panel_local = (getattr(self, "_compare_panels", {}) or {}).get(
                        side_token
                    ) or {}
                    error_text = str((payload or {}).get("error") or "").strip()
                    panel_local["cycle_rows"] = []
                    panel_local["total_drop"] = None
                    panel_local["cycle_fallback_used"] = False
                    panel_local["cycle_rows_synthesized"] = False
                    panel_local["cycle_compute_backend"] = ""
                    panel_local["render_success"] = False
                    panel_local["render_error_message"] = (
                        error_text or "Compare render preparation failed."
                    )
                    self._compare_update_side_status(
                        side_token, panel_local["render_error_message"]
                    )
                    self._compare_log_render_completion_event(side_token)
                _mark_side_done()

            def _on_err(exc: BaseException, *, side_token: str = side_key) -> None:
                """Handle one compare async worker failure."""
                if request_token != int(getattr(self, "_compare_render_request_token", 0)):
                    return
                panel_local = (getattr(self, "_compare_panels", {}) or {}).get(
                    side_token
                ) or {}
                panel_local["cycle_rows"] = []
                panel_local["total_drop"] = None
                panel_local["cycle_fallback_used"] = False
                panel_local["cycle_rows_synthesized"] = False
                panel_local["cycle_compute_backend"] = ""
                panel_local["render_success"] = False
                panel_local["render_error_message"] = (
                    f"Compare render worker failed: {type(exc).__name__}"
                )
                self._compare_update_side_status(
                    side_token, panel_local["render_error_message"]
                )
                self._compare_log_render_completion_event(side_token)
                _mark_side_done()

            runner.submit(
                f"compare_render_prepare_{side_key.lower()}",
                _worker,
                _on_ok,
                _on_err,
            )
    def _compare_render_profile_side(
        self,
        side_key: str,
        *,
        reason: str = "",
        prepared: Optional[
            Tuple[RenderContext, List[Dict[str, Any]], Optional[float], Dict[str, Any]]
        ] = None,
    ) -> None:
        """Render one Compare pane using the combined-plot display pipeline.

        Purpose:
            Build and install one profile's combined triple-axis figure.
        Why:
            Compare rendering must reuse the existing combined preview/display
            pipeline so resize behavior and annotation/layout interactions remain
            consistent with the main Plot tab.
        Args:
            side_key: Compare side token ("A" or "B").
            reason: Optional reason label for debug/status context.
        Returns:
            None.
        Side Effects:
            Rebuilds the target pane canvas figure, updates side status/title text,
            and caches cycle rows/total uptake used by comparison tables.
        Exceptions:
            Errors are captured and converted into side-local status text so one
            failed pane does not break the other pane.
        """
        panel = self._compare_panels.get(side_key) or {}
        canvas = panel.get("canvas")
        widget = panel.get("widget")
        bundle = panel.get("bundle")
        title_var = panel.get("title_var")
        if canvas is None or widget is None:
            return
        if not isinstance(bundle, dict):
            fig = Figure(figsize=(5.0, 3.2), dpi=100)
            ax = fig.add_subplot(111)
            load_error_message = str(panel.get("load_error_message") or "").strip()
            placeholder_text = (
                load_error_message if load_error_message else "No profile selected."
            )
            ax.text(0.5, 0.5, placeholder_text, ha="center", va="center")
            ax.set_axis_off()
            try:
                fig.set_canvas(canvas)
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                canvas.figure = fig
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            try:
                fig._gl260_layout_health_context = "compare"  # type: ignore[attr-defined]
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            self._finalize_matplotlib_canvas_layout(
                canvas=canvas,
                fig=fig,
                tk_widget=widget,
                keep_export_size=False,
                trigger_resize_event=True,
                force_draw=True,
            )
            panel["figure"] = fig
            panel["cycle_rows"] = []
            panel["total_drop"] = None
            panel["cycle_fallback_used"] = False
            panel["cycle_rows_synthesized"] = False
            panel["cycle_compute_backend"] = ""
            panel["title_text"] = ""
            panel["suptitle_text"] = ""
            panel["render_success"] = False
            panel["render_error_message"] = placeholder_text
            if isinstance(title_var, tk.StringVar):
                title_var.set("Title: --\nSuptitle: --")
            self._compare_update_side_status(side_key, placeholder_text)
            self._compare_log_render_completion_event(side_key)
            return

        try:
            if prepared is not None:
                (
                    render_ctx,
                    cycle_rows,
                    total_drop,
                    cycle_meta,
                ) = prepared
            else:
                (
                    render_ctx,
                    cycle_rows,
                    total_drop,
                    cycle_meta,
                ) = self._compare_build_render_context_from_bundle(
                    bundle,
                    side_key=side_key,
                )
        except Exception as exc:
            panel["cycle_rows"] = []
            panel["total_drop"] = None
            panel["cycle_fallback_used"] = False
            panel["cycle_rows_synthesized"] = False
            panel["cycle_compute_backend"] = ""
            panel["render_success"] = False
            panel["render_error_message"] = f"Cycle prep failed: {type(exc).__name__}"
            self._compare_update_side_status(
                side_key, f"Cycle prep failed: {type(exc).__name__}"
            )
            self._compare_log_render_completion_event(side_key)
            return

        fig_size = self._compare_resolve_figsize_for_panel(side_key)
        prior_df = getattr(self, "df", None)
        prior_combined_state = getattr(self, "_combined_plot_state", None)
        prior_combined_layout_state = getattr(self, "_combined_layout_state", None)
        prior_combined_layout_dirty = getattr(self, "_combined_layout_dirty", False)
        prior_combined_legend_anchor = getattr(self, "_combined_legend_anchor", None)
        prior_combined_legend_loc = getattr(self, "_combined_legend_loc", None)
        prior_layout_profiles = settings.get("layout_profiles")
        sentinel = object()
        overridden_keys: Dict[str, Any] = {}
        overridden_tk_vars: Dict[str, Any] = {}
        args_for_render = list(bundle.get("args") or ())
        if len(args_for_render) < 14:
            args_for_render.extend([""] * (14 - len(args_for_render)))
        default_titles = self._compare_profile_title_defaults(side_key, bundle)
        # Profile-exact compare rendering must preserve each side's own
        # title/suptitle identity; only fall back when profile fields are blank.
        args_for_render[12] = str(args_for_render[12] or "").strip() or str(
            default_titles.get("title_text") or ""
        ).strip()
        args_for_render[13] = str(args_for_render[13] or "").strip() or str(
            default_titles.get("suptitle_text") or ""
        ).strip()
        resolved_title_text = str(args_for_render[12] or "").strip()
        resolved_suptitle_text = str(args_for_render[13] or "").strip()
        panel["title_text"] = resolved_title_text
        panel["suptitle_text"] = resolved_suptitle_text
        if isinstance(title_var, tk.StringVar):
            display_title = resolved_title_text or "--"
            display_suptitle = resolved_suptitle_text or "--"
            title_var.set(f"Title: {display_title}\nSuptitle: {display_suptitle}")

        def _override_tk_var_from_profile(
            setting_key: str,
            var_attr_name: str,
            payload: Mapping[str, Any],
        ) -> None:
            """Temporarily stage one profile plot setting into a Tk-bound control.

            Purpose:
                Mirror profile-native combined settings that are sourced from Tk vars.
            Why:
                `_combined_plot_config` reads many combined settings from Tk vars,
                so profile-exact Compare rendering must stage profile values there.
            Inputs:
                setting_key: Profile setting key to apply when present.
                var_attr_name: Tk-var attribute name bound to the combined control.
                payload: Source profile plot settings mapping.
            Outputs:
                None.
            Side Effects:
                Temporarily mutates one Tk variable and records its prior value.
            Exceptions:
                Missing vars or invalid assignments are ignored safely.
            """
            if setting_key not in payload:
                return
            var_obj = getattr(self, var_attr_name, None)
            if var_obj is None:
                return
            if var_attr_name not in overridden_tk_vars:
                try:
                    overridden_tk_vars[var_attr_name] = var_obj.get()
                except Exception:
                    overridden_tk_vars[var_attr_name] = sentinel
            try:
                var_obj.set(payload.get(setting_key))
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

        fig: Optional[Figure] = None
        try:
            profile_plot_settings = dict(bundle.get("plot_settings") or {})
            for key, value in profile_plot_settings.items():
                overridden_keys[key] = settings.get(key, sentinel)
                settings[key] = copy.deepcopy(value)
            for setting_key, attr_name in COMPARE_RENDER_PROFILE_TK_STAGING_BINDINGS:
                _override_tk_var_from_profile(setting_key, attr_name, profile_plot_settings)

            pair_plot_elements_override = self._compare_effective_pair_plot_elements_override()
            retain_profile_elements = bool(
                pair_plot_elements_override.get("retain_profile_elements", True)
                if isinstance(pair_plot_elements_override, Mapping)
                else True
            )
            hide_text_family = bool(
                pair_plot_elements_override.get("hide_text_family", True)
                if isinstance(pair_plot_elements_override, Mapping)
                else True
            )
            merged_elements = (
                copy.deepcopy(settings.get("plot_elements"))
                if isinstance(settings.get("plot_elements"), dict)
                else {}
            )
            profile_elements_map = bundle.get("plot_elements")
            profile_elements_map = (
                profile_elements_map
                if isinstance(profile_elements_map, Mapping)
                else {}
            )
            profile_elements_raw = (
                list(profile_elements_map.get("fig_combined_triple_axis") or [])
                if retain_profile_elements
                else []
            )
            normalized_profile_elements = _normalize_plot_elements(
                {"fig_combined_triple_axis": profile_elements_raw}
            ).get("fig_combined_triple_axis", [])
            if hide_text_family:
                filtered_elements: List[Dict[str, Any]] = []
                # Keep trace masks and spans while removing text-heavy callouts
                # that can clutter Compare side-by-side renders.
                for element in normalized_profile_elements:
                    if not isinstance(element, Mapping):
                        continue
                    raw_type = str(element.get("type") or "").strip().lower()
                    canonical_type = _canonicalize_annotation_type(raw_type) or raw_type
                    if canonical_type in {"text", "callout"}:
                        continue
                    filtered_elements.append(dict(element))
                normalized_profile_elements = filtered_elements
            merged_elements["fig_combined_triple_axis"] = copy.deepcopy(
                normalized_profile_elements
            )
            overridden_keys["plot_elements"] = settings.get("plot_elements", sentinel)
            settings["plot_elements"] = merged_elements
            overridden_keys["layout_health_context"] = settings.get(
                "layout_health_context", sentinel
            )
            settings["layout_health_context"] = "compare"
            # Compare panes should not inherit the main-tab persisted legend anchor.
            self._combined_legend_anchor = None
            self._combined_legend_loc = None

            profile_layouts = bundle.get("layout_profiles")
            profile_layouts = (
                profile_layouts if isinstance(profile_layouts, Mapping) else {}
            )
            profile_layout_source: Any = profile_layouts.get("fig_combined_triple_axis", {})
            resolved_layout_profile = _normalize_layout_profile(
                profile_layout_source,
                "fig_combined_triple_axis",
            )
            merged_layouts = _normalize_layout_profiles(prior_layout_profiles)
            merged_layouts["fig_combined_triple_axis"] = copy.deepcopy(
                resolved_layout_profile
            )
            settings["layout_profiles"] = merged_layouts
            for layout_key in COMPARE_LAYOUT_ANCHOR_KEYS:
                if layout_key not in overridden_keys:
                    overridden_keys[layout_key] = settings.get(layout_key, sentinel)
                settings.pop(layout_key, None)

            self.df = bundle.get("df_reference")
            fig = self._build_combined_triple_axis_from_state(
                args=tuple(args_for_render),
                fig_size=fig_size,
                mode="display",
                reuse=False,
                canvas=canvas,
                render_ctx=render_ctx,
                perf_run=None,
            )
        except Exception as exc:
            fig = None
            panel["render_success"] = False
            panel["render_error_message"] = f"Render failed: {type(exc).__name__}."
            self._compare_update_side_status(
                side_key, f"Render failed: {type(exc).__name__}."
            )
        finally:
            for key, prior_value in overridden_keys.items():
                if prior_value is sentinel:
                    settings.pop(key, None)
                else:
                    settings[key] = prior_value
            if prior_layout_profiles is None:
                settings.pop("layout_profiles", None)
            else:
                settings["layout_profiles"] = prior_layout_profiles
            for attr_name, prior_value in overridden_tk_vars.items():
                var_obj = getattr(self, attr_name, None)
                if var_obj is None:
                    continue
                try:
                    if prior_value is sentinel:
                        continue
                    var_obj.set(prior_value)
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass
            self.df = prior_df
            self._combined_plot_state = prior_combined_state
            self._combined_layout_state = prior_combined_layout_state
            self._combined_layout_dirty = prior_combined_layout_dirty
            self._combined_legend_anchor = prior_combined_legend_anchor
            self._combined_legend_loc = prior_combined_legend_loc

        if fig is None:
            fig = Figure(figsize=(5.0, 3.2), dpi=100)
            ax = fig.add_subplot(111)
            ax.text(0.5, 0.5, "Combined plot unavailable.", ha="center", va="center")
            ax.set_axis_off()
            panel["cycle_rows"] = []
            panel["total_drop"] = None
            panel["cycle_fallback_used"] = False
            panel["cycle_rows_synthesized"] = False
            panel["cycle_compute_backend"] = ""
            panel["render_success"] = False
            if not str(panel.get("render_error_message") or "").strip():
                panel["render_error_message"] = "Combined plot unavailable."
        else:
            # Compare pane identity text is rendered in the panel controls rather
            # than inside plot space to maximize data area.
            for axis in list(getattr(fig, "axes", []) or []):
                try:
                    axis.set_title("")
                except Exception:
                    continue
            for title_attr in ("_gl260_title_text", "_gl260_suptitle_text", "_suptitle"):
                title_artist = getattr(fig, title_attr, None)
                if title_artist is None:
                    continue
                try:
                    title_artist.set_text("")
                except Exception:
                    continue
            panel["cycle_rows"] = list(cycle_rows or [])
            panel["total_drop"] = total_drop
            panel["cycle_fallback_used"] = bool(
                (cycle_meta or {}).get("cycle_fallback_used", False)
            )
            panel["cycle_rows_synthesized"] = bool(
                (cycle_meta or {}).get("cycle_rows_synthesized", False)
            )
            panel["cycle_compute_backend"] = str(
                (cycle_meta or {}).get("cycle_compute_backend") or ""
            ).strip()
            panel["render_success"] = True
            panel["render_error_message"] = ""

        try:
            fig.set_canvas(canvas)
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            canvas.figure = fig
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        try:
            fig._gl260_layout_health_context = "compare"  # type: ignore[attr-defined]
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass
        self._finalize_matplotlib_canvas_layout(
            canvas=canvas,
            fig=fig,
            tk_widget=widget,
            keep_export_size=False,
            trigger_resize_event=(reason != "lock_x_axis"),
            force_draw=True,
        )
        legend_guard = getattr(self, "_compare_main_legend_visibility_guard", None)
        xlabel_guard = getattr(self, "_compare_xlabel_placement_guard", None)
        legend_adjusted = bool(legend_guard(fig)) if callable(legend_guard) else False
        xlabel_adjusted = bool(xlabel_guard(fig)) if callable(xlabel_guard) else False
        if legend_adjusted or xlabel_adjusted:
            self._finalize_matplotlib_canvas_layout(
                canvas=canvas,
                fig=fig,
                tk_widget=widget,
                keep_export_size=False,
                trigger_resize_event=False,
                force_draw=True,
            )
        panel["figure"] = fig

        profile_name = str(bundle.get("profile_name") or "").strip() or "(unnamed)"
        cycle_count = len(panel.get("cycle_rows") or [])
        uptake_value = self._compare_parse_float_entry(panel.get("total_drop"))
        uptake_text = "--" if uptake_value is None else f"{uptake_value:.4f} g"
        reason_text = f" [{reason}]" if reason else ""
        if bool(panel.get("render_success", False)):
            self._compare_update_side_status(
                side_key,
                f"{profile_name}{reason_text}\nCycles: {cycle_count}  |  Total dP uptake: {uptake_text}",
            )
        else:
            render_error_message = str(panel.get("render_error_message") or "").strip()
            self._compare_update_side_status(
                side_key,
                render_error_message or f"{profile_name}: render failed.",
            )
        self._compare_update_status_chips()
        self._compare_log_render_completion_event(side_key)

    def _compare_main_legend_visibility_guard(self, fig: Optional[Figure]) -> bool:
        """Ensure compare main legend remains on-canvas after layout solve.

        Purpose:
            Apply one bounded recovery when the main legend is clipped/off-canvas.
        Why:
            Compare panes are compact and occasionally inherit anchor drift that
            pushes the main legend outside or against figure bounds.
        Args:
            fig: Figure to inspect for clipped main legend placement.
        Returns:
            bool: True when legend placement was adjusted.
        Side Effects:
            May reset main legend anchor to lower-center and run one layout pass.
        Exceptions:
            Best-effort guards preserve render stability.
        """
        if fig is None:
            return False
        main_legend = None
        for legend in list(getattr(fig, "legends", []) or []):
            if legend is None:
                continue
            if getattr(legend, "_cycle_overlay_legend", False):
                continue
            main_legend = legend
            break
        if main_legend is None:
            for axis in list(getattr(fig, "axes", []) or []):
                try:
                    legend = axis.get_legend()
                except Exception:
                    legend = None
                if legend is None:
                    continue
                if getattr(legend, "_cycle_overlay_legend", False):
                    continue
                main_legend = legend
                break
        if main_legend is None:
            return False
        canvas = getattr(fig, "canvas", None)
        if canvas is None:
            try:
                FigureCanvasAgg(fig)
                canvas = getattr(fig, "canvas", None)
            except Exception:
                canvas = None
        if canvas is None:
            return False
        try:
            canvas.draw()
            renderer = canvas.get_renderer()
        except Exception:
            return False
        if renderer is None:
            return False
        try:
            bbox = main_legend.get_window_extent(renderer)
            bbox = bbox.transformed(fig.transFigure.inverted())
        except Exception:
            return False
        if bbox is None:
            return False
        off_canvas = bool(
            bbox.x1 <= 0.0
            or bbox.x0 >= 1.0
            or bbox.y1 <= 0.0
            or bbox.y0 >= 1.0
        )
        clipped = bool(
            bbox.x0 < 0.01
            or bbox.x1 > 0.99
            or bbox.y0 < 0.01
            or bbox.y1 > 0.99
        )
        if not (off_canvas or clipped):
            return False
        anchor = (0.5, 0.02)
        try:
            main_legend.set_loc("lower center")
            main_legend.set_bbox_to_anchor(anchor, transform=fig.transFigure)
        except Exception:
            return False
        adjusted = True
        layout_mgr = getattr(fig, "_gl260_layout_manager", None)
        if layout_mgr is not None:
            try:
                layout_mgr.legend_anchor = anchor
                layout_mgr.legend_anchor_y = anchor[1]
                layout_mgr.solve(max_passes=1, allow_draw=True)
            except Exception:
                pass
        return adjusted

    def _compare_xlabel_placement_guard(self, fig: Optional[Figure]) -> bool:
        """Ensure compare xlabel remains below the primary axis after layout solve.

        Purpose:
            Apply a compare-local clamp when xlabel drifts into the data region.
        Why:
            Compact side-by-side layouts can leave xlabel artists inside plot space
            after downstream solves or legend corrections.
        Args:
            fig: Figure to inspect for xlabel band placement.
        Returns:
            bool: True when xlabel position was adjusted.
        Side Effects:
            May move the figure-level xlabel to the lower label band.
        Exceptions:
            Best-effort guards preserve render stability.
        """
        if fig is None:
            return False
        primary_axis = self._compare_primary_axis(fig)
        xlabel_artist = getattr(fig, "_gl260_xlabel_text", None)
        if primary_axis is None or xlabel_artist is None:
            return False
        canvas = getattr(fig, "canvas", None)
        if canvas is None:
            try:
                FigureCanvasAgg(fig)
                canvas = getattr(fig, "canvas", None)
            except Exception:
                canvas = None
        if canvas is None:
            return False
        try:
            canvas.draw()
            renderer = canvas.get_renderer()
        except Exception:
            return False
        if renderer is None:
            return False
        try:
            xlabel_bbox = xlabel_artist.get_window_extent(renderer)
            xlabel_bbox = xlabel_bbox.transformed(fig.transFigure.inverted())
            axes_bbox = primary_axis.get_position()
        except Exception:
            return False
        if xlabel_bbox is None or axes_bbox is None:
            return False
        fig_h_pts = max(float(fig.get_size_inches()[1]) * 72.0, 1.0)
        layout_mgr = getattr(fig, "_gl260_layout_manager", None)
        try:
            xlabel_tick_gap_pts = float(
                getattr(layout_mgr, "xlabel_tick_gap_pts", DEFAULT_COMBINED_XLABEL_TICK_GAP_PTS)
            )
        except Exception:
            xlabel_tick_gap_pts = float(DEFAULT_COMBINED_XLABEL_TICK_GAP_PTS)
        if not math.isfinite(xlabel_tick_gap_pts):
            xlabel_tick_gap_pts = float(DEFAULT_COMBINED_XLABEL_TICK_GAP_PTS)
        xlabel_tick_gap_frac = max(xlabel_tick_gap_pts / fig_h_pts, 0.0)
        if float(xlabel_bbox.y1) < float(axes_bbox.y0) - xlabel_tick_gap_frac:
            return False
        try:
            current_x, current_y = xlabel_artist.get_position()
        except Exception:
            current_x = 0.5
            current_y = 0.0
        try:
            x_value = float(current_x)
        except Exception:
            x_value = 0.5
        if not math.isfinite(x_value):
            x_value = 0.5
        xlabel_height = max(float(xlabel_bbox.height), 0.01)
        epsilon_frac = max(1.0 / fig_h_pts, 1e-4)
        ceiling = float(axes_bbox.y0) - xlabel_tick_gap_frac - (xlabel_height / 2.0) - epsilon_frac
        floor = (xlabel_height / 2.0) + epsilon_frac
        target_y = max(floor, ceiling)
        try:
            current_y_value = float(current_y)
        except Exception:
            current_y_value = 0.0
        if not math.isfinite(current_y_value):
            current_y_value = 0.0
        if abs(current_y_value - target_y) <= 1e-4:
            return False
        try:
            xlabel_artist.set_position((x_value, target_y))
            if layout_mgr is not None:
                layout_mgr.register_artist("xlabel", xlabel_artist)
        except Exception:
            return False
        return True

    def _compare_primary_axis(self, fig: Optional[Figure]) -> Optional[Any]:
        """Return the primary combined axis from a Compare pane figure.

        Purpose:
            Resolve the axis used for x-limit locking operations.
        Why:
            Combined figures may include multiple axes; x-axis synchronization
            should target the primary pressure axis for consistent comparison.
        Args:
            fig: Candidate figure from one Compare pane.
        Returns:
            Primary axis object when available; otherwise the first axis or None.
        Side Effects:
            None.
        Exceptions:
            Figure inspection failures return None.
        """
        if fig is None:
            return None
        try:
            axes = list(fig.get_axes())
        except Exception:
            return None
        if not axes:
            return None
        for axis in axes:
            if str(getattr(axis, "_gl260_axis_role", "") or "") == "primary":
                return axis
        return axes[0]

    def _compare_apply_locked_x_axis(self, *, redraw_mode: str = "force") -> None:
        """Apply synchronized x-axis limits across both Compare panes.

        Purpose:
            Keep the two combined plots on one shared x-domain.
        Why:
            Locked x-limits improve visual run-to-run comparisons when profiles
            have different ranges or when users resize panes repeatedly.
        Args:
            redraw_mode: `"force"` for immediate blocking redraw or `"idle"` for
                queued non-blocking redraw.
        Returns:
            None.
        Side Effects:
            Mutates pane axis limits and redraws both pane canvases.
        Exceptions:
            Axis/figure access failures are ignored per pane.
        """
        if not bool(self.compare_lock_x_axis_var.get()):
            return
        redraw_mode_norm = str(redraw_mode or "force").strip().lower()
        if redraw_mode_norm not in {"force", "idle"}:
            redraw_mode_norm = "force"
        panels = getattr(self, "_compare_panels", {})
        if not isinstance(panels, dict):
            return
        limits: List[Tuple[float, float]] = []
        for side_key in ("A", "B"):
            panel = panels.get(side_key) or {}
            axis = self._compare_primary_axis(panel.get("figure"))
            if axis is None:
                continue
            try:
                x0, x1 = axis.get_xlim()
                x0 = float(x0)
                x1 = float(x1)
            except Exception:
                continue
            if not (math.isfinite(x0) and math.isfinite(x1)):
                continue
            if x1 <= x0:
                continue
            limits.append((x0, x1))
        if len(limits) < 2:
            return
        locked_min = min(pair[0] for pair in limits)
        locked_max = max(pair[1] for pair in limits)
        if not (math.isfinite(locked_min) and math.isfinite(locked_max)):
            return
        if locked_max <= locked_min:
            return
        draw_targets: List[Tuple[Any, Any, Any]] = []
        for side_key in ("A", "B"):
            panel = panels.get(side_key) or {}
            fig = panel.get("figure")
            canvas = panel.get("canvas")
            widget = panel.get("widget")
            axis = self._compare_primary_axis(fig)
            if axis is None or fig is None or canvas is None or widget is None:
                continue
            try:
                axis.set_xlim(locked_min, locked_max)
            except Exception:
                continue
            draw_targets.append((fig, canvas, widget))
        for fig, canvas, widget in draw_targets:
            if redraw_mode_norm == "idle":
                try:
                    canvas.draw_idle()
                except Exception:
                    try:
                        canvas.draw()
                    except Exception:
                        # Best-effort guard; ignore failures to avoid interrupting workflow.
                        pass
                continue
            self._finalize_matplotlib_canvas_layout(
                canvas=canvas,
                fig=fig,
                tk_widget=widget,
                keep_export_size=False,
                trigger_resize_event=False,
                force_draw=True,
            )

    def _compare_cycle_mass_value(self, row: Mapping[str, Any]) -> Optional[float]:
        """Extract one per-cycle uptake mass value from a cycle-transfer row.

        Purpose:
            Normalize per-cycle uptake fields from mixed cycle payload schemas.
        Why:
            Compare tables must support legacy and current cycle-transfer key names
            across profiles generated by different app versions.
        Args:
            row: One cycle-transfer row mapping.
        Returns:
            Optional float mass in grams for the cycle uptake.
        Side Effects:
            None.
        Exceptions:
            Invalid values return None.
        """
        for key in (
            "selected_mass_g",
            "selected_mass",
            "co2_added_g",
            "co2_added_mass_g",
            "co2_mass_g",
            "co2_g",
            "cycle_mass_g",
            "cycle_co2_mass_g",
        ):
            value = self._compare_parse_float_entry(row.get(key))
            if value is not None:
                return float(value)
        return None

    def _compare_cycle_cumulative_mass_value(
        self, row: Mapping[str, Any]
    ) -> Optional[float]:
        """Extract one cumulative uptake mass value from a cycle-transfer row.

        Purpose:
            Normalize cumulative uptake fields from cycle payload variants.
        Why:
            Table alignment and delta math need one consistent cumulative basis.
        Args:
            row: One cycle-transfer row mapping.
        Returns:
            Optional float cumulative mass in grams.
        Side Effects:
            None.
        Exceptions:
            Invalid values return None.
        """
        for key in (
            "cumulative_co2_mass_g",
            "cumulative_co2_added_mass_g",
            "cumulative_co2_added_g",
            "cumulative_co2_g",
            "cumulative_added_g",
            "cumulative_mass_g",
        ):
            value = self._compare_parse_float_entry(row.get(key))
            if value is not None:
                return float(value)
        return None

    def _compare_refresh_cycle_table(self) -> None:
        """Rebuild the Compare per-cycle table with deltas and summary rows.

        Purpose:
            Render aligned cycle uptake metrics for profile A/B.
        Why:
            Users need cycle-by-cycle and cumulative deltas to quantify run
            differences beyond visual plot inspection.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Clears/repopulates the Compare treeview and updates the cached rows
            used by CSV export.
        Exceptions:
            Missing panes/treeview are treated as no-op.
        """
        tree = getattr(self, "_compare_cycle_tree", None)
        if tree is None:
            return
        panel_a = self._compare_panels.get("A") or {}
        panel_b = self._compare_panels.get("B") or {}
        rows_a = list(panel_a.get("cycle_rows") or [])
        rows_b = list(panel_b.get("cycle_rows") or [])
        for item_id in tree.get_children():
            tree.delete(item_id)
        if not rows_a and not rows_b:
            tree.insert(
                "",
                "end",
                values=(
                    "No cycle uptake data",
                    "Load profiles with valid cycle detection output.",
                    "",
                    "",
                    "",
                    "",
                    "",
                ),
            )
            self._compare_cycle_table_rows = []
            self._compare_cycle_table_apply_view_mode_from_var(persist=False)
            return

        aligned_rows = _rust_compare_aligned_cycle_rows_core(rows_a, rows_b)
        alignment_backend = "rust"
        if not isinstance(aligned_rows, Sequence):
            alignment_backend = "python"
            aligned_rows = _python_compare_aligned_cycle_rows_core(rows_a, rows_b)
        aligned_rows = [
            dict(row) for row in (aligned_rows or []) if isinstance(row, Mapping)
        ]

        def _opt_float_any(raw_value: Any) -> Optional[float]:
            """Parse optional finite float values including signed deltas."""
            if raw_value in (None, ""):
                return None
            try:
                candidate = float(raw_value)
            except Exception:
                return None
            if not math.isfinite(candidate):
                return None
            return float(candidate)

        export_rows: List[Dict[str, Any]] = []
        sum_uptake_a = 0.0
        sum_uptake_b = 0.0
        last_cum_a = 0.0
        last_cum_b = 0.0
        valid_a = False
        valid_b = False

        for row in aligned_rows:
            cycle_id = int(_coerce_int(row.get("cycle")) or 0)
            if cycle_id <= 0:
                continue
            uptake_a = _opt_float_any(row.get("uptake_a_g"))
            uptake_b = _opt_float_any(row.get("uptake_b_g"))
            cum_a = _opt_float_any(row.get("cum_a_g"))
            cum_b = _opt_float_any(row.get("cum_b_g"))
            if uptake_a is not None:
                sum_uptake_a += float(uptake_a)
            if uptake_b is not None:
                sum_uptake_b += float(uptake_b)
            if cum_a is not None:
                last_cum_a = float(cum_a)
                valid_a = True
            if cum_b is not None:
                last_cum_b = float(cum_b)
                valid_b = True
            delta = _opt_float_any(row.get("delta_g"))
            cum_delta = _opt_float_any(row.get("cum_delta_g"))

            def _fmt(value: Optional[float]) -> str:
                return "" if value is None else f"{float(value):.4f}"

            row_payload = {
                "cycle": cycle_id,
                "uptake_a_g": uptake_a,
                "uptake_b_g": uptake_b,
                "delta_g": delta,
                "cum_a_g": cum_a,
                "cum_b_g": cum_b,
                "cum_delta_g": cum_delta,
            }
            export_rows.append(row_payload)
            tree.insert(
                "",
                "end",
                values=(
                    str(cycle_id),
                    _fmt(uptake_a),
                    _fmt(uptake_b),
                    _fmt(delta),
                    _fmt(cum_a),
                    _fmt(cum_b),
                    _fmt(cum_delta),
                ),
            )

        total_delta = sum_uptake_b - sum_uptake_a
        cum_total_delta = (last_cum_b - last_cum_a) if (valid_a or valid_b) else None
        tree.insert(
            "",
            "end",
            values=(
                "Totals",
                f"{sum_uptake_a:.4f}" if rows_a else "",
                f"{sum_uptake_b:.4f}" if rows_b else "",
                f"{total_delta:+.4f}" if (rows_a and rows_b) else "",
                f"{last_cum_a:.4f}" if valid_a else "",
                f"{last_cum_b:.4f}" if valid_b else "",
                (
                    f"{cum_total_delta:+.4f}"
                    if cum_total_delta is not None and valid_a and valid_b
                    else ""
                ),
            ),
        )
        uptake_a_values = [
            _opt_float_any(row.get("uptake_a_g")) for row in aligned_rows
        ]
        uptake_b_values = [
            _opt_float_any(row.get("uptake_b_g")) for row in aligned_rows
        ]
        valid_uptake_a = [value for value in uptake_a_values if value is not None]
        valid_uptake_b = [value for value in uptake_b_values if value is not None]
        mean_a = (
            (sum(float(value) for value in valid_uptake_a) / len(valid_uptake_a))
            if valid_uptake_a
            else None
        )
        mean_b = (
            (sum(float(value) for value in valid_uptake_b) / len(valid_uptake_b))
            if valid_uptake_b
            else None
        )
        max_a = (
            max((float(value) for value in valid_uptake_a), default=None)
            if valid_uptake_a
            else None
        )
        max_b = (
            max((float(value) for value in valid_uptake_b), default=None)
            if valid_uptake_b
            else None
        )
        tree.insert(
            "",
            "end",
            values=(
                "Mean Uptake",
                "" if mean_a is None else f"{mean_a:.4f}",
                "" if mean_b is None else f"{mean_b:.4f}",
                (
                    ""
                    if mean_a is None or mean_b is None
                    else f"{(mean_b - mean_a):+.4f}"
                ),
                "",
                "",
                "",
            ),
        )
        tree.insert(
            "",
            "end",
            values=(
                "Max Uptake",
                "" if max_a is None else f"{float(max_a):.4f}",
                "" if max_b is None else f"{float(max_b):.4f}",
                (
                    ""
                    if max_a is None or max_b is None
                    else f"{(float(max_b) - float(max_a)):+.4f}"
                ),
                "",
                "",
                "",
            ),
        )
        tree.insert(
            "",
            "end",
            values=("Cycle Count", str(len(rows_a)), str(len(rows_b)), "", "", "", ""),
        )
        self._compare_cycle_table_rows = export_rows
        diagnostics_state = dict(getattr(self, "_compare_load_diagnostics_state", {}) or {})
        summary_base = str(diagnostics_state.get("summary") or "").strip()
        summary_base = summary_base.split("\nCycle alignment backend:")[0].strip()
        diagnostics_state["summary"] = (
            f"{summary_base}\n"
            f"Cycle alignment backend: {alignment_backend}".strip()
        ).strip()
        self._compare_load_diagnostics_state = diagnostics_state
        self._compare_update_status_chips()
        self._compare_cycle_table_apply_view_mode_from_var(persist=False)

    def _compare_export_cycle_table_csv(self) -> None:
        """Export the Compare per-cycle table rows to CSV.

        Purpose:
            Save aligned A/B cycle uptake values and deltas for reporting.
        Why:
            External review and QC workflows often require table exports.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Opens a save dialog and writes CSV rows to disk.
        Exceptions:
            File write failures show an error message.
        """
        rows = list(getattr(self, "_compare_cycle_table_rows", []) or [])
        if not rows:
            try:
                messagebox.showinfo(
                    "Export Compare CSV", "No cycle comparison rows are available."
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        path = filedialog.asksaveasfilename(
            title="Export Compare Cycle Table",
            defaultextension=".csv",
            filetypes=[("CSV File", "*.csv")],
            initialfile="compare_cycle_uptake.csv",
        )
        if not path:
            return
        canonical_fieldnames = [
            "cycle",
            "uptake_a_g",
            "uptake_b_g",
            "delta_g",
            "cum_a_g",
            "cum_b_g",
            "cum_delta_g",
        ]
        display_columns = self._compare_cycle_table_current_display_columns()
        fieldnames = [
            col for col in display_columns if col in set(canonical_fieldnames)
        ] or list(canonical_fieldnames)
        try:
            with open(path, "w", encoding="utf-8", newline="") as handle:
                writer = csv.DictWriter(handle, fieldnames=fieldnames)
                writer.writeheader()
                for row in rows:
                    writer.writerow(
                        {
                            fieldname: row.get(fieldname)
                            for fieldname in fieldnames
                        }
                    )
        except Exception as exc:
            try:
                messagebox.showerror(
                    "Export Compare CSV", f"Failed to export cycle table.\n{exc}"
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass

    def _interactive_html_figure_data_uri(
        self,
        fig_obj: Any,
        *,
        dpi: float = 150.0,
        tight_bbox: bool = True,
    ) -> str:
        """Encode one Matplotlib figure as a PNG data URI for HTML reports.

        Purpose:
            Provide a reusable figure-embedding helper for interactive HTML exports.
        Why:
            Compare and Final Report HTML outputs both need self-contained embedded
            images without external file dependencies.
        Args:
            fig_obj: Figure-like object supporting `savefig`.
            dpi: Target raster DPI for embedded PNG payloads.
            tight_bbox: True uses `bbox_inches="tight"` crop behavior.
        Returns:
            Data URI string, or empty string when encoding fails.
        Side Effects:
            None.
        Exceptions:
            Encoding failures return an empty string safely.
        """
        if fig_obj is None:
            return ""
        buffer = io.BytesIO()
        try:
            _sanitize_figure_text_artists(fig_obj)
            savefig_kwargs: Dict[str, Any] = {"format": "png", "dpi": dpi}
            if tight_bbox:
                savefig_kwargs["bbox_inches"] = "tight"
            fig_obj.savefig(buffer, **savefig_kwargs)
            buffer.seek(0)
            payload = base64.b64encode(buffer.read()).decode("ascii")
            return f"data:image/png;base64,{payload}"
        except Exception:
            return ""
        finally:
            try:
                buffer.close()
            except Exception:
                pass

    def _interactive_html_render_shell(
        self,
        *,
        title: str,
        subtitle: str,
        sections_html: Sequence[str],
        script_body: str,
        body_class: str = "",
        extra_style: str = "",
    ) -> str:
        """Render a shared interactive HTML shell used by Compare and Final Report.

        Purpose:
            Centralize page scaffolding, styling, and layout primitives.
        Why:
            Compare and Final Report interactive HTML should share one visual and
            structural format family for consistency.
        Args:
            title: Page heading text.
            subtitle: Top metadata/status line text.
            sections_html: Ordered HTML sections inserted into the document body.
            script_body: JavaScript payload for client-side interactivity.
            body_class: Optional CSS class token added to the body element.
            extra_style: Optional CSS rules appended to the shared style block.
        Returns:
            Complete HTML document string.
        Side Effects:
            None.
        Exceptions:
            Inputs are sanitized for safe embedding.
        """
        safe_title = html.escape(str(title or "").strip() or "GL-260 Interactive Report")
        safe_subtitle = html.escape(str(subtitle or "").strip())
        safe_body_class = html.escape(str(body_class or "").strip())
        extra_style_blob = str(extra_style or "").strip()
        section_blob = "\n".join(str(section or "") for section in sections_html)
        body_open = (
            f"<body class=\"{safe_body_class}\">" if safe_body_class else "<body>"
        )
        return "\n".join(
            [
                "<!doctype html>",
                "<html lang=\"en\">",
                "<head>",
                "  <meta charset=\"utf-8\">",
                "  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">",
                f"  <title>{safe_title}</title>",
                "  <style>",
                "    :root { --bg:#f3f6f8; --card:#ffffff; --ink:#152129; --muted:#4a6270; --edge:#ced9df; --accent:#0c7c93; --good:#1c7f46; --bad:#9f3f3f; }",
                "    * { box-sizing: border-box; }",
                "    body { margin:0; padding:24px; background:linear-gradient(180deg,#eaf1f5 0%, #f8fbfc 100%); color:var(--ink); font-family:'Segoe UI',Verdana,sans-serif; }",
                "    h1,h2,h3 { margin:0 0 8px 0; line-height:1.2; }",
                "    .page-head { margin-bottom:14px; }",
                "    .meta { color:var(--muted); font-size:13px; margin-top:6px; }",
                "    .grid { display:grid; gap:12px; }",
                "    .grid.cards { grid-template-columns:repeat(auto-fit,minmax(180px,1fr)); }",
                "    .card { background:var(--card); border:1px solid var(--edge); border-radius:12px; padding:12px 14px; box-shadow:0 8px 22px rgba(20,40,60,.07); }",
                "    .label { color:var(--muted); text-transform:uppercase; letter-spacing:.04em; font-size:11px; margin-bottom:3px; }",
                "    .kpi { font-size:22px; font-weight:700; }",
                "    .toolbar { display:flex; gap:8px; flex-wrap:wrap; margin:10px 0; }",
                "    .toolbar input { border:1px solid var(--edge); border-radius:8px; padding:8px 10px; min-width:180px; }",
                "    .btn { border:1px solid var(--edge); border-radius:8px; background:#fff; color:var(--ink); padding:8px 10px; cursor:pointer; }",
                "    .btn.active { background:var(--accent); color:#fff; border-color:var(--accent); }",
                "    table { width:100%; border-collapse:collapse; font-size:13px; }",
                "    thead th { position:sticky; top:0; background:#f4f8fa; z-index:1; }",
                "    th,td { border-bottom:1px solid var(--edge); padding:7px 8px; text-align:right; white-space:nowrap; }",
                "    th:first-child,td:first-child { text-align:left; }",
                "    .table-wrap { overflow:auto; max-height:420px; border:1px solid var(--edge); border-radius:10px; }",
                "    .images { display:grid; gap:12px; grid-template-columns:repeat(auto-fit,minmax(300px,1fr)); }",
                "    img { width:100%; height:auto; border:1px solid var(--edge); border-radius:10px; background:#fff; }",
                "    details summary { cursor:pointer; font-weight:600; }",
                "    pre { margin:10px 0 0; white-space:pre-wrap; word-break:break-word; }",
                "    .good { color:var(--good); }",
                "    .bad { color:var(--bad); }",
                "    .muted { color:var(--muted); }",
                extra_style_blob,
                "  </style>",
                "</head>",
                body_open,
                f"  <header class=\"page-head\"><h1>{safe_title}</h1><div class=\"meta\">{safe_subtitle}</div></header>",
                section_blob,
                "  <script>",
                script_body,
                "  </script>",
                "</body>",
                "</html>",
            ]
        )

    def _build_compare_interactive_html(
        self,
        *,
        profile_a_name: str,
        profile_b_name: str,
        profile_a_title: str,
        profile_a_suptitle: str,
        profile_b_title: str,
        profile_b_suptitle: str,
        cycle_rows: Sequence[Mapping[str, Any]],
        yield_rows: Sequence[Mapping[str, Any]],
        diagnostics_text: str,
        fig_a: Any,
        fig_b: Any,
        actual_a: Optional[float],
        actual_b: Optional[float],
    ) -> str:
        """Build the Compare tab interactive HTML report document.

        Purpose:
            Render compare report artifacts into one self-contained interactive HTML.
        Why:
            Compare exports require portable filtering, diagnostics, and embedded
            side-by-side pane imagery.
        Args:
            profile_a_name: Side-A profile display name.
            profile_b_name: Side-B profile display name.
            profile_a_title: Side-A title text displayed above the compare pane.
            profile_a_suptitle: Side-A suptitle text displayed above the compare pane.
            profile_b_title: Side-B title text displayed above the compare pane.
            profile_b_suptitle: Side-B suptitle text displayed above the compare pane.
            cycle_rows: Per-cycle compare table rows.
            yield_rows: Yield KPI rows for A/B/delta.
            diagnostics_text: Diagnostics panel text payload.
            fig_a: Side-A rendered figure.
            fig_b: Side-B rendered figure.
            actual_a: Actual yield (%) for side A.
            actual_b: Actual yield (%) for side B.
        Returns:
            Complete Compare interactive HTML document.
        Side Effects:
            None.
        Exceptions:
            Malformed rows/figures are handled with empty fallbacks.
        """
        cycle_rows_list = [dict(row or {}) for row in list(cycle_rows or [])]
        yield_rows_list = [dict(row or {}) for row in list(yield_rows or [])]
        fig_a_uri = self._interactive_html_figure_data_uri(fig_a, dpi=150.0)
        fig_b_uri = self._interactive_html_figure_data_uri(fig_b, dpi=150.0)
        caption_a = (
            f"Profile A | Title: {str(profile_a_title or '').strip() or '--'} | "
            f"Suptitle: {str(profile_a_suptitle or '').strip() or '--'}"
        )
        caption_b = (
            f"Profile B | Title: {str(profile_b_title or '').strip() or '--'} | "
            f"Suptitle: {str(profile_b_suptitle or '').strip() or '--'}"
        )
        safe_caption_a = html.escape(caption_a)
        safe_caption_b = html.escape(caption_b)
        yield_delta = (
            None
            if actual_a is None or actual_b is None
            else float(actual_b) - float(actual_a)
        )
        subtitle = (
            f"Generated: {datetime.now().isoformat(timespec='seconds')} | "
            f"Profile A: {profile_a_name or '--'} | Profile B: {profile_b_name or '--'} | "
            "Comparison report uses side-by-side panes as the output source."
        )
        sections = [
            (
                "<section class=\"grid cards\">"
                f"<article class=\"card\"><div class=\"label\">Yield A (%)</div><div class=\"kpi\">{'--' if actual_a is None else f'{actual_a:.2f}'}</div></article>"
                f"<article class=\"card\"><div class=\"label\">Yield B (%)</div><div class=\"kpi\">{'--' if actual_b is None else f'{actual_b:.2f}'}</div></article>"
                f"<article class=\"card\"><div class=\"label\">Yield Delta B-A (%)</div><div class=\"kpi\">{'--' if yield_delta is None else f'{yield_delta:+.2f}'}</div></article>"
                f"<article class=\"card\"><div class=\"label\">Cycle Rows</div><div class=\"kpi\">{len(cycle_rows_list)}</div></article>"
                "</section>"
            ),
            (
                "<section class=\"card\">"
                "<h2>Combined Side-by-Side Render Source</h2>"
                "<div class=\"images\">"
                f"<figure><figcaption class=\"label\">{safe_caption_a}</figcaption><img alt=\"Profile A compare plot\" src=\"{fig_a_uri}\" /></figure>"
                f"<figure><figcaption class=\"label\">{safe_caption_b}</figcaption><img alt=\"Profile B compare plot\" src=\"{fig_b_uri}\" /></figure>"
                "</div>"
                "</section>"
            ),
            (
                "<section class=\"card\">"
                "<h2>Per-Cycle Uptake Comparison</h2>"
                "<div class=\"toolbar\">"
                "<button id=\"btn-all\" class=\"btn active\" type=\"button\">All</button>"
                "<button id=\"btn-pos\" class=\"btn\" type=\"button\">Positive Delta</button>"
                "<button id=\"btn-neg\" class=\"btn\" type=\"button\">Negative Delta</button>"
                "<input id=\"cycle-filter\" type=\"text\" placeholder=\"Filter cycle rows...\" />"
                "</div>"
                "<div class=\"table-wrap\">"
                "<table id=\"cycle-table\">"
                "<thead><tr><th>Cycle</th><th>Uptake A (g)</th><th>Uptake B (g)</th><th>Delta (g)</th><th>Cumulative A (g)</th><th>Cumulative B (g)</th><th>Cumulative Delta (g)</th></tr></thead>"
                "<tbody></tbody></table>"
                "</div>"
                "</section>"
            ),
            (
                "<section class=\"card\">"
                "<h2>Yield Comparison</h2>"
                "<div class=\"table-wrap\">"
                "<table id=\"yield-table\">"
                "<thead><tr><th>Side</th><th>Profile</th><th>Isolated (g)</th><th>Theoretical (g)</th><th>Actual Yield (%)</th></tr></thead>"
                "<tbody></tbody></table>"
                "</div>"
                "</section>"
            ),
            (
                "<details class=\"card\" open>"
                "<summary>Diagnostics Panel</summary>"
                "<pre id=\"diag-text\"></pre>"
                "</details>"
            ),
        ]
        script_body = "\n".join(
            [
                f"const cycleRows = {json.dumps(cycle_rows_list, ensure_ascii=False)};",
                f"const yieldRows = {json.dumps(yield_rows_list, ensure_ascii=False)};",
                f"const diagnosticsText = {json.dumps(str(diagnostics_text or ''), ensure_ascii=False)};",
                "const cycleBody = document.querySelector('#cycle-table tbody');",
                "const yieldBody = document.querySelector('#yield-table tbody');",
                "const filterInput = document.getElementById('cycle-filter');",
                "let cycleMode = 'all';",
                "const normalizeText = (value) => (value === null || value === undefined || value === '') ? '--' : String(value);",
                "const rowMatchesFilter = (row, needle) => {",
                "  if (!needle) return true;",
                "  const text = [row.cycle,row.uptake_a_g,row.uptake_b_g,row.delta_g,row.cum_a_g,row.cum_b_g,row.cum_delta_g].map(v => String(v ?? '')).join(' ').toLowerCase();",
                "  return text.includes(needle);",
                "};",
                "const renderCycles = () => {",
                "  const needle = String((filterInput?.value || '')).trim().toLowerCase();",
                "  cycleBody.innerHTML = '';",
                "  for (const row of cycleRows) {",
                "    const delta = Number(row.delta_g ?? NaN);",
                "    if (cycleMode === 'pos' && !(delta > 0)) continue;",
                "    if (cycleMode === 'neg' && !(delta < 0)) continue;",
                "    if (!rowMatchesFilter(row, needle)) continue;",
                "    const tr = document.createElement('tr');",
                "    const cells = [row.cycle,row.uptake_a_g,row.uptake_b_g,row.delta_g,row.cum_a_g,row.cum_b_g,row.cum_delta_g];",
                "    cells.forEach((value, idx) => {",
                "      const td = document.createElement('td');",
                "      td.textContent = normalizeText(value);",
                "      if (idx === 3 && Number(value) > 0) td.classList.add('good');",
                "      if (idx === 3 && Number(value) < 0) td.classList.add('bad');",
                "      tr.appendChild(td);",
                "    });",
                "    cycleBody.appendChild(tr);",
                "  }",
                "};",
                "const renderYield = () => {",
                "  yieldBody.innerHTML = '';",
                "  for (const row of yieldRows) {",
                "    const tr = document.createElement('tr');",
                "    const vals = [row.profile_side,row.profile_name,row.isolated_mass_g,row.theoretical_yield_g,row.actual_yield_pct];",
                "    vals.forEach((value, idx) => {",
                "      const td = document.createElement('td');",
                "      td.textContent = normalizeText(value);",
                "      if (idx <= 1) td.style.textAlign = 'left';",
                "      tr.appendChild(td);",
                "    });",
                "    yieldBody.appendChild(tr);",
                "  }",
                "};",
                "const setMode = (mode) => {",
                "  cycleMode = mode;",
                "  document.getElementById('btn-all').classList.toggle('active', mode === 'all');",
                "  document.getElementById('btn-pos').classList.toggle('active', mode === 'pos');",
                "  document.getElementById('btn-neg').classList.toggle('active', mode === 'neg');",
                "  renderCycles();",
                "};",
                "document.getElementById('btn-all').addEventListener('click', () => setMode('all'));",
                "document.getElementById('btn-pos').addEventListener('click', () => setMode('pos'));",
                "document.getElementById('btn-neg').addEventListener('click', () => setMode('neg'));",
                "if (filterInput) filterInput.addEventListener('input', () => renderCycles());",
                "document.getElementById('diag-text').textContent = diagnosticsText || 'No diagnostics available.';",
                "renderYield();",
                "renderCycles();",
            ]
        )
        return self._interactive_html_render_shell(
            title="GL-260 Compare Interactive Report",
            subtitle=subtitle,
            sections_html=sections,
            script_body=script_body,
        )

    def _compare_generate_report_artifacts(self) -> None:
        """Generate Compare report artifacts (PDF + CSV pack + interactive HTML).

        Purpose:
            Export side-by-side compare evidence for run-review workflows.
        Why:
            Sodium bicarbonate synthesis review needs portable artifacts that
            summarize cycle deltas, yield KPIs, and diagnostics for handoff/QC.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Opens save dialog, writes PDF/CSV/HTML files, and shows completion
            status dialogs.
        Exceptions:
            File write failures show user-facing errors.
        """
        panel_a = (getattr(self, "_compare_panels", {}) or {}).get("A") or {}
        panel_b = (getattr(self, "_compare_panels", {}) or {}).get("B") or {}
        if not isinstance(panel_a.get("bundle"), dict) and not isinstance(
            panel_b.get("bundle"), dict
        ):
            try:
                messagebox.showinfo(
                    "Generate Comparison Report",
                    "Load at least one compare profile before generating a report.",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return
        if not bool(panel_a.get("render_success", False)) and not bool(
            panel_b.get("render_success", False)
        ):
            try:
                messagebox.showinfo(
                    "Generate Comparison Report",
                    "Run Comparison before generating a report.",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return

        output_pdf_path = filedialog.asksaveasfilename(
            title="Generate Comparison Report",
            defaultextension=".pdf",
            filetypes=[("PDF File", "*.pdf")],
            initialfile="compare_report.pdf",
        )
        if not output_pdf_path:
            return
        output_pdf = Path(output_pdf_path)
        output_base = output_pdf.with_suffix("")
        cycle_csv = output_base.with_name(f"{output_base.name}_cycle_table.csv")
        yield_csv = output_base.with_name(f"{output_base.name}_yield_kpi.csv")
        diagnostics_txt = output_base.with_name(f"{output_base.name}_diagnostics.txt")
        html_report = output_base.with_name(f"{output_base.name}.html")

        try:
            report_prefs = _normalize_compare_report_preferences(
                getattr(self, "_compare_report_preferences", {})
            )
            cycle_rows = list(getattr(self, "_compare_cycle_table_rows", []) or [])
            profile_a_name = str((panel_a.get("bundle") or {}).get("profile_name") or "").strip()
            profile_b_name = str((panel_b.get("bundle") or {}).get("profile_name") or "").strip()
            side_a_defaults = self._compare_profile_title_defaults(
                "A", panel_a.get("bundle")
            )
            side_b_defaults = self._compare_profile_title_defaults(
                "B", panel_b.get("bundle")
            )
            profile_a_title = str(panel_a.get("title_text") or "").strip() or str(
                side_a_defaults.get("title_text") or ""
            ).strip()
            profile_a_suptitle = str(panel_a.get("suptitle_text") or "").strip() or str(
                side_a_defaults.get("suptitle_text") or ""
            ).strip()
            profile_b_title = str(panel_b.get("title_text") or "").strip() or str(
                side_b_defaults.get("title_text") or ""
            ).strip()
            profile_b_suptitle = str(panel_b.get("suptitle_text") or "").strip() or str(
                side_b_defaults.get("suptitle_text") or ""
            ).strip()
            iso_a = self._compare_parse_float_entry(self.compare_isolated_mass_a_var.get())
            iso_b = self._compare_parse_float_entry(self.compare_isolated_mass_b_var.get())
            basis_a = self._compare_resolve_reaction_basis(panel_a.get("bundle"))
            basis_b = self._compare_resolve_reaction_basis(panel_b.get("bundle"))
            theo_a = self._compare_compute_theoretical_yield_g(basis_a)
            theo_b = self._compare_compute_theoretical_yield_g(basis_b)
            actual_a = (
                None
                if iso_a is None or theo_a in (None, 0.0)
                else (float(iso_a) / float(theo_a)) * 100.0
            )
            actual_b = (
                None
                if iso_b is None or theo_b in (None, 0.0)
                else (float(iso_b) / float(theo_b)) * 100.0
            )
            yield_rows = [
                {
                    "profile_side": "A",
                    "profile_name": profile_a_name,
                    "isolated_mass_g": iso_a,
                    "theoretical_yield_g": theo_a,
                    "actual_yield_pct": actual_a,
                },
                {
                    "profile_side": "B",
                    "profile_name": profile_b_name,
                    "isolated_mass_g": iso_b,
                    "theoretical_yield_g": theo_b,
                    "actual_yield_pct": actual_b,
                },
                {
                    "profile_side": "Delta (B-A)",
                    "profile_name": "",
                    "isolated_mass_g": (
                        None if iso_a is None or iso_b is None else float(iso_b) - float(iso_a)
                    ),
                    "theoretical_yield_g": (
                        None
                        if theo_a is None or theo_b is None
                        else float(theo_b) - float(theo_a)
                    ),
                    "actual_yield_pct": (
                        None
                        if actual_a is None or actual_b is None
                        else float(actual_b) - float(actual_a)
                    ),
                },
            ]
            diagnostics_text = str(
                getattr(self, "_compare_diagnostics_var", tk.StringVar(value="")).get()
                if isinstance(getattr(self, "_compare_diagnostics_var", None), tk.StringVar)
                else "No diagnostics available."
            ).strip()

            if report_prefs.get("include_cycle_table", True):
                with open(cycle_csv, "w", encoding="utf-8", newline="") as handle:
                    writer = csv.DictWriter(
                        handle,
                        fieldnames=[
                            "cycle",
                            "uptake_a_g",
                            "uptake_b_g",
                            "delta_g",
                            "cum_a_g",
                            "cum_b_g",
                            "cum_delta_g",
                        ],
                    )
                    writer.writeheader()
                    for row in cycle_rows:
                        writer.writerow(row)
            with open(yield_csv, "w", encoding="utf-8", newline="") as handle:
                writer = csv.DictWriter(
                    handle,
                    fieldnames=[
                        "profile_side",
                        "profile_name",
                        "isolated_mass_g",
                        "theoretical_yield_g",
                        "actual_yield_pct",
                    ],
                )
                writer.writeheader()
                for row in yield_rows:
                    writer.writerow(row)
            if report_prefs.get("include_diagnostics", True):
                diagnostics_txt.write_text(diagnostics_text + "\n", encoding="utf-8")

            with PdfPages(str(output_pdf)) as pdf:
                fig_a = panel_a.get("figure")
                fig_b = panel_b.get("figure")

                def _save_compare_side_figure(
                    fig_obj: Any,
                    *,
                    side_label: str,
                    title_text: str,
                    suptitle_text: str,
                ) -> None:
                    """Save one compare side figure with caption text outside plot data.

                    Purpose:
                        Preserve profile title identity in exports after compare panes
                        moved title/suptitle text out of plot area.
                    Why:
                        Compare PDF output should still include both title fields per
                        side without consuming in-plot rendering space.
                    Args:
                        fig_obj: Side figure object saved into the report PDF.
                        side_label: Human-readable side label (for example `Profile A`).
                        title_text: Side title text.
                        suptitle_text: Side suptitle text.
                    Returns:
                        None.
                    Side Effects:
                        Adds/removes one temporary figure-level caption before save.
                    Exceptions:
                        Caption artist failures fall back to figure-only save.
                    """
                    if fig_obj is None:
                        return
                    caption_text = (
                        f"{side_label} | Title: {title_text or '--'} | "
                        f"Suptitle: {suptitle_text or '--'}"
                    )
                    caption_artist = None
                    try:
                        caption_artist = fig_obj.text(
                            0.01,
                            0.995,
                            caption_text,
                            ha="left",
                            va="top",
                            fontsize=9.0,
                            family="monospace",
                            bbox={
                                "boxstyle": "round,pad=0.20",
                                "facecolor": "#f4f4f4",
                                "edgecolor": "#cdcdcd",
                                "alpha": 0.92,
                            },
                        )
                    except Exception:
                        caption_artist = None
                    pdf.savefig(fig_obj)
                    if caption_artist is not None:
                        try:
                            caption_artist.remove()
                        except Exception:
                            # Best-effort guard; ignore failures to avoid interrupting export.
                            pass

                if fig_a is not None:
                    _save_compare_side_figure(
                        fig_a,
                        side_label="Profile A",
                        title_text=profile_a_title,
                        suptitle_text=profile_a_suptitle,
                    )
                if fig_b is not None:
                    _save_compare_side_figure(
                        fig_b,
                        side_label="Profile B",
                        title_text=profile_b_title,
                        suptitle_text=profile_b_suptitle,
                    )

                summary_fig = Figure(figsize=(11.0, 8.5), dpi=110)
                ax = summary_fig.add_subplot(111)
                ax.axis("off")
                summary_lines = [
                    "GL-260 Compare Report",
                    f"Generated: {datetime.now().isoformat(timespec='seconds')}",
                    "",
                    f"Profile A: {profile_a_name or '--'}",
                    f"Profile B: {profile_b_name or '--'}",
                    f"Profile A title: {profile_a_title or '--'}",
                    f"Profile A suptitle: {profile_a_suptitle or '--'}",
                    f"Profile B title: {profile_b_title or '--'}",
                    f"Profile B suptitle: {profile_b_suptitle or '--'}",
                    "Report source: side-by-side compare panes",
                ]
                if report_prefs.get("include_yield_summary", True):
                    summary_lines.extend(
                        [
                            "",
                            f"Theoretical A (g): {'--' if theo_a is None else f'{theo_a:.4f}'}",
                            f"Theoretical B (g): {'--' if theo_b is None else f'{theo_b:.4f}'}",
                            f"Actual Yield A (%): {'--' if actual_a is None else f'{actual_a:.2f}'}",
                            f"Actual Yield B (%): {'--' if actual_b is None else f'{actual_b:.2f}'}",
                            (
                                "Yield Delta B-A (%): "
                                f"{(actual_b - actual_a):+.2f}"
                                if actual_a is not None and actual_b is not None
                                else "Yield Delta B-A (%): --"
                            ),
                        ]
                    )
                if not cycle_rows:
                    summary_lines.extend(
                        [
                            "",
                            "Cycle table: no rows available (check marker assignment/data).",
                        ]
                    )
                summary_text = "\n".join(summary_lines)
                ax.text(
                    0.03,
                    0.97,
                    summary_text,
                    ha="left",
                    va="top",
                    fontsize=11,
                    family="monospace",
                )
                pdf.savefig(summary_fig)
                try:
                    plt.close(summary_fig)
                except Exception:
                    # Best-effort guard; ignore failures to avoid interrupting the workflow.
                    pass

            if report_prefs.get("include_interactive_html", True):
                html_report.write_text(
                    self._build_compare_interactive_html(
                        profile_a_name=profile_a_name,
                        profile_b_name=profile_b_name,
                        profile_a_title=profile_a_title,
                        profile_a_suptitle=profile_a_suptitle,
                        profile_b_title=profile_b_title,
                        profile_b_suptitle=profile_b_suptitle,
                        cycle_rows=cycle_rows,
                        yield_rows=yield_rows,
                        diagnostics_text=diagnostics_text,
                        fig_a=panel_a.get("figure"),
                        fig_b=panel_b.get("figure"),
                        actual_a=actual_a,
                        actual_b=actual_b,
                    ),
                    encoding="utf-8",
                )
        except Exception as exc:
            try:
                messagebox.showerror(
                    "Generate Comparison Report",
                    f"Failed to generate report artifacts.\n{exc}",
                )
            except Exception:
                # Best-effort guard; ignore failures to avoid interrupting the workflow.
                pass
            return

        try:
            html_line = (
                f"- Interactive HTML: {html_report}"
                if report_prefs.get("include_interactive_html", True)
                else "- Interactive HTML: skipped (disabled in Report Options)"
            )
            messagebox.showinfo(
                "Generate Comparison Report",
                (
                    "Comparison report artifacts generated:\n"
                    f"- PDF: {output_pdf}\n"
                    f"- Cycle CSV: {cycle_csv}\n"
                    f"- Yield CSV: {yield_csv}\n"
                    f"- Diagnostics: {diagnostics_txt}\n"
                    f"{html_line}"
                ),
            )
        except Exception:
            # Best-effort guard; ignore failures to avoid interrupting the workflow.
            pass

    def _build_tab_ledger(self) -> None:
        """Build the Ledger tab UI and initialize ledger state.

        Purpose:
            Construct a persistent QC ledger editor for profile end-of-run records.
        Why:
            Users need an in-app place to add/edit/export final QC outcomes across
            runs without external spreadsheets.
        Args:
            None.
        Returns:
            None.
        Side Effects:
            Creates Ledger-tab widgets, initializes entry cache/sort/filter state,
            and populates the table from persisted settings.
        Exceptions:
            Returns early when the Ledger tab frame is unavailable.
        """
        frame = getattr(self, "tab_ledger", None)
        if frame is None:
            return

        frame.grid_rowconfigure(1, weight=1)
        frame.grid_columnconfigure(0, weight=1)

        controls = ttk.LabelFrame(frame, text="Ledger Controls")
        controls.grid(row=0, column=0, sticky="ew", padx=8, pady=(8, 4))
        for col in range(16):
            controls.grid_columnconfigure(col, weight=1 if col in {1, 5} else 0)

        self._ledger_profile_filter_var = tk.StringVar(value="All Profiles")
        self._ledger_status_var = tk.StringVar(value="")
        self._ledger_sort_key = "updated_at"
        self._ledger_sort_desc = True
        self._ledger_sort_mode_var = tk.StringVar(value="Manual Order")
        self._ledger_sort_filter_cache: "OrderedDict[str, List[int]]" = OrderedDict()
        self._ledger_table_refresh_after_id: Optional[str] = None
        self._ledger_table_refresh_generation = 0
        self._ledger_table_refresh_pending_rows: List[Dict[str, Any]] = []
        self._ledger_table_refresh_runtime_columns: List[str] = []
        self._ledger_table_refresh_cursor = 0
        self._ledger_table_refresh_total_count = 0
        self._ledger_table_refresh_filter_label = "All Profiles"
        self._ledger_table_refresh_sort_label = "Manual Order"
        ledger_table_state_raw = _normalize_ledger_table_settings(settings.get("ledger_table"))
        self._ledger_custom_columns = list(ledger_table_state_raw.get("custom_columns") or [])
        ledger_allowed_columns = _ledger_allowed_columns_from_custom_columns(
            self._ledger_custom_columns
        )
        ledger_table_state = _normalize_ledger_table_settings(
            ledger_table_state_raw,
            allowed_columns=ledger_allowed_columns,
        )
        settings["ledger_table"] = dict(ledger_table_state)
        self._ledger_view_profiles = _normalize_ledger_view_profiles(
            ledger_table_state.get("view_profiles")
        )
        self._ledger_active_view_mode = _normalize_ledger_view_mode(
            ledger_table_state.get("view_mode"),
            default="standard",
        )
        self._ledger_view_mode_var = tk.StringVar(
            value=LEDGER_VIEW_MODE_LABELS.get(self._ledger_active_view_mode, "Standard")
        )
        self._ledger_column_order = tuple(
            ledger_table_state.get("column_order")
            or list(
                _ledger_allowed_columns_from_custom_columns(self._ledger_custom_columns)
            )
        )
        self._ledger_column_order_window: Optional[tk.Toplevel] = None
        self._ledger_custom_columns_window: Optional[tk.Toplevel] = None
        self._ledger_column_resize_active = False

        ttk.Label(controls, text="Profile Filter").grid(
            row=0, column=0, sticky="w", padx=(8, 4), pady=6
        )
        self._ledger_profile_filter_combo = ttk.Combobox(
            controls,
            textvariable=self._ledger_profile_filter_var,
            state="readonly",
            values=("All Profiles",),
        )
        self._ledger_profile_filter_combo.grid(
            row=0, column=1, sticky="ew", padx=(0, 8), pady=6
        )
        _ui_button(
            controls,
            text="Clear Filter",
            command=lambda: (
                self._ledger_profile_filter_var.set("All Profiles"),
                self._ledger_refresh_table(),
            ),
        ).grid(row=0, column=2, sticky="ew", padx=(0, 8), pady=6)
        _ui_button(
            controls,
            text="Add Entry",
            command=self._ledger_add_entry,
        ).grid(row=0, column=3, sticky="ew", padx=(0, 4), pady=6)
