        self._data_multi_frame = ttk.Frame(f)
        self._data_multi_frame.grid(row=4, column=0, columnspan=4, sticky="nsew")
        self._data_multi_frame.grid_columnconfigure(0, weight=1)

        list_frame = ttk.Frame(self._data_multi_frame)
